window.__PUBMED__ = {"count": 2229, "records": [{"year": 1969, "pmid": "5358345", "author": "Jarrett O", "n_authors": 3, "title": "Growth of feline leukaemia virus in human cells.", "abstract": null, "journal": "Nature", "doi": "10.1038/2241208a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1969, "pmid": "4981495", "author": "Hardy WD Jr", "n_authors": 6, "title": "Feline leukemia virus: occurrence of viral antigen in the tissues of cats with lymphosarcoma and other diseases.", "abstract": "Felinie leutkemia viruts antigen is demonstrable by immunodiffusion with rabbit precipitating antiserum to purified felinie leukemia virus. The felinie leukemia virus antigen was found in the tissues of 25 of 33 cats with lymphosarcoma and of 5 of 13 cats with infectious peritonitis. Its presence was correlated with the occurrence of felinie leukemia virus demonstrable by electron microscopy. The one clinically normal cat giving a positive test for feline leukemia virus antigen belonged to a household in which two cats had developed lymphosarcoma. With the exception of a dog with lymphosarcoma induced by feline leukemia virus, the antigent was absent from lymphosarcoma and nonlymphomatous tumors of other species (man, dog, cow, goat, or pig).", "journal": "Science (New York, N.Y.)", "doi": "10.1126/science.166.3908.1019", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1969, "pmid": "5793978", "author": "Fischinger PJ", "n_authors": 2, "title": "Viral infection across species barriers: reversible alteration of murine sarcoma virus for growth in cat cells.", "abstract": "Infection of cat embryo cells by a centrifugally induced aggregate of murine sarcoma virus and feline leukemia virus gave rise to a defective, focus-forming virus which propagated in cat cells, but not in mouse cells. This virus, apparently enveloped with a feline leukemia virus coat, was later subjected to aggregation with murine leukemia virus, whereupon it regained the capacity for growth in mouse cells.", "journal": "Science (New York, N.Y.)", "doi": "10.1126/science.165.3894.714", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1970, "pmid": "5487542", "author": "Anderson LJ", "n_authors": 2, "title": "Immunological responses in lymph nodes of the cat.", "abstract": "To study the zonal response to antigenic stimuli in lymph nodes of the cat, three groups of eight cats received epicutaneous application of oxazolone and inoculations of ovalbumin plus Freund's adjuvant and feline leukaemia virus (FeLV) respectively into the left hind footpads. The changes in the left popliteal nodes were followed histologically and autoradiographically for 14 days. In the oxazolone-treated group, there was an extremely marked proliferation of blast cells in the paracortical areas, maximal on days 3–7; germinal centres developed on day 6; plasma cells did not feature in the response. In the ovalbumin-treated group, the nodes developed a full zonal response, with marked blast cell response in the paracortical areas, formation of prominent germinal centres and a striking plasma cell reaction. In both groups, there was a considerable increase in mast cell numbers in the course of the reactions; the origin of the new mast cells was not clear. The response to FeLV was minimal, despite direct stimulation of the node with high titre virus.", "journal": "Immunology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1970, "pmid": "18605433", "author": "Chapman AL", "n_authors": 3, "title": "Infection and transformation of dog cells with a modified sarcoma virus.", "abstract": "Dog-embryo cell cultures were infected with a mixture of feline leukemia virus (FelLV) and a modified murine (Moloney) sarcoma virus MSV(FelLV). Morphological alteration of the cells was observed 3 days post infection. Virus progeny from the infected cultures increased 50- to 100-fold in foci of cellular alteration on dog cell cultures pretreated with diethylaminoethyl-dextran, but only twofold on cat embryo cultures similarly treated. The numbers of foci produced corresponded to a dual infection with the MSV(FelLV) and endogenous FelLV and could be increased by simultaneous infection with exogenous FelLV. After five serial passages in dog cell cultures, the virus mixture still had a superior focus-inducing capacity on cat cells as compared with dog cells. Electron microscopic examination of infected dog cultures showed typical C-type virions. FelLV alone propagated in dog cell cultures without inducing morphological alteration, and progeny virus, capable of promoting focus formation by MSV(FelLV), could be detected 48 hours post infection.", "journal": "Journal of the National Cancer Institute", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1970, "pmid": "5002008", "author": "Sibal LR", "n_authors": 6, "title": "Methods for the detection of viral antigen and antibody to a feline leukemia virus (a preliminary report).", "abstract": null, "journal": "Journal of the National Cancer Institute", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1970, "pmid": "5002006", "author": "Burger CL", "n_authors": 2, "title": "Feline leukemia virus: purification from tissue culture fluids.", "abstract": null, "journal": "Journal of the National Cancer Institute", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1970, "pmid": "4991275", "author": "Dougherty E 3rd", "n_authors": 2, "title": "Ultrastructural studies of feline leukemia virus.", "abstract": null, "journal": "Journal of ultrastructure research", "doi": "10.1016/s0022-5320(70)80023-5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1970, "pmid": "5467915", "author": "Sarma PS", "n_authors": 6, "title": "Feline leukemia virus detection in vitro.", "abstract": null, "journal": "Virology", "doi": "10.1016/0042-6822(70)90092-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1970, "pmid": "4376374", "author": "Jarrett O", "n_authors": 3, "title": "Growth of feline leukemia virus in human, canine and porcine cells.", "abstract": null, "journal": "Bibliotheca haematologica", "doi": "10.1159/000391730", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1970, "pmid": "4376372", "author": "Sarma PS", "n_authors": 5, "title": "Feline leukemia virus: detection of group-specific viral antigen and infectious virus by a complement-fixation test.", "abstract": null, "journal": "Bibliotheca haematologica", "doi": "10.1159/000391728", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1970, "pmid": "4376371", "author": "Hardy WD Jr", "n_authors": 6, "title": "Serological studies of the feline leukemia virus.", "abstract": null, "journal": "Bibliotheca haematologica", "doi": "10.1159/000391726", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1970, "pmid": "4313195", "author": "Sarma PS", "n_authors": 3, "title": "Trans-species rescue of defective genomes of murine sarcoma virus from hamster tumor cells with helper feline leukemia virus.", "abstract": "This report describes a trans-species rescue of defective MSV genome with helper leukemia virus derived from cats. This rescue was achieved by in vitro co-cultivation of hamster tumor cells with feline embryo cells in the presence of helper feline leukemia virus (FeLV), or by inoculation of tumor cells into FeLV-infected newborn cats. The rescued focus-forming viruses produced foci in feline embryo cultures but not in cultures of mouse, rat, and hamster species. One isolate was tested and found to induce sarcoma in a kitten. Antigenic and viral interference studies indicated that the focus-forming virus has the viral envelope of FeLV. Virus stocks consisted of a mixture of focus-forming particles and a 1000-fold excess of helper FeLV. Virus assay pattern in feline embryo cultures with or without added helper FeLV indicated that this helper virus is required for the transformation of feline cells.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.65.1.81", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1971, "pmid": "5157829", "author": "Fischinger PJ", "n_authors": 2, "title": "Quantitative interactions of feline leukaemia virus and its pseudotype of murine sarcoma virus in cat cells: requirement for DNA synthesis.", "abstract": null, "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-13-2-203", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1971, "pmid": "4332148", "author": "Oroszlan S", "n_authors": 4, "title": "Specific inhibition of mammalian ribonucleic acid C-type virus deoxyribonucleic acid polymerases by rat antisera.", "abstract": "Inhibition of the ribonucleic acid (RNA)- and deoxyribonucleic acid (DNA)-dependent DNA polymerase activities of mammalian C-type viruses was obtained with sera from rats bearing murine leukemia virus-induced transplant tumors. Polymerase activities of nonmammalian (viper) C-type virus and murine mammary tumor virus were not inhibited by such sera nor by serum from a rat immunized with the DNA polymerase of feline leukemia virus purified by isoelectric focusing. The latter serum appeared to inhibit preferentially the DNA-dependent DNA polymerase activity of mammalian C-type viruses showing no inhibition of RNA-dependent DNA synthesis.", "journal": "Journal of virology", "doi": "10.1128/JVI.8.5.816-818.1971", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1971, "pmid": "5286051", "author": "Anderson LJ", "n_authors": 4, "title": "Feline leukemia-virus infection of kittens: mortality associated with atrophy of the thymus and lymphoid depletion.", "abstract": null, "journal": "Journal of the National Cancer Institute", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1971, "pmid": "4108573", "author": "Sarkar NH", "n_authors": 3, "title": "Helical nucleocapsid structure of the oncogenic ribonucleic acid viruses (oncornaviruses).", "abstract": "Negative staining of virions and isolated nucleoids from avian myeloblastosis virus, murine leukemia virus, murine mammary tumor virus, and feline leukemia virus reveals common internal structures. The majority of virions that are penetrated by phosphotungstate show spherical nucleoids with no apparent symmetry. In a small percentage of virions, two distinctive structures are found: (i) single strands (3 to 5 nm in diameter) which are presumed to be the nucleoprotein and are found randomly oriented throughout the viral interior and (ii) helical structures (7 to 9 nm in diameter) which contain these nucleoprotein strands and are observed at the periphery of the nucleoid. The finding of helical nucleocapsid segments at the periphery of the nucleoid, as well as the hollow spherical structure observed in thin section of budding virions, has led to the hypothesis that the nucleocapsid of the freshly budded oncornavirus is supercoiled as a hollow sphere. This symmetry, however, is considered transient, as the internal structure of the extracellular virus undergoes a conformational rearrangement; thus, due to structural instability, the nucleocapsid uncoils and the nucleoprotein strands fill the interior of the virion. The extracellular virion is therefore considered degenerate in respect to symmetry, explaining the difficulty in detecting a helical nucleocapsid.", "journal": "Journal of virology", "doi": "10.1128/JVI.8.4.564-572.1971", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1971, "pmid": "5558544", "author": "Jarrett WF", "n_authors": 5, "title": "Myeloid leukaemia in a cat produced experimentally by feline leukaemia virus.", "abstract": null, "journal": "Research in veterinary science", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1971, "pmid": "4328488", "author": "Schäfer W", "n_authors": 6, "title": "Isolation and characterization of two group-specific antigens from feline leukemia virus.", "abstract": null, "journal": "Virology", "doi": "10.1016/0042-6822(71)90154-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1971, "pmid": "4105993", "author": "Ubertini T", "n_authors": 4, "title": "A fluorescent antibody technique for the detection of the group-specific antigen of feline leukemia virus in infected tissue-culture cells.", "abstract": null, "journal": "Virology", "doi": "10.1016/0042-6822(71)90168-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1971, "pmid": "5575715", "author": "Schneider R", "n_authors": 1, "title": "Comments on epidemiologic implications of feline leukemia virus.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1971, "pmid": "5108376", "author": "Jarrett O", "n_authors": 1, "title": "Virology and host range of feline leukemia virus.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1971, "pmid": "5103499", "author": "Lee KM", "n_authors": 1, "title": "Comments on feline leukemia virus.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1971, "pmid": "4995863", "author": "Fink MA", "n_authors": 3, "title": "Serologic detection of feline leukemia virus antigens or antibodies.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1971, "pmid": "4930305", "author": "Brodey RS", "n_authors": 1, "title": "Comments on epidemiologic aspects of feline leukemia virus.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1971, "pmid": "4930304", "author": "Heath CW Jr", "n_authors": 1, "title": "Epidemiologic implications of feline leukemia virus.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1971, "pmid": "5172343", "author": "Oksanen A", "n_authors": 3, "title": "Histology of the salivary gland of two leukotic cats.", "abstract": "Feline leukemia (leukosis, lymphosarcomatosis) is now known to be caused by a virus (", "journal": "Acta veterinaria Scandinavica", "doi": "10.1186/BF03547729", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1971, "pmid": "5101019", "author": "Jarrett O", "n_authors": 5, "title": "Isolation of the nucleic acid of feline leukemia virus.", "abstract": null, "journal": "Virology", "doi": "10.1016/0042-6822(71)90252-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1972, "pmid": "4118867", "author": "Grandgenett DP", "n_authors": 3, "title": "Ribonuclease H: a ubiquitous activity in virions of ribonucleic acid tumor viruses.", "abstract": "Ten ribonucleic acid (RNA) tumor viruses grown in five different host cell species and three non-oncogenic viruses from three different virus groups have been examined for ribonuclease H content. Three different substrates were used to assay ribonuclease H: calf thymus [(3)H]RNA-deoxyribonucleic acid (DNA) hybrid prepared with denatured calf thymus DNA and Escherichia coli DNA-directed RNA polymerase, (3)H-polydenylic acid [(3)H-poly(A)] complexed to polydeoxythymidylic acid [poly(dT)], and (3)H-polyuridylic acid [(3)H-poly(U)] complexed to polydeoxyadenylic acid [poly(dA)]. All ten RNA tumor viruses contained ribonuclease H activity which degraded the RNA of both the calf thymus hybrid and poly(A)-poly(dT), whereas only the ribonuclease H in the Moloney strain of murine sarcoma-leukemia virus and in RD-feline leukemia virus hydrolyzed the RNA strand of poly(U)-poly(dA). No appreciable ribonuclease H activity was detected in influenza, Sendai, or vesicular stomatitis virus. The ribonuclease H and RNA-directed DNA polymerase activities in Moloney murine sarcoma-leukemia virus were inseparable by phosphocellulose chromatography or glycerol gradient centrifugation, but appeared to be partially separated by diethylaminoethyl-cellulose chromatography.", "journal": "Journal of virology", "doi": "10.1128/JVI.10.6.1136-1142.1972", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1972, "pmid": "4116139", "author": "Albino AP", "n_authors": 3, "title": "Theta particles: a structure found in hamster sarcoma virus.", "abstract": "Hamster sarcoma virus (HaSV), a ribonucleic acid tumor virus, pelleted from tissue culture fluid manifests type C morphology by electron microscopy. However, if virus is first concentrated by polyethylene glycol or ammonium sulfate followed by density gradient banding, the virus shows a dramatically atypical barred core structure, termed \"theta particles.\" This structure suggests a condensation of the ribonucleoprotein into a flat disc. Atypical particles are found with HaSV and not in similarly treated feline leukemia virus or Rauscher-murine leukemia virus. Differences in the composition of HaSV as compared with these other viruses may be responsible for the production of such particles.", "journal": "Journal of virology", "doi": "10.1128/JVI.10.3.477-483.1972", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1972, "pmid": "4558350", "author": "Jarrett O", "n_authors": 3, "title": "Restricted host range of a feline leukaemia virus.", "abstract": null, "journal": "Nature", "doi": "10.1038/238220a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1972, "pmid": "4504461", "author": "Rogers R", "n_authors": 5, "title": "Cat interferon inhibits feline leukaemia virus infection in cell culture.", "abstract": null, "journal": "Nature: New biology", "doi": "10.1038/newbio237270a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1972, "pmid": "4336663", "author": "Rangan SR", "n_authors": 4, "title": "Cytopathogenic test for feline leukemia virus infections.", "abstract": "A mixed culture cytopathogenic effect with the development of multinucleated giant cells in feline leukemia virus-infected cultures after cocultivation with XC cells is described. This cytopathogenic effect has been utilized as a convenient visual marker for the detection and assay of feline leukemia virus in feline and canine embryo fibroblasts as well as in a canine tumor cell line, M-132-1. Comparison of the cytopathogenic reaction in the three cell lines indicates that the reaction is more rapid and pronounced in M-132-1 cells than in the embryo fibroblast cultures.", "journal": "Applied microbiology", "doi": "10.1128/am.23.3.628-636.1972", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1972, "pmid": "4336013", "author": "Olpin JL", "n_authors": 2, "title": "Analytical measurements of isopycnic density in the preparative ultracentrifuge with application to FeLV and FeLV-RNA.", "abstract": null, "journal": "Analytical biochemistry", "doi": "10.1016/0003-2697(72)90418-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1972, "pmid": "4336391", "author": "De Noronha F", "n_authors": 4, "title": "Induction of group-specific interspecies antibody in a cat by immunization with disrupted feline leukaemia virus.", "abstract": null, "journal": "Nature: New biology", "doi": "10.1038/newbio235014a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1972, "pmid": "4621402", "author": "Essex M", "n_authors": 3, "title": "Continuous long-term replication of feline leukemia virus (FeLV) in an established canine cell culture (MDCK).", "abstract": null, "journal": "Proceedings of the Society for Experimental Biology and Medicine. Society for Experimental Biology and Medicine (New York, N.Y.)", "doi": "10.3181/00379727-139-36129", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1972, "pmid": "4333572", "author": "Rangan SR", "n_authors": 4, "title": "Detection and assay of feline leukemia virus (FeLV) by a mixed-culture cytopathogenicity method.", "abstract": null, "journal": "Virology", "doi": "10.1016/0042-6822(72)90258-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1973, "pmid": "4357865", "author": "Benveniste RE", "n_authors": 2, "title": "Homology between type-C viruses of various species as determined by molecular hybridization.", "abstract": "Two strains of feline leukemia virus, two endogenous feline type-C viruses (RD/CCC group), several endogenous and laboratory strains of murine \"leukemia\" virus, two rat viruses, two primate viruses (woolly monkey and gibbon ape), as well as hamster, pig, and avian type-C viruses were examined for their relatedness to one another by molecular hybridization. The extent of nucleic-acid homology was determined by hybridization of the various viral RNAs to a [(3)H]DNA product synthesized from each virus. Among the murine type-C viruses (Rauscher, Kirsten, AT-124, and endogenous BALB/c virus) a high degree of homology is observed, although the viruses are not identical. The two primate viruses are also closely related to one another. The feline, rat, hamster, and pig endogenous viruses can be readily distinguished from one another and from the murine and primate viruses since their DNA products share very little or no nucleic-acid homology. However, the murine and primate type-C virus groups possess a surprising degree of relatedness. Feline type-C viruses fall into two distinct groups, the feline leukemia virus group and the RD-114/CCC group, with little detectable nucleic-acid homology between them. Infection of feline or rat cells with type-C virus results in production of the endogenous type-C virus of the species along with the infecting virus.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.70.12.3316", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1973, "pmid": "4129928", "author": "Okabe H", "n_authors": 3, "title": "Specificity of the DNA product of RNA-dependent DNA polymerase in type C viruses. II. Quantitative analysis.", "abstract": "A number of mammalian Type C viruses were analyzed for relatedness by the technique of DNA.RNA hybridization. Viral DNAs were prepared in single-stranded form from complexes with 70S viral RNA formed during endogenous polymerase reactions. Extent of hybridization was assayed with the single-strand nuclease (S-1) from Aspergillus oryzae. Results obtained indicated a high degree of viral specificity, with significant cross-reactions being observed only with viruses obtained from within a species, as in the case of mouse and cat viruses, or in the special case of woolly monkey-gibbon comparisons. Comparisons of RD-114 virus, recently determined to be of feline origin, and conventional feline Type C viruses (FeLV), revealed minimal relatedness, especially when feline virus was grown on human cells, thus indicating the possibility of coexistence of greatly disparate Type C viruses within one species. A rat-specific virus, recovered from tumors induced by murine sarcoma virus, was found to contain genetic material common to both the original mouse virus and viruses indigenous to the rat, even though only rat-specific proteins have been detected during infection by this virus.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.70.12.3923", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1973, "pmid": "4358162", "author": "East JL", "n_authors": 4, "title": "Structural characteristics and nucleotide sequence analysis of genomic RNA from RD-114 virus and feline RNA tumor viruses.", "abstract": "The results of molecular hybridization experiments have demonstrated that the RNA genome of RD-114 virus has extensive nucleotide sequence homology with the RNA genome of Crandell virus, an endogenous type C virus of cats, but only limited homology with the RNA genomes of feline sarcoma virus and feline leukemia virus. The genomic RNAs of RD-114 virus and Crandell virus also had identical sedimentation coefficients of 50S. A structural rearrangement of genomic RNA did not exist within released RD-114 virions, whereas a structural rearrangement of genomic RNA did occur within feline sarcoma virions and feline leukemia virions after release from virus-producing cells.", "journal": "Journal of virology", "doi": "10.1128/JVI.12.5.1085-1091.1973", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1973, "pmid": "4353951", "author": "Boone CW", "n_authors": 3, "title": "Testing by the \"paired-label\" antibody binding technique for feline leukemia virus-induced cell surface antigens (FeLV-CSA) on the surface of human rhabdomyosarcoma cells releasing RD-114 virus.", "abstract": null, "journal": "Virology", "doi": "10.1016/s0042-6822(73)81017-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1973, "pmid": "4123999", "author": "Oroszlan S", "n_authors": 4, "title": "Feline leukemia and RD-114 virus group-specific proteins: comparison of amino terminal sequence.", "abstract": "The major internal virion polypeptide from feline and RD-114 type C viruses has been subjected to amino terminal sequence analyses with the Beckman automated sequencer. These proteins, as well as their homologs in rat and mouse viruses, begin with the sequence prolylleucylarginyl (Pro-Leu-Arg). Virus RD-114 differs from conventional feline type C viruses that show about 80 percent relatedness based on calculation of the minimum number of base changes to give equivalent coding for the protein segments analyzed. In addition, insertion of a gap in the RD-114 sequence is necessary to maintain positional homology. The difference between RD-114 and feline leukemia virus appears as great as the difference between mouse type C viruses and either of these two viruses. Thus, even though current evidence suggests that RD-114 is of feline origin, the sequence differences between RD-114 and conventional feline virus group-specific proteins is well beyond that based on one or a few point mutations.", "journal": "Science (New York, N.Y.)", "doi": "10.1126/science.181.4098.454", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1973, "pmid": "4147636", "author": "Hardy WD Jr", "n_authors": 5, "title": "Horizontal transmission of feline leukaemia virus.", "abstract": null, "journal": "Nature", "doi": "10.1038/244266a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1973, "pmid": "4352660", "author": "Yoshiki T", "n_authors": 3, "title": "Common cell-surface antigen associated with murine and feline C-type RNA leukemia viruses.", "abstract": "A new common cell-surface antigen associated with murine and feline C-type RNA leukemia viruses was demonstrated by the use of rabbit antiserum against feline leukemia virus and the indirect membrane immunofluorescence test. Common cell-surface antigen was found in all leukemias of all strains of mice tested, in normal lymphoid tissues of Gross-positive (high incidence of leukemia) mouse strains AKR, AKR.H-2(b), C58, and NZB, in cultured rat fibroblasts infected with Rauscher virus, in cultured feline fibroblasts infected with feline leukemia virus, and in spontaneous feline lymphosarcoma. The antigen was not demonstrable in normal adult and fetal tissues of Gross-negative mouse strains or in tissues and cultured fibroblasts derived from normal rats and normal cats. The immunoferritin study of murine leukemia cells revealed that the antigen was located on the cell surface in discrete areas; budding and C-type RNA viral envelope was not labeled as antigen site. The distribution of common cell-surface antigen on murine and feline leukemias, as well as on normal lymphoid tissues of Gross-positive mouse strains, indicates the presence of an antigen distinct from any cell-surface antigen heretofore shown to be associated with, or specified by, mammalian C-type RNA viruses.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.70.6.1878", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1973, "pmid": "4123287", "author": "Fischinger PJ", "n_authors": 4, "title": "Isolation of RD-114-like oncornavirus from a cat cell line.", "abstract": "A clone of cells derived from a continuous line of cat cells (CCC) spontaneously produced an RNA C-type virus (CCC virus) which did not have the group-specific antigen of the standard strains of feline leukemia viruses but did have that of the RD-114 virus. Single-hit infection of a virus yielding CCC cell with only the feline leukemia virus pseudotype of murine sarcoma virus [MSV(FeLV)] resulted in the release of a pseudotype of MSV coated with the CCC virus envelope. Host range, transmission of virus, helper functions, interference properties, and specific neutralization showed that the CCC and the RD-114 isolates as well as their respective MSV pseudotypes are closely similar if not identical. Parental, virus-negative cells frozen before the existence of RD-114 were chemically induced to yield CCC-like virus de novo. Infection of susceptible human cells with the chemically induced virus resulted in interference with the CCC virus pseudotype of MSV but not with the FeLV pseudotype of MSV.", "journal": "Journal of virology", "doi": "10.1128/JVI.11.6.978-985.1973", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1973, "pmid": "4349492", "author": "Boone CW", "n_authors": 3, "title": "Surface antigens on cat leukemic cells induced by feline leukemia virus: area density and antibody-binding affinity.", "abstract": "The binding of autologous bovine antibody to feline leukemia virus-induced cell surface antigens (FeCSA) on cat leukemia cells was studied by performing certain titration procedures with a mixture of immune and normal sera labeled with different iodine radioisotopes (paired-label technique). By using plots of titration data which conformed to linear equations derived from the mass action law, we determined the following constants. (i) The density of FeCSA was 2.03 x 10(6) sites per cell, or 5,230 sites per mum(2). (ii) The equilibrium constant of the FeCSA-antibody reaction was 2.67 x 10(7), from which the antibody binding affinity or standard free energy of the FeCSA-antibody bond was determined to be - 10.48 kcal (-43,869.28 J) per mol. The use of the techniques described to measure the concentration of antibody in antiserum, in micrograms per milliliter, is discussed.", "journal": "Journal of virology", "doi": "10.1128/JVI.11.4.515-519.1973", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1973, "pmid": "4345834", "author": "Schneider R", "n_authors": 2, "title": "A serologic survey of veterinarians for antibody to feline leukemia virus.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1973, "pmid": "4360200", "author": "Jarrett WF", "n_authors": 4, "title": "Feline leukaemia virus infection--the spectrum of associated disease and its relevance to the pathogenesis and immunology of leukaemia.", "abstract": null, "journal": "Bibliotheca haematologica", "doi": "10.1159/000427804", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1973, "pmid": "4360195", "author": "Hardy WD Jr", "n_authors": 3, "title": "Detection of the feline leukemia virus and other mammalian oncornaviruses by immunofluorescence.", "abstract": null, "journal": "Bibliotheca haematologica", "doi": "10.1159/000427906", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1973, "pmid": "4360154", "author": "Laird HM", "n_authors": 3, "title": "Electron microscopy of early interactions between feline leukaemia virus and cells in tissue culture.", "abstract": null, "journal": "Bibliotheca haematologica", "doi": "10.1159/000427836", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1973, "pmid": "4360153", "author": "Whalley JM", "n_authors": 1, "title": "Electron microscopy of feline leukaemia virus RNA.", "abstract": null, "journal": "Bibliotheca haematologica", "doi": "10.1159/000427834", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1973, "pmid": "4360147", "author": "Rickard CG", "n_authors": 4, "title": "Interspecies infection by feline leukemia virus: serial cell-free transmission in dogs of malignant lymphomas induced by feline leukemia virus.", "abstract": null, "journal": "Bibliotheca haematologica", "doi": "10.1159/000427807", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1973, "pmid": "4345148", "author": "Hoover EA", "n_authors": 3, "title": "Early lesions in cats inoculated with feline leukemia virus.", "abstract": null, "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1973, "pmid": "4130406", "author": "Jarrett O", "n_authors": 1, "title": "Antigenic determinants shared by polypeptides of feline leukaemia virus.", "abstract": null, "journal": "Bibliotheca haematologica", "doi": "10.1159/000427908", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1974, "pmid": "4374458", "author": "Hardy WD Jr", "n_authors": 4, "title": "Feline leukemia virus and public health awareness.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1974, "pmid": "4372380", "author": "Hoover EA", "n_authors": 2, "title": "Bone lesions in cats with anemia induced by feline leukemia virus.", "abstract": null, "journal": "Journal of the National Cancer Institute", "doi": "10.1093/jnci/53.5.1277", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1974, "pmid": "4372379", "author": "Hoover EA", "n_authors": 4, "title": "Erythroid hypoplasia in cats inoculated with feline leukemia virus.", "abstract": null, "journal": "Journal of the National Cancer Institute", "doi": "10.1093/jnci/53.5.1271", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1974, "pmid": "4138682", "author": "Charman HP", "n_authors": 3, "title": "Radioimmunoassay for the major structural protein of hamster type C viruses.", "abstract": "A radioimmunoassay for the major, group-specific antigen (p30) of hamster type C viruses was developed. The test detected approximately 5 ng of viral protein per ml and was highly specific for hamster viruses when used with homologous antibody. Comparison of three hamster viruses, two being mouse-hamster pseudotypes, in homologous and heterologous intraspecies assays, showed no evidence of type specificity for these proteins. The pseudotype viruses showed no evidence of mouse virus p30 antigenic determinants. An interspecies antigen assay employing (125)I-labeled hamster p30 and anti-feline p30 was completely inhibited by cat (feline leukemia virus), hamster, and rat viruses, to a slightly lesser degree by mouse viruses, and only poorly by RD 114 and Gibbon ape viruses. The Mason-Pfizer virus did not inhibit this assay. Hamster p30 was detected by radioimmunoassay in individual embryos from two LSH hamsters and in several adult tissues, excluding muscle at levels below that required for detection in complement-fixation tests.", "journal": "Journal of virology", "doi": "10.1128/JVI.14.4.910-917.1974", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1974, "pmid": "4369074", "author": "Velicer LF", "n_authors": 2, "title": "Properties of feline leukemia virus. II. In vitro labeling of the polypeptides.", "abstract": "Radioactive labeling of proteins from guanidine-hydrochloride disrupted feline leukemia virus was done in vitro by attaching [(3)H]methyl groups to protein amino groups with reductive alkylation. When in vitro labeled disrupted virus was analyzed by gel filtration in the presence of 6 M guanidine-hydrochloride the expected six major and one minor protein peaks were detected. When the same preparation was analyzed by immunodiffusion, the three antigens tested were found to have retained their antigenic activity.", "journal": "Journal of virology", "doi": "10.1128/JVI.14.3.700-703.1974", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1974, "pmid": "4368860", "author": "Hardy WD Jr", "n_authors": 1, "title": "Letter: Feline leukemia virus.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1974, "pmid": "4211925", "author": "Olsen RG", "n_authors": 5, "title": "Differences in acute and convalescent-phase antibodies of cats infected with feline picornaviruses.", "abstract": "Complement fixation inhibiting and complement-fixing antibodies were demonstrated in sera from cats during the acute and convalescent stages, respectively, of feline picornavirus infections. Complement-fixing antibody activity was present in 19S and 7S globulins, whereas complement fixation inhibiting antibody activity was confined to the 7S globulins. Sera with complement-fixing antibody and sera with complement fixation inhibiting antibody were also shown to have neutralizing and precipitating antibodies. In a study of antibody responses to homotypic and heterotypic strains of feline picornavirus, less serological cross-reactions were observed between strains of feline picornavirus in sera from cats in the acute phase of feline picornavirus infection than in the convalescent phase. The temporal relationship of complement fixation inhibiting and complement-fixing antibody responses of cats after acute viral respiratory infections is contrasted with previously observed antibody response in cats to feline leukemia virus.", "journal": "Infection and immunity", "doi": "10.1128/iai.10.2.375-380.1974", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1974, "pmid": "4136230", "author": "Graves DC", "n_authors": 2, "title": "Properties of feline leukemia virus. I. Chromatographic separation and analysis of the polypeptides.", "abstract": "Rickard's strain of feline leukemia virus (FeLV) contains two large glycoproteins and five smaller polypeptides of molecular weights 100,000 (gp >/= 100), 70,000 (gp70), 30,000 (p30), 21,000 (p21), 15,000 (p15), 11,200 (p11), and 10,000 (p10) when chromatographed on 6% agarose in the presence of 6 M guanidine hydrochloride (GuHCl). P21 is a minor component which was not previously described for mammalian leukemia-sarcoma viruses and may be analogous to the seventh protein found in avian viruses. Analysis on 4% agarose and by sodium dodecyl sulfate polyacrylamide gel electrophoresis revealed that gp >/= 100 is actually >/= 200,000 daltons and dissociates to polypeptides of approximately 100,000 to 115,000 daltons, whereas gp70 can be resolved into six stained bands ranging from 40,000 to 80,000 daltons despite being rechromatographed as a single symmetrical peak on 6% agarose. Rechromatography on 8% agarose was found to be more effective than on 6% agarose or sodium dodecyl sulfate polyacrylamide gel electrophoresis for obtaining the five small polypeptides, especially p11 and p10, in a highly purified form suitable for further analysis and for obtaining more precise estimates of their molecular weights, especially when done by co-chromatography with iodinated standard proteins markers. Rechromatographed p30, p21, p15, p11, and p10 had molecular weights of 27,000, 18,000, 15,000, 12,000, and 12,000 respectively, by co-electrophoresis with the marker proteins on sodium dodecyl sulfate polyacrylamide gel electrophoresis, clearly establishing that the latter two FeLV polypeptides comigrate to form one less band when compared to elution from agarose. The isoelectric points of p30 and p15 were 5.5 and 8.9, respectively, after renaturation from GuHCl and 5.6 and 8.7, respectively, when isolated from Tween-ether treated virus. Rechromatographed p30, p15, and p11, renatured by removing GuHCl with dialysis, reacted only with their homologous antisera in immunodiffusion analysis, indicating that they are immunologically unrelated. Also the interspecies gs-3 determinant associated with p30 could be regained by removal of GuHCl.", "journal": "Journal of virology", "doi": "10.1128/JVI.14.2.349-365.1974", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1974, "pmid": "4142463", "author": "Gardner MB", "n_authors": 7, "title": "Natural expression of feline type-C virus genomes, prevalence of detectable felv and RD-114 GS antigen, type-C particles and infectious virus in postnatal and fetal cats.", "abstract": null, "journal": "International journal of cancer", "doi": "10.1002/ijc.2910140112", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1974, "pmid": "4365331", "author": "Fischinger PJ", "n_authors": 3, "title": "Simple, quantitative assay for both xenotropic murine leukemia and ecotropic feline leukemia viruses.", "abstract": "A cat cell line carrying the genome of a murine sarcoma virus developed discrete foci in linear response to infection with feline leukemia virus or xenotropic murine C-type virus.", "journal": "Journal of virology", "doi": "10.1128/JVI.14.1.177-179.1974", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1974, "pmid": "4134740", "author": "Hellman A", "n_authors": 7, "title": "Baboon virus isolate M-7 with properties similar to feline virus RD-114.", "abstract": "A virus (M-7) isolated from baboon placental tissue demonstrates many similarities to endogenous feline virus RD-114. Immunodiffusion analysis shows a group-specific antigen (gs-1) line of identity between M-7 and RD-114. Anti-RD-114 DNA polymerase IgG inhibits M-7 polymerase by 57% compared to 97% for RD-114. M-7 virus has helper activity as demonstrated by rescue of murine sarcoma virus (MSV) from sarcoma-positive leukemia-negative human amnion cells. The host range of the rescued M-7 pseudotype of MSV, MSV (M-7), is similar to that of RD-114 virus. MSV (M-7) is also able to transform baboon cells and causes no detectable transformation of feline cells without addition of helper feline leukemia virus. Interference properties of M-7 and RD-114 virus are identical. Virus-specific neutralizing antisera, although partially cross-reacting, can distinguish MSV (M-7) from MSV (RD-114). These similarities and differences between RD-114 and M-7 viruses are best explained as type-specific differences between two viruses within the same strain.", "journal": "Journal of virology", "doi": "10.1128/JVI.14.1.133-138.1974", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1974, "pmid": "4363231", "author": "Bardell D", "n_authors": 2, "title": "Glycolysis during early infection of feline and human cells with feline leukemia virus.", "abstract": "A 30 to 40% increase in glucose uptake and lactic acid production was observed during a 48-h period immediately following inoculation of feline fibroblasts and HEp-2 cells with feline leukemia virus. There was no evidence of morphological alterations in either cell type. Immunofluorescent procedures to detect feline leukemia virus group-specific antigen revealed that the feline and HEp-2 cells were infected, whereas the antigen was not found in parallel cultures of uninoculated cells. Increased glycolysis depends upon the physiological state of the host cell and was not observed with infected stationary-phase cells.", "journal": "Infection and immunity", "doi": "10.1128/iai.9.5.824-827.1974", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1974, "pmid": "4131513", "author": "Yoshiki T", "n_authors": 4, "title": "Common cell surface antigen associated with mammalian C-type RNA viruses. Cell membrane-bound gs antigen.", "abstract": "The indirect membrane immunofluorescence test and the absorption analysis of rabbit anti-FeLV, rabbit anti-FeLVp 30, and rabbit anti-MuLVp 30 antisera yielded the following conclusions. An antigen shared by mammalian (murine and feline) C-type RNA leukemia and sarcoma viruses was detected on the surface of cells infected or transformed by C-type viruses. The antigen was characterized as membrane-bound gs antigen bearing two determinants, membrane-bound gs-1, intraspecies-specific antigenic determinant, and membrane-bound gs-3, interspecies-specific antigenic determinant. Membrane-bound gs antigen was located on the cell surface, frequently near the site of virus budding but not on the envelope of murine C-type RNA virus.", "journal": "The Journal of experimental medicine", "doi": "10.1084/jem.139.4.925", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1974, "pmid": "4361185", "author": "Chapman AL", "n_authors": 3, "title": "Effect of feline leukemia virus on transferrred hamster fetuses.", "abstract": null, "journal": "Journal of the National Cancer Institute", "doi": "10.1093/jnci/52.2.583", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1974, "pmid": "4374332", "author": "Hadden JW", "n_authors": 1, "title": "Editorial: the current status of feline leukemia virus research.", "abstract": null, "journal": "Clinical bulletin", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1974, "pmid": "4137190", "author": "Hoekstra J", "n_authors": 2, "title": "Simian sarcoma and feline leukemia virus antigens: isolation of species- and interspecies-specific proteins.", "abstract": null, "journal": "Intervirology", "doi": "10.1159/000149427", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "173656", "author": "Schaller JP", "n_authors": 2, "title": "Determination of subgroup-specific feline oncornavirus-neutralizing antibody.", "abstract": "A microneutralization assay was developed for antibody-to-subgroup-specific feline oncornaviruses. This study combines the economic advantage of a microtiter system and the quantitative focus reduction method which permits contruction of multiplicity curves for determination of virus-neutralizing titers. A twofold increase in Synder-Theilen feline sarcoma virus (ST-FeSV) on feline embryo cells decreased by approximately twofold the titer of reference goat serum prepared against Kawakami-Theilen feline leukemia virus. Similar dose effects with FeLV serotype virus preparations were not observed. An assay system utilizing FeLV serotypes on sarcoma-positive leukemia-negative cells demonstrated slightly greater sensitivity than one employing ST-FeSV on FE cells. Differential antibody responses to the three subgroup-specific feline oncornaviruses (A, B ,and C) were observed in reference goat sera. This test demonstrated good reproducibility as well as sensitivity and constitutes a significant improvement over end point dilution assay systems.", "journal": "Infection and immunity", "doi": "10.1128/iai.12.6.1405-1410.1975", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "52892", "author": "Benveniste RE", "n_authors": 3, "title": "Evolution of type C viral genes: origin of feline leukemia virus.", "abstract": "Reiterated gene sequences related to the RNA of feline leukemia virus (FeLV) are detected in all tissues of domestic cats and their close Felis relatives but not in more distantly related Felis species. Partially homologous viral gene sequences are found in rodent, and particularly rat, DNA. Together with the immunologic relationships observed between FeLV and endogenous rodent type C viruses, the results lead to the conclusion that FeLV-related genes were transmitted from a rodent to cat ancestor and have been perpetuated in the germ line of cats.", "journal": "Science (New York, N.Y.)", "doi": "10.1126/science.52892", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "171229", "author": "Rhim JS", "n_authors": 6, "title": "Characterization of non-producer human cells induced by Kirsten sarcoma virus.", "abstract": "Non-producer (NP) human cells induced by the Kirsten sarcoma virus were characterized. These morphologically altered NP cells produced neither infectious virus nor complement-fixing antigens of the murine sarcoma-leukemia virus complex. The NP cells did not release RNA-dependent DNA polymerase and type-C virus particles with a density of approximately 1.15 g/ml in sucrose gradients by 3H-uridine labelling. The NP cells produced tumors when transplanted subcutaneously into athymic nude mice. The tumor cells re-established in culture resembled the orginal NP cells, were confirmed as human cells by karyological analysis and were also found to be \"non-producer\". The sarcoma virus genome in NP cells could be rescued not only by co-cultivation with \"helper virus\"-releasing cells but also by superinfection with helper type-C viruses. Murine (Rauscher, Ki-MuLV, AT-124 and two other xenotropic viruses), feline, RD-114 and Simian (woolly monkey and baboon) type-C viruses possessed the ability to rescue the sarcoma genome from NP cells but not AKR leukemia virus. In addition, the feline leukemia virus titer obtained by the rescuing technique in NP cells was the same as those obtained in feline embryo and NP cells by CF induction assay.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910160516", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "1080752", "author": "Jones PA", "n_authors": 4, "title": "The relationship between tumorigenicity, growth in agar and fibrinolytic activity in a line of human osteosarcoma cells.", "abstract": "The TE-85 osteosarcoma cell line has several of the in vitro properties of malignant cells, including colony formation in agar, but has low extracellular fibrinolytic activity and no capacity to form tumors in ATS-treated hamsters. Some TE-85 cells clones (clones 2, 4 and 6) have increased fibrinolytic activity but do not form tumors in hamsters. TE-85 cells infected with mammalian transformation-defective viruses have low (FeLV) or increased (RD-114 virus) levels of fibrinolytic activity and do not form tumors in hamsters. TE-85 cell either nonproductively infected with Ki-MSV or productively infected with M-MSV (RD-114), have fibrinolytic activity and can form tumors in hamsters. The MSV gene(s) but not colony formation in agar or extracellular fibrinolytic activity appears to be capable of rendering TE-85 cells tumorigenic in ATS-treated hamsters.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910160411", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "170961", "author": "Rimai L", "n_authors": 6, "title": "Electrophoretic mobilities of RNA tumor viruses. Studies by Doppler-shifted light scattering spectroscopy.", "abstract": "We have used laser beat frequency light scattering spectroscopy to measure, at several pH values, the electrophoretic mobilities of purified avian myeloblastosis (AMV), murine leukemia (MuLV), murine mammary tumor (MuMTV), and feline leukemia (FeLV) viruses. The mobilities of these viruses are similar at pH greater than or equal to7 (-2.7 to -3.2 X 10(-4) (cm/sec)/(V/cm). The isoelectric points of MuLV and AMV are apparently less than pH 3, whereas for FeLV the data could be interpreted to indicate an isoelectric point between 3 and 5. Using a Debye-Hückel model to describe the interaction between electrolytes and virus, we show that our values for the mobility of MuMTV, obtained in ionic strength 0.005, are consistent with the values of Sarkar et al. ((1973), Cancer Res. 33, 2283), obtained in ionic strength of 0.10. This model is then used to calculate surface charge densities. In terms of the density of charged groups, the RNA tumor virus envelope is not very different from the erythrocyte membrane.", "journal": "Biochemistry", "doi": "10.1021/bi00692a009", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "183735", "author": "Cockerell GL", "n_authors": 5, "title": "Lymphocyte mitogen reactivity in feline leukemia virus-infected cats and identification of feline T and B lymphocytes.", "abstract": null, "journal": "Bibliotheca haematologica", "doi": "10.1159/000399102", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "183720", "author": "Hardy WD Jr", "n_authors": 8, "title": "Prevention of the contagious spread of the feline leukemia virus between pet cats.", "abstract": null, "journal": "Bibliotheca haematologica", "doi": "10.1159/000399206", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "183678", "author": "Caldwell GG", "n_authors": 9, "title": "Seroepidemiologic testing in man for evidence of antibodies to feline leukemia virus and bovine leukemia virus.", "abstract": null, "journal": "Bibliotheca haematologica", "doi": "10.1159/000399139", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "183672", "author": "Jarrett WF", "n_authors": 1, "title": "The epidemiology of feline leukemia virus infection.", "abstract": null, "journal": "Bibliotheca haematologica", "doi": "10.1159/000399131", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "183666", "author": "Hoover EA", "n_authors": 6, "title": "Biologic and immunologic response of cats to experimental infection with feline leukemia virus.", "abstract": null, "journal": "Bibliotheca haematologica", "doi": "10.1159/000399123", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "171336", "author": "Fischinger PJ", "n_authors": 4, "title": "Two levels of restriction by mouse or cat cells of murine sarcoma virus coated by endogenous xenotropic oncornavirus.", "abstract": "Mouse and cat cells were each examined for the mode of restriction of endogenous xenotropic oncornavirus. Murine xenotropic helper virus (MuX) and its pseudo-type of Moloney murine sarcoma virus (MSV(MuX)) were grown in cat cells to high titre. MuX alone did not replicate in any mouse cell tested including normal or transformed outbred Swis 3T3 cells or SC-I cells, but did grow in a variety of other mammalian cells. MSV(MuX) was not able to achieve that intracellular state from which it could be rescued by mouse leukaemia virus (MuLV) in any mouse cell tested with the exception of SC-I cells. Detection of MSV(MuX) foci with appropriate helper virus was as sensitive in SC-I cells as in the cells of several other species. Sequential passage of MSV(MuX) virus complex in SC=I cells resulted in a loss of infectious sarcoma and helper viruses, but transformed, MSV rescuable cells were retained. If cat embryo cells were infected with either the feline endogenous xenotropic virus (FeX) or its MSV pseudotype (MSV(FeX), two analogous states of restriction were observed. FeX alone did not replicate in cat cells as measured by release of progeny virus or by FeX group-specific antigen induction. Cat cells could be susceptible or insusceptible to the entry of MSV(FeX) as measured by MSV rescue with appropriate ecotropic feline leukaemia virus. The sensitivity of detection of MSV(FeX) foci in some cat cells in the presence of feline ecotropic virus was comparable to that exhibited by cells of other mammalian species. A single strain of cat cells underwent a change in its restrictive capacity for MSV(FeX) on prolonged passage. Late passage cat cells became very insusceptible to MSV(FeX) but not to other pseudotypes of MSV. Infectious FeX or its group-specific antigens were not detected in the insusceptible cells. The major glycoprotein of FeX did appear as a surface antigen of the insusceptibel cells. It is apparent that two levels of cellular restriction can be distinguished in each of two mammalian cell systems by the susceptibility to penetration of MSV coated with endogenous xenotropic oncornavirus.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-29-1-51", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "51882", "author": "Hino S", "n_authors": 3, "title": "Antigenic determinants of the 70,000 molecular weight glycoprotein of woolly monkey type C RNA virus.", "abstract": "The 70,000 molecular weight glycoprotein (gp70) of a type-C RNA virus originally isolated from a woolly monkey has been partially purified and immunologically characterized. Evidence that this viral protein is viral coded was derived from studies showing its antigenic properties to be unaltered by virus passage in cells of different species. A broadly reactive competition immunoassay was developed utilizing antiserum prepared against feline leukemia virus to precipitate 125I-labeled woolly monkey virus gp70. Gibbon and woolly viruses, as well as feline and several mouse type-C viruses, all reacted with equal efficiency in this assay. In contrast, an endogenous virus of the baboon failed to cross-react, suggesting that viruses of this latter group are less immunologically related to the others. In a homologous competition immunoassay for the woolly viral glycoprotein, the woolly virus was readily distingusihed from otherwise colsely related viruses of gibbon apes. These findings demonstrate the pronounced type-specific antigenic dterminants possessed by this viral protein. The antigenic determinants of gp70 responsible for neutralization have also been investigated.", "journal": "Journal of immunology (Baltimore, Md. : 1950)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "50883", "author": "Sottong P", "n_authors": 4, "title": "Partial characterization of C-type particles in a cell line (WR-9) derived from a rat epidermoid carcinoma of spontaneous origin.", "abstract": "A C-type virus continuously released from a cell line (WR-9) derived from a spontaneous epidermoid carcinoma was purified by means of large-scale tissue culture techniques and high-volume zonal centrifuges. With the use of relatively pure virus concentrates, partial characterization of the virus has been accomplished. Up to 60 liters of spent culture medium from relatively low virus-yielding cultures were processed at a time through the Model K ultracentrifuge in order to obtain quantities of virus sufficient for convenient Tween-ether extraction of the major polypeptide (30,000 daltons). This structural protein having group-specific reactivity was purified and isolated by isoelectric-focusing techniques. A UV absorption peak (A280) was found to be coincident with a major peak of radioacticity at pH 8.6, the isoelectric point (pI) for rat virus gs antigen previously reported by other investigators. Because species-specific (gs-1) and cross-reactive (gs-3) determinants coexist on this protein, fractions containing the group-specific antigen were identified on the basis of the mammalian interspecies determinant (gs-3), using antiserum prepared against Tween-ether-disrupted feline leukemia virus. At the same time, reactivity to the gs-1 determinants in identical fractions was observed in complement fixation and gel diffusion assays, using guinea pig antiserum known to contain principally antibodies to rat gs-1 determinants. Presently, the principal source of rat type C viral gs antigen is rat cell line MSB, which continuously releases a rat leukemia virus pseudotype of murine sarcoma virus. The WR-9 rat virus line may be of use in providing an additional source of C-type particles that are capable of yielding good gs reagents.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "169604", "author": "Weijer K", "n_authors": 1, "title": "[The incidence of lymphosarcoma (leukaemia) and feline leukaemia virus (FeLV) in cats in the Netherlands (author's transl)].", "abstract": "Seven different groups of cats were examined to study the incidence and distribution of feline leukaemia virus (FeLV) in the Netherlands. The indirect fluorescent antibody (IFA) technique was used to detect FeLV antigen. Of the cats with lymphosarcoma (leukaemia), 73.2 per cent and of those with infectious peritonitis, 32.4 per cent were found to be positive for FeLV antigen. Of the sixty-six cats with other tumours, only one, a cat with carcinoma of the mammary gland; was positive for FeLV antigen. Of 557 cats with various lesions, forty-two (7.5 percent) were positive for FeLV antigen. The IFA-test was found to be a useful adjunct in establishing the correct diagnosis. Of all stud cats which had been in contact with FeLV-positive cats, 24.7 percent were positive for FeLV antigen, wheras all those which had not been in contact with these cats, were negative. There was a marked difference between the proportions of FeLV-positive cats in the groups of clinically normal cats which had (20.6 per cent) and which had not (0.4 per cent) been in contact with FeLV-positive cats. Follow-up studies showed that 67.8 percent of the clinically normal, FeLV-positive cats had died from or been sacrificed because of FeLV-associated diseases within twenty months.", "journal": "Tijdschrift voor diergeneeskunde", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "170737", "author": "Peebles PT", "n_authors": 1, "title": "An in vitro focus-induction assay for xenotropic murine leukemia virus, feline leukemia virus C, and the feline--primate viruses RD-114/CCC/M-7.", "abstract": null, "journal": "Virology", "doi": "10.1016/0042-6822(75)90427-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "169389", "author": "Brian DA", "n_authors": 4, "title": "Properties of feline leukemia virus. III. Analysis of the RNA.", "abstract": "The kinetics of virus labeling was used to study the maturation of viral RNA in the Rickard strain of feline leukemia virus. Viral RNA labeled over differing intervals was characterized by gel electrophoresis and velocity sedimentation in sucrose gradients made up in aqueous buffer and 99% dimethyl sulfoxide. Labeled virus was found within 30 min after adding radioactive uridine to the cells and production of labeled virus reached a maximum at 4 to 5 h after pulse labeling. Native RNA from feline leukemia virus resolved into three size classes when analyzed by electrophoresis on 2.0% polyacrylamide-0.5% agarose gels: a 6.2 x 10(6) to 7.1 x 10(6) mol wt (50 to 60S) class, an 8.7 x 10(4) mol wt (approximately 8S) class, and a 2.5 x 10(4) mol wt (4 to 5S) class. From two experiments during which RNA degradation appeared minimal, these made up to 57 to 76%, 2 to 5%, and 6 to 12%, respectively, of the total RNA. The 8S RNA in feline leukemia virus has not previously been reported. The 50 to 60S RNA from virus harvested after 4 h of labeling electrophoretically migrated faster and sedimented more slowly in sucrose gradients than did the same RNA species harvested after 20 h of labeling. This argues for an intravirion modification of the high-molecular-weight RNA. The large subunits of denatured viral RNA from both 4- and 20-h labeled-viral RNA electrophoretically migrated with an estimated molecular weight of 3.2 x 10(6) but sedimented with 28S ribosomal RNA (1.8 X 10(6) mol wt) when analyzed by velocity sedimentation through 99% dimethyl sulfoxide.", "journal": "Journal of virology", "doi": "10.1128/JVI.16.3.535-545.1975", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "50133", "author": "Olsen RG", "n_authors": 3, "title": "Antibody in cats to mammalian RNA tumor virus interspecies antigens.", "abstract": "The studies were undertaken to determine whether the cat, a mammalian species that carries xenotropic endogenous C-type virus(es) and in addition undergoes horizontally transmitted oncogenic C-type RNA tumor virus infections, responds immunologically to the mammalian C-type virus interspecies antigens. Sera from normal cats and from cats with spontaneous or virus-induced neoplasms were examined for antibodies to interspecies antigen antigen by complement-fixation inhibition, by inhibition of the paired radioiodine-labeled antibody technique (PRILAT inhibition), and by two-step radioimmunoelectrophoresis. Using three separate complement-fixation inhibition systems designed to detect antibodies to interspecies antigen(s), 23 of 23 sera from tumor-bearing cats and 24 of 31 sera from normal cats were positive in both systems. The negative sera were from germ-free cats. Among the 49 positive sera, 47 yielded titers of 1:16 or greater by one or more complement-fixation inhibition tests. Of these 47 sera, 42 were positive by the paired radioiodine-labeled antibody technique inhibition test; the 5 paired radioiodine-labeled antibody technique-negative sera were from normal specific-pathogen-free cats. Direct reaction with the interspecies determinant on the p30 protein from Rauscher murine leukemia virus by immunoglobulin from cats immunized with feline leukemia virus was shown by two-step radioimmunoelectrophoresis. The feline antibody was also identified as an immunoglobulin by column chromatography and two-step radioimmunoelectrophoresis. These antibodies did not fix guinea pig complement during reaction with the interspecies antigen. That other mammals may produce similar noncomplement-fixing (guinea pig) antibodies to RNA tumor virus antigens is likely.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "169377", "author": "Essex M", "n_authors": 11, "title": "Feline oncornavirus-associated cell membrane antigen. IV. Antibody titers in cats with naturally occurring leukemia, lymphoma, and other diseases.", "abstract": "Cats with naturally occurring leukemia and lymphoma had low or negative humoral antibody titers to the feline oncornavirus-associated cell membrane antigen (FOCMA). Geographic differences were seen in the relative frequencies of various forms of lymphoproliferative neoplasms. Lymphatic leukemia and thymic lymphoma were most common in Boston, whereas alimentary lymphoma was most frequent in Glasgow. No significant differences were found in geometric mean FOCMA antibody titers for the various forms of leukemia-lymphoma or for feline leukemia virus (FeLV)-positive as compared to FeLV-negative cats. Approximately 70% of 76 Boston cats with nonregenerative anemias were FeLV gs antigen (gsa) positive; this was similar to the percentage with leukemia-lymphoma from the same population that was positive. Fifty-five to 62% of the Boston cats with other infectious diseases, such as peritonitis and septicemia, were gsa positive. We postulate that this is due to a predisposition to infectious diseases by the immunosuppressive action of FeLV. Young cats from the Boston population that developed lymphoma, infectious peritonitis, and certain other diseases were more likely to be FeLV gsa positive than older cats with the same diseases.", "journal": "Journal of the National Cancer Institute", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "169374", "author": "Chapman AL", "n_authors": 3, "title": "Establishment of two canine sarcoma cell lines: productive infection with feline leukemia virus.", "abstract": "Two canine sarcoma cell lines (11028, 11031) were established in vitro and have been transferred 213 and 306 times, respectively, since 1970. These cell lines had a chromosome pattern consistent with their canine origin. Both cultures were infected with feline leukemia virus (FeLV), which caused a morphologic and karyotypic changes. The cells became rounded after infection with FeLV and both cultures showed the presence of a single, large, acrocentric chromosome considered to be a marker chromosome. All tumors were transplanted into newborn beagle pups, but only the 11028-FeLV formed metastatic tumors. No helper or focus-forming activity or virus particles were found in the uninfected cultures. Helper activity and virus were demonstrated in both sarcoma lines after infection with FeLV, though no focus-forming activity was noted. Helper activity of progeny virus could be assayed on either cat or dog embryo cells.", "journal": "Journal of the National Cancer Institute", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "170211", "author": "Jarrett W", "n_authors": 6, "title": "Vaccination against feline leukaemia virus using a cell membrane antigen system.", "abstract": "Cats inoculated with live feline lymphoblastoid cells of the FL74 line developed high titres of antibody to feline oncornavirus-associated cell membrane antigen (FOCMA). Eight cats were subsequently challenged with a large dose of feline leukaemia virus (FeLV) of a highly pathogenic strain. All resisted infection while 10 cats given the challenge virus alone became infected. The FeLV produced by FL74 cells was shown to be of extremely low infectivity in cats and in cultured feline cells. Cats inoculated with either FL74 cells or virus purified from them did not become infected. The purified virus did not induce FOCMA antibody in cats not previously exposed to FeLV. The fact that FL74 cells are highly immunogenic, but produce virus of low infectivity, is of value in devising vaccines against FeLV. Cats were also inoculated with FL74 cells which had been inactivated with paraformaldehyde. They developed FOCMA antibody, reaching a peak titre of 256, and no virus could be cultured either from the vaccine preparations or from the tissues of the cats.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910160115", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "170454", "author": "Jarrett O", "n_authors": 1, "title": "Natural history of feline leukaemia virus.", "abstract": null, "journal": "The Journal of small animal practice", "doi": "10.1111/j.1748-5827.1975.tb05764.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "167623", "author": "Whitman JE Jr", "n_authors": 4, "title": "An unusual case of feline leukemia and an associated syncytium-forming virus.", "abstract": "A 3-year-old female Siamese cat was admitted to a local animal hospital with a history of recent extreme lethargy and anorexia. A hemorrhagic tumor was removed from an area of oral buccal skin and diagnosed histopathologically as lymphosarcoma. Rapid physical deterioration occurred, and the cat became moribund 2 weeks after surgical operation. Necropsy revealed at least 200 spherical hemorrhagic neoplastic nodules attached to the omentum, mesentery, and peritoneum. Examination of histopathologic sections confirmed the striking characteristics of an extremely vascular and highly invasive malignant lymphoma, which was designated feline tumor No. 01 (FeT-01). There was no evidence of peripheral blood leukemia. Electron microscopic examination of tumor tissue revealed numerous viral particles having characteristics common to both feline leukemia virus (FeLV) and feline syncytium-forming virus (FeSFV). Primary cells and cultures propagated from tumor tissue were found to be negative or weakly positive for group-specific (gs) antigen by radioimmunoassay but strongly positive when assayed by indirect immunofluorescence. Co-cultivation of cells from tumor tissue, with normal prescreened feline embryo cells, revealed the presence of numerous FeSFV-like viral particles in the absence of C-type virus. A FeSFV was isolated from these passaged cells, with characteristics similar to FeSFV isolates previously described in the literature. The apparent presence of FeSFV in lymphosarcomatous tissue and the apparent absence of FeLV C-type particles in passaged cells indicate the need to make a more intensive study of the FeSFV group of viruses and the possible etiologic relationship to feline malignancies.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "165603", "author": "Hardy WD Jr", "n_authors": 2, "title": "Infectious spread and control of feline leukemia virus.", "abstract": null, "journal": "Transplantation proceedings", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "49443", "author": "Sherr CJ", "n_authors": 4, "title": "Interspecies antigenic determinants of the reverse transcriptases and p30 proteins of mammalian type C viruses.", "abstract": "The major internal structural proteins (p30) of type C viruses isolated from several mammalian species were studied by radioimmunoprecipitation and competitive radioimmunoassays. Three antigenically distinguishable sets of interspecies determinants could be demonstrated by both methods. One set of determinants shared by viruses of rodent origin (mouse and rat) can be detected readily in feline leukemia viruses but not in other type C viral groups. The p30 proteins of murine viruses also contain a second discrete set of antigenic determinants related to those in infectious primate viruses and endogenous porcine viruses, but not detected in the feline leukemia virus group. The p30 proteins of endogenous viruses of baboons and domestic cats share yet a third set of cross-reactive determinants not detected in type C viruses isolated from other species of animals. Enzyme inhibition studies performed with antisera raised toward the reverse transcriptases of these same groups of type C viruses showed the same patterns of immunological cross-reactions as observed with p30 proteins. The antigenic cross-reactions between the homologous proteins of type C virus isolated from genetically distant animals may reflect transmission of type C viruses across species barriers.", "journal": "Journal of virology", "doi": "10.1128/JVI.15.6.1440-1448.1975", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "49060", "author": "Oskarsson MK", "n_authors": 6, "title": "A p60 polypeptide in the feline leukemia virus pseudotype of Moloney sarcoma virus with murine leukemia virus p30 antigenic determinants.", "abstract": "A 60,000-dalton polypeptide (p60) has been identified in the feline leukemia virus (FeLV) pseudotype of Moloney sarcoma virus [MSV(FeLV)]. This polypeptide is present in the purified virus complex in concentrations greater than either the murine p30 or the feline p27. Purified p60 crossreacts immunologically with murine p30 group antiserum and contains several interspecies determinants, whereas the group specific determinant of FeLV p27 is not detected. Comparison of peptide fingerprints of p60 and murine p30 show many peptides in common. Limited digestion of p60 with either trypsin or chymotrypsin produced p30-35 and p20 peptides which retain the MuLV p30 group and interspecies antigenic activities. The p30 produced by both enzymes comigrates in polyacrylamide gels with the murine p30 of MSV(FeLV), thus suggesting that p60 may be an uncleaved precursor to p30.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.72.6.2380", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "166947", "author": "Rogerson P", "n_authors": 3, "title": "Epidemiological studies on feline leukaemia virus infection. I. A serological survey in urban cats.", "abstract": "A survey of the incidence of feline leukaemia virus (FeLV) infection in cats in a large urban area was made by studying the prevalence of antibodies to feline leukaemia virus-associated cell membrane antigens. Two serological tests were used, immunofluorescence and a mixed immunoglobulin rosette technique. The overall incidence of cats with antibodies was 40%, contrasting with 6% in the surrounding rural area. Only 6% of urban kittens were positive while 50% of adults had antibodies. The incidence in adults rose from 29% at 5-6 months to 74% in cats over 3 years. Stray cats had an incidence twice as high as that of domestic pets. These results support and extend earlier findings that FeLV infection is common and is horizontally transmitted.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910150509", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "50852", "author": "Epstein LB", "n_authors": 2, "title": "Studies on mouse Moloney virus induced tumours: I. The detection of p30 as a cytotoxic target on murine Moloney leukaemic spleen cells, and on an in vitro Moloney sarcoma line by antibody mediated cytotoxicity.", "abstract": "Antigenic determinants of p30, the most abundant internal virion protein of C type RNA viruses, were detected on the surface of spleen cells from mice bearing Moloney leukaemia and on an in vitro line of Moloney sarcoma, MSC. On both cell types, these determinants on the p30 molecules served as cytotoxic targets in a xenogenic complement dependent antibody mediated 51Cr release assay. Two antisera were used: a rat anti MLV -M induced lymphoma serum, and an antiserum raised in goats to either disrupted FeLV. The cytotoxic target antigens of these antisera were analysed by inhibition of cytotoxicity with viral and cellular proteins.", "journal": "British journal of cancer", "doi": "10.1038/bjc.1975.90", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "163696", "author": "Mackey L", "n_authors": 3, "title": "A mixed-immunoglobulin rosette technique for detection of antibody to feline oncornavirus-associated cell membrane antigen.", "abstract": "A mixed-immunoglobulin rosette technique has been developed for the detection of antibodies to feline oncornavirus-associated cell membrane antigens. Lymphoblastoid cells infected with feline leukemia virus were incubated with test sera and then fixed in paraformaldehyde. They were then exposed to a rabbit anti-cat immunoglobulin G serum. Antigen-antibody reactions were detected by mixing the cells with sheep erythrocytes sensitized with cat anti-sheep red blood cell serum; the presence of cat antibody on the lymphoid cells was registered by the formation of sheep red blood cell rosettes around them. The method was shown to be at least 10 times more sensitive than indirect immunofluorescence. A high degree of correlation was shown between the mixed-immunoglobulin rosette and indirect immunofluorescence tests, using both feline leukemia virus-infected cat and dog cells as targets. The results indicate that the tests are likely to be measuring similar reactions. Using the indirect immunofluorescence test we found that 75% of cats with lymphoid neoplasia had no demonstrable antibodies. Twenty-four of such indirect immunofluorescence-negative sera were tested by the mixed-immunoglobulin rosette technique; antibody was shown in at least seven of these sera.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "170952", "author": "Jarrett WF", "n_authors": 1, "title": "The relation of immune response to pathogenesis, vaccination and epidemiology in virus induced leukaemia.", "abstract": "The antigenic systems of oncornaviruses and particularly feline leukaemia virus (FeLV) are reviewed briefly. The use of immunological methods in studying the epidemiology of the disease is described. The incidence of FeLV infection as judged by a serological survey is at least 100 times greater than that of leukaemia in the cat population. Horizontal transmission, due to virus replication in respiratory and alimentary epithelial cells, is common. A method of producing high titres of antibody against membrane antigens of virus infected cells is described; the use of such vaccination is discussed in relation to several epidemiological facets of feline leukaemia virus infection. Leukaemia viruses are well known to cause immunodepression to heterologous antigens. The hypothesis is advanced that depression of the humoral antibody response to leukaemia virus antigens and cell membrane antigens may be an early event allowing establishment and replication of virus in haemic and the lymphatic tissues. Subsequent depression of cell mediated immunity through direct action of thymic cells is known to take place in the cat system. This may allow further spread of the virus with replication in epithelial cells which are not susceptible to cytotoxic action. Thus the primary events leading to leukaemogenesis may be an interplay between immunostimulation and immunodepression.", "journal": "The British journal of cancer. Supplement", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "164569", "author": "Al-Adhami R", "n_authors": 2, "title": "Aberrant viruses in cells infected with murine sarcoma virus-feline leukemia virus.", "abstract": "This study describes an unusual type of virus seen when a feline leukemia virus (FeLV) pseudotype of murine sarcoma virus (MuSV) obtained by cocentrifugation procedures infected feline embryo cells (FEF) and two Crandell cat cell lines (CrFK1, CrFK2). When all three cell cultures were infected with MuSV-FeLV, only FEF and CrFK2 were transformed and only these showed normal and aberrant virus. The CrFK1 infected with MuSV-FeLV did not transform but did replicate normal type-C virus with a 50-A intermediate coat. The virus replicated in the two transformed lines showed three particles; a normal particle with a 50-A intermediate coat, a normal particle with a 100-A intermediate coat, and an aberrant particle with a 100-A intermediate coat.", "journal": "Journal of the National Cancer Institute", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "164563", "author": "Essex M", "n_authors": 6, "title": "Feline oncornavirus-associated cell membrane antigen. III. Antibody titers in cats from leukemia cluster households.", "abstract": "Serum samples from 182 healthy cats residing in environments known to have a natural exposure to feline leukemia virus (FeLV) were examined for the presence of antibody to the feline oncornavirus-associated cell membrane antigen. The number included 138 cats from leukemia-\"cluster\" households. Such cats previously showed greatly increased frequencies of FeLV infection, as determined by the virus group-specific antigen (gasa) in peripheral blood leukocytes and platelets. The geometric mean antibody titer for all 182 cats with known exposure to FeLV was 4.69, more than four times higher than the mean titer for healthy pet cats from the same geographic areas but with no known FeLV exposure. About 92 percent of the cats in exposure environments were positive for FeLV gsa or feline oncornavirus-associated cell membrane antigen (FOCMA) antibody, and gsa-positive cats had lower FOCMA antibody geometric mean titers than gsa-negative cats. In the exposure environments, no differences were seen for cats of different sexes, but a higher geometric mean antibody titer was observed for cats 5 years and over when compared to younger groups. These results prove that previous reports of increased incidences of leukemia in cluster households were not due to chance alone, but rather to increased infection rates of cats in the FeLV environment. Also, they suggest that horizontal transmission of FeLV is highly efficient under crowded conditions, and that most cats naturally exposed to virus elicit an active immune response.", "journal": "Journal of the National Cancer Institute", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "164562", "author": "Essex M", "n_authors": 8, "title": "Feline oncornavirus-associated cell membrane antigen. II. Antibody titers in healthy cats from household and laboratory colony environments.", "abstract": "Antibody titers to the feline oncornavirusassociated cell membrane antigen (FOCMA) were determined for 447 healthy cats from laboratory colony and household environments. Only 2.7 percent of 221 cats from colony environments were antibody positive as compared to 50.4 percent of 256 cats from household environments. Incidence of FOCMA antibody and geometric mean antibody titer for pet cats from New York City representing single cat apartment habitats were substantially lower than values for unscreened cats from the Boston, Glasgow, and Detroit suburban environments. Geometric mean antibody titer for young adults in the Boston population was significantly higher than titers for kittens or aged cats. This may be due to greater mobility resulting in increased exposure to other cats. In contrast to the high frequency of FOCMA antibody positivity in pet-cat populations, less than 2 percent of the same groups were positive for virus group-specific antigen in peripheral blood leukocytes and platelets. This was interpreted as an indication that many more cats became infected with feline leukemia virus under natural conditions that the number developing persistent virus infection and/or clinical leukemia.", "journal": "Journal of the National Cancer Institute", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "163793", "author": "Essex M", "n_authors": 5, "title": "Naturally occurring persistent feline oncornavirus infections in the absence of disease.", "abstract": "Healthy feline leukemia virus (FeLV)-infected cats from leukemia cluster environments were followed for up to 23 months for development of disease and evidence of alteration in the hemogram. The incidence of disease development in FeLV-postive cats was more than fivefold higher than the incidence for FeLV-negative cats. Ten cases of leukemia developed in 69 infected cats, whereas one case of leukemia occurred in 59 uninfected cats. The incidence for development of diseases other than leukemia was 30.4 percent for FeLV-infected cats as opposed to 6.8 per cent for uninfected cats. This could be a result of the immunosuppressive effects of FeLV. Felv-infected cats had no evidence of subclinical anemia. Mean packed cell volumes and total leukocyte counts were about the same for infected and uninfected animals. The only variation seen in healthy FeLV-infected cats was a decreased mean lymphocyte count. The difference between mean lymphocyte count for FeLV-infected and uninfected animals was significant at the 0.999 level. These findings suggest that the incubation period for feline leukemia may be very prolonged under natural conditions and that an increased susceptibility to unrelated infectious diseases exists during this period. This increased susceptibility was apparently not associated with anemia or depressed total leukocyte counts.", "journal": "Infection and immunity", "doi": "10.1128/iai.11.3.470-475.1975", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "163371", "author": "Pal BK", "n_authors": 2, "title": "Phosphoproteins: structural components of oncornaviruses.", "abstract": "Oncornaviruses, which contain a virion-associated protein kinase, were found to possess phosphoproteins as virion structural components. One major phosphoprotein common to strains of laboratory and wild mouse oncornaviruses and a strain of feline leukemia virus was shown to be a polypeptide of about 12, 000 mol wt. In addition to this, the Kirsten strain of murine sarcoma virus contained a second major phosphoprotein of about 10, 000 mol wt, and mouse erythroblastosis virus contained a second major phosphoprotein that was either identical to or comigrated with the virion glycoprotein of about 74, 000 mol wt. The major phosphoprotein of RD-114 virus was found to be of about 16, 000 mol wt. The major phosphoamino acid of the 12, 000-mol wt polypeptide of the mouse erythroblastosis virus was identified as phosphoserine, and that of the 16, 000-mol wt polypeptide of the RD-114 virus was identified as phosphothreonine.", "journal": "Journal of virology", "doi": "10.1128/JVI.15.3.540-549.1975", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "163223", "author": "Cotter SM", "n_authors": 3, "title": "Association of feline leukemia virus with lymphosarcoma and other disorders in the cat.", "abstract": "Two hundred fifty Boston cats with disorders such as lymphosarcoma, myeloproliferative disease, anemia, glomerulonephritis, pregnancy abnormalities, feline infectious peritonitis, toxoplasmosis, and various bacterial infections were examined for feline leukemia virus (FeLV) by immunofluorescence. Antibody titers against feline oncornavirus-associated cell membrane antigen (FOCMA) were tested in 133 of these cats. The tests for FeLV and FOCMA antibody were also conducted among healthy cats not known to have been exposed to FeLV, as well as among healthy cats from households where FeLV was known to be present. Most of the cats with lymphosarcoma and the other aforementioned disorders were infected with FeLV and low FOCMA antibody titers. Healthy cats known to have been exposed to FeLV were often viremic, but those that remained healthy were able to develop high FOCMA antibody titers. Healthy cats without known prior exposure to FeLV were unlikely to be viremic but often had detectable FOCMA antibody titers, indicating that some exposure occurs under natural conditions in the Boston area. The association of FeLV with infections other than lymphosarcoma was assumed to be caused by the immunosuppresive effect of FeLV, thus allowing development of disease.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "164675", "author": "Wang JT", "n_authors": 2, "title": "Demonstration of feline leukemia virus antibody in cats by passive hemagglutination (38583).", "abstract": "Two FeLV fractions from Sephadex G-150 gel filtration were used to sensitize RBC for the PHA test. When the cells were coated with the fraction from the second peak consisting mostly of a mojor gs antigen of FeLV, no antibodies could be detected either in hyperimmunized cat sera or sera from leukemic cats, whereas antibodies were readily detectable in immunized rabbits. Using cells coated with the first peak eluants or Tween-ether disrupted FeLV, PHA antibodies were detected in cat sera. There existed, however, one significant exception that a cat with the diagnosis of mast cell leukemia showed antibody against the second peak fraction. Little or no antibodies could be detected in cat sera by CF or gel-diffusion. There was some correlation between hemagglutinating antibodies and conglutinating complement absorbing antibodies, but these antibodies did seem to differ from neutralizing antibody.", "journal": "Proceedings of the Society for Experimental Biology and Medicine. Society for Experimental Biology and Medicine (New York, N.Y.)", "doi": "10.3181/00379727-148-38583", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "163515", "author": "Mackey L", "n_authors": 1, "title": "Feline leukaemia virus and its clinical effects in cats.", "abstract": "Feline leukemia virus (FeLV) infection is common among cats where contact is high. The virus can be transmitted readily between cats. It causes a variety of haemopoietic and lymphoid neoplasms; the most common types are alimentary, multicentric and thymic lymphosarcoma and lymphatic leukaemia. The virus is involved in the aetiology of certain other diseases including anaemia, glomerulonephritis and an immunosuppressive syndrome which predisposes cats to intercurrent infections. Many infected cats mount an immune response and do not suffer from any of these. The immune status is shown by serum antibody levels to feline leukaemia virus associated cell membrane antigens. Cats with a titre of 32 or more are most unlikely to suffer any ill effects and may eliminate the virus infection. The outcome of infection in an individual cat depends on the immunological competence of the cat, the dose of virus received and its ability to induce immunosuppression. FeLV infection can be detected by examination of tissues by electron microscopy, and by culture of virus from plasma and other tissues. In the United States, a method is now in use for the detection of leukaemia virus antigen in peripheral blood leukocytes; this is carried out on ordinary blood films. Successful prototype vaccines have been developed against FeLV. This paper describes the natural history of the virus, the diseases in which it is implicated and discusses recently developed diagnostic methods.", "journal": "The Veterinary record", "doi": "10.1136/vr.96.1.5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "179729", "author": "Hadden JW", "n_authors": 1, "title": "Feline leukemia virus research- an update.", "abstract": null, "journal": "Clinical bulletin", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "175893", "author": "Parodi AL", "n_authors": 1, "title": "[Feline leukemogenic and sarcomatogenic viruses].", "abstract": "Feline Leukemia and sarcoma viruses (FeLV, FeSV) are RNA viruses, belonging to the Oncornavirus group. They possess common morphological, biochemical and immunological properties, with viruses of leukemia and sarcoma already known in others mammalian and avian species. FeLV is widely present in feline population and its transmission is by horizontal way. FeLV and FeSV are oncogenic for others species, i.e., dog and some non-human primates but as far as we know, the human receptivity is not established. A correlation between humoral antibody directed against membran new-antigens and regression of tumors induced by FeSV, led to actual investigations on vaccination.", "journal": "Comptes rendus des seances de la Societe de biologie et de ses filiales", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "171892", "author": "Micheel B", "n_authors": 7, "title": "Serological analysis of an oncornavirus (PMF virus) detected in malignant permanent human cell lines.", "abstract": "Immunodiffusion analysis of the PMF virus which was detected in malignant permanent human cell lines revealed positive reactions with antisera against the Mason-Pfizer monkey virus (MPMV). No cross-reactivity was demonstrated with murine leukemia virus (MuLV), rat leukemia virus (RaLV), hamster leukemia virus (HaLV), feline leukemia virus (FeLV), simian (woolly monkey) sarcoma virus (SSV-1) and mouse mammary tumor virus (MTV). The cross-reactive antigens of the PMF virus and the MPMV are considered as evidence for the human origin of the PMF virus.", "journal": "Acta biologica et medica Germanica", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "169838", "author": "Maruyama K", "n_authors": 4, "title": "In vitro transformation of cells from human neoplasms.", "abstract": "The possible involvement of RNA tumor virus genomes in human cell transformation was investigated. Forty-nine cell cultures from neoplastic, normal, or embryo tissues were examined for transformation, following inoculation of murine leukemia virus (MuLV), feline leukemia virus (FeLV) grown in human cells, or bone marrow aspirates from leukemia patients. Five cultures exhibited transformation (1 after inoculation of MuLV grown in human cells; 4 after inoculation of human leukemic bone marrow), and 4 were established as cell lines. They were derived from giant cell tumor and fibrosarcomas. The established transformed cells formed colonies in soft agar, grew progressively in immunosuppressed mice, and carried antigens common to FeLV and MuLV. Although virus particles were not seen in these cultures, 68S RNA was detected in their media. Medium from nontransformed parent cultures also contained 68S RNA but in amounts about 15 times less than in transformed cultures. Transformed human cells passaged in mice produced both type C virus particles and 68S RNA. Antigens common to MuLV and FeLV were found in these particles. However, the results of biological and serological studies indicate their difference from conventional MuLV and FeLV. The relationship of this virus and 68S RNA found in transformed cultures remains to be determined.", "journal": "Bibliotheca haematologica", "doi": "10.1159/000397521", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "169834", "author": "Hardy WD Jr", "n_authors": 6, "title": "Horizontal transmission of feline leukemia virus in cats.", "abstract": "Traditionally, cancer has not been considered an infectious disease although some multiple cases of leukemia in man and cattle have been reported. The discovery that feline lymphosarcoma was associated with an RNA virus (feline leukemia virus(FeLV)) meant that infectious transmission of the disease was a possibility. The critical question was whether the predominant method of transmission from one animal to another was 'vertical' (via the gametes) or 'horizontal' (via contagion or infection). A number of epidemiological studies have shown that the chances of healthy cats contracting lymphosarcoma are greatly increased when a cat with the disease lives in close proximity. It does not matter whether the healthy cats are related to the sick animal or not. It has also been established that viremic normal cats have an approximately 900 times greater chance of developing leukemia than cats whose FeLV status is unknown. Infectious FeLV is present in the excretions and blood of viremic animals. In the natural environment, feline lymphosarcoma occurs in clusters. The results in pet cats have been supported by experiments with cat colonies under controlled conditions and prove that horizontal transmission of FeLV occurs. This does not mean that epigenetic (infection in utero or via the milk) or vertical transmission cannot also occur. It should be possible to break the cycle of horizontal transmission of the virus by vaccination and thus control FeLV-related diseases.", "journal": "Bibliotheca haematologica", "doi": "10.1159/000397519", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "169821", "author": "Sarma PS", "n_authors": 3, "title": "In vitro host range of feline leukemia virus.", "abstract": null, "journal": "Bibliotheca haematologica", "doi": "10.1159/000397566", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "169819", "author": "Olsen RG", "n_authors": 3, "title": "Complement-fixation-inhibition as a test for antibodies in cats and humans to C-type RNA tumor virus antigen.", "abstract": "The complement-fixation-inhibition (CFI) test was evaluated as a means of detecting humoral antibodies in cat sera and in human sera to mammalian C-type RNA virus interspecies antigen(s). CFI antibody titers of greater than or equal 1:2 were detected in sera from all tumor bearing (23) and normal cats (23), however, sera from most germ free cats were negative. When the same cat sera were tested for blocking antibody by the paired radioiodine labeled antibody technique the correlation between the radioimmune assay and CFI tests was 85%. Sera from 378 cancer patients and 193 normal people were tested for antibodies to the mammalian oncornavirus interspecies-specific antigen in the CFI test. This test used a rabbit antiserum prepared toward a purified feline leukemia virus (FeLV) interspecies antigen. Disrupted Rauscher murine leukemia virus (RLV) was used as source of interspecies antigen in the CFI test. A significantly (P=0.01) higher number of reactions occurred with sera from patients with lymphosarcoma (70.4%), osteosarcoma (41.0%), reticulum cell sarcoma (56.7%), and rhabdomyosarcoma (31.8%) as opposed to sera from normal individuals (6.2%). Of 51 sera from patients with acute lymphocytic leukemia 23.5% (P=0.05) were reactive. Of the sera from 88 breast cancer patients 22.7% reacted, as opposed to 7.8% of 116 normal females and 13.9% of 43 patients with benign breast disease. CFI antibody titers were shown to be dependent on RLV antigen concentration. Absorption with human A and B red blood cell (RBC) and Forssman antigen did not reduce the CFI titers in human sera whereas absorption with RLV reduced them significantly. By indirect radioimmunoelectrophoresis the antibody in selected human sera was shown to be an IgG.", "journal": "Bibliotheca haematologica", "doi": "10.1159/000397560", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "163317", "author": "Mackey L", "n_authors": 4, "title": "Anemia associated with feline leukemia virus infection in cats.", "abstract": "The types of anemia associated with natural and experimental feline leukemia virus (FeLV) infection in cats were investigated. In one experiment, 10 kittens were inoculated neonatally with Jarrett FeLV-1, an isolate of subgroup A; 6 developed anemia a few weeks later. This anemia was characterized by macrocytosis, normoblastosis, increased erythropoiesis in the bone marrow, and extramedullary hematopoiesis in the spleen. Anemia was transient and nonfatal and occurred before the onset of lympoid malignancy. The same type of anemia was also seen in 9 of 24 kittens inoculated with Jarrett FeLV-9 of subgroups A and B. A different form of anemai occurred in another experiment in which 10 kittens were inoculated with FeLV-C of subgroup C only. All 10 kittens developed a profound aplastic or erythroblastopenic anemia in which the bone marrow became depleted of erythroid tissue; all kittens died within 16 weeks, most as a direct result of anemia. In an experiment in which kittens were inoculated with FeLV-B of subgroup B only, no kitten showed anemia. Cats with naturally acquired, nonleukemic lymphosarcoma were also studied. Of 33 lymphosarcomas in which myelophthisis was excluded as a cause, 54% of the affected cats had anemia, the features of which were consistent with hemolytic origin. When virus could be grown from these lymphosarcomas, it was of subgroup A alone or a combination of A and B. With one exception, anemic cats had low or negative titers to feline oncornavirus-associated cell membrane antigens. Until more isolates have been tested, it is not known if the various hematologic changes reflected differences in the pathogenic effects of the subgroups of the virus or of types of strains within them.", "journal": "Journal of the National Cancer Institute", "doi": "10.1093/jnci/54.1.209", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "54444", "author": "Chapman HP", "n_authors": 4, "title": "Species and interspecies radioimmunoassays for rat type C virus p30: interviral comparisons and assay of human tumor extracts.", "abstract": "The major internal protein, p30, of rat type C virus (RaLV) was purified and utilized to establish intra- and interspecies radioimmunoassays. Three rat viruses were compared in homologous and heterologous intraspecies assays with no evidence of type specificity. The only heterologous viruses to give inhibition in these species assays were the feline (FeLV) and hamster (HaLV) type C viruses; these reactions were incomplete and required high virus concentrations. An interspecies assay using a goat antiserum prepared after sequentially immunizing with FeLV, RD 114, and woolly monkey virus p30's and labeled RaLV p30 was inhibited by all mammalian type C viruses, although preferentially by RaLV, FeLV, and HaLV. Thus, as in a previously reported assay developed with HaLV p30, rat, hamster, and cat p30's seem more closely related to each other than to mouse type C virus p30. High levels of specific antigen were found in all cell lines producing rat virus, whereas embryonic tissues from several rat strains and cell lines considered virus-free based on other tests were negative for p30. Rats bearing tumors containing Moloney murine sarcoma virus (RaLV) did not contain free circulating antibody to RaLV p30. Fifty-one human tumor extracts (including two tumor cell lines) were tested for activity in the RaLV species and 47 in the interspecies assays after Sephadex gel filtration and pooling of material in the 15,000- to 40,000-molecular-weight range. At a sensitivity level of 7 ng/ml (0.7 ng/assay) in the interspecies assay, all human tissues, with one exception, were negative. The one positive result is considered nonspecific based on proteolysis of the labeled antigen. Input tissue protein of the purified tumor extracts averaged 1.9 mg/ml with a range of less than 0.025 to 22 mg/ml. Tissues from NIH Swiss mice processed in the same manner were positive in the interspecies assay but negative in the intraspecies RaLV assay.", "journal": "Journal of virology", "doi": "10.1128/JVI.17.1.51-59.1976", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "186414", "author": "Levin R", "n_authors": 4, "title": "Expression of feline type-C virus in normal and tumor tissues of the domestic cat.", "abstract": "Tumor and normal tissues from domestic cats were examined for FeLV and RD-114 specific nucleic acids and proteins. Virus-positive tissues showed a 100- to 200-fold higher level of FeLV and a 200- to 400-fold higher level of FeLV p30 than virus-negative tumors and normal cat tissues. In contrast, the levels of RD-114 viral RNA and p30 antigen were comparable in the majority of tumorous and normal tissues examined. When the DNA of these tissues was examined for FeLV-related sequences, the virus-positive tumors were found to contain extra copies of FeLV DNA. Virus-negative tumors contained DNA sequences homologous with FeLV but the copy number of these sequences could not be distinguished from normal tissues. The results indicate that in certain FeLV-induced type-C lymphoproliferative diseases, extra type-C sequences not present in normal tissues can be identified.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910180515", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "187790", "author": "Cockerell GL", "n_authors": 5, "title": "Lymphocyte mitogen reactivity and enumeration of circulating B- and T-cells during feline leukemia virus infection in the cat.", "abstract": "Mitogen-induced blast transformation of peripheral blood lymphocytes and quantitative changes in circulating T- and B-cells were studied serially in cats inoculated with feline leukemia virus (FeLV). Concanavalin A-induced blast transformation sharply declined beginning at 5 weeks post inoculation (Pl) in FeLV-infected cats when compared to age-matched uninfected control cats. Similar but less consistent changes were seen in responses to pokeweed mitogen-induced stimulation. In most infected kittens this defect persisted until they died from thymic lymphosarcoma, 15-24 weeks Pl. An early lymphopenia, due primarily to a decrease in circulating B-cells, occurred in infected cats 5-8 weeks Pl. Following a return of total and B-lymphocytes to control values, infected cats developed increased numbers of T-cells at 16 or more weeks Pl, which correlated with circulating lymphoblastic lymphocytes bearing T-cell markers. These results correlated neoplasia arising in a thymus-derived lymphocyte population with mitogenic hyporeactivity in the preneoplastic period and suggested that FeLV-induced immune alterations may be a necessary antecedent of leukemogenesis in the cat.", "journal": "Journal of the National Cancer Institute", "doi": "10.1093/jnci/57.5.1095", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "186536", "author": "Ruscetti SK", "n_authors": 2, "title": "Natural immunity in cats to feline leukemia viral antigens.", "abstract": "An isotopic antiglobulin assay was developed to measure antibodies in \"normal\" cats to FOCMA, a cell surface antigen associated with immunity to FeLV-induced tumors. The assay was shown to be specific for detecting FOCMA antibody by several criteria including a correlation with cell membrane immunofluorescence and absorption tests. Antibody to FOCMA developed following FeLV infection and was expressed in heterologous species. In combination with an assay for antibody to FeLV p30, the major virion structural protein, 200 cats sera from three different geographic areas were examined for evidences of FeLV-type-C-virus infection. Approximately 17% of all sera examined contained antibody to FOCMA. Antibodies directed to the FeLV p30 were detected in 8 of the sera and only in cats with FOCMA antibody. The correlation in cat sera between antibody to FOCMA and FeLV p30 antigen suggests that both are associated with the same process, infection with FeLV type-C-virus. The relationship of the observed pattern of antibody response is discussed in relation to other horizontally transmitted RNA-containing viruses.", "journal": "Journal of immunology (Baltimore, Md. : 1950)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "185780", "author": null, "n_authors": 0, "title": "Control of feline leukaemia virus infection.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.99.16.303", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "187781", "author": "Cockerell GL", "n_authors": 5, "title": "Characterization of feline T-and B-lymphocytes and identification of an experimentally induced T-cell neoplasm in the cat.", "abstract": "Membrane markers of feline T- and B-lymphocytes were identified for further investigation of leukemogenesis in the cat. Feline T-cells formed spontaneous erythrocyte rosettes with guinea pig (GPE) and rat erythrocytes (RE). The receptors for GPE and RE were separate entities and expressed independently on lymphoid cell membranes. The RE receptor appeared to be present only on more mature or differentiated T-cells, whereas the GPE receptor reacted with a broader population that included less differentiated T-cells. Feline B-cells bore a complement receptor that was detected by adherence of SE coated with antibody and complement. Malignant lymphoblasts obtained from thoracic fluid of cats with feline leukemia virus (FeLV)-induced thymic lymphosarcomas, as well as FL-74 cells (a FeLV-transformed feline lymphoblastoid cell line) expressed T-cell markers. These results provided definitive evidence for markers of feline T- and B-cells and identified an experimentally induced T-cell lymphosarcoma.", "journal": "Journal of the National Cancer Institute", "doi": "10.1093/jnci/57.4.907", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "185459", "author": "Weijer K", "n_authors": 2, "title": "The presence of leukaemia (lymphosarcoma) and feline leukaemia virus (FeLv) in cats in The Netherlands.", "abstract": null, "journal": "The Journal of small animal practice", "doi": "10.1111/j.1748-5827.1976.tb06925.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "185422", "author": "Okasinki GF", "n_authors": 2, "title": "Analysis of intracellular feline leukemia virus proteins. I. Identification of a 60,000-dalton precursor of feline leukemia virus p30.", "abstract": "The synthesis and release of feline leukemia virus p30 was studied using a permanently infected feline thymus tumor cell line. Disrupted cells were divided into two subcellular fractions, a cytoplasmic extract (CE) representing cellular material soluble in 0.5% NP-40 and a particulate fraction (PF) insoluble in 0.5% NP-40 but soluble in 0.2% deoxycholate and 0.5% NP-40. Intracellular feline leukemia virus p30 was isolated from infected cells by immune precipitation with antiserum to p30 and subsequent sodium dodecyl sulfate-polyacrylamide gel electrophoresis of the precipitated proteins. Cells labeled for 3 h with [35S]methionine contained equal amounts of p30 in both the CE and the PF. p30 synthesis was estimated to be 0.8% of the total host cell protein synthesis. Immune precipitates from cell pulse labeled for 2.5 min contained a labeled 60,000-dalton polypeptide (Pp60) in the PF and a polypeptide in the CE that comigrated with feline leukemia virus p30 in sodium dodecyl sulfate-polyacrylamide gel electrophoresis. When cells were chased after a pulse label, there was a rapid loss of Pp60 in the PF and an accumulation of p30 in the CE within 30 min followed by distribution of p30 in both the PF and the CE. Estimation of intracellular and extracellular p30 levels during a 0.5- to 24-h chase period suggested that most of the newly synthesized p30 was incorporated into extracellular virus. Typtic peptide analysis of labeled Pp60 and p30 demonstrated the presence of 13 of 15 p30 peptides within the Pp60 molecule. The tryptic peptide analysis in concert with the pulse-chase labeling data provides strong evidence that Pp60 is a precursor of p30.", "journal": "Journal of virology", "doi": "10.1128/JVI.20.1.96-106.1976", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "185408", "author": "Thomason AR", "n_authors": 4, "title": "Methylation of high-molecular-weight subunit RNA of feline leukemia virus.", "abstract": "The high-molecular-weight subunit RNA of feline leukemia virus (Rickard strain) (FeLV-R) was analyzed for the presence of methyl groups. After purification of native 50-60S FeLV-R RNA on nondenaturing aqueous sucrose density gradients. FeLV-R 28S subunit RNA, doubly labeled with [14C]uridine and [methyl-3H]methionine, was isolated by centrifugation through denaturing sucrose density gradients in dimethyl sulfoxide. As calculated from their respective 3H/14C ratios. FeLV-R 28S RNA was methylated to the same degree as host cell poly(A)+ mRNA. When the 28S FeLV-R RNA was hydrolyzed to completion with RNase T2 or alkali, all of the methyl-3H chromatographed with mononucleotides on Pellionex-WAX, a weak anion exchanger. The methyl-labeled material co-chromatographed with 6-methyladenosine if the mononucleotide fraction obtained by Pellionex-WAX chromatography was hydrolyzed to nucleosides by bacterial alkaline phosphatase or with 6-methyladenine if purine bases were released from the mononucleotides by acid hydrolysis. In another experiment in which FeLV-R 28S RNA uniformly labeled with 32P was hydrolyzed and then analyzed by Pellionex-WAX chromatography, all of the 32P label again co-chromatographed with mononucleotides. Thus FeLV-R 28S RNA does not appear to contain a 5' structure, either methylated or nonmethylated similar to those recently reported for cellular and some animal virus mRNA's.", "journal": "Journal of virology", "doi": "10.1128/JVI.20.1.123-132.1976", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "183148", "author": "Hardy WD Jr", "n_authors": 8, "title": "Prevention of the contagious spread of feline leukaemia virus and the development of leukaemia in pet cats.", "abstract": null, "journal": "Nature", "doi": "10.1038/263326a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "184578", "author": "Bradley RL", "n_authors": 1, "title": "A case of feline infectious anemia (haemobartonellosis) with simultaneous feline leukemia virus.", "abstract": null, "journal": "Veterinary medicine, small animal clinician : VM, SAC", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "187771", "author": "Hoover EA", "n_authors": 5, "title": "Feline leukemia virus infection: age-related variation in response of cats to experimental infection.", "abstract": "Sixty-seven specific-pathogen-free cats of various ages (newborn, 2 wk, 1 mo, 2 mo, 4 mo, and 1 yr) were inoculated ip with either the Rickard (R) or the Kawakami-Theilen (KT) strain of feline leukemia virus (FeLV). Susceptibility to FeLV was judged by induction of a) FeLV group-specific antigens (gsa) in leukocytes, b) FeLV-related disease, c) antibody to feline oncornavirus-associated cell membrane antigen (FOCMA), and d) virus-neutralizing (VN) antibody. Susceptibility to FeLV-decreased with age. Persistent viremia and FeLV-related disease developed in 100% of cats inoculated as newborns, in 85% of cats inoculated at 2 weeks to 2 months of age, and in 15% of cats inoculated at 4 months or 1 year of age. Cats susceptible to FeLV leukemogenesis became persistently FeLV gsa-positive (viremic) at 4 weeks post inoculation and thereafter and produced little or no FOCMA or VN antibody. Cats that resisted leukemogenesis by FeLV all developed persistent FOCMA and VN titers and never became FeLV gsa-positive. The disease in inoculated cats was influenced by virus strain; FeLV-R induced predominantly thymic lymphosarcoma, whereas FeLV-KT caused fatal nonregenerative anemia without concurrent neoplasia.", "journal": "Journal of the National Cancer Institute", "doi": "10.1093/jnci/57.2.365", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "183335", "author": "Cotter SM", "n_authors": 1, "title": "Feline leukemia virus induced disorders in the cat.", "abstract": null, "journal": "The Veterinary clinics of North America", "doi": "10.1016/s0091-0279(76)50055-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "60495", "author": "Sherr CJ", "n_authors": 4, "title": "Type C viruses from Kirsten sarcoma-transformed mink cells co-cultivated with primate cells and expressing p30 antigens related to feline leukemia virus.", "abstract": "Two type C viruses with new antigenic and biological properties were isolated by co-cultivating secondary cell strains established from the kidneys of a baboon (Papio papio) and a patas monkey (Erythrocebus patas) with mink cells non-productively transformed by Kirsten sarcoma virus. Both new isolates (designated PP-1R and EP-1R) contain major structural proteins (p30) that are immunologically most closely related to the p30 proteins of feline leukemia viruses. The reverse transcriptases of both viruses, although antigenically related to polymerases of murine and rat type C viruses, are distinct from those of previously described type C viral groups. Both PP-1R and EP-1R can be transmitted to canine and feline cells and to sarcoma virus-transformed, but not normal, mink cells. Both viruses contain RNA genomes partially homologous to those of endogenous mouse and rat type C viruses and the Kirsten sarcoma virus. In addition, the RNA of PP-1R contains a portion of the nucleic acid sequences found in a type C virus isolated from the baboon species P. papio. We propose that both new isolates are genetic recombinants formed between endogenous primate type C viral genomes and sequences found in Kirsten sarcoma-transformed mink cells.", "journal": "Journal of virology", "doi": "10.1128/JVI.19.2.346-358.1976", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "782787", "author": "Schultz RD", "n_authors": 3, "title": "Effect of feline panleukopenia virus infection on development of humoral and cellular immunity.", "abstract": "Cats were infected with feline panleukopenia virus (FPLV) at various ages pre- and post-parturition. All fetuses infected at 35 days of gestation from one queen and a single fetus infected at 45 days of gestation from a second queen had a significant delay in time of skin allograft rejection. Older fetuses and newborn kittens infected with FPLV did not show this delay in rejection time. Adult cats infected with FPLV demonstrated a significant decrease in lymphocyte responsiveness to two T cell mitogens, phytohemagglutinin and Concanavalin A, however there was no significant decrease in lymphocyte response to pokeweed mitogen, a T cell and B cell mitogen. Primary and secondary antibody responses to rabbit red blood cells (RRBC) were not affected by FPLV infection. The results suggest that FPLV has its primary immunosuppressive effect on T cell activity. This effect does not appear to be as severe as that observed for feline leukemia virus of kittens nor as for canine distemper virus in dogs.", "journal": "The Cornell veterinarian", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "181753", "author": "Aoki T", "n_authors": 5, "title": "Natural antibodies in sera from healthy humans to antigens on surfaces of type C RNA viruses and cells from primates.", "abstract": "Sera from healthy humans contained naturally occurring antibody against group- or subgroup-specific antigen on the envelope of the following type C viruses isolated from primates: gibbon ape leukemia virus, simian (woolly monkey) sarcoma virus, baboon endogenous type C virus, and putative human type C viruses [HL23V isolated from blood cells of a patient with acute myelogenous leukemia (HL23) and HEL-12V from human embryonic diploid cells (CIH-32)]. Two sera also reacted with C57BL/6 mouse leukemia induced by Friend virus. These results were obtained by indirect immunoelectron microscopy with various virus-producing cells and by absorption tests using as targets gibbon lymphosarcoma cells that release gibbon ape leukemia virus. In a previous report, the presence of natural antibody in sera from healthy gibbon apes was demonstrated. When the specificities of the human and gibbon natural antibodies were compared, the human natural antibody reacted with two nonproducing culture cell lines of human lymphocytic leukemia (CEM-A and MOLT) and with human embryonic diploid (CIH-1(V-) cells [which became type C virus-producing CIH-32(V+) cells after many passages], but did not react with normal gibbon spleen monolayer cells. In contrast, gibbon natural antibody showed no reaction with CEM-A, MOLT, and CIH-1(V-) cells but reacted with gibbon spleen monolayer cells. Neither human nor gibbon natural antibody that was reactive with gibbon ape leukemia virus crossreacted with feline leukemia virus and mouse wild-type AKR leukemia virus. The gibbon lymphosarcoma cells releasing gibbon ape leukemia virus were used in a screening study of sera from healthy humans. Out of 72 sera screened by indirect immunoelectron microscopy using this system, 55 were positive (76%), i.e., 26 out of 35 males (74%) and 29 out of 37 females (78%). The highest incidence of antibody production was in 1- to 10-year-olds and 31- to 40-year-olds, with the adults exhibiting higher levels. Differences in incidence of natural antibody were not found to be sex-linked. These findings suggest that type C RNA viruses related to the gibbon ape leukemia virus and simian (woolly monkey) sarcoma virus family as well as the baboon endogenous type C virus family may be widespread in humans.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.73.7.2491", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "186623", "author": "Mathes LE", "n_authors": 6, "title": "Feline oncornavirus-associated cell membrane antigen. VI. Cytotoxic antibody in cats exposed to feline leukemia virus.", "abstract": "Feline leukemia virus (FeLV)-infected specific pathogen-free (SPF) cats, normal uninfected SPF cats, and healthy cats from leukemic households were tested for antibody reactive to the feline oncornavirus-associated cell membrane antigen (FOCMA)-containing target cell line FL-74 by microcytotoxicity and indirect membrane immunofluorescence. Of the infected SPF animals, 81% showed concordant reactivity for the two tests. In contrast, only 55% of the healthy cats known to be naturally exposed to FeLV for long periods showed such concordance. FOCMA antibody could not be detected in normal SPF cats by either indirect membrane immunofluorescence or microcytotoxicity. Most cats in the FeLV-infected SPF group developed antibody detectable by both procedures by the fifth week post inoculation. Antibody detectable by membrane immunofluorescence persisted in a high percentage (75-90%) of the animals throughout the observation period of 19 weeks; after 9 weeks, fewer cats had antibody that was also detectable by microcytotoxicity.", "journal": "Journal of the National Cancer Institute", "doi": "10.1093/jnci/56.6.1197", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "178890", "author": "Frankel AE", "n_authors": 3, "title": "Fractionation of DNA nucleotide transcripts from Moloney sarcoma virus and isolation of sarcoma virus-specific complementary DNA.", "abstract": "Radioactive DNA complementary to nucleotide sequences in Moloney murine sarcoma virus (MSV) and Moloney leukemia virus (M-MuLV) complex was made by the endogenous reverse transcriptase reaction. These virus stocks contained a threefold excess of MSV over M-MuLV as measured by biological assay. The complementary DNA was an accurate copy of the viral RNA in that 86% of 35S viral RNA hybridized with complementary (cDNA) DNA at a 1.5 to 1 cDNA-RNA molar ratio. The complementary DNA, of a 4-6S size, was fractionated by sequential absorptions with MulV and the feline leukemia virus pseudotype of MSV, [MSV(FeLV)] RNA. In this manner three sets of nucleotide sequences whichrepresent different portions of the MSV viral complex were obtained: a sarcoma virus-specific fraction (cDNAsarc) with sequences that had no homology to M-MuLV RNA but which hybridized to MSV (FeLV) RNA, a sarcoma-leukemia fraction (cDNA common) with sequences common to MSV as well as M-MuLV viral RNA, and a cDNAleuk representing those nucleotide sequences found only in M-MuLV. Hybridization of MSV-MuLV viral 35S RNA with a threefold molar excess of cDNA's revealed that approximately 20% was hybridized with cDNAsarc, whereas approximately 75% was hybridized with cDNAcommon. M-MuLV 35S RNA alone did not hybridize with cDNAsarc but did hybridize 40 and 50% with cDNAleuk and cDNAcommon, respectively. The cDNAsarc represents about 25% of the total MSV sequences, whereas the cDNAcommon represents the remainder of the MSV virus genome. Some cDNAcommon sequences were shared by two other sarcoma viruses and several distinctly different isolates of MulV. In contrast, the MSV \"sarc\" sequences had little or no homology with two other murine sarcoma virus isolates.", "journal": "Journal of virology", "doi": "10.1128/JVI.18.2.481-490.1976", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "178427", "author": "Heding LD", "n_authors": 4, "title": "Inactivation of tumor cell-associated feline oncornavirus for preparation of an infectious virus-free tumor cell immunogen.", "abstract": "Ultraviolet (UV) and thermal methods of inactivating the oncogenic potential of C-type particle-producing feline oncornavirus-induced tumor cells were developed. The techniques were evaluated by several parameters for their use in preparation of cellular immunogens. The UV inactivation dose required to reduce the number of focus-forming units per ml by 1 log10 for FL-74 lymphoblastoid cell-associated feline leukemia virus was 44,000 ergs/sq mm, and the thermal inactivation dose required to reduce the number of focus-forming units per ml by 1 log10 at 45 degrees was 16 min. Inactivation of greater than 6 log10 of virus per ml associated with 4 x 10(8) cells required a UV dose of 270,000 ergs/sq mm, 100 min at 45 degrees or 3 min at 56 degrees. All three treatments concomitantly destroyed the replicating potential of FL-74 cells as shown by their inability to propagate under normal growth conditions and to incorporate [3H]thymidine into nuclear DNA. UV inactivation and thermal inactivation at 45 degrees allowed the best retention of feline oncornavirus-associated cell membrane antigen. A 50% loss in antigenic activity was observed as a result of 56 degrees treatment, but this method was the only one that did not destroy the surface structural integrity of FL-74 cells.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "59993", "author": "Seal E Jr", "n_authors": 3, "title": "Oncornavirus-like protein expression in human prostatic tissue.", "abstract": "A sensitive competition radioimmunoassay using 125 I-labelled p 30 interspecies antigen, antiserum specific to the interspecies antigen of the feline leukaemia virus, and aqueous tissue extracts from prostate was used to examine benign hyperplastic prostates for the presence of protein components able to complete with the interspecies viral antigens. Six of 20 prostatic nodular hyperplastic tissues were competitive in radioimmunoassay with the 125 I-labelled viral antigen for binding sites on the antiviral antibodies. These findings suggest the presence of oncornavirus-like proteins in prostatic nodular hyperplasia. No correlation could be made between the presence of competing protein and histological features of acute or chronic prostatitis and squamous metaplasia.", "journal": "Urological research", "doi": "10.1007/BF00256132", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "177726", "author": "Russell PH", "n_authors": 2, "title": "An improved assay for feline leukaemia virus pseudotypes of murine sarcoma virus.", "abstract": "An assay is described for feline leukaemia virus pseudotypes of murine sarcoma virus which increased the virus titre by about 100-fold over conventional assays. The titre is independent of dilution and no secondary focus formation occurs. The assay may be used to study virus neutralization and to detect and type feline leukaemia virus in feline embryo cells by interference.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-31-1-139", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "176414", "author": "Charman HP", "n_authors": 5, "title": "Humoral immune responses of cats to feline leukemia virus: comparison of responses to the major structural protein p30 and to a virus-specific cell membrane antigen (FOCMA).", "abstract": "Radioimmunoprecipitation was used to test cat sera for ability to bind to the purified major internal protein p30 of feline leukemia viurs (FeLV), to the endogenous cat virus (RD-114), and to murine leukemia virus (MuLV). The data were compared with results of tests for antibody to the feline oncornavirus-associated cell membrane antigen FOCMA and for the presence of viremia. In contrast to the general lack of free antibody to FeLV p30 in a random sample of healthy cats, high levels of antibody to FeLV p30 and FOCMA were found in normal animals from high-leukemia-cluster households. Titers of greater than or equal to 200 for p30 and greater than or equal to 32 for FOCMA were found in nonviremic animals; a percentage of animals with high FOCMA titers and lower or no p30 binding activity were viremic. Animals with neoplasms were low or negative for FOCMA antibody and did not have high titers of free p30 antibody. The p30 binding activity could be divided into three main categories: high binding with FeLV p30 and much lower activity with RD-114 and MuLV p30's, as seen with hyperimmune sera; high binding with FeLV and RD-114 p30's and low activity with MuLV p30, possibly indicative of specific antibody to both of the aforementioned proteins; and low level binding to all three p30's.", "journal": "Journal of the National Cancer Institute", "doi": "10.1093/jnci/56.4.859", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "57616", "author": "Kettmann R", "n_authors": 9, "title": "Bovine leukemia virus: an exogenous RNA oncogenic virus.", "abstract": "Short-term cultures of bovine leukemic lymphocytes release virus particles with biochemical properties of RNA oncogenic viruses. These particles, tentatively called bovine leukemia virus (BLV), have a high molecular weight RNA-reverse transcriptase complex and a density of 1.155 g/ml in sucrose solutions. Molecular hybridizations between BLV/[3H]cDNA and several viral RNAs show that BLV is not related to Mason-Pfizer monkey virus, simian sarcoma associated virus, feline leukemia virus, or avian myeloblastosis virus. These results were confirmed by hybridization between BLV 70S RNA and [3H]cDNA synthesized in the various viruses tested. The high preference of BLV reverse transciptase for Mg++ as the divalent cation suggests that BLV might be an atypical mammalian leukemogenic \"type C\" virus. DNA-DNA hybridization studies using BLV [3H]cDNA as a probe strongly suggest that the DNA of bovine leukemic cells contains viral sequences that cannot be detected in normal bovine DNA.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.73.4.1014", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "56459", "author": "Ihle JN", "n_authors": 3, "title": "Purification and serological characterization of the major envelope glycoprotein from AKR murine leukemia virus and its reactivity with autogenous immune sera from mice.", "abstract": "The major envelope glycoprotein (gp71) from AKR murine leukemia virus (MuLV) was purified and its serological reactivity with heterologous and autogenous immune mouse sera was examined. Homologous and interspecies competition radioimmunoassays using antisera to Rauscher-MulV gp69/71 or Friend-MuLV gp71 or antisera to feline leukemia virus to precipitate 125I-labeled gp71 from various MuLV showed that distinct differences exist between Rauscher- or Friend-MuLV and AKR-MuLV glycoproteins. Characteristically the AKR-MuLV gp71, in contrast to FLV or RLV gp71, does not compete fully in homologous or interspecies radioimmunoassays with iodinated Friend of Rauscher glycoproteins. Purified 125I-labeled AKR-MuLV gp71, in contrast to the Rauscher- or Friend-MuLV glycoproteins, reacts with normal (autogenous immune) mouse sera in direct radioimmune precipitation assays. Competition experiments further demonstrate that this is a predominant immunological reactivity of normal mouse sera which had previously been detected by radioimmune precipitation assay against intact virions.", "journal": "Journal of virology", "doi": "10.1128/JVI.17.3.727-736.1976", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "943234", "author": "Yohn DS", "n_authors": 7, "title": "Experimental oncornavirus vaccines in the cat.", "abstract": "An experimental approach to the immunoprophylatic control of feline oncornavirus-mediated diseases has included induction of antivirus immunity and antibodies to the feline oncornavirus-associated membrane (tumor) antigens. A suitable model for exploring the effectiveness of killed oncornavirus vaccines in the cat has been provided by the use of feline sarcoma virus. Immunization of seven pregnant queens over a 6-week period with ultraviolet light-inactivated Gardner-Arnstein feline sarcoma virus resulted in significant protection among 12 kittens challenged with a tumor-forming Dose 90 at 7 days of age. This immunity was not present in kittens challenged at 35 days of age. Among 12 kittens born of queens immunized during pregnancy with ultraviolet light-inactivated Kawakami-Theilen feline leukemia virus and challenged with the same live virus at 4 days of age, significant protection was noted, ranging from prolongation of survival time to complete protection in 3 kittens. In general, the higher the antibody titer in the mother, the more effective the protection afforded the kittens. Immunization of 43 kittens during their first 5 weeks of life with the same vaccines used in adult cats did not immunize sufficiently to protect against feline sarcoma virus challenge at 5 weeks of age. Neutralizing antibody responses in these kittens were significantly lower than in pregnant queens. That kittens of this age are immunologically responsive was established, since complete protection of 9 kittens to feline sarcoma virus was obtained by immunization with a crude tumor extract inactivated with 5 to 7 megarads of gamma-irradiation. All these kittens developed feline oncornavirus-associated membrane antibodies while 3 developed demonstrable levels of virus-neutralizing antibodies. The results of these studies are believed indicative that killed virus vaccines and tumor vaccines can be effective immunoprophylatic measures in the control of RNA tumor virus oncogenesis in the cat. Developments in this model system should be relevant to any consideration given similar vaccines in humans.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "176431", "author": "Salmeen I", "n_authors": 7, "title": "Hydrodynamic diameters of murine mammary, Rous sarcoma, and feline leukemia RNA tumor viruses: studies by laser beat frequency light-scattering spectroscopy and electron microscopy.", "abstract": "We have studied purified preparations of murine mammary tumor virus (MuMTV), Rous sarcoma virus (RSV; Prague strain), and feline leukemia virus (FeLV) by laser beat frequency light-scattering spectroscopy, ultra-centrifugation, and electron microscopy. The laser beat frequency light-scattering spectroscopy measurements yield the light-scattering intensity, weighted diffusion coefficients. The corresponding average hydrodynamic diameters, as calculated from the diffusion coefficients by the Stokes-Einstein equation for MuMTV, RSV, and FeLV, respectively, are: 144 +/- 6 nm, 147 +/- 7 nm, and 168 +/- 6 nm. Portions of the purified RSV and MuMTV preparations, from which light-scattering samples were obtained, and portions of the actual FeLV light-scattering samples were examined by negatively stained, catalase crystal-calibrated electron microscopy. The light-scattering intensity weighted averages of the electron micrograph size distributions were calculated by weighing each size by its theoretical relative scattering intensity, as obtained from published tables computed according to the Mie scattering theory. These averages and the experimentally observed hydrodynamic diameters agreed to within +/- 5%, which is the combined experimental error in the electron microscopic and light-scattering techniques. We conclude that the size distributions of singlet particles observed in the electron micrographs are statistically true representations of the sedimentation-purified solution size distributions. The sedimentation coefficients (S20, w) for MuMTV, RSV, and FeLV, respectively, are: 595 +/- 29S, 689 +/- 35S, and 880 +/- 44S. Virus partial specific volumes were taken as the reciprocals of the buoyant densities, determined in sucrose density gradients. The Svedberg equation was used to calculate particle weights from the measured diffusion and sedimentation coefficients. The particle weights for MuMTV, RSV, and FeLV, respectively, are: (3.17 +/- 0.32) x 10(8), (4.17 +/- 0.42) x 10(8), and (5.50 +/- 0.55) x 10(8) daltons.", "journal": "Journal of virology", "doi": "10.1128/JVI.17.2.584-596.1976", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "175919", "author": "Hardy WD Jr", "n_authors": 8, "title": "Biology of feline leukemia virus in the natural environment.", "abstract": "The feline leukemia virus (FeLV) was discovered in 1964 in a cluster of cats with lymphosarcoma. The observed clustering of cases of feline lymphosarcoma suggested that FeLV was an infectious agent for cats. The development of a simple immunofluorescent test for FeLV permitted a seroepidemiological study to be undertaken on the distribution of the virus in cats living in their natural environment. Over 2000 cats were tested, and the results showed conclusively that FeLV is an infectious agent for cats. This finding has now been independently confirmed using three different test procedures. After the infectious nature of FeLV was discovered, a simple FeLV test and removal program was devised to control the spread of the virus in the natural environment. The spread of FeLV was controlled in 45 households by removing the FeLV-infected cats, while in 25 households, where the infected cats were left in contact with the uninfected cats, 12% of the uninfected cats became infected. The ultimate control of FeLV awaits the development of an effective FeLV vaccine, which now seems feasible since we have already experimentally immunized some cats with attenuated FeLV. Although FeLV is infectious for cats there is no evidence that FeLV can infect humans.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "56809", "author": "Okabe H", "n_authors": 6, "title": "FeLV-related sequences in DNA from a FeLV-free cat colony.", "abstract": null, "journal": "Virology", "doi": "10.1016/0042-6822(76)90510-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "56224", "author": "Essex M", "n_authors": 4, "title": "Immune response to leukemia virus and tumor-associated antigens in cats.", "abstract": "Cats represent an unusually valuable model for studying the role of the immune response to leukemia, lymphoma, and other mesodermal neoplasms. The agents that cause spontaneous feline leukemias, lymphomas, and fibrosarcomas, the feline leukemia and sarcoma viruses, are well characterized. A specific tumor cell membrane antigen, designated the feline oncornavirus-associated cell membrane antigen (FOCMA) has also been described. Feline leukemia and feline sarcoma viruses are antigenically indistinguishable, and FOCMA is common for both. Both laboratory-induced and spontaneous feline leukemias, lymphomas, and fibrosarcomas are available for study. A clear correlation has been shown between the resistance of cats to development of lethal tumors following inoculation of feline sarcoma virus and the presence of high humoral antibody titers to FOCMA. The geometric mean antibody titer to FOCMA for cats that resisted growth of fibrosarcomas was more than 20-fold higher than the mean for cats that succumbed to lethally progressing tumors. Cats with induced or spontaneous leukemia or lymphoma also have either no detectable FOCMA antibody or very low levels. Conversely, some cats resist development of leukemia or lymphoma following natural exposure to feline leukemia virus in leukemia cluster households, and these cats have high FOCMA antibody titers. These results support the concept of a natural immunosurveillance mechanism against leukemia or lymphoma development in an outbred mammalian species.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "175024", "author": "Charman HP", "n_authors": 5, "title": "Humoral immune responses of cats to mammalian type-C virus p30s.", "abstract": "Natural and experimental cat sera were tested in radioimmune precipitation assays vs purified p30s from FeLV, RD114 and MuLV. Antibodies with specificity for FeLV p30 comparable to hyperimmune sera from heterologous species but of low titer were found in a high percentage of normal cats from households with a high incidence of FeLV and neoplasia. Sera from cats with neoplasms were generally negative. Cats immunized with FeLV gave low-level immune response, also of the same general specificity as heterologous hyperimmune sera. Cat sera do not normally show antibody to RD114 p30 although two immunized weanling cats produced low titered but highly specific p30 antibody. Thus, for both classes of feline type-C virus p30s, there is an evident capability of the cat to mount an immune response to natural or experimental exposure to the respective proteins. The magnitude of the response is between 100 and 1,000 fold below that seen in heterologous species. In contrast, cats immunized with MuLV p30 gave immune responses comparable to those seen in guinea-pigs, rabbits and goats. Several very old cats with carcinoma had antibody which preferentially precipitated MuVL p30. A competition assay using one such serum and labelled MuVL p30 was inhibited by FeVL, RD114, and MuLV p30s. This indicates that the assay is \"interspecies\" in nature. Among the possible explanations of this reaction category is that it represents antibody to the p30 of an as yet undefined class of feline type-C virus.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910170114", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "172437", "author": "Olsen RG", "n_authors": 6, "title": "Influence of culture conditions of growth of FL-74 cells and feline oncornavirus cell membrane associated antigen production.", "abstract": "The FL-74 cell, a feline lymphoblastoid cell line derived from a tumor induced by leukemia virus, grows equally well in static suspension culture (plastic T-flask or silicone treated glass bottles) or in spinner culture. No growth was observed in unsiliconized glass bottles. Although feline leukemia virus production was nearly the same in FL-74 grown in each of the above types of vessel, the expression of the feline oncornavirus membrane associated antigen (FOCMA), as determined by membrane immunofluorescence, was more intense and more complete on cells grown in static suspension. Moreover, higher fluorescent antibody titer endpoints were observed with cells from static suspension cultures than with cells from spinner cultures, FL-74 cells grown in spinner culture, when subjected to partial synchrony by cold block or by deprivation of essential amino acids (arginine and/or isoleucine) for 12 hr, achieved a membrane fluorescent pattern for FOCMA similar to cells grown in static suspension. It is proposed that the expression of FOCMA on the cell membrane surface is cell-cycle dependent, and that the rate at which a cell passes through the cell cycle determines the pattern and intensity of the fluorescence of the cell membrane.", "journal": "In vitro", "doi": "10.1007/BF02832791", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "64382", "author": "Kettmann R", "n_authors": 9, "title": "Bovine leukemia virus: an exogenous RNA oncogenic virus?", "abstract": "Short term cultures of bovine leukemic lymphocytes release virus particles with biochemical properties of RNA oncogenic viruses. These particles, tentatively called Bovine Leukemia Virus (BLV) have a high molecular weight-reverse transcriptase complex and a density averaging 1.155 g/ml in sucrose solutions. Molecular hybridizations between BLV-3H cDNA and several viral RNAs show that BLV is not related to Mason-Pfizer Monkey Virus (MPMV) Simian Sarcoma Associated Virus (SSV-1) Feline Leukemia Virus (FeLV) or Avian Myeloblastosis Virus (AMV). Rauscher Leukemia Virus (RLV) exhibits a slight but reproducible relatednesse to BLV. The high preference of BLV reverse transcriptase for Mg++ as the divalent cation suggests that BLV might be an atypical mammalian leukemogenic type C virus. Hybridization studies using BLV 3H cDNA as a probe suggest that the DNA of bovine leukemic cells contains viral sequences that cannot be detected in normal bovine DNA.", "journal": "Hamatologie und Bluttransfusion", "doi": "10.1007/978-3-642-87524-3_37", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "202959", "author": "Stephenson JR", "n_authors": 4, "title": "Feline oncornavirus-associated cell membrane antigen: evidence for an immunologically crossreactive feline sarcoma virus-coded protein.", "abstract": "The feline oncornavirus-associated cell membrane antigen (FOCMA) acts as a target for natural immuno-surveillance against tumor development in the cat. In the present study, mink and rat cells nonproductively transformed by feline sarcoma virus (FeSV) were shown to express FOCMA as well as 5'-terminal feline leukemia virus (FeLV) gag gene proteins, p15 and p12. In contrast, such cells lack detectable levels of other FeLV gag gene-coded proteins or the env gene product, gp70. FOCMA, p15, and p12 antigen expression is initially in the form of an 80,000-100,000 molecular weight precursor which, upon post-translational cleavage, gives rise to a 65,000 molecular weight component that contains FOCMA and a 25,000 molecular weight component containing p15 and p12. Feline lymphoma cells, including those from several tumors that lacked detectable levels of FeLV structural protein expression, were shown to be FOCMA-positive. These findings strongly suggest that FOCMA represents an FeSV-coded transformation specific protein and provide preliminary information regarding the position within the FeSV genome coding for its synthesis.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.74.12.5608", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "200353", "author": "Hebebrand LC", "n_authors": 3, "title": "Inhibition of concanavalin A stimulation of feline lymphocytes by inactivated feline leukemia virus.", "abstract": "In a lymphocyte blast transformation assay, the response of feline lymphocytes to concanavalin A was suppressed 20 to 65 percent in the presence of inactivated feline leukemia virus. The decrease was not due to viral cytotoxicity, as determined by trypan blue viability counts, nor was the virus binding the concanavalin A and interfering with its mitogenic stimulation. The virus may be biochemically repressive in itself, interfering with cell-mediated immunity within the feline system.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "201856", "author": "Hardy WD Jr", "n_authors": 5, "title": "A feline leukaemia virus- and sarcoma virus-induced tumour-specific antigen.", "abstract": null, "journal": "Nature", "doi": "10.1038/270249a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "72739", "author": "Calafat J", "n_authors": 3, "title": "Feline malignant mammary tumors. III. Presence of C-particles and intracisternal A-particles and their relationship with feline leukemia virus antigens and RD-114 virus antigens.", "abstract": "Thirty-six feline mammary tumors were examined by the electron microscope, and by the indirect immunofluorescence (IFA) test with anti-FeLV and anti-RD-114 serum. In 11 (30.6%) tumors intracisternal A-particles (IAP) were found. One of these tumors contained a few particles with an electron-dense nucleoid in the cisternae of the endoplasmic reticulum. In 7 (19.4%) other tumors C-particles were found and in the remaining 18 (50.0%) no particles at all could be detected. In 11 (30.6%) tumors FeLV antigens and in 20 (55.5%) tumors RD-114 virus antigens were present. In 9 (25%) tumors we found a high (greater than 1/64) and in 11 (30.6%) tumors a low (greater than 1/16 less than or equal to 1/64) titer. There was a good correlation between the presence of C-particles and the demonstration of FeLV-antigen but none between IAP and FeLV antigens. No correlation was found between RD-114 virus antigens and any type of particle. Morphologically, the IAP found in feline mammary tumors were indistinguishable from the IAP present in mammary tumors of some inbred mice strains. The IAP in feline mammary tumors possibly represent an endogenous virus, different from RD-114 virus. The role of these viruses in the etiology of feline mammary tumors is discussed.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910200516", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "18625484", "author": "Charman HP", "n_authors": 4, "title": "Immunologic characterization of gp70 and gp45 from Rauscher murine leukemia virus.", "abstract": "The envelope glycoproteins gp70 and gp45 were purified from Rauscher leukemia virus and compared in radioimmunoassay and gel diffusion using antibody to the purified proteins and a cross-reactive antibody prepared against feline leukemia virus. Previous studies indicated that gp70 and gp45 had very similar polypeptide components and differed mainly in carbohydrate content. The current studies indicate that gp70 contains the major antigenic determinants of gp45, and, in addition, determinants unique to gp70. We presume that these differences involve the carbohydrate components, either directly or indirectly by influence on conformation. The major antigenic deficiencies in gp45, relative to gp70, appeared to be in interspecies reactivity.", "journal": "Virology", "doi": "10.1016/0042-6822(77)90219-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "198129", "author": "Wolff LH", "n_authors": 5, "title": "Detection and evaluation of feline oncornavirus-induced cell surface antigen(s) shed from cells in vitro.", "abstract": "A method for preparation of soluble feline oncornavirus-induced cell surface antigens was described. This technique relied upon the natural release of antigen(s) from FL-74 feline lymphoblastoid cells during their maintenance at 37 degrees in serum-deficient medium. When concentrated and clarified spent medium from 4-day cultures was tested for its antigen content by inhibition of humoral cytotoxicity, it was found that this natural production of soluble antigen provided more feline oncornavirus-associated cell membrane antigen per cell than did a solubilization procedure in which papain was used. The shed antigen preparation was immunogenic in cats, eliciting humoral antibody that was reactive with the surface of FL-74 Cells and feline sarcoma virus-transformed nonproducer mink cells but was not reactive with feline leukemia virus in a virus neutralization assay.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "198125", "author": "Cockerell GL", "n_authors": 2, "title": "Inhibition of normal lymphocyte mitogenic reactivity by serum from feline leukemia virus-infected cats.", "abstract": "The effect of serum from 12 cats with lymphosarcoma induced by feline leukemia virus (FeLV) on the response of normal cat peripheral blood lymphocytes to phytomitogen-induced blastogenesis was studied. The majority of FeLV sera, when tested at a concentration of 20% of the incubation medium, caused a 40 to 70% reduction in the mean blastogenic response to concanavalin A compared to the response obtained with a similar concentration of normal feline serum. Results with pokeweed mitogen were similar, but the depression in blastogenesis was less than with concanavalin A. Further studies showed that the blastogenic inhibitory activity of FeLV serum (a) was heat labile at 56 degrees for 30 min, (b) could not be overcome by greater concentrations of mitogens, (c) was proportional to the concentration of FeLV serum in the incubation medium, and (d) could not be demonstrated when lymphocytes were preincubated in FeLV serum followed by washing and reincubating in normal feline serum. The results suggested that a substance present in the serum of FeLV-infected cats contributes to altered immunological reactivity during leukemogenesis in the cat.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "199981", "author": "Jarrett O", "n_authors": 3, "title": "Protection of kittens from feline leukaemia virus infection by maternally-derived antibody.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.101.15.304", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "201187", "author": "Pedersen NC", "n_authors": 8, "title": "Studies of naturally transmitted feline leukemia virus infection.", "abstract": null, "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "198120", "author": "Hoover EA", "n_authors": 4, "title": "Relationship between feline leukemia virus antigen expression and viral infectivity in blood, bone marrow, and saliva of cats.", "abstract": "Correlation was greater than 90% between feline leukemia virus (FeLV), group-specific antigen (GSA) in leukocytes, and viral infectivity (VI) in serum or plasma from 132 cats infected with either the Rickard strain of FeLV, the Snyder-Theilen strain of feline sarcoma virus, or field strains of FeLV. Detection of GSA in blood cells was at least as sensitive as detection of VI in serum. In 45% of FeLV GSA-positive cats inoculated with FeLV-Rickard strain, VI was detected in saliva. No saliva samples from GSA-negative cats had VI. Sequential bone marrow biopsies from 34 cats inoculated with Snyder-Theilen feline sarcoma virus indicated that the correlation between FeLV GSA in bone marrow cells and blood cells was virtually 100%. FeLV GSA appeared in bone marrow leukocyte precursors 1 week before its appearance in peripheral blood leukocytes in 50% of the cats. The FeLV GSA-positive state was transient (3 to 6 weeks) in 34% of the Snyder-Theilen feline sarcoma virus-inoculated cats.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "201852", "author": "Francis DP", "n_authors": 3, "title": "Excretion of feline leukaemia virus by naturally infected pet cats.", "abstract": null, "journal": "Nature", "doi": "10.1038/269252a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "198602", "author": "Schäfer W", "n_authors": 1, "title": "[Model studies on virus-induced tumors and their immunological treatment (author's transl)].", "abstract": "After a review of the general biological properties of C-type oncorna viruses, results are presented on the structure of an exogenous murine leukemia virus (FLV) and on the serobiological properties of its structural proteins. Our findings suggested a major role of the viral surface glycoprotein gp71 in immunological defense mechanisms. This was confirmed by vaccination experiments with isolated gp71 in mice. The induced immunity was highly specific and not operative against endogenous murine C-viruses belonging to other serotypes. Surprisingly the latter were found to be activated by the vaccination with gp71 of FLV. In heterologous animal species isolated FLV-gp71 induced the formation of broadly reacting antibodies. They were found to be effective in the therapy of infections with FLV in mice as well as with feline leukaemia virus in cats. Most impressive results were obtained with an antiserum prepared against feline leukaemia virus in a goat. This serum completely suppressed sarcomas induced by infection with feline sarcoma virus.", "journal": "Klinische Wochenschrift", "doi": "10.1007/BF01491299", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "197262", "author": "Khan AS", "n_authors": 2, "title": "Feline leukemia virus: biochemical and immunological characterization of gag gene-coded structural proteins.", "abstract": "The major non-glycosylated structural proteins of feline leukemia virus have been isolated, and competition immunoassays have been developed for each. These proteins include the 27,000- to 30,000-molecular-weight major internal antigen designated p30, a 15,000-molecular-weight protein (p15), an acidic protein of 12,000 molecular weight (p12), and a highly basic 10,000-molecular-weight protein (p10). Immunologically and biochemically corresponding proteins of feline and murine leukemia viruses have been identified. and, on the basis of analogy to the known sequence of a prototype type C virus of mouse origin, the map order of the gag region of the feline type C viral genome has been tentatively deduced as NH2-p15-p12-p10-COOH. The demonstration of two feline leukemia virus gag gene-coded proteins, p15 and p12, expressed in the form of an uncleaved precursor in a mink cell line nonproductively transformed by feline sarcoma virus provides indirect support for the proposed sequence.", "journal": "Journal of virology", "doi": "10.1128/JVI.23.3.599-607.1977", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "197261", "author": "Niman HL", "n_authors": 4, "title": "Endogenous RD-114 virus genome expression in malignant tissues of domestic cats.", "abstract": "Endogenous xenotropic cat type C virus (RD-114)- and infectious feline leukemia virus (FeLV)-specific gene expressions were measured in spontaneous sarcomas carcinomas, and nonmalignant cat tissues by molecular hybridization for virus-specific RNA and competition radio-immunoassays for the major internal protein (p30) of these two viruses. The results indicate that RD-114 gene expression in sarcomas and carcinomas at both RNA and p30 levels is significantly higher than histologically normal tissues from cats free of cancer. In contrast, the levels of FeLV viral RNA and p30 are fount to be low or undetectable in the majority of these tumored and normal tissues examined. Whereas variability in the amounts of RD-114 OR FeLV RNA and p30 expressed is found in tissues from different cats, their expression is fairly uniform in multiple malignant tissues of the same cat. The finding of widespread occurrence of elevated RD-114 gene expression in sarcomas and carcinomas is consistent with our similar observation with natural lymphomas of domestic cats and suggests that expression of certain functions of this endogenous virus may be etiologically involved in the development of many different spontaneous neoplasms of cats.", "journal": "Journal of virology", "doi": "10.1128/JVI.23.3.578-586.1977", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "196021", "author": "Grant CK", "n_authors": 5, "title": "Antibodies from healthy cats exposed to feline leukemia virus lyse feline lymphoma cells slowly with cat complement.", "abstract": null, "journal": "Journal of immunology (Baltimore, Md. : 1950)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "69721", "author": "Oskarsson MK", "n_authors": 5, "title": "Phosphorylation and nucleic acid binding properties of m1 Moloney murine sarcoma virus-specific pP60gag.", "abstract": "The pP60gag polyprotein of the feline leukemia virus pseudotype of m1 Moloney murine sarcoma virus [m1MSV(FeLV)] was previously shown to be MSV specific and to contain murine p30 and smaller structural polypeptides. This protein was detected in m1MSV-transformed cells, and in pulse-chase studies it was found to be stable. In this study virion P60 was shown to contain murine pp12, to be phosphorylated, and to bind to nucleic acids. 32P-labeled m1MSV[FeLV) was fractionated by guanidine agarose chromatography and analyzed by gel electrophoresis. Both P60 and pp12 were found to be the major phosphoproteins, phosphorylated in both serine and threonine residues. Virion P60 bound preferentially to single-stranded DNA and RNA in a competition filter binding assay, using 125I-labeled single-stranded calf thymus DNA and various unlabeled nucleic acids. Similar phosphorylation and DNA binding properties were demonstrated for cellular P60. Thus, immunoprecipitation of cellular extracts showed that P60 was phosphorylated in both producer and nonproducer transformed cells, indicating that phosphorylation occurs independently of virus assembly. Moreover, P60 from cytoplasmic extracts was retained on single-stranded DNA-Sepharose columns, demonstrating that cellular P60 binds to DNA.", "journal": "Journal of virology", "doi": "10.1128/JVI.23.1.196-204.1977", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "67886", "author": "Olsen RG", "n_authors": 5, "title": "Abrogation of resistance to feline oncornavirus disease by immunization with killed feline leukemia virus.", "abstract": "Four-week-old specific-pathogen-free cats were immunized with a combined vaccine composed of killed feline leukemia virus and killed feline oncornavirus-associated cell membrane antigen-containing tumor cells. Immunization induced feline oncornavirus-associated cell membrane antigen antibody titers ranging from 1:32 to 1:256 but did not elicit detectable virus-neutralizing antibody titers. Kittens immunized with tumor cells alone developed higher feline oncornavirus-associated cell membrane antigen antibody titers (ranging from 1:512 to 1:2048) than those given the combined vaccine. All kittens were challenged with virulent Dynder-Theilen feline sarcoma virus at 12 weeks of age. Seventy-five % of the kittens vaccinated with combined vaccine and 67% of unvaccinated control kittens developed progressive fibrosarcomas after challenge. By contrast, none of the kittens vaccinated with killed tumor cells alone developed progressive fibrosarcomas after challenge. The combined vaccine did not, however, inhibit the induction of feline leukemia virus viremia.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "194310", "author": "Sliski AH", "n_authors": 4, "title": "Feline oncornavirus-associated cell membrane antigen: expression in transformed nonproducer mink cells.", "abstract": "The feline oncornavirus-associated cell membrane antigen (FOCMA) is a target for naturally occurring immunity that protects the cat against development of fibrosarcoma and leukemia. Feline sarcoma virus-transformed \"nonproducer\" mink cells express high levels of FOCMA, but not the major viral structural proteins. Transformation of the same cells by murine sarcoma virus, or infection with feline leukemia virus, which is nontransforming for epithelial or fibroblastic cells, did not induce FOCMA. Thus, FOCMA expression in mind lung cells is specifically associated with transformation by feline sarcoma virus.", "journal": "Science (New York, N.Y.)", "doi": "10.1126/science.194310", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "69678", "author": "O'Brien SJ", "n_authors": 2, "title": "Expression of feline leukaemia virus antigens on cat lymphoma cells: kinetics of biosynthesis.", "abstract": null, "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-35-3-511", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "191415", "author": "Gardner MB", "n_authors": 11, "title": "FeLV epidemiology in Los Angeles cats: Appraisal of detection methods.", "abstract": "We investigated the reliability of the fixed cell indirect fluorescent antibody (IFA) peripheral blood smear test as an index of systemic infection with FeLV. Positive results with this test were found to correlate well with detectable FeLV p30 antigen in bone-marrow smears by IFA, in serum and tissue by competition immunoassays, and with type-C particles in bone marrow or spleen by electron microscopy. Most cats with lymphoma, anemia or infectious peritonitis were positive for FeLV and showed a poor or absent antibody response to FeLV p30, gp70, and FOCMA antigens. Most older cats with lymphoma, carcinoma, or sarcoma were negative for FeLV expression and also lacked these FeLV-related antibodies. Detectable immunologic response to FeLV p30 and gp70 proteins and a high-titered FOCMA antibody response were generally restricted to certain healthy cats exposed to FeLV. Antibody to endogenous RD-114 viral p30 and gp70 was not detected in any of a large number of feline sera tested. The prevalence of FeLV-related diseases and immunologic responses to FeLV in healthy cats was directly correlated with the degree of FeLV exposure. By using the IFA blood smear and FOCMA antibody tests one can monitor the horizontal spread of FeLV in multi-cat household and accurately predict the FeLV disease susceptibilty or resistance of individual cats in each environments.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910190420", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "194840", "author": "Hoover EA", "n_authors": 4, "title": "Passive immunity to feline leukemia: evaluation of immunity from dams naturally infected and experimentally vaccinated.", "abstract": "Antibodies against feline leukemia virus (FeLV) and the feline oncornavirus-associated cell membrane antigen (FOCMA) were transferred from pregnant cats to their suckling kittens. All of these kittens were protected against infection and oncogenesis by virulent FeLV when challenged at 2 weeks of age. Suckling kittens acquired 25 to 100% of maternal virus-neutralizing and FOCMA titers by 3 days of age, and titers underwent linear decay to undetectable levels by 2 to 3 months of age. FOCMA antibody in dams and kittens was identified as immunoglobulin G (IgG) by use of goat anti-human IgG serum, which cross-reacts with feline IgG in the indirect membrane immunofluorescence test for FOCMA antibody. In an attempt to induce protective maternal antibody by vaccination, 10 pregnant cats were immunized by three to five weekly intramuscular injections with purified FeLV inactivated by ultraviolet irradiation. After the course of immunization, neither virus-neutralizing nor FOCMA antibody was detectable in the dams or in 19 kittens born to these cats. When these kittens were challenged with FeLV at 2 weeks of age, 18 of 19 developed persistent viremia and FeLV-related disease.", "journal": "Infection and immunity", "doi": "10.1128/iai.16.1.54-59.1977", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "192917", "author": "Okasinski GF", "n_authors": 2, "title": "Analysis of intracellular feline leukemia virus proteins II. Generation of feline leukemia virus structural proteins from precursor polypeptides.", "abstract": "The synthesis and processing of feline leukemia virus (FeLV) polypeptides were studied in a chronically infected feline thymus tumor cell line, F-422, which produces the Rickard strain of FeLV. Immune precipitation with antiserum to FeLV p30 and subsequent sodium dodecyl sulfate-polyacrylamide gel electrophoresis (SDS-PAGE) were used to isolate intracellular FeLV p30 and possible precursor polypeptides. SDS-PAGE of immune precipitates from cells pulse-labeled for 2.5 min with [35S]methionin revealed the presence of a 60,000-dalton precursor polypeptide (Pp60) as well as a 30,000-dalton polypeptide. When cells were grown in the presence of the proline analogue L-azetidine-2-carboxylic acid, a 70,000-dalton precursor polypeptide (Pp70) was found in addition to Pp60 after a 2.5-min pulse. The cleavage of Pp60 could be partially inhibited by the general protease inhibitor phenyl methyl sulfonyl fluoride (PMSF). This partial inhibition was found to occur only if PMSF was present during pulse-labeling. Intracellular Pp70 and Pp60 and FeLV virion p70, p30, p15, p11, and p10 were subjected to tryptic peptide analysis. The results of this tryptic peptide analysis demonstrated that intracellular Pp70 and virion p70 were identical and that both contained the tryptic peptides of FeLV p30, p15, p11, and p10. Pp60 contained the tryptic peptides of FeLV P30, P15, and P10, but lacked the tryptic peptides of P11. The results of pactamycin gene ordering experiments indicated that the small structural proteins of FeLV are ordered p11-p15-p10-p30. The data indicate that the small structural proteins of FeLV are synthesized as part of a 70,000-dalton precursor. A cleavage scheme for the generation of FeLV p70, p30, p15, p11, and p10 from precursor polypeptides is proposed.", "journal": "Journal of virology", "doi": "10.1128/JVI.22.1.74-85.1977", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "192437", "author": "Hardy WD Jr", "n_authors": 6, "title": "The epidemiology of the feline leukemia virus (FeLV).", "abstract": "Clustering of cases of feline lymphosarcoma (LSA) has been observed by veterinarians for many years. In 1964 it was discovered that feline LSA was caused by an oncornavirus, the feline leukemia virus (FeLV). In 1970, a simple, indirect immunoflourescent antibody (IFA) test for FeLV was developed which enabled large numbers of cats, living in their natural (household) environments, to be tested for the virus. In one study, over 2,000 cats were tested and the results showed conclusively that FeLV is a contagious agent for cats. This finding was independently confirmed by several other investigators using different testing procedures. After discovering the contagious nature of FeLV a test and removal program was devised which successfully prevents the spread of FeLV and the development of FeLV diseases in the pet cat population. There is, at present, no evidence that FeLV infects humans living with FeLV infected cats.", "journal": "Cancer", "doi": "10.1002/1097-0142(197704)39:4+<1850::aid-cncr2820390817>3.0.co;2-s", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "191424", "author": "Albert DM", "n_authors": 5, "title": "Retinal neoplasia and dysplasia. I. Induction by feline leukemia virus.", "abstract": "Feline leukemia virus, a naturally occurring C-type virus (oncorna virus), was injected systemically and intraocularly into fetal and newborn kittens. A light microscopy study of the resultant ocular tumor changes was carried out. One animal developed an intraocular tumor of apparent retinal origin. Eight animals showed intraocular neoplastic cell infiltration. The most common ocular change observed was retinal dysplasia. Sequential histologic examination of enucleated eyes showed diffuse intraocular inflammation after viral inoculation. In the developing retinas progressive disorganization and necrosis were documented, with subsequent reorganization into cell clumps and dysplastic rosette structures. The retinal pigment epithelium showed proliferation and intraretinal migration. The mature retina exhibited full-thickness folds and tubes associated with infoldings of the retinal pigment epithelium.", "journal": "Investigative ophthalmology & visual science", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "193031", "author": "Niman HL", "n_authors": 4, "title": "RD-114 and feline leukaemia virus genome expression in natural lymphomas of domestic cats.", "abstract": null, "journal": "Nature", "doi": "10.1038/266357a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "192759", "author": "Mathes LE", "n_authors": 3, "title": "Purification of infectious feline leukemia virus from large volumes of tissue culture fluids.", "abstract": "Feline leukemia virus from tissue culture fluids was concentrated 100 times by continuous-flow molecular filtration. Virus concentrates retained 100% of their original infectivity. Further purification was accomplished by a single sucrose density gradient centrifugation.", "journal": "Journal of clinical microbiology", "doi": "10.1128/jcm.5.3.372-374.1977", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "191832", "author": "Stephenson JR", "n_authors": 5, "title": "Feline oncornavirus-associated cell-membrane antigen (FOCMA): distinction between FOCMA and the major virion glycoprotein.", "abstract": "The humoral antibody response of feline leukemia virus (FeLV)-exposed cats to the feline oncornavirus-associated tumor cell-membrane antigen (FOCMA) is directly correlated with immunosurveillance against tumor development under natural conditions. By means of membrane immunofluorescence and radioimmunoprecipitation, the antibody response to FOCMA was found to be independent of the antibody response to the major envelope and core proteins of FeLV, gp70 and p30. This was especially true for healthy viremic cats, where antigenemia with circulating FeLV gp70 and p30 apparently binds any free antibody to these proteins, but high levels of FOCMA antibody are often concurrently present. Exhaustive in vitro absorption of highly immune nonviremic serum with gp70 and p30 also failed to remove FOCMA antibody activity. These results indicate that FOCMA is not one of these major FeLV structural proteins.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.74.3.1219", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "191976", "author": "Hardy WD Jr", "n_authors": 2, "title": "Feline leukemia virus. Its related diseases and control.", "abstract": null, "journal": "The Veterinary clinics of North America", "doi": "10.1016/s0091-0279(77)50008-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "189052", "author": "Hoover EA", "n_authors": 4, "title": "Horizontal transmission of feline leukemia virus under experimental conditions.", "abstract": "Thirty-seven specific-pathogen-free (SPF) cats ranging from newborn to 1 year were inoculated with the Rickard strain of feline leukemia virus (FeLV). Each inoculated cat shared a cage with a control SPF cat for 40 weeks post inoculation. After 4-5 weeks, 20 of the inoculated cats became group-specific antigen (gsa)-positive; the other 17 remained gsa-negative but developed virus neutralizing and feline oncornavirus cell membrane-associated antigen antibody titers. Seventeen of the control cats in contact with the gsa-positive cats developed evidence of FeLV infection 4-18 weeks after virema was detected in their inoculated cage mates. Of the control cats in contact with inoculated cats that remained gsa-negative, none developed evidence of FeLV infection. Data indicated that the gsa-positive state in cats inoculated with FeLV correlated with the capacity for horizontal transmission of the virus.", "journal": "Journal of the National Cancer Institute", "doi": "10.1093/jnci/58.2.443", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "66679", "author": "Smith HS", "n_authors": 3, "title": "Expression of antigenic crossreactivity to RD114 p 30 protein in a human fibrosarcoma cell line.", "abstract": "An antigen crossreacting with the 30,000-molecular-weight protein (p30) of the feline endogenous oncornavirus (RD114) was detected in a well-characterized human fibrosarcoma cell line, HT1080, by indirect immunofluorescence. Three antisera against RD114 p30 gave similar positive results, while two antisera prepared against simian sarcoma virus p30, one antiserum prepared against murine leukemia virus p30, and one antiserum prepared against feline leukemia virus p30 gave no immunofluorescence. The reactivity observed with the antiserum against RD114 p30 was detected in 10-40% of the cells at early passages and was no longer expressed by the forty-first subculture. The reactivity could be removed by adsorption of the antiserum with RD114-infected dog or human cells, but not by uninfected cells or by cells infected with an antigenically unrelated oncornavirus, feline leukemia virus. Neither complete virus particles nor reverse transcriptase (RNA-dependent DNA nucleotidyltransferase) activity was detected in the culture. These experiments suggest that the fibrosarcoma cell line is expressing an antigen related to the p30 protein of RD114 baboon endogenous virus group of oncornaviruses without producing complete virions.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.74.2.744", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "189647", "author": "Hinshaw VS", "n_authors": 2, "title": "Isolation of feline leukemia virus from clinical specimens.", "abstract": "Specimens obtained from feline leukemia virus (FeLV)-positive cats were examined for infectious FeLV. Feline leukemia virus was detected by a focus-forming assay and confirmed by florescent antibody. Techniques of sample processing were evaluated and adjusted for optimum detection of FeLV. Low levels of FeLV were detected in 2 of 10 oral samples; however, the majority of these samples (17 of 27 tested) produced cytopathic effects in tissue culture which prevented Fe LV detection. Three of 24 urine samples and 1 of 20 rectal specimens were positive for FeLV. One milk sample contained high levels of FeLV.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "189040", "author": "Grant CK", "n_authors": 3, "title": "Detection of complement-dependent lytic antibodies in sera from feline leukemia virus-infected cats by the chromium-51 release assay.", "abstract": "Sera from feline leukemia virus-infected cats lysed FL74 cells in the presence of an appropriate complement source; lysis was detected with the use of the 51 Cr release method. Serum complement from both rabbits and guinea pigs mediated lysis. Partial correlation of results was obtained from preliminary comparisons of lysis and immunofluorescence tests with the use of FL74 cells as targets.", "journal": "Journal of the National Cancer Institute", "doi": "10.1093/jnci/58.1.157", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "189037", "author": "de Noronha F", "n_authors": 4, "title": "Virus isolation test for feline leukemia virus.", "abstract": "A method was developed for detecting feline leukemia virus (FeLV) infection in cats by coculturing separated blood lymphocytes and platelets with clone 81 cells carrying a murine sarcoma genome but free of leukemia virus (S+L-). FeLV caused cell transformation that was easily visible 3-12 days after infection. This method is simple, sensitive, and easily read; it has the advantage of directly detecting infectious FeLV rather than viral antigens.", "journal": "Journal of the National Cancer Institute", "doi": "10.1093/jnci/58.1.129", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "188865", "author": "Cloyd MW", "n_authors": 2, "title": "Contained indirect viable-cell membrane immunofluorescence microassay for surface antigen analysis of cells infected with hazardous viruses.", "abstract": "A microtechnique for an indirect viable-cell membrane immunofluorescence titration assay was developed using Friend murine leukemia virus (F-MuLV)-producing cells and monospecific rabbit antisera to F-MuLV structural antigens. The assay was sensitive and displayed little variation within or between assays. Since moderate-risk tumor viruses, such as recently discovered primate oncornaviruses or feline leukemia virus (FeLV), may be hazardous to laboratory personnel, the assay was adapted for containment of cells infected with such viruses. Cells producing gibbon ape lymphoma virus or FeLV were grown in class III containment cabinets and transferred in sealed flasks to a class II laminar-flow cabinet, where the assay was performed. This micromethod not only conserved reagents but also minimized the numbers of moderate-risk tumor virus-infected cells handled at one time. Centrifugation was contained using custom-made devices shown to form a gas-tight seal over microtiter plates. Interspecies reactivity of monospecific rabbit antisera against F-MuLV structural antigen gp71, but not against p12, was demonstrated for surface antigens on FeLV-producing cells.", "journal": "Journal of clinical microbiology", "doi": "10.1128/jcm.5.1.86-90.1977", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "188773", "author": "Essex M", "n_authors": 7, "title": "Horizontal transmission of feline leukemia virus under natural conditions in a feline leukemia cluster household.", "abstract": "Ten post-weanling 4-month-old cats, designated \"tracers\", were placed in a feline leukemia cluster household to determine the efficiency of horizontal transmission of feline leukemia virus (FeLV). The tracer cats were confirmed as negative for prior exposure to FeLV. Following the placement in the leukemia cluster environment, the tracer cats were serologically monitored at intervals of 3-6 weeks for a total period of 1 year. The tests employed included the detection of FeLV using fixed-cell immunofluorescence and the detection and titration of antibody to : (1) the feline oncornavirus-associated cell membrane antigen (FOCMA), as detected by membrane immunofluorescence; (2) viable FeLV, using serum neutralization; (3) virion core protein p30, using radioimmunoprecipitation; and (4) virion glycoprotein gp70, using radioimmunoprecipitation. All of the tracers had evidence of horizontal infection by FeLV, by several criteria. Seven of the 10 had virus that could be isolated from plasma. All of these 7 developed a terminal illness within 18 months; 3 developed aplastic anemia, 3 infectious peritonitis, and 1 lymphoma. The remaining 3 were negative for FeLV by both virus isolation and fixed-cell immunofluorescence. These 3 did, however, develop high antibody titers by all four criteria and they remained healthy throughout the examination period. These results clearly indicate that unprotected pros-weanling cats brought into a leukemia exposure household environment have a high risk of becoming infected with FeLV. Furthermore, a large proportion of the cats are at risk for development of persistent viremia and FeLV-related diseases.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910190113", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "65230", "author": "Robey WG", "n_authors": 7, "title": "Cells transformed by certain strains of Moloney sarcoma virus contain murine p60.", "abstract": "It was previously demonstrated that the 60,000 dalton (p60) precursor-like polyprotein containing murine p30 was a constituent of the feline leukemia virus pseudotype of Moloney sarcoma virus [m1MSV(FeLV)]. It is now shown that p60 is detected in cells of five mammalian species transformed by m1MSV, indicating that p60 is specified by this genome. Moreover, little or no murine p30 is detected in the m1MSV-transformed cells, suggesting that the murine group p30 antigenic reactivity of S + L- cells is ude to p60. Pulse-chase studies in cells producing m1MSV(FeLV) show that p60 is the largest polypeptide detectable during the pulse, and that intracellular p60 is not cleaved into smaller (for example, p30) polypeptides during chase periods of up to 10 hr. The lack of cleavage of p60 is in contrast to the properties of p30 precursors detected in cells containing replicating avian or mammalian RNA tumor viruses. The inefficient cleavage of intracellular p60 and the kinetics of appearance of murine p30 in extracellular m1MSV(FeLV) suggest that p60 cleavage to p30 occurs in cells shortly before virus release. While only p60 was detected in the m1MSV-transformed cells, p60 and p70 were detected in m3MSV-transformed cells, and no immunoprecipitable polypeptides were detected in HT-1 MSV-transformed cells. The observed differences in the intracellular polypeptide expression by each of the strains of MSV suggests differences in genetic content.", "journal": "Cell", "doi": "10.1016/0092-8674(77)90142-8", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "64623", "author": "Collins JJ", "n_authors": 4, "title": "Interspecies determinants of Friend leukemia virus antigens involved in cytolysis of virus-pfoducing cells.", "abstract": "The cytolytic reactivity of a complex goat anti-feline leukemia virus (FeLV) antiserum for mouse cells (Eveline) releasing large quantities of Friend leukemia virus (FLV) was analyzed by the sensitive [14C]nicotinamide release microcytotoxicity assay. Whereas this interspecies killing reactivity could be blocked by absorption of the goat anti-FeLV serum with a preparation of disrupted FLV, absorption with purified FLV gp71, the major envelope glycoprotein, had no effect. Subsequent serum absorptions with the individual FLV structural polypeptides revealed that the lysis of the Eveline cells by the goat anti-FeLV serum is mediated by antibodies recognizing the interspecies determinant of p30, the major internal capsid protein. The expression of this internal viral component at the surface of virus-producing cells is discussed further. The results also demonstrated that removal of approximately 70% of the carbohydrate portion of gp71 with a preparation of glycosidases did not affect the integrity of its interspecies determinant; these results are in agreement with an earlier study (Bolgnesi et al., 1975) that examined primarily the group- and type-specific sites.", "journal": "Journal of virology", "doi": "10.1128/JVI.21.1.113-118.1977", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "219732", "author": "Hoover EA", "n_authors": 5, "title": "Modifications of the immunofluorescence assay for feline leukemia virus group-specific antigens.", "abstract": "Observations and minor modifications are presented concerning the immunofluorescence assay for feline leukemia virus (FeLV) group-specific antigens (GSA) in blood cells of cats. Data are given regarding absorption of goat FeLV GSA antiserum in vivo in cats, absorption of the antiserum in vitro with feline blood cells, and the comparative efficacy of various chemical fixatives in preservation of FeLV GSA for immunofluorescent staining. The best results were obtained with in vitro absorption of antiserum and methanol fixation of FeLV GSA in blood smears.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "216756", "author": "Francis DP", "n_authors": 2, "title": "Leukemia and lymphoma: infrequent manifestations of common viral infections? A review.", "abstract": "Horizontally transmitted viruses have been etiologically linked to leukemia and lymphoma in several higher mammals (gibbons, cows, and cats). In the best-studied example, the cat, feline leukemia virus is a common community-acquired virus that infrequently produces cancer. However, the infection and its complications (cancer) are not typical of infectious diseases. Epidemilogically, serologically, and virologically, infections with this type of virus can contradict classic infectious disease dogma. Therefore, previous studies that failed to link characteristics of infectious diseases (epidemiologic, serologic, or virologic) to human cancer must be cautiously interpreted. A link between retroviruses and/or DNA viruses and human lympho-reticular malignancies is hypothesized, and it is suggested that systematized nation-wide studies of selected cancer patients and their contacts be executed with the most sensitive and specific laboratory probes available.", "journal": "The Journal of infectious diseases", "doi": "10.1093/infdis/138.6.916", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "214605", "author": "Salerno RA", "n_authors": 4, "title": "Feline leukemia virus envelope glycoprotein vaccine: preparation and evaluation of immunizing potency in guinea pig and cat.", "abstract": null, "journal": "Journal of the National Cancer Institute", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "84436", "author": "Jacquemin PC", "n_authors": 5, "title": "Antibody response in cats to feline leukemia virus reverse transcriptase under natural conditions of exposure to the virus.", "abstract": null, "journal": "Virology", "doi": "10.1016/0042-6822(78)90393-8", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "82207", "author": "Jacquemin PC", "n_authors": 3, "title": "Surface antibodies of human myelogenous leukaemia leukocytes reactive with specific type-C viral reverse transcriptases.", "abstract": "Purified immunoglobin G (IgG) from patients with chronic myelogenous leukaemia specifically neutralised RT from feline leukaemia virus while purified IgG from other types of leukaemias and from normal blood cells were less reactive and in some cases preferentially reacted with RT from horizontally transmitted primate type-C viruses (simian sarcoma virus-gibbon ape leukaemia virus group). This indicates the presence of a heterogeneous immune response to RT or to an RT-like molecule in humans.", "journal": "Nature", "doi": "10.1038/276230a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "213655", "author": "Weijer K", "n_authors": 2, "title": "The control of lymphosarcoma/leukaemia and feline leukaemia virus.", "abstract": null, "journal": "The Journal of small animal practice", "doi": "10.1111/j.1748-5827.1978.tb05552.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "213612", "author": "Rojko JL", "n_authors": 6, "title": "Detection of feline leukemia virus in tissues of cats by a paraffin embedding immunofluorescence procedure.", "abstract": null, "journal": "Journal of the National Cancer Institute", "doi": "10.1093/jnci/61.5.1315", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "212375", "author": "Russell PH", "n_authors": 2, "title": "The occurrence of feline leukaemia virus neutralizing antibodies in cats.", "abstract": null, "journal": "International journal of cancer", "doi": "10.1002/ijc.2910220320", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "211674", "author": "Weijer K", "n_authors": 2, "title": "[Control of lymphosarcoma or leukaemia in cats and of feline leukaemia virus (author's transl)].", "abstract": "A removal programme, specially designed for catteries or multiple cat households, to reduce the incidence of lymphosarcoma or leukaemia in cats and the spread of feline leukaemia virus (FeLV), is discussed. This removal programme includes annual testing of male stud cats, testing all contacts of FeLV-positive cats they had during the past two years, testing cats imported from abroad and isolation--or, if this is not possible, euthanasia--of cats found to be positive for FeLV-antigen. To detect the FeLV-antigen a simple indirect fluorescent antibody technique (FAT) was used to detect FeLV-antigen. During a period of four years, the following results were obtained when a removal programme was carried out by a large cat breeders' association in the Netherlands. The proportion of catteries, in which FeLV-positive cats were found to be present, decreased from 11.5 per cent in the former half of 1974 to 2.1 per cent in the latter half of 1977. The proportion of FeLV-positive cats and male studs decreased from 4.9 per cent to 1.2 per cent and from 5.9 per cent to 1.0 per cent respectively during this period. It is concluded that the recommended removal programme is a simple and successful procedure.", "journal": "Tijdschrift voor diergeneeskunde", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "212755", "author": "Sherr CJ", "n_authors": 4, "title": "Characterization of a feline sarcoma virus-coded antigen (FOCMA-S) by radioimmunoassay.", "abstract": "A radioimmunoassay has been developed that detects a unique antigen encoded by the genome of the feline sarcoma virus (FeSV). Pseudotype viral particles containing an FeSV-specific polyprotein (p85) were used both as a source of antigen and to prepare specific antisera in rabbits. Because p85 contains antigens related to two structural proteins (p15 and p12) of feline leukemia virus (FeLV), antibodies directed to these were adsorbed with purified FeLV proteins. The adsorbed rabbit antiserum bound to antigenic determinants (designated FOCMA-S) which are also present in p85 and reacted specifically in immunofluorescence tests with rat cells transformed by FeSV and with FOCMA-positive cat lymphoid tumor cells. Competition assays detect FOCMA-S in pseudotype type C viruses rescued from FeSV-transformed mink and rat cells but not in heterologous type C helper viruses or in FeLV. A crossreactive antigen was also detected in pseudotypes of Kirsten sarcoma virus. The assay permits the quantitative measurement of an FeSV-coded protein whose expression is associated with viral transformation.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.75.9.4489", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "209338", "author": "Mathes LE", "n_authors": 5, "title": "Abrogation of lymphocyte blastogenesis by a feline leukaemia virus protein.", "abstract": null, "journal": "Nature", "doi": "10.1038/274687a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "677265", "author": "Glick AD", "n_authors": 3, "title": "Characterization of feline glomerulonephritis associated with viral-induced hematopoietic neoplasms.", "abstract": "Light, electron, and immunofluorescence microscopy on tissues from 63 domestic cats revealed that glomerulonephritis occurred in almost one third of cats with hematopoietic neoplasms of the type linked with feline leukemia virus (FeLV). Glomerular lesions were of the immune complex type with subepithelial, subendothelial, and mesangial dense deposits and reticular aggregates, similar to the nephropathy associated with systemic lupus erythematosus in humans. Evidence that the glomerular lesions may be viral-induced raises the possibility of similar pathogenetic mechanisms in human disease.", "journal": "The American journal of pathology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "211186", "author": "Russell PH", "n_authors": 1, "title": "Potentiation of the neurtalization of feline leukaemia virus in hypotonic medium.", "abstract": "The neutralization of feline leukaemia virus could be enhanced by performing the reaction in hypotonic medium. Absorption of antibody by virus specific antigens was also made more sensitive under these conditions.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-40-2-373", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "210130", "author": "Okabe H", "n_authors": 4, "title": "A portion of the feline leukaemia virus genome is not endogenous in cat cells.", "abstract": "Although viral sequences closely related to feline leukaemia virus are represented in multiple copies in cellular DNA of all domestic cats, a specific fraction was present only in the virus-infected cells. This fraction was detected by viral cDNA enriched by a prior absorption of a total complementary DNA (cDNA) transcript with normal cat liver DNA. The recycled cDNA hybridized well with the cellular DNA of virus-infected cells, but to a lesser extent with DNA from uninfected cat cells. The probe was used to differentiate virus-positive from virus-negative tumour tissues of cats. The same approach with cDNA of another endogenous feline virus, RD114, failed to show any difference between a virus-infected cell line and normal cells, including both virus-inducible and non-inducible lines.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910220114", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "220806", "author": "Maggio L", "n_authors": 6, "title": "Feline preleukemia: an animal model of human disease.", "abstract": "In man, hematologic abnormalities precede the development of acute myeloblastic leukemia in about one-third of individuals. This preleukemic state may represent a stage of adult leukemia wherein small numbers of leukemic cells are present and the normal marrow stem cell compartment has not been seriously compromised. A syndrome resembling human preleukemia occurs in cats infected with feline leukemia virus (FeLV). This disorder is characterized by anemia, leukopenia or thrombocytopenia occurring weeks or months prior to the development of feline acute leukemia. The natural occurrence of this syndrome in this domestic animal population makes it a potential model of human preleukemia. Initial poor results of therapy of human preleukemia presently prohibit one from carrying out controlled trials with chemotherapeutic agents in such a group of patients. Preliminary trials with chemo- and/or immunotherapy may be more easily attempted with FeLV infected preleukemic cats.", "journal": "The Yale journal of biology and medicine", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "208991", "author": "Russell PH", "n_authors": 2, "title": "The specificity of neutralizing antibodies to feline leukaemia viruses.", "abstract": "Feline leukaemia viruses (FeLV) of subgroups A (FeLV-A), B(FeLV-B) and C(FeLV-C) were examined by neutralization. The FeLV-A isolates were monotypic. By contrast, there was antigenic variation within subgroups B and C. There was also considerable cross-reactivity between subgroups. Thus, FeLV-A viruses showed weak cross-reactivity to the standard FeLV-C isolate; four of the subgroup B viruses were identical and cross-reactied with the standard FeLV-C, but not with FeLV-A or the fifth FeLV-B, and this latter virus weakly cros-reacted with FeLV-A but not with the FeLV-C; within subgroup C, one virus was indistinguishable from the standard FeLV-C strain but the other two were very similar to FeLV-A. Therefore, subgroup classification based on interference did not altogether correspond with neutralizing behaviour for subgroups B and C.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910210615", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "207994", "author": "Krakower JM", "n_authors": 2, "title": "Seroepidemiologic assessment of feline leukaemia virus infection risk for man.", "abstract": null, "journal": "Nature", "doi": "10.1038/273463a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "208436", "author": "Hoover EA", "n_authors": 5, "title": "Influence of thymectomy on the susceptibility of cats to feline leukemia virus and lymphosarcoma.", "abstract": "Twelve cats were thymectomized at 5 weeks of age. Six of these cats were inoculated at 8 weeks of age and 6 at 4 months of age with the Rickard (R) strain of feline leukemia virus (FeLV), which produces a high incidence of thymic lymphosarcoma. Two groups of age-matched nonthymectomized cats were inoculated with the same FeLV-R stock. Thymectomy prior to FeLV infection had no influence on the induction of viremia or the incidence of lymphosarcoma. In the FeLV-inoculated nonthymectomized cats, lymphosarcoma developed in the thymus. In the thymectomized cats, lymphosarcoma developed in the intestine, mesenteric lymph nodes, and bone marrow, but the malignant lymphoblasts had surface markers characteristic of feline T lymphocytes. It was concluded that the presence of the thymus per se is not required for infection and oncogenesis by FeLV and that feline T lymphocytes may be transformed after peripheralization to other tissues.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "207884", "author": "Thomason AR", "n_authors": 4, "title": "Presence of 5'-terminal cap structures in virus-specific RNA from feline leukemia virus-infected cells.", "abstract": "The F-422 line of feline thymus tumor cells, chronically infected with the Rickard strain of feline leukemia virus (R-FeLV), was labeled with 32P, and the total cytoplasmic RNA was isolated. The RNA was centrifuged through sucrose gradients, and R-FeLV virus-specific RNA (vRNA) was located by hybridization of portions of the gradient fractions to R-FeLV complementary DNA. vRNA classes with average sedimentation coefficients of approximately 36S, 28S, 23S, and 15S were identified. Each class of RNA was recovered by hybridized with mercurated R-FeLV complementary DNA, and the hybrids were chromatographed on columns of sulfhydryl-Sepharose to separate them from unhybridized cellular RNA. Although insufficient amount of 36S and 28S vRNA were obtained for further analysis, the 23S and 15S VRNA classes were analyzed to determine the nature of their 5' termini. Each of these vRNA classes was found to contain stoichiometric amounts of cap structures per unit length of RNA, consistent with the presence of one cap per molecule. The structure of the 23S vRNA cap was found to be m7G5'ppp5'GmpAp, whereas that of the 15S vRNA cap was m7G5'ppp5'GmpGp.", "journal": "Journal of virology", "doi": "10.1128/JVI.26.2.226-235.1978", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "80888", "author": "Al'tshteĭn AD", "n_authors": 3, "title": "[Detection of common antigenic determinants in the envelopes of mammalian type D (Mason--Pfizer) and type C virions by using the virion precipitation reaction].", "abstract": "Immune sera to Mason-Pfizer virus (M-PMV) are capable of precipitating type C viruses of mice (NIH-MuLV, G-MuLV, and to a lower degree R-MuLV), cats (FeLV, RD-114), and monkeys (SSV-1, GALV, BEV). The immune sera to RD-114, BEV, SSV-1 and GALV viruses can precipitate M-PMV virions. The adsorption analysis suggests that cross-reactions between M-PMV, RD-114, NIH-MuLV, and G-MuLV viruses depend on common virus-specific antigenic determinants in the envelopes of the virions. The relationship between M-PMV and type C viruses decreases in the series RD-114--NIG-MuLV--G-MuLV. Type C viruses of mammals have common envelope antigenic determinants lacking in M-PMV. No common antigenic determinants with M-PMV have been found in the envelope of virions of bovine leukemia virus, type B virus of mice (MMTV), or type C avian virus (Pr-RSV).", "journal": "Voprosy virusologii", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "208983", "author": "Jarrett O", "n_authors": 2, "title": "Differential growth and transmission in cats of feline leukaemia viruses of subgroups A and B.", "abstract": "The outcome of infecting cats with FeLV of sub-groups A (FeLV-A) or B (FeLV-B) was different. After FeLV-A infection, virus was quickly recovered from the blood and oropharynx of most animals. Following infection with FeLV-B, only a small proportion of cats developed a viraemia, and this after a long interval. There was no evidence that FeLV-B was transmitted by contact. The result of infecting cats with mixtures of FeLV-A and B (FeLV-AB) was that to a large extent each virus operated independently. FeLV-A was recovered from the plasma first, in a high proportion of the cats, and FeLV-B appeared later but not in all cats. There was evidence of interaction, however, in that the proportion of cats which were viraemic with FeLV-B was greater following FeLV-AB infection than after infection with FeLV-B alone; also FeLV-B was transmitted by contact from cats excreting FeLV-AB. These results help to explain the apparent dependence of FeLV-B on FeLV-A under natural conditions and the frequency of occurrence of sugroups A and B in FeLV isolates.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910210411", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "206528", "author": "Schneider R", "n_authors": 1, "title": "The feline leukemia virus question.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "208242", "author": "de Noronha F", "n_authors": 4, "title": "Influence of antisera to oncornavirus glycoprotein (gp71) on infections of cats with feline leukemia virus.", "abstract": null, "journal": "Virology", "doi": "10.1016/0042-6822(78)90467-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "205356", "author": "Schaller JP", "n_authors": 5, "title": "Increased susceptibility to feline leukemia virus infection in cats exposed to methylnitrosourea.", "abstract": "Exposure of adult specific-pathogen-free cats to methylnitrosourea resulted in increased susceptibility to infection by feline leukemia virus. A greater proportion of cats exposed to methylnitrosourea and feline leukemia virus (69%) became persistently viremic than those exposed to feline leukemia virus alone (17%). Segmented neutrophils were reduced by 90 to 99% within 3 days following exposure to methylnitrosourea, (15 to 20 mg/kg) whereas the effects on lymphocytes and erythrocytes, although less obvious, were also detected.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "77333", "author": "Gerard GF", "n_authors": 1, "title": "Multiple RNase H activities in mammalian type C retravirus lysates.", "abstract": "Lysates of Moloney murine sarcoma-leukemia virus [M-MSV(MLV)], a virus complex grown in the rat cell line 78A-1, were found to contain three RNase H species separable by polycytidylic acid[poly(C)]-agarose chromatography. RNase H activity (RNase H I) associated with RNA-directed DNA polymerase eluted at 0.23 M KCI from poly(C)-agarose. RNase H II, which eluted from poly(C)-agarose at 0.12 M KCI and was not associated with DNA polymerase activity, was shown to be identical to an RNase H species (designated RNase H II) previously isolated from M-MSV(MLV) by a different procedure (G. F. Gerard and D. P. Grandgenett, J. Virol. 15:785-797, 1975). M-MSV(MLV) RNase H II was established to be a random exohybridase that requires free-chain termini in its hybrid substrate for activity. Lysates of Rickard feline leukemia virus also contained RNase H activity not associated with DNA polymerase activity that eluted from poly(C)-agarose at 0.12 M KCl. A third species of enzyme from M-MSV(MLV) lysates, called RNase H III, did not bind to poly(C)-agarose in 0.06 M KCl. RNase H III was purified from lysates of M-MSV(MLV) and M-MLV (grown in mouse cells) by sequential chromatography on poly(C)-agarose, DEAE-cellulose, phosphocellulose, and polyuridylic acid-Sepharose. Purified RNase H III (i) was free of any associated DNA polymerase activity, (ii) had an apparent molecular weight of 30,000 determined by Sephadex G-100 gel filtration, (iii) had an absolute requirement for Mn2+ (1 mM optimum) for the degradation of [3H](A)n.(dT)n, (iv) was inhibited by the presence of any salt in reaction mixtures, and (v) was endoribonucleolytic in its mode of action as indicated by the size distribution of limited degradation products of [3H](A)n.(dT)n. RNase H III was inhibited by antisera prepared against Rauscher MLV and simian sarcoma virus reverse transcriptase, and the quantity of RNase H III and RNase H I present in lysates of M-MLV were reduced and increased proportionately if virus was lysed in the presence of the protease inhibitor phenylmethylsulfonyl fluoride. These results indicate that RNase H III is a proteolytic cleavage product of DNA polymerase-RNase H. Substantial RNase H activity that did not bind to poly(C)-agarose in 0.06 M KCl was also found in lysates of Harvey MSV(MLV), Rauscher MLV, and Rickard feline leukemia virus, but not in lysates of avian myeloblastosis virus.", "journal": "Journal of virology", "doi": "10.1128/JVI.26.1.16-28.1978", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "75981", "author": "Sarma PS", "n_authors": 5, "title": "Experimental horizontal transmission of feline leukemia viruses of subgroups A, B, and C.", "abstract": "Experiments were conducted with cats in metal cages inside plastic isolators to determine whether feline leukemia virus (FeLV) of the three known antigenic subgroups (A, B, and C) is transmitted horizontally from infected cats to normal \"contact\" cats. Blood smears collected at weekly intervals were examined by the fixed-cell, indirect immunofluorescence test for FeLV internal p30 to follow the spread of infection from inoculated cat to contact cats. These studies established that viruses of all three subgroups are transmitted horizontally among kittens and adults with slightly varying degrees of speed. Virus was reisolated from one horizontally infected contact cat of each group, and its envelope antigenic type was the same as that originally inoculated into one cat of the same group. After the cats acquired the infection, they became chronic carriers of virus (viremic) during the observation period of 9 or 11 weeks post inoculation.", "journal": "Journal of the National Cancer Institute", "doi": "10.1093/jnci/60.4.871", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "204584", "author": "Jarrett O", "n_authors": 4, "title": "The frequency of occurrence of feline leukaemia virus subgroups in cats.", "abstract": "Feline leukaemia viruses (FeLV) were isolated from cats in Glasgow and New York with lymphosarcoma and from apparently healthy carrier cats. The subgroup composition of each isolate was determined. All isolates contained FeLV of subgroup A(FeLV-A) and a high proportion also contained subgroup B virus (FeLV-B). Virus of subgroup C (FeLV-C) was rare and occurred in association with FeLV-A and, in some isolates, with FeLV-B as well. The same pattern was observed in isolates from British and American cats. The frequency of FeLV subgroups was different in cats with lymphosarcoma and in healthy carrier cats. In cats with lymphosarcoma, 42% had FeLV-A and 58% had FeLV-AB; there was no obvious correlation between virus subgroup and type of disease. In FeLV-positive healthy cats, 65% had FeLV-A and 33% had FeLV-AB. FeLV-C was isolated only from cats with disease. The healthy carrier cats were from multiple-cat households (MCH). Two distinct types of FeLV-infected MCH were found: MCH-A in which the carrier cats yielded only FeLV-A, and MCH-AB in which cats with either FeLV-A or FeLV-AB were present. In MCH-AB half of the cats had FeLV-A and half had FeLV-AB. Overall, the proportion of cats in MCH which were viraemic with FeLV was 42%. However, there was a marked difference in the prevalence of carrier cats in each type of MCH: in MCH-A, 28% were FeLV-positive while in MCH-AB, 53% were viraemic.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910210314", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "206902", "author": "Sherr CJ", "n_authors": 5, "title": "Pseudotypes of feline sarcoma virus contain an 85,000-dalton protein with feline oncornavirus-associated cell membrane antigen (FOCMA) activity.", "abstract": "Feline sarcoma virus (FeSV) rescued from transformed nonproducer mink or rat cells contains two FeSV-specific antigens (p15 and p12), and the feline oncornavirus-associated cell membrane antigen (FOCMA). All three antigens are helper virus-independent and are encoded by the FeSV genome, FOCMA, p15, and p12 antigens cochromatograph as phosphorylated molecules of 85,000 molecular weight (pp85), adsorb to immunoadsorbant columns prepared with antibodies to feline leukemia virus (FeLV), and are precipitated with antisera to FeLV or FOCMA. Antibodies to FOCMA can be adsorbed with fractions containing pp85 but not with FeLV proteins, including p15 and p12. Thus, a virus-coded tumor antigen which immunizes cats against tumors induced by feline type C viruses is packaged in FeSV particles and is linked to viral structural protein.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.75.3.1505", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "205670", "author": "Conely AJ", "n_authors": 2, "title": "Analysis of cytoplasmic RNA and polyribosmomes from feline leukemia virus-infected cells.", "abstract": "Cytoplasmic virus-specific RNA and polyribosomes from a chronically infected feline thymus tumor cell line, F-422, were analyzed by using in vitro-synthesized feline leukemia virus (Rickard strain) (R-FeLV) complementary DNA (cDNA) probe. By hybridization kinetics analysis, cytoplasmic, polyribosomat, and nuclear RNAs were found to be 2.1, 2.6, and 0.7% virus specific, respectively. Size classes within subcellular fractions were determined by sucrose gradient centrifugation in the presence of dimethyl sulfoxide followed by hybridization. The cytoplasmic fraction contained a 28S size class, which corresponds to the size of virion subunit RNA, and 36S, 23S, and 15 to 18S RNA species. The virus-specific 36S, 23S, and 15 to 18S species but not the 28S RNA were present in both the total and polyadenylic acid-containing polyribosomal RNA. Anti-FeLV gamma globulin bound to rapidly sedimenting polyribosomes, with the peak binding at 400S. The specificity of the binding for nascent virus-specific protein was determined in control experiments that involved mixing polyribosomes with soluble virion proteins, absorption of specific gamma globulin with soluble virion proteins, and puromycin-induced nascent protein release. The R-FeLV cDNA probe hybridized to RNA in two polyribosomal regions (approximately 400 to 450S and 250S) within the polyribosomal gradients before but not after EDTA treatment. The 400 to 450S polyribosomes contained three major peaks of virus-specific RNA at 36S, 23S, and 15 to 18S, whereas the 250S polyribosomes contained predominantly 36S and 15 to 18S RNA. Further experiments suggest that an approximately 36S minor subunit is present in virion RNA.", "journal": "Journal of virology", "doi": "10.1128/JVI.25.3.750-763.1978", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "76684", "author": "Sherr CJ", "n_authors": 3, "title": "Endogenous mink (Mustela vison) type C virus isolated from sarcoma virus-transformed mink cells.", "abstract": "A previously described type virus stock (designated PP-1R), isolated by cocultivating baboon cells with mink cells transformed by Kirsten sarcoma virus (64J1), has been further cloned and characterized. End point-diluted stocks of PP-1R have been obtained that are free of focus-forming activity and lack both Kirsten sarcoma and primate type C viral sequences. Nucleic acid hybridization experiments show that the cloned virus (MiLV) is an endogenous, genetically transmitted virus of the mink (Mustela vison). MiLV replicates in canine, feline, and 64J1 mink cells but not in an untransformed mink cell line. Multiple viral gene copies can be detected in the DNA of normal mink cells in culture and in normal mink tissues; related endogenous viral genes are also detected in several related Mustela species. The virus codes for a p30 protein very closely related antigenically to that of feline leukemia virus but contains p15 and p12 proteins that are antigenically distinct. The mink cell line, Mv1Lu, and its Kirsten sarcoma-transformed derivatives, 64J1, express relatively low levels of type C viral RNA related to MiLV and normally do not produce detectable levels of MiLV p30 protein or complete, infectious viral particles. Infection of sarcoma virus-transformed mink cells with baboon type C virus, however, can augment the level of expression of endogenous mink viral RNA and can result in the synthesis and packaging of mink viral RNA and p30 antigen in extracellular virions. Since the Mv1Lu cell line and its tranformed derivatives have become widely used in studies of retroviruses, the possibility of activating endogenous mink viral genes should be considered by investigators working with these cells.", "journal": "Journal of virology", "doi": "10.1128/JVI.25.3.738-749.1978", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "75945", "author": "O'Brien SJ", "n_authors": 3, "title": "Deposition of retrovirus associated antigens (p30 and gp70) on cell membranes of feline and murine leukaemia virus infected cells.", "abstract": "A quantitative estimation of retrovirus associated cell membrane antigens of murine and feline cells infected with their respective type C leukosis virus is presented. Using a radio-immune assay with three broadly reactive antisera, the minimum estimated number of retrovirus associated antigenic determinants on YAC [Moloney leukaemia virus (MuLV) infected murine] and FL-74 [feline leukaemia virus (FeLV) infected feline] cells was 1.3 x 10(6) and 1.6 x10(6) determinants per cell respectively. The virus structural proteins p27-30 and gp70 were detected by three component specific antisera on murine and feline cell surfaces in amounts which varied between cell isolates. MuLV infected cells produced as many as 1.9 x 10(5) p30 antigenic determinants and 7.5 x 10(5) gp70 determinants on infected cells. FeLV infected cells (FL-74) expressed 5.6 x 10(5) p27 and 7.5 x 10(5) gp70 antigenic determinants per single cell surface. The major core protein (p27-30) and the major envelope glycoprotein (gp70) antigens are sufficiently physically separated on cell surfaces so that binding of either of the membrane antigens with component specific antibodies does not interfere with binding of antibodies specific for the other. Despite the expression of interspecies determinants for p30, gp70, and other retrovirus associated antigens detected by antibody procedures, interspecies determinants of cell mediated immunity could not be demonstrated in immune mice bearing Moloney sarcoma virus (MSV) induced tumours. Furthermore, xenogeneic immunization of mice with FL-74 cells failed to protect mice against the growth of MSV induced lymphoma or sarcoma.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-38-3-483", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "224760", "author": "Busse C", "n_authors": 3, "title": "Further investigations on the porcine lymphoma C-type particle (PLCP) and the possible biological significance of the virus in pigs.", "abstract": "The possible biological significance of the procine lymphoma C-type particle (PLCP) was investigated serologically. The screening of 1 200 field sera of apparently normal breeder pigs, performed with an immunodiffusion test, revealed negative results. The same results were obtained with sera from a herd with hereditary lymphosarcoma and with sera from experimentally infected piglets. In cases of doubtful precipitation lines additional tests with a more sensitive indirect immunofluorescence assay were performed. In no case a specific cytoplasmic fluorescence could be observed. The same sera of the 1 200 pigs were tested with BLV antigen as well as 350 bovine sera from BLV-positive cattle were tested with PLCP antigen. A possible antigenic relationship between BLV and PLCP could not be detected by the assays mentioned above. Purified PLCP was compared in SDS-PAGE with MuLV, FeLV, and BLV. The electrophoretical pattern presents suggestive evidence for a typical oncornavirus polypeptide composition. Apart from the presumable major internal protein with a molecular weight of 28 000 d, three low molecular weight proteins appeared at 12 000 d, 11 000 d, and 10 000 d. High molecular weight proteins could not be detected yet. The antigenic specificity of these bands has still to be confirmed.", "journal": "Annales de recherches veterinaires. Annals of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "203702", "author": "Grant CK", "n_authors": 7, "title": "Lysis of feline lymphoma cells by complement-dependent antibodies in feline leukemia virus contact cats. Correlation of lysis and antibodies to feline oncornavirus-associated cell membrane antigen.", "abstract": null, "journal": "Journal of the National Cancer Institute", "doi": "10.1093/jnci/60.1.161", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "201591", "author": "Okabe H", "n_authors": 4, "title": "Reiteration frequency of feline type C viral genomes in homologous and heterologous host cell DNA.", "abstract": "Differences in the multiplicity of proviral sequences of two feline endogenous viruses, RD-114 and FeLV, in homologous and heterologous host DNA were examined by viral cDNA hybridization using cellular DNA fractionated with respect to reiteration frequency. The endogenous proviral DNAs in cat cells were fractionated predominantly with intermediate-repeated sequences, while RD-114 proviral DNA in virus-infected human cells was fractionated together with unique-sequence DNA. These differences were consistent with the results of kinetic analysis using unfractionated DNA.", "journal": "Intervirology", "doi": "10.1159/000148943", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "80755", "author": "Grófová M", "n_authors": 7, "title": "The retrovirus particles in human myeloma cells RPMI8226: morphological, biochemical, immunological and infective transmission studies.", "abstract": "The retrovirus designated RPMI8226V (isolated from human myeloma cells RPMI8226) has been characterized with respect to its morphological, biochemical and immunological properties as well as its propagation in various animal and human cells. The myeloma cells RPMI8226 produce intracytoplasmatic A-type particles and extracellular particles. The extracellular particles have been classified as immature particles with translucent core center, typical mammalian C-type virus particles and C-type particles with intermediate membrane. However, the budded particles in secondarily infected human neoplastic cells contained complete doughnut-shaped nucleoids. This type of budding is rather characteristic for B-type particles. The 3H-uridine labeled RPMI8226 viral particles have a buoyant density 1.17 g/ml in sucrose gradient containing high molecular weight RNA and the distribution of viral structural proteins in SDS-PAGE is characteristic for oncornaviruses. The internal structural proteins according to MW are ranged from 13 000 to 30 000 daltons. The virus contains a magnesium-dependent reverse transcriptase. The cellular homogenate and viral concentrate from RPMI8226 cultures do not react with antibodies against ALSV, MuLV, FeLV, RD114, MP-MV and SiSLV. The only reaction was scored with anti BLV antibodies. However, anti BLV serum inhibiting the reverse transcriptase activity of BLV to 60% does not cross-react with the reverse transcriptase of RPMI8226V. In contrast to BLV concentrates, neither XC nor KC cells show syncytia formation by RPMI8226V. The RPMI8226V replication is restricted to human tumor and normal human glia-like cells. The possible origin of the virus is discussed.", "journal": "Neoplasma", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "316659", "author": "Legendre AM", "n_authors": 2, "title": "Feline skin lymphoma: characterization of tumor and identification of tumor-stimulating serum factor(s).", "abstract": "A feline leukemia virus-negative skin lymphoma was characterized as a T-lymphocyte neoplasm, using the guinea pig erythrocyte rosetting technique. The lymphoma cells responded well to phytohemagglutinin compared with normal feline lymphocytes which did not respond. Serum factor(s) was found in serum of a cat with lymphoma that was highly stimulating to autologous tumor cells, but not to normal cat lymphocytes.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "229270", "author": "Sherr CJ", "n_authors": 4, "title": "Restriction endonuclease mapping of unintegrated proviral DNA of Snyder-Theilen feline sarcoma virus: localization of sarcoma-specific sequences.", "abstract": "Extrachromosomal DNA purified from mink cells acutely infected with the Snyder-Theilen strain of feline sarcoma virus (FeSV) was digested with restriction endonucleases, and the DNA fragments were electrophoretically separated, transferred to a solid substrate, and hybridized with radiolabeled DNA transcripts complementary to different portions of the FeSV RNA genome. Major DNA species 8.4 and 5.0 kilobase pairs (kbp) long represent the linear, unintegrated proviruses of Snyder-Theilen feline leukemia virus and FeSV, respectively. Transfection experiments performed with electroeluted DNAs showed that the 8.4-kbp form led to the production of replicating nontransforming virus in mink and cat cells; in contrast, the 5.0-kbp DNA produced helper virus-independent foci of transformation in mouse NIH/3T3 cells and helper virus-dependent foci in mink cells at an efficiency comparable to that obtained with unfractionated extrachromosomal DNA. Sites of restriction endonuclease cleavage for six enzymes were oriented with respect to one another within the FeSV provirus. EcoRI recognized cleavage sites at 0.3 to 0.4 kbp from each terminus of FeSV DNA, reducing the 5.0-kbp DNA to molecules 4.3 kbp long; this enzyme excised a large internal proviral DNA fragment of corresponding size from the DNA of FeSV-transformed mink nonproducer cells. By using DNA transcripts complementary to different portions of the FeSV genome, sarcoma-specific sequences (the FeSV src gene) were positioned within 2.1 and 3.4 kbp from the 5' end of the proviral DNA with respect to the viral RNA genome. The src gene is flanked at both ends by sequences shared in common with feline leukemia virus. The localization of src sequences to this region suggests that a portion of an FeSV polyprotein which contains feline oncornavirus-associated cell membrane antigen (FOCMA-S) is the major product of this gene.", "journal": "Journal of virology", "doi": "10.1128/JVI.32.3.860-875.1979", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "229095", "author": "Cotter SM", "n_authors": 1, "title": "Anemia associated with feline leukemia virus infection.", "abstract": "One hundred feline leukemia virus-positive cats with evidence of anemia were examined to determine characteristics of the anemia. The anemia was usually normochromic and normocytic, with low reticulocyte counts but with normal white blood cell and platelet counts. About one third of the cats had splenomegaly. The bone marrow was usually hypocellular or normally cellular, with an increased myeloid to erythroid ratio. A history of recent stress or infection in many cases indicated that the immunosuppressive effect of feline leukemia virus may have been involved. Supportive treatment with periodic blood transfusions was successful in prolonging survival. Corticosteroids and androgens may have been beneficial in some cases.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "162045", "author": "Tarr MJ", "n_authors": 5, "title": "The effects of methylnitrosourea on the immune system and hematopoietic system of adult specific pathogen free cats.", "abstract": "The effects of a single non-carcinogenic dose of 15 mg/kg methylnitrosourea (MNU) on the immune and hematopoietic systems of adult specific-pathogen-free (SPF) cats were determined. The cell-mediated-immune (CMI) system was markedly suppressed, as evidenced by: (i) Prolonged cutaneous allograft retention time (41-84 days); (ii) Decreased lymphocyte blast transformation response to mitogens (2% of pretreatment response to pokeweed mitogen or concanavalin A) and antigen (12% of untreated control cat response to keyhole limpet hemocyanin); (iii) Reduced number of absolute erythrocyte-rosetting T-cells in the peripheral blood. This immunosuppression lasted at least 3 months, the duration of the experiment. Suppression of the hematopoietic system was also noted as evidenced by: (i) Peripheral lymphopenia lasting 3 months and neutropenia lasting 3 weeks; (ii) Bone marrow hypocellularity lasting 3 weeks; (iii) Hypoplasia of neutrophilic precursors lasting 3 weeks and erythroid precursors lasting 4 days. It was concluded that a single non-carcinogenic dose of MNU induces a prolonged suppression of the CMI system and a brief suppression of hematopoiesis in adult SPF cats. The immunosuppression may in part be responsible for the previously observed increased susceptibility to feline leukemia virus infection and disease of adult SPF cats treated with MNU.", "journal": "Chemico-biological interactions", "doi": "10.1016/0009-2797(79)90160-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "93586", "author": "Schaller JP", "n_authors": 4, "title": "Enhancement of feline leukemia virus-induced leukemogenesis in cats exposed to methylnitrosourea.", "abstract": "The effect of methylnitrosourea (MNU), a potent resorptive carcinogen, was evaluated for its influence on the susceptibility of adult cats to infection and induction of oncornavirus disease by feline leukemia virus (FeLV). Young adult cats at an age previously demonstrated to be highly resistant to FeLV, were injected intravenously with moderately toxic doses (15-20 mg/kg) of MNU alone or with infections FeLV (Rickard strain). Following exposure to virus and chemical, cats were monitored for antibody to the feline oncornavirus-associated cell membrane antigen (FOCMA), viremia by direct infectivity and the presence of gsa in peripheral blood leukocytes, and for toxic effects of MNU by hemogram analyses on peripheral blood. Of 8 cats injected with MNU + FeLV, 6 developed persistent viremia, 5 of which became debilitated from thymic lymphoma. Only 1 of 6 non-MNU-treated and infected cats of the same age became transiently viremic. FOCMA antibody development was markedly depressed in MNU + FeLV inoculated cats compared with cats inoculated with FeLV alone. Results show that MNU was apparently responsible for the obliteration of age-related susceptibility in cats to FeLV infection and induction of FeLV-related disease, and suggest that in nature exposure to toxic chemical carcinogens may act as factors which determine susceptibility to feline oncornaviruses in the cat.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910240526", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "229397", "author": "Sodikoff C", "n_authors": 1, "title": "In-hospital FeLV testing.", "abstract": null, "journal": "Modern veterinary practice", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "228103", "author": "Azocar J", "n_authors": 2, "title": "Susceptibility of human cell lines to feline leukemia virus and feline sarcoma virus.", "abstract": "The susceptibility of human fibroblasts and human lymphoid cell lines to feline leukemia virus (FeLV) and feline sarcoma virus (FeSV) was investigated. Human cells were highly sensitive to infection by FeLV subgroups B and C and FeSV but resistant to infection by FeLV subgroup A. The cells became infected, produced infectious virus, and displayed no differences in morphology or viability. T-cell lines appeared to be more sensitive to FeLV and FeSV infection and to produce more virus than did autochthonous B-cells. B-cell lines with membrane IgG appeared more resistant to infection than did those with no membrane IgG.", "journal": "Journal of the National Cancer Institute", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "227157", "author": "Koshy R", "n_authors": 5, "title": "Distribution of feline leukemia virus DNA sequences in tissues of normal and leukemic domestic cats.", "abstract": null, "journal": "Virology", "doi": "10.1016/0042-6822(79)90044-8", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "92319", "author": "Jurjus A", "n_authors": 4, "title": "Placenta-bound immunoglobulins.", "abstract": "Low pH eluates were prepared from trophoblasts derived from 8 term human placentas. A qualitative analysis for immunoglobulins revealed the presence of IgG, IgA, and IgM in these eluates. IgC-rich fractions were obtained by DEAE-cellulose chromatography of ammonium sulfate-concentrated eluates. These fractions were able to neutralize, in vitro, the catalytic activity of reverse transcriptases (RT) from several retroviruses. RT from baboon endogenous virus (BEV) seemed to be more susceptible to the neutralizing activity of some eluates. This was in contrast to RT from feline leukemia virus (FeLV) which were neutralized by eluates of leukocytes from chronic myelogenous leukemia. In contrast to previous and present results with purified IgG from leukemic leukocytes, the purified IgG from placenta eluates was incapable of RT neutralization. However, such purified IgG fractions inhibited mixed lymphocyte reactions.", "journal": "Arthritis and rheumatism", "doi": "10.1002/art.1780221120", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "225010", "author": "Francis DP", "n_authors": 4, "title": "Comparison of virus-positive and virus-negative cases of feline leukemia and lymphoma.", "abstract": "One hundred eighty-four cases of feline leukemia and lymphoma diagnosed in Boston from 1972 through 1976 were investigated. Fifty-eight % of these cases were lymphoma, and 42% were leukemia. Sixty-seven % of the cats had positive fluorescent antibody tests for circulating feline leukemia virus. The rest (33%) were virus negative. Clinically and epidemiologically, the virus-positive and virus-negative cases were remarkably similar except for their age at diagnosis. Virus-negative cats tended to be older (mean age at diagnosis, 4.9 years) as compared to virus-positive cats (3.5 years). For 22 cases of leukemia and lymphoma diagnosed after the age of 8 years, 15 were virus negative. The minimum mean induction period (time from first positive virus test to diagnosis of cancer) for 19 cats that were virus positive and healthy at their first test was 16.7 months (range, 2 to 41 months).", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "93140", "author": "Calafat J", "n_authors": 4, "title": "Studies on antibodies against feline leukaemia virus (FeLV) in cat sera and rabbit anti-FeLV sera: cross reaction and differences.", "abstract": "The indirect immunoferritin technique (IFT) that enables us to distinguish clearly whether an antibody reacts with a virus particle or only with the cell membrane, was used to study 25 cat sera and one rabbit anti-feline leukaemia virus (FeLV) serum using FL-74 cells as target. (1) All sera contained antibodies against FeLV even though 11 of the cats were viraemic at the same time; (2) from the effect of glutaraldehyde fixation of the FL-74 cells on the reaction with cat sera and the results of blocking experiments, it could be concluded that cat sera and rabbit anti-FeLV sera react partly with different antigenic specificities of FeLV, partly with the same antigens; and (3) the indirect membrane immunofluorescence test using FL-74 cells as target is not a good test to detect the presence of antibodies against feline oncornavirus-associated cell membrane antigen (FOCMA) because FL-74 cells produce a large quantity of FeLV and the fluorescence measured could be from antibodies against FeLV.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-45-1-217", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "291976", "author": "Bernstein A", "n_authors": 4, "title": "Presence and expression of Friend erythroleukemia virus-related sequences in normal and leukemic mouse tissues.", "abstract": "The nature and distribution of sequences related to the murine erythroleukemia virus, Friend spleen focus-forming virus (SFFV), have been analyzed by using a radioactive cDNA probe specific for the SFFV genome (cDNA(sff)). From the proportion of high molecular weight viral [(32)P]RNA which hybridized to cDNA(sff), it was estimated that these sequences represent about 50% of the SFFV genome, indicating a genetic complexity of about 3300 nucleotides. cDNA(sff) hybridized extensively (80-95%) to SFFV virion RNA and to cellular RNA from murine and rat cells productively or nonproductively infected with SFFV. Only background homology was detected between cDNA(sff) and viral RNA from a number of murine [Friend murine leukemia virus (MuLV), Moloney-MuLV, and Kirsten sarcoma virus] and nonmurine (Rous sarcoma virus, feline leukemia virus, baboon endogenous virus, and Mason-Pfizer mammary tumor virus) retroviruses. Limited homology was also detected to a number of murine xenotropic and mink cell focus-inducing viruses (20-35%) as well as Rauscher leukemia virus (50%). Nucleotide sequences homologous to cDNA(sff) were also detected in the DNA of normal cells of several mouse strains as single or a few copies per cell. Thermal denaturation analysis indicated that duplexes formed between cDNA(sff) and normal DBA/2J cellular DNA have a reduction in melting temperature of 2 degrees C when compared with the dissociation of hybrids between cDNA(sff) and homologous sequences in SFFV-infected mouse spleen cell DNA. Examination of cellular RNA from uninfected mouse cells indicated that SFFV-related RNA sequences were also expressed in varying degrees in different tissues of adult DBA/2J mice. The highest amounts were observed in cells from bone marrow and spleen, whereas considerably lower amounts were found in cells from the thymus and kidney. No SFFV-related sequences could be detected in RNA extracted from liver, muscle, or fibroblasts. The presence of these SFFV-related sequences in normal, uninfected mouse cell DNA and their differential expression in hematopoietic tissues suggest that these sequences may be an integral part of the program of both normal and leukemic hematopoietic cell differentiation.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.76.9.4455", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "289225", "author": "Madewell BR", "n_authors": 3, "title": "Hematologic abnormalities preceding myeloid leukemia in three cats.", "abstract": "Cytopenia were recognized in three cats infected with feline leukemia virus. In one cat, marrow blast cells were increased in number, and a diagnosis of aleukemic leukemia was made. The disease progressed slowly for 3 1/2 months before terminating in acute myelomonocytic leukemia, recognized as a blast crisis in blood. In the other two cats, neutropenia and altered granulopoiesis in bone marrow preceded development of myeloid leukemia.", "journal": "Veterinary pathology", "doi": "10.1177/030098587901600502", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "232311", "author": "Gwalter RH", "n_authors": 1, "title": "[Feline leukosis virus (FeLV). Part II].", "abstract": null, "journal": "Schweizer Archiv fur Tierheilkunde", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "225025", "author": "Rojko JL", "n_authors": 5, "title": "Influence of adrenal corticosteroids on the susceptibility of cats to feline leukemia virus infection.", "abstract": "The natural resistance of adult specific-pathogen-free cats to feline leukemia virus (FeLV) was abrogated by treatment with various doses of a synthetic corticosteroid, methylprednisolone acetate (MPA), prior to either oral-nasal or i.p. inoculation of FeLV. Persistent viremia was induced in 82% (18 of 22) of MPA-treated cats versus 11% (1 of 9) of age-matched control cats. MPA-treated FeLV-inoculated cats developed prolonged lymphopenia (2 to 8 weeks postinoculation) and a delayed antibody response to the feline oncornavirus-associated cell membrane antigen. The distribution of FeLV group specific antigen in tissues of MPA-treated, FeLV-inoculated cats suggested that corticosteroids enhanced susceptibility to FeLV by impairing early viral containment in the reticuloendothelial and lymphoid tissues.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "225020", "author": "Azocar J", "n_authors": 2, "title": "Incorporation of HLA antigens into the envelope of RNA tumor viruses grown in human cells.", "abstract": "Virion antigens of feline leukemia virus are associated with HLA antigens in the membrane of human cells infected with the virus. Feline leukemia virus produced by these cells incorporates host membrane antigens into the virion envelope, making the virus susceptible to lysis by antisera directed to HLA or to uninfected cells plus complement.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "224237", "author": "Rojko JL", "n_authors": 5, "title": "Pathogenesis of experimental feline leukemia virus infection.", "abstract": null, "journal": "Journal of the National Cancer Institute", "doi": "10.1093/jnci/63.3.759", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "230767", "author": "Pedersen NC", "n_authors": 3, "title": "Safety and efficacy studies of live- and killed-feline leukemia virus vaccines.", "abstract": "The safety and the efficacy of several feline leukemia virus (FeLV) vaccines for 16-week-old kittens were determined. Vaccines were derived from an FL74 lymphoblastoid cell line that has been in continuous tissue culture passage for about 4 years. The vaccines were made from living virus, formaldehyde-inactivated whole FL74 cells, and formaldehyde-inactivated whole virus. The efficacy of each produced vaccine was determined by challenge exposure of vaccinated cats with virulent FeLV. The two formaldehyde-inactivated vaccines were found to be safe for use in kittens. Neither vaccine produce a significant feline oncornavirus-associated cell membrane antigen or virus-neutralizing antibody response, nor did they prevent infection with virulent FeLV. The inactivated whole-virus vaccine, however, did substantially decrease the proportion of kittens infected with virulent FeLV that became persistently viremic. In contrast, the whole FL74 cell vaccine did not reduce the number of infected kittens that became persistently viremic. The live-virus vaccine was found to be both safe and efficacious. About a half of the kittens vaccinated with live virus had transient bone marrow infection that lasted from 2 to 4 weeks. Viral antigen was not detected in peripheral blood, and infective virus was not shed in saliva, urine, or feces during the period that the vaccinal virus could be recovered from the bone marrow. In addition, there was no horizontal spread of vaccinal virus from vaccinated to non-vaccinated cagemates. Within several weeks, vaccinated kittens demonstrated no clinical or hematologic abnormalities and had high serum levels of feline oncornavirus-associated cell membrane antigen and virus-neutralizing antibody. Kittens vaccinated with living FeLV were resistant to infection with virulent virus.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "225379", "author": "Lutz H", "n_authors": 4, "title": "The demonstration of antibody specificity by a new technique. The gel electrophoresis-derived enzyme-linked immunosorbent assay (GEDELISA) and its application to antibodies specific for feline leukemia virus.", "abstract": "By combining the high resolution of sodium dodecylsulfate polyacrylamide gel electrophoresis with the sensitivity of enzyme-linked immunosorbent assay (ELISA) antibodies specific for different feline leukemia virus components are characterized. Based on the same principle, Concanavalin A binding sites of FeLV components are also detected.", "journal": "The journal of histochemistry and cytochemistry : official journal of the Histochemistry Society", "doi": "10.1177/27.8.225379", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "224571", "author": "Robbins KC", "n_authors": 4, "title": "Involvement of different exogenous feline leukemia virus subgroups in the generation of independent feline sarcoma virus isolates.", "abstract": null, "journal": "Virology", "doi": "10.1016/0042-6822(79)90367-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "507498", "author": "Nichols WS", "n_authors": 5, "title": "Feline lymphocytes: observations on surface membrane concanavalin A receptor mobility.", "abstract": "The mechanics of concanavalin A receptor mobility of the feline lymphocyte surface membrane were investigated, utilizing fluorescein-labeled lectin to quantitate lymphocyte capping. The results of this study indicated that lectin concentration and buffer selection were critical for extensive receptor redistribution with cap formation of feline lymphocytes. Maximal capping was obtained with 50 microgram of concanavalin A/ml of minimal essential medium. The mean capping rate of peripheral blood lymphocytes increased significantly with colchicine exposure at 10(-7) M concentration. The mean values of capping increased slightly with advancing age of feline donors, although this difference was not statistically significant. Concurrent work has indicated that concanavalin A capping may be useful in the study of immunosuppression in feline leukemia virus-infected cats.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "225795", "author": "Gwalter R", "n_authors": 1, "title": "[Feline leukemia virus (FeLV) I].", "abstract": null, "journal": "Schweizer Archiv fur Tierheilkunde", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "225544", "author": "Frankel AE", "n_authors": 5, "title": "Nature and distribution of feline sarcoma virus nucleotide sequences.", "abstract": "The genomes of three independent isolates of feline sarcoma virus (FeSV) were compared by molecular hybridization techniques. Using complementary DNAs prepared from two strains, SM- and ST-FeSV, common complementary DNA'S were selected by sequential hybridization to FeSV and feline leukemia virus RNAs. These DNAs were shown to be highly related among the three independent sarcoma virus isolates. FeSV-specific complementary DNAs were prepared by selection for hybridization by the homologous FeSV RNA and against hybridization by fline leukemia virus RNA. Sarcoma virus-specific sequences of SM-FeSV were shown to differ from those of either ST- or GA-FeSV strains, whereas ST-FeSV-specific DNA shared extensive sequence homology with GA-FeSV. By molecular hybridization, each set of FeSV-specific sequences was demonstrated to be present in normal cat cellular DNA in approximately one copy per haploid genome and was conserved throughout Felidae. In contrast, FeSV-common sequences were present in multiple DNA copies and were found only in Mediterranean cats. The present results are consistent with the concept that each FeSV strain has arisen by a mechanism involving recombination between feline leukemia virus and cat cellular DNA sequences, the latter represented within the cat genome in a manner analogous to that of a cellular gene.", "journal": "Journal of virology", "doi": "10.1128/JVI.30.3.821-827.1979", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "223166", "author": "Oroszlan S", "n_authors": 5, "title": "Amino-terminal sequence of bovine leukemia virus major internal protein: homology with mammalian type C virus p30 structural proteins.", "abstract": "The amino acid composition, the COOH-terminal amino acid, and the NH2-terminal amino acid sequence of the first 55 residues of the major internal structural protein, p24, of bovine leukemia virus (BLV) were determined. The compositional data and the results of end-group analysis revealed that, although BLV p24 is chemically distinct, it more closely resembles the p30 structural proteins than the other gag gene products of mammalian retroviruses. It was found that BLV p24 shares the common NH2-terminal proline and COOH-terminal leucine but lacks the common prolylleucylarginine tripeptide and the larger conserved region found near the NH2 terminus of all mammalian type C viral p30s. Alignment of the amino acid sequence of BLV p24 with the previously determined sequence of feline leukemia virus p27 revealed a statistically significant sequence homology. A more distant relationship was found between BLV p24 and other mammalian p30s. The finding of a definite sequence homology between BLV p24 and mammalian type C virus p30s clearly establishes the origin of these contemporary viral proteins from common progenitor genes.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.76.6.2996", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "221581", "author": "Kobilinsky L", "n_authors": 3, "title": "Hypocomplementemia associated with naturally occurring lymphosarcoma in pet cats.", "abstract": "Eighty cats were classified by indirect immunofluorescence and histologic diagnosis into four categories: normal, feline leukemia virus (FeLV) infected; normal noninfected; lymphosarcoma-FeLV infected; lymphosarcoma, no FeLV present. All viremic cats with lymphosarcoma were found to be hypocomplementemic and activation of the complement system had occurred via the classical pathway. Sera of cats with lymphosarcoma in the absence of FeLV had varying levels of total hemolytic complement (TCH50) ranging from normal to hypocomplementemic. Approximately 50% of the cats that were viremic but histologically and clinically free of disease had TCH50 levels within normal range, and the remainder exhibited varying degrees of hypocomplementemia.", "journal": "Journal of immunology (Baltimore, Md. : 1950)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "225513", "author": "Pinter A", "n_authors": 2, "title": "Structural studies of retroviruses: characterization of oligomeric complexes of murine and feline leukemia virus envelope and core components formed upon cross-linking.", "abstract": "To examine the protein proximity and subunit organization of type C retroviruses, preparations of AKR murine leukemia virus were treated with bifunctional cross-linking reagents and analyzed by sodium dodecyl sulfate-polyacrylamide gel electrophoresis (SDS-PAGE). The cross-linked components obtained were characterized by immunoprecipitation with monospecific antisera against purified viral proteins, followed by SDS-PAGE analysis both before and after cleavage of the cross-links. With these procedures, complexes of both viral envelope and core components were identified. The major envelope subunit obtained was a large (apparent molecular weight of 450,000 to 500,000), glycosylated complex, composed of four to six gp70-p15(E) subunits. This complex was detected over a 100-fold range of cross-linker concentration and thus seems to represent a particularly stable viral substructure. The cross-linked complexes of the core proteins consisted of oligomers of p30 dimers, suggesting that the p30 dimer is a basic structural unit of the viral core. When virion preparations, which had previously been disrupted with the nonionic detergent Nonidet P-40, were cross-linked, the envelope complex was still observed, indicating that this structure is stable in the presence of Nonidet P-40. A similar envelope structure was observed for feline leukemia virus, suggesting that such a complex may be a conserved feature of oncornavirus structure.", "journal": "Journal of virology", "doi": "10.1128/JVI.30.1.157-165.1979", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "222681", "author": "Mandel MP", "n_authors": 4, "title": "Endogenous RD-114 virus of cats: absence of antibodies to RD-114 envelope antigens in cats naturally exposed to feline leukemia virus.", "abstract": "Healthy cats, including those exposed to feline leukemia virus in leukemia cluster households, lack evidence of humoral immunity to virion surface antigens of the endogenous RD-114 virus.", "journal": "Infection and immunity", "doi": "10.1128/iai.24.1.282-285.1979", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "442447", "author": "Slauson DO", "n_authors": 2, "title": "Comparative pathology of glomerulonephritis in animals.", "abstract": "Glomerulonephritis constitutes an important category of renal diseases in animals and has been recognized with increasing frequency in the last decade. We report here the comparative morphologic aspects of glomerulonephritis as a naturally occurring disease of animals. We briefly review the immunopathogenesis of glomerulonephritis. The morphology of renal lesions occurring in glomerulonephritis in dogs, cats, cattle, sheep, horses and swine has been reviewed with emphasis on the range and specificity of various glomerular lesions and on the comparison of lesions between various species. A distinction was made between glomerulonephritis as a primary disease entity and glomerulonephritis associated with other disease processes. Primary idiopathic glomerulonephritis occurred in all species but was most commonly recognized as a clinically important disease in dogs and cats. Glomerulonephritis also occurred in association with other diseases such as equine infectious anemia, chronic hog cholera, canine pyometra, dirofilariasis, feline leukemia virus infection and canine systemic lupus erythematosus.", "journal": "Veterinary pathology", "doi": "10.1177/030098587901600201", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "218726", "author": "Dunlap JE", "n_authors": 5, "title": "Mobility of lymphocyte surface membrane concanavalin A receptors of normal and feline leukemia virus-infected viremic felines.", "abstract": "The virus-associated depression of concanavalin A mitogenesis which accompanies feline leukemia virus-induced cat lymphoma was investigated by comparing lymphocyte surface receptor mobility of normal cats to that of viremic diseased animals. The mechanics of feline lymphocyte receptor mobility were studied using fluorescein-conjugated concanavalin A to quantitate lymphocyte capping. The results of a study of 21 disease-free animals showed that cat lymphocytes undergo appreciable concanavalin A capping, with a mean capping rate of 17% under conditions developed in this study. In contrast, morphologically normal peripheral blood lymphocytes of six feline leukemia virus-infected viremic cats, with or without lymphoma, exhibited a mean capping of only 7%, significantly less than that of the control animals (p less than 0.005). These findings suggest that a membrane-related lymphocyte deficiency accompanies the development of virus-induced lymphoma in the cat.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "218725", "author": "Mathes LE", "n_authors": 7, "title": "Immunosuppressive properties of a virion polypeptide, a 15,000-dalton protein, from feline leukemia virus.", "abstract": "The 15,000-molecular-weight polypeptide (p15) of feline leukemia virus (FeLV) was shown to impair normal lymphocyte function in vitro and to abrogate immunity to feline oncornavirus disease in vivo. FeLVp15 suppressed concanavalin A-induced blast transformation of normal feline lymphocytes by 68%, while other virion proteins had no effect. p15 suppression was not due to toxicity, nor was p15 a competitive inhibitor of concanavalin A binding. Capping of receptors for concanavalin A on normal feline lymphocytes also was inhibited by either inactivated FeLV or FeLV p15. Groups of cats were immunized with either killed feline oncornavirus-associated cell membrane antigen bearing tumor cells or tumor cells plus FeLV p15. After challenge with feline sarcoma virus, three of four p15-treated cats developed progressive fatal fibrosarcoma as compared to one of five non-p15-treated cats. The cats receiving p15 also had lower cytotoxic antibody titers against feline oncornavirus-associated cell membrane antigen (mean peak titer, 1:6) than did the non-p15 group (1:74). These data support the hypothesis that the immunosuppression in cats infected with FeLV is mediated by FeLV p15.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "219252", "author": "Khan AS", "n_authors": 2, "title": "Feline sarcoma virus-coded polyprotein: enzymatic cleavage by a type C virus-coded structural protein.", "abstract": "A purified 15,000-molecular-weight (Mr) Prague strain Rous sarcoma virus gag gene-coded structural protein, p15, was shown to enzymatically cleave the previously described 130,000 Mr feline sarcoma virus-coded polyprotein, Pr130. Cleavage products included proteins ranging in molecular weight from 12,000 to 110,000. The specificity of this cleavage reactivity was indicated by the fact that, under similar conditions, neither purified type C viral structural proteins nor nonviral proteins such as bovine serum albumin were cleaved to significant extents. Moreover, feline leukemia virus Pr65gag was efficiently cleaved, resulting in the generations of proteins of 30,000 (p30), 15,000 (p15), 12,000 (p12), and 10,000 (p10) Mr. Using enzymatically (p15) treated feline sarcoma virus Pr130 as starting material, we were able to purify a major 72,000 Mr cleavage product and to show it to contain the previously described feline sarcoma virus-coded nonstructural component.", "journal": "Journal of virology", "doi": "10.1128/JVI.29.2.649-656.1979", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "216488", "author": "Hebebrand LC", "n_authors": 4, "title": "Inhibition of human lymphocyte mitogen and antigen response by a 15,000-dalton protein from feline leukemia virus.", "abstract": "Peripheral blood lymphocyte response of normal human subjects to mitogens and antigens was suppressed by a 15,000-dalton protein (p15) from a C-type feline leukemia virus. Four of six subjects were suppressed 70 to 96% when responding to concanavalin A or phytohemagglutinin in the presence of 5.0 microgram of p15. The three subjects who responded to streptokinase-streptodornase and Candida were suppressed 68 to 91% when cultured with 5.0 microgram of p15. The subviral protein did not appear to be cytotoxic at doses reported. Lymphocyte membrane studies with fluorescein isothiocyanate-concanavalin A revealed a reduction in concanavalin A-induced cap formation of 51 to 91% in the presence of the same dose of p15. These results demonstrate that in vitro immunological dysfunction in human lymphocytes can be induced by a C-type virion protein.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "232893", "author": "Francis DP", "n_authors": 5, "title": "Feline leukemia virus infections: the significance of chronic viremia.", "abstract": null, "journal": "Leukemia research", "doi": "10.1016/0145-2126(79)90040-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "232469", "author": "Essex M", "n_authors": 5, "title": "Leukemia specific antigens: FOCMA and immune surveillance.", "abstract": "In cats, horizontally transmitted viruses cause leukemia and lymphoma under natural conditions. As with other retroviruses, feline leukemia virus (FeLV) contains products of 3 major genes; the virus core gag gene products, the polymerase, and the virus envelope glycoprotein. When cells are transformed in vitro by the related feline sarcoma virus (FeSV), an additional protein, FOCMA is expressed at the cell membrane. FOCMA, which is FeSV-coded, is transformation and/or tumor specific and expressed regardless of whether or not the cells make virus or contain virus structural antigens. Lymphoid leukemia cells also express FOCMA, both when FeLV is used to induce the disease in laboratory cats and when the tumors occur under natural conditions. FOCMA is expressed on both T and B lymphoid leukemia cells, but not expressed on non-malignant lymphoid cells, even when they are infected with FeLV. About one-third of the naturally occurring lymphoid tumors of cats lack detectable FeLV proteins and varying portions of the FeLV provirus. Despite this, they regularly express FOCMA, which is the target of an immuno-surveillance response that functions effectively under most conditions. FOCMA thus provides a useful model for antigens that might be expressed in \"virus-negative\" leukemias of man.", "journal": "Haematology and blood transfusion", "doi": "10.1007/978-3-642-67057-2_60", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "219019", "author": "Francis DP", "n_authors": 3, "title": "Feline leukemia virus: survival under home and laboratory conditions.", "abstract": "Feline leukemia virus maintained its infectiousness in cell culture medium at 37 degrees C or lower for at least 48 h. However, virus in saliva or medium was inactivated within a few hours if allowed to dry.", "journal": "Journal of clinical microbiology", "doi": "10.1128/jcm.9.1.154-156.1979", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "217021", "author": "Salerno RA", "n_authors": 4, "title": "Infection and immunization of cats with the Kawakami-Theilen strain of feline leukemia virus.", "abstract": null, "journal": "Proceedings of the Society for Experimental Biology and Medicine. Society for Experimental Biology and Medicine (New York, N.Y.)", "doi": "10.3181/00379727-160-40379", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "216484", "author": "Grant CK", "n_authors": 5, "title": "Complement and tumor antibody levels in cats, and changes associated with natural feline leukemia virus infection and malignant disease.", "abstract": null, "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "94533", "author": "Micheel B", "n_authors": 3, "title": "Interspecies antigenic determinants of structural proteins of mammalian type-C viruses as detected by a competitive sepharose bead immunofluorescence assay.", "abstract": "The present paper describes a competitive immunoassay using antiserum to FeLV p 27 and SSV-conjugated Sepharose beads. The assay is applied to compare the interspecies-specific antigenic determinants of the major structural proteins of type-C viruses of different mammalian species. The test proves to be highly sensitive and specific and may be used for the demonstration of viral proteins in crude cellular extracts.", "journal": "Archiv fur Geschwulstforschung", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "83351", "author": "Ahmed M", "n_authors": 7, "title": "Characterization of a retrovirus isolated from normal mink cells co-cultivated with a dog mammary tumour.", "abstract": "A retrovirus antigenically distinct from known type C, B and D viruses was isolated from normal mink (Mustela vison) lung cells that had been co-cultivated with 5-iododeoxyuridine- and dexamethasone-treated dog mammary tumour cells. Cytogenetic studies of the virus-releasing co-culture showed mitotic figures identical to the normal mink cell line (MvlLu) with the exception of a low frequency of cells with extensive chromosomal breakage and uncoiling. The new virus bands at a buoyant density of 1.16 g/ml, contains 60S RNA and a reverse transcriptase which prefers Mn2+ over Mg2+ for the synthesis of DNA. This enzyme utilizes poly(rA).oligo(dT) more efficiently than poly(dA).oligo(dT) and is also able to synthesize DNA copies from the endogenous RNA. Morphologically, it is a typical type C virus. Filtered virus readily infects mink, dog and other mammalian cells indicating the amphotropic nature of its cell growth requirement. Hybridization studies showed that normal mink DNA contains multiple copies of proviral sequences of this newly isolated virus. Serological analyses indicate that the mink endogenous virus contains in its core protein, in addition to the interspecies type-C determinant, an antigenic component related to one of the determinants found in the feline leukaemia virus p30 protein. This determinant is not present in the Rauscher leukaemia virus, RD114 virus or simian sarcoma virus.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-42-1-179", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6262439", "author": "Kimball PC", "n_authors": 2, "title": "Three sizes of subunits in RNAs from feline sarcoma-leukaemia virus mixtures.", "abstract": "RNA from the Snyder-Theilen feline sarcoma-leukaemia virus complex (ST-FeSV-FeLV) sedimented in a double-peaked band between 50 and 70S, but Gardner-Arnstein (GA) FeSV-FeLV RNA sedimented in a single 70S peak. FeLV isolated from the ST virus mixture contained RNA which sedimented in a 70S band like GA-FeSV-FeLV RNA, but F422 FeLV RNA sedimented more slowly, at 50 to 60S. After thermal denaturation, resedimentation revealed three classes of RNA subunits in ST-FeSV-FeLV RNA: the first class, 35 to 37S, was also found in ST-FeLV and other FeLVs (except F422 FeLV), in the endogenous feline virus, RD114 and in GA-FeSV-FeLV; the second class, 32 to 34S, was similar to subunits in F422 FeLV and minor components of GA-FeSV-FeLV and ST-FeLV; the third class, 25S, was detected only in ST-FeSV-FeLV RNA. Electrophoresis of RNA species in buffered formamide provided evidence that the three classes of RNA subunits distinguishable on the basis of sedimentation rates actually represent three size classes of subunits. The ST virus mixture was shown to contain about equal titres of infectious FeLV and transforming FeSV whereas GA-FeSV-FeLV had at least a 10-fold excess fo FeLV over FeSV. These observations are discussed in terms of possible origins of the three sizes of FeSV-FeLV RNA subunits and their relationships to three species of FeSV-FeLV proviral DNA described recently (Sherr et al. 1979).", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-51-2-295", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6253714", "author": "Grant CK", "n_authors": 5, "title": "Protection of cats against progressive fibrosarcomas and persistent leukemia virus infection by vaccination with feline leukemia cells.", "abstract": "Young cats (3-6 mo old) were challenged with oncogenic Snyder-Theilen feline sarcoma virus (FeSV) after vaccination with live or killed FL74 cat lymphoma cells. Compared with controls immunized with normal cat fibroblasts, the FL74-vaccinated cats exhibited increased resistance to FeSV-induced progressive primary and disseminated secondary tumors. Maximum protection was achieved by vaccination with live FL74 cells or with a low dose of freeze-thawed cells, but tumor cells inactivated by glutaraldehyde or paraformaldehyde were also effective. Infectious helper feline leukemia virus (FeLV) was detected in the blood of all cats after FeSV challenge, but the duration and magnitude of this viremia were reduced in animals that had been previously vaccinated with live, freeze-thawed, or paraformaldehyde-fixed cells. Although immunized cats were resistant to FeSV-induced tumors and FeLV viremia, no evidence was obtained to suggest that vaccination with dead cells induced detectable circulating antibody prior to challenge with oncogenic virus. After FeSV challenge, complement-dependent antibody to feline oncornavirus-associated cell membrane antigen (CDA-FOCMA) appeared at high titer in cats that were destined either to survive tumor-free or to develop small, localized, and eventually regressing tumors. Cats immunized with live FL74 cells developed CDA-FOCMA prior to challenge, and antibody appeared in these cats following an episode of transient FeLV viremia induced by virus replicating from the injected tumor cells. Therefore, apparently, a state of transient or persistent FeLV viremia regularly preceded detection of CDA-FOCMA activity. Several individually derived feline lymphoma cell lines were used as targets for CDA-FOCMA, and the results suggested that lytic activity is directed to multiple antigen determinants expressed differently by individual feline lymphomas.", "journal": "Journal of the National Cancer Institute", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6253567", "author": "Day NK", "n_authors": 5, "title": "Circulating immune complexes associated with naturally occurring lymphosarcoma in pet cats.", "abstract": "Cats were classified into 4 categories by immunofluorescence antibody assay for the presence of feline leukemia virus (FeLV) and histologically as a) normal, FeLV-, b) normal, FeLV+, c) lymphosarcoma (LSA), FeLV+, and d) LSA, FeLV-. Determinations by Raji cell radioimmunoassay modified for cat serum revealed circulating immune complex (CIC) levels of healthy cats to be less than or equal to 50 micrograms equivalent aggregated cat immunoglobulin/ml (microgram/ml). In contrast, sera of cats in groups b, c, and d all contained significantly higher CIC levels (up to 12,000 micrograms/ml) associated with marked hypocomplementemia and C activation occurring via the classical pathway. Sera from FeLV+, LSA+ cats with high levels of CIC and sera of healthy cats were fractionated according to size and bouyant density by centrifugation through 10 to 40% sucrose gradients. Analysis of fractions from LSA+, FeLV+ sera revealed that both immune complexes (ICs), FeLV reverse transcriptase (RT), and IgG were present in fractions corresponding to a bouyant density of 1.15 to 1.18 g/ml. The CIC containing fractions activated C by the classical pathway. Sera from normal cats did not have CIC or RT and none of the fractions activated the classical pathway. These data suggest that vital antigen-antibody complexes are present in sera of viremic cats with LSA and these complexes activate the C system.", "journal": "Journal of immunology (Baltimore, Md. : 1950)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6253821", "author": "Hardy WD Jr", "n_authors": 7, "title": "Development of virus non-producer lymphosarcomas in pet cats exposed to FeLv.", "abstract": "Naturally occurring oncoviruses of several species are transmitted contagiously and cause lymphosarcoma (LSA) or leukaemia in their hosts. All naturally occurring oncoviruses replicate in vivo in the tumours they induce or, as with bovine leukaemia virus, can be isolated from tumour cells grown in short-term cell culture. However, we have shown that feline leukemia virus (FeLV) is not present in a significant minority of pet cats that develop LSA. Unlike experimentally induced virus-negative leukaemias and sarcomas of other species, LSA cells from FeLV-negative LSA cats lack any FeLV proteins, including p15 or p12, and complete functional copies of FeLV provirus and thus do not produce FeLV when grown in cell culture. Thus, except for FeLV, the naturally occurring animal leukaemogenic oncoviruses seem to induce only virus-producing lymphoid tumours. Our earlier findings prompted a study to determine the frequency of occurrence of FeLV non-producer (NP) LSA in pet cats and whether NP LSAs develop in cats exposed to FeLV. We report here epidemiological data which indicate that development of NP LSAs in pet cats is associated with exposure to FeLV and suggest that FeLV may be the aetiological agent for FeLV NP feline LSAs. Thus, feline NP LSAs may be suitable for studying the potential viral aetiology and mechanism of leukaemogenesis of human lymphoid tumours in which no oncoviruses have, as yet, been proved to cause the disease.", "journal": "Nature", "doi": "10.1038/288090a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6257828", "author": "Neil JC", "n_authors": 3, "title": "Polypeptides of feline leukaemia virus: identification of p15(E) and p12(E).", "abstract": "Antiserum to the p15(E) polypeptide of Rauscher murine leukaemia virus (R-MuLV) precipitated two proteins from purified virions of feline leukaemia virus (FeLV) with apparent mol. wt. of 18500 and 155000 on SDS-polyacrylamide gels. These proteins have been designated p15(E) and p12(E), in line with the nomenclature for MuLV proteins. Like the analogous protein of MuLV, FeLV p15(E) was found to be disulphide-linked to the virion glycoprotein, gp70. FeLV p15(E) was sensitive to digestion of intact virus particles with the proteolytic enzyme, bromelain, indicating that this protein is on the outer surface of the virion. An analysis of cat sera for precipitating activity for FeLV p12(E) showed this only in sera from cats which had recovered from FeLV infection and had virus-neutralizing activity.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-50-2-455", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6254637", "author": "Lutz H", "n_authors": 6, "title": "Humoral immune reactivity to feline leukemia virus and associated antigens in cats naturally infected with feline leukemia virus.", "abstract": null, "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6254060", "author": "Barbacid M", "n_authors": 3, "title": "Origin and functional properties of the major gene product of the Snyder-Theilen strain of feline sarcoma virus.", "abstract": "The only known product of the Snyder-Theilen strain of feline sarcoma virus (ST-FeSV) is a 85,000-dalton protein, designated ST P85, that contains feline leukemia virus gag gene encoded proteins (p15, p12, and a fragment of p30) and a sarcoma virus-specific polypeptide. Antibodies directed against the latter immunoprecipitated a 92,000-dalton phosphoprotein (NCP 92) expressed at low levels in normal feline embryo fibroblasts as well as in feline cells of epithelial or lymphoid origin. Normal cellular proteins crossreactive with ST P85 were also detected in cell lines from various other mammalian species. These results suggest that the ST-FeSV sequences encoding for the sarcoma virus-specific domain of ST P85 originated from an evolutionarily conserved cellular gene expressed in cells of independent differentiation lineage. Immunoprecipitates containing ST-FeSV P85 exhibited a protein kinase activity that specifically phosphorylated tyrosine residues. The physiological significance of this finding is illustrated by the finding that phosphotyrosine is an intrinsic component of ST P85. Furthermore, 5- to-fold higher levels of this unusual phosphorylated amino acid were present in ST-FeSV transformants than in uninfected control cells. Phosphorylation of tyrosine residues appears to be associated with cellular transformation caused by Rous sarcoma virus and Abelson murine leukemia virus. Thus, independent transforming virus isolates from birds, mice, and cats may utilize common pathways in exerting their oncogenic potential.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.77.9.5158", "deposited_data": "Sim", "nuccore_ids": "1907177353, 1907177352, 1720420852, 111185913", "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6250976", "author": "Milo GE", "n_authors": 4, "title": "Feline sarcoma virus induced in vitro progression from premalignant to neoplastic transformation of human diploid cells.", "abstract": "Human diploid cells morphologically transformed by feline sarcoma virus were serially propagated under selective cell culture conditions. When injected into nude mice prior to passage in soft agar (0.35%), morphologically transformed cells did not produce tumors. However, when propagated under selective cell culture conditions, transformed cells grew in soft agar and, when injected subcutaneously into the subcapsular region of the n mu/n mu mice, produced neoplastic nodules histopathologically interpreted as fibromas. Karyological examination of cell populations grown out from the tumors confirmed that the tumors were composed of human cells. Examination of electron micrographs of the excised tumor tissue revealed the presence of budding virus particles. Tumor cells isolated from nude mice and morphologically transformed cells both contained the feline oncornavirus-associatied cell membrane antigen. It was concluded that expression of feline oncornavirus-associated cell membrane antigen is associated with an early stage of feline retrovirus-induced carcinogenesis, namely focus formation. In addition, it was shown that FeLV-FeSV can induce morphological transformation in human cells in vitro and that there is a requirement for the cells to passage through soft agar before subsequent tumor formation (neoplastic transformation) can be demonstrated.", "journal": "In vitro", "doi": "10.1007/BF02619317", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6159069", "author": "Rho HM", "n_authors": 2, "title": "Biochemical and immunological properties of the DNA polymerase and RNAase H activities of purified feline leukemia virus reverse transcriptase.", "abstract": "Feline leukemia virus DNA polymerase was purified by ion-exchange and nucleic acid affinity chromatographies. The enzyme consists of a single polypeptide chain of mol. wt. approx. 72,000 as determined by both glycerol density gradient centrifugation and SDS-polyacrylamide gel electrophoresis. The preferred divalent cation for DNA synthesis is Mn2+ on a variety of template-primers, and its optimum concentration appears to be significantly lower than reported results of other mammalian type-C viral enzymes. The purified enzyme also contained RNAase H activity. Both DNA polymerase and RNAase H activities appear to reside on the same molecule as demonstrated by the copurification of both activities through various purification steps. The divalent cation requirement for maximum activity of RNAase H is also similar to that of the DNA polymerase. RNAase H without detectable polymerase activity was generated by a limited chymotrypsin digestion of the purified reverse transcriptase. This RNAase H activity was inhibited equally effectively as RNAase H in the intact reverse transcriptase by antisera prepared against reverse transcriptase of feline leukemia virus. These results indicate that the RNAase H catalytic activity of reverse transcriptase is distinct from the polymerase portion of the molecule. Since the RNAase H activity appears to be more stable, the measurement of RNAase H activity with a proper antibody might be useful for assaying tumor cells for the presence of the viral enzyme.", "journal": "Cancer letters", "doi": "10.1016/0304-3835(80)90073-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6249487", "author": "Jones FR", "n_authors": 4, "title": "Treatment of feline leukemia and reversal of FeLV by ex vivo removal of IgG: a preliminary report.", "abstract": "Cats that were spontaneously infected with feline leukemia virus (FeLv) were treated with a combination of low-dose irradiation and extracorporeal immunosorption using formalin and heat-fixed S. aureus as a non-specific immunosorbent to remove plasma IgG and immune complexes. The treatment resulted in reduction of circulating lymphoblasts within two weeks and clinical improvement of three of the five animals. A reversal of the FeLV status is reported in five of five cats. Two of the five cats remain FeLV negative and completely tumor free seven and eight months post-therapy at the time of writing (July 1979). A third cat returned to an FeLV positive state but remained tumor free for 24 weeks. Another cat responded to the therapy by reduction of lymphoblasts and became FeLV negative but died of a hemorrhage during an immunosorption. The last cat's status was FeLV positive, then FeLV negative, and finally FeLV positive again. He died 20 weeks after initiation of therapy. During the treatment there was a weight gain in the three cats responding by tumor regression. The results are discussed in terms of a removal of some type of immunoinhibiting factors such as antigen-antibody complexes or suppressor molecules.", "journal": "Cancer", "doi": "10.1002/1097-0142(19800815)46:4<675::aid-cncr2820460408>3.0.co;2-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6255412", "author": "Mullins JI", "n_authors": 4, "title": "Sequence organization of feline leukemia virus DNA in infected cells.", "abstract": "A restriction site map has been deduced of unintegrated and integrated FeLV viral DNA found in human RD cells after experimental infection with the Gardner-Arnstein strain of FeLV. Restriction fragments were ordered by single and double enzyme digests followed by Southern transfer (1) and hybridization with 32P-labeled viral cDNA probes. The restriction map was oriented with respect to the 5' and 3' ends of viral RNA by using a 3' specific hybridization probe. The major form of unintegrated viral DNA found was a 8.7 kb linear DNA molecule bearing a 450 bp direct long terminal redundancy (LTR) derived from both 5' and 3' viral RNA sequences. Minor, circular forms, 8.7 kb and 8.2 kb in length were also detected, the larger one probably containing two adjacent copies of the LTR and the smaller one containing one comtaining one copy of the LTR. Integrated copies of FeLV are colinear with the unintegrated linear form and contain the KpnI and SmaI sites found in each LTR.", "journal": "Nucleic acids research", "doi": "10.1093/nar/8.15.3287", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6255191", "author": "Rosenberg ZF", "n_authors": 3, "title": "Comparative analysis of the genomes of feline leukemia viruses.", "abstract": "The genomes of several strains of feline leukemia virus (FeLV) were compared by two-dimensional polyacrylamide gel electrophoresis of the large RNase T1-resistant oligonucleotides of the 70S RNA. Differences between each strain of FeLV tested were detected by this method. We estimate that the degree of sequence identity between the viruses is: FeLV A (Glasgow-1) to FeLV B (Snyder-Theilen), 52%; FeLV A (Glasgow-1) to FeLV C(Sarma), 66%; FeLV B(Snyder-Theilen) to FeLV C (Sarma), 37%. The fingerprints of two independent isolates of FeLV strains of subgroup A (Glasgow-1 and Rickard) were detectably different. We conclude that the RNase T1 oligonucleotide fingerprint pattern provides a useful tool for identification of FeLV strains.", "journal": "Journal of virology", "doi": "10.1128/JVI.35.2.542-546.1980", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6251608", "author": "Neil JC", "n_authors": 4, "title": "Polypeptides of feline leukemia virus: a glycosylated gag-related protein is released into culture fluids.", "abstract": null, "journal": "Virology", "doi": "10.1016/0042-6822(80)90173-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6250064", "author": "Reynolds FH Jr", "n_authors": 3, "title": "Feline sarcoma virus polyprotein P115 binds a host phosphoprotein in transformed cells.", "abstract": "Several independent isoltes of feline sarcoma virus (FeSV) have been described. Such viruses are apparently derived by genetic recombination between feline leukaemia virus (FeLV) genomic RNA and host cellular genetic sequences with transforming potential. Two FeSV isolates, one originally described by Gardner and the second by Snyder-Theilen, have been shown to encode polyproteins of around 115,000 molecular weight. Both polyproteins contain FeLV structural components (p15, p12) at their amino terminus in addition to nonstructural carboxyl terminal components encoded by acquired sequences within the FeSV genome. We have previously shown that Gardner FeSV P115 contains multiple sites of phosphorylation within its nonstructural component and possesses an associated protein kinase activity. In the present study we describe the expression in cells derived from a number of mammalian species, of a highly conserved celklular phosphoprotein with binding affinity for Gardner FeSV P115. This protein, designated P150, exhibits an associated protein kinase activity and is immunologically and structurally distinct from polyproteins encoded by the Gardner or Snyder-Theilen strains of FeSV.", "journal": "Nature", "doi": "10.1038/286409a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6251274", "author": "Ruscetti SK", "n_authors": 3, "title": "Three independent isolates of feline sarcoma virus code for three distinct gag-x polyproteins.", "abstract": "Cells nonproductively transformed by the Snyder-Theilen, Gardner-Arnstein, and McDonough strains of feline sarcoma virus synthesize gag-x polyproteins of 78,000, 100,000, and 180,000 daltons, respectively. These feline sarcoma virus-coded products were precipitated by antisera to polypeptides encoded by the gag gene of feline leukemia virus and by rat antisera raised to feline sarcoma virus-transformed rat tumor cells. Precipitation with rat antisera absorbed with feline leukemia virus showed that the x-portions of the three gag-x proteins were each antigenically distinct, suggesting that the src genes of the three independent isolates are not identical. Anti-x sera did not precipitate products from radiolabeled cat lymphoid tumor cells (FL74) and therefore lacked reactivity to the feline leukemia virus-induced tumor-specific antigen, FOCMA.", "journal": "Journal of virology", "doi": "10.1128/JVI.35.1.259-264.1980", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6251265", "author": "Van de Ven WJ", "n_authors": 4, "title": "Characterization of a 170,000-dalton polyprotein encoded by the McDonough strain of feline sarcoma virus.", "abstract": "In this study, we demonstrated the expression of a 170,000-Mr polyprotein in each of several McDonough feline sarcoma virus (FeSV)-transformed mink cell clones and one McDonough FeSV-transformed rat clone. This polyprotein designated McDonough FeSV P170, contained feline leukemia virus (FeLV) p15, p12, and p30 immunological determinants and shared two of its five [35S]methionine-labeled tryptic peptides with FeLV Pr180gag-pol. Both of these peptides were shown to be specific to the p30 component of Pr180gag-pol. The remaining McDonough FeSV P170 methionine-containing peptides were not represented within either FeLV Pr180gag-pol or Pr82env. Of interest, of the three peptides specific to the nonstructural component of McDonough FeSV P170, one was also represented in the 115,000-Mr polyproteins encoded by the Gardner and Snyder-Theilen strains of FeSV. These findings raise the possibility that the nonstructural components of polyproteins encoded by each of the three independently derived feline transforming viruses contained both common and unique regions. Moreover, if the sequences encoding these components are involved in transformation, as appears to be the case, our findings establish that the position of their insertion within the gag-pol region of the FeLV genome can vary among individual isolates.", "journal": "Journal of virology", "doi": "10.1128/JVI.35.1.165-175.1980", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6249754", "author": "Kobilinsky L", "n_authors": 5, "title": "In vitro activation of feline complement by feline leukemia virus.", "abstract": "Incubation of normal feline serum with purified feline leukemia virus (FeLV) at 37 degrees C for 30 min resulted in the activation of the complement system via the classical pathway as demonstrated by consumption of the C1, C4, C2, C3, and, to a lesser extent, the later C components. A similar finding was observed when normal human serum was substituted for normal cat serum. In contrast, complement-dependent lysis of FeLV with normal feline serum as assayed by the release of ribonucleic acid-dependent deoxyribonucleic acid polymerase was one-third that of complement-dependent FeLV lysis with normal human serum. The levels of total hemolytic complement and neutralizing antibody in individual feline sera were also not proportional to the degree of virolytic activity. These observations indicate that the inefficient virolysis of FeLV by normal cat serum may be one of the factors contributing to the high incidence of leukemia observed in cats.", "journal": "Infection and immunity", "doi": "10.1128/iai.29.1.165-170.1980", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6248115", "author": "Waters LC", "n_authors": 4, "title": "Differential association of transfer RNAs with the genomes of murine, feline and primate retroviruses.", "abstract": "The tRNAs that are bound to the genomic RNAs of several murine, feline, and primate retroviruses have been identified. Transfer RNAs were divided into those loosely bound and those tightly bound by stepwise thermal dissociation of the 70 S RNA. They were then identified and semiquantitated by aminoacylation. Proline tRNA is the most tenaciously bound tRNA in several strains of murine leukemia virus, two strains of feline leukemia virus, and the primate viruses simian sarcoma, baboon endogenous, and gibbon ape lymphoma. In the feline xenotropic virus, RD-114, tRNAGly is enriched in the most tightly bound fraction. In Mason-Pfizer monkey virus, as in the murine mammary tumor virus, tRNALys is the tRNA most tenaciously bound to its genomic RNA. Besides the most tightly associated tRNA, one or more different tRNAs are found in relatively large amounts in association with the 70 S RNA. (For convenience, we refer to the largest RNA ccomplex (50-70 S) isolated from any of the retroviruses studies as '70 S' RNA.) These tRNAs can be distinguished from the most tightly bound tRNA by the fact that they can be dissociated at lower temperatures. However, they occur in the same relative abundance as the tightly bound tRNA.", "journal": "Biochimica et biophysica acta", "doi": "10.1016/0005-2787(80)90139-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6254235", "author": "Jarrett O", "n_authors": 1, "title": "Feline leukaemia virus diagnosis.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.106.24.513-a", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6247824", "author": "Koshy R", "n_authors": 3, "title": "Characterization of the endogenous feline leukemia virus-related DNA sequences in cats and attempts to identify exogenous viral sequences in tissues of virus-negative leukemic animals.", "abstract": null, "journal": "Virology", "doi": "10.1016/0042-6822(80)90202-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6246303", "author": "Grant CK", "n_authors": 6, "title": "Protection of cats against feline leukemia virus-positive and virus-negative tumors by complement-dependent antibody.", "abstract": null, "journal": "Journal of the National Cancer Institute", "doi": "10.1093/jnci/64.6.1527", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6250422", "author": "Pedersen NC", "n_authors": 3, "title": "Feline chronic progressive polyarthritis.", "abstract": "Twenty cats with a chronic progressive polyarthritis were studied. The disorder occurred exclusively in male cats, and all but six of the cats were between 1.5 and 5.0 years of age. There were two forms of the disease as determined by radiographic changes: joint instability and deformity, and clinical course. The most prevalent form of the disease was characterized by osteopenia and periosteal new bone formation surrounding affected joints. Marginal periarticular erosions and collapse of the joint spaces with fibrous ankylosis occurred with time, but joint instability and deformities were not seen. The second form of the disease was characterized by severe subchondral marginal erosions, joint instability, and deformities. The periosteal proliferative form resembled Reiter's arthritis of man, and the deforming type resembled human rheumatoid arthritis. The disease began as tenosynovitis and synovitis, with subsequent changes in the articular cartilage and periosteal bone. Histopathologic changes in these cats were similar to those occurring in both chronic Reiter's and rheumatoid arthritis of man. Chronic progressive polyarthritis of cats was not caused by identifiable bacteria or mycoplasma, but was etiologically linked to feline leukemia virus (FeLV) and feline syncytia-forming virus (FeSFV) infections. The FeSFV was isolated from the blood or was detected by a serologic test in all of the cats with the disease, whereas FeLV was isolated or identified by immunofluorescence technique in 60% of the cats. The arthritis could not be reproduced by inoculation of cell-free cynovial tissue from diseased cats or with tissue culture fluid containing FeSFV and FeLV isolates. It was postulated that arthritis was an uncommon manifestation of FeSFV infection that occurred in predisposed male cats. Feline leukemia virus may not have been directly involved in the disease, but may have acted in some way to potentiate the pathogenic effects of FeSFV.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6246254", "author": "Sherr CJ", "n_authors": 5, "title": "Molecular cloning of Snyder-Theilen feline leukemia and sarcoma viruses: comparative studies of feline sarcoma virus with its natural helper virus and with Moloney murine sarcoma virus.", "abstract": "Extrachromosomal DNA obtained from mink cells acutely infected with the Snyder-Theilen (ST) strain of feline sarcoma virus (feline leukemia virus) [FeSV(FeLV)] was fractionated electrophoretically, and samples enriched for FeLV and FeSV linear intermediates were digested with EcoRI and cloned in lambda phage. Hybrid phages were isolated containing either FeSV or FeLV DNA \"inserts\" and were characterized by restriction enzyme analysis, R-looping with purified 26 to 32S viral RNA, and heteroduplex formation. The recombinant phages (designated lambda FeSV and lambda FeLV) contain all of the genetic information represented in FeSV and FeLV RNA genomes but lack one extended terminally redundant sequence of 750 bases which appears once at each end of parental linear DNA intermediates. Restriction enzyme and heteroduplex analyses confirmed that sequences unique to FeSV (src sequences) are located at the center of the FeSV genome and are approximately 1.5 kilobase pairs in length. With respect to the 5'-3' orientation of genes in viral RNA, the order of genes in the FeSV genome is 5'-gag-src-env-c region-3'; only 0.9 kilobase pairs of gag and 0.6 kilobase pairs of env-derived FeLV sequences are represented in ST FeSV. Heteroduplex analyses between lambda FeSV or lambda FeLV DNA and Moloney murine sarcoma virus DNA (strain m1) were performed under conditions of reduced stringency to demonstrate limited regions of base pair homology. Two such regions were identified: the first occurs at the extreme 5' end of the leukemia and both sarcoma viral genomes, whereas the second corresponds to a 5' segment of leukemia virus \"env\" sequences conserved in both sarcoma viruses. The latter sequences are localized at the 3' end of FeSV src and at the 5' end of murine sarcoma virus src and could possibly correspond to regions of helper virus genomes that are required for retroviral transforming functions.", "journal": "Journal of virology", "doi": "10.1128/JVI.34.1.200-212.1980", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6258787", "author": "Grant CK", "n_authors": 4, "title": "Natural feline leukemia virus infection and the immune response of cats of different ages.", "abstract": "Forty-two kittens and 28 adult cats were placed as tracers in leukemia cluster environments in contact with resident cats, 30% of which were persistently infected with feline leukemia virus (FeLV). After 7 months exposure, FeLV viremia had been detected in 71% of the tracer kittens, although only 55% of these remained persistently infected; in the same period, 11% of tracer adults became infected, but by 2 years the figure reached 43%. Mean latent periods before detection of viremia were 3.4 +/- 1.8 (S.D.) and 13.0 +/- 5.9 months for kittens and adults, respectively. First detection of FeLV infection was accompanied by a sharp although transient drop in peripheral white blood cell numbers, and infection onset triggered the humoral immune response which was comprised of separate antibodies with virus-neutralizing and tumor lysis activities. High titers of virus-neutralizing antibody appeared in transiently viremic cats immediately following elimination of viremia; this antibody was rarely detected in cats that remained persistently viremic. Lytic complement-dependent antibody to feline oncornavirus-associated cell membrane antigen appeared in most cats 1 to 2 weeks after FeLV infection was first detected, and subsequently high titers of this antibody remained in both transiently and persistently infected cats. If the rate of FeLV infection was summarized by using viremia and/or antibody appearance, then 95% of the kittens became infected within 1 year and 61% of the adults within 2 years. Adult cats are, therefore, susceptible to FeLV infection following long-term natural exposure, and their apparent resistance cannot be attributed to a protective humoral immune response that developed immediately after exposure commenced.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6245259", "author": "Van de Ven WJ", "n_authors": 5, "title": "Translational products encoded by newly acquired sequences of independently derived feline sarcoma virus isolates are structurally related.", "abstract": "Polyproteins encoded by several independent isolates of feline sarcoma virus (FeSV) were analyzed with respect to molecular weight, extent of phosphorylation, and tryptic peptide composition. As previously reported, cells nonproductively transformed by the Gardner strain of FeSV express a polyprotein which has a molecular weight of approximately 115,000 and contains feline leukemia virus p15, p12, and minor portion of p30. In addition, a major 72,000-dalton possible cleavage product can be identified. Snyder-Theilen FeSV-transformed cells express a major polyprotein of approximately 115,000 daltons and a second highly related 80,000-dalton protein. The p12 structural component of Gardner FeSV P115, but not Snyder-Theilen FeSV 115, corresponds to feline leukemia virus subgroup A with respect to immunological type specificity, a finding consistent with the independent origin of these viruses. Tryptic peptide analysis revealed five methionine-containing peptides specific to the nonstructural portion of Gardner FeSV 115, three of which were also represented in Snyder-Theilen FeSV P115, three of which were also represented in Snyder-Theilen FeSV P115. None of these [35S]methionine-labeled tryptic peptides were present in translational products representative of the complete feline leukemia virus subgroup A genome, including Pr180gag-pol, Pr65gag, and Pr82env. Similarly phosphorylated tryptic peptides within the structural (p12) and nonstructural components of Gardner FeSV P115 and Snyder-Theilen FeSV P115 Are highly related. These findings support the possibility that acquired sequences of two independently derived isolates of FeSV encode structurally related proteins.", "journal": "Journal of virology", "doi": "10.1128/JVI.33.3.1034-1045.1980", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6244730", "author": "Francis DP", "n_authors": 6, "title": "Increased risk for lymphoma and glomerulonephritis in a closed population of cats exposed to feline leukemia virus.", "abstract": "Feline leukemia virus (FeLV)-associated diseases were observed in a household in eastern Connecticut having 134 cats over a period of five and a half years. FeLV-positive cats had a much higher mortality rate (34.6 deaths per 1000 cat-months of follow-up) than did FeLV-negative cats (8.9 deaths per 1000 cat-months of follow-up). The leading cause of death was glomerulonephritis followed by lymphoma. The relative risk for virus-positive cats as compared to virus-negative cats for the two diseases was 9.9 and 9.6, respectively. The major risk factors for the development of lymphoma were virus positivity and low antibody titer to the feline oncornavirus-associated cell membrane antigen (FOCMA). No significant differences in cancer incidence were seen between the two major breeds (Abyssinian and Burmese) in the household. An older age at arrival in the house decreased death rates for all causes in the household, but it did not significantly affect death rates from lymphoma, although there was a positive trend.", "journal": "American journal of epidemiology", "doi": "10.1093/oxfordjournals.aje.a112905", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6154154", "author": "Versteegen RJ", "n_authors": 2, "title": "Effect of chemical modification and fragmentation on antigenic determinants of internal protein p30 and surface glycoprotein gp70 of type C retroviruses.", "abstract": "The effects of protein modification on the antigenic determinants of p30 and gp70 of type C retroviruses were investigated by using solid-phase competition radioimmunoassays. Proteins were modified by reduction with 2-mercaptoethanol and subsequent carboxymethylation of SH groups with iodoacetamide or by amidination of alpha and epsilon amino groups with methylacetimidate. The type-specific determinants of gp70 were found to be conformational in nature, as they were destroyed by these chemical modifications. Group- and interspecies-specific determinants of gp70 antigens, however, appear to be sequential and do not involve residues susceptible to these chemical reagents. Conformation-dependent type-specific determinants of p30 were affected only by methylacetimidate. Group- and interspecies-specific determinants of p30 are similar to those of gp70 in that they also appear to be sequential antigenic sites. Therefore, the broadly reactive group- and interspecies-specific determinants of gp70 and p30 can be followed into small peptides. Accordingly, a cyanogen bromide cleavage fragment derived from the carboxyl-terminal one-third of Rauscher leukemia virus p30 was found to carry group-specific determinants but no detectable interspecies-specific determinants. In contrast, a peptide obtained by limited trypsin cleavage of p30, which was derived from the NH(2)-terminal region of the protein, contained at least one of the interspecies determinants shared with feline leukemia virus p27.", "journal": "Journal of virology", "doi": "10.1128/JVI.33.3.983-992.1980", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6252115", "author": "Cohen D", "n_authors": 2, "title": "Feline leukemia in Israel: prevalence of antibody to feline oncornavirus-associated cell membrane antigen in stray cats.", "abstract": "Feline lymphoma was recorded for the first time in pet cats in Israel. Furthermore, a serological survey in urban stray cats was carried out to determine the prevalence of antibody to feline oncornavirus-associated cell membrane antigen (FOCMA). A total of 91 cats was tested and only 5 has antibody to FOCMA. Of these 5 positive cats, 4 originated from an area where a feline leukemia virus-positive cat had been detected prior to the survey. The prevalence of stray cats with antibody to FOCMA is lower in Israel than found in similar studies in the USA and Scotland.", "journal": "Intervirology", "doi": "10.1159/000149144", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6247186", "author": "Pack FD", "n_authors": 2, "title": "Light and electron microscopic evaluation of thymuses from feline leukemia virus-infected kittens.", "abstract": "Light microscopic and electron microscopic findings in thymuses from 4-week old feline leukemia virus-infected and 4- and 9-week old noninfected kittens were evaluated and found to be morphologically similar to each other. Thymuses from 9-week old feline leukemia virusinfected kittens were markedly atrophied and individual lobules within each thymus varied in the severity of atrophy. Loubules having the least severe atrophy had a moderate thinning of the cortex and a heterogeneous thymuses included intense eosinopoiesis at the corticomedullary junction, increased prominence of vasculature, and enlarged Hassal's corpuscles. In addition to these changes lobules of thymus having the most severe atrophy had a marked cortical thymocyte depletion, lobule collapse, and increased numbers of mast cells. Degeneration of epithelial cells in most lobules was indicated by electronlucency of the cytoplasmic matrix and often greatly dilated rough endoplasmic reticulum.", "journal": "Experimentelle Pathologie", "doi": "10.1016/s0014-4908(80)80058-5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6244200", "author": "Schneider J", "n_authors": 3, "title": "Search for mammalian type-C retrovirus polypeptides on infected animal cells and human tumor cell lines using interspecies-reacting antibodies.", "abstract": "Cells producing endogenous and exogenous type-C retroviruses of murine, feline and primate origin were evaluated for expression of those virus-specific cell-surface antigens which cross-react with antibodies to interspecies determinants of mammalian type-C viral polypeptides. Surface polypeptides of cells replicating endogenous and exogenous type-C retroviruses were iodinated by the lactoperoxidase method. Labelled antigens were immunoprecipitated and analyzed in polyacrylamide gel electrophoresis in the presence of sodium dodecyl sulfate. This method detected gp71 and less frequently p15E/p12E on the surface of virus-producing cells; in addition, p27 was found on F422 cells replicating feline leukemia virus. Antibodies to the membrane protein p15E displayed the broadest cross-reactivity but only antibodies to gp71 mediated complement-dependent interspecies cell lysis. The pattern of cross-reactivity reflected known genetic relationships among these mammalian viruses. Although antiserum to the simian sarcoma virus complex (SSV) was strongly cytotoxic to some human tumor cell lines, this reactivity could not be attributed to antibodies cross-reacting with SSV gp71.", "journal": "Experimental cell biology", "doi": "10.1159/000162979", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6154148", "author": "Barbacid M", "n_authors": 3, "title": "Biochemical and immunological characterization of polyproteins coded for by the McDonough, Gardner-Arnstein, and Snyder-Theilen strains of feline sarcoma virus.", "abstract": "The McDonough (SM), Gardner-Arnstein (GA), and Snyder-Theilen (ST) strains of feline sarcoma virus (FeSV) code for high-molecular-weight polyproteins that contain varying amounts of the amino-terminal region of the FeLV gag gene-coded precursor protein and a polypeptide(s) of an as yet undetermined nature. The SM-FeSV primary translational product is a 180,000-dalton polyprotein which is immediately processed into a highly unstable 60,000-dalton molecule containing the p15-p12-p30 fragment of the FeLV gag gene-coded precursor protein and a 120,000-dalton FeSV-specific polypeptide. The GA- and ST-FeSV genomes code for polyproteins of 95,000 and 85,000 daltons, respectively, which in addition to the amino-terminal moiety (p15-12 and a portion of p30) of the FeLV gag gene-coded precursor protein also contain FeSV-specific polypeptides. However, the GA- and ST-FeSV polyproteins appear to be relatively stable molecules (half-lives of around 16 h) and are not significantly processed into smaller polypeptides. Immunological and biochemical analysis of each of the above FeSV translational products revealed that the sarcoma-specific regions of the GA- and ST-FeSV polyproteins are antigenically cross-reactive and exhibit common methionine-containing peptides. These findings favor the concept that these sarcoma-specific polypeptides are coded for by the similar subsets of cellular sequences incorporated into the GA- and ST-FeSV genomes during the generation of these transforming agents.", "journal": "Journal of virology", "doi": "10.1128/JVI.33.1.196-207.1980", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6109397", "author": "Torres J Jr", "n_authors": 4, "title": "Cell cycle kinetics of uninfected and feline leukemia virus-infected canine lymphoma cell lines: effects of methotrexate treatment.", "abstract": "The cell cycle kinetics of uninfected and feline leukemia virus-infected canine lymphoma cell lines were determined by autoradiography (PLM method) as follows: DT-5: generation time (TC), 15.2 h; pre-synthetic gap phase (TG1), 3.2 h; DNA-synthetic phase (TS), 8.2 h; post-synthetic gap ph se (TG2), 3.3 h; visible mitotic phase (TM), 0.5 h. 11028: TC, 13.6 h; TG1, 1.9 h; TS, 7.7 h; TG2, 3.4 h; TM, 0.6 h. 11028+FeLV (11028 productively infected with feline leukemia virus): TC, 11.2 h; TG1, 0.2 h; TS, 8.3 h; TG2, 2.1 h; TM, 0.6 h. Exposure of the lymphoma cell lines to methotrexate (MTX) in vitro produces dose-related increases in cellular volume, associated with reductions in cellular proliferation. The relative sensitivities of these cell lines to MTX, measured by the ID50 MTX concentrations for DT-5, 11028, and 11028+FeLV are 118 nM, 122 nM, and 28 nM respectively. The cell kinetic effects of the ID50 MTX concentrations added to cultures of lymphoma cells pulse-labeled with tritiated thymidine are an approximately 2-h prolongation of TC, attributable to a lengthening of TS, with other cell cycle phases not significantly altered. These cell lines are highly tumorigenic when transplanted into the cheek pouches of immunosuppressed hamsters, with inocula of 10(4) cells producing rapidly growing, well vascularized tumors.", "journal": "Virchows Archiv. B, Cell pathology including molecular pathology", "doi": "10.1007/BF02899177", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6283220", "author": "Ishida T", "n_authors": 3, "title": "Detection of feline leukemia virus infection in Tokyo area by enzyme-linked immunosorbent assay (ELISA).", "abstract": null, "journal": "Nihon juigaku zasshi. The Japanese journal of veterinary science", "doi": "10.1292/jvms1939.43.871", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6278488", "author": "Casey JW", "n_authors": 7, "title": "The U3 portion of feline leukemia virus DNA identifies horizontally acquired proviruses in leukemic cats.", "abstract": "The presence and location of DNA sequences related to the U3 and U5 portions of the infectious exogenous feline leukemia virus (FeLV) long terminal repeat (LTR) in various cat DNAs have been determined by hybridization experiments. In uninfected cat DNAs, the U5 LTR segment from the Gardner-Arnstein strain B virus is present at approximately 150 copies per cell. This level is approximately 10-fold greater than that of endogenous internal FeLV sequences. The U5 sequences differ in copy number and, to some extent, in location from one animal to another. For any one animal, the sequence organization of the U5 segments is the same among different tissues, showing that the pattern is inherited through the germ line. Most importantly, the viral U3 LTR probe hybridizes only very weakly with uninfected cat DNAs. Both the U3 and the U5 regions of the LTR from the Gardner-Arnstein strain of virus cross-hybridize with DNA derived from four other infectious FeLVs representing A, B, and C subtypes. Thus, the C3 region may be used as a probe for studying the number and location of exogenously acquired FeLV proviruses in infected cat tissues. In some cases exogenously acquired proviruses are present in unique sites in the genome of virus-positive cat lymphosarcomas, indicating a monoclonal origin for the tumor. In other tumors, the proviral sequences are randomly distributed over many sites. Lymphosarcomas of virus-negative cats have no exogenous U3 sequences despite epidemiological evidence of an association of virus-negative leukemia with exposure to FeLV.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.78.12.7778", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6277792", "author": "Lewis MG", "n_authors": 3, "title": "Protection against feline leukemia by vaccination with a subunit vaccine.", "abstract": "An effective vaccine against feline leukemia virus infection has been developed by the collection and concentration of tissue culture medium harvested from a tumor cell line. Lymphoid cells were grown to near saturation density in a normal growth medium and then transferred to a serum-free medium. The serum-free medium was collected, concentrated, and evaluated for its vaccine potential. Cats receiving the vaccine emulsified in complete Freund adjuvant developed high antiviral and antitumor titers and were protected (81%) against virus challenge. Cats receiving the vaccine without an adjuvant developed lower antibody levels and lower protection (53%) from viremia. Age-matched and litter-matched controls developed no antibody to test antigens before the challenge, and 100% became persistently viremic after the challenge. Vaccination with the soluble tumor cell antigen vaccine proved successful in preventing the induction of feline leukemia virus infection.", "journal": "Infection and immunity", "doi": "10.1128/iai.34.3.888-894.1981", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6276347", "author": "Ladiges WC", "n_authors": 4, "title": "Prevalence and sequelae of feline leukemia virus infection in laboratory cats.", "abstract": "Over a 4-year period, 1,683 pound-source cats received at a research institution were screened for feline leukemia virus (FeLV) infection, using an indirect fluorescent antibody test. Viremia was detected in 83 of the cats, for a prevalence of 4.9%. During this period, FeLV infection was detected in 5 kittens on a research project; lymphoma or anemia developed 6 to 17 months after the infections were detected. It was concluded that apparently healthy cats infected with FeLV may not be appropriate for some biomedical research projects.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6275118", "author": "Barbacid M", "n_authors": 2, "title": "Gene products of McDonough feline sarcoma virus have an in vitro-associated protein kinase that phosphorylates tyrosine residues: lack of detection of this enzymatic activity in vivo.", "abstract": "The primary translational product of the McDonough (SM) strain of feline sarcoma virus (FeSV) is a 180,000-dalton molecule, SM P180, that contains the p15-p12-p30 region of the FeLV gag gene-coded precursor protein and a sarcoma virus-specific polypeptide. In addition, cells transformed by SM-FeSV express a 120,000-dalton molecule, SM P120, that is highly related to the non-helper virus domain of SM P180. Both SM-FeSV gene products were found to be intimately associated with the membrane fraction of SM-FeSV-transformed cells. Immunoprecipitates containing SM P180 and SM P120 exhibited a protein kinase activity capable of phosphorylating tyrosine residues of both viral gene products but not immune immunoglobulin G molecules. By independently immunoprecipitating each of the two SM-FeSV proteins we found that most of the tyrosine-specific phosphorylating activity was associated with the SM P120 molecule. In vivo analysis of 32P-labeled SM P180 and SM P120 revealed their phosphoprotein nature; however, both molecules exhibited low levels of phosphorylation and did not contain phosphotyrosine residues. Finally, we did not detect any significant elevation in the levels of phosphotyrosine in the protein fraction of SM-FeSV transformants. Thus, if SM-FeSV were to induce malignant transformation by a mechanism involving phosphorylation of tyrosine residues, the viral gene products must interact with a small subset of cellular proteins that do not represent a significant fraction of the total cellular protein content.", "journal": "Journal of virology", "doi": "10.1128/JVI.40.3.812-821.1981", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6273200", "author": "Boyce JT", "n_authors": 4, "title": "Feline leukemia virus-induced erythroid aplasia: in vitro hemopoietic culture studies.", "abstract": "Colony forming unit (CFU) assays were developed for feline granulocyte-macrophage (CFUGM), early erythroid (day 2 CFUE), and late erythroid (day 7 CFUE) colonies in methylcellulose medium. Feline CFUGM and both day 2 and day 7 CFUE were enhanced by feline macrophage conditioned medium and late CFUE often were intimately associated with macrophages. Kittens were inoculated with the Kawakami-Theilen (KT) strain of feline leukemia virus (FeLV) and sequential changes in marrow CFU determined. Erythroid aplasia, characterized by progressive non-regenerative anemia, lymphopenia, and a profound decrease in early and late CFUE but not CFUGM was induced by 3 to 5 weeks after FeLV-KT inoculation. The susceptibility of kittens to FeVL-induced erythroid aplasia was strongly age-related; neonatal kittens were most sensitive and substantial natural resistance developed by 4 weeks of age. The results demonstrate that FeLV-KT infection induced a rapid and selective suppression of erythroid progenitor cells and represents a suitable model of experimentally-induced acquired erythroid aplasia.", "journal": "Experimental hematology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6272982", "author": "Toth SR", "n_authors": 1, "title": "Cell cycle-related morphological changes of feline lymphoid cells as revealed by electron microscopy.", "abstract": "The aim of this study was to correlate morphological changes in cells to known phases of the cell cycle. For this purpose, feline lymphoblastoid cells (FL74) chronically infected with feline leukemia virus were synchronized and examined by scanning and transmission electron microscopy. Scanning electron microscopy revealed that the cell surface underwent distinct changes which were found to be cell cycle specific. Morphological changes shown by transmission electron microscopy were used as ultrastructural markers to confirm the findings made by scanning electron microscopy relating to the various phases of the cell cycle. The results of these experiments suggest that the presence of morphologically mixed populations of cells in many lymphoproliferative disorders, which had been described previously, may be explained by normal cell cycle-dependent variations.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6278376", "author": "Jones BR", "n_authors": 2, "title": "Feline leukaemia virus testing.", "abstract": null, "journal": "New Zealand veterinary journal", "doi": "10.1080/00480169.1981.34842", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6268887", "author": "Rasheed S", "n_authors": 2, "title": "Isolation of feline leukemia virus from a leopard cat cell line and search for retrovirus in wild felidae.", "abstract": "A strain of feline leukemia virus (FeLV), subgroup A, was isolated in early subpassage of a testicular fibroblast culture obtained from a captive Asian leopard cat. Neither FeLV nor RD-114 virus was recovered from cultured tissues of 15 other animals, representing eight species of wild Felidae.", "journal": "Journal of the National Cancer Institute", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6268886", "author": "Rojko JL", "n_authors": 4, "title": "Determinants of susceptibility and resistance to feline leukemia virus infection. II. Susceptibility of feline lymphocytes to productive feline leukemia virus infection.", "abstract": "The interplay between feline leukemia virus (FeLV) and feline lymphocytes (lc) infected in vitro or in vivo was investigated. Surface marker analysis and viral infectivity (VI) assays of lc populations were used to determine susceptibility of lc subsets to FeLV. The principal FeLV-replicating cell in the mesenteric lymph node of persistently infected, preleukemic cats was a nonadherent, complement receptor (CR)-bearing lc (B-cell). The lymph nodes of preleukemic cats also had increased numbers of uninfected T-cells [cells forming rosettes with guinea pig erythrocytes (GPE)] and cells with receptors for the Fc portion of 7S IgG (Fc gamma R cells) as compared with lymph nodes of age-matched specific-pathogen-free (SPF) cats. The induction of productive infection of feline peripheral blood mononuclear leukocytes (PBL) in vitro depended on a 48-hour in vitro preincubation period before virus exposure. The equivalent susceptibility of whole and adherent cell-depleted PBL to productive infection and the failure of hydrocortisone to enhance viral infection were compatible with identification of the FeLV-replicating cell as an lc. Furthermore, lc from susceptible SPF kittens replicated 50 times as much FeLV as did lc from resistant adult SPF cats. The Ic productively infected with FeLV after in vitro exposure were more precisely identified with the use of Ficoll-Isopaque density gradient separations of rosetted and nonrosetted lc. Whole PBL, GPE rosette-positive PBL (T-cells), and CR-positive PBL (B-cells) were permissive to FeLV infection, and maximal VI was evident at 14 days after exposure. The substantial (1,325-fold) increment in VI found in the Fc gamma R-depleted PBL suggested a role for Fc gamma R cells in the containment of FeLV infection. Unstimulated mononuclear leukocytes from blood, spleen, lymph node, thymus, and marrow were susceptible to productive FeLV infection after in vitro exposure. The degree of spontaneous DNA synthesis in marrow, thymus, and spleen but not lymph node or PBL was inversely related to permissiveness to viral replication. Mitogen activation of lc was associated with decreased viral replication when either T-cell mitogens (concanavalin A, phytohemagglutinin, or pokeweed mitogen) or a B-cell mitogen (dextran sulfate) was used. Virus production by spleen cells and PBL was enhanced twofold to tenfold by prior lc stimulation by the B-cell mitogen, lipopolysaccharide, or protein A-bearing Staphylococcus aureus, a mitogen for feline T-cells with Fc gamma R. Both productively infected (preincubated) and nonproductively infected (freshly isolated) PBL transferred infectious FeLV to autochthonous peritoneal macrophages (M theta); most of the virus in PBL-peritoneal M theta cocultures was produced by adherent cells, irrespective of whether the adherent or nonadherent cell population was inoculated originally.", "journal": "Journal of the National Cancer Institute", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6268885", "author": "Hoover EA", "n_authors": 4, "title": "Determinants of susceptibility and resistance to feline leukemia virus infection. I. Role of macrophages.", "abstract": "The role of autochthonous peritoneal feline macrophages (M theta) in the age-related resistance of cats to feline leukemia virus (FeLV) was investigated by a study of the functional properties and FeLV susceptibility of M theta from kittens and adult cats and the effect of hydrocortisone (HC) and silica on M theta-FeLV interactions. Although the phagocytic functions of isolated M theta from kittens and adults were equivalent, the mean FeLV susceptibility of M theta from kittens was five times that of M theta from adult cats, thus establishing a direct correlation between the age-related susceptibility of cats and M theta from cats to FeLV. M theta of viremic cats were found to be infected with FeLV in vivo; virus titers were slightly higher than those obtained after in vitro infection of M theta, M theta from cats that had experienced regressive FeLV infection were not significantly more resistant to FeLV infection in vitro than were M theta from naive adult specific-pathogen-free cats. HC, which has been shown to enhance the in vivo FeLV susceptibility of cats, also enhanced the permissiveness of M theta from cats to FeLV in vitro (600-fold for M theta from adult cats and 200-fold for M theta) from kittens. M theta permissiveness to FeLV was highly sensitive to HC and occurred in M theta infected in vivo or in vitro. In parallel with the effect of HC on the natural resistance of cats to FeLV, administration of silica before virus inoculation also markedly enhanced the FeLV susceptibility of adult cats. Silica was toxic for isolated M theta but not for lymphocytes in vitro, and silica produced monocytopenia and neutrophilia, delayed skin allograft rejection, and augmented feline oncovirus-associated cell membrane antigen antibody responses in vivo. These experiments indicate that M theta were linked to the natural resistance of cats to FeLV and that the temporary elimination of M theta functions (e.g., by silica) and/or the conversion of the M theta-FeLV relationship from a nonpermissive to a permissive state (e.g., by corticosteroids) resulted in failure of early virus containment, in persistent virus amplification in hemolymphatic tissues, and in subsequent FeLV-related proliferative or antiproliferative disease.", "journal": "Journal of the National Cancer Institute", "doi": "10.1093/jnci/67.4.889", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6273557", "author": "Randles JL", "n_authors": 1, "title": "Feline leukaemia virus infection.", "abstract": "All aspects, including aetiology, incidence, transmission, immunity, clinical signs, pathogenesis, pathology and diagnosis of feline leukaemia virus infection in domestic cats are considered with a bias towards the more clinical aspects for the benefit of private practitioners. Non-neoplastic disease and possible methods of control are also discussed.", "journal": "Journal of the South African Veterinary Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6270364", "author": "Fischinger PJ", "n_authors": 4, "title": "Selective host range restriction of goat cells for recombinant murine leukemia virus and feline leukemia virus type A.", "abstract": "We isolated a strain of normal goat fibroblasts which was uniquely selective in that it allowed the replication of xenotropic murine leukemia virus but not polytropic recombinant murine leukemia virus. In addition, feline leukemia virus type A replication was severely diminished in these goat cells, whereas feline leukemia virus type B and feline endogenous RD114-CCC viruses replicated efficiently. No other known cells exhibit this pattern of virus growth restriction. These goat cells allow the study of xenotropic murine leukemia virus in mixtures which also contain recombinant murine leukemia virus and may be helpful in eliminating feline leukemia virus type which often coexists in feline sarcoma or leukemia virus mixtures with other feline leukemia virus types.", "journal": "Journal of virology", "doi": "10.1128/JVI.39.3.981-985.1981", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6269117", "author": "Rhim JS", "n_authors": 1, "title": "Characterization of sarcoma-positive, leukemia-negative (S+L-) human cells induced by the feline leukemia virus pseudotype of Moloney sarcoma virus.", "abstract": null, "journal": "Proceedings of the Society for Experimental Biology and Medicine. Society for Experimental Biology and Medicine (New York, N.Y.)", "doi": "10.3181/00379727-167-41221", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6172390", "author": "Grant CK", "n_authors": 2, "title": "Feline leukemia - unique and cross-relating antigens on individual virus-producing tumors identified by complement-dependent antibody.", "abstract": "Following exposure to feline leukemia virus (FeLV), cats that resist leukemia produce complement dependent antibodies (CDA) which lyse leukemia cells in the presence of cat complement. The CDA activity has been shown to be directed to feline oncornavirus-associated cell membrane antigen (FOCMA) found on the surface of most feline leukemias. Despite the retrovirus etiology of feline leukemia, and the ubiquity of FOCMA expression by individual tumors, we found that CDA activity did not cross-react when five feline leukemia lines were compared (FL74, F422, 3272, 3281, and 79-14940). Profiles for CDA mediated lysis of the leukemia target lines were determined for sera from 149 FeLV exposed cats, and animals were identified whose sera would selectively lyse almost any possible combination of tumors from one to five lines tested. Cross absorption and cold target inhibition studies were performed on selected sera, and a spectrum of different antigens was identified which included both individual determinants and antigens shared by some of the tumor lines. Leukemias FL74 and F422 carried a cross-reactive determinant which was distinct from a second antigen shared by 3272 and 3281; lines F422, 3272 and 3281 each also carried a unique antigen. Leukemia 79-14940 did not cross-react with other target tumor lines. Targets of CDA mediated lysis on leukemia cells maybe associated with normal feline cell surface antigens, because CDA titers were sometimes reduced after serum absorption with normal cat spleen cells. The relevance of multiple FOCMA determinants is discussed in terms of tumor escape from immunity.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910280215", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6973601", "author": "Posner LE", "n_authors": 9, "title": "Natural antibodies to the human T cell lymphoma virus in patients with cutaneous T cell lymphomas.", "abstract": "Sera from patients with cutaneous T cell lymphoma and leukemia were screened for the presence of natural antibody to the human T cell lymphoma (leukemia) virus, HTLVCR, using a solid-phase radioimmunoassay. Sera from two patients, including patient CR, from whose cultured T lymphoblastic cell line (HUT102), the retrovirus HTLVCR was isolated, reacted specifically with proteins of HTLVCR. Serum from patient CR also reacted specifically with proteins of HTLVMB, an independent but highly related retroviral isolate from a patient with Sezary T cell leukemia. The specificity for HTLVCR proteins was demonstrated by solid-phase immunocompetition assays and competition radioimmunoprecipitation assays. Analysis of radioimmunoprecipitates indicated that the natural antibodies were directed against HTLVCR core proteins with molecular weights of 24,000 and 19,000 (p24 and p19). Whereas the serum reactivities for HTLVCR proteins were shown to be highly specific, additional reactivities seen against proteins of animal retroviruses including GaLV, SSV, FeLV, and BaEV were clearly shown not to be viral specific but rather were due to reactivity with cellular antigens contaminating the viral preparations or with related antigens present in fetal calf serum. These results demonstrating natural antibodies to HTLVCR provide the first evidence for a specific antibody response to a retrovirus in humans.", "journal": "The Journal of experimental medicine", "doi": "10.1084/jem.154.2.333", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6270524", "author": "Jochen RF", "n_authors": 2, "title": "Diagnosis of feline leukemia virus infections.", "abstract": null, "journal": "Modern veterinary practice", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6270655", "author": "Fedele LA", "n_authors": 5, "title": "Recombinant bacteriophages containing the integrated transforming provirus of Gardner--Arnstein feline sarcoma virus.", "abstract": "The integrated DNA provirus of the Gardner-Arnstein (GA) strain of feline sarcoma virus (FeSV) was molecularly cloned in a bacteriophage lambda vector. The cloned DNA fragment is 14.4 kilobase pairs long and contains a 6.7-kilobase provirus flanked by cellular sequences derived from nonproductively transformed mink cells. Transfection of mouse NIH/3T3 cells with the cloned DNA fragment induced foci of transformation at efficiencies of 10(4) focus-forming units/pmol of sarcoma virus DNA. Restriction endonuclease mapping and heteroduplex analyses were used to compare the GA-FeSV provirus with that of Snyder-Theilen (ST)-FeSV, a second strain that contains homologous transformation-specific sequences (v-fes). Both viruses have the general structure 5'-gag-fes-env-c region-3', each having retained portions of the feline leukemia virus (FeLV) gag and env genes. In addition to segments shared by the two sarcoma viruses, GA-FeSV contains 1.7 kilobases of extra sequences not found in ST-FeSV. Of these, at least 400-500 base pairs located near the 5' end of v-fes encode a portion of the GA-FeSV polyprotein; the remaining 1.2 kilobases are derived from the FeLV env gene but do not appear to encode any detectable product related to the FeLV envelope glycoprotein. The close homology of the v-fes sequences shows that GA- and ST-FeSV were formed by recombination of FeLV with similar portions of a cat cellular gene (c-fes).", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.78.7.4036", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6973761", "author": "Chen AP", "n_authors": 5, "title": "Retrovirus-encoded transformation-specific polyproteins: expression coordinated with malignant phenotype in cells from different germ layers.", "abstract": "A transformation-associated polyprotein designated \"gag-x\" was previously shown to be induced by the feline sarcoma virus (FeSV) after the nonproductive transformation of rat or mink cells. We found that this protein was also expressed in cells derived from the native species (cat) with or without the production of feline leukemia helper virus (FeLV) and that cats could mount a humoral antibody response to the transformation-specific (x) portion of the molecule. Such antisera also reacted with the feline oncornavirus-associated cell membrane antigen (FOCMA) by membrane immunofluorescence. Expression of the gag-x protein was coordinated with malignant phenotype in that both transformed cat fibroblasts and cultured cells from a FeSV-induced melanoma expressed antigenically indistinguishable proteins of the same size. These cells are derived from different embryonic germ layers, suggesting that such transformation-related proteins may function in a pleiotropic manner when introduced by a virus.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.78.6.3915", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6270875", "author": "Jarrett JO", "n_authors": 1, "title": "Serology in feline leukaemia virus infections.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.108.21.465-a", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "7032046", "author": "Zinkl JG", "n_authors": 1, "title": "The leukocytes.", "abstract": "Dogs and cats respond to many diseases by changes in leukocyte numbers. Infectious diseases often cause leukocytosis due to neutrophilia. Left shift may accompany the leukocytosis, indicating that the marrow is mounting a response to the disease. Left shift also indicates that the marrow has fallen somewhat behind the needs of the animal. Degenerative left shift is considered a poor sign. Lymphopenia and eosinopenia also are found in infectious diseases. Lymphocytosis may occur during the recovery or if the disease becomes chronic. The nature and duration of the infection determine the magnitude of the monocyte response. It is erroneous to consider a disease chronic based only upon monocytosis. Trauma, autoimmunity, or any disease with significant tissue destruction can evoke a monocyte response. Leukopenias are relatively common in cats and are found with moderate frequency in dogs. Drugs, viral diseases (such as FeLV, feline enteritis, parvovirus), ehrlichiosis, and hereditary conditions may cause panleukopenias or single leukopenias. Occasionally leukocyte examination provides evidence of a specific etiology (such as with ehrlichiosis). Sometimes changes occur which, although not specific for a disease, may provide a strong evidence of a particular disease (such as in salmon poisoning). Leukocyte evaluation should include not only total count and differential count (with calculation of absolute numbers of the different cells) but also morphologic examination of the cells by qualified people. In many practices the only qualified person is the veterinarian.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": "10.1016/s0195-5616(81)50029-5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6264144", "author": "Rosenberg ZF", "n_authors": 6, "title": "Biochemical characterization of cells transformed via transfection by feline sarcoma virus proviral DNA.", "abstract": "Murine fibroblasts transformed by transfection with DNA from mink cells infected with the Snyder-Theilen strain of feline sarcoma virus and subgroup B feline leukemia virus were analyzed for the presence of integrated proviral DNA and the expression of feline leukemia virus- and feline sarcoma virus-specific proteins. The transformed murine cells harbored at least one intact feline sarcoma virus provirus, but did not contain feline leukemia virus provirus. The transformed murine cells expressed an 85,000-dalton protein that was precipitated by antisera directed against feline leukemia virus p12, p15, and p30 proteins. No feline oncornavirus-associated cell membrane antigen reactivity was detected on the surfaces of the transformed murine cells by indirect membrane immunofluorescence techniques. The 85,000-dalton feline sarcoma virus-specific protein was also found in feline cells transformed by transfection. However, these cells also contained env gene products. The results of this study demonstrate that the feline sarcoma virus genome is sufficient to transform murine cells and that expression of the 85,000-dalton gag-x protein is associated with transformation of both murine and feline cells transformed by transfection.", "journal": "Journal of virology", "doi": "10.1128/JVI.38.2.782-788.1981", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6264136", "author": "Mullins JI", "n_authors": 5, "title": "Sequence arrangement and biological activity of cloned feline leukemia virus proviruses from a virus-productive human cell line.", "abstract": "We examined 14 different feline leukemia virus proviruses from the productively infected human cell line RD(FeLV)-2 after cloning in the modified lambda vector Charon 4A. Each isolate was characterized by restriction digestion and Southern blot analysis. The DNA of each isolate was tested for competence to express virus after uptake by sensitive animal cells (transfection). All but one isolate contained an apparently complete provirus, but only four were infectious. Seven isolates (four noninfectious, three infectious) were studied by heteroduplexing followed by electron microscopy or by S1 nuclease treatment and gel electrophoresis. No regions of nonhomology between proviruses were detected by either criterion, and in no case did we observe homology between flanking sequences. Random shearing or removal of flanking sequences by S1 nuclease had no effect on the status of infectivity of the clones. Thus, we were unable to find molecular differences between infectious and noninfectious proviruses. Our data are consistent with either of the following hypotheses: (i) that there is a short host sequence which is essential as a promoter for virus expression; or (ii) that lack of infectivity is due to small mutations within the proviral genome.", "journal": "Journal of virology", "doi": "10.1128/JVI.38.2.688-703.1981", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6262553", "author": "Rice JB", "n_authors": 2, "title": "Feline oncovirus-associated cell membrane antigen and feline leukemia virus group-specific antigen expression in bone marrow and serum.", "abstract": "Feline retrovirus-induced possible preneoplastic lesions were identified by detection of feline oncovirus-associated cell membrane antigen (FOCMA) in bone marrow (BM) and mesenteric lymph nodes of noninbred, domestic short- or long-hair kittens. Cell-bound FOCMA was detected 1-3 weeks after feline leukemia virus (FeLV) infection and at least 6 months before a tumor was evident. BM FOCMA was detected earlier and reached higher levels at early periods in cats that became persistently viremic. Serum FeLV group-specific antigen (gsa) increased more rapidly and reached a higher level in cats that became persistently viremic, but nonviremic cats still had detectable gsa as late as 7-9 months after FeLV infection, even in the presence of high levels of viral antibody. The presence in nonviremic cats of FeLV gsa in sera and FOCMA in BM and sera suggests that these cats may have a persistent, low-level FeLV infection.", "journal": "Journal of the National Cancer Institute", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6268292", "author": "Francis DP", "n_authors": 6, "title": "Epidemiologic association between virus-negative feline leukemia and the horizontally transmitted feline leukemia virus.", "abstract": "About two-thirds of the natural cases of feline leukemia-lymphoma are assumed to be caused by the feline leukemia virus (FeLV) because they occur in cats, which harbor this agent, and FeLV will induce the disease under laboratory conditions. Epidemiological evidence is presented which associates cases of naturally occurring 'virus negative' feline leukemia with exposure to FeLV.", "journal": "Cancer letters", "doi": "10.1016/0304-3835(81)90035-5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6264700", "author": "Schneider J", "n_authors": 3, "title": "Purification of murine and feline type-C virus envelope polypeptides as micellar protein complexes.", "abstract": "A technique originally described for the isolation of Friend leukaemia virus envelope polypeptides [1] yields equivalent structures from Moloney leukaemia. AKR and BALB/c xenotropic virus as well as feline leukaemia virus. The envelope polypeptides are obtained as micellar protein complexes, named rosettes. Rosettes of the five mammalian type-C viruses examined are indistinguishable by electron microscopy. Separation of these aggregates in polyacrylamide gel electrophoresis under nonreducing conditions reveals a glycoprotein of about 85000 d as their major component. Tryptic peptide analyses identify the viral origin of these polypeptides and emphasize strain specific differences in their primary structure.", "journal": "Zeitschrift fur Naturforschung. Section C, Biosciences", "doi": "10.1515/znc-1981-3-430", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6263848", "author": "Lester SJ", "n_authors": 2, "title": "Hematologic abnormalities preceding apparent recovery from feline leukemia virus infection.", "abstract": "A 5-month-old domestic short-haired cat was referred to the Western College of Veterinary Medicine because of hemorrhage from the mouth. Neutropenia and bone marrow dyscrasia developed within 2 weeks, and results of a fluorescent antibody test for feline leukemia virus (FeLV) were positive. During the next 6 months, the feline oncornavirus cell membrane-associated antibody titer increased, the hematologic abnormalities regressed, and the cat became negative to the FeLV fluorescent antibody test (FeLV test). The results of 3 consecutive FeLV tests were negative, and the cat has been clinically normal for the past 18 months.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6258283", "author": "Schaller JP", "n_authors": 4, "title": "Induction of retinal degeneration in cats by methylnitrosourea and ketamine hydrochloride.", "abstract": "Persistent mydriasis seen in cats used in an oncology study apparently was not related to neoplasia. Ophthalmoscopically, the cats had severely atrophic retinas and clinically observable visual impairment. These findings were confirmed by electroretinographic and histologic examination. Cats with these retinal lesions had received combinations of methylnitrosourea, ketamine hydrochloride, and feline leukemia virus. Retinopathy was not seen in ketamine-anesthetized cats receiving feline leukemia virus. To test the nature of this phenomenon, four cats were given both drugs and three received methylnitrosourea alone. The four cats developed severe generalized retinal degeneration by day 5, whereas the three cats given methylnitrosourea alone had normal retinas. Histologic changes in the affected cats were extensive loss of rods and cones, and of the outer nuclear layer. The electroretinographic responses to white light were depressed or extinguished. Retinal degeneration, therefore, appeared to be dependent upon administration of both methylnitrosourea and ketamine hydrochloride.", "journal": "Veterinary pathology", "doi": "10.1177/030098588101800212", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6939520", "author": "Goh K", "n_authors": 3, "title": "Chromosomal aberrations in leukemic cats.", "abstract": "The bone marrows of two female acute lymphoblastic leukemic cats were studied cytogenetically with the conventional and one also with the G-banding techniques. Both cats had marked aneuploidies. Cat leukemia is caused by virus, FeLV. Perhaps, this virus is capable of affecting cat chromosomes and as a result of this process converts the normal cells into leukemic cells.", "journal": "The Cornell veterinarian", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6274764", "author": "Hardy WD Jr", "n_authors": 7, "title": "Feline leukemia virus nonproducer lymphosarcomas of cats as a model for the etiology of human leukemias.", "abstract": null, "journal": "Haematology and blood transfusion", "doi": "10.1007/978-3-642-67984-1_90", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6269798", "author": "Mia AS", "n_authors": 4, "title": "A micro-enzyme-linked immunosorbent assay (ELISA) test for detection of feline leukemia virus in cats.", "abstract": null, "journal": "Comparative immunology, microbiology and infectious diseases", "doi": "10.1016/0147-9571(81)90036-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6268565", "author": "Saxinger C", "n_authors": 1, "title": "Evaluation of the parameters of the ELISA procedure for feline type C retroviral antigens: assay of FeLV antigens in chronically infected or nonproducer transformed cells.", "abstract": "The successful application of an improved enzyme-linked immunosorbent assay (ELISA) to the specific detection and quantitation of feline leukemia virus (FeLV) is presented. The methods described can detect FeLV antigens at the picogram/milliliter level using a fluorometric assay for peroxidase-linked antibody. The use of a fluorogenic substrate resulted in at least a 9-fold increase in sensitivity of the peroxidase assay. FeLV antigens could be specifically detected in chronically infected cells as well as in feline sarcoma virus-transformed nonproducer mink cells which only partially express viral proteins.", "journal": "Intervirology", "doi": "10.1159/000149208", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6262865", "author": "Francis DP", "n_authors": 3, "title": "Feline leukemia virus and hepatitis B virus: a comparison of late manifestations.", "abstract": null, "journal": "Progress in medical virology. Fortschritte der medizinischen Virusforschung. Progres en virologie medicale", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6261000", "author": "Barbacid M", "n_authors": 1, "title": "Cellular transformation by subgenomic feline sarcoma virus DNA.", "abstract": "The genome of the Snyder-Theilen strain of feline sarcoma virus (ST-FeSV) is a 4.3-kilobase-pair (kbp) RNA molecule that contains a 1.5-kbp cellular insertion (fes gene) flanked by feline leukemia virus sequences at its 5' end (1.6 kbp) and 3' end (1.2 kbp) (Sherr et al., J. Virol. 34:200-212, 1980). DNA transfection techniques have been utilized to determine the regions of the ST-FeSV genome involved in malignant transformation. I have found that the 3.7-kbp 5'-end fragment of the ST-FeSV provirus (which corresponds to the 3.4-kbp 5'-end fragment of the viral genome) is sufficient to transform NIH/3T3 fibroblasts. Enzymes that cleave the ST-FeSV provirus DNA within the feline leukemia virus gag gene sequences or within the fes gene abolished the transforming activity. Preservation of the proviral large terminal repeats was also required for transformation. Transformed NIH/3T3 cells obtained by transfection of total or subgenomic ST-FeSV DNA expressed normal levels of the ST-FeSV gene product ST P85 and of its associated protein kinase activity. Furthermore, these cells contained high levels of phosphotyrosine residues, a biochemical marker associated with cellular transformation induced by certain retroviruses including ST-FeSV. These results, taken together, strongly support the concept that only those ST-FeSV proviral sequences necessary for ST P85 expression are involved in malignant transformation.", "journal": "Journal of virology", "doi": "10.1128/JVI.37.1.518-523.1981", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6256575", "author": "Rice JB", "n_authors": 6, "title": "Infection of feline embryo adherent cells with feline leukemia virus: feline oncornavirus-associated cell membrane antigen expression and morphologic transformation.", "abstract": "Feline embryo adherent cells were infected with the Richard or Kawakami-Theilen strains of feline leukemia virus (FeLV) and examined for feline oncornavirus-associated cell membrane antigen (FOCMA), viral group-specific antigen (gsa) production, and in vitro evidence of transformation. As early as 10 days after infection, when more than half of the infected cells were gsa positive, FOCMA was detected on 5-10 percent of the cells. Transitory morphologic alterations (epithelioid appearance and rounding) were first noted in most cultures around 20-30 days post infection. At this time, approximately 50% of the cells in infected cultures expressed FOCMA. Morphologic characteristics of transformed fibroblastic cells (rounded shape, disordered alignment, and low adhesion to substratum), as well as enhanced agglutinability by plant lectins and ability to grow in agar, were demonstrated in one of four FeLV-infected, FOCMA-positive cultures. Findings showed that FOCMA may be expressed in FeLV-infected monolayer cells independent of transformation as assessed by in vitro criteria.", "journal": "Journal of the National Cancer Institute", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1982, "pmid": "6185520", "author": "Schetters H", "n_authors": 4, "title": "Detection of group and interspecies reactivities of mammalian C-type virus p30 proteins by an enzyme-linked immunosorbent assay (ELISA): enhancement of interspecies reactivity by denaturation.", "abstract": "The applicability of the enzyme immunoassay technique to the detection of group and interspecies determinants of C-type retroviral proteins was tested. For this purpose four groups of C-type retroviruses (MuLV, FeLV, SiSV/GaLV, and BaEV/RD114) were assayed for group-specific and interspecies reactivities of their p30 proteins by an enzyme-linked immunosorbent assay (ELISA). We found that the ELISA can detect group-specific as well as interspecies determinants with sensitivity and reproducibility in purified p30 proteins, disrupted viruses, and cell extracts if an anti-p30 interspecies antiserum is used. If monospecific antisera against MuLV p30, SiSV p30, or BaEV p30 were used, only group-specific reactivities were detected reproducibly, whereas the detectability of interspecies determinants depended on the antisera used and varied even with the same antisera. In assays in which the reactivity of native and denatured p30 proteins was compared the detectability of sodium dodecyl sulphate-denatured MuLV p30 was better than that of native MuLV p30 suggesting that some of the most broadly cross-reactive sequences are localized inside the protein molecule and are freed by the denaturation process. Antisera raised against native and denatured p30 proteins showed identical spectra of reactivity.", "journal": "Journal of virological methods", "doi": "10.1016/0166-0934(82)90008-8", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1982, "pmid": "16030832", "author": "Jones BR", "n_authors": 2, "title": "Feline leukemia virus testing.", "abstract": null, "journal": "New Zealand veterinary journal", "doi": "10.1080/00480169.1982.34925", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1982, "pmid": "7142977", "author": "Fischinger PJ", "n_authors": 5, "title": "Persistence of one species of oncovirus in mixed infection after antiserum treatment or transspecies rescue.", "abstract": "Attempts were made to change the envelope of murine sarcoma virus (MSV) from B-MuX (a xenotropic murine leukaemia virus isolate) to feline leukaemia virus (FeLV) by infecting cat cells with MSV(B-MuX), adding excess FeLV as helper and using mouse serum oncovirus-inactivating factor or anti-B-MuX serum. In several attempts, virus from single foci of MSV initially contained only MSV(FeLV) but on passage each showed a minimal persistence of B-MuX. To eliminate the B-MuX component, MSV(B-MuX) was subjected to two consecutive transspecies rescues. The first was performed by co-cultivation of MSV(B-MuX)-producing quail cells with mouse 3T3FL cells, which are completely non-permissive for B-MuX, and pure ecotropic Friend Eveline strain of murine leukaemia virus (F-MuLV); this resulted in apparently pure MSV(F-MuLV). Second, these MSV(F-MuLV)-infected 3T3FL cells were co-cultivated with FeLV and cat cells, which are completely non-permissive for F-MuLV; this resulted in the generation of MSV(FeLV). Passage of this apparently pure FeLV pseudotype in cells permissive only for the replication of B-MuX surprisingly revealed residual murine xenotropic virus. It appears that pressure for survival resulted in genomic masking of B-MuX by heterologous virus envelopes. This phenomenon, which also occurs extensively in nature, implies that if absolute oncovirus genetic purity is required, even extensive attempts at purification may be inadequate.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-62-2-393", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1982, "pmid": "6286102", "author": "Lee TH", "n_authors": 4, "title": "Neutralization of feline leukemia virus with feline antisera to leukocyte alloantigens.", "abstract": "The possibility that normal cellular antigens might serve as targets for antibody neutralization of the feline leukemia virus was investigated. Xenospecific antiserum directed to normal feline cells was shown to inactivate feline leukemia virus grown in fibroblasts. Cat antisera to normal feline leukocyte alloantigens were then prepared, after which persistent viremia was induced in the donor cats. Such alloantisera neutralized virus taken from plasma of the appropriate cat but did not neutralize virus from a different cat. The virus neutralization was dependent on the presence of complement. These results indicate that alloantigens are present at the virus surface and raise the possibility that such antigens may play a role in the natural immune response directed to retrovirus infections.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1982, "pmid": "6183005", "author": "Hampe A", "n_authors": 5, "title": "Nucleotide sequences of feline retroviral oncogenes (v-fes) provide evidence for a family of tyrosine-specific protein kinase genes.", "abstract": "The nucleotide sequences encoding the transforming polyproteins of the Snyder-Theilen and Gardner-Arnstein strains of feline sarcoma virus (FeSV) have been determined. These sequences include a viral transforming gene (v-fes), derived from cellular proto-oncogene sequences (c-fes) of domestic cats by recombination with feline leukemia virus (FeLV). The v-fes sequences are predicted to encode a polypeptide domain strikingly similar to that specified by the transforming gene (v-fps) of the avian Fujinami sarcoma virus. In addition, the 3' 0.8 kilobase pairs of v-fes encode amino acid sequences homologous to the carboxy-terminal portion of pp60src, the transforming protein encoded by the avian Rous sarcoma virus src gene. Thus different feline and avian retroviral transforming genes, all of which encode functionally related proteins with associated tyrosine-specific kinase activities, must be derived from divergent members of the same proto-oncogene family.", "journal": "Cell", "doi": "10.1016/0092-8674(82)90282-3", "deposited_data": "Sim", "nuccore_ids": "323892, 323872, 2462543208, 2462543206, 2462543204, 2462543202, 2462543200, 2462543198, 2462543196, 2462543194, 2462543192, 2462543190, 2462543188, 2462543186, 2462543184, 2462543182, 2462543180, 2217300426, 2217300424, 2217300422, 2217300420, 2217300418, 2217300417, 2217300415, 2217300414, 2217300413, 2217300411, 2217300410, 2217300409, 2217300408, 2217300407, 2217300406, 1676324916, 1519245536, 219842232, 219842229", "bioproject_ids": null, "sra_ids": null}, {"year": 1982, "pmid": "7129681", "author": "Rhim JS", "n_authors": 3, "title": "Neoplastic transformation of rabbit cells by murine sarcoma viruses.", "abstract": "Neoplastic transformation of rabbit cells by Kirsten murine sarcoma virus (Ki-MSV), the Ki-MSV pseudotype of baboon endogenous virus (Ki-MSV[BaEV]) and the Moloney-MSV pseudotype of feline leukemia virus (M-MSV[FeLV]) is reported. Rabbit cells can be readily transformed by Ki-MSV, Ki-MSV(BaEV) and M-MSV(FeLV). Rabbit cells transformed by Ki-MSV and M-MSV(FeLV) were found to be virus producers, whereas those transformed by Ki-MSV(BaEV) were nonproducers (NP). The NP cells were obtained by simply infection rabbit cells with Ki-MSV(BaEV) and subculturing the infected cells. Although the morphologically altered NP cells did not produce infectious virus or murine leukemia virus antigen, they did contain a rescuable MSV genome. All of the transformed cells formed colonies in soft agar, grew to high saturation densities and produced tumors when transplanted into nude mice. The Ki-MSV and M-MSV(FeLV)-transformed cells produced tumors in newborn WH/J rabbits, thus providing an important tool for studying tumor immunity in the rabbit.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910300318", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1982, "pmid": "6183442", "author": "Veronese F", "n_authors": 5, "title": "Monoclonal antibodies specific to transforming polyproteins encoded by independent isolates of feline sarcoma virus.", "abstract": "Hybridomas secreting monoclonal antibodies directed against polyprotein gene products of the Gardner, Snyder-Theilen, and McDonough strain of feline sarcoma virus have been isolated. Antibody produced by one hybridoma recognizes immunological determinants localized within a feline leukemia virus gag gene structural component (p15) common to polyproteins encoded by each feline sarcoma virus isolate while antibody produced by a second is specific for p30 determinants unique to P170gag-fms. Additional hybridomas secrete antibody directed against v-fes specific determinants common to the Gardner and Snyder-Theilen feline sarcoma virus-encoded polyproteins and to v-fms determinants unique to P170gas-fms polyprotein. GA P110gas-fes and ST P85gas-fes immunoprecipitated by antibody directed against p15 exhibit readily detectable levels of protein kinase activity but lack such activity when precipitated by antibody specific for their acquired sequence (v-fes) components. P170gas-fms immunoprecipitated by monoclonal antibody to either p15 or p30 lacks detectable levels of autophosphorylation but represents a substrate for the GA P110gag-fes and ST P85gag-fes enzymatic activities. These findings argue that the v-fes-associated protein kinase represents an intrinsic property of the v-fes gene product and recognizes tyrosine acceptor sites within polyprotein gene products of all three strains of feline sarcoma virus.", "journal": "Journal of virology", "doi": "10.1128/JVI.43.3.896-904.1982", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1982, "pmid": "6287075", "author": "Sordillo PP", "n_authors": 3, "title": "Search for evidence of feline leukemia virus infection in humans with leukemias, lymphomas, or soft tissue sarcomas.", "abstract": "Two-hundred and thirty-nine patients, including 66 with soft tissue sarcomas and 173 with hematologic cancers, were investigated for evidence of infection with feline leukemia virus (FeLV). Included in this group were 2 patients with acute lymphocytic leukemia who had lived in the same household with leukemic cats. None of the patients demonstrated measurable levels of neutralizing antibody to FeLV or had detectable FeLV antigens in peripheral blood normal leukocytes or leukemic cells. In a smaller number of patients, there was no evidence of antibody to FOCMA or of FOCMA on tumor cells in the bone marrow.", "journal": "Journal of the National Cancer Institute", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1982, "pmid": "6283387", "author": "Rojko JL", "n_authors": 4, "title": "Reactivation of latent feline leukaemia virus infection.", "abstract": "In most cats exposed to the contagious feline leukemia virus (FeLV), viral replication is contained in target haematopoietic tissues and elicits humoral immunity to FeLV and to the feline oncornavirus-associated cell membrane antigen (FOCMA). Recently, we and others have considered that these ostensibly self-limiting infections might be persistent nonproductive (latent) infections in certain haematopoietic cells. This hypothesis could account for the relapsing viraemias, protracted incubation periods, persistently high titres of antiviral and anti-FOCMA antibodies, appearance of FeLV p27 antigen in serum of otherwise non-viraemic animals and occurrence of FeLV-negative but FOCMA-positive leukaemias in naturally infected pet cats. Here we describe the reactivation of latent FeLV from myelomonocytic and lymphoid cells of cats immune to FeLV, cats bearing FeLV-negative tumours, and kittens congenitally exposed to FeLV. Furthermore, the reappearance of FeLV infection is suppressed by the Host's immune system but his can be altered by adrenal corticosteroid hormones in vivo and in vitro.", "journal": "Nature", "doi": "10.1038/298385a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1982, "pmid": "6281336", "author": "Snyder HW Jr", "n_authors": 4, "title": "Isolation and characterization of circulating feline leukemia virus-immune complexes from plasma of persistently infected pet cats removed by ex vivo immunosorption.", "abstract": "IgG and circulating IgG immune complexes (CIC) were purified from plasma of three pet cats persistently infected with feline leukemia virus (FeLV) by adsorption to, and elution from, Staphylococcus aureus Cowan I. CIC were then separated from free IgG by sucrose gradient ultracentrifugation and were analyzed for the presence of FeLV structural proteins and corresponding specific antibodies. Radioimmunoprecipitation analysis indicated that FeLV envelope (gp70) and major core (p30) proteins, along with cat IgG heavy and light chains, were present in the CIC from all three cats. Further analysis of the CIC from one of the cats also revealed the presence of FeLV core proteins p15 and p12. IgG purified from isolated CIC was also shown to bind specifically to purified FeLV gp70, p30, and p15. These data provide direct evidence for FeLV-specific CIC in the plasma of persistently viremic pet cats, and suggest these animals are immunologically response to the virus even though free antibodies against the major structural proteins cannot be demonstrated in standard assays.", "journal": "Journal of immunology (Baltimore, Md. : 1950)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1982, "pmid": "6281960", "author": "Jarrett O", "n_authors": 3, "title": "A comparison of three methods of feline leukaemia virus diagnosis.", "abstract": "Samples of blood from pet cats were examined for evidence of feline leukaemia virus (FeLV) by three techniques: virus isolation, immunofluorescence and an enzyme-linked immunosorbent assay (ELISA) Leukassay F. There was good agreement between the results from virus isolation and immunofluorescence. However, about 30 per cent of cats which were positive for FeLV antigen by ELISA were negative by either of the other tests. The status of most of these cats was unchanged four or 12 weeks later.", "journal": "The Veterinary record", "doi": "10.1136/vr.110.14.325", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1982, "pmid": "6278316", "author": "Onions D", "n_authors": 5, "title": "Selective effect of feline leukaemia virus on early erythroid precursors.", "abstract": null, "journal": "Nature", "doi": "10.1038/296156a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1982, "pmid": "6281958", "author": "Jarrett O", "n_authors": 3, "title": "Detection of transient and persistent feline leukaemia virus infections.", "abstract": "A study was made of cats persistently or transiently viraemic with feline leukaemia virus (FeLV) following experimental oronasal infection. Cats of two ages were exposed to the virus. One group was infected when eight weeks old in the expectation that most of the cats would become persistently viraemic, and the second group when 16 weeks old, so that some would show signs of a transient infection and then recover. The periods following infection when virus was detectable in the blood and in the oropharynx were determined for each group. Three methods for detecting viraemia were compared: virus isolation, immunofluorescence on blood smears and an enzyme-linked immunosorbent assay (ELISA). There was good overall agreement among the three tests in detecting virus-positive cats. Virus was found sooner after infection by virus isolation than by the other methods, and virus appeared in the blood slightly sooner in cats which developed persistent viraemia than in transiently viraemic cats. Infectious FeLV was isolated from the oropharynx of all of the persistently viraemic cats, in most cases simultaneously with virus in the plasma. Virus was also isolated from the mouth of most transiently viraemic cats. Under field conditions such transient excretion of virus lasting only a few days would rarely be detected in a single sampling. This might explain how FeLV is maintained in free range urban cats in the absence of a large number of cats with persistent active FeLV infection. For routine diagnosis, immunofluorescence would appear to offer the best chance of differentiating transient and persistent infections by FeLV.", "journal": "The Veterinary record", "doi": "10.1136/vr.110.10.225", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1982, "pmid": "6284972", "author": "Cohen M", "n_authors": 4, "title": "DNA sequence relationship of the baboon endogenous virus genome to the genomes of other type C and type D retroviruses.", "abstract": "Baboon endogenous virus (BaEV) is a type C retrovirus present in multiple proviral copies in the DNA of baboons. Although interspecies antigenic determinants present on reverse transcriptase and gag proteins are shared among all mammalian type C viruses, no nucleic acid homology between BaEV and other type C viruses (except RD-114) has been found in conventional liquid hybridization experiments. In this study, we used restriction fragments of cloned BaEV DNA immobilized on nitrocellulose to test for relatedness with [(32)P]cDNA's of various type C and type D viruses. We detected the following distant relationships previously found only through immunological and protein sequencing techniques: (i) eight type C viral cDNA's (the endogenous virus of rhesus monkeys, feline leukemia virus, simian sarcoma virus, gibbon ape leukemia virus, Rauscher murine leukemia virus, BALB-2, NZB, and RD-114) and two type D viral cDNA's (Mason-Pfizer monkey virus and squirrel monkey retrovirus) were able to hybridize with cloned BaEV DNA; (ii) the eight type C probes hybridized to restriction fragments spanning most of the BaEV genome, but only RD-114 hybridized to fragments within the 1.9 kilobases at the 3' end of the genome; (iii) the two type D probes hybridized primarily to fragments within the 1.9 kilobases at the 3' terminus and weakly or not at all elsewhere; and (iv) [(32)P]cDNA's of several other oncornaviruses (mouse mammary tumor virus, equine infectious anemia virus, bovine leukemia virus, and reticuloendotheliosis virus) exhibited no homology with BaEV DNA. DNA sequence analysis has allowed us to orient the BaEV restriction map with the genetic map at both ends of the genome. Homologies between retroviral cDNA's and BaEV clone restriction fragments could thus be related to specific BaEV genes. Whereas type C cDNA's hybridized to fragments from gag, pol, and the pol-env junction, squirrel monkey retrovirus cDNA hybridized only to a fragment coding for the p15E portion of env. Mason-Pfizer monkey virus cDNA also hybridized within the p15E region, but exhibited homology to the 3' half of gp70 as well. These results are discussed relative to previously reported antigenic relatedness of retroviral proteins. The data suggest that BaEV represents an important link in oncornavirus evolution.", "journal": "Journal of virology", "doi": "10.1128/JVI.41.3.801-812.1982", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1982, "pmid": "6281462", "author": "Donner L", "n_authors": 5, "title": "McDonough feline sarcoma virus: characterization of the molecularly cloned provirus and its feline oncogene (v-fms).", "abstract": "The genetic structure of the McDonough strain of feline sarcoma virus (SM-FeSV) was deduced by analysis of molecularly cloned, transforming proviral DNA. The 8.2-kilobase pair SM-FeSV provirus is longer than those of other feline sarcoma viruses and contains a transforming gene (v-fms) flanked by sequences derived from feline leukemia virus. The order of genes with respect to viral RNA is 5'-gag-fms-env-3', in which the entire feline leukemia virus env gene and an almost complete gag sequence are represented. Transfection of NIH/3T3 cells with cloned SM-FeSV proviral DNA induced foci of morphologically transformed cells which expressed SM-FeSV gene products and contained rescuable sarcoma viral genomes. Cells transformed by viral infection or after transfection with cloned proviral DNA expressed the polyprotein (P170gag-fms) characteristic of the SM-FeSV strain. Two proteolytic cleavage products (P120fms and pp55gag) were also found in immunoprecipitates from metabolically labeled, transformed cells. An additional polypeptide, detected at comparatively low levels in SM-FeSV transformants, was indistinguishable in size and antigenicity from the envelope precursor (gPr85env) of feline leukemia virus. The complexity of the v-fms gene (3.1 +/- 0.3 kilobase pairs) is approximately twofold greater than the viral oncogene sequences (v-fes) of Snyder-Theilen and Gardner-Arnstein FeSV. By heteroduplex, restriction enzyme, and nucleic acid hybridization analyses, v-fms and v-fes sequences showed no detectable homology to one another. Radiolabeled DNA fragments representing portions of the two viral oncogenes hybridized to different EcoRI and HindIII fragments of normal cat cellular DNA. Cellular sequences related to v-fms (designated c-fms) were much more complex than c-fes and were distributed segmentally over more than 40 kilobase pairs in cat DNA. Comparative structural studies of the molecularly cloned proviruses of Synder-Theilen, Gardner-Arnstein, and SM-FeSV showed that a region of the feline-leukemia virus genome derived from the pol-env junction is represented adjacent to v-onc sequences in each FeSV strain and may have provided sequences preferred for recombination with cellular genes.", "journal": "Journal of virology", "doi": "10.1128/JVI.41.2.489-500.1982", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1982, "pmid": "6279852", "author": "Stiff MI", "n_authors": 2, "title": "Loss of the short-lived suppressive function of peripheral leukocytes in feline retrovirus-infected cats.", "abstract": "Normal feline peripheral blood mononuclear cells demonstrated increased phytomitogen blast transformation after a 24 hr delay in mitogen addition as compared to 0 hr mitogenesis. Increased stimulation after 24 hr which is not due to enhancing factors accumulating in the culture medium has been attributed to a short-lived suppressor cell which loses its effect after 24 hr in culture. This short-lived suppressive phenomenon was studied in normal specific-pathogen-free cats and compared to experimental animals infected with retrovirus (FeLV). Experimental cats demonstrated a subsequent loss of this function following acquisition of a persistent viremia.", "journal": "Journal of clinical & laboratory immunology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1982, "pmid": "6947860", "author": "Scheinberg DA", "n_authors": 2, "title": "Leukemic cell targeting and therapy by monoclonal antibody in a mouse model system.", "abstract": "A monoclonal antibody prepared against the Rauscher virus envelope glycoprotein with a molecular weight of 70,000 targeted to neoplastic cells and cured the Rauscher leukemia virus-induced erythroleukemia in BALB/c mice. This antibody, 103A, specifically reacted with the Rauscher and Friend erythroleukemia viruses and erythroleukemic cells but did not react with other murine ecotropic or xenotropic viruses or feline leukemia virus or with normal spleen cells, thymocytes, or fibroblasts, as measured by radioimmunoassays. P3, a control antibody of the same immunoglobulin G1 subclass, did not bind to any of these cells or viruses. This specificity was maintained in vivo. 125I-Labelled 103A injected into mice targeted to leukemic spleen cells but not to normal cells. Mean uptake ratios of binding to leukemic over normal spleen cells ranged from greater than 70 at 7 hr after injection to less than 10 at 40 hr later. The control antibody showed no binding in vivo. A single small dose of 103A was able to cure leukemic mice as assayed by spleen focus formation on Day 8 or splenomegaly on Day 20. The 50% effective dose was 1.5 micrograms when injected 72 hr after onset of leukemia. The therapeutic potencies of drugs, toxins, and cytotoxic radioisotopes conjugated to antibodies can be quantitatively compared using the established dose-response curve. Such quantitative comparisons showed that 131-labeled 103A immunoglobulin G was no more potent than unlabeled 103A immunoglobulin G in this system.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1982, "pmid": "6195744", "author": "Hardy WD Jr", "n_authors": 1, "title": "Immunopathology induced by the feline leukemia virus.", "abstract": null, "journal": "Springer seminars in immunopathology", "doi": "10.1007/BF00201958", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6318434", "author": "Snyder HW Jr", "n_authors": 5, "title": "The feline oncornavirus-associated cell membrane antigen (FOCMA) is related to, but distinguishable from, FeLV-C gp70.", "abstract": "The feline oncornavirus-associated cell membrane antigen (FOCMA) on the surface of feline lymphosarcoma (LSA) cells is defined as the target(s) recognized in immunofluorescence (IFA) tests by antibody in sera of cats relatively resistant to development of FeLV (feline leukemia virus) LSA and FeSV (feline sarcoma virus) fibrosarcoma. The specificities of antibodies in cat FOCMA-typing sera and the nature of the LSA antigens recognized were investigated in the present study. FOCMA sera obtained from viremic cats were separable into at least two classes : those which contained antibodies against the envelope glycoprotein (gp70) of subgroup C FeLV and those which did not contain antibodies against any subgroup of FeLV. The first class of sera could be further subdivided into three groups: those whose FOCMA reactivity could be completely absorbed, partially absorbed, or not absorbed by FeLV-C antigens. The second class of sera could be further subdivided into two groups: those whose FOCMA reactivity could be partially absorbed and those whose activity could not be absorbed by FeLV-C. The results indicate that the FOCMA reactivity exhibited by some viremic cat sera can be partially, if not entirely, attributed to antibodies not crossreactive with FeLV virion antigens. A consistent property of all FOCMA sera in this study is the ability to bind to 70-kDa proteins on the surface of LSA cells. Staphylococcus aureus V8 protease partial digest maps of 70-kDa proteins purified from 12 primary feline LSAs (five FeLV positive and seven FeLV negative) all showed 18-, 14-, and 10-kDa fragments. V8 maps of FeLV-C gp70 showed similarly sized fragments while the maps of the RD114, FeLV-A, and FeLV-B gp70s were distinct. However, in a subgroup-specific radioimmunoassay for FeLV-C gp70-related antigens, the LSA 70-kDa proteins were found to be serologically related to, but distinct from, FeLV-C gp70. The results on the antigenic variations among LSA 70-kDa proteins and the antibodies which bind them are entirely consistent with previous studies indicating heterogeneity among FOCMA determinants.", "journal": "Virology", "doi": "10.1016/0042-6822(83)90500-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6196410", "author": "Grant CK", "n_authors": 4, "title": "Feline leukemia virus envelope gp70 of subgroups B and C defined by monoclonal antibodies with cytotoxic and neutralizing functions.", "abstract": "Nine murine monoclonal antibodies (MAb) to the envelope proteins of feline leukemia virus (FeLV) are described. Eight MAb are directed to epitopes of the same molecular species of gp70 and the other MAb is directed to the p15E moiety. Six of the gp70 epitopes are discrete; two are closely associated or overlapping. Four anti-gp70 MAb (2 of IgG2A and 2 of IgG2B subclasses) were directly cytotoxic for FeLV-producer lymphoma cells with cat or with rabbit complement (C). Another MAb (IgG2B), which was not cytotoxic alone, specifically and synergistically increased the cytotoxic effects of both IgG2A MAb. Cytotoxic anti-gp70 MAb also had virus-neutralizing capacity; one MAb recognized a determinant common to all FeLV subgroups (A, B, and C), the others recognized gp70 epitopes not present on subgroup A but common to both B and C subgroups. Competitive inhibition of MAb binding was employed to map spatial distributions of the epitopes, and the results fitted a molecule shaped as an incomplete loop. According to the model, epitopes involved with cytotoxic and virus neutralizing antibody functions were closely associated; the region involved is approximately in the center of the molecule, and it contains epitopes that are variably expressed among individual isolates of FeLV derived from different cat lymphoma cell lines.", "journal": "Journal of immunology (Baltimore, Md. : 1950)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6316819", "author": "Lutz H", "n_authors": 3, "title": "Course of feline leukemia virus infection and its detection by enzyme-linked immunosorbent assay and monoclonal antibodies.", "abstract": "Monoclonal antibodies specific for 3 distinct epitopes of the species-specific determinants of feline leukemia virus (FeLV) p27 were used in an enzyme-linked immunosorbent assay (ELISA) for measurement of serum p27 in cats infected with FeLV. Group-specific antigen (GSA) of FeLV in peripheral blood leukocytes was also determined by an immunofluorescence assay. Antibodies to FeLV and the feline oncornavirus-associated cell membrane antigen (FOCMA) were also measured. Thirty-six cats were surveyed and assigned to 4 categories. Five developed persistent viremia (category 1), characterized by continuous expression of p27, GSA, and low antibody titers to FeLV and FOCMA. Eleven cats with transient viremia (category 2) and 13 cats that were never detectably viremic (category 3), as judged by absence of GSA and p27, developed increased antibody titers to FeLV and FOCMA. Seven cats were never viremic, as judged by the GSA in the peripheral blood leukocytes, but still had detectable serum p27 (category 4). Most category 4 cats developed high antibody titers against FOCMA and/or FeLV. Of 307 field cats examined, 7% of the healthy cats and 10% of the sick cats could be assigned to category 4. However, this difference was not significant (P greater than or equal to 0.05). Of 26 cats with neoplasms 2 (1 of 12 with lymphosarcoma) could be classified as category 4. Because virus could be isolated from 2 category 4 cats, they were considered immune carriers.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6316617", "author": "Weiser MG", "n_authors": 2, "title": "Erythrocyte macrocytosis in feline leukemia virus associated anemia.", "abstract": "Using erythrocyte volume distribution histograms (erythrograms), erythrocyte macrocytosis and anisocytosis were quantitated in 139 cats tested for feline leukemia virus group-specific antigen. Feline leukemia virus-negative cats with non-regenerative anemia or normal packed cell volumes had normal mean corpuscular volume values. Uninfected cats with regenerative anemia had prominent significantly increased macrocytosis and anisocytosis (p less than 0.01). Ninety percent of 62 feline leukemia virus-positive cats had altered erythrograms. Thirty-three feline leukemia virus-positive cats with non-regenerative anemia had marked macrocytosis. Their mean corpuscular volume values (mean 60 fl +/- 2 fl standard error, reference range of 37-49 fl) were significantly greater than those of feline leukemia virus-negative cats except for those with regenerative anemia. Feline leukemia virus-positive, non-anemic cats had significantly increased mean corpuscular volume values of intermediate magnitude. Nine adult cats experimentally infected with feline leukemia virus developed non-regenerative anemia with significant increases in mean corpuscular volume and anisocytosis. However, the macrocytosis observed in these cats was considerably less than in naturally occurring feline leukemia virus-positive cats with non-regenerative anemia. These observations indicate there are events in the pathogenesis of feline leukemia virus-associated anemia other than simple erythroid hypoplasia. We suggest that hemolysis and erythrocyte regeneration occur before erythroid hypoplasia and may partially account for macrocytosis observed in the face of non-regenerative anemia.", "journal": "Veterinary pathology", "doi": "10.1177/030098588302000604", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6196994", "author": "Floyd K", "n_authors": 3, "title": "Granules of blood eosinophils are stained directly by anti-immunoglobulin fluorescein isothiocyanate conjugates.", "abstract": "Direct staining of the granules of blood eosinophils by anti-immunoglobulin fluorescein isothiocyanate (FITC) conjugates was observed when feline blood smears were tested for presence of feline leukemia virus (FeLV) antigen by immunofluorescent antibody. When blood smears of other species including swine, horses, cattle, dogs, sheep, birds, and human beings were examined, direct staining of eosinophils by FITC conjugates was also detected. This FITC staining was restricted to eosinophils and was not observed in neutrophils, lymphocytes, and platelets. Direct FITC staining of eosinophils does not represent a problem in immunofluorescent test for the detection of FeLV infection in cats, as long as the eosinophils, which can easily be recognized as such, are excluded from the spectrum of interpreted cells.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6311904", "author": "Copelan EA", "n_authors": 6, "title": "The mechanism of retrovirus suppression of human T cell proliferation in vitro.", "abstract": "Immunosuppression is commonly associated with retrovirus-induced animal tumors. Studies in the murine and feline retrovirus systems suggest that the 15,000-dalton envelope protein (p15E) of the virion may contribute to immunosuppression by interfering with normal lymphocyte function. We examined the effect of inactivated feline leukemia virus (UV-FeLV) and p15E derived from this virus on concanavalin A (Con A) driven human T cell proliferation. Virus and p15E markedly suppressed mononuclear cell proliferative response to Con A. Suppression was not due to inhibition of monocyte accessory cell function, or interleukin 1 (IL 1) secretion. In fact, the presence of monocytes partially protected T cells from UV-FeLV suppression. UV-FeLV, however, suppressed T cell secretion of and response to interleukin 2 (IL 2). We conclude that UV-FeLV and derived p15E inhibit T cell proliferation by direct inhibition of T cell function. These findings, extended to the in vivo situations, suggest that retrovirus-associated suppression of the immune response involves the induction of T cell but not monocyte dysfunction.", "journal": "Journal of immunology (Baltimore, Md. : 1950)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6311439", "author": "McCarty JM", "n_authors": 2, "title": "Feline cytotoxic immune mechanisms against virus-associated leukemia and fibrosarcoma.", "abstract": "Humoral and cellular cytotoxic immune mechanisms of cats were compared against feline leukemia virus (FeLV)- and feline sarcoma virus (FeSV)-transformed cells. The groups of animals studied were nonexposed control cats; FeLV-infected immune or viremic tumor-bearing cats; FeSV-inoculated tumor progressor or regressor cats, and cats immunized with FeSV-transformed autochthonous fibroblasts (ATF). Sera containing complement-dependent antibodies (CDA), which lysed FeLV-producer lymphoma lines, had no cytotoxic effects when tested against FeLV-producer FeSV-transformed fibroblasts. Sera with lytic CDA activity were also tested for antibody-dependent cellular cytotoxic (ADCC) effects with peripheral blood lymphocytes (PBL) from nonimmune cats. No ADCC activity was detected against either lymphoid or fibroblast target lines. To demonstrate that cat PBL contained ADCC effector cells, antibody-coated murine target cells were employed and positive results obtained. Natural killer (NK) assays were performed using PBL from normal and tumor-bearing cats. Cytotoxic effects were only detectable to FeLV-producer lymphomas, and comparable levels of NK activity were found in normal and lymphoid tumor-bearing animals. In cats immunized with ATF, a population of effector cells was found in peripheral blood which had functional characteristics of cytotoxic T lymphocytes (CTL). The killing of ATF by CTL-like cells was not inhibited by FeLV/FeSV immune sera or by sera from autochthonous immune cats. The comparative importance of humoral and cellular cytotoxic mechanisms against FeLV- and FeSV-induced tumors is discussed.", "journal": "Cellular immunology", "doi": "10.1016/0008-8749(83)90221-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6314629", "author": "Kociba GJ", "n_authors": 4, "title": "Serum erythropoietin changes in cats with feline leukemia virus-induced erythroid aplasia.", "abstract": "Erythropoietin concentrations were increased significantly (p less than 0.025) in nine cats with natural feline leukemia virus infection and associated erythroid aplasia compared to six clinically normal cats. Adult cats experimentally inoculated with the Kawakami-Theilen isolate of feline leukemia virus developed a progressive simultaneous increase in erythropoietin activity and decrease in packed cell volume. These findings indicate that erythroid aplasia associated with feline leukemia virus infection is not caused by a failure in erythropoietin production.", "journal": "Veterinary pathology", "doi": "10.1177/030098588302000506", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6312085", "author": "Naharro G", "n_authors": 6, "title": "Molecular cloning of integrated Gardner-Rasheed feline sarcoma virus: genetic structure of its cell-derived sequence differs from that of other tyrosine kinase-coding onc genes.", "abstract": "Gardner-Rasheed feline sarcoma virus (GR-FeSV) is an acute transforming retrovirus which encodes a gag-onc polyprotein possessing an associated tyrosine kinase activity. The integrated form of this virus, isolated in the Charon 21A strain of bacteriophage lambda, demonstrated an ability to transform NIH/3T3 cells at high efficiency upon transfection. Foci induced by GR-FeSV DNA contained rescuable sarcoma virus and expressed GR-P70, the major GR-FeSV translational product. The localization of long-terminal repeats within the DNA clone made it possible to establish the length of the GR-FeSV provirus as 4.6 kilobase pairs. The analysis of heteroduplexes formed between lambda feline leukemia virus (FeLV) and lambda GR-FeSV DNAs revealed the presence of a 1,700-base-pair FeLV unrelated segment, designated v-fgr, within the GR-FeSV genome. The size of this region was sufficient to encode a protein of approximately 68,000 daltons and was localized immediately downstream of the FeLV gag gene coding sequences present in GR-FeSV. Thus, it is likely that this 1.7-kilobase-pair stretch encodes the onc moiety of GR-P70. Utilizing probes representing v-fgr, we detected homologous sequences in the DNAs of diverse vertebrate species, implying that v-fgr originated from a well-conserved cellular gene. The number of cellular DNA fragments hybridized by v-fgr-derived probes indicated either that proto-fgr is distributed over a very large region of cellular DNA or represents a family of related genes. By molecular hybridization, v-fgr was not directly related to the onc genes of other known retroviruses having associated tyrosine kinase activity.", "journal": "Journal of virology", "doi": "10.1128/JVI.47.3.611-619.1983", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6311020", "author": "Maeda S", "n_authors": 5, "title": "Immunohistologic detection of antigen related to primate type C retrovirus p30 in normal human placentas.", "abstract": "This study reports the immunohistologic detection of SSAV/GaLV type C retrovirus p30-related antigen in unfixed cryostat sections of normal human term placentas by the indirect immunofluorescence method. Goat anti-SSAV p28 serum reacted specifically with 10 of 10 anatomic specimens of human placenta. Goat anti-GaLV p29 serum reacted similarly with 8 of 10 specimens. Goat anti-BaEV p28, anti-RD-114 p28, anti-FeLV p27, anti-R-MuLV p30, and anti-MPMV p27 gave no specific reaction with placenta. The anti-SSAV p28 and anti-GaLV p29 reactive antigen was located in the placenta mainly at the basal aspect of syncytiotrophoblast near the underlying trophoblastic basement membrane where type C retroviruslike particles have been found electronmicroscopically. The specific antibody activity of anti-SSAV p28 serum against placenta was removed by critical absorption with disrupted SSAV or GaLV but not RD-114 or MuLV. These results suggest the presence in human placenta of a putative type C retroviral protein which cross-reacts with the p30 protein of the SSAV/GaLV type C retrovirus group.", "journal": "The American journal of pathology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "16030991", "author": "Jones BR", "n_authors": 3, "title": "Feline leukaemia virus testing.", "abstract": null, "journal": "New Zealand veterinary journal", "doi": "10.1080/00480169.1983.35001", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6874270", "author": "Lubin JR", "n_authors": 5, "title": "Experimental anterior uveitis after subcutaneous injection of feline sarcoma virus.", "abstract": "Feline sarcoma virus (FeSV) is a naturally occurring virus that causes spontaneous tumors in cats. The immunologic and morphologic characteristics of these tumors have been studied extensively. It was recently observed in experiments undertaken to induce systemic malignancy with this virus, that severe uveitis and clinical blindness occurred. An investigation of the ophthalmologic changes was undertaken. A fulminent anterior uveitis was produced in cats by a series of subcutaneous injections of live FeLV-FeSV. This intraocular inflammation occurred in five of six animals using high viral titers, and four of seven with lower titers, resulting from the freeze thaw process. On histopathologic examination, most animals demonstrated dysplastic changes of the ciliary body in addition to the iridocyclitis. The remainder of the eye was unaffected. These animals developed systemic tumors unaccompanied by local inflammation, many of which spontaneously regressed. Notable features of this potential model for uveitis are that (1) direct injection into the eye is unnecessary, and (2) intravenous administration inducing immune tolerance with antigenic overload presented to the spleen is avoided. This inflammatory reaction seems to be specific to the iris and ciliary body. Levels of live virus detected in the aqueous humor exceeded those in the serum. These results suggest that the virus may be actively secreted by the ciliary epithelium, or may preferentially proliferate within the eye.", "journal": "Investigative ophthalmology & visual science", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6312876", "author": "Jameson P", "n_authors": 2, "title": "Inhibition of feline leukemia virus replication by human leukocyte interferon.", "abstract": "The replication of feline leukemia virus (FeLV) is inhibited by treatment of cat cell cultures with crude human leukocyte interferon (HuIFN-alpha) as evidenced by titration of the infectious progeny. The inhibition can be demonstrated in three different cell lines in which the production of hemagglutinin by encephalomyocarditis (EMC) virus, and plaque formation by vesicular stomatitis virus (VSV) are also inhibited by the HuIFN-alpha. The dose dependency of the inhibition of EMC virus by the HuIFN-alpha is similar to that obtained with feline interferon in each of the three cell lines. VSV and EMC virus are less than 10 times more sensitive than FeLV to the inhibitory action of HuIFN-alpha if responses to a single interferon treatment are compared for each of the viruses tested in the most sensitive cell line, FEA. The interferon effect on FeLV is more pronounced when it is added within one day after the inoculation of the cells rather than applied before cell infection. The induction of focus formation by FeLV can also be inhibited by HuIFN-alpha in cat cells (CCC-81) which contain the murine sarcoma virus genome.", "journal": "Antiviral research", "doi": "10.1016/0166-3542(83)90033-5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6850643", "author": "Rasheed S", "n_authors": 1, "title": "Characterization of a differentiated cat melanoma cell line.", "abstract": "We have established several long-term cultures of a naturally occurring metastatic melanoma of a domestic cat. The cells are fully differentiated as indicated by the Fontana-Masson staining of the melanin in the perinuclear region and by electron microscopy of the cytoplasmic melanosomes in various stages of development. The melanoma cells do not produce virus particles or the major core proteins (i.e., protein with a molecular weight of 30,000) of the feline leukemia virus or the endogenous cat virus RD-114. Retrovirus is also not induced when melanoma cultures are treated with 5-iodo-2'-deoxyuridine or bromodeoxyuridine and cocultivated with susceptible cells. Treatment of cells with N6,O2'-dibutyryl cyclic adenosine 3' :5'-monophosphate or theophyllin, however, accentuates melanin production and increases the number of pigmented cells. The cultured cells develop melanotic tumors in s.c. inoculated newborn cats and athymic nude mice. As far as we can ascertain, this is the first report of a spontaneous malignant melanoma of a cat which provides an important resource for studying cell differentiation in vitro.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6306469", "author": "Besmer P", "n_authors": 6, "title": "The Hardy-Zuckerman 2-FeSV, a new feline retrovirus with oncogene homology to Abelson-MuLV.", "abstract": "There is substantial evidence that oncogenes (v-onc) of acute transforming retroviruses have been acquired by transduction of cellular genes (c-onc) with retroviruses. Feline leukaemia virus (FeLV)-associated feline fibrosarcomas have proven to be extremely useful for the isolation of acute transforming retroviruses of a mammalian species. Three different v-onc genes have been identified in five acute transforming feline retroviruses. The Susan McDonough feline sarcoma virus (SMFeSV) contains the oncogene fms (ref. 4). The Snyder-Theilen (ST) and Gardner-Arnstein (GA) FeSVs contain the oncogene fes (ref. 4), which is homologous to the oncogene fps of the avian sarcoma viruses FSV, RRCII, PRCIV and 16L (refs 7, 8). The v-onc sequences of the Parodi-Irgens (PI) FeSV have recently been found to be homologous with the v-sis sequences of the simian sarcoma virus. We report here the isolation of another acute transforming feline retrovirus from a naturally occurring feline fibrosarcoma, designated the Hardy-Zuckerman 2 feline sarcoma virus (HZ2-FeSV) and demonstrate that the HZ2-FeSV and Abelson murine leukaemia virus (A-MuLV) have homologous oncogenes.", "journal": "Nature", "doi": "10.1038/303825a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6305890", "author": "Azocar J", "n_authors": 3, "title": "Cell culture density modulates the incorporation of HLA antigens by enveloped viruses.", "abstract": "Uninfected, as well as feline leukemia virus (FeLV) infected human cells cultured under high cell density conditions undergo changes in the expression of major histocompatibility complex (MHC) antigens, as determined by indirect trace binding radio immunoassay (RIA) using monoclonal anti-HLA antibodies and by decreased sensitivity to complement mediated cytotoxicity by anti-HLA alloantibodies. FeLV particles produced by the viral infected cells are also sensitive to neutralization by anti-HLA antibodies, suggesting that enveloped viral particles incorporated MHC antigens in the viral envelope. The amount of HLA antigens expressed in the viral enveloped, closely reflects the expression of HLA antigens by the virus-producer lymphoid cells. FeLV-infected HsB-2 (T) and SB (B) lymphoid cells cultured under high cell concentration condition show decreased expression of some HLA antigens (A2, B12, B17), and the viral particles produced by those cells also incorporate lower amounts of such antigens. Our results, based on the findings that human lymphoid cells (uninfected, as well as FeLV infected) show decreased expression of some HLA membrane determinants when grown under high cell density conditions, indicate that no viral selective mechanism operates in the incorporation of HLA determinants by enveloped viruses. Instead, our results suggest that viruses pick up MHC antigens from the host cell membrane according to the concentration of those antigens on the surface of the cells at the time of virus budding.", "journal": "Human immunology", "doi": "10.1016/s0198-8859(83)80006-8", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6304347", "author": "Elder JH", "n_authors": 2, "title": "Nucleotide sequence of the envelope gene of Gardner-Arnstein feline leukemia virus B reveals unique sequence homologies with a murine mink cell focus-forming virus.", "abstract": "The nucleotide sequence of the envelope gene and the adjacent 3' long terminal repeat (LTR) of Gardner-Arnstein feline leukemia virus of subgroup B (GA-FeLV-B) has been determined. Comparison of the derived amino acid sequence of the gp70-p15E polyprotein to those of several previously reported murine retroviruses revealed striking homologies between GA-FeLV-B gp70 and the gp70 of a Moloney virus-derived mink cell focus-forming virus. These homologies were located within the substituted (presumably xenotropic) portion of the mink cell focus-forming virus envelope gene and comprised amino acid sequences not present in three ecotropic virus gp70s. In addition, areas of insertions and deletions, in general, were the same between GA-FeLV-B and Moloney mink cell focus-forming virus, although the sizes of the insertions and deletions differed. Homologies between GA-FeLV-B and mink cell focus-forming virus gp70s is functionally significant in that they both possess expanded host ranges, a property dictated by gp70. The amino acid sequence of FeLV-B contains 12 Asn-X-Ser/Thr sequences, indicating 12 possible sites of N-linked glycosylation as compared with 7 or 8 for its murine counterparts. Comparison of the 3' LTR of GA-FeLV-B to AKR and Moloney virus LTRs revealed extensive conservation in several regions including the \"CCAAT\" and Goldberg-Hogness (TATA) boxes thought to be involved in promotion of transcription and in the repeat region of the LTR. The inverted repeats that flanked the LTR of GA-FeLV-B were identical to the murine inverted repeats, but were one base longer than the latter. The region of U3 corresponding to the approximately 75-nucleotide \"enhancer sequence\" is present in GA-FeLV-B, but contains deletions relative to AKR and Moloney virus and is not repeated. An interesting pallindrome in the repeat region immediately 3' to the U3 region was noted in all the LTRs, but was particularly pronounced in GA-FeLV-B. Possible roles for this structure are discussed.", "journal": "Journal of virology", "doi": "10.1128/JVI.46.3.871-880.1983", "deposited_data": "Sim", "nuccore_ids": "61524", "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6304345", "author": "Soe LH", "n_authors": 4, "title": "Molecular cloning and characterization of endogenous feline leukemia virus sequences from a cat genomic library.", "abstract": "Recombinant bacteriophage lambda clones from a cat genomic library derived from placental DNA of a specific pathogen-free cat were screened to identify endogenous feline leukemia virus (FeLV) sequences. Restriction endonuclease mapping of four different clones indicates that there are a number of similarities among them, notably the presence of a 6.0- to 6.4-kilobase pair (kbp) EcoRI hybridizing fragment containing portions of sequences homologous to the gag, pol, env, and long terminal repeat-like elements of the infectious FeLV. The endogenous FeLV sequences isolated are approximately 4 kbp in length and are significantly shorter than the cloned infectious FeLV isolates, which are 8.5 to 8.7 kbp in length. The endogenous elements have 3.3- to 3.6-kbp deletions in the gag-pol region and approximately 0.7- to 1.0-kbp deletions in the env region. These deletions would render them incapable of encoding an infectious virus and may therefore be related to the non-inducibility of FeLV from uninfected cat cells and the subgenomic expression of these endogenous sequences in placental tissue. It appears that there is conservation in the ordering of restriction sites previously reported in the proviruses of the infectious FeLVs in sequences corresponding to the pol and env boundary as well as the region spanning the env gene of the endogenous clones, whereas a greater divergence occurs among restriction sites mapped to the gag and part of the pol regions of the infectious FeLV. Such deleted, FeLV-related subsets of DNA sequences could have originated either by germ-line integration of a complete ecotropic virus followed by deletion, or by integration of a preexisting, defective, deleted variant of the infectious virus.", "journal": "Journal of virology", "doi": "10.1128/JVI.46.3.829-840.1983", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6302837", "author": "Trainin Z", "n_authors": 4, "title": "Suppression of the humoral antibody response in natural retrovirus infections.", "abstract": "The feline leukemia virus (FeLV) frequently causes death by predisposing the host to acute infections by other pathogens rather than by inducing leukemia. In a previous study, cats infected with FeLV were found to have prolonged homograft rejection responses but there was no evidence that the humoral immune response was impaired. In the present study, the humoral response to the synthetic multichain polypeptide (L-tyrosine-L-glutamic acid)-poly-DL-alanine-poly-L-lysine, denoted (T.G)AL, was found to be significantly depressed in healthy cats that were naturally infected with FeLV compared to uninfected controls. In cats with persistent FeLV viremia the major antibody response to (T.G)AL, normally seen at days 9 to 14 after immunization, was both delayed and greatly reduced.", "journal": "Science (New York, N.Y.)", "doi": "10.1126/science.6302837", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6852979", "author": "McCarty JM", "n_authors": 2, "title": "Cellular immune response in the blood of cats is restricted to autochthonous feline sarcoma virus-transformed cells.", "abstract": "The blood-borne cytotoxic cellular immune response of cats to autochthonous fibroblasts transformed with feline sarcoma virus (FeSV) was examined. Peripheral blood lymphocytes (PBL) from immune animals were assayed for cytotoxic activity using a 51Cr release microcytotoxicity assay. The time courses for appearance of cytotoxic cells were similar for all cats: effector lymphocytes appeared in the blood 7 days after immunization; peak activity occurred about day 16, and cytotoxic PBL were no longer detectable by 35 days. The specificity of cytotoxic lymphocytes was studied using autochthonous and allogeneic targets. PBL from each of five immunized cats killed autochthonous transformed fibroblast (ATF) targets, but the immune lymphocytes were not cytotoxic for non-transformed autochthonous fibroblasts, for allogeneic fibroblasts transformed with FeSV, or for an allogeneic lymphoma cell line which produces feline leukemia virus (FeLV). Specific restriction of target-cell killing to the ATF occurred at all effector:target-cell ratios tested, and was maintained throughout prolonged assay incubation periods. The results suggest that for cytotoxicity to occur it is necessary for the immune lymphocytes to recognize a combination of virus-associated antigens and \"self\" antigens on the ATF. The similarities between this restricted killing and that caused by cytotoxic T lymphocytes in other mammalian systems are discussed.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910310515", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6302323", "author": "Besmer P", "n_authors": 5, "title": "The Parodi-Irgens feline sarcoma virus and simian sarcoma virus have homologous oncogenes, but in different contexts of the viral genomes.", "abstract": "We have identified the oncogene and the putative transforming protein of the Parodi-Irgens feline sarcoma virus (PI-FeSV). The PI-FeSV is defective and needs a helper virus for its replication. The v-onc sequences in the PI-FeSV were found to be related to the v-sis sequences of the simian sarcoma virus (SSV). PI-FeSV nonproducer cells express two viral RNAs, a 6.8-and a 3.3-kilobase RNA. The 6.8-kilobase RNA contains gag, sis, and env sequences but lacks the pol gene. The 3.3-kilobase RNA, on the other hand, contains only env sequences. We have detected one feline leukemia virus-related protein product in these cells, namely, a 76-kilodalton protein which contains determinants of the feline leukemia virus gag proteins p15 and p30. The v-sis sequences in the PI-FeSV have been located near the 5' end of the viral genome. Taken together, these results imply that the p76 protein contains both feline leukemia virus gag and sis sequences and probably is the transforming protein of this virus. In contrast, in SSV the sis sequences are located towards the 3' end of the viral genome, and the sis protein is thought to be expressed via a subgenomic RNA. PI-FeSV and SSV therefore use different schemes to express their onc-related sequences. The v-sis sequences in the PI-FeSV contain restriction sites which reflect the different origin of the v-sis sequences in the PI-FeSV and SSV. The homologous oncogenes of the PI-FeSV and SSV thus were transduced by two different retroviruses, feline leukemia virus and the simian sarcoma-associated virus, apparently from the genomes of different species.", "journal": "Journal of virology", "doi": "10.1128/JVI.46.2.606-613.1983", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6299534", "author": "Langweiler M", "n_authors": 3, "title": "Role of suppressor cells in feline leukemia virus-associated immunosuppression.", "abstract": "Protein from detergent-disrupted feline leukemia virus was found to suppress lymphocyte blastogenic responsiveness of peripheral blood mononuclear cells from normal cats. When suppressive doses of this protein were substituted for mitogen in the preactivation step of the concanavalin A-induced suppressor cell assay, significant suppression was observed in five of eleven cats tested. These results suggest that feline leukemia virus-associated immunosuppression may be mediated by a virus-induced suppressor cell.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6304986", "author": "Madewell BR", "n_authors": 2, "title": "Recovery of feline leukaemia virus from non-viraemic cats.", "abstract": "The persistence of virus in the bone marrow of cats which had ostensibly recovered from feline leukaemia virus (FeLV) infection was investigated. Nineteen cats were exposed to FeLV by natural, contact infection and 36 weeks later three were found to be persistently viraemic while the remainder were non-viraemic and had virus neutralising serum antibodies. Virus was isolated in bone marrow cultures established from nine of the 16 non-viraemic cats which were considered, therefore, to have latent infections. Cats infected soon after exposure to FeLV carrier cats were more likely to become persistently viraemic or develop a latent infection than those infected later, which tended to recover. There was no difference in serum antibody levels between the latently infected and recovered cats. Whether cats with latent infections spread virus or develop FeLV-negative haemopoietic tumours was considered. Six kittens housed together for eight months with a cat with a latent infection showed no signs of having been exposed to FeLV. Virus was not isolated from bone marrow cultures of two cats with FeLV-free lymphosarcoma or myelomonocytic leukaemia.", "journal": "The Veterinary record", "doi": "10.1136/vr.112.15.339", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6300313", "author": "Stiff MI", "n_authors": 2, "title": "Effects of retrovirus protein on the feline one-way mixed leukocyte reaction.", "abstract": "The objective of this study was to evaluate the effects of feline retrovirus protein on cat lymphocyte recognition of allogeneic cells in the mixed leukocyte reaction (MLR), using u.v.-inactivated feline leukaemia virus (FeLV) and a non-disease-producing endogenous cat virus (RD-114). Twenty micrograms of u.v.-inactivated virus protein from each virus were added to mixed leukocyte cultures. FeLV induced significant suppression of the MLR (P less than 0.005) whereas no significant suppression was found using RD-114. Since feline leukaemia infection is associated with immunosuppression, the retrovirus proteins may be interfering with the response of immunocompetent cells when they are confronted with an altered host cell.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-64-4-957", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6298455", "author": "Morgan MA", "n_authors": 3, "title": "Structural and antigenic analysis of the nucleic acid-binding proteins of bovine and feline leukemia viruses.", "abstract": "The nucleic acid-binding proteins of bovine leukemia virus (BLV) and feline leukemia virus (FeLV) were isolated in a high state of purity with chloroform-methanol extraction followed by reversed-phase liquid chromatography. Selective solubilization and purity of BLV p12 and FeLV p10 was confirmed by sodium dodecyl sulfate-polyacrylamide gel electrophoresis. The compositions and molecular weights were determined by amino acid analysis. An abundance of lysine and arginine residues along with their size identifies both BLV p12 and FeLV p10 as small basic proteins similar to well-defined type C viral nucleoproteins. NH2-terminal degradation by the semiautomated Edman method provided the sequence of the first 40 amino acids for both proteins. The putative nucleic acid binding site found in several type C viral nucleoproteins was contained within this sequence, with the most homology centered around an eight-amino acid region involving seven identical residues and one substitution. Antisera were developed in rabbits, and specificity and titers were determined by electroblotting and immunoautoradiography. By this technique, an immunological cross-reaction was found between BLV p12 and FeLV p10. The shared antigenic determinant most likely exists in the highly conserved eight-amino acid region. Although this sequence is also highly conserved in the nucleic acid-binding proteins of murine leukemia viruses, the shared antigenic determinant is not found in these or any other type C viruses tested. It is suggested that substitution of arginine (BLV p12/FeLV p10) to lysine (murine leukemia virus p10) is sufficient to elicit a change in antibody specificity.", "journal": "Journal of virology", "doi": "10.1128/JVI.46.1.177-186.1983", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6688827", "author": "van der Riet FD", "n_authors": 4, "title": "Lymphosarcoma in a cat.", "abstract": "Feline leukaemia virus (FeLV) antigen was detected in a cat from Cape Town which was subjected to euthanasia after a long history of upper respiratory infection and progressive emaciation. Based on the necropsy findings and subsequent histopathological examinations, a diagnosis of lymphosarcoma was made. It is regarded as likely that this tumour was caused by infection with FeLV.", "journal": "Journal of the South African Veterinary Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6301316", "author": "Madewell BR", "n_authors": 3, "title": "Ferrokinetic and erythrocyte survival studies in healthy and anemic cats.", "abstract": "Erythrocyte survival and ferrokinetic studies were adapted to the cat. For 5 clinically healthy 4- to 9-month-old cats, mean 51Cr-labeled erythrocyte survival was 144 hours, and mean plasma 59Fe-labeled transferrin disappearance halftime was 51 minutes. Erythrocyte use of radioiron was rapid and efficient, with 50% to 80% of labeled iron incorporated into the erythron by 100 hours after injection into the cat. Six cats with feline leukemia virus infection were studied. For 2 cats with erythroid aplasia associated with C subgroup of feline leukemia virus, erythrocyte survival times were similar to those determined for the healthy cats, but plasma radioiron disappearance half time and erythrocyte use of radioiron were markedly diminished.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6301150", "author": "Groffen J", "n_authors": 5, "title": "Transforming genes of avian (v-fps) and mammalian (v-fes) retroviruses correspond to a common cellular locus.", "abstract": "The Gardner (GA) and Snyder-Theilen (ST) isolates of feline sarcoma virus (FeSV) represent genetic recombinants between feline leukemia virus (FeLV) and transformation-specific sequences (v-fes gene) of cat cellular origin. A related transforming gene (v-fps), common to the Fujinami, PRC II, and UR 1 strains of avian sarcoma virus has also been described. Translational products of each of these recombinant virus isolates are expressed in the form of polyproteins exhibiting protein kinase activities with specificity for tyrosine residues. In the present study, v-fes and v-fps homologous sequences of GA-FeSV, ST-FeSV, and Fujinami sarcoma virus (FSV) are defined and these independently derived transforming genes are shown to correspond to a common cellular genetic locus which has remained highly conserved throughout vertebrate evolution.", "journal": "Virology", "doi": "10.1016/0042-6822(83)90219-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6186079", "author": "Vedbrat SS", "n_authors": 7, "title": "Feline oncornavirus-associated cell membrane antigen: a viral and not a cellularly coded transformation-specific antigen of cat lymphomas.", "abstract": "The feline oncornavirus-associated cell membrane antigen (FOCMA) was defined as a tumor antigen common to cat lymphomas and fibrosarcomas induced by feline leukemia virus (FeLV) and feline sarcoma virus (FeSV), respectively. The antigen was recognized by sera from cats thought to be resistant to leukemogenesis. We report here that a common denominator in the activity of naturally occurring viremic cat antisera to FOCMA is, in fact, their reactivity to FeLV C antigenic determinants. The cat antisera, monoclonal antibodies to FOCMA, and monoclonal antibodies to FeLV C, all reacted in immunofluorescence assays with FeLV C-infected cells and immunoprecipitated a molecule electrophoretically indistinguishable from envelope glycoprotein of FeLV. Viremic cat antisera to FOCMA bound to budding virus particles of FeLV C-infected cells, even though some of them could not be absorbed by mature virion proteins. Thus, the unusual feature of cat antibodies to FOCMA is their binding to nascent but not to mature virus particles. FOCMA-positive cat lymphomas expressed antigenic determinants of FeLV-C gp70, with or without productive infection. FeLV-negative tumors not expressing FeLV C gp70 were also FOCMA negative. Furthermore, most of the viremic cat sera and the monoclonal antibodies to FOCMA did not react with FeSV-transformed nonproducer cells. The absence of FOCMA from these cells and from FeLV-negative lymphoid tumors and its presence in FeLV-C infected fibroblasts indicated that this antigen is virus encoded and not a cellular tumor-specific antigen.", "journal": "Virology", "doi": "10.1016/0042-6822(83)90360-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6186744", "author": "Lutz H", "n_authors": 4, "title": "Monoclonal antibodies to three epitopic regions of feline leukemia virus p27 and their use in enzyme-linked immunosorbent assay of p27.", "abstract": "Three different monoclonal antibodies were developed against the major core protein (p27) of feline leukemia virus (FeLV). Each antibody was directed against a different epitope of the species-specific portion of FeLV-p27. The 3 antibodies reacted with 5 different isolates of FeLV but not with 7 other retroviruses (MuLV (Rauscher), MuLV (AKR), MPMV, MMTV, SMRV, BAEV, RD 114). These monoclonal antibodies could readily be adapted to an enzyme-linked immunosorbent assay (ELISA) for the specific measurement of FeLV-p27. When compared in an ELISA with conventional reagents, the battery of monoclonal antibodies proved to be as sensitive as conventional polyclonal antibodies.", "journal": "Journal of immunological methods", "doi": "10.1016/0022-1759(83)90413-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6329934", "author": "Busch MP", "n_authors": 6, "title": "Characterization of the expression of cellular retrovirus genes and oncogenes in feline cells.", "abstract": "Expression of endogenous retrovirus genes and two different cellular oncogenes (c-onc genes) was examined at the transcriptional level in a variety of normal and lymphoma/leukemia tissues of the domestic cat. The two oncogenes, c-myb(related to avian myeloblastosis virus) and c-myc(related to avian myelocytomatosis virus) were selected for their association with the induction of hematopoietic malignancies, when present in the transforming retroviruses. Tissue-specific expression of endogenous feline leukemia virus (FeLV)-related genes was detected in cellular subpopulations of the cat placenta by in situ method of hybridization. Gel blotting analysis of placental poly(A)-selected RNA revealed that the FeLV-related RNA species were primarily subgenomic, representing the env gene region of the endogenous provirus elements. Like the endogenous retrovirus genes, c-myb and c-myc loci of the cat genomic DNA were also transcribed at differential levels in normal tissues of the cat. Dot-blot hybridization analysis showed that the expression of these two oncogenes was linked to growth and development as it varied with the gestational age of the fetus and from fetal to adult tissues. Among the major hematopoietic organs, spleen and bone marrow contained both c-myb and c-myc transcripts, while thymus preferentially expressed the c-myb gene. In contrast to the low level of c-myc expression in fetal thymus tissues, enhanced c-myc expression was detected in all five thymomas tested and also in several other neoplasms including two granulocytic leukemias. The feline c-myb gene was not very active in granulocytic leukemias or in three of the five thymomas. RNA gel blotting analysis of poly(A)-selected RNA of a thymoma and its lymph node metastasis showed identical pattern of c-myc transcripts.", "journal": "Hematological oncology", "doi": "10.1002/hon.2900010108", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6321156", "author": "Wünsch M", "n_authors": 5, "title": "Sequence analysis of Gardner-Arnstein feline leukaemia virus envelope gene reveals common structural properties of mammalian retroviral envelope genes.", "abstract": "We have sequenced the envelope (env) gene and most of the adjacent 3' long terminal repeat (LTR) of Gardner-Arnstein feline leukaemia virus subtype B. The LTR of this virus contains, at corresponding positions, all signal sequence elements known from other retroviral LTRs. The deduced amino acid sequence of the longest open reading frame was compared with env polypeptide sequences of several murine leukaemia viruses. This allowed us to predict the positions of both p12/15env and gp70 polypeptides as well as a hydrophobic leader polypeptide. The env polypeptides of the different viruses show long stretches of homology and similar hydrophilicity profiles in the p12env region and in the carboxy-terminal half of gp70 (constant region). The most extensive variations are confined to certain parts of the amino-terminal half of gp70 (differential region). In this region, however, feline leukaemia virus and murine mink cell focus forming viruses are still closely related. A correspondingly spaced pattern of identical, short amino acid sequences appears in three different parts of the env polyprotein, suggesting its evolution from a primordial env-related precursor by tandem duplications.", "journal": "The EMBO journal", "doi": "10.1002/j.1460-2075.1983.tb01729.x", "deposited_data": "Sim", "nuccore_ids": "61518", "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6320992", "author": "Snyder HW Jr", "n_authors": 2, "title": "Association of the transforming proteins of the ST and GA strains of feline sarcoma virus and their in vitro associated protein kinase activities with cellular membranes.", "abstract": "The translation products of the Snyder-Theilen (ST) and Gardner-Arnstein (GA) strains of feline sarcoma virus (FeSV), termed gag-fes proteins, are high molecular weight polyproteins containing different amounts of the amino terminus of the feline leukemia virus (FeLV) gag gene-coded precursor protein linked to a similar sarcoma virus-specific polypeptide. Both polyproteins are phosphoproteins with indistinguishable in vitro associated tyrosine-specific protein kinase activities. The polyproteins are extremely hydrophobic proteins which are intimately associated with the plasma membrane fraction of transformed cells. Approximately 10% of the proteins are modified by glycosylation and expressed on the cell surface where they are accessible to lactoperoxidase-mediated radio-iodination and trypsinization. Cell surface localization of the polyproteins does not appear to be necessary for transformation. However, preliminary evidence suggests that the amount of FeLV p30 sequences at the amino end of the proteins may have some effect on the intracellular distribution of the gag-fes polyproteins and on the phenotype of the transformed cell.", "journal": "Cancer investigation", "doi": "10.3109/07357908309041362", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6308016", "author": "Veronese F", "n_authors": 5, "title": "Monoclonal antibodies to feline sarcoma virus gag and fes gene translational products.", "abstract": "A series of hybridomas have been isolated which produce monoclonal antibodies directed against polyprotein gene products of the Gardner, Snyder-Theilen, and McDonough strains of FeSV. Within these are representatives of several immunoglobulin classes including IgG1, IgG2a, IgG2b, and IgM. Antibody produced by one hybridoma recognizes immunologic determinants localized within an FeLV gag gene structural component (p15) common to polyproteins encoded by all three FeSV isolates whereas antibody produced by a second is specific for p30 determinants unique to P170gag-fms. Additional hybridomas secrete antibody directed against v-fes-encoded determinants common to the Gardner and Snyder-Theilen FeSV-encoded polyproteins. GA P110gag-fes and ST P85gag-fes immuno-precipitated by antibody directed against p15 exhibit tyrosine-specific protein kinase activity but lack such activity when precipitated by antibody specific for their acquired sequence (v-fes) components.", "journal": "Journal of cellular biochemistry", "doi": "10.1002/jcb.240210103", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6306490", "author": "Lizonová A", "n_authors": 2, "title": "Circulating antibodies to the feline leukemia virus and FOCMA in cats.", "abstract": "Presence of antibodies to the structural proteins of the feline leukemia virus and the feline oncornavirus-associated cell membrane antigen FOCMA was analyzed in sera of 120 cats from household environments. In our experiments 35% of the sera tested were positive with the viable cells of FL-74 feline lymphoma cell line. On the other hand, only 5% of the feline sera reacted with FeLV from FL-74 cells in the solid phase RIA. Selected positive sera were analyzed for the presence of antibodies to the viral structural proteins of FeLV and FOCMA in lysates of FL-74 cells by radioimmunoprecipitation. Absorption of the selected sera (reacting with viable FL-74 cells) with disrupted FeLV had a negligible effect on the precipitating activity of the 70000 protein.", "journal": "Neoplasma", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6304480", "author": "Hunsmann G", "n_authors": 4, "title": "Active immunization with feline leukemia virus envelope glycoprotein suppresses growth of virus-induced feline sarcoma.", "abstract": "The efficiency was examined of immunization with feline leukemia virus glycoprotein complexes (gp85 rosettes) to protect cats against tumors induced by feline sarcoma virus (FeSV). The glycoprotein was isolated from feline leukemia virus (FeLV). Young cats were vaccinated with the purified viral glycoprotein and challenged with FeSV (FeLV). FeLV gp85 antibody levels were measured by enzyme-linked immunosorbent assay and tumor volumes were determined. In immunized animals tumor development was reduced. Gp85 antibody levels before challenge were correlated inversely with tumor size (r2 = 0.79). This method appears to be suitable for fast and efficient testing of future FeLV vaccines.", "journal": "Medical microbiology and immunology", "doi": "10.1007/BF02123497", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6304428", "author": "Testa NG", "n_authors": 5, "title": "Haemopoietic colony formation (BFU-E, GM-CFC) during the development of pure red cell hypoplasia induced in the cat by feline leukaemia virus.", "abstract": "The GM-CFC assay for granulocyte-macrophage progenitors and the BFU-E and CFU-E assay for early and late erythroid progenitors from cat bone marrow were characterized. GM-CFC gave 59 +/- 4 to 118 +/- 6 colonies per 10(5) bone marrow cells using colony stimulating factors (CSF) from cat, mouse or human sources. The CFU-E and BFU-E assays gave 114 +/- 7 and 58 +/- 7 colonies respectively with optimum doses of erythropoietin. Irradiated cat bone marrow cells were good sources of CSF and of burst promoting activity for these assays. Kittens infected with feline leukaemia virus, subgroup C (FeLV-C), which induces pure red cell hypoplasia, showed the incidence of BFU-E decreased to 25-35% of controls as early as one week postinfection, and even lower values at later times. In contrast, the incidence of GM-CFC remained normal for several weeks. No evidence of inhibitory cells or of lack of stimulatory cells in the infected marrows was seen when they were cultured together with normal marrow in the BFU-E assay. Conversely, normal marrow cells were not able to restore BFU-E growth from infected marrow. This suggests a direct action of FeLV-C on early erythroid precursors. Infection with FeLV, subgroup A, which induces only a mild transitory anaemia, produces only a moderate decrease in the incidence of BFU-E.", "journal": "Leukemia research", "doi": "10.1016/0145-2126(83)90001-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6299244", "author": "Pal BK", "n_authors": 2, "title": "Mink type C virus: biochemical characterization of the structural polypeptides.", "abstract": "Mink type C virions contained six major protein species of approximate M.W. of 90,000, 70,000, 30,000, 15,000, 12,000 and 10,000. The two largest polypeptides were glycosylated and the 12,000 M.W. polypeptide was the major phosphoprotein of the virion. Two-dimensional tryptic peptide map of the 30,000 M.W. major structural protein of MiLV showed a pattern distinct from those of analogous proteins from mouse and endogenous cat type C viruses. Significant peptide homology of this protein was, however, found with the corresponding protein of infectious feline type C virus (FeLV).", "journal": "Archives of virology", "doi": "10.1007/BF01314138", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6197953", "author": "Goldschmied-Reouven A", "n_authors": 3, "title": "Hamster endogenous retrovirus (HaER)--distinct properties of structural proteins and DNA polymerase.", "abstract": "The structural proteins as well as some features of the RNA-dependent DNA polymerase of the hamster endogenous retrovirus (HaER) were examined. The polypeptide pattern of this virus is substantially different from that of other known retroviruses in containing major polypeptides with molecular weights of 68,000, 59,000, 27,000 and 24,000 daltons. Double antibody competitive radioimmunoassays showed that the HaER particles do not share any detectable antigenic relatedness with the murine viruses' p30, but manifest a considerable relatedness with the feline leukemia virus p27 and a slight cross-reactivity with the rat virus major protein. The RNA-dependent DNA polymerase of HaER virus has a molecular size of approximately 73,000 daltons and in contrast to other mammalian retroviruses shows no significant preference for Mn2+ over Mg2+. Apart from the lack of antigenic relatedness between the HaER virus proteins and the p30 protein of murine viruses, there is also no antigenic relatedness between HaER and murine viruses insofar as their DNA polymerase is concerned.", "journal": "Archives of virology", "doi": "10.1007/BF01311319", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6099323", "author": "Roach A", "n_authors": 3, "title": "Transcription and expression of the herpes simplex virus tk gene inserted into proviral sequences of feline leukemia virus.", "abstract": "Recombinant DNA molecules containing the herpesvirus tk gene inserted near the middle of a cloned feline leukemia virus proviral genome, in the same transcriptional orientation as the long terminal redundancies (LTRs), were used to transform human tk- cells. Analysis of RNA from cloned lines indicates that the 5' LTR promotes a high level of transcription which, as a result of differing RNA splicing and polyadenylation pathways, results in three large, abundant RNAs, two of which contain the entire tk coding region. The tk promoter itself initiates transcription of a smaller, relatively rare tk mRNA, of the same length and abundance as found in cells transformed with the tk gene alone. Assays indicate that there is little if any thymidine kinase (TK) enzymatic activity contributed by the abundant LTR-promoted transcripts. This is presumably due to inefficient initiation of tk translation from the longer LTR-initiated transcripts because of upstream AUG codons in the viral sequences. RNA blots indicate that the viral LTR is stronger as a promoter than the tk promoter. The results also indicate that about one-third of the LTR-initiated transcripts are polyadenylated at the tk poly(A) site, while the rest use the poly(A) site of the 3' LTR.", "journal": "Gene", "doi": "10.1016/0378-1119(84)90014-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6096331", "author": "Meric SM", "n_authors": 1, "title": "Suspected feline leukemia virus infection and pancytopenia in a western cougar.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6097009", "author": "Loar AS", "n_authors": 1, "title": "The management of feline lymphosarcoma.", "abstract": "Lymphoma may occur in almost any site, in a cat of any age, in either a FeLV-infected or uninfected animal. As the most common tumor type found in this species, LSA should be included in the differential diagnosis for virtually any clinical problem in any body system. For the unusual forms of this malignancy, just as for the more common types, the prognosis and response to cytotoxic therapy is generally based on the pretreatment volume and location of the tumor, as well as on the overall status of the cat. Dramatic differences have been noted in the sensitivities of some of the various forms of LSA to conventional chemotherapy. Recognizing these differences and managing our patients and their owners accordingly should make the treatment of this disease far more rewarding.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": "10.1016/s0195-5616(84)50160-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6208683", "author": "Ziemiecki A", "n_authors": 9, "title": "Biological and biochemical characterization of a new isolate of feline sarcoma virus: Theilen-Pedersen (TP1-FeSV).", "abstract": "A new feline sarcoma virus designated Theilen-Pedersen (TP1-FeSV) has been isolated from a spontaneous, slowly growing fibrosarcoma of a domestic short-haired 4-year-old castrated cat. The virus codes for a gag-onc fusion protein of 83,000 molecular weight phosphorylated in vivo at serine, threonine, and tyrosine residues. Cells transformed in vitro with TP1-FeSV exhibit five- to 10-fold elevated levels of phosphotyrosine over FeLV-infected cells. The gag-onc polyprotein has associated with it a tyrosyl protein kinase activity which in vitro results in autophosphorylation of the molecule at tyrosine residues. The fusion protein cannot be labeled metabolically with [3H]glucosamine and tunicamycin has no effect on the electrophoretic mobility of the in vivo [32P]orthophosphate-labeled fusion protein. The fusion protein, in common with the gag precursor Pr65gag, can be metabolically labeled with palmitic acid.", "journal": "Virology", "doi": "10.1016/0042-6822(84)90355-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6504011", "author": "Yates RW", "n_authors": 3, "title": "Myeloproliferative disease in a cat.", "abstract": "Myeloproliferative disorders, a complex of cytologic abnormalities arising in the bone marrow, are among domestic animals most frequently recognized in cats but are relatively uncommon. A 4-year-old female Siamese, with splenomegaly and weight loss, was listless, anorectic, pale and dehydrated. A hemogram showed severe, macrocytic normochromic anemia, leukocytosis and reticulocytosis, with abnormally high numbers of nucleated RBC and undifferentiated blast cells. Bone marrow smears contained predominantly undifferentiated blast cells, RBC precursors and myeloblasts. The fluorescent antibody test for FeLV was positive. The cat died 66 days later despite a blood transfusion and chemotherapy. Necropsy confirmed a diagnosis of myeloproliferative disease, with hepatic and splenic invasion.", "journal": "Modern veterinary practice", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6504010", "author": "Ackerman L", "n_authors": 1, "title": "Demodicosis in cats.", "abstract": "Feline demodicosis, caused by Demodex cati, may be associated with immunosuppression, as from FeLV infection or diabetes mellitus. Clinical signs include nonpruritic alopecia, scaling, erythema and hyperpigmentation in the facial region. Local topical application of 2.5% lime sulfur solution every 10 days is usually curative in a few weeks or months.", "journal": "Modern veterinary practice", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6208551", "author": "Liu WT", "n_authors": 5, "title": "Remission of leukemia and loss of feline leukemia virus in cats injected with Staphylococcus protein A: association with increased circulating interferon and complement-dependent cytotoxic antibody.", "abstract": "We have injected purified Staphylococcus aureus protein A intraperitoneally into leukemic cats infected with feline leukemia virus, into cats persistently infected with feline leukemia virus but without hematologic or cytologic abnormalities, and into healthy cats without feline leukemia virus infection. Pre- and post-treatment serum samples were evaluated sequentially for interferon activity and for complement-dependent cytotoxic antibody. Our results indicate that serum interferon increased dramatically (less than 3 to 324 units/ml) during treatment only in cats that responded to staphylococcal protein A therapy. Increase of interferon preceded or was closely associated with increasing levels of cytotoxic antibody, loss of viremia, and correction of cytological and hematological abnormalities of three leukemic cats. The cytotoxic antibody was shown to be specific for envelope glycoprotein gp70 of the feline leukemia virus. One persistently feline leukemia virus-infected cat without leukemia that became nonviremic also developed high levels of interferon and specific cytotoxic antibody. By contrast, interferon levels of cats not responding to treatment had levels of less than 3 to 27 units/ml. Normal healthy cats injected with staphylococcal protein A showed moderate transient increases of interferon but no detectable cytotoxic antibodies to FL-74 cells. These data suggest that interferon and cytotoxic antibody may play important, possibly complementary roles in inducing remission of leukemia and loss of viremia in cats treated with staphylococcal protein A.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.81.20.6471", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6095976", "author": "Dunn JK", "n_authors": 3, "title": "The diagnostic significance of a positive direct antiglobulin test in anemic cats.", "abstract": "The preparation of a feline Coombs serum (rabbit antifeline gamma globulin) is described. The direct antiglobulin test using this serum was performed on 20 anemic and 20 healthy control cats. Red cell membrane antibodies were detected in cats with feline leukemia virus infection and in others with inflammatory and neoplastic diseases. A low titre of cold agglutinating antibody was present in a high proportion of the control cats. Positive direct antiglobulin tests were noted in cats without overt hemolytic disease. It was concluded that the direct antiglobulin test in anemic cats has certain diagnostic limitations. A positive reaction should be interpreted cautiously especially when there is no clinical or laboratory evidence to support a diagnosis of autoimmune hemolytic anemia.", "journal": "Canadian journal of comparative medicine : Revue canadienne de medecine comparee", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6095518", "author": "Tuomari DL", "n_authors": 4, "title": "Detection of circulating immune complexes by a Clq/protein A-ELISA during the preneoplastic stages of feline leukemia virus infection.", "abstract": "A microscale ELISA immune complex assay which utilized a solid phase C1q and a Protein A-peroxidase enzyme conjugate is described. This ELISA was used to detect and quantitate circulating immune complexes (CIC) during the initial feline leukemia virus infection. Significant increases in CIC were seen in the cats which were transiently infected at weeks three through eight after viral exposure. A persistent elevation in CIC was observed in the one cat which developed a persistent viremia. The addition of EDTA to the serum strongly interfered with this assay.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(84)90081-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6090693", "author": "Reeves RH", "n_authors": 2, "title": "Molecular genetic characterization of the RD-114 gene family of endogenous feline retroviral sequences.", "abstract": "RD-114 is a replication-competent, xenotropic retrovirus which is homologous to a family of moderately repetitive DNA sequences present at ca. 20 copies in the normal cellular genome of domestic cats. To examine the extent and character of genomic divergence of the RD-114 gene family as well as to assess their positional association within the cat genome, we have prepared a series of molecular clones of endogenous RD-114 DNA segments from a genomic library of cat cellular DNA. Their restriction endonuclease maps were compared with each other as well as to that of the prototype-inducible RD-114 which was molecularly cloned from a chronically infected human cell line. The endogenous sequences analyzed were similar to each other in that they were colinear with RD-114 proviral DNA, were bounded by long terminal redundancies, and conserved many restriction sites in the gag and pol regions. However, the env regions of many of the sequences examined were substantially deleted. Several of the endogenous RD-114 genomes contained a novel envelope sequence which was unrelated to the env gene of the prototype RD-114 env gene but which, like RD-114 and endogenous feline leukemia virus provirus, was found only in species of the genus Felis, and not in other closely related Felidae genera. The endogenous RD-114 sequences each had a distinct cellular flank which indicates that these sequences are not tandem but dispersed nonspecifically throughout the genome. Southern analysis of cat cellular DNA confirmed the conclusions about conserved restriction sites in endogenous sequences and indicated that a single locus may be responsible for the production of the major inducible form of RD-114.", "journal": "Journal of virology", "doi": "10.1128/JVI.52.1.164-171.1984", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6093325", "author": "Jarrett O", "n_authors": 4, "title": "Feline leukaemia virus-free lymphosarcoma in a specific pathogen free cat.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.115.10.249", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6149649", "author": "Werner LL", "n_authors": 2, "title": "Immune-mediated disorders of cats.", "abstract": "Immune-mediated disorders in cats share many clinical and pathologic similarities with their counterparts in other species. Cats, however, are unique among domestic animals owing to the involvement of feline leukemia virus. In addition, a number of other infectious organisms can produce immune-mediated sequelae--that is, FIP virus, FeSFV, and H. felis. Therefore, the diagnostic and therapeutic aims in the management of feline immune-mediated disorders must take into account the probability of a primary or underlying disease process.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": "10.1016/s0195-5616(84)50106-5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6088406", "author": "Jarrett O", "n_authors": 5, "title": "Interaction between feline leukaemia virus subgroups in the pathogenesis of erythroid hypoplasia.", "abstract": "The interaction of feline leukaemia virus (FeLV) of subgroups A and C in the pathogenesis of erythroid hypoplasia in cats was studied. Weanling kittens infected with FeLV-A became permanently viraemic but remained haematologically normal over a period of 36 weeks. Similar kittens inoculated with FeLV-C, which produces erythroid hypoplasia when administered to newborn kittens, neither became viraemic nor developed the disease. However, weanling kittens inoculated with a mixture of FeLV-A and C became viraemic, first with FeLV-A and then additionally with FeLV-C, and the emergence of FeLV-C into the blood coincided with the advent of erythroid hypoplasia. When FeLV-C was inoculated into five older cats which had been viraemic with FeLV-A for several months previously, it appeared in the plasma of three of the cats and erythroid hypoplasia was diagnosed in two of these, 16-20 weeks after infection with FeLV-C. These results show that FeLV-A enhances the growth of FeLV-C in cats and overcomes their age-related resistance to FeLV-C. Also, the appearance of FeLV-C in the plasma of cats viraemic with FeLV-A indicates that erythroid hypoplasia will subsequently occur rapidly. These findings are relevant to the origin of FeLV-C isolates and their occurrence in nature.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910340222", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6331649", "author": "Youngren SD", "n_authors": 3, "title": "Characterization of monoclonal antibodies directed against the envelope proteins of feline leukemia virus.", "abstract": "Monoclonal antibodies directed against the feline leukemia virus (FeLV) envelope proteins, gp70 and p15E, were identified by radioimmunoprecipitation and sodium dodecyl sulfate-polyacrylamide gel electrophoresis. Six of these monoclonal antibodies were specific for the gp70; two for the p15E. Enzyme-linked immunosorbent assay binding assays against FeLV subtypes A, B, and C showed that most of the monoclonal antibodies bound to more than one subtype but have a greater affinity for subtype B. One monoclonal bound exclusively to the FL74 isolate. These studies also indicate that antigenic variability exists between FeLV isolates previously classified as being the same subtype. One antibody was found to bind the gp70s of all FeLV isolates tested and to be directed against a viral neutralizing site. A p15E-specific monoclonal antibody, in addition to binding all the FeLV subtypes, also bound to Moloney and Rauscher murine leukemia viruses, suggesting a group determinant is involved. No binding was seen to human T-cell leukemia virus, bovine leukemia virus, equine infectious anemia virus, or RD114V proteins, however.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6738522", "author": "Hause WR", "n_authors": 1, "title": "Management of acute illness in cats.", "abstract": "Pleural effusions can cause dyspnea and cyanosis, and are caused by cardiomyopathy, pyothorax, FIP, FeLV-related disease and trauma. Thoracentesis is used to obtain fluid samples for cytologic examination and culture. Radiographs made after thoracentesis may reveal the cause. Lymphosarcoma causes a sterile exudate containing neoplastic cells. Congestive cardiomyopathy causes a transudate or modified transudate. The sterile exudate of FIP has a proteinaceous background on cytologic examination. The exudate of pyothorax is septic. Treatment depends on the cause but generally includes thoracentesis and supportive care. Cardiomyopathy causes dyspnea, cyanosis, murmurs, gallop rhythms and other arrhythmias. Radiography reveals a globoid heart in the congestive form and a \"valentine-shaped\" heart in the hypertrophic form. Treatment of congestive cardiomyopathy involves use of furosemide, but is usually unrewarding. Hypertrophic cardiomyopathy is treated with propranolol. Fever may be caused by infection, immune-mediated disease, neoplasia and unknown causes. Treatment is aimed at removal of the underlying cause.", "journal": "Modern veterinary practice", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6328520", "author": "Liu WT", "n_authors": 6, "title": "Appearance of cytotoxic antibody to viral gp70 on feline lymphoma cells (FL-74) in cats during ex vivo immunoadsorption therapy: quantitation, characterization, and association with remission of disease and disappearance of viremia.", "abstract": "Fifty cats with feline leukemia virus (FeLV) infection and leukemia-lymphoma complex were treated by ex vivo immunoadsorption with Staphylococcus protein A-bound filters. Most cats responded to therapy. Twelve showed tumor regression, including disappearance of tumor cells, but died later of other complications. Three have had long-term remission of more than 1 year and remain healthy. A consistent finding in these three cats was the appearance during treatment of a complement-dependent cytotoxic antibody against cat lymphoma cells (FL-74). The cytotoxic antibody increased substantially during treatment. Appearance and increase of the cytotoxic antibody was associated with disappearance of FeLV from blood and remission of leukemia. By electroblot analysis, antibody to FeLV protein (Mr, 70,000) was detected in serum prior to detection of the cytotoxic antibody. The cytotoxic antibody was found by immunofluorescence to be specific for antigens on membranes of viable FL-74 cells. By using monoclonal antibodies to FL-74 cells and to components of FeLV, the cytotoxic antibody was shown to be directed against gp70, a glycoprotein of Mr 70,000, but not against p27 of FeLV or other membrane antigen(s) of FL-74 cells. The development of a high concentration of cytotoxic antibody to FeLV gp70 may play an important role in tumor regression and in disappearance of FeLV infection.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.81.11.3516", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6328019", "author": "Laprevotte I", "n_authors": 4, "title": "Nucleotide sequence of the gag gene and gag-pol junction of feline leukemia virus.", "abstract": "The nucleotide sequence of the gag gene of feline leukemia virus and its flanking sequences were determined and compared with the corresponding sequences of two strains of feline sarcoma virus and with that of the Moloney strain of murine leukemia virus. A high degree of nucleotide sequence homology between the feline leukemia virus and murine leukemia virus gag genes was observed, suggesting that retroviruses of domestic cats and laboratory mice have a common, proximal evolutionary progenitor. The predicted structure of the complete feline leukemia virus gag gene precursor suggests that the translation of nonglycosylated and glycosylated gag gene polypeptides is initiated at two different AUG codons. These initiator codons fall in the same reading frame and are separated by a 222-base-pair segment which encodes an amino terminal signal peptide. The nucleotide sequence predicts the order of amino acids in each of the individual gag-coded proteins (p15, p12, p30, p10), all of which derive from the gag gene precursor. Stable stem-and-loop secondary structures are proposed for two regions of viral RNA. The first falls within sequences at the 5' end of the viral genome, together with adjacent palindromic sequences which may play a role in dimer linkage of RNA subunits. The second includes coding sequences at the gag-pol junction and is proposed to be involved in translation of the pol gene product. Sequence analysis of the latter region shows that the gag and pol genes are translated in different reading frames. Classical consensus splice donor and acceptor sequences could not be localized to regions which would permit synthesis of the expected gag-pol precursor protein. Alternatively, we suggest that the pol gene product (RNA-dependent DNA polymerase) could be translated by a frameshift suppressing mechanism which could involve cleavage modification of stems and loops in a manner similar to that observed in tRNA processing.", "journal": "Journal of virology", "doi": "10.1128/JVI.50.3.884-894.1984", "deposited_data": "Sim", "nuccore_ids": "323914", "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6203125", "author": "Nunberg JH", "n_authors": 4, "title": "Method to map antigenic determinants recognized by monoclonal antibodies: localization of a determinant of virus neutralization on the feline leukemia virus envelope protein gp70.", "abstract": "A method is presented whereby antigenic determinants recognized by specific monoclonal antibodies can be mapped to specific sites on a protein sequence with high resolution. Short DNase I-generated DNA fragments encoding portions of the protein of interest are molecularly cloned into the EcoRI site of the beta-galactosidase gene of phage lambda Charon 16 so as to obtain expression of random protein fragments as fusion proteins. The monoclonal antibody is used to screen the phage library to isolate phage expressing the specific antigenic determinant. DNA of immunoreactive phage can be analyzed rapidly and subcloned to allow DNA sequence determination. The method is generally applicable and permits antigenic determinants of functionally interesting monoclonal antibodies to be mapped and related to specific protein sequences. We have used this procedure to determine the region of the feline leukemia virus envelope protein gp70 recognized by a virus-neutralizing monoclonal antibody, cl.25. Antibody binding was mapped to a 14-amino acid region in the amino-terminal half of gp70. This region may be directly involved in an essential function of the gp70 protein, perhaps in gp70-mediated host recognition functions. Synthetic peptides derived from this region may provide useful vaccine antigens for the prevention of feline leukemia virus-associated disease in cats.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.81.12.3675", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "17422403", "author": "Harasen GL", "n_authors": 1, "title": "Multicentric fibrosarcoma in a cat and a review of the literature.", "abstract": "A case of multicentric fibrosarcoma in a ten month old domestic short-haired cat is presented and discussed. Tumor tissue was found to involve the right distal forepaw, right shoulder area and a popliteal lymph node. This anaplastic neoplasm was concentrated primarily in subcutaneous tissues but also extended to muscle, bone and lung. The cat was found to be positive for feline leukemia virus by the ELISA test. Based on these findings, it is likely that the lesions in this case result from an interaction between the feline leukemia virus and feline sarcoma virus.", "journal": "The Canadian veterinary journal = La revue veterinaire canadienne", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6204435", "author": "Rojko JL", "n_authors": 2, "title": "The immunobiology of the feline leukemia virus.", "abstract": null, "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(84)90050-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6325922", "author": "Mullins JI", "n_authors": 4, "title": "Viral transduction of c-myc gene in naturally occurring feline leukaemias.", "abstract": "Feline leukaemia virus (FeLV) is epidemiologically associated with induction of the majority of lymphoid tumours of the domestic cat. However, about one-third of these tumours are devoid of exogenous virus or show evidence of virus integration only after tumour outgrowth. To help define the genetic mechanisms of feline lymphomagenesis we have explored here the possibility that cellular oncogenes (c-onc genes) are rearranged in tumour cell DNA. Of 16 FeLV-positive T-cell tumours among 31 naturally occurring lymphomas, 2 showed evidence of recombinant FeLV proviruses containing myc oncogene sequences. One of the two produced a transmissible myc-containing FeLV. In both cases c-myc and its surrounding DNA appeared unaltered. We believe that the association of myc with FeLV may result in its activation and play a part in the development of a significant fraction of cat T-cell lymphomas. Our findings contrast with studies of experimental induction of chicken lymphoma, in which myc activation occurs by retrovirus promoter insertion near c-myc (refs 3-5), rather than by incorporation into virus.", "journal": "Nature", "doi": "10.1038/308856a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6325921", "author": "Levy LS", "n_authors": 3, "title": "Isolation of a feline leukaemia provirus containing the oncogene myc from a feline lymphosarcoma.", "abstract": "The molecular mechanism by which feline leukaemia virus (FeLV) induces lymphoid malignancy in domestic cats is largely unknown. Using the insertional activation model of c-myc by avian leukosis virus in the induction of bursal lymphoma in chickens, we have now characterized the c-myc locus in feline tissues and investigated the possibility that FeLV may also insert within feline c-myc. We used the 1.5 kilobase (kb) PstI fragment of MC29 v-myc in Southern blot analysis to characterize the structure of the c-myc locus in the DNA of 31 naturally occurring feline lymphomas. Analysis of a cloned c-myc gene from one lymphoma demonstrated that sequences homologous to v-myc occupy 2.6 kb of feline DNA in which a putative intron of 0.5 kb separates sequences homologous to the 5' and 3' exons represented in avian v-myc. We also observed in the DNA of this lymphoma tumour-specific fragments homologous to v-myc. Characterization of these molecularly cloned myc-hybridizing fragments revealed the presence of at least two identical FeLV proviruses 5.5 kb in length, each containing long terminal repeats enclosing a spliced version of the feline myc gene.", "journal": "Nature", "doi": "10.1038/308853a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6325920", "author": "Neil JC", "n_authors": 7, "title": "Transduction and rearrangement of the myc gene by feline leukaemia virus in naturally occurring T-cell leukaemias.", "abstract": "Evidence of myc gene transduction by feline leukaemia virus in several spontaneous lymphoid tumours of cats suggests that recombinant viruses carrying oncogenes may be much more involved in oncogenesis in natural conditions than previously recognized.", "journal": "Nature", "doi": "10.1038/308814a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6322979", "author": "Wellman ML", "n_authors": 5, "title": "Inhibition of erythroid colony-forming cells by a Mr 15,000 protein of feline leukemia virus.", "abstract": "The effects of concentrated ultraviolet-inactivated feline leukemia virus (FeLV), the purified Mr 15,000 envelope protein (p15E) of FeLV, or the purified Mr 27,000 structural protein (p27) of FeLV on feline bone marrow mononuclear cells were studied in vitro in methylcellulose cultures. Whole virus and purified viral proteins were from the Kawakami-Theilen isolate of FeLV, which induces erythroid aplasia in cats. Bone marrow mononuclear cells from FeLV-negative young adult cats were preincubated with a medium control, ultraviolet-inactivated whole virus, or the p15E or p27 of FeLV, incubated in methylcellulose cultures for 2 days, and then observed for the formation of colony-forming units-erythroid (CFU-E) and colony-forming units-granulocyte/macrophage. The ultraviolet-inactivated Kawakami-Theilen isolate of FeLV at concentrations of 10 or 20 micrograms of viral protein/5 X 10(4) cells suppressed CFU-E to 66 to 56% of control values but had no significant effect on proliferation of colony-forming units-granulocyte/macrophage. p15E at concentrations of 0.1 to 0.2 micrograms/5 X 10(4) cells decreased CFU-E numbers to 0 to 1% of control values, whereas the same concentration of p27 did not alter CFU-E growth when compared with controls. Neither p15E nor p27 had a significant effect on growth of colony-forming units-granulocyte/macrophage. The erythrosuppressive effects of whole virus and an envelope-derived protein but not a structural core protein suggest that FeLV envelope proteins are important in the selective inhibition of erythrogenesis observed in vivo in FeLV-infected cats.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6321796", "author": "Gupta P", "n_authors": 3, "title": "Transcriptional control of the bovine leukemia virus genome: role and characterization of a non-immunoglobulin plasma protein from bovine leukemia virus-infected cattle.", "abstract": "Using cloned bovine leukemia virus (BLV) DNA as a probe in the dot blot hybridization technique, we demonstrated that the expression of the BLV genome in infected lymphocytes is blocked in vivo at the transcriptional level. This blocking effect is due to a non-immunoglobulin protein present in the plasma but not in the serum of BLV-infected cattle. The plasma BLV-blocking protein also blocks the expression of the BLV genome in fibroblast cells of bovine and nonbovine origin infected with BLV in vitro. The plasma BLV-blocking factor has no inhibitory effect on the expression of Rauscher murine leukemia virus and feline leukemia virus in monolayer culture. The plasma BLV-blocking factor is not an interferon molecule. As determined by gel filtration chromatography, the plasma BLV-blocking factor has an apparent molecular weight of ca. 150,000.", "journal": "Journal of virology", "doi": "10.1128/JVI.50.1.267-270.1984", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6321840", "author": "McCoy JL", "n_authors": 8, "title": "Indirect leukocyte migration inhibition in breast cancer and benign breast disease patients by mouse mammary tumor virus grown in feline kidney cells.", "abstract": "Indirect migration inhibition assays were performed with normal and mammary tumor-bearing C3H/HeN mice and patients with breast disease to assess cellular immunity against three different mouse mammary tumor virus (MTV) preparations grown in feline kidney cell cultures and against a mouse-derived MTV preparation. MTV obtained after passage through feline kidney cells and the mouse-derived MTV were capable of eliciting macrophage migration inhibitory factor production by mouse spleen cells obtained from normal or mammary tumor-bearing C3H/HeN mice, thus demonstrating a similar degree of antigenicity of these preparations. In experiments with human breast cancer patients' leukocytes, leukocyte inhibitory factor (LIF) was produced by 32-50% of these patients in response to the mouse-derived MTV or to three different MTV preparations obtained after passage through feline kidney cells. A significant proportion (31-54%) of benign breast disease patients also reacted with both the mouse-derived and feline-derived MTV preparations. Patients with both malignant and benign breast disease, however, had a significantly different (P less than .05) pattern of reactivity to mouse- and feline-derived MTV preparations from that observed with normal donors. Finally, some LIF activity was also observed (but not statistically significant with the use of nonparametric analysis methods) when feline leukemia virus was used as antigen with these patients. The data suggest that both breast cancer and benign breast disease patients were reactive against antigens largely specific for MTV in the feline cells and, presumably, were not reactive against feline cellular components, although the second possibility cannot be completely ruled out.", "journal": "Journal of the National Cancer Institute", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6319496", "author": "Snyder HW Jr", "n_authors": 4, "title": "Clearance of feline leukemia virus from persistently infected pet cats treated by extracorporeal immunoadsorption is correlated with an enhanced antibody response to FeLV gp 70.", "abstract": "Six persistently feline leukemia virus (FeLV)-infected pet cats were treated by extracorporeal immunoadsorption with Staphylococcus aureus Cowan I (SAC) to remove circulating immune complexes and immunoglobulin G (IgG) from plasma. In three of these cats, the FeLV infection was eliminated, whereas in the other three cats the infection persisted. The amounts of peripheral blood leukocyte (PBL)-associated FeLV, soluble FeLV envelope glycoprotein (gp70) antigens in serum, and FeLV-gp70-specific antibodies were determined in all six cats at different times during treatment. In all of the cats, there were fluctuations in the amounts of FeLV-positive PBL and of serum antigen related to FeLV gp70. The one serologic parameter that always correlated with complete clearance of FeLV in the responder cats was the development of free antibodies to gp70. These results suggest that extracorporeal immunoadsorption treatment stimulates an existing low level antibody response to FeLV in some cats, and that these antibodies mediate the clearance of FeLV. The results also suggest that determination of antibody titer to FeLV is of value in predicting the outcome of extracorporeal immunoadsorption treatments as well as when treatment may be terminated.", "journal": "Journal of immunology (Baltimore, Md. : 1950)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6319298", "author": "Aoki T", "n_authors": 8, "title": "Location of human T-cell leukemia virus (HTLV) p19 antigen on virus-producing cells.", "abstract": "Mouse monoclonal antibody to HTLV p19 was used to locate HTLV p19 on the surface of cells and virions by immunofluorescence microscopy (IFM) and immunoelectron microscopy (IEM). When HTLV-producing cells HUT 102 (B2 clone), MT-2 and strain A were used as target cells, HTLV p19 was detected on the surface of cells and virions as spots or small sectors by both IFM and IEM. Cells infected with animal type-C retroviruses, e.g., gibbon ape leukemia virus, simian sarcoma virus, feline leukemia virus, and Gross murine leukemia virus, were completely negative for HTLVp19 expression. Other human T cells not producing HTLV, including HUT78 and HSB2-0, immature or pre-T cells (Molt-3) derived from leukemia patients, and fresh peripheral blood T cells from healthy persons, were also negative. In addition, B cells including Rob-B, IM-9, Raji, and BT-1 did not react with the monoclonal antibody to HTLV p19. In the light of the presence of HTLV p19 in the periphery of acetone-fixed HTLV-producing cells as shown by IFM, it seems most likely that HTLV p19 is an internal antigen of HTLV with part of its structure protruding out of the viral and cell membrane. The monoclonal antibody to HTLV p19 did not lyse HTLV-producing cells in the presence of complement, as expected, because the antibody is an IgG1. Antibody-dependent cell-mediated cytotoxicity was also studied by the 51Cr-release assay. No cytotoxicity was observed. Although HTLV p19 does not contribute to the destruction of malignant T cells for treatment and/or virions for prophylaxis, this protein is an important marker for diagnosis of HTLV infection. The patterns of HTLV p19 expression described above were exactly the same for American HTLV-producing HUT 102 (B2 clone), for strain A cells and for Japanese HTLV-producing MT-2 cells. These results further substantiate the close relationship of the Japanese and American HTLV isolates.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910330202", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6324338", "author": "Lutz H", "n_authors": 1, "title": "[Infection with feline leukemia virus: immunology and serodiagnosis as a basis for the prevention of infection. 2].", "abstract": null, "journal": "Schweizer Archiv fur Tierheilkunde", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6322425", "author": "Copeland TD", "n_authors": 3, "title": "Complete amino acid sequence of the basic nucleic acid binding protein of feline leukemia virus.", "abstract": "The complete amino acid sequence of the nucleic acid binding protein p10 of the Rickard strain of feline leukemia virus (FeLV) has been determined. Fragments obtained by enzymatic digestion were purified by reverse-phase liquid chromatography and subjected to semiautomated Edman degradation. FeLV p10 is a basic polypeptide composed of 57 amino acids with Mr = 6604. The structure of p10 is compared to the structures of other retroviral nucleic acid binding proteins, and an analysis of a highly conserved region, the putative binding domain, is presented.", "journal": "Virology", "doi": "10.1016/0042-6822(84)90432-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6319767", "author": "Nunberg JH", "n_authors": 3, "title": "Nucleotide sequences of the envelope genes of two isolates of feline leukemia virus subgroup B.", "abstract": "We determined the nucleotide sequences of the envelope genes of the Snyder-Theilen and Gardner-Arnstein isolates of feline leukemia virus subgroup B. Comparison of the deduced amino acid sequences of the envelope gene products revealed regions of sequence divergence, which we relate to structural features of the viral protein. We also examined nucleotide sequences within the long terminal repeats of these related isolates of feline leukemia virus subgroup B.", "journal": "Journal of virology", "doi": "10.1128/JVI.49.2.629-632.1984", "deposited_data": "Sim", "nuccore_ids": "323929, 323910", "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6319286", "author": "Pedersen NC", "n_authors": 3, "title": "Biological behavior of tumors and associated retroviremia in cats inoculated with Snyder-Theilen fibrosarcoma virus and the phenomenon of tumor recurrence after primary regression.", "abstract": "The fate of tumors and associated retroviremia was studied in 111 cats infected with the Snyder-Theilen strain of feline sarcoma virus (FeSV). Tumors appeared at the site of inoculation within 7 to 10 days. A retroviremia, due mainly to the associated feline leukemia virus helper virus (FeLV-helper), developed at the same time as tumors. Of the cats, 44 developed progressively growing tumors and therefore had to be killed, and 67 developed tumors that regressed. There was a strong correlation between the persistence of the accompanying retroviremia and the growth of the tumors. The 44 cats with progressively growing fibrosarcomas remained retroviremic until death. Conversely, 53 of the 67 cats with solitary, regressing tumors were only transiently retroviremic. Tumor regression in these cats paralleled the disappearance of retrovirus from the blood. The fate of tumors and retroviremia was not always the same, however. Twelve cats remained persistently retroviremic after all signs of gross tumors disappeared. Two other kittens became nonviremic within 20 days after inoculation, yet tumors continued to grow and even metastasize for another 3 to 5 weeks before regressing. Fibrosarcomas recurred 3 weeks to 8 months later in 8 of 12 persistently retroviremic cats with regressed tumors. Although the blood and bone marrow from these cats contained predominantly FeLV-helper, tumor cells yielded both FeSV and FeLV-helper. Of 53 animals, 3 developed recurrent fibrosarcomas 5 weeks to 8 months after all signs of tumors and retroviremia had disappeared. Cells cultured from these tumors appeared initially like normal fibroblasts and were virus nonproducers. After one to three passages in culture, however, cells became malignantly transformed and replicated both FeSV and FeLV-helper. Cultures of the bone marrow from these and other nonviremic cats with regressed tumors yielded only FeLV-helper.", "journal": "Infection and immunity", "doi": "10.1128/iai.43.2.631-636.1984", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6318972", "author": "Grant CK", "n_authors": 3, "title": "Comparison of feline leukemia virus-infected and normal cat T-cell lines in interleukin 2-conditioned medium.", "abstract": "Following mitogen stimulation (phytohemagglutinin or concanavalin A), feline lymphocytes were maintained in medium containing feline interleukin 2. Lymphocyte lines derived from the blood of feline leukemia virus-infected cats contained cells 50 to 90% of which expressed virus antigens, but lymphocyte lines derived from uninfected cats remained virus free. Leukemia virus-positive and -negative lymphocyte lines retained total dependence upon the presence of interleukin 2 for finite life spans of 20 to 40 cell divisions. Cell-doubling times and surface properties (membrane immunoglobulin negative, guinea pig red cell rosette positive) of all T-cell lines were similar. All cat lymphocyte lines rapidly developed strong but nonspecific cytotoxic effects against a variety of established cat target lines, including normal and leukemia virus-infected fibroblasts and virus-producing lymphomas. Attempts to infect virus-negative lymphocytes with leukemia virus in vitro produced lines containing 1 to 4% of infected cells; subsequently, this level of infection remained constant. Within observation limits, the characteristics of feline leukemia virus-infected and normal cat T-cells were similar. Leukemia virus infection did not predispose target lymphocytes to exhibit properties in vitro that might be associated with preneoplastic change, such as rapid or infinite cell division or development of independence from interleukin 2 regulation.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6198530", "author": "Pinter A", "n_authors": 2, "title": "Characterization of structural and immunological properties of specific domains of Friend ecotropic and dual-tropic murine leukemia virus gp70s.", "abstract": "A detailed comparison of the gp70 proteins of cloned ecotropic Friend murine leukemia virus (FLV) and dual-tropic Friend mink focus-forming virus (FrMCF) was performed by analyzing the structural and immunological properties of amino- and carboxy-terminal domains of these molecules generated upon controlled trypsinization. The two gp70s gave characteristic fragmentation patterns; the amino-terminal fragments of FrMCF gp70 were smaller than the corresponding fragments of FLV and contained a trypsin site which resulted in a 19,000-dalton amino-terminal fragment not observed for FLV, whereas both molecules yielded an identically sized carboxy-terminal fragment. All amino-terminal fragments of both gp70 molecules contained an endo H-sensitive oligosaccharide chain; for FrMCF, a second endo H-sensitive carbohydrate was present as well at a carboxy-terminal site for approximately 50% of the molecules. Several aspects of the disulfide interactions of the two gp70s were conserved; in both cases the carboxy-terminal fragments were disulfide bonded to p15(E), there were no disulfide bonds between amino- and carboxy-terminal fragments, and the amino-terminal fragments exhibited a significant increase in mobility upon analysis by sodium dodecyl sulfate-polyacrylamide gel electrophoresis under nonreducing conditions. Analysis of the immunoreactivity of the different domains of the proteins by immunoprecipitation of the fragments with antisera prepared against xenotropic murine leukemia virus and feline leukemia virus gp70s indicated major differences in antigenicity for the amino-terminal domains of FLV and FrMCF gp70, whereas the carboxy-terminal domains were immunologically conserved. Similar analyses with antibodies specific for p15(E) and Pr15(E) demonstrate that these components are conserved as well. These data provide direct evidence that p15(E) and the C-terminal gp70 domain of FrMCF gp70 are related to the corresponding regions of the ecotropic FLV parent and indicate that the acquisition of MCF-specific properties is due to the replacement of the ecotropic amino-terminal gp70 domain with sequences related to those of xenotropic gp70s.", "journal": "Journal of virology", "doi": "10.1128/JVI.49.2.452-458.1984", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6320533", "author": "Snyder HW Jr", "n_authors": 4, "title": "Isolation of a new feline sarcoma virus (HZ1-FeSV): biochemical and immunological characterization of its translation product.", "abstract": "A new strain of feline sarcoma virus, designated HZ1-FeSV, was isolated from a 4-year-old domestic cat with multicentric fibrosarcoma. A primary tumor cell line was established and virus produced from that line was found to induce foci in feline embryonic lung fibroblasts (FLF3) and mink lung fibroblasts (CCL64) in tissue culture and fibrosarcomas in inoculated 10-week-old kittens. The derivation of transformed nonproducer clones of FLF3 and CCL64 cells containing helper virus-rescuable, focus-forming activity indicated that HZ1-FeSV was defective for replication. The only discernible translation product of the HZ1-FeSV genome in cultured cells was a 100,000-Da polyprotein (P100) which contained amino-terminal sequences of the FeLV gag gene precursor protein covalently linked to a sarcoma virus-specific domain. Immunoprecipitates containing P100 exhibited a protein kinase activity capable of phosphorylating tyrosine residues of P100. Immunologically, P100 was highly cross-reactive with gag-fes polyproteins encoded by two previously characterized strains of FeSV, the GA- and the ST-FeSV. By comparison of methionine-containing tryptic peptides, the HZ1-FeSV protein was shown to be more closely related to the GA-FeSV protein than to the ST-FeSV protein, but to be distinguishable from both other proteins.", "journal": "Virology", "doi": "10.1016/0042-6822(84)90104-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6582485", "author": "Hampe A", "n_authors": 4, "title": "Nucleotide sequence of the feline retroviral oncogene v-fms shows unexpected homology with oncogenes encoding tyrosine-specific protein kinases.", "abstract": "The nucleotide sequence encoding the transforming polyprotein of the McDonough strain of feline sarcoma virus was determined. This sequence includes 231 nucleotides specifying a leader peptide, 1,377 nucleotides encoding most of the feline leukemia virus-derived gag gene, and 2,969 nucleotides representing the viral transforming gene v-fms. A single open reading frame was predicted to encode a fusion polyprotein of 160,000 daltons (P160gag-fms). Fourteen potential sites for glycosylation were predicted within the v-fms-encoded portion of the protein, consistent with previous observations that the primary translation product is rapidly glycosylated. The presence of hydrophobic signal peptides within the amino-terminal leader sequence and in the middle of the v-fms-encoded moiety suggests that the transforming glycoprotein becomes oriented with its amino terminus within the lumen of the rough endoplasmic reticulum and its carboxyl terminus protruding across the membrane of the rough endoplasmic reticulum into the cytoplasm. The latter portion of the protein shows unexpected homology to tyrosine-specific protein kinases encoded by several of the known retroviral oncogenes.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.81.1.85", "deposited_data": "Sim", "nuccore_ids": "323890", "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6329486", "author": "Chen AP", "n_authors": 2, "title": "Infection with feline leukemia virus associated with induction of humoral response to a normal cell protein.", "abstract": "Selected populations of cats that were naturally exposed to the feline leukemia virus (FeLV) were found to have humoral antibodies to a normal cell protein designated NCP105. Earlier studies revealed that cats exposed to FeLV often had serum antibodies to the feline oncornavirus-associated cell membrane (FOCMA) as well as to a feline sarcoma virus (FeSV) -specific transforming protein designated gag-fes. Cats with no history of exposure to FeLV or FeSV lacked antibodies to all three antigens: NCP105, FOCMA, and gag-fes. Following exposure to FeLV, cats develop antibodies to either NCP105 or to gag-fes and FOCMA, but not to both groups of antigens. NCP105 is present in both normal and transformed cells from a wide variety of species. It lacks peptide homology with gag-fes and it is not a phosphoprotein. The presence of antibodies to NCP105 in cats exposed to FeLV but not in unexposed cats suggests that FeLV may activate the NCP105 gene or increase the relative immunogenicity of this protein in vivo.", "journal": "Cancer investigation", "doi": "10.3109/07357908409020290", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6324337", "author": "Lutz H", "n_authors": 1, "title": "[Infection with feline leukemia virus: immunology and serodiagnosis as the basis for control. 1].", "abstract": null, "journal": "Schweizer Archiv fur Tierheilkunde", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6209091", "author": "Zueva IuN", "n_authors": 1, "title": "[Detection of antigenic determinants of the major structural proteins of various mammalian type C retroviruses in the leukocytes of patients with hemoblastoses and in healthy donors by the ELISA method].", "abstract": "Using the enzyme-labelled antibodies it was shown that extracts from leukocytes of patients with leukemias and healthy donors contain antigenic determinants related to major virus protein of mammalian C type oncornaviruses SSV/SSAV, BaEV, FeLV and RLV. The highest antigen activity in patients was detected in the feline leukemia (FeLV) system, and the least one--in the system of murine leukemia (RLV). Common antigenic determinants of major virus protein of the viruses under study were detected in all groups of patients with haemoblastoses and healthy donors, but the amount of positive results was considerably higher in the group of patients as compared to that in the group of donors.", "journal": "Eksperimental'naia onkologiia", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6098972", "author": "Theilen GH", "n_authors": 1, "title": "[Clinical aspects of infection with feline leukemia virus in cats].", "abstract": "The leukemia-sarcoma complex constitutes the most common group of malignancies in the cat. Epizootiology of FeLV infections and pathogenesis, which can be divided into three stages, are described. Diagnosis can be made by immunofluorescent, ELISA and virus isolation techniques, as well as FOCMA-antibody tests. Symptomatology of FeLV related illnesses is presented. Feline lymphoma can be categorized into four anatomic types: thymic, alimentary and multicentric type and true leukemia. Forms, which do not fit this classification, are classified as miscellaneous. Treatment of these forms and prevention and control of FeLV infections are discussed.", "journal": "Tierarztliche Praxis", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6097827", "author": "Hlubinová K", "n_authors": 5, "title": "Purification and protein composition of endogenous rat viruses.", "abstract": "Endogenous retroviruses are not in the majority of cases the cause of any neoplasia, except for the laboratory conditions. As far as they might serve for the evolution of pathogenic retroviruses more attention should have been paid to them. In this paper we introduce some approaches to the purification of rat endogenous retroviruses to such a degree of purity that enabled satisfactory SDS-PAGE analysis of its structural proteins. Purities of samples obtained by usual purification methods, long-term isopycnic centrifugation at a high gravity force and velocity centrifugation are compared. Protein profile of rat endogenous virus in SDS-PAGE is compared with the ones of other retroviruses. For the first time the evidence was obtained for the striking similarity between electrophoretic protein profile of rat endogenous virus WERC and feline leukemia virus. The major structural proteins of rat endogenous retrovirus and feline leukemia virus cannot be distinguished even when resolution long gradient PAGE had been employed. The accordance of electrophoretic mobilities of major structural proteins in SDS-PAGE can indicate the relatedness of retroviruses.", "journal": "Neoplasma", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6086847", "author": "Jones FR", "n_authors": 3, "title": "Lymphosarcoma and persistent feline leukemia virus infection of pet cats: a system to study responses during extracorporeal treatments.", "abstract": "Pet cats, persistently infected with feline leukemia virus and having lymphosarcoma, were treated by extracorporeal immunoadsorption using Staphylococcus aureus Cowan I (which has protein A on its surface) to remove immunoglobulin G and circulating immune complexes. Complete viral clearance and long-lasting tumor regression were achieved following such treatments in 9 of 16 cats. In addition, in vitro immunologic assays have been developed that are useful in the clinical evaluation of cats during treatment.", "journal": "Journal of biological response modifiers", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2999596", "author": "Francis DP", "n_authors": 2, "title": "The prospects for and pathways toward a vaccine for AIDS.", "abstract": null, "journal": "The New England journal of medicine", "doi": "10.1056/NEJM198512193132506", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "3001000", "author": "Hoover JP", "n_authors": 3, "title": "Serologic evaluation of vaccinated American river otters.", "abstract": "The Oklahoma Department of Wildlife Conservation acquired 20 American river otters (Lutra canadensis) between 1984 and 1985 for reintroduction into Oklahoma waterways. In 1985, 10 otters were evaluated for serum antibody titers after vaccination with canine distemper virus, canine adenovirus type 2, canine parvovirus (CPV), feline panleukopenia virus (FPV), feline rhinotracheitis virus (FRV), and feline calicivirus. Prevaccination serum-virus neutralization (SVN) antibody to feline rhinotracheitis virus was found in 2 otters and to feline calicivirus in 1 otter. Using an indirect fluorescent antibody (IFA) assay, prevaccination antibody to CPV and FPV was found in 2 otters. A significant increase in SVN antibody titers was found after vaccination of otters with canine adenovirus type 2 (6 of 8 animals) and feline calicivirus (1 of 8 animals). One of 8 otters developed significant antibody titers to CPV and FPV, as measured by IFA assay. Otters did not develop SVN antibody titers to canine distemper virus after vaccination. Antigens of feline leukemia virus, using ELISA, or antibodies to feline infectious peritonitis, using IFA assay, were not found in the 20 otters.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2415715", "author": "Soe LH", "n_authors": 4, "title": "Molecular analysis of several classes of endogenous feline leukemia virus elements.", "abstract": "Five recombinant DNA clones of endogenous feline leukemia virus-related DNA sequences were isolated by screening a lambda phage genomic library of cat placental DNA with a probe specific to the gag-pol region of infectious feline leukemia virus. The clones containing retroviral long terminal repeat-like sequences demonstrated the existence of different size classes of endogenous elements in the cat genome, including those of nearly full length in which the gag region is heterogeneous but all of pol and most of env are highly conserved. Other size classes included elements with major deletions in gag or pol. A genomic DNA analysis suggested that the majority of endogenous elements were close to full length in size and that the highly truncated sequences which we described previously (Soe et al., J. Virol. 46:829-840, 1983) represented only a subset of the elements present. A restriction analysis of genomic DNA suggested a high degree of conservation in pol and the 5' portion of env among the various endogenous sequences present in the cat genome. We also found by using DNA transfection that while all of the endogenous clones were noninfectious, there was differential expression of the elements which we examined. These findings correlate with the subgenomic expression of endogenous feline leukemia virus sequences in cat placental tissue.", "journal": "Journal of virology", "doi": "10.1128/JVI.56.3.701-710.1985", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "3000061", "author": "Pacitti AM", "n_authors": 2, "title": "Duration of the latent state in feline leukaemia virus infections.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.117.18.472-a", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "3000060", "author": "Toth SR", "n_authors": 4, "title": "Chronic eosinophilic leukaemia in blast crisis in a cat negative for feline leukaemia virus.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.117.18.471", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2993416", "author": "Tompkins MB", "n_authors": 2, "title": "Stimulation of a cell-mediated cytotoxic response to FeLV-induced T cell lymphomas in the cat.", "abstract": "Nonspecific cell-mediated cytotoxicity was examined in the peripheral blood and spleens of normal and vaccinia virus-infected adult domestic cats. Natural cytotoxic (NC)-like cells, as measured by lysis of vaccinia- or HSV-infected, adherent cat tongue cells, were found in both the spleen and peripheral blood of normal, nonimmune cats. Cytotoxicity was expressed in a 16-hr assay but not in a 4-hr assay. Natural killer (NK)-like cells, as measured by lysis of an FeLV-induced lymphoid tumor cell line (FL-74) growing in suspension, were found in the spleen but not PBL, and required a 16-hr assay for expression. Infection with vaccinia virus did not increase the activity of feline NC-like cells in either the peripheral blood or the spleen. NK-like function, however, was increased. Cytotoxicity peaked 6 days post-infection and required a 16-hr assay for maximal expression of cell lysis. Furthermore, a cell with cytotoxic characteristics of the spleen NK-like cell appeared at low levels in the circulation at 6 days post-vaccinia infection. NK-like cells from vaccinia-infected cats showed some cytotoxicity for FL74 targets in a 4-hr assay. The cat thus possesses at least two functionally different populations of naturally cytotoxic cells. NC-like cells are found in the spleen and peripheral blood, lyse virus-infected monolayer targets, and are not activated by infection. NK-like cells are found in the spleen, lyse-lymphoid tumor targets, and can be activated by infection, with their peak activity occurring 6 days after infection.", "journal": "Journal of immunology (Baltimore, Md. : 1950)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2992811", "author": "Kooistra LH", "n_authors": 2, "title": "Killer cells of feline leukemia virus- and feline sarcoma virus-infected transformed cells: the role of NK, ADCC, and in vitro generated cytotoxic cells.", "abstract": "Feline white blood cells (WBC) manifested a primary in vitro mixed lymphocyte tumor cell culture (MLTC) proliferative response to feline leukemia virus-feline sarcoma virus (FeLV-FeSV)-infected transformed target cells, which reached a peak at Day 15. Furthermore, primary in vitro MLTC cultures generated cytotoxic killer cells capable of killing a variety of targets in non-major histocompatibility gene complex restricted fashion, and effector cells were capable of killing targets introduced repeatedly into cultures over a 49-day period. The presence of feline fibrosarcoma (f-sarc) stimulators was the primary driving force for proliferation and generation of killing because exogenous IL-2 conditioned medium did not appreciably increase the yield of killer cells generated in vitro. WBC cultured without f-sarc stimulators with or without IL-2 supplementation also generated killer (K) cells but at a low level. The killer cell population was composed of approximately 50% lymphocytes and 50% monocytes. Cats had K cells functional in antibody-dependent cell-mediated cytotoxicity against FeLV-coated chicken red blood cells but not against any FeLV-FeSV-infected transformed targets tested. Natural killer (NK) cell activity to any targets tested was not found. Although no evidence was found for K or NK cell activity against FeLV-FeSV-infected transformed cells, feline WBC were readily able to generate killer cells in vitro and it is probable that this cell-mediated immune potential is functionally important in vivo.", "journal": "Cellular immunology", "doi": "10.1016/0008-8749(85)90271-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2991607", "author": "Yoshinaka Y", "n_authors": 4, "title": "Translational readthrough of an amber termination codon during synthesis of feline leukemia virus protease.", "abstract": "Feline leukemia virus contains a protease which apparently has the same specificity as murine leukemia virus protease. It cleaves in vitro the Pr65gag of Gazdar-mouse sarcoma virus into the constituent p15, p12, p30, and p10 proteins. We purified the protease and determined its NH2-terminal amino acid sequence (the first 15 residues). Alignment of this amino acid sequence with the nucleotide sequence (I. Laprevotte, A. Hampe, C. H. Sherr, and F. Galibert, J. Virol. 50:884-894, 1984) reveals that the protease is a viral-coded enzyme and is located at the 5' end of the pol gene. As previously found for murine leukemia virus (Y. Yoshinaka, I. Katoh, T. D. Copeland, and S. Oroszlan, Proc. Natl. Acad. Sci. U.S.A. 82:1618-1622, 1985), feline leukemia virus protease is synthesized through in-frame suppression of the gag amber termination codon by insertion of a glutamine in the fifth position, and the first four amino acids are derived from the gag gene.", "journal": "Journal of virology", "doi": "10.1128/JVI.55.3.870-873.1985", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2990654", "author": "Engelman RW", "n_authors": 4, "title": "Hypercalcemia in cats with feline-leukemia-virus-associated leukemia-lymphoma.", "abstract": "Three cases of hypercalcemia were recognized among 11 cats presenting with leukemia-lymphoma for ex vivo immunoadsorption therapy using Staphylococcal Protein-A-coated filters. In addition, the initial mean serum calcium concentration of cats with leukemia-lymphoma was significantly higher (P less than 0.005) than that of healthy control cats or feline-leukemia-virus-infected cats without malignancy. During immunotherapy of the hypercalcemic cats, objective reduction in the extent of the malignancies was associated with a small reduction in the serum calcium concentrations. This response to treatment, the lack of skeletal metastasis, and the absence of renal and parathyroid pathologic findings imply that humorally mediated mechanisms may have been responsible for the production of the hypercalcemia.", "journal": "Cancer", "doi": "10.1002/1097-0142(19850815)56:4<777::aid-cncr2820560413>3.0.co;2-v", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2995795", "author": "Snyder HW Jr", "n_authors": 4, "title": "Quantitation of specific antibodies bound to feline leukemia virus in the plasma of pet cats.", "abstract": "A method is described for determining levels of circulating immune complexes (CIC) composed of feline leukemia virus (FeLV) antigens and corresponding antibodies in plasma of persistently-infected pet cats. The procedure is based on the ability of high-titered heterologous anti-FeLV serum to chase cat anti-FeLV IgG from dissociated CIC by successfully competing for binding of free antigen. The eluted cat antibody is then collected and quantitated. In a study of cats in the process of clearing persistent FeLV infections, measured levels of FeLV-specific CIC correlated well with fluctuating levels of free FeLV antigen and antibody. The Raji cell assay for CIC in those cats was of comparatively little value in following the clearance of the virus, presumably because that assay does not distinguish between CIC containing viral and those containing non-viral antigens. The method described can be adapted to studies of specific immune complexes associated with a variety of syndromes, provided that the antigen eliciting the immune response is known.", "journal": "Molecular immunology", "doi": "10.1016/0161-5890(85)90071-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2995717", "author": "Mochizuki M", "n_authors": 3, "title": "Epizootiologic survey of feline leukemia virus in South-Kyushu area.", "abstract": null, "journal": "Nihon juigaku zasshi. The Japanese journal of veterinary science", "doi": "10.1292/jvms1939.47.661", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "3894522", "author": "Engelman RW", "n_authors": 4, "title": "Polyclonal induction of immunoglobulin synthesis by feline leukocytes as identified in a reverse hemolytic plaque assay.", "abstract": "Optimal conditions of culture and assay for identification of feline immunoglobulin-secreting mononuclear cells were determined for the staphylococcal protein A-reverse hemolytic plaque assay (SpA-RHPA). Hemolytic plaques were most distinct and numerous when peripheral blood mononuclear cells were stimulated with 6.9 micrograms/ml pokeweed mitogen for 7 days. Immunoglobulin-secreting cells were identified morphologically within a zone of hemolysis utilizing a 1:5 dilution of rabbit anti-cat IgG and a 1:30 dilution of guinea pig complement as developing reagents. The SpA-RHPA system should contribute to an understanding of normal feline T- and B-lymphocyte interactions and will likely aid in the identification and understanding of immune cell dysfunctions associated with chronic feline leukemia virus infection.", "journal": "Journal of immunological methods", "doi": "10.1016/0022-1759(85)90122-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "4035941", "author": "Latimer KS", "n_authors": 3, "title": "Pelger-Huët anomaly in cats.", "abstract": "Pelger-Huët anomaly was diagnosed in a young male cat on the basis of persistent nuclear hyposegmentation of blood granulocytes, absence of clinical disease or feline leukemia virus infection, and demonstration of genetic transmission of the anomaly. Neutrophils, eosinophils, basophils, and monocytes had significantly less nuclear segmentation when compared to similar leukocyte types from a control cat. On smears of bone marrow, megakaryocytes also appeared hyposegmented. A test mating with an unaffected queen produced a litter of five kittens (three males, two females). One male and one female kitten had the Pelger-Huët trait on examination of blood smears. Autosomal dominant transmission of this anomaly is suspected based on these findings.", "journal": "Veterinary pathology", "doi": "10.1177/030098588502200412", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2993377", "author": "Ungar-Waron H", "n_authors": 4, "title": "Rheumatoid factors in natural retrovirus infections of the cat and cattle.", "abstract": "The occurrence of IgM-rheumatoid factors (RFs) was investigated in natural retrovirus infection of cats with feline leukaemia virus and of cattle with bovine leukaemia virus. IgM-RFs of polyclonal character were detected. No significant differences were observed between the amounts of IgM-RFs in the retrovirus-infected animals and their respective controls.", "journal": "Journal of comparative pathology", "doi": "10.1016/0021-9975(85)90044-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2993169", "author": "Jarrett O", "n_authors": 1, "title": "Feline leukaemia virus.", "abstract": null, "journal": "In practice", "doi": "10.1136/inpract.7.4.125", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2989554", "author": "Braun MJ", "n_authors": 3, "title": "Nucleotide sequence of a transduced myc gene from a defective feline leukemia provirus.", "abstract": "The nucleotide sequence of a feline v-myc gene and feline leukemia virus (FeLV) flanking regions was determined. Both the nucleotide and predicted amino acid sequences are very similar to the murine and human c-myc genes (ca. 90% identity). The entire c-myc coding sequence is represented in feline v-myc and replaces portions of the gag and env genes and the entire pol gene. The coding sequence is in phase with the gag gene reading frame; v-myc, therefore, appears to be expressed as a gag-myc fusion protein. Viral sequences at the 3' myc-FeLV junction begin with the hexanucleotide CTCCTC, which is also found at the 3' fes-FeLV junction of both Gardner-Arnstein and Snyder-Theilen feline sarcoma viruses. These similarities suggest that some sequence specificity may exist for the transduction of cellular genes by FeLV. Feline v-myc lacks a potential phosphorylation site at amino acid 343 in the putative DNA-binding domain, whereas both human and murine c-myc have such sites. Avian v-myc has lost a potential phosphorylation site which is present in avian c-myc five amino acids from the potential mammalian site. If these sites are actually phosphorylated in normal c-myc proteins, their loss may alter the DNA-binding affinity of v-myc proteins.", "journal": "Journal of virology", "doi": "10.1128/JVI.55.1.177-183.1985", "deposited_data": "Sim", "nuccore_ids": "323922", "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2987351", "author": "Osterhaus A", "n_authors": 6, "title": "Induction of protective immune response in cats by vaccination with feline leukemia virus iscom.", "abstract": "An effective candidate subunit vaccine consisting of the gp 70/85 of feline leukemia virus (FeLV) was prepared by using the immunostimulating complex (iscom) method for the presentation of membrane proteins of enveloped viruses. Two 32-wk-old specific pathogen-free (SPF) cats were immunized with a FeLV iscom vaccine prepared from the supernatant fluid of the FL74 tumor cell line without adjuvant. Both cats developed FeLV serum antibodies, as measured in an enzyme-linked immunosorbent assay (ELISA) and in a virus neutralization test. A proportion of the antibodies were directed to an epitope located on gp70/85, which was shown in competition ELISA with a peroxidase-labeled virus-neutralizing monoclonal antibody to be shared by all three subtypes of FeLV. The protective effect of FeLV iscom was studied by vaccinating six 8-wk-old SPF cats with iscom prepared from cell culture supernatant of another tumor cell line F422, followed by oronasal challenge with 10(6) ffu FeLV-A (strain Glasgow-1). Six unvaccinated cats were also challenged with the same dose of FeLV. The vaccinated cats developed FeLV serum antibodies, some of which were directed to the shared epitope on gp70/85. At 10 wk after challenge, none was viremic, whereas three of the control cats had developed FeLV viremia. The potential of FeLV iscom as a vaccine against FeLV-associated disease in cats, and of iscom vaccines for protection against mammalian retrovirus infections, is discussed.", "journal": "Journal of immunology (Baltimore, Md. : 1950)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2987350", "author": "Orosz CG", "n_authors": 4, "title": "Retrovirus-mediated immunosuppression. II. FeLV-UV alters in vitro murine T lymphocyte behavior by reversibly impairing lymphokine secretion.", "abstract": "Murine splenocytes and cloned murine T cells were used to study the in vitro immunosuppressive effects of UV-inactivated feline leukemia virus (FeLV-UV) on lymphokine secretion. FeLV-UV can significantly depress the accumulation of IL 2 in cultures of Con A-stimulated C57BL/6 splenocytes and in cultures containing the alloreactive helper T cell clone B6D/2-2m plus Con A. Inhibition of lymphokine accumulation in these cultures could not be attributed to absorption or inactivation of IL 2 by the FeLV-UV or to the FeLV-UV-induced production of substances which interfere with the IL 2 bioassay. Thus, FeLV-UV appears to block production and/or secretion of IL 2 by a direct inhibitory effect on IL 2-secreting murine T lymphocytes. Additional studies indicate that FeLV-UV impairs IL 2 production only if added very soon after lymphocyte contact with lymphokine-inducing agents and that IL 2 secretion resumes when FeLV-UV is removed from the culture. FeLV-UV also impairs accumulation of MAF (interferon-gamma?) in cultures of Con A-stimulated C57BL/6 splenocytes and in cultures containing the alloreactive cytotoxic T lymphocyte clone B6D/2-7c plus Con A. The latter observation again suggests that FeLV-UV impairs lymphokine secretion by a direct effect on lymphokine-producing T lymphocytes. Furthermore, it suggests that FeLV-UV does not selectively impair production of IL 2 nor does it have selective inhibitory effects on helper T cells. Rather, FeLV-UV appears to have a general inhibitory effect on lymphokine production by T lymphocytes. Finally, concentrations of FeLV-UV which suppress MAF production by the CTL clone have little influence on the cytolysis mediated by the same cloned T cell population. Thus, the immunosuppressive influence of FeLV-UV is selective for phenomena associated with induction of new T lymphocyte functions, such as lymphokine secretion, and spares other immune functions already expressed by the same cells.", "journal": "Journal of immunology (Baltimore, Md. : 1950)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2987539", "author": "Kraut EH", "n_authors": 4, "title": "Effects of cobra venom factor treatment on latent feline leukemia virus infection.", "abstract": "The role of the complement system in containment of feline leukemia virus infection was studied by cobra venom factor treatment of feline leukemia virus-immune cats. One to three weeks after cobra venom factor treatment, an increase in viral antigen in marrow myelomonocytic cells and circulating immune complexes was noted. Prevention of reactivation of feline leukemia virus infection may in part depend on an intact complement system.", "journal": "Journal of virology", "doi": "10.1128/JVI.54.3.873-875.1985", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "3923875", "author": "Pang VF", "n_authors": 2, "title": "Susceptibility of cats, sheep, and swine to a rabbit isolate of Encephalitozoon cuniculi.", "abstract": "Newborn cats, pigs, and sheep (3 to 14 days old) and postweanling cats (2.5 months old) that had been inoculated with Gardner feline sarcoma virus and feline leukemia virus at 10 days of age were infected experimentally with a rabbit isolate of the mammalian protozoan parasite Encephalitozoon cuniculi. Infection occurred in all cats and in some sheep, but was questionable in pigs. Brain and kidney were the 2 major target organs in cats. The lesions were compatible with, but less severe than, those of naturally infected cats and other carnivores. Of 13 cats, E cuniculi could be detected morphologically in the kidneys of 12 cats and in the brain of 1 cat. The organisms were reisolated from 2 cats with ground tissue suspension of kidney or urine sediment. The indirect immunofluorescence antibody (IFA) titers were 1:20 to 1:1,280 at the time the animals were killed, but antibodies were not detected before inoculation. Lesions were seen in the kidneys of 2 of 4 sheep. These lesions were mild, but were compatible with those in a spontaneously affected goat. Encephalitozoon cuniculi were found morphologically in the kidney of 1 sheep with lesions. All sheep had IFA titers of 1:10 to 1:20 before inoculation, and the titers were 1:20 to 1:320 when they were killed. Vasculitis, similar to the subacute-to-chronic stage of polyarteritis nodosa, was observed in 1 of 8 pigs. The lesions were primarily present in the kidney; comparable but milder lesions were also seen in the heart and brain. Antibody was not detected before inoculation.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2988377", "author": "Lewis MG", "n_authors": 7, "title": "Retroviral-associated eosinophilic leukemia in the cat.", "abstract": "Fourteen specific-pathogen-free cats were inoculated with a putative env gene recombinant feline retrovirus, PR8. An isolate of the Rickard strain of feline leukemia virus (FeLV-R), PR8, has the properties of both an exogenous (FeLV-R) and an endogenous (xenotropic) feline retrovirus (RD-114). Twelve of the PR8-inoculated cats developed viremia; 2 of the 12 cats developed eosinophilia, with 1 being diagnosed with eosinophilic leukemia and the other with extreme eosinophilic hyperplasia. Eosinophilic leukemia is rare in cats and has not previously been associated with retroviral infection. Changes in the viral envelope properties may have altered the pathogenicity of the exogenous virus to cause this rare form of leukemia.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2984289", "author": "Orosz CG", "n_authors": 4, "title": "Retrovirus-mediated immunosuppression. I. FeLV-UV and specific FeLV proteins alter T lymphocyte behavior by inducing hyporesponsiveness to lymphokines.", "abstract": "Murine splenocytes were used to study the in vitro immunosuppressive effects of UV-inactivated feline leukemia virus (FeLV-UV). FeLV-UV blocks both alloantigen (DBA/2)-induced and Con A-induced proliferation of C57BL/6 splenocytes in a dose-dependent manner. Furthermore, C57BL/6 anti-DBA/2 mixed lymphocyte cultures containing FeLV-UV fail to develop detectable DBA/2-specific cytolytic activity, although FeLV-UV has no effect on the cytolytic activity of preformed C57BL/6 anti-DBA/2 cytolytic T cells (CTL). Disruption of lymphocyte proliferation and CTL generation by FeLV-UV could not be overcome by the addition of exogenous lymphokines. These data suggest that FeLV-UV can interfere with the lymphokine reactivity of alloactivated lymphocytes. In fact, FeLV-UV blocks the lymphokine-induced proliferation of the murine IL 2-dependent cell line CTLL-20. The CTLL-20 cells were subsequently used to study the mechanism(s) by which retroviruses alter T lymphocyte function. Normally, CTLL-20 cells undergo significant proliferation when cultured in EL4 SN, an IL 2-containing culture supernatant from PMA-stimulated EL4 cells. This lymphokine-induced CTLL-20 proliferation is abrogated in a dose-dependent manner by UV-inactivated murine leukemia virus (MuLV-UV), FeLV-UV, and a purified 15,000 dalton viral protein, p15, derived from FeLV. Suppression of CTLL-20 proliferation requires only brief contact (6 hr) with FeLV-UV or with p15, but is most efficient after prolonged (24 hr) contact with these agents. Furthermore, suppression of CTLL-20 proliferation by FeLV-UV and p15 is reversible, because CTLL-20 cells which have been pretreated for 24 hr with FeLV-UV or p15 are equally as efficient at responding to EL4 SN as untreated CTLL-20. Additional studies indicate that CTLL-20 cells continue to remove IL 2 activity from EL4 SN in the presence of suppressive concentrations of FeLV-UV, and that suppressive concentrations of FeLV-UV do not remove IL 2 activity from EL4 SN. This suggests that FeLV does not block CTLL-20 proliferation by absorbing or inactivating IL 2, or by occluding IL 2 receptors, and that T lymphocytes develop an insensitivity to lymphokines after contact with FeLV-UV, which may be caused by a metabolic, rather than an immunologic, defect. Because lymphokines are requisite signals for T cell function, considerable immunosuppression would be associated with acquired lymphokine insensitivity.", "journal": "Journal of immunology (Baltimore, Md. : 1950)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2983866", "author": "Harper HD", "n_authors": 4, "title": "Antitumor activity of protein A administered intravenously to pet cats with leukemia or lymphosarcoma.", "abstract": "Extracorporeal immunoadsorption with protein A (SpA) containing Staphylococcus aureus Cowan I (SAC) has previously been shown to induce an antitumor and antiviral response in some feline leukemia virus (FeLV)-infected, lymphosarcoma (LSA) cats. However, the mechanism by which this response is induced is unknown. Since it is possible that SpA dissociates from the SAC column during treatment, and that intravenous infusion of SpA could be a more efficacious form of treatment than extracorporeal immunoadsorption therapy, 6 normal cats and 15 FeLV-infected pet cats with naturally occurring leukemia or LSA were infused with SpA. No toxic effects resulting from SpA infusion were observed in the normal cats. Antitumor effects were observed in one of the eight cats with LSA and in three of the six cats with leukemia, but there were no antiviral responses. The antitumor responses were objective regressions; however, all tumors recurred. These results demonstrate that infusion of SpA into FeLV-infected LSA or leukemic cats can result in an antitumor but apparently not in an antiviral response.", "journal": "Cancer", "doi": "10.1002/1097-0142(19850501)55:9<1863::aid-cncr2820550903>3.0.co;2-t", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2985857", "author": "Haley PJ", "n_authors": 5, "title": "Influence of antibody infusion on pathogenesis of experimental feline leukemia virus infection.", "abstract": "For examination of the influence of antibody on the pathogenesis of feline leukemia virus (FeLV) infection, 12 weanling specific-pathogen-free cats were inoculated with isolates of FeLV and were treated beginning at 7, 19, 21, 24, 34, or 49 days post inoculation (DPI) with feline anti-FeLV hyperimmune serum (10 infusions, 37 mg globulin/kg each at 48-hr intervals). Anti-FeLV serum infusion initiated at 7 DPI prevented the onset of hematopoietic cell infection and viremia. Antibody treatment initiated at 19 or 24 DPI abrogated recently established FeLV viremia and extinguished p27 expression in bone marrow and blood cells. Viremia established for longer periods was refractory to antibody infusion despite establishment of enzyme-linked immunosorbent assay antibody titers of 1:80 to 1:320 in the treated cats. Latent FeLV infection was a sequel to antibody-induced curtailment of viral replication in bone marrow cells and was able to reactivate spontaneously in vivo as well as in vitro.", "journal": "Journal of the National Cancer Institute", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2983424", "author": "Engelman RW", "n_authors": 4, "title": "Suppression of gamma interferon production by inactivated feline leukemia virus.", "abstract": "Supernatants from cultures of normal feline lymphocytes stimulated with Staphylococcus enterotoxin A showed antiviral activity, characterized as a gamma-like interferon. With the addition of inactivated feline leukemia virus, markedly less interferon was produced. The reduction in interferon production was not attributable to lowered lymphocyte viability or reduced mitogenic properties of Staphylococcus enterotoxin A and appears to be a direct retroviral effect. This finding may reflect clinically relevant events that may contribute to the development of the feline or human states of acquired immunodeficiency.", "journal": "Science (New York, N.Y.)", "doi": "10.1126/science.2983424", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2983560", "author": "Engelman RW", "n_authors": 6, "title": "Clinicopathologic responses in cats with feline leukemia virus-associated leukemia-lymphoma treated with staphylococcal protein A.", "abstract": "Purified protein A from Staphylococcus aureus Cowan I was injected intraperitoneally or was incorporated in filters ex vivo through which plasma from cats with feline leukemia virus (FeLV)-associated leukemia-lymphoma was passed. Before treatment, 65% of the FeLV-infected cats were anemic, and 70% were thrombocytopenic. Concomitant infections, or immune-mediated disease, was common. During treatment 50% of the cats with FeLV-associated disease improved objectively with normal posttreatment hematocrits, thrombocyte and leukocyte counts, disappearance of dysplastic hematologic elements, and correction of marrow dyscrasias. A 33% response to treatment occurred in cats with unequivocal manifestations of malignant disease and was characterized by reductions in tumor size and marrow and peripheral blood neoplastic cell populations. Clearance of FeLV viremia was documented in 28% of the treated cats. The several possible mechanisms by which treatment with staphylococcal protein A causes reduction in the extent of malignant disease are considered.", "journal": "The American journal of pathology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2983093", "author": "Haapala DK", "n_authors": 4, "title": "Isolation from cats of an endogenous type C virus with a novel envelope glycoprotein.", "abstract": "A search for variant endogenous cat viruses led to a novel isolate. Although the major envelope glycoprotein of this virus was similar in size to that of an RD-114-like virus that was coisolated, it was unrelated to RD-114 or feline leukemia virus by immunological and biological criteria. This degree of dissimilarity suggests a different evolutionary progenitor from that for the RD-114 and feline leukemia virus viral envelopes. The novel virus did, however, code for gag gene polypeptides which are closely related to RD-114 virus. Neither the novel isolate nor the RD-114-like coisolate induced foci in S+L- cat cells which restrict focus induction by RD-114 virus. This suggests that the two viruses share a common genomic target of restriction which resides outside of the env region.", "journal": "Journal of virology", "doi": "10.1128/JVI.53.3.827-833.1985", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2981974", "author": "Mochizuki M", "n_authors": 2, "title": "Haemadsorption and haemagglutination by feline leukaemia viruses.", "abstract": "The interaction of feline leukaemia viruses (FeLV) with erythrocytes was investigated. Haemadsorption (HAd) was observed on the surface of feline embryonic fibroblast cells infected with FeLV. HAd was detected in various degrees when cat, hamster or horse erythrocytes were incubated with cells infected with viruses of subgroup C (FeLV-C) and on cells infected with some FeLV subgroup A viruses (FeLV-A), but not on cells infected with FeLV subgroup B viruses (FeLV-B). HAd of sheep erythrocytes was detected on cells infected with some FeLV-C viruses. The HAd of hamster erythrocytes on cells infected with FeLV-C/Sarma virus was inhibited by antisera against gp70 or p15(E) but not by sera to the other FeLV structural polypeptides. HAd inhibition was also exhibited by cat sera which had FeLV-neutralizing activity but not by sera of specific pathogen-free cats. Haemagglutination by FeLV-C viruses was demonstrated after the virus was treated with neuraminidase and phospholipase C, or Tween-80 and ether. Contrary to expectations from the pattern observed by HAd, all FeLV-A viruses had similar haemagglutinin (HA) activity to FeLV-C viruses. FeLV-B viruses did not possess an HA.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-66-2-385", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "15221680", "author": "Grindem CB", "n_authors": 3, "title": "Chemical reactions in cells from leukemic cats.", "abstract": "Cytochemical staining for leukocyte alkaline phosphatase(LAP), nonspecific esterase (NSE), nonspecific esterase with fluoride inhibition (NSE-F), periodic acid Schiff (PAS) reactivity, and peroxidase (PO) was valuable in identification of the neoplastic cell type in 10 leukemic cats. Staining both blood and bone marrow smears was often necessary for making the correct diagnosis. Cytochemical staining resulted in changing the morphologic diagnosis of leukemia in two of the 10 cats. Also, increased LAP activity, probably a marker for myelocytic leukemia in the cat, was observed in bone marrow cells from three nonleukemic, FeLV-positive cats.", "journal": "Veterinary clinical pathology", "doi": "10.1111/j.1939-165x.1985.tb00855.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "3002564", "author": "Ganguly K", "n_authors": 2, "title": "Feline leukemia virus-and feline sarcoma virus-related polypeptides released by virus producer and nonproducer cells.", "abstract": "Polypeptides specific for feline leukemia virus (FeLV) have been identified in the media of cells that produce FeLV as well as in nonproducer cells transformed by feline sarcoma viruses (FeSV). Cat fibroblasts that were persistently infected with FELV release the major virus envelope glycoprotein, whereas cultured cat lymphoma cells shed both glycopeptides related to the virus core gene (gag) and glycopeptides related to the virus envelope gene (env). Mink cells and cat cells transformed by FeSV secrete polypeptides of a wide range of sizes that cross-react with the major virus core protein p27. Differences in the classes of p27-related proteins produced may be related to the strain of virus and the cell type. Cat cells transformed by FeSV release a glycopeptide that appears to be processed differently from those identified in the media of FeSV-transformed mink cells. The possibility that such FeLV-related secretory proteins may interfere with the immune response of the host is discussed.", "journal": "Cancer investigation", "doi": "10.3109/07357908509039814", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "3001436", "author": "Lewis MG", "n_authors": 3, "title": "Reversal of feline retroviral suppression by indomethacin.", "abstract": "The immunosuppressive effect of feline leukemia virus (FeLV) and its 15,000 dalton envelope protein (p15E) were studied to determine if the mechanism of action was due to an increase in prostaglandin production. We examined the effects of exogenous PGE1 and PGE2 on the normal Con A response of feline peripheral blood lymphocytes (PBL) and found them to be inhibitory. The addition of the cyclooxygenase inhibitor indomethacin to cells incubated with FeLV or FeLV p15E and Con A completely abrogated the viral suppressive effects. This reversal was titratable and time-dependent. Other non-steroidal anti-inflammatory (NSAI) drugs were found to have similar actions. Indomethacin was also able to increase the suppressed Con A response of PBL from FeLV-infected cats. Upon measurement of PGE2 levels from PBL cultured with FeLV, we found a decrease in PGE2 accumulation associated with FeLV presence during the first 24 h of culture. These findings indicate that FeLV does not cause its immunosuppressive effects by increasing PG production and suggests that indomethacin and the other tested NSAI drugs do not produce their effect by PG inhibition.", "journal": "Leukemia research", "doi": "10.1016/0145-2126(85)90035-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2999519", "author": "Lewis MG", "n_authors": 3, "title": "The reversal of feline retroviral-induced suppression of lymphocyte Con A receptor mobility by indomethacin and PGE2.", "abstract": "Ultraviolet light-inactivated feline leukemia virus (FeLV) and its 15,000 dalton envelope protein (p15E) inhibited concanavalin A receptor motility of feline peripheral lymphocytes (PBL). In contrast, the virus had no effect on immunoglobulin capping of feline PBL. The inhibitory action of FeLV and FeLV p15E was reversed by the addition of indomethacin. The indomethacin effect was titratable and gave significant reversal between 1 X 10(-5) and 1 X 10(-10) M. The indomethacin inhibition of the prostaglandin synthesis does not appear to be the mechanism of action in its ability to reverse FeLV suppression of Con A receptor mobility. Since the addition of prostaglandin E2 (PGE2) (1.0 microM) was also able to reverse the FeLV-induced inhibition and neither indomethacin nor PGE2 had an observable effect on Con A receptor mobility of normal PBL without FeLV present. PBL from FeLV-infected cats were sensitive to indomethacin (1.0-10.0 microM) and an indomethacin-related increase in cap formation was observed. Since both indomethacin and PGE2 were able to reverse the FeLV-induced suppression it was concluded that their mechanism of action may be through a common site. In addition, indomethacin may prove useful as an immune response modifier for therapy in FeLV-infected cats.", "journal": "Leukemia research", "doi": "10.1016/0145-2126(85)90099-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2993104", "author": "Verbeek JS", "n_authors": 7, "title": "Molecular cloning of the feline c-fes proto-oncogene and construction of a chimeric transforming gene.", "abstract": "The feline c-fes proto-oncogene, different parts of which were captured in feline leukemia virus (FeLV) to generate the transforming genes (v-fes) of the Gardner-Arnstein (GA) strain of feline sarcoma virus (FeSV) and the Snyder-Theilen strain (ST) of FeSV, was cloned and its genetic organization determined. Southern blot analysis revealed that the c-fes genetic sequences were distributed discontinuously and colinearly with the v-fes transforming gene over a DNA region of around 12.0 kb. Using cloned c-fes sequences, complementation of GA-FeSV transforming activity was studied. Upon replacement of the 3' half of v-fesGA with homologous feline c-fes sequences and transfection of the chimeric gene, morphological transformation was observed. Immunoprecipitation analysis of these transformed cells revealed expression of high Mr fusion proteins. Phosphorylation of these proteins was observed in an in vitro protein kinase assay, and tyrosine residues appeared to be involved as acceptor amino acid.", "journal": "Gene", "doi": "10.1016/0378-1119(85)90155-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2989102", "author": "Wong TC", "n_authors": 4, "title": "The promoter of the long terminal repeat of feline leukemia virus is effective for expression of a mouse H-2 histocompatibility gene in mouse and human cells.", "abstract": "DNA-mediated gene transfer techniques have been used to study the effectiveness of a novel construction involving the feline leukemia virus long terminal repeat (FeLV LTR) for expressing the mouse H-2 Ld gene in mouse and human cells. In this construction, the transcription initiation (promoter) and termination (polyadenylation) functions of the FeLV LTR have been split by insertion of a promoterless H-2 gene between them. An S1 nuclease assay has been developed that makes it possible to measure accumulated LdRNA against a background of endogenous major histocompatibility antigen RNAs in mouse and human cells. In mouse cells, the H-2 Ld gene was expressed at approximately equal levels (measured as accumulated RNA) when driven either by its own promoter or by the FeLV LTR construction. In human cells, expression at the RNA level was highest when driven by the FeLV LTR. We conclude that the FeLV LTR construction is useful for expressing foreign genes in human cells.", "journal": "Gene", "doi": "10.1016/0378-1119(85)90291-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2986521", "author": "Neil JC", "n_authors": 2, "title": "Feline leukaemia viruses: molecular biology and pathogenesis.", "abstract": "The feline leukaemia virus (FeLV) group represents one of the most important viral pathogens of the domestic cat. In addition, this virus - host system is one of the major experimental models for retroviral pathogenesis. Under natural conditions, the virus is horizontally transmitted through the cat population. The outcome of infection depends on a variety of factors including the virus does encountered and the age and immune status of the host. FeLVs can establish persistent infection, either overt or latent. Degenerative diseases of the haemopoietic system are the most common result of persistent infection and immunosuppression with secondary infection accounts for more deaths than does neoplastic disease. However, more is known about the molecular mechanisms of oncogenesis in this system and there are now numerous examples of field case tumours where FeLV has transduced an oncogene or acted as an insertional mutagen. The factors affecting the relative frequency of these mechanisms are considered as is the possibility that recombinant env gene recombinants play a role in FeLV pathogenesis.", "journal": "Anticancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2981248", "author": "Abkowitz JL", "n_authors": 6, "title": "Feline glucose-6-phosphate dehydrogenase cellular mosaicism. Application to the study of retrovirus-induced pure red cell aplasia.", "abstract": "Neoplasms result from the uncontrolled proliferation of abnormal or transformed cells. The early stages of this process are difficult to study because of the lack of sensitive and specific markers of clonal evolution in an experimental system. We have developed a cat model using cellular mosaicism for glucose-6-phosphate dehydrogenase (G-6-PD). Our findings confirm that the structural locus for feline G-6-PD is on the X-chromosome and demonstrate that it is randomly inactivated in somatic cells. Heterozygous cats have balanced ratios of G-6-PD enzyme types in peripheral blood cells and hematopoietic progenitors that remain stable over time. In our initial studies, we used the model to analyze the events surrounding marrow failure experimentally induced by selected strains of feline leukemia virus (FeLV). Two G-6-PD heterozygous cats, one F1 male hybrid and one domestic cat were infected with FeLV (C or KT) and developed pure red cell aplasia (PRCA). Colonies arising from the more mature erythroid colony-forming cell were not detected in marrow culture of anemic animals although erythroid bursts persisted, suggesting that the differentiation of early erythroid progenitors (BFU-E) was inhibited in vivo. The ratio of G-6-PD types in hematopoietic progenitors and peripheral blood cells from the heterozygous cats did not change when the animals developed PRCA. Thus, the anemia did not result from the clonal expansion of a transformed myeloid stem cell. With this experimental approach, one may prospectively assess clonal evolution and cellular interactions in other FeLV-induced diseases.", "journal": "The Journal of clinical investigation", "doi": "10.1172/JCI111665", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3028385", "author": "Lewis MG", "n_authors": 4, "title": "Identification of calmodulin activity in purified retroviruses.", "abstract": "Several viruses have been shown to require calcium for their function, and to bind calcium at specific sites. However, the nature of the calcium binding molecule on viruses has not been established. One possibility is the ubiquitous calcium-binding protein calmodulin. Our studies were designed to determine whether feline leukemia virus contained calmodulin. Accordingly, we tested purified feline leukemia virus for the presence of calmodulin-like activity. The virus, like authentic calmodulin, activated cyclic AMP phosphodiesterase. The ability of the virus to activate the enzyme was blocked in the presence of the known calmodulin inhibitors trifluoperazine and W-7. This indirect evidence for the presence of calmodulin was confirmed by radioimmunoassay. Several other retroviruses were also tested using radioimmunoassay and found to contain calmodulin. Our results indicate that the calcium binding site in retroviruses may be calmodulin.", "journal": "Biochemical and biophysical research communications", "doi": "10.1016/s0006-291x(86)80153-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3491989", "author": "Hirsch V", "n_authors": 6, "title": "Cross-reactivity to human T-lymphotropic virus type III/lymphadenopathy-associated virus and molecular cloning of simian T-cell lymphotropic virus type III from African green monkeys.", "abstract": "Simian T-lymphotropic retroviruses with structural, antigenic, and cytopathic features similar to the etiologic agent of human acquired immunodeficiency syndrome, human T-lymphotropic virus type III/lymphadenopathy-associated virus (HTLV-III/LAV), have been isolated from a variety of primate species including African green monkeys (STLV-IIIAGM). This report describes nucleic acid cross-reactivity between STLV-IIIAGM and HTLV-III/LAV, molecular cloning of the STLV-IIIAGM genome, and evaluation of its structure and genetic relationship to other retroviruses. Overlapping clones from a cell line infected with virus from a single animal were found to encompass the entire STLV-IIIAGM genome and exhibit a limited degree of restriction-site variability. Specific hybridizing fragments were detected in DNA from this and other STLV-IIIAGM-infected cell lines. A fraction of viral DNA present in at least two STLV-IIIAGM lines persists as unintegrated viral DNA, a characteristic of infection with cytopathic retroviruses. Strongest cross-reactivity was detected between HTLV-III/LAV pol- and gag- genes and STLV-IIIAGM, whereas no cross-reactivity was detected between STLV-IIIAGM and molecular clones of human T-lymphotropic virus types I and II (HTLV-I and -II), visna virus, bovine leukemia virus, or feline leukemia virus.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.83.24.9754", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3024406", "author": "Ishida T", "n_authors": 3, "title": "Monoclonal antibodies to the v-fes product and to feline leukemia: virus P27 interspecies-specific determinants encoded by feline sarcoma viruses.", "abstract": "Monoclonal antibodies to p27 gag and v-fes specific determinants on the gag-onc poly-protein encoded by Snyder-Theilen feline sarcoma virus (ST-FeSV) were prepared. In order to obtain hybridoma clones specific to the antigenic determinants encoded by the FeSV genome, Lou rats were immunized with ST-FeSV-transformed, virus-nonproducing syngeneic cells, and boosted with either the same cells or affinity-purified feline leukemia virus (FeLV) p27. Three distinct clones reactive to both FeLV p27 and p85gag-fes, and one clone specific for a p85fes determinant were established. The anti-p27 monoclonal antibodies also reacted with the polyproteins p95gag-fes and p83gag-fgr, from Gardner-Arnstein (GA) and Theilen-Pedersen (TP1) FeSV, respectively. The anti-p27 monoclonal antibodies reacted with MuLV p30 and RD114 p28 but not with RSV, MMTV, or BLV. These results indicated that the part of the p27 gag gene that is preserved in ST-, GA, and TP1-FeSV encodes interspecies-specific p27 determinants.", "journal": "Virology", "doi": "10.1016/0042-6822(86)90227-8", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3026079", "author": "Weijer K", "n_authors": 3, "title": "Control of feline leukaemia virus infection by a removal programme.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.119.22.555", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3022000", "author": "Wernicke D", "n_authors": 4, "title": "Humoral immune response of asymptomatic cats naturally infected with feline leukemia virus.", "abstract": "The humoral immune response of cats that were naturally infected with the feline leukemia virus (FeLV) was examined after antigenic stimulation with the synthetic antigen poly(L-Tyr, L-Glu)-poly(DL-Ala)-poly(L-Lys). The primary humoral antibody response in FeLV-infected cats was both delayed and greatly reduced, compared with that seen in uninfected control cats. A similar discordance was observed after secondary stimulation with the antigen, in the FeLV-infected cats had both a delayed response and a reduced response, compared with uninfected cats. The levels of total immunoglobulins of the immunoglobulin G and immunoglobulin M classes in the sera of FeLV-infected cats were significantly higher (two- and threefold, respectively) than were those of the uninfected control animals. The presence of an impaired humoral immune response to newly presented antigens in the presence of elevated immunoglobulin levels has been thoroughly documented in the case of people with the acquired immunodeficiency syndrome. This further emphasizes the potential value of FeLV-infected cats as a model for human acquired immunodeficiency syndrome.", "journal": "Journal of virology", "doi": "10.1128/JVI.60.2.669-673.1986", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "2851578", "author": "Briggs MB", "n_authors": 2, "title": "Feline leukemia virus infection in a captive cheetah and the clinical and antibody response of six captive cheetahs to vaccination with a subunit feline leukemia virus vaccine.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3018999", "author": "Stewart MA", "n_authors": 6, "title": "Conservation of the c-myc coding sequence in transduced feline v-myc genes.", "abstract": "We have cloned the normal feline c-myc locus and determined the nucleotide sequence of all three exons. The feline c-myc gene shows close homology to other mammalian c-myc genes, particularly human c-myc. The feline and human sequences are colinear within the open reading frame for the putative c-myc product but show insertions and deletions relative to each other outside this domain. We have also analyzed a cloned FeLV provirus, CT4, which contains the host-derived myc gene. In this provirus the v-myc sequences are located at the 3' end of the pol gene, replacing pol and env sequences. Nucleotide sequence analysis of CT4 shows an open reading frame for a v-myc gene product which may be expressed without fusion to any viral protein sequences. This contrasts with another FeLV v-myc (LC), in which myc and gag sequences were found to be fused. Unlike previously identified avian v-myc genes, the feline v-myc genes contain exon 1-derived sequences, but these have been truncated or internally deleted. The FeLV CT4 v-myc sequence shows very few coding changes relative to c-myc and the FeLV LC v-myc coding sequence is unchanged relative to c-myc apart from fusion to gag. These results are discussed in relation to the mechanism of transduction and activation of myc by FeLV.", "journal": "Virology", "doi": "10.1016/0042-6822(86)90435-6", "deposited_data": "Sim", "nuccore_ids": "2884342622, 1036032670, 323924, 2884342622, 2131073108, 2131073107", "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3787999", "author": "Nash AS", "n_authors": 2, "title": "Haemobartonella felis infection in cats from the Glasgow area.", "abstract": "A survey of 155 cats for Haemobartonella felis infection in the Glasgow area revealed a prevalence of 23.2 per cent. The infection occurred in all age groups and there was no significant difference between sex or breed type. Infection with H felis was more prevalent among cats with fleas and those with feline leukaemia virus infection than among the other cats in the sample. H felis organisms identified were mainly coccoid with diameters between 0.63 micron and 1.73 micron. Rod forms, found in two cats, had lengths ranging from 0.79 micron to 1.1 micron and diameters between 0.17 micron and 0.24 micron.", "journal": "The Veterinary record", "doi": "10.1136/vr.119.15.373", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3022625", "author": "Wardrop KJ", "n_authors": 5, "title": "Quantitative studies of erythropoiesis in the clinically normal, phlebotomized, and feline leukemia virus-infected cat.", "abstract": "Erythropoiesis was evaluated in 5 cats at base line with normal PCV and then in the same cats with anemia induced by phlebotomy and in 5 other cats with nonregenerative anemia from community-acquired feline leukemia virus (FeLV) infection. The hematologic evaluation included complete blood cell and reticulocyte counts, marrow morphologic features, determination of serum erythropoietin concentrations by radioimmunoassay, ferrokinetic studies, and in vitro marrow culture of early erythroid progenitors (erythroid burst-forming units; BFU-E) and late erythroid progenitors (erythroid colony-forming units; CFU-E). Phlebotomized cats developed marrow erythroid hyperplasia and an increased reticulocyte count. Ferrokinetic studies revealed an increase in plasma iron turnover from 1.4 to 3.8 mg of Fe/dl of blood/day and RBC use from 50.4% to 78.5%. The mean CFU-E number and CFU-E/BFU-E ratio increased after phlebotomy, but the increase was not significant (P greater than 0.05). Serum erythropoietin values did increase significantly. In FeLV-infected cats, a nonregenerative anemia was demonstrated by marrow erythroid hypoplasia and a low total reticulocyte count. An increased percentage of rubriblasts and prorubricytes was observed in 4 of the 5 cats. Although serum erythropoietin values were high (321 +/- 123 mU/ml vs normal 14 +/- 1 mU/ml), ferrokinetic data revealed decreased erythropoiesis. Marrow culture studies in the FeLV-infected cats also revealed low numbers of BFU-E and CFU-E, but normal numbers of granulocyte-macrophage progenitors remained. Seemingly, the FeLV infection impaired the ability of feline marrow to respond physiologically to anemia.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3022623", "author": "Cogan DC", "n_authors": 3, "title": "Effect of suramin on serum viral replication in feline leukemia virus-infected pet cats.", "abstract": "Suramin treatments were administered (IV) to 2 healthy adult cats infected with naturally acquired feline leukemia virus. Serum viral infectivity--as assessed by focus induction by the method of Fischinger, using serial serum samples titrated on clone 81 cells--ceased transiently in both cats during treatment with suramin, but returned to significantly high levels approximately 14 days after treatment was stopped. Both cats tested positive for FeLV internal antigens in peripheral blood cells and serum before, during, and after treatment. Both cats tested negative for antibody to feline oncornavirus membrane antigen before, during, and after treatment. The major adverse effects of suramin in the 2 cats were transient vomiting and anorexia.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3020157", "author": "Lewis MG", "n_authors": 5, "title": "Polymorphonuclear leukocyte dysfunction associated with feline leukaemia virus infection.", "abstract": "The chemiluminescent characteristics of enriched (greater than 95%) peripheral blood polymorphonuclear leukocyte populations (PMN) from normal and feline leukaemia virus (FeLV)-infected cats were investigated. FeLV-infected cats demonstrated a significantly lower (P less than 0.001) PMN chemiluminescent response when compared to the response of normal age-matched controls. Normal PMN treated with FeLV-infected cat serum exhibited a depressed response in comparison to control cells. A titration of serum from infected cats supplemented with normal serum revealed a titratable suppression of chemiluminescence with increasing concentration of serum from the infected cats. However, PMN from FeLV-infected cats treated with normal serum displayed a slight increase in chemiluminescence over the same cells in autologous serum. The addition of inactivated FeLV to normal PMN caused a titratable decrease in chemiluminescence.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-67-10-2113", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3018287", "author": "Riedel N", "n_authors": 5, "title": "Molecular analysis and pathogenesis of the feline aplastic anemia retrovirus, feline leukemia virus C-Sarma.", "abstract": "We describe the molecular cloning of an anemogenic feline leukemia virus (FeLV), FeLV-C-Sarma, from the productively infected human rhabdomyosarcoma cell line RD(FeLV-C-S). Molecularly cloned FeLV-C-S proviral DNA yielded infectious virus (mcFeLV-C-S) after transfection of mammalian cells, and virus interference studies using transfection-derived virus demonstrated that our clone encodes FeLV belonging to the C subgroup. mcFeLV-C-S did not induce viremia in eight 8-week-old outbred specific-pathogen-free (SPF) cats. It did, however, induce viremia and a rapid, fatal aplastic anemia due to profound suppression of erythroid stem cell growth in 9 of 10 inoculated newborn, SPF cats within 3 to 8 weeks (21 to 58 days) postinoculation. Thus, the genome of mcFeLV-C-S encodes the determinants responsible for the genetically dominant induction of irreversible erythroid aplasia in outbred cats. A potential clue to the pathogenic determinants of this virus comes from previous work indicating that all FeLV isolates belonging to the C subgroup, an envelop-gene-determined property, and only those belonging to the C subgroup, are potent, consistent inducers of aplastic anemia in cats. To approach the molecular mechanism underlying the induction of this disease, we first determined the nucleotide sequence of the envelope genes and 3' long terminal repeat of FeLV-C-S and compared it with that of FeLV-B-Gardner-Arnstein (mcFeLV-B-GA), a subgroup-B feline leukemia virus that consistently induces a different disease, myelodysplastic anemia, in neonatal SPF cats. Our analysis revealed that the p15E genes and long terminal repeats of the two FeLV strains are highly homologous, whereas there are major differences in the gp70 proteins, including five regions of significant amino acid differences and apparent sequence substitution. Some of these changes are also reflected in predicted glycosylation sites; the gp70 protein of FeLV-B-GA has 11 potential glycosylation sites, only 8 of which are present in FeLV-C-S.", "journal": "Journal of virology", "doi": "10.1128/JVI.60.1.242-250.1986", "deposited_data": "Sim", "nuccore_ids": "323898", "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3018286", "author": "Besmer P", "n_authors": 7, "title": "A new acute transforming feline retrovirus with fms homology specifies a C-terminally truncated version of the c-fms protein that is different from SM-feline sarcoma virus v-fms protein.", "abstract": "The HZ5-feline sarcoma virus (FeSV) is a new acute transforming feline retrovirus which was isolated from a multicentric fibrosarcoma of a domestic cat. The HZ5-FeSV transforms fibroblasts in vitro and is replication defective. A biologically active integrated HZ5-FeSV provirus was molecularly cloned from cellular DNA of HZ5-FeSV-infected FRE-3A rat cells. The HZ5-FeSV has oncogene homology with the fms sequences of the SM-FeSV. The genome organization of the 8.6-kilobase HZ5-FeSV provirus is 5' delta gag-fms-delta pol-delta env 3'. The HZ5-and SM-FeSVs display indistinguishable in vitro transformation characteristics, and the structures of the gag-fms transforming genes in the two viruses are very similar. In the HZ5-FeSV and the SM-FeSV, identical c-fms and feline leukemia virus p10 sequences form the 5' gag-fms junction. With regard to v-fms the two viruses are homologous up to 11 amino acids before the C terminus of the SM-FeSV v-fms protein. In HZ5-FeSV a segment of 362 nucleotides then follows before the 3' recombination site with feline leukemia virus pol. The new 3' v-fms sequence encodes 27 amino acids before reaching a TGA termination signal. The relationship of this sequence with the recently characterized human c-fms sequence has been examined. The 3' HZ5-FeSV v-fms sequence is homologous with 3' c-fms sequences. A frameshift mutation (11-base-pair deletion) was found in the C-terminal fms coding sequence of the HZ5-FeSV. As a result, the HZ5-FeSV v-fms protein is predicted to be a C-terminally truncated version of c-fms. This frameshift mutation may determine the oncogenic properties of v-fms in the HZ5-FeSV.", "journal": "Journal of virology", "doi": "10.1128/JVI.60.1.194-203.1986", "deposited_data": "Sim", "nuccore_ids": "1015600352", "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3021028", "author": "Reimann KA", "n_authors": 5, "title": "Immunologic profiles of cats with persistent, naturally acquired feline leukemia virus infection.", "abstract": "Several immunologic responses were measured in 13 healthy cats with naturally acquired, persistent feline leukemia virus (FeLV) viremia from 4 multiple-cat households and were compared with responses from 28 of their healthy, non-FeLV-viremic housemates. Significant differences (P = less than 0.05) were not observed between results of FeLV-viremic and nonviremic cats for peripheral blood leukocyte or lymphocyte count, percentage of peripheral blood mononuclear cells able to form rosettes with guinea pig RBC or with antibody- and complement-coated sheep RBC, lymphocyte proliferative response to concanavalin A or pokeweed mitogen, or serum immunoglobulin G concentration. Seemingly, persistent FeLV viremia, when naturally acquired, may exist for some time without lymphopenia or a marked loss of mitogen-induced lymphocyte proliferation.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3525854", "author": "Wheeler EF", "n_authors": 8, "title": "The amino-terminal domain of the v-fms oncogene product includes a functional signal peptide that directs synthesis of a transforming glycoprotein in the absence of feline leukemia virus gag sequences.", "abstract": "The nucleotide sequence of a 5' segment of the human genomic c-fms proto-oncogene suggested that recombination between feline leukemia virus and feline c-fms sequences might have occurred in a region encoding the 5' untranslated portion of c-fms mRNA. The polyprotein precursor gP180gag-fms encoded by the McDonough strain of feline sarcoma virus was therefore predicted to contain 34 v-fms-coded amino acids derived from sequences of the c-fms gene that are not ordinarily translated from the proto-oncogene mRNA. The (gP180gag-fms) polyprotein was cotranslationally cleaved near the gag-fms junction to remove its gag gene-coded portion. Determination of the amino-terminal sequence of the resulting v-fms-coded glycoprotein, gp120v-fms, showed that the site of proteolysis corresponded to a predicted signal peptidase cleavage site within the c-fms gene product. Together, these analyses suggested that the linked gag sequences may not be necessary for expression of a biologically active v-fms gene product. The gag-fms sequences of feline sarcoma virus strain McDonough and the v-fms sequences alone were inserted into a murine retroviral vector containing a neomycin resistance gene. Both constructs were biologically active when transfected into NIH 3T3 cells and produced morphologically transformed foci at equivalent efficiencies. When transfected into a cell line (psi 2) expressing complementary viral gene functions, G418-resistant (Neor) cells containing either of these vector DNAs produced high titers of transforming viruses. Analysis of proteins produced in cells containing the vector lacking gag gene sequences showed that gP180gag-fms was not synthesized, whereas normal levels of both immature gp120v-fms and mature gp140v-fms were detected. The glycoprotein was efficiently transported to the cell surface, and it retained wild-type tyrosine kinase activity. We conclude that a cryptic hydrophobic signal peptide sequence in v-fms was unmasked by gag deletion, thereby allowing the correct orientation and transport of the v-fms gene product within membranous organelles. It seems likely that the proteolytic cleavage of gP180gag-fms is mediated by signal peptidase and that the amino termini of gp140v-fms and the c-fms gene product are identical.", "journal": "Journal of virology", "doi": "10.1128/JVI.59.2.224-233.1986", "deposited_data": "Sim", "nuccore_ids": "182676, 1890391548, 1890334128, 1889652442, 1769155979, 1769069769, 1769047530, 1769047514", "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "2426463", "author": "Tanese N", "n_authors": 3, "title": "Analysis of retroviral pol gene products with antisera raised against fusion proteins produced in Escherichia coli.", "abstract": "Portions of the pol gene of Moloney murine leukemia virus (MuLV) were expressed as fusion proteins in Escherichia coli, and the purified proteins were used to elicit antibodies in Escherichia coli, and the purified proteins were used to elicit antibodies in rabbits. The sera were used to examine the mature pol gene products contained in virion particles and identified the reverse transcriptase and a second protein, P46pol, encoded by the 3' portion of the gene. The P46 protein was not phosphorylated and was present at the same molar abundance as the reverse transcriptase. The sera were also used to detect the Pr200gag-pol intracellular precursor protein and to analyze its processing to the mature forms. The proteins formed by several Moloney MuLV mutants were analyzed. Further tests revealed cross-reactivity with Friend MuLV and feline leukemia virus proteins, but not with avian retrovirus proteins.", "journal": "Journal of virology", "doi": "10.1128/JVI.59.2.328-340.1986", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3013786", "author": "Weijer K", "n_authors": 5, "title": "Post-exposure treatment with monoclonal antibodies in a retrovirus system: failure to protect cats against feline leukemia virus infection with virus neutralizing monoclonal antibodies.", "abstract": "We have attempted to protect kittens against oronasal infection with FeLV (strain A/Glasgow-1) by treatment with a mixture of two virus-neutralizing (VN) MAbs (IgGl, K) directed against the same epitope on the viral glycoprotein gp70. Ten SPF 9-week-old kittens were infected on day 0 with 10(6) ffu FeLV and subsequently inoculated i.m. with MAbs every 2 days over a 20-day period at different times after infection. The results clearly show that no protection was achieved. It is unlikely that the amount of VN antibodies, the mode and route of their application or the infectious dose of FeLV used can account for the failure to protect cats against infection. Other possibilities which may explain the lack of protective effect are that the restricted epitope specificity of the MAb preparation used may have led to selection of neutralization-resistant virus mutants, or that other mechanisms than virus neutralization (complement-mediated lysis, antibody-dependent cell cytotoxicity), that may be involved in protection, function less efficiently with MAb. However, in the light of our finding that an early anti-idiotypic response is observed in all cats following administration of the MAb preparation, the rapid clearance of anti-FeLV MAb from the circulation is a more likely explanation. The data presented support our hypothesis that by administration of MAb-as compared to polyclonal antibody-a more vigorous anti-idiotypic response is elicited due to the presentation of only a limited set of idiotopes. This potential drawback of rapid clearance of MAbs as a consequence of an anti-idiotypic response might be overcome by the use of mixtures of MAbs resulting in a more heterogeneous set of idiotypic determinants.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910380114", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3750732", "author": "Moore FM", "n_authors": 4, "title": "Distinctive peripheral lymph node hyperplasia of young cats.", "abstract": "Peripheral lymph node enlargement was found in 14 of a series of 132 feline lymph node biopsy specimens. Six of nine cats tested had antibodies for feline leukemia virus (FeLV). Half of the cats were clinically normal while the remainder had fever, lethargy, anorexia, and hepatosplenomegaly. There was severe distortion of lymph nodal architecture with variable loss of discernible follicles and sinuses. Histiocytes, lymphocytes, immunoblasts, and plasma cells were present in expanded paracortical regions which encroached on, and occasionally effaced, lymphoid follicles. Postcapillary venules were numerous and prominent throughout the paracortex. The lymphadenopathy was most commonly transient (86% of cases) with subsequent development of lymphoma in one cat. Lymph nodes from seven kittens with experimental FeLV infection were compared with spontaneously enlarged lymph nodes; four of seven had B and T lymphocyte hyperplasia with normal nodal architecture. Three had partial loss of nodal architecture as a result of expanded paracortical regions populated largely by histiocytes and lymphocytes. Proliferation of postcapillary venules was not prominent in nodes from FeLV-infected cats. The cause of spontaneous lymph node hyperplasia of young cats was not determined. However, the similarity of lesions to those of kittens with experimental FeLV infection and the association with FeLV by serologic tests in six of nine cats suggest that this retrovirus may be involved in the pathogenesis of the lesion.", "journal": "Veterinary pathology", "doi": "10.1177/030098588602300407", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3018983", "author": "Toth SR", "n_authors": 3, "title": "Histopathological and hematological findings in myeloid leukemia induced by a new feline leukemia virus isolate.", "abstract": "Myeloid leukemia was induced by a new feline leukemia virus isolate FeLV-AB/GM-1 in a high proportion of cats. The latency period was short. Three to 5 weeks after infection early changes were detectable in the bone marrow, and cats developed leukemia 5 to 8 weeks after infection. The results of the present histological and cytological studies suggested that there were two stages in the development of leukemia. The first stage appeared to be equivalent to the syndrome of bone marrow dysplasia or preleukemia which, however, converted rapidly to leukemia. Cytopenia(s) were the main hematological findings in all preleukemic and leukemic cats. White blood cell counts were low or normal, but the number of leukemic and abnormal cells increased in the peripheral blood with the progression of the disease. This reliable model system lends itself to further studies to elucidate the pathogenesis of myeloproliferative disorders.", "journal": "Veterinary pathology", "doi": "10.1177/030098588602300417", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3009890", "author": "Stewart MA", "n_authors": 7, "title": "Nucleotide sequences of a feline leukemia virus subgroup A envelope gene and long terminal repeat and evidence for the recombinational origin of subgroup B viruses.", "abstract": "Molecular clones of the subgroup A feline leukemia virus FeLV-A/Glasgow-1 have been obtained. Nucleotide sequence analysis of the 3' end of the proviral genome and comparison with the published sequence of FeLV-B/Gardner-Arnstein showed that the most extensive differences are located within the 5' domain of the env gene. Within this domain, several divergent regions of env are separated by more conserved segments. The 3' end of env is highly conserved, with only a single amino acid coding difference in p15env. The proviral long terminal repeats are also highly conserved, differing by only eight base substitutions and one base insertion. Specific probes constructed from the FeLV-A or FeLV-B env genes were used to compare the env genes of various exogenous FeLV isolates and the endogenous FeLV-related proviruses of normal cat DNA. An FeLV-A-derived env probe showed no hybridization to normal cat DNA but detected all FeLV-A and FeLV-C isolates tested. In contrast, an FeLV-B env probe detected independent FeLV-B isolates and a family of endogenous FeLV-related proviruses. Our observations provide strong evidence to support the hypothesis that FeLV-B viruses have arisen by recombination between FeLV-A and endogenous proviral elements in cat DNA.", "journal": "Journal of virology", "doi": "10.1128/JVI.58.3.825-834.1986", "deposited_data": "Sim", "nuccore_ids": "323912", "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3014644", "author": "Lutz H", "n_authors": 1, "title": "[The feline leukemia virus vaccine Leukocell: reference for use].", "abstract": null, "journal": "Schweizer Archiv fur Tierheilkunde", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3011717", "author": "Hawkins EC", "n_authors": 4, "title": "Use of tears for diagnosis of feline leukemia virus infection.", "abstract": "A comparison was made of the use of serum, tears, and saliva for the detection of feline leukemia virus (FeLV) infection in cats. Cotton swabs were used to collect saliva, and tear-test strips were used to collect tears. Specimens were analyzed by a commercially available ELISA. Using a 10- to 15-minute specimen incubation period, FeLV was detected in 70% of the saliva specimens and in 73% of the tear specimens from viremic (serum-positive) cats. Feline leukemia virus antigen was not detected in saliva and tear specimens from serum-negative cats. The sensitivity of the tear assay was improved by increasing the incubation time to 24 hours. Tear strips could be air-dried and stored at room temperature for up to 7 days without any appreciable loss of activity. Client-owned and experimentally infected laboratory cats were tested for FeLV, using air-dried tear-test strips and a 24-hour incubation period. Tears were positive (contained FeLV antigen) in 65 of 72 (90%) serum-positive cats and did not contain antigen in 46 of 46 (100%) serum-negative cats. Results of ELISA obtained from serum and tears also were compared with results obtained from indirect fluorescent antibody testing of blood smears. Results of indirect fluorescent antibody and ELISA compared favorably with each other and with the results of tear testing.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "2423498", "author": "Engelman RW", "n_authors": 7, "title": "Characterization of a newly established feline lymphoma-derived cell line (BKD) lacking T and B cell surface markers.", "abstract": "A new feline lymphoma-derived cell line, designated BKD, was isolated from an anterior mediastinal tumor. Cells of this line were characterized as lymphoid based on morphology, the lack of intracellular esterase and peroxidase activity, and absence of phagocytic function. In contrast with other established feline lymphoma-derived cell lines, cells of the BKD line lack characteristics of both feline T-cells and B-cells in that they neither form rosettes with guinea pig erythrocytes nor have demonstrable surface or cytoplasmic immunoglobulin. Approximately one third of BKD cells form EAC rosettes, a significant number of rosette forming cells (p = 0.0001) when compared to background sheep E-rosetting activity. In addition, a consistently titratable level of interleukin-2-like activity was produced when BKD cells were coincubated with concanavalin A and phorbol-12-myristate-13-acetate. Chromosome analysis showed that a majority of BKD cells are diploid. This new cell line has been continuously replicating in culture for over one year and produces feline leukemia virus as demonstrated by several analyses.", "journal": "In vitro cellular & developmental biology : journal of the Tissue Culture Association", "doi": "10.1007/BF02621230", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3012849", "author": "Pacitti AM", "n_authors": 3, "title": "Transmission of feline leukaemia virus in the milk of a non-viraemic cat.", "abstract": "The possibility of the transmission of feline leukaemia virus (FeLV) from latently infected cats was studied. Five female cats with latent infections were examined for evidence of transmission of the virus to their kittens. One of the cats infected members of four consecutive litters of kittens which subsequently became persistently viraemic and transmitted the virus to other susceptible kittens by contact. Shortly after birth its kittens were apparently FeLV-free since neither viral antigen nor infectious virus was detected in their blood and no virus was found in cell cultures made from aspirates of bone marrow. The kittens became viraemic from 45 days of age onwards at a time when their passively acquired colostral FeLV neutralising antibodies were no longer detectable. Transmission of the virus occurred via the milk since both FeLV antigen and infectious virus were found in milk samples taken six weeks after kittening and the virus was transmitted to a fostered kitten. Eleven weeks after the birth of the fourth litter the cat became viraemic. The intermittent presence of FeLV antigens detected by the Leukassay F test, but not infectious virus, in the plasma of this cat over the previous months and a low level of serum neutralising antibodies distinguished it from four other latently infected queens which did not transmit infection to their kittens. These factors may indicate a risk of milk transmission and reactivation of latent virus.", "journal": "The Veterinary record", "doi": "10.1136/vr.118.14.381", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3007997", "author": "Besmer P", "n_authors": 10, "title": "A new acute transforming feline retrovirus and relationship of its oncogene v-kit with the protein kinase gene family.", "abstract": "A new acute transforming feline retrovirus, the Hardy-Zuckerman 4 feline sarcoma virus (HZ4-FeSV), has been isolated from a feline fibrosarcoma. The viral genome of HZ4-FeSV contains a new oncogene designated v-kit, has the structure 5' delta gag-kit-delta pol-delta env 3' and specifies a gag-kit polyprotein of relative molecular mass 80,000. The predicted kit amino-acid sequence displays partial homology with tyrosine-specific protein kinase oncogenes. HZ4-FeSV appears to have been generated by transduction of feline c-kit sequences with feline leukaemia virus.", "journal": "Nature", "doi": "10.1038/320415a0", "deposited_data": "Sim", "nuccore_ids": "1464310402, 61535, 170650720, 170650718", "bioproject_ids": "485481", "sra_ids": null}, {"year": 1986, "pmid": "3008612", "author": "Lafrado LJ", "n_authors": 3, "title": "Evaluation of terminal deoxynucleotidyl transferase expression in bone marrow of clinically normal and feline leukemia virus-exposed cats.", "abstract": "Bone marrow cells from 8 specific-pathogen-free and 11 feline leukemia virus-exposed cats were examined for the expression of the nuclear antigen terminal deoxynucleotidyl transferase (TdT). Using a standard indirect immunofluorescence technique, feline leukemia-exposed cats had increased expression of TdT in bone marrow aspirates (2.0% to 29.0%) when compared with that in bone marrow cells from specific-pathogen-free cats (2.5% to 6.0%). Seemingly, TdT can be used as an antigenic marker in leukemogenesis of FeLV-infected cats.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3008609", "author": "McMichael JC", "n_authors": 3, "title": "Prevalence of feline leukemia virus infection among adult cats at an animal control center: association of viremia with phenotype and season.", "abstract": "The overall frequency of feline leukemia virus infection among 555 cats tested from the Hillsborough County Florida Animal Control facility, using a commercial enzyme-linked immunosorbent assay, was 9.4%. Among male cats, the frequency was 13.8%, which was statistically higher (P = 0.003) than that for females (5.9%). There was no statistical evidence to associate frequency of viral infection with hair length or coloration. There was an association with color distribution. The frequency of viral infection in cats with a solid color in their coat, excluding tabby, calico, and tortoise, was higher (12.2%) than the frequency in the remainder of the cats (5.5%; P = 0.011). Finally, there was a difference in frequency related to season. For the 10 months of the study, cats collected in the 5 cooler months (January, February, March, April, and October) had a frequency of 14.6%; cats obtained in the 5 warmer months (May, June, July, August, and September) had a frequency of 7.2% (P = 0.038).", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3007539", "author": "Abkowitz JL", "n_authors": 4, "title": "Multilineage, non-species specific hematopoietic growth factor(s) elaborated by a feline fibroblast cell line: enhancement by virus infection.", "abstract": "In studies designed to determine the role of feline leukemia virus (FeLV) in the pathogenesis of marrow failure in the cat, we tested medium conditioned by uninfected and FeLV-infected feline embryonic fibroblasts (FEA) for its effect on hematopoietic colony growth in culture. As opposed to an inhibitory effect, we found that the conditioned medium (CM) from FEA or FEA/FeLV increased the in vitro growth of multiple hematopoietic progenitor cell types including erythroid burst-forming cells (BFU-E), granulocyte/macrophage colony-forming cells, megakaryocytic colony-forming cells, and mixed-cell colony-forming cells. Furthermore, CM enhanced the growth of progenitors in cultures of mouse or human marrow cells, as well as cat marrow cells. Stimulation of feline BFU-E was most marked with an increment in growth of 400% over control. The human burst promoting activity (BPA) of the CM was equivalent or better than other CM available in our laboratory. The evidence suggest that the growth-promoting activity is a constitutive product(s) released by FEA which was enhanced eightfold with virus infection. Studies with non-adherent and T-lymphocyte-depleted human marrow cells and human peripheral blood cells suggest that the growth factor(s) acts directly on progenitor cells and not through readily identified accessory cells. These findings are consistent with the concept that mesenchymal cells such as fibroblasts have the capacity to release hematopoietic growth factor(s) capable of acting on primitive hematopoietic progenitors. The results provide an example of how injury of such cells, through virus infection, may enhance growth factor(s) release and influence the hematopoietic microenvironment.", "journal": "Journal of cellular physiology", "doi": "10.1002/jcp.1041270123", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3009564", "author": "Engelman RW", "n_authors": 5, "title": "Changing manifestations of a chronic feline haematopoietic proliferative disease during immunotherapy with staphylococcal protein A.", "abstract": "A cat with feline leukaemia virus-associated malignant disease was treated by ex vivo immunoadsorption using staphylococcal protein A coated filters. During the 12-week course of treatment, the morphological manifestations of the haematopoietic disease showed a progressive transition from erythroid to myeloerythroid to myeloid predominance, and the disease was preceded by and associated initially and terminally with a blast transformation of lymphoblastic morphology. Necropsy revealed massive meningo-cerebral, as well as hepatic, renal, myeloid, lymphoid, peritoneal and pelvic infiltrations largely consisting of lymphoblastic cells. Evidence of myeloid and erythroid differentiation was present in all the infiltrates. The several possible bases for this shift of morphological expression are considered.", "journal": "Journal of comparative pathology", "doi": "10.1016/0021-9975(86)90008-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3008410", "author": "Mastro JM", "n_authors": 6, "title": "Feline leukemia vaccine: efficacy, contents and probable mechanism.", "abstract": "An effective subunit vaccine against feline leukemia virus infection and related diseases has been developed. The source of the vaccine immunogen is feline retrovirus persistently infected cells that continuously synthesize and shed virus polypeptides. Western blot analysis identifies FeLV-gp70, p27, p15, p12, and p10 in the subunit vaccine preparation. Cats immunized with the vaccine developed antibodies to a 70,000 MW protein of the vaccine that seems to be distinct from, but related to the FeLV-gp70 polypeptide.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(86)90001-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3012854", "author": "Deeb BJ", "n_authors": 2, "title": "Feline leukaemia virus antigen in cats from Beirut, Lebanon.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.118.8.209", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3954230", "author": "Wellman ML", "n_authors": 3, "title": "Guinea pig erythrocyte rosette formation as a nonspecific cell surface receptor assay in the cat.", "abstract": "The specificity of guinea pig erythrocyte (GPE) rosettes for feline peripheral blood lymphocytes was studied. Of the GPE rosette-positive cells from peripheral blood, 54% were monocytes, 29% were granulocytes, and only 17% were lymphocytes. Results were similar for rosettes incubated at 4 C and those incubated at 37 C. Mononuclear cells separated with polyvinylpyrrolidone-coated silica formed fewer monocyte rosettes (49%) and more granulocyte rosettes (34%) than did cells separated with sodium diatrizoate-Ficoll (60% monocyte rosettes and 18% granulocyte rosettes), whereas the percentage of lymphocyte rosettes was similar for both media. Mononuclear cells suspended in Eagle's minimum essential medium had a higher percentage of monocyte rosettes (75%) and a lower percentage of granulocyte rosettes (12%) than did cells suspended in RPMI 1640 medium (59% monocyte rosettes and 27% granulocyte rosettes). The percentage of lymphocyte rosettes was similar in the 2 media. Two sequential 45-minute plastic adherent cell depletions decreased monocyte rosettes to 51% and increased lymphocyte rosettes to 23% compared with 63% monocyte rosettes and 12% lymphocyte rosettes before adherent cell depletion. The granulocyte rosettes were unchanged by plastic adherent cell depletion. The percentage of rosette-positive cells (9%) was not significantly affected by incubation at 4 C or 37 C, cell separation with polyvinylpyrrolidone-coated silica or lymphocyte separation medium, or suspension in Eagle's minimum essential medium or RPMI 1640 medium. Plastic adherent cell depletion decreased the percentage of rosette-positive cells. Feline thymocytes were 38% to 80% GPE rosette-positive and a feline leukemia virus-infected lymphoblastic cell line (F422) was 88% GPE rosette-positive.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3008409", "author": "Pedersen NC", "n_authors": 4, "title": "Possible immunoenhancement of persistent viremia by feline leukemia virus envelope glycoprotein vaccines in challenge-exposure situations where whole inactivated virus vaccines were protective.", "abstract": "Kittens immunized with purified native FeLV-gp70 or -gp85 envelope proteins developed ELISA, but not virus neutralizing, antibodies in their serum to both whole FeLV and FeLV-gp70. Kittens vaccinated with envelope proteins and infected with feline sarcoma virus (FeSV) developed smaller tumors than nonvaccinates, but a greater incidence of persistent retroviremia. Similarly, FeLV-gp70 and -gp85 vaccinated kittens were more apt to become persistently retroviremic following virulent FeLV challenge exposure than nonvaccinates. Kittens vaccinated with inactivated whole FeLV developed smaller tumors after FeSV inoculation and had a lower incidence of persistent retroviremia than nonvaccinates. The protective effect of inactivated whole FeLV vaccine against persistent retroviremia was also seen with FeLV challenge-exposed cats. Protection afforded by inactivated whole FeLV vaccine was not associated with virus neutralizing antibodies, although ELISA antibodies to both whole FeLV and FeLV-gp70 were induced by vaccination.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(86)90093-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "2853437", "author": "Rojko JL", "n_authors": 1, "title": "Feline leukemia virus vaccines.", "abstract": null, "journal": "Seminars in veterinary medicine and surgery (small animal)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3001539", "author": "Mullins JI", "n_authors": 3, "title": "Disease-specific and tissue-specific production of unintegrated feline leukaemia virus variant DNA in feline AIDS.", "abstract": "Feline leukaemia viruses (FeLVs) have long been known to be associated with induction of proliferative and anti-proliferative diseases of domestic cats. Strains of FeLV have been recognized which specifically induce lymphosarcoma, aplastic anaemia, myelodysplastic anaemia, and, recently, feline AIDS (acquired immune deficiency syndrome), a naturally occurring immunosuppressive syndrome strikingly similar to human AIDS which is lethal in 100% of inoculated and viraemic specific-pathogen-free (SPF) cats. Here, we have analysed FeLV DNA in tissues of 22 SPF cats that had been inoculated with the feline AIDS strain (FeLV-FAIDS) and we find two classes of viral DNA--a monotypic common form which is detectable in bone marrow regardless of disease state, and variant forms, recognizable by restriction site differences, whose appearance correlates with onset of disease symptoms and persists throughout the course of the disease. FeLV-FAIDS variant DNA is detected at high concentration (10-50 copies per cell) and principally as unintegrated viral DNA (UVD) in bone marrow of cats with feline AIDS. In marked contrast high levels of UVD were not present in cats in the terminal-stages of T-cell lymphosarcoma, aplastic anaemia, or myelodysplastic anaemia induced by other FeLV strains. These results parallel recent observations in humans, where high levels of UVD were sometimes found in cells derived from AIDS patients infected with human T-lymphotropic virus type III (HTLV-III)/lymph-adenopathy-associated virus (LAV), and suggest that persistence of unintegrated variant viral DNA is a crucial indicator of retrovirus-induced cytopathic disease syndromes such as AIDS.", "journal": "Nature", "doi": "10.1038/319333a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3742354", "author": "Baker RJ", "n_authors": 2, "title": "Dysmyelopoiesis in the cat: a hematological disorder resembling refractory anemia with excess blasts in man.", "abstract": "Clinical and pathological findings in three cats affected with a myelodysplastic disorder are presented. This hematological disorder resembles that of refractory anemia with excess of blasts as seen in man. The hematological profile in man is one of peripheral cytopenia in one or all of the marrow cell lines which occurs despite a normal to hypercellular bone marrow. Quantitatively, the marrow has a preponderance of blasts (up to 20%). Qualitative abnormalities consist of dysthrombopoiesis and/or dyserythropoiesis and/or dysgranulopoiesis. Myelodysplastic disorders in the cat are a form of marrow failure often associated with infection with feline leukemia virus. The use of the term refractory anemia with excess of blasts appears to be applicable to the cat and should be considered in evaluating dysplastic disorders of the feline bone marrow.", "journal": "Canadian journal of veterinary research = Revue canadienne de recherche veterinaire", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3022080", "author": "Rojko JL", "n_authors": 7, "title": "Infectious feline leukaemia virus is erythrosuppressive in vitro.", "abstract": "The direct effect of the feline leukaemia virus (FeLV) on erythroid colony formation in vitro was investigated. Bone marrow mononuclear cells (BMMC) from FeLV-naïve, specific-pathogen-free (SPF), adult cats were inoculated with FeLVs of characterized strains and biologically cloned subgroups and the subsequent development of colony forming units-erythroid (CFUE) and burst forming units-erythroid (BFUE) and colony forming units-granulocyte-macrophage (CFUGM) was monitored. Exposure to the anaemia-causing Kawakami-Theilen strain of FeLV (FeLV-KT), a phenotypic mixture of subgroups A, B, and C, caused constant depression of day 2 CFUE (to 47% of sham-inoculated controls), day 4 CFUE (41% of controls), and day 10 BFUE (38% of controls). CFUGM were unaffected. The lymphoma-causing Rickard strain of FeLV (FeLV-R-TL) caused sporadic depression of CFUE and BFUE. In contrast, neither FeLV-R passaged through feline embryonic kidney fibroblasts (FeLV-R-CRFK) nor biologically cloned, subgroup-specific, FeLVs of fibroblast origin, caused decrements in CFUE or BFUE, suggesting that fibroblast passage attenuated the direct erythrosuppressive effect of FeLV. Suppression of CFUE and BFUE by lymphoma cell-origin FeLV was dependent on infectious virus and was associated with FeLV replication by the cultured myelomonocytic precursor cells. Attenuation of infectivity by heat or u.v. restored CFUE and BFUE development. Examination of the relationship between viral infectivity (VI), viral protein concentration, and CFUE suppression showed that the infectious FeLV was 20-fold more effective than u.v.-inactivated FeLV as an inhibitor of erythrogenesis in vitro.", "journal": "Leukemia research", "doi": "10.1016/0145-2126(86)90237-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3021292", "author": "Lafrado LJ", "n_authors": 2, "title": "Demonstration of depressed polymorphonuclear leukocyte function in nonviremic FeLV-infected cats.", "abstract": "Polymorphonuclear leukocytes (PMN) from healthy, normal control cats and FeLV-infected cats were analyzed for differences in phagocytic capabilities. One week after experimental infection, PMNs from FeLV-infected cats exhibited a marked decrease in phagocytic function as determined by the luminol-dependent chemiluminescent response. Depressed PMN function was observed in these cats during the viremic stage of infection and subsequently remained depressed after the cessation of viremia. The data presented here suggest that while nonviremic cats are reported as clinically normal, they may in fact be exhibiting a suppressed PMN function.", "journal": "Cancer investigation", "doi": "10.3109/07357908609017509", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3017470", "author": "Labat ML", "n_authors": 1, "title": "Retroviruses, immunosuppression and osteopetrosis.", "abstract": "Since decades, retroviruses are known to induce the formation of dense bones (osteopetrosis) in animals, either by increasing osteoblastic proliferation (ALVs viruses) or by decreasing osteoclastic bone resorption (FeLV virus). The latter is a good model of the inherited disease since neonatally infected cats die from wasting disease, like mutant op/op rats and children suffering from juvenile-malignant osteopetrosis. These similarities have prompted this review of retrovirus-induced osteopetrosis in animals. We suggest the possibility that retroviruses might be involved, at least in part, in the induction of the human disease.", "journal": "Biomedicine & pharmacotherapy = Biomedecine & pharmacotherapie", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3010935", "author": "Luciw P", "n_authors": 6, "title": "Recombinant DNA approaches to feline leukemia virus immunization.", "abstract": "We have utilized 2 recombinant DNA strategies for immunization against FeLV in cats: (a) modified live virus was attenuated by mutation and recombination, and (b) an immunogen, consisting of subunit envelope protein, was prepared in genetically engineered yeast. Results indicated that the genetically manipulated live virus preparations were not protective against FeLV challenge because they were either not attenuated in virulence or were not sufficiently antigenic. Immunization with yeast-synthesized FeLV envelope protein followed by the modified live virus gave protective immunity in cats under experimental conditions. Future immunization attempts will concentrate on enhancing the immunogenic potency of the yeast- synthesized FeLV envelope protein.", "journal": "Basic life sciences", "doi": "10.1007/978-1-4684-5110-8_18", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3008168", "author": "Hardy WD Jr", "n_authors": 2, "title": "FeLV-induced feline acquired immune deficiency syndrome. A model for human AIDS.", "abstract": null, "journal": "Progress in allergy", "doi": "10.1159/000318453", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3006326", "author": "Yamamoto JK", "n_authors": 3, "title": "A feline retrovirus induced T-lymphoblastoid cell-line that produces an atypical alpha type of interferon.", "abstract": "A cell-line, designated LSA-1, was derived from a thymic lymphosarcoma that occurred in a cat with experimentally induced feline leukemia virus (FeLV) infection. LSA-1 cells possessed surface receptors and antigens of normal T-lymphocytes, but were unresponsive to interleukin-2 stimulation. The LSA cell-line was found to constitutively produce and release an interferon into the culture supernatants. Production of this interferon was enhanced in certain clones of the original LSA-1 cell lines. The interferon produced by LSA-1 cells and some of its clones was compared to the standard alpha, beta, and gamma interferons of cats. Unlike alpha and beta interferons, which were acid, SDS, and heat stable, LSA interferon was acid labile and SDS and heat stable. In comparison, standard feline gamma interferon was acid, SDS, and heat labile. LSA interferon had a molecular weight of 20,000 daltons, compared to 17-19,000 daltons for gamma, 19-25,000 for beta, and 25-45,000 daltons for alpha interferons. Standard feline interferons were active only on cat cell lines, with the exceptions of alpha interferon, which also reacted with MDCK canine cells. LSA interferon resembled the standard feline alpha interferon because it also reacted with feline and canine cells. It was concluded that LSA interferon was an atypical acid labile alpha interferon, resembling in this respect the abnormal alpha interferon seen in humans with AIDS and SLE, and mice with retrovirus infections. LSA-1 cells produced high levels of FeLV structural proteins but very little infectious virus. This effect was due to endogenously produced interferon; LSA cell clones that were selected for low interferon production produced much higher levels of infectious FeLV than parent cells or clones selected for high interferon production. Cat cells pretreated with LSA or with standard feline alpha and beta interferons, and then infected with FeLV, produced high levels of FeLV proteins but very little infectious virus.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(86)90084-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3004846", "author": "Jacobs RM", "n_authors": 3, "title": "Flow cytometric and radioisotopic determinations of platelet survival time in normal cats and feline leukemia virus-infected cats.", "abstract": "This study demonstrates the potential usefulness of a flow cytometric technique to measure platelet survival time in cats utilizing autologous platelets labeled in vitro with fluorescein isothiocyanate (FITC). When compared with a 51Cr method, no significant differences in estimated survival times were found. Both the 51Cr and FITC-labeling procedures induced similar changes in platelet shape and collagen-induced aggregation. Platelets labeled with FITC had significantly greater volumes compared with those of glutaraldehyde-fixed platelets. These changes were primarily related to the platelet centrifugation and washing procedures rather than the labels themselves. This novel technique potentially has wide applicability to cell circulation time studies as flow cytometry equipment becomes more readily available. Problems with the technique are discussed. In a preliminary study of the platelet survival time in feline leukemia virus (FeLV)-infected cats, two of three cats had significantly reduced survival times using both flow cytometric and radioisotopic methods. These data suggest increased platelet turnover in FeLV-infected cats.", "journal": "Cytometry", "doi": "10.1002/cyto.990070109", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3004002", "author": "Boyce JT", "n_authors": 4, "title": "Feline leukemia virus-induced thrombocytopenia and macrothrombocytosis in cats.", "abstract": "The Kawakami-Theilen strain of feline leukemia virus (FeLV-KT), an exogenous anemia-inducing retrovirus, induced significant macrothrombocytosis and thrombocytopenia during acute infections of cats. The geometric mean platelet volumes of both freshly isolated fixed platelets and ethylenediamine tetraacetic acid-sphered platelets from infected cats were increased, but the ratio of fresh-fixed to ethylenediamine tetraacetic acid-sphered platelet volumes, an estimate of ethylenediamine tetraacetic acid-induced isovolumetric shape change, was normal. Total plasma membrane increased as the platelet volumes increased in FeLV-KT-infected cats, but estimated surface connected canalicular system surface area did not. Platelet concentrations were decreased 2 to 6 weeks after inoculation, but marked macrothrombocytosis resulted in a trend toward increased platelet mass on weeks 5 and 6 after inoculation. Thus, FeLV-KT-induced macrothrombocytosis may serve as a model of impaired platelet volume regulation. The platelet volume and platelet membrane surface area abnormalities found suggest that this model would allow studies of the megakaryocyte/platelet axis, particularly in the area of membrane formation and territorial demarcation.", "journal": "Veterinary pathology", "doi": "10.1177/030098588602300103", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3693001", "author": "Mooney SC", "n_authors": 4, "title": "Renal lymphoma in cats: 28 cases (1977-1984).", "abstract": "Renal lymphoma was diagnosed, staged, and treated in 28 cats. Renal lymphoma staging was done according to clinical findings: 11 cats had stage-2 lymphomas, 5 had stage-3 lymphomas, 6 had stage-4 lymphomas, and 6 had stage-5 lymphomas. All cats were treated with chemotherapy: 17 cats had a complete response, 9 cats had a partial response, and 2 cats had no response. The cats with stage-2 lymphomas that were FeLV-test negative had the best response to treatment.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2830393", "author": "Hagler DN", "n_authors": 3, "title": "Feline leukemia virus and Pneumocystis carinii infection.", "abstract": null, "journal": "The Journal of parasitology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2829454", "author": "Kitchen LW", "n_authors": 1, "title": "Effect of diethylcarbamazine on cats given feline leukaemia virus vaccine.", "abstract": "Leukocell (Norden Laboratories, Lincoln, NE, USA), a commercially available retroviral vaccine, is given to protect susceptible cats against feline leukaemia virus. Oral diethylcarbamazine, an immunomodulator used in the treatment of filariasis, when given with 1 ml i.m. Leukocell, increased titres and duration of serum antibodies to feline oncornavirus-associated cell membrane antigen and transient average monocyte counts in treated/vaccinated cats as compared to cats that received vaccine without diethylcarbamazine. These results may have implications for the development of more effective retroviral vaccination techniques for humans as well as for cats.", "journal": "Vaccine", "doi": "10.1016/0264-410x(87)90148-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2828737", "author": "Higashihara T", "n_authors": 4, "title": "Feline leukemia virus infection in street cats in Tokyo area.", "abstract": null, "journal": "Nihon juigaku zasshi. The Japanese journal of veterinary science", "doi": "10.1292/jvms1939.49.1162", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2823940", "author": "Hoover EA", "n_authors": 4, "title": "Experimental transmission and pathogenesis of immunodeficiency syndrome in cats.", "abstract": "We describe the identification, experimental transmission, and pathogenesis of a naturally occurring powerfully immunosuppressive isolate of feline leukemia virus (designated here as FeLV-FAIDS) which induces fatal acquired immunodeficiency syndrome (AIDS) in 100% (25 of 25) of persistently viremic experimentally infected specific pathogen-free (SPF) cats after predictable survival periods ranging from less than 3 months (acute immunodeficiency syndrome) to greater than one year (chronic immunodeficiency syndrome), depending on the age of the cat at time of virus exposure. The pathogenesis of FeLV-FAIDS-induced feline immunodeficiency disease is characterized by: a prodromal period of largely asymptomatic viremia; progressive weight loss, lymphoid hyperplasia associated with viral replication in lymphoid follicles, lymphoid depletion associated with extinction of viral replication in lymphoid follicles, intractable diarrhea associated with necrosis of intestinal crypt epithelium, lymphopenia, suppressed lymphocyte blastogenesis, impaired cutaneous allograft rejection, hypogammaglobulinemia, and opportunistic infections such as bacterial respiratory disease and necrotizing stomatitis. The clinical onset of immunodeficiency syndrome correlates with the replication of a specific FeLV-FAIDS viral variant, detected principally as unintegrated viral DNA, in bone marrow, lymphoid tissues, and intestine. Two of seven cats with chronic immunodeficiency disease that survived greater than 1 year after inoculation developed lymphoma affecting the marrow, intestine, spleen, and mesenteric nodes. Experimentally induced feline immunodeficiency syndrome, therefore, is a rapid and consistent in vivo model for prospective studies of the viral genetic determinants, pathogenesis, prevention, and therapy of retrovirus-induced immunodeficiency disease.", "journal": "Blood", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3424614", "author": "Evans RJ", "n_authors": 2, "title": "Myeloproliferative disease in the dog and cat: definition, aetiology and classification.", "abstract": "The term myeloproliferative disease may be applied to all the non-lymphoid dysplastic and neoplastic conditions arising from the haematopoietic stem cell or its progeny. Thus the chronic and acute myeloid leukaemias, thrombocythaemia, megakaryocytic myelosis, myelofibrosis, the myelodysplastic syndromes and some cases of aplastic anaemia may be viewed as variants of a single disease process. This view is useful in explaining the common occurrence of mixed forms of disease or interconversions between the myeloproliferative diseases. This variability is a consequence of the development of all the haematopoietic lineages from a single class of haematopoietic stem cell by progressive differentiation. The aetiology of the myeloproliferative diseases in the domestic animals is uncertain but feline leukaemia virus infection has been implicated in the cat. These conditions may be classified as aplastic anaemia, as preleukaemic dysplastic conditions with variable cytopenias and morphological abnormalities of blood cells, as smouldering leukaemias, or as leukaemias with a frankly leukaemic blood or bone marrow.", "journal": "The Veterinary record", "doi": "10.1136/vr.121.19.437", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2829413", "author": "Shelton GH", "n_authors": 2, "title": "Murine monoclonal antibodies cross-reactive with feline peripheral blood mononuclear cells.", "abstract": "Twelve murine monoclonal antibodies (MAB), specific for canine, human, and mouse cell surface determinants on lymphohemopoietic cells, were tested for reactivity (using indirect immunofluorescence) with peripheral blood mononuclear cells (PBMC) from 3 normal cats and 3 FeLV-positive cats with lymphoblastic leukemia. MAB DLy6 and 1H3, specific for canine lymphocytes, MAB HB57S, specific for human mu(IgM) chain, MAB J-118 40.164.3 and H81.98.71, specific for murine and human Ia, all had higher binding levels with PBMC from FeLV-positive cats compared to normal cats. Two MAB (S-78, S-24), specific for human class I determinants, cross-reacted with PBMC from both groups of cats. This panel of MAB may be useful for characterizing immunologically reactive cell subsets in normal as well as retrovirus-diseased animals.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(87)90023-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2823466", "author": "Guilhot S", "n_authors": 4, "title": "Nucleotide sequence analysis of the LTRs and env genes of SM-FeSV and GA-FeSV.", "abstract": "The nucleotide sequences of the env genes and the LTRs of SM- and GA-FeSV lambda recombinants have been determined by the Maxam and Gilbert method and/or the dideoxy method with specific sequencing primers. Comparison of the two sequences reveals a homology of 93%, the differences being randomly distributed. Two frameshift mutations are observed in the GA-FeSV isolate which close the reading frame and would prevent the synthesis of the env protein. Comparison of these two FeSV sequences with the env sequences of each antigenic subgroup of FeLV (A, B, C) reveals that these two viruses can be assigned to the A/C subgroups.", "journal": "Virology", "doi": "10.1016/0042-6822(87)90194-2", "deposited_data": "Sim", "nuccore_ids": "340791, 340790, 340789", "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2444714", "author": "Nicolaisen-Strouss K", "n_authors": 5, "title": "Natural feline leukemia virus variant escapes neutralization by a monoclonal antibody via an amino acid change outside the antibody-binding epitope.", "abstract": "We have molecularly cloned a natural variant of feline leukemia virus subtype B. This isolate is unique in that it is not neutralized by a monoclonal antibody which neutralized all other feline leukemia virus isolates tested, including members of the A, B, and C subtypes. Western immunoblotting indicated that the monoclonal antibody was less able to bind to the gp70 of the resistant isolate (designated lambda B1) than to the gp70s of susceptible viruses. Nucleotide sequence analysis of the envelope gene of lambda B1 revealed a high degree of homology with the susceptible Snyder-Theilen, Gardner-Arnstein, and Rickard subtype B isolates, including the presence of a 5-amino-acid minimal binding epitope required for binding by the neutralizing monoclonal antibody. The only change within the vicinity of this epitope was in a single nucleotide, and this difference changed a proline residue to leucine three amino acids from the N terminus of the binding epitope. Competitive binding studies with synthetic peptides indicated that substitution of leucine for proline resulted in a 10-fold decrease in the ability of the peptide to compete for antibody binding to native antigen. The results are consistent with the interpretation that this amino acid change lowers the affinity of antibody binding, resulting in failure of the antibody to neutralize the variant virus.", "journal": "Journal of virology", "doi": "10.1128/JVI.61.11.3410-3415.1987", "deposited_data": "Sim", "nuccore_ids": "323896", "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2822586", "author": "Miura T", "n_authors": 7, "title": "Structural abnormality and over-expression of the myc gene in feline leukemias.", "abstract": "Tumor cells of feline leukemia were examined for structural abnormality and expression of the myc gene. Four of 12 spontaneous leukemia cases showed structural abnormalities of the myc gene detected by Southern blotting analysis. Of these 4 cases, one (Case 1) showed a DNA rearrangement in the 5' portion of the c-myc locus associated with integration of feline leukemia virus (FeLV) genome. Another case had a newly inserted myc gene which was transduced by FeLV. In the 2 other cases, no relation of abnormalities of the myc gene to FeLV was detected. One case of experimental leukemia induced by inoculation of a cell line, FT-1, established from Case 1 showed a c-myc gene rearrangement similar to that observed in Case 1. Expression of myc RNA was examined in 3 leukemia T-cell lines, FT-1, FL74 and F422, by Northern blotting analysis. A high level of myc transcript was detected in all 3 cell lines. The size of myc RNAs in FT-1 and FL74 was the same as that of normal myc RNA, while in F422 which had myc-containing FeLV (myc-FelV), the full genome and spliced form of myc-FeLV viral RNA were detected.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910400422", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3041029", "author": "Bonham L", "n_authors": 4, "title": "Transforming potential of a myc-containing variant of feline leukemia virus in vitro in early-passage feline cells.", "abstract": "We studied a naturally occurring variant of feline leukemia virus (FeLV) in which the oncogene myc has substituted for a portion of the viral structural genes (myc-FeLV). myc-FeLV was rescued by replication in the presence of FeLV as helper, and its biological activity was examined in early-passage feline cells in vitro. Infection of leukocytes from peripheral blood, spleen, or thymus, or of kitten fibroblasts did not immortalize these cells or alter them morphologically. Northern blot (RNA blot) analysis of virion RNA prepared from the supernatant of infected cells demonstrated the 8.2-kilobase genome of FeLV, but did not demonstrate the 5.0-kilobase genome of myc-FeLV. Apparently, the myc-FeLV genome was lost in the absence of the selective pressure of transformation. In contrast, infection of embryonic fibroblasts with myc-FeLV(FeLV) rendered these cells capable of greatly increased, if not infinite, proliferative potential. The cells were morphologically altered compared with controls and were only loosely adherent to the substrate. The cells failed to proliferate in semisolid medium and did not form tumors when inoculated subcutaneously into athymic mice. Blot analyses demonstrated the presence and expression of integrated proviral DNAs of both FeLV and myc-FeLV in these cells. They appear, then, to represent cells partially transformed by infection with myc-FeLV(FeLV). The action of feline v-myc in early-passage cells in vitro was compared to that of avian v-myc.", "journal": "Journal of virology", "doi": "10.1128/JVI.61.10.3072-3081.1987", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2821071", "author": "Abkowitz JL", "n_authors": 3, "title": "Retrovirus-induced feline pure red cell aplasia. Hematopoietic progenitors are infected with feline leukemia virus and erythroid burst-forming cells are uniquely sensitive to heterologous complement.", "abstract": "Feline leukemia virus subgroup C/Sarma (FeLV-C) induces pure red cell aplasia (PRCA) in cats. Just before the onset of anemia, erythroid colony-forming cells (CFU-E) become undetectable in marrow culture, yet normal frequencies of erythroid burst-forming cells (BFU-E)- and granulocyte-macrophage colony-forming cells (CFU-GM) persist. To determine if erythroid progenitors were uniquely infected with retrovirus, marrow mononuclear cells from cats viremic with FeLV-C were labeled with monoclonal antibodies to gp70 and then analyzed with a fluorescence-activated cell sorter. Both erythroid and granulocyte-macrophage progenitors were among cells sorting positively, suggesting that infection of BFU-E alone did not result in PRCA. The results were confirmed by complement (C') lysis studies using baby rabbit or guinea pig sera as sources of C'. These studies also suggested that BFU-E from cats with PRCA were unusually sensitive to C' alone, without the addition of antibody. In further studies, we demonstrated that C' activation was via the classical pathway and that C' sensitivity was unique to BFU-E and not a property of CFU-E, CFU-GM, or progenitors that were capable of giving rise to BFU-E in suspension culture. As BFU-E from cats viremic with FeLV-A/Glasgow-1 or the Rickard strain of feline leukemia virus were not sensitive to C', this finding may relate to the pathogenesis of feline PRCA. We hypothesize that, in cats viremic with FeLV-C, the abnormal C' sensitivity of BFU-E leads to the absence of CFU-E and anemia.", "journal": "The Journal of clinical investigation", "doi": "10.1172/JCI113160", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2824411", "author": "Monticello TM", "n_authors": 4, "title": "Cryptosporidiosis in a feline leukemia virus-positive cat.", "abstract": "A 4-year-old FeLV-positive cat with a 1-year history of intermittent diarrhea and subsequent anorexia, depression, and weight loss had enteric cryptosporidiosis at necropsy. Cryptosporidium sp is an important cause of gastroenteritis and diarrhea in various species, including human beings with acquired immunodeficiency syndrome. A major determinant of the severity of the disease caused by Cryptosporidium sp is the immunologic status of the affected animal. Cryptosporidiosis should be included in the differential diagnosis of protracted diarrhea in FeLV-positive cats. Because cryptosporidiosis now is recognized as a zoonosis, cats with this disease should be considered a potential source of human infection.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2825396", "author": "Osterhaus A", "n_authors": 6, "title": "Comparison of serological responses in cats vaccinated with two different FeLV vaccine preparations.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.121.11.260", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3118559", "author": "Tompkins MB", "n_authors": 5, "title": "Induction of IL-2 and lymphokine activated killer cells in the cat.", "abstract": "We have described the use of a cloned murine IL-2-dependent T-cell line to directly measure feline IL-2. Concanavalin A stimulated feline peripheral blood lymphocytes produced an IL-2-rich supernatant that supported the growth of this murine IL-2-dependent T-cell line. In addition to producing IL-2, Con A stimulated killer cells in PBL were cytotoxic for the FeLV transformed tumor cell line FL74. Incubating feline PBL with a cocktail of the calcium ionophore A23187 and phorbol ester also led to the generation of cytotoxic cells as well as the production of high levels of IL-2. Finally, IL-2-rich supernatant was able to stimulate cytotoxic activity in PBL from normal cats.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(87)90169-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2821017", "author": "Abkowitz JL", "n_authors": 3, "title": "Retrovirus-induced feline pure red cell aplasia: the kinetics of erythroid marrow failure.", "abstract": "Cats viremic with feline leukemia virus subgroup C (FeLV-C) develop pure red cell aplasia (PRCA) characterized by the loss of detectable late erythroid progenitors (CFU-E) in marrow culture. Normal numbers of early erythroid progenitors (BFU-E) and granulocyte-macrophage progenitors (CFU-GM) remain, suggesting that the maturation of BFU-E to CFU-E is impaired in vivo. We have examined the cell cycle kinetics of BFU-E and their response to hematopoietic growth factor(s) to better characterize erythropoiesis as anemia develops. Within 3 weeks of FeLV-C infection, yet 6-42 weeks before anemia, the traction of BFU-E in DNA synthesis as determined by tritiated thymidine suicide increased to 43 +/- 4% (normal 23 +/- 2%) while there was no change in the cell cycle kinetics of CFU-GM. In additional studies, we evaluated the response of marrow to the hematopoietic growth factor(s) present in medium conditioned by FeLV-infected feline embryonic fibroblasts (FEA/FeLV CM). With cells from normal cats or cats viremic with FeLV-C but not anemic, a 4-fold increase in erythroid bursts was seen in cultures with 5% FEA/FeLV CM when compared to cultures without CM. However, just prior to the onset of anemia, when the numbers of detectable CFU-E decreased, BFU-E no longer responded to FEA/FeLV CM in vitro. BFU-E from anemic cats also required 10% cat or human serum for optimal in vitro growth. These altered kinetics and in vitro growth characteristics may relate to the in vivo block of BFU-E differentiation and PRCA. Finally, when marrow from cats with PRCA was placed in suspension culture for 2 to 4 days in the presence of cat serum and CM, the numbers of BFU-E increased 2- to 4-fold although no CFU-E were generated. By 4 to 7 days, CFU-E were detected, suggesting that conditions contributing to the block of erythroid maturation did not persist. The suspension culture technique provides an approach to study further the defect in erythroid differentiation characteristic of feline PRCA.", "journal": "Journal of cellular physiology", "doi": "10.1002/jcp.1041320322", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3039006", "author": "Snyder HW Jr", "n_authors": 6, "title": "Selective removal of antigen-complexed IgG from cat plasma by adsorption onto a protein A-silica matrix.", "abstract": "The binding of normal cat IgG, heat-aggregated cat IgG and specific immune complexes (IC) containing cat IgG to a silica matrix containing covalently bound Staphylococcus aureus protein A was evaluated. The amounts of serum relative to protein A-silica, the flow rates and the perfusion times were representative of those existing when protein A-silica columns are used for therapeutic extracorporeal immunoadsorption of IgG and IC from humans and animals. When cat IgG was present in a large excess, approximately one molecule was bound to the matrix per molecule of solid-phase protein A with a KA of 1.5 X 10(6) 1/mol. Aggregated and immune complexed IgG bound to the matrix with relatively higher affinity. IC prepared in vitro between the purified envelope glycoprotein of the feline leukemia virus (FeLV gp70) and affinity-purified cat antibodies bound to the matrix even though normal IgG was present in greater than 10,000-fold excess. Once bound, IC were not eluted from columns upon further perfusion with normal serum. However, bound IgG was eluted from columns by further perfusion of normal serum or IC. IC were at least five-fold more efficient than normal IgG in exerting this effect. The results suggest that protein A-silica columns can be used for preferential removal of IC from plasma in a clinical or experimental setting.", "journal": "Journal of immunological methods", "doi": "10.1016/0022-1759(87)90152-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3041092", "author": "Chuma T", "n_authors": 4, "title": "Effect of feline leukemia virus on the development of plaque forming cells in feline peripheral blood lymphocytes.", "abstract": null, "journal": "Nihon juigaku zasshi. The Japanese journal of veterinary science", "doi": "10.1292/jvms1939.49.737", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2820639", "author": "Yasuda M", "n_authors": 3, "title": "Influence of inactivated feline retrovirus on feline alpha interferon and immunoglobulin production.", "abstract": "The effect of ultraviolet-inactivated feline leukaemia virus (UV-FeLV) on the development of feline immunoglobulin-secreting cells (ISC) was investigated using a reverse haemolytic plaque assay. Low concentrations of UV-FeLV at 2 X 10(-4) to 2.0 micrograms/ml stimulated the production of ISC. By contrast, the same concentration of UV-FeLV suppressed the development of pokeweed mitogen (PWM)-driven ISC. Maximum suppression of ISC occurred at 50 micrograms/ml of UV-FeLV. The generation of an interferon resistant to acid, heat and sodium dodecyl sulphate (SDS) in the media of lymphocyte cultures incubated with PWM was also significantly suppressed in the presence of 0.2 microgram/ml of UV-FeLV. These findings suggest that non-infectious viral particles appear to modify feline immunoglobulin and interferon-secreting systems.", "journal": "Clinical and experimental immunology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3039688", "author": "Reinacher M", "n_authors": 1, "title": "[Infections with feline leukemia virus (FeLV) in postmortem cats].", "abstract": "Cats presented for post-mortem examination were examined by immune histological techniques for the presence of persistent FeLV infections. Persistent FeLV infection was found to be the most common fatal infectious disease currently occurring in cats. It was detected in 16 per cent of the cats referred for post-mortem examination, whereas a proportion of 3 per cent may be regarded as likely in the normal population.", "journal": "Tijdschrift voor diergeneeskunde", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3036720", "author": "Onions D", "n_authors": 4, "title": "Recombinant feline viruses containing the myc gene rapidly produce clonal tumours expressing T-cell antigen receptor gene transcripts.", "abstract": "We, and others, have recently shown that recombinant feline leukaemia viruses (FeLV) containing the myc gene (FeLV-myc) occur in up to 30% of naturally occurring cases of T-cell lymphosarcoma. Investigation of the disease spectrum of two FeLV-myc isolates showed that they induced clonal or oligoclonal T-cell tumours after a short latent period. The phenotypic pattern of the thymic tumours was restricted in that they all expressed the alpha and beta chains of the T-cell antigen receptor and could readily be established in culture in vitro without the addition of exogenous interleukin-2. Although helper FeLV was transmitted from infected cats to uninfected tracer cats, there was no evidence of horizontal transmission of FeLV-myc viruses, suggesting that these viruses arise de novo in individual cases of thymic lymphosarcoma.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910400108", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3038950", "author": "Lewis MG", "n_authors": 7, "title": "Saliva as a source of feline leukemia virus antigen for diagnosis of disease.", "abstract": "An enzyme-linked immunosorbent assay (ELISA) for detection of feline leukemia virus (FeLV) p27 in saliva was tested for its accuracy and sensitivity in diagnosing FeLV infections. Saliva and serum samples from 564 clinical cases were tested with a 99.2% specificity. The overall accuracy of the saliva ELISA reactive to the serum ELISA was 97.9%. Experimentally, the ELISA saliva was the least sensitive in diagnosing early FeLV infections. However, the overall accuracy, ease of use, and simplicity of the test support its use as a screening procedure in clinical practice.", "journal": "Journal of clinical microbiology", "doi": "10.1128/jcm.25.7.1320-1322.1987", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3038808", "author": "Swenson CL", "n_authors": 6, "title": "Cyclic hematopoiesis associated with feline leukemia virus infection in two cats.", "abstract": "Cyclic oscillations in the numbers of blood elements were detected in 2 cats with FeLV infection. Periodic neutropenia, followed by a return to normal neutrophil numbers, was detected in both cats. The mean cycle duration was 11.8 days, with a range of 8 to 14 days. Just before the return of normal neutrophil numbers, monocytosis developed. In 1 cat, cyclic variations in the number of reticulocytes and platelets also were detected. Bone marrow aspirates obtained during periods of neutropenia had a predominance of progranulocytes in the myeloid cell line. myeloid hyperplasia, with numerous segmented neutrophils, was seen in bone marrow aspirates obtained during periods of normal neutrophil numbers. Oral administration of prednisolone resulted in cessation of the cyclic oscillations of blood elements in 1 cat. Cyclic hematopoiesis appeared to be another non-neoplastic manifestation of FeLV infection.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2820273", "author": "Kraut EH", "n_authors": 4, "title": "Effects of treatment with cobra venom factor on experimentally induced feline leukemia.", "abstract": "Five- to six-month-old specific-pathogen-free cats were exposed to cobra venom factor (CVF) alone (4 cats), Rickard feline leukemia virus (FeLV; 9 cats), or CVF and FeLV (6 cats). Host-virus relationships were evaluated by monitoring the development of viremia, production of antibody against feline oncornavirus-associated cell membrane antigen, and amount of circulating immune complexes (CIC). Exposure to CVF induced complement depletion, which lasted 8 to 15 days. However, complement depletion did not promote the development of persistent viremia nor alter the production of antibody to feline oncornavirus-associated cell membrane antigen or CIC. Results indicated that the complement system did not protect cats during their initial exposure to FeLV and that an intact complement system was not necessary for the development of antibody against feline oncornavirus-associated antigen or for the formation of CIC.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2820053", "author": "Boller E", "n_authors": 2, "title": "[The distribution of feline leukemia virus (FeLV) in Switzerland].", "abstract": null, "journal": "Schweizer Archiv fur Tierheilkunde", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3039686", "author": "Weijer K", "n_authors": 3, "title": "[Feline leukemia virus (FeLV) and FeLV-associated diseases in cats: a review].", "abstract": "Feline leukaemia virus (FeLV) usually occurs in its natural species, the domestic cat. FeLV is also important to human individuals as a comparative model, as FeLV may cause a variety of diseases which are partly malignant and partly benign, such as immunosuppression which bears a resemblance to AIDS (acquired immune deficiency syndrome) in man. Although FeLV is a common infective agent, the incidence of disease due to FeLV is much higher in cats kept in closed households in which several of them are present than it is in free-range cats. Consequently, diseases caused by FeLV are frequently diagnosed in pedigree cats which are often maintained in relatively large numbers. FeLV is transmitted among cats by contagion. The main sources of infection are persistantly infected FeLV carrier cats which continuously excrete virus from the mouth and in other secretions. The majority of cats infected with FeLV will produce neutralising antibodies. Cats which are unable to do so, will become permanently infected. The prognosis is bad in these cats: 90 per cent will die within five years. Various techniques are used to detect FeLV. The most common method, the indirect immunofluorescence (IFA) test, is performed on air-dried blood smears. The results of the IFA agree with that are almost completely identical to those of the virus isolation test. Another test is ELISA (enzyme-linked immunosorbent assay), which produces approximately 10 per cent more positive results which are probably due to circulating FeLV antigens. Dissemination of FeLV among cats may be prevented by identifying infected carrier cats and removing them from contact with non-infected cats. Removal programmes using indirect immunofluorescent antibody (IFA) tests were used successfully in the Netherlands. The proportion of FeLV-positive cats decreased from 9 per cent in 1974 to approximately 3 per cent in 1985 during such a removal programme. During the above period, the removal programme was carried out in the society of Dutch cat breeders 'Felikat', the programme being made compulsory on all members of the society. The incidence of cats positive for FeLV decreased from over 11 per cent in 1974 to less than 2 per cent within four years. None of the cats tested in this society was found to be positive for FeLV in 1984 and 1985. Besides removal programmes, other methods of control, such as vaccination, were developed to prevent the spread of FeLV. The FeLV-immunostimulating complex vaccine (FeLV-ISCOM vaccine) a subunit vaccine in which FeLV-gp70 is presented in a particular manner, seems to be promising.", "journal": "Tijdschrift voor diergeneeskunde", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3034403", "author": "Tavares L", "n_authors": 5, "title": "3'-Azido-3'-deoxythymidine in feline leukemia virus-infected cats: a model for therapy and prophylaxis of AIDS.", "abstract": "Due to similarities between human immunodeficiency virus and feline leukemia virus, the etiological agents of acquired immunodeficiency syndromes in humans and cats, the feline system was used as a model to conduct preliminary investigations as to the efficacy of the thymidine analogue 3'-azido-3'-deoxythymidine (AZT) as a therapeutic and preventive agent against retroviruses. In vitro evaluations of AZT cytotoxicity and its antiviral effects were conducted. Subsequently, 50 6-week-old specific pathogen free kittens were inoculated with a highly immunosuppressive strain of Richard-Feline Leukemia Virus. These cats were randomly subdivided into smaller groups with initiation of AZT treatment at variable times postinfection. All animals were periodically monitored for circulating infectious virus particles and virus-neutralizing antibodies. Their clinical condition was closely followed throughout the 6-week AZT treatment phase and for several months thereafter. The results indicate that AZT prevents retrovirus infection if administered immediately following virus exposure, and may also reduce retrovirus replication if administered to previously infected animals. Some of the treated cats developed neutralizing antibodies against the virus and became resistant to subsequent viral challenge. Future trials with this drug, both for the prevention and treatment of retroviral diseases in humans and animals, are warranted.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3610758", "author": "Clinkenbeard KD", "n_authors": 3, "title": "Disseminated histoplasmosis in cats: 12 cases (1981-1986).", "abstract": "Anemia, weight loss, lethargy, fever, anorexia, and interstitial lung disease were the predominant clinical findings in 12 cats with disseminated histoplasmosis. Some cats were examined because of dysfunction or lesions of bone, eyes, or skin. In most cases, the clinical signs were observed by the owner for 4 weeks or less before seeking veterinary care. Young cats were most commonly affected, with 7 of the 12 cats less than or equal to 1 year old. Identification of Histoplasma organisms in bone marrow aspirates was used to confirm the diagnosis of histoplasmosis in 11 of the 12 cats. Histoplasma infection of multiple organs was found at necropsy. In this study, disseminated histoplasmosis had a higher prevalence in cats than in dogs at the same veterinary medical teaching hospital. Feline disseminated histoplasmosis was not associated with FeLV infection. Treatment was attempted in 7 of the 12 cats.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3599907", "author": "Kwang HS", "n_authors": 6, "title": "Viremia, antigenemia, and serum antibodies in rhesus macaques infected with simian retrovirus type 1 and their relationship to disease course.", "abstract": "The course of simian retrovirus type 1 (SRV-1) infection was studied in 14 experimentally inoculated juvenile rhesus monkeys. Viral transmembrane protein antigenemia and antibodies to whole virus were measured by enzyme linked immunosorbent assay and correlated with the clinical course of disease and virus isolation. Based on these parameters, animals with simian retrovirus type 1-induced disease were divided into three categories: monkeys dying within a few months of fulminating simian acquired immune deficiency syndrome in the face of a high level persistent antigenemia and viremia, and a nondetectable serum antibody response; monkeys that developed a milder form of simian acquired immune deficiency syndrome but remained alive in spite of a chronic low-grade antigenemia and viremia and only a transient initial antibody response; and monkeys that never became ill and that were either transiently or nontransiently viremic and antigenemic. This latter group developed high levels of serum antibodies. The outcome of simian retrovirus type 1-induced disease was similar to that described for feline leukemia virus infection of cats, another retroviral disease of animals. The disease course differed considerably, however, from that reported for retrovirus-induced human acquired immune deficiency syndrome.", "journal": "Laboratory investigation; a journal of technical methods and pathology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3553615", "author": "Roebroek AJ", "n_authors": 5, "title": "Structure of the feline c-fes/fps proto-oncogene: genesis of a retroviral oncogene.", "abstract": "The nucleotide sequence of the feline c-fes/fps proto-oncogene was analyzed. Comparison with v-fes and v-fps revealed that all v-fes/fps homologous sequences were dispersed over 11 kilobase pairs in 19 interspersed segments. All segments, numbered exon 1 to exon 19 as in the chicken and human loci, were flanked by consensus splice junctions. The putative promoter region contained a CATT sequence and three CCGCCC motifs which were also found in the human locus at similar positions. About 200 nucleotides downstream of a translational stop codon in exon 19, a putative poly(A) addition signal was identified. Using the putative translation initiation codon in exon 2, a 93,000-molecular-weight protein could be deduced. This protein resembled very well the putative protein of the human c-fes/fps proto-oncogene (94% overall homology) and, although less well, the putative protein of the chicken c-fes/fps proto-oncogene (70% overall homology). As far as the feline c-fes/fps proto-oncogene sequences transduced to the Gardner-Arnstein (GA) and Snyder-Theilen (ST) strains of feline sarcoma virus (FeSV) are concerned, homology in deduced amino acid sequences between the GA- and ST-v-fes viral oncogenes and the proto-oncogene was 99%. Analysis of the recombination junctions between feline leukemia virus and v-fes sequences in GA- and ST-FeSV proviral DNA revealed for the left-hand junction the involvement of homologous recombination, presumably at the DNA level. The right-hand junction, which appeared identical in the GA-FeSV and ST-FeSV genomes, could have been the result of a site-specific recombination at the RNA level.", "journal": "Journal of virology", "doi": "10.1128/JVI.61.6.2009-2016.1987", "deposited_data": "Sim", "nuccore_ids": "1036032546, 2130978967, 2130978965", "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3039250", "author": "Stark DM", "n_authors": 3, "title": "Prevalence of feline leukemia virus infection in random source laboratory cats.", "abstract": "Three years of quarantine data involving the prevalence of Feline Leukemia Virus (FeLV) in laboratory cats (Felis catus) was evaluated. Testing was performed using a commercially available ELISA system. Annual prevalence of infection ranged from 5.4 to 10.7% of the 937 cats tested. Results obtained with the enzyme linked immunosorbent assay (ELISA) system compared well with tests performed using an immunofluorescent antibody assay system (IFA). Seasonal periodicity was noted with higher infection rates among animals received in April. Holding period at the supplier and gender did not influence disease prevalence. The availability of a simple test system, the unacceptability of FeLV infected cats for research, the danger of transmission and a higher prevalence of infection than earlier reports indicated that supplier and user evaluation of research cats for FeLV would be prudent.", "journal": "Laboratory animal science", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3037951", "author": "Reinacher M", "n_authors": 2, "title": "Frequency and significance of feline leukemia virus infection in necropsied cats.", "abstract": "Feline leukemia virus (FeLV) infection was diagnosed immunohistologically on paraffin-embedded tissues obtained from 1,095 necropsied cats. Significant association of FeLV infection was demonstrated by chi 2 and Fisher's tests with various conditions and diseases (ie, anemia, tumors of the leukemia/lymphoma complex, feline infectious peritonitis, bacterial infections, emaciation, FeLV-associated enteritis, lymphatic hyperplasia, and hemorrhage). Unexpected findings associated with FeLV infection were icterus, several types of hepatitis, and liver degeneration. A negative association with FeLV infection was found for most parasitic and viral infections, including feline panleukopenia. Neither positive nor negative associations were established for FeLV infection and most forms of nephritis, including severe glomerulonephritis. Feline leukemia virus-infected cats were significantly (Kruskal-Wallis test) older than were FeLV-negative cats with the same nonneoplastic FeLV-associated diseases.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3037814", "author": "Haffer KN", "n_authors": 3, "title": "Feline leukaemia vaccine protection against viral latency.", "abstract": "Seventeen cats, which were previously vaccinated with a subunit, feline leukaemia vaccine (Leukocell) and subsequently challenged with virulent feline leukaemia virus (FeLV), were tested at 2 to 4 years postchallenge for reactivation of latent FeLV infections. Administration of weekly doses of methylprednisolone induced significant decreases in lymphocyte numbers, but did not reactivate virus in bone marrow cultures from 15 cats in vivo or in vitro. These cats were observed to be neither persistently or latently viraemic prior to corticosteroid administration. The results of this study indicate that the vaccine is effective in affording significant protection against latent FeLV infections, even after severe immunosuppression. This finding, coupled with previously published results indicating protection against persistent viraemia and tumour formation, makes this vaccine highly effective in protecting against FeLV infections and associated disease.", "journal": "Vaccine", "doi": "10.1016/0264-410x(87)90060-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2884777", "author": "Bergold PJ", "n_authors": 6, "title": "Structure and origins of the HZ2-feline sarcoma virus.", "abstract": "The HZ2-feline sarcoma virus (HZ2-FeSV) is a replication-defective acute transforming feline retrovirus with oncogene homology to Abelson murine leukemia virus (A-MuLV) (P. Besmer, W.D. Hardy,Jr., E. E. Zuckerman, P. J. Bergold, L. Lederman, and H. W. Snyder, Jr. (1983) Nature (London) 303, 825-828). In contrast to A-MuLV which was isolated from a hematopoietic tumor, the HZ2-FeSV derives from a multicentric fibrosarcoma. We have molecularly cloned the HZ2-FeSV provirus from mink HZ2-FeSV nonproducer cells. The molecularly cloned HZ2-FeSV provirus is biologically active upon transfection of NIH 3T3 indicator cells. The genetic structure of the HZ2-FeSV provirus was determined by EM heteroduplex and Southern blot analysis. The HZ2-FeSV has a 6.8 kb-viral genome with the structure: 5' delta gag-abl-delta pol-delta env 3'. The abl insert, which is 1.4 kb, is located 1.9 kb from the 5' end and 3.5 kb from the 3' end of the viral genome. The 5' 1.9 kb in the HZ2-FeSV are colinear with 5' FeLV sequences, and the 3' 3.5 kb are colinear with 3' FeLV sequences, with the exception of a 0.85-kb deletion in the env gene. HZ2-FeSV v-abl and A-MuLV v-abl share 1.2 kb of abl sequences which are known to specify the protein kinase domain of the abl gene product and are necessary for fibroblast transformation in vitro. The DNA from several tumor tissues of cat 3590 from which the HZ2-FeSV was obtained was found to contain several HZ2-FeSV-related proviruses including the HZ2-FeSV. The variant HZ2-FeSVs have indistinguishable 5' gag-abl sequences; however, they differ in 3' sequences which likely do not include any abl sequences. The DNAs from fibrosarcomas obtained by inoculation of kittens with tumor extract were found to contain variant HZ2-FeSV proviruses as well. Taken together these results indicate a role for the HZ2-FeSVs in sarcomagenesis.", "journal": "Virology", "doi": "10.1016/0042-6822(87)90204-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3034965", "author": "Lutz H", "n_authors": 2, "title": "Detection of feline leukemia virus infection in saliva.", "abstract": "The question was investigated whether feline leukemia virus (FeLV) infection may be diagnosed by testing saliva in an enzyme-linked immunosorbent assay (ELISA). Saliva was collected with commercially available swabs, eluted from the swabs, and tested in the ELISA. A comparison of results with saliva and serum samples from 60 specific-pathogen-free cats, 9 experimentally infected cats, and 1,117 field cats led to the following conclusions. False-positive saliva results, if any occurred, were rare events. During experimental infections, antigen excretion in saliva was observed 1.5 weeks after the first appearance of FeLV antigen in serum. In one of four positive serum samples from sick animals brought to veterinarians, saliva samples tested negative. The use of saliva in an ELISA for the detection of FeLV p27 in individual sick cats is therefore less reliable than the use of serum. In seven cats with diseases typical of FeLV, including one with an intestinal form of lyphosarcoma, saliva tested positive and serum tested negative. Based on the saliva and serum results for cats living in 92 multicat households, it was concluded that saliva may be a useful secretion for FeLV screening.", "journal": "Journal of clinical microbiology", "doi": "10.1128/jcm.25.5.827-831.1987", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3033889", "author": "Forrest D", "n_authors": 4, "title": "Altered structure and expression of c-myc in feline T-cell tumours.", "abstract": "The c-myc gene is rearranged in a subset of feline T-cell lymphosarcomas. Detailed mapping of c-myc rearrangements showed that some result from feline leukaemia virus (FeLV) proviral integration within or upstream of c-myc, but one case involves a complex 3' alteration and amplification which is apparently not directly virus-induced. S1 nuclease mapping of RNA from normal cells using c-myc probes revealed two presumptive 5' ends, each corresponding to a promoter-like sequence (P1 and P2), and a major 3' discontinuity which mapped to the 3'-most of two possible polyadenylation signals. Analysis of RNA from a series of tumours revealed different modes of c-myc expression. All tumours produced P1 and P2 transcripts with apparently normal structure except for one case where an insertion in intron 1 displaced exon 1 sequences. The abundance ratio of P1/P2 transcripts varied considerably and was high in tumours which carry a rearrangement adjacent to c-myc, but some other T-cell tumours with no apparent myc alteration displayed an equally high ratio. However, a consistent feature was the lack of detectable RNA from normal c-myc alleles in tumours which express a rearranged c-myc allele or a transduced FeLV v-myc gene. We suggest that this may prove to be a useful indicator of the presence of an oncogenically active myc gene, whether this is a rearranged c-myc or transduced v-myc sequence.", "journal": "Virology", "doi": "10.1016/0042-6822(87)90253-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3029415", "author": "Bergold PJ", "n_authors": 8, "title": "Nucleic acid sequence and oncogenic properties of the HZ2 feline sarcoma virus v-abl insert.", "abstract": "Hardy-Zuckerman 2 feline sarcoma virus (HZ2-FeSV), isolated from a multicentric feline fibrosarcoma is a replication-defective acute transforming feline retrovirus which originated by transduction of feline c-abl sequences with feline leukemia virus (FeLV) and is known to encode a 110-kilodalton gag-abl fusion protein with tyrosine-specific protein kinase activity (P. Besmer, W. D. Hardy, E. E. Zuckerman, P. J. Bergold, L. Lederman, and H. W. Snyder, Nature (London) 303:825-828, 1983). The nucleotide sequence of the abl segment in the HZ2-FeSV genome was determined and compared with the murine and human v-abl and c-abl sequences. The predicted transforming protein consists of 344 amino acids (aa) of FeLV gag origin, 439 aa of abl origin, and at least 200 aa of FeLV pol origin (p110gag-abl-pol). The 1,317-base-pair HZ2-FeSV v-abl segment (fv-abl) corresponds to 5' abl sequences which include the region known to specify the protein kinase domain. The 5' 189 base pairs of fv-abl correspond to 5' c-abl sequences not contained in Abelson murine leukemia virus (MuLV) v-abl. The mouse c-abl exon which contains these segments was identified, and its nucleotide sequence was determined. Comparison of the predicted amino acid sequence of fv-abl with those of Abelson MuLV v-abl and c-abl revealed five aa differences. The 5' junction between FeLV and abl was found to involve a preferred region in FeLV gag p30 (P. Besmer, J. E. Murphy, P. C. George, F. H. Qiu, P. J. Bergold, L. Lederman, H. W. Snyder, D. Brodeur, E. E. Zuckerman, and W. D. Hardy, Nature (London) 320:415-421, 1986). A six-base homology exists at the recombination site between the parental FeLV and the c-abl sequences. The 3' junction between fv-abl and FeLV pol predicts an in-frame fusion of fv-abl and FeLV pol. A transformed cell line containing a truncated gag-abl-pol protein, p85, that lacks most of the FeLV pol sequences was obtained by transfection of NIH 3T3 mouse cells. This result implies that the pol sequences of the p110gag-abl-pol protein are dispensable for fibroblast transformation. To assess whether the fv-abl segment specifies the unique biological properties of HZ2-FeSV, we constructed a Moloney MuLV-based version of HZ2-FeSV, Mo-MuLV(fv-abl), in which the fv-abl sequences were contained in a genetic context similar to that in HZ2-FeSV.(ABSTRACT TRUNCATED AT 400 WORDS)", "journal": "Journal of virology", "doi": "10.1128/JVI.61.4.1193-1202.1987", "deposited_data": "Sim", "nuccore_ids": "323883", "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3029597", "author": "Fulton R", "n_authors": 5, "title": "Retroviral transduction of T-cell antigen receptor beta-chain and myc genes.", "abstract": "Support for multistage models of oncogenesis has been provided by several highly leukaemogenic retrovirus isolates that have transduced more than one host cell gene. Where functional studies have been performed, these retroviral oncogenes show synergy for in vitro transformation and leukaemogenesis. In naturally occurring feline leukaemias associated with feline leukaemia virus (FeLV), retroviral transduction of myc is a frequent oncogenic mechanism. But evidence suggesting that the FeLV v-myc genes might be insufficient for leukaemogenesis was provided by the latency (12 weeks) and clonality of FeLV/v-myc-induced tumours and the absence of demonstrable in vitro transformation by these viruses. In the search for secondary leukaemogenic events in FeLV/v-myc tumours, we have identified a case of FeLV transduction of a T-cell antigen receptor beta-chain gene. The proviruses carrying this gene (which we have named v-tcr) were a separate population from those carrying v-myc. In its normal role, the T-cell receptor beta-chain forms part of a multimeric complex involved in antigen recognition and T-cell activation. We suggest that v-tcr is a novel viral oncogene which assisted v-myc in the genesis of a naturally occurring case of thymic lymphosarcoma.", "journal": "Nature", "doi": "10.1038/326190a0", "deposited_data": "Sim", "nuccore_ids": "61528", "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2832022", "author": "Onions D", "n_authors": 1, "title": "Epidemiology of feline leukaemia virus infections.", "abstract": "In cats the commonest cause of leukaemia and lymphomas is infection with feline leukaemia virus (FeLV). Following infection with this retrovirus some cats eliminate the virus and produce neutralizing antibody whereas others remain latently infected. A final group become persistently infected, and eventually succumb to neoplastic or non-neoplastic diseases induced by the virus. The proportion of cats falling into these different post-infection states depends on the age of exposure and the dose of virus received. In breeding colonies where the virus is endemic, up to 40% may be persistently infected, whereas in surveys of urban or suburban cats, only 1% are found to be infected for life. An important epidemiological feature of FeLV infection is that the majority of cats die from anaemia or immunosuppression rather than from leukaemia. Recent studies of the molecular biology of FeLV have shown that T cell tumour induction involves either transduction or insertional mutagenesis of the myc gene. Recombination between FeLV and FeLV related sequences present in all cat cells also appears to be important in generating different subgroups of the virus.", "journal": "Bailliere's clinical haematology", "doi": "10.1016/s0950-3536(87)80044-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3643650", "author": "Pedersen NC", "n_authors": 4, "title": "Isolation of a T-lymphotropic virus from domestic cats with an immunodeficiency-like syndrome.", "abstract": "A highly T-lymphotropic virus was isolated from cats in a cattery in which all the animals were seronegative for feline leukemia virus. A number of cats in one pen had died and several had an immunodeficiency-like syndrome. Only 1 of 18 normal cats in the cattery showed serologic evidence of infection with this new virus, whereas 10 of 25 cats with signs of ill health were seropositive for the virus. Tentatively designated feline T-lymphotropic lentivirus, this new feline retrovirus appears to be antigenically distinct from human immunodeficiency virus. There is no evidence for cat-to-human transmission of the agent. Kittens experimentally infected by way of blood or plasma from naturally infected animals developed generalized lymphadenopathy several weeks later, became transiently febrile and leukopenic, and continued to show a generalized lymphadenopathy 5 months after infection.", "journal": "Science (New York, N.Y.)", "doi": "10.1126/science.3643650", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3033380", "author": "Goitsuka R", "n_authors": 4, "title": "The decline in the production of interleukin 2 in cats spontaneously infected with feline leukemia virus.", "abstract": null, "journal": "Nihon juigaku zasshi. The Japanese journal of veterinary science", "doi": "10.1292/jvms1939.49.7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3031895", "author": "Gilbert JH", "n_authors": 3, "title": "Feline leukemia virus envelope protein expression encoded by a recombinant vaccinia virus: apparent lack of immunogenicity in vaccinated animals.", "abstract": "We have constructed a recombinant vaccinia virus encoding the expression of the feline leukemia virus (FeLV) envelope gene of the Gardner-Arnstein strain of FeLV subgroup B. Human cells infected with the recombinant virus (vFeLVenv) express and process the FeLV envelope protein similarly to cells infected with authentic FeLV. The mature gp 70 protein is transported to and accumulates on the surface of vFeLVenv-infected cells. Vaccinia virus replication and FeLV gp70 accumulation was also observed in cells of feline and murine origin, albeit at levels somewhat reduced from those in human cells. Toward the goal of developing a recombinant vaccinia virus as a live vaccine for feline leukemia disease in cats, immunogenicity studies were performed in cats and mice. These experiments yielded surprising results: although animals mounted a typical virus-neutralizing antibody response to the vaccinia virus vector, we were unable to detect antibodies against FeLV gp70 in any of the vaccinated animals. A subsequent 'booster' immunization with killed FeLV was unable to elicit evidence of immunologic 'priming' by the recombinant virus. We are presently unable to explain the apparent lack of immunogenicity. These results may point to complexities involved in the development of vaccines to protect against retrovirus infection.", "journal": "Virus research", "doi": "10.1016/0168-1702(87)90057-8", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3029288", "author": "Lafrado LJ", "n_authors": 4, "title": "Suppression of in vitro neutrophil function by feline leukaemia virus (FeLV) and purified FeLV-p15E.", "abstract": "Feline neutrophils (PMN) were isolated and exposed to ultraviolet light-inactivated feline leukaemia virus (UV-FeLV) and purified envelope component p15E (FeLV-p15E). Functional capacity of exposed PMN was measured in vitro utilizing the chemiluminescence (CL) response. PMN exposed to UV-FeLV demonstrated depressed CL responses to Ca2+-ionophore A23187 and latex particles. However, FeLV-p15E produced significant suppression in the CL response to A23187 but failed to produce significant alterations in response to latex particles. The data indicate that FeLV-p15E may, in part, be responsible for increased morbidity and mortality among FeLV-infected cats through suppression of the PMN population.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-68-2-507", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3303441", "author": "Juchem R", "n_authors": 2, "title": "[Megakaryocytic leukemia in three cats].", "abstract": "The present report describes a myeloproliferative disease, type megakaryocytic leukemia in three cats, 4, 8 and 11 years old. Clinically, the animals showed severe anemia. Neoplastic infiltrates were present in bone marrow, spleen, lymphnodes, liver and kidney. Two animals were FeLV positive.", "journal": "Tierarztliche Praxis", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3032440", "author": "Engelman RW", "n_authors": 3, "title": "Clearance of retroviremia and regression of malignancy in cats with leukemia-lymphoma during treatment with staphylococcal protein A.", "abstract": "Cats persistently infected with a type C retrovirus (feline leukemia virus; FeLV) were treated either by the extracorporeal perfusion of their plasma through filter columns containing staphylococcal protein A (SPA) or by the intraperitoneal injection of SPA for up to 32 treatments. The clearance of evidence of viral infection occurred during treatment with SPA in 67% of the treated cats with chronic viral infection that had FeLV-related abnormalities other than overt malignancy. This rate of viral clearance is more than 30 times greater than the incidence of spontaneous clearance of persistent FeLV viremia in the untreated cat. Actual clearance of viremia occurred in 28% of all cats treated. Regression of malignancy, which occurred in four of 12 (33%) treated cats, was demonstrated by reductions in tumor size and bone marrow neoplastic cell populations. Immediately preceding or concurrent with these remissions from viral infection and malignant disease, a marked though transient elevation in the plasma level of circulating gamma-like interferon occurred in some responding cats and was followed by the appearance and rising titer of a complement-dependent cytotoxic antibody that reacted with FeLV-infected cells. This IgG antibody was shown by several analyses to be specific for the major viral envelope glycoprotein gp70. Further investigations demonstrated that high levels of FeLV at the cellular level might be responsible for the reduced ability of normal feline lymphocytes to secrete gamma-interferon in response to mitogenic stimuli in vitro. These findings may provide some clue to the variation in the responsiveness of individual cats to immunotherapy with staphylococcal protein A.", "journal": "Cancer detection and prevention", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3031865", "author": "Loar AS", "n_authors": 1, "title": "The zoonotic potential of feline leukemia virus.", "abstract": "The many studies that have addressed the possibility for FeLV infection in human beings are reviewed in this article. Because of the many similarities between FeLV-induced immune system impairment in cats and retrovirus related acquired immune deficiency syndrome in man, these two conditions are discussed as well.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": "10.1016/s0195-5616(87)50608-8", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3030165", "author": "Kiehl AR", "n_authors": 4, "title": "Effects of feline leukemia virus infection on neutrophil chemotaxis in vitro.", "abstract": "A procedure for measuring in vitro feline neutrophil chemotaxis was developed, using a modified Boyden chamber apparatus and 3-microns-pore polycarbonate filters. A pooled feline serum sample was used as the chemoattractant. Chemotaxis was evaluated in 5 groups of cats: group 1-specific-pathogen-free cats that had not been exposed to feline leukemia virus (FeLV); group 2-previremic, FeLV-infected, specific-pathogen-free cats; group 3-FeLV-viremic, subclinically affected cats; group 4-FeLV-viremic, clinically affected cats; and group 5-sick cats that were not infected with FeLV. Neutrophils from the viremic, clinically affected cats had significantly lower (P less than 0.025) chemotactic responses than did those from subclinically affected, viremic cats. Conversely, neutrophils from cats that were ill due to causes other than FeLV had the highest mean chemotactic values. Among the viremic, subclinically affected cats, a linear relationship was found between age and chemotaxis, indicating that impairment of neutrophil function may be greater in younger viremic cats. However, FeLV-infected cats can not be identified on the basis of neutrophil chemotaxis.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3029936", "author": "Reinacher M", "n_authors": 1, "title": "Feline leukemia virus-associated enteritis--a condition with features of feline panleukopenia.", "abstract": "Infection with feline leukemia virus (FeLV) was demonstrated immunohistologically in 218 necropsied cats suffering from enteritis. The animals were divided into three groups according to histopathological criteria. The first group exhibited the signs of feline panleukopenia in intestine, lymphoid tissues, and bone marrow. Only 1.6% of these animals were FeLV-infected. The animals of the second group had histopathological alterations as seen in cats suffering from feline panleukopenia, but these were found only in the intestine and not in lymphoid tissues or bone marrow. Of these 71.9% were infected with FeLV. The third group consisted of all other cats suffering from enteritis of which 6.3% were FeLV-positive. The association between FeLV infection and the lesions seen in the animals of group 1 (feline panleukopenia) and group 3 (other types of enteritis) is statistically not significant whereas the alterations exhibited by the cats of group 2 are significantly FeLV-associated. Cats with FeLV-associated enteritis (group 2) are of a mean age of about 2.5 years and are significantly older than animals with feline panleukopenia which are of a mean age of about half a year. Thus a FeLV-associated enteritis exists as a histopathologically recognizable condition which sometimes might be mistaken for feline panleukopenia in routine post-mortem investigations.", "journal": "Veterinary pathology", "doi": "10.1177/030098588702400101", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3025858", "author": "Mitani M", "n_authors": 6, "title": "Suppressive effect on polyclonal B-cell activation of a synthetic peptide homologous to a transmembrane component of oncogenic retroviruses.", "abstract": "Purified feline leukemia virus, UV light-inactivated feline leukemia virus, and a synthetic peptide (CKS-17) homologous to a well-conserved region of the transmembrane components of several human and animal retroviruses were each studied for their effects on IgG production by feline peripheral blood lymphocytes. Using a reverse hemolytic plaque assay, both the viable virus and the UV-inactivated feline leukemia virus, but not the CKS-17, activated B lymphocytes to secrete IgG. When staphylococcal protein A, a polyclonal B-cell activator, was used to stimulate IgG synthesis by feline lymphocytes, the viable virus, the UV-inactivated virus, and the CKS-17 peptide each strongly suppressed IgG secretion without compromising viability of the lymphocytes. These findings suggest that the immunosuppressive influences of feline leukemia virus on immunoglobulin synthesis may reside in a conserved portion of the envelope glycoprotein that includes the region homologous to CKS-17.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.84.1.237", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "3025500", "author": "Abkowitz JL", "n_authors": 4, "title": "Lymphocytes and antibody in retrovirus-induced feline pure red cell aplasia.", "abstract": "The possible role of antibody and T-lymphocytes was investigated in the pure red cell aplasia (PRCA) associated with feline leukemia virus, subgroup C (FeLV-C), infection. In previous studies, erythroid colony-forming cells were undetectable in marrow culture of cats with PRCA. Yet erythroid burst-forming cells (BFU-E) remained, suggesting that BFU-E were able to differentiate in vitro but not in vivo. It was inferred that immunologic suppression may contribute to the pathogenesis of feline PRCA, and the interactions of antibody and T-lymphocytes with erythroid and granulocyte-macrophage progenitors were studied. Incubation of normal or PRCA marrow cells with PRCA serum or IgG concentrated from this serum and then complement (C') failed to decrease hematopoietic colony growth when compared to the results obtained with cultures of marrow cells incubated with C' alone. In crossover coculture studies, T-cells from Safari cats with PRCA had no inhibitory effect on colony growth from normal or autologous PRCA marrow cells. For the determination of whether feline PRCAs were associated with a clonal T-cell process, lymphocytes were obtained periodically from glucose-6-phosphate dehydrogenase (Glc-6-PD) heterozygous cats following FeLV-C infection and were expanded with a crude preparation of interleukin-2. The ratios of Glc-6-PD enzyme types in these samples did not change as cats developed anemia, suggesting that the inhibition of erythropoiesis was not associated with the clonal expansion of T-cells. These studies, therefore, do not support the premise that feline PRCA results from the interaction of antibody or T-cells with erythroid progenitors.", "journal": "Journal of the National Cancer Institute", "doi": "10.1093/jnci/78.1.135", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2830503", "author": "Osterhaus A", "n_authors": 4, "title": "Idiotype networks in the immune response to feline leukemia virus.", "abstract": null, "journal": "Monographs in allergy", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2829567", "author": "Pedersen NC", "n_authors": 1, "title": "Virologic and immunologic aspects of feline infectious peritonitis virus infection.", "abstract": "A number of feline coronavirus isolates have been characterized over the last few years. These isolates consist of what we have referred to as feline enteric coronaviruses (FECVs) and feline infectious peritonitis viruses (FIPVs). FECVs cause a transient enteritis in kittens but no systemic illness. FIPVs, in contrast, cause a systemic and usually fatal disease syndrome characterized either by an exudative serositis or a disseminated granulomatous disease. Although the diseases they cause are quite different, FECVs and FIPVs are antigenically and morphologically indistinguishable from each other. FECVs have a strict tropism for mature intestinal epithelial cells and do not appear to replicate in macrophages. In contrast, FIPVs, appear to spread rapidly from the intestinal mucosa and replicate in macrophages. Experiments will be presented, and literature cited, that will allow us to make the following assumptions about the pathogenesis of FIPV infection: 1) FIPVs and FECVs represent a spectrum of viruses that differ only in infectivity (ability to evoke seroconversion following oral infection) and virulence (ability to cause FIP), 2) field isolates are generally nearer to FECVs in behavior than laboratory isolates made from animal passaged material, 3) immunity to FIPV appears to be of the premunition type and is maintained for as long as the infection persists in a reactivatable form, 4) strains of feline coronaviruses that do not cause systemic disease, such as FECVs or low virulence FIPVs, can actually sensitize cats to infection with virulent FIPV strains, 5) FeLV infection interferes with established FIP immunity and allows for the reactivation of disease in healthy carriers, 6) FIPV may be passaged from queen to kitten either in utero or during neonatal life, and 7) kittens infected by their mothers with FIPV do not usually develop FIP but become immune carriers of the virus for a period of 5-6 months; recovery from the carrier state is associated with a loss of premunition immunity.", "journal": "Advances in experimental medicine and biology", "doi": "10.1007/978-1-4684-1280-2_69", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2826931", "author": "Kociba GJ", "n_authors": 2, "title": "Demonstration of retroviral proteins associated with erythroid progenitors of cats with feline leukemia virus-induced erythroid aplasia.", "abstract": "Feline erythroid aplasia is a fatal retrovirus-induced disease related to infection with feline leukemia virus of subgroup C. When bone marrow cells from cats inoculated with FeLV were incubated with polyvalent antibody to FeLV and cultured for erythroid colony formation, a complement-dependent inhibition of erythroid progenitors was demonstrated with virtually complete suppression of erythroid colony-forming units (CFU-E) and burst-forming units (BFU-E) evident from post-inoculation week 4 until termination in cats with progressive infection. When bone marrow cells from cats with regressive infection were treated similarly, CFU-E were inhibited on post-inoculation week 4 (98% inhibition) when the cats were viremic, and on week 6 (77% inhibition) when the leukocytes were negative for FeLV by immunofluorescence. These data suggest that the retroviral proteins are associated with erythroid progenitors or critical accessory cells and may play a role in selective suppression of erythropoiesis.", "journal": "Leukemia research", "doi": "10.1016/0145-2126(87)90168-8", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2826030", "author": "Olsen RG", "n_authors": 6, "title": "Feline leukemia virus: current status of the feline induced immune depression and immunoprevention.", "abstract": "This is a review of the current knowledge of feline leukemia virus (FeLV) associated with immune depression observed in cats. It will focus on the clinical and experimental observations associated with feline retroviral infection and presence in vivo and in vitro. We will briefly describe retroviral-associated acquired immune deficiency syndrome associated with FeLV infection in the cat and specific cellular pathology associated with FeLV latency. In addition, we will focus on the action of FeLV-p15E in vitro and describe possible mechanisms of the FeLV-associated immunosuppression observed both in vivo and in vitro. Lastly, we will evaluate the current status of immunoprevention of FeLV. We will not attempt an in-depth analysis of the current literature; our focus is to review current findings as they relate to feline AIDS and immunotherapy.", "journal": "Cancer metastasis reviews", "doi": "10.1007/BF00144266", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2825985", "author": "Neil JC", "n_authors": 4, "title": "The role of feline leukaemia virus in naturally occurring leukaemias.", "abstract": null, "journal": "Cancer surveys", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2821968", "author": "Beyer W", "n_authors": 5, "title": "Molecular cloning of an endogenous cat retroviral element (ECE 1)--a recombinant between RD-114 and FeLV-related sequences. Brief report.", "abstract": "A lambda L 47.1 clone library was constructed from BamHI digests of cellular cat DNA and was screened with cDNA probes specific for the 3'-terminus of the replication competent RD-114 virus. The first analysis of one clone (lambda-ECE 1) shows that it consists at least of a 3'-LTR and a 5' adjacent env gene. The LTR nucleotide sequences of the RD-114 cDNA clones and ECE 1 are identical within the R region and unrelated to FeLV. Otherwise, the region upstream from the 3'-LTR of ECE 1 shows homology to the transmembrane protein encoding gene of FeLV, but not to RD-114. These results imply that ECE 1 is a recombinant between an RD-114-like 3'-LTR and a FeLV-related env portion.", "journal": "Archives of virology", "doi": "10.1007/BF01320971", "deposited_data": "Sim", "nuccore_ids": "163878", "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2439849", "author": "Kodama T", "n_authors": 4, "title": "Infection of feline lymphoid cells with feline leukemia virus in culture.", "abstract": "An in-vitro system for infection of cat T lymphocytes with feline leukemia virus (FeLV) was developed. For establishment of this system, FeLV was inoculated in vitro into concanavalin-A stimulated primary lymphoid cells and long-term cultured T cells grown with interleukin-2 (IL-2) from various feline lympho-hematopoietic organs. During serial cultivation with IL-2, FeLV group-specific antigen (GSA) was detected 5-6 weeks after infection in the primary cultures, and 1 week after infection in the long-term cultures of T cells. The percentage of FeLV-GSA-positive cells gradually increased with passages and reached more than 80% in several cultures of lymphoid cells, that became persistently infected and produced FeLV. These FeLV-infected lymphoid cells expressed T-cell markers, but showed no obvious differences in growth or cytological characteristics from FeLV-free feline lymphoid cells during the observation period of 60 weeks.", "journal": "Leukemia research", "doi": "10.1016/0145-2126(87)90091-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2431166", "author": "Elder JH", "n_authors": 7, "title": "Localization of neutralizing regions of the envelope gene of feline leukemia virus by using anti-synthetic peptide antibodies.", "abstract": "We synthesized 27 synthetic peptides corresponding to approximately 80% of the sequences encoding gp70 and p15E of Gardner-Arnstein feline leukemia virus (FeLV) subtype B. The peptides were conjugated to keyhole limpet hemocyanin and injected into rabbits for preparation of antipeptide antisera. These sera were then tested for their ability to neutralize a broad range of FeLV isolates in vitro. Eight peptides elicited neutralizing responses against subtype B isolates. Five of these peptides corresponded to sequences of gp70 and three to p15E. The ability of these antipeptide antisera to neutralize FeLV subtypes A and C varied. In certain circumstances, failure to neutralize a particular isolate corresponded to sequence changes within the corresponding peptide region. However, four antibodies which preferentially neutralized the subtype B viruses were directed to epitopes in common with Sarma subtype C virus. These results suggest that distal changes in certain subtypes (possibly glycosylation differences) alter the availability of certain epitopes in one virus isolate relative to another. We prepared a \"nest\" of overlapping peptides corresponding to one of the neutralizing regions of gp70 and performed slot blot analyses with both antipeptide antibodies and a monoclonal antibody which recognized this epitope. We were able to define a five-amino-acid sequence required for reactivity. Comparisons were made between an anti-synthetic peptide antibody and a monoclonal antibody reactive to this epitope for the ability to bind both peptide and virus, as well as to neutralize virus in vitro. Both the anti-synthetic peptide and the monoclonal antibodies bound peptide and virus to high titers. However, the monoclonal antibody had a 4-fold-higher titer against virus and a 10-fold-higher neutralizing titer than did the anti-synthetic peptide antibody. Competition assays were performed with these two antibodies adjusted to equivalent antivirus titers against intact virions affixed to tissue culture plates. The monoclonal antibody had a greater ability to compete for virus binding, which suggested that differences in neutralizing titers may relate to the relative affinities of these antisera for the peptide conformation in the native structure.", "journal": "Journal of virology", "doi": "10.1128/JVI.61.1.8-15.1987", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "3219234", "author": "Brown AL", "n_authors": 2, "title": "Evolution of the structural proteins of human immunodeficiency virus: selective constraints on nucleotide substitution.", "abstract": "We have estimated the frequency of synonymous (KS) and amino acid replacement nucleotide substitutions (KA) among gag and env genes of published HIV sequences. The ratio of KS to KA can be used as an indicator of the intensity of the selective constraints on the amino acid sequence of a protein. By this approach we have shown that for both gp120 and gp41, the rate of change in amino acid sequence relative to the overall rate of change in nucleotide sequence is higher than for any other protein yet analyzed. The gag proteins p15 and p17 evolve slightly less rapidly, but p24 is relatively strongly conserved. We have compared the env gene of HIV with those of two other retroviruses for which appropriate data are available. In neither murine leukemia virus nor feline leukemia virus do the envelope glycoproteins evolve particularly rapidly. These results suggest that HIV is unusual among retroviruses in that both gp120 and gp41 are evolving under extremely weak selective constraints relative to the rest of the viral genome; accordingly, much of the observed variation may be selectively neutral.", "journal": "AIDS research and human retroviruses", "doi": "10.1089/aid.1988.4.399", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2855466", "author": "Neil JC", "n_authors": 7, "title": "Receptor-mediated leukaemogenesis: hypothesis revisited.", "abstract": "The discovery of the first example of retroviral transduction of an immunological effector molecule has led us to reconsider the possible importance of cell surface receptors of the immune system in leukaemia development. Antigen receptors on lymphoid cells not only bind external ligands but are crucial in the control of cellular proliferation. The concept of autocrine stimulation in oncogenesis is already well established and we see no reason to exclude the possibility of analogous mechanism operating through antigen receptors. At present, we are investigating the oncogenic function of the retrovirus (FeLV-T17) carrying a T-cell receptor gene (v-tcr). In addressing the general concept of oncogenesis by ligand/receptor interactions in the immune system we face the problem of the diversity and, for T-cell antigen receptors, the complex nature of receptor-ligand interaction. Nevertheless, the implications of the model encourage us to continue to search for new experimental tools and approaches to the question.", "journal": "The British journal of cancer. Supplement", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2855080", "author": "Kitchen LW", "n_authors": 3, "title": "Effect of continuous oral diethylcarbamazine treatment on lymphocyte counts of feline leukemia virus-infected cats.", "abstract": "In previous studies, administration of diethylcarbamazine (DEC) resulted in increased serum antibody titers to feline oncornavirus-associated cell membrane antigen (FOCMA) in cats infected with feline leukemia virus (FeLV). FeLV infection of cats frequently results in immunosuppression associated with lymphopenia. The present investigation demonstrated that chronic administration of DEC prevented or delayed severe lymphopenia in two FeLV-infected offspring of an FeLV-infected queen as compared to two untreated littermates.", "journal": "Journal of clinical & laboratory immunology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2848998", "author": "Yamamoto JK", "n_authors": 5, "title": "Feline immunodeficiency syndrome--a comparison between feline T-lymphotropic lentivirus and feline leukemia virus.", "abstract": "A feline T-lymphotrophic lentvirus (FTLV) has recently been isolated from a domestic cat free of feline leukemia virus (FeLV). This virus is distinct from FeLV (an oncornavirus), although they share a common denominator, namely, the ability to cause immunosuppression and induce lymphadenopathy and anemia. Their differences can be revealed by examining the following: the metal requirement for reverse transcriptase activity, the antigenic comparison by Western blot analysis, the different susceptibilities of a variety of feline cells, and the morphology based on electron microscopy. In the serological survey of 1,612 cats surveyed in the USA, 232 (14.4%) were seropositive for antibodies to FTLV, which was lower than for the 42 Canadian cats surveyed of which 8 (19%) were seropositive. Of the 61 cats positive for FeLV, 15 (25%) were also positive for FTLV, giving the impression that coinfection between these two retroviruses plays an important role in the cliniocpathological signs of what was previously thought to be solely an FeLV syndrome.", "journal": "Leukemia", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2847891", "author": "Zack PM", "n_authors": 2, "title": "Antithymocyte globulin treatment of retrovirus-induced feline erythroid aplasia: in vivo and in vitro studies.", "abstract": "The Kawakami-Theilen strain of feline leukemia virus (FeLV-KT) was used experimentally to produce erythroid aplasia in cats. The in vivo effects of goat anti-feline-thymocyte globulin (ATG) on hematopoiesis were investigated in FeLV-negative normal and FeLV-positive anemic cats. Treatment was initiated in anemic cats between 4 and 6 weeks postinoculation (PI) when erythroid progenitors were reduced to 10% of normal levels. During the first 2 weeks of treatment, ATG significantly increased the numbers of erythroid precursors in bone marrow from 15 to 35% in anemic cats and from 28 to 43% in normal cats. ATG stimulated a twofold increase of CFU-E and a threefold increase of CFU-GM in normal cats between 2 and 4 weeks after initiation of treatment but had no effect on CFU-E or CFU-GM in anemic cats. The in vivo effects of ATG were transient despite weekly treatment. Cats treated with normal globulin were not significantly different from untreated anemic control cats. In vitro treatment of low density bone marrow mononuclear cells with ATG plus complement increased CFU-E and BFU-E of bone marrow from cats prior to inoculation but not from viremic cats. These results indicate that, although ATG stimulates erythropoiesis and granulopoiesis in normal cats, it does not reverse retrovirus-induced erythroid aplasia.", "journal": "Clinical immunology and immunopathology", "doi": "10.1016/0090-1229(88)90128-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2846887", "author": "Levy LS", "n_authors": 3, "title": "Tumorigenic potential of a myc-containing strain of feline leukemia virus in vivo in domestic cats.", "abstract": "The oncogenic capacity of a myc-containing strain of feline leukemia virus (FeLV), termed LC-FeLV, has been examined after inoculation of the virus into neonatal kittens. Like other myc-containing strains of FeLV, LC-FeLV may induce with relatively short latency, but does not necessarily induce, thymic lymphosarcoma in viremic animals. Naturally occurring and experimentally induced tumors are T-cell lymphomas which contain clonally integrated LC-FeLV proviral DNA and which cannot readily be cultivated in vitro in the presence or absence of exogenously supplied interleukin-2. Acquisition of myc by FeLV decreases the period of latency before the appearance of tumors but does not expand the spectrum of tumors induced by FeLV alone.", "journal": "Journal of virology", "doi": "10.1128/JVI.62.12.4770-4773.1988", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2846702", "author": "Zelikman I", "n_authors": 2, "title": "Protein immunoassay based on agglutination of antibody-coated ferric oxide particles.", "abstract": "A novel immunoassay is described based on the agglutination by antigens of antibody-coated ferric oxide (Fe2O3) particles. The procedure for attachment of antibodies to the ferric oxide particles is simple and fast. The assay was used for identification and quantification of gamma-globulin in human serum and in chromatographic fractions as well as of gp70 (an envelope protein from feline leukemia virus) in the culture medium and for identification of the thyroid-stimulating hormone (TSH).", "journal": "Journal of immunological methods", "doi": "10.1016/0022-1759(88)90183-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2846700", "author": "Kushner NN", "n_authors": 4, "title": "Fluorometric enzyme immunoassay for measurement of infectious feline leukemia virus and its neutralization.", "abstract": "A fluorometric enzyme immunoassay using an alkaline phosphatase-conjugated monoclonal antibody was developed to quantitate feline leukemia virus (FeLV) infection. Monoclonal antibodies, directed against the FeLV structural protein p27, were conjugated with alkaline phosphatase using a modified maleimide method. The enzyme immunoassay requires only 4 days to reproducibly measure FeLV production instead of the 12 days required for the commonly used transformation assay using C81 cells. A linear correlation was found between the virion associated reverse transcriptase activity and the amount of intracellular p27 as determined by the fluorometric enzyme immunoassay. An immunocytochemical assay using the same conjugated monoclonal with a different substrate gave visible plaques in infected cell monolayers and was therefore used to titrate FeLV in plaque-forming units. The results obtained by all the procedures followed single hit kinetics for FeLV infection. The fluorometric enzyme immunoassay was adapted to measure FeLV neutralizing antibodies, allowing a sensitive and accurate determination of neutralizing titers.", "journal": "Journal of immunological methods", "doi": "10.1016/0022-1759(88)90181-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2460996", "author": "Aoyama A", "n_authors": 8, "title": "Major structural polypeptides of retrovirus produced by a Suncus murinus mammary tumor cell line and type D retrovirus share interspecies antigenic determinants.", "abstract": "Constitutive polypeptides of retrovirus produced by a Suncus murinus mammary tumor cell line (Sm-MTV) were characterized by immunofluorescence and immunoblotting. The major structural polypeptide of Sm-MTV, molecular weight 44/43K, immunologically cross reacted with the structural polypeptides of Mason-Pfizer monkey virus (MPMV) (molecular weights 27K and 12/10K). Sm-MTV constitutive polypeptides did not show antigenic relatedness with those of the following mammalian retroviruses: murine mammary tumor virus, Rausher murine leukemia virus, Molony murine leukemia virus, Osborn-Mendel rat leukemia virus, feline leukemia virus, RD114 virus, simian sarcoma virus 1, and human T-cell leukemia virus type I. Among the Sm-MTV structural polypeptides, those with molecular weights of 72/69K and 47K were glycosylated.", "journal": "Virology", "doi": "10.1016/0042-6822(88)90088-8", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "3266982", "author": "Bauer RM", "n_authors": 2, "title": "Parameters of production and partial characterization of feline interleukin 2.", "abstract": "The conditions for the production of feline interleukin 2 (IL-2) from peripheral blood leukocytes (PBL) and splenocytes by concanavalin A (Con A) stimulation are described. Feline IL-2 was quantitated by measuring DNA synthesis in the murine IL-2-dependent cell line, CTLL-20. In addition, feline IL-2 was generated for the maintenance of long-term cultures of Con A-stimulated feline PBL and for biochemical characterization. Finally, IL-2 production was evaluated from the PBL of feline leukemia virus (FeLV)-infected cats. Con A at 9.6 micrograms/ml produced a plateau of peak IL-2 activity from 24 to 48 h following stimulation. The tumor promoter, phorbol myristic acetate, stimulated feline IL-2 production and enhanced Con A-stimulated feline IL-2 production. Fetal calf serum (FCS) was not required for IL-2 production; however, FCS at 5% (v/v) allowed for maximal Con A-stimulated IL-2 production. Feline IL-2 generated from Con A-stimulated splenocytes migrated with an apparent molecular size of 13.7 to 23 kD by gel filtration chromatography and supported the proliferation of Con A-activated feline PBL at a final concentration of 0.3 to 0.9 units/ml.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(88)90105-5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "3183686", "author": "Cummins JM", "n_authors": 5, "title": "Oral use of human alpha interferon in cats.", "abstract": "Low doses (0.5 or 5.0 U) of human alpha interferon (HuIFN alpha) given orally prevented the experimental development of fatal feline leukemia virus (FeLV)-related disease. Twenty-one FeLV-susceptible cats were inoculated with the Rickard strain of FeLV. Cats given oral HuIFN alpha survived significantly (p less than 0.001) longer than untreated FeLV-infected cats. Moreover, only 4 of 13 (30.8%) HuIFN alpha-treated cats developed clinical disease during the course of the study, whereas 100% of the untreated control cats developed fatal FeLV-related disease. Thus, in experimental retroviral disease, heterologous species HuIFN alpha provided significant clinical benefits.", "journal": "Journal of biological response modifiers", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "3142827", "author": "Edwards JF", "n_authors": 4, "title": "Disseminated sarcocystosis in a cat with lymphosarcoma.", "abstract": "Cysts of the protozoan Sarcocystis sp were found in skeletal and cardiac musculature in a 1.5-year-old cat with lymphosarcoma. The cat was FeLV-positive and had grossly visible neoplastic involvement of the spinal cord, mediastinum, bone marrow, and kidneys. Ultrastructural examination of the parasitic cyst wall suggested that the species in this case was different from that described in the only other reported case. It was hypothesized that immunosuppression from FeLV infection permitted an aberrant life cycle with encystment of Sarcocystis sp in this cat.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2856249", "author": "Lyman SD", "n_authors": 3, "title": "Colony stimulating factor-1 induced growth stimulation of v-fms transformed fibroblasts.", "abstract": "The v-fms oncogene, which is capable of transforming fibroblasts, was derived by recombination of a feline leukemia virus with a cellular gene (c-fms) that encodes the receptor for colony stimulating factor 1 (CSF-1). We examined the capacity of recombinant human CSF-1 (produced in a yeast expression system) to stimulate the growth of v-fms transformed rat fibroblasts. Recombinant human CSF-1 bound to v-fms transformed fibroblasts with high affinity (apparent Kd = 6.0 x 10(-10) M); only non-specific binding was observed on control cells. The number of colonies formed in soft agar by v-fms transformed cells was increased by CSF-1 treatment in a dose-dependent manner; a nine fold increase in the number of colonies was seen in the presence of 10(-8) M CSF-1. CSF-1 did not stimulate the growth of either non-transformed cell lines, a non-transformed cell line that expresses a mutated v-fms protein on the cell surface, or cells transformed by the v-fgr oncogene. The growth stimulating effect of CSF-1 on v-fms transformed cells was also seen in monolayer culture. The v-fms transformed cells treated with CSF-1 had a more refractile, rounded morphology than non-treated cells; no morphology change was observed in CSF-1 treated control cells. CSF-1 treatment also increased both the number and size of foci that arose from fibroblasts following transfection with the v-fms oncogene. These data show that the altered CSF-1 receptor encoded by the v-fms oncogene retains a capacity to bind, and be stimulated by, human CSF-1.", "journal": "Oncogene", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2848490", "author": "Kölbl S", "n_authors": 2, "title": "[Critical application of the CITE-FeLV test, a new concept ELISA for the study of feline leukemia virus in blood samples from cats].", "abstract": null, "journal": "Berliner und Munchener tierarztliche Wochenschrift", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2845601", "author": "Weijer K", "n_authors": 5, "title": "[Prevalence of FTLV (feline T-lymphotropic lentivirus) infections in cats in The Netherlands and in West Germany].", "abstract": "The prevalence in the Netherlands and the Free Republic of Germany (FRG) of the newly discovered retrovirus of cats, which causes an immunodeficiency syndrome in this species and is termed feline T-lymphotropic lentivirus (FTLV), was estimated by conducting a serological survey among cats with different histories of disease. In an enzyme-linked immunosorbent assay (Petcheck, Agritech Trademark, Portland, USA) 265 samples of cats with chronic disease symptoms, and 78 samples of clinically healthy cats in the Netherlands, and 138 samples of cats with chronic disease symptoms in the FRG, were tested for the presence of FTLV-specific antibodies. All these samples had been taken from cats which were negative for FeLV antigen in the immunofluorescence test. In the groups of chronically ill animals 18 (7%) and 6 (4.5%) seropositive animals were found respectively, whereas in the group of clinically healthy cats no seropositive animals could be demonstrated.", "journal": "Tijdschrift voor diergeneeskunde", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2843665", "author": "Berry BT", "n_authors": 5, "title": "Structure and function of endogenous feline leukemia virus long terminal repeats and adjoining regions.", "abstract": "The nucleotide sequence of the 5' long terminal repeat (LTR) of three independent loci (CFE-6, CFE-16, and CF-14) of endogenous feline leukemia virus (FeLV) DNAs of the domestic cat genome was determined. The 3' LTR of the CFE-6 clone was also sequenced. The endogenous FeLV LTRs, which were very similar to each other in sequence and in organization of the functional domains, differed considerably from the exogenous FeLV LTR in the U3 region. The major differences in U3 included variations in sets of small (14 to 19 base pair) direct repeats, altered location of the simian virus 40 core enhancer-like sequence, and occurrence of three segments of largely nonhomologous sequences. There was extensive homology between endogenous and exogenous FeLV LTRs in sequences beginning from the TATA box through the R region down to the 3' end of the U5 region. The DNA sequence downstream of the 5' LTR encompassing the primer-binding site, leader, and almost to the end of the p15gag coding region, a point up to which the sequencing was carried out, also revealed a high degree of conservation. However, the detection of frameshift and nonsense mutations in this region of a nearly full-length endogenous provirus sequence (CFE-6) predicted its defectiveness and correlated with the lack of infectivity of this DNA. The functional studies of the endogenous LTRs, based on linkage to the bacterial cat gene and transient expression in feline cell lines, indicated that although the basic characteristics for promotion and enhancement of transcription were retained in each LTR, there was a significant variation in the activity of the cat constructs. Reconstruction and deletion analyses with the CFE-6 5' LTR revealed the presence of strong transcription regulatory sequences in the 702-base-pair region immediately upstream of the 5' boundary of the endogenous LTR. These and related data suggest that in addition to the transcription-modulating elements occurring within the LTR, the cis-acting nucleotide sequences in the upstream cellular DNA may determine the overall efficiency of transcription of the defective endogenous FeLV provirus loci of the felid genome.", "journal": "Journal of virology", "doi": "10.1128/JVI.62.10.3631-3641.1988", "deposited_data": "Sim", "nuccore_ids": "163819, 163818, 163817", "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "17423122", "author": "Hitt ME", "n_authors": 2, "title": "FeLV Infection, Hemolytic Anemia and Hypocellular Bone Marrow in a Cat: Treatment with Protein A and Prednisone.", "abstract": null, "journal": "The Canadian veterinary journal = La revue veterinaire canadienne", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "3044082", "author": "Furman PA", "n_authors": 2, "title": "Spectrum of antiviral activity and mechanism of action of zidovudine. An overview.", "abstract": "Zidovudine is a potent in vitro inhibitor of human immunodeficiency virus (HIV) with varying efficacy against other retroviruses. With the exception of Epstein-Barr virus, all non-retroviruses tested so far have been insensitive to inhibition by zidovudine. In vivo, efficacy of zidovudine was demonstrated against Rauscher murine leukemia virus and feline leukemia virus. In both experimental models, infections completely resolved in animals when the drug was administered soon after infection. These results suggest that prompt initiation of zidovudine therapy, following a known exposure to HIV, should be considered. Mechanism studies show that zidovudine is phosphorylated to the monophosphate and diphosphate derivatives by the host cell cytosolic thymidine kinase and thymidylate kinase, respectively. The identity of the enzyme that phosphorylates zidovudine diphosphate is not known, but is believed to be the cellular nucleoside diphosphate kinase. The triphosphate of zidovudine appears to be the active form of the drug. Zidovudine triphosphate competes well with thymidine 5'-triphosphate for binding to the HIV reverse transcriptase and also functions as an alternative substrate. Incorporation of zidovudine monophosphate results in chain termination. However, it is not clear which mechanism, chain termination or competition with thymidine 5'-triphosphate, or a combination of both, is responsible for the inhibition of HIV replication.", "journal": "The American journal of medicine", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2847394", "author": "Lewis MG", "n_authors": 6, "title": "Feline leukemia virus vaccine: new developments.", "abstract": null, "journal": "Veterinary microbiology", "doi": "10.1016/0378-1135(88)90071-5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2847393", "author": "Ogilvie GK", "n_authors": 3, "title": "Clinical and immunologic aspects of FeLV-induced immunosuppression.", "abstract": "Cats exposed to the feline leukemia virus (FeLV) may mount an effective immune response and eliminate the virus, develop a non-viremic, latent infection or become persistently infected and shed the virus. Persistently infected cats commonly die of secondary opportunistic infections that result from FeLV-induced immunosuppression. The acquired immunosuppression is the most frequent and most devastating consequence of FeLV infection in the cat. Immunosuppression is targeted primarily to the cell-mediated immune system and has been attributed to the viral p15e envelope protein. The decreased IgG response and proliferative response to T cell mitogens is thought to be due to a defect in the helper cell function. As a result of T helper cell immunosuppression, infected cats may also have defective cytotoxic lymphocyte and activated macrophage functions which are regulated by their lymphokines. Research has shown that the virus causes a general suppression in the production of T cell-derived lymphokines, including gamma interferon and interleukin 2. A decrease in the function of polymorphonuclear leukocytes has also been reported and may contribute to deaths due to opportunistic infections in FeLV-positive cats. There are numerous parallels between the acquired immunodeficiency syndrome (AIDS) in man and the FeLV-induced immunodeficiency syndrome in cats. Frequent deaths due to opportunistic infections, lymphopenia, depressed cell-mediated immune responses to T cell-dependent antigens despite hypergammaglobulinemia and the presence of a long period of time between infection and the onset of clinical signs are just a few of the syndromes that are similar between the 2 retroviral diseases. A new strain of FeLV, FeLV-FAIDS has been associated with a naturally occurring immunosuppressive syndrome that is strikingly similar to AIDS in man. In addition, a T-lymphotropic retrovirus has recently been identified from cats with an immunodeficiency-like syndrome; this feline lentivirus disease is morphologically similar, but antigenically distinct from the human immunodeficiency virus, the cause of AIDS. Treatment for FeLV immunosuppression is primarily supportive. The development of a soluble tumor cell antigen vaccine has been shown to be efficacious in preventing FeLV infections.", "journal": "Veterinary microbiology", "doi": "10.1016/0378-1135(88)90070-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2844635", "author": "Testa NG", "n_authors": 3, "title": "A feline model for the myelodysplastic syndrome: pre-leukaemic abnormalities caused in cats by infection with a new isolate of feline leukaemia virus (FeLV), AB/GM1.", "abstract": null, "journal": "Haematologica", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2850387", "author": "Chuma T", "n_authors": 4, "title": "IgG-Fc-receptor positive and negative T cells from feline leukemia virus-infected cats.", "abstract": null, "journal": "Nihon juigaku zasshi. The Japanese journal of veterinary science", "doi": "10.1292/jvms1939.50.699", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2895894", "author": "Overbaugh J", "n_authors": 4, "title": "Transduction of endogenous envelope genes by feline leukaemia virus in vitro.", "abstract": "Feline leukaemia viruses (FeLV) are exogenous retroviruses that can be detected in most cats with leukaemia, aplastic anaemia, myeloproliferative diseases and fatal immunosuppression. FeLV isolates have been divided into three subgroups, based on the viral envelope-determined properties of interference and host range in vitro. FeLV-A is present in all natural isolates and is generally minimally pathogenic. FeLV-B is found with FeLV-A in isolates from approximately 40% of natural infections and in a higher percentage of cats with lymphoma. Following the fundamental observations of genetic reassortment of avian retroviruses with endogenous viral genes and the origination of lymphomagenic viruses during the ontogeny of AKR mice, we show here that transfection of feline cells with FeLV-A DNA results in its recombination with endogenous FeLV-related sequences to produce viruses with the structural and host range properties of FeLV-B. Thus in vitro propagation of a retrovirus may result in the generation of variants with very different properties.", "journal": "Nature", "doi": "10.1038/332731a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "3221355", "author": "Swenson CL", "n_authors": 3, "title": "Chronic idiopathic neutropenia in a cat.", "abstract": "Persistent neutropenia (0-0.6 X 10(9) neutrophils/l) was documented during a 10-month period in a 4-year-old spayed female domestic shorthair cat that was presented for anorexia and depression. Salient abnormalities detected on physical examination were fever (40.3 degrees C), dehydration, and gingivitis. The cat was neutropenic (0.5 X 10(9) neutrophils/l) and enzyme-linked immunosorbent assay (ELISA) test for feline leukemia virus was negative. A bone marrow aspirate showed decreased numbers of mature granulocytic cells. In vitro bone marrow cultures for colony-forming units-granulocyte/macrophage (CFU-GM) were performed comparing bone marrow from the patient with that of a normal cat. The patient had fewer CFU-GM than the control. The number of CFU-GM increased when bone marrow mononuclear cells were cultured in the presence of 10(-5) and 10(-6) mol/l of hydrocortisone, but the cat did not respond to oral prednisolone therapy. The pathogenesis of the neutropenia in this cat remains obscure, but resembles the chronic idiopathic neutropenia syndrome of man.", "journal": "Journal of veterinary internal medicine", "doi": "10.1111/j.1939-1676.1988.tb02801.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2840305", "author": "Higashihara T", "n_authors": 5, "title": "[Serological survey of feline leukemia virus infection and the outcome of antibody-positive cats].", "abstract": "A serological survey was carried out to examine the presence of antibodies against feline leukemia virus (FeLV) and feline oncornavirus-associated cell membrane antigen (FOCMA) in 208 cat sera collected at Teikyo University School of Medicine. Seven cats (3.4%) were positive for FeLV antibodies by enzyme-linked immunosorbent assay whereas no cat was positive for FOCMA antibody by indirect membrane immunofluorescent test. Anemia, leukemia and/or lymphoma formation were not observed in these FeLV antibody-positive cats. But among these seven cats, three were positive for toxoplasma antibodies. One of them was also positive for Chlamydia psittaci antibody and it died in pneumonia. Among the four toxoplasma antibody negative cats, one was died in eosinophilic granuloma. Furthermore, two of three cats, which were used for experiments, had cold and took therapy.", "journal": "Jikken dobutsu. Experimental animals", "doi": "10.1538/expanim1978.37.2_201", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2835347", "author": "Citino SB", "n_authors": 1, "title": "Use of a subunit feline leukemia virus vaccine in exotic cats.", "abstract": "Three adult bengal tigers, 2 immature white tigers, and 3 adult servals were vaccinated IM with three 1-ml doses of a subunit FeLV vaccine with dosage interval guidelines of the manufacturer. All cats had increased antibody titers to FeLV gp 70 capsular antigen and feline oncornavirus cell membrane-associated antigen during the vaccination trial. Three weeks after the third vaccination, 7 of the 8 cats had gp70 antibody titers greater than 0.2 (optical density), and all 8 cats had feline oncornavirus cell membrane-associated antigen antibody titers greater than 1:8.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2833751", "author": "Riedel N", "n_authors": 4, "title": "Pathogenic and host range determinants of the feline aplastic anemia retrovirus.", "abstract": "Feline leukemia virus (FeLV) C-Sarma (or FSC) is a prototype of subgroup C FeLVs, which induce fatal aplastic anemia in outbred specific-pathogen-free (SPF) cats. FeLV C isolates also possess an extended host range in vitro, including an ability, unique among FeLVs, to replicate in guinea pig cells. To identify the viral determinants responsible for the pathogenicity and host range of FSC we constructed a series of proviral DNAs by exchanging gene fragments between FSC and FeLV-61E (or F6A), the latter of which is minimally pathogenic and whose host range in vitro is restricted to feline cells. Transfer of an 886-base-pair (bp) fragment of FSC, encompassing the codons for 73 amino acids at the 3' end of pol (the integrase/endonuclease gene) and the codons for 241 amino acids of the N-terminal portion of env [the extracellular glycoprotein (gp70) gene], into the F6A genome was sufficient to confer onto chimeric viruses the ability to induce fatal aplastic anemia in SPF cats. In contrast, no chimera lacking this sequence induced disease. When assayed in vitro, all chimeric viruses containing the 886-bp fragment of FSC acquired the ability to replicate in heterologous cells, including dog and guinea pig cells. Thus, the pathogenic and the host range determinants of the feline aplastic anemia retrovirus colocalize to a 3' pol-5' env region of the FSC genome and likely reside within a region encoding 241 amino acid residues of the N terminus of the extracellular glycoprotein.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.85.8.2758", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2834859", "author": "Blue JT", "n_authors": 1, "title": "Myelofibrosis in cats with myelodysplastic syndrome and acute myelogenous leukemia.", "abstract": "Bone marrow sections from 44 cats with myelodysplastic syndrome (MDS) or acute myelogenous leukemia (AML) were graded for reticulin content using light microscopic methods. Twenty-seven (61%) of the cats had slight to marked reticulin myelofibrosis. The association of myelofibrosis with possible pathogenetic factors, including megakaryocyte count, intramedullary lymphoid follicles, hemosiderin content, and FeLV antigenemia, was examined. No evidence was found that indicated a causal relationship between myelofibrosis and any of these factors.", "journal": "Veterinary pathology", "doi": "10.1177/030098588802500208", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2828667", "author": "Donahue PR", "n_authors": 7, "title": "Strong sequence conservation among horizontally transmissible, minimally pathogenic feline leukemia viruses.", "abstract": "We report the first complete nucleotide sequence (8,440 base pairs) of a biologically active feline leukemia virus (FeLV), designated FeLV-61E (or F6A), and the molecular cloning, biological activity, and env-long terminal repeat (LTR) sequence of another FeLV isolate, FeLV-3281 (or F3A). F6A corresponds to the non-disease-specific common-form component of the immunodeficiency disease-inducing strain of FeLV, FeLV-FAIDS, and was isolated from tissue DNA of a cat following experimental transmission of naturally occurring feline acquired immunodeficiency syndrome. F3A clones were derived from a subgroup-A-virus-producing feline tumor cell line. Both are unusual relative to other molecularly cloned FeLVs studied to date in their ability to induce viremia in weanling (8-week-old) cats and in their failure to induce acute disease. The F6A provirus is organized into 5'-LTR-gag-pol-env-LTR-3' regions; the gag and pol open reading frames are separated by an amber codon, and env is in a different reading frame. The deduced extracellular glycoproteins of F6A, F3A, and the Glasgow-1 subgroup A isolate of FeLV (M. Stewart, M. Warnock, A. Wheeler, N. Wilkie, J. Mullins, D. Onions, and J. Neil, J. Virol. 58:825-834, 1986) are 98% homologous, despite having been isolated from naturally infected cats 6 to 13 years apart and from widely different geographic locations. As a group, their envelope gene sequences differ markedly from those of the disease-associated subgroup B and acutely pathogenic subgroup C viruses. Thus, F6A and F3A correspond to members of a highly conserved family and represent prototypes of the horizontally transmitted, minimally pathogenic FeLV present in all naturally occurring infections.", "journal": "Journal of virology", "doi": "10.1128/JVI.62.3.722-731.1988", "deposited_data": "Sim", "nuccore_ids": "323904, 323902", "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2828650", "author": "Pinter A", "n_authors": 2, "title": "O-linked glycosylation of retroviral envelope gene products.", "abstract": "Treatment of [3H]glucosamine-labeled Friend mink cell focus-forming virus (FrMCF) gp70 with excess peptide:N-glycanase F (PNGase F) resulted in removal of the expected seven N-linked oligosaccharide chains; however, approximately 10% of the glucosamine label was retained in the resulting 49,000-Mr (49K) product. For [3H]mannose-labeled gp70, similar treatment led to removal of all the carbohydrate label from the protein. Prior digestion of the PNGase F-treated gp70 with neuraminidase resulted in an additional size shift, and treatment with O-glycanase led to the removal of almost all of the PNGase F-resistant sugars. These results indicate that gp70 possesses sialic acid-containing O-linked oligosaccharides. Analysis of intracellular env precursors demonstrated that O-linked sugars were present in gPr90env, the polyprotein intermediate which contains complex sugars, but not in the primary translation product, gPr80env, and proteolytic digestion studies allowed localization of the O-linked carbohydrates to a 10K region near the center of the gp70 molecule. Similar substituents were detected on the gp70s of ecotropic and xenotropic murine leukemia viruses and two subgroups of feline leukemia virus, indicating that O-linked glycosylation is a conserved feature of retroviral env proteins.", "journal": "Journal of virology", "doi": "10.1128/JVI.62.3.1016-1021.1988", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2893454", "author": "Overbaugh J", "n_authors": 5, "title": "Molecular cloning of a feline leukemia virus that induces fatal immunodeficiency disease in cats.", "abstract": "A replication-defective variant of feline leukemia virus was molecularly cloned directly from infected tissue and found to induce a rapid and fatal immunodeficiency syndrome in cats. Studies with cloned viruses also showed that subtle mutational changes would convert a minimally pathogenic virus into one that would induce an acute form of immunodeficiency. The data suggest that acutely pathogenic viruses may be selected against by current methods for isolation of the human and simian immunodeficiency viruses.", "journal": "Science (New York, N.Y.)", "doi": "10.1126/science.2893454", "deposited_data": "Sim", "nuccore_ids": "323926", "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2836593", "author": "Kitchen LW", "n_authors": 2, "title": "Effect of diethylcarbamazine on serum antibody to feline oncornavirus-associated cell membrane antigen in feline leukemia virus cats.", "abstract": "Diethylcarbamazine (N,N-diethyl-4-methyl-1-piperazine carboxamide; DEC) is a drug frequently used for prevention and treatment of the filariases. An opsonic action of DEC may generate increased immune responses to microfilariae. We tested the hypothesis that DEC treatment could result in higher antibody levels to other infectious agents. A retroviral animal model was studied, in light of the consideration that use of DEC as an antifilarial agent could conceivably alter seroepidemiologic surveys as well as serologic outcomes of vaccine trials in Africa regarding human immunodeficiency virus (HIV). The effect of DEC treatment on serum antibody to feline oncornavirus-associated cell membrane antigen (FOCMA) in domestic cats exposed to feline leukemia virus (FeLV) was examined. Nine cats that tested negative before treatment tested positive (greater than or equal to 1:10 serum dilution, geometric mean titer [GMT] = 278) for antibody to FOCMA after DEC treatment. Among 19 cats initially testing positive for FOCMA antibody, higher titers were noted after treatment in 17 (pretreatment GMT = 264; posttreatment GMT = 6,158). We conclude that a history of DEC treatment should be considered in evaluating humoral responses to infectious agents. Whether use of ivermectin, a recently introduced antifilarial agent, in lieu of DEC will affect clinical expression of HIV infection in humans also warrants analysis.", "journal": "Journal of clinical & laboratory immunology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2833042", "author": "Kitchen LW", "n_authors": 1, "title": "Effect of diethylcarbamazine on serum antibodies to feline infectious peritonitis in cats.", "abstract": "In preceding studies by the author, use of the immunomodulator drug diethylcarbamazine resulted in the detection of antibodies to feline oncornavirus-associated cell membrane antigen in nine feline leukaemia virus infected cats that had previously given negative results to this antibody. In the present report, seven diethylcarbamazine-treated cats developed higher serum antibody titres to feline infectious peritonitis more frequently than did seven untreated controls. Since feline infectious peritonitis is caused by a coronavirus, these results suggest that diethylcarbamazine treatment could be exploited for vaccination and treatment strategies for non-retroviral in addition to retroviral infections.", "journal": "Vaccine", "doi": "10.1016/0264-410x(88)90005-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2831764", "author": "Wellman ML", "n_authors": 4, "title": "Suppression of feline bone marrow fibroblast colony-forming units by feline leukemia virus.", "abstract": "Bone marrow fibroblast colony-forming units (CFU-F) were evaluated in cats experimentally infected with feline leukemia virus (FeLV). Cats that developed persistent viral infection and anemia (progressor cats) had a progressive decrease in the number of CFU-F at 2, 4, 6, 8, and 10 weeks after inoculation with FeLV. This suppression of CFU-F number in progressor cats ranged from 16 to 44% of the preinoculation CFU-F value. Cats that did not develop persistent viral infection or anemia (regressor cats) had decreased numbers of CFU-F (24% of the preinoculation CFU-F value) at 2 weeks after inoculation, but normal CFU-F numbers at 4, 6, 8, and 10 weeks after inoculation. In vitro incubation of bone marrow mononuclear cells from healthy cats with the 15,000-dalton envelope protein of FeLV resulted in decreased number of CFU-F (21% of that of untreated cultures). The number of CFU-F from bone marrow mononuclear cells incubated with the 27,000-dalton core protein of FeLV was similar to that from untreated cultures.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2834861", "author": "Bobade PA", "n_authors": 3, "title": "Feline haemobartonellosis: clinical, haematological and pathological studies in natural infections and the relationship to infection with feline leukaemia virus.", "abstract": "Haemobartonella felis infection was demonstrated in 38 cats which could be divided into four groups as follows: group A, feline leukaemia virus (FeLV) free cats with H felis infection alone; group B, FeLV free cats with H felis infection and other clinical conditions; group C, FeLV positive cats with H felis infection but no clinical manifestation of FeLV related or any other intercurrent disease; and group D, FeLV positive cats with H felis infection and clinical manifestations of FeLV related or other diseases. Cats in group A were healthy carriers of the infection and none was anaemic, whereas some in group B had clinical haemobartonellosis and anaemia. This anaemia was mainly mild, normocytic and normochromic. Most of the cats in group C and all in group D were more severely ill and anaemic, the anaemia usually being macrocytic and hypochromic. Splenomegaly occurred only in groups C and D. Treatment with tetracyclines did not eliminate H felis from any of the cats and blood transfusions were ineffective in promoting long term recovery from anaemia in cats with intercurrent H felis and FeLV infections. The findings in the cats in groups C and D were further compared with those in a fifth group of cats which were infected with FeLV but free of H felis.", "journal": "The Veterinary record", "doi": "10.1136/vr.122.2.32", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2847504", "author": "Rojko J", "n_authors": 3, "title": "Feline leukemia/sarcoma viruses and immunodeficiency.", "abstract": "This chapter discusses the structure feline leukemia virus (FeLV) and pathogenesis of lymphomas and leukemias BY FeLV. FeLV is quite similar to the better-studied murine leukemia viruses in structure and genetic map. The virus particles bud from cytoplasmic membranes into either extracellular spaces or into vacuoles. FeLV has long been considered a typical noncytopathogenic, longlatency leukemia virus based on its behavior in fibroblasts ", "journal": "Advances in veterinary science and comparative medicine", "doi": "10.1016/b978-0-12-039232-2.50007-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2556312", "author": "Gardner MB", "n_authors": 2, "title": "Animal models of AIDS.", "abstract": "Animal models of AIDS are essential for understanding the pathogenesis of retrovirus-induced immune deficiency and encephalopathy and for development and testing of new therapies and vaccines. AIDS and related disorders are etiologically linked to members of the lentivirus subfamily of retroviruses; these lymphocytopathic lentiviruses are designated human immuno-deficiency virus type 1 (HIV-1) and human immuno-deficiency virus type 2 (HIV-2). The only animals susceptible to experimental HIV-1 infection are the chimpanzee, gibbon ape, and rabbit but AIDS-like disease has not yet been reported in these species. Macaques can be persistently infected with some strains of HIV-2 but no AIDS-like disease has resulted. It is not yet clear how suitable HIV-infected SCID-hu mice will be as a model for AIDS. Several subfamilies of naturally occurring cytopathic retroviruses cause immune suppression, including fatal immunodeficiency syndromes in chickens, mice, cats, and monkeys. Domestic cats suffer immunosuppression from both an onco-virus, feline leukemia virus, and a member of the lentivirus subfamily, feline immunodeficiency virus (FIV). Asian macaques are susceptible to fatal simian AIDS from a type D retrovirus, indigenous in macaques, and from a lentivirus, simian immunodeficiency virus (SIV), which is indigenous to healthy African monkeys. SIV is the animal lentivirus most closely related to HIV. Of these animal models, the lentivirus infections of cats (FIV) and macaques (SIV) appear to bear the closest similarity in their pathogenesis to HIV infection and AIDS. This review will summarize these various animal model systems for AIDS and illustrate their usefulness for antiviral therapy and vaccinology.", "journal": "FASEB journal : official publication of the Federation of American Societies for Experimental Biology", "doi": "10.1096/fasebj.3.14.2556312", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2560357", "author": "Chew-Lim M", "n_authors": 3, "title": "A survey of the feline leukaemia virus in Singapore.", "abstract": "In this survey for the presence of the feline leukaemia virus (FeLV) in the Singapore domestic cat population, the sera of two different groups of unvaccinated mainly short haired cats which were over 6 months old were sampled. The FeLV enzyme-linked immunoadsorbent assay (ELISA) diagnostic test kit was used to detect the presence of the FeLV group specific (gs) antigens in the blood of cats. Of the 345 clinically healthy cats surveyed, 34 sera (9.9%) were found to be positive and of the group of 123 cats with clinical signs such as chronic wasting, marked by anaemia, anorexia and lethargy, 33 sera (26.8%) were found to be positive. From the time of diagnosis of a viraemia, 70% of cats will die within 20 months. The results are therefore indicative that annually a small proportion of cats in the local environment will die from a FeLV infection. This survey reflects the natural distribution of an infectious oncovirus in a susceptible host population which is unaffected by any control programme to interfere with the normal sequence of events of host virus interactions.", "journal": "Annals of the Academy of Medicine, Singapore", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2562225", "author": "Fisch H", "n_authors": 2, "title": "Feline immunodeficiency virus infection in a population of pet cats from southeastern Florida.", "abstract": "Blood samples from 95 randomly selected pet cats that were brought to veterinarians in southeastern Florida were tested for antibodies to feline immunodeficiency virus (FIV). Virus-specific antibodies (indicative of virus infection) were found in 8 of the 95 (8.4%) cats tested. All of the virus-infected cats were males (statistically significant, P less than or equal to 0.016) and were at least 1 year of age. The 3 most severely ill cats infected with FIV were also infected with feline leukemia virus.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/104063878900100411", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2551866", "author": "Romatowski J", "n_authors": 1, "title": "Interpreting feline leukemia test results.", "abstract": "Routine prevaccinal screening for FeLV has inherent statistical limitations owing to the magnification of false-positive test errors by the low prevalence of FeLV viremia in the general cat population. Positive ELISA test results obtained in a screening program should be interpreted with caution, because a high proportion--approximately 72%--of such are likely to be false-positive results. On the other hand, routine screening is an excellent method for ruling out FeLV viremia, because a false-negative result is likely to be obtained in only 1/1,000 tests.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2551864", "author": "Lopez NA", "n_authors": 6, "title": "Sensitivity and specificity of blood test kits for feline leukemia virus antigen.", "abstract": "Enzyme-linked immunosorbent assay (ELISA) test kits have been used widely to diagnose FeLV infection. Several companies have licensed such kits, but because these test kits are designed somewhat differently, a demonstration of their relative merits was needed. Differences in the sensitivity and specificity of 7 commercial test kits were determined by testing sera that induce false-negative (limiting dilution of FeLV group specific antigen, p27), and false-positive (cat anti-mouse antibody) test results. Among the panels of sera used in this study, significant differences in test kit sensitivity were not observed, but differences in specificity were identified. An interim report of these studies, supplied to the manufacturers, prompted changes in some of the kits, resulting in improved specificities. Generally, FeLV test kits are now more efficient in accurately detecting p27 in blood, serum, or plasma of cats. Nevertheless, some kits still lack specificity attributable to reagents supplied by the manufacturer.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2551863", "author": "Lopez NA", "n_authors": 2, "title": "False-positive reactions associated with anti-mouse activity in serotests for feline leukemia virus antigen.", "abstract": "False-positive reactions were observed in commercial test kits designed to detect FeLV infections in cats. The false-positive reactions were associated with heterophilic antibody in cat serum directed primarily against mouse immunoglobulins. Of 2,830 sera tested, 579 were considered FeLV positive or equivocal via ELISA; of these, 10 were found that did not have FeLV antigen but did have anti-mouse antibody. With 95% confidence, 0.14% to 0.57% of cats would have such false-positive reactions in ELISA, because one in 283 (0.35%) cats had anti-mouse antibodies.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2554556", "author": "Hosie MJ", "n_authors": 3, "title": "Prevalence of feline leukaemia virus and antibodies to feline immunodeficiency virus in cats in the United Kingdom.", "abstract": "A representative sample of the pet cat population of the United Kingdom was surveyed. Blood samples from 1204 sick and 1007 healthy cats of known breed, age and sex were tested for antibodies to feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV). The prevalence of FIV was 19 per cent in sick cats and 6 per cent in healthy cats, and the prevalence of FeLV was 18 per cent in sick cats and 5 per cent in healthy cats; both infections were more common in domestic cats than in pedigree cats. Feline immunodeficiency virus was more prevalent in older cats but FeLV was more prevalent in younger cats. There was no difference between the prevalence of FeLV in male and female cats but male cats were more likely to be infected with FIV than female cats. No interaction was demonstrated between FIV and FeLV infections. Of the cats which were in contact with FIV in households with more than one cat, 21 per cent had seroconverted. The prevalence of FeLV viraemia in cats in contact with FeLV was 14 per cent. The clinical signs associated with FIV were pyrexia, gingivitis/stomatitis and respiratory signs, and with FeLV, pyrexia and anaemia. It was concluded that both viruses were significant causes of disease, and that the cats most likely to be infected with FIV were older, free-roaming male cats and for FeLV, younger, free-roaming cats.", "journal": "The Veterinary record", "doi": "10.1136/vr.125.11.293", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2746730", "author": "Ruegg CL", "n_authors": 3, "title": "Identification, using synthetic peptides, of the minimum amino acid sequence from the retroviral transmembrane protein p15E required for inhibition of lymphoproliferation and its similarity to gp21 of human T-lymphotropic virus types I and II.", "abstract": "Synthetic peptides containing portions of a highly conserved region of retroviral transmembrane proteins of human and animal retroviruses were tested for their ability to inhibit lymphoproliferation to determine the minimum amino acid sequence required. The previously reported immunosuppression mediated by the peptide CKS-17 was confirmed and further localized to a sequence of eight residues essentially identical to the sequence present in the transmembrane protein gp21 of human T-lymphotropic virus types I and II (HTLV-I and -II). To substantiate the physiological relevance of the inhibition of lymphoproliferation observed with the synthetic peptides and to relate this activity to the intact protein, we purified the Rauscher murine leukemia virus transmembrane protein p15E by immunoaffinity chromatography and report that this purified component presented in the form of protein micelles inhibited the interleukin-2-dependent proliferation of the murine T-cell line CTLL-2 in a dose-dependent manner, with a half-maximal inhibitory dose (ID50) of approximately 16 nM. In comparison, the ID50 concentration of a recombinant form of p15E required to inhibit lymphoproliferation was approximately 2.2 microM. The results reported here support the hypothesis that the transmembrane protein gp21 of HTLV-I and -II participates in the mechanism of immunosuppression previously reported for the transmembrane proteins of feline leukemia virus and other animal retroviruses. Thus, the transmembrane protein of HTLV-I, the etiological agent of adult T-cell leukemia-lymphoma, may be partially responsible for the immunocompromised clinical course of this disease that results in fatal opportunistic infections in a majority of cases.", "journal": "Journal of virology", "doi": "10.1128/JVI.63.8.3250-3256.1989", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2553988", "author": "Laprevotte I", "n_authors": 1, "title": "Scrambled duplications in the feline leukemia virus gag gene: a putative pattern for molecular evolution.", "abstract": "The present study is a detailed computer-assisted analysis of the feline leukemia virus gag gene nucleotide sequence together with its flanking sequences (ST-FeLV GAG) that is compared with the aligned sectors of the Moloney strain of murine leukemia virus (Mo-MuLV GAG) and of three strains of feline sarcoma virus. It shows that perfectly matched repeated oligomers up to 13 nucleotides long are overrepresented and scattered throughout both ST-FeLV GAG and Mo-MuLV GAG, in noncoding and coding sectors, with no stringent correlation to codon usage in ST-FeLV gPr80gag. Many repeated oligomers share a core consensus that is intriguingly part of the inverted repeat at the termini of the long terminal repeat. Local scrambled repetitions of nucleotide subsequences have been found; they suggest a model of molecular evolution by slippage-like mechanisms. Thus, viral genomes could be subject to the same evolutionary mechanisms that are now known to be operating extensively in eukaryotic genomes. The data are discussed in light of putative patterns of molecular evolution.", "journal": "Journal of molecular evolution", "doi": "10.1007/BF02100112", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2544649", "author": "Tompkins MB", "n_authors": 8, "title": "Feline cytotoxic large granular lymphocytes induced by recombinant human IL-2.", "abstract": "Large granular lymphocytes (LGL) have been characterized phenotypically and functionally as cytotoxic T lymphocytes, NK cells or lymphokine-activated killer cells. The most prominent morphologic feature of LGL is large cytoplasmic granules that are thought to contain the molecules responsible for cell lysis. In this study, we describe the morphologic and functional characteristics of IL-2-dependent cytotoxic lymphocytes derived from feline PBL. Stimulation of feline PBL with Con A followed by culturing in 50 U of gibbon monkey IL-2 human rIL-2 induced long term lymphocyte cultures. These lymphocytes are cytotoxic for the feline leukemia virus-induced T cell lymphoma (FL74), in a 4-h 51Cr release assay. All cell lines are either constitutively cytotoxic for FL74 cells, or cytotoxic in a lectin-dependent cell cytotoxic assay, the latter being a characteristic of low passage cultures. In contrast, no cell lines express self lysis or lysis for other lines. [3H]TdR uptake showed that 1 U of human rIL-2 produces a 50% maximal proliferative response by feline lymphocytes suggesting a high degree of homology between the ligand binding sites of feline and human IL-2R. Feline cytotoxic lymphocytes possess abundant cytoplasm containing large azurophilic granules characteristic of LGL. These granules are bound by a bilipid membrane and contain numerous smaller membrane-bound vesicles 50 to 60 nm in diameter. A model is proposed, whereby subsequent to binding of LGL to target cell the large granules fuse to the LGL plasma membrane and release the small vesicles into the binding pocket. The vesicles then transport the lytic molecules directly and selectively to the target cell membrane.", "journal": "Journal of immunology (Baltimore, Md. : 1950)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2794150", "author": "Grindem CB", "n_authors": 2, "title": "Cytogenetic analysis in nine leukaemic cats.", "abstract": "Eight of nine leukaemic cats had chromosomal abnormalities. The major differences between the healthy, FeLV-negative control cats and the leukaemic cats were the increased number of hyperdiploid cells and the presence of double minute or morphologically abnormal chromosomes in the leukaemic cats. Three leukaemic cats had cells with double minute chromosomes, while no normal cats had cells with double minute chromosomes. Tetrasomy or trisomy most frequently involved chromosomes C2 and B4. Monosomy was most common in chromosomes A3, C2, D4, E3 and F2. Chromosome abnormalities were also observed in bone marrow cells from two of three healthy, FeLV-positive cats and both cats with thymic lymphosarcoma. Increased numbers of hyperdiploid cells, double minute chromosomes and trisomy of C2 were the most important findings. No correlations between cytogenetic findings and diagnosis or prognosis were found. Additional research is necessary to determine the significance of chromosome aberrations in cells from healthy, FeLV-positive cats. If these changes prove to represent early neoplastic transformation, chromosome analysis could provide valuable diagnostic information and identify patients that might benefit from early chemotherapy. Results of this limited study indicate (1) chromosome aberrations are common in leukaemic cats, (2) chromosome changes are not completely random, (3) direct bone marrow technique for chromosome analysis is generally preferable in leukaemic cats and (4) the cat appears to be a good model in which to study chromosomal abnormalities in leukaemia, though more research is needed.", "journal": "Journal of comparative pathology", "doi": "10.1016/0021-9975(89)90073-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2786762", "author": "Hofmann B", "n_authors": 10, "title": "Investigation of immunosuppressive properties of inactivated human immunodeficiency virus and possible neutralization of this effect by some patient sera.", "abstract": "Retroviral infections are accompanied by immunosuppression in a variety of species. For feline leukemia virus, the immunosuppression has been ascribed to the transmembrane envelope protein, p15E, which suppresses the proliferative responses of cat, mouse, and human lymphocytes. A similar suppressive effect has been shown for a lysate of human immunodeficiency virus (HIV), strain HTLV-IIIB. Here we determined that detergent-disrupted HTLV-IIIB lystate exerted a strong suppressive effect on PHA-stimulated lymphocytes. Preparations of whole virions, a lysate of a local HIV isolate grown on MP-6 cells, and a commercially obtained UV and psoralene-inactivated lysate were examined and demonstrated to have a similar suppressive effect. The HIV lysate was not directly cytotoxic to lymphocytes and did not contain tumor necrosis factor or lymphotoxin. The HIV lysate specifically suppressed the proliferation of a range of hemopoietic cell lines from man and mouse including three EBV transformed CD4- and IL-2 receptor-negative B-cell lines. The lysate also suppressed the formation of human bone marrow colonies, whereas the lysate had only a slight or no effect on fibroblasts. The suppression of lymphocyte proliferation was not abrogated by addition of IL-2 or IL-1 and the HIV lysate inhibited the expression of IL-2 receptors on suboptimal PHA-stimulated mononuclear cells. The suppressive factor(s) has not been characterized in molecular terms, but suppressive activity was recovered in fractions with a molecular weight of about 67,000 and in both the glycoprotein fraction and in the glycoprotein-depleted fraction of the HIV lysate. Sera from one-third of a small series (N = 13) of individuals with antibodies to HIV seem to be able to neutralize the suppressive properties of HIV lysate in cultures.", "journal": "Cellular immunology", "doi": "10.1016/0008-8749(89)90032-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2778747", "author": "Lappin MR", "n_authors": 5, "title": "Clinical feline toxoplasmosis. Serologic diagnosis and therapeutic management of 15 cases.", "abstract": "Clinical toxoplasmosis was diagnosed in 15 cats by correlating serologic evidence of infection and clinical signs to either response to therapy or histopathologic demonstration of the organism. Ophthalmic manifestations, primarily involving the anterior segment, were common. Other common physical examination abnormalities included muscle hyperesthesia, fever, and weight loss. Response to therapy was variable, but administration of clindamycin hydrochloride resulted in resolution of all clinical signs not involving the eyes in surviving animals. This drug, alone or in combination with corticosteroids, led to total resolution of clinical signs in four of four cats with active retinochoroiditis and in six of nine cats with anterior uveitis. Four of the 15 cats had concurrent infection with feline immunodeficiency virus (FIV). Feline leukemia virus antigen or antibodies to feline infectious peritonitis virus were not detected.", "journal": "Journal of veterinary internal medicine", "doi": "10.1111/j.1939-1676.1989.tb03089.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2752129", "author": "Lin L", "n_authors": 4, "title": "Use of 8-methoxypsoralen and long-wavelength ultraviolet radiation for decontamination of platelet concentrates.", "abstract": "Transmission of viral diseases through blood products remains an unsolved problem in transfusion medicine. We have developed a psoralen photochemical system for decontamination of platelet concentrates in which platelets are treated with long wavelength ultraviolet radiation (UVA, 320-400 nm) in the presence of 8-methoxypsoralen (8-MOP). Bacteria, RNA viruses, and DNA viruses ranging in genome size from 1.2 x 10(6) daltons, encompassing the size range of human pathogens, were inoculated into platelet concentrates and subjected to treatment. This system inactivated 25 to 30 logs/h of bacteria Escherichia coli or Staphylococcus aureus, 6 logs/h of bacteriophage fd, 0.9 log/h of bacteriophage R17 and 1.1 logs/h of feline leukemia virus (FeLV) in platelet concentrates maintained in standard storage bags. Platelet integrity and in vitro function before, immediately following photochemical treatment, and during prolonged storage after treatment, were evaluated by measuring: (1) extracellular pH; (2) platelet yields; (3) extracellular lactate dehydrogenase (LDH) levels; (4) platelet morphology; (5) platelet aggregation responsiveness; (6) thromboxane beta-2 (TXB-2) production; (7) dense body secretion; and (8) alpha granule secretion. These assays demonstrated that this photochemical inactivation system inactivated bacteria and viruses in platelet concentrates with minimal adverse effects on the in vitro function of platelets in comparison to untreated control concentrates maintained under current, standard blood bank conditions.", "journal": "Blood", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2549672", "author": "Parry BW", "n_authors": 3, "title": "Diagnosis of feline leukemia virus and feline immunodeficiency virus infections.", "abstract": "Feline leukemia virus is an oncogenic retrovirus that can result in a wide variety of neoplastic and non-neoplastic diseases, including immunosuppression. Diagnosis of FeLV infection can be achieved by several methods, including virus isolation; IFA assay of a peripheral blood smear; and detection of a viral protein (called p27) by ELISA testing of whole blood, plasma, serum, saliva, or tears. Commercially available ELISA kits have revolutionized FeLV testing and have become very popular as \"in-house\" procedures. This article discusses the interpretation of ELISA results and compares them with IFA assay findings. Feline immunodeficiency virus is a lentivirus that causes immunosuppression, but not neoplasia, in cats. It originally was called feline T-lymphotropic lentivirus. Differentiating FIV infection from the immunosuppressive type of FeLV infection requires virus isolation or serology. The most rapid method for diagnosis of FIV infection is ELISA testing for antiviral antibody.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": "10.1016/s0195-5616(89)50080-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2543497", "author": "Kitchen LW", "n_authors": 2, "title": "Hematologic effects of short-term oral diethylcarbamazine treatment given to chronically feline leukemia virus-infected cats.", "abstract": "Diethylcarbamazine (N,N-diethyl-4-methyl-1-piperazine carboxamide [DEC]) is widely used, especially in tropical regions, to prevent and treat filariasis. The antifilarial effect of this drug has been attributed to immunomodulation. Evidence is accumulating to indicate that DEC may mitigate the course of feline leukemia virus infection (FeLV) in cats. Previous studies have suggested that continuous oral DEC treatment given shortly after evidence of FeLV infection prevents or delays lymphopenia and prolongs survival. The present study focuses on the hematologic effects of one month oral DEC treatment given to adult chronically FeLV-infected cats and uninfected cats as compared to untreated FeLV-infected cats. Such treatment frequently resulted in abruptly lowered peripheral lymphocyte counts in chronically FeLV-infected cats. Further studies are warranted to evaluate whether administration of DEC could eliminate circulating retroviral-infected cells.", "journal": "Cancer letters", "doi": "10.1016/0304-3835(89)90075-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2549696", "author": "Reinacher M", "n_authors": 1, "title": "Diseases associated with spontaneous feline leukemia virus (FeLV) infection in cats.", "abstract": "More than 2000 cats sent for necropsy in order to provide a diagnosis were investigated immunohistologically using paraffin sections for the presence of a persistent infection with feline leukemia virus (FeLV). The spectrum of neoplastic and non-neoplastic diseases associated significantly with FeLV infection was determined statistically. Three-quarters of the cats with persistent FeLV infections died of non-neoplastic diseases and about 23% died of tumors, nearly exclusively those of the leukemia/lymphoma disease complex. A strong association with liver degeneration, icterus and a FeLV-associated enteritis was found in addition to the known association with non-neoplastic diseases and conditions such as anemia, bacterial secondary infections and respiratory tract inflammations due to the immunosuppressive effect of FeLV, hemorrhages and feline infectious peritonitis. Surprisingly, diseases and conditions like feline infectious panleukopenia, enteritis (of other types than FeLV-associated enteritis and feline infectious panleukopenia), glomerulonephritis, uremia and hemorrhagic cystitis were not associated with persistent FeLV infection. Another unexpected finding was that most pathogenic infectious agents demonstrated in the cats were not FeLV-associated either. Thus, immunosuppression due to FeLV infection seems to make the animals susceptible to certain pathogenic infectious agents, but not to the majority.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(89)90132-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2549695", "author": "Weijer K", "n_authors": 3, "title": "Control of feline leukaemia virus.", "abstract": "Feline leukaemia virus (FeLV) usually occurs in its natural species, the domestic cat. FeLV is also important to human individuals as a comparative model, as it may cause a variety of diseases, some malignant and some benign, such as immunosuppression, which bears a resemblance to AIDS (acquired immune deficiency syndrome) in man. FeLV is transmitted among cats by contagion. The main sources of infection are persistently infected carrier cats which continuously excrete virus. Dissemination of FeLV among cats may be prevented by identifying infected carrier cats and removing them from contact with non-infected cats. Removal programmes using indirect immunofluorescence antibody tests were applied successfully in The Netherlands. The proportion of FeLV-positive cats decreased from 9% in 1974 to approximately 3% in 1985 during such a programme. The results of a removal programme carried out in a catbreeders' society were even better: the incidence of cats positive for FeLV decreased from 11% in 1974 to less than 2% within 4 years. None of the cats tested in this society has been found to be positive for FeLV since 1984. Besides removal programmes, other methods of control, such as pre-exposure treatment, were developed to prevent the spread of FeLV. We attempted to protect kittens against oronasal infection with FeLV by treatment with virus-neutralizing (VN) monoclonal antibodies (MoAbs) directed against an epitope on the viral glycoprotein gp70. However, no protection was achieved. It is unlikely that the amount of VN antibodies, the mode and route of their application or the infectious dose of FeLV used can account for this failure. Other possible explanations for the lack of protective effect are that (i) the restricted epitope specificity of the MoAb preparation used may have led to selection of neutralization-resistant virus mutants, or (ii) other mechanisms than virus neutralization (complement-mediated lysis, antibody-dependent cell cytotoxicity), that may be involved in protection, function less efficiently with MoAb. However, in the light of our finding that an early anti-idiotypic response is observed in all cats following administration of the MoAb preparation, the rapid clearance of anti-FeLV MoAb from the circulation is a more likely explanation. Efforts were further made to develop a vaccine for controlling FeLV infection. The immunostimulating complex vaccine (FeLV-ISCOM vaccine), a subunit vaccine in which FeLV gp70 is presented in a particular manner, looks promising. The protective effect of FeLV-ISCOM vaccine was studied by vaccinating six 8-week-old SPF cats with ISCOM, followed by oronasal challenge with FeLV.(ABSTRACT TRUNCATED AT 400 WORDS)", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(89)90131-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2549694", "author": "Dezzutti CS", "n_authors": 5, "title": "FeLV-induced immunosuppression through alterations in signal transduction: down regulation of protein kinase C.", "abstract": "Activation of protein kinase C by a phorbol ester, 12-O-tetradecanoylphorbol-13-acetate (TPA), was shown to stimulate the respiratory burst in normal cat neutrophils. Neutrophils from feline leukemia virus (FeLV)-exposed viremic and nonviremic cats had significant suppression of their respiratory burst when stimulated with TPA. The addition of whole ultraviolet light-inactivated FeLV and FeLV proteins to normal cat neutrophils produced no significant suppression of the respiratory burst. These data suggest two possible mechanisms for suppression. The first is partially due to viral alterations of the neutrophil as seen in viremic cats, but, because exogenously applied FeLV or FeLV proteins had no effect on the respiratory burst, an additional mechanism is present. The second mechanism may be caused by a latent FeLV infection residing in nonviremic cat bone marrows which alters their immune system, resulting in immunosuppression.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(89)90130-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2549693", "author": "Wright KA", "n_authors": 4, "title": "FeLV-induced immunosuppression through alterations in signal transduction: changes in intracellular free calcium levels.", "abstract": "Feline leukemia virus (FeLV) is a retrovirus with immunosuppressive properties. The mechanism(s) of immunosuppression is unknown. Calcium has been shown to be a second messenger in cellular activation and regulation. This study was designed to determine whether FeLV alters intracellular free calcium (IFC) levels in an FeLV-infected feline lymphoid cell line. Control cells and FeLV-infected cells were exposed to Concanavalin A, formyl-L-methionyl-L-leucyl-L-phenylalanine, and leukotriene B4. The basal IFC and post-stimulation IFC levels were recorded using Fura 2 AM and a luminescence spectrometer. Data collected indicate that FeLV-infected cells have a higher basal level of IFC and a reduced amount of increase in IFC after stimulation when compared to the control cells. The results would seem to indicate retrovirus-mediated interference occurring in the intracellular calcium signaling process.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(89)90129-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2549692", "author": "Lafrado LJ", "n_authors": 4, "title": "Immunodeficiency in latent feline leukemia virus infections.", "abstract": "Challenge of naive experimental animals with a retroviral inoculum may result in one of two broad sequelae. The first is the establishment of an appropriate humoral and cellular immune response leading to a condition of immunity to subsequent infection with the retrovirus. Alternatively, the host may fail to develop a successful immune response, resulting in a chronic viremia associated with immunosuppression and ultimately death due to secondary pathogens. An alternate disease course is the establishment of a latent infection characterized by the presence of neutralizing antibody and strong cellular immune reactivity. Recent data from the feline leukemia virus (FeLV) system suggest that cats infected with this virus may develop immunosuppression in the form of persistent neutrophil dysfunction. The potential effect of this cellular dysfunction is the possible susceptibility of the host to the same opportunistic pathogens which are responsible for the increased mortality noted in chronic FeLV infections. These data demonstrate that persistent retroviremia is not essential for the establishment of immunosuppression. This overview presents data accumulated from the feline model of the human acquired immunodeficiency syndrome (AIDS) and discusses its relationship to human retroviral infections.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(89)90128-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2549691", "author": "Mullins JI", "n_authors": 6, "title": "FeLV-FAIDS-induced immunodeficiency syndrome in cats.", "abstract": "Findings are reviewed, relevant to elucidation of the pathogenic, genetic and biochemical properties of a single, genetically heterogeneous isolate of feline leukemia virus (FeLV-FAIDS) shown to induce fatal immunodeficiency disease in nearly 100% of inoculated cats. Hypotheses are suggested which pertain to the mechanism of T-cell killing by this virus, and which extrapolate findings in the FeLV-FAIDS animal model to AIDS induced in humans by human immunodeficiency virus (HIV).", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(89)90127-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2549690", "author": "Pedersen NC", "n_authors": 4, "title": "Feline immunodeficiency virus infection.", "abstract": "Feline immunodeficiency virus (FIV) (formerly feline T-lymphotropic lentivirus or FTLV) was first isolated from a group of cats in Petaluma, California in 1986. The virus is a typical lentivirus in gross and structural morphology. It replicates preferentially but not exclusively in feline T-lymphoblastoid cells, where it causes a characteristic cytopathic effect. The major structural proteins are 10, 17 (small gag), 28 (major core), 31 (endonuclease?), 41 (transmembrane?), 52 (core precursor polyprotein), 54/62 (reverse transcriptase?), and 110/130 (major envelope) kilodaltons in size. The various proteins are antigenically distinguishable from those of other lentiviruses, although serum from EIAV-infected horses will cross-react with some FIV antigens. Kittens experimentally infected with FIV manifest a transient (several days to 2 weeks) fever and neutropenia beginning 4 to 8 weeks after inoculation. This is associated with a generalized lymphadenopathy that persists for up to 9 months. Most cats recover from this initial phase of the disease and become lifelong carriers of the virus. Complete recovery does not occur to any extent in nature or in the laboratory setting. One experimentally infected cat died from a myeloproliferative disorder several months after infection. The terminal AIDS-like phase of the illness has been seen mainly in naturally infected cats. It appears a year or more following the initial infection in an unknown proportion of infected animals. FIV has been identified in cats from all parts of the world. It is most prevalent in high density populations of free roaming cats (feral and pet), and is very uncommon in closed purebred catteries. Male cats are twice as likely to become infected as females. Older male cats adopted as feral or stray animals are at the highest risk of infection, therefore. The infection rate among freely roaming cats rises throughout life, and reaches levels ranging from less than 1% to 12% or more depending on the area. Clinically affected cats tend to be 5 years or older at the time of hospitalization. Experimental and seroepidemiologic studies suggest that FIV is transmitted mainly by bites. Intimate, non-traumatic contact (mutual grooming, shared use of food, water and litter pans) is inefficient in transmitting the infection. In utero and venereal transmission could not be demonstrated in laboratory settings. There is no statistical linkage between FIV and feline leukemia virus (FeLV) infections in nature. The FeLV infection rate in FIV-infected animals is the same as it is for non-FIV-infected cats.(ABSTRACT TRUNCATED AT 400 WORDS)", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(89)90134-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2539525", "author": "Kumar DV", "n_authors": 3, "title": "Nucleotide sequence and distinctive characteristics of the env gene of endogenous feline leukemia provirus.", "abstract": "Nucleotide sequence analysis of the env gene of two different endogenous feline leukemia virus (FeLV) loci, CFE-6 and CFE-16, of domestic cats revealed the following characteristics. (i) Both proviruses contain an open reading frame in the env region; (ii) whereas the full complement of the exogenous FeLV env is generally present in CFE-6 DNA, it is truncated in CFE-16 DNA such that the 5' half of the gp70 domain and the untranslated region 3' to the p15E domain have been fused by an internal deletion, resulting in loss of the C-terminal half of the gp70- and all of the p15E-coding sequences; (iii) endogenous env is highly homologous to large sequence domains conserved in all three exogenous FeLV subgroups (A, B, and C) but is similar to FeLV-B sequence domains in the variable regions detected in these viruses; and (iv) there are four other sequence domains, one residing at the C terminus of gp70 and three scattered in p15E, which are unique for the endogenous env, thereby distinguishing it from the FeLV-B gene.", "journal": "Journal of virology", "doi": "10.1128/JVI.63.5.2379-2384.1989", "deposited_data": "Sim", "nuccore_ids": "163851, 163849", "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2539507", "author": "Doggett DL", "n_authors": 6, "title": "Structure, origin, and transforming activity of feline leukemia virus-myc recombinant provirus FTT.", "abstract": "A myc-containing recombinant feline leukemia provirus, designated FTT, was molecularly cloned from the cat T-cell lymphoma line F422. Its transforming activity, as well as the nucleotide sequence of the 3' 2.7 kilobases of FTT, including v-myc, was determined. The predicted v-myc protein differs from feline c-myc by three amino acid changes and is truncated by two amino acids at the carboxyl terminus. Comparison with feline leukemia virus (FeLV), feline c-myc, and other FeLV proviruses indicates that recombination junctions involved in the generation of FeLV-onc viruses occur at preferred locations within the virus. They usually follow or occur within the sequence ACCCC at 5' junctions and may result from homologous recombination between sequences of marked purine-pyrimidine strand bias, especially at 3' junctions. Some recombination sites also resemble recombinase recognition sequences utilized in immunoglobulin and T-cell receptor variable-region joining. Transfection of primary rat embryo fibroblasts and subsequent in vivo analysis revealed that morphologic and tumorigenic transformation require cotransfection of FTT with human EJ-ras DNA; neither gene alone is sufficient. FTT v-myc is expressed in these transformed rat cells as a 3.0-kilobase subgenomic RNA; however, in contrast to the depressed level of c-myc expression in v-myc-involved feline tumors, steady-state levels of rat c-myc RNA and protein are apparently unaltered.", "journal": "Journal of virology", "doi": "10.1128/JVI.63.5.2108-2117.1989", "deposited_data": "Sim", "nuccore_ids": "2884342622, 163856, 2884342622, 2131073108, 2131073107", "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2538760", "author": "Aziz DC", "n_authors": 3, "title": "Severe immunodeficiency disease induced by a defective murine leukaemia virus.", "abstract": "Different classes of retroviruses have been shown to induce immunodeficiency diseases in various animal species. These animal models may provide an insight into our understanding of AIDS but, with the exception of one strain of feline leukaemia virus, the determinants of pathogenicity have not yet been mapped to these viral genomes. The immunodeficiency-inducing feline leukaemia virus is replication-defective, harbouring the determinant of pathogenicity within its env sequences. We have studied the Duplan strain of murine leukaemia virus which induces, in C57BL/6 mice, a severe immunodeficiency disease with striking similarities to human AIDS. We have identified the aetiological agent of this murine immunodeficiency disease as another defective retrovirus, with a genome of 4.8 kilobases. Molecular cloning and sequencing of this DNA showed that the pol and env genes have been deleted, but that the complete gag region has been conserved and has a novel sequence encoding the p12 protein. As with the feline leukaemia virus, these results provide evidence for the role of defective retroviruses in inducing immunodeficiency and facilitate the study of the mechanisms underlying the pathogenesis of retrovirus-induced immunodeficiency syndromes, including AIDS.", "journal": "Nature", "doi": "10.1038/338505a0", "deposited_data": "Sim", "nuccore_ids": "61652", "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2750272", "author": "Akerblom L", "n_authors": 5, "title": "Formation and characterization of FeLV ISCOMs.", "abstract": "Immunostimulating complexes (ISCOMs) have been prepared from feline leukaemia virus (FeLV) envelope proteins. The ISCOMs were characterized biochemically in SDS-polyacrylamide gel electrophoresis showing the presence of proteins of estimated molecular weights of 15,000, 27,000 and 70,000. Immunoblotting showed that both the transmembrane protein p15E and the external glycoprotein gp70 (making up the gp85 protein) were present in the ISCOM. Furthermore, a degradation product of gp70 with an estimated molecular weight of 32,000 was identified in the immunoblot. The FeLV ISCOM was shown by electron microscopy to have the characteristic cage-like structure of an ISCOM with a mean diameter of 37 nm. About 10% of the total amount of gp70 in the culture fluid was recovered in the ISCOMs. The largest loss was encountered during the sedimentation of the virus. In a preliminary immunization experiment in mice the FeLV ISCOMs elicited after a booster gave a clear-cut immune response against gp70.", "journal": "Vaccine", "doi": "10.1016/0264-410x(89)90054-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2750271", "author": "Osterhaus A", "n_authors": 7, "title": "Serological responses in cats vaccinated with FeLV ISCOM and an inactivated FeLV vaccine.", "abstract": "Various approaches have been considered for generation of effective and safe vaccines against retroviruses, including HIV, with limited success. In the present vaccination study, encompassing 137 household cats, we have composed an experimental ISCOM subunit vaccine containing gp70 of feline leukaemia virus (FeLV)--the external glycosylated envelope protein, and the transmembrane protein p15E, with a commercial available inactivated FeLV vaccine (Leukocell). The two vaccines were estimated to contain approximately the same amount of gp70 antigen and the cats were immunized three times according to the recommendations of the commercial vaccine. A control preparation not containing gp70 or p15E was also included. During the observation period of 200 days all cats remained healthy and no virus was isolated during the isolation attempts. The serological responses were measured in ELISA, membrane immunofluorescence (MIF) and virus neutralization (VN) tests. In contrast to the cats in the other groups almost all ISCOM-vaccinated cats responded by seroconversion or increased titres in the three tests. The development of specific antibodies to gp70 and p15E were confirmed in Western blot. These results clearly illustrate the potential of the ISCOM structure for the development of safe and effective vaccines against retroviruses.", "journal": "Vaccine", "doi": "10.1016/0264-410x(89)90053-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2547820", "author": "Hammar L", "n_authors": 4, "title": "Concentration and purification of feline leukaemia virus (FeLV) and its outer envelope protein gp70 by aqueous two-phase systems.", "abstract": "The major protective antigens of retroviruses are considered to be their glycosylated envelope proteins. However, the methods commonly employed to enrich and purify virus from culture media such as pelleting and density-gradient centrifugation result in a low recovery of the viral external glycoproteins. This is an obvious drawback when the virus is intended for use in a vaccine. In search for alternative methods to concentrate and purify FeLV, we have attempted extraction in two-phase systems based on water-soluble polymers (Albertsson PA., Biochem Biophys Acta 1958; 27: 378-395). A variety of polymer systems was tested. Some of them seem attractive for a large-scale concentration of the virus and/or its glycoprotein. The distribution between the phases of two FeLV proteins, the outer envelope protein, gp70, and the gag protein, p27, was determined. With a system composed of dextran sulfate and polyvinyl alcohol both the glycoprotein and the gag protein were almost completely recovered in the lower phase which constitutes about 3% of the total system in weight. The two proteins were more than 40-fold purified as calculated on protein basis. The proteins can be extracted readily.", "journal": "Journal of virological methods", "doi": "10.1016/0166-0934(89)90011-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2544137", "author": "Zeidner NS", "n_authors": 6, "title": "Treatment of FeLV-induced immunodeficiency syndrome (FeLV-FAIDS) with controlled release capsular implantation of 2',3'-dideoxycytidine.", "abstract": "2',3'-dideoxycytidine (ddC) inhibits replication of the immunodeficiency inducing strain of feline leukemia virus (FeLV-FAIDS) in vitro at concentrations ranging from 1-10 micrograms/ml. Additive antiviral effect is achieved when ddC is combined with either human recombinant alpha interferon (IFN alpha) or tumor necrosis factor (TNF) plus IFN alpha. Initial in vivo pharmacokinetic studies in cats, utilizing bolus intravenous administration of ddC (20 mg/kg), resulted in peak plasma concentrations of 15 micrograms/ml 1 min after administration and a half-life of approximately 1 h. These values could not be augmented with high levels of the deaminase blocker tetrahydrouridine administered prior to or concurrently with ddC. In vivo trials utilizing multiple, daily intravenous injections of ddC could not prevent the development of persistent viremia in cats infected with FeLV-FAIDS. To enhance ddC pharmacokinetics and antiviral activity, controlled release capsular implants were developed by blending ddC with a copolymer consisting of DL-lactide glycolide and hydroxypropyl cellulose, which was melt-spun into fibers and encapsulated in a sheath of polyethylene glycol for subcutaneous implantation. Pharmacokinetic studies, conducted in cats receiving an average dose of 600 mg of ddC, indicated an average peak plasma concentration of 17 micrograms/ml achieved at 6 h post implantation with 3.5 micrograms/ml noted at 48 h; and an extension of plasma half-life from 1.5 (bolus subcutaneous injection) to 20 h. sustained plasma concentrations of 1.5 to 10 micrograms/ml, equivalent to ddC levels previously shown to have anti-FeLV activity in vitro, were maintained throughout a 72 h period. Implantation devices could be replenished every 48 h and elevated plasma levels were sustained for four weeks without signs of clinical toxicity, sepsis or significant alterations in the hemogram. Initial clinical trials employing controlled release capsular ddC implants in vivo indicate significant retardation of FeLV-FAIDS replication throughout a four week treatment period.", "journal": "Antiviral research", "doi": "10.1016/0166-3542(89)90026-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2543084", "author": "Snyder HW Jr", "n_authors": 3, "title": "Remission of FeLV-associated lymphosarcoma and persistent viral infection after extracorporeal immunoadsorption of plasma using staphylococcal protein A columns: details of immune response.", "abstract": "Sixteen feline leukemia virus (FeLV)-infected cats with lymphosarcoma (LSA) were treated by extracorporeal immunoadsorption using staphylococcal protein A columns in order to remove immunoglobulin G (IgG) and circulating immune complexes (CIC) from plasma. Complete viral clearance and long-lasting tumor regression were achieved in nine of the cats and tumor regression without virus clearance was observed in two other cats. Since LSA cats rarely go into spontaneous remission, and since other forms of therapy are ineffective, these cats offered a unique system for analyzing details of the immune response to LSA and FeLV as they are cleared. Immunological parameters associated with the FeLV and LSA responses were assessed in detail in three responder cats and three nonresponders during the treatment and follow-up periods. Two serological parameters that always correlated with complete clearance of LSA were development of precipitating antibodies against FeLV-C gp70 and development of cytotoxic antibodies that kill cultured FL74 LSA cells in the presence of complement. The precipitating antibodies were detected prior to the clearance of LSA and prior to the detection of free cytotoxic antibodies. One serological parameter that always correlated with complete clearance of. FeLV was development of free antibodies to FeLV-AB gp70. Quantitative levels of FeLV-specific CIC and feline oncornavirus-associated cell membrane antigen (FOCMA)-specific CIC correlated well with fluctuating levels of the corresponding antigens and antibodies. These results suggest that the staphylococcal protein A treatment columns remove CIC \"blocking factors\" directly or indirectly and thereby stimulate existing antibody responses. These antibodies mediate clearance of FeLV and LSA.", "journal": "Seminars in hematology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2541738", "author": "Zelikman I", "n_authors": 4, "title": "Free gp70 from FeLV: enrichment from cell culture fluid by ferric oxide-agarose chromatography.", "abstract": "A new chromatographic material based on beads of macroporous crosslinked agarose containing ferric oxide particles was used for enrichment of gp70--the envelope glycoprotein of feline leukemia virus (FeLV). Free gp70 was purified from cell culture fluid in one step with a recovery of 50 to 60% and a purification of about 60 times. The described procedure is a suitable first step for the purification of gp70 from large volumes of cell culture fluid.", "journal": "Biotechnology and applied biochemistry", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2541529", "author": "Knowles JO", "n_authors": 5, "title": "Prevalence of feline calicivirus, feline leukaemia virus and antibodies to FIV in cats with chronic stomatitis.", "abstract": "The prevalence of feline calicivirus (FCV), feline leukaemia virus (FeLV) and feline immunodeficiency virus (FIV) antibodies were assessed in 78 British and 18 North American household cats with chronic stomatitis and in appropriate controls. In British cats, FCV was significantly (P less than 0.005) more prevalent in both hospital (92 per cent) and general practice (79 per cent) cases compared to their controls (19 per cent in both cases). A similar difference in prevalence of FCV was noted in North American cats where 50 per cent of cases were positive compared to 0 per cent of controls (P less than 0.01). FeLV prevalence was low in all chronic stomatitis populations. A significantly higher prevalence of antibody to FIV was found in British hospital cases (81 per cent) compared with time-matched controls (16 per cent) (P less than 0.001): a similar rate was found in the general practice cases (75 per cent) for which no controls were available. In the North American sample, FIV antibody status was similar in cases (54 per cent positive) and their age, sex and breed matched controls (50 per cent). The possible role of FCV and FIV in the pathogenesis of feline chronic stomatitis is discussed.", "journal": "The Veterinary record", "doi": "10.1136/vr.124.13.336", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2539700", "author": "Miura T", "n_authors": 5, "title": "Molecular cloning of a feline leukemia provirus integrated adjacent to the c-myc gene in a feline T-cell leukemia cell line and the unique structure of its long terminal repeat.", "abstract": "This paper reports the molecular cloning of a rearranged c-myc region from the FT-1 cell line, which was derived from a spontaneous feline T-cell leukemia carrying the feline leukemia virus (FeLV). An abnormal c-myc EcoRI fragment of about 18 kilobases, detected by Southern blotting, was molecularly cloned from the DNA of the FT-1 cell line. The c-myc rearrangement in FT-1 was due to direct integration of the FeLV provirus genome immediately upstream of the c-myc gene in the opposite transcriptional orientation. Nucleotide sequencing showed that the LTR of this provirus had three copies of an enhancer-like sequence, unlike the sequences of FeLVs reported previously, which have only a single copy of this enhancer-like sequence.", "journal": "Virology", "doi": "10.1016/0042-6822(89)90172-4", "deposited_data": "Sim", "nuccore_ids": "407725321, 323909", "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2925488", "author": "Mooney SC", "n_authors": 6, "title": "Treatment and prognostic factors in lymphoma in cats: 103 cases (1977-1981).", "abstract": "The records of 103 cats with lymphoma that underwent chemotherapy were reviewed. Diagnosis was confirmed by cytologic or histopathologic examination of appropriate tissue specimens. Sixty-four cats (62%) had a complete response to chemotherapy (median survival time, 7 months); 21 cats (20%) had a partial response (median survival time, 2.5 months); and 18 cats had a minimal response (median survival time, 1.5 months). Seventy-seven cats (75%) died of recurrent or progressive lymphoma, 9 cats died of feline leukemia-related anemia, 13 cats died of unrelated causes, and 4 cats were alive. Stage of disease was significantly (P = 0.009) related to response to treatment, and stage of disease and FeLV status were both significantly (P = 0.002 and P less than 0.001, respectively) related to survival.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2539576", "author": "Kappes B", "n_authors": 6, "title": "The TP1 isolate of feline sarcoma virus encodes a fgr-related oncogene lacking gamma actin sequences.", "abstract": "We have isolated a new feline sarcoma virus, TP1-FeSV. The virus encodes a myristilated 83 kD gag-onc fusion protein displaying tyrosine kinase activity. We have established nonproducer cell lines lacking the TP1-FeSV associated helper virus (FeLV) and TP1-FeSV transfected NIH cell lines. Southern Blot analysis of genomic DNA and Northern Blot analysis of RNA isolated from these cell lines revealed that the oncogene of the TP1-FeSV isolate is related to the fgr oncogene of the GR-FeSV, but shows no hybridization to the gamma actin homologous sequences of the GR-FeSV. We have isolated TP1-FeSV specific clones from a genomic library. Restriction enzyme and sequence analysis showed that the TP1-FeSV genome consists of the first 1651 nucleotides of the gag gene, followed directly by fgr sequences. The TP1-FeSV fgr sequence starts 43 nucleotides after the beginning of the GR-FeSV fgr sequence. In contrast to the GR-FeSV fgr which has lost 13 amino acids of the c-fgr carboxy terminus, the TP1-FeSV fgr contains the complete carboxy terminus of the cellular fgr gene. The TP1-FeSV fgr sequence is followed by a unique 328 nucleotide long sequence of unknown origin. The 3' recombination site occurs within the pol gene, 460 nucleotides from the start of the env leader sequence. Comparison of the subcellular localization of the transforming proteins of TP1-FeSV and GR-FeSV show no striking difference; both molecules are in part associated with subcellular membrane/cytoskeletal fractions and form complexes with the cellular pp90 and pp50.", "journal": "Oncogene", "doi": null, "deposited_data": "Sim", "nuccore_ids": "1089", "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2540425", "author": "Flanagan JR", "n_authors": 4, "title": "Negative control region at the 5' end of murine leukemia virus long terminal repeats.", "abstract": "Using in vitro protein binding and in vivo functional studies, we have identified novel regulatory sequences near the 5' end of murine leukemia virus (MuLV) long terminal repeats (LTRs). These sequences are highly conserved in all MuLV LTRs as well as in feline leukemia virus and gibbon ape leukemia virus LTRs. In this upstream conserved region (UCR), gel retardation assays detected two overlapping but distinct binding sites (UCR-U and UCR-L) for nuclear proteins (UCRF-U and UCRF-L). Three lines of evidence suggest a negative regulatory role for the UCR in viral transcription: (i) an inverse correlation was found between MuLV transcripts and nuclear proteins binding the UCR in the spleens of five different mouse strains; (ii) in vivo treatment of NFS mice with lipopolysaccharide resulted in the induction of splenic viral transcripts and the concomitant disappearance of UCR-binding proteins; and (iii) in mouse L cells transfected with an MuLV LTR linked to the chloramphenicol acetyltransferase (CAT) gene, cotransfected UCR oligonucleotides increased CAT expression, presumably by competing for inhibitory trans-acting factors.", "journal": "Molecular and cellular biology", "doi": "10.1128/mcb.9.2.739-746.1989", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2537886", "author": "Tompkins MB", "n_authors": 6, "title": "Interleukin-2 suppression in cats naturally infected with feline leukemia virus.", "abstract": "Feline peripheral blood lymphocytes (PBLs) produce interleukin-2 (IL-2) when stimulated with concanavalin A (Con A) or the combination of the Ca2+ ionophore A23187 (A2) plus the phorbol ester phorbol-12-myristate-13-acetate (PMA). To determine the status of T helper cell function in cats naturally infected with feline leukemia virus (FeLV), PBLs from 19 normal cats and 49 FeLV-infected (34 asymptomatic and 15 symptomatic) cats were tested for their ability to produce IL-2 in response to Con A or A2/PMA stimulation. In the case of Con A stimulation, 21, 41, and 67% of normal, FeLV-infected asymptomatic, and FeLV-infected symptomatic cats, respectively, failed to produce detectable levels of IL-2. In contrast, A2/PMA stimulation yielded high titers of IL-2 in 100% of the normal cats, 92% of asymptomatic cats, but only 44% of clinically ill cats. All of the A2/PMA nonresponders in the FeLV-infected symptomatic population were also unresponsive to Con A. T Helper immunosuppression was observed in cats with FeLV-induced lymphoproliferative diseases as well as cats with FeLV-associated acquired immune deficiency syndrome-like diseases. These data suggest that TH immunosuppression in naturally infected viremic cats may precede development of clinical disease. Moreover, the ability to restore TH function with A2/PMA is diminished with development of clinical disease.", "journal": "Journal of biological response modifiers", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2537113", "author": "Quackenbush SL", "n_authors": 3, "title": "Colony forming T lymphocyte deficit in the development of feline retrovirus induced immunodeficiency syndrome.", "abstract": "The identification and molecular cloning of a feline leukemia virus (FeLV) isolate (FeLV-FAIDS) that consistently produces immunodeficiency syndrome has allowed prospective investigation of events that occur in the prodromal phase of disease. Using a T-lymphocyte colony forming assay (T-CFU-Ic) we have demonstrated that a drastic depletion of circulating T-CFU-Ic prefigures the development of clinical immunodeficiency disease in inoculated cats and correlates with the appearance and replication of the FeLV-FAIDS variant genome in serially collected bone marrow samples. During the same presymptomatic time period, no significant alterations in conventional mitogen-induced lymphocyte blastogenic responses or in circulating lymphocyte numbers were evident. Thus T-CFU-Ic assay but not conventional mitogen-driven blastogenesis identified animals destined to develop immunodeficiency syndrome. The correlation among T-CFU-Ic depletion, the replication of the lymphocytopathic FeLV-FAIDS variant genome in hematopoietic and lymphoid tissues, and the onset of clinical disease, infers that ablation of a colony-forming T lymphocyte progenitor subset is important in the early pathogenesis of feline retrovirus-induced immunodeficiency syndrome.", "journal": "Blood", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2536328", "author": "Dornsife RE", "n_authors": 4, "title": "In vitro erythrocytopathic activity of an aplastic anemia-inducing feline retrovirus.", "abstract": "Although feline leukemia viruses (FeLV) cause a spectrum of proliferative and anti-proliferative diseases in vivo, in vitro studies demonstrating cell lineage-specific pathogenic properties of feline retroviruses have been rare. We describe here an efficient in vitro system that demonstrates the selective cytopathic effect of a molecularly cloned anemogenic FeLV (FeLV-Sarma-subgroup C; FSC) on erythroid progenitor cells. Forty-eight-hour coculture of normal feline bone marrow mononuclear cells with an underlayer of FSC-infected feline fibroblasts (FeF) resulted in infection of 60% to 90% of marrow mononuclear cells and pronounced depletion of early erythroid progenitor cells (BFUe). The dramatic depletion of BFUe was specific for FSC and did not occur in marrow cells infected with a molecularly cloned nonanemogenic subgroup A FeLV (FeLV 1161E; F6A). The ablation of BFUe by FSC in vitro paralleled both the decrease in BFUe and the induction of aplastic anemia in vivo. This combination of marrow cell infection by coculture and colony-forming unit (CFU) assessment by methylcellulose assay provides a reliable in vitro technique for studies of mechanisms involved in retrovirus-induced marrow aplasias.", "journal": "Experimental hematology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2537276", "author": "Chalmers S", "n_authors": 3, "title": "Demodicosis in two cats seropositive for feline immunodeficiency virus.", "abstract": "Two cats were diagnosed with generalized demodicosis. Serotest results were negative for FeLV and positive for feline immunodeficiency virus. In one cat, demodicosis resolved in response to topical application of lime-sulfur solution, but the other cat was euthanatized.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2537274", "author": "Shelton GH", "n_authors": 6, "title": "Feline leukemia virus and feline immunodeficiency virus infections in a cat with lymphoma.", "abstract": "Lymphoma was diagnosed in a 7-year-old domestic cat found to be infected with FeLV and feline immunodeficiency virus (FIV). The cat was affected by chronic disorders suggestive of immunosuppression, including gingivitis, periodontitis, keratitis, and abscesses. Despite treatment, peripheral keratitis of the left eye progressed, resulting in uveitis, chronic glaucoma, and eventual corneal rupture. Microscopic retinal and optic disk pathologic processes also were suspected. Abnormal jaw movements that were believed to be indicative of neurologic disease were observed. Approximately 17 months later, the cat developed generalized lymphadenopathy, hepatosplenomegaly, and bilateral renomegaly. Lymphoblastic lymphoma and glomerulonephritis were diagnosed histologically. Manganese- and magnesium-dependent reverse transcriptase activity were detected in supernatants from lymph node and spleen mononuclear cell cultures, suggesting T-lymphocyte infection with FeLV and FIV.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2537273", "author": "Hoover JP", "n_authors": 3, "title": "Serologic response of domestic ferrets (Mustela putorius furo) to canine distemper and rabies virus vaccines.", "abstract": "Nine unrelated 12-week-old naive domestic ferrets (Mustela putorius furo) were used to evaluate the serologic responses to commercial canine distemper virus (CDV) and rabies virus (RV) vaccines. Five of the ferrets (group 1) were inoculated 3 times at 2-week intervals with a multivalent modified-live virus vaccine of canine cell-line origin, containing CDV and an inactivated RV vaccine. Four of the ferrets (group 2) were inoculated once with the multivalent modified-live virus vaccine containing CDV and were not inoculated with the RV vaccine. Both group-1 and group-2 ferrets seroconverted to the CDV component of the vaccine. Group-1 ferrets also seroconverted after RV vaccination and maintained serum antibody titers to both CDV and RV for at least 7 months. Domestic ferret sera were found to have IgG epitopes similar to sera of domestic dogs and cats. Domestic ferret sera did not contain antibodies to feline coronavirus or FeLV antigens.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2537272", "author": "Witt CJ", "n_authors": 5, "title": "Epidemiologic observations on feline immunodeficiency virus and Toxoplasma gondii coinfection in cats in Baltimore, Md.", "abstract": "Five hundred eighty-five serum samples obtained between 1980 and 1981 from a diverse population of cats were tested by use of an indirect immunoperoxidase assay for antibodies to feline immunodeficiency virus (FIV). Results of 14 of the samples were positive (prevalence, 2.4%). The FIV-positive cats were markedly older than the overall population and frequently were coinfected (57%) with Toxoplasma gondii. The Toxoplasma titers of the FIV-positive cats were significantly (P less than 0.03) higher than those of the FIV-negative cats. The FIV-positive cats were not coinfected with FeLV. Our findings suggested that FIV-associated immunosuppression may be a factor in active Toxoplasma infection in adult cats.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2537271", "author": "Grindem CB", "n_authors": 4, "title": "Seroepidemiologic survey of feline immunodeficiency virus infection in cats of Wake County, North Carolina.", "abstract": "Feline immunodeficiency virus (FIV) antibodies were detected in 9 of 123 (7.3%) cats. More clinically ill cats had titers to FIV than did healthy cats (15% vs 3.6%). Previous or current illnesses in these FIV-positive cats included urinary bladder disease, anemia, cat-bite abscesses, bacterial infections, bleeding disorders, diabetes mellitus, and chronic respiratory tract disease. All FIV-positive cats were males, with mean age of 6.0 years (range, 1 to 11 years). Half (n = 3) of the clinically ill FIV-positive cats were concurrently seropositive for FeLV antigen. Three of the ill cats were euthanatized or died 1 month after initially testing, whereas the remaining 3 ill cats and the 3 healthy FIV-positive cats were healthy 1 year after initial testing. Antibody titer to FIV persisted in 4 of 5 cats, but serotest results were equivocal in 1 cat evaluated 1 year later.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2537270", "author": "Ishida T", "n_authors": 6, "title": "Feline immunodeficiency virus infection in cats of Japan.", "abstract": "A seroepidemiologic survey for feline immunodeficiency virus (FIV) infection was conducted in Japan. Between June and December 1987, individual sera (n = 3,323) were submitted by veterinary practitioners from many parts of the country. Specimens were from 1,739 cats with clinical signs suggestive of FIV infection and from 1,584 healthy-appearing cats seen by the same practitioners. The overall FIV infection rate among cats in Japan was 960/3,323 cats (28.9%). The infection rate was more than 3 times higher in the clinically ill cats, compared with that in the healthy cats of the same cohort (43.9 vs 12.4%). Male cats were 1.5 times as likely to be infected as were females. Almost all FIV-infected cats were domestic cats (as opposed to purebred cats). Complete clinical history was available for 700 of 960 FIV-infected cats. Of these 700 FIV-infected cats, 626 (89.4%) were clinically ill, and the remainder did not have clinical signs of disease. The mean age at the time of FIV diagnosis for the 700 cats was 5.2 years, with younger mean age for males (4.9 years) than for females (5.8 years). Most of the infected cats (94.7%) were either allowed to run outdoors or had lived outdoors before being brought into homes. The mortality for FIV-infected cats during the 6 months after diagnosis was 14.7%, and the mean age at the time of death was 5.7 years. Concurrent FeLV infection was seen in 12.4% of the FIV-infected cats, but this was not much different from the historical incidence of FeLV infection in similar groups of cats not infected with FIV.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2537269", "author": "Yamamoto JK", "n_authors": 8, "title": "Epidemiologic and clinical aspects of feline immunodeficiency virus infection in cats from the continental United States and Canada and possible mode of transmission.", "abstract": "The epidemiologic features of feline immunodeficiency virus (FIV) infection were evaluated in 2,765 cats from the United States and Canada. Of these cats, 2,254 were considered by veterinarians to be at high risk for the infection, and 511 were healthy cats considered to be at low or unknown risk. Of the cats in the high-risk group, 318 (14%) were found to be infected with FIV. The infection rate among low- or unknown-risk cats was 6 of 511 (1.2%). Male cats in the high-risk group were 3 times more likely to be infected than were females, similarly as were cats greater than 6 years old, compared with younger cats; domestic cats, compared with purebred cats; and free-roaming cats, compared with confined cats. Feline immunodeficiency virus and FeLV infections did not appear to be linked with each other; 16% of FeLV-infected cats in the high- and low-risk groups were coinfected with FIV. In contrast, there was a pronounced linkage between FIV and feline syncytium-forming virus (FeSFV) infections. Seventy-four percent of FeSFV-infected cats in the high-risk study group were coinfected with FIV, compared with a 38% FIV infection rate among cats that were not infected with FeSFV. The major clinical manifestations associated with FIV infection in cats that were surveyed included chronic oral cavity infections (56%), chronic upper respiratory tract disease (34%), chronic enteritis (19%), and chronic conjunctivitis (11%). Bacterial infections of the urinary tract (cystitis), skin, and ears were seen in a small proportion of cats.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2535958", "author": "Rojko JL", "n_authors": 7, "title": "Feline lymphomas: immunological and cytochemical characterization.", "abstract": "The immunological and cytochemical phenotypes of five primary feline lymphomas and six feline lymphoma lines are reported. Thymic lymphomas induced by the Rickard strain of FeLV (FeLV-R) are of prothymocyte or (immature) cortical thymocyte origin, as these express terminal deoxynucleotidyl transferase, the guinea pig erythrocyte rosette receptor, Ia antigens, partial cortisone sensitivity, and nonspecific esterase. Lymphomas associated with other strains of FeLV form rosettes with guinea pig erythrocytes, frequently have Ia antigens and cytoplasmic nonspecific esterase, and probably originate from helper T-cells, monocyte/macrophages, or null cells. These data belie previous conclusions that FeLV leukemogenesis is restricted to mature T-cells; rather, the considerable heterogeneity in the surface and cytochemical phenotype of feline lymphomas probably reflects transformation of multipotent lymphoid or monocytoid precursors in the bone marrow by FeLV.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2684547", "author": "Kabat D", "n_authors": 1, "title": "Molecular biology of Friend viral erythroleukemia.", "abstract": "Friend virus clearly provides an important model for understanding the molecular biology of cancer. Moreover, the most important aspects of the erythroleukemia can be caused by a single SFFV infection in the absence of any helper virus. The SFFV env gene encodes a membrane glycoprotein, gp55. This glycoprotein, when expressed on erythroblast surfaces, causes a constitutive mitogenesis. However, SFFV infections only rarely increase the cell's self-renewal capability or abrogate its commitment to differentiate. Therefore, the consequence of infection is initially a polyclonal erythroblastosis. This polyclonal proliferation usually leads to cell differentiation and to recovery unless helper virus is present to cause continuing infection of new erythroblasts. Extremely rare SFFV proviral integrations, however, result in abrogation of the cell's commitment to differentiate and in the concomitant acquisition of cell immortality. These immortalizing proviral integrations occur at only a small number of sites in the mouse genome. Therefore, the mitogenic and immortalizing stages of erythroleukemia are now known to be caused by discrete genetic events--the first involving the SFFV env gene and the second involving the rare proviral integration sites. In early investigations of Friend virus, the first stage always preceded the second stage by at least several weeks. Now it is known that this delay in onset of the second stage is caused solely by statistics. Every SFFV-infected erythroblast is mitogenically activated, yet only rarely does the SFFV proviral integration produce immortality. Both steps in leukemogenesis can be caused simultaneously in an erythroblast by a rare single SFFV proviral integration. There has been an explosion of interest in retroviral env gene-mediated pathogenesis. Such pathogenesis has been recently associated with most of the naturally transmitted retroviral diseases including AIDS. Such pathogenesis involves in different viruses immunosuppression, anemia, neuropathy, and leukemia (Mathes et al. 1978; Simon et al. 1984, 1987; Weiss et al. 1985; Lifson et al. 1986; Riedel et al. 1986; Sitbon et al. 1986; Sodroski et al. 1986; Mitani et al. 1987; Schmidt et al. 1987; Klase et al. 1988; Overbaugh et al. 1988a, b). The shuffling and dynamic env gene rearrangements that have been associated with murine retroviral leukemogenesis have also now been seen in FeLV-FAIDS and HIV (Fisher et al. 1988; Overbaugh et al. 1 t88b; Saag et al. 1988; Tersmette et al. 1988). Friend virus provides an important established example of such env gene pathogenesis. Although we still do not understand precisely how gp55 causes erythroblast mitosis, workers in this field have discovered important clues that may lead to answers.(ABSTRACT TRUNCATED AT 400 WORDS)", "journal": "Current topics in microbiology and immunology", "doi": "10.1007/978-3-642-74700-7_1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2560447", "author": "Tzavaras T", "n_authors": 4, "title": "Isolation and characterisation of a myeloid leukaemia inducing strain of feline leukaemia virus.", "abstract": null, "journal": "Haematology and blood transfusion", "doi": "10.1007/978-3-642-74621-5_60", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2552228", "author": "Dornsife RE", "n_authors": 4, "title": "Induction of aplastic anemia by intra-bone marrow inoculation of a molecularly cloned feline retrovirus.", "abstract": "Intra-bone marrow inoculation of cells infected with molecularly cloned feline retrovirus (FeLV-C-Sarma [FSC]) associated with aplastic anemia was examined to test the hypothesis that cell-to-cell transmission of virus might facilitate marrow cell infection and anemogenesis, a possibility suggested by in-vitro co-culture experiments. IBM inoculation of either FSC-infected feline marrow cells or fibroblasts of weanling cats bypassed age-related restriction of FSC replication, initiated viremia, caused irreversible depletion of erythroid burst forming units, and induced rapid fatal aplastic anemia. A second significant finding observed with FSC infection was pronounced systemic lymphoid depletion. The direct bone marrow inoculation system described facilitates experimental study of retrovirus-target cell interactions involved in erythroid aplasia.", "journal": "Leukemia research", "doi": "10.1016/0145-2126(89)90087-8", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2540111", "author": "Tavares L", "n_authors": 4, "title": "Testing of nucleoside analogues in cats infected with feline leukemia virus: a model.", "abstract": "In the present communication we evaluate the feline leukemia virus (FeLV) infection of cats as a model for antiretroviral chemotherapy studies. Additionally, we report the results of testing the antiviral effect of the compounds, 3'-azido-3'-deoxythymidine (AZT), 2',3'-dideoxycytidine, 2',3'-dideoxyinosine and 2',3'-dideoxyadenosine against FeLV replication in vitro. Cumulative data from experiments in which FeLV-infected cats were treated with AZT at different stages of experimental infection are also evaluated.", "journal": "Intervirology", "doi": "10.1159/000150121", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2540109", "author": "Hoover EA", "n_authors": 7, "title": "Feline leukemia virus-induced immunodeficiency syndrome in cats as a model for evaluation of antiretroviral therapy.", "abstract": "Severe progressive immunodeficiency syndrome can be induced experimentally with a molecularly cloned isolate of feline leukemia virus (FeLV-FAIDS). The resultant disease syndrome is characterized by persistent viremia, lymphopenia, progressive weight loss, persistent diarrhea, enteropathy, and opportunistic infections. The onset of clinical immunodeficiency disease is prefigured by the replication of the FeLV-FAIDS variant virus in bone marrow and other tissues. The FeLV-FAIDS system can be used to evaluate antiviral agents which act on steps in the replication cycle which are conserved among retroviruses (e.g. reverse transcriptase, protease, assembly). The persistence and magnitude of viremia serves as a useful parameter in antiviral studies because it can be easily measured, presages the eventual development of immunodeficiency, and provides a convenient indicator of therapeutic efficacy either in preventing de novo FeLV infection or in reversing or ameliorating established infection. We describe here the evaluation of 2',3'-dideoxycytidine (ddC) against FeLV-FAIDS infection - both in vitro in cell culture assay systems and in vivo in cats administered ddC either via intravenous bolus dosage or via controlled release subcutaneous implants. We found that, although controlled release delivery of ddC inhibited de novo FeLV-FAIDS replication and delayed onset of viremia when therapy was discontinued (after 3 weeks), an equivalent incidence and level of viremia were established rapidly in both ddC-treated and control cats. The FeLV model, therefore, can be used to assess rapidly experimental single agent or combined antiviral therapies for persistent retrovirus infection and disease.", "journal": "Intervirology", "doi": "10.1159/000150120", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2535725", "author": "Poss ML", "n_authors": 3, "title": "Posttranslational modifications distinguish the envelope glycoprotein of the immunodeficiency disease-inducing feline leukemia virus retrovirus.", "abstract": "The envelope glycoprotein (gp70) of a molecularly cloned, replication-defective feline leukemia virus (FeLV-FAIDS clone 61C) carries determinants for induction of fatal immunodeficiency disease, whereas the gp70 of its companion replication-competent, probably parent virus (clone 61E) does not. Immunoprecipitation analysis of the extracellular glycoproteins of 61E and EECC, a replication-competent viral construct composed of the 61C env and 3' long terminal repeat fused to the 61E gag-pol genes, demonstrated that the gp70 of EECC could be distinguished from that of 61E by both feline immune serum and a murine monoclonal antibody. Molecular weights of both the envelope precursor polyprotein (gp80) and the mature extracellular glycoprotein (gp70) of 61E were smaller than the corresponding proteins from the pathogenic EECC. Both the molecular weight disparity and monoclonal antibody discrimination of the two gp80s were abolished by inhibition of envelope protein glycosylation with tunicamycin, whereas the apparent gp70 size differences were resolved by enzymatic removal of N-linked oligosaccharides. Pulse-chase studies in EECC-infected cells demonstrated that processing of gp80 to gp70 was delayed and that this retardation of envelope glycoprotein processing could be simulated in 61E-infected cells by treatment with the glucosidase inhibitor N-methyldeoxynojirimycin, a compound that causes retention of oligosaccharides in the high-mannose form. The resultant 61E gp70 then could be recognized by sera from EECC-immunized cats. The presence of a higher content of sialic acid on the apathogenic 61E gp70 indicated that oligosaccharides of 61E and EECC gp70 were processed differently. These data suggested that the unique biochemical properties which distinguish the envelope glycoproteins of the FeLV-FAIDS variant from its companion apathogenic parent virus were responsible for T-cell cytopathicity and induction of immunodeficiency disease. Further biochemical characterization of these glycoproteins should be useful in understanding the pathogenic mechanisms of immunodeficiency disease induced by retroviruses.", "journal": "Journal of virology", "doi": "10.1128/JVI.63.1.189-195.1989", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2482029", "author": "Osterhaus AD", "n_authors": 4, "title": "Induction of anti-viral immune response by immunization with monoclonal anti-idiotype antibodies directed to private idiotopes.", "abstract": "Syngeneic monoclonal anti-idiotypic antibodies were raised against idiotopes on neutralizing monoclonal antibodies with specificity for feline leukemia virus and canine parvovirus. The anti-idiotypic antibodies were shown to recognize paratope-related private idiotopes. Mice were injected with the monoclonal anti-idiotypic antibodies and the sera of these mice were screened for antiviral reactivities. Antibodies to both feline leukemia and canine parvovirus could be induced as determined by ELISA. These results suggest that anti-idiotypic antibodies which detect private idiotopes and thus do not represent internal images of viral antigens may be considered as candidates for the induction of antiviral immunity.", "journal": "Viral immunology", "doi": "10.1089/vim.1989.2.255", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2230598", "author": "Tompkins MB", "n_authors": 7, "title": "Human recombinant interleukin-2 induces maturation and activation signals for feline eosinophils in vivo.", "abstract": "Immunotherapy, with interleukin-2 (IL-2) or IL-2 plus lymphokine-activated killer (LAK) cells, has been used to treat cancer and acquired immunodeficiency syndrome (AIDS) in man. Similarities between feline leukemia virus (FeLV) infection in the cat and human immunodeficiency virus (HIV) infection in man have prompted immunotherapeutic studies in the cat. To develop baseline data on hematological responses to infused IL-2, cats were given daily (1-14 days) i.v. injections of 5 x 10(4) U/kg of recombinant human IL-2 (rHulL-2). Complete blood cell (CBC) counts were done weekly. Red blood cell (RBC), neutrophil, and lymphocyte numbers did not change appreciably over the course of the study. In contrast, rHulL-2 caused an eosinophilia in all but the 1 day treatment group. Treatment for 3 days generated a transient eosinophilia on day 7 that returned to baseline by 3 weeks. Five day and 7 day treatments generated an eosinophilia by day 7 that peaked on day 14 and returned to normal values by day 28. Treatment of cats for 14 days did not increase the magnitude or duration of the eosinophilia beyond the 5 or 7 day treatments. Bone marrow (BM) biopsies from rHulL-2-treated cats revealed a marked selective hyperplasia of eosinophil precursors. In the 5 day treatment group, all maturation stages of eosinophils were elevated by week 1 of treatment. By week 2, the early stages had returned to normal, whereas the late stage cells remained elevated, suggesting an ordered maturation response. Numbers of all eosinophil precursors approximated pretreatment numbers by weeks 3-4. Thus the BM hyperplasia preceded the blood eosinophilia by 1 week, suggesting that an enhanced maturation response of BM eosinophil precursors is a major contributor to the rHulL-2-induced blood eosinophilia. In addition to a maturation signal, rHulL-2 induces a potent activation signal for eosinophils as measured by a decrease in density and an increase in longevity in culture. The significance of the activated eosinophil in the therapeutic or toxicologic response to rHulL-2 infusion is discussed.", "journal": "Journal of leukocyte biology", "doi": "10.1002/jlb.48.6.531", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "1982410", "author": "Novotney C", "n_authors": 8, "title": "Lymphocyte population changes in cats naturally infected with feline immunodeficiency virus.", "abstract": "Feline immunodeficiency virus (FIV) is associated with feline acquired immunodeficiency syndrome (FAIDS) and has been suggested as a model for HIV-induced human AIDS. The most obvious immunological defect in HIV infection is a reduction in CD4+ cell numbers and an inversion of the CD4:CD8 ratio. To determine whether the same is true in FIV infection, we analyzed by flow cytometry using a panel of monoclonal antibodies to feline lymphocyte populations the CD4:CD8 ratios in cats naturally infected with the virus. We report that 13 of 19 FIV-infected cats had ratios below the 5th percentile of normal cats (0.57, established from analysis of 39 normal cats) and 18 of 19 had ratios below 1. Repeated analyses over a period of several months revealed the inverted ratios to be consistent. Analysis of lymphocyte numbers in FIV-infected cats shows that the inverted ratios are due to a decrease in CD4+ T cells, while CD8+ T and B cells remain relatively normal in number. Analysis of a group of cats with a variety of other chronic diseases, including feline leukemia virus (FeLV) infections, revealed a near-normal distribution of CD4:CD8 ratios. These findings are similar to those in HIV infections and indicate that, like HIV, FIV causes a selective reduction in CD4+ cells and should be an excellent model for studying retrovirus-induced AIDS.", "journal": "AIDS (London, England)", "doi": "10.1097/00002030-199012000-00005", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "1965124", "author": "Teng CS", "n_authors": 1, "title": "Induction of feline immunodeficiency syndrome by feline leukemia virus: pituitary and adrenocortical dysfunctions.", "abstract": "Seven young cats were injected with feline leukemia virus (FeLV); six of them became viremic. All of the viremic cats developed AIDS-related symptoms, i.e. lymphopenia, neutropenia, thymic atrophy, and wasting syndrome, along with an altered pituitary and adrenocortical function. These symptoms closely resemble human AIDS induced by HIV. It was discovered that, after 2 weeks of infection, the average amount of plasma adrenocorticotropic hormone (ACTH) detected in the infected cats was reduced by 29% in comparison with that before the infection. In contrast to the second week, the fifth week of infection showed a 94% increase of plasma ACTH which then dropped back down to 38% after the sixth and seventh weeks. This opposing biphasic pattern of change was also observed in the plasma cortisol content of the infected cats. The amount of change in plasma cortisol did not correlate with the detected increase in plasma ACTH, indicating a weak adrenal response to pituitary action.", "journal": "AIDS (London, England)", "doi": "10.1097/00002030-199012000-00006", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "1976822", "author": "Quackenbush SL", "n_authors": 8, "title": "Lymphocyte subset alterations and viral determinants of immunodeficiency disease induction by the feline leukemia virus FeLV-FAIDS.", "abstract": "The FeLV-FAIDS strain of feline leukemia virus consistently induces fatal immunodeficiency. To investigate the immunopathogenesis and viral genetic determinants responsible for the induction of immunodeficiency disease in vivo, we have generated chimeras between the two major viral genomes in the original virus isolate, designated common form clone 61E and major variant clone 61C, which were molecularly cloned directly from DNA of the same animal and tissue. Each of three 61E/C chimeras, containing at minimum a 34-amino-acid segment (including a 6-amino-acid insertion and one amino acid substitution) near the C terminus of the 61C surface glycoprotein (gp70), induced fatal immunodeficiency disease in all (12 of 12) infected animals over a course of 33 +/- 10 weeks. By contrast, animals infected with virus 61E, although persistently antigenemic, remained asymptomatic throughout a 48-week observation period. Beginning 14 weeks after infection, a significant decrease (8 to 10%) in the percent of circulating CD4+ T lymphocytes developed in the 61E/C chimera-infected cats, compared with either 61E-infected or control animals. At this time, no significant changes were seen in CD8 cells, B cells, or mitogen-induced blastogenesis. Prior to this initial decline in CD4 cells, the ability of all antigenemic 61E/C-infected cats to generate a primary antibody response to the T-cell-dependent antigen keyhole limpet hemocyanin was markedly impaired, whereas all 61E-infected cats, one 61E/C-infected but nonviremic cat, and all uninfected control cats produced normal antibody responses. The results reported here demonstrate that a major determinant of in vivo immunodeficiency induction by FeLV-FAIDS is contained within a 34-amino-acid C-terminal segment of its surface glycoprotein and that this gp70 alteration determines the early and persistent deficits in CD4+ T lymphocytes and T-cell-dependent antibody responses. We hypothesize that these early immunologic alterations could result from early deletion of a CD4+ helper T-cell subset.", "journal": "Journal of virology", "doi": "10.1128/JVI.64.11.5465-5474.1990", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "1967004", "author": "Kitchen LW", "n_authors": 4, "title": "Effect of administration of diethylcarbamazine on murine leukemia virus (Cas-Br-M) infected mice.", "abstract": "Previous studies indicate that decreased serum viral infectivity and viral antigen levels follow oral administration of diethylcarbamazine (DEC) in feline leukemia virus infected cats, even though DEC has not been shown to exhibit in vitro antiviral activity. In this investigation, DEC was given by oral administration or (single dose) IP injection to murine leukemia virus (Cas-Br-M) inoculated mice to permit evaluation of its effect on viral-induced central nervous system disease. The survival of Cas-Br-M inoculated mice receiving DEC in water was significantly prolonged relative to similarly inoculated mice receiving distilled water. Among the Cas-Br-M inoculated mice euthanatized after the study, higher body weights and trend toward less severe brain and splenic lesions were noted in those receiving DEC in drinking water. Given these results, the possible utility of DEC in treatment of retroviral and other infections warrants further study.", "journal": "Journal of clinical & laboratory immunology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2168977", "author": "Cole GE", "n_authors": 3, "title": "Recombinant feline herpesviruses expressing feline leukemia virus envelope and gag proteins.", "abstract": "We constructed recombinant feline herpesviruses (FHVs) expressing the envelope (env) and gag genes of feline leukemia virus (FeLV). Expression cassettes, utilizing the human cytomegalovirus immediate-early promoter, were inserted within the thymidine kinase gene of FHV. The FeLV env glycoprotein expressed by recombinant FHV was processed and transported to the cell surface much as in FeLV infection, with the exception that proteolytic processing to yield the mature gp70 and p15E proteins was less efficient in the context of herpesvirus infection. Glycosylation of the env protein was not affected; modification continued in the absence of efficient proteolytic processing to generate terminally glycosylated gp85 and gp70 proteins. A recombinant FHV containing the FeLV gag and protease genes expressed both gag and gag-protease precursor proteins. Functional protease was produced which mediated the proteolytic maturation of the FeLV gag proteins as in authentic FeLV infection. Use of these recombinant FHVs as live-virus vaccines may provide insight as to the role of specific retroviral proteins in protective immunity. The current use of conventional attenuated FHV vaccines speaks to the wider potential of recombinant FHVs for vaccination in cats.", "journal": "Journal of virology", "doi": "10.1128/JVI.64.10.4930-4938.1990", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2400806", "author": "Shelton GH", "n_authors": 4, "title": "Hematologic manifestations of feline immunodeficiency virus infection.", "abstract": "Studies were done on 53 cats with community-acquired infection with the feline immunodeficiency virus (FIV) to determine if hematologic abnormalities were comparable with those observed in patients seropositive for the human immunodeficiency virus (HIV). Nine cats were asymptomatic, 24 had clinical symptoms equivalent to AIDS-related complex (ARC), and 20 had AIDS-like disease. Hematologic abnormalities were detected in 75% (40 of 53) of FIV-seropositive cats, and multiple concurrent cytopenias were common. Anemia, lymphopenia, neutropenia, and thrombocytopenia occurred in 36%, 53%, 34%, and 8% of FIV-seropositive cats, respectively. Cytopenias were seen only in symptomatic (ARC or AIDS) cats. The occurrence of cytopenias and the distribution of clinical stages were similar in cats with concurrent feline leukemia virus (FeLV) infection and those with FIV alone, suggesting that these abnormalities were a direct consequence of FIV infection. In addition, abnormalities were noted in 72% of marrows from symptomatic cats and included hyperplasia of individual cell lineages and dysmorphic features. Our results demonstrate that the hematologic manifestations of FIV infection are strikingly similar to those reported in HIV-seropositive patients. Thus, FIV infection in cats is an excellent animal model to study the pathogenesis of blood and marrow abnormalities in AIDS, as well as to evaluate the hematologic toxicities of drug therapies.", "journal": "Blood", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "1975376", "author": "Kinlen LJ", "n_authors": 3, "title": "Evidence from population mixing in British New Towns 1946-85 of an infective basis for childhood leukaemia.", "abstract": "Mortality from leukaemia under age 25 was studied in British New Towns to test the hypothesis that leukaemia represents a rare response to a much commoner (but unrecognised) infection, the transmission of which is facilitated when large numbers of people come together. The density of children was higher in the rural, but lower in the overspill, New Towns than in the areas from which their incomers originated. Residents of the rural New Towns had greater diversity of origin than those of the overspill towns of London and Glasgow. These two factors would encourage a greater rise in the postulated underlying infection in the rural towns, and in these a significant excess of leukaemia at ages 0-4 was found in 1946-65. In both sets of towns there was a significant deficit in other age groups consistent with immunising effects of the relevant infection. There are parallels with feline leukaemia virus infection, in which contrasting leukaemogenic and immunising effects occur in different social settings owing mainly to differences in intensity of viral exposure.", "journal": "Lancet (London, England)", "doi": "10.1016/0140-6736(90)93389-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2178336", "author": "Zeidner NS", "n_authors": 6, "title": "Alpha interferon (2b) in combination with zidovudine for the treatment of presymptomatic feline leukemia virus-induced immunodeficiency syndrome.", "abstract": "The therapeutic efficacies of human recombinant alpha interferon (IFN-alpha), IFN-alpha plus zidovudine (AZT), and AZT alone were evaluated in presymptomatic cats with established feline leukemia virus (FeLV)-acquired immunodeficiency syndrome (FAIDS) infection and high levels of persistent antigenemia. Subcutaneous injection of 1.6 x 10(6) U of human recombinant IFN-alpha 2b per kg delivered peak concentrations in plasma of 3,600 U/ml at 2 h postadministration with a half-life of elimination of 2.9 h. This dosage of IFN-alpha could be delivered to cats for up to 12 weeks without significant clinical toxicity. Oral administration of AZT (20 mg/kg three times daily) resulted in peak concentrations in plasma of 3 micrograms/ml at 2 h with a half-life of elimination of approximately 1.60 h. Treatment of FeLV-FAIDS-infected cats with IFN-alpha, either alone or in combination with orally administered AZT, resulted in significant decreases in circulating p27 core antigen beginning 2 weeks after the initiation of therapy. AZT alone had no effect on circulating virus antigen. Depending upon whether high (1.6 x 10(6) U/kg)- or low (1.6 x 10(4) to 1.6 x 10(5) U/kg)-dosage IFN-alpha was used, cats became refractory to therapy 3 or 7 weeks after the beginning of treatment. At these times, IFN-alpha-treated animals developed antibodies to IFN-alpha that were neutralizing, specific for human recombinant IFN-alpha, and dose dependent in magnitude. The results of this study indicate that human recombinant IFN-alpha is effective in reducing circulating virus antigenic load in cats persistently infected with FeLV-FAIDS. However, the continued efficacy of IFN-alpha therapy appeared to be limited by the formation of cytokine-specific neutralizing antibodies.", "journal": "Antimicrobial agents and chemotherapy", "doi": "10.1128/AAC.34.9.1749", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2171713", "author": "Lin DS", "n_authors": 6, "title": "Feline immunodeficiency virus, feline leukaemia virus, Toxoplasma gondii, and intestinal parasitic infections in Taiwanese cats.", "abstract": "A population consisting of 70 breeder cats, 43 clinical cases, and 16 feral cats was examined for the presence of Toxoplasma gondii, feline immunodeficiency virus (FIV), and feline leukaemia virus (FeLV). No oocysts of T. gondii were observed in 96 faecal samples; faecal samples were not available from the feral cats. Other intestinal parasites identified included Isospora felis (three cats), Isospora rivolta (five), Dipylidium canium (two), Toxocara cati (four), Toxascaris leonina (one), and Ancylostoma sp. (two). Using a kinetics-based enzyme-linked immunosorbent assay on 117 sera including all the feral cats, nine had antibody to T. gondii antigen, three for antigens to FIV, and seven to the p27 antigen of FeLV. Of the nine cats with antibody to T. gondii, only one was also infected with FIV.", "journal": "The British veterinary journal", "doi": "10.1016/0007-1935(90)90037-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2166820", "author": "Poss ML", "n_authors": 4, "title": "Characterization and significance of delayed processing of the feline leukemia virus FeLV-FAIDS envelope glycoprotein.", "abstract": "FeLV-FAIDS, an immunodeficiency-inducing isolate of feline leukemia virus, is composed of a pathogenic but replication-defective genome (molecular clone 61C) and a replication-competent but non-immunodeficiency-inducing variant genome (molecular clone 61E). The chimeric virus EECC, composed of the 5' gag-pol of 61E fused to the env-3' LTR of 61C, also induces immunodeficiency. The 61C (or EECC) gp80 can be distinguished from that of 61E on the basis of antigenic recognition, size, and rate of posttranslational processing. We found that the nascent precursor polypeptides of the two viruses were the same size; however, the 61E gp80 rapidly shifted to a smaller size and was subsequently cleaved to gp70, whereas EECC gp80 maintained its nascent size and was cleaved to gp70 only after a prolonged time. Endo-beta-N-acetyl glucosaminidase H and N-glycanase digestions of newly formed glycoproteins resulted in a similar banding pattern for both viruses, indicating that both contained the same number of oligosaccharide side chains and that all of these were high mannose sugars. The metabolic inhibitors of glycosylation, castanospermine or N-methyldeoxynojirimycin, prevented both the rapid trimming of 61E gp80 and its cleavage to gp70. Treatment with mannosidase inhibitors, however, did not affect 61E gp80 processing or size, suggesting that retention of glucose residues on EECC was responsible for these distinguishing properties of the glycoprotein. The pathological consequence of aberrant viral glycoprotein processing was evaluated in feline 3201 T lymphocytes, which are infectable by both 61E and EECC but are killed only by EECC. As in fibroblasts, the EECC glycoprotein produced in lymphocytes was larger, antigenically distinct, and processed more slowly than was the glycoprotein of 61E. Castanospermine treatment of 61E-infected 3201 T cells, however, not only abrogated the antigenic differences between the 61E and EECC glycoproteins but also resulted in a cytopathic effect. Our results suggest that (i) intracellular accumulation of EECC envelope glycoprotein may occur consequent to retention of glucose residues on carbohydrate side chains and (ii) a strong correlation exists between delayed glycoprotein processing and cytopathicity in FeLV-FAIDS-infected T lymphocytes.", "journal": "Journal of virology", "doi": "10.1128/JVI.64.9.4338-4345.1990", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2391276", "author": "Gionfriddo JR", "n_authors": 5, "title": "Ocular manifestations of a metastatic pulmonary adenocarcinoma in a cat.", "abstract": "A primary pulmonary bronchogenic adenocarcinoma originating from an intramediastinal accessory lung was diagnosed in a 14.5-year-old cat. The cat had been admitted because of a cloudy right eye. Physical examination revealed a thin cat with severe iritis, aqueous flare, and a fibrin clot in the anterior chamber of the right eye. Right fundic examination revealed bullous retinal detachment superior to the optic disc. Euthanasia and necropsy were requested when FeLV test results were positive. Metastatic neoplastic cells similar to those of the primary tumor were detected in the choroid, ciliary body, and ciliary processes of the right eye. Ciliary and iridic stromal necrosis attributable to neoplastic embolization of uveal vessels had led to severe uveitis. Foci of metastasis were also in the heart, kidney, and cerebral meninges.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2283159", "author": "Morein B", "n_authors": 1, "title": "The iscom: an immunostimulating system.", "abstract": "To make purified antigens highly immunogenic, they have to be presented in several copies in the form of a microscopic or submicroscopic particle. This is the case, regardless of whether the antigens are obtained by isolation from conventional microorganisms, or from gene-manipulated cells, or synthesized. In the iscom, the antigens are attached as multimers to a 40-nm cage-like particle with a built-in adjuvant. The antigens in iscoms are rapidly transported from the injection site to the draining lymphatic organ. Iscom-borne antigens induced a 10-fold higher antibody response than the same amount of antigen in micelle form. One intranasal immunization with influenza virus iscoms induced protection to intranasal challenge infection in mice. Besides a strong antibody response in all Ig classes and isotypes, cytotoxic T cells were induced. With iscoms containing gp160 of HIV-1, cytotoxic T cells (CD8+ CD4-) were induced under restriction of class I MHC antigen. Iscoms containing the fusion protein of measles virus induced T cell clones in mice whereof one, after adoptive transfer, protected mice against intracerebral challenge infection. Protective immunity against Epstein-Barr virus (EBV)-induced tumor formation by iscoms containing gp350 of EBV has been elicited in cotton-top Tamerin monkeys. Protective immunity has also been induced against several virus infections including feline leukemia virus and against parasites, i.e., Trypanosoma cruzi, in mice.", "journal": "Immunology letters", "doi": "10.1016/0165-2478(90)90128-d", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2167995", "author": "Yang MP", "n_authors": 5, "title": "Effect of Toxoplasma lysate antigen (TLA) on feline cytotoxicity against FeLV positive lymphoma cells.", "abstract": "The cytotoxic activities of feline spleen cells treated with Toxoplasma lysate antigen (TLA) were assayed against feline leukemia virus (FeLV)-producing lymphoma. FL74 cells, and xenogeneic target lymphoma, mouse YAC-1 cells. The TLA treatments were performed in vivo alone, in vitro alone, and in vivo plus in vitro, respectively. In vivo plus in vitro treatments with TLA induced a marked augmentation in cytotoxic activity of spleen cells to FL74 cells. The treatment with TLA in vivo alone showed an enhancement of cytotoxic activity but in vitro alone did not. The cytotoxic effects of TLA-treated spleen cells obtained from the cats which had been previously immunized with live FL74 cells were similar to those of spleen cells from non-immunized cats treated with TLA. However, no increase of cytotoxicity was shown in the response to mouse YAC-1 cells regardless of TLA treatments. These results indicated that the in vivo TLA treatment augmented the cytotoxicity of feline spleen cells against FeLV-producing lymphoma cell.", "journal": "Nihon juigaku zasshi. The Japanese journal of veterinary science", "doi": "10.1292/jvms1939.52.735", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "1966584", "author": "Kopelovich L", "n_authors": 2, "title": "Histiocytic conversion of human adult skin fibroblasts by the Snyder-Theilen feline sarcoma virus.", "abstract": "Oncogenes are apparently involved in the transformation/neodifferentiation of human cells. We now report a novel example of transformation/neodifferentiation: the specific conversion of cultured human adult skin fibroblasts (HSF) to histiocytes (tissue macrophages (TM)) by the Snyder-Theilen feline sarcoma virus (ST: (FeSV)). The de novo conversion of cultured HSF was demonstrated in a large fraction of ST:FeSV (FeLV)-transformed foci in the presence of dexamethasone (DX). Identification of tissue macrophages in ST:FeSV(FeLV)-infected HSF cultures was established by light-and transmission electron microscopy, histochemistry, immunohistochemistry, adherence-reattachment, latex particle uptake, and secretion of bioactive interleukin-1. The ST:FeSV gene and glucocorticosteroids, or other naturally occurring hormones, may play a role in morphogenetic processes within cells from a variety of normal and diseased tissues in situ, including induction of non-bone marrow, mesenchyme-derived, tissue macrophages.", "journal": "European cytokine network", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2166726", "author": "Cohen ND", "n_authors": 5, "title": "Epizootiologic association between feline immunodeficiency virus infection and feline leukemia virus seropositivity.", "abstract": "Five hundred twenty-one feline serum samples submitted to the Texas Veterinary Medical Diagnostic Laboratory between Nov 1, 1988, and Jan 31, 1989 were tested for antibody to feline immunodeficiency virus (FIV) by use of an ELISA. The prevalence of FIV infection in this population was 11.3% (95% confidence interval: 8.6 to 14.0%). Serologic test results for FeLV were available for 156 of the 521 cats. A significant (P = 0.008) association between FIV infection and FeLV seropositivity was observed; FeLV-positive cats were nearly 4 times more likely to be seropositive for FIV than were FeLV-negative cats. The association remained statistically significant (P = 0.021) after adjusting for age and gender, using multiple-logistic regression analysis.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2167039", "author": "Polas PJ", "n_authors": 8, "title": "In vitro and in vivo evidence that the antiviral activity of 2',3'-dideoxycytidine is target cell dependent in a feline retrovirus animal model.", "abstract": "2',3'-Dideoxycytidine (DDC) was evaluated for prophylactic antiviral activity in vitro and in vivo, using the feline leukemia virus (FeLV)-cat animal model. In vitro antiviral activity of DDC against FeLV was dependent upon the target cell used for infection. DDC (5 to 10 microM) inhibited FeLV infection of feline lymphoid cells by greater than 80%, while 6.07 to 12.13 microM DDC was required to similarly inhibit infection of feline fibroblasts. However, 43 to 384 microM DDC was needed to inhibit FeLV infection of primary bone marrow cells by greater than 80%. These in vitro results suggest that, although relatively low doses of DDC may be adequate to prevent infection of feline lymphoid cells, 8- to 80-times-higher doses may be necessary to block infection of bone marrow cells, a primary target cell type for FeLV infection. In vivo studies with DDC consisted of pharmacokinetic and toxicity determinations and evaluation of the prophylactic antiviral activity against FeLV in cats. Clearance and half-life values for DDC in cats were 6.5 ml/min per kg and 54.7 min, respectively. In the prophylactic studies, DDC was administered by continuous intravenous infusion at doses of 22, 15, 10, and 5 mg/kg per h for 28 days in most animals. Cats were challenged intravenously with FeLV 1 to 3 days after drug treatment began. Doses of 22 and 15 mg/kg per h were extremely toxic, causing death in 8 of 10 cats. The mg/kg per h dose was slightly toxic, causing chronic progressive thrombocytopenia over the 28-day treatment period. Of 10 cats given 10 to 5 mg of DDC per kg per h, only one was completely protected from FeLV antigenemia. However, conversion to positive FeLV antigenemia status was delayed by 2 to 7 weeks in seven of nine remaining animals. Interestingly, FeLV infection of bone marrow cells, as indicated by FELV antigen in peripheral blood neutrophils, was only slightly delayed by 0 to 2 weeks, except in the case of the one protected cat, and usually preceded conversion to antigenemia. This pattern of neutrophils becoming antigen positive before detection of antigenemia was not seen in FeLV challenge control animals and indicates that the antiviral activity of DDC may be incomplete during DDC treatment. Results of our in vitro and in vivo studies suggest that feline bone marrow cells may remain partially susceptible to FeLV infection at tolerated doses, while other somatic target tissues (i.e., lymphoid or epithelial tissues) may be protected from infection. Incomplete inhibition of FeLV infection permitted focal bone marrow infection to develop in cats given DDC. These loci of infection served as virus reservoirs which, subsequent to discontinuation of DDC treatment, permitted spread of infection to tissues previously protected during treatment.", "journal": "Antimicrobial agents and chemotherapy", "doi": "10.1128/AAC.34.7.1414", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2165140", "author": "Levy LS", "n_authors": 5, "title": "An unusual retrovirus-like sequence identified in human DNA.", "abstract": "The human genome contains many different types of endogenous proviruses and retrovirus-like elements. An unusual element of this kind has been isolated from human DNA on the basis of its relatedness to the integrase-coding domain of the pol gene of feline leukaemia virus (FeLV). The element, termed Hs5, is related to FeLV only over a short region of 81 nucleotides predicted to encode the carboxyl terminus of the FeLV integrase protein, p46pol. The region of relatedness between Hs5 and FeLV identifies a short conserved amino acid stretch which is shared among distantly related retroviruses. The conservation of this sequence, its position, and predicted secondary structure suggest that it may represent a conserved substrate binding site or active site of the integrase enzyme. Nucleotide sequence analysis of Hs5 reveals that it is not an intact retrovirus, but contains only the 3' terminus of pol and a defective env gene without apparent long terminal repeat; Hs5 is unusual among human endogenous retrovirus-like elements in this respect.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-71-7-1613", "deposited_data": "Sim", "nuccore_ids": "220062", "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2161948", "author": "Levesque KS", "n_authors": 3, "title": "flvi-1, a common integration domain of feline leukemia virus in naturally occurring lymphomas of a particular type.", "abstract": "A locus in feline DNA, termed flvi-1, which may play an important role in the natural induction of lymphomas by feline leukemia virus (FeLV) was identified. Examination of a bank of 21 naturally occurring FeLV-positive feline lymphomas revealed that FeLV proviral integration occurs at flvi-1 in four independent tumors (19%). Independent integrations occurred within a 2.4-kilobase region of flvi-1, the probability of which by random chance can be estimated as 10(-16). Several lines of evidence, including sequence analysis of the long terminal repeat, demonstrated that proviruses integrated at flvi-1 are exogenously acquired and are oriented in the same transcriptional direction with respect to the locus. Molecularly cloned flvi-1 did not hybridize with probes representing several previously described proviral integration domains or with probes representing 10 oncogenes. The natural feline lymphomas examined in this study were heterogeneous with respect to tissue of origin, cell type, and number of monoclonal proviral integrations. The four tumors in which flvi-1 is interrupted were classified as members of a phenotypic subgroup containing seven lymphomas, i.e., at least four (57%) of seven lymphomas of this type contained FeLV proviral integration at flvi-1. Members of this phenotypic subgroup are non-T-cell lymphomas isolated from the spleen and contain an average of three proviruses, compared with an average of eight among all of the tumors examined. The small number of proviral integrations in tumors of this subgroup suggests that an early proviral integration event into flvi-1 can induce malignant change.", "journal": "Journal of virology", "doi": "10.1128/JVI.64.7.3455-3462.1990", "deposited_data": "Sim", "nuccore_ids": "50402028, 50402026, 37577222, 37577217, 323908", "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "1975194", "author": "Vowels BR", "n_authors": 4, "title": "Natural killer cell activity of rhesus macaques against retrovirus-pulsed CD4+ target cells.", "abstract": "Rhesus peripheral blood mononuclear cells (PBMC) fail to demonstrate natural killer (NK) activity against the human T-cell lines CEM, CEM x 174, or SUP-T1. However, these cell lines could act as NK-sensitive target cells if they were pulsed with heat-inactivated, whole simian immunodeficiency virus (SIV). The ability of these SIV-pulsed T-cell lines to act as NK-sensitive target cells was directly related to the relative density of CD4 on their surface. Target cell generation was inhibited by preincubation of cell lines with CD4 monoclonal antibody (MAb) with specificity for the SIV binding site. In addition, NK activity was seen against target cells that had been prepared with human immunodeficiency virus type 1 (HIV-1) gp120, nonglycosylated gp120, env A of feline leukemia virus (FeLV), and simian type D retrovirus (SRV). Addition of leupeptin to target cells prior to SIV pulsing did not result in a significant decrease in cytotoxic activity, suggesting that processing is not required for the generation of target cells. The cells that mediate NK activity are nonadherent, do not form rosettes with AET-treated sheep red blood cells (SRBC), and are phenotypically CD16+ and CD8+. NK activity of SIV-infected macaques was significantly decreased against both K562 cells and SIV-pulsed target cells as compared with uninfected animals. However, treatment of PBMC with interleukin-2 (IL-2) resulted in a partial restoration of NK activity.", "journal": "AIDS research and human retroviruses", "doi": "10.1089/aid.1990.6.905", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "1965583", "author": "Rodgers SJ", "n_authors": 2, "title": "A serologic survey of Oklahoma cats for antibodies to feline immunodeficiency virus, coronavirus, and Toxoplasma gondii and for antigen to feline leukemia virus.", "abstract": "A serologic survey was done on 618 cat sera submitted to the Oklahoma Animal Disease Diagnostic Laboratory between July 1, 1987 and June 30, 1988. The samples were collected from clinically normal and sick cats. The sera were tested for the presence of antibodies to feline immunodeficiency virus by a commercial immunoassay, to a coronavirus by an indirect fluorescent antibody test, and to Toxoplasma gondii by a commercial latex agglutination test and for the presence of feline leukemia virus antigen with one of 3 different commercial assay kits. Ten percent of the sera had antibodies to feline immunodeficiency virus, 35% had antibodies to a coronavirus, and 22% had antibodies to Toxoplasma gondii. Feline leukemia virus antigen was detected in 15% of the sera. Thirty-two percent of the sera had evidence of exposure to 2 or more of the agents.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/104063879000200305", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2205974", "author": "Morein B", "n_authors": 1, "title": "Iscoms.", "abstract": "The common problem for defined purified antigens or antigen determinants has been to make them immunogenic regardless of whether they are produced conventionally, produced as cloned genetechnology products or chemically synthesized. The first problem is to get the protective antigen into a submicroscopic particle where the antigen is presented in several copies, i.e. as a multimer. For some antigens it seems also necessary to enhance the immunogenicity with an adjuvant. The immunostimulating complex (iscom) was created to fulfil these criteria by assembling antigens in a multimeric form on a matrix with built-in adjuvant to form a particle. The components are held together by hydrophobic interactions. The iscom has turned out to be highly immunogenic, inducing high antibody mediated and cell-mediated immunity including cytotoxic T cell response to influenza virus. In a mouse model iscoms containing influenza virus envelope proteins induced protective immunity by one intranasal administration. Protective immunity was also induced to a retrovirus--feline leukemia virus. In a monkey model system iscoms containing gp360 of Epstein-Barr virus induced protection to induction of tumours. Iscoms have also been used as carriers for small molecules such as oligopeptides, which combination appeared to be highly immunogenic.", "journal": "Veterinary microbiology", "doi": "10.1016/0378-1135(90)90138-l", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2197046", "author": "Tas M", "n_authors": 3, "title": "Beneficial effects of the thymic hormone preparation thymostimulin in patients with defects in cell-mediated immunity and chronic purulent rhinosinusitis. A double-blind cross-over trial on improvements in monocyte polarization and clinical effects.", "abstract": "Twenty patients with chronic purulent rhinosinusitis were treated with TP-1 (Serono; 1 mg/kg body weight), in a double-blind cross-over trial. TP-1 was administered by daily i.m. injections for the first 14 days followed by two injections/week for 6 further weeks. The patients were immunologically special in that they had defects in their cell-mediated immune system. Fourteen showed a decreased chemotactic responsiveness of their peripheral blood monocytes as measured in the polarization assay. This defective function can probably be ascribed to the presence in serum of low molecular weight factors (LMWFs; less than 25 kD). As reported earlier, this factor shows a structural homology to the envelope protein of murine and feline leukaemia virus (P15E). Thirteen patients showed a defective delayed-type hypersensitivity (DTH) skin test reactivity towards candidin and/or streptokinase-streptodornase (Sk/Sd) antigen, 14 had a defective MIF production from their peripheral blood lymphocytes towards candidin, Sk/Sd and/or Haemophilus influenzae antigen. Eighteen patients completed the TP-1 trial and showed clinical improvements: 12 out of 15 were feeling better during TP-1 therapy and the nasal mucosa showed on inspection absent mucopurulent secretion in 13 patients. Positive bacterial culture rates for the nose decreased from 14 out of 16 to five out of 15. Placebo treatment had no significant effects. The clinical improvements were accompanied by a better performance of the cell-mediated immune system; the most significant effects were recorded in the monocyte polarization assay. The suppressive P15E-like LMWFs in serum clearly decreased during TP-1 treatment. In vitro TP-1 neutralized the immunosuppressive effect of the LMWFs. The restoring effects of TP-1 on monocyte polarization and its neutralizing activity of P15E-like LMWFs could explain the beneficial effects of thymic hormone treatment reported in adults with clinical signs of immunodeficiency in the presence of a full T cell repertoire.", "journal": "Clinical and experimental immunology", "doi": "10.1111/j.1365-2249.1990.tb03286.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2170778", "author": "Racz P", "n_authors": 8, "title": "Lymphatic tissue changes in AIDS and other retrovirus infections: tools and insights.", "abstract": "Based on immunohistochemistry, in situ hybridization, and electron microscopy, lymphatic tissue changes in human immunodeficiency virus (HIV) and other retroviral infections represent different stages of a dynamic process progressing from hyperplasia to atrophy. The germinal centers (GC) function early as a virus reservoir in both HIV and feline leukemia virus infection, which also produces lymphadenopathy, severe immune impairment, and death from opportunistic infections. Core proteins of HIV can be detected on the surface of follicular dendritic cells, electron microscopy reveals cell-free HIV and virus replication in the same location, and in situ hybridization shows that the majority of cells with mRNA of HIV can be found in germinal centers (GC). Double immunohistochemical labeling of lymphocyte populations suggests that one of the most important events in HIV lymphadenitis with explosive follicular hyperplasia is the accumulation of CD8+CD45R0+ lymphocytes in the lymph nodes. Their clustering in the vicinity of the FDC network could play a key role in disintegration of GC and lymphocyte depletion as the disease progresses.", "journal": "Lymphology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2170777", "author": "Good RA", "n_authors": 5, "title": "Immunosuppressive actions of retroviruses.", "abstract": "The immunosuppressive properties of retroviruses were first demonstrated by Old et al. We later showed that Gross Passage A retrovirus superinfection in mice resulted in decreased antibody production and diminished allograft rejection. We have studied in some detail the immunosuppression which occurs subsequent to infection with feline leukemia virus (FeLV) as characterized by profoundly depressed T and B lymphocyte responses and decreased production of gamma-interferon. Injection of staphylococcal protein A (SPA) corrected these deficient immune responses, cleared circulating FeLV from blood and produced a regression of FeLV-induced lymphomas and leukemias. The immunosuppressive properties of FeLV and certain other retroviruses have been linked to the transmembrane viral envelope peptide, p15E. Cianciolo et al synthesized a 17-amino acid viral component which shares sequence homology with a highly conserved region of p15E. In vitro analyses have shown that this synthetic retroviral peptide suppresses T and B cell functions, inhibits the generation of cytotoxic lymphocyte (CTL) responses and dramatically alters the morphology and distribution of monocytes. The latter finding, along with reports that cells of the monocyte/macrophage lineage play a critical role in the initiation of human immunodeficiency infection, suggests that monocytes and macrophages may play a crucial role in retroviral infection and some of the associated immunodeficiencies associated with retroviral infection.", "journal": "Lymphology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2169669", "author": "Lutz H", "n_authors": 1, "title": "Feline retroviruses: a brief review.", "abstract": "Representatives of all three retrovirus subfamilies are recognized in the cat: feline leukaemia virus (an Oncovirus), feline syncytium-forming virus (a Spumavirus) and feline immunodeficiency virus (a Lentivirus). Each of these is briefly reviewed.", "journal": "Veterinary microbiology", "doi": "10.1016/0378-1135(90)90143-j", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2163339", "author": "Haschek WM", "n_authors": 8, "title": "Zidovudine toxicity to cats infected with feline leukemia virus.", "abstract": "Feline leukemia virus (FeLV) infection of cats is a model for the acquired immunodeficiency syndrome in humans. The toxicity of zidovudine was evaluated in SPF cats experimentally infected with FeLV. At initiation of the zidovudine study, all cats were antibody positive for FeLV antigens but clinically asymptomatic. Four cats were also viremic. Thirteen, 6- to 10-month-old cats were divided into five dosage groups and given zidovudine po at 0, 7.5, 15, 30, or 60 mg/kg daily in three equally divided doses for 32 to 34 days. Titers of circulating virus antigen remained constant; however, three of six cats receiving the higher doses of zidovudine (greater than or equal to 30 mg/kg) showed an increase in antibody titers to FeLV. Administration of zidovudine resulted in a progressive anemia, dependent upon dose and time. Macrocytes were observed prior to the development of anemia and were also found in several nonanemic cats. Repeated measures regression analyses indicated that an increased dose of zidovudine was associated with decreased packed cell volume, red blood cell count, and hemoglobin. As determined from the packed cell volume, the analyses indicate that anemia is induced only by the two highest doses of zidovudine. The regression model indicates that daily doses of 60 and 30 mg/kg are expected to induce anemia by Day 4 and Day 13, respectively. Progressive absolute neutropenia was observed in the greater than or equal to 30 mg/kg groups. Histopathologic lesions consisted of marked bone marrow hypercellularity in cats given greater than or equal to 30 mg/kg zidovudine and splenic extramedullary hematopoiesis in cats given greater than or equal to 15 mg/kg. Thus, oral toxicity of zidovudine in the cat is manifested by a dose-related anemia and neutropenia as observed in humans.", "journal": "Fundamental and applied toxicology : official journal of the Society of Toxicology", "doi": "10.1016/0272-0590(90)90301-y", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2161827", "author": "Cheney CM", "n_authors": 8, "title": "A feline large granular lymphoma and its derived cell line.", "abstract": "A lymphoma cell line (MCC) was derived from an abdominal mass from a 13-yr-old castrated male cat. The cells resemble natural killer precursor cells, have membrane-bound granules, and are positive for chloroacetate esterase, alpha-naphthyl butyrate esterase, and tartrate-resistant acid phosphatase activities. The MCC cells are negative for rearranged feline T-cell receptor genes, negative for feline T-cytotoxic antigen, Ia, and surface mu, tau, and lambda chains and do not form E-rosettes. The MCC cell line is negative for the feline leukemia virus (FeLV); e.g., negative for exogenous FeLV (exU3) sequences, negative for cytoplasmic and surface FeLV major core protein of 27,000 daltons (p27) by indirect immunofluorescence assay, negative for helper FeLV by clone 81 assay, and negative for release of soluble FeLV p27 by enzyme-linked immunosorbent assay. Electron microscopy reveals budding type C retrovirus particles and MCC cells react with anti-RD-114 (anti-endogenous feline retrovirus) reference serum. After in vitro infection, MCC replicate FeLV readily, but replication is noncytopathic.", "journal": "In vitro cellular & developmental biology : journal of the Tissue Culture Association", "doi": "10.1007/BF02624087", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "1691887", "author": "Sommerfelt MA", "n_authors": 2, "title": "Receptor interference groups of 20 retroviruses plating on human cells.", "abstract": "The types of receptors on the surfaces of human and other mammalian cells for 13 C-type and 7 D-type retrovirus strains were determined by interference to the formation of syncytia and the plating of viral pseudotypes. All the D-type simian retroviruses (SRV-1-5, SMRV, PO-1-Lu) share a common receptor which is also utilized by the baboon and cat endogenous C-type viruses (BaEV, RD114). Syncytial cross-interference was also observed in human cells between the gibbon ape leukemia/simian sarcoma associated viruses (GALV/SSAV) and feline leukemia virus subgroup B (FeLV-B). Amphotropic and xenotropic murine leukemia viruses (MLV-A, MLV-X), bovine leukemia virus (BLV), and FeLV-C infect human cells via unique cell surface receptors. Human T-cell leukemia viruses types 1 and 2 (HTLV-1, HTLV-2) share a common receptor with related chimpanzee and simian viruses (STLV). Thus seven distinct receptor groups were delineated on human cells for C-type and D-type retroviruses.", "journal": "Virology", "doi": "10.1016/0042-6822(90)90230-o", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2158493", "author": "Swenson CL", "n_authors": 7, "title": "Prevalence of disease in nonviremic cats previously exposed to feline leukemia virus.", "abstract": "Feline leukemia virus status and antibody titer to feline oncornavirus-associated cell membrane antigen (FOCMA) were determined on plasma from 183 outpatient cats and 61 cats from 2 closed, FeLV-positive, multiple-cat households. Cats with FOCMA antibody titer had a significantly (P less than 0.02) higher prevalence of history of disease than did cats without FOCMA antibody. Diseases included upper respiratory tract infections, abscesses, ear infections, lower urinary tract infections, gastrointestinal disease, pneumonia, uterine infection, lymphadenopathy, fever of unknown origin, and bacterial infections. The FOCMA antibody titer was determined by use of an indirect fluorescent antibody test; titer greater than or equal to 1:16 was considered to be positive results. Lower mean FOCMA antibody titer was observed in young cats with history of disease (P less than 0.05) than in young cats without history of disease or in older cats with or without history of disease. Prevalence of FOCMA antibody titer was identical (38%) in young and adult cats, indicating cats likely were exposed to FeLV as kittens because a higher prevalence of FOCMA antibody titer in older cats would otherwise be expected.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2157050", "author": "Fulton R", "n_authors": 4, "title": "Structural diversity and nuclear protein binding sites in the long terminal repeats of feline leukemia virus.", "abstract": "The long terminal repeat U3 sequences were determined for multiple feline leukemia virus proviruses isolated from naturally occurring T-cell tumors. Heterogeneity was evident, even among proviruses cloned from individual tumors. Proviruses with one, two, or three repeats of the long terminal repeat enhancer sequences coexisted in one tumor, while two proviruses with distinct direct repeats were found in another. The enhancer repeats are characteristic of retrovirus variants with accelerated leukemogenic potential and occur between -155 and -244 base pairs relative to the RNA cap site. The termini of the repeats occur at or near sequence features which have been recognized at other retrovirus recombinational junctions. In vitro footprint analysis of the feline leukemia virus enhancer revealed three major nuclear protein binding sites, located at consensus sequences for the simian virus 40 core enhancer, the nuclear factor 1 binding site, and an indirect repeat which is homologous to the PEA2 binding site in the polyomavirus enhancer. Only the simian virus 40 core enhancer sequence is present in all of the enhancer repeats. Cell type differences in binding activities to the three motifs may underlie the selective process which leads to outgrowth of viruses with specific sequence duplications.", "journal": "Journal of virology", "doi": "10.1128/JVI.64.4.1675-1682.1990", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2110982", "author": "Mochizuki M", "n_authors": 3, "title": "Serological survey of the Iriomote cat (Felis iriomotensis) in Japan.", "abstract": "The Iriomote cat (Felis iriomotensis) was first discovered on Iriomote Island in the Yaeyama Islands of Japan in 1965. Ten male and 11 female adult cats were captured during the 6 yr period from 1983 to 1988. These were examined for evidence of viral and mycoplasmal infections. Neither Mycoplasma sp. nor Ureaplasma sp. were detected in swab samples of oropharyngeal and urogenital regions. A foamy virus was isolated from the oropharyngeal swab of a female cat examined in 1988. Feline leukemia virus was not detected in any of the cats. All cats were negative for serum antibodies to feline panleukopenia virus, feline herpesvirus, feline immunodeficiency virus and rotavirus. Eleven of 19 (58%), 14 of 17 (82%) and 6 of 17 cats (35%) had serum antibodies against feline calicivirus, coronavirus and feline syncytium forming virus, respectively.", "journal": "Journal of wildlife diseases", "doi": "10.7589/0090-3558-26.2.236", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "1969500", "author": "Wegemer DE", "n_authors": 3, "title": "Biological activities of a synthetic peptide composed of two unlinked domains from a retroviral transmembrane protein sequence.", "abstract": "We report several biological activities of a synthetic peptide whose sequence contains the highly conserved region of feline leukemia virus transmembrane protein (TM) synthetically linked to another short TM-derived sequence particularly rich in polar positive residues. This 29-amino-acid peptide blocked [3H]thymidine uptake 30 to 50% by concanavalin A-stimulated CD4(+)--but not CD8(+)-enriched murine splenocytes. Maximal suppression was detected at 12.5 micrograms (3 microM) to 75 micrograms (19 microM) per ml of growth medium; stimulation of [3H]thymidine uptake was observed at higher peptide concentrations. The synthetic peptide inhibited but did not stimulate [3H]thymidine uptake by mitogen-activated thymocytes and antibody production by splenocytes as determined in a liquid hemolytic plaque assay. Similarities are reported between a consensus sequence of diverse retroviral TMs and a region of alpha interferons shown by others to be important for antiviral and cytostatic properties. The TM sequence-derived synthetic peptide blocked in a nontoxic and sequence-specific manner the release of murine leukemia virus from two chronically infected cell lines. We suggest that some of the biological effects of retroviral TM are mediated through a common pathway shared with alpha interferons.", "journal": "Journal of virology", "doi": "10.1128/JVI.64.4.1429-1436.1990", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2161136", "author": "Copelan EA", "n_authors": 4, "title": "Purine metabolism in feline lymphomas.", "abstract": "Deficiency of the purine metabolic enzyme adenosine deaminase causes severe immunodeficiency. Retroviruses have been reported to decrease the activity of adenosine deaminase, and many retroviruses, including feline leukemia virus, cause immunodeficiency. Levels of purine metabolic enzymes including adenosine deaminase and consequences of adenosine deaminase inhibition were investigated in feline leukemia virus-infected fresh tumor cells and infected and uninfected cell lines. No evidence of virus effect on levels of adenosine deaminase or other purine metabolic enzymes was detected. Neoplastic cells demonstrated considerable heterogeneity of activity levels of purine metabolic enzymes.", "journal": "Veterinary pathology", "doi": "10.1177/030098589002700207", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2160531", "author": "Legendre AM", "n_authors": 3, "title": "Efficacy of a feline leukemia virus vaccine in a natural exposure challenge.", "abstract": "A commercial feline leukemia virus (FeLV) vaccine was evaluated in a natural exposure system. All kittens were negative for FeLV antigen on two enzyme-linked immunosorbent assay (ELISA) tests and one indirect immunofluorescence antibody (IFA) test before vaccination or exposure. Twenty-three kittens were vaccinated subcutaneously at nine and 12 weeks of age. The vaccinated kittens and 14 unvaccinated littermates were housed in an infected environment starting at 14 weeks. The kittens were exposed for 24 weeks by living in a large room with one feline leukemia virus-positive, asymptomatic adult cat for each five kittens. Sixty-four percent of the unvaccinated kittens and 70% of the vaccinated kittens became infected as determined by ELISA. Forty-three percent of unvaccinated kittens and 39% of vaccinated kittens died. There was no difference between the infection and mortality of vaccinated kittens that developed antibodies to anti-FeLV glycoprotein 70-envelope antigen and those that did not. Consideration should be given to evaluation of feline leukemia virus vaccines using \"street\" virus in a natural exposure system.", "journal": "Journal of veterinary internal medicine", "doi": "10.1111/j.1939-1676.1990.tb00882.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2156003", "author": "Steinman R", "n_authors": 10, "title": "Biochemical and immunological characterization of the major structural proteins of feline immunodeficiency virus.", "abstract": "Feline immunodeficiency virus (FIV) structural proteins were identified using sera obtained from experimentally inoculated cats. Proteins analysed by both radioimmunoprecipitation and Western blotting were specific for FIV infection and failed to cross-react with either antisera to feline leukaemia virus of feline syncytium-forming virus. Western blot analysis of purified virus revealed immunoreactive proteins with apparent Mr of 65K, 50K, 40K, 32K, 24K, 15K and 10K. The major core structural proteins of the virus were isolated by reverse phase HPLC and the aminoterminal sequences of p10 and p24 were determined. Monoclonal antibodies specific for p24 suggested the presence of a precursor protein that could be detected in 35[S]methionine/cysteine-labelled, virus-infected cell extracts. This putative precursor protein possessed an apparent Mr of 50K (Pr50gag). Further analysis revealed the presence of two additional proteins of 130K and 40K. Experiments utilizing tunicamycin, endoglycosidase H and glycopeptidase F revealed that p130 and p40 exhibited properties characteristic of glycoproteins. Our studies also indicated that FIV is immunologically related to other lentiviruses.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-71-3-701", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "1966725", "author": "Haas L", "n_authors": 3, "title": "Use of biotechnical methods in veterinary medicine.", "abstract": "Biotechnological methods offer promising approaches for improved diagnostic and prophylactic purposes. The following biotechnological techniques are used in the Institute of Virology at the Hanover Veterinary School:--Production of monoclonal antibodies directed against viral and bacteria-specific antigens such as bovine virus diarrhoea virus, classical swine fever (hog cholera) virus, feline leukaemia virus, animal parvoviruses, Alphavirus, Brucella and Francisella--Establishment of improved and sensitive diagnostic enzyme immunoassays (ELISA) using monoclonal antibodies--Molecular cloning and sequencing of classical swine fever virus RNA and parvovirus DNA--Development of diagnostic hybridisation techniques (dot, slot, Southern and Northern blot, in situ, oligonucleotides)--Detection of viral genomes in tissues of infected animals--Development of synthetic oligopeptides as diagnostic antigens and as potential immunogens for vaccines. Currently available techniques used in basic research (e.g. pathogenesis studies) will be tested for their application in routine diagnosis of viral diseases, e.g. by molecular hybridisation. Some techniques need to be simplified (e.g. RNA extraction procedures) and, particularly, alternative labelling schedules must be developed (e.g. biotin or sulfone labelling instead of radionuclides).", "journal": "Revue scientifique et technique (International Office of Epizootics)", "doi": "10.20506/rst.9.1.474", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "1690524", "author": "Lafrado LJ", "n_authors": 4, "title": "Biological effects of staphylococcal protein A immunotherapy in cats with induced feline leukemia virus infection.", "abstract": "Biological effects of staphylococcal protein A (SPA) immunotherapy were studied in 5 viremic and 6 nonviremic cats with induced FeLV infection and in 6 control cats. The SPA therapy neither reversed FeLV viremia nor resulted in consistent improvement in humoral immune responses to FeLV antigens. However, SPA immunotherapy induced a proliferative response in bone marrow granulocytic lineage, possibly resulting in expression of FeLV-free mature neutrophils in the blood. Seemingly, viral burden and chemiluminescent responses were reversed in viremic cats during SPA immunotherapy.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2154424", "author": "Pollock RV", "n_authors": 2, "title": "Randomized blind trial of a commercial FeLV vaccine.", "abstract": "A randomized blind trial of a commercial FeLV vaccine was conducted to evaluate its performance in cats under conditions of long-term natural exposure. Seventy-nine nonviremic, seronegative cats were randomized into 2 groups. Cats were given 3 doses of either FeLV vaccine or placebo (killed rabies virus vaccine) sc at weeks 0, 3, and 9 of the trial. Six weeks later, 44 known-viremic cats were added to the colony. Cats were housed in a single large room and food dishes and litter pans were used in common. Blood samples were collected at 4, 8, and 12 months after the addition of the viremic cats and were assayed for viremia by use of ELISA. Twelve-month samples were also assayed independently by use of indirect fluorescent antibody testing. Investigators conducted assays on coded samples without knowledge of the cat's vaccination status; neither the investigators nor colony personnel knew which cats had been given the FeLV vaccine and which had been given the placebo until the twelfth month of exposure. After 12 months of cohabitation with infected cats, vaccinated cats had a significantly (P less than or equal to 0.02) lower incidence of persistent viremia (defined as 2 positive ELISA test results at least 8 weeks apart or 1 positive indirect fluorescent antibody test result), compared with the placebo-inoculated cats. The incidence of persistent viremia was approximately 3 times greater among the placebo-inoculated cats than among vaccinates.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2156386", "author": "Haffer KN", "n_authors": 4, "title": "Evaluation of immunosuppressive effect and efficacy of an improved-potency feline leukaemia vaccine.", "abstract": "An inactivated feline leukaemia vaccine was tested to determine if process improvements would permit it to be effectively used in a two-dose primary regimen versus the three-dose regimen required for a previous vaccine. Twenty-five cats were vaccinated with two subcutaneous doses given 3 weeks apart. Vaccinates and controls were artificially immunosuppressed to enhance susceptibility to challenge, and inoculated with virulent feline leukaemia virus (FeLV) 2 weeks after the second dose. Following challenge, seven (28%) vaccinates became persistently viraemic, versus six (60%) controls. Nine (36%) other vaccinates became transiently viraemic and nine were aviraemic. The mean postvaccination ELISA gp70 antibody value was 0.796 for aviraemic vaccinates, 0.575 for transiently viraemic vaccinates, and 0.350 for persistently viraemic vaccinates. Eighteen of 25 vaccinates had a postvaccination antibody response greater than or equal to 32 to feline oncornavirus associated cell membrane antigen. Seven of 25 (28%) vaccinates developed postvaccination virus neutralization (VN) antibody titres, and 16 of 25 (64%) developed postchallenge VN antibody titres. One of 10 controls developed postchallenge VN antibody titres. An in vitro lymphocyte blastogenesis assay to evaluate immunosuppressive effects of vaccination revealed no significant difference in the mean stimulation index for vaccinates versus controls. Results indicated that vaccination with two doses was an effective immunoprophylactic regimen in the face of FeLV challenge severe enough to produce persistent viraemia in 60% of non-vaccinated controls.", "journal": "Vaccine", "doi": "10.1016/0264-410x(90)90170-q", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2155287", "author": "Tzavaras T", "n_authors": 7, "title": "Molecular cloning and characterization of a defective recombinant feline leukaemia virus associated with myeloid leukaemia.", "abstract": "The GM1 strain of feline leukaemia virus (FeLV) was isolated from a naturally occurring case of myeloid leukaemia and induces severe haematopoietic abnormalities, including myeloblastic leukaemia, on inoculation into cats. Molecular clones of FeLV-GM1 proviruses were obtained and studied by restriction enzyme mapping, blot hybridization and partial DNA sequence analysis. Two types of clone were isolated; the first was a replication-competent FeLV of subgroup A, resembling other low or minimally pathogenic FeLV-A isolates; the second was replication-defective with extensive deletions and mutations in gag and pol, although it has an intact env gene of subgroup B phenotype. Large segments of the defective proviruses, from the 5' leader sequence upstream of the gag gene to the 5' half of the env gene, show structural hallmarks of endogenous FeLV-related proviruses. Infectious FeLV-GM1 viruses recovered after transfection were tested for their leukaemogenic potential in newborn cats. Early polyclonal myeloproliferative changes were observed in cats inoculated with FeLV-A/GM1 alone, although these were more pronounced in animals receiving the full FeLV-AB/GM1 complex reconstituted by cotransfection of the defective virus FeLV-B with its FeLV-A helper. Analysis of viruses in the bone marrow showed that replication of the subgroup B component is delayed and restricted to a proportion of cats. Most of the infected cats developed persistent abnormalities of haematopoiesis and one progressed to disseminated myeloid leukaemia. The defective recombinant FeLV-B/GM1 appears to play an indirect but important role in myeloid leukaemogenesis.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-71-2-343", "deposited_data": "Sim", "nuccore_ids": "221268", "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2153226", "author": "Pedersen NC", "n_authors": 9, "title": "Feline leukemia virus infection as a potentiating cofactor for the primary and secondary stages of experimentally induced feline immunodeficiency virus infection.", "abstract": "Preexistent feline leukemia virus (FeLV) infection greatly potentiated the severity of the transient primary and chronic secondary stages of feline immunodeficiency virus (FIV) infection. Of 10 FeLV-FIV carrier cats, 5 died of experimentally induced FIV infection, compared with 2 deaths in 10 cats infected only with FeLV and 1 death in 7 cats infected only with FIV. FIV-infected cats with preexistent FeLV infections developed severe depression, anorexia, fever, diarrhea, dehydration, weight loss, and leukopenia 4 to 6 weeks after infection and were moribund within 2 weeks of the onset of signs, whereas cats infected only with FIV developed much milder self-limiting gross and hematologic abnormalities. Pathologic findings in dually infected cats that died were similar to those observed previously in cats dying from uncomplicated primary FIV infection but were much more widespread and severe. Coinfection of asymptomatic FeLV carrier cats with FIV did not increase the levels of FeLV p27 antigen present in their blood over that seen in cats infected with FeLV alone. The amount of proviral FIV DNA was much higher, however, in dually infected cats than in cats infected only with FIV; there was a greater expression of FIV DNA in lymphoid tissues, where the genome was normally detected, and in nonlymphoid tissues, where FIV DNA was not usually found. Dually infedted cats that recovered from the primary stage of FIV infection remained more leukopenic than cats infected with FIV or FeLV alone, and their CD4+/CD8+ T-lymphocyte ratios were inverted. One of these cats developed what was considered to be an opportunistic infection. It was concluded, therefore, that a preexistent FeLV infection in some way enhanced the expression and spread of FIV in the body and increased the severity of both the resulting transient primary and chronic secondary stages of FIV infection. This study also demonstrated the usefulness of the FIV model in studying the role of incidental infectious diseases as cofactors for immunodeficiency-causing lentiviruses.", "journal": "Journal of virology", "doi": "10.1128/JVI.64.2.598-606.1990", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2295559", "author": "Grindem CB", "n_authors": 3, "title": "Risk factors for Haemobartonella felis infection in cats.", "abstract": "A seroepidemiologic survey for Haemobartonella felis infection in cats of Wake County, NC was undertaken. To help assess risk factors, cat owners completed a 10-item questionnaire. Additionally, blood samples were obtained for determination of H felis presence, FeLV infection, and anemia. Prevalence rates for H felis presence were as follows: all cats, 4.9% (6/123); healthy cats, 3.6% (3/83); and ill cats, 7.5% (3/40). The estimated relative risk for haemobartonellosis was also increased in cats with any of the following: anemia, FeLV-positive status, lack of vaccinations, history of catbite abscesses and/or anemia, age less than or equal to 3 years, or outdoor-roaming status. The sex, breed, number of cats in the household, or presence of fleas were not significant factors, although ill male cats had a greater estimated relative risk for haemobartonellosis.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2178116", "author": "Charreyre CE", "n_authors": 2, "title": "Evaluation of humoral immunity tests in FeLV infected cats.", "abstract": null, "journal": "Developments in biological standardization", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2178113", "author": "Mullins JI", "n_authors": 10, "title": "The FeLV and SIV AIDS pathogenesis models: search for and analysis of molecularly defined pathogens.", "abstract": null, "journal": "Developments in biological standardization", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2178111", "author": "Neil JC", "n_authors": 7, "title": "Origins and characteristics of pathogenic variants of feline leukaemia virus.", "abstract": null, "journal": "Developments in biological standardization", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2174630", "author": "Schrenzel MD", "n_authors": 5, "title": "Type C retroviral expression in spontaneous feline olfactory neuroblastomas.", "abstract": "Three cases of spontaneous olfactory neuroblastoma (ONB) in domestic cats were morphologically and immunocytochemically characterized. Diagnostic light microscopic features included Flexner and Homer-Wright rosettes, while ultrastructurally the cells had neuritic processes, intracellular intermediate filaments, and intercellular junctions. Immunocytochemically, the tumors stained positively for neuron-specific enolase, cytokeratins, and S-100 protein antigens. In each case, a key finding was the identification of numerous mature type C retroviral particles within the tumors. In one case, budding of viral particles from the plasmalemma of tumor cells suggested the source of mature particles. This cat and one other were tested, and both were serologically positive for feline leukemia virus (FeLV). The virus in the tumors was identified as FeLV by polymerase chain reaction and immunocytochemistry. No other neoplasms were found in any of the cats, nor was there similar evidence of active viral infection in other non-tumor tissues, including the brain. Although the relationship between FeLV infection and ONB is uncertain, our findings indicate that FeLV should be investigated as an etiologic agent of ONB.", "journal": "Acta neuropathologica", "doi": "10.1007/BF00294617", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2167513", "author": "Lutz H", "n_authors": 7, "title": "[Feline immunodeficiency virus in Switzerland: clinical aspects and epidemiology in comparison with feline leukemia virus and coronaviruses].", "abstract": "Serum samples from 1421 domestic cats (561 healthy, 860 sick) were tested for FIV-, FeLV- and coronavirus infection. The results were stored in a computer data base and compared with epidemiologic data and clinical findings. All 3 infections were significantly more prevalent in sick than healthy cats: FIV was found in 0.7% of healthy and 3.4% of sick cats. For FeLV the prevalence was 3.0% and 13.0% and for coronavirus 21% and 36.2%, respectively. FIV-infected cats were mostly male (73%); no sex predilection was observed in FeLV- and coronavirus infection. In sick cats FIV-infection was significantly more prevalent in cats greater than 2 years of age; no age-dependence was found in FeLV- and coronavirus infections. The prevalence of FIV-infection increased significantly with the number of animals per household. In contrast, the frequency of FeLV infection decreased with the number of animals per household. Prevalence of coronavirus infection did not vary with group size or living conditions. The following clinical symptoms were associated with infection: FIV: general depression, diseases of the urinary tract; FeLV: general depression, fever, rough hair coat, lymphadenopathy, impaired functions of heart and circulation and muscle atrophy; coronavirus: lymphadenopathy and alterations in the abdomen. It was concluded that based on the clinical symptoms alone FIV-infection could not be diagnosed nor differentiated from the other 2 infections.", "journal": "Schweizer Archiv fur Tierheilkunde", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2164083", "author": "Zeidner NS", "n_authors": 7, "title": "Zidovudine in combination with alpha interferon and interleukin-2 as prophylactic therapy for FeLV-induced immunodeficiency syndrome (FeLV-FAIDS).", "abstract": "Zidovudine (3'-azido-3'-deoxythymidine; AZT) inhibited replication of an immunodeficiency-inducing strain of feline leukemia virus (FeLV-FAIDS) in vitro at concentrations of 0.5-0.005 micrograms/ml. A 25-30% additional antiviral effect was achieved in vitro when AZT was combined with human recombinant alpha interferon 2a (IFN alpha). Oral administration of AZT (20 mg/kg three times daily) to cats resulted in plasma concentrations of 3 micrograms/ml at 2 h post-administration with a T1/2 of approximately 1.60 h. Administration of AZT alone or in combination with IFN alpha or interleukin-2 (IL-2) throughout a 6-week treatment period enabled cats to resist challenge with FeLV-FAIDS. In contrast, those cats treated with IFN alpha or IL-2 alone became persistently antigenemic (core protein p27) in parallel with placebo-treated controls. Antigenemia remained undetectable in AZT-treated cats throughout an 80-day period post-inoculation (38 days after treatment was withdrawn). However, latent FeLV-FAIDS in bone marrow was detectable by in vitro culture of progenitor cells in the presence of hydrocortisone. Serial analysis of circulating p27 antigen, neutralizing antibody, and quantification of latent, reactivatable virus indicated that those animals receiving AZT in combination with IFN alpha were most able to resist FeLV-FAIDS challenge. This work provides additional evidence that early presymptomatic treatment employing combination chemoimmunotherapy can be effective in medical intervention of retroviral infection.", "journal": "Journal of acquired immune deficiency syndromes", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2162159", "author": "Matsumoto Y", "n_authors": 9, "title": "Molecular cloning of feline leukemia provirus genomes integrated in the feline large granular lymphoma cells.", "abstract": "Feline leukemia virus (FeLV) is a horizontally transmitted agent of the domestic cat which is known to be associated with wide spectrum of diseases of the hematopoietic system. In the present study, proviral DNAs of FeLV proviruses were examined in the tumor cells of natural killer cell lineage which is very rare in cats. In the chromosomal DNA of the tumor cells, 5 distinct bands corresponding to exogenous FeLV provirus genomes were detected by digestion with EcoRI which does not cut most FeLV isolates. Five clones of pLC1, pLC2, pLC3, pLC4, and pLC5 obtained from the 5 respective bands were analysed by restriction endonuclease mapping and Southern blot hybridization using gene-specific probes of FeLV. The results have clearly demonstrated that pLC4 and pLC5 contained large deletions in the pol and part of gag regions, while the full-length proviruses could be observed in pLC1 and pLC2. Furthermore, pLC3 contained part of a variant FeLV genome having an EcoRI site in its gag region. The molecular clones of defective and variant FeLV in this study may be useful for the further examination of tumorigenesis of large granular lymphoma in the cat.", "journal": "Archives of virology", "doi": "10.1007/BF01311052", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2159993", "author": "Shelton GH", "n_authors": 6, "title": "Feline immunodeficiency virus and feline leukemia virus infections and their relationships to lymphoid malignancies in cats: a retrospective study (1968-1988).", "abstract": "Sera from 353 cats with naturally occurring feline leukemia virus (FeLV) infection were collected in Boston, Los Angeles, New York City, and Seattle between 1968 and 1988. These sera were retrospectively assayed by enzyme-linked immunosorbent assay for antibodies to feline immunodeficiency virus (FIV). Fifty-one (14.4%) of the FeLV-positive sera had antibodies to FIV, indicating dual oncovirus and lentivirus infections. FIV infections were confirmed by Western blot analysis, antibodies against the 15 and 27 kDa proteins being used as definitive markers. FIV infection was diagnosed in one cat sampled in 1968 and in eight other cats sampled before 1975 in New York City. Illnesses exhibited by coinfected cats were similar to those of cats infected with FeLV only. Two unrelated cats with multicentric fibrosarcomas were found to be simultaneously infected with FIV, FeLV, and feline sarcoma virus. FIV was less contagious than FeLV in 73 cats residing in an exposure household between 1977 and 1980 as determined by evaluation of sera collected sequentially. In this household, 15 resident cats became FeLV infected whereas no cats contracted FIV infection. Comparison of serologic results from 53 cats with leukemia/lymphoma and matched controls confirmed a strong correlation between FeLV viremia and leukemia/lymphoma. A significant correlation between FIV infection and lymphoproliferative malignancies was also found independent of FeLV infection.", "journal": "Journal of acquired immune deficiency syndromes", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2158290", "author": "Dezzutti CS", "n_authors": 4, "title": "Inhibition of phorbol ester-induced neutrophil chemiluminescence by FeLV.", "abstract": "Receptor-mediated activation is accompanied by phospholipid metabolism and by calcium fluctuation resulting in a chemiluminescence (CL) response in the neutrophil. This pathway involves activation of protein kinase C (PKC) and the NADPH oxidase. Artificial stimulants such as phorbol esters, specifically 12-O-tetradecanylphorbol-13-acetate (TPA), circumvent the receptor-mediated pathway and activate PKC resulting in a measurable CL response. Neutrophils from feline leukemia virus (FeLV) exposed cats were tested for their ability to generate a TPA-induced CL response. As compared to the non-FeLV-exposed specific-pathogen-free (SPF) control cat neutrophil CL responses, both viremic and nonviremic FeLV-exposed cats showed significant decreases in their CL responsiveness. Neither ultraviolet light-inactivated FeLV (UV-FeLV) nor protein components (FeLV-p15E and FeLV-p27) caused a significant decrease in the CL responses of the SPF cat neutrophils. The suppressed TPA-induced CL response from FeLV-infected cats may involve an intracellular mechanism not affected in vitro by exposure of the neutrophil to the virus or viral components.", "journal": "Archives of virology", "doi": "10.1007/BF01310506", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2152775", "author": "Lopez NA", "n_authors": 4, "title": "Sensitivity, specificity, and predictive values of ClinEase-Virastat saliva test for feline leukemia virus infection.", "abstract": "Detection of virus in saliva using a commercial enzyme-linked immunosorbent assay (ELISA), ClinEase-VirastatR, was compared to evidence of FeLV infection by the indirect immunofluorescent antibody assay (IFA) and plasma ELISA. The sensitivity and specificity of the saliva ELISA were derived by comparison to IFA and plasma ELISA in 103 cats from a large colony in New York State. The sensitivity of the saliva test in relation to IFA and plasma ELISA was approximately 100% and 93%, respectively. The specificity of the saliva ELISA in relation to IFA and plasma ELISA was approximately 85% and 92%, respectively. This test appears to be particularly suitable as a screening test for FeLV infection, especially in populations where the expected prevalence is low. Because of its high sensitivity, the saliva test has a high negative predictive value, particularly in populations where the disease is rare. Since the specificity is moderate, however, the predictive value of a positive test will be poorest in cats originating from places where the infection is rare (e.g. single cat households, or free roaming cats), and better among cats from environments having a high prevalence of FeLV (e.g. multiple-cat households).", "journal": "The Cornell veterinarian", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "1980900", "author": "Pedersen NC", "n_authors": 4, "title": "Asymptomatic feline leukemia virus carrier cats have an enhanced susceptibility to feline immunodeficiency virus-induced disease.", "abstract": null, "journal": "Developments in biological standardization", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "1964030", "author": "Hoover EA", "n_authors": 3, "title": "Therapy of presymptomatic FeLV-induced immunodeficiency syndrome with AZT in combination with alpha interferon.", "abstract": "AZT inhibited replication of an immunodeficiency-inducing strain of feline leukemia virus (FeLV-FAIDS) in vitro at concentrations as low as 0.005 microgram/mL. This antiviral activity was augmented an additional 25-30% when AZT was combined with human recombinant alpha-interferon (2b) (IFN alpha). Administration of AZT alone or in combination with IFN alpha, beginning at the time of exposure to a 100% persistent viremia-inducing dose of FeLV-FAIDS, abrogated the progression of viral infection and protected treated animals from induction of persistent antigenemia and disease. Low levels of antigenemia were detected intermittently in some AZT-treated cats throughout the 6 week treatment and 40 week observation period. Combination of AZT with IFN alpha appeared even more effective than AZT alone. In this treatment group even transient antigenemia was undetectable throughout the therapy and posttherapy observation periods, and latent virus could not be reactivated from bone marrow cells of protected animals. These results provide additional evidence that early treatment with AZT or AZT/IFN alpha therapy can be effective in completely aborting retroviral infections.", "journal": "Annals of the New York Academy of Sciences", "doi": "10.1111/j.1749-6632.1990.tb17846.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "1697669", "author": "Majumder S", "n_authors": 3, "title": "Tyrosine protein kinase activity of the HZ4-feline sarcoma virus P80gag-kit-transforming protein.", "abstract": "The Hardy-Zuckerman 4 feline sarcoma virus (HZ4-FeSV), isolated from a feline fibrosarcoma, is a replication defective acute transforming feline retrovirus that originated by transduction of feline c-kit sequences with feline leukemia virus (FeLV). The v-kit sequences of the HZ4-FeSV, a segment of 1106 nucleotides, correspond to sequences of the cytoplasmic domain of the c-kit receptor kinase. The HZ4-FeSV is known to encode an 80-kilodalton protein with FeLV gag and kit determinants. The P80gag-kit protein and its associated activities from HZ4-FeSV-transformed mink cells were characterized. The P80gag-kit protein was found to be myristoylated, suggesting a membrane association for this protein. In agreement with the predicted relationship with tyrosine kinases, by using the in vitro immune complex-kinase procedure, the P80gag-kit protein was shown to display a tyrosine-specific autophosphorylation activity. In vivo, the P80 protein was found to be phosphorylated on serine and threonine and to a lesser degree on tyrosine. In addition, potential in vivo protein substrates for tyrosine-specific phosphorylation mediated by the P80gag-kit kinase were identified in HZ4-FeSV-transformed cells.", "journal": "Oncogene research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "1689371", "author": "Nick S", "n_authors": 6, "title": "Virus neutralizing and enhancing epitopes characterized by synthetic oligopeptides derived from the feline leukaemia virus glycoprotein sequence.", "abstract": "Synthetic peptides that mimic antigenic determinants of viral proteins were used in vaccine studies of feline leukaemia virus (FeLV) infection. Immunoreactive epitopes on FeLV gp70 and p15E were predicted according to the criteria of their terminal position, hydrophilicity and the probability of them constituting helical structures. Nineteen peptides, consisting of seven to 19 amino acid residues, were synthesized, of which two peptides were derived from the FeLV subtype A, 16 from subtype B and one from subtype C. Rabbits were immunized with individual peptides coupled to keyhole limpet haemocyanin and the specificity and biological activities of these hyperimmune sera were determined by ELISA, Western blotting, virus neutralization and cytotoxicity assays. All sera reacted specifically with the immunizing peptide. Twelve of the 19 peptides induced antibodies against purified gp85 and antibodies to 11 peptides reacted with the whole virus. One peptide representing the carboxy terminus of the transmembrane protein p15E, and two peptides derived from the external glycoprotein gp70 elicited neutralizing antibodies, whereas antisera against four peptides enhanced virus infection in vitro. None of the peptide antisera mediated complement lysis of FeLV-infected cells.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-71-1-77", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1768375", "author": "Elmslie RE", "n_authors": 7, "title": "Evaluation of a biologic response modifier derived from Serratia marcescens: effects on feline macrophages and usefulness for the prevention and treatment of viremia in feline leukemia virus-infected cats.", "abstract": "Normal feline bone marrow-derived macrophages released maximum concentrations of interleukin-6, tumor necrosis factor, and interleukin-1 when stimulated with ImuVert (Cell Technology Inc, Boulder, CO, USA) at dosages of 1.0 microgram/ml, 5.0 micrograms/ml, and 10.0 micrograms/ml, respectively. When ImuVert was administered to healthy adult cats, significant elevations in rectal temperature and neutrophil counts were observed 10 and 24 hours after each treatment. Weekly treatment with ImuVert failed to prevent or reverse viremia in cats when initiated prior to or 6 weeks after inoculation with feline leukemia virus.", "journal": "Molecular biotherapy", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1724122", "author": "Swenson CL", "n_authors": 5, "title": "Prophylactic and therapeutic effects of phosphonoformate against feline leukemia virus in vitro.", "abstract": "Phosphonoformate (PFA), a noncompetitive inhibitor of reverse transcriptase (RT), inhibited feline leukemia virus (FeLV) infection of 2 feline cell lines and inhibited progeny virus RT activity in a chronically FeLV-infected cell line. Feline leukemia virus infection of 3201 cells, an FeLV-negative lymphoma cell line, was inhibited by greater than 70% at a concentration of only 1 microM PFA and by greater than 90% at concentrations of 64 to 256 microM PFA, as evidenced by RT activity. However, FeLV antigen expression by 3201 cells remained relatively constant over noncytotoxic concentrations of PFA. Because the persistence of viral antigen expression with concomitant suppression of RT activity appears to be unique and because 3201 cells express small amounts of an endogenous retrovirus (RD-114) and contain endogenous FeLV proviral sequences, a possible role of endogenous retroviruses acting as helper viruses was suggested. Feline leukemia virus infection of 81C cells, a sarcoma-positive, leukemia-negative fibroblast cell line, was inhibited by greater than 50% at a concentration of 64 microM PFA and by greater than 98% at concentrations of 256 to 512 microM PFA, as indicated by suppression of focus formation. The feline lymphoid cell line FL-74 is a large producer of FeLV. When FL-74 cells were cultured in the presence of 256 microM PFA, virus production (virus budding and viral antigen) was not affected, but progeny virus lost RT activity and infectivity. Direct addition of PFA (256 microM) to FeLV also reduced RT activity and infectivity. These data indicate that PFA can directly and rapidly inactivate retrovirus independent of cellular processing, presumably by inhibiting RT.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1667194", "author": "Glennon PJ", "n_authors": 3, "title": "Prevalence of feline immunodeficiency virus and feline leukemia virus infections in random-source cats.", "abstract": "Retroviral serologic profiles were generated for 506 random-source cats (Felis catus) that were received by our facility during a twenty-month period. Feline leukemia virus antigens were detected in plasma samples from 26 (5.1%) of the cats. Antibodies to feline immunodeficiency virus were present in 24 (4.7%) of the samples tested. A single cat (0.2%) was positive for both viruses. Neither gender nor vendor correlation with retroviral seropositivity could be demonstrated.", "journal": "Laboratory animal science", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1661037", "author": "Gregory CR", "n_authors": 4, "title": "Feline leukemia virus-associated lymphosarcoma following renal transplantation in a cat.", "abstract": null, "journal": "Transplantation", "doi": "10.1097/00007890-199112000-00034", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1658356", "author": "Pandey R", "n_authors": 6, "title": "Recombination between feline leukemia virus subgroup B or C and endogenous env elements alters the in vitro biological activities of the viruses.", "abstract": "An important question in feline leukemia virus (FeLV) pathogenesis is whether, as in murine leukemia virus infection, homologous recombination between the infecting FeLV and the noninfectious endogenous FeLV-like proviruses serves as a significant base for the generation of proximal pathogens. To begin an analysis of this issue, several recombinant FeLVs were produced by using two different approaches: (i) the regions of the viral envelope (env) gene of a cloned FeLV (subgroup B virus [FeLV-B], Gardner-Arnstein strain) and those of two different endogenous proviral loci were exchanged to create specific FeLV chimeras, and (ii) vectors containing endogenous env and molecularly cloned infectious FeLV-C (Sarma strain) DNA sequences were coexpressed by transfection in nonfeline cells to facilitate recombination. The results of these combined approaches showed that up to three-fourths of the envelope glycoprotein (gp70), beginning from the N-terminal end, could be replaced by endogenous FeLV sequences to produce biologically active chimeric FeLVs. The in vitro replication efficiency or cell tropism of the recombinants appeared to be influenced by the amount of gp70 sequences replaced by the endogenous partner as well as by the locus of origin of the endogenous sequences. Additionally, a characteristic biological effect, aggregation of feline T-lymphoma cells (3201B cell line), was found to be specifically induced by replicating FeLV-C or FeLV-C-based recombinants. Multiple crossover sites in the gp70 protein selected under the conditions used for coexpression were identified. The results of induced coexpression were also supported by rapid generation of FeLV recombinants when FeLV-C was used to infect the feline 3201B cell line that constitutively expresses high levels of endogenous FeLV-specific mRNAs. Furthermore, a large, highly conserved open reading frame in the pol gene of an endogenous FeLV provirus was identified. This observation, particularly in reference to our earlier finding of extensive mutations in the gag gene, reveals a target area for potentially productive homologous recombination upstream of the functional endogenous env gene.", "journal": "Journal of virology", "doi": "10.1128/JVI.65.12.6495-6508.1991", "deposited_data": "Sim", "nuccore_ids": "163853", "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1724772", "author": "Hardy WD Jr", "n_authors": 1, "title": "General principles of retrovirus immunodetection tests.", "abstract": "Because infecting retroviruses contain protein and glycoprotein antigenic determinants that can be readily distinguished from host cell determinants, the development of immunologic detection systems, immunodetection tests, or immunoassays capable of identifying antigens of some retroviruses (oncoretroviruses) in blood, body fluids, or cells is possible. Conversely, detection of antibodies produced by animals against some infecting retroviruses can also be used to identify current infections of lentiretroviruses and some oncoretroviruses. Studies of various microorganisms by various immunodetection systems indicate that the most specific and sensitive assays are immunofluorescence, radioimmunoassay, and immunoblot (western blot) analysis, followed by sensitive but less specific ELISA and agglutination assays, and finally by even less sensitive but very specific isolation in culture and double immunodiffusion techniques. The first test used routinely for clinical detection of any retrovirus was the immunofluorescent antibody test, introduced in 1972, for detection of FeLV infection in pet cats. Since then, tests for human retroviruses, the human immunodeficiency virus types 1 and 2 (HIV-1 and HIV-2 and the human T-cell lymphotropic virus types I and II (HTLV-I and HTLV-II) have been introduced for routine use in human medicine. Recently, retroviral tests for a second feline retrovirus, the feline immunodeficiency virus (FIV) have been introduced in veterinary medicine. General principles of sensitivity, specificity, true-positive and -negative rates, false-positive and -negative rates, and positive and negative predictive values apply to all methods used for detection of retroviral infections.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666084", "author": "Hardy WD Jr", "n_authors": 2, "title": "Ten-year study comparing enzyme-linked immunosorbent assay with the immunofluorescent antibody test for detection of feline leukemia virus infection in cats.", "abstract": "Immunodetection tests for feline retroviruses are powerful tools used in modern veterinary practice. Veterinarians must fully understand the characteristics--strengths and weaknesses--of the FeLV tests so that the information gained from them can be used properly. Any FeLV ELISA or immunofluorescent antibody (IFA) test is a method for detection of FeLV infection (the virus) and is not a diagnostic test for leukemia or other feline disease. From previous studies, it was determined that the most accurate test for detection of persistent FeLV infection is the IFA test, which detects FeLV antigens in cytoplasm of leukocytes in the blood of infected cats. In the study reported here, 1,142,600 FeLV IFA tests were performed between June 1972 and December 1990. During this period 19.8% of the IFA test results were positive and 78% were negative. Evaluation was not possible for the remaining 2.2% of the tests because of lack of enough leukocytes in the smears to evaluate, or nonspecific staining reactions. In 1979, 7 years after introduction of the IFA test, in-hospital FeLV ELISA were introduced, which enabled veterinarians to test for FeLV in their hospitals. Ever since that time, continual discrepancies have been reported between results of FeLV ELISA and IFA tests, particularly between positive ELISA results and their IFA test confirmation. A 10-year comparison was made between practitioner-performed in-hospital FeLV ELISA (n = 20, 240 tests) results and FeLV IFA test performed by a commercial laboratory. All samples tested by ELISA were submitted (for confirmation of results) by veterinarians from the United States, Canada, Europe, Japan, and Australia.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666080", "author": "O'Connor TP Jr", "n_authors": 3, "title": "Report of the National FeLV/FIV Awareness Project.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666076", "author": "Hardy WD Jr", "n_authors": 2, "title": "Development of the immunofluorescent antibody test for detection of feline leukemia virus infection in cats.", "abstract": "Studies of the immunodetection of various microorganisms by various assay systems indicated that the most specific and sensitive assays are immunofluorescence, radioimmunoassay, and immunoblot analysis (western blot), followed by sensitive but less specific ELISA and agglutination assays and, finally, by even less sensitive but very specific virus isolation and double immunodiffusion techniques. The first test for the clinical detection of FeLV infection in pet cats was the immunofluorescent antibody (IFA) test, which was introduced in 1972. The FeLV test is used for detection for FeLV infection and not as a test for leukemia or any other feline disease. The IFA test was compared with an immunodiffusion (ID) test and with tissue culture isolation (TCI) of the virus in 26 cats to establish a standard for FeLV tests. Excellent correlation was observed between the IFA and the ID tests (100%).", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1724773", "author": "Tizard I", "n_authors": 1, "title": "Use of immunomodulators as an aid to clinical management of feline leukemia virus-infected cats.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1686876", "author": null, "n_authors": 0, "title": "Colloquium on feline leukemia virus/feline immunodeficiency virus: tests and vaccination. Orlando, Florida, March 1-3, 1991.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666107", "author": "Weiss RC", "n_authors": 3, "title": "Low-dose orally administered alpha interferon treatment for feline leukemia virus infection.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666106", "author": "August JR", "n_authors": 1, "title": "Husbandry practices for cats infected with feline leukemia virus or feline immunodeficiency virus.", "abstract": "Cats that are persistently infected with FeLV or feline immunodeficiency virus but are not manifesting clinical signs of disease are at risk for developing a wide variety of immunosuppressive, degenerative, or neoplastic diseases. Infected cats should be isolated to prevent transmission of virus to healthy cats, and to protect infected cats from exposure to pathogens that can cause life-threatening secondary infections. Iatrogenic transmission of virus from infected cats in isolation to healthy cats may be reduced by strict adherence to handling, sanitation, and disinfection procedures. Husbandry practices that may delay the complications of infection include regular vaccination, provision of high-quality diets, reduction of stress, control of endoparasites and ectoparasites, and early and aggressive treatment of clinical signs of disease.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666105", "author": "Cotter SM", "n_authors": 1, "title": "Management of healthy feline leukemia virus-positive cats.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666104", "author": "Hawks DM", "n_authors": 7, "title": "Antibody response of kittens after vaccination followed by exposure to feline leukemia virus-infected cats.", "abstract": "Protein (western) blot analysis and virus-neutralization assay were used to evaluate the antibody response of specific-pathogen-free kittens to FeLV vaccination and followed by natural exposure. Several kittens had barely detectable reactions to specific FeLV antigens prior to vaccination or exposure. Correlation was not found between protection against persistent viremia and antibody response after vaccination as measured by western blot analysis or virus neutralization assay. A statistically significant (P less than 0.01) difference in the antibody response against p27 antigen after natural exposure to FeLV was observed between persistently viremic kittens and transiently viremic or aviremic kittens. Measurable (P less than 0.05) virus neutralizing antibody titer after FeLV exposure was found only in a small number of kittens that were protected against persistent viremia. Lack of association between humoral response and vaccination-induced protection against persistent FeLV infection suggests an important role for cell-mediated immunity in such protection.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666103", "author": "Legendre AM", "n_authors": 7, "title": "Comparison of the efficacy of three commercial feline leukemia virus vaccines in a natural challenge exposure.", "abstract": "Forty-seven kittens were exposed for 31 weeks to 12 FeLV-positive carrier cats. The carrier cats were infected with 2 laboratory strains of FeLV and at least 2 strains of street virus. Eleven nonvaccinated control kittens and 12 vaccinated kittens were allotted to 3 groups. After 31 weeks of exposure, the following kittens were persistently blood FeLV positive by ELISA and immunofluorescence antibody (IFA) testing: 7 of the 11 control kittens, 0 of 12 kittens inoculated with vaccine A, 5 of 12 kittens inoculated with vaccine B, and 6 of 12 kittens inoculated with vaccine C. Only the kittens inoculated with vaccine A were significantly (P less than 0.05) different from the control group. After 23 weeks of exposure, culture was done to identify FeLV in the bone marrow of the kittens. Feline leukemia virus was isolated from the bone marrow of 9 of 11 control kittens. Virus was isolated from the bone marrow of 5 of 12 kittens inoculated with vaccine A, 11 of 12 kittens inoculated with vaccine B, and 10 of 12 kittens inoculated with vaccine C. Of the 17 cats that had FeLV isolated only from culture of bone marrow (negative results of blood virus isolation, ELISA, and IFA testing), 13 eliminated the virus from the bone marrow by week 31 of exposure. After 31 weeks of exposure, FeLV was isolated from the bone marrow of 8 of 11 control kittens, 0 of 12 kittens inoculated with vaccine A, 7 of 12 kittens inoculated with vaccine B, and 7 of 12 kittens inoculated with vaccine C.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666102", "author": "Pedersen NC", "n_authors": 2, "title": "Comparative efficacy of three commercial feline leukemia virus vaccines against methylprednisolone acetate-augmented oronasal challenge exposure with virulent virus.", "abstract": "Three commercial FeLV vaccines, (A, B, and C) were purchased on the open market and administered to 8- to 20-week-old specific-pathogen-free kittens, according to manufacturers' instructions. A similar group of nonvaccinated kittens served as controls. All kittens were challenge-exposed oronasally with virulent FeLV 4 weeks after the final vaccination. Serum samples were monitored for FeLV-p27 antigenemia using an ELISA at 1- to 2-week intervals for at least 16 weeks after the last day of challenge exposure. Kittens that were either transiently (1 to 4 weeks) or never viremic during this period were counted as recovered, whereas kittens that became viremic and retained viremia for at least 10 weeks were counted as persistently viremic. The 3 vaccines were found to be 39% (vaccine C), 28% (vaccine B), and 17% (vaccine A) efficacious in preventing persistent viremia in immunized, compared with nonimmunized kittens.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666101", "author": "Lehmann R", "n_authors": 6, "title": "Vaccination of cats experimentally infected with feline immunodeficiency virus, using a recombinant feline leukemia virus vaccine.", "abstract": "A group of 15 cats experimentally infected with a Swiss isolate of feline immunodeficiency virus (FIV) and a group of 15 FIV-negative control cats were inoculated with an FeLV vaccine containing recombinant FeLV-envelope. High ELISA antibody titer developed after vaccination in FIV-positive and FIV-negative cats. Vaccinated and nonvaccinated controls were later challenge exposed by intraperitoneal administration of virulent FeLV subtype A (Glasgow). Although 12 of 12 nonvaccinated controls became infected with FeLV (10 persistently, 2 transiently), only 1 of 18 vaccinated (9 FIV positive, 9 FIV negative) cats had persistent and 2 of 18 had transient viremia. From these data and other observations, 2 conclusions were drawn: In the early phase of FIV infection, the immune system is not depressed appreciably, and therefore, cats may be successfully immunized; a recombinant FeLV vaccine was efficacious in protecting cats against intraperitoneal challenge exposure with FeLV.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666100", "author": "Osterhaus AD", "n_authors": 5, "title": "Toward vaccination against feline leukemia virus and feline immunodeficiency virus infections.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666099", "author": "Clark N", "n_authors": 6, "title": "Efficacy and safety field trials of a recombinant DNA vaccine against feline leukemia virus infection.", "abstract": "A new recombinant gp70 vaccine was found to be safe and effective for prevention of infection by FeLV. The vaccine incorporates a unique purified saponin adjuvant with the recombinant antigen. Serious systemic reactions were not observed during the efficacy trial. Local reactions were transient and mild. More than 2,000 doses were administered to a cross section of household cats in a field safety trial. Only 1 cat had hypersensitivity reaction, which resolved. Among veterinarians who used the vaccine and the cat owners, the vaccine was judged satisfactory and safe. After rigorous intraperitoneal challenge exposure without use of immunosuppressants, 100% of the controls in the efficacy trial became infected, 70% of which remained persistently infected with FeLV. Among vaccinates, 45% were never viremic and 40% cleared transient infection within 12 weeks after challenge exposure. Of the 20 vaccinated cats, 3 were persistently infected. Overall, 85% of cats vaccinated with this recombinant DNA FeLV vaccine resisted persistent FeLV infection after stringent challenge exposure, which translates to preventable fraction of 78.6%.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666098", "author": "Scarlett JM", "n_authors": 2, "title": "Year two of follow-up evaluation of a randomized, blind field trial of a commercial feline leukemia virus vaccine.", "abstract": "A blind randomized field trial of a commercial FeLV vaccine was conducted. Cats on study were vaccinated with either a commercial FeLV vaccine or a placebo, then housed with FeLV-positive cats in a ratio of approximately 2 study cats to 1 infected cat (results of the first 12 months of the study have been reported). All surviving placebo-treated and FeLV-vaccinated cats were re-vaccinated 1 year after initial exposure to FeLV-infected cats. Exposure continued for an additional 12 months, and the viremia status of the cats was monitored by immunofluorescent antibody (IFA) and ELISA testing at 4-month intervals. During the second year of observation, 1 additional FeLV-vaccinated cat had positive results of 2 consecutive ELISA tests, but remained IFA negative. Classifying this cat as persistently viremic reduced the estimate of the preventable fraction, but did not alter the conclusions drawn earlier, viz, that vaccination appreciably reduces the number of cats that become persistently viremic after long-term natural exposure.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666097", "author": "Hines DL", "n_authors": 4, "title": "Evaluation of efficacy and safety of an inactivated virus vaccine against feline leukemia virus infection.", "abstract": "An inactivated virus vaccine was developed for prevention of FeLV infection in domestic cats. When given in 2 doses, 3 weeks apart, to cats that were greater than or equal to 9 weeks old at the time of first vaccination, the vaccine prevented persistent viremia from developing in 132 of 144 (92%) vaccinates after oronasal challenge exposure with virulent FeLV. In contrast, persistent viremia developed after oronasal challenge exposure with FeLV in 39 of 45 (87%) age-matched nonvaccinated control cats. Transient viremia, indicated by early detection of p27 by ELISA in serum of cats protected from persistent viremia at 12 weeks after challenge exposure, was found in 10 of 132 (8%) vaccinates. Cats that were aviremic 12 to 16 weeks after challenge exposure were examined for reactivation of latent FeLV infection; 4 weekly doses of methylprednisolone were administered, followed by in vitro culture of bone marrow cells. Latent infection was readily reactivated in 6 of 8 (75%) nonvaccinated control cats that had been transiently viremic after challenge exposure. However, latent infection was reactivated in only 5 of 48 (10%) protected vaccinates, and in none of 38 vaccinates in which transient viremia had not been detected. In a safety field trial, only 34 mild reactions of short duration were observed after administration of 2,379 doses of vaccine to cats of various ages, breeds, and vaccination history, for a 1.43% reaction rate. Results indicate that the aforementioned inactivated virus vaccine is safe and efficacious for the prevention of infection with FeLV.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666096", "author": "Kensil CR", "n_authors": 9, "title": "Development of a genetically engineered vaccine against feline leukemia virus infection.", "abstract": "A genetically engineered subunit vaccine against FeLV infection was developed. The protective immunogen in the vaccine was a purified recombinant protein containing the entire amino acid sequence of FeLV subgroup A gp70 envelope protein. The optimal adjuvant was determined to be a highly purified saponin, QS-21, derived from Quillaja saponaria Molina. A vaccine formulation containing the recombinant protein, QS-21, and aluminum hydroxide was tested in specific-pathogen-free kittens and was shown to induce neutralizing antibodies as well as appreciable antibody responses to native gp70 by enzyme immunoassay and protein (western) immunoblot analysis and of whole virus preparations.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666095", "author": "York SM", "n_authors": 2, "title": "Development of a whole killed feline leukemia virus vaccine.", "abstract": "A whole killed FeLV vaccine was developed. By use of a chromatography method of purification and concentration, the resulting vaccine has been shown to be significantly lower in bovine serum albumin and total protein contents than were the same ingredients in the starting materials. The virus was inactivated or killed as an essential part of the vaccine development process. Vaccination trials with the vaccine without use of adjuvants indicated appreciable virus-neutralizing serum titer (greater than or equal to 1:10) in 107 of 110 vaccinated cats. Of 43 cats vaccinated and subsequently challenge exposed with virulent FeLV, only 2 developed persistent virus antigenemia (longer than 1 month), whereas 14 of 22 nonvaccinated control cats developed persistent viremia. In field tests, 2,770 cats from 6 states were vaccinated and observed. Postvaccinal reactions were not observed.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666094", "author": "Sebring RW", "n_authors": 8, "title": "Feline leukemia virus vaccine development.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666093", "author": "Tizard I", "n_authors": 2, "title": "Evaluation of a killed, whole virion feline leukemia virus vaccine.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666092", "author": "Pollock VH", "n_authors": 2, "title": "Review of the first feline leukemia virus vaccine.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666091", "author": "Shibley GP", "n_authors": 3, "title": "United States Department of Agriculture licensing requirements for feline leukemia virus vaccines.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666090", "author": "Hoover EA", "n_authors": 8, "title": "Protection against feline leukemia virus infection by use of an inactivated virus vaccine.", "abstract": "The protective immunity induced by 3 experimental FeLV vaccines were evaluated: Prototype inactivated FeLV vaccine developed from a molecularly cloned FeLV isolate (FeLV-FAIDS-61E-A); a mixture of immunodominant synthetic peptides corresponding to regions of the FeLV-Gardner-Arnstein-B (FeLV-GA-B) envelope proteins; and an adjuvant-disrupted but non-activated virus prepared from a non-cloned FeLV field isolate comprised of subgroup A and B viruses (FeLV-05821-AB). Included as controls were parallel groups of cats inoculated with adjuvants alone or with an established commercial FeLV vaccine. After each inoculation and after virulent virus challenge exposure, sera from all cats were assayed for ELISA-reactive antibody against purified FeLV, FeLV neutralizing (VN) antibody, and FeLV antigenemia/viremia--viral p27 antigen in serum and within circulating leukocytes. Immunity was challenged by oral/nasal exposure of vaccinated and control cats with FeLV-FAIDS-61E-A or FeLV-05821-AB, an infective, noncloned, tissue-origin, FeLV field isolate containing subgroup-A and -B viruses. Vaccine-induced immunity was assessed by comparing the postchallenge-exposure incidence of persistent viremia and the pre- and postchallenge exposure titers of VN and ELISA antibody in cats of the control and vaccine groups. The percentage of cats, that resisted development of persistent viremia after FeLV challenge exposure and the preventable fraction (PF) for the vaccine groups (which adjusts for the severity of the challenge and the degree of innate resistance in the controls) were as follows: adjuvant controls, 26%; FeLV-FAIDS-61E-A inactivated virus vaccine, 95% (PF = 93.2%); FeLV-GA-B peptide vaccine, 5% (-28.4%); FeLV-05821-AB noninactivated vaccine, 67% (55.4%); and commercial FeLV vaccine, 35% (12.2%). The prechallenge exposure mean VN antibody titer for each group was: less than 1:8 in the adjuvant controls; 1:43 in the FeLV-FAIDS-61E-A-vaccinated cats; less than 1:8 in the peptide-vaccinated cats; 1:38 in the noninactivated virus-vaccinated cats group; and 1:12 in the cats vaccinated with the commercial vaccine. Thus, induction of VN antibody in the vaccinated cats, although modest, appeared to be correlated with induction of protective immunity as defined by resistance to FeLV challenge exposure. Results of these studies indicate that inoculation of cats with an experimental inactivated virus vaccine prepared from a molecularly cloned FeLV isolate was most effective in stimulating protective immunity against heterologous and homologous FeLV challenge exposure.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666089", "author": "Jacobson RH", "n_authors": 2, "title": "Comparative study of diagnostic testing for feline leukemia virus infection.", "abstract": "Results of commercially available diagnostic test kits and commercial laboratory test results were compared for ability to detect FeLV antigen. Results of the immunofluorescent antibody (IFA) test were compared with test kit ELISA results and with results of a system in which samples were applied to an absorbent material, dried, sent to a laboratory, eluted, and assayed by a plate ELISA. Test kits were generally highly sensitive and specific, compared with the IFA test performed at a commercial laboratory. Feline heterophile antibody, specific for mouse immunoglobulin, was detected in approximately 0.14 to 0.57% of the cat population. Test kits B, E, and D contain reagents that correct for antimouse antibodies. During 1989 and 1990, 2,229 feline serum samples were tested for FeLV antigen (gsa p27); positive ELISA results were obtained for 204 (9%) of the samples. Results for 32 (1.4%) samples were interpreted as equivocal (color development slightly exceeded that of the negative control, but was much less than that of the positive control). Collectively, the data indicate that when testing serum or saliva, a negative test result may be a good predictor that a cat is not infected. In populations of cats in which FeLV prevalence is low, a positive test result may not be reliable and thus, a confirmatory test should be performed.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666088", "author": "Swango LJ", "n_authors": 1, "title": "Evaluation of feline leukemia virus diagnostic tests available for in-office use by veterinarians.", "abstract": "Blood samples from cats were tested for FeLV group-specific antigen by use of an indirect immunofluorescent antibody (IFA) test, ELISA, or both. Several ELISA kits were evaluated as they would be used in a veterinary clinic, and some ELISA kits were compared with an IFA test for agreement of results. Good agreement of results was evident among the commercially available ELISA kits; results for most blood samples were clearly negative or decidely positive. Occasionally, test results were equivocal and retesting was necessary to obtain clear interpretation. Negative results are highly reliable, which makes ELISA valuable screening tests for FeLV in healthy cats. Results of tests on blood from healthy cats in Alabama indicated positivity rate of 4.0% in 1978 with an IFA test and 4.8% with ELISA in 1988 through 1989. Infection rate in sick cats ranged from 11.6 to 35.8%. The frequency of positive test results for FeLV in cats tested at Auburn University decreased from a 5-year average of 27.7% during 1980 through 1984 to a 5-year average of 14.9% during 1986 through 1990; the rate in 1990 was 11.6%.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666087", "author": "Hawkins EC", "n_authors": 1, "title": "Saliva and tear tests for feline leukemia virus.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666085", "author": "Hawks DM", "n_authors": 3, "title": "Comparison of four test kits for feline leukemia virus antigen.", "abstract": "The sensitivity and specificity of 4 commercial FeLV ELISA kits, using blood, were compared with results of virus isolation from blood and immunofluorescent antibody (IFA) testing on blood. Significant differences were not found among the 4 ELISA kits. Marked decrease in sensitivity of the ELISA kits was detected when virus isolation was used as the standard of positivity rather than the IFA test. Virus isolation was a more sensitive indicator of early infection, with marked discrepancy among results obtained by virus isolation, ELISA, and the IFA test. Results became progressively more concordant as infection became fully established. Cats FeLV-positive by virus isolation alone were more likely to eliminate viremia. All cats FeLV-positive by IFA testing remained persistently viremic. Virus isolation, ELISA, and IFA testing appear to differ in their prognostic value. The use of blood rather than serum for the ELISA resulted in several discordant results. Six cats were FeLV-positive by ELISA when blood was tested but were FeLV-negative when serum was tested. Positive ELISA results were obtained for 4 of these cats when serum was tested, using extended incubation to increase sensitivity. It is possible that blood may actually be more sensitive than serum for use of the ELISA method.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666083", "author": "Jarrett O", "n_authors": 4, "title": "Comparison of diagnostic methods for feline leukemia virus and feline immunodeficiency virus.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666082", "author": "Hutson CA", "n_authors": 3, "title": "Neoplasia associated with feline immunodeficiency virus infection in cats of southern California.", "abstract": "Between 1988 and 1991, feline immunodeficiency virus (FIV) infection status was evaluated in 1,160 cats examined at an oncology referral and general practice in Los Angeles, California. Twenty-nine (2.5%) cats were FIV positive. Neoplasia was present in 18 of the 29 (62%) cats. Sampling for neoplasia was intentionally biased in the oncology referral group. However, 33% (6/18) of FIV-infected cats with neoplasia originated from the general practice. Three neoplastic processes were observed; myeloproliferative disease (MPD; 5/18), lymphoma (LSA; 5/18), and squamous cell carcinoma (SCC; 7/18). One cat had LSA and SCC. Extranodal sites of LSA were common (66%) in FIV-infected cats. Sites of LSA were submandibular and mesenteric lymph nodes, liver, kidneys, periorbital area, and diffuse (heart, pancreas, bladder). Sites of SCC were sublingual (n = 2), nasal planum (n = 3), nasal planum and eyelids (n = 1), and mandible (n = 2). Feline leukemia virus co-infection was observed in 17% (5/29) of FIV-infected cats. The FIV-infected cats with MPD were young (range, 8 months to 13 years; median, 4 years) and had short survival duration (2, 6, 21, 134, 249 days) even in response to aggressive treatment. The FIV-infected cats with LSA were older (median age, 8 years; range, 4 to 14 years) and survived 60 days if untreated. Cats administered chemotherapy survived 39, 45, 217, and 243 days; the latter 2 cats had partial remission of 2 months' duration. Older FIV-infected cats had SCC (median age, 12 years; remission range, 7 to 16 years) because of more frequent association of both diseases in older cats with outdoor environment.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666078", "author": "Egberink HF", "n_authors": 3, "title": "Use of western blot and radioimmunoprecipitation for diagnosis of feline leukemia and feline immunodeficiency virus infections.", "abstract": "The uses and limitations of the western blot (WB) and radioimmunoprecipitation assay (RIPA) techniques for study of feline immunodeficiency virus (FIV) and FeLV were evaluated. Western blot analysis was used to detect antigenic relatedness between the 2 lentiviruses. Using a rabbit serum directed against p26 of the equine infectious anemia virus (EIAV) and anti-EIAV horse serum obtained from an infected horse, cross-reactivity with p24 of FIV was revealed. Cat sera obtained late after experimentally induced FIV infection recognized p26 of EIAV, which indicates reciprocal cross-reactivity. For RIPA, FIV was metabolically labeled, and virus-coded proteins were identified, using immunoprecipitation. Polypeptides with apparent molecular mass of about 15, 24, 43, 50, 120, and 160 kilodaltons were detected. An additional polypeptide of 10 kilodaltons was found only by use of WB analysis.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666077", "author": "Tonelli QJ", "n_authors": 1, "title": "Enzyme-linked immunosorbent assay methods for detection of feline leukemia virus and feline immunodeficiency virus.", "abstract": "Enzyme-linked immunosorbent assays have been widely used for diagnosis of FeLV and feline immunodeficiency virus (FIV) infections. Various ELISA kits for FeLV are available from several manufacturers. Although these tests are configured in a variety of formats, they are all direct antigen-detection systems for the viral core protein p27. On the other hand, ELISA for FIV exposure detects specific feline antibody to FIV. Basic immunoassay principles and the application of ELISA technology used in FeLV and FIV ELISA kits are described.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666075", "author": "Morgan AP", "n_authors": 1, "title": "Regulatory considerations for licensing feline leukemia virus antigen or antibody test kits.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666074", "author": "Charreyre C", "n_authors": 2, "title": "Study of feline leukemia virus immunity.", "abstract": "Fifteen specific-pathogen-free cats were experimentally infected with FeLV; 8 cats recovered after transient or nondetectable viremia, and 7 cats became persistently viremic. Four additional cats served as noninfected controls. Antibodies to whole FeLV (ELISA and immunoblot [western] analysis), antibodies to fixed FeLV-infected cells, and virus-neutralizing antibodies were monitored for as long as 3 years after infection. As a group, cats that recovered after acute infection developed higher titer of these various antibodies than did cats that became persistently viremic. However, specific combination or titer of antibodies was not always found in recovered cats or in persistently viremic cats. Six cats that had recovered from acute FeLV infection nearly 3 years earlier were reinfected with the same virus. Three of the cats appeared to be resistant to reinfection, 2 cats became transiently viremic, and 1 cat became persistently viremic. Slight and transient anamnestic ELISA-detectable antibody response to whole virus was seen after reinfection; immunofluorescence- and western blot-detectable responses were not greatly enhanced. Five FeLV-recovered cats were monitored for 2 years; FeLV infection spontaneously recurred in 1 cat.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666073", "author": "Tompkins MB", "n_authors": 4, "title": "Early events in the immunopathogenesis of feline retrovirus infections.", "abstract": "Feline leukemia virus and feline immunodeficiency virus (FIV) are lymphotropic retroviruses that cause a wide range of diseases in domestic cats. Although it is known that both viruses are capable of infecting T lymphocytes and that infected cats are lymphopenic, it was not known how infection with either virus might alter specific lymphocyte subpopulations. Using a panel of monoclonal antibodies to feline lymphocyte subpopulations, we examined, by use of flow cytometric analysis, lymphocyte changes in cats naturally infected with FeLV or FIV and explored the early stages in the immunopathogenesis of experimentally induced infection with these viruses. Both groups of naturally infected cats had T-cell lymphopenia. In the FIV-infected cats, the T-cell decrease was principally attributable to loss of CD4+ cells, whereas CD8+ and B-cell numbers remained normal. This led to inversion of the CD4+ to CD8+ ratio in these cats. In contrast, the T-cell lymphopenia in FeLV-infected cats resulted from decrease in CD4+ and CD8+ cells, which led to a CD4+ to CD8+ ratio within normal limits. Experimentally induced infection with these 2 viruses supported these findings. Infection with FIV induced early (10 weeks after infection), chronic inversion of the CD4+ to CD8+ ratio. In contrast, infection with FeLV did not alter CD4+ to CD8+ ratio in the first 20 weeks after infection.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666072", "author": "Rojko JL", "n_authors": 2, "title": "Pathogenesis of infection by the feline leukemia virus.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666070", "author": "Hoover EA", "n_authors": 2, "title": "Feline leukemia virus infection and diseases.", "abstract": "Feline leukemia virus is a naturally occurring, contagiously transmitted and oncogenic immunosuppressive retrovirus of cats. The effects of FeLV are paradoxical, causing cytoproliferative and cytosuppressive disease (eg, lymphoma and myeloproliferative disorders vs immunodeficiency and myelosuppressive disorders). In the first few weeks after virus exposure, interactions between FeLV and hemolymphatic system cells determine whether the virus or the cat will dominate in the host/virus relationship--persistent viremia and progressive infection or self limiting, regressive infection will develop. The outcome of these early host/virus interactions is revealed in the diagnostic assays for FeLV antigenemia and viremia. The latter, in turn, predict the outcome of FeLV infection in cats. Known host resistance factors include age and immune system functional status. Known virus virulence factors are magnitude of exposure and virus genotype. Molecular analysis of FeLV strains indicated that natural virus isolates exist as mixtures of closely related virus genotypes and that minor genetic variations among FeLV strains can impart major differences in pathogenicity. The genetic coding regions responsible for cell targeting and specific disease inducing capacity (eg, thymic lymphoma, acute immunosuppression, or aplastic anemia) have been mapped to the virus surface glycoprotein and/or long terminal repeat regions for several FeLV strains. Infection by specific FeLV strains leads to either malignant transformation or cytopathic deletion of specific lymphocyte and hemopoietic cell population, changes that prefigure the onset of clinical illness. Another notable feature of the biology of FeLV is that many cats are able to effectively contain and terminate viral replication, an important example of host immunologic control of a retrovirus infection and a process that can be selectively enhanced by vaccination. Thus, FeLV infection serves as a natural model of the multifaceted pathogenesis of retroviruses and as a paradigm for immunoprophylaxis against an immunosuppressive leukemogenic retrovirus.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666069", "author": "Jarrett O", "n_authors": 1, "title": "Overview of feline leukemia virus research.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1666068", "author": null, "n_authors": 0, "title": "Panel report on the colloquium on feline leukemia virus/feline immunodeficiency virus: tests and vaccination.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1664674", "author": "Wellman ML", "n_authors": 3, "title": "Variable suppression of feline bone marrow fibroblast colony-forming units by two isolates of feline leukemia virus.", "abstract": "Bone marrow fibroblast colony-forming units (CFU-F) were evaluated in cats experimentally infected with different, isolates of FeLV. Cats infected with the Kawakami-Theilen isolate of FeLV (FeLV-KT) had progressive decrease in the number of CFU-F at 2, 4, and 6 weeks after infection. The number of CFU-F in FeLV-KT-infected cats ranged from 38 to 70% of the preinoculation CFU-F value. Of 3 cats with FeLV-KT-induced suppression of CFU-F, 2 developed fatal nonregenerative anemia. Cats infected with the Rickard isolate of FeLV (FeLV-R) had more moderate decrease in the number of CFU-F at 2, 4, and 6 weeks after infection. The number of CFU-F in FeLV-R-infected cats ranged from 62 to 82% of the preinoculation CFU-F value. The FeLV-R-infected cats did not become anemic.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1758037", "author": "McOrist S", "n_authors": 6, "title": "Some viral and protozool diseases in the European wildcat (Felis silvestris).", "abstract": "Ten European wildcats (Felis silvestris) were examined at necropsy and an additional 23 were examined clinically for evidence of viral diseases in Scotland. Two plasma samples taken from live free-living wildcats showed positive ELISA reactions to feline leukemia antigen. A feline leukemia virus of subgroup A was isolated from one of these samples, taken from a wildcat in north-western Scotland. No antibodies to feline coronavirus or feline immunodeficiency virus were detected in any sample. Three of the live wildcats and one of the dead had chronic mucopurulent rhinotracheitis suggestive of \"cat flu.\" One other dead wildcat had diffuse enlargement of anterior lymph nodes. The findings indicated that feline leukemia virus infection can occur in free-living Felis silvestris. It is possible that the disease exists as a sustained infection in some wildcat populations, although the close interaction between wildcat and the domestic cat means that the latter could act as a continual source of infection.", "journal": "Journal of wildlife diseases", "doi": "10.7589/0090-3558-27.4.693", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1662026", "author": "Mathes LE", "n_authors": 6, "title": "Evaluation of antiviral activity and toxicity of dextran sulfate in feline leukemia virus-infected cats.", "abstract": "The feline leukemia virus (FeLV) disease model was used to conduct a toxicity and antiretrovirus efficacy trial of dextran sulfate (DS; molecular mass, 7,000 to 8,000 Da). In vitro, FeLV infection of feline lymphoid cells was inhibited by 10 micrograms of DS per ml. DS was administered to cats by continuous intravenous infusion at doses of 600, 120, 24, or 4.8 mg/kg of body weight per day, beginning 24 h before FeLV challenge. Doses of 24 mg/kg/day and more were excessively toxic, causing intestinal lesions and death. Similar changes were observed in unchallenged animals receiving 24 mg/kg/day, indicating that toxicity was DS mediated. The dosage of 4.8 mg/kg/day was subtoxic but did not prevent the induction and persistence of FeLV viremia. The results demonstrate that DS by continuous intravenous infusion is excessively toxic at high doses and ineffective at preventing FeLV infection at a subtoxic dose in the FeLV cat model.", "journal": "Antimicrobial agents and chemotherapy", "doi": "10.1128/AAC.35.10.2147", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1928912", "author": "Padrid PA", "n_authors": 6, "title": "Cytologic, microbiologic, and biochemical analysis of bronchoalveolar lavage fluid obtained from 24 healthy cats.", "abstract": "Twenty-four healthy cats underwent bronchoscopy and bronchoalveolar lavage to determine the normal cytologic environment of the lower respiratory tract of cats. Initial screening to ensure the health of the study population included complete histories, physical examinations, thoracic radiography, CBC, serologic tests for feline leukemia virus, feline immunodeficiency virus, and occult heartworm, and sugar and Baermann fecal flotation. In 18 cats, protected catheter brush samples of airway secretions from the lavaged lung segment were taken for culture of aerobic and anaerobic bacteria and mycoplasma. Bronchial lavage fluid (5 sequential 10-ml aliquots of normal saline solution) was pooled and filtered with cotton gauze. The unspun sample was used for determination of a total nucleated cell count. Lavage fluid was cytocentrifuged and 500 cells/slide were scored for determination of the cellular differential. Activity of lactate dehydrogenase and concentrations of total protein and IgG within the supernatant were measured, and assays were performed to detect the presence of IgA and IgM. Complete histologic evaluation of the lavaged lung of each of 6 random-source cats was performed after differential cell counting revealed 18% eosinophils within bronchoalveolar lavage fluid recovered from this group. Alveolar macrophages were the predominant cells encountered; however, a quarter of all cells recovered were eosinophils. A significant relationship was not found between the abundance of eosinophils in the lavage fluid, and either isolation of aerobic bacteria, high total nucleated cell counts, total protein concentrations, or activity of lactate dehydrogenase. Histologic evaluation of the lungs of 5 of 6 random-source cats revealed normal lungs in 2 cats, and minimal abnormal change in 3 others. Evaluation of the lungs from 1 random source cat revealed acute, mild eosinophilic bronchiolitis. We conclude that large numbers of eosinophils may be retrieved from the bronchoalveolar lavage fluid of healthy cats.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1679530", "author": "Levesque KS", "n_authors": 3, "title": "Evolutionary conservation and chromosomal localization of flvi-1.", "abstract": "A locus in feline DNA, termed flvi-1, has been identified as harboring retroviral integrations commonly found in natural feline lymphomas induced by infection with feline leukemia virus (FeLV). Southern blot analysis of human and murine DNA using restriction fragments representing flvi-1 demonstrates its phylogenetic conservation among mammals, flvi-1 is localized to murine chromosome 2, proximal portion of band E, by in situ hybridization to metaphase chromosomes. This position is adjacent to that of another putative proto-oncogene, sfpi-1, although probes representing flvi-1 and sfpi-1 do not cross-hybridize. The repeated implication of flvi-1 in natural feline leukemogenesis, its evolutionary conservation and its chromosomal position support the hypothesis that flvi-1 may represent a previously unidentified protooncogene.", "journal": "Oncogene", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1659031", "author": "Tenorio AP", "n_authors": 4, "title": "Chronic oral infections of cats and their relationship to persistent oral carriage of feline calici-, immunodeficiency, or leukemia viruses.", "abstract": "Two hundred and twenty-six cats from the Veterinary Medical Teaching Hospital (VMTH), a cat shelter, and a purebred cattery were tested for chronic feline calicivirus (FCV), feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) infections. Chronic oral carriage of FCV was present in about one-fifth of the cats in each of the groups. FIV infection was not present in the purebred cattery, was moderately prevalent (8%) in the pet population of cats examined at the VMTH for various complaints and was rampant in the cat shelter (21%). Unexpectedly high FeLV infection rates were found in the hospital cat population (28%) and in the purebred cattery (36%), but not in the cat shelter (1.4%). FCV and FeLV infections tended to occur early in life, whereas FIV infections tended to occur in older animals. From 43 to 100% of the cats in these environments had oral cavity disease ranging from mild gingivitis (23-46%), proliferative gingivitis (18-20%), periodontitis (3-32%) and periodontitis with involvement of extra-gingival tissues (7-27%). Cats infected solely with FCV did not have a greater likelihood of oral lesions, or more severe oral disease, than cats that were totally virus free. This was also true for cats infected solely with FeLV, or for cats dually infected with FeLV and FCV. Cats infected solely with FIV appeared to have a greater prevalence of oral cavity infections and their oral cavity disease tended to be more severe than cats without FIV infection. FIV-infected cats that were coinfected with either FCV, or with FCV and FeLV, had the highest prevalence of oral cavity infections and the most severe oral lesions.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(91)90048-h", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1649341", "author": "Donahue PR", "n_authors": 7, "title": "Viral genetic determinants of T-cell killing and immunodeficiency disease induction by the feline leukemia virus FeLV-FAIDS.", "abstract": "Within the fatal immunodeficiency disease-inducing strain of feline leukemia virus, FeLV-FAIDS, are viruses which range in pathogenicity from minimally (clone 61E is the prototype) to acutely pathogenic, most of the latter of which are also replication defective (clone 61C is the prototype). Mixtures of 61E and 61C virus and chimeras generated between them, but not 61E alone, killed feline T cells. T-cell killing depended on changes within a 7-amino-acid region near the C terminus of the gp70 env gene or was achieved independently by changes within a 109-amino-acid region encompassing the N terminus of gp70. The carboxy-terminal change was also sufficient for induction of fatal immunodeficiency disease in cats. Other changes within the 61C gp70 gene enhanced T-cell killing, as did changes in the long terminal repeat, the latter of which also enhanced virus replication. T-cell killing correlated with high levels of intracellular unintegrated and proviral DNA, all of which were blocked by treatment of infected cells with sera from 61C-immune cats or with a neutralizing monoclonal antibody. These findings indicate that T-cell killing is a consequence of superinfection and that the mutations in env critical to pathogenicity of the immunosuppressive variant result in a failure to establish superinfection interference in infected cells.", "journal": "Journal of virology", "doi": "10.1128/JVI.65.8.4461-4469.1991", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1663730", "author": "Hoover EA", "n_authors": 4, "title": "Early therapy of feline leukemia virus infection (FeLV-FAIDS) with 9-(2-phosphonylmethoxyethyl)adenine (PMEA).", "abstract": "Cats infected with molecularly cloned FeLV-FAIDS develop an immunodeficiency syndrome characterized by persistent antigenemia, decline in circulating CD4+ T lymphocytes, and impaired T-cell-dependent immune responses and opportunistic infection. We evaluated the capacity of PMEA to inhibit the replication of FeLV-FAIDS in vitro and to inhibit the progression of FeLV-FAIDS infection in vivo. We found that PMEA inhibited replication of FeLV-FAIDS by greater than or equal to 50% at concentrations of greater than or equal to 0.5 microgram/ml (1.63 microM) in feline fibroblasts and prevented T lymphocyte killing at concentrations of 3 micrograms/ml. PMEA administered to cats at dosages of greater than or equal to 6.25 mg/kg/day from 0 to 49 days after FeLV-FAIDS infection prevented the development of persistent antigenemia and the induction of immunodeficiency disease. In contrast to placebo treated controls, cats successfully treated with PMEA contained viral infection, developed neutralizing antibody, and resisted a second virulent virus challenge without further therapy. Manifestations of PMEA toxicity produced by higher dosages (25 or 12.5 mg/kg/day) were anemia, leukopenia, and diarrhea. These results indicate PMEA to be a potent antiretroviral agent effective in aborting fatal progression of FeLV-FAIDS infection when therapy is initiated at the time of virus exposure.", "journal": "Antiviral research", "doi": "10.1016/0166-3542(91)90060-5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1659028", "author": "Pardi D", "n_authors": 5, "title": "Selective impairment of humoral immunity in feline leukemia virus-induced immunodeficiency.", "abstract": "We used a panel of in vitro assays to investigate the nature of immune dysfunction in cats infected with FeLV-FAIDS, a naturally occurring, molecularly cloned feline leukemia virus (FeLV) isolate which induces a fatal immunodeficiency syndrome in infected cats. During the asymptomatic period preceding immunodeficiency disease, we were unable to detect any deficits in concanavalin A-induced blastogenesis, xenogeneic mixed-lymphocyte reaction assays, stimulation of lymphocytes by soluble protein antigen, and cytotoxic T lymphocyte assays. However, during this period humoral immune responses in the FeLV-FAIDS-infected cats were dramatically impaired. As early as 9 weeks after virus inoculation, the ability to mount either an IgM or IgG response to soluble protein antigens was lost. Neither B cell function, as assessed by lipopolysaccharide-induced blastogenesis or circulating B cell numbers, as assessed by immunofluorescence, differed between infected and control cats. These results suggest that FeLV-FAIDS infection may impair a subpopulation of T helper cells, that provides help for the production of antibody. Consistent with earlier observations of cats naturally infected with FeLV, our results indicate that early impairment of humoral immunity is an important component of the immunodeficiency syndrome induced by FeLV in cats.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(91)90114-r", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1648894", "author": "Robicsek F", "n_authors": 6, "title": "Prevention of retrovirus infection after injury with contaminated instruments: an experimental study.", "abstract": "Owing to similarities between human immunodeficiency virus and feline retroviruses, the feline model was chosen for the study to investigate the efficacy of timely topical treatment of accidental human immunodeficiency virus infection in the operating room. Cats were subcutaneously inoculated with either feline leukemia virus or feline immunodeficiency virus. An effort was made to neutralize the virus in loco either by infiltration of the inoculation site with povidone-iodine or with monoclonal antibodies, or by cauterization and excision. The animals were periodically monitored for feline leukemia virus antigens or for feline immunodeficiency virus antibodies. The results indicated that in the feline model, the development of generalized virus infection may be prevented by local measures if applied immediately.", "journal": "The Annals of thoracic surgery", "doi": "10.1016/0003-4975(91)91423-s", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1653471", "author": "Hörber D", "n_authors": 2, "title": "[Paramunization of FeLV-positive cats with PIND-AVI].", "abstract": "84 FeLV-positive cats were continually treated with the paramunity inducer (immunomodulator) PIND-AVI (23 healthy cats once a week, 61 diseased cats up to 3 times a week), the frequency depending on their general condition. The ELISA control tests were repeated after 4 to 6 weeks. Paramunization was continued in cats still viremic until remission of viremia. 21 healthy cats already reacted negatively to the first control ELISA, the 2 others after 8 weeks of paramunization. Within an observation time of 18 to 30 months there were no relapses. 49 of the 61 diseased cats (80.3%) reacted negatively to the first control. 5 cats (8.2%) had died at the beginning of the treatment. 5 cats (8.2%) showed a remission of viremic after being paramunized continually for 7 to 20 weeks. 2 cats (3.3%) remained viremic throughout the observation time (more than 2 years). None of the animals had a relapse. Neither had any of 9 chronically diseased cats, known to have been viremic for 3 to 12 months at the beginning of paramunization. The importance of the results of these paramunization tests for the treatment of various retrovirus infections of human beings and animals is briefly discussed.", "journal": "Tierarztliche Praxis", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1920257", "author": "Patton S", "n_authors": 4, "title": "Concurrent infection with Toxoplasma gondii and feline leukemia virus. Antibody response and oocyst production.", "abstract": "Four adult cats (two testing positive and two negative for feline leukemia virus FeLV) were fed Toxoplasma gondii tissue cysts collected from the brains of mice. Two control cats (1 FeLV+, 1 FeLV-) were not fed cysts. The cats infected with T. gondii shed thousands of oocysts but remained clinically and physically normal, with hemograms and clinical chemistry values essentially unchanged irrespective of their FeLV status. Infection with FeLV did not increase the duration of oocyst shedding. At necropsy no significant lesions were found. T. gondii antibodies were detected by three serologic tests in the cats fed tissue cysts. The time necessary for an antibody response to T. gondii was not altered by the FeLV infection. Indirect hemagglutination (IHA) was the least reliable of the serologic tests studied; it detected antibodies later in the infection, and titers were less than in the other tests. Latex agglutination (LA) detected antibodies a few days before IHA, but titers were less than in modified direct agglutination (MAT). MAT detected antibodies earliest in the infection and also measured antibodies in aqueous humor and cerebrospinal fluid.", "journal": "Journal of veterinary internal medicine", "doi": "10.1111/j.1939-1676.1991.tb00948.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "2068715", "author": "Reinacher M", "n_authors": 2, "title": "[Glomerulonephritis in dogs and cats].", "abstract": "Immunohistology and special staining of plastic sections allow diagnosis and differentiation of subtypes of glomerulonephritis in dogs. Frequency and clinical importance of these forms of glomerulonephritis vary significantly. In cats, glomerulonephritis occurs frequently in FIV-positive cats but is rare in animals suffering from persistent FeLV infection or FIP.", "journal": "Tierarztliche Praxis", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1849031", "author": "Abkowitz JL", "n_authors": 1, "title": "Retrovirus-induced feline pure red blood cell aplasia: pathogenesis and response to suramin.", "abstract": "Feline leukemia virus, subgroup C/Sarma (FeLV-C/Sarma) induces pure red blood cell aplasia in cats. Although erythroid (BFU-E and CFU-E) and granulocyte/macrophage (CFU-GM) progenitors are infected with this virus, only erythropoiesis is impaired. Two to 3 weeks before the onset of anemia, CFU-E become undetectable in marrow cultures while earlier erythroid progenitors (BFU-E) persist, suggesting that FeLV-C/Sarma (presumably via its envelope glycoprotein gp70) inhibits the differentiation of BFU-E to CFU-E in vivo. To correlate in vitro observations with the progression of disease, prospective studies were performed in six cats. These studies showed that at the time that the frequencies of CFU-E decreased in marrow cultures, BFU-E no longer responded to hematopoietic growth factor(s), although the responses of CFU-GM were unchanged. In further studies, anemic cats received suramin, a reverse-transcriptase inhibitor with other diverse effects. Within 4 to 14 days, erythropoiesis improved and up to 1,616 CFU-E were detected per 10(5) marrow mononuclear cells. However, progenitor cells remained infected, suggesting that suramin modulated erythroid differentiation without inhibiting progenitor infection. These observations led to the hypothesis that the gp70 of FeLV-C/Sarma impairs BFU-E differentiation by interference with ligand/receptor interactions or signal transduction pathways unique to erythroid cells. Understanding this mechanism should provide insights into the interactions controlling early erythropoiesis.", "journal": "Blood", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1848314", "author": "Plumb M", "n_authors": 6, "title": "Nuclear factor 1 activates the feline leukemia virus long terminal repeat but is posttranscriptionally down-regulated in leukemia cell lines.", "abstract": "A recombinant feline leukemia virus (FeLV) proviral clone (T17T-22) with a long terminal repeat (LTR) which differs from prototype FeLV by a point mutation within a conserved nuclear factor 1 (NF1)-binding motif in the LTR enhancer domain was found to be poorly expressed after DNA transfection. The NF1 point mutation reduced in vitro protein binding as assessed by gel shift analysis and reduced promoter activity significantly (2- to 10-fold). However, the degree of promoter impairment due to the NF1 site mutation varied according to cell type and was least severe in a feline leukemia cell line (T3) which had low levels of nuclear NF1 DNA-binding activity. Low NF1 DNA-binding activity was observed in three FeLV-induced leukemia cell lines (T3, T17, and FL74) and in murine F9 embryonal carcinoma cells. While similar levels of NF1 gene mRNA transcripts were detected in all cell lines, Western immunoblot analysis of F9, T17, and FL74 but not T3 nuclear extracts revealed very low levels of nuclear NF1 protein. These results indicate that NF1 activity is down-regulated in FeLV-induced leukemia cells by diverse posttranscriptional mechanisms. We suggest that NF1 down-regulation may be an important characteristic of target cells susceptible to FeLV transformation in vivo and may provide the selective pressure which favors duplication of the LTR core enhancer sequence in T-cell leukemogenic FeLV variants.", "journal": "Journal of virology", "doi": "10.1128/JVI.65.4.1991-1999.1991", "deposited_data": "Sim", "nuccore_ids": "2462509602, 2217267789, 1676453034, 1519244821", "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1649129", "author": "Kizaki T", "n_authors": 6, "title": "Specific association of retroviral envelope protein, p15E, with human cell surfaces.", "abstract": "Experiments were carried out to analyze the binding sites on human cells for highly purified retroviral protein p15E isolated from Feline Leukemia Virus, Rickard Strain. Binding of 125I-labeled p15E was tested with surfaces of human peripheral blood lymphocytes and 3 cell lines, Raji, MOLT-4, and U-937. 125I-labeled p15E showed specific binding to human peripheral blood lymphocytes. In addition, all of the cell lines tested showed binding of 125I-labeled p15E. Using U-937 cells, we characterized the interaction between p15E and the surface of these cells, and showed that the binding was specific by the following 3 different sets of evidence: (i) in equilibrium binding experiments, 18,000 binding sites with a dissociation constant of 2 x 10(-9) M were present on U-937 cells; (ii) trypsin or N-glycanase treatment decreased the binding sites of 125I-labeled p15E; and (iii) by affinity chromatography using p15E or BSA Sepharose columns, the isolated membranes of 125I-labeled U-937 cells previously treated with Triton X-100 showed a significantly higher binding to the p15E column than to the BSA column.", "journal": "Immunology letters", "doi": "10.1016/0165-2478(91)90121-p", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1852082", "author": "Jarrett O", "n_authors": 1, "title": "National FeLV/FIV awareness project.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.128.13.311-b", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1852080", "author": "Boid R", "n_authors": 6, "title": "Isolation of FeLV from a wild felid (Felis silvestris).", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.128.11.256-a", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1851738", "author": "Brightman AH 2nd", "n_authors": 3, "title": "Ocular disease in FeLV-positive cats: 11 cases (1981-1986).", "abstract": "A total of 147 cats positive for FeLV were retrospectively studied to determine the incidence of ocular disease. Of those cats, 97 had clinical cases of the disease and 50 were artificially infected with the virus. The incidence of ocular disease among FeLV-positive cats with clinical signs of disease was less than 2%, and represented less than 0.1% of the total feline cases for the 5-year period studied. The only ocular findings that could be associated with FeLV were pupillary and motility abnormalities. Retinal hemorrhage and subsequent degeneration found in experimentally infected and naturally infected cats were secondary to profound anemia, which was secondary to FeLV infection. On the basis of the literature and our findings, FeLV is not a major cause of primary or secondary ocular disease in the cat. Anterior uveal disease (iris bombé) was detected in 1 of 147 FeLV-positive cats, and the incidence of secondary infectious disease was zero.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1648929", "author": "Sheets MA", "n_authors": 4, "title": "Studies of the effect of acemannan on retrovirus infections: clinical stabilization of feline leukemia virus-infected cats.", "abstract": "Feline leukemia is a disease induced by an oncornavirus infection that inevitably causes clinically affected cats to die. It has been estimated that 40% of cats are dead within 4 weeks and 70% within 8 weeks of the onset of clinical symptoms. Acemannan is a complex carbohydrate with both immunostimulatory and direct antiviral properties. Administration of acemannan for 6 weeks intraperitoneally to clinically symptomatic cats significantly improved both the quality of life and the survival rate. Twelve weeks after initiation of treatment, 71% of treated cats were alive and in good health.", "journal": "Molecular biotherapy", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1667481", "author": "Kopelovich L", "n_authors": 1, "title": "Conversion of human fibroblasts to tissue macrophages by the Snyder-Theilen feline sarcoma virus (ST:FeSV) is associated with the de-novo expression of IL-1 alpha, IL-1 beta, IFN-alpha, TNF-alpha, GM-CSF, and CD4.", "abstract": "In an earlier study, we have demonstrated the conversion of human fibroblasts (HF) to tissue macrophages (TM) by the Snyder-Theilen feline sarcoma virus (ST:(FeSV)) [1]. The present study shows that conversion of cultured HF by the ST:FeSV to TM resulted in the de-novo expression of interleukin-1 alpha, IL-1 beta, interferon-alpha, tumor necrosis factor-alpha, granulocyte-macrophage colony stimulating factor, and CD4. The conversion of HF to TM was also associated with increased expression of non-specific esterases as well as increased amount of ingested lipid material by the TM. Clonotypic and organotypic analyses of cells infected with the ST:FeSV(FeLV) showed a similar degree of conversion to TM among eleven individual clones of skin fibroblasts, and among fibroblasts obtained from eight different organs. These findings bear on the origin (heterogeneity) of TM, the nature of TM-induced cytokines, and the potential role of ST:FeSV-recruited TM during immune reactions in vivo.", "journal": "European cytokine network", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1647576", "author": "Marciani DJ", "n_authors": 6, "title": "Genetically-engineered subunit vaccine against feline leukaemia virus: protective immune response in cats.", "abstract": "A recombinant retroviral subunit vaccine has been developed that successfully protects cats from infectious feline leukaemia virus (FeLV) challenge. The antigen used is a non-glycosylated protein derived from the envelope glycoprotein of FeLV subgroup A, expressed in Escherichia coli. This recombinant protein, rgp70D, includes the entire exterior envelope protein gp70, plus the first 34 amino acids from the transmembrane protein p15E. The vaccine consists of purified rgp70D absorbed on to aluminium hydroxide and used in conjunction with a novel saponin adjuvant. Cats immunized with this formulation developed a strong humoral immune response, including neutralizing and feline oncornavirus-associated cell membrane antigen antibodies. Vaccinated animals showed an anamnestic response upon intraperitoneal challenge with FeLV-A, and were protected from viral infection. In contrast, the control animals developed viraemia shortly after the challenge, which in most cases became chronic. Formulation of the same antigen with other widely used adjuvants elicited poor protective immune responses in cats.", "journal": "Vaccine", "doi": "10.1016/0264-410x(91)90262-5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1995571", "author": "Peiffer RL Jr", "n_authors": 2, "title": "Histopathologic study of uveitis in cats: 139 cases (1978-1988).", "abstract": "Histopathologic findings in 158 globes obtained from 139 cats by enucleation or at necropsy, with histopathologic diagnosis of uveitis, were compared, and morphology was correlated with clinical and/or histopathologic diagnosis. The most common morphologic feature was a lymphocytic-plasmacytic anterior uveal infiltrate that was either diffuse or nodular; specific cause could not be associated with this nongranulomatous anterior uveitis. In decreasing order of frequency, other common causes of uveitis in cats included feline infectious peritonitis; FeLV-associated lymphosarcoma; trauma; and lens-induced uveitis.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1850796", "author": "Mullins JI", "n_authors": 4, "title": "Disease progression and viral genome variants in experimental feline leukemia virus-induced immunodeficiency syndrome.", "abstract": "A fatal immunodeficiency syndrome with clinical and pathologic features similar to human AIDS is inducible in cats by experimental inoculation with a specific strain of feline leukemia virus (FeLV) called FeLV-FAIDS. The course of the feline disease is characterized by an age-dependent prodromal period during which a non-disease-specific, common form of proviral DNA is detected in bone marrow. Preceding clinical onset of immunodeficiency is production of high levels of specific, pathogenic variant genomes, primarily as unintegrated viral DNA, in bone marrow. Acute immunodeficiency syndrome (survival period approximately 3 months) is associated with a short prodromal period and appearance of a characteristic variant genome (variant A) that persists at high copy number as integrated and full-length unintegrated viral DNA in bone marrow. Chronic immunodeficiency syndrome (survival greater than 1 year) is marked by a longer prodromal period, a more gradual onset of severe clinical immunosuppression, and a predominance of other variant genomes that often contain substantial internal deletions. In both forms of the disease, tissue-specific replication of certain variant viruses is noted in the bone marrow, intestine, and lymph nodes. Evidence from in vitro and in vivo virus transmission studies indicates that the appearance of FeLV-FAIDS variant viruses reflects differential replication of viral genomes pre-existing in the inoculum rather than rapid de novo evolution of new variants within each animal. These results demonstrate that retrovirus-induced immunodeficiency disease in cats can be associated with and prefigured by the amplified replication of specific viral variants in target tissues.", "journal": "Journal of acquired immune deficiency syndromes", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1726399", "author": "Fevereiro M", "n_authors": 3, "title": "Antibody response to reverse transcriptase in cats infected with feline immunodeficiency virus.", "abstract": "The antibody response in cats to feline immunodeficiency virus (FIV) reverse transcriptase (RT) was followed for 3 years. Eight of the nine cats used in this study produced reverse transcriptase-inhibiting (RTI) antibodies. Relative inhibitory means of 2.9%, 18.4%, 33%, and 47% were found 6, 12, 24, and 36 months, respectively, after infection with FIV. The enzyme activity was suppressed by greater than or equal to 78% with the use of 100 micrograms of FIV-associated IgG. The RTI antibodies were FIV-specific, as they did not inhibit other mammalian retroviral polymerases, including feline leukemia virus RT. An RT-inhibition assay with sera in the presence of protein A and immunoblot analysis showed that antibody binding to FIV RT protein p62 is independent of antibody ability to block enzyme activity. Viral RT released by detergent-treated virus was stable for more than 6 weeks at 4 degrees C, whereas its activity was reduced by 50% after 2 weeks at 37 degrees C. Because significant concentrations of RTI antibodies are detected only at 1 to 2 years after infection, they can be used to determine the approximate time of virus infection and as a marker for disease progression.", "journal": "Viral immunology", "doi": "10.1089/vim.1991.4.225", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1668553", "author": "Good RA", "n_authors": 4, "title": "In vitro immunomodulation and in vivo immunotherapy of retrovirus-induced immunosuppression.", "abstract": "Early studies with the Gross passage A leukemia virus demonstrated that retroviral infection suppresses cellular and humoral immune responses. In extensive studies of the feline leukemia (FeLV) virus, which can induce profound immunodeficiency disease, are generative anemia and lymphoid, myeloid and erythroid neoplasia, the immunosuppressive effects of this retrovirus could be attributed to the actions of the retroviral envelope protein p15E. We found that a highly conserved, synthetic 17 amino acid peptide synthesized by Cianciolo and co-workers that is homologous to the hydrophilic portion of the otherwise hydrophobic transmembrane envelope protein can suppress polyclonal activation of B-cells, impair production of gamma- and alpha-interferon, inhibit production of interleukin-2, inhibit expression of IL-2 receptors, and suppress responses of cytotoxic lymphocytes. In analyses with inactivated preparations of the human immunodeficiency virus, with Pahwa et al. we demonstrated that purified non-infectious retrovirus and also retroviral proteins, in particular gp120, appeared to produce some of the immunosuppressive properties of HIV, particularly suppression of B-cell activation in response to known B-cell stimulants irrespective of T-cell influence, suppression of T-helper cell functions essential to B-lymphocyte responsiveness, and impaired function of immunoglobulin-secreting cells. Other investigators have also reported strong immunosuppressive or immunostimulatory influences for components of the HIV retrovirus and also gp120 through yet poorly elucidated but certainly complex actions on both T- and B-lymphocyte-mediated immune functions.", "journal": "International journal of immunopharmacology", "doi": "10.1016/0192-0561(91)90118-q", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1667630", "author": "Neil JC", "n_authors": 4, "title": "Feline leukaemia virus: generation of pathogenic and oncogenic variants.", "abstract": null, "journal": "Current topics in microbiology and immunology", "doi": "10.1007/978-3-642-76524-7_4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1648360", "author": "Tavares L", "n_authors": 5, "title": "Anti-idiotypic antibodies to feline leukemia virus: an approach for retroviral immunization strategies.", "abstract": "The present study describes an approach to the development and use of anti-idiotypic antibodies as a possible immunization strategy to prevent retroviral infection. The rationale for using anti-idiotypes (anti-Ids) to try to elicit an antigenic-specific immune response is examined, and the production and characterization of polyclonal and monoclonal anti-Ids are described. Several techniques were used to determine antigenic mimicry and anti-Id subtypes. The potential use of anti-Ids in feline leukemia virus (FeLV) receptor studies and vaccine trials in vivo were investigated. Results from these studies suggest that the anti-Id strategy is feasible for the FeLV model. Polyclonal Ab2 reagents were developed that blocked virus-receptor binding and thus inhibited viral infection in vitro and induced humoral immune responses in 6- to 8-week old kittens characterized by production of Ab3 with the ability to bind the original FeLV envelope protein gp70 as assessed by Western blot analysis.", "journal": "Viral immunology", "doi": "10.1089/vim.1991.4.5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1363010", "author": "Rideout BA", "n_authors": 3, "title": "Persistent upregulation of MHC class II antigen expression on T-lymphocytes from cats experimentally infected with feline immunodeficiency virus.", "abstract": "A significant elevation in the percentage of CD4+ and CD8+ T-lymphocytes expressing major histocompatibility complex (MHC) Class II antigens was observed in the blood of cats shortly after they were experimentally infected with feline immunodeficiency virus (FIV). In addition to an increase in the relative proportion of T-lymphocytes expressing Class II antigens, there was an increase in the density of Class II antigens on the cell surface. These elevations were still evident at the completion of the 5 month study. A second group of cats that had been infected with FIV for almost 5 years, and with either normal or abnormally low levels of CD4+ T-lymphocytes, had similar elevations in MHC II expression, suggesting that such abnormalities are lifelong. Cats with chronic (2 year) feline leukemia virus (FeLV) infection or dual FIV/FeLV infections also showed similar alterations in MHC II expression on CD4+ and CD8+ T-lymphocytes, suggesting that these alterations were not FIV specific. Feline T-lymphocytes expressed more MHC II antigen and interleukin-2 (IL-2) receptor following stimulation in vitro with conconavalin A and IL-2, demonstrating that feline T-lymphocytes respond to activation signals in a manner similar to T-lymphocytes of other species. However, changes in MHC II expression on T-cells of FIV infected cats were not explainable by viral induced T-cell activation alone, because FIV infected cats with elevated MHC II expression did not have coincident elevations in IL-2 receptor expression.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(92)90122-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1363009", "author": "Lehmann R", "n_authors": 10, "title": "Immunization-induced decrease of the CD4+:CD8+ ratio in cats experimentally infected with feline immunodeficiency virus.", "abstract": "In a previous experiment a group of 15 specified pathogen free (SPF) cats were experimentally infected with a Swiss isolate of feline immunodeficiency virus (FIV). A group of 15 SPF cats served as FIV negative controls. Nine cats of each group were vaccinated with a recombinant feline leukemia virus (FeLV) vaccine, six cats in each group with a placebo vaccine. All vaccinated cats developed high antibody titers to FeLV and were protected against subsequent FeLV challenge infection. In both control groups five of six cats became persistently infected with FeLV. Unexpectedly, the primary immune response to the vaccine antigen was significantly higher in the FIV positive group than in the FIV negative. The secondary response was stronger in the FIV negative cats. The goal of the present investigation was to further study the immune response in these 30 cats. They were immunized twice with the synthetic peptide L-tyrosine-L-glutamic acid-poly(DL-alanine)-poly(L-lysine) (TGAL) 21 days apart. Blood samples were collected on four occasions during the immunization process. They were tested for antibodies to TGAL, complete blood cell counts and CD4+, CD8+ and pan-T-lymphocyte counts. The following observations were made: (1) in contrast to the FeLV vaccine experiment, the primary immune response to TGAL was not significantly stronger in the FIV positive cats when tested by enzyme-linked immunosorbent assay (2). The absolute size of the CD4+ lymphocyte population was distinctly smaller in the FIV positive than in the FIV negative cats. The lowest CD4+ values were found in the dually FIV/FeLV infected cats. (3) A population of CD8+ lymphocytes was identified that was characterized by a distinctly weaker fluorescence. The size of this population increased in FIV positive and decreased in FIV negative cats during the TGAL immunization experiment. (4) The CD4+:CD8+ ratio increased in FIV negative cats during TGAL immunization from 1.9 to 2.3. In contrast, in FIV positive animals the CD4+:CD8+ ratio decreased significantly from 1.9 to 1.3 during the same period. From these and earlier data it was concluded that in short-term FIV infection the immune response to T-cell dependent antigens may be increased over that of the controls. Immune suppression develops gradually with duration of the infection. The significant drop of the CD4+:CD8+ ratio over a 5 week immunization period suggests that antigenic stimulation may accelerate the development of immune suppression in FIV positive cats. If this is a general feature, FIV infection may provide a particularly interesting model for studying the pathogenesis of AIDS.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(92)90132-a", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1363008", "author": "Hartmann K", "n_authors": 9, "title": "Use of two virustatica (AZT, PMEA) in the treatment of FIV and of FeLV seropositive cats with clinical symptoms.", "abstract": "In the present study the therapeutic efficacy and the side effects of two antiretroviral compounds used in human acquired immunodeficiency syndrome (AIDS) research, 3'-azido-2',3'-dideoxythymidine (AZT, zidovudine, Retrovir) and 9-(2-phosphonylmethoxyethyl)adenine (PMEA), were investigated in the treatment of cats naturally infected with feline immunodeficiency virus (FIV) and cats naturally infected with feline leukemia virus (FeLV). AZT was administered subcutaneously at a dose of 5 mg kg-1 body weight every 12 h and PMEA was administered subcutaneously at a dose of 2.5 mg kg-1 body weight every 12 h during a 3 week hospitalization. The therapeutic efficacy of both compounds was investigated. There was a stronger potency of PMEA than of AZT on the regression of stomatitis in FIV and in FeLV infected cats. In addition, in FIV infection PMEA had a stronger effect on the improvement of the general clinical status. Both antiretroviral compounds were potent agents to improve the immunologic status of FIV infected cats by raising the CD4/CD8 ratio. In FeLV infection PMEA and AZT appeared to reduce antigenemia. The hematological side effects caused by PMEA were severe and stronger than those of AZT. Therefore the advantage of PMEA in clinical and immunologic improvement was diminished by the hematologic disorders, which do not allow long term treatment with this drug in the dose used.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(92)90129-e", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1339067", "author": "McOrist S", "n_authors": 1, "title": "Diseases of the European wildcat (Felis silvestris Schreber, 1777) in Great Britain.", "abstract": "The author describes an examination conducted in collaboration with the Nature Conservancy Council of Great Britain into the status with regard to disease, conservation and genetics of the European wildcat (Felis silvestris). Feline leukaemia virus (FeLV) infection was detected by positive enzyme-linked immunosorbent assay in blood from 2 of 23 wildcats and was tested and confirmed by FeLV isolation in one of the two cats. This is the first time the virus has been clearly demonstrated in a free-living felid, other than the domestic cat. Toxoplasmosis was detected in all cats tested, but neither feline coronavirus nor feline immunodeficiency virus was detected in any sample. The genetic analysis indicated that only 8 of 42 wildcats tested were genetically distinct. These were mainly located in the western highlands of Scotland where \"relict\" populations may have survived. Interbreeding with domestic cats and persecution by trapping and hunting represent major threats to the survival of the European wildcat.", "journal": "Revue scientifique et technique (International Office of Epizootics)", "doi": "10.20506/rst.11.4.655", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1337403", "author": "Lehmann R", "n_authors": 4, "title": "Tumor necrosis factor alpha levels in cats experimentally infected with feline immunodeficiency virus: effects of immunization and feline leukemia virus infection.", "abstract": "Tumor necrosis factor alpha (TNF alpha) levels were determined by enzyme-linked immunosorbent assay (ELISA) and by cell culture bioassay in supernatants of lipopolysaccharide-stimulated feline monocyte cultures and in cat serum samples. There was a good correlation between the results obtained by the two methods. From the fact that TNF alpha was neutralized quantitatively by antibodies to human TNF alpha in feline monocyte supernatants and in feline sera, it was concluded that feline TNF alpha immunologically cross-reacts with human TNF alpha and that the human TNF alpha ELISA can be used to quantitate feline TNF alpha. During the first 6 months after experimental feline immunodeficiency virus (FIV) infection no differences in serum TNF alpha values were observed between infected and non-infected cats. TNF alpha levels increased significantly after primary vaccination with a feline leukemia virus (FeLV) vaccine in FIV infected cats over those in the non-infected controls. During secondary immune response TNF alpha levels rose transiently for a period of a few days in both the FIV positive and the FIV negative cats. After FeLV challenge, TNF alpha levels increased in all animals challenged with virulent FeLV for a period of 3 weeks. This period corresponded to the time necessary to develop persistent FeLV viremia in the control cats. It was concluded from these experiments that in the asymptomatic phase of FIV infection no increased levels of TNF alpha are present, similar to the situation in asymptomatic HIV infected humans. Activation of monocytes/macrophages in FIV infected cats by stimuli such as vaccination or FeLV challenge readily leads to increased levels of TNF alpha.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(92)90121-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1337401", "author": "Beebe AM", "n_authors": 5, "title": "Detection of feline immunodeficiency virus infection in bone marrow of cats.", "abstract": "Natural or experimental feline immunodeficiency virus (FIV) infection in cats is often associated with hematologic abnormalities which are similar to those observed in human immunodeficiency virus (HIV) infected patients. To determine if cells in bone marrow are infected with FIV and whether severity of hematopoietic disorder is correlated with the level of viral infection, bone marrow tissues from ten experimentally and two naturally FIV infected cats were examined by in situ hybridization for presence of FIV RNA. Seven of the 12 FIV infected cats were also naturally or experimentally coinfected with feline leukemia virus (FeLV). FIV RNA was detected mainly in megakaryocytes and unidentified mononuclear cells in the bone marrow of cats that were sick and had marrow hypercellularity and immaturity. These included all cats in the acute phase of FIV infection and two of seven long term FIV infected cats. One long term FIV infected cat with lymphosarcoma was also positive for FIV RNA in bone marrow cells. The other four long term FIV infected cats were relatively healthy, with normal bone marrow morphology, and were negative for FIV infected cells. Bone marrow from three non-infected and two cats infected with FeLV alone were also negative for FIV RNA by in situ hybridization. We concluded that megakaryocytes and mononuclear cells were targets of the viral infection and that the presence of FIV RNA in cells of the bone marrow correlated with marrow hypercellularity and immaturity, and severity of illness.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(92)90119-b", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1337398", "author": "Lutz H", "n_authors": 5, "title": "Retrovirus infections in non-domestic felids: serological studies and attempts to isolate a lentivirus.", "abstract": "An African lioness from the Zoo of Zurich had to be euthanized because of an inoperable tumor. The serum tested negative for feline leukemia virus (FeLV) p27 antigen by enzyme-linked immunosorbent assay (ELISA) but was strongly positive for feline immunodeficiency virus (FIV) antibodies by ELISA and Western blot. When her only offspring and mate were tested for FIV, high antibody titers to FIV were also found in their serum. Lymphocytes were prepared from these two lions on different occasions and co-cultivated with specific pathogen free (SPF) cat lymphocytes in the presence of concanavalin A and recombinant human interleukin-2 (IL-2) for 6 weeks. The cell culture supernatants tested negative for Mg(2+)-dependent reverse transcriptase and FIV p24 by a double antibody sandwich ELISA throughout the culture period. Whole blood and buffy coat cells collected from these two lions were transmitted by intraperitoneal injection into two SPF cats. The two cats did not seroconvert for a period of 11 months nor could reverse transcriptase activity and FIV p24 antigen be demonstrated in the supernatant of several lymphocyte cultures. To determine the importance of lentivirus infections in zoo-kept wild felids, 124 serum samples were obtained from African lions, Indian and Siberian tigers, snow leopards, panthers, cheetahs and other wild cats from nine European zoos. In addition, serum samples collected from 12 Asiatic lions originating from Gir forest in the Indian State of Gujarat were included in this study. The sera were tested for antibodies to FIV, FeLV and feline syncytium-forming virus (FeSFV) by ELISA and Western blot using the respective viruses after gradient purification. In addition, some of the sera were also tested for antibodies to equine infectious anemia virus (EIAV) and Visna-Maedi virus (VMV). Antibodies to FIV were found in 30/53 (57%) of African lions, one of 18 tigers and one of four panthers. All other sera including those collected from the 12 Asiatic lions were negative for FIV antibodies. Some of the FIV positive lion sera had high antibody titers producing strong bands on Western blot strips even in dilutions of >> 1:1000. The Western blot pattern of the lion sera differed from that of domestic cats in that primarily p24 and to a lesser degree p17 was recognized. Antibodies to FeSFV were found in 14 animals (seven with strong, seven with intermediate, reaction). No correlation was found between FIV and FeSFV infection. Antibodies to FeLV were found in two cheetahs which later turned out to have been vaccinated with Leukocell, a FeLV vaccine.(ABSTRACT TRUNCATED AT 400 WORDS)", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(92)90133-b", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1337258", "author": "Gelman IH", "n_authors": 5, "title": "Identification and evaluation of new primer sets for the detection of lentivirus proviral DNA.", "abstract": "We have developed sets of degenerate oligonucleotides designed to detect pol gene sequences from any member of the lentivirus subfamily when used as primers in amplification techniques such as the polymerase chain reaction (PCR). This pan-lentivirus-specific primer set (PLSPS) consists of primers, LV1, LV2, and LV3, based on conserved regions common to lentiviruses only. Our protocol is based on primary amplification with LV1 and LV2 followed by secondary amplification with a nested primer set based on the YM/VDD motif found in all reverse transcriptases (or \"DDMY,\" in the opposite direction), and LV3, a block of lentivirus homology nested just downstream of LV1. PLSPS-PCR analysis of DNA from cells infected with HIV-1, HIV-2, SIVmac239, BIV, visna, EIAV, CAEV, OPPV, or FIV resulted in the amplification of appropriately sized products. Sequence analysis of the LV1/2 products, cloned into pBluescript (pBS), indicated that at least 20% (most often, > 80%) contained the predicted lentivirus pol sequence. Greater than 95% of the LV3/DDMY products contained the expected lentiviral sequences. Using the PLSPS, lentivirus pol sequences could typically be detected at levels of one copy in 2 x 10(6) cells after secondary amplification. No specific lentiviral PCR products were detected in DNA from uninfected human or mouse monocytes, feline or bovine leukocytes, mouse, rat or human fibroblast cell lines, chicken embryo fibroblasts, Tahr lung cells, or cell lines infected with the following retroviruses which are not lentiviruses: Rous sarcoma virus, Moloney leukemia virus or Kirsten sarcoma virus, mouse mammary tumor virus, human T-cell lymphotropic virus I, and feline leukemia virus.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "AIDS research and human retroviruses", "doi": "10.1089/aid.1992.8.1981", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1336708", "author": "Gulino SE", "n_authors": 1, "title": "Chromosome abnormalities and oncogenesis in cat leukemias.", "abstract": "Chromosome abnormalities are found in feline leukemia virus (FeLV)-infected tumor cells as well as in tumor cells free of the virus. Three cell lines derived from tumors in the domestic cat (Felis catus), two of thymic origin and one of multicentric lymphoma origin, were analyzed cytogenetically to determine whether the FeLV virus was associated with chromosomal abnormalities in these tumor cell lines. One thymic tumor and the multicentric lymphoma were FeLV infected. The other thymic tumor cell line was FeLV-free. The normal diploid number in the domestic cat is 38. All three cell lines had numerical chromosome abnormalities with modal numbers of 37, 38 (pseudodiploid), and 39, respectively and had consistent structural chromosome abnormalities. Three markers in the virus-free cell line (S markers) were shared with one or the other of the virus-positive cell lines. The two FeLV-positive cell lines did not have S markers in common. The finding of chromosome abnormalities in both the virus-infected and the virus-free cell lines suggests that these abnormalities may be important in oncogenesis. The FeLV virus could not be considered the only causative agent of the abnormalities observed.", "journal": "Cancer genetics and cytogenetics", "doi": "10.1016/0165-4608(92)90346-a", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1336345", "author": "Mathes LE", "n_authors": 6, "title": "Pre- and postexposure chemoprophylaxis: evidence that 3'-azido-3'-dideoxythymidine inhibits feline leukemia virus disease by a drug-induced vaccine response.", "abstract": "The benefits of postexposure 3'-azido-3'-dideoxythymidine (AZT) prophylaxis following human immunodeficiency virus exposure are unknown. We describe a comprehensive assessment of pre- and postexposure AZT therapy in the feline leukemia virus (FeLV)-cat model for AIDS which included in vitro testing, an in vivo dose-response titration, a postexposure treatment study, plasma drug concentration determinations, and evaluation of the immune response to FeLV. In in vitro studies, AZT prevented FeLV infection of a feline T-lymphoid cell line, giving 50 and 90% inhibition concentrations of 4.6 and 11.1 mM, respectively. In all of the in vivo efficacy studies, AZT was administered by continuous subcutaneous infusion for 28 days. AZT toxicity was excessive at a dosage of 120 mg/kg of body weight per day, causing acute anemia, but AZT was tolerable at 60 mg/kg/day. In preexposure studies, AZT was efficacious in preventing chronic antigenemia at a dosage of > or = 15 mg/kg/day, at which plasma AZT concentrations averaged between 0.51 and 0.81 micrograms/ml (2.13 and 3.03 microM). As a postexposure treatment, at 60 mg/kg/day, AZT prevented chronic FeLV antigenemia when treatment was started up to 96 h post-virus inoculation (p.i.), but not when treatment was started at 192 h p.i. The 4-day period between 96 and 192 h p.i. appears to be critical for establishing chronic viremia. It is presumed that the increase in virus load between 4 and 8 days p.i. was able to overwhelm the immunologic functions responsible for containment of FeLV infection, even though AZT therapy effectively controlled viremia during the treatment period. The antibody response to FeLV varied depending on the time of AZT treatment initiation relative to virus challenge. When AZT treatment was started 48 h before or 8 h after FeLV challenge, antibodies to FeLV were not detected until after AZT treatment was discontinued at 28 days p.i. Following AZT treatment, however, antibody titers rapidly increased at a rate suggestive of a secondary immune response. When AZT treatment was initiate at later time points relative to virus challenge (24, 48, and 96 h p.i.), antibodies to FeLV became detectable during the treatment period. These results indicate that AZT treatment does not completely prevent FeLV infection, even when treatment begins before virus challenge, and that immune sensitization to FeLV proceeds during the prophylactic drug treatment period.", "journal": "Antimicrobial agents and chemotherapy", "doi": "10.1128/AAC.36.12.2715", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1333529", "author": "Diehl LJ", "n_authors": 2, "title": "Early and progressive helper T-cell dysfunction in feline leukemia virus-induced immunodeficiency.", "abstract": "Cats infected with the highly pathogenic feline leukemia virus isolate FeLV-FAIDS develop an immunodeficiency syndrome characterized by progressive loss of CD4+ T cells and eventual pan-lymphocyte depletion. Prior to the decline in circulating CD4+ cells, infected cats are unable to mount primary antibody responses to T-dependent antigens. We investigated whether the altered ability of helper T cells to produce cytokines necessary for B cell growth and differentiation might be a primary event in the pathogenesis of FeLV-FAIDS infection. We found that as early as 9 weeks after infection, lymphocytes from cats with normal CD4+ cell numbers produced significantly lower levels of B-cell stimulatory factors. This deficit became progressively more severe with time. By contrast, resting B cells isolated from infected cats did not differ from controls in the ability to undergo activation and differentiation to antibody-secreting cells. The results suggest that a progressive defect in Th function occurs prior to CD4+ T-cell depletion early in the course of FeLV-FAIDS induced immunodeficiency.", "journal": "Journal of acquired immune deficiency syndromes", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1384795", "author": "Constantoulakis P", "n_authors": 6, "title": "Cell lines produce factors that induce fetal hemoglobin in human BFUe-derived colonies.", "abstract": "Established cell lines were screened for secretion of activities than can stimulate fetal hemoglobin (HbF) production in adult burst-forming unit-erythroid (BFUe) cultures. Conditioned media from four cell lines, a human teratocarcinoma, an osteosarcoma, a bladder cell carcinoma, and feline leukemia virus (FeLV) A-infected feline fibroblasts (FEF-A cells), consistently increased the relative production of fetal globin in BFUe-derived colonies. In vitro translation of RNA from these cells in Xenopus oocytes yielded products that increased the gamma to gamma+beta ratio in adult erythroid colonies. These results demonstrate that a variety of cell lines produce factors that stimulate the production of HbF in vitro. The genes of such factors could be isolated by expression cloning of cDNA from cell lines using the Xenopus oocyte system.", "journal": "Blood", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1336472", "author": "Yasuda M", "n_authors": 3, "title": "Effects of ultraviolet-inactivated feline leukemia virus on the production of alpha/beta interferon by feline peripheral blood mononuclear cells.", "abstract": "The effects of ultraviolet-inactivated feline leukemia virus (UV-FeLV) on the production of alpha and/or beta interferon (IFN) by mononuclear cells stimulated with the Newcastle disease virus (IFN-NDV) was investigated. The production of IFN-NDV and gamma IFN was suppressed by 50% as compared to the control in the presence of 200 ng/ml or 200 micrograms/ml of UV-FeLV, respectively. The presence of UV-FeLV decreased the rate of the production, but the time to reach the plateau of the IFN activity in the culture supernatant was not shortened in both IFNs. It was suggested that the suppressive effects of UV-FeLV against both IFNs were through rather similar mechanisms. The suppressive effects of UV-FeLV on IFN-NDV production was most evident in the cultures to which UV-FeLV was added at the early stages of the culture, and could not be demonstrated when UV-FeLV was added 8 hr after initiation of the culture. These data therefore indicate that non-infectious feline leukemia viral particles can modify the production of feline IFNs by peripheral blood mononuclear cells.", "journal": "Fukuoka igaku zasshi = Hukuoka acta medica", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1336243", "author": "Egberink H", "n_authors": 2, "title": "Animal immunodeficiency viruses.", "abstract": "Feline immunodeficiency virus (FIV) has morphological, physical and biochemical characteristics similar to human immunodeficiency virus (HIV), the cause of AIDS in man. However, it is antigenically and genetically distinct from HIV; an antigenic relatedness with equine infectious anaemia virus has been demonstrated. FIV has been molecularly cloned and sequenced. Diagnostic tests are commercially available and attempts at preparing inactivated, subunit and molecularly engineered vaccines are being made in different laboratories. During FIV infection a transient primary illness can be recognized, with fever, neutropenia and lymphadenopathy. After a long period of clinical normalcy a secondary stage is distinguished with signs of an immunodeficiency-like syndrome. The incubation period for this stage can be as long as 5 years, during which gradual impairment of immune function develops. Many FIV-infected cats are presented for the first time showing vague signs of illness: recurrent fevers, emaciation, lack of appetite, lymphadenopathy, anaemia, leucopenia and behavioural changes. Later, the predominant clinical signs observed are chronic stomatitis/gingivitis, enteritis, upper respiratory tract infections, and infections of the skin. Neoplasias, neurological, immunological and haematological disorder are seen in a smaller proportion. The immunodeficiency-like syndrome is progressive over a period of months to years. Concomitant infection with feline leukaemia virus has been shown to accelerate the progression of disease. In vitro, phenotypic mixing between FIV and an endogenous feline oncovirus (RD114) has been demonstrated which leads to a broadening of the cell spectrum of the lentivirus. Bovine immunodeficiency virus (BIV) has been isolated only once, and all attempts to obtain additional isolates have failed; it has been recovered from the leucocytes of cattle with persistent lymphocytosis, lymphadenopathy, lesions in the central nervous system, progressive weakness and emaciation. As with the feline representative, BIV also was found to possess a lentivirus morphology and to encode a reverse transcriptase with Mg++ preference; it replicates and induces syncytia in a variety of embryonic bovine tissues in vitro. Antigenic analyses have demonstrated a conservation of epitopes between the major core protein of BIV and HIV. The original isolate has been molecularly cloned and sequenced. Besides the three large open reading frames (ORFs) comprising the gag, pol, and env genes common to all replication-competent retroviruses, five additional small ORFs were found. Numerous point mutations and deletions were found, mostly in the env-encoding ORF. These data suggest that, within a single virus isolate, BIV displays extensive genomic variation.(ABSTRACT TRUNCATED AT 400 WORDS)", "journal": "Veterinary microbiology", "doi": "10.1016/0378-1135(92)90059-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1331290", "author": "Rigby MA", "n_authors": 10, "title": "Partial dissociation of subgroup C phenotype and in vivo behaviour in feline leukaemia viruses with chimeric envelope genes.", "abstract": "Feline leukaemia viruses (FeLVs) are classified into subgroups A, B and C by their use of different host cell receptors on feline cells, a phenotype which is determined by the viral envelope. FeLV-A is the ubiquitous, highly infectious form of FeLV, and FeLV-C isolates are rare variants which are invariably isolated along with FeLV-A. The FeLV-C isolates share the capacity to induce acute non-regenerative anaemia and the prototype, FeLV-C/Sarma, has strongly age-restricted infectivity for cats. The FeLV-C/Sarma env sequence is closely related to that of common, weakly pathogenic FeLV-A isolates. We now show by construction of chimeric viruses that the receptor specificity of FeLV-A/Glasgow-1 virus can be converted to that of FeLV-C by exchange of a single env variable domain, Vr1, which differs by a three codon deletion and nine adjacent substitutions. Attempts to dissect this region further by directed mutagenesis resulted in disabled proviruses. Sequence analysis of independent natural FeLV-C isolates showed that they have unique Vr1 sequences which are distinct from the conserved FeLV-A pattern. The chimeric viruses which acquired the host range and subgroup properties of FeLV-C retained certain FeLV-A-like properties in that they were non-cytopathogenic in 3201B feline T cells and readily induced viraemia in weanling animals. They also induced a profound anaemia in neonates which had a more prolonged course than that induced by FeLV-C/Sarma and which was macrocytic rather than non-regenerative in nature. Although receptor specificity and a major determinant of pathogenicity segregate with Vr1, it appears that sequences elsewhere in the genome influence infectivity and pathogenicity independently of the subgroup phenotype.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-73-11-2839", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1429172", "author": "Wellman ML", "n_authors": 6, "title": "Lymphoma involving large granular lymphocytes in cats: 11 cases (1982-1991).", "abstract": "Medical records of 11 cats with lymphoma involving large granular lymphocytes were reviewed. All 9 cats tested were FeLV-negative. Ten cats had a history of anorexia, lethargy, vomiting, or diarrhea, and had lymphoma involving abdominal viscera. The most common site of tumor in these cats was the jejunum. One cat had cutaneous masses caused by dermal and epidermal infiltration with neoplastic large granular lymphocytes. The most common hematologic abnormality was leukocytosis, characterized by neutrophilia with a left shift (7 cats); 2 cats had a left shift without neutrophilia. None of the cats had lymphocytosis, but immature large granular lymphocytes were found in the blood of 4 cats. The most common serum biochemical abnormalities were hypoalbuminemia (10 cats), hypocalcemia (10 cats), hypoproteinemia (9 cats), high aspartate transaminase activity (9 cats), and hyperbilirubinemia (8 cats). Large granular lymphocytes were characterized by abundant cytoplasm containing distinct azurophilic granules that varied in size and number. The most common cytochemical staining pattern included detection of alpha-naphthyl butyrate esterase, acid phosphatase, and beta-glucuronidase activities. On examination of histologic sections, granules stained weakly eosinophilic with Giemsa and moderately with periodic acid-Schiff reaction. Ultrastructurally, the granules appeared membrane bound and contained an electron-dense matrix in 4 cats.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1429123", "author": "Lappin MR", "n_authors": 5, "title": "Enzyme-linked immunosorbent assays for the detection of Toxoplasma gondii-specific antibodies and antigens in the aqueous humor of cats.", "abstract": "Serum and aqueous humor samples, collected from 14 clinically normal cats and 96 cats with clinical evidence of intraocular inflammation, were assayed with ELISA for Toxoplasma gondii-specific immunoglobulin M (IgM), T gondii-specific IgG, T gondii-specific antigens, total IgG, and total IgM. Additionally, serum was assayed with ELISA for feline leukemia virus p27 antigen and antibodies against the feline immunodeficiency virus as well as with an immunofluorescent antibody assay for antibodies against feline coronaviruses. Calculation of the Goldmann-Witmer coefficient (C-value) for the T gondii-specific antibodies detected in aqueous humor established the likelihood of local antibody production. Serologic evidence of present or prior infection by an infectious agent was found in 81.9% of the clinically affected cats from which serologic results were available (77/94 cats). Seropositive results for toxoplasmosis were found in 74.0% of the clinically affected cats. Anterior segment inflammation was found in 93.1% (81/87 cats from which information was available) of the clinically affected cats, most of which were older males. Toxoplasma gondii-specific antibodies were not detected in the aqueous humor of 6 seropositive, clinically normal cats. The C-values for aqueous T gondii antibodies were greater than 1 in 44.8% of the cats and greater than 8 in 24.0% of the cats. Response to treatment with clindamycin HCl was positive in 15/20 (75%) of the T gondii-seropositive, clinically affected cats treated with this drug. In 13/15 (86.7%) T gondii-seropositive, clinically affected cats having a C-value greater than 1, response to treatment with clindamycin HCl was positive.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1381539", "author": "Sheets RL", "n_authors": 5, "title": "Biologically selected recombinants between feline leukemia virus (FeLV) subgroup A and an endogenous FeLV element.", "abstract": "In efforts to elucidate the proximal leukemogens that might be produced during a feline leukemia virus (FeLV) infection of cats, homologous recombinations between molecularly cloned exogenous and endogenous FeLV proviruses of known sequences were examined in cell cultures in vitro. A plasmid containing an infectious member of the most commonly occurring FeLV subgroup (FeLV subgroup A or FeLV-A) was coexpressed with noninfectious constructs containing the envelope (env) gene of an endogenously inherited FeLV-like feline genomic element in transfected feline fibroblasts. The viruses generated were selected for their ability to propagate in human cells which are resistant to infection by the parental ecotropic FeLV-A or the noninfectious endogenous constructs. An analysis of the recombinants thus derived identified a limited number of sites in the env gene which were preferentially utilized in the generation of recombinant FeLVs under the selection conditions used. These sites were clustered in the surface glycoprotein (SU) moiety of the env gene, and it appeared that most, but not all, of the SU gene product of FeLV-A, beginning from the N-terminus, can be replaced by sequences from an endogenous element, still allowing the virus to be biologically viable. In fact, these substitutions in the env gene expanded infectivity of the parental FeLV-A from ecotropic to polytropic cell tropism. Additionally, substitutions in the SU region yielded many recombinants in which a primary neutralizing pentapeptide epitope of FeLV-A was altered because of its variance in the endogenous element. In several of the recombinants, this sequence was also found to be frequently mutated. Consistent with the changes identified in this antibody-binding domain, the recombinant viruses were only weakly inhibited by a monoclonal antibody directed against this epitope, while FeLV-A was highly sensitive to neutralization.", "journal": "Virology", "doi": "10.1016/0042-6822(92)90924-e", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1330999", "author": "Post G", "n_authors": 2, "title": "Nonhematopoietic hepatic neoplasms in cats: 21 cases (1983-1988).", "abstract": "Nonhematopoietic hepatic neoplasms (n = 25) were diagnosed in 21 cats during a 5.5-year period. Thirteen of the neoplasms were benign bile duct adenomas and 12 were malignant, 6 of which were bile duct adenocarcinomas. All cats were greater than or equal to 10 years old, and 14 were male. Main clinical signs were anorexia and lethargy, and 15 of 21 cats had hepatomegaly. All 21 cats were feline leukemia virus-test negative. Although there was a trend toward high activities of serum alanine transaminase and aspartate transaminase, neither clinical signs nor enzyme activity were specific for diagnosis of hepatic neoplasia in the cats of this study.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1330998", "author": "Lappin MR", "n_authors": 7, "title": "Serologic prevalence of selected infectious diseases in cats with uveitis.", "abstract": "Serologic evidence of infection by Toxoplasma gondii, feline leukemia virus, feline coronaviruses, or feline immunodeficiency virus (FIV) is commonly found in cats with uveitis. Serum samples from 124 cats with uveitis were assayed by use of ELISA for the detection of T gondii-specific immunoglobulin M (IgM), IgG, and circulating antigens (Ag), as well as an ELISA for feline leukemia virus Ag, an ELISA for antibodies to FIV, and an indirect fluorescent antibody assay for antibodies to feline coronaviruses. Serologic evidence of infection by 1 or more of the infectious agents was detected in 83.1% of the samples. Serologic evidence of T gondii infection, defined as the detection of T gondii-specific IgM, IgG, or Ag in serum, was found in 74.2% of the samples. The seroprevalence of T gondii infection was significantly greater in cats with uveitis than in healthy cats from a similar geographic area. Serum samples from cats with serologic evidence of both T gondii and FIV infections were more likely to contain T gondii-specific IgM without IgG than samples from cats with serologic evidence of T gondii infection alone. Cats with serologic evidence of FIV and T gondii coinfection had a higher T gondii-specific IgM titer geometric mean and a lower T gondii-specific IgG titer geometric mean than did cats with serologic evidence of T gondii infection alone. Serologic evaluation for T gondii infection should include assays that detect IgM, IgG, and Ag, particularly in cats coinfected with FIV.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1330430", "author": "Reid RW", "n_authors": 3, "title": "Retrospective serologic survey for the presence of feline immunodeficiency virus antibody: a comparison of ELISA and IFA techniques.", "abstract": "A total of 878 samples from the New York State Diagnostic Laboratory (NYSDL), dating from January 1984 to May 1987, were examined to detect antibodies to feline immunodeficiency virus (FIV). We used 2 screening methods; an indirect immunofluorescence assay (IFA) and an enzyme-linked immunosorbent assay (ELISA). Of these, 211 samples were from cats that tested negative for feline leukemia virus (FeLV) and exhibited disease signs consistent with immunodeficiency disease; 19 (9.0%) serum samples were determined to be positive. An additional 508 samples were from cats that tested FeLV-negative and were asymptomatic; 6 (1.2%) sera were determined to be positive. The final 159 samples were from FeLV-positive cats and included symptomatic and asymptomatic animals; this population of cats produced 6 (3.8%) positives. Additionally, 521 samples from the Cornell Feline Health Center (CFHC) serum bank, dating back to 1966, were tested to determine the earliest sample in which FIV antibodies could be detected. Five (2.7%) 1971 and 3 (3.3%) 1969 CFHC samples tested positive. The IFA for FIV antibody proved to be a sensitive (97.4%) and specific (100%) test. The ELISA also had high sensitivity (100%) and specificity (99.6%); however, the IFA proved to be more specific than the ELISA when assaying FeLV-positive cats.", "journal": "The Cornell veterinarian", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1326757", "author": "Brojatsch J", "n_authors": 6, "title": "Feline leukemia virus subgroup C phenotype evolves through distinct alterations near the N terminus of the envelope surface glycoprotein.", "abstract": "Feline leukemia viruses (FeLVs) belonging to the C subgroup induce aplastic anemia in domestic cats and have the ability, unique among FeLV strains, to proliferate in guinea pig fibroblasts in tissue culture. Previous studies have shown that the pathogenic and host range specificity of a prototype molecular clone of FeLV-C [FeLV-Sarma-C (FSC)] colocalize to a region encoding the 3' 73 amino acids of the pol gene product and the N-terminal 241 amino acids of the envelope surface glycoprotein named SU. Here, we amplified, via PCR, cloned, and sequenced the SU coding sequence from three additional anemia-inducing subgroup C FeLV isolates. Chimeric viruses were constructed by replacement of fragments of FeLV-C envelope genes into the FeLV-A prototype virus 61E. Using a modified vesicular stomatitis virus-FeLV pseudotype assay, we demonstrated that the subgroup C receptor specificity for each virus was determined by changes within the N-terminal 87-92 amino acids of SU, in which most changes occurred within the 15- to 20-amino-acid first variable region (V1). Determinants for growth in guinea pig cells colocalized to this region. Despite the consistent localization of biological determinants, the only consistent features that distinguished the deduced FeLV-A and FeLV-C proteins was one lysine-to-arginine change and a structural prediction of an alpha-helix in FeLV-A proteins versus random coil in FeLV-C proteins within V1. However, arginine in equilibrium with lysine substitutions were not sufficient to convert the subgroup A virus to the subgroup C phenotype or vice versa. Thus, certain distinct structural changes within the N-terminal region of FeLV SU can result in convergent viral phenotypes.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.89.18.8457", "deposited_data": "Sim", "nuccore_ids": "323920, 323918", "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1413406", "author": "Rideout BA", "n_authors": 5, "title": "Characterization of morphologic changes and lymphocyte subset distribution in lymph nodes from cats with naturally acquired feline immunodeficiency virus infection.", "abstract": "Lymph nodes were collected at biopsy or necropsy from 18 cats with naturally acquired symptomatic feline immunodeficiency virus (FIV) infection and from 18 seronegative cats. Thirty-five of the cats were domestic shorthairs and one was a Persian cross. The cats ranged from 7 months to 16 years of age and were mainly obtained from California veterinary practitioners, a California cattery, and a Veterinary Teaching Hospital. Based on clinical signs present at tissue collection, ten FIV-infected cats fell into the acquired immunodeficiency syndrome (AIDS)-related complex (ARC) clinical stage and eight in the terminal (AIDS) stage of FIV disease. All cats were FeLV negative by antigen ELISA. Histologic sections of lymph nodes from each cat were examined blindly and were categorized as hyperplastic, involuting, mixed hyperplastic and involuting, depleted, or normal based upon subjective evaluation of follicles and paracortex. The relative abundance of plasma cells was evaluated in methyl green pyronin (MGP) and hematoxylin and eosin-stained sections. Similar numbers of FIV-seropositive and -seronegative cats fell into each lymph node category. The only difference evident between FIV-infected cats and control cats was in the degree of plasmacytosis present; moderate to marked plasmacytosis was present in 13/18 FIV-infected cats but in only 3/18 control cats.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "Veterinary pathology", "doi": "10.1177/030098589202900504", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1324184", "author": "Linenberger ML", "n_authors": 2, "title": "In vivo infection of marrow stromal fibroblasts by feline leukemia virus.", "abstract": "Marrow stromal fibroblasts (FBs) likely play an important role in the regulation of hematopoiesis within the marrow microenvironment. Infection of these cells by feline leukemia virus (FeLV) might not only contribute to the pathogenesis of FeLV-induced hematologic diseases, but could provide a reservoir for virus in the infected cat. To determine the frequency of FeLV infection among marrow FB precursor cells (fibroblast colony-forming units, CFU-F) of cats viremic with FeLV-C/Sarma and FeLV-A/61E, marrow FBs and FB cell clones were isolated and assayed for expression of FeLV gag protein. From 30% to 86% and 64% to 88% of marrow FB precursors were infected with FeLV-C/Sarma and FeLV-A/61E, respectively. CFU-F from a cat viremic with FeLV-A/61E were not affected by exposure to antibody against FeLV envelope glycoprotein gp70 and heterologous complement, whereas similarly treated hematopoietic progenitors (erythroid colony-forming units, CFU-E; erythroid burst-forming units, BFU-E; and granulocyte-macrophage colony-forming units, CFU-GM) and culture-propagated, FeLV-infected marrow FBs were effectively lysed, suggesting that infected CFU-F within the marrow microenvironment do not express a significant amount of gp70 on their cell membranes. Thus, marrow FB precursor cells appear to be a major target for FeLV in vivo. Furthermore, the low level of gp70 antigen expression on the surface of these cells in vivo may allow them to escape immune surveillance and provide a reservoir of virus during active or latent infection.", "journal": "Experimental hematology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1323710", "author": "Dean GA", "n_authors": 4, "title": "Hematopoietic target cells of anemogenic subgroup C versus nonanemogenic subgroup A feline leukemia virus.", "abstract": "Feline leukemia viruses (FeLVs) belonging to interference subgroup C induce fatal anemia resembling human pure red cell aplasia (PRCA). Subgroup A FeLVs, although closely related genetically to FeLVs of subgroup C, do not induce PRCA. The determinants for PRCA induction by a molecularly cloned prototype subgroup C virus (FeLV-Sarma-C [FSC]) have been localized to the N-terminal 241 amino acids of the surface glycoprotein (SU) gp70. To investigate whether the anemogenic activity of FSC reflects a unique capacity to infect erythroid progenitor cells, we used correlative immunogold, immunofluorescence, and cytological staining to study prospectively the hemopoietic cell populations infected by either FSC or FeLV-FAIDS-61E-A (F6A), a prototype of subgroup A virus. The results demonstrated that although only FSC-infected animals developed erythrocyte aplasia, the env SU and the major core protein (p27) were expressed in a surprisingly large fraction of the lymphoid, erythroid, and myeloid lineage marrow cells in both FSC- and F6A-infected cats. Between days 8 and 17 postinoculation, gp70 and p27 were detected in 43 to 73% of erythroid, 25 to 75% of lymphoid, and 35 to 50% of myeloid lineage cells, regardless of whether the cats were infected with FSC or F6A. Thus, anemogenic subgroup C and nonanemogenic subgroup A FeLVs have similar hemopoietic cell tropism and infection kinetics, despite their divergent effects on erythroid progenitor cell function. Acute anemia induction by subgroup C FeLV, therefore, does not reflect a unique tropism for marrow erythroid cells but rather indicates a unique cytopathic effect of the SU on erythroid progenitor cells.", "journal": "Journal of virology", "doi": "10.1128/JVI.66.9.5561-5568.1992", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1524577", "author": "Klimentowski S", "n_authors": 3, "title": "[The effectiveness of paramunization for the control of feline coryza].", "abstract": "20 cats in a cat home were treated prophylactically and therapeutically with Baypamun HK. The animals were allocated into three groups as described. 7 freshly admitted clinically healthy cats were treated prophylactically on day 1, 2 and 9 with 1 ml Baypamun HK (group I). 7 cats, who already were allocated for one year in the home and were sick of the feline respiratory disease complex were treated as described for group I (group II). 6 further cats, who also showed symptoms of the feline respiratory disease complex and had stayed for one year in the home were treated with physiol.saline solution according to group I (group III). From all cats blood samples were taken at day 1, 3, 10 and 17. The blood samples were checked for antibodies against feline calicivirus (FCV), feline herpesvirus (FHV), panleukopenia virus (PLV), feline peritonitis virus (FIPV) and feline immunodeficiency virus (FIV). Also the occurrence of the feline leukemia virus (FeLV) was evaluated. The cellular immunity was evaluated by means of the lymphocyte transformations test (LTT), nitroblue-tetrazolium reduction test (NBT) and cytochrome C-reduction test (CRT). Mean value and standard deviation was calculated from the results. The significance was determined by the t-test. The animals were examined clinically daily for 20 days for the feline respiratory disease complex. When necessary, the animals were treated by homeopathic and antibiotic products. At the time of admission to the home all cats were or had been treated with an attenuated panleukopenia vaccine. The serologic parameters were not influenced in the cats of group I.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "Berliner und Munchener tierarztliche Wochenschrift", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1322598", "author": "Matsumoto Y", "n_authors": 6, "title": "Detection of enhancer repeats in the long terminal repeats of feline leukemia viruses from cats with spontaneous neoplastic and nonneoplastic diseases.", "abstract": "Enhancer duplication in the long terminal repeat of feline leukemia virus (FeLV) was examined in primary cells from naturally FeLV-infected cats with various neoplastic and nonneoplastic diseases using the polymerase chain reaction. In all cases, a 170-bp band, corresponding to a standard exogenous FeLV with one copy of enhancer, was detected. Repeated enhancer sequences were found in all 8 cases of thymic-form lymphosarcoma, in some cases of lymphosarcoma of other forms (3/8) and myeloid tumors (2/3), and in only 1 of 6 cases with nonneoplastic diseases. The copy number of FeLV proviruses with a repeated enhancer seemed higher than that of those with one copy of enhancer in 3 cases of thymic form lymphosarcoma. In 5 cases of thymic form lymphosarcoma and in 1 case of erythroleukemia, coexistent FeLVs with double and triple enhancers of different sizes were found. Of the enhancer elements, only the SV40 core binding site was found in all the enhancer direct repeats of these FeLVs. All the provirus clones with single and duplicated enhancer sequences from a single tumor showed mutations or deletions characteristic to that tumor, indicating that enhancer repeats may arise in individual animals after infection with a single virus clone. The present findings indicate that FeLV with enhancer repeats generated in the cat is associated with the induction of neoplastic diseases in natural conditions.", "journal": "Virology", "doi": "10.1016/0042-6822(92)90598-j", "deposited_data": "Sim", "nuccore_ids": "285799, 285798, 285797, 285796, 285795, 285794, 285793, 285792, 285791, 285790, 285789", "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1322201", "author": "Linenberger ML", "n_authors": 2, "title": "Studies in feline long-term marrow culture: hematopoiesis on normal and feline leukemia virus infected stromal cells.", "abstract": "To study the effects of feline leukemia virus (FeLV) on the hematopoietic microenvironment, a two-step feline long-term marrow culture (LTMC) system was developed and characterized. The adherent, stromal layer of these cultures is composed of fibroblastoid cells (50% to 80%), macrophages (10% to 30%), fat cells (10% to 20%), and large, polygonal cells that express muscle actin (1% to 2%). When fresh, enriched marrow mononuclear cells (MMNC) were added to 3-week-old irradiated stromal cultures, nonadherent erythroid progenitors (BFU-E) and granulocyte/macrophage progenitors (CFU-GM) could be detected for up to 5 and 12 weeks, respectively. LTMC stromal layers established from marrow cells from cats viremic with either a nonpathogenic strain of FeLV (FeLV-A/61E) or the anemogenic strain FeLV-C/Sarma were morphologically equivalent to uninfected LTMC stromal layers, although more than 80% of the stromal cells expressed FeLV gag protein. When FeLV-infected stromal cultures were recharged with uninfected MMNC, altered patterns of hematopoiesis were observed, compared with recharged, uninfected stromal cultures. In cultures with infected stroma, fewer nonadherent cells (NAC), nonadherent BFU-E, and nonadherent CFU-GM were detected during the first 4 to 5 weeks after recharge. In contrast, greater numbers of NAC and nonadherent CFU-GM were found from weeks 5 to 12 after recharge. When FeLV-infected stromal cultures were recharged with MMNC from a cat heterozygous for the X-chromosome-linked enzyme glucose-6-phosphate dehydrogenase (G-6-PD), the percentage of nonadherent CFU-GM expressing the domestic type G-6-PD isoenzyme remained stable over time (mean % domestic [%d], 53% +/- 3%), and was equivalent to that of nonadherent CFU-GM maintained in uninfected cultures (mean %d, 56% +/- 3%), indicating that clonal drift or clonal selection was not responsible for the enhanced maintenance of CFU-GM. Furthermore, as only 10% to 20% of recharged hematopoietic cells became infected with FeLV in vitro, it is unlikely that the altered pattern was due to progenitor infection. We hypothesize that the increase in NAC and nonadherent CFU-GM in FeLV-infected cultures resulted from enhanced growth factor production by stromal cells. The two-step LTMC system may facilitate the characterization of stromal-derived factors that affect progenitor cell engraftment and proliferation.", "journal": "Blood", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1321052", "author": "Khan KN", "n_authors": 4, "title": "Effects of tumor necrosis factor-alpha on normal feline hematopoietic progenitor cells.", "abstract": "The effects of tumor necrosis factor-alpha (TNF-alpha) on feline bone marrow hematopoietic progenitors were evaluated by exposing bone marrow mononuclear cells from specific pathogen-free cats to different concentrations of TNF-alpha (ranging from 50 to 800 pg/ml) for 2 h before plating for clonal assays of colony-forming units. TNF-alpha caused a dose-dependent suppression of feline erythroid colony-forming units (CFU-E) and erythroid burst-forming units (BFU-E), whereas granulocyte-macrophage colony-forming units (CFU-GM) were minimally affected. TNF-alpha concentrations as low as 200 pg/ml significantly inhibited growth of erythroid progenitors. Addition of polyclonal rabbit anti-TNF-alpha antibodies completely neutralized the suppressive effect of TNF-alpha on erythroid progenitors. At higher concentrations of TNF-alpha (800 pg/ml), 35% of CFU-E and 21% of BFU-E still survived, indicating that some erythroid progenitors are not sensitive to a single exposure of TNF-alpha in vitro. These results suggest that TNF-alpha may play a role in regulating hematopoiesis in cats and may be involved in the pathogenesis of erythroid aplasia in cats infected with feline leukemia virus.", "journal": "Experimental hematology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1322571", "author": "Lutz H", "n_authors": 1, "title": "[Kittens and FeLV].", "abstract": null, "journal": "Tijdschrift voor diergeneeskunde", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1629349", "author": "Fontenot JD", "n_authors": 4, "title": "Evaluation of feline immunodeficiency virus and feline leukemia virus transmembrane peptides for serological diagnosis.", "abstract": "The general model for retrovirus transmembrane (TM) proteins proposed by Gallaher et al. (W. R. Gallaher, J. M. Ball, R. F. Garry, M. C. Griffin, and R. C. Montelaro, AIDS Res. Hum. Retroviruses 5:431-440, 1989) suggests that all retrovirus TM proteins may contain an immunodominant domain (Imd-TM peptide) located at the apex of the TM polypeptide. Although this Imd-TM peptide has been shown to be immunodominant in a variety of lentivirus infections, there has not been a detailed serological analysis of an oncovirus Imd-TM peptide as a diagnostic agent. We describe here an analysis of the antigenic properties and diagnostic potentials of the predicted Imd-TM peptides of feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) in serological assays of sera from infected cats. The results of these studies demonstrate that antibodies specific to the FIV Imd-TM peptide are detected within 2 weeks postinfection, are maintained at high levels for extended periods, and are not detectable in uninfected or FeLV-infected cats. In marked contrast, the FeLV Imd-TM peptide displayed only negligible levels of serological reactivity in FeLV-infected cats. These studies indicate that the peptide is a useful reagent for the detection of antibodies to FIV.", "journal": "Journal of clinical microbiology", "doi": "10.1128/jcm.30.7.1885-1890.1992", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1321215", "author": "Thomsen DR", "n_authors": 3, "title": "Expression of feline leukaemia virus gp85 and gag proteins and assembly into virus-like particles using the baculovirus expression vector system.", "abstract": "In order to test components of feline leukaemia virus (FeLV) as subunit vaccines, we have constructed recombinant baculoviruses that express the FeLV envelope glycoprotein gp85 [Autographa californica nuclear polyhedrosis virus (AcNPV)-gp85] and the structural protein, gag (AcNPVgag). The gag protein is expressed and shed into the medium of infected cells as particles which have a buoyant density on sucrose gradients and appearance by electron microscopy similar to those of authentic FeLV virions. The gag precursor protein within the particles is not fully processed and appears to be a result of partial cleavage of the gag polypeptide. Insect cells that are coinfected with AcNPVgag and AcNPVgp85 shed particles that contain both the gag protein and the gp85 glycoprotein.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-73-7-1819", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1321214", "author": "Wardley RC", "n_authors": 5, "title": "The use of feline herpesvirus and baculovirus as vaccine vectors for the gag and env genes of feline leukaemia virus.", "abstract": "The env and gag genes from feline leukaemia virus were expressed in a thymidine kinase-negative feline herpes-virus and a baculovirus. Cats were vaccinated with various combinations of these recombinant viruses and 100% protection against feline leukaemia virus challenge was achieved using an immunization schedule which utilized both env and gag products delivered at both a mucosal and systemic site.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-73-7-1811", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1320842", "author": "Tshikuka JG", "n_authors": 4, "title": "The microepidemiology of wasting syndrome, a common link to diarrheal disease, cancer, rabies, animal models of AIDS, and HIV-AIDS YHAIDS). The feline leukemia virus and rabies virus models.", "abstract": "Infant cats were inoculated intracranially with rabies or feline leukemia viruses in an experimental study of wasting syndrome. The daily pre- and postinoculation body weights were recorded until kittens were moribund. Affected animals in both groups manifested growth failure or wasting syndrome. Immunodepression, manifested by a conspicuous depletion of thymic cortex, the thymus dependent areas of the spleen, and growth hormone producing-alpha adenopituicytes was significantly (p less than 0.01) related to the wasting status of the animals. The ability of pituitary glands from these animals to produce growth hormone was studied by in situ immunoperoxidase staining and showed a significant (p less than 0.01) difference between healthy and wasted animals. Rabies and feline leukemia viruses were each found responsible for the low immunoreactivity of growth hormone producing alpha adenopituicytes. Because the hypothalamus and the hypophysis were both found infected, it was concluded that regardless of the triggering agent in primary wasting, the hypothalamic-hypophyseal-thymic axis was always involved through a decrease in growth hormone production.", "journal": "Annals of the New York Academy of Sciences", "doi": "10.1111/j.1749-6632.1992.tb19656.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1374984", "author": "Petry H", "n_authors": 6, "title": "Isolation and characterization of a retrovirus from the fish genus Xiphophorus.", "abstract": "A cell line (BsT) established from neoplastic embryonal tissues of the platyfish (Xiphophorus maculatus) released spontaneously retrovirus-like particles. The particles have a buoyant density of 1.16 g/ml, a mean diameter of 100 nm and the morphology of immature retroviruses. The particle-associated proteins p70, p65, and p28 react with an antiserum directed against the major internal feline leukemia virus structural protein p27. The particles are associated with a reverse transcriptase. The purified enzyme has a molecular weight of about 70 kDa and prefers the template primers poly(rA):oligo(dT), poly(dC):oligo(dG), and poly(rC):oligo(dG) in the presence of Mn2+. The enzyme activity is inhibited by antibodies directed against the reverse transcriptase of feline leukemia virus and simian sarcoma virus. The particles contain a ribonucleic acid of about 70 S. In an endogenous reverse transcriptase reaction nucleic acids in the range of 0.2 to 0.4 kb were synthesized. In Northern blots with these nucleic acids as probe, three transcripts of about 8.5, 4.2, and 1.5 kb were detected in BsT cells. Southern blot analysis with the same probe demonstrates related sequences in the DNA of BsT cells and the platyfish and swordtail (Xiphophorus helleri). Hybridization experiments with the LTR-gag region of the feline leukemia virus show homologous sequences in the Xiphophorus genome.", "journal": "Virology", "doi": "10.1016/0042-6822(92)90533-u", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1316674", "author": "Overbaugh J", "n_authors": 8, "title": "Structure and pathogenicity of individual variants within an immunodeficiency disease-inducing isolate of FeLV.", "abstract": "We previously described the molecular cloning of a replication-defective variant of feline leukemia virus (FeLV) that induced fatal immunodeficiency in cats. Eighteen proviruses have now been molecularly cloned from cats inoculated with the original isolate (FeLV-FAIDS) or its in vivo passages. Three were replication-competent and each of these was noncytopathic for the feline T-cell line, 3201. Replication of the prototype, FeLV-61E, in cats was associated with development of T cell tumors in some cats. The remaining 15 proviruses were replication-defective, but each of six of these tested was found to be cytopathic for 3201 cells when rescued with the noncytopathic helper virus, 61E. Three defective/helper virus mixtures were inoculated into cats and all induced fatal immunodeficiency, but with varied efficiency and kinetics. Each of these virus mixtures was attenuated relative to a mixture containing 61E and the intestine-targeted, FeLV-FAIDS-61C prototype defective molecular clone. Furthermore, one replication-competent virus chimera generated using the envelope and LTR of the defective pathogenic variant was incapable of inducing viremia in cats. The observed differences in the biological activity between the defective viruses could be attributed to no more than 10 scattered amino acid changes in envelope and either one or two nucleotide changes in the LTR.", "journal": "Virology", "doi": "10.1016/0042-6822(92)90510-v", "deposited_data": "Sim", "nuccore_ids": "323907, 323900", "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1316496", "author": "Pandey R", "n_authors": 6, "title": "Recombination between feline leukemia virus subgroup B or C and endogenous env elements alters the in vitro biological activities of the viruses.", "abstract": null, "journal": "Journal of virology", "doi": "10.1128/JVI.66.6.3976-.1992", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1316477", "author": "Ghosh AK", "n_authors": 4, "title": "Identification of a putative receptor for subgroup A feline leukemia virus on feline T cells.", "abstract": "Retrovirus infection is initiated by the binding of virus envelope glycoprotein to a receptor molecule present on cell membranes. To characterize a receptor for feline leukemia virus (FeLV), we extensively purified the viral envelope glycoprotein, gp70, from culture supernatants of FeLV-61E (subgroup A)-infected cells by immunoaffinity chromatography. Binding of purified 125I-labeled gp70 to the feline T-cell line 3201 was specific and saturable, and Scatchard analysis revealed a single class of receptor binding sites with an average number of 1.6 x 10(5) receptors per cell and an apparent affinity constant (Ka) of 1.15 x 10(9) M-1. Cross-linking experiments identified a putative gp70-receptor complex of 135 to 140 kDa. Similarly, coprecipitation of 125I-labeled cell surface proteins with purified gp70 and a neutralizing but noninterfering anti-gp70 monoclonal antibody revealed a single cell surface protein of approximately 70 kDa. These results indicate that FeLV-A binds to feline T cells via a 70-kDa cell surface protein, its presumptive receptor.", "journal": "Journal of virology", "doi": "10.1128/JVI.66.6.3707-3714.1992", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1316466", "author": "Terry A", "n_authors": 5, "title": "Pathogenesis of feline leukemia virus T17: contrasting fates of helper, v-myc, and v-tcr proviruses in secondary tumors.", "abstract": "A naturally occurring feline thymic lymphosarcoma (T17) provided the unique observation of a T-cell antigen receptor beta-chain gene (v-tcr) transduced by a retrovirus. The primary tumor contained three classes of feline leukemia virus (FeLV) provirus, which have now been characterized in more detail as (i) v-tcr-containing recombinant proviruses, (ii) v-myc-containing recombinant proviruses, and (iii) apparently full-length helper FeLV proviruses. The two transductions appear to have been independent events, with distinct recombinational junctions and no sequence overlap in the host-derived inserts. The T17 tumor cell line releases large numbers of FeLV particles of low infectivity; all three genomes are encapsidated, but passage of FeLV-T17 on feline fibroblast and lymphoma cells led to selective loss of the recombinant viruses. The oncogenic potential of the T17 virus complex was, therefore, tested by infection of neonatal cats with virus harvested directly from the primary T17 tumor cell line. A single inoculation of FeLV-T17 caused persistent low-grade infection culminating in thymic lymphosarcoma and acute thymic atrophy, which was accelerated by coinfection with the weakly pathogenic FeLV subgroup A (FeLV-A)/Glasgow-1 helper. Molecularly cloned FeLV-tcr virus (T-31) rescued for replication by a weakly pathogenic FeLV-A/Glasgow-1 helper virus was similarly tested in vivo and induced thymic atrophy and thymic lymphosarcomas. Most FeLV-T17-induced tumors manifested either v-myc or an activated c-myc allele and had undergone rearrangement of endogenous T-cell antigen receptor beta-chain genes, supporting the proposition that the oncogenic effects of c-myc linked to the FeLV long terminal repeat are targeted to a specific window in T-cell differentiation. However, neither the FeLV-T17-induced tumors nor the T-31 + FeLV-A-induced tumors contained clonally represented v-tcr sequences. Only one of the FeLV-T17-induced tumors contained detectable v-tcr proviruses, at a low copy number. While v-tcr does not have a readily transmissible oncogenic function, a more restricted role is not excluded, perhaps involving antigenic peptide-major histocompatibility complex recognition by the T-cell receptor complex. Such a function could be obscured by the genetic diversity of the outbred domestic cat host.", "journal": "Journal of virology", "doi": "10.1128/JVI.66.6.3538-3549.1992", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1381880", "author": "Weiss RC", "n_authors": 1, "title": "Immunologic responses in healthy random-source cats fed N,N-dimethylglycine-supplemented diets.", "abstract": "The immunomodulatory capacities of N,N-dimethylglycine (DMG) were examined in random-source cats. Blood mononuclear leukocytes of healthy adult cats that had negative results to tests for FeLV and feline immunodeficiency virus were exposed in vitro to various concentrations of DMG (10 to 1,000 micrograms/ml) and were evaluated for proliferative responses to T- or B-cell phytomitogens. Although increased, mean lymphocyte blastogenic responses to phytolectins in DMG-treated cultures did not differ significantly from responses of untreated cultures. For in vivo studies, cats were given a solution containing either 100 mg of DMG or a control solution without DMG orally at 8 AM and 6 PM for 40 consecutive days. On post-treatment day 24 and 25, mean blastogenic responses to phytolectins in DMG-treated and control cats inoculated 10 days earlier with an inactivated feline virus vaccine were similar. Cats given DMG and inoculated twice in a 3-week interval with a commercial vaccine containing inactivated feline herpesvirus-1 and feline calicivirus had significantly (P = 0.045) lower virus neutralizing serum antibody titers against feline herpesvirus-1, compared with titers of control cats, whereas feline calicivirus titers were similar in both groups. On day 25, mean serum interferon activity, induced after IV inoculation of Newcastle disease virus, was significantly (P = 0.021) lower in the DMG-treated cats. Results of this study of DMG in healthy cats failed to demonstrate enhancement of either specific or nonspecific immunity.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1313907", "author": "Levy LS", "n_authors": 2, "title": "Insertional mutagenesis of flvi-2 in tumors induced by infection with LC-FeLV, a myc-containing strain of feline leukemia virus.", "abstract": "LC-FeLV is a myc-containing strain of feline leukemia virus (FeLV) which exhibits only partial transforming activity in vitro and in vivo. LC-FeLV infection in kittens may induce, but does not necessarily induce, thymic lymphosarcoma in viremic animals after a short latency. These observations suggest that infection with LC-FeLV is not sufficient to induce complete transformation and that another genetic event(s) is required. One possibility for such an event is that the integrating provirus acts as an insertional mutagen and thereby disrupts the structure or function of another proto-oncogene. Using a strategy of transposon tagging, this possibility was examined in eight feline T-cell lymphosarcomas, including four induced by experimental infection with LC-FeLV, three induced by natural infection with FeLV, and one FeLV-negative tumor. The analysis demonstrated one locus, termed flvi-2, to be structurally altered in six of the tumors examined, including three induced by LC-FeLV and three in which no activated myc oncogene is apparent. Inverse polymerase chain reaction was used to demonstrate the presence and transcriptional orientation of proviruses integrated at flvi-2 in five of these tumors. The flvi-2 locus does not hybridize to cloned probes representing 21 previously identified proto-oncogenes or common domains of retroviral integration. Thus, the data suggest that interruption of the flvi-2 locus cooperates with the myc oncogene in the induction of T-cell lymphomas by LC-FeLV; indeed, the observations indicate that the insertional mutagenesis of flvi-2 plays a role in T-cell lymphomagenesis even in the absence of feline v-myc.", "journal": "Journal of virology", "doi": "10.1128/JVI.66.5.2885-2892.1992", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1317615", "author": "Callanan JJ", "n_authors": 7, "title": "Lymphosarcoma in experimentally induced feline immunodeficiency virus infection [corrected].", "abstract": "A cat experimentally infected with feline immunodeficiency virus (FIV) but known to be free of feline leukaemia virus (FeLV) developed lymphosarcoma. The lesions in the liver and kidneys were present nine months after infection, when the cat was 21 months old. The cat had no overt signs of immunodeficiency and it is suggested that the B cell activation induced shortly after FIV infection produced a large pool of proliferating lymphocytes from which the malignant cells emerged.", "journal": "The Veterinary record", "doi": "10.1136/vr.130.14.293", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1349933", "author": "Rojko JL", "n_authors": 10, "title": "Lymphocytotoxic strains of feline leukemia virus induce apoptosis in feline T4-thymic lymphoma cells.", "abstract": "Feline leukemia retrovirus (FeLV) strains with subgroup C env genes kill feline T4 lymphoma 3201 cells by 7 to 12 days after in vitro inoculation, whereas FeLV strains with subgroup A env genes do not. Neither FeLV-A nor FeLV-C kill feline fibroblasts. FeLV-C, but not FeLV-A, is replicated to higher titer by 3201 cells and productive infection precedes death by 3 to 7 days. Transcriptional activity of the FeLV-C long terminal repeat, as assessed by chloramphenicol acetyltransferase activity, is high in feline lymphoid cells but low in feline fibroblasts. Activity of the FeLV-A long terminal repeat is moderate in both cell types. FeLV-C-infected cells form aggregates 1 to 4 days before dying; ultrastructurally, virus particles can be seen approximating the clustered cells. Dying cells demonstrate nuclear condensation, surface blebbing, and fragmentation. DNA fragmentation and laddering compatible with apoptosis occur 1 to 2 days before massive cell death. In FeLV-C-infected 3201 cells, a shift from phospholipid to neutral lipid incorporation of [14C]oleic acid, increases in palmitic acid proportions and decreases in linoleic acid proportions occur 1 to 2 days before peak killing. Exposure of 3201 cells to ultraviolet-inactivated FeLV-KT (200-800 micrograms/10(6) cells) causes cytostasis within 2 days and death within 4 days. Blebbing and nuclear condensation occur but clusters do not form. The induction of programmed cell death in feline thymic lymphoma cells by subgroup C feline retroviruses may be relevant to the pathogenesis of FeLV-induced thymic atrophy, paracortical lymphoid depletion and acquired immunodeficiency in vivo.", "journal": "Laboratory investigation; a journal of technical methods and pathology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1324982", "author": "Gunasekera SP", "n_authors": 2, "title": "Fistularin 3 and 11-ketofistularin 3. Feline leukemia virus active bromotyrosine metabolites from the marine sponge Aplysina archeri.", "abstract": "Two brominated tyrosine metabolites, fistularin 3 [1] and a new compound 11-ketofistularin 3 [2] have been isolated from a marine sponge, Aplysina archeri. Their structures were determined on the basis of spectral data. Both compounds inhibited the growth of feline leukemia virus.", "journal": "Journal of natural products", "doi": "10.1021/np50082a020", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1319717", "author": "Hurtrel M", "n_authors": 8, "title": "Comparison of early and late feline immunodeficiency virus encephalopathies.", "abstract": "The study of the early and late stages of encephalopathy following infection by the feline immunodeficiency virus (FIV) was carried out with laboratory and naturally infected cats. Animals infected experimentally were injected with three different isolates of the virus, administered either intracerebrally or intravenously, and sacrificed at 7 days, 1 and 6 months (intracerebral injection), and 2, 6 and 12 months (intravenous injection) post-inoculation, respectively. General features of encephalopathy were found to be identical, regardless of the method of inoculation or the viral strain used. Moderate gliosis and glial nodules, sometimes associated with perivascular infiltrates and white matter pallor, were observed at 1 month (intracerebral injection) and 2 months (intravenous injection), and remained unchanged until 12 months post-inoculation. The fact that these initial stages are identical for intravenously and intracerebrally inoculated cats suggests that the virus enters the brain very quickly in intravenously infected animals. Encephalopathy in cats naturally infected with FIV only consisted of gliosis, glial nodules, white matter pallor, meningeal perivascular calcification and meningitis. These lesions were more frequent and more severe in the group coinfected with feline leukaemia virus and feline infectious peritonitis virus. Although multinucleated cells were rare, the strong similarities between HIV and simian immunodeficiency virus encephalopathies at comparable stages support the view that FIV infection may represent an interesting model for a physiopathological approach of HIV infection of the central nervous system.", "journal": "AIDS (London, England)", "doi": "10.1097/00002030-199204000-00007", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1319091", "author": "Gothe R", "n_authors": 4, "title": "[Trichomonad infections of the oral cavity in cats in south Germany].", "abstract": "In this investigation trichomonads were isolated from the oral cavity in 21 of 110 examined cats, and only from those which were simultaneously FeLV, FIV or FIP positive. By means of scanning electron microscopy the trichomonads were shown to be round or piriform parasites which were on average 7.9 microns long and 6.2 microns wide at maximum width. They had 4 anterior flagella, which were on average 9.4 microns long, an undulating membrane measuring 6.7 microns with no trailing flagellum as well as an axostyle extending on average 5.0 microns beyond the body, and therefore should be attributed to the genus Trichomonas.", "journal": "Tierarztliche Praxis", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1318063", "author": "Toedter G", "n_authors": 9, "title": "Development of a monoclonal antibody-based p24 capsid antigen detection assay for HTLV-I, HTLV-II, and STLV-I infection.", "abstract": "A monoclonal antibody-based antigen capture enzyme-linked immunosorbent assay (ELISA) was developed and employed to detect p24 capsid antigen from human T-cell lymphotropic viruses type I and II (HTLV-I, HTLV-II), simian T-cell lymphotropic virus type I (STLV-I)-infected cell lines, and from mononuclear cell cocultures of HTLV-infected humans and STLV-I infected monkeys. A monoclonal antibody specific for HTLV p24 and p53 capsid antigens was coated onto 96-well microtiter plates to capture HTLV/STLV antigen. Captured antigen was then detected by the addition of a polyclonal, biotinylated human anti-HTLV-I antibody, and color developed with tetramethyl benzidine/H2O2 substrate. As little as 15 pg/ml of HTLV-I p24 antigen could be detected in this assay. Culture supernatants from HTLV-I-infected cell lines (HUT-102, MT-2, C5/MJ, HTLV-II-infected cell lines (Mo-T, Mo-B, PanG 12.1, NRA) and STLV-I-infected cell lines (Matsu, NEPC M39) were all positive in the assay. In addition, p24 was detected from peripheral blood mononuclear cell (PBMC) cocultures of 8 of 8 (100%) HTLV-I diseased patients, 14 of 20 (70%) HTLV-I and HTLV-II-infected, asymptomatic persons, and 8 of 8 (100%) STLV-I-infected, asymptomatic monkeys. Culture supernatants of cells infected with human immunodeficiency virus type (HIV-1), simian immunodeficiency virus (SIV), Chlamydia trachomatis, cytomegalovirus (CMV), herpes simplex I and II (HSV), feline leukemia virus (FELV), bovine leukemia virus (BLV), and bovine immunodeficiency virus (BIV) were all negative. Similarly, normal human peripheral blood mononuclear cells and uninfected, transformed human T cells, were also negative in the assay.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "AIDS research and human retroviruses", "doi": "10.1089/aid.1992.8.527", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1316726", "author": "Hayes KA", "n_authors": 3, "title": "Incidence of localized feline leukemia virus infection in cats.", "abstract": "Anecdotal descriptions of atypical FeLV infections, wherein standard clinical ELISA or immunofluorescence testing fails to detect active infections, suggest that an unknown proportion of FeLV-infected cats may go undetected. In this study, 127 viremic and nonviremic cats experimentally inoculated with FeLV were evaluated at necropsy for atypical expression of FeLV antigen. Results from viremic cats were in accordance with results of earlier studies on the pathogenesis of FeLV infection in cats, wherein antigen was found in lymphoid and epithelial tissues. Differences in time course or tissue distribution of viral antigen in some cats appeared to be attributable to the challenge virus preparations, consisting of cell-free tumor homogenate or infectious plasma. It was discovered that 5 of 19 of the FeLV challenge-exposed cats that were nonviremic had FeLV-specific antigens in select tissues (bone marrow, spleen, lymph node, and small intestine) 6 to 75 weeks after inoculation. These results indicated an additional category of possible outcomes for cats exposed to FeLV. Localized FeLV infection, as described here, may explain the discordance between clinical disease and laboratory testing for FeLV.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1316351", "author": "Khan KN", "n_authors": 4, "title": "Cytotoxicity in feline leukemia virus subgroup-C infected fibroblasts is mediated by adherent bone marrow mononuclear cells.", "abstract": "The pathogenesis of retrovirus-induced erythroid aplasia in cats is unknown. In studies to define mechanisms of cytotoxicity associated with retroviral infections, bone marrow mononuclear cells (BMMC) from healthy specific pathogen-free cats were co-cultured with uninfected feline embryonic fibroblasts (FEA cells) and FEA cells infected with feline leukemia virus (FeLV) of subgroup A (FEA-A) or subgroup C (FEA-C). Moderate to marked cytotoxicity (CPE) developed in co-cultures of BMMC and FEA-C cells on Days 5 to 7 of incubation but not in co-cultures of BMMC and FEA-A or BMMC and uninfected cells (FEA-CT). Cytotoxicity was associated with adherent cells of light density (1.056) from bone marrow and peripheral blood, which were positive for alpha naphthyl butyrate esterase activity. Stimulation of adherent cells with phorbol ester or addition of recombinant human tumor necrosis factor-alpha (rhTNF-alpha) caused similar CPE in FEA-CT cells. The TNF-alpha concentrations in the culture supernatants of BMMC+FEA-C were higher than those of BMMC+FEA-A or BMMC+FEA-CT, and addition of anti-TNF antibodies to the cultures blocked the CPE. These data support the hypothesis that macrophages exposed to FeLV-C cause CPE in co-cultures of BMMC and FEA cells by a mechanism involving TNF-alpha. It is suggested that TNF-alpha may be involved in the suppression of hematopoiesis in cats which develop FeLV-C induced erythroid aplasia.", "journal": "In vitro cellular & developmental biology : journal of the Tissue Culture Association", "doi": "10.1007/BF02634242", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "34644821", "author": "Guaguere E", "n_authors": 3, "title": "Feline Pododermatoses.", "abstract": "Abstract- Pododermatoses are uncommon in the cat. Diagnosis is based on a detailed and thorough history including progression of the disease, its response to previous therapy, involvement of other animals or people, and the cats' environment. Physical examination of both the skin and the body, as a whole, is essential because feline pododermatoses are often associated with systemic disease such as feline leukaemia virus (FeLV), feline immunodefiency virus (FIV) and diabetes mellitus. Laboratory tests include skin scrapings, Wood's light examination, fungal culture, lesion smears, and skin biopsy. The latter is often the key to the diagnosis of feline pododermatoses. Other tests may include the intradermal skin test, patch testing and evaluation of endocrine function. Successful therapy of feline pododermatoses is dependent upon obtaining a definitive diagnosis. Résumé- Les pododermatites sont peu fréquentes chez le chat. Le diagnostic repose sur une anamnèse soignée comprenant l'évolution de la maldie, sa réponse aux traitements antérieurs l'atteinte d'autres animaux on de personnes et l'environnement du chat. L'examen clinique, de la peau et de l'enseble du corps comme un tout, est essentiel, les pododermatites félines étant souvent associées à des maladies générales telles que le FeLV, le FIV ou le diabète sucré. Les examens complémentaires comportent des raclages cutanés, un examen à la lampe de Wood, une culture fongique, des caiques des lésions et des biopsies. Cette derrière est souvent la clef du diagnostic d'une pododermatite féline. Les autres examens complémentaires peuvent ètre des intradermopréactions, des tests épicutanés et des tests hormonaux. Le succès du traitement d'une pododermatite féline dépend de la possibilité d'établir un diagnostic définitif. Zusammenfassung- Pododermatitis bei Katzen ist selten. DieDiagnose beruht auf einer detaillierten und sorgfältig erhobenen Anamnèse einschließlich des Verlaufs der Erkrankung, ihrem Ansprechen auf bereits durchgeführte Therapien, die Erkrankung weiterer Tiere oder Menschen sowie Angaben über die Lebensumstände der Katze. Die klinische Untersuchungen von Haut und dem Körper als Ganzes ist ein wesentlicher Punkt, da feline Pododermatosen oft mit systemischen Erkrankungen wie FeLV, FIV und Diabetes mellitus vergesellschaftet sind. Laboruntersuchungen schließben Hautgeschabsel, Untersuchungen mit der Wood-Lampe, Pilzkultur, Abklatschpräparate, der Hautveränderungen und Hautbiopsien mit ein. Letztere sind oft der Schlüssel zur Diagnose der felinen Pododermatitis. Andere diagnostische Methoden können intradermale Hauttests, Patchtests und überprüfung endokriner Organfunktionene beinhalten. Die erfolgreiche Behandlung der felinen Pododermatitis hängt davon ab, ob eine definitive Diagnose erstellt werden kann. Resumen  Pododermatosis es un hallazgo infrequente en el gato. El diagnóstico se basa en una historia detallada y completa incluyendo el curso de la enfermedad, respuesta a la terapia instaurada, si ha afectado a otros animales o personas, y el medio ambiente que rodea al gato. El examen fisico de ambos, piel y cuerpo, como si se tratase de una entidad única, és esencial, ya que las pododermatosis felinas se asocian frequentemente a enfermedades sistémicas como FeLV, FIV y diabetes mellitus. Los exámenes de laboratorio incluyen raspados cutáneos, investigación con la lámpara de wood, cultivos fungales, examinación microscópica directa del exudado, y biopsia cutánea. Esta última es frecuentemente la clave en el diagnóstico de la pododermatosis felina. Otros tests a llevar a cabo podrían ser pruebas cutáneas intradérmicas, tests de sensibilidad de contacto, y evalucación de la función endocrina. El éxito de la terapia depende de la obtención de un diagnóstico correcto.", "journal": "Veterinary dermatology", "doi": "10.1111/j.1365-3164.1992.tb00137.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1541910", "author": "Oostendorp RA", "n_authors": 5, "title": "Synthetic hexapeptides derived from the transmembrane envelope proteins of retroviruses suppress N-formylpeptide-induced monocyte polarization.", "abstract": "Retroviral infections are frequently associated with immunosuppression. Retroviral transmembrane envelope proteins (TM proteins) play an important role in this phenomenon. CKS-17, a synthetic heptadecapeptide, represents the immunosuppressive site of these retroviral TM proteins. Here we support on the further delineation of this immunosuppressive site using CKS-17-derived hexapeptides. The N-formyl-methionyl-leucyl-phenylalanine-induced monocyte polarization assay was used throughout this study because this monocyte function has been shown to be highly sensitive to TM protein p15E-related immunosuppression. We found that in addition to CKS-17 one CKS-17-derived hexapeptide, LDLLFL, reversibly inhibited monocyte polarization, with 50% inhibitory concentrations of 20 and 2 microM respectively. LDLLFL-mediated inhibition was sequence specific because the reverse peptide LFLLDL and scrambled peptides were not inhibitory. Hexapeptides corresponding to LDLLFL, but derived from various retroviruses other than murine leukemia virus, also inhibited monocyte polarization. Peptides most homologous to LDLLFL-LDILFL (feline leukemia virus) and LDLLFW (human T lymphotropic virus types I and II)--were the most potent inhibitors. Peptides homologous to primate and human endogenous proviruses were not suppressive. LDLLFL and some of its homologous also inhibited polarization of neutrophilic granulocytes. These findings lend further support to the view that conserved retroviral TM protein-related peptides can play an important role in suppression of inflammatory cell function as encountered in retrovirus-associated immunosuppression.", "journal": "Journal of leukocyte biology", "doi": "10.1002/jlb.51.3.282", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1317073", "author": "Bandecchi P", "n_authors": 7, "title": "Prevalence of feline immunodeficiency virus and other retroviral infections in sick cats in Italy.", "abstract": "Two hundred and seventy-seven sick pet cats living in Italy were tested for antibodies to feline immunodeficiency virus (FIV) and for feline leukemia virus (FeLV) antigen. Overall, 24% of the cats resulted positive for anti-FIV antibody and 18% for FeLV antigen. FIV was isolated from the peripheral mononuclear blood cells of ten out of 15 seropositive cats examined and from one out of eight saliva samples. No FIV isolations were obtained from six serum samples cultured. Feline syncytium forming virus (FeSFV) could be isolated from blood and/or saliva in ten out of 11 FIV seropositive cats examined, in six out of nine FeLV antigen positive cats, in two cats found positive for both infection markers, and in three out of 11 cats negative for both markers. Thus, the probability of isolating FeSFV was enhanced by infection with other exogenous retroviruses.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(92)90020-q", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1733113", "author": "Takeuchi Y", "n_authors": 5, "title": "Retroviral pseudotypes produced by rescue of a Moloney murine leukemia virus vector by C-type, but not D-type, retroviruses.", "abstract": "Human HOS cells containing a Moloney murine leukemia virus (Mo-MLV) recombinant genome were infected by a panel of retroviruses. The C-type viruses simian sarcoma associated virus, feline leukemia virus subgroup B, and the feline endogenous virus RD114 were able to form pseudotypes with the Mo-MLV genome, which transferred a selectable marker gene to target cells; however, Human T cell leukemia virus-1 and the D-type viruses Mason-Pfizer monkey virus and simian retrovirus-1 failed to rescue the Mo-MLV vector. Further characterization of the RD114 pseudotype demonstrated that it retained the receptor specificity of RD114 and will therefore prove useful in receptor characterization.", "journal": "Virology", "doi": "10.1016/0042-6822(92)90049-u", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1556164", "author": "Toth TE", "n_authors": 3, "title": "Simultaneous separation and purification of mononuclear and polymorphonuclear cells from the peripheral blood of cats.", "abstract": "Peripheral blood mononuclear cells (PBMC) and polymorphonuclear cells (PMNC) play important roles in immunodeficiency diseases and AIDS-like syndromes in cats caused by feline leukemia virus (FeLV) and presumably also when caused by feline immunodeficiency virus (FIV). For comparative or functional studies it is advantageous or necessary to obtain these cells as separate entities from the same sample of an animal. Therefore, we analyzed the technical parameters of obtaining, separating and purifying these cells simultaneously from several blood samples of several cats. Flow cytometric studies with outbred cats indicated that of various cell separation/purification methods, e.g. from lysed whole blood, by Histopaque 1.077 or 1.119 single-density, or by 1.077/1.119 double-density centrifugation, the 1.077/1.119 double-density centrifugation of diluted whole blood is the most consistent, practical and effective method of yielding both highly purified PBMC and PMNC as separate entities from the same sample. The interface between plasma and 1.077 contained an average 86% PBMC vs. 14% PMNC, and the interface between 1.077 and 1.119 an average of 2% PBMC vs. 98% PMNC. Lymphocytes separated by this method had an average CD4/CD8 T-cell ratio of 2.0. These data indicate that Histopaque 1.077/1.119 double-density gradient allows purification and physical separation of lymphocytes and phagocytes from a blood sample, enabling the investigator to examine both cell types from the same sample simultaneously.", "journal": "Journal of virological methods", "doi": "10.1016/0166-0934(92)90150-c", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1548176", "author": "Spodnick GJ", "n_authors": 4, "title": "Spinal lymphoma in cats: 21 cases (1976-1989).", "abstract": "Medical records of 21 cats with spinal lymphoma were reviewed. All cats were evaluated for neurologic deficits, although 85% of cats necropsied had multicentric disease. Eighty-one percent of cats had hind limb paresis. Results of FeLV tests were positive in 84.2% (16/19) of the cats, and 68.7% (11/16) of the cats had leukemic bone marrow. Spinal lymphoma was confirmed by necropsy in 13 cats, by examination of a biopsy specimen in 1 cat, and by examination of cells aspirated from an epidural lesion in 2 cats. In the remaining 5 cats, a presumptive diagnosis was made on the basis of neurologic examination findings, positive FeLV test results, and leukemic bone marrow. Nine cats were treated with chemotherapy alone. The complete remission rate was 50% in 6 cats given cyclophosphamide, vincristine, and prednisone. The median duration of complete remission was 14 weeks. Complete remissions were not observed in 3 cats given only corticosteroids. A single cat treated by laminectomy and postoperative chemotherapy had a prolonged remission (62 weeks). At necropsy, lymphoma of the CNS was limited to the vertebral canal in 10 of 13 cats; 2 cats had malignant tissue in the brain and vertebral canal, and in the remaining cat, the tumor extended into the brachial plexus. Most tumors extended over multiple vertebral bodies, and 4 cats had more than 1 level of spinal cord involvement. The lymphoma was high-grade lymphoblastic or immunoblastic type in all cats.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1371895", "author": "North J", "n_authors": 5, "title": "Photodynamic inactivation of retrovirus by benzoporphyrin derivative: a feline leukemia virus model.", "abstract": "The ability of a photosensitizer, benzoporphyrin derivative monoacid ring A (BPD-MA), and either broad-spectrum (400-1200 nm) or narrow-band (600-700 nm) red light to kill feline leukemia virus (FeLV) and FeLV-infected cat T cells (cell line 3201) was investigated in culture medium containing fetal calf serum and in blood from infected cats. A molecular clone of FeLV, 61E, is minimally pathogenic and productively infects 3201 cells while causing no change in rate of cell division, viability, or size. Active virus (either free or within infected cells) was quantified by using a limiting dilution assay that involved cocultivation of test samples with naive 3201 cells, after which either the polymerase chain reaction or a reverse transcriptase assay was used to detect the presence of virus. It was shown that 61E-infected T cells in culture were slightly more sensitive to photodynamic killing than were uninfected cells. Infected cells and free virus were eliminated from whole blood taken from infected cats by using 4 micrograms per mL of BPD-MA and 40 J per cm2 of red light. These results correlate well with previous results with BPD-MA and vesicular stomatitis virus in whole human blood and suggest that this photosensitizer is a promising agent for the elimination of retroviruses that are either free or located within infected cells in blood.", "journal": "Transfusion", "doi": "10.1046/j.1537-2995.1992.32292180139.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1316024", "author": "Ueland K", "n_authors": 2, "title": "Prevalence of feline leukemia virus and antibodies to feline immunodeficiency virus in cats in Norway.", "abstract": "Serum samples from 224 Norwegian cats were analyzed for the presence of feline leukemia virus (FeLV) p27 common core antigen, and for antibodies to feline immunodeficiency virus (FIV). Ninety specimens originated from the serum bank at the central referral clinic at the Norwegian College of Veterinary Medicine, which had been collected during the years 1983-1989; 67 sera were submitted from veterinarian practitioners; while 67 sera originated from cats presented for euthanasia. The cats were classified into one \"healthy\" and one \"sick\" group. Only 2.2% of sick cats and 1.2% of healthy cats showed FeLV antigenemia, a finding which is lower than which has been reported from many other countries. The prevalence of FIV antibodies was 10.1% in sick cats and 5.9% in healthy cats. Antibodies to FIV was most prevalent in male cats (14.7%) than in female cats (2.1%), and more prevalent among domestic cats (12.0%) compared to pedigree cats (2.4%). Antibodies to FIV in the cats demonstrated increasing prevalence with increasing age. It may be concluded that FeLV causes minor problems in Norwegian cats, while FIV is present in a similar prevalence to what is reported from other countries.", "journal": "Zentralblatt fur Veterinarmedizin. Reihe B. Journal of veterinary medicine. Series B", "doi": "10.1111/j.1439-0450.1992.tb01137.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1313618", "author": "Hohdatsu T", "n_authors": 10, "title": "Detection of feline immunodeficiency proviral DNA in peripheral blood lymphocytes by the polymerase chain reaction.", "abstract": "Feline immunodeficiency virus (FIV) proviral DNA was detected by the polymerase chain reaction method (PCR). PCR products were detected by gel electrophoresis and ethidium bromide staining. The P-10, P-15 and P-24 regions of the gag gene of FIV were chosen as the target sequences for amplification, and three primer pairs were prepared. The PCR products subjected to amplification with each primer pair were found to possess sites of digestion by a restriction enzyme, as hypothesized. They did not react with feline leukemia virus (FeLV)-infected or feline syncytium-forming virus (FeSFV)-infected cell-derived DNA, and specifically amplified FIV-infected cell-derived DNA. FIV proviral DNA was detected by the PCR method with either primer pair (one-step amplification: single PCR) in DNA derived from peripheral blood lymphocytes (PBL) from 7 of 12 FIV antibody-positive cats. When PCR products in each of the 12 cats were subjected to a second amplification using the same primer pair (two-step amplification: double PCR), FIV proviral DNA was detected in all of the cats. When PBL samples collected from three cats that were negative and three that were positive in the single PCR were cultured for a few weeks in the presence of interleukin 2, FIV proviral DNA was detected in all six cats by the single PCR method. The results suggest that either the use of cultured PBL as the sample or the performance of the double PCR method enables simple and specific detection of FIV proviral DNA in PBL.", "journal": "Veterinary microbiology", "doi": "10.1016/0378-1135(92)90107-5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1309898", "author": "Takeuchi Y", "n_authors": 6, "title": "Feline leukemia virus subgroup B uses the same cell surface receptor as gibbon ape leukemia virus.", "abstract": "Pseudotypes of gibbon ape leukemia virus/simian sarcoma-associated virus (GALV/SSAV) and feline leukemia virus subgroup B (FeLV-B) have been constructed by rescuing a Moloney murine leukemia virus vector genome with wild-type GALV/SSAV or FeLV-B. The resulting recombinant viruses utilized core and envelope proteins from the wild-type virus and conferred resistance to growth in L-histidinol upon infected cells by virtue of the HisD gene encoded by the vector genome. They displayed the host range specificity of the rescuing viruses and could be neutralized by virus-specific antisera. Receptor cross-interference was observed when the GALV/SSAV or FeLV-B pseudotypes were used to superinfect cells productively infected with either GALV/SSAV or FeLV-B. Although murine cells are resistant to FeLV-B infection, murine cells expressing the human gene for the GALV/SSAV receptor became susceptible to FeLV-B infection. Therefore GALV/SSAV and FeLV-B utilize the same cell surface receptor.", "journal": "Journal of virology", "doi": "10.1128/JVI.66.2.1219-1222.1992", "deposited_data": "Sim", "nuccore_ids": "2501363558, 2501363550, 2501356983, 2501356593, 1519311779, 1243938578, 2501363558, 2501363550, 2501356983, 2501356593, 1907137055, 1907137051, 1519311779, 1243938578", "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "21390720", "author": "Burns NR", "n_authors": 5, "title": "Production and Purification of Hybrid Ty-VLPs.", "abstract": "The self-assembly properties of a protein encoded by the TYA gene of the yeast Ty element can be exploited to produce hybrid Ty-VLPs (virus-like particles) (1,2). There has been developed a series of expression vectors that allow the construction of Ty fusion genes containing protein coding sequences of interest (see Chapter 24 ). Many different hybrid Ty-VLPs have now been produced that carry additional proteins that range in size from 3 to 42 kDa. These include regions from human immunodeficiency virus-1 (HIV-1) env, pol, tat, rev, nef, and vif genes; influenza virus hemagglutinin; human α-interferon, feline leukemia virus env, and bovine papillomavirus El and E2 (1-5 and unpublished data).", "journal": "Methods in molecular biology (Clifton, N.J.)", "doi": "10.1385/0-89603-191-8:277", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1617193", "author": "Corash L", "n_authors": 3, "title": "Use of 8-methoxypsoralen and long wavelength ultraviolet radiation for decontamination of platelet concentrates.", "abstract": "Transmission of viral diseases through blood products remains a problem in transfusion medicine. We have developed a photochemical decontamination system (PCD) for platelet concentrates (PC) utilizing treatment with long wavelength ultraviolet radiation (UVA, 320-400 nm) and 8-methoxypsorlan (8-MOP). This system is capable of inactivating 25-30 logs/hour of bacteria E. coli or S. aureus, 6 logs/hour of bacteriophage fd, 0.9 log/hour of bacteriophage R17, and 1.1 logs/hour of feline leukemia virus (FeLV) in PC. Immediately following 6 hours of PCD treatment, platelet integrity and function of PCD-treated and control PC were equivalent. After overnight storage, PCD-treated and control PC platelet properties were equal, but there was a slight reduction in TXB-2 production of PCD-treated PC compared to controls. Following PCD treatment, PC were stored for 48 to 96 hours. Platelet counts, morphology scores, extracellular LDH levels, aggregation response, dense body (db) content, and alpha granule (alpha g) content of PCD-treated and control PC were comparable. We assessed the ability of the PCD technique to inactivate intracellular and extracellular virus, quantified the degree of DNA adduct formation in contaminating lymphocytes, and measured the inhibition of polymerase chain reaction (PCR) mediated amplification of intracellular DNA. High titers of cell-free murine cytomegalovirus added to human platelet concentrates (final concentration 10(6)) were inactivated by PCD within 30 minutes. Cat renal fibroblasts infected at high levels with feline rhinotracheitis virus (FeRTV) were seeded into PC followed by PCD treatment with inactivation of 4.8 logs of FeRTV within 10 minutes. Purified human lymphocytes were seeded into PC and treated with PCD in the presence of 3H 8-MOP. Six hours of PCD treatment resulted in the formation of 9.3 to 12.8 8-MOP adducts per 1000 base pairs (bp) of DNA. PCR amplification of a 242 bp segment at the HLA-DQ alpha locus was examined. Inhibition of PCR DNA amplification was dependent on the numbers of 8-MOP adducts formed, and no amplification was present when greater than 12 adducts per 1000 bp were formed. These studies indicate that PCD can effectively inactivate high titers of cell-associated and cell-free virus seeded into standard human PC. The efficiency of DNA adduct formation can be quantitated, and the level of 8-MOP adduct formation in lymphocytes contaminating PC is comparable to the level of adduct formation in cellular DNA reported in the absence of platelets.", "journal": "Blood cells", "doi": "10.1117/12.137506", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1556256", "author": "Erdman SE", "n_authors": 4, "title": "Malignant lymphoma in ferrets: clinical and pathological findings in 19 cases.", "abstract": "The clinical and pathological findings in 19 ferrets (Mustela putorius furo) with malignant lymphoma are reviewed. Peripubescent ferrets had rapidly progressive stage IV high grade immunoblastic or small non-cleaved cell lymphoma. Adult ferrets had stage II or IV low grade diffuse small lymphocytic (DSL) lymphoma, stage IV high grade small non-cleaved cell lymphoma, or stage IV high grade immunoblastic polymorphous (IBP) lymphoma. Three ferrets had concurrent IBP and DSL lymphoma involving different organs. The IBP admixture of immunoblasts, large atypical lymphocytes, Reed-Sternberg-like cells, lymphoblasts and small lymphocytes has been associated with certain retrovirally associated lymphomas and nodal hyperplasias in man, non-human primates and cats. Aleutian disease, a parvovirus-induced lymphoproliferative disease, also involves clinical and histological features similar to certain lymphomas in ferrets. Seven ferrets tested were seronegative for feline leukaemia virus antigen. Only one of eight ferrets was positive for Aleutian parvovirus antibody. The clinical and pathological findings are suggestive of a viral aetiology for certain lymphomas in ferrets.", "journal": "Journal of comparative pathology", "doi": "10.1016/0021-9975(92)90066-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1336930", "author": "Sukura A", "n_authors": 4, "title": "Association between feline immunodeficiency virus antibodies and host characteristics in Finnish cats.", "abstract": "Toward the end of 1989 the largest private veterinary laboratory in Finland (Vet/lab) began using a commercial combined ELISA test for Feline Immunodeficiency Virus (FIV) antibodies and Feline Leukemia Virus (FeLV) antigens (Cite Combo). The overall proportion of FIV seropositive feline samples was 5% during the 22 month study period. The number of tests performed increased slowly while the positive test results decreased with time (7% in 1990 and 4% in 1991). The decrease in prevalence was assumed to reflect a change in the sample population rather than an actual change in the general cat population. There were more symptomatic and domestic cats tested in 1990 than 1991. The lower-risk groups in the second year of the study may simply be an indication that the cat owners became more aware of FIV and the motivation to send samples switched from the veterinarian's interest to diagnose the disease in a symptomatic cat to the owner's interest to survey their cats for possible FIV infection. In a multivariable analysis, breed, symptoms, age and sex were associated with the risk of FIV seropositivity. The risk increased faster with age in males than in females (i.e., the age effect was not constant between sexes). The cats with symptoms had a higher risk than those without symptoms and non-purebred cats were at a higher risk than purebred cats. FeLV infection was not associated with FIV.", "journal": "Acta veterinaria Scandinavica", "doi": "10.1186/BF03547298", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1333753", "author": "Meers J", "n_authors": 5, "title": "Feline immunodeficiency virus: quantification in peripheral blood mononuclear cells and isolation from plasma of infected cats.", "abstract": "The titer of feline immunodeficiency virus in peripheral blood mononuclear cells (PBMC) and the presence of infectious virus in plasma was investigated over 20 week period in 8 experimentally infected cats, 3 uninfected cats and 2 naturally infected cats by end point dilution cultures using a feline T-lymphoblastoid cell line (MYA-1). FIV was isolated from PBMC of all infected cats, but not from the uninfected cats. FIV was also isolated consistently from 100 microliters plasma from most of the experimentally infected cats, but not from the 2 naturally infected cats. The virus titer in PBMCs in both experimentally and naturally infected cats was comparatively high, ranging from 10 TCID/10(6) PBMC to 14,286 TCID/10(6) PBMC. The titers in PBMC of individual cats remained unchanged or varied only slightly over the 20 week period. In contrast, the titers varied substantially between cats, with significantly higher titers in the youngest litter (4 cats) than in the oldest litter (3 cats). This suggests that there is an age-related factor influencing the level of PBMC virus titers in experimental infection with FIV. A similar age-related susceptibility has been shown with feline leukemia virus. More importantly, the sustained titers in the experimentally infected cats bear close resemblance to infection of children with human immunodeficiency virus. These data reinforce suggestions that age and immune maturity have a fundamental influence on PBMC and plasma titers in lentivirus infections.", "journal": "Archives of virology", "doi": "10.1007/BF01309587", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1327427", "author": "Rezanka LJ", "n_authors": 3, "title": "Feline leukemia virus: pathogenesis of neoplastic disease.", "abstract": null, "journal": "Cancer investigation", "doi": "10.3109/07357909209024796", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1319771", "author": "North J", "n_authors": 4, "title": "Viral inactivation in blood and red cell concentrates with benzoporphyrin derivative.", "abstract": "Using both the vesicular stomatitis virus (VSV) and feline leukemia virus (FeLV) as models we have shown that the photosensitizer benzoporphyrin derivative ring A (BPD), when activated with red light (600-700 nm), is effective in eliminating both free virus and virally infected cells from spiked blood products and whole blood drawn from viremic cats experimentally infected with FeLV, under conditions which appear to share red blood cells. The effect of photodynamic therapy on infected lymphocytes, as visualized by scanning electron microscopy, initially appeared as a limited area of tiny holes in the membrane. These holes were subsequently seen to increase in size until the membrane appeared completely decomposed. The red cell membranes however, seem to be undamaged by such photodynamic treatment.", "journal": "Blood cells", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1318467", "author": "Jarrett O", "n_authors": 1, "title": "Pathogenicity of feline leukemia virus is commonly associated with variant viruses.", "abstract": "Many of the serious diseases resulting from feline leukemia virus (FeLV) infection are associated with the generation of novel variant viruses. The prototype FeLV-A virus is highly stable and circulates in the cat population without apparent antigenic change. However, recombination with cellular oncogenes produces viruses which cause leukemia or other malignant diseases. Other recombinants within the env genes of FeLV-A and endogenous FeLV are recognized as belonging to a second subgroup, FeLV-B, the presence of which is correlated with an increased risk of infection with FeLV and a higher incidence of leukemia. Mutants of FeLV which affect the env gene are phenotypically of a third subgroup, FeLV-C, and have a close association with erythroid aplasia. None of these viruses, apart from FeLV-B, is transmitted further in nature. Therefore the generation of these novel viruses and the production of disease is an inadvertent consequence of FeLV infection.", "journal": "Leukemia", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1317991", "author": "Sukura A", "n_authors": 3, "title": "A survey of FIV antibodies and FeLV antigens in free-roaming cats in the capital area of Finland.", "abstract": "Feline immunodeficiency virus (FIV) was first isolated and identified in 1986. Since then it has been shown to have a worldwide distribution, and the infection generally appears to have reached a state of endemicity. This is the 1st study of FIV-prevalence in Finland. Serum samples of 196 free-roaming cats were tested for antibodies to FIV and FeLV antigens (Feline leukemia virus). With a combined enzyme-linked immunosorbent assay (ELISA), 13 of the cats (6.6%) turned out to be positive for FIV and 2 for FeLV (1.0%). Adult male cats in the capital area of Finland had a FIV prevalence of 24%, a relative proportion 4.7 times higher than that for females.", "journal": "Acta veterinaria Scandinavica", "doi": "10.1186/BF03546930", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1316189", "author": "Kopelovich L", "n_authors": 1, "title": "Conversion of human fibroblasts to tissue macrophages by the Snyder-Theilen feline sarcoma virus (ST:FeSV): tumoricidal potential in monolayers and in agar suspensions.", "abstract": "In earlier studies [1-3], we have demonstrated the conversion of human fibroblasts (HF) to tissue macrophages (TM) by the Snyder-Theilen feline sarcoma virus (ST:(FeSV)). The purpose of the present study is to determine the cytolytic potential of ST:FeSV(FeLV)-induced TM against tumorigenic target cells under defined conditions in vitro. The results show that ST:FeSV-induced TM, but not mock-infected HF, produced significant lysis of human colon adenocarcinoma cells (LS-180) after a 3-day preincubation period, followed by a 4-day coincubation period at an effector to target cell ratio of 5:1. The presence of IFN-gamma, or lipopolysaccharides (LPS), and especially of M-CSF, during the coincubation period generally yielded optimal lysis of the tumor cells. Addition of LS-180 specific antibody (NRCO-4) substantially increased the cytolytic potential of TM. Significantly, coincubation of TM with LS-180 tumor cells in an agar medium, where no direct contact between cells occurs, resulted in the inhibition of tumor cell proliferation. Addition of LPS has further accentuated this inhibition. The results indicate that ST:FeSV-induced macrophages are potent oncocytolytic agents of LS-180 tumor cells in the absence and in the presence of direct contact between effector and target cells.", "journal": "European cytokine network", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1312884", "author": "Cotter SM", "n_authors": 1, "title": "Feline leukemia virus: pathophysiology, prevention, and treatment.", "abstract": null, "journal": "Cancer investigation", "doi": "10.3109/07357909209032778", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8254466", "author": "Tochikura TS", "n_authors": 10, "title": "Fusion activity dissociated from replication ability in feline immunodeficiency virus (FIV) in human cells.", "abstract": "Multinucleated-giant-cell formation followed by cell killing was observed after cocultivation of the feline immunodeficiency virus (FIV)-producing feline T-cell line 3201/FIV with various human cells, including T-cell lines carrying human T-cell lymphotropic virus type I (HTLV-I). The susceptibility to giant cell formation varied with the cell lines tested. Cocultivation of irradiated 3201/FIV cells with MT-2 cells resulted in giant cell formation as early as 2 h in culture, with striking resemblance to that induced by human immunodeficiency virus (HIV). MT-4 cells (HTLV-I positive) and H9 cells (HTLV-I negative) were less susceptible than MT-2 to the induction of syncytia. MOLT-4 cells (HTLV-I negative) had intermediate sensitivity to syncytia formation. No syncytia were observed in the monocytic cell line U-937 (HTLV-I negative). Syncytia formation between 3201/FIV and MT-2 cells was inhibited by polyclonal cat anti-FIV antisera but not polyclonal cat anti-feline leukemia virus (FeLV) antisera, goat anti-FeLV, uninfected specific-pathogen-free cat serum, human anti-HTLV-I antisera, or normal human and goat serum. Concentrated cell-free FIV supernatant from 3201/FIV also induced giant cells of MT-2 cells that were indistinguishable from those induced by cocultivation. Giant cells and extensive cell killing associated with giant cell formation declined and disappeared within 10 days. Surviving cells appeared to be of normal size and grew continuously without expressing FIV antigen or releasing infective virus. Although Southern blot analysis using probes specific for FIV could not detect proviral DNA in any of the five human cell lines cocultured with irradiated 3201/FIV cells, the polymerase chain reaction (PCR) technique detected FIV-specific DNA in MOLT-4 cells. DNA from the FIV-PCR positive MOLT-4 cells was PCR negative for endogenous FeLV-specific sequences, indicating that the MOLT-4 cell DNA was not contaminated with DNA from feline cells (i.e., 3201 cells). The FIV-MOLT-4 cells remained PCR positive for FIV after 40 passages, suggesting stable integration in the human cell line. These findings indicate that FIV is capable of forming proviral DNA in human T-lymphoid cells by cocultivation, although this FIV-carrying human cell line failed to produce replication-competent viruses.", "journal": "Journal of acquired immune deficiency syndromes", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8122242", "author": "Hartmann K", "n_authors": 2, "title": "[Retrovirus infections of the cat: feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV). A review from the clinical viewpoint].", "abstract": "Diseases caused by FeLV are very variable. They can be classified in FeLV associated, proliferative and neoplastic signs. Moreover there are other nonspecific diseases and clinically inapparent infections. FeLV as well as FIV may cause immunodeficiency syndromes; this is the main problem in FIV infections. In contrast to humans FIV does not induce specific secondary diseases. Positive diagnostic results obtained by use of commercial test kits must be verified by other methods. Methods of treatment and their problems are discussed.", "journal": "Tierarztliche Praxis", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8296439", "author": "Mainland TR", "n_authors": 1, "title": "FeLV vaccination.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.133.20.508-a", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8411376", "author": "Tailor CS", "n_authors": 6, "title": "Mutation of amino acids within the gibbon ape leukemia virus (GALV) receptor differentially affects feline leukemia virus subgroup B, simian sarcoma-associated virus, and GALV infections.", "abstract": "The three type C retroviruses, gibbon ape leukemia virus (GALV), simian sarcoma-associated virus (SSAV), and feline leukemia virus subgroup B (FeLV-B), infect human cells by interacting with the same cell surface receptor, GLVR1. Using LacZ retroviral pseudotypes and murine cells transfected with mutant GLVR1 expression vectors, we show that the same 9-amino-acid region of human GLVR1 is critical for infection by the three viruses. Rat cells were not susceptible to infection by LacZ (FeLV-B) pseudotypes because of a block at the receptor level. We found multiple amino acid differences from human GLVR1 in the 9-amino-acid critical region of rat GLVR1. Expression of a human-rat chimeric GLVR1 in murine cells demonstrated that rat GLVR1 could function as a receptor for GALV and SSAV but not for FeLV-B. Substitution of human GLVR1 amino acids in the critical region of rat GLVR1 identified three amino acids as responsible for resistance to FeLV-B infection; two of these affect SSAV infection, but none affects GALV infection.", "journal": "Journal of virology", "doi": "10.1128/JVI.67.11.6737-6741.1993", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8292850", "author": "Fontenot JD", "n_authors": 5, "title": "Synthesis of large multideterminant peptide immunogens using a poly-proline beta-turn helix motif.", "abstract": "We report the synthesis and characterization of a novel secondary structural motif, the poly-proline beta-turn helix. This motif is found in the proline-rich immunogenic domains of feline retroviruses, mucins and many proline-rich tandem repeat-containing surface proteins. We describe the synthetic methodology to directly synthesize natural and engineered immunogens of up to 100+ amino acids. Using manual solid-phase peptide synthesis modified for optimal efficiency, we directly synthesized 1, 2, 3, 4 and 5.25 tandem repeats corresponding to 20, 40, 60, 80, 105 amino acids of the human mucin muc-1, the complete 60 amino acid proline-rich neutralization domain of feline leukemia virus, and 70 and 72 amino acids of two very hydrophobic engineered tandem repeat proteins. High pressure liquid chromatography and mass spectrometry results indicate that the desired peptide can be synthesized up to 92% pure. The secondary structures of these peptides were studied using circular dichroism (CD) spectroscopy. The CD spectra revealed a characteristic intense negative band at 198 nm. A melting of structure could be demonstrated with increasing temperature as measured by decreasing molar ellipticity at 198 nm. The intensity of the molar ellipticity at 198 nm, as compared to the molar ellipticity of random coil, non-proline-containing peptides, led to the conclusion that the large, intense negative band at 198 nm is diagnostic of the poly-proline beta-turn helix.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "Peptide research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8279119", "author": "Vivian JS", "n_authors": 1, "title": "FeLV vaccination.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.133.17.432-b", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8396818", "author": "Levy LS", "n_authors": 6, "title": "Coincident involvement of flvi-2, c-myc, and novel env genes in natural and experimental lymphosarcomas induced by feline leukemia virus.", "abstract": "The flvi-2 locus is a target of insertional mutagenesis in thymic lymphosarcomas induced by feline leukemia virus (FeLV). flvi-2 encodes the gene bmi-1, whose product is implicated as a myc-collaborator in the induction of B- and T-cell lymphoma. We have examined the involvement of flvi-2 and myc in natural and experimentally induced FeLV-positive feline lymphosarcomas which are heterogeneous in anatomical origin, geographic origin, and strain of FeLV involved. We further compared these findings with previous reports of novel FeLV env genes in the same tumors. The results show that proviral insertion at flvi-2 occurs commonly in natural and experimental feline thymic lymphosarcomas of diverse origins [52% overall], and that alterations in c-myc commonly accompany insertional mutagenesis of flvi-2 [54% overall]. However, 46% of tumors with flvi-2 insertions apparently lack involvement of c-myc. These observations support the hypothesis that interruption of flvi-2 may be an early event in a multistep cascade, one possibility for completion of which is activation of c-myc. Interruption of flvi-2 was not observed in nonthymic lymphosarcomas of alimentary or multicentric origin, although c-myc may be involved. A proportion of both thymic and nonthymic tumors have been shown previously to contain FeLV proviruses with recombinant or mutant env genes. Our findings strongly implicate the insertional mutagenesis of flvi-2, the activation of c-myc, and the emergence of novel env genes in FeLV-mediated lymphomagenesis, particularly in the induction of thymic lymphosarcoma. The data show that these events may overlap, but do not necessarily occur concurrently.", "journal": "Virology", "doi": "10.1006/viro.1993.1553", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8396812", "author": "Tsujimoto H", "n_authors": 10, "title": "A common proviral integration region, fit-1, in T-cell tumors induced by myc-containing feline leukemia viruses.", "abstract": "Feline leukemia viruses carrying transduced v-myc genes (myc-FeLV) induce tumors of clonal origin, suggesting that activated myc alone is not sufficient for tumorigenesis. To investigate the hypothesis that insertional mutagenesis plays a role by activating genes which collaborate with v-myc, we looked for evidence of common proviral integration sites in these tumors. By inverse polymerase chain reaction we identified a 6-kb domain, designated fit-1, in which FeLV proviruses were inserted in four of nine (44%) T-cell tumors induced by myc-FeLV. The fit-1 locus was mapped to feline chromosome B2 and appears to be distinct from known oncogenes located on this chromosome. Fit-1 represents a novel common proviral integration region which may harbor a cellular gene which acts in concert with the myc gene in T-cell tumorigenesis.", "journal": "Virology", "doi": "10.1006/viro.1993.1544", "deposited_data": "Sim", "nuccore_ids": "5359632", "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8396654", "author": "Thomas E", "n_authors": 2, "title": "Delayed cytopathicity of a feline leukemia virus variant is due to four mutations in the transmembrane protein gene.", "abstract": "Two molecularly cloned, replication-defective variants of feline leukemia virus, called 61B and 61C, have both been shown to cause fatal immunodeficiency in cats when coinfected with a replication-competent, minimally pathogenic helper virus, but 61B exhibits a longer latency period between infection and disease (J. Overbaugh, E. A. Hoover, J. I. Mullins, D. P. W. Burns, L. Rudensey, S. L. Quackenbush, V. Stallard, and P. R. Donahue, Virology 188:558-569, 1992). Infection of the 3201 feline T-cell line with 61B plus helper virus also results in longer time from infection to cytopathic effect compared with 61C plus helper virus, providing an in vitro system with which to study the mechanism for this difference. We report that the primary determinant of cytopathicity of 61B maps to gp70, the extracellular envelope glycoprotein. The long latency of 61B, on the other hand, maps to the extracellular portion of the envelope transmembrane protein, in which there are only four predicted amino acid differences between 61B and 61C. These differences render 61B replication defective, and two of the predicted amino acid changes lie in a region that is highly conserved among many retroviruses. The eventual onset of 61B cytopathicity in cell culture was associated with the outgrowth of an apparent recombinant virus that encodes the pathogenic gp70 of 61B and replaces the transmembrane protein of 61B with that of the helper virus. Thus, during in vitro infection, a cytopathic virus evolved from a replication-defective virus and a nonpathogenic virus, suggesting that recombination between multiple variants in natural infection may influence progression of feline leukemia virus-associated immunodeficiency disease.", "journal": "Journal of virology", "doi": "10.1128/JVI.67.10.5724-5732.1993", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8286547", "author": "Goitsuka R", "n_authors": 9, "title": "Establishment and characterization of a feline large granular lymphoma cell line expressing interleukin 2 receptor alpha-chain.", "abstract": "A feline large granular lymphocyte (LGL) cell line was established from a cat with an alimentary-form lymphoma. This cell line, designated as FGL, had many large azurophilic granules in the cytoplasm, which were typical to LGL cells. Proviral genome of feline leukemia virus was detected in the chromosomal DNA of FGL cells, and reverse transcriptase activity was also demonstrated in the culture supernatant. Furthermore, we found expression of interleukin 2 (IL-2) receptor alpha-chain on the cell surface of FGL and its natural killer activity against human erythroblastic leukemia cell line, K562.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.55.863", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8269365", "author": "Jackson ML", "n_authors": 4, "title": "Feline leukemia virus detection by immunohistochemistry and polymerase chain reaction in formalin-fixed, paraffin-embedded tumor tissue from cats with lymphosarcoma.", "abstract": "The prevalence of feline leukemia virus (FeLV) antigen and DNA was assessed in formalin-fixed, paraffin-embedded tumor tissues from 70 cats with lymphosarcoma (LSA). Tissue sections were tested for FeLV gp70 antigen using avidinbiotin complex (ABC) immunohistochemistry (IHC); DNA was extracted and purified from the same tissue blocks for polymerase chain reaction (PCR) amplification of a 166 base pair region of the FeLV long terminal repeat (LTR). Results were related to antemortem FeLV enzyme-linked immunosorbent assay (ELISA) for serum p27 antigen, anatomic site of LSA, and patient age. Viral DNA was detected by PCR in 80% of cases and viral antigen by IHC in 57% of cases. Seventeen cases were PCR-positive and IHC-negative; one case was PCR-negative and IHC-positive. Clinical records included FeLV ELISA results for 30 of 70 cats. All 19 ELISA-positive cats were positive by PCR and IHC; of the 11 ELISA-negative cats that were negative by IHC, seven were positive by PCR. When evaluated according to anatomic site, FeLV DNA and antigen were detected less frequently in intestinal LSAs than in multicentric and mediastinal tumors. Lymphosarcoma tissues from cats < 7 yr were several fold more likely to be positive for FeLV antigen by IHC than were tumors from cats > or = 7 yr. However, there was no significant difference in PCR detection of FeLV provirus between LSAs from cats < 7 yr and those > or = 7 yr.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "Canadian journal of veterinary research = Revue canadienne de recherche veterinaire", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8226238", "author": "Nasisse MP", "n_authors": 5, "title": "Clinical and laboratory findings in chronic conjunctivitis in cats: 91 cases (1983-1991).", "abstract": "Clinical findings and laboratory test results from 91 cats with chronic conjunctivitis were studied to determine the causes of the disease and the sensitivity of diagnostic procedures used, and to identify correlations between results of various diagnostic procedures and clinical or signalment variations. Mean age of affected cats was 2.9 +/- 2.7 years (+/- SD), with a range from 1 month to 11 years. Conjunctivitis was more likely to be bilateral (56 cats) than unilateral (35 cats). In cats tested for FeLV or feline immunodeficiency virus infection, 15 and 8.5%, respectively, of the results were positive, compared with 4 and 2.6% for the general hospital population. Culturing or immunofluorescent assay (IFA) for feline herpesvirus 1 (FHV-1) and Chlamydia psittaci IFA resulted in identification of pathogens (positive test results) in 19% (FHV-1) and 18% (C psittaci) of tested cats. For FHV-1, culturing was more sensitive than was IFA, yielding positive results in 19 vs 8.8% of cases. In only 1 cat were FHV-1 and chlamydiae recovered. The probability of positive test results for FHV-1 or chlamydiae was unrelated to concurrent corneal disease, unilateral vs bilateral involvement, or age. Cause of conjunctivitis could not be definitively determined in the remaining 35 cases tested for both agents. Bacterial species considered to be potentially pathogenic were isolated from conjunctival sac specimens in only 1 of 38 attempts. Cytologic changes considered compatible with chlamydial or FHV-1 infection (intracytoplasmic inclusions or multinucleated epithelial cells, respectively) were found in 8 and 5 cases, respectively.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8394443", "author": "Reinhart TA", "n_authors": 4, "title": "Distinct superinfection interference properties yet similar receptor utilization by cytopathic and noncytopathic feline leukemia viruses.", "abstract": "Cell killing by cytopathic retroviruses is often associated with a delay or failure in the establishment of superinfection interference. Superinfection has been observed during T-cell killing and fatal immunodeficiency disease induction by the feline leukemia virus (FeLV) chimera FeLV-FAIDS-EECC, containing the surface envelope glycoprotein (SU) of FeLV-FAIDS clone 61C. We demonstrate here that 61C SU has a defect that results in a nearly complete failure to establish superinfection interference against homologous virus challenge. This failure was evident only in feline T (FeT) cell clones expressing envelope protein, not in the rare cells that have survived cytopathic infection to become chronically infected. The regions of SU responsible for this defect were the same as those previously identified as responsible for T-cell killing. The superinfection interference properties of a noncytophatic molecular clone, FeLV-FAIDS-61E, were different in that 61E established interference to homologous virus challenge, both in SU-expressing cell clones and in chronically infected cells. Neither 61E nor EECC established interference against heterologous virus challenge. Viruses expressing chimeric SU proteins displayed varied and intermediate interference properties. Purified 61E and 61C SU competed for binding sites on FeT cell surfaces, and purified 61E SU blocked infection of virus bearing 61E or 61C SU. In addition, purified 61E and 61C SU each coprecipitated 70-kDa FeT cell surface proteins. Our data are consistent with the hypothesis that there are multiple cellular components necessary for 61E and 61C attachment to and penetration of FeT cells, a primary receptor that is utilized by both 61E and 61C, and secondary receptors that are likely to be virus specific.", "journal": "Journal of virology", "doi": "10.1128/JVI.67.9.5153-5162.1993", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8263843", "author": "Jordan HL", "n_authors": 3, "title": "Thrombocytopenia in cats: a retrospective study of 41 cases.", "abstract": "The prevalence of feline thrombocytopenia (< 200,000 platelets/microL) at North Carolina State University, College of Veterinary Medicine Teaching Hospital, from January 1985 to March 1990, was 1.2% (41/3300). Cats were divided into six categories based on clinical diagnoses: 29% (12/41) had infectious disease, 20% (8/41) had neoplasia, 7% (3/41) had cardiac disease, 2% (1/41) had primary immune-mediated disease, 22% (9/41) had multiple diseases, and 20% (8/41) had disorders of unknown etiology. The mean platelet count for all thrombocytopenic cats was 52,000/microL +/- 46,000/microL (1 SD) with a range of 1000-190,000/microL. No significant differences were found between groups with respect to platelet count, packed cell volume, or white blood cell count, though anemia and leukopenia were common among the cats as a whole. Bleeding disorders (hemorrhage or thrombosis) were observed in 29% (12/41) of thrombocytopenic cats and were more likely to be associated with neoplasia, cardiac disease, and platelet counts less than or equal to 30,000/microL. Disseminated intravascular coagulopathy was diagnosed in 12% (5/41) of the cats. Infections and/or neoplasia affecting the bone marrow were the most common diseases associated with thrombocytopenia. Feline leukemia virus and myeloproliferative neoplasia accounted for approximately 44% (18/41) of the specific diagnoses in thrombocytopenic cats.", "journal": "Journal of veterinary internal medicine", "doi": "10.1111/j.1939-1676.1993.tb01017.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8256439", "author": "Otto CM", "n_authors": 4, "title": "Delayed hypersensitivity testing as a clinical measure of cell-mediated immunity in the cat.", "abstract": "The purposes of this study were to examine the cell-mediated immune response of the normal cat to the modified live feline viral rhinitis, calicivirus, and parvovirus (FVRCP) vaccine (Felocell CVR, Norden, Lincoln, NE), and to evaluate the intradermal skin test as a clinical measure of the immune response of cats. Vaccine and diluent were injected intradermally on the dorsal pinna of 34 normal adult cats. Skin thickness measurements, lymphocyte counts, and Concanavalin A mitogenesis indices were evaluated in 18 of these cats. Skin biopsies were obtained in 16 cats. In normal cats, the FVRCP vaccine induced a delayed hypersensitivity response characterized by a mononuclear infiltrate most pronounced at 72 h. Five cats with either feline leukemia (FeLV) or feline immunodeficiency virus (FIV) were tested and had a significantly reduced response to the skin test. The skin test provides a clinically useful method of evaluating immune function in cats and may be useful in development of a prognostic index.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(93)90115-k", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8352761", "author": "Cozzi PJ", "n_authors": 6, "title": "Sequence and functional characterization of feline interleukin 2.", "abstract": "Since the discovery of its involvement in the pathogenesis of feline immunodeficiency virus infection (\"cat AIDS\") and feline leukemia virus infection, the role of feline interleukin 2 (IL-2) has been a focus of particular interest. The purpose of this study was to clone feline IL-2 cDNA, as well as synthesize bioactive recombinant feline IL-2. The isolation of cDNA encoding feline IL-2 was carried out using a PCR-based strategy and screening of a feline leukocyte cDNA library. Feline IL-2 consists of 154 amino acids including a putative signal sequence and has 81%, 69%, 60% and 64% identity to human, bovine, murine and rat IL-2, respectively. Feline IL-2 cDNA was expressed in COS-7 cells. The secreted protein has CTLL-4 murine cytotoxic T cell proliferative activity characteristic of authentic IL-2. These data confirm the synthesis of bioactive recombinant feline IL-2.", "journal": "Biochemical and biophysical research communications", "doi": "10.1006/bbrc.1993.1926", "deposited_data": "Sim", "nuccore_ids": "112807218, 304313, 112807218", "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8393248", "author": "Papenhausen MD", "n_authors": 2, "title": "Nucleotide sequence of the splice junction of feline leukemia virus envelope mRNA.", "abstract": "The splice donor and acceptor sequences for the subgenomic envelope messenger RNA of feline leukemia virus (FeLV) were determined. The splice junction was characterized for viral mRNA from a prototype subgroup A FelV and an immunodeficiency-inducing FeLV variant. Thirty-seven of 38 partial envelope cDNAs, cloned after PCR amplification from T cells infected with either virus, utilized the same splice donor and acceptor sites to generate a mRNA that would be predicted to encode envelope protein. One novel cDNA, which could also code for envelope protein, was generated from a cryptic splice acceptor 109 nucleotides downstream of the normal junction. No additional subgenomic FeLV gene products were detected using reverse transcription and polymerase chain reaction amplification of FeLV sequences from chronically infected cells.", "journal": "Virology", "doi": "10.1006/viro.1993.1434", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8257557", "author": "Kass PH", "n_authors": 5, "title": "Epidemiologic evidence for a causal relation between vaccination and fibrosarcoma tumorigenesis in cats.", "abstract": "Within the past 2 years, a putative causal relationship has been reported between vaccination against rabies and the development of fibrosarcomas at injection sites in cats. A retrospective study was undertaken, involving 345 cats with fibrosarcomas diagnosed between January 1991 and May 1992, to assess the causal hypothesis. Cats with fibrosarcomas developing at body locations where vaccines are typically administered (n = 185) were compared with controls (n = 160) having fibrosarcomas at locations not typically used for vaccination. In cats receiving FeLV vaccination within 2 years of tumorigenesis, the time between vaccination and tumor development was significantly (P = 0.005) shorter for tumors developing at sites where vaccines are typically administered than for tumors at other sites. Univariate analysis, adjusted for age, revealed associations between FeLV vaccination (odds ratio [OR] = 2.82; 95% confidence interval [CI] = 1.54 to 5.15), rabies vaccination at the cervical/interscapular region (OR = 2.09; 95% CI = 1.01 to 4.31), and rabies vaccination at the femoral region (OR = 1.83; 95% CI = 0.65 to 5.10) with fibrosarcoma development at the vaccination site within 1 year of vaccination. Multivariate analysis, adjusted for age and other vaccines, also revealed increased risks after FeLV (OR = 5.49; 95% CI = 1.98 to 15.24) and rabies (OR = 1.99; 95% CI = 0.72 to 5.54) vaccination.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8399067", "author": "Zeidner NS", "n_authors": 3, "title": "Reversal of feline leukemia virus infection by adoptive transfer of lectin/interleukin-2-activated lymphocytes, interferon-alpha, and zidovudine.", "abstract": "Previous experimental studies utilizing human recombinant interferon-alpha-2b (IFN alpha-2b) alone or with zidovudine (AZT) to treat established feline leukemia virus (FeLV) infection resulted in a significant reduction in circulating virus throughout a 49-day treatment period. However, the anti-FeLV effect of IFN alpha was limited by the production of IFN alpha-neutralizing antibodies detected 7 weeks after the start of treatment. AZT without IFN alpha had no effect on circulating virus load. To examine the hypothesis that combination chemoimmunotherapy might induce the clearance of FeLV infection, persistently infected cats were infused with activated lymphocytes, IFN alpha, and AZT 12 weeks after infection with FeLV. Recipient cats received weekly infusions of 1.46 x 10(8) lymphocytes activated in vitro with lectin/IL-2 comprised of 98% T cells and an even distribution of CD4+ and CD8+ lymphocytes. FeLV infection was cleared in 4 of 9 cats receiving combined therapy after four adoptive cell transfers. These cats remained negative for circulating virus during a 63-day treatment period (17 adoptive cell transfers) despite the production of anti-IFN alpha-neutralizing antibodies. Sequential development of virus-neutralizing and virus envelope antibody titers were detected in those cats which cleared retroviremia, an antiviral response that was absent in untreated control animals or nonresponders. Three of four responder cats remained negative for FeLV 95 days after treatment was discontinued. Treatment of cats with lymphocytes without chemotherapy failed to influence the course of FeLV infection. These results suggest that combined treatment using IFN alpha and adoptive lymphocyte transfer served to reconstitute antiviral humoral immunity, counteract immunosuppression, and induce the reversal of retroviremia.", "journal": "Journal of immunotherapy with emphasis on tumor immunology : official journal of the Society for Biological Therapy", "doi": "10.1097/00002371-199307000-00004", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8390036", "author": "Levy LS", "n_authors": 3, "title": "flvi-2, a target of retroviral insertional mutagenesis in feline thymic lymphosarcomas, encodes bmi-1.", "abstract": "LC-FeLV is a myc-containing strain of feline leukemia virus which induces thymic lymphosarcoma in the domestic cat with short latency. A locus in feline DNA, termed flvi-2, is commonly interrupted in naturally occurring and experimentally induced thymic lymphosarcomas containing LC-FeLV; thus, interruption of a gene encoded by flvi-2 may cooperate with the myc oncogene in the induction of T-cell tumors by LC-FeLV. Clones homologous to flvi-2 have been isolated from a normal human thymus cDNA library. Nucleotide sequence analysis of the cDNA clones demonstrates that flvi-2 encodes bmi-1, a gene previously identified as a target for MoMuLV integration and as a myc-collaborator in retrovirally-induced B-cell lymphomas in E mu-myc transgenic mice. In feline thymic lymphomas, retroviral integrations occur downstream of the gene, and result in enhanced expression of a bmi-1 transcript of normal size. These findings demonstrate the interruption of bmi-1 in natural as well as experimentally induced tumors, implicate the activation of bmi-1 in the induction of T-cell as well as B-cell lymphoma, and support the premise that bmi-1 functions as a myc collaborator.", "journal": "Oncogene", "doi": null, "deposited_data": "Sim", "nuccore_ids": "68163488, 1682961, 2695401866, 2695401864, 2695401862, 2695401860, 2130994063, 2130994062, 2130994061, 2130994060, 2130994059, 1519242454, 68163488", "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8389921", "author": "Kristal BS", "n_authors": 4, "title": "Interference with superinfection and with cell killing and determination of host range and growth kinetics mediated by feline leukemia virus surface glycoproteins.", "abstract": "The functions of the surface glycoproteins (SU) of feline leukemia viruses (FeLVs) are of interest since these proteins mediate virus infection and interference and are critical determinants of disease specificity. In this study, we examined the biochemical and genetic determinants of SU important to virus entry and cell killing. In particular, we developed and used vesicular stomatitis virus (VSV)/FeLV pseudotype virus interference assays to determine interference subgroupings and assess mechanisms of host cell restriction. We also assessed roles of SU in virus growth kinetics and in the inhibition of cell killing caused by superinfection with cytopathic virus. Subgroup classification by VSV/FeLV pseudotype assay was in agreement with that defined previously by focus interference assay and was found to be determined by changes near the N terminus of SU for FeLV subgroups A (FeLV-A) and C. Virus host range restriction was found to be mediated at the level of virus entry in most cases, although postentry events mediated restriction in the failure of a subgroup A-like, T-cell cytopathic and immunodeficiency-inducing clone (FeLV-FAIDS-EECC) to replicate in feline fibroblasts. FeLV-FAIDS-EECC-induced cell killing was also inhibited by prior infection with one of two FeLV-A isolates. This inhibition could be conveyed by as few as four amino acid changes near the N terminus of the FeLV-A SU and also appeared to be mediated at a postentry level. Lastly, the SU-coding sequence was also found to determine differences in growth kinetics of viruses within the same subgroup. These studies demonstrate that subtle alterations in the FeLV SU, particularly in the N-terminal region, impart multiple significant functional differences which distinguish virus variants.", "journal": "Journal of virology", "doi": "10.1128/JVI.67.7.4142-4153.1993", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8388492", "author": "Sheets RL", "n_authors": 4, "title": "Recombinant feline leukemia virus genes detected in naturally occurring feline lymphosarcomas.", "abstract": "Using a polymerase chain reaction strategy aimed at detecting recombinant feline leukemia virus (FeLV) genomes with 5' env sequences originating from an endogenous source and 3' env sequences resulting from FeLV subgroup A (FeLV-A), we detected recombinant proviruses in approximately three-fourths of naturally occurring thymic and alimentary feline lymphosarcomas (LSAs) and one-third of the multicentric LSAs from cats determined to be FeLV capsid antigen positive by immunofluorescence assay. In contrast, only 1 of 22 naturally arising FeLV-negative feline LSAs contained recombinant proviruses, and no recombinant env gene was detected in seven samples from normal tissues or tissues from FeLV-positive animals that died from other diseases. Four preferred structural motifs were identified in the recombinants; one is FeLV-B like (recognizing that FeLV-B itself is a product of recombination between FeLV-A and endogenous env genes), and three contain variable amounts of endogenous-like env gene before crossing over to FeLV-A-related sequences: (i) a combination of full-length and deleted env genes with recombination at sites in the middle of the surface glycoprotein (SU), (ii) the entire SU encoded by endogenous-like sequences, and (iii) the entire SU and approximately half of the transmembrane protein encoded by endogenous-like sequences. Additionally, three of the thymic tumors contained recombinant proviruses with mutations in the vicinity of the major neutralizing determinant for the SU protein. These molecular genetic analyses of the LSA DNAs correspond to our previous results in vitro and support the occurrence and association of viral recombinants and mutants in vivo in FeLV-induced leukemogenesis.", "journal": "Journal of virology", "doi": "10.1128/JVI.67.6.3118-3125.1993", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8320159", "author": "Fossum TW", "n_authors": 4, "title": "Eosinophilic pleural or peritoneal effusions in dogs and cats: 14 cases (1986-1992).", "abstract": "Case records of 9 dogs and 5 cats with eosinophilic effusions were reviewed. The animals ranged from 11 months to 13 years old. Seven animals had pleural effusions, 5 had peritoneal effusions, and 2 had pleural and peritoneal effusions. Neoplasia was confirmed in 6 animals and suspected in 1. Eosinophilic pleural effusion was diagnosed 2 days after pneumothorax developed as a consequence of thoracic tube placement in a cat, and pneumothorax was diagnosed in another cat with eosinophilic peritoneal effusion. Other abnormalities seen in 1 or 2 animals associated with eosinophilic effusion were radiographic signs of interstitial or peribronchial pulmonary infiltrates, a history of allergic respiratory tract and skin disease, intestinal lymphangiectasia and lung lobe torsion, chylothorax, bite wounds causing intestinal perforation, and feline leukemia virus infection. Based only on the protein concentration of the effusion, 7 effusions were classified as transudates and 7 were classified as exudates. Five of the 14 animals had eosinophilia (> 1,200 eosinophils/microliters); 3 of these animals had neoplastic disease. Mean eosinophil count in blood samples was not significantly different between animals with neoplasia and those without. Eosinophil counts in blood samples were not linearly related to counts in effusions; however, in some animals the number of eosinophils in the effusion was much higher than the eosinophil count in blood, suggesting concentration of eosinophils in the effusion.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8387834", "author": "Khan KN", "n_authors": 3, "title": "Macrophage tropism of feline leukemia virus (FeLV) of subgroup-C and increased production of tumor necrosis factor-alpha by FeLV-infected macrophages.", "abstract": "Erythroid aplasia is induced in cats by feline leukemia virus (FeLV) of subgroup C but not by FeLV of subgroup A. In an investigation of the role of macrophages in FeLV-C-induced diseases, the concentrations of FeLV and tumor necrosis factor-alpha (TNF-alpha) were compared between feline peritoneal macrophages incubated with FeLV of subgroup A or C. FeLV of both subgroups infected macrophages, but expression of FeLV-C was 21-fold higher than FeLV-A in peritoneal macrophages (P = .004). The supernatants of FeLV-C-inoculated macrophage cultures contained significantly higher levels of TNF-alpha (70 +/- 14 U/mL) at 72 hours postincubation compared with FeLV-A-inoculated (38 +/- 8 U/mL) and uninoculated (31 +/- 8 U/mL) cultures. Moreover, a positive correlation was shown between cell-associated FeLV surface glycoprotein gp70 and TNF-alpha expression in FeLV-C-infected macrophages by immunofluorescence (r = .6; P = .001), measured with a computer-assisted, laser-based digital imaging system. The addition of TNF-alpha to a uniform population of FeLV-infected cells (feline embryonic fibroblasts) caused an enhancement of viral expression (P < .05). These results indicate that FeLV-C has tropism for macrophages, FeLV expression is positively correlated with TNF-alpha expression in macrophages, and TNF-alpha enhances FeLV replication in fibroblasts. We suggest that FeLV-C infection of macrophages and secretion of TNF-alpha may be important in hematopoietic suppression in FeLV-C-infected cats.", "journal": "Blood", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8391229", "author": "Zenger E", "n_authors": 8, "title": "Evaluation of cofactor effect of feline syncytium-forming virus on feline immunodeficiency virus infection.", "abstract": "Although feline immunodeficiency virus (FIV) and the unrelated retrovirus feline leukemia virus (FeLV) are associated with acquired immune deficiency in cats, experimental and field evidence indicates that coinfection with both viruses may lead to more serious disease syndrome. A third feline retrovirus, feline syncytium-forming virus (FeSFV), which is far more prevalent than either FIV or FeLV and is considered nonpathogenic in nature, is consistently coisolated from sick, FIV-infected cats. To determine the potential role of FeSFV in enhancement of FIV-mediated disease, persistent FeSFV infection was established in 14 of 24 nine-month-old cats. Four months later, half the FeSFV-infected and half the noninfected cats were inoculated with blood obtained from a cat persistently infected with the Petaluma strain of FIV. At postinoculation week 17, 1 male cat infected with only FIV died of bacterial bronchopneumonia that could have been attributed to FIV-induced acquired immune deficiency-like syndrome. However, none of the remaining cats had clinical illness, whether infected with either virus alone or coinfected with both viruses. As early as postinoculation week 6, decreases were observed in the CD4+ to CD8+ T-lymphocyte ratio of both groups of cats inoculated with FIV. Infection with FeSFV had no effect on the CD4+ to CD8+ T-cell ratio. Mitogen stimulation assays and total WBC count were unaffected by FeSFV infection, although an increase in numbers of neutrophils from FeSFV-infected cats was consistent, especially when compared with the decrease observed after FIV infection.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8383248", "author": "Tartaglia J", "n_authors": 5, "title": "Protection of cats against feline leukemia virus by vaccination with a canarypox virus recombinant, ALVAC-FL.", "abstract": "Two ALVAC (canarypox virus)-based recombinant viruses expressing the feline leukemia virus (FeLV) subgroup A env and gag genes were assessed for their protective efficacy in cats. Both recombinant viruses contained the entire gag gene. ALVAC-FL also expressed the entire envelope glycoprotein, while ALVAC-FL(dl IS) expressed an env-specific gene product deleted of the putative immunosuppressive region. Although only 50% of the cats vaccinated with ALVAC-FL(dl IS) were protected against persistent viremia after oronasal exposure to a homologous FeLV isolate, all cats administered ALVAC-FL resisted the challenge exposure. Significantly, protection was afforded in the absence of detectable FeLV-neutralizing antibodies. These results represent the first effective vaccination of cats against FeLV with a poxvirus-based recombinant vector and have implications that are relevant not only to FeLV vaccine development but also to developing vaccines against other retroviruses, including human immunodeficiency virus.", "journal": "Journal of virology", "doi": "10.1128/JVI.67.4.2370-2375.1993", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8470340", "author": "McEntee MF", "n_authors": 4, "title": "Granulated round cell tumor of cats.", "abstract": "Morphologic and biologic features of five feline granulated round cell tumours were compared with those previously reported to be of globule leukocyte and large granular lymphocyte origin. The five cats ranged from 6 to 9 years of age and presented with nonspecific gastrointestinal signs. Four of the five cats were tested for feline leukemia virus and were negative by enzyme-linked immunosorbent assay. The neoplastic process involved the abdominal cavity in all cases, with a predilection for the distal small intestine and mesentery. The liver and peripheral and thoracic lymphoid tissues were also sporadically affected. Neoplastic round cells contained 0.5-1.5-microns eosinophilic cytoplasmic granules that were difficult to discern on causal observation with hematoxylin and eosin stain but were deep blue and easily visualized when stained with phosphotungstic acid-hematoxylin. In two cases, epithelium in the affected ileum and liver contained unusually large numbers of apparently normal globule leukocytes. Ultrastructurally, the tumor granules tended to cluster at one nuclear pole and were spindle to round in shape with variably dense contents. Some granules contained a dense \"cap\" at one end or internal crystalloid bars that distorted the granule membrane. The tumors reported herein are similar to all three of the previously reported feline granulated round cell tumors and probably have a common cellular origin.", "journal": "Veterinary pathology", "doi": "10.1177/030098589303000213", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8382406", "author": "Morgan RA", "n_authors": 4, "title": "In vitro infection of human bone marrow by feline leukemia viruses.", "abstract": "Four subgroup feline leukemia viruses (FeLV) were tested for their ability to infect primary cultures of human bone marrow in vitro. Using three sequential exposures to both concentrated and unconcentrated virus, FeLV infection of human bone marrow was documented by indirect immunofluorescence, ELISA, and polymerase chain reaction (PCR) assays. Based on comparison to known standards, it was estimated that between 5 and 10% of the bulk human marrow culture could be infected by FeLV. Further evidence for FeLV reverse transcription, integration, and expression was obtained using specific PCR assays.", "journal": "Virology", "doi": "10.1006/viro.1993.1141", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8148094", "author": "Wiggs RB", "n_authors": 4, "title": "Effects of preactivated MC540 in the treatment of lymphocytic plasmacytic stomatitis in feline leukemia virus and feline immunodeficiency virus positive cats.", "abstract": "Photoactive compounds and drugs are used therapeutically as antibacterial, antiviral and antitumor agents. This report examines the use of a photoactive compound, preactivated merocyanine 540 (pMC540), in the treatment of stomatitis in two cats that are both feline immunodeficiency virus (FIV) positive. One of the cats was also feline leukemia virus (FeLV) positive. Dramatic short term improvement is reported with the dosage regimen and complications.", "journal": "Journal of veterinary dentistry", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8384389", "author": null, "n_authors": 0, "title": "Advances in the understanding of feline leukaemia virus.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.132.7.147", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8380929", "author": "Williams LL", "n_authors": 6, "title": "Chronic feline leukemia virus infection alters arachidonic acid proportions in vivo and in vitro.", "abstract": "The polyunsaturated omega-6 fatty acid, arachidonic acid ([AA] 20:4n-6), is both the key of the immunoregulatory substances, prostaglandins, and leukotrienes, and an essential component of immune cell membrane phospholipids, providing stability and flexibility to ensure cellular function. To explore possible effects of the physiological burden of viral replication in chronic viral infections on AA availability, plasma total esterified fatty acid (FA) proportions were measured in the feline leukemia (FeLV) model. Plasma FA profiles of 12 specific-pathogen-free cats with chronic infections with Rickard strain feline leukemia virus (FeLV-R) were compared with 12 age- and sex-matched uninfected specific-pathogen-free cats at 4 months after infection. A significant decrease from normal of average AA proportion was found in FeLV-R-infected cat plasma, while other major FA (palmitic, stearic, and oleic and omega-3 FA normally remained present until near death. Since plasma FA content rapidly affects circulating immune cell membrane composition and since FeLV infection also targets immune cells, we compared FA profiles of feline T4-thymic lymphoma 3201 cell membranes that were infected with virulent FeLV-R or less virulent FeLV-A, at 20 days after viral inoculation with sham-inoculated uninfected 3201 cells. Significantly altered FA proportions and ratios of saturated to unsaturated FA found in infected cell membranes were similar to plasma FA changes and paralleled the virulence of the FeLV inoculum. Altered postinfection FA proportions may impart serious functional defects to the immune cells of chronic FeLV-infected cats, contributing to the inability of their immune systems to eliminate FeLV by depleted plasma AA stores and modified cell membrane composition. Decreased AA availability may be an important factor in the cachexia and fatal outcome of FeLV infection.", "journal": "Proceedings of the Society for Experimental Biology and Medicine. Society for Experimental Biology and Medicine (New York, N.Y.)", "doi": "10.3181/00379727-202-43533", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8445789", "author": "Roelke ME", "n_authors": 8, "title": "Seroprevalence of infectious disease agents in free-ranging Florida panthers (Felis concolor coryi).", "abstract": "Serum samples obtained from 38 free-ranging Florida panthers (Felis concolor coryi) in southern Florida, March 1978 through February 1991, were tested for antibodies against eight bacterial, parasitic, and viral disease agents. Sera were positive for antibodies against feline panleukopenia virus (FPV) (78%), feline calicivirus (56%), feline immunodeficiency virus/puma lentivirus (37%), feline enteric coronavirus/feline infectious peritonitis virus (19%), and Toxoplasma gondii (9%). All samples were seronegative for Brucella spp., feline rhinotracheitis virus, and pseudorabies virus. In addition, all the animals tested were negative for feline leukemia virus p27 antigen as determined by enzyme-linked immunosorbent assay. Feline panleukopenia virus was considered to be a potentially significant disease agent; FPV antibodies occurred in the highest prevalences in older age classes (P = 0.027) and in panthers living in the dense mixed hardwood swamps in the western portion of their range compared to the open cypress and sawgrass prairies to the east (P = 0.096). Because < 50 animals remain in this relict population and the probable resultant depression of genetic diversity and lowered disease resistance, FPV or other disease agents could contribute to the extinction of this endangered subspecies.", "journal": "Journal of wildlife diseases", "doi": "10.7589/0090-3558-29.1.36", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8421890", "author": "Carney HC", "n_authors": 2, "title": "Feline hemobartonellosis.", "abstract": "H. felis is a rickettsial parasite that causes hemolysis and sequestration of feline erythrocytes. It should be considered as a potential primary pathogen or opportunist in any cat presented with signs ranging from episodic malaise to acute anemic collapse. Diagnosis requires visualization of the organism in properly prepared blood smears. Treatment uses antirickettsial drugs, corticosteroids, and supportive measures. Clinical recovery requires immune containment of the organism. Treatment does not eliminate the organism from the host. Carrier cats may relapse when their immunity is severely compromised by other diseases such as FeLV. Transmission is presumed to be by blood-sucking parasites and possibly bite wounds between cats. Prevention requires prudent health management of cats. Future advances in the knowledge of the disease will relate mainly to the development of a diagnostic technique that will allow identification of all infected cats.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": "10.1016/s0195-5616(93)50005-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8384261", "author": "Pedersen NC", "n_authors": 1, "title": "Immunogenicity and efficacy of a commercial feline leukemia virus vaccine.", "abstract": "Twenty young adult specific pathogen-free cats were randomly divided into two groups of 10 animals each. One group was vaccinated with two doses of feline leukemia virus vaccine according to the manufacturer's recommendations. All 20 cats were challenge exposed oronasally (4 times over a 1-week period), beginning 3 weeks after immunization, with a virulent subgroup A strain of FeLV (CT600-FeLV). The severity of the FeLV infection was enhanced by treating the cats with methylprednisolone acetate at the time of the last FeLV exposure. Ten of 10 nonvaccinated cats became persistently viremic compared with 0/10 of the vaccinates. ELISA antibodies to whole FeLV were present at high concentrations after immunization in all of the vaccinated cats, and there was no observable anamnestic antibody response after challenge exposure. ELISA antibodies to whole FeLV appeared at low concentrations in the serum of nonvaccinated cats after infection but disappeared as the viremia became permanently established. Virus neutralizing antibodies were detected in 3/10 vaccinates and 0/10 nonvaccinates immediately before FeLV challenge exposure, and in 8/10 vaccinates and 1/10 nonvaccinates 5 weeks later. Although vaccination did not consistently evoke virus neutralizing antibodies, it appeared to immunologically prime cats for a virus-neutralizing antibody response after infection. Active FeLV infection was detected in bone marrow cells taken 14 weeks after infection from 10/10 nonvaccinates and 0/10 vaccinates. Latent FeLV infection was not detected in bone marrow cells from any of the vaccinated cats 14 weeks after challenge exposure.", "journal": "Journal of veterinary internal medicine", "doi": "10.1111/j.1939-1676.1993.tb03166.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8380657", "author": "Loar AS", "n_authors": 1, "title": "Feline leukemia virus. Immunization and prevention.", "abstract": "Our understanding of the pathogenesis of FeLV infection is little changed from what was described by Hardy and his colleagues in the mid-1970s. The prevention of FeLV infection consists, first, of avoiding the agent and, second, of providing optimum immunologic resistance. In multi-cat environments, the former is achieved through test-and-removal methods perennially reviewed in the literature and by minimizing exposure to outdoor cats. The latter is possible by attempting to maintain a low-stress, pathogen-free household and by the use of appropriate, effective immunization programs. Simple immunologic concepts used for the development of vaccines against feline distemper and rabies have evolved to enable generation of products that can now protect against retroviruses. The use of more complex biologic methods, such as recombinant technology and the manipulation of antigen presentation, bears encouragement, so that perhaps one day the most destructive of feline infectious diseases may be checked.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": "10.1016/s0195-5616(93)50012-8", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "7692683", "author": "Weijer K", "n_authors": 7, "title": "Induction of feline leukaemia virus-neutralizing antibodies by immunization with synthetic peptides derived from the FeLV env gene.", "abstract": "The surface glycoprotein, gp70, of feline leukaemia virus (FeLV) contains sites which are important in inducing neutralizing antibodies. Using synthetic peptides corresponding to nucleotide sequence 729-957 (amino acid sequence 243-319) of FeLV-A/Glasgow-1, the antigenicity and immunogenicity of this part of the viral surface glycoprotein were investigated. The region contains two highly conserved domains separated by a variable region (VR4), when compared with FeLV of subgroups B and C, and an epitope known to be involved in virus neutralization is located in the N-terminal conserved domain. Five murine monoclonal antibodies generated by immunization with virus were found to be directed to this domain and four were virus-neutralizing. Polyclonal mouse, rabbit and cat anti-FeLV antisera, which were virus-neutralizing, were directed to B-cell epitopes in the peptides. To determine if those synthetic peptides could induce neutralizing antibodies, rabbits were immunized with the peptides, singly or in combination. Antibody responses were measured by ELISA for anti-peptide, anti-FeLV and anti-gp70 activity, by immunoblotting, by membrane immunofluorescence and by virus-neutralization tests. Virus-neutralizing antibodies were induced by FeLV gp70 peptides and there was a synergistic effect on antibody production when a combination of peptides covering amino acid sequence 243-319 of FeLV-A was used. In a second experiment, six rabbits and six cats were immunized with a combination of two peptides, which covered the above-defined FeLV gp70 sequence. Comparisons were made of the responses to these peptides incorporated into immunostimulating complexes (ISCOMs) via myristic acid tails, inoculated with 'empty' ISCOMs, or with Al(OH)3. Complete Freund's adjuvant (CFA) had a very strong potentiating effect on the induction of antibodies and immunization with peptides incorporated into ISCOMs was superior to immunization using adjuvants other than CFA. It is very promising that not only in rabbits, but also in the natural host of FeLV, the cat, anti-FeLV gp70 (peptides) antibodies could be induced by FeLV gp70 peptides.", "journal": "Vaccine", "doi": "10.1016/0264-410x(93)90384-a", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "7992306", "author": "Misdorp W", "n_authors": 1, "title": "[Oncology, pathology and companion animal practice].", "abstract": "A review of research in veterinary oncology, as executed in Amsterdam and Utrecht, is presented. Also an inquiry into the cooperation between oncologist, pathologist and practitioner is discussed. It is concluded that microscopic tumour diagnosis is practized at too low a scale (+/- 30%). Veterinary oncology has significance both from the veterinary and the comparative (model) point of view. Etiologic-pathogenetic and biologic-therapeutic aspects are studied in a multidisciplinary way. Intercellular communication, growth factors and intercellular matrix are items of present and future research. Molecular-genetic research is in progress. Prevention of mammary tumours by ovariectomy (dog, cat) and of malignant lymphoma (cat) by fighting FeLV seems promising.", "journal": "Tijdschrift voor diergeneeskunde", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "7975256", "author": "Sparger EE", "n_authors": 7, "title": "Infection of cats with molecularly cloned and biological isolates of the feline immunodeficiency virus.", "abstract": "Molecularly cloned viruses are considered essential reagents for characterizing viral domains responsible for infectivity and disease pathogenesis in the host. The infectivity and hematological alterations associated with two molecularly cloned isolates of feline immunodeficiency virus (FIV-pPPR and FIV-pF34) and an uncloned isolate (FIV-PPR) were assessed by inoculation of cats. Inoculated cats were tested for viral antibody, viremia, and clinical pathological disease. Peripheral blood mononuclear cells isolated from inoculated cats were assayed for virus infection by virus isolation, amplification of proviral DNA (by polymerase chain reaction), and in situ hybridization for viral RNA. Over 50% of the cats inoculated with cloned virus FIV-pF34 failed to seroconvert even when coinfected with feline leukemia virus; these cats were consistently virus positive only by amplification of proviral DNA. All cats inoculated with cloned virus FIV-pPPR seroconverted and were found virus positive by at least two of three virus detection assays. Both cloned viruses were less capable of suppressing CD4:CD8 ratios when compared to the biological isolates from which they were cloned. Isolates which replicate efficiently in feline peripheral blood mononuclear cells (PBMC), i.e., FIV-pPPR or biological FIV-PPR, caused greater virus load and lower CD4:CD8 ratios when compared to cloned FIV-pF34, which replicates efficiently in feline adherent cell lines and macrophages but poorly in primary feline PBMC. Molecular clones FIV-pF34 and FIV-pPPR will be useful reagents for characterization of viral determinants of virus load and possibly, cell tropism in vivo.", "journal": "Virology", "doi": "10.1006/viro.1994.1677", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "7966623", "author": "Tsatsanis C", "n_authors": 9, "title": "Genetic determinants of feline leukemia virus-induced lymphoid tumors: patterns of proviral insertion and gene rearrangement.", "abstract": "The genetic basis of feline leukemia virus (FeLV)-induced lymphoma was investigated in a series of 63 lymphoid tumors and tumor cell lines of presumptive T-cell origin. These were examined for virus-induced rearrangements of the c-myc, flvi-2 (bmi-1), fit-1, and pim-1 loci, for T-cell receptor (TCR) gene rearrangements, and for the presence of env recombinant FeLV (FeLV-B). The myc locus was most frequently affected in naturally occurring lymphomas (32%; n = 38) either by transduction (21%) or by proviral insertion (11%). Proviral insertions were also common at flvi-2 (24%). The two other loci were occupied in a smaller number of the naturally occurring tumors (fit-1, 8%; pim-1, 5%). Examination of the entire set of tumors showed that significant numbers were affected at two (19%) or three (5%) of the loci. Occupation of the fit-1 locus was observed most frequently in tumors induced by FeLV-myc strains, while flvi-2 insertions occurred with similar frequency in the presence or absence of obvious c-myc activation. These results suggest a hierarchy of mutational events in the genesis of feline T-cell lymphomas by FeLV and implicate insertion at fit-1 as a late progression step. The strongest links observed were with T-cell development, as monitored by rearrangement status of the TCR beta-chain gene, which was positively associated with activation of myc (P < 0.001), and with proviral insertion at flvi-2 (P = 0.02). This analysis also revealed a genetically distinct subset of thymic lymphomas with unrearranged TCR beta-chain genes in which the known target loci were involved very infrequently. The presence of env recombinant FeLV (FeLV-B) showed a negative correlation with proviral insertion at fit-1, possibly due to the rapid onset of these tumors. These results shed further light on the multistep process of FeLV leukemogenesis and the relationships between lymphoid cell maturation and susceptibility to FeLV transformation.", "journal": "Journal of virology", "doi": "10.1128/JVI.68.12.8296-8303.1994", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "7966574", "author": "Lie YS", "n_authors": 7, "title": "Chinese hamster ovary cells contain transcriptionally active full-length type C proviruses.", "abstract": "We have isolated a genomic locus from Chinese hamster ovary (CHO) cells that contains a full-length provirus. Nucleotide sequence analysis indicates that it is a defective member of the rodent type C retrovirus family with an env region that is similar to those of mouse amphotropic retrovirus and subgroup B feline leukemia virus. We were able to demonstrate that this provirus is a member of a closely related family of full-length proviruses in CHO cells and Chinese hamster liver. Hybridization probes generated from this genomic clone were used to characterize type C retrovirus RNA expression in CHO cells. Full-length genomic RNA and subgenomic envelope mRNA were detected in CHO cell lines but not in the human-derived 293 cell line. Interestingly, we discovered that the site of retrovirus integration lies within a G repeat sequence belonging to the short interspersed element family of retroposons.", "journal": "Journal of virology", "doi": "10.1128/JVI.68.12.7840-7849.1994", "deposited_data": "Sim", "nuccore_ids": "495488", "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "7721332", "author": "Kopelovich L", "n_authors": 1, "title": "Conversion of human fibroblasts to tissue macrophages by the Snyder-Theilen feline sarcoma virus (ST:FeSV(FeLV)): productive infection by Leishmania major.", "abstract": "The decisive role of macrophages in T-cell differentiation is best exemplified by cutaneous leishmaniasis. During infection, Leishmania attach to macrophages, the only site of replication for the parasite. We have recently demonstrated the conversion of human fibroblasts to tissue macrophages (TM) by transduction with the Snyder-Theilen feline sarcoma virus (ST:FeSV-(FeLV)). Since Leishmania have tropism only for macrophages, we have used the parasite to ascertain the functional phenotype of the ST:FeSV-induced TM. Here, we have demonstrated the productive infection of the ST:FeSV-induced TM by L. major. These results point to the utility of ST:FeSV-induced TM in studies that concern the role of human macrophages in T-cell differentiation during the course of infection by Leishmania.", "journal": "Immunology letters", "doi": "10.1016/0165-2478(94)90222-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "7698923", "author": "Hendrick MJ", "n_authors": 7, "title": "Comparison of fibrosarcomas that developed at vaccination sites and at nonvaccination sites in cats: 239 cases (1991-1992).", "abstract": "Questionnaires were sent to veterinarians who had submitted a fibrosarcoma from a cat to the surgical pathology services of the veterinary schools of the University of Pennsylvania and Tufts University between Jan 1, 1991 and June 30, 1992. Questionnaire items included signalment, FeLV and feline immunodeficiency virus status, site of sarcoma, vaccination site, vaccines used, treatment, biologic behavior of the tumor, and final outcome. Data were analyzed, using Student's t-test for continuous data, chi 2 test for categoric data, and log-rank test for survival estimates. Comparing results for cats with vaccination-site (VS) tumors and nonvaccination-site (NVS) tumors, we determined that VS tumors developed in younger cats and were larger than NVS tumors. Although VS sarcomas were biologically aggressive and redeveloped more often than NVS sarcomas, metastasis was not detected, and cats with VS tumors survived longer than cats with NVS tumors. Vaccination-site sarcomas developed in cats after injection of many types of vaccines, administered singularly or in combination. Of the cats in the VS group administered a single vaccine, 37% were given rabies, 33% were given feline viral rhinotracheitis/calicivirus/panleukopenia virus, and 30% were given FeLV vaccines. Cats with VS tumors were more likely to have received FeLV vaccine and less likely to have received rabies vaccine than those with NVS tumors. Although vaccines produced by certain manufacturers were used most often in cats with VS and NVS sarcomas, it was believed that this probably represented marketing practices and brand popularity.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "7941350", "author": "Boomer S", "n_authors": 4, "title": "Isolation of a novel subgroup B feline leukemia virus from a cat infected with FeLV-A.", "abstract": "Proviruses were cloned directly from a cat that developed neurological disorders approximately 28 months after inoculation with a molecularly cloned, minimally pathogenic subgroup A feline leukemia virus (FeLV-A). In addition to FeLV-A proviruses that were nearly identical to the inoculated virus, we detected a subgroup B-like variant in brain, bone marrow, and lymph node that apparently had acquired the major portion of its extracellular envelope gene (gp70) from endogenous FeLV-related sequences. A similar recombinant was also detected, by PCR, at low levels in bone marrow from an early time postinfection (2.5 months). A full-length proviral variant with this recombinant structure cloned from brain tissue encoded a replication-defective virus. A chimera encoding the 5' gag-pol portion of FeLV-A and the 3' env-LTR portion of the defective brain-derived clone was replication-competent and had the extended host range properties of FeLV-B.", "journal": "Virology", "doi": "10.1006/viro.1994.1597", "deposited_data": "Sim", "nuccore_ids": "413736, 413735, 413734", "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "7530594", "author": "McSharry JJ", "n_authors": 1, "title": "Uses of flow cytometry in virology.", "abstract": "This article reviews some of the published applications of flow cytometry for in vitro and in vivo detection and enumeration of virus-infected cells. Sample preparation, fixation, and permeabilization techniques for a number of virus-cell systems are evaluated. The use of flow cytometry for multiparameter analysis of virus-cell interactions for simian virus 40, herpes simplex viruses, human cytomegalovirus, and human immunodeficiency virus and its use for determining the effect of antiviral compounds on these virus-infected cells are reviewed. This is followed by a brief description of the use of flow cytometry for the analysis of several virus-infected cell systems, including blue tongue virus, hepatitis C virus, avian reticuloendotheliosis virus, African swine fever virus, woodchuck hepatitis virus, bovine viral diarrhea virus, feline leukemia virus, Epstein-Barr virus, Autographa californica nuclear polyhedrosis virus, and Friend murine leukemia virus. Finally, the use of flow cytometry for the rapid diagnosis of human cytomegalovirus and human immunodeficiency virus in peripheral blood cells of acutely infected patients and the use of this technology to monitor patients on antiviral therapy are reviewed. Future prospects for the rapid diagnosis of in vivo viral and bacterial infections by flow cytometry are discussed.", "journal": "Clinical microbiology reviews", "doi": "10.1128/CMR.7.4.576", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "7837113", "author": "Hart SW", "n_authors": 2, "title": "Hemostatic disorders in feline immunodeficiency virus-seropositive cats.", "abstract": "The hemostatic function of 40 feline immunodeficiency virus (FIV) seropositive and 8 FIV and feline leukemia virus (FeLV) seropositive cats was evaluated and compared with reference values from 30 clinically healthy cats. The FIV-positive cats were divided into 3 groups: group I included asymptomatic carriers; group II comprised sick FIV-infected cats with illnesses not likely to influence the hemostatic system; and group III included FIV-positive cats with diseases potentially associated with coagulopathies. Platelet counts in FIV/FeLV-infected cats were significantly lower than in healthy cats (P < .003), whereas the differences in the 3 groups of FIV-positive cats were variable (group I, P = .009; II, P = .05; III, P = .09). Thrombocytopenia (< 145,000 platelets/microL) was present in 4 FIV-positive and 3 FIV/FeLV-positive cats. Platelet aggregation induced by collagen (0.5 and 0.25 micrograms/mL), adenosine diphosphate (ADP) (1 and 0.6 mumol/L), and thrombin (0.4 and 0.25 IU/mL) was not significantly different from that of healthy cats. The plasma coagulation system was evaluated by measuring one-stage prothrombin time (OSPT), activated partial thromboplastin time (APTT), thrombin time, fibrinogen concentration, coagulation factor assays, fibrinogen and fibrin degradation products (FDP), and plasma exchange test. The OSPT was similar in FIV-seropositive cats and in the healthy control group. Cats with FIV infection, however, had markedly shorter clotting times than healthy cats when using a modified test system (P < .05).(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "Journal of veterinary internal medicine", "doi": "10.1111/j.1939-1676.1994.tb03250.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "7522182", "author": "deCastro CM", "n_authors": 8, "title": "The c-kit proto-oncogene receptor is expressed on a subset of human CD3-CD4-CD8- (triple-negative) thymocytes.", "abstract": "The c-kit receptor is a tyrosine-kinase transmembrane receptor first identified as an oncogene in the HZ4-feline leukemia virus and later found to be important in hematopoiesis in mice. The ligand for this receptor (Steel factor) can stimulate hematopoiesis both in vitro and in vivo. To study the pattern of c-kit receptor expression in normal human hematopoietic progenitor cells, we prepared a monoclonal antibody (9B9) against human c-kit receptor by using a synthetic peptide (amino acids 476-501) from the extracellular domain of c-kit receptor to immunize Balb/c mice. Monoclonal antibody 9B9 bound to recombinant c-kit protein, the erythroleukemic line HEL, the megakaryocytic line MEG-01, and the murine mast cell line P815. Monoclonal antibody 9B9 also bound to the surface of the CD7+CD3-CD4-CD8- T cell lymphoid cell lines DU.528 and HSB2T, and also to 1 to 4% of normal bone-marrow cells. The majority (67 +/- 6%) of CD34+ bone-marrow progenitor cells coexpressed c-kit receptor. Flow-cytometry analysis of immature CD3-CD4-CD8- (triple-negative) thymocytes indicated 30 +/- 9.5% expressed the c-kit receptor, and thymidine incorporation assay revealed that the receptor is functional. Indirect fluorescent microscopy of human thymic tissue, using a monoclonal antibody against Steel factor, revealed its presence on scattered mononuclear cells within the intralobular septae and the subcapsular cortex, which are regions where the triple-negative thymocytes are also localized. These data provide evidence that the c-kit receptor is present on human hematopoietic bone marrow and intrathymic T cell progenitor cells, and that it likely plays a role in early T cell lymphopoiesis.", "journal": "Experimental hematology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "16031766", "author": "Cull RM", "n_authors": 4, "title": "Humoral immunity in cats infected with feline immunodeficiency virus or leukaemia virus.", "abstract": "The humoral antibody responses of 82 domestic cats to the common commensal bacteria Pasteurella multocida and Staphylococcus aureus were measured by an indirect immunofluorescence assay to give a subjective quantification of specific IgG in serum. There was no significant difference in specific serum IgG levels between sick cats which tested antibody-positive to feline immunodeficiency virus or antigen-positive to feline leukaemia virus and sick, virus-negative cats. This finding suggested that there was no change in immune status, as measured by this method, in both feline leukemia and feline immunodeficiency virus infections, although, based on clinical signs shown by the virus-positive cats, overall immunosuppression was indicated. Feline immunodeficiency virus and feline leukemia virus infection may have an effect on cellular immunity, as is the case with human immunodeficiency virus.", "journal": "New Zealand veterinary journal", "doi": "10.1080/00480169.1994.35806", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8560843", "author": "Kovacević S", "n_authors": 2, "title": "[Distribution of p27 and gp70 feline leukemia virus antigens in various tissues].", "abstract": "Application of immunocytochemical methods (DP, IP, PAP, APAAP and IP-IP) has confirmed the existence of p27 and gp70 feline leukosis viral antigens (FeLV) in various tissues of 22 cats. Both viral antigens were found in bone marrow stem cells, but p27 antigens were mostly found in epithelial cells of intestinal crypts. In splenic T-lymphocytes and mediastinal lymph nodes the predominance of gp70 antigens in FeLV was confirmed, while the tropism of leukosis viruses in the lung was inclined to epithelial cells of bronchial glands where p27 antigens were dominant.", "journal": "Vojnosanitetski pregled", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8027111", "author": "Nemzek JA", "n_authors": 3, "title": "Retroviral transmission by the transplantation of connective-tissue allografts. An experimental study.", "abstract": "The transmission of a retrovirus by the transplantation of allografts of connective tissues was studied in a feline model with use of the feline leukemia virus, a retrovirus with a replication cycle and pathological characteristics similar to those of the human immunodeficiency virus. The retrovirus was used to infect four specific-pathogen-free cats that were subsequently used as tissue donors. Fresh allografts of menisci, patellar ligaments, and patellar ligament and bone composites were harvested from infected donors and were transplanted into the knee joints of twelve specific-pathogen-free cats. A fresh cancellous-bone allograft was transplanted into the proximal part of the tibia of four additional specific-pathogen-free cats, which served as positive control animals. Additional grafts from infected donors were harvested and were stored at -80 degrees Celsius for ten weeks. A fresh-frozen graft was then transplanted into the knee of twelve other specific-pathogen-free cats. Samples of plasma were obtained weekly from all twenty-eight cats and were tested with both an enzyme-linked immunosorbent assay to detect the presence of viral antigen and an immunofluorescent antibody assay to determine exposure to the virus. All types of fresh and fresh-frozen connective-tissue allografts from the infected donors resulted in transmission of the retrovirus to the recipient cats. The recipients had evidence of viral antigen or rising antibody titers as early as two weeks after the transplantation. Histological examination of specimens of the allografts revealed normal incorporation of the transplanted tissues, with no sign of rejection of the graft.", "journal": "The Journal of bone and joint surgery. American volume", "doi": "10.2106/00004623-199407000-00012", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8009844", "author": "Bechtel MK", "n_authors": 6, "title": "Abnormal processing of a recombinant feline leukemia virus envelope polyprotein and its interference with subgroup C virus infection.", "abstract": "Processing of the env polyprotein of a noninfectious feline leukemia virus (FeLV) recombinant, named r6gp, was examined in human-transfected cells. The r6gp provirus was previously generated in the frame of FeLV, subgroup B, GA clone with substitution of all but 40 C-terminal amino acid sequences of the surface glycoprotein (SU) from an endogenous FeLV provirus element (CFE-6). Although r6gp produced a normal size (85 kDa) env glycoprotein precursor, the product, unlike the precursor of the parental virus, was neither additionally glycosylated nor further processed into mature env proteins. Biochemical observations were consistent with the idea that the chimeric env polyprotein was trapped in the endoplasmic reticulum (ER) and were directly supported by immunofluorescence microscopy analyses. Interestingly, the residence of the chimeric protein in the ER specifically interfered with FeLV, subgroup C (Sarma) virus infection but not the parental FeLV-B virus infection. Since FeLV-C provirus sequences could be readily detected in the infected cells, it appeared that r6gp env expression did not block entry of the challenge virus. While FeLV-B and CFE-6 env genes share an extensive overall sequence homology, a variable region (region VI) of CFE-6 near the C-terminus of SU, which was retained in the r6gp construct, exhibits a considerably higher degree of homology to FeLV-C than FeLV-B. Thus, we propose that region VI is involved in conferring specificity for the env polyprotein oligomerization in the ER, and that co-oligomerization of the trapped r6gp env with FeLV-C is the reason for specific interference with FeLV-C infection. The results also demonstrate for the first time a functional abnormality of a recombinant FeLV env gene which is structurally similar to those commonly detected in FeLV-induced feline lymphosarcomas.", "journal": "Virology", "doi": "10.1006/viro.1994.1349", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "7946095", "author": "Beebe AM", "n_authors": 6, "title": "Evaluation of in vivo and in vitro interactions of feline immunodeficiency virus and feline leukemia virus.", "abstract": "To determine the potential mechanisms for disease potentiation where feline immunodeficiency virus (FIV) infection of persistently feline leukemia virus (FeLV)-infected cats results in more severe FIV disease and increased mortality than FIV infection of specific pathogen-free cats. To determine whether pseudotype formation resulting in expanded cell tropism may be an important mechanism, cellular targets and tissue distribution of FIV and FeLV were determined by in situ hybridization and/or immunohistochemistry. To determine whether FeLV can transactivate the FIV long terminal repeat (LTR) resulting in increased FIV expression, in vitro transient expression assays were performed. To examine whether persistent FeLV infection can cause the deletion of a suppressive T-lymphocyte population, peripheral blood mononuclear cell (PBMC) cultures from persistently FeLV-infected cats were infected with FIV and monitored for FIV antigen levels. Macrophages were the predominant target of FIV infection and were disseminated in a similar pattern in lymphoid and nonlymphoid tissues of both FIV-infected and FeLV/FIV-coinfected cats. FeLV-infected cells expressing FIV RNA were not present. Significant transactivation of the FIV LTR in FeLV-infected cells was not demonstrated. FIV antigen production was similar upon in vitro infection of PBMC from FeLV-infected and uninfected cats. Neither direct virus/virus interactions, such as FeLV/FIV pseudotype formation or transactivation of the FIV LTR in FeLV-infected cells, nor deletion of a regulatory cell subset from the blood of FeLV-infected cats, was found to be the mechanism of disease potentiation.", "journal": "AIDS (London, England)", "doi": "10.1097/00002030-199407000-00002", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "7928542", "author": "Legendre AM", "n_authors": 1, "title": "Evaluation of feline leukemia virus vaccines.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "7526781", "author": "Mukherji E", "n_authors": 3, "title": "Differential antiviral activities and intracellular metabolism of 3'-azido-3'-deoxythymidine and 2',3'-dideoxyinosine in human cells.", "abstract": "Dideoxynucleosides such as 3'-azido-3'-deoxythymidine (AZT) and 2',3'-dideoxyinosine (ddI) can effectively inhibit the replication of human immunodeficiency virus (HIV) in T lymphoid cells. There is evidence that HIV can infect and replicate in other cells including monocytoid cells and macrophages. The present study compared the antiretroviral activities of ddI and AZT in three lineages of human cells, i.e., MOLT4 (T lymphocytoid, CD4+), U937 (monocytoid, CD4+), and HT1080 (fibroblastoid, CD4-) cells. Feline leukemia virus, a retrovirus that causes immunodeficiency in cats, was used to infect the cells. The drug concentrations needed to reduce the viral p27 antigen titers in cell lysates by 50% (IC50s) were determined. The data show that AZT and ddI inhibited viral replication in all three cell lines. The IC50s of AZT were 0.02, 1.75, and 2.31 microM in MOLT4, HT1080, and U937 cells, respectively. For ddI, the IC50s were 4.31, 9.52, and 43.5 microM, respectively. These data indicate differential antiviral activities of ddI and AZT in the different cells with the following rank order of drug sensitivity: MOLT4 > HT1080 > U937. A study of the intracellular metabolism of [3H]AZT and [3H]ddI shows that the antiretroviral activities of AZT and ddI in the three cell lines correlated with the levels of their intracellular triphosphate metabolites.", "journal": "Antimicrobial agents and chemotherapy", "doi": "10.1128/AAC.38.7.1573", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8048038", "author": "Fuchs A", "n_authors": 3, "title": "[Epidemiology of FeLV and FIV infection in the Federal Republic of Germany].", "abstract": "In a nationwide study 6101 cats were tested for presence of feline leukemia virus (FeLV) antigen and for feline immunodeficiency virus (FIV) antibodies utilizing enzyme linked immunosorbent assay (ELISA). 21.8% of the German cat population may be FeLV- and/or FIV-positive. Of the animals tested, 13.4% were found to be FeLV carriers, while 8.4% showed evidence of FIV infection. Infection with both viruses was identified in 2.1% of the cats tested. Of the animals showing clinical symptoms, nearly one cat in three was found to be carrying either one or both of the viruses. Male cats were more likely to be infected then were females, similarly as were free-roaming cats, compared with confined cats; domestic cats, compared with purebred cats; and cats > 6 years old, compared with younger cats.", "journal": "Tierarztliche Praxis", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "7914523", "author": "Poli A", "n_authors": 6, "title": "Malignant lymphoma associated with experimentally induced feline immunodeficiency virus infection.", "abstract": "A malignant low-grade B-cell lymphoma, primarily in the kidney, is described in a specific-pathogen-free cat experimentally infected with feline immunodeficiency virus (FIV) and free of feline leukaemia virus. At the time of diagnosis the cat showed a marked reduction of circulating CD4+ T lymphocytes, was 2 years old, and had been infected for 18 months. FIV was isolated both from peripheral blood mononuclear cells and the neoplastic tissue. DNA of FIV gag gene was detected in several specimens, including the neoplastic tissue. Even if they do not demonstrate a direct role for virus promotion of lymphomas, these and previous observations indicate that B-cell malignant lymphoma might be associated with FIV infection as reported for human and simian immunodeficiency virus infections.", "journal": "Journal of comparative pathology", "doi": "10.1016/s0021-9975(08)80309-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8080585", "author": "Kerr MG", "n_authors": 1, "title": "Vaccination against feline leukaemia virus.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.134.17.455", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8171057", "author": "Wang SW", "n_authors": 2, "title": "Induction of feline acquired immune deficiency syndrome by feline leukemia virus: immuno- and neuroendocrine dysfunctions.", "abstract": "Young cats, when chronically infected with feline leukemia virus (FeLV), developed feline acquired immune deficiency syndrome (FAIDS). The syndrome was associated with a sequence of dysfunctions in the hypothalamic-pituitary-gonadal (HPG) and the immune system, manifested in the reduction of luteinizing hormone-releasing hormone (LHRH), follicle stimulating hormone (FSH), luteinizing hormone (LH), and testosterone in blood plasma. The average FSH and LH (in plasma or lymphocyte), testosterone, and LHRH concentrations in the 20 FeLV-infected cats were measured by radioimmunoassay. The results were compared with those of the 12 control cats that were not FeLV-infected. Four weeks after infection, the plasma LHRH concentration in the infected cats showed a 43% reduction. Five to six weeks after infection, the content of FSH and LH in lymphocyte was reduced by 50% and 28%, respectively, whereas, the plasma FSH and LH was reduced by 52% and 42%, respectively. A significant reduction in testosterone content was detected at Week 11 of infection. The onset of the immuno- and neuroendocrine dysfunctions in FAIDs cats followed this sequence: hypothalamus, lymphocyte, pituitary, adrenal gland, and gonads. Indirect immunofluorescence assay showed the presence of FeLV cytoplasmic antigens in the fibers of the hypothalamic preoptic region and the Leydig cells. The possible causal relationship between the dysfunction of the lymphocyte and HPG systems and the presence of FeLV was discussed.", "journal": "Proceedings of the Society for Experimental Biology and Medicine. Society for Experimental Biology and Medicine (New York, N.Y.)", "doi": "10.3181/00379727-205-43715", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8139030", "author": "Rohn JL", "n_authors": 4, "title": "Evolution of feline leukemia virus variant genomes with insertions, deletions, and defective envelope genes in infected cats with tumors.", "abstract": "In order to study retroviral variation, selection, and viral correlates of in vivo pathogenicity, we documented the evolution of feline leukemia virus (FeLV) variants in cats that died with thymic lymphoma after infection with molecularly cloned subgroup A FeLV. Using genomic DNA from cat necropsy samples, we employed PCR to amplify and clone the envelope gene, which is a major determinant of the specific pathogenicity of different FeLV variants. In the envelope gene, mutations encoded scattered amino acid changes that did not cluster into clearly definable variable regions; however, characterization of these terminal variant sequences revealed a predominance of G-to-A and A-to-G nucleotide substitutions. Additionally, some cats harbored variants with recombinant subgroup B-like envelope genes, while the major variant from one cat had a 12-bp insertion in a region previously characterized as an immunodeficiency-inducing determinant. Finally, proviruses from tumor DNA frequently possessed envelope genes predicted to encode a protein truncated in the N-terminal half because of either premature termination codons or deletions ranging from 29 to 1,666 bp. In contrast, all envelope genes cloned from the bone marrow of one cat were predicted to encode full-length envelope product, and only a minority of proviral clones from a cat that did not develop a tumor had defective envelope genes. Thus, in the cat, viruses evolved from subgroup A FeLV that had point mutations, insertions, deletions, or recombinant envelope genes. Furthermore, defective variants were particularly prominent in T-cell tumors.", "journal": "Journal of virology", "doi": "10.1128/JVI.68.4.2458-2467.1994", "deposited_data": "Sim", "nuccore_ids": "417963, 417961, 417959, 417957, 417955, 417953, 417952, 417951, 417950, 417948, 417947, 417946, 417939, 417938, 417937, 417936, 417934, 417933, 417922, 417920, 417918, 417916, 417914, 417912, 417910, 417909, 417907, 417905, 417902, 417901, 417892, 417890, 417888, 417887, 417885, 417883, 417878, 417876, 417874, 417872, 417870", "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8138999", "author": "McDougall AS", "n_authors": 6, "title": "Defective endogenous proviruses are expressed in feline lymphoid cells: evidence for a role in natural resistance to subgroup B feline leukemia viruses.", "abstract": "Endogenous feline leukemia virus (FeLV)-related sequences (enFeLV) are a family of proviral elements found in domestic cats and their close relatives. These elements can recombine with exogenous, infectious FeLVs of subgroup A (FeLV-A), giving rise to host range variants of FeLV-B. We found that a subset of defective enFeLV proviruses is highly expressed in lymphoma cell lines and in a variety of primary tissues, including lymphoid tissues from healthy specific-pathogen-free cats. At least two RNA species were detected, a 4.5-kb RNA containing gag, env, and long terminal repeat sequences and a 2-kb RNA containing env and long terminal repeat sequences. Cloning of enFeLV cDNA from two FeLV-free lymphoma cell lines (3201 and MCC) revealed a long open reading frame (ORF) encoding a truncated env gene product corresponding to the N-terminal portion of gp70env. Interestingly, all of three natural FeLV-B isolates include 3' env sequences which are missing from the highly transcribed subset and hence must be derived from other enFeLV elements. The enFeLV env ORF cDNA clones were closely similar to a previously characterized enFeLV provirus, CFE-16, but were polymorphic at a site corresponding to an exogenous FeLV neutralization epitope. Site-specific antiserum raised to a C-terminal 30-amino-acid peptide of the enFeLV env ORF detected an intracellular product of 35 kDa which was also shed from cells in stable form. Expression of the 35-kDa protein correlated with enFeLV RNA levels and was negatively correlated with susceptibility to infection with FeLV-B. Cell culture supernatant containing the 35-kDa protein specifically blocked infection of permissive fibroblast cells with FeLV-B isolates. We suggest that the truncated env protein mediates resistance by receptor blockade and that this form of enFeLV expression mediates the natural resistance of cats to infection with FeLV-B in the absence of FeLV-A.", "journal": "Journal of virology", "doi": "10.1128/JVI.68.4.2151-2160.1994", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8042281", "author": "Peri EV", "n_authors": 6, "title": "Seroepidemiological and clinical survey of feline immunodeficiency virus infection in northern Italy.", "abstract": "Four hundred and thirty-nine feline serum samples from cats with different living conditions in the north of Italy were tested for antibodies to feline immunodeficiency virus (FIV) and for antigen of Feline Leukemia Virus by enzyme-linked immunosorbent assay. A Western blot technique was also used on the positive sera in order to confirm the presence of specific antibodies to FIV. The Western blot enabled the detection of a false positive serum. The prevalence of FIV infection in this population was 12.5% and among the seropositive cats a greater proportion was male (74.5%) than female (25.5%). A correlation between the clinical status and the evolution of the pathology is described together with a score based on the severity of the stomatitis in infected cats. The Western blot patterns of positive samples were then compared with the stage of the pathology. Statistical analysis on the distribution of FIV in stray cats, cats with garden and courtyard access and strictly house-confined cats showed a highly significant risk of the infection in the first group.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(94)90040-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8028105", "author": "Paul-Murphy J", "n_authors": 5, "title": "Serologic survey and serum biochemical reference ranges of the free-ranging mountain lion (Felis concolor) in California.", "abstract": "Serum samples from 58 mountain lions (Felis concolor) in California (USA) were collected between April 1987 and February 1990. Nineteen serum samples were used for serum biochemistry determinations; the ranges were similar to reference values in domestic cats, captive exotic felidae and free-ranging mountain lions. A serological survey was conducted to determine whether antibodies were present against selected infectious agents. Fifty-four (93%) of 58 sera had antibodies against feline panleukopenia virus. Fifteen (68%) of 22, 16 (28%) of 58, 11 (19%) of 58, and 10 (17%) of 58 had serum antibodies against feline reovirus, feline coronavirus, feline herpes virus, and feline calicivirus, respectively. Twenty-three (40%) of 58 and 21 (58%) of 36 had serum antibodies against Yersinia pestis and Toxoplasma gondii, respectively. Only one of 22 sera had antibodies against the somatic antigen of Dirofilaria immitis. Feline leukemia virus and feline immunodeficiency virus antigens were not detected in any mountain lion's sera. All 58 sera samples were negative for antibodies to feline immunodeficiency virus and Chlamydia psittaci.", "journal": "Journal of wildlife diseases", "doi": "10.7589/0090-3558-30.2.205", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "7514879", "author": "Sharma SK", "n_authors": 4, "title": "Engineering of the human-immunodeficiency-virus-type-1 (HIV-1) reverse transcriptase gene to prevent dimerization of the expressed chimaeric protein: purification and characterization of a monomeric HIV-1 reverse transcriptase.", "abstract": "We report here a human-immunodeficiency-virus-type-1 (HIV-1) recombinant reverse transcriptase (RT) engineered to contain a 26-amino-acid linker insertion from the tether domain of feline leukaemia virus (FLV) RT. The chimaeric protein was expressed in Escherichia coli and migrated on SDS/PAGE as a 68 kDa band. A monomeric form of the chimaeric HIV-1 RT has been prepared by the coordinated applications of immobilized-metal-affinity chromatography and gel filtration on Superose 12 columns. The monomeric nature of this chimaeric HIV-I RT was further characterized by cross-linking studies using disuccinimidyl suberate. The RNA-dependent DNA polymerase activity of the monomeric chimaeric HIV-1 RT was 35% that of the heterodimeric (p66/p51) HIV-1 RT. These results support our recent studies on the monomeric polymerase domain (p51 RT) which exhibited an RNA-dependent DNA polymerase activity equal to 33% of that of the p66/p51 heterodimeric HIV-1 RT (Evans, Kezdy, Tarpley and Sharma [1993] Biotechnol. Appl. Biochem. 17, 91-102). The inability of the monomeric chimaeric HIV-1 RT to display polymerase activity like that of the heterodimeric HIV-1 RT is attributed to a decrease in the processive rate of DNA synthesis (75%) and DNA binding (65%). However, the monomeric chimaeric HIV-1 RT (p68) exhibited RNAase H activity like that of the heterodimeric form (p66/p51) of HIV-1 RT. These results suggest that the linker insertion from FLV RT does not interfere with the RNAase H activity associated with the monomeric HIV-1 RT.", "journal": "Biotechnology and applied biochemistry", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8188511", "author": "Lafrado LJ", "n_authors": 1, "title": "Evaluation of a feline leukemia virus vaccine in a controlled natural transmission study.", "abstract": "Twenty-six 8-week-old specific-pathogen-free cats were vaccinated subcutaneously with 2 doses of a commercially available FeLV vaccine, and 26 age-matched specific-pathogen-free cats were similarly vaccinated with a placebo vaccine containing the same adjuvant as the FeLV vaccine. Cats then were randomly assigned to 2 groups of 26 cats (13 FeLV-vaccinated cats and 13 control cats), and each group was housed with 5 cats previously inoculated with FeLV. All cats were tested biweekly for the next 26 weeks for evidence of FeLV antigenemia. Five of the 26 control cats developed antigenemia. However, 4 of these cats were only transiently antigenemic (positive results for 3 consecutive biweekly samples) and only 1 was persistently antigenemic. None of the FeLV-vaccinated cats developed antigenemia. Preventable fraction was calculated to be 100%.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8197689", "author": "Carmichael N", "n_authors": 2, "title": "Prevalence of FeLV in sick cats.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.134.10.255-a", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8046683", "author": "Lane SB", "n_authors": 4, "title": "Feline spinal lymphosarcoma: a retrospective evaluation of 23 cats.", "abstract": "A retrospective study of pathologically confirmed cases of feline spinal lymphosarcoma (FSL) admitted to the Colleges of Veterinary Medicine at the University of Georgia and North Carolina State University from 1973 to 1988 was conducted. Two hundred fourteen cases of feline lymphosarcoma were diagnosed histopathologically; involvement of the central nervous system (CNS) was identified in 26 (12.1%). Twenty-three of these tumors involved the spinal cord, and 22 of the 23 were solitary. A predilection for the thoracic and lumbar vertebral canal was noted. Most cats with spinal disease were young, with mean and median ages of 43 and 24 months, respectively; 67 cats were 36 months of age or younger. In most cases, affected cats had acute neurological deterioration after an initial insidious course. Extraneural abnormalities were not consistently present. Neoplastic lymphocytes diagnostic of FSL were identified on cerebrospinal fluid (CSF) analysis in 6 of 17 cats evaluated. Sixteen of 17 cats evaluated had serologically positive test results for feline leukemia virus (FeLV) p27 antigen, and all cats tested for feline immunodeficiency virus (FIV) antibodies had negative test results.", "journal": "Journal of veterinary internal medicine", "doi": "10.1111/j.1939-1676.1994.tb03205.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8080515", "author": "Jarrett O", "n_authors": 1, "title": "Vaccination against feline leukaemia virus.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.134.8.198-a", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8163416", "author": "Tobey JC", "n_authors": 5, "title": "Cutaneous T-cell lymphoma in a cat.", "abstract": "An 8-year-old castrated male cat was examined because of a chronic, nonhealing, ulcerative lesion on the left hind limb. Cutaneous lymphoma was diagnosed on the basis of the morphologic appearance of malignant cells and Pautrier's microabscesses on light and electron microscopic examination. The tumor was found to be of T-cell origin by use of a polyclonal antibody recognizing T-cell antigen. Results of serum ELISA for FeLV were negative. The gp70 antigen of FeLV was not detected immunohistochemically in tumor tissue sections, using polyclonal goat antisera and avidin/biotin/peroxidase complex technique. Presence of FeLV was demonstrated by the polymerase chain reaction procedure, involving amplification of a 166-base pair region of FeLV DNA. Although FeLV is reported to be the cause of most types of lymphoma in cats, cats with epitheliotropic cutaneous lymphoma have consistently negative test results for circulating FeLV antigen. In such cases, using the polymerase chain reaction method, tumor DNA may be assessed for integrated FeLV provirus and the presence of FeLV can be confirmed.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "7509077", "author": "Pyra H", "n_authors": 3, "title": "Ultrasensitive retrovirus detection by a reverse transcriptase assay based on product enhancement.", "abstract": "Reverse transcriptase (RT) is an indispensable component of infectious retroviruses. We have developed an ultrasensitive RT test in which RNA of bacteriophage MS2 serves as the template for RT-mediated cDNA synthesis. A fragment of the cDNA is selectively amplified by polymerase chain reaction and the amplification product is analyzed by Southern blot hybridization or enzyme immunoassay. The procedure was 10(6) to 10(7) times more sensitive than a conventional RT test and detected as little as 10(-9) unit of murine leukemia virus RT, which corresponded to 2.1 x 10(2) molecules, a number present in 3-11 virions. As a screening assay for filterable particle-associated RT, it was positive with supernatants from cell cultures producing human immunodeficiency virus (HIV) type 1 or human T-cell leukemia virus (HTLV) type 1 or 2, but was negative with nonproducer cultures. It was positive with plasma samples from all tested individuals infected with HIV-1, HIV-2, or HTLV-1 and sera from cats infected with feline leukemia virus or feline immunodeficiency virus. Control samples from blood donors or uninfected cats were negative. Density banding experiments with culture supernatants showed that the RT activity was associated with virus particles. The assay should detect all replication-competent retroviruses or similar agents. It may be used as a screening assay for such agents, for quantitation of the viral load, drug susceptibility testing of RT, and control of virus inactivation in biological products.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.91.4.1544", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8160342", "author": "Mainland TR", "n_authors": 1, "title": "FeLV incidence.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.134.7.176-b", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8311118", "author": "Chakrabarti R", "n_authors": 5, "title": "Recombination between feline exogenous and endogenous retroviral sequences generates tropism for cerebral endothelial cells.", "abstract": "Brain tissues of domestic cats that died of aplastic anemia from infection with either parental feline leukemia virus (FeLV), subgroup C, or a mixture of FeLV-C and recombinants between FeLV-C and an endogenous FeLV provirus were examined by the immunoperoxidase staining technique using a monoclonal antibody (C11D8) directed against an epitope of the viral surface glycoprotein (SU). Positive staining of the central nervous system (CNS) capillary endothelial cells with no labeling on neuronal or glial cells was observed in cats that were inoculated with the virus mixture. This was in contrast to brain tissue of cats infected with FeLV-C alone, which showed no such staining. While non-CNS endothelial cells derived from human umbilical vein (HUVEC) could be readily infected in culture by FeLV-C, endothelial cells derived from human retina (REC) or brain (BEC) were resistant to infection by this parental virus. These latter cells in culture, however, could be infected by the viral mixture. The data suggested that at least one or more of the presumptive recombinant viruses could specifically infect CNS-derived endothelial cells. Using polymerase chain reaction and DNA sequencing strategies to amplify and analyze DNA fragments of the proviral SU region from cells infected with REC-selected viruses, we found the occurrence of a single recombinant in which two-thirds of the SU gene from the N-terminus of FeLV-C was replaced by the endogenous FeLV element. This recombinant virus, when molecularly cloned, should be useful in determining its potential in vivo neuropathogenicity.", "journal": "The American journal of pathology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8204217", "author": "Fontenot JD", "n_authors": 5, "title": "Structure and self assembly of a retrovirus (FeLV) proline rich neutralization domain.", "abstract": "The 60 amino acid proline-rich neutralization domain of the external surface unit glycoprotein of feline leukemia virus was chemically synthesized in total and in fragments. We examined the ability of these retroviral peptides to form ordered conformations using 1H-NMR, circular dichroism spectroscopy, and intrinsic viscosity measurements. One dimensional nuclear magnetic resonance spectroscopy revealed that the 60 amino acid peptide could form a stable, folded structure that was long-lived, as shown by the ability to protect amide-protons in D20. Peptides corresponding to the N-terminal 42, N-terminal 20 amino acids, and middle 20 amino acid sections could also form stable structures. The C-terminal segment did not protect any protons in D20. Interestingly, self assembly of the N-terminal 42 and C-terminal 16 amino acid peptides into a structure very close to that of the 60 amino acid domain was observed. The circular dichroism results reveals a large negative cotton effect at 198 nm that is characteristic of the proline-rich beta-turn helixes which consist predominantly of trans-proline. The intrinsic viscosity results suggest a non-random coil structure that is rod shaped. Our conclusion is that PRN60 forms a beta-turn helix and that this region of FeLV-gp70 is a separate folding domain of the retroviral surface unit glycoprotein. The unique conformational properties of PRN60 and its critical role as the predominant target for neutralizing antibody responses suggest that this peptide is a reasonable candidate for producing a synthetic peptide vaccine for FeLV.", "journal": "Journal of biomolecular structure & dynamics", "doi": "10.1080/07391102.1994.10508035", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8165663", "author": "Trautwein G", "n_authors": 2, "title": "[Immunopathogenesis of virus diseases of cats and dogs].", "abstract": "Immunopathological reactions may determine the pathogenesis of some viral infections of cats and dogs. Three pathomechanisms may aggravate the viral disease or may ultimately cause death. Some viruses cause transient or persistent immunosuppression (Feline Immunodeficiency, Feline Leukemia, Feline Panleukopenia Virus, Canine Parvovirus-2, Canine Distemper Virus). In other viral infections cells and tissues are destroyed as a sequela of cell-mediated cytotoxicity reactions (demyelinating encephalitis in distemper). The third example of a pathogenic immune reaction is virus-induced immune complex diseases (infections with FeLV, FIPV and CAV-1).", "journal": "Tierarztliche Praxis", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "12666034", "author": "Bounous DI", "n_authors": 4, "title": "Acute myeloid leukemia with basophilic differentiation (AML, M-2B) in a cat.", "abstract": "A 4-year-old, neutered male Domestic Shorthair cat with a history of depression, anorexia, and weight loss was diagnosed with acute myelogenous leukemia (AML). The cat tested positive by both the feline immunodeficiency virus antibody test and feline leukemia virus enzyme-linked immunosorbent assay test. Results of cytochemical stains on peripheral blood and bone marrow specimens indicated acute myeloid leukemia with unusual basophilic differentiation (AML, M-2B).", "journal": "Veterinary clinical pathology", "doi": "10.1111/j.1939-165x.1994.tb01010.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8259654", "author": "Mathes LE", "n_authors": 7, "title": "Pathogenicity of a subgroup C feline leukemia virus (FeLV) is augmented when administered in association with certain FeLV recombinants.", "abstract": "There is evidence to suggest that infectious feline leukemia viruses (FeLVs) may be altered biologically because of homologous recombination with non-infectious endogenous FeLV (enFeLV) sequences in the infected cells. To evaluate the role of such recombination events in FeLV pathogenesis, a molecular clone of subgroup C FeLV, Sarma strain (FSC), was tested for induction of aplastic anemia in the absence or presence of mixtures of recombinants between FSC and an enFeLV element. In the recombinants, FSC sequences in the viral surface glycoprotein (SU) protein were variably replaced by the corresponding sequences of the enFeLV. The results showed that the virus mixtures varied in their infectivity to neonatal specific pathogen-free cats. One group of mixtures, although exhibiting relatively reduced infectivity, represented the most acute disease-inducing agents. The presence of recombinants in this mixture significantly accelerated the development of erythrocyte aplasia compared to cats infected with FSC alone. In addition, infected cells appeared to be distributed differently in various hematopoietic organs with respect to infection with FSC versus viral mixture. Viral recombinants which were present in this inoculum mixture, however, could not be detected in the plasma or infected tissues of the cats at the end stage of the disease, although their presence in the plasma at the early stages could be detected. Clearly, parental FSC outgrew the recombinants in the infected animals, since its detection was prominent at all stages of the progression of the disease. Therefore, we hypothesize that recombinants initially present in the infected animals, while only poorly replicated compared to FSC in the host, might have had the opportunity to infect certain target cells (potentially erythroid progenitor cells) and then disappeared with the associated cytopathic effect.", "journal": "Virology", "doi": "10.1006/viro.1994.1021", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8148438", "author": "Heneine W", "n_authors": 7, "title": "Lack of evidence for infection with known human and animal retroviruses in patients with chronic fatigue syndrome.", "abstract": "We investigated 21 patients with chronic fatigue syndrome who were identified through the surveillance system of the Centers for Disease Control and Prevention (CDC) in Atlanta for the presence of several human and animal retroviruses. In addition, we evaluated 21 CDC employee controls matched with the patients for age (+/- 5 years), gender, and race. The viruses tested included human T-lymphotropic viruses types I and II; human spuma retrovirus; simian T-lymphotropic virus type I; simian retroviruses types 1, 2, and 3; bovine leukemia virus; feline leukemia virus; and gibbon ape leukemia virus. Samples of peripheral blood lymphocytes and leukocytes from patients and controls were analyzed in a blinded fashion for retroviral sequences; polymerase chain reaction (PCR) amplification assays and Southern blot hybridization to 32P-labeled internal oligoprobes were used. All PCR assays were optimized for maximal sensitivity on respective infected cell lines or plasmids, and sensitivity controls were included in each experiment. All samples from patients and controls were negative for the tested retroviral sequences. Our data indicate that none of these retroviruses plays an etiologic role or is a cofactor in the chronic fatigue syndrome illnesses of our study population.", "journal": "Clinical infectious diseases : an official publication of the Infectious Diseases Society of America", "doi": "10.1093/clinids/18.supplement_1.s121", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8025833", "author": "Hosie MJ", "n_authors": 1, "title": "The development of a vaccine against feline immunodeficiency virus.", "abstract": "Feline immunodeficiency virus (FIV) is a retrovirus causing significant disease in cats. The virus has been shown to be similar biologically to the human immunodeficiency virus (HIV), the cause of acquired immunodeficiency syndrome (AIDS) in humans. Much interest has been expressed in the use of FIV as an animal model for HIV vaccination studies. Both FIV and HIV belong to the lentivirus group of retroviruses. While there are several effective vaccines against feline leukaemia virus (FeLV), a mammalian type C retrovirus, at present there are no effective vaccines against lentiviruses. This review illustrates the obstacles to the production of vaccines against FIV or HIV. FIV vaccine studies conducted in several laboratories are reviewed, the results are compared and factors important for inducing protection from FIV infection are discussed.", "journal": "The British veterinary journal", "doi": "10.1016/S0007-1935(05)80094-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "7998833", "author": "Kyaw-Tanner MT", "n_authors": 4, "title": "The induction of in vivo superinfection and recombination using feline immunodeficiency virus as the model.", "abstract": "This study investigated the hypothesis that under certain conditions, superinfection of cats with feline immunodeficiency virus (FIV), may occur. One FIV isolate (T91) was used to inoculate three FIV and FeLV-free cats. Blood from an FIV-infected cat (N), which contained two variants and differed from T91 by at least 5% in nucleotide sequence in the env gene, was inoculated into a fourth cat. Both T91 and blood from N were inoculated simultaneously into a fifth cat. After 22 weeks, two of the three cats initially infected with T91 were challenged with blood from N. At 30 weeks following initial infection, peripheral blood mononuclear cells were obtained from all cats, DNA was extracted, and a segment of the env gene was PCR amplified, cloned and sequenced. Nucleotide sequence analysis of the cloned PCR product showed that virus strains used in initial infection were recovered from cats not challenged with a second variant. Challenge of cats with the blood of N following initial infection with T91 resulted in superinfection occurring in one cat and recombination occurring in the other. Furthermore, the use of blood as a source of challenge, in cats where superinfection and simultaneous infections were attempted, may have induced the appearance of variants which more closely resembled the most heterologous strain present in the infectious source.", "journal": "Archives of virology", "doi": "10.1007/BF01379130", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "7958467", "author": "Taylor J", "n_authors": 7, "title": "Applications of canarypox (ALVAC) vectors in human and veterinary vaccination.", "abstract": "This paper presents data derived from safety and efficacy studies of ALVAC-based rabies and feline leukemia virus (FeLV) vaccine candidates in target species. Inoculation of the ALVAC-RG recombinant was well tolerated in all species including humans and very young dogs. Protection induced in dogs against rabies challenge was long-lasting and could be elicited in the face of high levels of maternally-derived neutralizing antibody. Parenteral inoculation of cats with an ALVAC-FeLV recombinant was safe and induced protection against persistent infection following oro-nasal FeLV challenge.", "journal": "Developments in biological standardization", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "7801087", "author": "Hofmann-Lehmann R", "n_authors": 5, "title": "[Vaccination of cats against infection with feline leukemia virus (FeLV): first recombinant vaccine and the effect of a pre-existing infection with feline immunodeficiency virus (FIV)].", "abstract": "A new recombinant FeLV vaccine was evaluated in 30 specified pathogen-free cats 10 months of age cats. The vaccine consisted of the non-glycosylated FeLV envelope protein p45, aluminium hydroxide and a saponin adjuvant. The cats (n = 18) were vaccinated twice intramuscularly, 3 weeks apart. All animals were challenged intraperitoneally with FeLV subgroup A, 18 weeks later. While 94% of the vaccinated cats showed no viraemia or were only transiently viraemic, 80% of the non-vaccinated animals became persistently viraemic within 2 to 3 weeks. In our hands the preventable fraction of the vaccine was 93%. In order to determine the effect of a pre-existing infection with feline immunodeficiency virus on the efficacy of vaccination, 50% of the cats were previously infected with FIV. The infected cats were protected to the same degree as the non-infected animals. With prolonged duration of FIV infection the probability increases, that the immune system of the cat will fail and clinical signs will appear. In order to observe a state of possible immunodeficiency, an accurate clinical examination of every cat prior to vaccination seems of major importance.", "journal": "Schweizer Archiv fur Tierheilkunde", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "8553560", "author": "Pandey R", "n_authors": 7, "title": "Feline leukemia virus variants in experimentally induced thymic lymphosarcomas.", "abstract": "This study was initiated to evaluate the in vivo infectivity and pathogenicity of a group of recombinant feline leukemia viruses (rFeLVs) previously generated by in vitro forced recombination between a FeLV subgroup A virus (FeLV-A) and an endogenous FeLV (enFeLV) envelope (env) element (Sheets et al., 1992, Virology 190, 849-855). To determine infectivity of rFeLVs, neonatal cats were inoculated with rFeLVs alone or in combination with FeLV-A. The recombinant viruses were able to replicate efficiently in vivo only when administered along with FeLV-A. Of six co-infected cats, three developed thymic lymphosarcomas, one severe aplastic anemia, and two cachexia and depression; all were viremic and seroconverted shortly after inoculation. While both virus types were detected in virtually all tissues examined from these tumor-bearing cats, there was a particularly noteworthy sequence reversion in the rFeLVs. It is known that exogenous FeLV isolates carry a conserved neutralizing MGPNL epitope in the middle of the surface glycoprotein domain of the env gene. In contrast, the parental recombinant viruses used to inoculate these cats harbored the enFeLV-derived MGPNP sequence at this position. However, all in vivo-propagated recombinants displayed the MGPNL sequence, while the env-encoded backbone flanking the MGPNL sequence was that of the parental recombinant virus. These results suggest that viruses with the MGPNL epitope have an in vivo proliferative advantage. The data also provide an explanation for the conservation of this epitope in exogenous FeLVs despite the existence of variant forms in enFeLV proviral elements with which they can recombine.", "journal": "Virology", "doi": "10.1006/viro.1995.0069", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "8553544", "author": "Athas GB", "n_authors": 5, "title": "Genetic determinants of feline leukemia virus-induced multicentric lymphomas.", "abstract": "Three discrete forms of feline leukemia virus (FeLV)-associated lymphoma have been described clinically: (1) thymic, (2) alimentary, and (3) multicentric. The most common and best-characterized lymphomas are of T-cell origin, generally occurring in the thymus. These tumors typically contain mature T-cells, involve the activation of a distinctive set of proto-oncogenes, and contain FeLV proviruses whose long terminal repeat (LTR) sequences contain tandemly repeated enhancers. Previous studies of a small group of extrathymic, multicentric lymphomas implicated a different set of genetic determinants. The present study expands those observations by examining the lineage of origin, the involvement of proto-oncogenes, and the structure of LTR and env gene sequences in a set of 11 natural, extrathymic lymphomas of the multicentric type. A pattern of genetic events associated with FeLV-positive multicentric lymphomas emerges from this analysis that is clearly distinct from the pattern associated with thymic lymphomas. The tumors do not contain T-cells or B-cells, as evidenced by the germ line organization of TCR beta and IgH loci. Proto-oncogenes strongly implicated in T-cell lymphomagenesis are not involved in these tumors. Rather, a distinct set of proto-oncogenes may be involved. Most striking is the repeated occurrence of an FeLV isolate whose LTR and env gene bear unique sequence elements.", "journal": "Virology", "doi": "10.1006/viro.1995.0053", "deposited_data": "Sim", "nuccore_ids": "37577227, 37577226, 37577225, 37577224, 37577223, 37577222, 37577221, 37577220, 37577219, 37577218, 37577217, 37577216, 37577215, 37577214, 1911484", "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7493898", "author": "Mahony OM", "n_authors": 6, "title": "Alimentary lymphoma in cats: 28 cases (1988-1993).", "abstract": "To evaluate response to chemotherapy in cats with alimentary lymphoma and to determine factors associated with survival time. Retrospective case series. 28 cats with alimentary lymphoma that underwent chemotherapy. In all cats, the diagnosis had been established by means of cytologic or histologic examination of ultrasound-guided aspirates and biopsy specimens (18 cats), histologic examination of surgically obtained biopsy specimens (7 cats), or examination of specimens obtained endoscopically (3 cats). Clinical signs included anorexia, weight loss, vomiting, and diarrhea. Twenty-seven cats were treated with vincristine sulfate, cyclophosphamide, and prednisone; 1 was treated with chlorambucil and prednisone. Survival time ranged from 2 to 2,120 days (median, 50 days). Nine cats achieved complete remission (remission time ranged from 30 to 1,700 days; median, 213 days), 2 achieved partial remission, and 17 failed to respond to chemotherapy. Sex, FeLV status, hematocrit, serum total protein concentration, site and extent of gastrointestinal involvement, and clinical stage were not found to be associated with survival time. Cats with alimentary lymphoma are poorly responsive to treatment with vincristine, cyclophosphamide, and prednisone; however, a small subset of cats may have long survival times.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "8820601", "author": "Zeidner NS", "n_authors": 3, "title": "Reversal of feline leukemia virus infection by adoptive transfer of activated T lymphocytes, interferon alpha, and zidovudine.", "abstract": "Previous experimental studies utilizing human recombinant interferon-alpha-2b (IFNalpha-2b) alone or with zidovudine (AZT) to treat established feline leukemia virus (FeLV) infection resulted in a significant reduction in circulating virus throughout a 49-day treatment period. However, the anti-FeLV effect of IFNalpha was limited by the production of IFNalpha-neutralizing antibodies detected 7 weeks after the start of treatment. AZT without IFNalpha had no effect on circulating virus load. To examine the hypothesis that combination chemoimmunotherapy might induce the clearance of FeLV infection, persistently infected cats were infused with activated lymphocytes, IFNalpha, and AZT 12 weeks after infection with FeLV. Recipient cats received weekly infusions of 1.46 x 10(8) lymphocytes activated in vitro with lectin/IL-2 comprised of 98% T cells and an even distribution of CD4+ and CD8+ lymphocytes. FeLV infection was cleared in 4 of 9 cats receiving combined therapy after four adoptive cell transfers. These cats remained negative for circulating virus during a 63-day treatment period (17 adoptive cell transfers) despite the production of anti-IFNalpha-neutralizing antibodies. Sequential development of virus-neutralizing and virus envelope antibody titers were detected in those cats which cleared retroviremia, an antiviral response that was absent in untreated control animals or nonresponders. Three of four responder cata remained negative for FeLV 95 days after treatment was discontinued. Treatment of cats with lymphocytes without chemotherapy failed to influence the course of FeLV infection. These results suggest that combined treatment using IFNalpha and adoptive lymphocyte transfer served to reconstitute antiviral humoral immunity, counteract immunosuppression, and induce the reversal of retroviremia.", "journal": "Seminars in veterinary medicine and surgery (small animal)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "8820599", "author": "Lappin MR", "n_authors": 1, "title": "Opportunistic infections associated with retroviral infections in cats.", "abstract": "Naturally occurring infection of cats with feline leukemia virus and feline immunodeficiency virus is common. A wide variety of clinical manifestations occur in retrovirus-infected cats including gastrointestinal tract disease, respiratory tract disease, central nervous system disease, ophthalmic disease, hepatic disease, urogenital tract disease, dermatologic disease, hematologic disease, and musculoskeletal disease. Clinical signs are often directly attributable to the primary viral infection, but because both feline leukemia virus and feline immunodeficiency virus can induce immunodeficiency, opportunistic secondary infections may cause the clinical manifestations of disease in some cats. Diagnosis, treatment, and zoonotic potential of the common opportunistic agents associated with feline retroviral infections are reviewed.", "journal": "Seminars in veterinary medicine and surgery (small animal)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "8820598", "author": "Hoover EA", "n_authors": 4, "title": "Development and testing of an inactivated feline leukemia virus vaccine.", "abstract": "We assessed an inactivated whole virus feline leukemia virus (FeLV) vaccine developed from a molecularly cloned feline leukemia virus isolate (FeLV-61E-A) for its ability to protect cats against homologous and heterologous virulent virus challenge. The fractions of cats that resisted the induction of persistent viremia after FeLV challenge were the following: (1) FeLV-61E-A vaccine, 95%; (2) adjuvant controls, 26%; and (3) established commercial control FeLV vaccine, 35%. The pre-challenge mean neutralizing antibody titers for each group were (1) FeLV-61E-A vaccine, 1:43; (2) adjuvant controls, <1:8; and (3) established commercial control FeLV vaccine: 1:12. The commercial version of the prototype FeLV-61E-A vaccine (Fel-O-Vax, Fort Dodge Laboratories, Fort Dodge, IA) was developed through use of a proprietary adjuvant and a stable high antigen production cell lines. The efficacy and duration of immunity produced by Fel-O-Vax was studied alone and in multivalent combination with other feline virus vaccines in seven subsequent efficacy trials conducted in over 150 immunized cats. The overall FeLV-resistant fraction in these trials was 87% in vaccinated cats versus 8% in adjuvant controls. The duration of protective immunity induced by the multivalent Fel-O-Vax-LvK IV at 1 year postvaccination was 100% in challenged vaccinees versus 0% in challenged controls. The results of these studies show that an inactivated FeLV vaccine prepared from a molecularly cloned subgroup A FeLV can produce high level protective immunity against FeLV infection. This immunity is durable for at least 1 year without intervening booster immunization or virus exposure.", "journal": "Seminars in veterinary medicine and surgery (small animal)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "8820597", "author": "Macy DW", "n_authors": 1, "title": "The potential role and mechanisms of FeLV vaccine-induced neoplasms.", "abstract": "Vaccine-induced sarcomas are reported to occur in 1 in 10,000 or less cats vaccinated with feline leukemia virus (FeLV) vaccines. The potential of local vaccine site adjuvant-associated inflammation plays in the pathogenesis of these tumors is probably significant. However, it is believed that the feline leukemia antigens contained within these vaccines also play an important role in malignant transformation.", "journal": "Seminars in veterinary medicine and surgery (small animal)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "8820596", "author": "Shelton GH", "n_authors": 2, "title": "Hematologic abnormalities associated with retroviral infections in the cat.", "abstract": "Feline patients with unexplained peripheral blood cytopenias, circulating immature or neoplastic cells, dysplastic or dysmorphic bone marrow abnormalities, and/or lymphoid tumors are likely suffering from an underlying retroviral infection with feline leukemia virus (FeLV) and/or feline immunodeficiency virus (FIV). Cytopenic hematologic disorders are often caused by the direct or indirect hematosuppressive effects of these retroviruses. Alternatively, secondary infections, nutritional deficiencies, and/or hematopoietic neoplasms may be important cofactors in the development of blood and bone marrow abnormalities in retrovirus-positive patients. Mild to moderate nonregenerative anemia, with or without concurrent granulocytopenia and/or thrombocytopenia, is one of the most frequent hematologic disorders encountered with either infectious agent. Severe, isolated anemia with absent reticulocytes (pure red blood cell aplasia) specifically suggests infection with FeLV subgroup C. Hemolytic (regenerative) anemia, more commonly associated with FeLV infection, may be caused by an autoimmune process and/or coinfection with Haemobartonella felis. Lymphopenia is a hallmark of chronic, symptomatic FIV infection. Neutropenia may accompany a panleukopenia-like syndrome in FeLV-positive cats or it may be associated with acute primary infection or an adverse drug effect in the FIV-infected patient. FeLV and, to a lesser extent, FIV are both causally related to lymphoid neoplasms in domestic cats, but with dissimilar epidemiologic, clinical, and host cell phenotypic features. Clinicians must be cognizant of the wide spectrum of hematologic manifestations of FeLV and FIV infections to recognize and appropriately manage these complications in their feline patients.", "journal": "Seminars in veterinary medicine and surgery (small animal)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "8820595", "author": "McCaw D", "n_authors": 1, "title": "Caring for the retrovirus infected cat.", "abstract": "No commercial vaccine [correction of vacine] exists for feline immunodeficiency virus (FIV), and although feline leukemia virus (FeLV) vaccines are available, they are neither 100% effective nor used in all cats. These realities clearly indicate the veterinarian will be required to treat either FeLV- or FIV-positive cats for some time to come. The management of FIV- or FeLV-positive cats may require supportive therapies as well as virus-specific therapies such as zidovudine (AZT; Retrovir, Burroughs Wellcome, Research Triangle Park, NC).", "journal": "Seminars in veterinary medicine and surgery (small animal)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "8551803", "author": "Wu FY", "n_authors": 5, "title": "Chromosomal translocations in two feline T-cell lymphomas.", "abstract": "Two feline malignant lymphoma cell lines, FT-1 and FT-G, established from cats naturally infected with the feline leukemia virus were analyzed for chromosomal aberrations. Both FT-1 and FT-G cells had a modal number of 38 which is the normal diploid (2n) chromosome number of the domestic cat. G-banding-analysis showed that FT-1 had a translocation involving the short arms of chromosome A2 and D3--t (A2;D3) (p-;p+), and FT-G had a translocation involving the short arms of chromosomes A2 and B2--t (A2;B2) (p-;p+). Our data suggest that the chromosomal translocations were closely associated with the tumorigenesis in malignant lymphoma in cats.", "journal": "Leukemia research", "doi": "10.1016/0145-2126(95)00073-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7561518", "author": "Zhao Y", "n_authors": 6, "title": "Enhanced expression of novel CD57+CD8+ LAK cells from cats infected with feline immunodeficiency virus.", "abstract": "As a model for lymphokine-activated killer (LAK) function in HIV infection, we studied LAK cells in cats infected with feline immunodeficiency virus (FIV), which causes an acquired immunodeficiency syndrome. Peripheral blood mononuclear cells cultured in concanavalin A and interleukin-2 developed LAK cytotoxicity against chronically FIV-infected CrFK cells and acutely infected CD4+ lymphocytes but not uninfected cells. LAK cells from FIV+ cats were more cytotoxic than LAK cells from uninfected cats. Enhanced FIV+ LAK cytotoxicity against feline leukemia virus-infected cells (FL74) suggested that the cytotoxicity was not antigen specific. Two-color fluorescence-activated cell sorter analysis and antibody depletion studies demonstrated that the majority of LAK cells and their progenitors were positive for both CD8 and CD57. The in vitro induction of dual positive CD8+CD57+ LAK cells was enhanced in FIV+ cats, as reported for HIV+ patients. These CD8+CD57+ LAK cells may play a role in maintaining the long asymptomatic stage of infection in FIV+ cats.", "journal": "Journal of leukocyte biology", "doi": "10.1002/jlb.58.4.423", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7574682", "author": "Ghosh AK", "n_authors": 2, "title": "cDNA encoding a functional feline liver/bone/kidney-type alkaline phosphatase.", "abstract": "Feline alkaline phosphatase (FeALP) was copurified with the putative 70-kDa feline leukemia virus subgroup-A (FeLV-A) receptor protein from feline T-lymphocyte cells (FeT) by two-dimensional gel electrophoresis. The sequence of the N-terminal 17 amino acids and five other internal tryptic peptides revealed that it is homologous to the liver/bone/kidney (L/B/K)-type alkaline phosphatase of other mammalian species. Corresponding oligonucleotides were synthesized and used for amplification of a 1.2-kb segment of the FeALP gene by polymerase chain reaction, using phage DNA from a FeT cell cDNA library as template. The 1.2-kb FeALP gene fragment generated was then used as a probe to isolate a 2127-bp L/B/K-type FeALP cDNA clone from the same library harboring a large, intact open reading frame. This cDNA possessed an open reading frame encoding a 524-amino-acid protein including a putative signal peptide of 17 amino acids followed by 14-amino-acid residues identical to the N-terminal sequence determined from the purified protein. Sequences closely related to five tryptic peptides from the purified protein were also contained within the cDNA-encoded protein. Homology with the human, bovine, rat and mouse L/B/K-type ALP was found to be 88-90% at both the nucleotide and the amino acid levels. The cDNA was transferred into a eukaryotic expression vector and expressed following transfection into murine and mink lung fibroblast cell lines. High levels of enzymatically active ALP were detected, along with a 70-kDa protein reactive in immunoblot assay using a polyclonal antibody against the original crude FeALP preparation. FeALP was specifically released from intact cells by treatment with phosphoinositol-specific phospholipase-C. By Northern blot analysis, only one species of mRNA was detected using a 32P-labeled cDNA probe. These results indicate that the 2127-bp cDNA encodes a functional feline L/B/K-type ALP expressed on cell surfaces via phosphatidylinositol-glycan linkage. Despite electrophoretic comigration in two dimensions and following deglycosylation in a third dimension, FeALP failed to function as an FeLV receptor since its expression failed to provide for attachment or entry of virus into cells.", "journal": "Archives of biochemistry and biophysics", "doi": "10.1006/abbi.1995.1458", "deposited_data": "Sim", "nuccore_ids": "110350018, 947118, 2131002708, 2131002706, 2131002704, 110350018", "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7656928", "author": "Linenberger ML", "n_authors": 3, "title": "Feline leukemia virus infection downmodulates the production of growth-inhibitory activity by marrow stromal cells.", "abstract": "To determine the role of infected marrow accessory cells in the pathogenesis of viral-associated hematologic disorders, we evaluated whether feline leukemia virus (FeLV) infection alters the cytoadhesive properties of long-term marrow culture (LTMC) stromal cells, the support of stromal-associated progenitors in LTMCs, and the production of progenitor growth-promoting and -inhibiting activities by marrow stromal cells. Our previous studies demonstrated that LTMCs containing FeLV-infected stromal cells generated two- to three-fold higher numbers of total nonadherent cells and nonadherent granulocyte-macrophage progenitors (CFU-GM) compared with uninfected LTMCs. In the present studies, CFU-GM and primitive erythroid progenitors (BFU-E) bound equivalently to FeLV-infected or uninfected LTMC stromal cells in a 2-hour adherence assay. In recharge LTMC studies, the numbers of adherent CFU-GM maintained in cultures containing stromal cells infected with FeLV-A/61E were not significantly different from controls (range 84-191% of uninfected control cultures, p > 0.1); however, the percentages of adherent CFU-GM in S phase of the cell cycle were consistently increased (range 42-62% compared with controls, range 5-23%). FeLV infection had no significant effect on the cell-cycle status of the nonadherent CFU-GM in LTMCs. Agar co-culture assays revealed that multilineage colony-stimulating activity was constitutively and equivalently produced by feeder cell layers consisting of either uninfected or FeLV-infected irradiated heterogeneous LTMC stromal cells, homogeneous marrow stromal fibroblasts, or a fibroendothelial marrow stromal cell line. However, FeLV infection significantly attenuated the soluble progenitor growth-inhibitory activity associated with higher densities of these stromal cells. Assays of conditioned medium from cultures of irradiated stromal cells demonstrated that FeLV infection or hydrocortisone exposure decreased the utilization of glucose, the production of acidic metabolic products, and the constitutive production of active and latent transforming growth factor beta (TGF-beta) bioactivity and TGF-beta 2 immunoreactivity. Levels of macrophage inflammatory protein 1 alpha (MIP-1 alpha) and tumor necrosis factor alpha (TNF-alpha) were undetectable and unchanged in CM samples. Together, these observations suggest that downmodulation of TGF-alpha and/or the basal metabolic status of stromal cells may be responsible for the high basal proliferative activity of adherent CFU-GM in FeLV-infected LTMCs, and by extension, that retroviral infection in vivo could alter hematopoiesis by perturbing the progenitor growth-regulatory and -supportive function of marrow stromal cells.", "journal": "Experimental hematology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7649774", "author": "Stiles J", "n_authors": 1, "title": "Treatment of cats with ocular disease attributable to herpesvirus infection: 17 cases (1983-1993).", "abstract": "Medical records of 17 cats with ocular disease attributable to herpesvirus injection were reviewed. Herpesvirus infection was confirmed by a positive result on an immunofluorescent antibody test or by detection of dendritic corneal ulcers. Cats were 3 months to 23 years old (mean, 4.8 years). Sex or breed predilections were not evident. Vaccination history was available for 13 cats, 9 of which had been adequately vaccinated against feline viral rhinotracheitis, calici, and panleukopenia viruses. Six cats had a history of respiratory tract disease. Twelve cats were tested for FeLV, and 3 had positive results; 7 cats were tested for feline immunodeficiency virus, with 1 positive result. The most common ocular abnormality seen was conjunctivitis (13/17 cats), followed by dendritic corneal ulcers (10/17 cats). Keratitis was detected in 6 of 17 cats, and nondendritic corneal ulcers in 3 of 17 cats. Corneal sequestra were evident on initial examination or developed during the follow-up period in 4 of 17 cats. Keratoconjunctivitis sicca was diagnosed in 2 of 17 cats, and anterior uveitis was evident in 1 of 17 cats. All cats had 2 or more clinical ocular abnormalities associated with herpesvirus infection. Treatment with topically applied antiviral medications was instituted in 14 cats, including idoxuridine in 7, vidarabine in 4, and trifluridine in 3. Antibiotics were used topically in 10 cats, and atropine was used in 3 cats. Topical administration of corticosteroids was used in 2 cats. Recombinant human alpha-interferon was given orally to 3 cats in conjunction with topical administration of antiviral agents. In addition to medical treatment, 4 cats were treated surgically.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "8560729", "author": "Tribe GW", "n_authors": 2, "title": "Detection of FeLV antigen.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.137.8.200-b", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "8533260", "author": "Weijer K", "n_authors": 2, "title": "Detection of FeLV antigen.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.137.5.127-a", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "8533259", "author": "Jarrett O", "n_authors": 1, "title": "Detection of FeLV antigen.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.137.5.127-b", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7628875", "author": "Starkey CR", "n_authors": 2, "title": "Identification of differentially expressed genes in T-lymphoid malignancies in an animal model system.", "abstract": "The molecular events characterizing lymphoid malignancy have been examined in an animal model system, specifically, the retroviral induction of leukemia and lymphoma in the domestic cat following infection with feline leukemia virus (FeLV). Genes differentially expressed in FeLV-induced lymphomas were isolated using a strategy of differential hybridization. Six genes were identified which demonstrate a higher level of expression in an FeLV-induced feline thymic tumor as compared with normal thymus. The differentially expressed genes encode the feline homologues of ribosomal proteins S3a, S4, S17, and L41, elongation factor-1 alpha, and cytochrome oxidase sub-unit I. Northern-blot analysis and quantification by phosphorimaging demonstrates that these genes are expressed at levels from 1.5- to 3.1-fold higher in J5-1 thymic tumor as compared with normal thymus. Expression of the selected ribosomal protein mRNA was further examined in a series of human and feline tissues, including normal tissues, malignant tumors and cell lines. Our data reveal that elevation of the selected ribosomal protein mRNA is associated with all FeLV-induced thymic lymphomas examined. The differentially expressed ribosomal protein mRNA accumulates in a balanced manner in thymic lymphomas. By contrast, the elevation in ribosomal protein mRNA levels is not associated uniformly with hematopoietic malignancy. T-lymphoid malignancy, solid tumors or actively proliferating cells. Rather, the elevation appears to be a uniform and distinctive feature of T-cell malignancy of this particular type. The elevated expression of these genes may be causally related to the neoplastic process.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910620316", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "8525575", "author": "Merchant SR", "n_authors": 2, "title": "Systemic diseases with cutaneous manifestations.", "abstract": "The purpose of this article is to briefly discuss the following cutaneous manifestations of selected systemic diseases: poxvirus; feline leukemia virus (FeLV); feline immunodeficiency virus (FIV); herpesvirus; calcivirus; pseudorabies; plague; tularemia; toxoplasmosis; leishmania; hypothyroidism; hyperthyroidism; hyperadrenocorticism; diabetes mellitus; acromegaly; thallium poisoning; pancreatic disease; hypereosinophilic syndrome; mucopolysaccharidosis; and pansteatitis. Recognition of these cutaneous signs may help alert the clinician to the possibility of an internal disorder so that the appropriate diagnostic tests can be considered.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": "10.1016/s0195-5616(95)50136-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "8525571", "author": "Angarano DW", "n_authors": 1, "title": "Erosive and ulcerative skin disease.", "abstract": "Many causes exist for ulcerative disease of the skin and mucous membranes of cats. History, physical examination, cytology, skin biopsy, a hemogram, serum biochemical evaluation, and FeLV and feline immunodeficiency virus testing are a standard diagnostic protocol for such cases. Therapy is dependent on the underlying cause. Symptomatic therapy consisting of cleansing soaks (chlorhexidine) and systemic antibiotics (trimethoprim-sulfadiazine or amoxicillin-clavulanic acid) may be helpful to control secondary bacterial infections. If ulceration is widespread, serum leakage may result in a decreased total protein and more systemic signs. When oral ulcers are present, food and water consumption may be affected. Enteral nutrition may be helpful to sustain the cat during the diagnostic workup or until results of treatment are evident.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": "10.1016/s0195-5616(95)50132-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7483231", "author": "Webb PJ", "n_authors": 1, "title": "Detection of FeLV antigen.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.137.1.28-a", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7745680", "author": "Athas GB", "n_authors": 3, "title": "Function of a unique sequence motif in the long terminal repeat of feline leukemia virus isolated from an unusual set of naturally occurring tumors.", "abstract": "Feline leukemia virus (FeLV) proviruses have been characterized from naturally occurring non-B-cell, non-T-cell tumors occurring in the spleens of infected cats. These proviruses exhibit a unique sequence motif in the long terminal repeat (LTR), namely, a 21-bp tandem triplication beginning 25 bp downstream of the enhancer. The repeated finding of the triplication-containing LTR in non-B-cell, non-T-cell lymphomas of the spleen suggests that the unique LTR is an essential participant in the development of tumors of this particular phenotype. The nucleotide sequence of the triplication-containing LTR most closely resembles that of FeLV subgroup C. Studies performed to measure the ability of the triplication-containing LTR to modulate gene expression indicate that the 21-bp triplication provides transcriptional enhancer function to the LTR that contains it and that it substitutes at least in part for the duplication of the enhancer. The 21-bp triplication confers a bona fide enhancer function upon LTR-directed reporter gene expression; however, the possibility of a spacer function was not eliminated. The studies demonstrate further that the triplication-containing LTR acts preferentially in a cell-type-specific manner, i.e., it is 12-fold more active in K-562 cells than is an LTR lacking the triplication. A recombinant, infectious FeLV bearing the 21-bp triplication in U3 was constructed. Cells infected with the recombinant were shown to accumulate higher levels of viral RNA transcripts and virus particles in culture supernatants than did cells infected with the parental type. The triplication-containing LTR is implicated in the induction of tumors of a particular phenotype, perhaps through transcriptional regulation of the virus and/or adjacent cellular genes, in the appropriate target cell.", "journal": "Journal of virology", "doi": "10.1128/JVI.69.6.3324-3332.1995", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7660550", "author": "Kerr MG", "n_authors": 2, "title": "Detection of FeLV antigen by indirect immunofluorescence in ELISA/CITE negative cats.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.136.20.516", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7775231", "author": "Moore AS", "n_authors": 5, "title": "Efficacy of, and toxicoses associated with, oral idarubicin administration in cats with neoplasia.", "abstract": "Idarubicin, a new synthetic anthracycline analogue, was administered orally to 34 cats with spontaneous tumors. The maximum tolerated dosage was determined to be 2 mg/cat/d given for 3 consecutive days every 3 weeks. Anorexia and leukopenia were found to be dose limiting in cats receiving the drug at a higher dosage. The most common toxicoses seen at the maximum tolerated dosage were leukopenia, anorexia, and vomiting; however, development of toxicoses was not found to be associated with sex, FeLV test result, tumor type, dosage, age, or weight. Idarubicin (2 mg/cat/d for 3 days, q 3 wks) was used to treat 18 cats with lymphoma in which complete remission had been achieved by administration of other chemotherapeutic agents. Median remission duration for these cats was comparable to that reported for cats treated with other protocols. We concluded that orally administered idarubicin would be useful in the treatment of cats with lymphoma.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7712229", "author": "Hartke JR", "n_authors": 5, "title": "Acute feline leukemia virus infection causes altered energy balance and growth inhibition in weanling cats.", "abstract": "Naturally occurring retroviral infections cause progressive weight loss, immune suppression, invasion by opportunistic organisms, and eventual death. Feline leukemia virus (FeLV) inhibited growth and decreased energy intake in seven experimentally infected weanling cats compared with age- and sex-matched controls. Remarkably, changes in energy intake, energy expenditure, and weight gain occurred in the acute phase of infection prior to the systemic/productive bone marrow phase of FeLV infection. In other words, growth inhibition developed before FeLV infection was clinically detectable with use of standard enzyme-linked immunosorbent assay or fixed-cell immunofluorescence assays of circulating neutrophils and platelets. Acutely infected, previremic cats consumed 25% less energy [Day 4 postinoculation to Day 16 postinoculation (p < 0.05)] and expended 20% less energy [Day 8 postinoculation to Day 18 postinoculation (p < 0.05)] compared with control cats. Growth stunting of inoculated cats began by Day 11 postinoculation (p < 0.05) and was not corrected during the remaining 4 months of the study. Thus, experimental FeLV infection causes perturbations of metabolism and energy balance resulting in permanent growth impairment. Secondly, detrimental metabolic effects begin in the acute phase of retroviral infection, prior to the clinically detectable phase of FeLV infection.", "journal": "Journal of acquired immune deficiency syndromes and human retrovirology : official publication of the International Retrovirology Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7618258", "author": "Lutz H", "n_authors": 8, "title": "Panleukopenia-like syndrome of FeLV caused by co-infection with FeLV and feline panleukopenia virus.", "abstract": "To study the effect of interferon on feline leukemia virus (FeLV) infection, 30 specific pathogen free (SPF) cats were infected with the apathogenic FeLV A Glasgow. Unexpectedly, between 5 and 8 weeks after FeLV infection, all 19 cats with persistent FeLV infection but not the FeLV-negative cats died from a panleukopenia-like syndrome. No feline panleukopenia virus (FPLV) antigen was found in feces by latex agglutination, enzyme-linked immunosorbent assay (ELISA) or immunoelectron microscopy. No enteropathogenic bacteria were found. Histopathology revealed changes resembling those of FPLV infection such as destruction of crypts and pancytopenia of bone marrow. Neither clinical signs nor seroconversion to FPLV could be induced by transmitting intestinal extracts to two SPF cats. However, FPLV antigen was demonstrated by immunofluorescence assay in intestinal cryostat sections of diseased animals. FPLV could also be demonstrated in intestinal extracts by immunoelectron microscopy, by latex agglutination and ELISA after anti-FPLV antibodies were removed from immune-complexed FPLV by ultracentrifugation over a CsCl gradient at pH 2.0. From these experiments it was concluded that the panleukopenia-like syndrome of FeLV may not be caused by FeLV alone but at least in some cases by co-infection with FeLV and FPLV. In addition, some form of 'cooperation' between FeLV and FPLV must be postulated because neither virus alone induced symptoms.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(94)07003-p", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7618257", "author": "Nelson P", "n_authors": 8, "title": "Therapeutic effects of diethylcarbamazine and 3'-azido-3'-deoxythymidine on feline leukemia virus lymphoma formation.", "abstract": "Twenty-four specific pathogen-free kittens were infected with the Rickard strain of feline leukemia virus (FeLVR). The kittens were divided into four equal groups and were orally administered either a high dose of diethylcarbamazine (DECH, 12 mg kg-1), a low dose of diethylcarbamazine (DECL, 3 mg kg-1), 3'-azido-3'-deoxythymidine (AZT, 15 mg kg-1, b.i.d.), or a placebo (250 mg granular dextrose) daily for 10 weeks. Blood was collected at 2-week intervals for complete blood counts (CBC) and flow cytometric analysis (FACS) of peripheral blood lymphocytes (PBL). Plasma was assayed for antibodies to FeLV gp70 and for FeLV p27 antigen using ELISA assays. For FACS analysis, lymphocytes were incubated with monoclonal antibodies to feline Pan T, CD8+, CD4+, and B cell (Anti-Ig) antigens. In the placebo treated cats, FeLVR infection caused an early (2 weeks p.i.) and persistent decrease in leukocyte numbers attributable primarily to a decrease in neutrophil numbers and a secondary lesser decrease in B and CD4+ lymphocyte numbers. The DEC-treated groups showed a delayed but similar leukopenia by 4 weeks p.i. The lymphopenia in the DEC groups (primarily B cells and CD4+ cells) was reversed by 10 weeks p.i., but the neutropenia persisted. AZT treatment inhibited FeLVR-induced lymphopenia but did not prevent a reduction in neutrophil numbers. A marked p27 antigenemia that peaked at 4 weeks p.i. was noted in the placebo treated cats and in most cats (11/12) treated with either dose of DEC. However, AZT significantly inhibited the p27 antigenemia and all cats were negative for p27 antigen between 6 and 10 weeks of treatment. In general, placebo treated cats as well as DECH and DECL cats had low levels of antibody to gp70 throughout the study, suggesting FeLVR-induced immunosuppression. In contrast, significantly higher titers of anti-gp70 antibodies were seen in AZT-treated cats at 6 weeks p.i., and were maintained throughout treatment. Eighteen month survival rates provide efficacy data for AZT as well as both DEC treatment groups. While all placebo treated cats were euthanized by 52 weeks p.i. due to FeLV associated lymphomas with a mean survival time of 35.5 weeks p.i., median survival time of the AZT treated group was > or = 102 weeks p.i., while that of the DECH and DECL groups was 69.7 and 72 weeks p.i., respectively. Thus, DEC as well as AZT therapy delays the development of lymphomas associated with FeLV infection and significantly improves survival.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(94)07017-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7618252", "author": "Hofmann-Lehmann R", "n_authors": 6, "title": "Recombinant FeLV vaccine: long-term protection and effect on course and outcome of FIV infection.", "abstract": "The efficacy and the long-term protection of a recombinant feline leukemia virus (FeLV) vaccine were determined in 30 specified pathogen free cats for over 3 years. At the same time, in order to specify the effects of feline immunodeficiency virus (FIV) on the immune system, one half of the cats (n = 15) were previously infected with the Swiss isolate FIV Zurich 2. The second half of the animals (n = 15) served as non-infected controls. Eighteen (nine FIV-negative, nine FIV-positive) vaccinated and 12 (six FIV-negative, six FIV-positive) non-vaccinated cats were intraperitoneally challenged with FeLV A. Seventeen of 18 vaccinated cats were protected against persistent viremia, while ten of 12 non-vaccinated controls became infected. An increase of antibodies against FeLV SU was found in all protected cats after the challenge exposure. No difference in vaccine efficacy was found between FIV-negative and FIV-positive animals. The whole group of cats was observed for over 3 years. There were no further vaccinations during this period. CD4+ and CD8+ cell subsets, clinical outcome and time of survival of the cats were recorded. FIV-negative and FIV-positive animals were kept in two different rooms. However, FeLV-negative and FeLV viremic cats were housed together in both rooms in order to imitate a natural FeLV exposure situation. Anti-recombinant FeLV SU antibodies were measured by enzyme-linked immunosorbent assay. Although a continuous decline of antibodies was found in FeLV vaccinated cats, they remained protected against constant FeLV challenge for over 3 years. FIV infection had a stronger effect on the depression of the CD4+:CD8+ ratio than FeLV infection. Within the group of FIV-positive cats, the FeLV-vaccinated animals had significantly better survival rates as well as better clinical and laboratory parameters. FIV- and FeLV-coinfected cats showed the lowest CD4+:CD8+ ratio, mainly caused by decreased CD4+ lymphocyte counts. CD8+ lymphocytes with strong fluorescence (CD8(high)) disappeared and cells with weak fluorescence (CD8(low)) appeared instead. Prevention of coinfection by immunizing FIV-positive cats against FeLV infection improved the clinical outcome and prolonged the cat's life expectancy.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(94)07012-v", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7705953", "author": "Terry A", "n_authors": 5, "title": "Molecular analysis of tumours from feline immunodeficiency virus (FIV)-infected cats: an indirect role for FIV?", "abstract": "Five tumours, which arose in cats naturally or experimentally infected with feline immunodeficiency virus (FIV), were examined with molecular probes to establish tumour cell lineage and to screen for integrated viral sequences. Three of the tumours were classed as B-cell lymphomas on the basis of morphology, immunocytochemistry, rearrangement of immunoglobulin heavy chain genes and lack of rearrangement of T-cell receptor (TCR) beta-chain genes. Two of these B-cell tumours arose in specific pathogen-free (SPF) cats experimentally infected with FIV. One case of multi-centric lymphosarcoma came from a cat naturally infected with both FIV and feline leukaemia virus (FeLV). This tumour contained integrated FeLV proviral sequences and was judged to be of T-cell origin on the basis of TCR gene rearrangement. The fifth case was a mast cell tumour. Rearrangement of the c-myc locus was not found in any of the FIV-associated tumours but was shown to be present in a rare immunoblastic B-cell lymphoma which arose in an uninfected SPF cat. None of the FIV-associated tumours showed evidence of integrated FIV sequences by Southern blot hybridisation, despite isolation of infectious virus from in vitro cultures of tumour cells in I case. These results confirm that FIV-associated tumours can occur in the absence of FeLV and suggest that the role of FIV in lymphomagenesis is generally indirect.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910610215", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "11362398", "author": "Downing D", "n_authors": 1, "title": "HIV and pet ownership.", "abstract": null, "journal": "STEP perspective", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7884886", "author": "Pedersen L", "n_authors": 5, "title": "Chimeras of receptors for gibbon ape leukemia virus/feline leukemia virus B and amphotropic murine leukemia virus reveal different modes of receptor recognition by retrovirus.", "abstract": "Glvr1 encodes the human receptor for gibbon ape leukemia virus (GALV) and feline leukemia virus subgroup B (FeLV-B), while the related gene Glvr2 encodes the human receptor for amphotropic murine leukemia viruses (A-MLVs). The two proteins are 62% identical in their amino acid sequences and are predicted to have 10 transmembrane domains and five extracellular loops. A stretch of nine amino acids (region A) in the predicted fourth extracellular loop was previously shown to be critical for the function of Glvr1 as receptor for GALV and FeLV-B. Glvr1 and -2 show clusters of amino acid differences in several of their predicted extracellular loops, with the highest degree of divergence in region A. Chimeras were made between the two genes to further investigate the role of Glvr1 region A in defining receptor specificity for GALV and FeLV-B and to map which regions of Glvr2 control receptor specificity for A-MLVs. Region A from Glvr1 was sufficient to confer receptor specificity for GALV upon Glvr2, with the same chimera failing to act as a receptor for FeLV-B. However, introduction of additional N- or C-terminal Glvr1-encoding sequences in addition to Glvr1 region A-encoding sequences resulted in functional FeLV-B receptors. Therefore, FeLV-B is dependent on Glvr1 sequences outside region A for infectivity. The receptor specificity of Glvr2 for A-MLV could not be mapped to a single critical region; rather, N-terminal as well as C-terminal Glvr2-encoding sequences could confer specificity for A-MLV infection upon Glvr1. Surprisingly, though GALV/FeLV-B and A-MLV belong to different interference groups, some chimeras functioned as receptors for all three viruses.", "journal": "Journal of virology", "doi": "10.1128/JVI.69.4.2401-2405.1995", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7884859", "author": "Burns CC", "n_authors": 4, "title": "Mutations within a putative cysteine loop of the transmembrane protein of an attenuated immunodeficiency-inducing feline leukemia virus variant inhibit envelope protein processing.", "abstract": "A replication-defective feline leukemia virus molecular clone, 61B, has been shown to cause immunodeficiency in cats and cytopathicity in T cells after a long latency period when coinfected with a minimally pathogenic helper virus (J. Overbaugh, E. A. Hoover, J. I. Mullins, D. P. W. Burns, L. Rudensey, S. L. Quackenbush, V. Stallard, and P. R. Donahue, Virology 188:558-569, 1992). The long-latency phenotype of 61B has been mapped to four mutations in the extracellular domain of the envelope transmembrane protein, and we report here that these mutations cause a defect in envelope protein processing. Immunoprecipitation analyses demonstrated that the 61B gp85 envelope precursor was produced but that further processing to generate the surface protein (SU/gp70) and the transmembrane protein (TM/p15E) did not occur. The 61B precursor was not expressed on the cell surface and appeared to be retained in the endoplasmic reticulum or Golgi apparatus. Two of the four 61B-specific amino acid changes are located within a putative cysteine loop in a region of TM that is conserved among retroviruses. Introduction of these two amino acid changes into a replication-competent highly cytopathic virus resulted in the production of noninfectious virus that exhibited an envelope-protein-processing defect. This analysis suggests that mutations in a conserved region within a putative cysteine loop affect retroviral envelope protein maturation and viral infectivity.", "journal": "Journal of virology", "doi": "10.1128/JVI.69.4.2126-2132.1995", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7700890", "author": "Wang SW", "n_authors": 2, "title": "Induction of feline acquired immune deficiency syndrome by feline leukemia virus: alteration in response to hormones in the hypothalamic-pituitary-gonadal system.", "abstract": "Male kittens who were infected with the feline leukemia virus (FeLV) were found at various times after exposure to contain a sequence of dysfunction in their hypothalamic-pituitary-gonadal (HPG) system. To understand whether the involved endocrine glands in this system were damaged by FeLV, the hypothalamus, pituitary, and testes were tested for hormonal responsiveness in vivo and in vitro. The infected cats were administered with luteinizing hormone-releasing hormone (LHRH) and human chorionic gonadotropin (hCG). Their response to the treatment was studied, and they were then compared with untreated control cats. Normal response to LHRH for the synthesis of follicle stimulating hormone (FSH), luteinizing hormone (LH), and testosterone were found in the infected cats prior to 10 weeks of infection. After 10 weeks, the response was reduced by 25%, 38%, and 42%, respectively. Twelve weeks after infection, the response to hCG for testosterone synthesis was drastically reduced. The control cats, however, demonstrated normal prolonged biphasic patterns of response to hCG. The in vivo administration of the tropic hormones had no effect on the titer of FeLV gs antigen in the blood of the infected cats. The medial basal hypothalamus (MBH) from the control cats and cats in their 13th week of infection were cultured in vitro, with the presence of high K+ ion (60 mM). The control MBH responded to K+ ion stimulation for LHRH release. The K(+)-stimulated release of LHRH in the control MBH was 99% higher than that of the infected MBH. In contrast, the amount of unreleased LHRH in the infected MBH was 74% higher than that of the control MBH. In in vitro culture, the control pituitary gland responded markedly higher to LHRH stimulation for the release of gonadotropins (FHS and LH) than that of the infected one (140% compared with 56% for FSH, and 70% compared with 28% for LH, respectively). Whereas, the amount of unreleased FSH and LH in the infected pituitary gland were 59% and 31%, higher than that of the control gland. These results suggest that (i) the progressive development of neuroendocrine glands' dysfunction is related to viral replication time; (ii) the in vivo and in vitro responses to tropic hormones in the infected endocrine glands are drastically reduced; and (iii) this reduction in hormonal response may be caused by defective regulation of peptide hormonal secretion.", "journal": "Proceedings of the Society for Experimental Biology and Medicine. Society for Experimental Biology and Medicine (New York, N.Y.)", "doi": "10.3181/00379727-208-43869", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7492633", "author": "Shimada T", "n_authors": 10, "title": "Erythroleukemia in two cats naturally infected with feline leukemia virus in the same household.", "abstract": "Erythroleukemia was observed in two unrelated cats infected with feline leukemia virus (FeLV) from the same household. Case 1, a 1-year-old neutered male cat developed erythroleukemia (M6) after a diagnosis of myelodysplastic syndrome (MDS-Er) on the criteria of FAB classification of acute leukemias. Case 2, a 1-year-old neutered female cat, which had close contact with Case 1, also developed erythroleukemia (M6Er). In both cases, marked proliferation of erythroid progenitor cells with disproportionally large numbers of immature forms was observed in the bone marrow. In Case 1, neoplastic proliferation of myeloid cells in the bone marrow was also noted at the terminal stage. Combination chemotherapy with daunomycin was partially effective for treatment of these erythroid neoplasias, but did not induce complete remission. Southern blot analysis using exogenous FeLV-specific probes indicated the clonal origin of these hematopoietic tumor cells. Furthermore, the erythroid and myeloid tumor cells in Case 1 were shown to be derived from independent transformed clones. A variant FeLV was shown to be integrated into the tumor cells in Case 1, while a full-length FeLV was found in both cases. Because these erythroid neoplastic diseases occurred in two unrelated cats kept in the same household and these diseases are rare, they may both have been associated with the same FeLV strain.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.57.199", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7770670", "author": "Hartke JR", "n_authors": 3, "title": "Increased insensible water loss in feline retrovirus-infected cats.", "abstract": "Feline retroviruses such as feline leukemia virus (FeLV) adversely affect the regulation of many vital host systems such as the immune response, erythropoiesis, and nutrient metabolism. In this paper, we describe the disruption of an additional homeostatic mechanism-evaporative water loss-by FeLV. Viremic cats had greater evaporative water losses (24.0 +/- 1.4 gm water/kg per day) at low relative humidity levels (19% to 25% relative humidity) when compared to age- and sex-matched control cats (19.7 +/- 1.4 gm of water/kg per day [P < 0.05]). At relative humidity levels greater than 50%, viremic and control cats had similar evaporative water losses. Viremia also resulted in an elevation in the average body temperature (39.1 +/- 0.5 degrees C) compared to control cats (38.4 +/- 0.3 degrees C) (P < 0.001). However, the energy expenditure of viremic cats (17.14 +/- 1.60 kJ/kg/h) was not significantly different from the energy expenditure of control cats (17.02 +/- 2.22 kJ/kg/h). The elevated body temperature of viremic cats likely causes a greater increase in evaporative water loss at low relative humidity levels and suggests further study of water balance in retroviral infection is warranted.", "journal": "Respiration physiology", "doi": "10.1016/0034-5687(94)00106-a", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7760314", "author": "Greene RT", "n_authors": 2, "title": "Coccidioidomycosis in 48 cats: a retrospective study (1984-1993).", "abstract": "Coccidioidomycosis was diagnosed in 48 cats. Forty-one cases were identified within a period of 3 years. Coccidioides immitis was revealed by cytological or histopathological examinations, or culture in 70% of cats. The remaining 30% of cases were diagnosed by appropriate clinical signs, radiographic lesions, and serological test results. The average age of affected cats was 6.2 years with a median age of 5.0 years. Fifty-four percent (n = 26) were female and 46% (n = 22) were male. Domestic shorthaired and longhaired breeds comprised 89% (n = 41) of affected cats. Sixty-seven percent of cases were diagnosed during the 6-month period of December through May. Cats infected with C immitis were presented for evaluation of dermatologic (56%), respiratory (25%), musculoskeletal (19%), and neurological or ophthalmologic signs (19%). Fever, inappetence, and weight loss were present in 44% of the cats. Duration of clinical signs before diagnosis was less than 4 weeks in 85% (n = 42) of cats, with an average of 3.8 weeks and a median of 2 weeks. Agar gel immunodiffusion tests were positive in all 39 cats tested at sometime during the course of their disease. Hyperproteinemia (greater than 7.9 g/dL) was present in 52% (10/23) of cases. The majority of cats (n = 39) were negative for feline leukemia virus. Antibodies to feline immunodeficiency virus were absent in the 19 cats tested. Ketoconazole was the most common antifungal agent used to treat cats with coccidioidomycosis. Duration of treatment ranged from less than 1 week to 43 months. Thirty-two cats are currently asymptomatic, with or without treatment. Eleven cats died or were euthanized.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "Journal of veterinary internal medicine", "doi": "10.1111/j.1939-1676.1995.tb03277.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7663052", "author": "Linenberger ML", "n_authors": 2, "title": "Haematological disorders associated with feline retrovirus infections.", "abstract": "Feline oncornavirus and lentivirus infections have provided useful models to characterize the virus and host cell factors involved in a variety of marrow suppressive disorders and haematological malignancies. Exciting recent progress has been made in the characterization of the viral genotypic features involved in FeLV-associated diseases. Molecular studies have clearly defined the causal role of variant FeLV env gene determinants in two disorders: the T-lymphocyte cytopathicity and the clinical acute immunosuppression induced by the FeLV-FAIDS variant and the pure red cell aplasia induced by FeLV-C/Sarma. Variant or enFeLV env sequences also appear to play a role in FeLV-associated lymphomas. Additional studies are required to determine the host cell processes that are perturbed by these variant env gene products. In the case of the FeLV-FAIDS variant, the aberrant env gene products appear to impair superinfection interference, resulting in accumulation of unintegrated viral DNA and cell death. In other cases it is likely that the viral env proteins interact with host products that are important in cell viability and/or proliferation. Understanding of these mechanisms will therefore provide insights to factors involved in normal lymphohaematopoiesis. Similarly, studies of FeLV-induced haematological neoplasms should reveal recombination or rearrangement events involving as yet unidentified host gene sequences that encode products involved in normal cell growth regulation. These sequences may include novel protoncogenes or sequences homologous to genes implicated in human haematological malignancies. The haematological consequences of FIV are quite similar to those associated with HIV. As with HIV, FIV does not appear to directly infect myeloid or erythroid precursors, and the mechanisms of marrow suppression likely involve virus, viral antigen, and/or infected accessory cells in the marrow microenvironment. Studies using in vitro experimental models are required to define the effects of each of these microenvironmental elements on haematopoietic progenitors. As little is known about the molecular mechanisms of FIV pathogenesis, additional studies of disease-inducing FIV strains are needed to identify the genotypic features that correlate with virulent phenotypic features. Finally, experimental FIV infection in cats provides the opportunity to correlate in vivo virological and haematological changes with in vitro observations in a large animal model that closely mimics HIV infection in man.", "journal": "Bailliere's clinical haematology", "doi": "10.1016/s0950-3536(05)80233-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7815521", "author": "Meyer MK", "n_authors": 3, "title": "Identification of a new viral protein containing CAp30 and NCp10 sequences in murine and feline leukemia retroviruses.", "abstract": "Because Pr65gag is in part located in the nucleus and contains a putative bipartite nuclear targeting signal, we investigated the cellular location and structure of P55gag, a gag-encoded polyprotein known to lack the nucleocapsid (NC) protein NCp10. P55gag was found to be restricted to the cytoplasm of Moloney murine leukemia virus-infected cells. Of interest, P55gag was produced in cells infected by a viral protease deletion mutant and by a recombinant murine sarcoma virus known to lack the protease gene. Surprisingly, our structural and immunological studies indicated that P55gag also lacks carboxy-terminal residues of CAp30. During the course of studying P55gag, we detected a new viral protein within purified virus particles that contained NCp10 tryptic peptide sequences and a CAp30 tryptic peptide lacking in P55gag. This viral protein, which we have named nucleocapsid-related protein (NCRP), also contained antigenic epitopes present in CAp30 and NCp10. P55gag- and NCRP-like proteins were also observed in AKV murine leukemia virus and feline leukemia virus systems. The precise site of cleavage within Pr65gag that produces P55gag and NCRP is unknown but lies upstream of the CAp30-NCp10 junction within the carboxy-terminal domain of CAp30. The existence of a form of NCp10 containing carboxy-terminal CAp30 sequences raises interesting possibilities about its functional role in genomic RNA packaging and/or viral RNA dimerization.", "journal": "Journal of virology", "doi": "10.1128/JVI.69.2.1353-1358.1995", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7786279", "author": "Reinacher M", "n_authors": 4, "title": "[The significance of FeLV infection for diseases in necropsied cats].", "abstract": "Persistent FeLV infection was demonstrated in more than 3000 necropsied cats by an immunohistological method. The findings were associated with the diagnoses established by means of post-mortem examination, histopathological, bacteriological, virological, and parasitological investigations. Statistically significant differences between FeLV-positive and FeLV-negative cats in the relative risk for certain lesions could be demonstrated for the first time. As a consequence, the importance of FeLV infection for the development of certain lesions in cats is to be seen under new aspects for some diagnoses. The relative risk for development of anemia, e.g., is only slightly increased in FeLV-positive animals whereas the relative risk for focal myocardial necrosis and coccidiosis is elevated tremendously in these cats. The relative risk for some lesions and diagnoses is much higher in FeLV-negative cats than in FeLV-positive animals. This is true, e.g., for myocardiopathy and hemorrhagic cystitis.", "journal": "Berliner und Munchener tierarztliche Wochenschrift", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7756412", "author": "Lin JA", "n_authors": 9, "title": "Seroepidemiological survey of feline retrovirus infections in cats in Taiwan in 1993 and 1994.", "abstract": "In order to investigate the prevalence of infections with three feline retroviruses feline immunodeficiency virus (FIV), feline leukemia virus (FeLV) and feline syncytial virus (FSV) in Taiwan, we collected a total of 75 blood samples from cats from veterinary hospitals, a breeding cattery and a homeless shelter in 1993 and 1994. We examined the presences of anti-FIV and FSV antibodies and FeLV-p27 antigen in these samples by the indirect immunofluorescence and/or enzyme-linked immunosorbent assays. All of the serum samples positive for FIV were obtained from homeless cats and the overall FIV positive rate was 4%. The overall positive rates of FSV and FeLV were 28% and 1.3%, respectively. From these results, together with previous seroepidemiological surveys by others, it was revealed that the prevalence of FIV and FeLV infections appeared to be lower in Taiwan than in the United States or Japan. In contrast, the prevalence of FSV infection in Taiwan was as high as that in Japan.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.57.161", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7831823", "author": "Rohn JL", "n_authors": 2, "title": "In vivo selection of long terminal repeat alterations in feline leukemia virus-induced thymic lymphomas.", "abstract": "To determine what genetic changes are selected in the enhancer sequences of the feline leukemia virus (FeLV) long terminal repeat in cats that develop T cell tumors, we cloned proviral U3 sequences in cats that died with thymic lymphoma following infection with molecularly cloned FeLV. Analysis of the U3 enhancer region revealed single base changes, including point mutations in the core and FLV-1 sequences. Additionally, in clones from two of four cat tumors, portions of the enhancer including Lvb and core were duplicated with respect to the single enhancer unit of the inoculating virus. In contrast, a PCR survey of necropsy DNA samples derived from five cats that did not develop tumors revealed that all retained the single enhancer unit of the infecting virus. These results demonstrate that viruses with duplicated enhancers can be generated and selected after only a single passage in cats, and furthermore, that such viruses may be particularly selected in tumors.", "journal": "Virology", "doi": "10.1016/s0042-6822(95)80085-9", "deposited_data": "Sim", "nuccore_ids": "538384, 538383, 538382, 538381, 417970, 417969, 417968, 417967, 417966, 417965, 417945, 417944, 417943, 417942, 417941, 417940, 417932, 417931, 417929, 417927, 417925, 417899, 417898, 417897, 417895, 417894, 417881, 417880, 417879, 417878", "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "8828142", "author": "Roy-Burman P", "n_authors": 1, "title": "Endogenous env elements: partners in generation of pathogenic feline leukemia viruses.", "abstract": "Feline leukemia viruses (FeLVs), which are replication-competent oncoretroviruses of the domestic cat species, are contagiously transmitted in natural environments. They are capable of inducing either acute antiproliferative disease or, after prolonged latency, lymphoid malignancies in this animal population. Current knowledge of the recombinational events between infectious FeLV and noninfectious endogenously inherited FeLV-like elements is reviewed, and the potential role of the derived recombinant viruses in pathogenesis is discussed. Major observations made are as follows: (1) Up to three fourths of the exogenous FeLV envelope glycoprotein (SU), beginning from the N-terminal end, can be replaced by sequences from an endogenous FeLV to produce biologically active chimeric FeLVs. The in vitro replication efficiency or cell tropism of the recombinants appears to be influenced by the amount of SU sequences replaced by the endogenous partner, as well as by the locus of origin of the endogenous sequences. (2) Generation of FeLV recombinants in tissue culture cells corresponds closely to the findings from natural tumors. There is direct evidence, based on molecular genetic analysis, for the prevalence of recombinant proviruses in naturally arising FeLV-induced lymphomas. (3) Certain recombinants harboring an altered primary neutralizing epitope in the middle of SU corresponding to the endogenous FeLV sequence can evade immunity developed against common FeLV infection. In several other recombinants, the epitope sequence is found to be frequently mutated during the process of recombination. (4) FeLV variants with altered epitope, although they may not be efficient in replication in vivo, apparently are capable of causing focal infection in target organs. Evidence is also presented that when coinfected with an exogenous FeLV, the epitope sequence in the variants is reverted to the exogenous type, providing an explanation why this sequence is found to be conserved in all natural isolates of FeLV. (5) A prototype chimeric polyprotein containing most of the SU from the endogenous source is abnormally processed and becomes trapped in the endoplasmic reticulum. A functional consequence of such trapping is interference with specific FeLV infection. (6) Some recombinants, while only poorly replicating in the host, may have the ability to infect target erythroid progenitor cells for the induction of strong cytopathic effect. (7) Some other recombinants appear to potentiate lymphomagenesis by exogenous FeLV and others to acquire properties to infect CNS endothelial cells, an event that could potentially be related to FeLV-induced neuropathogenicity. (8) Of multiple recombinant viruses, a specific recombinant species was found to occur in each of the three cats examined in which lymphoma was experimentally induced, and it was exclusively seen in one of these cats. This recombinant FeLV may potentially be a candidate for strong leukemogenic function. In addition to commonly encountered virus envelope changes, another prominent viral factor involved in tumorigenesis is mutated FeLV transcription regulatory sequences, most frequently with enhancer duplication or triplication. Although only a limited amount of information is available in the area of insertional mutagenesis in FeLV neoplastic disease, activation of certain key nuclear transcription factor genes has been documented.", "journal": "Virus genes", "doi": "10.1007/BF01728655", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "8666525", "author": "Pumpens P", "n_authors": 4, "title": "Hepatitis B virus core particles as epitope carriers.", "abstract": "HBV core (HBc) particle is one of the most intensively studied particulate carriers for the insertion of foreign peptide sequences. Recombinant HBc protein expressed from the cloned gene undergoes the correct folding in a large variety of bacterial, yeast, insect and mammalian cells. Unique assembly properties and shape of 30/34-nm HBc particles allow substantial insertions into their primary structure without loss of their capsid-forming ability. N- and C-terminal regions, as well as the immunodominant loop in the middle of the molecule are widely accepted as targets for the introduction of foreign epitopes, ensuring retention and even enhancement of the original immunological activity of inserted sequences. Special sets of display vectors have been constructed on the basis of the cloned HBc gene. Epitope sequences of viral (BLV, FeLV, FMDV, HBV, HCV, HIV-1, HRV2, MCMV, PV-1, SIV) and nonviral (human chorionic gonadotropin) origin have been studied as model display moieties.", "journal": "Intervirology", "doi": "10.1159/000150415", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7777836", "author": "Schiller I", "n_authors": 3, "title": "[Malignant melanoma in two cats].", "abstract": "Malignant melanomas with extensive metastasis in various organs were diagnosed in a 8-year-old European shorthair cat and a 10-year-old Persian cat. The primary tumor in the European shorthair cat was located within the eye. The clinical progress, gross pathology and histology are outlined. The possibility of an increase of melanomas in combination with FIV- or FeLV-infections is discussed.", "journal": "Schweizer Archiv fur Tierheilkunde", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "9008333", "author": "Jackson ML", "n_authors": 3, "title": "Sequence analysis of the putative viral enhancer in tissues from 33 cats with various feline leukemia virus-related diseases.", "abstract": "Diseases resulting from infection by feline leukemia virus (FeLV) and several other retroviruses relate in part, to non-coding regulatory sequences within the viral long terminal repeat (LTR). Both enhancer repeats and mutations within the LTR have been implicated in FeLV related disease. In order to investigate the relationship between nucleotide sequence of the FeLV LTR and disease, tissues from 33 cats with different types of degenerative and proliferative FeLV-related disease were studied. An FeLV LTR region containing the putative transcriptional enhancer unit was amplified by polymerase chain reaction (PCR) from FeLV-infected tissues. Phylogenetic analysis of FeLV 3'unique (U3) sequences revealed only one meaningful grouping which contained 4 of the 5 antigen-negative lymphosarcomas (LSAs). No sequence duplications were found in any of the 33 FeLV U3 regions. Point mutations relative to the corresponding region of FeLV-A/Glasgow, were identified at 102 positions; 68 of these were accounted for by mutations at 5 locations. Only 1 point mutation was found within the leukemia virus b-simian virus 40-like core (LVb-CORE) site. However, the nuclear factor 1 (NF1) site contained 11 mutations, and the FeLV-specific (FLV-1) site contained 26 mutations. Most of the remaining mutations were upstream of the LVB site between glucocorticoid response element (GRE) and FLV-1. The 10 LSAs, particularly the 5 antigen-negative LSAs, deviated least from the corresponding sequence for FeLV-A/Glasgow. Conclusions were that the spectrum of neoplastic and non-neoplastic FeLV-related diseases investigated in this study, developed in the presence of FeLVs containing the single enhancer unit. The significance of the point mutations is unknown, however, those occurring with high frequency and within nuclear protein binding should be first to be investigated in functional studies.", "journal": "Veterinary microbiology", "doi": "10.1016/s0378-1135(96)01228-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8946923", "author": "Rohn JL", "n_authors": 5, "title": "Viral genetic variation, AIDS, and the multistep nature of carcinogenesis: the feline leukemia virus model.", "abstract": "Feline leukemia virus (FeLV) infection in cats serves as a valuable animal model system for understanding the mechanisms of human diseases such as cancer and immunodeficiency. We have used experimental infection with molecularly cloned viruses to isolate and characterize novel FeLV variants that evolved in vivo and that were associated with the development of thymic lymphoma. One variant, FeLV-81T, contained a mutated envelope gene that conferred cytopathicity, enhanced replication rate, and syncytium induction in feline T cells, and is reminiscent of immunodeficiency-inducing strains of FeLV. Another variant transduced a portion of the feline Notch2 gene, which was expressed as a novel truncated protein in the cell nucleus and which we believe functioned as an oncogene in the development of T cell malignancy. Understanding how FeLV variants that either stimulate or destroy lymphocytes evolve and interrelate during disease progression will help elucidate the mechanisms of retroviral pathogenicity.", "journal": "Leukemia", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8941325", "author": "Kabát P", "n_authors": 4, "title": "Human endogenous retrovirus HC2 is a new member of the S71 retroviral subgroup with a full-length pol gene.", "abstract": "We have isolated and characterized a new human endogenous provirus, which is closely related to the human retrovirus S71, but unlike S71 has a full-length pol gene. Two degenerate oligonucleotide primers based on highly conserved motifs within the active sites of two retroviral proteins (the protease and reverse transcriptase) were designed and used for PCR. An amplified product of 847 bp in length, which showed significant homology to protease and reverse transcriptase of several retroviruses, was used for high stringency hybridization with a human genomic library. The MuLV-related endogenous retrovirus sequence, designated HC2, was isolated and completely sequenced. HC2 is a provirus with complete gag and pol genes and a 3' LTR; the 5' LTR and env gene are missing. The gag and pol genes appear complete, since they contain sequences homologous to the matrix protein, capsid protein, and nucleocapsid protein of gag and to the protease, reverse transcriptase, tether, RNase H, and integrase of pol. Phylogenetic analysis suggests that although HC2 and S71 are MuLV-related retroviruses, their characters are quite distinct, being placed outside of a clade containing most of the previously characterized MuLV-related retroviruses such as GaLV, FeLV, BaEV, and SSV/SSAV.", "journal": "Virology", "doi": "10.1006/viro.1996.0630", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "9014292", "author": "Willemse MJ", "n_authors": 4, "title": "Vaccination against feline leukaemia using a new feline herpesvirus type 1 vector.", "abstract": "A recombinant feline herpesvirus type 1 (FHV-1) was constructed expressing the envelope glycoprotein gene from feline leukaemia virus (FeLV). The expression cassette containing the long terminal repeat promoter from Rous sarcoma virus was stably integrated at the locus downstream of the gC homologue in FHV-1. Oronasal vaccination with recombinant FHV-1 engendered significant protection against challenge with the homologous FelV-A/Glasgow-1 isolate. Three of four vaccinated cats did not become viraemic for FeLV and developed serum neutralizing antibodies while five of six controls became persistently infected after challenge. However, latent FeLV was detected at 12 weeks after challenge in bone marrow cultures of all animals except one. The potential of this new vector to protect against FeLV was compared with previous reports using live recombinant vaccines.", "journal": "Vaccine", "doi": "10.1016/s0264-410x(96)00108-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8938851", "author": "Hoffmann-Fezer G", "n_authors": 8, "title": "Comparison of T-cell subpopulations in cats naturally infected with feline leukaemia virus or feline immunodeficiency virus.", "abstract": "T-cell subsets were studied by flow cytometry in 58 feline leukaemia virus (FeLV)-positive cats with naturally acquired FeLV infection to determine whether the changes in CD4+ or CD8+ T cell populations differed from those observed in 55 feline immunodeficiency virus (FIV)-positive cats with naturally acquired FIV infection. The sole criterion for inclusion into the study was seropositivity. Mean (SD) CD4+ T cell values of FeLV positive cats were decreased to 31.1 (8.0) per cent and their CD8+ T cell values were increased to 22.8 (6.3) per cent in comparison with uninfected control cats (37.9 [9.5] per cent CD4+; 15.2 [6.3] per cent CD8+). The CD4+/CD8+ ratio was reduced to 1.5 (0.7), compared with 3.0 (1.5) in 39 FeLV-and FIV-negative control cats. Differences from control values were significant, but there was no significant difference between CD4+ and CD8+ lymphocytes of FeLV-versus FIV-infected cats. These findings indicate that FeLV and FIV have similar effects on T lymphocyte subsets. Both retrovirus infections can induce immunodeficiency, both viruses infect a broad range of lymphohaemopoietic cells, despite having different primary target cells, and can induce the killing of lymphocytic cells in vitro. It is concluded that a decreased CD4+/CD8+ ratio is not restricted to FIV infections but may also occur in FeLV infection.", "journal": "Research in veterinary science", "doi": "10.1016/s0034-5288(96)90067-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8892932", "author": "Rohn JL", "n_authors": 4, "title": "Transduction of Notch2 in feline leukemia virus-induced thymic lymphoma.", "abstract": "Feline leukemia virus (FeLV) is thought to induce neoplastic diseases in infected cats by a variety of mechanisms, including the transduction of host proto-oncogenes. While FeLV recombinants that encode cellular sequences have been isolated from tumors of naturally infected animals, the acquisition of an unrelated host gene has never been documented in an experimental FeLV infection. We isolated recombinant FeLV proviruses encoding feline Notch2 sequences from thymic lymphoma DNA of two cats inoculated with the molecularly cloned virus FeLV-61E. Four recombinant genomes were identified, three in one cat and one in the other. Each had similar but distinct transduction junctions, and in all cases, the insertions replaced most of the envelope gene with a region of Notch2 that included the intracellular ankyrin repeat functional domain. The product of the FeLV/Notch2 recombinant provirus was a novel, truncated 65- to 70-kD Notch2 protein that was targeted to the cell nucleus. This virally encoded Notch2 protein, which resembles previously constructed, constitutively activated forms of Notch, was apparently expressed from a subgenomic transcript spliced at the normal envelope donor and acceptor sequences. The data reported here implicate a nuclear, activated Notch2 protein in FeLV-induced leukemogenesis.", "journal": "Journal of virology", "doi": "10.1128/JVI.70.11.8071-8080.1996", "deposited_data": "Sim", "nuccore_ids": "1622788, 1622786, 1622784, 1622782", "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8876138", "author": "Paoletti E", "n_authors": 1, "title": "Applications of pox virus vectors to vaccination: an update.", "abstract": "Recombinant pox viruses have been generated for vaccination against heterologous pathogens. Amongst these, the following are notable examples. (i) The engineering of the Copenhagen strain of vaccinia virus to express the rabies virus glycoprotein. When applied in baits, this recombinant has been shown to vaccinate the red fox in Europe and raccoons in the United States, stemming the spread of rabies virus infection in the wild. (ii) A fowlpox-based recombinant expressing the Newcastle disease virus fusion and hemagglutinin glycoproteins has been shown to protect commercial broiler chickens for their lifetime when the vaccine was administered at 1 day of age, even in the presence of maternal immunity against either the Newcastle disease virus or the pox vector. (iii) Recombinants of canarypox virus, which is restricted for replication to avian species, have provided protection against rabies virus challenge in cats and dogs, against canine distemper virus, feline leukemia virus, and equine influenza virus disease. In humans, canarypox virus-based recombinants expressing antigens from rabies virus, Japanese encephalitis virus, and HIV have been shown to be safe and immunogenic. (iv) A highly attenuated vaccinia derivative, NYVAC, has been engineered to express antigens from both animal and human pathogens. Safety and immunogenicity of NYVAC-based recombinants expressing the rabies virus glycoprotein, a polyprotein from Japanese encephalitis virus, and seven antigens from Plasmodium falciparum have been demonstrated to be safe and immunogenic in early human vaccine studies.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.93.21.11349", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8870719", "author": null, "n_authors": 0, "title": "FeLV, FIV testing recommendations issued.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8800258", "author": "Flatland B", "n_authors": 3, "title": "Clinical and serologic evaluation of cats with cryptococcosis.", "abstract": "To evaluate the long-term clinical outcomes and serologic changes in cryptococcal antigen and antibody titers in cats with confirmed Cryptococcus neoformans infection. Prospective case series. 47 cats with cryptococcosis. Cats included in this study were determined to have cryptococcosis on the basis of identification of C neoformans on histologic or cytologic examination, isolation of C neoformans in culture, or positive serologic test results for cryptococcal antigens. Information concerning the signalment, history, physical examination findings, FeLV and feline immunodeficiency virus status, serologic testing, treatment, and outcome for each cat was requested on a survey form. Follow-up measurements of serum cryptococcal antigen and antibody titers were requested for all surviving cats. Signalment and clinical signs of cats with cryptococcosis reported here were consistent with previous reports. Treatment consisted primarily of azole antifungal drugs. All cats were seronegative for cryptococcal antibody titers, whether tested initially or at follow-up examination. All but 1 cat tested were seropositive for cryptococcal antigens when initially tested. Cats with and without clinical signs of C neoformans infection were seropositive for cryptococcal antigens months to years after initial diagnosis of cryptococcosis. The results of this study indicate that serum titers to cryptococcal antigens in cats can persist with or without clinical signs for months to years after an initial diagnosis of cryptococcosis is made. Repeated evaluation of serum cryptococcal antigen titers is advised during the treatment of cats to monitor progress, evaluate prognosis, and guide cessation of treatment.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8941981", "author": "Kitchen LW", "n_authors": 1, "title": "Diethylcarbamazine treatment of feline leukemia virus-infected cats.", "abstract": null, "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/0165-2427(95)05522-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8878603", "author": "Mathes LE", "n_authors": 3, "title": "Evidence that high-dosage zidovudine at time of retrovirus exposure reduces antiviral efficacy.", "abstract": "The antiviral efficacy of prophylactic 3'-azido-3'-deoxythymidine (AZT) therapy administered by continuous infusion or intermittent injection was compared in pediatric cats infected with feline leukemia virus. A 4-week treatment regimen of AZT was initiated at -48, 8, or 96 h postinfection (p.i.). For AZT therapy begun at -48 h p.i., significant efficacy was attained when therapy was given by continuous infusion but not by intermittent injection. However, when AZT therapy was delayed until 96 h p.i., both continuous infusion and intermittent injection gave complete protection. The results suggest that intermittent AZT administration is less efficacious than continuous infusion. Higher peak AZT concentrations in plasma associated with intermittent injection compared with those associated with continuous infusion may be immunotoxic, thus reducing the drug-induced vaccine effect. Furthermore, AZT toxicity seemed to be restricted to a window of sensitivity close to the time of virus challenge because delaying the start of AZT therapy until 96 h p.i. was highly efficacious, regardless of the method of administration.", "journal": "Antimicrobial agents and chemotherapy", "doi": "10.1128/AAC.40.9.2183", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8877134", "author": "Hofmann-Lehmann R", "n_authors": 8, "title": "Prevalence of antibodies to feline parvovirus, calicivirus, herpesvirus, coronavirus, and immunodeficiency virus and of feline leukemia virus antigen and the interrelationship of these viral infections in free-ranging lions in east Africa.", "abstract": "While viral infections and their impact are well studied in domestic cats, only limited information is available on their occurrence in free-ranging lions. The goals of the present study were (i) to investigate the prevalence of antibodies to feline calicivirus (FCV), herpesvirus (FHV), coronavirus (FCoV), parvovirus (FPV), and immunodeficiency virus (FIV) and of feline leukemia virus (FeLV) antigen in 311 serum samples collected between 1984 and 1991 from lions inhabiting Tanzania's national parks and (ii) to evaluate the possible biological importance and the interrelationship of these viral infections. Antibodies to FCV, never reported previously in free-ranging lions, were detected in 70% of the sera. In addition, a much higher prevalence of antibodies to FCoV (57%) was found than was previously reported in Etosha National Park and Kruger National Park. Titers ranged from 25 to 400. FeLV antigen was not detectable in any of the serum samples. FCoV, FCV, FHV, and FIV were endemic in the Serengeti, while a transient elevation of FPV titers pointed to an outbreak of FPV infection between 1985 and 1987. Antibody titers to FPV and FCV were highly prevalent in the Serengeti (FPV, 75%; FCV, 67%) but not in Ngorongoro Crater (FPV, 27%; FCV, 2%). These differences could be explained by the different habitats and biological histories of the two populations and by the well-documented absence of immigration of lions from the Serengeti plains into Ngorongoro Crater after 1965. These observations indicate that, although the pathological potential of these viral infections seemed not to be very high in free-ranging lions, relocation of seropositive animals by humans to seronegative lion populations must be considered very carefully.", "journal": "Clinical and diagnostic laboratory immunology", "doi": "10.1128/cdli.3.5.554-562.1996", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8875354", "author": "Babyak SD", "n_authors": 4, "title": "Evaluation of a saliva test kit for feline leukemia virus antigen.", "abstract": "An enzyme-linked immunosorbent assay (ELISA) test kit for the detection of feline leukemia virus (FeLV) antigen in saliva was evaluated in 150 cats. Saliva and blood samples from all cats were tested for FeLV using the saliva ELISA kit and a plasma ELISA kit, respectively. These results were compared with indirect immunofluorescent antibody (IFA) testing of blood smears also obtained from each cat. The proportion of cats that tested positive were 10%, 7%, and 8% for each test, respectively. Using the IFA test as the gold standard, the saliva FeLV test had a sensitivity of 91.7% and specificity of 97.1%, while the plasma ELISA test had a sensitivity of 91.7% and specificity of 100%.", "journal": "Journal of the American Animal Hospital Association", "doi": "10.5326/15473317-32-5-397", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8875352", "author": "Davies C", "n_authors": 2, "title": "Deep mycotic infections in cats.", "abstract": "A review of deep mycotic infections assessed incidence, signalment, clinical presentation, and outcome in 571 feline cases. Pertinent findings included a predisposition in young, male cats for Sporothrix schenckii and Blastomyces dermatitidis. There was an increased incidence of feline leukemia virus infection in cases with histoplasmosis and of feline panleukopenia virus infection in cases with either aspergillosis or mucoralosis. Few other predisposing conditions were identified. Cryptococcosis, coccidioidomycosis, and sporotrichosis had better prognoses for recovery. Blastomycosis, histoplasmosis, and aspergillosis commonly were disseminated infections and were associated with guarded-to-poor prognoses.", "journal": "Journal of the American Animal Hospital Association", "doi": "10.5326/15473317-32-5-380", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8863390", "author": "Grindem CB", "n_authors": 1, "title": "Blood cell markers.", "abstract": "Cytochemistry and immunocytochemistry are important adjunctive technologies to the morphologic characterization of blood cells and hematopoietic neoplasms. Although cytochemistry is briefly discussed, the emphasis of this article is on the clinical application of flow cytometry and leukocyte monoclonal antibodies in veterinary medicine. Classification and significance of immunophenotyping in canine and feline lymphomas and immunodeficiencies such as feline immunodeficiency virus and feline leukemia virus are discussed.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": "10.1016/s0195-5616(96)50055-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8806534", "author": "Quackenbush SL", "n_authors": 4, "title": "Analysis of FeLV-FAIDS provirus burden and productive infection in lymphocyte subsets in vivo.", "abstract": "To help elucidate the immunopathogenesis of feline leukemia virus (FeLV)-induced immunodeficiency we studied the tropism of viruses derived from the FeLV-FAIDS isolate for lymphocyte subpopulations in cats. FeLV-FAIDS is composed of a replication-competent virus typical of subgroup A FeLV (prototype, clone 61E) and a family of replication-defective but immunopathogenic variant viruses (prototype, clone 61C). We sorted CD4+, CD8+, and IgG+ lymphocytes to > or = 97% purity and analyzed viral load in each cell population via genome-specific semiquantitative PCR. Both the 61E and 61C viruses were tropic for CD4+ and CD8+ T cells as well as IgG+ B lymphocytes in blood and lymph node. High provirus burden were established for both virus genomes-ranging from 0.3 to > 2 copies/cell. To identify the fraction of circulating cells which expressed viral antigen in vivo, we developed a flow cytometric method to simultaneously label blood leukocytes for surface immunophenotype and intracytoplasmic FeLV CA (p27 Gag). These experiments established that 20 to 60% of CD4+, CD8+, and IgG+ lymphocytes and > 85% of monocytes and granulocytes expressed FeLV p27 intracellularly. Thus the in vivo target cells for FeLV-FAIDS infection are manifold and include CD4+ and CD8+ T cells, B cells, and myeloid cells.", "journal": "Virology", "doi": "10.1006/viro.1996.0449", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8790539", "author": "Troy GC", "n_authors": 3, "title": "Proficiency testing of selected antigen and antibody tests for use in dogs and cats.", "abstract": "To determine the correlation of seroimmunologic test results between reference and nonreference laboratories. Retrospective data analysis. Serum samples obtained from naturally infected dogs and cats were distributed to reference and nonreference laboratories for seroimmunologic testing. Correlation of test results was evaluated by use of nonparametric analysis. Correlation coefficients were high between laboratory groups for samples tested for feline immunodeficiency virus antibodies, FeLV antigen, and toxoplasmosis antibodies in cats. Results for feline immunodeficiency virus antibody tests from reference laboratories were more likely to be positive than results from nonreference laboratories. Test results for feline infectious peritonitis antibodies, antinuclear antibodies, and Borrelia antibodies in cats were not significant. Coefficient correlations were significant for results of heart-worm antigen, Brucella antibodies, Toxoplasma antibodies, antinuclear antibodies, and rheumatoid factor in dogs. Results for Borrelia antibodies were not correlated between laboratory groups. Results were highly correlated between reference and nonreference laboratories for 8 of 14 seroimmunologic tests. Seroimmunologic tests for use in cats were less correlated as a group than those for use in dogs. Poor correlation of results between laboratories was attributed to variations in control agents, antigens, reagents, technical expertise, and cutoff values and end-point titers used for diagnosis.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8756876", "author": "Ellis JA", "n_authors": 7, "title": "Use of immunohistochemistry and polymerase chain reaction for detection of oncornaviruses in formalin-fixed, paraffin-embedded fibrosarcomas from cats.", "abstract": "To determine whether there was intralesional infection or expression of FeLV or feline sarcoma virus in suspected vaccine-associated fibrosarcomas in cats. Prospective case series. 130 suspected vaccine-associated fibrosarcomas from cats and 1 multicentric fibrosarcoma from 1 cat. Excisional biopsy specimens were fixed in formalin and embedded in paraffin. Expression of FeLV antigen was assessed, using a polyclonal goat anti-FeLV glycoprotein 70 (gp 70) serum and an avidinbiotin immunoperoxidase staining technique. The FeLV genome was detected with a polymerase chain reaction (PCR), using primers targeted to a conserved sequence in the untranslated region of the long terminal repeat (LTR) of the FeLV. FeLV gp 70 and LTR sequence were detected in a multicentric fibrosarcoma. All 130 of the suspected vaccine-associated fibrosarcomas were FeLV gp 70 negative on the basis of immunohistochemical test results: 100 fibrosarcomas also were examined by use of PCR and were negative for FeLV LTR region. Exogenous retroviruses, FeLV, and feline sarcoma virus were not detected in these suspected vaccine-associated fibrosarcomas, using immunohistochemistry and PCR. Additional testing will be required to determine the nature of genomic alterations that are involved in the oncogenesis of vaccine-associated fibrosarcomas in cats.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8942210", "author": "Barr MC", "n_authors": 1, "title": "FIV, FeLV, and FIPV: interpretation and misinterpretation of serological test results.", "abstract": "Serological testing is a common method of diagnosis of felina viral infections, including feline immunodeficiency virus (FIV), feline leukemia virus (FeLV), and feline infectious peritonitis virus (FIPV). Infections with these viruses can be difficult to diagnose by clinical signs alone and are sometimes clinically inapparent for months after initial exposure. Serological testing to confirm a tentative diagnosis or as a screening tool for infection can be invaluable. However, serological tests must be used only with a thorough understanding of the mechanisms and abilities of the tests, and with recognition of their potential inadequacies and misinterpretations. This report summarizes the assays available for FIV, FeLV, and FIPV, and discusses merits and pitfalls associated with each test.", "journal": "Seminars in veterinary medicine and surgery (small animal)", "doi": "10.1016/s1096-2867(96)80026-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8879373", "author": "Glimelius B", "n_authors": 8, "title": "Chemotherapy improves survival and quality of life in advanced pancreatic and biliary cancer.", "abstract": "In certain patients with pancreatic and biliary cancer, chemotherapy may relieve tumour-related symptoms, improve quality of life and possibly prolong survival. The extent of these improvements is not completely known in spite of the extensive use of this treatment modality. The aim of this study was to estimate any gain in the quantity and quality of life produced by chemotherapy in patients with pancreatic and biliary cancer. Between January 1991 and February 1995, 90 eligible patients with pancreatic or biliary cancer were randomized to either chemotherapy in addition to best supportive care or to best supportive care. Chemotherapy was allowed in the latter group if the supportive measures did not lead to palliation. Chemotherapy was either sequential 5-fluorouracil/leucovorin combined with etoposide (FELv) or, in elderly and poor performance patients, the same regimen without etoposide (FLv). Quality of life was evaluated with the EORTC-QLQ-C30 instrument. Mean scale scores in the QLQ-C30 improved more often/deteriorated less frequently in the chemotherapy group than in the best supportive care group. More patients in the chemotherapy group (36%, 17/49) had an improved or prolonged high quality of life for a minimum period of 4 months compared to those in the best supportive care group (10%, 4/41, P < 0.01). Overall survival was significantly longer in the chemotherapy group (median 6 vs. 2.5 months, P < 0.01). Also, the quality-adjusted survival time was longer for patients randomized to chemotherapy (median 4 vs. 1 months, P < 0.01). The effects were seen both in pancreatic and biliary cancer. The results show that chemotherapy can add to both quantity and quality of life in advanced pancreatic and biliary cancer. The number of patients who benefit from treatment is, however, still limited; for this reason careful selection before, and close monitoring during, treatment are necessary.", "journal": "Annals of oncology : official journal of the European Society for Medical Oncology", "doi": "10.1093/oxfordjournals.annonc.a010676", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8806483", "author": "Burns CC", "n_authors": 5, "title": "Identification and deletion of sequences required for feline leukemia virus RNA packaging and construction of a high-titer feline leukemia virus packaging cell line.", "abstract": "Sequences required for specific encapsidation of feline leukemia virus (FeLV) genomic RNA have not yet been defined. Deletion of 107 nucleotides between the splice donor (SD) and the gag coding region of a prototypic subgroup A FeLV, 61E, resulted in an approximately 200-fold reduction of packaged viral RNA. Virus particle production was not disrupted by the deletion, although viral infectivity was dramatically reduced. These data indicate that the 107-nucleotide sequence comprises a portion of the FeLV packaging signal. FeLV particles expressed from the deleted genome were able to efficiently package murine leukemia virus vectors, resulting in high-titer G418R virus production. This system can be easily adapted to produce FeLV particles that contain envelope proteins from other feline leukemia virus subgroups and will be broadly useful for studies of FeLV envelope/receptor interactions.", "journal": "Virology", "doi": "10.1006/viro.1996.0393", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8817854", "author": "Rudmann DG", "n_authors": 6, "title": "Pulmonary and mediastinal metastases of a vaccination-site sarcoma in a cat.", "abstract": "Sarcomas at vaccination sites in cats were first reported in 1992. Recent retrospective studies have confirmed an association between these vaccination-site sarcomas (VSS) and feline leukemia virus (FeLV) and/ or rabies vaccines. In most cases, VSS are locally invasive fibrosarcomas that tend to recur but rarely metastasize. We report the mediastinal and pulmonary metastases of a VSS in a FeLV-and feline immunodeficiency virus-negative, 8-year-old, domestic short-haired cat. The primary sarcoma was removed from an interscapular vaccination site and diagnosed as a VSS 3 months prior to radiographic lesions suggestive of pulmonary and mediastinal metastases. At necropsy, there were multiple pulmonary and mediastinal nodules that histologically and ultrastructurally were fibrosarcomas, cytomorphologically similar to the VSS. In addition, immunohistochemical staining patterns of the VSS and metastatic sites were consistent with that described for VSS. Recent reports of pulmonary and mediastinal metastases of interscapular VSS emphasize the importance of early diagnosis and treatment of these tumors.", "journal": "Veterinary pathology", "doi": "10.1177/030098589603300422", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8813751", "author": "Parent JM", "n_authors": 2, "title": "Seizures in cats.", "abstract": "Seizures in cats are caused by active structural disease or secondary epilepsy. The most common structural causes are inflammatory diseases, many of which are probably viral (non-FIP) in origin. Toxoplasmosis, FIP, FeLV, and FIV are rare causes of recurrent seizures in cats. The incidence of primary epilepsy is unknown; it is unlikely to occur in domestic cats. The pattern (type and frequency) of the seizures and the age at onset of the seizures are important factors in establishing a differential diagnosis. More than 50% of cats with seizures experience nonconvulsive (mild generalized or partial complex) seizures. Though many cats experience severe cluster seizures and status epilepticus, severity of seizures is not a good predictor of outcome. Many cats stop having seizures or are controlled well with AEDs regardless of the severity of their seizure activity.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8809383", "author": "Jackson ML", "n_authors": 4, "title": "Immunohistochemical identification of B and T lymphocytes in formalin-fixed, paraffin-embedded feline lymphosarcomas: relation to feline leukemia virus status, tumor site, and patient age.", "abstract": "The lymphocyte phenotype of 70 formalin-fixed, paraffin-embedded feline lymphosarcomas (LSAs) was determined immunohistochemically using a T cell polyclonal antibody, and a B cell monoclonal antibody. Forty-seven of 70 (67%) tumors were T cell, 19/70 (27%) were B cell, and 4/70 (6%) did not stain with either marker. Thirty-eight of 70 (54%) tumors were positive for feline leukemia virus (FeLV) antigen by immunohistochemistry (IHC), and 52/70 (74%) tumors were positive for FeLV DNA using the polymerase chain reaction (PCR). B cell tumors were as frequently FeLV-positive as T cell tumors using either IHC or PCR. Intestinal tumors were more likely to be B cell than T. The incidence of B and T cell tumors was not different among young (< or = 3 y), middle-aged (> 3 y to < or = 8 y), and old (> 8 y) cats. Both B and T cell tumors from old cats were FeLV-positive more often by PCR than by IHC. Feline leukemia virus DNA but not antigen, was detected in B cell tumors and intestinal tumors from cats > 8 y as often as it was detected in B cell tumors and intestinal tumors from cats < or = 8 y. Previously, most B cell and intestinal tumors from old cats were considered to be negative for FeLV. Here, the results suggest involvement of latent or replication-defective forms of the virus in such tumors from old cats. This study supports a role for FeLV in feline B cell as well as T cell tumorigenesis.", "journal": "Canadian journal of veterinary research = Revue canadienne de recherche veterinaire", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8757981", "author": "Quackenbush SL", "n_authors": 3, "title": "Replication kinetics and cell tropism of an immunosuppressive feline leukaemia virus.", "abstract": "To elucidate in vivo cell tropism and infection kinetics of an immunodeficiency-inducing isolate of feline leukaemia virus (FeLV-FAIDS), we quantified the two major genotypes comprising FeLV-FAIDS [the replication-competent common form (clone 61E) and the replication-defective variant (clone 61C)] in lymphocyte and leukocyte populations from infected cats. Micromagnetic separation of cell subsets, virus genome-specific PCR and flow cytometry were used to demonstrate the following sequence of events in infected animals: (i) very early replication of both 61E and 61C in CD4 T cells (provirus burden 0.2 to 1 copy/cell at 2-4 weeks post-infection); (ii) lower magnitude replication of both viruses in CD8 T cells and B cells during this initial phase of infection; (iii) plateauing of CD4 cell virus burden accompanied by escalation in CD8 and B cell provirus burdens after 4 weeks; (iv) extensive infection of haemopoietic and circulating myeloid cells. FeLV-FAIDS 61E and 61C replication kinetics and lymphocyte tropisms were similar in blood and lymph nodes, where provirus burdens ranged from 0.15 to 1.0 copy/cell. Moreover, virus infection was productive; 8-48 percent of blood lymphocytes, 35-81 percent of node lymphocytes and 53-98 percent of bone marrow cells expressed FeLV capsid antigen (p27 Gag). These findings suggest that the immunosuppressive potency of FeLV-FAIDS reflects the unique cytopathicity rather than unique cytotropism of its 61C (versus 61E) component.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-77-7-1411", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8795188", "author": "Kerr MG", "n_authors": 2, "title": "FeLV testing.", "abstract": null, "journal": "The Veterinary record", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "21544487", "author": "Kopelovich L", "n_authors": 1, "title": "Differentiation of primary human fibroblasts into tissue macrophages by the Snyder-Theilen strain of the feline sarcoma virus is associated with endoreduplication, a 1,9 translocation, phenotypic stability, and apoptosis.", "abstract": "We have previously reported the conversion of human fibroblasts to tissue macrophages by transduction with the Snyder-Theilen feline sarcoma virus [ST:FeSV (FeLV)]. The ST:FeSV-induced macrophages were largely configured as spherical cells, each with an extensive network of microvilli. Nuclear alterations included the appearance of three sub-populations within these mononucleated macrophages consisting of diploid (19%), tetraploid (43%), and octaploid (38%) cells. A karyotypic analysis revealed a 1,9 translocation in a small, dividing, subpopulation within the diploid fraction of the ST:FeSV-induced macrophages. Clonotypic assays demonstrated the conversion of all individually expanded, cloned fibroblasts, to macrophages following transduction with ST:FeSV. None of the converted macrophages reverted to the fibroblastic cell phenotype as determined by co-expression of v-fes and the receptor for the macrophage colony stimulating factor (CSF-IR). The ST:FeSV-induced macrophages did not form colonies in agar, nor did they form tumors in athymic mice. They appeared to undergo apoptosis after 4-6 weeks in culture. The findings pertain to the heterogeneous nature of tissue macrophages and their recruitment process during normal conditions, and in response to inflammatory stimuli.", "journal": "International journal of oncology", "doi": "10.3892/ijo.8.6.1223", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8799931", "author": "Batchelder MA", "n_authors": 4, "title": "A cluster of cases of juvenile mediastinal lymphoma in a ferret colony.", "abstract": "Three cases of juvenile mediastinal lymphoma developed in a laboratory colony of ferrets. Two ferrets became acutely moribund, and one was found dead with no preceding signs of illness. Splenomegaly, hepatomegaly, and a large thoracic mass were the primary features in each case. All three ferrets had multiorgan metastasis of the tumor. Two ferrets were tested for feline leukemia virus and Aleutian disease virus with negative results.", "journal": "Laboratory animal science", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8767729", "author": "Goldberg M", "n_authors": 2, "title": "Studies and comparison of pterin patterns in the plasma of dogs and cats and their alteration in various neoplasias and virus infections.", "abstract": "Physiological pterin levels were evaluated in plasma samples of healthy dogs and cats. Biopterin and 7-xanthopterin were determined quantitatively by HPLC after partial purification by ion exchange chromatography. Neopterin, pterin and 6-hydroxymethylpterin were not detectable in plasma samples. Pterin levels in plasma of dogs with neoplasias and cats with neoplasias or viral infections (FeLV, FIV, FIP) were determined. Dogs with various tumours did not show qualitative but distinct quantitative alterations in the pterin concentration in plasma. Biopterin concentrations in plasma of dogs after tumour exstirpation significantly decreased compared to the levels before surgery. There was only a moderate increase of the biopterin levels in plasma of cats with neoplasias in comparison to healthy animals of this species. Cats suffering from viral infections, however, showed a significant rise in biopterin concentrations. The results underscore the importance of pterins as sensitive indicators for the presence of activation of cell mediated immune response. With emphasis on biopterin the role of pterins as helpful parameters for the preventation and the monitoring of diseases is pointed out.", "journal": "Zentralblatt fur Veterinarmedizin. Reihe A", "doi": "10.1111/j.1439-0442.1996.tb00445.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8727505", "author": "Porter CD", "n_authors": 7, "title": "Comparison of efficiency of infection of human gene therapy target cells via four different retroviral receptors.", "abstract": "The relative efficiency of transduction of gene therapy target cells was measured for retroviruses bearing the envelopes of amphotropic murine leukemia virus (MLV-A), xenotropic murine leukemia virus (MLV-X), gibbon ape leukemia virus (GALV), feline leukemia virus subgroup B (FeLV-B), and the feline endogenous virus RD114. These viruses use various cell-surface receptors. Activated peripheral blood lymphocytes (PBL) and primary melanoma cultures were infected relatively poorly by MLV-X pseudotypes. RD114 pseudotypes infected PBL relatively well, whereas bone marrow progenitor cells were efficiently infected by all viruses. Helper-free virus bearing the envelopes of MLV-A, RD114, or GALV was similarly tested. All infected melanoma or bone marrow progenitor cells efficiently, whereas MLV-A was relatively inefficient for infection of PBL. The general utility of RD114 pseudotyped virus for gene delivery coupled with its resistance to inactivation by human serum makes this envelope the most suitable choice for in vivo gene therapy.", "journal": "Human gene therapy", "doi": "10.1089/hum.1996.7.8-913", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8740699", "author": "Callanan JJ", "n_authors": 6, "title": "Histologic classification and immunophenotype of lymphosarcomas in cats with naturally and experimentally acquired feline immunodeficiency virus infections.", "abstract": "Lymphosarcoma (malignant lymphoma) is the commonest hematopoietic tumor in the cat. Many cases are associated with feline leukemia virus (FeLV) infection, but epidemiologic and experimental data suggest that feline immunodeficiency virus (FIV) may also have a role in lymphomagenesis. In this paper, we describe the clinical presentation, histologic classification, and immunophenotype of lymphosarcoma in eight domestic cats with natural or experimental FIV infections. The tumors were often of unusual distribution, with the majority of cases conforming to the least common anatomic classification of \"miscellaneous.\" Histopathologic and immunophenotypic analysis using a panel of anti-cat and cross-reactive anti-human monoclonal and polyclonal antibodies identified seven of these tumors as high-grade B cell lymphomas of the centroblastic or immunoblastic subtypes. The remaining case was a T-cell tumor associated with a concurrent FeLV infection. Our findings, together with the results of an analysis of FIV proviral DNA in these tumors, indicate that the B-cell lymphosarcomas were comparable to those observed in human and simian immunodeficiency virus infections and that the role of FIV in lymphomagenesis is indirect and related to the potential for malignant transformation during polyclonal B cell activation.", "journal": "Veterinary pathology", "doi": "10.1177/030098589603300302", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8736227", "author": "Scott HW", "n_authors": 2, "title": "Fibro-cartilaginous embolism in a cat.", "abstract": "A nine-year-old cat was presented with a history of an acute onset of paraplegia. On the basis of the neurological examination, the lesion was localised between the fourth lumbar and third sacral segments (L4 to S3) of the spinal cord. Investigations included radiography, myelography, cerebrospinal fluid analysis, routine haematology and biochemistry, feline leukaemia virus testing and urinalysis. A definitive diagnosis was not achieved and the cat was euthanased 12 days after presentation. Post mortem examination revealed infarction of the spinal cord secondary to fibrocartilaginous embolisation. This is the first reported case of fibrocartilaginous embolism in the cat in the UK.", "journal": "The Journal of small animal practice", "doi": "10.1111/j.1748-5827.1996.tb01774.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8635972", "author": "Gasper PW", "n_authors": 3, "title": "Allogeneic marrow transplantation in a cat with acute myeloid leukemia.", "abstract": "A listless, anorectic 2-year-old cat was found to have a normocytic, nonregenerative anemia. A diagnosis of acute myeloid leukemia type M6Er was made. Because the cat was young, had negative FeLV and feline immunodeficiency virus test results, had a sibling that could be used as a bone marrow donor, had received only 1 transfusion, and was in good health other than being anemic, allogeneic bone marrow transplantation (BMT) was attempted using marrow from the cat's sibling. The most life-threatening complication following BMT was hemorrhage caused by severe thrombocytopenia. Complete hematopoietic engraftment was evident 36 days after BMT. The cat then was discharged to its owner. In the first year, the cat continued to improve with the exception of an intractable dermatophytosis, which resolved eventually. The cat continues to do well 4 years after BMT. To our knowledge, this represents the first report of successful allogeneic BMT for a cat with acute myeloid leukemia.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "22074523", "author": "Legendre AM", "n_authors": 1, "title": "Feline leukemia virus & feline immunodeficiency virus.", "abstract": null, "journal": "The veterinary quarterly", "doi": "10.1080/01652176.1996.9694668", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8650690", "author": "Horzinek MC", "n_authors": 1, "title": "[Vaccination against feline retrovirus infections].", "abstract": "Feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV), both of veterinary importance, their antigenic and genetic variability as well as their pathogenicity are described. Disease following FeLV infection is interpreted as a consequence of genetic recombination, as a result of viral evolution in vivo. The principles and efficacy of vaccines are discussed.", "journal": "Tierarztliche Praxis", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8620914", "author": "Yamaguchi N", "n_authors": 5, "title": "Parasite prevalence in free-ranging farm cats, Felis silvestris catus.", "abstract": "No animals tested were positive for feline leukemia virus antigen and Chlamydia psittaci antibodies, but all were positive for antibodies to feline calicivirus (FCV), feline herpesvirus 1 (FHV1) and rotavirus. They had antibodies to feline parvovirus (96%), feline coronavirus (84% and cowpox virus (2%). Antibody to feline immunodeficiency virus (FIV) was found in 53% of animals, which were less likely to be infected with Haemobartonella felis, and had higher FHV antibody titres than cats without FIV. FCV was isolated from 51% cats and FHV1 and feline reovirus each from 4%. H. felis was present in 42% of animals, and antibody to Toxoplasma gondii in 62%. Clinical abnormality had a significant association with FIV and feline calicivirus infections, but sex, age, social status and feeding group had no significant association with prevalence of any parasites. Toxocara cati and Toxascaris leonina eggs were found, respectively, in 91% and 82% of animals tested.", "journal": "Epidemiology and infection", "doi": "10.1017/s0950268800052468", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8882328", "author": "Jarrett O", "n_authors": 1, "title": "Efficacy of recombinant feline leukemia virus vaccines.", "abstract": null, "journal": "AIDS research and human retroviruses", "doi": "10.1089/aid.1996.12.435", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8882314", "author": "Hoover EA", "n_authors": 4, "title": "Efficacy of an inactivated feline leukemia virus vaccine.", "abstract": "An inactivated whole-virus FeLV vaccine, developed from a molecularly cloned FeLV isolate (FeLV-61E-A), was assessed for its ability to protect cats against homologous and heterologous virulent viral challenge. The fractions of cats that resisted the induction of persistent viremia after FeLV challenge were as follows: FeLV-61E-A vaccine, 95%; adjuvant controls, 26%; and established commercial control FeLV vaccine, 35%. The prechallenge mean neutralizing antibody titers for each group were as follows: FeLV-61E-A vaccine, 1:43; adjuvant controls, < 1:8; and commercial control FeLV vaccine, 1:12. The prototype FeLV-61E-A vaccine was developed commercially for immunization of pet cats by substitution of a proprietary adjuvant and development of stable, high antigen production cell lines. This vaccine (Fel-O-Vax) has been studied extensively, alone and in multivalent combination with other feline virus vaccines, in seven efficacy trials involving a total of 150 immunized cats. These studies yielded an FeLV-resistant fraction of 87% in vaccinated cats as compared with 8% in adjuvant controls. The duration of immunity induced by an FeLV-61E-A commercial vaccine (Fel-O-Vax-LvK IV) was also assessed. One year after vaccination, 100% of challenged vaccinated cats and none of challenged controls resisted induction of persistent viremia. The results of these studies demonstrate that an inactivated FeLV vaccine prepared from a molecularly cloned subgroup A FeLV produces a high level of protective immunity against heterologous and homologous FeLV infection. This vaccine-induced immunity is durable for at least 1 year without intervening booster immunization or exposure to virus.", "journal": "AIDS research and human retroviruses", "doi": "10.1089/aid.1996.12.379", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "21544403", "author": "Kopelovich L", "n_authors": 1, "title": "Differentiation of human fibroblasts to tissue macrophages by the Snyder-Theilen feline sarcoma virus (ST:FeSV).", "abstract": "We have previously reported the conversion of human fibroblasts (HF) to tissue macrophages (TM) by transduction with the Snyder-Theilen feline sarcoma virus [ST:FeSV(FeLV)]. Here, we have demonstrated macrophage mediated tumor cytotoxicity (MTC) of human teratocarcinoma cells (NTERA-2) by ST:FeSV-induced TM. Inclusion of the NTERA-2 specific antibody (SSEA-4), substantially increased antibody-dependent cellular cytotoxicity (ADCC) of the tumor cells by ST:FeSV-induced TM. Tumor cell lysis by ST:FeSV-induced TM through either MTC or ADCC was especially effective at low serum concentrations (1%). The presence of cytokines during co-incubation, M-CSF in particular, enhanced the lysis of NTERA-2 cells by ST:FeSV-induced TM. Whereas pretreatment of the NTEBA-2 cells with all-trans retinoic acid (AtRA) enhanced MTC-induced lysis, it abrogated ADCC-induced lysis of the tumor cells by ST:FeSV-induced TM. Significantly, the co-incubation of NTERA-2 cells with ST:FeSV-induced TM in agar, resulted in a considerable stimulation of growth of untreated and TPA-pretreated NTERA-2 cells. In contrast, the growth of AtRA-pretreated NTERA-2 cells in agar was completely inhibited by ST:FeSV-induced TM. These results indicate that ST:FeSV-induced TM can produce potent growth-modulating cytokines, and that AtRA can modify their antitumor activity in monolayer cultures and in agar. The effects by AtRA, serum, and growth conditions (whether monolayers or agar) point to several levels of complexity regarding the interaction of tissue macrophages with tumor cells.", "journal": "International journal of oncology", "doi": "10.3892/ijo.8.3.603", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8833612", "author": "Misdorp W", "n_authors": 1, "title": "Veterinary cancer epidemiology.", "abstract": "This paper reviews the impact of veterinary cancer epidemiology on veterinary oncology, human oncology, comparative oncology, and on the etiology and pathogenesis of cancer. The detection of clusters of diseased animals has led to the discovery of the infectious, viral-associated nature of malignant lymphoma of cats, poultry, and cattle. Although some viruses (FeLV, BLV) can, under experimental conditions, cross the species barrier, there is thus far no evidence for a zoonotic hazard for the human. The keeping of pet/birds or pigeons was found to be associated with an increased risk of lung cancer in the bird keepers. Dogs appear to be useful 'sentinels' for environmental hazards (asbestos, dyes, passive smoking, insecticides). The complex pathogenesis of cancer was dissected in an epidemiologic-experimental study in cows, which had intestinal papillomas and carcinomas. Endogenous genetic factors may also play a role in pathogenesis, as is evidenced by species, breed (Boxer!), and family related aggregates of tumour diseases. Epidemiology may provide a means to prevent tumour diseases by, for example, withdrawal of hormones (mammary cancer) or isolation of tumour-virus positive animals (malignant lymphoma).", "journal": "The veterinary quarterly", "doi": "10.1080/01652176.1996.9694610", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8786609", "author": "Goodhead AD", "n_authors": 1, "title": "Uveitis in dogs and cats: guidelines for the practitioner.", "abstract": "Uveitis is a commonly misdiagnosed ophthalmic condition with a wide aetiological base and often the cause cannot be established. Uveitis can be associated with systemic diseases like feline infectious peritonitis, feline immunodeficiency virus, feline leukaemia virus, lymphoma, toxoplasmosis and canine ehrlichiosis. The classification and general clinical signs of uveitis are discussed. Applicable clinical cases, manifestations and diagnostic methods of the selected diseases are mentioned, and a general approach to the treatment of uveitis is given.", "journal": "Journal of the South African Veterinary Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8680926", "author": "Lester S", "n_authors": 3, "title": "Vaccine site-associated sarcomas in cats: clinical experience and a laboratory review (1982-1993).", "abstract": "Recent information regarding vaccine site-associated sarcomas in cats suggest a relationship to either feline leukemia virus or rabies vaccines. The authors' initial case was in a cat that had received neither of these vaccines. Review of the available hospital records revealed an increasing number of vaccine site-associated sarcomas, none of which were related to feline leukemia virus vaccines. Only one was related to the use of a rabies vaccine, and this tumor occurred in the thigh as opposed to between the shoulder blades. The laboratory data supported an increasing incidence of vaccine site-associated sarcomas, the majority of which occurred in the interscapular area and were associated with routine prophylactic vaccinations.", "journal": "Journal of the American Animal Hospital Association", "doi": "10.5326/15473317-32-2-91", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8595768", "author": "Nemzek JA", "n_authors": 3, "title": "Retroviral transmission in bone allotransplantation. The effects of tissue processing.", "abstract": "The transmission of a retrovirus through transplantation of processed bone allografts was studied using the feline leukemia virus. The long bones of 4 previously infected donor cats were harvested and assigned to 1 of 3 treatment groups: single freeze/thaw cycle, double freeze/thaw cycle, or double freeze/thaw cycle with water flush to remove bone marrow. Cortical bone grafts and corticocancellous bone grafts from each treatment group were transplanted into individual specific-pathogen-free recipients. Samples of plasma were obtained weekly from all recipients and were tested with an enzyme-linked immunosorbent assay to detect viral antigen. For animals that tested consistently negative for viral antigen, plasma samples also were tested for antiviral antibody to feline leukemia virus measured by live cell immunofluorescence. The results of the antigen and antibody testing revealed that all of the cortical and corticocancellous bone allografts in each of the 3 treatment groups transmitted virus. The ability of the treated bone allografts to transmit a feline retrovirus suggests that routine processing and removal of bone marrow may not inhibit their ability to transmit other retroviruses, such as the human immunodeficiency virus.", "journal": "Clinical orthopaedics and related research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8551576", "author": "Fulton R", "n_authors": 4, "title": "Apparent uncoupling of oncogenicity from fibroblast transformation and apoptosis in a mutant myc gene transduced by feline leukemia virus.", "abstract": "The T17 v-myc oncogene was transduced by feline leukemia virus in a spontaneous feline T-cell lymphosarcoma. Molecular cloning and sequencing of the v-myc gene revealed several unique mutations, including a large deletion affecting amino acids 49 to 124 and a 3-bp insertion within the basic DNA binding domain which converts Leu-362 to Phe-Arg. The T17 lymphoma cell line was found to express a truncated 50-kDa Myc protein at exceptionally high levels, while the endogenous c-myc gene was not detectably expressed. These observations suggest that the mutant Myc product expresses an oncogenic function in T cells. Further evidence that the T17 mutant gene retains oncogenic potential was provided by its detection in clonally integrated proviruses in secondary tumors induced by feline leukemia virus T17, where no reversion mutations were found in any of three tumors examined. However, the mutant T17 v-myc gene did not induce transformation in a chicken embryo fibroblast assay, in contrast to wild-type feline c-myc, which conferred higher growth rates on the chicken fibroblasts, along with altered morphology and the ability to form foci in soft agar. Chicken cells over-expressing feline c-myc died by apoptosis when cultured with low serum concentrations, while the T17 mutant had no discernible effect. These results suggest that the leukemogenic potential of Myc can be uncoupled from its ability to cause transformation in fibroblasts. A possible explanation for this apparent paradox is that developing T cells are acutely sensitive to a subset of Myc functions which are insufficient for fibroblast transformation.", "journal": "Journal of virology", "doi": "10.1128/JVI.70.2.1154-1162.1996", "deposited_data": "Sim", "nuccore_ids": "1173534", "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8857332", "author": "Lubkin SR", "n_authors": 5, "title": "Evaluation of feline leukemia virus control measures.", "abstract": "A susceptible-infected-recovered-susceptible (SIRS) model of the epidemiology of feline leukemia virus is formulated and analysed. The dynamics of the disease are dramatically different in no-risk, low-risk and high-risk subpopulations of asocial, free roaming, and multiple cat household cats. Among low risk (<1% prevalence) free roaming cats, the model predicts that an effective immunization rate of 4% year-1, or an effective removal rate of 8% year-1 are adequate to control the disease completely. Under higher risk (10% prevalence) conditions, an effective immunization rate of 23-72% year-1 or a removal rate of 69-145% year-1 are required for control. At very high (30%) prevalence rates, even heroic measures may not suffice to substantially reduce disease prevalence: a vaccination rate of 100% year-1 even if attainable, would only slightly reduce disease prevalence from 30% to 29%. We conclude that the current estimated effective feline leukemia virus immunization rate of 11-19% of the general population is inadequate to provide herd immunity in the subpopulation of cats which are genuinely at risk of infection. A substantial increase in the vaccination rate and/or intensification of test and removal efforts in the at risk population would be required to attain an effective level of protection.", "journal": "Journal of theoretical biology", "doi": "10.1006/jtbi.1996.0006", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8825325", "author": "Jarrett O", "n_authors": 2, "title": "Comparative studies of the efficacy of a recombinant feline leukaemia virus vaccine.", "abstract": "The efficacy of three feline leukaemia virus (FeLV) vaccines was compared. Kittens were immunised with either a recombinant subunit vaccine, Leucogen, or one of two inactivated virus vaccines, Leukocell 2 or Leucat. On subsequent challenge by intraperitoneal inoculation of FeLV of subgroup A (FeLV-A), only Leucogen gave significant protection. In a second experiment, kittens vaccinated with Leucogen were protected against oronasal challenge with a phenotypic mixture of FeLV of subgroups A, B and C. These results indicate that a recombinant vaccine, containing only the protein moiety of the surface glycoprotein of FeLV-A, can provide better protection than the inactivated virus vaccines tested against challenge with virus of the same subgroup, and can also protect against challenge by all three subgroups of FeLV.", "journal": "The Veterinary record", "doi": "10.1136/vr.138.1.7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "9026077", "author": "Jackson ML", "n_authors": 4, "title": "Feline leukemia virus detection by ELISA and PCR in peripheral blood from 68 cats with high, moderate, or low suspicion of having FeLV-related disease.", "abstract": "Clinicopathologic criteria were used to group 68 cats according to high, moderate, or low suspicion of having feline leukemia virus (FeLV)-related disease. Peripheral blood samples were tested for FeLV antigen by enzyme-linked immunosorbent assay (ELISA) and for FeLV DNA by polymerase chain reaction (PCR). There was no significant difference between ELISA and PCR results in the 68 cats. In the high-suspicion group, 46%(11/24) of cytopenic cats were test positive (ELISA and PCR) and 87% (13/15) with hemopoietic neoplasms were test-positive. Also within the high suspicion group, test-positive cats were 2.5 times more likely to die within the 1 year follow-up period than were test-negative (ELISA and PCR) cats. Among cats in the moderate-suspicion group, 15% (2/13) were test-positive, and none (0/16) of the cats in the low suspicion group was test positive. The relative risk of a positive test (ELISA and PCR) in the high suspicion group was 3.7 times that for the moderate-suspicion group and 22.8 times that for the low suspicion group. There was no significant difference in the relative risk of a positive test result between the moderate and low suspicion groups. The results indicate that FeLV detection by PCR can be adapted for diagnostic purposes using peripheral blood samples, however, results do not differ significantly from FeLV ELISA results. Also, a proportion of cats with a high suspicion of having FeLV-related cytopenia and hemopoietic tumors are negative for both circulating FeLV antigen and DNA. These cats may not have FeLV-related disease, or FeLV may exist in a disease-producing but nonreplicating form ultimately detectable by PCR in tissues other than peripheral blood.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/104063879600800105", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8825569", "author": "Macy DW", "n_authors": 2, "title": "The potential role of inflammation in the development of postvaccinal sarcomas in cats.", "abstract": "Epidemiologic evidence shows a strong association between the administration of inactivated feline vaccines (feline leukemia virus and rabies) and subsequent soft tissue sarcoma development at vaccine sites. Although more research is needed to understand the complete pathogenesis of vaccine-induced tumors in cats, good evidence exists that inflammation plays a role.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": "10.1016/s0195-5616(96)50009-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8822790", "author": "Rojko JL", "n_authors": 5, "title": "Cytopathic feline leukemia viruses cause apoptosis in hemolymphatic cells.", "abstract": "Certain isolates of the oncoretrovirus feline leukemia virus (FeLV) are strongly cytopathic for hemolymphatic cells. A major cytopathicity determinant is encoded by the SU envelope glucoprotein gp70. Isolates with subgroup C SU gp70 genes specifically induce apoptosis in hemolymphatic cells but not fibroblasts. In vitro exposure of feline T-cells to FeLV-C leads first to productive viral replication, next to virus-induced cell agglutination, and lastly to apogenesis. This in vitro phenomenon may explain the severe progressive thymic atrophy and erythroid aplasia which follow viremic FeLV-C infection in vivo. Inappropriate apoptosis induction has also been hypothesized to explain the severe thymico-lymphoid atrophy and progressive immune deterioration associated with isolates of FeLV containing variant envelope genes. The influence of envelope hypervariability (variable regions 1 [Vr1] and 5 [Vr5] on virus tropism, viremia induction, neutralizing antibody development and cytopathicity is discussed. Certain potentially cytopathic elements in FeLV SU gp70 Vr5 may derive from replication-defective, poorly expressed, endogenous FeLVs. Other more highly conserved regions in FeLV TM envelope p15E may also influence apoptosis induction.", "journal": "Progress in molecular and subcellular biology", "doi": "10.1007/978-3-642-79850-4_2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8739348", "author": "Leskovar P", "n_authors": 2, "title": "Treatment of solid tumors should obligatorily be combined with the in vivo codepletion of tumor-protecting, CD8+/HLA-DR(+)-suppressor T cells by alloreactive donor T cells whose preprogrammed cell death allows a high GvL-effect before GvHD can be established. Results of animal experiments, including more than 6000 mice.", "abstract": "The FACS-analysis of diseases as different as cancer, autoimmune disorders and chronic (retro)viral infections, including HIV-infection, shows -at least temporarily- a common feature of lymphocyte hyperactivation, characterized by cellular activation markers (HLA-DR, CD26, CD38, CD69, CD2R and/or CD30), as well as by solubilized membrane structures, such as beta-2m, sICAM-I, sIL-2R/sCD25, sCD8, and by some oversecreted immunocyte products (e.g. neopterin, lysozyme and/or cathepsin D). We tested two potential approaches to down-regulate the pathologically elevated CD8+ and HLA-DR+ T cells: (a) In animal model, we tested the sensibility of these, disease inducing and maintaining T cell subsets to in vitro pretreated (cell death preprogrammed) semi-syngeneic and allogeneic donor T cells in tumor-bearing mice. (b) In the first clinical study, we used a novel combination of FDA-approved drugs which inhibits Ca(2+)-influx and concomitantly down-regulates cytosolic cAMP in patient's overstimulated immunocompetent cells. We could achieve a 94.6-100% long-term survival in tumor-bearing mice. In patients, large primary tumors and large metastases shrinked by 80-85% and small metastases disappeared completely. Since in HIV-infected persons, the increased number of HLA-DR+ CD38+T (T8) cells is associated with a fall in CD4-level and with development of AIDS, we are looking for the elimination of these HLA-DR+ targets by our novel technique in two AIDS-simulating (FIV/FeLV and SIV) animal models.", "journal": "Pflugers Archiv : European journal of physiology", "doi": "10.1007/BF02346352", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8630683", "author": "Erdman SE", "n_authors": 9, "title": "Clusters of lymphoma in ferrets.", "abstract": "Cluster outbreaks of lymphoma and leukemia have been associated with viral infections in many species including humans, cattle, and cats. This study describes epidemiological, clinical, and pathological features of cluster outbreaks of lymphoma in multiferret households and examines and compares the Aleutian disease virus (ADV) and feline leukemia virus (FeLV) status of cases, ferrets at risk, and controls. Three ferret groups with 21 cases of histologically diagnosed lymphoma (12.6% cumulative incidence) and their cohabitants (n = 35) were examined and compared with three control groups (n = 52) of cohabitating ferrets without lymphoma. A familial distribution was observed in one group but most cases were not consanguinous. Ferrets greater than 3 years of age developed chronic disease in two of the groups and 2-year-old adults had acute disease in the remaining group. Lymphocytosis, splenomegaly, and lymphadenopathy were prominent features. Histologically, predominantly small noncleaved cell and polymorphous lymphoid lesions were observed. All of the ferrets with lymphoma that were tested for ADV and FeLV using serology or PCR were negative. The rate of ADV antibody among cases or ferrets at risk was not significantly different from controls. None of the cluster ferrets were seropositive for FeLV p27 antigen using a monoclonal ELISA. Infection with a novel ferret virus is suspected, but an etiological agent has not yet been identified.", "journal": "Cancer investigation", "doi": "10.3109/07357909609012143", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8523548", "author": "de Noronha CM", "n_authors": 3, "title": "Generation and role of defective proviruses in cytopathic feline leukemia virus (FeLV-FAIDS) infections.", "abstract": "Cytopathic feline leukemia virus (FeLV) infections of feline T-cell line (FeT-cell) cultures led to the accumulation and maintenance of threefold more proviruses with deletions within the polymerase gene (pol) than minimally cytopathic FeLV infections. Over 60% of the viral DNA from cytopathic infections bore deletions in pol. Characterization of DNA sequences adjoining the deletions revealed that the junctions were most often flanked by RNA splice donor and acceptor consensus motifs. A thymidine-to-cytidine mutation introduced at the +2 position of one RNA splice donor-like motif inhibited formation of the two most prevalent viral DNA species with deletions, confirming the origin of many proviruses with deletions from reverse transcription of aberrantly spliced viral RNA species. An example of deletion by misalignment was also characterized. Viral inocula obtained from cells recovered after cytopathic infections were attenuated in their ability to cause cytopathic effects (CPE) and were able to confer superinfection resistance to naïve FeT-cells, despite maintaining envelope gene (env) sequences with full cytopathic potential. This suggested that viral genomes with deletions, rather than being required for cytopathicity, play a role in protecting cells from CPE. Indeed, expression of a molecularly cloned provirus bearing one of the characterized deletions attenuated CPE in FeT-cells caused by superinfecting cytopathic virus.", "journal": "Journal of virology", "doi": "10.1128/JVI.70.1.359-367.1996", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9413100", "author": "Usinger WR", "n_authors": 1, "title": "A comparison of antibody responses to veterinary vaccine antigens potentiated by different adjuvants.", "abstract": "Six adjuvant formulations were compared for their ability to potentiate the primary and memory antibody responses in mice to three companion animal vaccine immunogens--feline leukemia virus (FeLV), feline immunodeficiency virus (FIV), and a recombinantly-derived heartworm antigen. The combination of a novel bacterial immunostimulator, gliding bacterial adjuvant (GBA), either adsorbed onto an aluminum hydroxide gel (Rehydragel HPA), or emulsified with a vehicle of polyalcohol and detergent, elicited the strongest memory responses to both virus preparations. Both forms of aluminum hydroxide gels administered without GBA gave similar levels of adjuvant effects, on par with or greater than those generated by incomplete Freund's adjuvant (IFA). The Acemannan immunostimulant was not effective in increasing the responses to the virus antigens, but increased the primary response to the heart-worm antigen over tenfold from control levels. All preparations appeared to be well tolerated, with no detectable adverse reactions observed in any of the 250 mice used. The proven safety of aluminum hydroxide adjuvants and the apparent absence of adverse reactions seen with GBA make this vehicle/adjuvant formulation worthy of additional study.", "journal": "Vaccine", "doi": "10.1016/s0264-410x(97)00136-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9371646", "author": "Pantginis J", "n_authors": 4, "title": "The feline leukemia virus long terminal repeat contains a potent genetic determinant of T-cell lymphomagenicity.", "abstract": "Feline leukemia virus (FeLV) is an important pathogen of domestic cats. The most common type of malignancy associated with FeLV is T-cell lymphoma. SL3-3 (SL3) is a potent T-cell lymphomagenic murine leukemia virus. Transcriptional enhancer sequences within the long terminal repeats (LTRs) of SL3 and other murine retroviruses are crucial genetic determinants of the pathogenicities of these viruses. The LTR enhancer sequences of FeLV contain identical binding sites for some of the transcription factors that are known to affect the lymphomagenicity of SL3. To test whether the FeLV LTR contains a genetic determinant of lymphomagenicity, a recombinant virus that contained the U3 region of a naturally occurring FeLV isolate, LC-FeLV, linked to the remainder of the genome of SL3 was generated. When inoculated into mice, the recombinant virus induced T-cell lymphomas nearly as quickly as SL3. Moreover, the U3 sequences of LC-FeLV were found to have about half as much transcriptional activity in T lymphocytes as the corresponding sequences of SL3. This level of activity was severalfold higher than that of the LTR of weakly leukemogenic Akv virus. Thus, the FeLV LTR contains a potent genetic determinant of T-cell lymphomagenicity. Presumably, it is adapted to be recognized by transcription factors present in T cells of cats, and this yields a relatively high level of transcription that allows the enhancer to drive the requisite steps in the process of lymphomagenesis.", "journal": "Journal of virology", "doi": "10.1128/JVI.71.12.9786-9791.1997", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9371598", "author": "Tailor CS", "n_authors": 2, "title": "Variable regions A and B in the envelope glycoproteins of feline leukemia virus subgroup B and amphotropic murine leukemia virus interact with discrete receptor domains.", "abstract": "The surface (SU) envelope glycoproteins of feline leukemia virus subgroup B (FeLV-B) and amphotropic murine leukemia virus (A-MLV) are highly related, even in the variable regions VRA and VRB that have been shown to be required for receptor recognition. However, FeLV-B and A-MLV use different sodium-dependent phosphate symporters, Pit1 and Pit2, respectively, as receptors for infection. Pit1 and Pit2 are predicted to have 10 membrane-spanning domains and five extracellular loops. The close relationship of the retroviral envelopes enabled us to generate pseudotype virions carrying chimeric FeLV-B/A-MLV envelope glycoproteins. We found that some of the pseudotype viruses could not use Pit1 or Pit2 proteins but could efficiently utilize specific chimeric Pit1/Pit2 proteins as receptors. By studying Mus dunni tail fibroblasts expressing chimeric Pit1/Pit2 proteins and pseudotype virions carrying chimeric FeLV-B/A-MLV envelopes, we show that FeLV-B and A-MLV VRA and VRB interact in a modular manner with specific receptor domains. Our results suggest that FeLV-B VRA interacts with Pit1 extracellular loops 4 and 5 and that residues Phe-60 and Pro-61 of FeLV-B VRA are essential for receptor choice. However, this interaction is insufficient for infection, and an additional interaction between FeLV-B VRB and Pit1 loop 2 is essential. Similarly, A-MLV infection requires interaction of A-MLV VRA with Pit2 loops 4 and 5 and VRB with Pit2 loop 2, with residues Tyr-60 and Val-61 of A-MLV VRA being critical for receptor recognition. Together, our results suggest that FeLV-B and A-MLV infections require two major discrete interactions between the viral SU envelope glycoproteins and their respective receptors. We propose a common two-step mechanism for interaction between retroviral envelope glycoproteins and cell surface receptors.", "journal": "Journal of virology", "doi": "10.1128/JVI.71.12.9383-9391.1997", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9362033", "author": "Nogami S", "n_authors": 2, "title": "Prevalence of Dirofilaria immitis infection in cats in Saitama, Japan.", "abstract": "To clarify Dirofilaria immitis infection among cats in Saitama Prefecture, Japan, 1,840 cats were examined postmortem for adult worms and microfilariae in the blood from 1989 to 1995. As a reference control, 500 dogs from the same area were examined in the same way and period. D. immitis worms were found in 15 cats, one of which had microfilariae in the blood. Prevalence rate of D. immitis infection was 0.8% (15/1,840) in cats and 46.8% (234/500) in dogs examined, whereas it was 4.1% and 64.6% in cats and dogs, respectively, aged 2 years and over. Worm burden per positive cat was 1.5 +/- 0.7 (mean +/- SD), the maximum number of worm was 3 in 2 cats, and 10 cats had a single worm each. All the worm-positive cats were tested for antibodies to feline immunodeficiency virus (FIV) and antigens of feline leukemia virus (FeLV) in sera. Positive rates of coinfection with D. immitis were 26.7% and 13.3% for FIV and FeLV, respectively.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.59.869", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9350752", "author": "Glaus T", "n_authors": 6, "title": "Seroprevalence of Bartonella henselae infection and correlation with disease status in cats in Switzerland.", "abstract": "The prevalence of infection with Bartonella henselae was investigated in cats from different areas of Switzerland. Serum samples of 728 cats were examined for antibodies to B. henselae by immunofluorescent antibody testing, and the results were analyzed with a view to a possible correlation between a positive titer and signalment, clinical signs, infection with feline leukemia virus (FeLV), feline immunodeficiency virus (FIV), feline coronavirus (FCoV), or feline spumavirus (FeSFV), and the living environments of the cats. The seroprevalence in all cats was 8.3%. No significantly different prevalence was found in sick versus healthy cats (9.2 versus 7.2%); however, in sick cats seropositive for B. henselae, there was an increased frequency of stomatitis and a variety of diseases of the kidneys and the urinary tract. There was an increased prevalence of B. henselae in cats positive for FCoV (P = 0.0185) or FeSFV (P = 0.0235) and no statistically significant increased prevalence in cats infected with FeLV or FIV. There was no correlation between a positive titer and sex or breed. The same prevalence of B. henselae antibodies was found in cats with and without access to the outdoors and in cats from single- and multicat households. The seroprevalence was increased in cats living south of the Alps (12.1%); however, this difference was not significant (P = 0.0616).", "journal": "Journal of clinical microbiology", "doi": "10.1128/jcm.35.11.2883-2885.1997", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9343161", "author": "Boomer S", "n_authors": 4, "title": "Three distinct envelope domains, variably present in subgroup B feline leukemia virus recombinants, mediate Pit1 and Pit2 receptor recognition.", "abstract": "Subgroup B feline leukemia viruses (FeLV-Bs) evolve from subgroup A FeLV (FeLV-A) by recombining with portions of endogenous FeLV envelope sequences in the cat genome. The replication properties of FeLV-B are distinct from those of FeLV-A; FeLV-B infects many nonfeline cell lines and recognizes the human Pit1 (HuPit1) receptor, whereas FeLV-A infects primarily feline cells, using a distinct but as yet undefined receptor. Here, we demonstrate that some FeLV-Bs can also use human Pit2 (HuPit2) and hamster Pit2 (HaPit2) for entry. By making viruses that contain chimeric surface (SU) envelope proteins from FeLV-A and FeLV-B, and testing their infectivity, we have defined genetic determinants that confer host range and specific receptor recognition. HuPit1 receptor recognition determinants localize to the N-terminal region of the FeLV-B SU, amino acids 83 to 116, encompassing the N-terminal portion of variable region A (VRA). While this 34-amino-acid domain of the FeLV-B VRA is sufficient for infection of some cells (feline, canine, and human), amino acids 146 to 249 of FeLV-B, which include variable region B (VRB), were required for efficient infection in other cell types (hamster, bovine, and rat). Chimeras encoding FeLV-B VRA and VRB also infected cells expressing HaPit2 and HuPit2 receptors more efficiently than chimeras encoding only the VRA of FeLV-B, suggesting that VRB provides a secondary determinant that is both cell and receptor specific. However, viruses containing additional FeLV-B sequences in the C terminus of SU could not recognize HuPit2, implying that there is a determinant beyond VRB that negatively affects HuPit2 interactions. Thus, Pit2 recognition may drive selection for the generation of specific FeLV-B recombinants, offering an explanation for the two major classes of FeLV-B that have been observed in vivo. Furthermore, the finding that some FeLV-Bs can use both Pit1 and Pit2 may explain previous observations that FeLV-B and GALV, which primarily uses Pit1, display nonreciprocal interference on many cell types.", "journal": "Journal of virology", "doi": "10.1128/JVI.71.11.8116-8123.1997", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9322178", "author": "Day MJ", "n_authors": 1, "title": "Review of thymic pathology in 30 cats and 36 dogs.", "abstract": "Data are presented from 30 cats and 36 dogs in which thymic disease was recognised clinically or on postmortem examination. The diagnoses included thymic lymphoma (19 cats, 12 dogs), thymoma (five cats, 18 dogs), thymic branchial cyst formation or cystic change (one cat, four dogs), thymic hyperplasia (two cats), congenital hypoplasia (one cat, one dog), thymic haemorrhage (one cat, one dog) and thymic amyloidosis (one cat). Thymic lymphoma occurred in younger dogs and cats, and was recorded equally among domestic shorthaired and purebred (especially Siamese) cats. Eight cats with thymic lymphoma were tested for feline leukaemia virus and four were positive. Thymoma occurred more frequently in older cats and dogs, and in Labradors and German shepherd dogs. Thymic tumours were associated with paraneoplastic hypercalcaemia (six dogs), megaoesophagus (two dogs) or interface dermatitis with basement membrane immune complex deposition (one cat). Non-neoplastic thymic diseases were associated with myasthenia gravis (one cat), pemphigus foliaceus (one cat) and superficial necrolytic dermatitis (one cat).", "journal": "The Journal of small animal practice", "doi": "10.1111/j.1748-5827.1997.tb03492.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9345792", "author": "Fromont E", "n_authors": 5, "title": "Modelling the feline leukemia virus (FeLV) in natural populations of cats (Felis catus).", "abstract": "A compartmental model was built in order to study the circulation and impact of Feline Leukemia Virus (FeLV) in populations of domestic cats. The model was tested with data from a long-term study of several feline populations. The study of stability shows that FeLV is maintained in the population with a stable equilibrium and a slight reduction of population size. Estimation of the transmission rate allows us to make a comparison with the values previously estimated in the literature. We compare the impact of mass vaccination or removal programmes in controlling FeLV infection, and conclude that vaccination is more efficient.", "journal": "Theoretical population biology", "doi": "10.1006/tpbi.1997.1320", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9343336", "author": "Lappin MR", "n_authors": 4, "title": "Elevated interleukin 6 activity in aqueous humor of cats with uveitis.", "abstract": "The purpose of this study was to assess the role of interleukin 6 (IL-6) in feline uveitis by measuring IL-6 activity in the serum and aqueous humor of cats. Serum and aqueous humor was collected from clinically normal, random source cats (n = 10); clinically normal, specific-pathogen free cats experimentally inoculated with Toxoplasma gondii strain ME49 and sampled sequentially for 20 months (n = 4); and client-owned cats with uveitis (n = 27). Interleukin 6 activity was measured in each sample. Client-owned cats with uveitis were also evaluated for evidence of present or prior exposure to T. gondii, feline leukemia virus, feline immunodeficiency virus, and feline coronaviruses. Interleukin 6 activity was non-detectable or low in serum from cats of each group. Interleukin 6 activity was not detected in aqueous humor of clinically normal cats. Interleukin 6 activity was detected in 22/27 (81.5%) aqueous humor samples from cats with uveitis, with a range of 28.9 U ml(-1)-15702.9 U ml(-1) (mean = 1911.9 U ml[-1], SD = 3946.7 U ml[-1]). Serologic evidence of exposure to T gondii, feline immunodeficiency virus, feline leukemia virus, or a coronavirus was present in 21/27 (77.8%) cats with uveitis. Interleukin 6 was detected in the aqueous humor of 18/21 (85.7%) and 3/6 (50%) of the cats with and without serologic evidence of exposure to one to the infectious diseases, respectively. Statistically significant increases in mean IL-6 activity in aqueous humor were found for cats with any evidence of infection with T. gondii, for cats with T. gondii antigen in aqueous humor and for cats with coronavirus antibody titers > or = 1:100. Aqueous humor IL-6 activity was greater than corresponding serum IL-6 activity in 21/27 cats. These results show that IL-6 is produced intraocularly in some cats with uveitis and that IL-6 may be a mediator of uveitis in cats.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/s0165-2427(96)05766-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9292421", "author": "Mignon BR", "n_authors": 2, "title": "Prevalence and characterization of Microsporum canis carriage in cats.", "abstract": "In order to determine the prevalence and to characterize the carriage of Microsporum canis in cats, different mycological examinations (including a culture obtained by hair brushing and Wood's light examination) were performed on 632 animals of different origins. Group 1 comprised 467 healthy pet cats belonging to veterinary students. In this group, prevalence of carriage was 2.1%: eight cats were asymptomatic transient carriers and one cat was an asymptomatic infected animal presenting discrete Wood's-positive lesions disseminated on the whole body that were visible after sedation and clipping. The carriage prevalence was higher (15.7%) in group 2 comprising 134 European cats destroyed in a pound and kept together. In two additional groups of cats, it was shown that an infected cat was responsible for the dissemination of fungal material into its environment including the other in-contact animals. When the active source of fungus was removed, the dissemination stopped, resulting in a decrease in the amount of infective material recovered from both the animal carriers and the environmental surfaces. This was also observed in two experimental groups of guinea pigs. No association between feline immunodeficiency virus infection and the M. canis carriage was observed in a retrospective case-control study performed on group 2. None of these cats was feline leukaemia virus positive.", "journal": "Journal of medical and veterinary mycology : bi-monthly publication of the International Society for Human and Animal Mycology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9261955", "author": "Endo Y", "n_authors": 10, "title": "Molecular characteristics of malignant lymphomas in cats naturally infected with feline immunodeficiency virus.", "abstract": "Neoplastic disease, especially malignant lymphomas, are often observed in cats infected with feline immunodeficiency virus (FIV). In order to clarify the characteristics of lymphoma cells and to investigate the pathogenesis in FIV-infected cats, we examined the lymphoma tissues developed in five cats naturally infected with FIV by Southern blot analyses using feline immunoglobulin (Ig), T-cell receptors (TCR) and FIV probes. All of the five cases were serologically positive for anti-FIV antibody and negative for feline leukemia virus antigen. Of these five lymphoma samples, two displayed rearrangement of the Ig heavy chain gene and deletion of the Ig light (kappa) chain gene, indicating that the tumor cells were committed to B-cell development. One tumor sample was identified as a T-cell lymphoma because of the presence of a rearranged TCR beta-chain gene. The other two cases were considered to be non-T non-B cell lymphoma because they did not show any rearrangement of the Ig and TCR genes. Therefore, no consistent tumor type was found in lymphoma cases infected with FIV. Clonal integration of FIV provirus was not detected in any of the five lymphoma samples obtained from FIV-infected cats using Southern blot analysis, although FIV proviral genome was detected in the genomic DNA of all the lymphoma samples by using a polymerase chain reaction (PCR). These results indicated that FIV might not play a direct role in tumorigenesis of lymphoma in cats.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/s0165-2427(97)00004-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9232783", "author": "Davidson EB", "n_authors": 3, "title": "Surgical excision of soft tissue fibrosarcomas in cats.", "abstract": "The purpose of this study was to determine the tumor-free interval and survival times of cats who had one (group 1) or more (group 2) surgeries, or surgery and radiation therapy (RTH) (group 3) for treatment of soft tissue fibrosarcomas (FSA). Retrospective study. 45 client-owned cats. Medical records of cats with soft tissue FSA were examined. Vaccination and feline leukemia virus (FeLV) status, age, sex, breed, tumor location, number of surgeries, completeness of excision, and histopathological grade were evaluated to correlate with tumor-free interval and survival periods. Overall median tumor-free interval and survival times were 10 and 11.5 (range, 1 to 40) months. Median tumor-free interval and survival times were more than 16 months each in group 1, more than 5 and 13 months in group 2, and 4.5 and 9 months in group 3. Age, sex, breed, vaccination or FeLV status, tumor location, or histopathological grade did not affect median tumor-free interval or survival times (P > .05). Cats with complete excisions had significantly longer median tumor-free interval (> 16 versus 4 months) and survival time (> 16 versus 9 months) than those with incomplete excisions (P = .008). Radiation therapy did not seem to extend tumor-free interval and survival times (P = .013). However, most group 3 cats had incomplete surgical excisions, resulting in recurrent or progressive disease. Complete surgical excision of FSA in cats is possible and can be curative. Aggressive surgical excision with wide margins appears to contribute to extended tumor-free interval and survival times in cats with soft tissue FSA. Controlled prospective studies are needed to determine the efficacy of RTH in treatment.", "journal": "Veterinary surgery : VS", "doi": "10.1111/j.1532-950x.1997.tb01497.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9215446", "author": "Schultze AE", "n_authors": 3, "title": "Repeated physical and cytologic characterizations of subcutaneous postvaccinal reactions in cats.", "abstract": "To examine local reactions and short-term cytologic responses of cats to administration of rabies virus (RV); FeLV; and combined feline rhinotracheitis, calicivirus, and panleukopenia virus (FRCPV) vaccines. 9 healthy 6- to 7-month-old specific-pathogen-free cats. One-milliliter doses of the aforementioned vaccines were administered SC (at different sites) to healthy, specific-pathogen-free cats. Each cat also received 1 ml of sterile saline solution SC as a control. Injection sites were visually examined and palpated daily for 4 weeks. Palpable lesions were measured by use of calipers. Temperature of the vaccination sites was measured weekly by use of a thermocouple. Aspirates were taken from vaccination sites weekly, and smears were submitted for cytologic analysis. There were no significant differences in lesion surface temperature among injection sites at any time. Injections of saline solution and FeLV vaccine resulted in no palpable lesions. The FRCPV vaccine elicited a minor reaction in 1 of the 9 cats. The RV vaccine caused palpable lesions in all cats. Smears of the aspirates from the sites of saline injection were poorly cellular. Cellularity of aspirates from the sites of FRCPV and FeLV vaccinations was moderate at week 1, and decreased with time. Inflammatory infiltrates were composed principally of lymphocytes, with fewer neutrophils and macrophages. In contrast, cellularity of aspirates from RV vaccination sites increased for 21 days and was characterized by increasing numbers of lymphocytes and macrophages. RV vaccine used in this study induced palpable lesions in many cats. In contrast, FRCPV and FeLV vaccines elicited less severe lesions. Subcutaneous administration of killed virus vaccines in cats may result in palpable lesions that are detected by clients or clinicians. Aspiration cytologic examination may reveal a different characteristic pattern of cells that is dependent on the individual vaccine and time elapsed from vaccination.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9225475", "author": "Courchamp F", "n_authors": 4, "title": "Dynamics of two feline retroviruses (FIV and FeLV) within one population of cats.", "abstract": "We present a deterministic model of the dynamics of two microparasites simultaneously infecting a single host population. Both microparasites are feline retroviruses, namely Feline Immunodeficiency Virus (FIV) and Feline Leukaemia Virus (FeLV). The host is the domestic cat Felis catus. The model has been tested with data generated by a long-term study of several natural cat populations. Stability analysis and simulations show that, once introduced in a population, FIV spreads and is maintained, while FeLV can either disappear or persist. Moreover, introduction of both viruses into the population induces an equilibrium state for individuals of each different pathological class. The viruses never induce the extinction of the population. Furthermore, whatever the outcome for the host population (persistence of FIV only, or of both viruses), the global population size at the equilibrium state is only slightly lower than it would have been in the absence of the infections (i.e. at the carrying capacity), indicating a low impact of the viruses on the population. Finally, the impact of the diseases examined simultaneously is higher than the sum of the impact of the two diseases examined separately. This seems to be due to a higher mortality rate when both viruses infect a single individual.", "journal": "Proceedings. Biological sciences", "doi": "10.1098/rspb.1997.0111", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9247693", "author": "Court EA", "n_authors": 3, "title": "Retrospective study of 60 cases of feline lymphosarcoma.", "abstract": "To characterise epidemiological and clinical findings, and diagnostic procedures undertaken, in cats with lymphosarcoma at a veterinary teaching hospital. Retrospective case study. Hospital records were reviewed for 7159 cats, sick or healthy, examined during a 10-year period (1984 to 1994). Sixty cats with lymphosarcoma were identified and classified by anatomical location of the tumor. Data on breed, age, sex, clinical signs and diagnostic procedures were collated. The prevalence of feline lymphosarcoma in the hospital population was 0.84%. Siamese cats appeared predisposed to lymphosarcoma but other purebreds were not. Males were somewhat overrepresented amongst affected cats. Similar numbers of cases (12 to 18) were seen in each of the four anatomic categories (multicentric, mediastinal, alimentary and extranodal). Cats with mediastinal lymphosarcoma were mostly young and Siamese. Clinical signs in affected cats were varied, usually multiple and often nonspecific. Two of 22 cases tested positive for feline leukaemia virus antigen in blood and 6 of 13 were positive for feline immunodeficiency virus antibody. Extranodal lymphosarcoma seemed more prevalent in this study than reported elsewhere. Siamese cats in the study population may have had a genetic predisposition to lymphosarcoma. Limited evidence suggested feline leukaemia virus may be less important, and feline immunodeficiency virus more important, in the local population than indicated in overseas reports. Additional studies are needed to investigate breed predisposition and feline leukaemia virus and feline immunodeficiency virus status in Australian cats with lymphosarcoma.", "journal": "Australian veterinary journal", "doi": "10.1111/j.1751-0813.1997.tb14347.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9200065", "author": "Fails AD", "n_authors": 4, "title": "An oligopeptide of the feline leukemia virus envelope glycoprotein is associated with morphological changes and calcium dysregulation in neuronal growth cones.", "abstract": "Neuropathogenic processes that affect the pathfinding properties of neuronal growth cones could account for many of the dysfunctions unique to retroviral infection of developing nervous systems. Pediatric HIV-1 infection, for example, is associated with a distinctive neuropathogenesis that includes marked cortical atrophy, cognitive disorders, and pyramidal dysfunction. The ability of HIV's envelope glycoprotein, gp120, to produce increased intracellular free calcium ([Ca2+]i) leading to neuronal death has been documented. We hypothesize that gp120 and the envelope glycoproteins of other retroviruses may have similar calcium-increasing effects in advancing growth cones, a property which could disrupt the orderly development of the nervous system. To explore this possibility, we exposed chick ciliary ganglion neurons in culture to a known cytopathic region (CVR5) of the feline leukemia virus' envelope glycoprotein. CVR5 produced [Ca2+]i increases and dose-dependent morphological changes in growth cones isolated from their cell bodies by axotomy. These responses of growth cones to CVR5 suggest that the neurotoxic effects of retroviruses could be mediated at the level of the individual growth cone through exposure to envelope glycoproteins and could constitute one mechanism by which these viruses perturb the normal development of the nervous system.", "journal": "Journal of neurovirology", "doi": "10.3109/13550289709018292", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9289888", "author": "Block A", "n_authors": 4, "title": "[Placebo-controlled double-blind study on the efficacy of a paramunity inducer in the treatment of naturally FeLV-infected cats].", "abstract": "The study involved 120 cats, of which 60 were treated with Baypamun HK and 60 cats received a preparation of virus free cell culture medium. Therapeutic efficacy was determined by monitoring the general status of health, body weight, skin, lymph nodes, oral cavity, the presence of the p27 antigen and the FeLV p27 antigen concentration in serum. No statistically significant differences between both groups could be demonstrated neither for clinical nor for virologic parameters. Remission of the viremia occurred in 11.7% of the cats treated with Baypamun HK and in 6.7% of the cats treated with placebo. The FeLV p27 antigen level decreased by an average of 7.2% with Baypamun HK and by an average of 5.1% with placebo.", "journal": "Tierarztliche Praxis", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9196815", "author": "Malik R", "n_authors": 7, "title": "Prevalences of feline leukaemia virus and feline immunodeficiency virus infections in cats in Sydney.", "abstract": "To determine prevalences of feline leukaemia virus (FeLV) and feline immunodeficiency virus (FIV) infections in 'healthy' cats that, through acute misadventure or other circumstance, were presented to veterinary practitioners. Prevalences of FeLV and FIV in this population were compared to those in a population of predominantly sick cats. Serum specimens were obtained over a 2-year period from 200 cats older than 1 year of age presented to veterinary clinics for routine procedures, including cat fight injuries or abscesses, vehicular trauma, neutering, dental scaling, vaccination, grooming or boarding. An additional 894 sera were obtained over approximately the same period from specimens submitted by veterinarians to a private clinical pathology laboratory, mainly from sick cars suspected of having immune dysfunction, but including some sera from healthy cats being screened prior to FeLV vaccination. FIV antibody and FeLV antigen were detected in samples using commercial enzyme immunoassays. Amongst 200 'healthy' cats, the prevalence of FeLV infection was 0 to 2%, and the prevalence of FIV was 6.5 to 7.5%, depending on the stringency of the criteria used to define positivity. FIV infection was significantly more prevalent in cats which resided in an inner city environment (P = 0.013). Of the 894 serum specimens submitted to the laboratory by practitioners, 11/761 (1.4%) were FeLV positive, while 148/711 (20.8%) were FIV positive. The prevalence of FIV was significantly higher in these predominantly 'sick' cats than in cats seen for routine veterinary procedures (P < 0.00001), while there was no difference in the prevalence of FeLV (P = 0.75) The prevalence of FeLV and FIV in healthy cats may have been substantially overestimated in some previous Australian surveys. FeLV infection would appear to be a rare cause of disease in Australian cats. The higher prevalence of FIV positivity in sick as opposed to healthy cats infers that FIV infection contributes to the development of disease.", "journal": "Australian veterinary journal", "doi": "10.1111/j.1751-0813.1997.tb15701.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9179815", "author": "Sparkes AH", "n_authors": 1, "title": "Feline leukaemia virus: a review of immunity and vaccination.", "abstract": "The availability feline leukaemia virus (FeLV) vaccines has added a new and important dimension to the control of this infectious agent. FeLV vaccination is a controversial issue, however, partly because of differences in the formulation between the current products, partly because of conflicting claims by vaccine manufactures and partly because experimental trials have shown that none of the vaccines provides 100 per cent protection against infection. This paper reviews the role of the immune response in determining the outcome following exposure to FeLV and describes the importance of FeLV subgroups. The five commercial FeLV vaccines currently available in the USA and Europe are described and the published literature on efficacy studies is summarised. However, these efficacy studies are often difficult to interpret for various reasons, including the small numbers of animals used; differences in challenge methods, vaccine strains and vaccine dose employed; and differences in postchallenge monitoring protocols.", "journal": "The Journal of small animal practice", "doi": "10.1111/j.1748-5827.1997.tb03339.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9179747", "author": "Holznagel E", "n_authors": 4, "title": "Feline immunodeficiency virus (FIV) infection in cats at necropsy: a serological study.", "abstract": "Sera collected post mortem during a 6-month period from cats were tested for feline immunodeficiency virus (FIV)-specific antibodies by (1) an enzyme-linked immunosorbent assay (ELISA), (2) an indirect peroxidase-based immunocytological test (IP), (3) a Western immunoblotting (WB) method with FIV-infected cell lysates, and (4) a WB method with purified viral antigen. All four methods were capable of detecting FIV-specific antibodies in haemolysed sera. However, the ELISA showed the lowest \"positive predictive value\" (PVpos = 22%) followed by the IP (PVpos 50-60%). Serum was FIV antibody-positive in 6% (15/255) of all cats examined. The mean age of seropositive cats was 9 years (4 years among seronegative cases) and the male-to-female ratio in such cats was 1.8 to 1 (overall ratio 0.8 to 1). Forty per cent of the seropositive cats were in the final phase of acquired immune deficiency syndrome. Feline leukaemia virus (FeLV) predominated among viral co-infections. It was concluded that (1) a combination of the IP and WB reliably detected FIV-specific antibodies in sera collected post mortem, and (2) at post-mortem examination, cats from high-risk groups (male, > 5 years old, hypercellular bone marrow) were frequently infected with FIV.", "journal": "Journal of comparative pathology", "doi": "10.1016/s0021-9975(97)80051-5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9209353", "author": "Levy LS", "n_authors": 4, "title": "Cooperating events in lymphomagenesis mediated by feline leukemia virus.", "abstract": "Feline leukemia virus (FeLV)-mediated lymphomagenesis in the domestic cat has been examined as a model of lymphoid malignancy in a naturally outbreeding population. The pathogenesis of two distinct, naturally occurring types of FeLV-induced tumors has been investigated: (1) a thymic lymphoma of T-cell origin, typical of FeLV-induced lymphoma, and (2) an extrathymic, extranodal lymphoma of non-B non-T-cell origin. The genetic features of these tumors are clearly distinguishable, and include determinants encoded both by the virus and the host. Virally encoded determinants of pathogenesis include the long terminal repeat (LTR) and the envelope SU protein. Cellular determinants include the involvement of a set of proto-oncogenes, and other factors characteristic of the specific cell type of origin of the tumor. Functional studies are aimed at evaluating the action and interaction of these genetic determinants in the pathogenesis of lymphoma in an animal model system.", "journal": "Leukemia", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9209339", "author": "Nishigaki K", "n_authors": 7, "title": "Regulation of gene expression directed by the long terminal repeats of feline leukemia viruses.", "abstract": "Repetitive structure of enhancer elements in the long terminal repeat (LTR) has been identified in feline leukemia viruses (FeLVs) integrated in lymphoid tumor cells in cats. In this study, promoter activities of the FeLV LTRs were measured in lymphoid and non-lymphoid cell lines in transient expression assays using plasmids containing the viral LTRs linked to the chloramphenicol acetyltransferase (CAT) gene. Promoter activity of the LTR with 3 enhancer repeats (pFTLTR) was significantly higher than that of the LTR with 1 enhancer (Glasgow-1 LTR) in feline (FT-1) and human (Jurkat) T-lymphoblastoid cell lines. Promoter activity of the pFTLTR was also significantly higher than that of its mutant (pFTLTR1E) in which 2 of the 3 enhancers were deleted in FT-1 and Jurkat cells. Both of these differences were not observed in a feline fibroblastic cell line (CrFK). Moreover, mutations affecting the consensus motifs for LVb, SV40, NF-1, GRE and FLV-1 resulted in decreased basal activity of the FeLV LTR (pFTLTR1E) in FT-1, Jurkat and CRFK cells. The decrease of the promoter activity was especially remarkable in FT-1 cells. The present study revealed the strong promoter activity of the FeLV LTR with 3 enhancer repeats and its modular enhancer elements positively regulating the transcription in a relatively tissue-specific manner.", "journal": "Leukemia", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9111472", "author": "Mitchell TW", "n_authors": 7, "title": "FeLV envelope protein (gp70) variable region 5 causes alterations in calcium homeostasis and toxicity of neurons.", "abstract": "In humans and animals, retroviruses have been implicated in nervous system disease. Our objective was to characterize the neurotoxicity of a peptide sequence derived from an animal retrovirus, the feline leukemia virus (FeLV). Using a peptide sequence from the subtype FeLV-C envelope protein variable region 5 (VR5), cytotoxicity was demonstrated in studies that evaluated neuronal survival, neurite outgrowth, and alterations in intracellular calcium ion concentration. The FeLV subtype isolate FeLV-CSarma possesses an envelope protein VR5 amino acid sequence that varies by four amino acids from the VR5 amino acid sequence of subtype FeLV-AGlasgow. The polypeptide representing the VR5 of FeLV-CSarma (FeLV-CVR5) is significantly more neurotoxic than the polypeptide sequence representing the VR5 of FeLV-AGlasgow (FeLV-AVR5). FeLV-CVR5 (> or = 3 microM) exposure resulted in significant dose-dependent neurotoxicity. Antibodies to FeLV-CVR5 blocked this effect. Neurite outgrowth was significantly reduced at all tested concentrations (3-12 microM) of FeLV-CVR5, with a 92% reduction in neurite length at 12 microM. FeLV-AVR5 was significantly less neurotoxic with respect to neurite outgrowth than was FeLV-CVR5. The significant reduction in neurotoxicity for FeLV-AVR5 illustrates the importance of the 4-amino-acid difference between it and FeLV-CVR5. Alterations in intracellular calcium ion concentration were associated with this neurotoxicity.", "journal": "Journal of acquired immune deficiency syndromes and human retrovirology : official publication of the International Retrovirology Association", "doi": "10.1097/00042560-199704010-00002", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9054996", "author": "Levy MS", "n_authors": 4, "title": "Nonlymphoid vertebral canal tumors in cats: 11 cases (1987-1995).", "abstract": "To determine outcome of cats with nonlymphoid tumors of the vertebral canal that undergo surgery. Retrospective study. 11 cats. Information obtained from the medical records included signalment, tumor location, gross evaluation of completeness of surgical excision, histologic diagnosis, and survival time. Median age of cats was 12 years: all cats had negative FeLV and feline immunodeficiency virus test results. All cats underwent a hemilaminectomy or dorsal laminectomy. The tumor was located in the thoracic portion of the vertebral column in 6 cats. Six cats had intradural-extramedullary tumors. Tumors included meningioma (n = 5), malignant nerve sheath tumors (2), and meningeal sarcoma, chondrosarcoma, lipoma, and osteosarcoma (1 each). One cat was lost to follow-up, 1 cat with meningioma was alive 1,400 days after surgery, and 1 cat with a nerve sheath tumor was alive 2,190 days after surgery. Median survival time for the other 4 cats with meningioma was 180 days (range, 30 to 600 days). Cats with nonlymphoid vertebral canal tumors that undergo surgery may have a good prognosis.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "21433345", "author": "Coffin JM", "n_authors": 5, "title": "Immunological and Pharmacological Approaches to the Control of Retroviral Infections.", "abstract": null, "journal": null, "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "12658601", "author": "Latimer KS", "n_authors": 5, "title": "Disseminated Mycobacterium avium complex infection in a cat: presumptive diagnosis by blood smear examination.", "abstract": "Disseminated mycobacteriosis was diagnosed in a 4-year-old, castrated male Domestic Shorthair cat following the observation of one to three retractile, non-staining bacilli in neutrophils and monocytes on a Wright-Leishman-stained blood smear Organisms were bright red following acid-fast staining by Kinyoun's technique. The cat had a history of progressive weight loss, anemia, fever, and sporadic vomiting after eating. In addition to blood smears, mycobacteria also were observed in bone marrow aspirates. During necropsy, multiple small white nodules were observed in the spleen and liver. An enlarged sternal lymph node and ascites also were present. In histologic sections, mycobacteria were observed in granulomas within the lungs, liver, spleen, colon, mesenteric and sternal lymph nodes, omentum, and kidney. Mycobacterium avium complex was isolated from cultures of liver, spleen, lung, and kidney. Occult feline leukemia virus infection, detected by immunofluorescent testing of bone marrow aspirates, may have predisposed this cat to bacterial infection. The serum ELISA test for group-specific feline leukemia virus antigen was negative.", "journal": "Veterinary clinical pathology", "doi": "10.1111/j.1939-165x.1997.tb00716.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9344336", "author": "Hishikawa T", "n_authors": 12, "title": "Detection of antibodies to a recombinant gag protein derived from human endogenous retrovirus clone 4-1 in autoimmune diseases.", "abstract": "To investigate whether human endogenous retroviruses (HERV) contribute to autoimmune diseases, we prepared a recombinant p30gag protein derived from clone 4-1 of the HERV family, using a baculovirus-vector system. This p30gag protein (CA41B) was approximately 30 kDa, as expected, and reacted with antibodies for p30gag purified from both murine and feline leukemia virus. This result suggested that the antigenic determinant for p30gag was well conserved in CA41B. Analysis of serum antibodies to p30gag in patients with autoimmune diseases was done by Western blotting. CA41B detected anti-p30gag antibodies in 48.3% of systemic lupus erythematosus (SLE) patients, 35.0% of Sjögren's syndrome (SS) patients, and 33.3% of mixed connective tissue disease (MCTD) patients, whereas no anti-p30gag antibodies were found in healthy subjects. This suggested that HERV p30gag or other retroviral p30gag proteins possessing the same antigenic determinant as CA41B may play a role in these diseases. Although detection of antibodies to HERV p30gag in autoimmune diseases is indirect evidence that HERV proteins are involved, this study showed that patients with autoimmune diseases have antibodies to HERV p30gag using a recombinant HERV protein rather than synthetic peptides based on HERV or retroviral proteins of other species.", "journal": "Viral immunology", "doi": "10.1089/vim.1997.10.137", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9132477", "author": "Jacobs GJ", "n_authors": 4, "title": "Cryptococcal infection in cats: factors influencing treatment outcome, and results of sequential serum antigen titers in 35 cats.", "abstract": "The relationship between treatment outcome and location of cryptococcal infection, gender, magnitude of pretreatment cryptococcal antigen titers, results of feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) serology, and serial changes in antigen titers during and after treatment were evaluated in a prospective and nonrandomized study of 35 cats with cryptococcosis. A commercial cryptococcal latex agglutination kit (CALAS; Meridian Diagnostic Inc, Cincinnati, OH) was used to detect cryptococcal antigen in sera. All cats were treated with itraconazole (Sporanox; Janssen Pharmaceutica Inc, Titusville, NJ). Pretreatment mean log titers for serum cryptococcal antigen were not influenced by location of the infection. Treatment outcome was not influenced by gender, location of the infection, or magnitude of pretreatment serum antigen titer. Treatment outcome was influenced by FeLV and FIV status; cats seropositive for FeLV or FIV had a higher likelihood of treatment failure (P = .008). The cryptococcal antigen titers of cats successfully treated decreased with significant linearity over time during treatment (r = -.64, P < .000001), whereas the corresponding titers for cats not treated successfully did not decrease with significant linearity (r = -.03, P > .9). For cats in which treatment was successful, antigen titers decreased significantly from pretreatment values by 1.3 orders of magnitude at 2 months after initiation of treatment. By 10 months after initiating treatment, log titers decreased by at least 2 orders of magnitude in all cats successfully treated, and 9 of 16 cats had undetectable titers. In contrast, in 5 of 6 cats in which treatment failed, antigen titers were unchanged or increased in magnitude even after at least 6 months of treatment.", "journal": "Journal of veterinary internal medicine", "doi": "10.1111/j.1939-1676.1997.tb00064.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9125046", "author": "Miyazawa T", "n_authors": 2, "title": "Feline leukaemia virus proviral DNA detected by polymerase chain reaction in antigenaemic but non-viraemic ('discordant') cats.", "abstract": "A nested polymerase chain reaction (PCR) was established to detect exogenous feline leukaemia virus (FeLV) proviral DNA in feline peripheral blood leukocytes (PBL). The assay detected a single copy of plasmid DNA of an infectious molecular clone of FeLV subgroup A in the sample by ethidium bromide staining in agarose gels. The utility of the nested PCR in the diagnosis of FeLV infections was compared with the detection of FeLV p27 antigen by enzyme-linked immunosorbent assay (ELISA) and virus isolation (VI). FeLV genomes were detected by PCR in all 4 samples that were positive by ELISA and VI but in none of 7 samples that were negative by the two methods. FeLV genomes were found by PCR in 13 of 39 samples from cats that were antigenaemic but from which no virus was isolated ('discordant' cats). These results demonstrated that a proportion of discordant cats harboured FeLV genome in their PBL.", "journal": "Archives of virology", "doi": "10.1007/s007050050079", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9008278", "author": "Hofmann-Lehmann R", "n_authors": 4, "title": "Parameters of disease progression in long-term experimental feline retrovirus (feline immunodeficiency virus and feline leukemia virus) infections: hematology, clinical chemistry, and lymphocyte subsets.", "abstract": "After several years of latency, feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) cause fatal disease in the cat. The aim of this study was to determine laboratory parameters characteristic of disease progression which would allow a better description of the asymptomatic phase and a better understanding of the pathogenesis of the two infections. Therefore, experimentally infected cats (FIV and/or FeLV positive) and control animals were observed over a period of 6.5 years under identical conditions. Blood samples were analyzed for the following: complete hematology, clinical chemistry, serum protein electrophoresis, and determination of CD4+ and CD8+ lymphocyte subsets. The following hematological and clinical chemistry parameters were markedly changed in the FIV-infected animals from month 9 onwards: glucose, serum protein, gamma globulins, sodium, urea, phosphorus, lipase, cholesterol, and triglyceride. In FeLV infection, the markedly changed parameters were mean corpuscular volume, mean corpuscular hemoglobin, aspartate aminotransferase, and urea. In contrast to reports of field studies, neither FIV-positive nor FeLV-positive animals developed persistent leukopenia, lymphopenia, or neutropenia. A significant decrease was found in the CD4+/CD8+ ratio in FIV-positive and FIV-FeLV-positive animals mainly due to loss of CD4+ lymphocytes. In FeLV-positive cats, both CD4+ and, to a lesser degree, CD8+ lymphocytes were decreased in long-term infection. The changes in FIV infection may reflect subclinical kidney dysfunction, changes in energy and lipid metabolism, and transient activation of the humoral immune response as described for human immunodeficiency virus (HIV) infections. The changes in FeLV infection may also reflect subclinical kidney dysfunction and, in addition, changes in erythrocyte and immune function of the animals. No severe clinical signs were observed in the FIV-positive cats, while FeLV had a severe influence on the life expectancy of persistently positive cats. In conclusion, several parameters of clinical chemistry and hematology were changed in FIV and FeLV infection. Monitoring of these parameters may prove useful for the evaluation of candidate FIV vaccines and antiretroviral drugs in cats. The many parallels between laboratory parameters in FIV and HIV infection further support the importance of FIV as a model for HIV.", "journal": "Clinical and diagnostic laboratory immunology", "doi": "10.1128/cdli.4.1.33-42.1997", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "8977651", "author": "Quesnel AD", "n_authors": 5, "title": "Diagnostic evaluation of cats with seizure disorders: 30 cases (1991-1993).", "abstract": "To investigate causes of seizure disorders in cats. Case series. 30 cats referred to the Ontario Veterinary College for recurrent seizures. Signalment and seizure pattern were evaluated. Diagnostic procedures included physical, neurologic, and fundic examinations; CBC; serum biochemical analyses, including determination of pre- and postprandial bile acid concentrations; urinalysis; serologic assays for FeLV and feline immunodeficiency virus, feline infectious peritonitis, and Toxoplasma gondii, magnetic resonance imaging of the brain; CSF analysis; and neuropathologic examination of euthanatized cats and of surgical biopsy specimens. All cats were found to have structural brain diseases; nonsuppurative meningoencephalitis of unknown cause was found in 14 cats, feline ischemic encephalopathy in 6, meningioma in 2, polycythemia vera with secondary brain lesions in 2, posttraumatic epilepsy in 1, and cerebral abscess in 1. A definitive diagnosis could not be reached in 4 cats. The most common cause of seizures in cats is structural brain disease. Structural brain lesions often can be detected on the basis of seizure pattern and results of neurologic examination. Cerebrospinal fluid analysis and brain imaging are essential to determine the cause of these lesions. Causes of seizures found in the cats of this study differ from those reported to be the most common. Nonsuppurative meningoencephalitis of unknown origin appears to be a frequent cause of neurologic disorders in cats, including seizure disorders. Feline ischemic encephalopathy appears to exist in a milder form than the classic disease and may be a common cause of seizures in cats.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "8977647", "author": "Buffington CA", "n_authors": 7, "title": "Clinical evaluation of cats with nonobstructive urinary tract diseases.", "abstract": "To identify the underlying cause of clinical signs in cats with nonobstructive diseases of the bladder and urethra. Prospective case series. 109 cats examined by the urology service of The Ohio State University's veterinary teaching hospital because of stranguria, hematuria, pollakiuria, or urination in inappropriate locations. History was obtained and a CBC, serum biochemical analyses, serologic tests for FeLV and feline immunodeficiency virus, urinalysis, bacterial culture of urine, and contrast radiography or urethrocystoscopy (females only) were performed. 16 cats had cystic calculi: 8 had struvite uroliths, 7 had calcium oxalate uroliths, and 1 had a urolith of unknown composition in conjunction with an anatomic defect. Anatomic defects, including diverticulae, urethral strictures, and a malpositioned urethra, were identified in 12 cats. A urinary tract infection was identified in 1 cat, and neoplasia was diagnosed in 2. One of the cats with neoplasia also had a struvite urolith. The remaining 80 cats did not have an anatomic defect, urolith, or tumor. Ten of these cats also did not have radiographic or cystoscopic abnormalities and were presumed to have a behavioral disorder. The remaining 70 cats had radiographic or cystoscopic abnormalities, and idiopathic cystitis was diagnosed. In 14 of the cats with idiopathic cystitis, results of a urinalysis were normal. Cats with idiopathic cystitis were significantly more likely to eat dry food exclusively (59%) than were cats in the general population (19%). Results suggest that idiopathic cystitis occurs commonly in cats with stranguria, hematuria, pollakiuria, or inappropriate elimination and is associated with consumption of dry foods. Contrast radiography or cystoscopy is necessary for differentiating idiopathic cystitis from behavioral disorders in some cats.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "11397230", "author": "Cullen CL", "n_authors": 5, "title": "The use of immunohistochemistry and the polymerase chain reaction for detection of feline leukemia virus and feline sarcoma virus in six cases of feline ocular sarcoma.", "abstract": "Ocular sarcoma was diagnosed by light microscopic examination in enucleated globes (n = 4), orbital tissue biopsy (n = 1) and ocular evisceration contents (n = 1) from six cats. To determine if feline leukemia virus (FeLV) or a replication-defective FeLV, feline sarcoma virus (FeSV), was present in these ocular sarcomas, immunohistochemistry (IHC) and polymerase chain reaction (PCR) for FeLV were utilized. Immunohistochemical staining for FeLV glycoprotein 70 (gp70) was performed on all six formalin-fixed, paraffin-embedded tumors using an avidin-biotin complex technique. DNA was extracted from each specimen and a 166 bp region of the FeLV long-terminal repeat (LTR) was amplified by PCR. All tumors were composed primarily of spindle cells; two neoplasms had PAS-positive basement membrane enveloping areas of spindle cells. All tumors involved the uvea and five of six tumors showed transcleral extension, one of which invaded the optic nerve. Immunohistochemical staining for FeLV gp 70 was negative. PCR to amplify a portion of the FeLV LTR was negative. Based on these findings of these limited number of cases, FeLV/FeSV may not play a role in the tumorigenesis of feline ocular sarcomas. However, additional tumors representing all morphological subtypes should be investigated for the presence of viral antigen and DNA. It is important to determine the etiology and pathogenesis of these malignant ocular sarcomas. If the cell of origin and pathogenesis involve ocular and lenticular injury, and FeLV/FeSV is not present, then the clinical management of cases of feline ocular trauma, uveitis and glaucoma may prevent the development of this tumor.", "journal": "Veterinary ophthalmology", "doi": "10.1046/j.1463-5224.1998.00035.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9880939", "author": "Mischke R", "n_authors": 1, "title": "[Cyclosporin A therapy in a cat with pure red cell aplasia].", "abstract": "The case of a one year and 7 months old castrated male cat suffering from severe, non regenerative anaemia (packed cell volume: 8.6%; reticulocyte count: 1/1000) is presented. A combined ELISA-test for feline leukaemia virus antigen and antibodies against feline immunodeficiency virus was negative. Using indirect Coomb's test IgM as well as the complement component C3b could be demonstrated on the erythrocytes. Cytological investigation of the bone marrow revealed a selective, nearly complete aplasia of the erythropoiesis. Immunosuppressive therapy with cyclosporin A (6.25 mg/kg BW orally, twice daily) and prednisolone (initially 5 mg/kg BW intravenously, twice daily) from the 9th day on led to a distinct regeneration of erythropoiesis with reticulocyte counts up to 126/1000 (341.000/microliter) and normalisation of the red blood picture as well as the general state of health. The therapy with cyclosporin A was continued for five months, reducing the dosis after 30 days to 6.25 mg/kg BW orally once daily corresponding to an extremely high blood level of cyclosporine A. At control examinations 24 and 63 days after depositing therapy all parameters of the red blood picture were within the reference range. This case report indicates that pure red cell aplasia can be due to an autoimmune process in cats also as well.", "journal": "Berliner und Munchener tierarztliche Wochenschrift", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9878855", "author": "Rudra-Ganguly N", "n_authors": 3, "title": "Retrovirus receptor PiT-1 of the Felis catus.", "abstract": "We isolated a cDNA encoding a feline homolog of human PiT-1, a sodium-dependent phosphate symporter which is utilized by gibbon ape leukemia virus (GALV) as a receptor for entry into host cells. The overall homology between the human and feline receptors is 92 and 93% at the nucleotide and deduced amino acid levels, respectively. Hydropathy analyses implied ten potential membrane spanning regions and, in analogy to human and murine homologs, five extracellular and four intracellular loops. Strikingly, the amino acid sequence of the fourth extracellular loop, which is critical for GALV surface glycoprotein binding, has complete identity between the human and feline PiT-1s, while the mouse PiT-1, non-functional for GALV entry, is quite divergent. Ectopic expression of the feline PiT-1 in guinea pig cells, which are non-permissive to feline leukemia virus (FeLV), subgroup B virus, conferred susceptibility to FeLV-B infection confirming the functional ability of the cloned product to serve as a receptor for a natural retrovirus of the homologous species.", "journal": "Biochimica et biophysica acta", "doi": "10.1016/s0167-4781(98)00241-3", "deposited_data": "Sim", "nuccore_ids": "57618977, 4185263, 2130930383, 2130930380, 57618977", "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9870370", "author": "Svobodová V", "n_authors": 3, "title": "Prevalence of IgG and IgM antibodies specific to Toxoplasma gondii in cats.", "abstract": "IgG and IgM antibodies specific to Toxoplasma gondii were determined simultaneously by IFAT in cats. Group 1 included 357 cats with various diagnoses, but negative for FeLV and FIV. Specific IgG antibodies in titres ranging from 10 to 2560 (mean 247) were detected in 61.3% animals, specific IgM antibodies were found only in one cat (0.28%) in titre 1:40 showing an IgG titre of 160. Oocyst shedding was demonstrated in one cat (0.28%) showing an IgG titre of 1:40. Group 2 included 33 cats positive for FeLV or FIV. IgG antibodies in titres ranging from 10 to 640 (mean 101) were found in 63.6% cats. Neither IgM antibodies nor shedding of T. gondii oocysts were detectable. Clinically unapparent toxoplasmosis, manifested by the presence of IgG antibodies is frequent in cats; the opportunistic character of the infection is important.", "journal": "Veterinary parasitology", "doi": "10.1016/s0304-4017(98)00201-5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9853314", "author": "Miyazawa T", "n_authors": 12, "title": "Seroepidemiological survey of feline retrovirus infections in domestic and leopard cats in northern Vietnam in 1997.", "abstract": "The prevalence of infections with three feline retroviruses (feline immunodeficiency virus (FIV), feline leukemia virus (FeLV) and feline syncytial virus (FSV)) was examined in northern Vietnam in 1997. We collected a total of 77 blood samples from 69 domestic and 8 leopard cats, and examined the presence of anti-FIV and FSV antibodies and FeLV p27 antigen in the plasma samples by the indirect immunofluorescence and/or two commercial kits. None of the samples was positive for FIV and FeLV. The overall positive rate of FSV was 31% and the positive rates among the domestic and leopard cats were 29 and 50%, respectively. We isolated FSV from peripheral blood mononuclear cells of 6 domestic and one leopard cats.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.60.1273", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9839881", "author": "Hofmann-Lehmann R", "n_authors": 5, "title": "Feline immunodeficiency virus (FIV) infection leads to increased incidence of feline odontoclastic resorptive lesions (FORL).", "abstract": "Feline odontoclastic resorptive lesions (FORL), previously known as 'neck lesions,' are commonly known in domestic, but also in non-domestic cats. They are characterized by odontoclastic resorptive processes, which take place at the dental root and at the periodontium. Chronic inflammation of gingiva and periodontium is believed to be an important etiological factor in the development of FORL. In this context, various feline viruses have been discussed to play a relevant role in the pathogenesis of these lesions. The aim of this project was to determine in a blinded study the incidence of FORL in 10 cats which were infected for several years with feline immunodeficiency virus (FIV), but were otherwise free of feline viral infections (feline leukemia virus, feline calicivirus, feline herpesvirus, feline parvovirus, feline coronavirus, feline syncytium-forming virus). Nine age-matched controls were kept under identical conditions, but free of FIV. Subgingival resorptive lesions were found in six of 10 FIV-positive cats, but in three of nine controls only. FIV-positive cats had significantly more often gingivae with an increased tendency for bleeding upon probing than FIV-negative cats (p=0.0055), and they had slightly more often hyperplastic gingivae (p=0.0867). In conclusion, signs characteristic of FORL such as subgingival lesions, granulomatous or hyperplastic gingivae with a tendency for bleeding, were found significantly more often in FIV-positive cats than in the controls (p=0.0198). Therefore, it was concluded that FIV infection is an important factor for the occurrence of FORL, possibly through immune suppression or changes of the (sub)gingival micro-environment. However, non-infected control cats also showed some evidence of FORL in the absence of all tested viral infections. Therefore, factors other than viral infections must also play a role in the development of FORL in cats.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/s0165-2427(98)00163-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9839879", "author": "Hartmann K", "n_authors": 6, "title": "Treatment of feline leukemia virus-infected cats with paramunity inducer.", "abstract": "Two placebo-controlled double-blind trials were performed to determine the therapeutic efficacy of the paramunity inducer, Baypamun in feline leukemia virus (FeLV)-infected cats under controlled conditions. In the first study, 120 cats were involved; 60 cats were treated with Baypamun and 60 with a placebo preparation of virus-free cell culture medium. Dosage and administration of the drug over a 7-week period were performed according to the instructions given by the company. Remission of viremia occurred in 12% and 7% of the cats treated with Baypamun and placebo, respectively. This difference was not statistically significant. In the second study, 30 naturally infected cats were treated in a placebo-controlled double-blind trial. In total, 20 immunological, clinical, laboratory, and virological parameters were examined. No statistically significant differences could be demonstrated between Baypamun and placebo application. Therefore, FeLV infection was not influenced by Baypamun treatment.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/s0165-2427(98)00161-5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9823600", "author": "Fondevila D", "n_authors": 3, "title": "Primary central nervous system T-cell lymphoma in a cat.", "abstract": "A 5-year-old intact male Persian cat was presented with progressive neurologic deficits, hyperesthesia, hyperreflexia, ataxia, and intention tremors, which resulted in death. Serologic tests for feline leukemia virus and feline immunodeficiency virus infection were negative. Neurohistologic examination revealed the presence of pleomorphic cellular infiltrates in cerebral leptomeninges and around parenchymal vessels. The majority of infiltrating cells were uniformly immunostained using an antiserum directed against T cells. Immunohistochemical examination of paraffin-embedded brain sections for the antigens of canine distemper virus, herpesvirus, Borna virus, and Toxoplasma gondii were negative. Histologic and immunohistochemical studies revealed a primary central nervous system T-cell lymphoma affecting the brain.", "journal": "Veterinary pathology", "doi": "10.1177/030098589803500613", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9820570", "author": "Malmsten A", "n_authors": 7, "title": "A colorimetric reverse transcriptase assay optimized for Moloney murine leukemia virus, and its use for characterization of reverse transcriptases of unknown identity.", "abstract": "A non-radioactive reverse transcriptase (RT) assay, reported as useful for lentivirus RTs, was optimized for the measurement of Moloney murine leukemia virus (MMuLV) RT. The optimized assay could detect 0.3 microU of MMuLV RT. The specificities of the MMuLV and lenti RT assays were demonstrated using the RTs of human immunodeficiency virus type 1, simian immunodeficiency virus, feline immunodeficiency virus (FIV), visna virus, human T-cell lymphotropic virus type 1, MMuLV and feline leukemia virus (FeLV). An RT activity blocking antibody (RTb-ab) assay was standardized for Mn2+ dependent MuLV-related RTs. The assay was used to demonstrate the distinct antigenic properties of RTs from mammalian MuLV-related retroviruses and lentiviruses. Cross-reactivity between MMuLV RTb-ab and FeLV RT but not between MMuLV RTb-ab and e.g. FIV RT was demonstrated. An RT activity found in the murine myeloma cell line SP2/0 was found to have similar assay preferences as MMuLV RT, and the MMuLV-RT hyperimmune sera reacted strongly against this RT, indicating the RT to be of MuLV-related etiology. The use of the RT and RTb-ab assays for detection and characterization of RTs of known or unknown identity is discussed.", "journal": "Journal of virological methods", "doi": "10.1016/s0166-0934(98)00091-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9820144", "author": "DeHaven JE", "n_authors": 7, "title": "Novel retroviral sequences are expressed in the epididymis and uterus of Syrian hamsters.", "abstract": "Combined androgen and oestrogen treatment of male or female Syrian hamsters results via an unknown mechanism in the formation of leiomyosarcomas in the reproductive tract. We have examined the possibility that retroviral gene expression may play a role in tumorigenesis. Evidence of virus-like particles in epididymis and seminal fluid is shown in electron micrographs. We identified expressed retroviral sequences by using RT-PCR to amplify a conserved retroviral reverse transcriptase coding region in RNA isolated from epididymis, testis, clarified seminal fluid and uterus. Phylogenetic analysis allowed us to classify the sequences into two distinct groups: (1) mammalian type-C viruses, having similarity to Moloney murine leukaemia virus, feline leukaemia virus and gibbon ape leukaemia virus amongst others; (2) a mixed ABCD group containing, for example, Chinese hamster and murine intracisternal A-particle virus sequences, mouse mammary tumour virus and human and simian retroviral sequences. The presence of putative full-length retrovirus related to mammalian type-C viruses in the epididymis and uterus was confirmed by Northern blot analysis. However, steroid treatment did not alter retroviral RNA levels in the epididymis or in a uterine tumour relative to untreated uterus. In summary, Syrian hamster reproductive tissues were found to express unique retroviral sequences; however, their role, if any, in hormonal carcinogenesis remains unresolved.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-79-11-2687", "deposited_data": "Sim", "nuccore_ids": "3153416, 3153414, 3153412, 3153410, 3153408, 3153406, 3153404, 3153402, 3153400, 3153398, 3153396, 3153394, 3153392, 3153390, 3153388, 3153386", "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9811727", "author": "Lee SY", "n_authors": 3, "title": "Genetic analysis of the rat leukemia virus: influence of viral sequences in transduction of the c-ras proto-oncogene and expression of its transforming activity.", "abstract": "The rat leukemia virus (RaLV) is an endogenous retrovirus that is spontaneously released by Sprague-Dawley rat embryo cells. The overall structure of the RaLV genome resembles that of other simple, replication-competent retroviruses, but the sequence of the long terminal repeats (LTR) is unique and unrelated to the known retroviruses. Phylogenetically, the RaLV genome appears to be more closely related to the feline leukemia virus group of retroviruses than to the murine leukemia virus group. A remarkable feature of RaLV is that it is capable of transducing a ras proto-oncogene from rat tumor cells in the form of an acutely transforming virus, designated the Rasheed strain of the rat sarcoma virus (RaSV). With the exception of the c-ras sequence, the genomes of both RaLV and RaSV are collinear. The RaSV-encoded oncogene v-Ra-ras expresses a fusion protein with a molecular mass of 29 kDa, and it exhibits a unique structure that has not been described previously for any known virus. The 5' end of this gene is derived from sequences encoding RaLV matrix followed by 20 bp derived from the U5 region of the RaLV LTR (RS-U5 element) which is joined at its 3' end to sequences derived from all six (coding and noncoding) exons of the c-ras proto-oncogene at the 3' end. This recombinational event represents a novel mechanism among the acutely transforming viruses that have been studied.", "journal": "Journal of virology", "doi": "10.1128/JVI.72.12.9906-9917.1998", "deposited_data": "Sim", "nuccore_ids": "349109, 348950", "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9806492", "author": "Baneth G", "n_authors": 4, "title": "Hepatozoon species infection in domestic cats: a retrospective study.", "abstract": "Hepatozoon sp. is a protozoan parasite of peripheral blood neutrophils in cats. Feline hepatozoonosis has been reported infrequently and little is known about the pathogenesis of this infection. In order to further clarify clinicopathological characteristics of hepatozoonosis in domestic cats, a retrospecitve study of hepatozoonosis in cats admitted during 1989-1995 to the Hebrew University School of Veterinary Medicine was conducted. The study population comprised all the cats whose medical records included a complete blood count with a microscopical examination of a blood smear during this 7-year period (n=1229). Hepatozoon gametocytes were identified in seven cats (0.57%) ranging from 1 to 6 years of age. Infected cats were mostly males (6/7) of mixed breed (5/7) with a variety of complaints and clinical signs. The clinicopathological findings included increased activities of serum lactate dehydrogenase (LDH) (5/6) and creatine kinase (CK) (5/6). The elevated enzymes detected in cats with hepatozoonosis are suggestive of muscular damage. Sixty-seven percent (4/6) of the cats with hepatozoonosis which were tested for a retroviral disease were found infected either in FIV or FELV. In addition, 2/7 cats were co-infected with Hemobartonella felis. In conclusion, parasitemia with Hepatozoon sp. is a rare finding in cats from Israel. The over-representation of cats with a retroviral disease among the cats with hepatozoonosis indicates a possible association between immunosupression and the development of Hepatozoon infection.", "journal": "Veterinary parasitology", "doi": "10.1016/s0304-4017(98)00160-5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9795899", "author": "Maruyama S", "n_authors": 11, "title": "Seroprevalence of Bartonella henselae and Toxoplasma gondii infections among pet cats in Kanagawa and Saitama Prefectures.", "abstract": "Seroprevalence of Bartonella henselae and Toxoplasma gondii was investigated among 471 pet cats obtained from seven private animal hospitals in Kanagawa and Saitama Prefectures during the period from May 1994 to June 1995. 'Furthermore, 67 randomly selected from the 471 serum samples were examined for the feline immunodeficiency virus (FIV) antibody and feline leukemia virus (FeLV) antigen. The antibody to B. henselae was examined by an indirect immunofluorescent antibody test. T. gondii, FIV and FeLV infections in cats were detected with respective commercial kits. Of the cat serum samples tested, 43 (9.1%) were found to be seropositive for B. henselae and 41 (8.7%) for T. gondii. The B. henselae-positive rate (12.9%) of male cats was significantly higher than that (5.2%) of female cats. On the other hand, T. gondii-positive rate was 9.1% in male and 8.7% in female cats and there was no significant difference in the positivity between sexes. The positive rate in each hospital varied from 0 to 19.5% for B. henselae and 4.9 to 18.8% for T. gondii. The ages of B. henselae- and T. gondii-positive cats were distributed from < 1-year-old to 14-year-old and the seropositivity increased with age of cats. Of the 67 cat serum samples, 16 and 6 cases were positive for FIV and FeLV, respectively. There was no relationship between these viral and B. henselae infections in cats.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.60.997", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9787382", "author": "Zwahlen CH", "n_authors": 4, "title": "Results of chemotherapy for cats with alimentary malignant lymphoma: 21 cases (1993-1997).", "abstract": "To determine clinical and pathologic findings in cats with alimentary malignant lymphoma and results of treatment with a combination of prednisone, L-asparaginase, vincristine, cyclophosphamide, doxorubicin, and methotrexate. Retrospective study. 21 cats with alimentary malignant lymphoma. Medical records were reviewed, and information on signalment, clinical history and signs, previous treatments, and results of laboratory tests, thoracic radiography, and abdominal ultrasonography were obtained. Test results in all cats were negative for FeLV; 3 of 19 were positive for feline immunodeficiency virus. Thirteen tumors were stage III, 7 were stage IV, and 1 was stage V. Diagnosis was confirmed on the basis of microscopic examination of histologic (n = 13) or cytologic (8) specimens. Immunophenotyping was performed on 13 tumors; 10 were T-cell and 3 were B-cell lymphomas. Overall median duration of first remission was 20 weeks. Overall median survival time was 40 weeks. The only factor significantly associated with duration of first remission was whether cats had a complete response following induction chemotherapy; duration of first remission was significantly associated with survival time. Cats tolerated treatment well; only 1 cat had a delay in the treatment schedule because of neutropenia. Use of a multidrug chemotherapeutic protocol that includes L-asparaginase and doxorubicin results in minimal adverse effects and prolonged survival times in cats with alimentary malignant lymphoma.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9781450", "author": "Berent LM", "n_authors": 3, "title": "Detection of Haemobartonella felis in cats with experimentally induced acute and chronic infections, using a polymerase chain reaction assay.", "abstract": "To develop a test for detection of Haemobartonella felis, using a polymerase chain reaction (PCR) assay. 4 adult cats seronegative for FeLV and feline immunodeficiency virus. Cats were infected with H felis by i.v. administration of 1 ml of blood obtained from an infected cat. Rectal temperature, PCV, and microscopic examination of blood smears for organisms were monitored daily. At peak of infection, doxycycline treatment was initiated for 21 days. Blood samples were collected at weekly intervals. Six months after treatment, 2 cats were given methylprednisolone (14 mg/kg of body weight, i.m.). Daily blood samples were collected for CBC, detection of organisms, and PCR evaluation. On the basis of the 16S rRNA gene sequence of H felis, specific PCR primers were created for a 393-basepair internal fragment. The 393-basepair product was consistently amplified from blood samples obtained during peak parasitemia but not during the last week of or immediately after completion of doxycycline treatment. After treatment, PCV returned to the reference range, and organisms were not observed in blood samples; however, the PCR product could be consistently amplified. After administration of methylprednisolone, organisms were only rarely observed in blood smears but were consistently detected by PCR analysis. Using PCR analysis, it was possible to detect H felis in blood samples obtained from cats during peak parasitemia, during most of the carrier phase, and after challenge with immunosuppressive drugs. During and immediately after antibiotic treatment, this test may fail to detect the organisms.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9773411", "author": "Vail DM", "n_authors": 4, "title": "Feline lymphoma (145 cases): proliferation indices, cluster of differentiation 3 immunoreactivity, and their association with prognosis in 90 cats.", "abstract": "Paraffin-embedded, formalin-fixed tissue samples from 145 cats with lymphoma were analyzed for cluster of differentiation 3 (CD3, a surface antigen) immunoreactivity, argyrophilic nucleolar organizer region (AgNOR) frequency, and proliferating cell nuclear antigen labeling index (PCNA-LI). This information along with signalment, anatomic site, and feline leukemia virus (FeLV) antigen status was used to determine the potential of these indicators to predict response to therapy, remission, and survival times, and to characterize cats with lymphoma in the era of general availability of FeLV testing and vaccination. Alimentary lymphoma, primarily occurring in older, FeLV-negative cats, was the most common site of involvement. Although the majority of tumors from FeLV-positive cats were CD3-immunoreactive, only one half of CD3-immunoreactive tumors occurred in FeLV-positive cats. Median remission duration and survival times were 126 days and 143 days, respectively, for all cats. Measures of tumor cell proliferation (AgNOR frequency and PCNA-LI) and CD3-immunoreactivity were not predictive of outcome. When all prognostic factors were accounted for by multivariate analysis, response to therapy, FeLV status, and clinical substage were predictive of outcome. FeLV-negative cats that achieved a complete response following induction therapy were likely to have durable (i.e., > 6-month) responses, particularly when doxorubicin was included in the chemotherapy protocol. However, FeLV-positive cats had significantly shorter remission and survival times with available chemotherapeutic protocols.", "journal": "Journal of veterinary internal medicine", "doi": "10.1111/j.1939-1676.1998.tb02134.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9765447", "author": "Holznagel E", "n_authors": 13, "title": "The role of in vitro-induced lymphocyte apoptosis in feline immunodeficiency virus infection: correlation with different markers of disease progression.", "abstract": "Human immunodeficiency virus infection is characterized by a progressive decline in the number of peripheral blood CD4(+) T lymphocytes, which finally leads to AIDS. This T-cell decline correlates with the degree of in vitro-induced lymphocyte apoptosis. However, such a correlation has not yet been described in feline AIDS, caused by feline immunodeficiency virus (FIV) infection. We therefore investigated the intensity of in vitro-induced apoptosis in peripheral blood lymphocytes from cats experimentally infected with a Swiss isolate of FIV for 1 year and for 6 years and from a number of long-term FIV-infected cats which were coinfected with feline leukemia virus. Purified peripheral blood lymphocytes were either cultured overnight under nonstimulating conditions or stimulated with phytohemagglutinin and interleukin-2 for 60 h. Under stimulating conditions, the isolates from the infected cats showed significantly higher relative counts of apoptotic cells than did those from noninfected controls (1-year-infected cats, P = 0.01; 6-year-infected cats, P = 0.006). The frequency of in vitro-induced apoptosis was inversely correlated with the CD4(+) cell count (P = 0. 002), bright CD8(+) cell count (P = 0.009), and CD4/CD8 ratio (P = 0. 01) and directly correlated with the percentage of bright major histocompatibility complex class II-positive peripheral blood lymphocytes (P = 0.004). However, we found no correlation between in vitro-induced apoptosis and the viral load in serum samples. Coinfection with feline leukemia virus enhanced the degree of in vitro-induced apoptosis compared with that in FIV monoinfected cats. We concluded that the degree of in vitro-induced apoptosis was closely related to FIV-mediated T-cell depletion and lymphocyte activation and could be used as an additional marker for disease progression in FIV infection.", "journal": "Journal of virology", "doi": "10.1128/JVI.72.11.9025-9033.1998", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9733816", "author": "Cupelli L", "n_authors": 4, "title": "The secondary structure of the R region of a murine leukemia virus is important for stimulation of long terminal repeat-driven gene expression.", "abstract": "In addition to their role in reverse transcription, the R-region sequences of some retroviruses affect viral transcription. The first 28 nucleotides of the R region within the long terminal repeat (LTR) of the murine type C retrovirus SL3 were predicted to form a stem-loop structure. We tested whether this structure affected the transcriptional activity of the viral LTR. Mutations that altered either side of the stem and thus disrupted base pairing were generated. These decreased the level of expression of a reporter gene under the control of viral LTR sequences about 5-fold in transient expression assays and 10-fold in cells stably transformed with the LTR-reporter plasmids. We also generated a compensatory mutant in which both the ascending and descending sides of the stem were mutated such that the nucleotide sequence was different but the predicted secondary structure was maintained. Most of the activity of the wild-type SL3 element was restored in this mutant. Thus, the stem-loop structure was important for the maximum activity of the SL3 LTR. Primer extension analysis indicated that the stem-loop structure affected the levels of cytoplasmic RNA. Nuclear run-on assays indicated that deletion of the R region had a small effect on transcriptional initiation and no effect on RNA polymerase processivity. Thus, the main effect of the R-region element was on one or more steps that occurred after the template was transcribed by RNA polymerase. This finding implied that the main function of the R-region element involved RNA processing. R-region sequences of human immunodeficiency virus type 1 or mouse mammary tumor virus could not replace the SL3 element. R-region sequences from an avian reticuloendotheliosis virus partially substituted for the SL3 sequences. R-region sequences from Moloney murine leukemia virus or feline leukemia virus did function in place of the SL3 element. Thus, the R region element appears to be a general feature of the mammalian type C genus of retroviruses.", "journal": "Journal of virology", "doi": "10.1128/JVI.72.10.7807-7814.1998", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9717127", "author": "Breuer W", "n_authors": 4, "title": "Bone-marrow changes in infectious diseases and lymphohaemopoietic neoplasias in dogs and cats--a retrospective study.", "abstract": "Bone-marrow changes in infectious diseases due to feline infectious peritonitis virus (FIPV), feline immunodeficiency virus (FIV), parvovirus (PV, canine and feline) and canine distemper virus (CDV), and in the lymphohaemopoietic neoplasias (LHNs) usually associated with feline leukaemia virus infection were studied in samples obtained from 204 cats and 82 dogs at necropsy. The study demonstrated (1) no changes, (2) non-specific reactive changes, and (3) disease-specific changes (similar to those occurring in extramedullary sites) in: 51.2, 48.8 and 9.7% of 41 cases of FIPV infection, respectively; 0, 100 and 0% of nine cases of FIV infection, respectively; 1.3, 0 and 92% of 75 cases of canine PV infection, respectively; 5.3, 3.9 and 84% of 76 cases of feline PV infection, respectively; 71.4, 28.6 and 0% of seven cases of CDV infection, respectively; and 35.9, 52.6 and 11.5% of 78 cases of LHN, respectively. The distribution of the disease-specific bone-marrow changes was either diffuse or focal; diffuse changes were frequently found in cases of feline and canine PV infection, and focal changes were found inconsistently in FIPV infections and feline LHN. To the extent that the bone marrow showed any changes in FIV and CDV infections, they were mostly reactive and not pathognomonic.", "journal": "Journal of comparative pathology", "doi": "10.1016/s0021-9975(98)80071-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9717123", "author": "Kipar A", "n_authors": 6, "title": "Fatal enteritis associated with coronavirus infection in cats.", "abstract": "This report describes five cases of naturally occurring feline coronavirus enteritis. The affected animals, aged 2 months to 7 years, had a clinical history of intestinal symptoms, including diarrhoea or vomiting, or both. They exhibited variable histological changes in the epithelium of the small intestine, ranging from degeneration of single cells and detachment of groups of cells from the villous tips to regenerative processes of the crypt epithelia. Post-mortem diagnosis was based on the immunohistochemical demonstration of coronavirus antigen within intestinal epithelial cells and on the electron microscopical demonstration of coronavirus particles in the faeces. In addition, one animal was immunohistochemically positive for antigens of feline leukaemia virus (FeLV) and exhibited intestinal changes consistent with FeLV-associated enteritis. Two cats were tested serologically for feline immunodeficiency antibodies, with negative results. The findings indicate that natural coronavirus infection is a potential cause of severe enteritis in juvenile and adult cats.", "journal": "Journal of comparative pathology", "doi": "10.1016/s0021-9975(98)80067-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9696797", "author": "Chen H", "n_authors": 7, "title": "Pathogenicity induced by feline leukemia virus, Rickard strain, subgroup A plasmid DNA (pFRA).", "abstract": "A new provirus clone of feline leukemia virus (FeLV), which we named FeLV-A (Rickard) or FRA, was characterized with respect to viral interference group, host range, complete genome sequence, and in vivo pathogenicity in specific-pathogen-free newborn cats. The in vitro studies indicated the virus to be an ecotropic subgroup A FeLV with 98% nucleotide sequence homology to another FeLV-A clone (F6A/61E), which had also been fully sequenced previously. Since subgroup B polytropic FeLVs (FeLV-B) are known to arise via recombination between ecotropic FeLV-A and endogenous FeLV (enFeLV) env elements, the in vivo studies were conducted by direct intradermal inoculation of the FRA plasmid DNA so as to eliminate the possibility of coinoculation of any FeLV-B which may be present in the inoculum prepared by propagating FeLV-A in feline cell cultures. The following observations were made from the in vivo experiments: (i) subgroup conversion from FeLV-A to FeLV-A and FeLV-B, as determined by the interference assay, appeared to occur in plasma between 10 and 16 weeks postinoculation (p.i.); (ii) FeLV-B-like recombinants (rFeLVs), however, could be detected in DNA isolated from buffy coats and bone marrow by PCR as early as 1 to 2 weeks p.i.; (iii) while a mixture of rFeLV species containing various amounts of N-terminal substitution of the endogenous FeLV-derived env sequences were detected at 8 weeks p.i., rFeLV species harboring relatively greater amounts of such substitution appeared to predominate at later infection time points; (iv) the deduced amino acid sequence of rFeLV clones manifested striking similarity to natural FeLV-B isolates, within the mid-SU region of the env sequenced in this work; and (v) four of the five cats, which were kept for determination of tumor incidence, developed thymic lymphosarcomas within 28 to 55 weeks p.i., with all tumor DNAs harboring both FeLV-A and rFeLV proviruses. These results provide direct evidence for how FeLV-B species evolve in vivo from FeLV-A and present a new experimental approach for efficient induction of thymic tumors in cats, which should be useful for the study of retroviral lymphomagenesis in this outbred species.", "journal": "Journal of virology", "doi": "10.1128/JVI.72.9.7048-7056.1998", "deposited_data": "Sim", "nuccore_ids": "9630707, 3420022", "bioproject_ids": "485481", "sra_ids": null}, {"year": 1998, "pmid": "9684375", "author": "Fromont E", "n_authors": 3, "title": "Dynamics of a feline retrovirus (FeLV) in host populations with variable spatial structure.", "abstract": "The predictions of epidemic models are remarkably affected by the underlying assumptions concerning host population dynamics and the relation between host density and disease transmission. Furthermore, hypotheses underlying distinct models are rarely tested. Domestic cats (Felis catus) can be used to compare models and test their predictions, because cat populations show variable spatial structure that probably results in variability in the relation between density and disease transmission. Cat populations also exhibit various dynamics. We compare four epidemiological models of Feline Leukaemia Virus (FeLV). We use two different incidence terms, i.e. proportionate mixing and pseudo-mass action. Population dynamics are modelled as logistic or exponential growth. Compared with proportionate mixing, mass action incidence with logistic growth results in a threshold population size under which the virus cannot persist in the population. Exponential growth of host populations results in systems where FeLV persistence at a steady prevalence and depression of host population growth are biologically unlikely to occur. Predictions of our models account for presently available data on FeLV dynamics in various populations of cats. Thus, host population dynamics and spatial structure can be determinant parameters in parasite transmission, host population depression, and disease control.", "journal": "Proceedings. Biological sciences", "doi": "10.1098/rspb.1998.0404", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9660073", "author": "Bechtel MK", "n_authors": 5, "title": "In vivo evolution and selection of recombinant feline leukemia virus species.", "abstract": "Ecotropic feline leukemia viruses subgroup A (FeLV-A) is known to recombine with endogenous FeLV (enFeLV) env elements yielding polytropic FeLV-B viruses. However, scattered nucleotide differences exist between enFeLV env elements and corresponding sequences of exogenous FeLV-B isolates. To address this disparity, we examined recombinant FeLV (rFeLV) viruses obtained from three experimentally-induced feline thymic tumors, along with rFeLVs derived from one naturally-occurring thymic tumor. Two of the three experimental cats were challenged with a FeLV-A/Rickard preparation, while one cat received this FeLV-A along with a mixture of in vitro-generated rFeLVs. The FeLV-A/Rickard preparation employed in this study was shown to be free of detectable rFeLVs since no recombinant products were observed in this preparation following nested PCR analyses. For each of the four tumor DNAs, nucleotide sequence analysis was performed on multiple clones of rFeLV-specific PCR products derived from the surface glycoprotein (SU) portion of the recombinant proviral env gene. Relative to the parental enFeLV sequence used to generate the rFeLVs, a total of 19 nucleotide differences were found scattered within the SU region of the env gene in these in vivo-derived rFeLV clones. Most interestingly, this set of 19 differences led to complete sequence identity with natural FeLV-B isolates. Our results indicate these differences are present early in the in vivo evolution of recombinant viruses, suggesting that rFeLVs harboring these differences are strongly selected. We also present evidence indicating an in vivo selection pattern exists for specific recombinant species containing relatively greater amounts of enFeLV-derived SU sequence. This in vivo selection process appears to be gradual, occurring over the infection timecourse, yielding rFeLV species which have recombination structural motifs similar to those seen in natural FeLV-B isolates.", "journal": "Virus research", "doi": "10.1016/s0168-1702(98)00015-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9637231", "author": "Ozon C", "n_authors": 7, "title": "Disseminated feline leishmaniosis due to Leishmania infantum in Southern France.", "abstract": "A fortuitously discovered case of feline leishmaniosis is reported. The parasites were found in the skin and the bone marrow of a domestic female cat that spontaneously died after a few weeks of evolution. Serological tests for FeLV, FIV and PIF virus detection gave negative results. By using Western blot serology, a characteristic pattern of leishmaniosis was obtained and by performing an isoenzyme electrophoresis, a Leishmania infantum MON-1 strain was identified. The same zymodeme is implicated in most of the canine and human leishmaniosis in Southern Europe. A study on the prevalence of asymptomatic feline leismaniosis is foreseen.", "journal": "Veterinary parasitology", "doi": "10.1016/s0304-4017(97)00174-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9618510", "author": "Laten HM", "n_authors": 3, "title": "SIRE-1, a copia/Ty1-like retroelement from soybean, encodes a retroviral envelope-like protein.", "abstract": "The soybean genome hosts a family of several hundred, relatively homogeneous copies of a large, copia/Ty1-like retroelement designated SIRE-1. A copy of this element has been recovered from a Glycine max genomic library. DNA sequence analysis of two SIRE-1 subclones revealed that SIRE-1 contains a long, uninterrupted, ORF between the 3' end of the pol ORF and the 3' long terminal repeat (LTR), a region that harbors the env gene in retroviral genomes. Conceptual translation of this second ORF produces a 70-kDa protein. Computer analyses of the amino acid sequence predicted patterns of transmembrane domains, alpha-helices, and coiled coils strikingly similar to those found in mammalian retroviral envelope proteins. In addition, a 65-residue, proline-rich domain is characterized by a strong amino acid compositional bias virtually identical to that of the 60-amino acid, proline-rich neutralization domain of the feline leukemia virus surface protein. The assignment of SIRE-1 to the copia/Ty1 family was confirmed by comparison of the conceptual translation of its reverse transcriptase-like domain with those of other retroelements. This finding suggests the presence of a proretrovirus in a plant genome and is the strongest evidence to date for the existence of a retrovirus-like genome closely related to copia/Ty1 retrotransposons.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.95.12.6897", "deposited_data": "Sim", "nuccore_ids": "3777526, 3142328", "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9612917", "author": "Robinson A", "n_authors": 7, "title": "Comparison of a rapid immunomigration test and ELISA for FIV antibody and FeLV antigen testing in cats.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.142.18.491", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9597305", "author": "Endo Y", "n_authors": 10, "title": "Clinicopathological and immunological characteristics of six cats with granular lymphocyte tumors.", "abstract": "Clinical and immunological characteristics were investigated in six cases of feline granular lymphocyte (GL) tumor. The ages of the affected cats were relatively old, ranging from 4 to 13 years of age. Gastrointestinal signs were commonly observed in these cases. Only one of the six GL tumor cases was positive for feline leukemia virus (FeLV) antigen. Phenotypic analysis revealed that the GL tumor cells from all of the six cases lacked the T- or B-cell markers. These GL tumor cells were examined by Southern blot analysis using feline immunoglobulin (Ig) and T-cell receptor (TCR) gene probes. GL tumor cells obtained from two cases were identified as cells of T-cell lineage by the presence of a rearranged TCR beta gene, whereas those from the other four cases were considered to be derived from non-T- non-B-cell lineage because of the absence of rearrangement of these genes. These findings indicated that feline GL tumors can be considered as a specific disease entity in feline lymphomas because the cases examined in this study showed onset at an older age, a low incidence of FeLV infection and frequent involvement of gastrointestinal lesions, which are not found in typical FeLV-associated lymphomas. Although no specific phenotypes was observed by phenotypic analysis, the feline GL tumor cells were divided into two consistent genotypes of T-cell or non-T- non-B-cell lineages.", "journal": "Comparative immunology, microbiology and infectious diseases", "doi": "10.1016/s0147-9571(97)00019-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9593451", "author": "Blakeslee J", "n_authors": 4, "title": "Adoptive immunotherapy of feline leukemia virus infection using autologous lymph node lymphocytes.", "abstract": "Adoptive immunotherapy using autologous cells expanded ex vivo from lymph nodes was examined in cats infected with the retrovirus feline leukemia virus (FeLV). Cells were obtained from popliteal lymph nodes from 18 FeLV-antigen-positive cats without complications; a mean of 6.2 x 10(7) cells were obtained. Lymph node cells were cultured with 600 IU/ml interleukin-2 (IL-2) for 7 days. Cells expanded 0.8- to 11-fold (mean, 2.7; median, 2.4); were 80% +/- 8.0% CD3+, 29% +/- 8.1% CD4+, and 41% +/- 7.0% CD8+, and exhibited cytolytic activity against FeLV-transformed FL74 cells. Sixteen cats received a single intravenous infusion of 0.13 to 3.9 x 10(8) cells. Cell infusion was well tolerated; fever developed approximately 1 hour postinfusion. Clinical activity, antiviral activity, or both was observed in 10 cats. Nine cats had clinical responses with improvement in weight, activity, appearance, or a combination of these that began 2 to 4 weeks after cell infusion and that lasted for up to 13 or more months. FeLV antigen became undetectable in 4 cats. These results indicate that adoptive immunotherapy using autologous lymph node cells, activated and expanded ex vivo in short-term cultures with low concentrations of IL-2, can modulate the course of a retroviral infection.", "journal": "Journal of acquired immune deficiency syndromes and human retrovirology : official publication of the International Retrovirology Association", "doi": "10.1097/00042560-199805010-00001", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9548958", "author": "Davies SM", "n_authors": 4, "title": "Modulation of lipid polymorphism by the feline leukemia virus fusion peptide: implications for the fusion mechanism.", "abstract": "The structural effects of the fusion peptide of feline leukemia virus (FeLV) on lipid polymorphism were studied, using differential scanning calorimetry (DSC), 31P nuclear magnetic resonance (NMR), and time-resolved X-ray diffraction. This peptide lowers the bilayer to inverted hexagonal phase transition temperature, TH, of dipalmitoleoylphosphatidylethanolamine (DiPoPE) at peptide mole fractions of up to 1.5 x 10(-3) at pH 5.0 and at pH 7.4. The temperature at which isotropic 31P NMR signals for monomethyldioleoylphosphatidylethanolamine (MeDOPE) first occurred is lowered by the FeLV peptide. The amount of isotropic signal seen at 40 degrees C is directly correlated to the peptide:lipid molar ratio. In the peptide-containing samples, more lipid remains in the isotropic state over the whole recorded temperature range. Isotropic 31P NMR signals were observed for DiPoPE in the presence of the FeLV peptide for the entire recorded temperature range of 35-50 degrees C, while pure DiPoPE showed no significant amount of isotropic signal. X-ray studies of DiPoPE show the formation of a new lipid phase with peptide, which is not seen in the pure lipid samples. Disordering of the Lalpha phase is evidenced by broadening of the diffraction peaks, and the hexagonal cell parameter is decreased with peptide present. Our results suggest that the FeLV peptide is increasing the negative curvature of the lipid system, which is thought to be crucial to the formation of highly bent, high-energy structural fusion intermediates, such as the \"stalk\" model. Fusion activity for this putative fusogenic peptide was also demonstrated, using a resonance energy transfer (RET) lipid mixing assay. To our knowledge, this work provides the first published experimental evidence of both fusogenic activity and effects on lipid polymorphism for the FeLV fusion peptide.", "journal": "Biochemistry", "doi": "10.1021/bi980227v", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9563505", "author": "Davies SM", "n_authors": 4, "title": "Structural plasticity of the feline leukaemia virus fusion peptide: a circular dichroism study.", "abstract": "The secondary structure of the feline leukaemia virus (FeLV) fusion peptide was investigated using circular dichroism (CD). Our results show that this peptide can readily flip between random, alpha-helical and beta-sheet conformations, depending upon its environment. The CD spectrum changes from one characteristic of random coil to predominantly beta-sheet type, and finally to that showing the characteristics of alpha-helical structure on moving from an aqueous solvent, through several increasingly hydrophobic systems, to a highly hydrophobic solvent. Electron microscopy confirmed the presence of beta structure. We propose that the structural plasticity demonstrated here is crucial to the ability of the fusion peptide to perturb lipid bilayers, and thus promote membrane fusion.", "journal": "FEBS letters", "doi": "10.1016/s0014-5793(98)00274-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9557753", "author": "Lundorf MD", "n_authors": 4, "title": "Single amino acid insertion in loop 4 confers amphotropic murine leukemia virus receptor function upon murine Pit1.", "abstract": "Pit1 is the human receptor for gibbon ape leukemia virus (GALV) and feline leukemia virus subgroup B (FeLV-B), while the related human protein Pit2 is a receptor for amphotropic murine leukemia virus (A-MuLV). The A-MuLV-related isolate 10A1 can utilize both Pit1 and Pit2 as receptors. A stretch of amino acids named region A was identified in Pit1 (residues 550 to 558 in loop 4) as critical for GALV and FeLV-B receptor function. We have here investigated the role of region A in A-MuLV and 10A1 entry. Insertion of a single amino acid in region A of mouse Pit1 resulted in a functional A-MuLV receptor, showing that region A plays a role in A-MuLV infection. Moreover, the downregulation of 10A1 receptor function by changes in region A of human Pit1 indicates that this region is also involved in 10A1 entry. Therefore, region A seems to play a role in infection by all viruses utilizing Pit1 and/or Pit2 as receptors.", "journal": "Journal of virology", "doi": "10.1128/JVI.72.5.4524-4527.1998", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9525654", "author": "Ramsey IK", "n_authors": 3, "title": "The receptor binding site of feline leukemia virus surface glycoprotein is distinct from the site involved in virus neutralization.", "abstract": "The external surface glycoprotein (SU) of feline leukemia virus (FeLV) contains sites which define the viral subgroup and induce virus-neutralizing antibodies. The subgroup phenotypic determinants have been located to a small variable region, VR1, towards the amino terminus of SU. The sites which function as neutralizing epitopes in vivo are unknown. Recombinant SU proteins were produced by using baculoviruses that contained sequences encoding the SUs of FeLV subgroup A (FeLV-A), FeLV-C, and two chimeric FeLVs (FeLV-215 and FeLV-VC) in which the VR1 domain of FeLV-A had been replaced by the corresponding regions of FeLV-C isolates. The recombinant glycoproteins, designated Bgp70-A, -C, -215, and -VC, respectively, were similar to their wild-type counterparts in several immunoblots and inhibited infection of susceptible cell lines in a subgroup-specific manner. Thus, Bgp70-A interfered with infection by FeLV-A, whereas Bgp70-C, -VC, and -215 did not. Conversely, Bgp70-C, -VC, and -215 blocked infection with FeLV-C, while Bgp70-A had no effect. These results indicate that the site on SU which binds to the FeLV cell surface receptor was preserved in the recombinant glycoproteins. It was also found that the recombinant proteins were able to bind naturally occurring neutralizing antibodies. Bgp70-A, -VC, and -215 interfered with the action of anti-FeLV-A neutralizing antibodies, whereas Bgp70-C did not. Furthermore, Bgp70-C interfered with the action of anti-FeLV-C neutralizing antibodies, while the other proteins did not. These results indicate that the neutralizing epitope(s) of FeLV SU lies outside the subgroup-determining VR1 domain.", "journal": "Journal of virology", "doi": "10.1128/JVI.72.4.3268-3277.1998", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9525586", "author": "Rohn JL", "n_authors": 5, "title": "In vivo evolution of a novel, syncytium-inducing and cytopathic feline leukemia virus variant.", "abstract": "Studies of feline leukemia virus (FeLV) have illustrated the importance of the genotype of the infecting virus in determining disease outcome. In FeLV infections, as in other retroviral infections, it is less clear how virus variants that evolve from the transmitted virus affect pathogenesis. We previously reported an analysis of the genotypic changes that occur in the viral envelope gene (env) in cats infected with a prototype transmissible FeLV clone, 61E (J. Rohn, M. Linenberger, E. Hoover, and J. Overbaugh, J. Virol. 68:2458-2467, 1994). In one cat, each variant (81T) had evolved, in addition to scattered amino acid changes, a four-amino-acid insertion with respect to 61E. This insertion was located at the same site in the extracellular envelope glycoprotein where the immunodeficiency-inducing molecular clone 61C possesses a six-amino-acid insertion critical for its pathogenic phenotype, although the sequences of the insertions were distinct. To determine whether acquisition of the four-amino-acid insertion was associated with a change in the replication or cytopathic properties of the virus, we constructed chimeras encoding 81T env genes in a 61E background. One representative chimeric virus, EET(TE)-109, was highly cytopathic despite the fact that it replicated with delayed kinetics in the feline T-cell line 3201 compared to the parental 61E virus. The phenotype of this virus was also novel compared to other FeLVs, including both the parental virus 61E and the immunodeficiency-inducing variant 61C, because infection of T cells was associated with syncytium formation. Moreover, in single-cycle infection assays, the 81T-109 envelope demonstrated receptor usage properties distinct from those of both 61E and 61C envelope. Thus, these studies demonstrate the evolution of a novel T-cell cytopathic and syncytium-inducing FeLV in the host. The 81T virus will be valuable for dissecting the mechanism of T-cell killing by cytopathic variants in the FeLV model.", "journal": "Journal of virology", "doi": "10.1128/JVI.72.4.2686-2696.1998", "deposited_data": "Sim", "nuccore_ids": "2351526, 2351525, 2351385", "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9514965", "author": "Moser M", "n_authors": 4, "title": "The host range and interference properties of two closely related feline leukemia variants suggest that they use distinct receptors.", "abstract": "The proviral clones 61E and 61C represent two closely related variants of feline leukemia virus (FeLV) that exhibit significant differences in their biological and pathogenic properties. The major pathogenic determinant has been mapped to the extracellular envelope glycoprotein (Env-SU), but the mechanism by which envelope differences influence pathogenesis is not well understood. Moreover, it is unclear whether these viruses infect the same target cells and/or enter cells using the same receptor. In the present study, we exploited a recently developed single cycle infection assay to examine the host range and interference properties of 61E and 61C FeLVs and found that these two FeLV variants differ significantly in their host ranges and receptor usages. FeLV-61C was found to be an ecotropic virus; the entry of viruses bearing a 61C envelope protein (Env-SU) into cell lines was limited to feline T-cells and feline fibroblasts. In contrast, the host range of 61E includes, in addition to all feline cells examined, some canine, murine, and human cell lines. Feline fibroblast and feline T-cells that expressed 61E envelope were resistant to infection with a virus bearing a 61E Env-SU, whereas these same cells were susceptible to infection by an otherwise similar virus pseudotyped with the 61C Env-SU. This pattern of interference was observed in cells expressing 61E envelope alone, in the absence of other FeLV gene products, demonstrating that interference was mediated specifically by Env-SU. Fibroblast cells chronically infected with a 61C virus were partially resistant to infection with a virus having a 61C Env-SU, but were not resistant to infection by a virus having a 61E Env-SU. On the basis of the current understanding of virus-receptor interactions, the lack of interference between 61E and 61C under conditions where there is significant homologous interference, combined with the differences in their host cell range, leads us to conclude that 61E and 61C use two distinct primary cellular receptors for entry.", "journal": "Virology", "doi": "10.1006/viro.1997.9008", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9494934", "author": null, "n_authors": 0, "title": "Feline leukaemia virus.", "abstract": null, "journal": "The Journal of small animal practice", "doi": "10.1111/j.1748-5827.1998.tb03671.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9493404", "author": "Pontier D", "n_authors": 5, "title": "Retroviruses and sexual size dimorphism in domestic cats (Felis catus L.).", "abstract": "Hochberg and co-workers have predicted that an increase in host adult mortality due to parasites is balanced by an earlier age at first reproduction. In polygynous species we hypothesize that such a pattern would lead to diverging selection pressure on body size between sexes and increased sexual size dimorphism. In polygynous mammals, male body size is considered to be an important factor for reproductive success. Thus, under the pressure of a virulent infection, males should be selected for rapid growth and/or higher body size to be able to compete successfully as soon as possible with opponents. In contrast, under the same selection pressure, females should be selected for lighter adult body size or rapid growth to reach sexual maturity earlier. We investigated this hypothesis in the domestic cat Felis catus. Orange cats have greater body size dimorphism than non-orange cats. Orange females are lighter than non-orange females, and orange males are heavier than non-orange males. Here, we report the extent to which orange and non-orange individuals differ in infection prevelance for two retroviruses, feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV). FIV is thought to be transmitted almost exclusively through aggressive contacts between individuals, whereas FeLV transmission occurs mainly through social contacts. The pattern of infection of both diseases is consistent with the higher aggressiveness of orange cats. In both sexes, orange cats are significantly more infected by FIV, and tend to be less infected by FeLV than other cats. The pattern of infection is also consistent with an earlier age at first reproduction in orange than in non-orange cats, at least for females. These results suggest that microparasitism may have played an important role in the evolution of sexual size dimorphism of domestic cats.", "journal": "Proceedings. Biological sciences", "doi": "10.1098/rspb.1998.0278", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9445002", "author": "Starkey CR", "n_authors": 6, "title": "Tumorigenic potential of a recombinant retrovirus containing sequences from Moloney murine leukemia virus and feline leukemia virus.", "abstract": "A recombinant retrovirus, termed MoFe2-MuLV, was constructed in which the U3 region of T-lymphomagenic Moloney murine leukemia virus (Mo-MuLV) was replaced by that of FeLV-945, a provirus of unique long terminal repeat (LTR) structure identified only in non-T-cell, non-B-cell lymphomas of the domestic cat. The LTR of FeLV-945 is unusual in that it contains only a single copy of the transcriptional enhancer followed 25 bp downstream by a 21-bp sequence in triplicate in tandem. Infectivity of MoFe2-MuLV was demonstrated in vitro in SC-1 cells and in vivo in neonatal NIH-Swiss mice. Tumors occurred in MoFe2-MuLV-infected animals following a latency period of 4 to 10 months (average, 6 months). The results of Southern blot analysis of the T-cell receptor beta locus demonstrated that all tumors were lymphomas of T-cell origin. MoFe2-MuLV LTRs were amplified by PCR from tumor DNA and were characterized by nucleotide sequence analysis. LTRs from the tumors that occurred with relatively shorter latency predominantly retained the original MoFe2-MuLV sequence intact and unaltered. Tumors that occurred with relatively longer latency contained LTRs that also retained the 21-bp sequence triplication characteristic of the original virus but had acquired various duplications of enhancer sequences. The repeated identification of enhancer duplications in late-appearing tumors suggests that the duplication affords a selective advantage, although apparently not in the efficient induction of T-cell lymphoma. Proto-oncogenes known to be targets of insertional mutagenesis in the majority of Mo-MuLV-induced tumors or in feline non-T-cell, non-B-cell lymphomas were shown not to be rearranged in any tumor examined. Mink cell focus-inducing (MCF) proviral DNA was readily detectable in some, but not all, tumors. The presence or absence of MCF did not correlate with the kinetics of tumor induction. These studies indicate that the single-enhancer, triplication-containing FeLV LTR, typical of non-T-cell, non-B-cell lymphomas in cats, is competent in the induction of T-cell lymphoma in mice. The findings suggest that the mechanism of MoFe2-MuLV-mediated lymphomagenesis may differ from that of Mo-MuLV-mediated disease, considering the possible involvement of novel oncogenes and the variable presence of MCF recombinants.", "journal": "Journal of virology", "doi": "10.1128/JVI.72.2.1078-1084.1998", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "11714237", "author": "Gunn-Moore DA", "n_authors": 5, "title": "Immune-mediated haemolytic anaemia in two sibling cats associated with multicentric lymphoblastic infiltration.", "abstract": "Immune-mediated haemolytic anaemia associated with multicentric lymphoblastic infiltration is reported in two sibling cats. Both cats presented at under 16 months of age with clinical signs of acute anaemia. In each case there was autoagglutination, a positive Coombs' test and the anaemia was regenerative. At presentation, both cats were negative for FeLV antigen. In each case, the disease proved fatal within 2 months of the initial diagnosis. In both cases, T-lymphoblastic infiltration of bone marrow, liver and spleen was found at post-mortem examination.", "journal": "Journal of feline medicine and surgery", "doi": "10.1053/jfms.1999.0043", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "11397251", "author": "Stiles J", "n_authors": 5, "title": "Use of nested polymerase chain reaction (PCR) for detection of retroviruses from formalin-fixed, paraffin-embedded uveal melanomas in cats.", "abstract": "Thirty-six formalin-fixed, paraffin-embedded enucleated globes from cats with a diagnosis of diffuse anterior uveal melanoma were obtained. Sections of tumor were excised, deparaffinized, and subjected to nested polymerase chain reaction (PCR) to identify proviral DNA sequences from the feline leukemia virus (FeLV)-feline sarcoma virus (FeSV; 36 eyes), and the feline immunodeficiency virus (FIV; 18 eyes). All samples tested were negative for FIV DNA. Three samples were positive for FeLV-FeSV DNA. This is the first reported evidence of a possible link between naturally occurring feline anterior uveal melanoma and the presence of FeLV-FeSV DNA.", "journal": "Veterinary ophthalmology", "doi": "10.1046/j.1463-5224.1999.00066.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10855821", "author": "Bolton LA", "n_authors": 7, "title": "Cryptococcosis in captive cheetah (Acinonyx jubatus): two cases.", "abstract": "Cryptococcus neoformans is a yeast-like organism associated with pulmonary, meningoencephalitic, or systemic disease. This case report documents 2 cases of cryptococcosis with central nervous system involvement in captive cheetah (Acinonyx jubatus). In both cases the predominant post mortal lesions were pulmonary cryptococcomas and extensive meningoencephalomyelitis. Both cheetahs tested negative for feline immunodeficiency virus and feline leukaemia virus. The organism isolated in Case 2 was classified as Cryptococcus neoformans var. gattii, which is mainly associated with disease in immunocompetent hosts.", "journal": "Journal of the South African Veterinary Association", "doi": "10.4102/jsava.v70i1.748", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10676143", "author": "Knotek Z", "n_authors": 5, "title": "Epidemiology of feline leukaemia and feline immunodeficiency virus infections in the Czech Republic.", "abstract": "Commercial serological sets were used for the examination of 727 cats kept in larger towns of the Czech Republic. FeLV antigen and antibodies to FIV were demonstrated in 96 (13.2%) and 42 (5.8%) of the animals, respectively. Seven (0.96%) animals were positive for both FeLV and FIV. Most of the FeLV and/or FIV positive patients were intact rambling males aged 1-4 years. Chronic gastrointestinal and respiratory diseases were found in 54.2% and 43.8% of the FeLV-positive patients, respectively. Chronic urinary tract diseases and generalized lymphadenopathy were found in 47.6% and 45.2% of the FIV-positive patients, respectively. The results of this first survey in the Czech Republic have shown prevalence values and clinical patterns similar to those reported formerly from other European countries.", "journal": "Zentralblatt fur Veterinarmedizin. Reihe B. Journal of veterinary medicine. Series B", "doi": "10.1046/j.1439-0450.1999.00302.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10628677", "author": "Linenberger ML", "n_authors": 2, "title": "The effects of feline retroviruses on cytokine expression.", "abstract": "To identify potential roles of cytokines in retroviral pathogenesis, we used reverse transcription-quantitative competitive polymerase chain reaction (RT-qcPCR) assays to characterize mRNA levels of 19 different lymphokines, chemokines, monokines and hematopoietic growth factors in three feline cell lines productively infected with subgroup A feline leukemia virus (FeLV-A) or various feline immunodeficiency virus (FIV) strains. Infection of a CD8+, CD5- large granular lymphocyte (LGL) cell line with FeLV-A activated expression of interleukin-7 (IL-7), induced modest (4-fold) increases in granulocyte/macrophage colony-stimulating factor (GM-CSF) and leukemia inhibitory factor (LIF) transcripts, and decreased transforming growth factor-beta (TGF-beta) mRNA (4-fold). The LGL cells were not susceptible to infection by FIV. Infection of MYA-1 cells, a CD4+ T-lymphoblastoid cell line, with FeLV-A activated expression of macrophage inflammatory protein-1alpha (MIP-1alpha), increased transcript levels of GM-CSF (8-fold), macrophage CSF (M-CSF) (16-fold) and stem cell factor (SCF) (250-fold), and decreased (4-fold) expression of IL-10 and tumor necrosis factor-alpha (TNF-alpha). Productive infection with four different FIV molecular clones caused progressive MYA-1 cell death; however, the mRNA expression profiles were unchanged except for 2- to 4-fold increases in M-CSF and 16- to 500-fold increases in SCF. Thus, FIV-induced MYA-1 cytopathicity was not associated with dysregulation of pro-apoptotic or survival factor transcript levels. Lastly, productive infection of PNI cells, a marrow-derived fibroendothelial cell line, with FeLV-A or any of three FIV strains induced 4-fold higher levels of IL-12p40 transcripts and variably higher levels (4- to 64-fold) of GM-CSF. Two viral strains, the FIV-14 molecular clone and the clinical isolate FIV-5122, caused syncytia formation and unique activation of IL-1beta and stromal cell-derived factor-1 (SDF-1) expression, suggesting a potential role for those factors in viral spread and/or cytopathicity. In addition, infection with FIV-5122, but not the other FIV strains or FeLV-A, induced significant increases in mRNA levels of the hematopoietic inhibitors TNF-alpha and MIP-1alpha, along with increased concentrations of soluble proteins in culture supernatants. Consistent with this, supernatant from FIV-5122 infected PNI cells suppressed hematopoietic progenitor growth in colony assays, compared to supportive activities in supernatants from other infected or uninfected PNI cell cultures. Together, these data demonstrate that feline retroviruses alter cytokine mRNA levels in general and strain-specific patterns. These changes may result in specific alterations in cell function and contribute to retroviral pathogenesis. Our observations provide a basis for directed studies of candidate factors within the hematopoietic, thymic and lymphoid microenvironments.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/s0165-2427(99)00147-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10596800", "author": "Nakamura Y", "n_authors": 9, "title": "High prevalence of Borna disease virus in domestic cats with neurological disorders in Japan.", "abstract": "A total of 15 (T-1-T-15) domestic cats with neurological disorders in Tokyo area were examined for association with Borna disease virus (BDV). None had detectable antibodies to feline immunodeficiency virus (FIV), feline leukemia virus, feline infectious peritonitis virus and Toxoplasma gondii, and only cat T-8 had detectable antibody to FIV. Serological and molecular epidemiological studies revealed a significantly high prevalence of BDV infection in these cats: antibodies against BDV p24 and/or p40 proteins in 10/15 (66.7%) and p24 and/or p40 RNA in peripheral blood mononuclear cells in 8/15 (53.3%). Further, in situ hybridization and immunohistochemistry analyses of the autopsied brain samples derived from one of the cats (T-15) revealed BDV RNA predominantly in neuronal cells in restricted regions, such as olfactory bulb and medulla of cerebrum. Thus, BDV is present in Japanese domestic cats with neurological disorders at a high prevalence.", "journal": "Veterinary microbiology", "doi": "10.1016/s0378-1135(99)00135-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10582737", "author": "Bernsteen L", "n_authors": 5, "title": "Comparison of two surgical techniques for renal transplantation in cats.", "abstract": "To compare two surgical techniques for renal transplantation in cats with respect to graft warm ischemia time, total surgical time, operative and postoperative complications, and return to normal renal function based on measurement of plasma creatinine concentrations. Research study using normal cats. Fourteen adult, feline leukemia virus and feline immunodeficiency virus (FELV/FIV) negative, neutered male and spayed female cats. Fourteen cats underwent heterotopic renal isograft transplantation with nephrectomy of the contralateral kidney. Renal arterial end-to-end anastomosis to the external iliac artery was performed in eight cats and renal arterial end-to-side anastomosis to the aorta was performed in six cats. Cats were monitored for 14 days after surgery. Renal function was evaluated by daily measurement of plasma creatinine concentrations. The cats' health was assessed by the daily recording of body weight, rectal temperature, postoperative complications, urine production, appetite, packed red blood cell volume, and total serum protein. Ultrasonographic assessment of the isograft was performed every third day. Animals were euthanatized or adopted 14 days after surgery and histopathologic analysis of biopsies or whole isograft tissues was performed. Nine of fourteen cats survived the 14-day study period. Although not statistically significant, mean total surgical time and graft warm ischemia time was shorter for the arterial end-to-side anastomosis. Mean daily plasma creatinine concentrations were not significantly different between the two groups. Five of eight cats (62%) undergoing the arterial end-to-end technique developed neuropraxia and lameness of the ipsilateral pelvic limb. Five cats died or were euthanatized because of other complications. The arterial end-to-side technique appears to be the better method for renal transplantation in cats. Shorter graft warm ischemia and total surgical times, absence of pelvic limb complications, and an adequate return to normal renal function were associated with this technique.", "journal": "Veterinary surgery : VS", "doi": "10.1111/j.1532-950x.1999.00417.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10574526", "author": "Leutenegger CM", "n_authors": 10, "title": "Viral infections in free-living populations of the European wildcat.", "abstract": "While the importance of viral infections is well studied in domestic cats, only limited information is available on their occurence and prevalence in the European wildcat (Felis silvestris silvestris). The aim of this study was to determine the prevalence of antibodies to feline coronavirus (FCoV), calicivirus (FCV), herpesvirus (FHV), parvovirus (FPV), immunodeficiency virus (FIV), leukemia virus (FeLV), and FeLV antigenemia in 51 European wildcat sera. Samples were collected between 1996 and 1997 from wildcat populations in France, Switzerland, and Germany. Antibodies to FCoV were detected in two cats (4%) and FCoV RNA was detected in feces of one of these two cats. Antibodies to FCV, FHV and FPV were found at relatively low frequencies of 16%, 4%, and 2%, respectively. Antibodies to FIV were not detected. Although antigen and antibodies to FeLV were detected in 49%, and 75%, respectively, no evidence of FeLV-associated pathology was found. From the low prevalence of FCoV, FCV, FHV and FPV infections and from the fact that the European wildcats live solitarily, it was concluded that these viral infections do not spread readily within a population. Therefore, it may be assumed that release into the wild of European wildcats bred in captivity would not bring about a high risk of introducing of these viral infections to the free-ranging wildcats. As an exception, wildcats should be tested for absence of FIV infection before release if they were at risk to acquire this infection from domestic cats.", "journal": "Journal of wildlife diseases", "doi": "10.7589/0090-3558-35.4.678", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10567693", "author": "Darkes MJ", "n_authors": 3, "title": "X-ray diffraction study of feline leukemia virus fusion peptide and lipid polymorphism.", "abstract": "The structural effects of the fusion peptide of feline leukemia virus (FeLV) on the lipid polymorphism of N-methylated dioleoylphosphatidylethanolamine were studied using a temperature ramp with sequential X-ray diffraction. This peptide, the hydrophobic amino-terminus of p15E, has been proven to be fusogenic and to promote the formation of highly curved, intermediate structures on the lamellar liquid-crystal to inverse hexagonal phase transition pathway. The FeLV peptide produces marked effects on the thermotropic mesomorphic behaviour of MeDOPE, a phospholipid with an intermediate spontaneous radius of curvature. The peptide is shown to reduce the lamellar repeat distance of the membrane prior to the onset of an inverted cubic phase. This suggests that membrane thinning may play a role in peptide-induced membrane fusion and strengthens the link between the fusion pathway and inverted cubic phase formation. The results of this study are interpreted in relation to models of the membrane fusion mechanism.", "journal": "FEBS letters", "doi": "10.1016/s0014-5793(99)01454-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10544118", "author": "Prabhu S", "n_authors": 3, "title": "The FeLV-945 LTR confers a replicative advantage dependent on the presence of a tandem triplication.", "abstract": "Feline leukemia virus (FeLV), like other naturally occurring retroviruses, is characterized by a high degree of genetic diversity. FeLV-945 is a natural isolate derived from non-B-cell non-T-cell lymphomas classified anatomically as multicentric. FeLV-945 exhibits a unique structural motif in the LTR composed of a 21-bp tandem triplication downstream of a single copy of enhancer. The unique FeLV-945 LTR is precisely conserved among eight independent multicentric lymphomas collected in a geographic cluster. Previous studies using reporter gene constructs predict that the FeLV-945 LTR would confer a replicative advantage on the virus that contains it, particularly in primitive hematopoietic cells. Such an advantage may account for the precise conservation of the unique LTR sequence. To test that prediction, a set of recombinant, infectious FeLVs was developed that are isogenic other than the presence of the FeLV-945 LTR or mutations of it. Replication assays show that the FeLV-945 LTR confers a distinct growth advantage in K-562, FEA, and 3201 cells and implicate the 21-bp triplication in that function. Replacement of two copies of the triplicated element with random sequence greatly diminished the replicative capacity, thus implicating the triplicated sequence itself in LTR function. The 21-bp triplication was shown to contain specific nuclear protein binding sites, which may account for the selective pressure to conserve the sequence.", "journal": "Virology", "doi": "10.1006/viro.1999.9974", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10515279", "author": "Hartmann K", "n_authors": 6, "title": "Treatment of feline leukemia virus (FeLV) infection.", "abstract": "FeLV infection is still considered to account for most disease-related deaths in pet cats. Different treatment attempts with various drugs were performed in the past but none resulted in healing or complete virus elimination. Therefore, it caused a sensation when Horber and Mayr [Horber, D., Mayr, B., 1991. Prax. 19, 311-314; Horber, D., Schnabl, W., Mayr, B., 1992. Tierarztl. Umschau 47, 556-560; Mayr, B., Horber, D., 1992. Kleintierprax. 37, 515-518] published that they were able to cure 80 to 100% FeLV-infected cats from viremia by using an immunomodulating compound. Articles in cat breeder and cat owner journals appeared assuming that obviously there is a rescue for FeLV-infected cats suffering from this deadly infection. The immunomodulator [Buttner, M., 1993. Comp. Immun. Microbiol. Infect. Dis. 18, 1-10] used in those studies was the so-called 'paramunity inducer' PIND-ORF (Baypamun, Bayer, Leverkusen, Germany) consisting of inactivated parapox ovis virus. Since that time, Baypamun is the most commonly used drug for treatment of FeLV infection in Germany and other European countries. Four placebo-controlled double-blind trials were performed to determine the therapeutic efficacy of Baypamun and other compounds in naturally FeLV-infected cats under controlled conditions.", "journal": "Veterinary microbiology", "doi": "10.1016/s0378-1135(99)00097-8", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10515277", "author": "Jarrett O", "n_authors": 1, "title": "Strategies of retrovirus survival in the cat.", "abstract": "Retroviruses establish persistent infections in their hosts which often lead to serious and fatal diseases after a long incubation period. The molecular basis of this persistence is the integration of a copy of the viral genome into cellular chromosomal DNA. At the level of the whole animal, however, each retrovirus genus has evolved a different strategy to ensure its survival. This variety is well illustrated in the cat. Feline leukaemia virus, an oncovirus, has a simple genomic structure and survives in its host by suppressing the immune response to the virus. As a result, this virus is antigenically highly conserved. By contrast, feline immunodeficiency virus and feline foamy virus, representatives of the lentiviruses and spumaviruses, respectively, have more complex genomes which include genes responsible for maintaining the virus in a latent state thereby avoiding elimination in the face of a powerful antiviral immune response. In the lentiviruses, this response drives the selection of viruses exhibiting variation in antigenicity and pathogenicity.", "journal": "Veterinary microbiology", "doi": "10.1016/s0378-1135(99)00095-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10507363", "author": "Linenberger ML", "n_authors": 6, "title": "Lymphokines modulate the growth and survival of thymic tumor cells containing a novel feline leukemia virus/Notch2 variant.", "abstract": "Tumorigenesis occurs through a multistep process initiated by genetic lesions and facilitated by endogenous and external growth/survival signals. In many malignancies, specific oncogenic mutations correlate with phenotypic characteristics, inferring lineage-specific pathogenic mechanisms. To characterize these relationships in a unique feline tumor, we studied primary cells and two-cell lines independently-derived from a thymic lymphoma that contained and actively expressed a novel feline leukemia virus (FeLV) recombinant with transduced host Notch2 sequences. All three tumor cell populations contained similar FeLV/Notch2 proviral variants and phenotypically resembled mature thymocytes. Multiple Notch2 transcripts were expressed in the cell lines, including species that correspond to viral genomes and spliced subgenomic viral mRNA. Tumor cell line FeLV/Notch2 virus was packaged into virions; however, the variant was not efficiently transmitted to feline cells in vitro. Primary tumor cells constitutively expressed mRNA for interleukin-4 (IL-4), IL-6 and the p40 subunit of IL-12. Lymphokine mRNA was not detected in established tumor cell lines nor was T-cell growth-promoting activity found in culture supernatants. Exogenous IL-4 enhanced primary tumor cell survival, but inhibited proliferation of the cell lines. Interleukin-4 abrogated hydrocortisone-induced apoptosis in all three populations and had divergent effects on cell line clonogenic colony formation. Exogenous IL-7 and, to a lesser degree, IL-6 also had variable positive effects on the growth and viability of the tumor cell populations. Collectively, these data suggest that thymocytes are susceptible to the transforming potential of dysregulated Notch2 and that thymopoietic factors could, through overlapping and distinct mechanisms, promote the survival and outgrowth of FeLV/Notch2-containing neoplastic cells.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/s0165-2427(99)00075-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10486157", "author": "Breuer W", "n_authors": 3, "title": "Myelodysplastic syndrome (MDS), acute myeloid leukaemia (AML) and chronic myeloproliferative disorder (CMPD) in cats.", "abstract": "Histological, enzyme histochemical and ultrastructural findings in three cases of feline bone marrow neoplasia are described. The following changes were observed: in myelodysplastic syndrome (MDS), a low medullary blast count, strongly atypical (micromegakaryocytic) proliferative megakaryocytopoiesis, hypoplastic erythrocytopoiesis with impairment of differentiation, multifocal extravasation and lymphoid aggregates; in acute myeloid leukaemia (AML), medullary proliferation of undifferentiated cell types; in chronic myeloIproliferative disorder (CMPD), trilinear medullary proliferation with complete cellular maturation, osteomyelosclerosis and extramedullary haemopoiesis. In two cases (MDS, AML), ultrastructural demonstration of C-type virus particles (feline leukaemia virus) suggested a viral aetiology.", "journal": "Journal of comparative pathology", "doi": "10.1053/jcpa.1999.0314", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10400745", "author": "Tailor CS", "n_authors": 3, "title": "A putative cell surface receptor for anemia-inducing feline leukemia virus subgroup C is a member of a transporter superfamily.", "abstract": "Domestic cats infected with the horizontally transmitted feline leukemia virus subgroup A (FeLV-A) often produce mutants (termed FeLV-C) that bind to a distinct cell surface receptor and cause severe aplastic anemia in vivo and erythroblast destruction in bone marrow cultures. The major determinant for FeLV-C-induced anemia has been mapped to a small region of the surface envelope glycoprotein that is responsible for its receptor binding specificity. Thus, erythroblast destruction may directly or indirectly result from FeLV-C binding to its receptor. To address these issues, we functionally cloned a putative cell surface receptor for FeLV-C (FLVCR) by using a human T-lymphocyte cDNA library in a retroviral vector. Expression of the 2.0-kbp FLVCR cDNA in naturally resistant Swiss mouse fibroblasts and Chinese hamster ovary cells caused substantial susceptibility to FeLV-C but no change in susceptibilities to FeLV-B and other retroviruses. The predicted FLVCR protein contains 555 amino acids and 12 hydrophobic potential membrane-spanning sequences. Database searches indicated that FLVCR is a member of the major-facilitator superfamily of transporters and implied that it may transport an organic anion. RNA blot analyses showed that FLVCR mRNA is expressed in multiple hematopoietic lineages rather than specifically in erythroblasts. These results suggest that the targeted destruction of erythroblasts by FeLV-C may derive from their greater sensitivity to this virus rather than from a preferential susceptibility to infection.", "journal": "Journal of virology", "doi": "10.1128/JVI.73.8.6500-6505.1999", "deposited_data": "Sim", "nuccore_ids": "1519315556, 322812157, 5565871, 2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10341084", "author": "Barr NI", "n_authors": 7, "title": "The fit-1 common integration locus in human and mouse is closely linked to MYB.", "abstract": "The fit-1 locus was originally identified as a common insertion site for feline leukemia virus (FeLV) in thymic lymphosarcomas induced by FeLV-myc recombinant viruses, suggesting that it harbors a gene that cooperates with Myc in T-cell leukemogenesis. We have previously mapped the fit-1 locus to feline Chromosome (Chr) B2. We have now identified conserved sequences that allow the mapping of the murine homolog using the European Interspecific Backcross (EUCIB). This shows that fit-1 is located on mouse Chr 10, 1cM proximal to Ahi-1, a murine retroviral integration locus that is closely linked to Myb. Moreover, the physical linkage to MYB is maintained in the human genome, as shown by cloning of the human homolog of fit-1 from a Chr 6 cosmid library and a series of overlapping PAC clones. Generation of a contig map around the human homolog of fit-1 reveals that it is approximately 100-kb upstream of MYB. In addition to fit-1 and Ahi-1, two other common insertion sites, Mis-2 and Mml-1, have also been mapped adjacent to Myb on mouse Chr 10. Previous analysis of tumors carrying insertions at fit-1, Mml-1, Mis-2 and Ahi-1 showed no obvious abnormalities in Myb expression. However, the cluster of viral insertion loci in this region suggests either the presence of a closely linked activation target or that subtle effects on Myb have been overlooked.", "journal": "Mammalian genome : official journal of the International Mammalian Genome Society", "doi": "10.1007/s003359901043", "deposited_data": "Sim", "nuccore_ids": "2707682558, 2707682364, 2707682315, 2707682309, 2707682295, 5359633, 5359632, 2707682558, 2707682364, 2707682315, 2707682309, 2707682295, 2497762068, 2497762067, 2497762050, 2497762005, 2497761981, 2497761965, 2497761948, 2462578435, 2462578433, 2217332033, 2217332032, 1907076130, 1907076128, 1907076127, 1907076125, 1890336247, 1701262052, 1676317148, 1653962473, 27894325", "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10233955", "author": "Ghosh SK", "n_authors": 2, "title": "Feline leukemia virus long terminal repeat activates collagenase IV gene expression through AP-1.", "abstract": "Leukemia and lymphoma induced by feline leukemia viruses (FeLVs) are the commonest forms of illness in domestic cats. These viruses do not contain oncogenes, and the source of their pathogenic activity is not clearly understood. Mechanisms involving proto-oncogene activation subsequent to proviral integration and/or development of recombinant viruses with enhanced replication properties are thought to play an important role in their disease pathogenesis. In addition, the long terminal repeat (LTR) regions of these viruses have been shown to be important determinants for pathogenicity and tissue specificity, by virtue of their ability to interact with various transcription factors. Previously, we have shown that, in the case of Moloney murine leukemia virus, the U3 region of the LTR independently induces transcriptional activation of specific cellular genes through an LTR-generated RNA transcript (S. Y. Choi and D. V. Faller, J. Biol. Chem. 269:19691-19694, 1994; S.-Y. Choi and D. V. Faller, J. Virol. 69:7054-7060, 1995). In this report, we show that the U3 region of exogenous FeLV LTRs can induce transcription from collagenase IV (matrix metalloproteinase 9) and monocyte chemotactic protein 1 (MCP-1) promoters up to 12-fold. We also show that AP-1 DNA-binding activity and transcriptional activity are strongly induced in cells expressing FeLV LTRs and that LTR-specific RNA transcripts are generated in those cells. Activation of mitogen-activated protein kinase kinases 1 and 2 (MEK1 and -2) by the LTR is an intermediate step in the FeLV LTR-mediated induction of AP-1 activity. These findings thus suggest that the LTRs of FeLVs can independently activate transcription of specific cellular genes. This LTR-mediated cellular gene transactivation may play an important role in tumorigenesis or preleukemic states and may be a generalizable activity of leukemia-inducing retroviruses.", "journal": "Journal of virology", "doi": "10.1128/JVI.73.6.4931-4940.1999", "deposited_data": "Sim", "nuccore_ids": "2283599713, 2283599664", "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10231950", "author": "Kabeya H", "n_authors": 4, "title": "Bovine leukaemia virus envelope peptides cause immunomodulation in BALB/c mice.", "abstract": "Immunomodulatory activity of two bovine leukaemia virus envelope (BLVEnv) derived peptides were examined in BALB/c mice. One is peptide homologous to CKS-17 which is known as a 17-amino acid peptide derived from p15E of feline leukaemia virus (CKS-17/BLV), and the other is an 18-amino acid synthetic peptide of BLV Env 61-78 (pep61). Priming with CKS-17/BLV in vitro, as well as CKS-17, significantly suppressed the mitogen-induced proliferative responses of spleen cells in naive BALB/c mice. In addition, priming of spleen cells with pep61 in vitro and in vivo resulted in suppression of lipopolysaccaride-induced B-cell proliferative response. This suppression was partially due to the basic amino acid sequence in the peptide because if the pep61-derived peptide lacking Arg was used, this inhibitory activity was partially restored. In contrast, pep61 enhanced both concanavalin A-stimulated proliferative response and IL-2 production. These findings showed that pep61 may contribute to the modification of the host immune responses in the course of BLV infection.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/s0165-2427(99)00005-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10212684", "author": "Lappin MR", "n_authors": 2, "title": "Bartonella spp infection as a possible cause of uveitis in a cat.", "abstract": "A 6-year-old castrated mixed-breed cat was evaluated because of unilateral anterior uveitis. The cat was seronegative for antibodies to Toxoplasma gondii, coronaviruses, and feline immunodeficiency virus, and antigens for FeLV p27 and Cryptococcus neoformans. Antibodies to Bartonella spp were detected in serum and aqueous humor. The antibody coefficient (C value) for IgG antibodies to Bartonella spp in the aqueous humor was 4.42; values > 1 suggest ocular production of antibodies and supports a diagnosis of ocular infection. Topical administration of prednisolone and oral administration of prednisone failed to induce a response; however, the uveitis resolved rapidly after the cat was given doxycycline orally. Clinical or laboratory evidence of immunodeficiency in this cat was not detected. Detection of a serum IgG antibody titer to Bartonella spp and ocular production of IgG antibodies to Bartonella spp, exclusion of other causes of uveitis, and response to doxycycline suggests that the cat may have had bartonellosis resulting in uveal tract inflammation.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10098636", "author": "Bechtel MK", "n_authors": 6, "title": "Recombinant feline leukemia virus (FeLV) variants establish a limited infection with altered cell tropism in specific-pathogen-free cats in the absence of FeLV subgroup A helper virus.", "abstract": "Feline leukemia virus subgroup B (FeLV-B) is commonly associated with feline lymphosarcoma and arises through recombination between endogenous retroviral elements inherited in the cat genome and corresponding regions of the envelope (env) gene from FeLV subgroup A (FeLV-A). In vivo infectivity for FeLV-B is thought to be inefficient in the absence of FeLV-A. Proposed FeLV-A helper functions include enhanced replication efficiency, immune evasion, and replication rescue for defective FeLV-B virions. In vitro analysis of the recombinant FeLV-B-like viruses (rFeLVs) employed in this study confirmed these viruses were replication competent prior to their use in an in vivo study without FeLV-A helper virus. Eight specific-pathogen-free kittens were inoculated with the rFeLVs alone. Subsequent hematology and histology results were within normal limits, however, in the absence of detectable viremia, virus expression, or significant seroconversion, rFeLV proviral DNA was detected in bone marrow tissue of 4/4 (100%) cats at 45 weeks postinoculation (pi), indicating these rFeLVs established a limited but persistent infection in the absence of FeLV-A. Altered cell tropism was also noted. Focal infection was seen in T-cell areas of the splenic follicles in 3/4 (75%) rFeLV-infected cats analyzed, while an FeLV-A-infected cat showed focal infection in B-cell areas of the splenic follicles. Nucleotide sequence analysis of the surface glycoprotein portion of the rFeLV env gene amplified from bone marrow tissue collected at 45 weeks pi showed no sequence alterations from the original rFeLV inocula.", "journal": "Veterinary pathology", "doi": "10.1354/vp.36-2-91", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10087489", "author": "Day MJ", "n_authors": 5, "title": "T-cell-rich B-cell lymphoma in the cat.", "abstract": "The clinical and pathological features of eight cases of feline T-cell-rich B-cell lymphoma are described. The disease occurred in older cats (mean age 11.4 +/- 3.9 years), which on initial examination generally showed enlargement of a single submandibular or cervical lymph node. After excision, there was no recurrence of the lesions at 6 months in three cats. In one further case, however, the lesion had recurred 6 months later; it was again excised but recurred after an additional 6 months. Microscopically, there was effacement of normal lymph node architecture by a nodular (n = 4) or diffuse (n = 4) proliferation of small to blastic lymphocytes, accompanied by a characteristic population of bizarre giant, or multinucleate, cells. The mitotic rate was low and mitoses were restricted to the atypical population. Immunophenotyping revealed the smaller lymphocytes to be a mixture of CD3+ MHC Class II+ T lymphocytes and BLA36+CD79variable MHC Class IIvariable B lymphocytes. The atypical cells were of the B-cell lineage (BLA36+MHC Class IIvariable). Polymerase chain reaction analysis revealed no proviral DNA products of feline leukaemia virus or feline immunodeficiency virus in tissue from any tumour, confirming that these neoplasms were not associated with either virus. The clinical, histological and immunophenotypic findings in these cats were identical with those of \"nodular lymphocyte predominance (lymphocytic and histiocytic/L&H) Hodgkin's disease\" in man.", "journal": "Journal of comparative pathology", "doi": "10.1053/jcpa.1998.0267", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10073361", "author": "Daniels MJ", "n_authors": 4, "title": "Feline viruses in wildcats from Scotland.", "abstract": "Few data are available on the prevalence of feline viruses in European wildcats (Felis silvestris). Previous surveys have indicated that wildcats may be infected with the common viruses of domestic cats, apart from feline immunodeficiency virus (FIV). In the present study, 50 wildcats trapped throughout Scotland (UK) between August 1992 and January 1997 were tested for evidence of viral infection. All were negative for FIV by several serological or virological methods. By contrast, 10% of the cats were positive for feline leukemia virus (FeLV) antigen and infectious virus was isolated from 13% of a smaller subset. Of the wildcats tested for respiratory viruses, 25% yielded feline calicivirus (FCV) and although no feline herpesvirus was isolated, 16% of the samples had neutralizing antibodies to this virus. Antibodies to feline coronavirus (FCoV) were found in 6% of samples. Feline foamy virus (FFV) was an incidental finding in 33% of samples tested. This study confirms that wildcats in Scotland are commonly infected with the major viruses of the domestic cat, except for FIV.", "journal": "Journal of wildlife diseases", "doi": "10.7589/0090-3558-35.1.121", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "9887944", "author": "Stokol T", "n_authors": 2, "title": "Pure red cell aplasia in cats: 9 cases (1989-1997).", "abstract": "To evaluate clinical features, laboratory test results, treatment, and outcome of FeLV-negative cats with pure red cell aplasia (PRCA) diagnosed by examination of bone marrow. Retrospective study. 9 cats. Medical records and smears of bone marrow aspirates were reviewed to determine clinical features, laboratory test results, treatment, and outcome of this syndrome in cats. PRCA was diagnosed in 9 cats that were between 8 months and 3 years old. Cats had 2- to 16-day histories of lethargy and anorexia, and a severe normocytic, normochromic to hypochromic, nonregenerative anemia (Hct range, 6 to 15%; reference range, 25 to 45%). Other hematologic values were generally within reference ranges. Consistent changes in biochemical profiles included high aminotransferase activities and hyperferremia. Cats were seronegative for FeLV and feline immunodeficiency virus. Smears of bone marrow aspirates were characterized by absence of identifiable erythroid precursors and a high proportion of small lymphocytes. Abnormalities were not identified in megakaryocytes or myeloid cells. Treatment with immunosuppressive drugs (corticosteroids and cyclophosphamide or cyclosporin) resulted in resolution of anemia within 3 to 5 weeks. Most cats required long-term treatment to maintain Hct within reference range and tended to relapse when treatment frequency or dosage was decreased (especially if done rapidly) or treatment was discontinued. PRCA is a rare syndrome in young FeLV-negative cats, and is characterized by severe nonregenerative anemia and absence of erythroid cells in bone marrow. The condition requires prompt, aggressive, often long-term treatment with immunosuppressive drugs for resolution.", "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "11716621", "author": "Comazzi S", "n_authors": 4, "title": "Erythremic myelosis (AML6er) in a cat.", "abstract": "A 4-year-old male European domestic cat was presented with dysorexia, weakness and depression. Normocytic normochromic non-regenerative anaemia, leucopaenia and thrombocytopenia were detected. Rubriblasts were detected both in the blood and in the bone marrow. Tests of blood chemistry revealed no alterations of renal and hepatic function and a positive reaction to FeLV antigen was detected in the cat's serum. Neoplastic cells did not show positive to cytochemical reactions against granulocytes, monocytes and lymphocytes. According to haematological and bone marrow cytological findings, a diagnosis of erythremic myelosis (AML6er) was made. Histopathology showed extramedullary haematopoiesis in the liver, spleen, kidney and lymph nodes and chronic nephropathy and degenerative signs in the liver.", "journal": "Journal of feline medicine and surgery", "doi": "10.1053/jfms.2000.0101", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "11716594", "author": "Yilmaz H", "n_authors": 3, "title": "Prevalence of FIV and FeLV infections in cats in Istanbul.", "abstract": null, "journal": "Journal of feline medicine and surgery", "doi": "10.1053/jfms.2000.0066", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "11701533", "author": "Young NS", "n_authors": 3, "title": "New Insights into the Pathophysiology of Acquired Cytopenias.", "abstract": "This review addresses three related bone marrow failure diseases, the study of which has generated important insights in hematopoiesis, red cell biology, and immune-mediated blood cell injury. In Section I, Dr. Young summarizes the current knowledge of acquired aplastic anemia. In most patients, an autoimmune mechanism has been inferred from positive responses to nontransplant therapies and laboratory data. Cytotoxic T cell attack, with production of type I cytokines, leads to hematopoietic stem cell destruction and ultimately pancytopenia; this underlying mechanism is similar to other human disorders of lymphocyte-mediated, tissue-specific organ destruction (diabetes, multiple sclerosis, uveitis, colitis, etc.). The antigen that incites disease is unknown in aplastic anemia as in other autoimmune diseases; post-hepatitis aplasia is an obvious target for virus discovery. Aplastic anemia can be effectively treated by either stem cell transplantation or immunosuppression. Results of recent trials with antilymphocyte globulins and high dose cyclophosphamide are reviewed. Dr. Abkowitz discusses the diagnosis and clinical approach to patients with acquired pure red cell aplasia, both secondary and idiopathic, in Section II. The pathophysiology of various PRCA syndromes including immunologic inhibition of red cell differentiation, viral infection (especially human parvovirus B19), and myelodysplasia are discussed. An animal model of PRCA (secondary to infection with feline leukemia virus [FeLV], subgroup C) is presented. Understanding the mechanisms by which erythropoiesis is impaired provides for insights into the process of normal red cell differentiation, as well as a rational strategy for patient management. Among the acquired cytopenias paroxysmal nocturnal hemoglobinuria (PNH) is relatively rare; however, it can pose formidable management problems. Since its first recognition as a disease, PNH has been correctly classified as a hemolytic anemia; however, the frequent co-existence of other cytopenias has hinted strongly at a more complex pathogenesis. In Section III, Dr. Luzzatto examines recent progress in this area, with special emphasis on the somatic mutations in the PIG-A gene and resulting phenotypes. Animal models of PNH and the association of PNH with bone marrow failure are also reviewed. Expansion of PNH clones must reflect somatic cell selection, probably as part of an autoimmune process. Outstanding issues in treatment are illustrated through clinical cases of PNH. Biologic inferences from PNH may be relevant to our understanding of more common marrow failure syndromes like myelodysplasia.", "journal": "Hematology. American Society of Hematology. Education Program", "doi": "10.1182/asheducation-2000.1.18", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "11428405", "author": "Langan J", "n_authors": 5, "title": "Tyzzer's disease in a red panda (Ailurus fulgens fulgens).", "abstract": "A debilitated 9-yr-old female red panda (Ailurus fulgens fulgens) with a recent history of corticosteroid administration displayed anorexia, depression, and diarrhea for 2 days. Blood work revealed a moderate nonregenerative anemia, leukocytosis, hypokalemia, hyperbilirubinemia, and mildly elevated alanine aminotransferase and aspartate aminotransferase. Serology was negative for occult heartworm, Toxoplasma gondii, feline leukemia virus, feline infectious peritonitis, feline immunodeficiency virus, and canine distemper virus. Electron microscopy of the feces demonstrated corona-like virus particles. The panda died 3 days after initial presentation. Histologic findings included multifocal, acute, hepatic necrosis and diffuse, necrotizing colitis. Liver and colon lesions contained intracellular, curved, spore-forming, gram-negative, silver-positive rods morphologically consistent with Clostridium piliforme. This panda most likely contracted Tyzzer's disease subsequent to having a compromised immune system after corticosteroid administration and concurrent disease.", "journal": "Journal of zoo and wildlife medicine : official publication of the American Association of Zoo Veterinarians", "doi": "10.1638/1042-7260(2000)031[0558:TSDIAR]2.0.CO;2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "11153220", "author": "Kalz B", "n_authors": 4, "title": "[Health status and causes of mortality in feral cats in a delimited area of the inner city of Berlin].", "abstract": "Results of the veterinary examination of feral cats living in a delimited area of Berlin city are presented. Between 1996 and 1999 thirty nine cats were investigated, among them eleven individuals twice. All animals were positive for one or several pathologies, but only seven cats were in bad condition. Most common were periodontal and gingival diseases, followed by conjunctivitis. Five cats were positive for FIV, seven for FeLV, one tomcat for both. Twenty six cats vanished during the study period of 42 months, only one third of cats survived and remained in the study area throughout. Four cats were given to pet lovers, nine cats disappeared without trace, seven animals died in traffic accidents and six cats died of illnesses. Cats less than three years of age vanished more often than expected from their representation in the population. Dirty or large feeding places for cats constitute a source of infections. Feeding sites should be accessible to only few individuals and left-overs that may attract stray cats, rats or birds should not remain at feeding places.", "journal": "Berliner und Munchener tierarztliche Wochenschrift", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "11090631", "author": "Lauring AS", "n_authors": 2, "title": "Evidence that an IRES within the Notch2 coding region can direct expression of a nuclear form of the protein.", "abstract": "We previously reported the isolation from a thymic tumor of a feline leukemia virus that had transduced a fragment of the Notch2 gene. Here we present evidence that a nuclear form of Notch2 corresponding to the biologically active intracellular domain (N2ICD) is expressed from this recombinant retrovirus through internal ribosome entry. Internal ribosome entry sites (IRESs) are RNA structural motifs that allow 5' cap-independent recruitment of ribosomal subunits to mRNAs. The Notch2 IRES maps exclusively to Notch2 sequences that correspond to the coding region of the cellular gene. Therefore, these studies not only provide insights into aberrant Notch2 expression in tumors, but they may also inform our understanding of N2ICD generation in the cellular context.", "journal": "Molecular cell", "doi": "10.1016/s1097-2765(05)00084-5", "deposited_data": "Sim", "nuccore_ids": "1889602511, 1519312484", "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "11073076", "author": "Hisasue M", "n_authors": 12, "title": "Clonality analysis of various hematopoietic disorders in cats naturally infected with feline leukemia virus.", "abstract": "The clonality analysis of the bone marrow cells was carried out by detecting the integrated proviruses of feline leukemia virus (FeLV) to understand the pathogenesis of FeLV-associated hematopoietic disorders in cats. Bone marrow cells from 4 cases with acute myeloid leukemia (AML), 9 cases with myelodysplastic syndromes (MDS), 2 cases with pure red cell aplasia (PRCA) and 3 healthy carriers infected with FeLV were subjected to Southern blot analyses using an exogenous FeLV probe. Clonal hematopoiesis was found in all the cases with AML and in 6 of the 9 cases with MDS, but not in the cases with both PRCA and healthy carriers infected with FeLV. In the 2 cases with MDS, it was thought that the same clones of the hematopoietic cells might proliferate before and after the progression of the disease irrespective of the changes of the hematological diagnoses by cytological examination. This study indicates that MDS in cats is a disease manifestation as a result of clonal proliferation of hematopoietic cells and can be recognized as a pre-leukemic state of AML.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.62.1059", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "11062034", "author": "Phipps AJ", "n_authors": 5, "title": "Inhibition of feline leukemia virus subgroup A infection by coinoculation with subgroup B.", "abstract": "Feline leukemia virus (FeLV) subgroup B arises de novo through recombination between the env genes of exogenous FeLV subgroup A and endogenous FeLV-like sequences. FeLV-B, which by itself is poorly infectious, will increase to high titer in the presence of FeLV-A, and is associated with FeLV-related neoplastic disease. Although the participation of FeLV-B in disease progression has not been definitively proven, circumstantial evidence supports the hypothesis that the generation of FeLV-B is linked to disease progression. The present study was designed to evaluate whether increasing the levels of FeLV-B early in FeLV-A infection could result in reduction of the incubation period for development of neoplastic disease. For this study, an isolate of FeLV-B, designated FeLV-1B3, was biologically cloned, partially sequenced, and subgroup typed. In in vivo studies, none of the neonatal cats inoculated with FeLV-1B3 alone converted to viremia positive, and all remained healthy throughout the observation period. All of the kittens inoculated with FeLV-A alone became chronically viremic, and those held for long-term observation all developed either neoplastic disease or anemia. However, kittens inoculated with the combination of FeLV-1B3 and FeLV-A showed attenuated infections whereby the majority of cats failed to develop chronic viremia. The apparent interference of FeLV-A infection by FeLV-B was time and titer dependent. This unexpected result suggests that FeLV-B may act as an attenuated virus, causing inhibition of FeLV-A possibly through an immune-mediated mechanism. Partial support for this view was provided by postmortem examination of cats inoculated with FeLV-1B3 alone. Even though none of these cats became viremic, FeLV antigen was detected as focal infections in select tissues, especially salivary gland epithelium, where enough antigen may be expressed to provide an immunizing dose against gag and pol cross-reacting antigens. This work may also provide another approach to vaccine development based on endogenous retrovirus vector systems.", "journal": "Virology", "doi": "10.1006/viro.2000.0606", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "11033869", "author": "Willis AM", "n_authors": 1, "title": "Feline leukemia virus and feline immunodeficiency virus.", "abstract": "Ophthalmic manifestations of FeLV or FIV infection can occur in all ocular tissues and may be manifestations of direct viral effects or secondary to viral-related malignant transformation. Additionally, the manifestations of common feline ophthalmic pathogens may be more severe and poorly responsive to therapy because of the immunosuppressive effects of FeLV or FIV infection. Prompt diagnosis of underlying viral infection in cats with ophthalmic disease is paramount for accurate diagnosis and prognosis and is required for appropriate therapeutic decision making.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": "10.1016/s0195-5616(00)05001-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "11012762", "author": "Flynn JN", "n_authors": 3, "title": "Feline leukaemia virus: protective immunity is mediated by virus-specific cytotoxic T lymphocytes.", "abstract": "Feline leukaemia virus (FeLV) nucleic acid vaccination of domestic cats affords protection against viraemia and the development of latency without inducing antiviral antibodies.1 To determine the contribution of cell-mediated immunity to the control of virus replication and clearance from the host, FeLV-specific cytotoxic T lymphocyte (CTL) responses were compared in vaccine-protected, transiently viraemic, and persistently viraemic cats. Vaccinal immunity was associated with the detection of higher levels of virus-specific effector CTL in the peripheral blood and lymphoid organs to FeLV Gag/Pro and Env antigens than those observed in unvaccinated control, persistently viraemic cats (P<0.001). Likewise, higher levels of virus-specific CTLs were also observed in transiently viraemic cats which recovered following exposure to FeLV. In cats that controlled their infection, recognition of Gag/Pro antigens was significantly higher than the recognition of Env antigens. This is the first report highlighting the very significant role that virus-specific CTL have in determining the outcome of FeLV infection in either vaccinated cats or cats recovering naturally from FeLV exposure.", "journal": "Immunology", "doi": "10.1046/j.1365-2567.2000.00089.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "11000257", "author": "Tailor CS", "n_authors": 3, "title": "Cellular and species resistance to murine amphotropic, gibbon ape, and feline subgroup C leukemia viruses is strongly influenced by receptor expression levels and by receptor masking mechanisms.", "abstract": "Chinese hamster ovary (CHO) cells are resistant to infections by gibbon ape leukemia virus (GALV) and amphotropic murine leukemia virus (A-MLV) unless they are pretreated with tunicamycin, an inhibitor of N-linked glycosylation. These viruses use the related sodium-phosphate symporters Pit1 and Pit2, respectively, as receptors in nonhamster cells, and evidence has suggested that the corresponding transporters of CHO cells may be masked by tunicamycin-sensitive secreted inhibitors. Although the E36 line of Chinese hamster cells was reported to secrete the putative Pit2 inhibitor and to be sensitive to the inhibitory CHO factors, E36 cells are highly susceptible to both GALV and A-MLV in the absence of tunicamycin. Moreover, expression of E36 Pit2 in CHO cells conferred tunicamycin-independent susceptibilities to both viruses. Based on the latter results, it was suggested that E36 Pit2 must functionally differ from the endogenous Pit2 of CHO cells. To test these ideas, we analyzed the receptor properties of CHO Pit1 and Pit2 in CHO cells. Surprisingly, and counterintuitively, transfection of a CHO Pit2 expression vector into CHO cells conferred strong susceptibility to both GALV and A-MLV, and similar overexpression of CHO Pit1 conferred susceptibility to GALV. Thus, CHO Pit2 is a promiscuous functional receptor for both viruses, and CHO Pit1 is a functional receptor for GALV. Similarly, we found that the natural resistance of Mus dunni tail fibroblasts to subgroup C feline leukemia viruses (FeLV-C) was eliminated simply by overexpression of the endogenous FeLV-C receptor homologue. These results demonstrate a novel and simple method to unmask latent retroviral receptor activities that occur in some cells. Specifically, resistances to retroviruses that are caused by subthreshold levels of receptor expression or by stoichiometrically limited masking or interference mechanisms can be efficiently overcome simply by overexpressing the endogenous receptors in the same cells.", "journal": "Journal of virology", "doi": "10.1128/jvi.74.20.9797-9801.2000", "deposited_data": "Sim", "nuccore_ids": "345842528, 10716881, 10716879, 1868056668, 1868056667, 1868056666, 345842528", "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "11000248", "author": "Ghosh SK", "n_authors": 3, "title": "Long terminal repeat regions from exogenous but not endogenous feline leukemia viruses transactivate cellular gene expression.", "abstract": "We have previously reported that the long terminal repeat (LTR) region of feline leukemia viruses (FeLVs) can enhance expression of certain cellular genes such as the collagenase IV gene and MCP-1 in trans (S. K. Ghosh and D. V. Faller, J. Virol. 73:4931-4940, 1999). Genomic DNA of all healthy feline species also contains LTR-like sequences that are related to exogenous FeLV LTRs. In this study, we evaluated the cellular gene transactivational potential of these endogenous FeLV LTR sequences. Unlike their exogenous FeLV counterparts, neither nearly full-length endogenous FeLV molecular clones (CFE-6 and CFE-16) nor their isolated LTRs were able to activate collagenase IV gene or MCP-1 expression in transient transfection assays. We had also demonstrated previously that production of an RNA transcript from exogenous FeLV LTRs correlates with their transactivational activity. In the present study, we demonstrate that the endogenous FeLV LTRs do not generate LTR-specific RNA transcripts in the feline embryo fibroblast cell line AH927. Furthermore, infection of AH927 cells by an exogenous FeLV subgroup A virus did not induce production of such LTR-specific transcripts from the endogenous proviral genomes, although the LTR-specific transcripts from the exogenous virus were readily detected. Finally, LTR-specific transcripts were not generated in BALB/3T3 cells transiently transfected with isolated CFE-6 LTR, in contrast to transfections with LTRs from exogenous viruses. Our data thus suggest that the inability of endogenous FeLV LTRs in gene transactivation is not due to cell line specificity or presence of any upstream inhibitory cis-acting element. Endogenous, nonleukemogenic FeLV LTRs, therefore, do not transactivate cellular gene expression, and this property appears to be specific to exogenous, leukemogenic FeLVs.", "journal": "Journal of virology", "doi": "10.1128/jvi.74.20.9742-9748.2000", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10993195", "author": "Nakamura K", "n_authors": 9, "title": "Contrastive prevalence of feline retrovirus infections between northern and southern Vietnam.", "abstract": "The prevalence of infections with three feline retroviruses; feline leukemia virus (FeLV), feline immunodeficiency virus (FIV) and feline foamy virus (FeFV), was examined in domestic cats (Felis catus) and leopard cats (Felis bengalensis) in southern Vietnam in 1998. We then compared this data with our previous study in northern Vietnam in 1997. None of the cats had FeLV antigens in both the northern and southern areas. In contrast, there is a great distinction in the seropositivity of FIV. Twenty-two percent of domestic cats had FIV antibodies whereas no FIV positive cats were detected in northern area. FIV may have entered southern Vietnam recently and spread rapidly. FeFV infections were found in both areas, suggesting that FeFV might be present in the cat populations in Vietnam from the earliest time.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.62.921", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10970400", "author": "Arjona A", "n_authors": 6, "title": "Seroepidemiological survey of infection by feline leukemia virus and immunodeficiency virus in Madrid and correlation with some clinical aspects.", "abstract": "A study of 180 healthy cats found that 15.6% were feline leukemia virus (FeLV) positive, 8.3% were feline immunodeficiency virus (FIV) positive, and 1.1% were FIV and FeLV positive, which corresponded to 30.4, 13.8, and 2.6, of 115 cats with FIV- and FeLV-related symptoms, respectively. Differences were seen in the sexes and ages of the populations studied. Anemia, leukopenia, and lymphopenia were the most frequent hematological abnormalities in infected cats.", "journal": "Journal of clinical microbiology", "doi": "10.1128/JCM.38.9.3448-3449.2000", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10899828", "author": "Josephson NC", "n_authors": 3, "title": "Transduction of feline hematopoietic cells by oncoretroviral vectors pseudotyped with the subgroup A feline leukemia virus (FeLV-A).", "abstract": "The domestic cat is an outbred species with many identified analogues of human genetic diseases. Therefore, it has the potential to serve as a large animal model for evaluating the feasibility of hematopoietic stem cell gene therapy. This study compared gene transfer rates into feline hematopoietic progenitors by oncoretroviral vectors pseudotyped with the subgroup A feline leukemia virus (FeLV-A), the gibbon ape leukemia virus (GALV), and the murine amphotropic virus. Gene transfer rates were superior with the FeLV-A pseudotypes, which were then tested for their ability to transduce a cat hematopoietic repopulating cell. At more than 1 year posttransplantation, persistent marking was seen in both lymphoid and myeloid lineages of a myeloablated domestic cat that had received autologous marrow cells transduced with an FeLV-A pseudotyped vector.", "journal": "Molecular therapy : the journal of the American Society of Gene Therapy", "doi": "10.1006/mthe.2000.0090", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10852967", "author": "Rasko JE", "n_authors": 5, "title": "Precise gene localization by phenotypic assay of radiation hybrid cells.", "abstract": "A high resolution map of the human genome previously has been constructed by using the G3 panel of human/hamster radiation hybrid cell lines and >15,000 unique human genetic markers. By determining whether human DNA sequences are present or absent in each of the hybrids, localization of single genes may routinely be achieved at approximately 250-kb resolution. In this paper we have tested whether similarly precise localization might be achieved by phenotypic screening of the hybrids to facilitate positional cloning of unknown genes. We assayed the susceptibility of each of the hybrid cell lines to transduction by retroviral vectors bearing different retroviral envelope proteins that recognize receptors present on human but not on hamster cells. The results for each of the retroviral vectors were informative and allowed precise localization of the receptor genes for the RD114 cat endogenous retrovirus, xenotropic murine leukemia virus, and type C feline leukemia virus. After cloning of the receptors for these retroviruses, we found that standard genotypic mapping by PCR gave results that were nearly identical to those from phenotypic mapping. These experiments show that precise gene localization by phenotypic assay of radiation hybrids is practical and was not appreciably impacted by the known instability of such hybrid cells. This technique should be applicable to many other human genes having discernible phenotypes in hamster cells and, with completion of the human genome project, will allow rapid identification of unknown genes on the basis of phenotype.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.130200097", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10846058", "author": "Phipps AJ", "n_authors": 5, "title": "Differential pathogenicity of two feline leukemia virus subgroup A molecular clones, pFRA and pF6A.", "abstract": "F6A, a molecular clone of subgroup A feline leukemia virus (FeLV) is considered to be highly infectious but weakly pathogenic. In recent studies with a closely related subgroup A molecular clone, FRA, we demonstrated high pathogenicity and a strong propensity to undergo recombination with endogenous FeLV (enFeLV), leading to a high frequency of transition from subgroup A to A/B. The present study was undertaken to identify mechanisms of FeLV pathogenesis that might become evident by comparing the two closely related molecular clones. F6A was shown to have an infectivity similar to that of FRA when delivered as a provirus. Virus load and antibody responses were also similar, although F6A-infected cats consistently carried higher virus loads than FRA-infected cats. However, F6A-infected cats were slower to undergo de novo recombination with enFeLV and showed slower progression to disease than FRA-infected cats. Tumors collected from nine pF6A- or pFRA-inoculated cats expressed lymphocyte markers for T cells (seven tumors) and B cells (one tumor), and non-T/B cells (one tumor). One cat with an A-to-A/C conversion developed erythrocyte hypoplasia. Genomic mapping of recombinants from pF6A- and pFRA-inoculated cats revealed similar crossover sites, suggesting that the genomic makeup of the recombinants did not contribute to increased progression to neoplastic disease. From these studies, the mechanism most likely to account for the pathologic differences between F6A and FRA is the lower propensity for F6A to undergo de novo recombination with enFeLV in vivo. A lower recombination rate is predicted to slow the transition from subgroup A to A/B and slow the progression to disease.", "journal": "Journal of virology", "doi": "10.1128/jvi.74.13.5796-5801.2000", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10846053", "author": "Gwynn SR", "n_authors": 5, "title": "Feline leukemia virus envelope sequences that affect T-cell tropism and syncytium formation are not part of known receptor-binding domains.", "abstract": "The envelope protein is a primary pathogenic determinant for T-cell-tropic feline leukemia virus (FeLV) variants, the best studied of which is the immunodeficiency-inducing virus, 61C. We have previously demonstrated that T-cell-tropic, cytopathic, and syncytium-inducing viruses evolve in cats infected with a relatively avirulent, transmissible form of FeLV, 61E. The envelope gene of an 81T variant, which encoded scattered single-amino-acid changes throughout the envelope as well as a 4-amino-acid insertion in the C-terminal half of the surface unit (SU) of envelope, was sufficient to confer the T-cell-tropic, cytopathic phenotype (J. L. Rohn, M. S. Moser, S. R. Gwynn, D. N. Baldwin, and J. Overbaugh, J. Virol. 72:2686-2696, 1998). In the present study, we examined the role of the 4-amino-acid insertion in determining viral replication and tropism of FeLV-81T. The 4-amino-acid insertion was found to be functionally equivalent to a 6-amino-acid insertion at an identical location in the 61C variant. However, viruses expressing a chimeric 61E/81T SU, containing the insertion together with the N terminus of 61E SU, were found to be replication defective and were impaired in the processing of the envelope precursor into the functional SU and transmembrane (TM) proteins. In approximately 10% of cultured feline T cells (3201) transfected with the 61E/81T envelope chimeras and maintained over time, replication-competent tissue culture-adapted variants were isolated. Compensatory mutations in the SU of the tissue culture-adapted viruses were identified at positions 7 and 375, and each was shown to restore envelope protein processing when combined with the C-terminal 81T insertion. Unexpectedly, these viruses displayed different phenotypes in feline T cells: the virus with a change from glutamine to proline at position 7 acquired a T-cell-tropic, cytopathic phenotype, whereas the virus with a change from valine to leucine at position 375 had slower replication kinetics and caused no cytopathic effects. Given the differences in the replication properties of these viruses, it is noteworthy that the insertion as well as the two single-amino-acid changes all occur outside of predicted FeLV receptor-binding domains.", "journal": "Journal of virology", "doi": "10.1128/jvi.74.13.5754-5761.2000", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10850843", "author": "Coronado GS Jr", "n_authors": 5, "title": "Effects of a 98% solution of glycerol or sterilization with ethylene oxide on FeLV in bone allografts and effects on bone incorporation of allografts in cats.", "abstract": "To compare virucidal effects and bone incorporation properties of cortical bone allografts transplanted into specific-pathogen-free (SPF) cats. Allografts consisted of untreated bone from a SPF cat (negative-control group) and bone from 5 FeLV-infected cats that was subjected to sterilization with ethylene oxide (ETO), preservation with glycerol, or no treatment (positive-control group). Bones from the aforementioned groups and twenty 8-week-old SPF cats (5 cats/group) implanted with an allograft from 1 of the aforementioned groups. After implantation, blood samples were collected weekly to monitor FeLV p27 antigen and antibody titers. Quantification of FeLV provirus was performed on blood samples at weeks 0, 4, and 8 and donor bone samples at time of implantation. Cats were euthanatized 8 weeks after transplantation, and graft sites were evaluated. All results for negative-control cats were negative. All ETO group cats had negative results for antigen and provirus in blood, whereas 1 cat had a low antibody titer. Although 3 ETO-treated allografts were positive for provirus, the DNA appeared denatured. One cat in the glycerol group had positive results for all tests in blood samples. All glycerol-preserved allografts were positive when tested for provirus. All results for positive-control group cats were positive. Differences in incorporation of bone grafts were not observed. Glycerol preservation of FeLV-infected bone allografts did not eliminate transmission of retrovirus to recipients. In contrast, ETO sterilization appeared to denature DNA and prevent infection. Treatments did not affect incorporation of bone grafts in young cats.", "journal": "American journal of veterinary research", "doi": "10.2460/ajvr.2000.61.665", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10811262", "author": "Addie DD", "n_authors": 6, "title": "Long-term impact on a closed household of pet cats of natural infection with feline coronavirus, feline leukaemia virus and feline immunodeficiency virus.", "abstract": "A closed household of 26 cats in which feline coronavirus (FCoV), feline leukaemia virus (FeLV) and feline immunodeficiency virus (FIV) were endemic was observed for 10 years. Each cat was seropositive for FCoV on at least one occasion and the infection was maintained by reinfection. After 10 years, three of six surviving cats were still seropositive. Only one cat, which was also infected with FIV, developed feline infectious peritonitis (FIP). Rising anti-FCoV antibody titres did not indicate that the cat would develop FIP. The FeLV infection was self-limiting because all seven of the initially viraemic cats died within five years and the remainder were immune. However, FeLV had the greatest impact on mortality. Nine cats were initially FIV-positive and six more cats became infected during the course of the study, without evidence of having been bitten. The FIV infection did not adversely affect the cats' life expectancy.", "journal": "The Veterinary record", "doi": "10.1136/vr.146.15.419", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10804261", "author": "Fitzgibbon WE", "n_authors": 2, "title": "Weakly coupled hyperbolic systems modeling the circulation of FeLV in structured feline populations.", "abstract": "Global existence and regularity results are provided for weakly coupled first order hyperbolic systems modeling the propagation of the Feline Leukemia Virus (FeLV), a retrovirus of domestic cats (Felis catus). In a simple example we find a threshold parameter yielding endemic stationary states.", "journal": "Mathematical biosciences", "doi": "10.1016/s0025-5564(00)00011-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10803986", "author": "Gueguen S", "n_authors": 6, "title": "Safety and efficacy of a recombinant FeLV vaccine combined with a live feline rhinotracheitis, calicivirus and panleukopenia vaccine.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.146.13.380-b", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10766116", "author": "Fromont E", "n_authors": 8, "title": "Prevalence and pathogenicity of retroviruses in wildcats in France.", "abstract": "Feline leukaemia virus (FeLV) and feline immunodeficiency virus (FIV) are frequently encountered in domestic cats (Felis catus) and in wild felids, but only FeLV has been previously identified in wildcats (Fellis silvestris). Thirty-eight wildcats, either captured alive or found dead, were sampled in eastern and central France. Nine of them (23.7 per cent) carried the FeLV p27 antigen, and three (7.9 per cent) had antibodies to FIV. There was a significant relationship between two measures of body condition and FeLV status; the FeLV-positive cats being in poorer condition than the FeLV-negative cats. The results suggest that FeLV is common in wildcats and may increase mortality in this species. The FIV-positive results constitute the first indication of a FIV-related virus in wildcats.", "journal": "The Veterinary record", "doi": "10.1136/vr.146.11.317", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10730956", "author": "Suchy A", "n_authors": 6, "title": "Diagnosis of feline herpesvirus infection by immunohistochemistry, polymerase chain reaction, and in situ hybridization.", "abstract": "An adult domestic shorthair cat had severe chemosis due to purulent and necrotizing blepharitis and conjunctivitis. Purulent rhinitis, necrotizing glossitis, and dermatitis were also diagnosed. The cat was positive for feline immunodeficiency virus and feline leukemia virus. Histologically, intranuclear Cowdry type A inclusions were found within numerous epithelial cells adjacent to the lesions in skin, conjunctiva, and tongue. Electron microscopic examination revealed herpesviral particles within the lesions. Paraffin-embedded skin and tongue tissues were processed in a polymerase chain reaction, using primers to amplify a 306-bp region of the thymidine kinase gene of feline herpesvirus type 1, resulting in a distinct amplification product of the predicted size. The distribution of feline herpesvirus was demonstrated by immunohistochemistry and nonradioactive in situ hybridization. Positive immunostaining was found in nuclei and cytoplasm of numerous epithelial cells within and next to the lesions, whereas in situ hybridization, performed with a digoxigenin-labeled double-stranded DNA probe, revealed hybridization signal only in nuclei of intact epithelial cells. Neither immunohistochemistry nor in situ hybridization showed feline herpesvirus type 1 in tissues of lungs, liver, spleen, intestine, or brain.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/104063870001200220", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10720191", "author": "Shimoda T", "n_authors": 4, "title": "Chronic myelomonocytic leukemia in a cat.", "abstract": "A 1-year-old spayed domestic short-haired cat was referred with anorexia and weight loss. Hematologic findings indicated nonregenerative anemia, severe neutropenia and monocytosis. The feline leukemia virus (FeLV) antigen test was positive reaction by enzyme-linked immunosorbent assay. Dysgranulopoiesis with slight increase in blast cells were observed in bone marrow smears. On the basis of blood and bone marrow findings, the cat was diagnosed as chronic myelomonocytic leukemia (CMMoL), which possibly corresponds to a kind of the subtypes in human myelodysplastic syndrome (MDS).", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.62.195", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10714641", "author": "Kipar A", "n_authors": 5, "title": "Expression of viral proteins in feline leukemia virus-associated enteritis.", "abstract": "Fourteen cases of feline leukemia virus (FeLV)-associated enteritis were immunohistologically examined for the expression of FeLV proteins gp70, p27, and p15E in the jejunum, mesenteric lymph nodes, spleen, and bone marrow. Results were compared with those of FeLV-infected cats without intestinal alterations. Other viral infections and specific bacterial, fungal, and parasitic infections were excluded by standard microbiologic methods, histopathology, immunohistology, and in situ hybridization. In FeLV-associated enteritis, FeLV gp70 and p15E were strongly expressed in intestinal crypt epithelial cells. In contrast, FeLV-positive cats without intestinal alterations showed only faint staining for gp70 and p15E and comparatively strong p27 expression in these cells. Findings suggest a direct relation between FeLV infection and alterations in intestinal crypt epithelial cells that may be attributed to the envelope proteins gp70 and p15E and/or their precursor protein. Distinct similarities to the intestinal changes in the experimentally induced FeLV-feline AIDS syndrome are obvious, suggesting that naturally occurring feline AIDS variants may be responsible for FeLV-associated enteritis.", "journal": "Veterinary pathology", "doi": "10.1354/vp.37-2-129", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10710311", "author": "Anderson MM", "n_authors": 4, "title": "Identification of a cellular cofactor required for infection by feline leukemia virus.", "abstract": "Retroviral infection involves continued genetic variation, leading to phenotypic and immunological selection for more fit virus variants in the host. For retroviruses that cause immunodeficiency, pathogenesis is linked to the emergence of T cell-tropic, cytopathic viruses. Here we show that an immunodeficiency-inducing, T cell-tropic feline leukemia virus (FeLV) has evolved such that it cannot infect cells unless both a classic multiple membrane-spanning receptor molecule (Pit1) and a second coreceptor or entry factor are present. This second receptor component, which we call FeLIX, was identified as an endogenously expressed protein that is similar to a portion of the FeLV envelope protein. This cellular protein can function either as a transmembrane protein or as a soluble component to facilitate infection.", "journal": "Science (New York, N.Y.)", "doi": "10.1126/science.287.5459.1828", "deposited_data": "Sim", "nuccore_ids": "7188715", "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10708051", "author": "Phipps AJ", "n_authors": 5, "title": "Neurophysiologic and immunologic abnormalities associated with feline immunodeficiency virus molecular clone FIV-PPR DNA inoculation.", "abstract": "Although direct feline immunodeficiency virus (FIV) proviral DNA inoculation has been shown to be infectious in cats, long-term studies to assess the pathogenic nature of DNA inoculation are lacking. We have recently reported that direct feline leukemia virus (FeLV) DNA inoculation resulted in infection and the development of FeLV-related disease end points with similar temporal expression and virulence to that of cats infected with whole virus. We show in this study that pFIV-PPR DNA inoculation resulted in infection of cats and the development of FIV-related immunologic and neurologic abnormalities. Infected cats demonstrated progressive loss of CD4+ lymphocytes resulting in decreased CD4:CD8 ratios. Neurologic dysfunction was demonstrated by increased bilateral frontal lobe slow-wave activity. Prolongation of the visual evoked potential peak latency onset response pattern also supported a similar progression of abnormal cortical response. Furthermore, histopathologic examination revealed lesions attributed to FIV infection in lymph node, thymus, brain, and lung. Finally, nested polymerase chain reaction detected FIV provirus in brain, bone marrow, mesenteric lymph node, thymus, spleen, tonsil, and liver. These results confirm that FIV DNA inoculation is an efficient model for study of the pathogenic nature of molecular clones in vivo and offers the opportunity to measure temporal genomic stability of a homogeneous challenge material.", "journal": "Journal of acquired immune deficiency syndromes (1999)", "doi": "10.1097/00126334-200001010-00002", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10707683", "author": "Hill SL", "n_authors": 6, "title": "Prevalence of enteric zoonotic organisms in cats.", "abstract": "To determine prevalence of enteric zoonotic organisms in cats in north-central Colorado. Prospective study. Serum and fecal samples from 87 cats with diarrhea, 106 cats without diarrhea, and 12 cats for which fecal consistency was unknown. Samples were obtained from client-owned cats and cats at a humane society shelter. Serum was assayed for feline leukemia virus antigen and antibodies against feline immunodeficiency virus, IgM antibodies against Toxoplasma gondii, and IgG antibodies against T gondii and Cryptosporidium parvum. Microscopic examination of unstained feces was performed after centrifugation in a zinc sulfate solution, thin fecal smears were stained with acid fast stain and examined for C parvum, and bacteriologic culture of feces was used to detect aerobic and anaerobic bacteria. Enteric zoonotic organisms were detected in feces from 27 of 206 (13.1%) cats and included C parvum (5.4%), Giardia spp (2.4%). Toxocara cati (3.9%), Salmonella enterica serotype Typhimurium (1.0%), and Campylobacter jejuni (1.0%); each organism was detected in samples from cats with and without diarrhea. Although differences between groups were not significant, a higher proportion of shelter cats (18.2%) had enteric zoonotic organisms than client-owned cats (10.1%). Enteric zoonotic organisms were detected in feces of 13.1% of cats, suggesting that cats, particularly those in homes of immunocompromised humans, should be evaluated for enteric zoonotic organisms.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.2000.216.687", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10685687", "author": "Sierra P", "n_authors": 5, "title": "Fungal flora on cutaneous and mucosal surfaces of cats infected with feline immunodeficiency virus or feline leukemia virus.", "abstract": "To compare cutaneous and mucosal mycoflora in cats infected with FIV or FeLV with that in noninfected cats. 85 client-owned cats; 24 seropositive for FIV, 10 seropositive for FeLV, 1 seropositive for both viruses, and 50 seronegative for both viruses. Cutaneous specimens were obtained from the coat and external acoustic meatus (ear canal) and mucosal specimens from the oropharynx and rectum. Fungi were isolated from specimens, using Sabouraud dextrose agar incubated at 27 or 37 C for cutaneous and mucosal specimens, respectively. Fungal colonies were cultured from at least 1 specimen from 83 of 85 (97.6%) cats. The most common fungal isolates were Aspergillus spp (cultured from 59.3% of all specimens), Penicillium spp (50.0%), Cladosporium spp (44.2%), Scopulariopsis spp (41.8%), and lipophilic yeasts of the genus Malassezia (31.4%). A greater diversity of fungal genera was isolated from retrovirus-infected cats, and Malassezia spp were more commonly recovered from these cats, compared with noninfected cats. Candida albicans, Cryptococcus neoformans, and dermatophytes (eg, Microsporum canis) were rarely isolated from any cat. Significant differences in frequency of isolation of C. neoformans and dermatophytes were not found between infected and noninfected cats. Cats infected with FIV or FeLV may have a greater diversity of cutaneous and mucosal mycoflora than noninfected cats. However, infected cats may be no more likely than noninfected cats to expose humans to zoonotic fungi such as C. albicans, C. neoformans, and M. canis.", "journal": "American journal of veterinary research", "doi": "10.2460/ajvr.2000.61.158", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10684313", "author": "Dreyer K", "n_authors": 3, "title": "A 13-amino-acid Pit1-specific loop 4 sequence confers feline leukemia virus subgroup B receptor function upon Pit2.", "abstract": "Feline leukemia virus subgroup B (FeLV-B) and gibbon ape leukemia virus (GALV) utilize the human protein Pit1 but not the related protein, Pit2, as receptor. A stretch of 9 amino acids, named region A, was identified in the putative fourth extracellular loop of Pit1 (residues 550 through 558) as critical for FeLV-B and GALV receptor function. However, the presence of Pit1 region A did not confer receptor function for FeLV-B upon Pit2, while it did so for GALV. We have here shown that the presence of two Pit1-specific loop 4 residues (tyrosine 546 and valine 548) in addition to Pit1 region A is sufficient to make Pit2 an efficient FeLV-B receptor; that is, a stretch of 13 amino acids encompassing all loop 4 amino acid differences between Pit1 and Pit2 comprises a C-terminal determinant for FeLV-B receptor function. Thus, the same limited receptor region is sufficient to confer receptor function for both viruses upon Pit2.", "journal": "Journal of virology", "doi": "10.1128/jvi.74.6.2926-2929.2000", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10676902", "author": "Shimoda T", "n_authors": 4, "title": "Bone marrow necrosis in a cat infected with feline leukemia virus.", "abstract": "A one-year old castrated male cat was admitted to the hospital with vomiting and diarrhea. Laboratory examination revealed pancytopenia and positive for FeLV antigen. A bone marrow examination indicated necrosis of the nucleated cells. Based on these findings, the cat was diagnosed as bone marrow necrosis. Pancytopenia was effectively treated with corticosteroids. Re-examination of the bone marrow confirmed a recovery of normal hematopoietic cells with a infiltration of many macrophages. It is strongly suspected that the bone marrow necrosis in this case could be associated with a bone marrow suppression due to FeLV infection.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.62.113", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10676891", "author": "Shimoda T", "n_authors": 4, "title": "A hematological study on thirteen cats with myelodysplastic syndrome.", "abstract": "Hematological abnormalities were investigated in 13 cats with myelodysplastic syndrome (MDS). Examination of the peripheral blood samples from the 13 cats revealed anemia in 11 cats, leukopenia in 9 cats, and thrombocytopenia in 9 cats. Four cats had pancytopenia (30.8%) and 9 cats had bicytopenia (69.2%). Dysplastic changes of erythrocytes, neutrophils, and platelets in the peripheral blood were found in 5, 10 and 8 cats, respectively. Bone marrow examination of the 13 cats revealed that ratios of blast cells to all nucleated cells (ANC) ranged from 0 to 20%. Ratios of erythroid progenitor cells to ANC were more than 50% in 3 cats and less than 50% in 10 cats. Eosinophils accounted for more than 5% of non-erythroid cells in 10 cats. Dysplastic changes in the granurocytic, erythrocytic, and megakaryocytic cells in the bone marrow were found in 11, 7 and 5 cats, respectively. Dysplastic changes in these cats included giant neutrophils, ring-nucleated neutrophils, binuclear myelocytes, hypersegmented and hyposegmented neutrophils, megaloblastoid erythroblasts, multinucleated erythroblasts, micromegakaryocytes, and segmented multinucleated megakaryocytes. Virological examination indicated the presence of feline leukemia virus antigen in the peripheral blood from all of the 13 cats with MDS. The peripheral blood cytopenias and dysplastic changes in each blood cell lineage in the bone marrow were shown to be important for the diagnosis of MDS in cats.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.62.59", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10648427", "author": "Quigley JG", "n_authors": 7, "title": "Cloning of the cellular receptor for feline leukemia virus subgroup C (FeLV-C), a retrovirus that induces red cell aplasia.", "abstract": "Feline leukemia virus-C (FeLV-C) causes red cell aplasia in cats, likely through its interaction with its cell surface receptor. We identified this receptor by the functional screening of a library of complementary DNAs (cDNA) from feline T cells. The library, which was cloned into a retroviral vector, was introduced into FeLV-C-resistant murine (NIH 3T3) cells. The gene conferring susceptibility to FeLV-C was isolated and reintroduced into the same cell type, as well as into FeLV-C-resistant rat (NRK 52E) cells, to verify its role in viral infection. The receptor cDNA is predicted to encode a protein of 560 amino acids with 12 membrane-spanning domains, termed FLVCR. FLVCR has significant amino acid sequence homology with members of the major facilitator superfamily and especially D-glucarate transporters described in bacteria and in C. elegans. As FeLV-C impairs the in vivo differentiation of burst-forming unit-erythroid to colony-forming unit-erythroid, we hypothesize that this transporter system could have an essential role in early erythropoiesis. In further studies, a 6-kb fragment of the human FLVCR gene was amplified by polymerase chain reaction from genomic DNA, using homologous cDNA sequences identified in the human Expressed Sequence Tags database. By radiation hybrid mapping, the human gene was localized to a 0.5-centiMorgan region on the long arm of chromosome 1 at q31.3.", "journal": "Blood", "doi": null, "deposited_data": "Sim", "nuccore_ids": "1519315556, 57163832, 7157951, 2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556, 57163832", "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "11128537", "author": "Butera ST", "n_authors": 8, "title": "Survey of veterinary conference attendees for evidence of zoonotic infection by feline retroviruses.", "abstract": "To examine exposure risks, possibility of zoonosis, and potential disease associations for feline retroviruses among a group of occupationally exposed individuals. Unlinked voluntary cross-sectional epidemiologic survey. 204 veterinarians, laboratory scientists, and other occupationally exposed individuals who attended a veterinary conference on feline geriatric medicine. Blood was collected from participants who also completed a 13-question survey requesting demographic, occupational, exposure, and health information. Blood specimens were fractionated into plasma and mononuclear cell components. Plasma was tested for antibodies against feline immunodeficiency virus (FIV) and feline foamy virus (FeFV), as well as p27 antigen of FeLV. Mononuclear cell lysates were tested for FeLV provirus. Subjects reported extensive duration of work with cats (mean, 17.3 years) and multiple high-risk exposures (eg, cat bites, scratches, and injuries with sharp instruments) per year. However, neither serologic nor molecular evidence of zoonosis with any of the 3 feline retroviruses was detected. Veterinarians encounter occupational exposures to animal material that place them at high risk for zoonoses. For feline retroviruses, the risk of zoonosis among healthy adult humans appears to be extremely small. However, potential for retroviral zoonosis, especially for viruses such as FeLV and FeFV that can replicate in human cells, cannot be eliminated, and universal precautions to reduce potential exposures should be used when handling sick cats.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.2000.217.1475", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10627556", "author": "Shi Y", "n_authors": 2, "title": "A novel truncated env gene isolated from a feline leukemia virus-induced thymic lymphosarcoma.", "abstract": "We PCR amplified the exogenous feline leukemia virus (FeLV)-related env gene species from lymphosarcomas induced by intradermally administered plasmid DNA of either the prototype FeLV, subgroup A molecular clone, F6A, or a new molecular clone, FeLV-A, Rickard strain (FRA). Of the nine tumors examined, six showed the presence of deleted env species of variable sizes in the tumor DNA. One env mutant, which was detected in a FRA-induced thymic lymphosarcoma, had a large internal deletion beginning from almost the N-terminal surface glycoprotein (SU) up to the middle region of the transmembrane (TM) protein of the env gene. The deduced polypeptide of this truncated env (tenv) retained the complete signal peptide and seven amino acids of the N-terminal mature SU of FRA env gene, followed by eight amino acids from the frameshift in the TM region. To study the biological function of tenv, we used a murine retrovirus vector to produce amphotropic virions. Infection of feline fibroblasts (H927), human fibrosarcoma cells (HT1080), or human B-lymphoma cells (Raji) led to pronounced cytotoxicity, while the tenv virus did not induce significant cytotoxicity to feline T-lymphoma cells (3201B) or human T-lymphoma cells (CEM). Together, these results convincingly demonstrated that the genetic events that led to truncation in the env gene occurred de novo in FeLV lymphomagenesis and that such a product, tenv could induce cytotoxicity to fibroblastic and B-lymphoid cells but not to T-lymphoid tumor cells. This type of selective toxicity might be potentially important in the development of the neoplastic disease.", "journal": "Journal of virology", "doi": "10.1128/jvi.74.3.1451-1456.2000", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10590111", "author": "Tailor CS", "n_authors": 3, "title": "A comprehensive approach to mapping the interacting surfaces of murine amphotropic and feline subgroup B leukemia viruses with their cell surface receptors.", "abstract": "Because mutations in envelope glycoproteins of retroviruses or in their cell surface receptors can eliminate function by multiple mechanisms, it has been difficult to unambiguously identify sites for their interactions by site-directed mutagenesis. Recently, we developed a gain-of-function approach to overcome this problem. Our strategy relies on the fact that feline leukemia virus subgroup B (FeLV-B) and amphotropic murine leukemia virus (A-MLV) have closely related gp70 surface envelope glycoproteins and use related Na(+)-dependent phosphate symporters, Pit1 and Pit2, respectively, as their receptors. We previously observed that FeLV-B/A-MLV envelope glycoprotein chimeras spliced between the variable regions VRA and VRB were unable to use Pit1 or Pit2 as a receptor but could efficiently use specific Pit1/Pit2 chimeras. The latter study suggested that the VRA of A-MLV and FeLV-B functionally interact with the presumptive extracellular loops 4 and 5 (ECL4 and -5) of their respective receptors, whereas VRB interacts with ECL2. We also found that FeLV-B gp70 residues F60 and P61 and A-MLV residues Y60 and V61 in the first disulfide-bonded loop of VRA were important for functional interaction with the receptor's ECL4 or -5. We have now extended this approach to identify additional VRA and VRB residues that are involved in receptor recognition. Our studies imply that FeLV-B VRA residues F60 and P61 interact with the Pit1 ECL5 region, whereas VRA residues 66 to 78 interact with Pit1 ECL4. Correspondingly, A-MLV VRA residues Y60 and V61 interact with the Pit2 ECL5 region, whereas residues 66 to 78 interact with Pit2 ECL4. Similar studies that focused on the gp70 VRB implicated residues 129 to 139 as contributing to specific interactions with the receptor ECL2. These results identify three regions of gp70 that interact in a specific manner with distinct portions of their receptors, thereby providing a map of the functionally interacting surfaces.", "journal": "Journal of virology", "doi": "10.1128/jvi.74.1.237-244.2000", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11876630", "author": "Herring ES", "n_authors": 6, "title": "Detection of feline leukaemia virus in blood and bone marrow of cats with varying suspicion of latent infection.", "abstract": "The purpose of this study was to determine if polymerase chain reaction (PCR) could be used to detect FeLV proviral DNA in bone marrow samples of cats with varying suspicion of latent infection. Blood and bone marrow samples from 50 cats and bone marrow from one fetus were collected, including 16 cats with diseases suspected to be FeLV-associated. Serum enzyme-linked immunosorbent assay (ELISA), blood and bone marrow immunofluorescent antibody test (IFA), and blood and bone marrow PCR were performed on each cat, and IFA and PCR on bone marrow of the fetus. Forty-one cats were FeLV negative. Five cats and one fetus were persistently infected with FeLV. Four cats had discordant test results. No cats were positive on bone marrow PCR only. It appears persistent or latent FeLV infection is not always present in conditions classically associated with FeLV.", "journal": "Journal of feline medicine and surgery", "doi": "10.1053/jfms.2001.0132", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11837901", "author": "Malik R", "n_authors": 5, "title": "Therapy for Australian cats with lymphosarcoma.", "abstract": "To determine the response of Australian cats with lymphosarcoma to chemotherapy and/or surgery in relation to patient and tumour characteristics, haematological and serum biochemical values and retroviral status. Prospective study of 61 client-owned cats with naturally-occurring lymphosarcoma subjected to multi-agent chemotherapy and/or surgery. An accepted chemotherapy protocol utilising l-asparaginase, vincristine, cyclophosphamide, doxorubicin, methotrexate and prednisolone was modified and used to treat 60 cats with lymphosarcoma. Clinical findings were recorded before and during therapy. As far as practical, cases were followed to death, euthanasia or apparent cure. Owner satisfaction with the results of chemotherapy was determined using a questionnaire sent after the completion of chemotherapy. One cat, with lymphosarcoma limited to a single mandibular lymph node, was treated using surgery alone and was cured. The other 60 cats were treated using multi-agent chemotherapy, although seven cats with localised intestinal, ocular and subcutaneous lesions had these lesions partially (2 intestinal lesions) or completely (2 eyes, 2 intestinal lesions and a cluster of regional lymph nodes) resected prior to starting chemotherapy. The median survival time for these 60 cats was 116 days. Of the 60 cats, 48 rapidly went into complete remission following the administration of 1-asparaginase, vincristine and prednisolone (complete remission rate 80%) and these cats had a median survival of 187 days. Three cats were censored from further analysis as their long-term survival data were uninterpretable because they died of causes unrelated to lymphosarcoma or were prematurely lost to follow-up. Twenty cats were classed as 'long-term survivors' based on survival time in excess of one year and at least 14 were 'cured' based on the absence of physical evidence of lymphosarcoma 2-years after initiating treatment. In other words, of the 48 cats that reached complete remission, in excess of 29% were 'cured'. Despite detailed analysis, few meaningful prognostic indicators based on patient or tumour characteristics were identified, although long-term survivors were more likely to be less than 4-years (P= 0.04) and to have tumours of the T-cell phenotype (P= 0.06). Excluding the one FeLV ELISA-positive cat with mediastinal LSA, 7 of 9 cats less than 4 years-of-age were long-term survivors (median survival time >1271 days). There was a strong association between achieving complete remission and long-term survival (P = 0.003). On the basis of 27 replies to a questionnaire, owners were generally very satisfied with the response to chemotherapy, irrespective of the survival time of the individual patient. Eighty five percent of owners expressed complete satisfaction with their decision to pursue chemotherapy and 70% believed their cat's health status improved during the first 2-weeks of treatment. Importantly, 78% of owners considered that chemotherapy required a very substantial time commitment on their part. It was possible to cure approximately one quarter of cats with lymphosarcoma using sequential multi-agent chemotherapy and/or surgery. FeLV-negative cats younger than 4 years (typically with mediastinal lymphosarcoma) had a particularly favourable prognosis. The decision to embark on chemotherapy should be based on the results of induction chemotherapy with l-asparaginase, vincristine and prednisolone, as the response to this was a good predictor of long-term survival. Cats surviving the first 16 weeks of chemotherapy generally enjoyed robust remissions (in excess of 1 year) or were cured of their malignancy.", "journal": "Australian veterinary journal", "doi": "10.1111/j.1751-0813.2001.tb10923.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11764326", "author": "Helps CR", "n_authors": 5, "title": "Detection of antibodies to Borna disease virus in Turkish cats by using recombinant p40.", "abstract": "Recombinant p40 produced by baculovirus was used in an ELISA to screen samples of serum taken from 80 cats in Istanbul. The sera were also analysed for feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV). Antibodies to Borna disease virus- (BDV) p40 were detected in 34 (42-5 per cent) of the 80 cats. Seventy-three per cent of the sera which were positive for FIV and 26 per cent of the sera which were negative for FIV had antibodies to BDV. There was no difference in the percentage of sera which were positive for BDV between the cats that were positive or negative for FeLV. Three of the cats had neurological disease and two of these had antibodies to BDV. Six sera with low, medium or high optical densities (ODS) by ELISA were analysed by Western blotting. Only the sera with medium and high ODS reacted specifically with p40 at a dilution of 1 in 1,000.", "journal": "The Veterinary record", "doi": "10.1136/vr.149.21.647", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11763193", "author": "Kidney BA", "n_authors": 4, "title": "Comparison of endogenous feline leukemia virus RNA content in feline vaccine and nonvaccine site-associated sarcomas.", "abstract": "To determine whether feline vaccine site-associated sarcomas (VSS) contain a higher amount of endogenous FeLV (enFeLV) RNA, compared with feline nonvaccine site-associated sarcomas (non-VSS). Formalin-fixed paraffin-embedded (FFPE) tissues from 50 VSS and 50 cutaneous non-VSS. RNA was extracted from FFPE sections of each tumor, and regions of the long terminal repeat (LTR) and envelope (env) gene of enFeLV were amplified by use of reverse transcriptase-polymerase chain reaction (RT-PCR). The density of each RT-PCR product band for enFeLV was compared with that of a constitutively expressed gene, glyceraldehyde-3-phosphate dehydrogenase (GAPDH). An integrated density value (IDV) was determined by use of densitometry, and the IDV ratio for enFeLV to GAPDH was calculated for each enFeLV primer set. The median (interquartile range) of the IDV ratio for the enFeLV LTR primer set was 0.52 (0.26 to 1.17) for the VSS group and 0.84 (0.21 to 1.53) for the non-VSS group. The median (interquartile range) of the IDV ratio for the enFeLV env primer set was 0.60 (0.37 to 0.91) for the VSS group and 0.59 (0.36 to 1.09) for the non-VSS group. Because the amount of enFeLV RNA within the LTR and env gene was not significantly different between the VSS and non-VSS groups, enFeLV replication or expression is unlikely to be involved in VSS development.", "journal": "American journal of veterinary research", "doi": "10.2460/ajvr.2001.62.1990", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11761301", "author": "Jarrett O", "n_authors": 1, "title": "Feline leukaemia virus neutralising antibodies.", "abstract": null, "journal": "The Veterinary record", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11688526", "author": "Delmage DA", "n_authors": 2, "title": "Auricular chondritis in a cat.", "abstract": "A four-year-old male neutered domestic shorthaired cat developed bilateral thickening of the pinnae, with slight curling, intense erythema and pain. No ear canal disease was present. The cat was negative for feline immunodeficiency virus, feline leukaemia virus and feline coronavirus. Biopsy of the ear lesion revealed auricular chondritis. In humans, histologically similar lesions may involve the pinnae, nose, trachea, joints, eyes and heart, and the disease is termed relapsing polychondritis. The cat reported had a history of corneal damage, resulting in corneal vascularisation and opacity, eyelid distortion, necessitating an entropion operation, and radiological evidence of mild cardiac enlargement. The ear disease responded rapidly to treatment with prednisolone and, apart from slight thickening and curling of the pinnae, the cat remained normal and pain-free. After two years, the prednisolone was withdrawn, and there was no recurrence of the condition in a follow-up period of 14 months.", "journal": "The Journal of small animal practice", "doi": "10.1111/j.1748-5827.2001.tb02457.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11602698", "author": "Anderson MM", "n_authors": 5, "title": "Feline Pit2 functions as a receptor for subgroup B feline leukemia viruses.", "abstract": "Different subgroups of feline leukemia virus (FeLV) use different host cell receptors for entry. Subgroup A FeLV (FeLV-A) is the virus that is transmitted from cat to cat, suggesting that cells expressing the FeLV-A receptor are important targets at the earliest stages of infection. FeLV-B evolves from FeLV-A in the infected cat through acquisition of cellular sequences that are related to the FeLV envelope gene. FeLV-Bs have been shown to infect cells using the Pit1 receptor, and some variants can infect cells at a lower efficiency using Pit2. Because these observations were made using receptor proteins of human or rodent origin, the role that Pit1 and Pit2 may play in FeLV-B replication in the cat is unclear. In this study, the feline Pit receptors were cloned and tested for their ability to act as receptors for different FeLV-Bs. Some FeLV-Bs infected cells expressing feline Pit2 and feline Pit1 with equal high efficiency. Variable region A (VRA) in the putative receptor-binding domain (RBD) was a critical determinant for both feline Pit1 and feline Pit2 binding, although other domains in the RBD appear to influence how efficiently the FeLV-B surface unit can bind to feline Pit2 and promote entry via this receptor. An arginine residue at position 73 in VRA was found to be important for envelope binding to feline Pit2 but not feline Pit1. Interestingly, this arginine is not found in endogenous FeLV sequences or in recombinant viruses recovered from feline cells infected with FeLV-A. Thus, while FeLV-Bs that are able to use feline Pit2 can evolve by recombination with endogenous sequences, a subsequent point mutation during reverse transcription may be needed to generate a virus that can efficiently enter the cells using the feline Pit2 as its receptor. These studies suggest that cells expressing the feline Pit2 protein are likely to be targets for FeLV-B infection in the cat.", "journal": "Journal of virology", "doi": "10.1128/JVI.75.22.10563-10572.2001", "deposited_data": "Sim", "nuccore_ids": "57618972, 15559051, 14916034, 2130946720, 2130946717, 2130946715, 2130946709, 2130946706, 2130946701, 2130946697, 2130946695, 2130946693, 2130946690, 57618972", "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11599813", "author": "Gabor LJ", "n_authors": 4, "title": "Feline immunodeficiency virus status of Australian cats with lymphosarcoma.", "abstract": "To determine the FIV status of Australian cats with lymphosarcoma and relate this to patient characteristics, tumour characteristics (tissue involvement, histological grade and immunophenotype), haematological and serum biochemical values and FeLV status of affected cats. Prospective study of 101 client-owned cats with naturally-occurring lymphosarcoma. Western blot analysis, ELISA and immunochromatography were used to detect FIV antibodies in serum from cats with lymphosarcoma. On the basis of Western blot analysis (which was considered the most accurate method for determining FIV status), 50/101 (50%) of cats with naturally-occurring lymphosarcoma were positive for FIV antibodies. Of these 50 cats, 35 had tumours of B-cell phenotype, 13 had T-cell tumours and 2 had tumours classified as non-B/non-T. Tumours from eight of these FIV-positive cats contained FeLV gene sequences, including a 9-month-old cat with FeLV antigenaemia. Compared with FlV-negative cats with lymphosarcoma, FIV-positive cats were more likely to be domestic crossbreds (P = 0.004), male (P = 0.048) and have atypical (especially nasal) forms of lymphosarcoma (P = 0.09). Only 39 of 107 (36%) blood or sera tested using ELISA were positive for FIV antibodies (including 5 false-positives). The prevalence of FIV infection was considerably higher in our cohort of cats compared with series of lymphosarcoma cases from the Northern hemisphere. A positive FIV status was strongly associated with lymphosarcoma in Australian cats and it is possible that this infection may predispose to the development of lymphoid neoplasia. The presence of FIV infection would have been underestimated if commercial kits alone had been used for serology.", "journal": "Australian veterinary journal", "doi": "10.1111/j.1751-0813.2001.tb10742.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11596735", "author": "Hisasue M", "n_authors": 13, "title": "Hematologic abnormalities and outcome of 16 cats with myelodysplastic syndromes.", "abstract": "We investigated the hematologic abnormalities and prognoses in 16 cats with myelodysplastic syndromes (MDS). Nonregenerative anemia, thrombocytopenia, and neutropenia were observed in 15, 13, and 4, respectively, of the 16 cats with MDS. Morphologic abnormalities characteristic of MDS included megaloblastoid rubricytes (9 cats), hyposegmentation of neutrophils (7 cats), nuclear abnormality of rubricytes (10 cats) and neutrophils (13 cats), and micromegakaryocytes (10 cats). Disease in these 16 cats was subclassified into refractory anemia (RA; 8 cats), RA with excess of blasts (RAEB; 5 cats), RAEB in transformation (RAEB in T; 1 cat), and chronic myelomonocytic leukemia (CMMoL; 2 cats), according to the human French-American-British (FAB) classification. In the cats in which the clinical outcome was known, 3 of 6 cats with high blast cell count MDS, including RAEB, RAEB in T, and CMMoL, developed acute myeloid leukemia, but only 1 of 8 cats with low blast cell count MDS (RA) developed acute myeloid leukemia. Based on the Dusseldorf scoring system for the prognosis of human MDS, the survival times of the cats showing high scores (> or =3 points) were significantly shorter than those of the cats with low scores (<3 points). The FAB classification and Dusseldorf scoring system were considered to be useful for predicting the prognosis of feline MDS. Furthermore, 15 of the 16 cats with MDS in this study were infected with feline leukemia virus, indicating its possible etiologic role in the pathogenesis of feline MDS.", "journal": "Journal of veterinary internal medicine", "doi": "10.1892/0891-6640(2001)015<0471:haaooc>2.3.co;2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11583125", "author": "Hartmann K", "n_authors": 4, "title": "Comparison of six in-house tests for the rapid diagnosis of feline immunodeficiency and feline leukaemia virus infections.", "abstract": "Six rapid tests for the diagnosis of feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV) infections which have recently been introduced in Europe for use in small animal practice were compared. Eight hundred serum samples were tested and those reacting FIV-positive in at least one of the tests were confirmed by Western blot, and those reacting FeLV-positive were confirmed by virus isolation. The specificity and sensitivity of each test and the quality of the results produced were compared.", "journal": "The Veterinary record", "doi": "10.1136/vr.149.11.317", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11563718", "author": "Schoeman T", "n_authors": 4, "title": "Feline babesiosis: signalment, clinical pathology and concurrent infections.", "abstract": "Fifty-six cats with naturally occurring Babesia felis infection were studied. No breed or sex predilection could be identified, but there was an apparent predilection for young adult cats less than 3 years of age. Macrocytic, hypochromic, regenerative anaemia was present in 57% of the cats and in-saline agglutination tests were positive in 16%. No characteristic changes were observed in total or differential leukocyte counts. Thrombocyte counts were variable and thrombocytopaenia was an inconsistent finding. Hepatic cytosol enzyme activity and total bilirubin concentrations were elevated in the majority of cats. Serum protein values were mostly normal, but increased values were occasionally observed and polyclonal gammopathies were observed in all cats with increased total globulin concentrations. No remarkable changes in renal parameters were observed. A variety of electrolyte abnormalities occurred in a number of cats, but no consistent pattern of change could be identified. A close correlation was evident between peripheral and central parasite counts. Concurrent infections with Haemobartonella felis, feline immunodeficiency virus and/or feline leukemia virus were identified in a number of cats.", "journal": "Journal of the South African Veterinary Association", "doi": "10.4102/jsava.v72i1.601", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11549046", "author": "Gabor LJ", "n_authors": 5, "title": "Feline leukaemia virus status of Australian cats with lymphosarcoma.", "abstract": "To determine the FeLV status of sera and tumours from Australian cats with lymphosarcoma in relation to patient characteristics, tumour characteristics (tissue involvement, histological grade and immunophenotype), haematological and biochemical values. Prospective study of 107 client-owned cats with naturally-occurring lymphosarcoma. An ELISA was used to detect FeLV p27 antigen in serum specimens collected from cats with lymphosarcoma. A PCR was used to detect FeLV DNA in formalin-fixed, paraffin-embedded tissue sections containing neoplastic lymphoid cells. The PCR was designed to amplify a highly conserved region of the untranslated long terminal repeat of FeLV provirus. Only 2 of 107 cats (2%), for which serum samples were available, were FeLV-positive on the basis of detectable p27 antigen in serum. In contrast, 25 of 97 tumours (26%) contained FeLV DNA. Of the 86 cats for which both PCR and ELISA data were available, 19(22%) had FeLV provirus in their tumours but no detectable circulating FeLV antigen in serum, while 2 (2%) had FeLV provirus and circulating FeLV antigen. FeLV PCR-positive/ELISA-negative cats (19) differed from PCR-negative/ELISA-negative cats (65) in having fewer B-cell tumours (P = 0.06), more non B-/non T-cell tumours (P = 0.02) and comprising fewer non-Siamese/Oriental pure-bred cats (P = 0.03). The prevalence of FeLV antigen or provirus was considerably lower in our cohort of cats compared with studies of lymphosarcoma conducted in the Northern hemisphere. This suggests that factors other than FeLV are important in the development of lymphosarcoma in many Australian cats. No firm conclusions could be drawn concerning whether FeLV provirus contributed to the development of lymphosarcoma in PCR-positive/ELISA-negative cats.", "journal": "Australian veterinary journal", "doi": "10.1111/j.1751-0813.2001.tb13017.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11533152", "author": "Lauring AS", "n_authors": 3, "title": "Specificity in receptor usage by T-cell-tropic feline leukemia viruses: implications for the in vivo tropism of immunodeficiency-inducing variants.", "abstract": "Cytopathic, T-cell-tropic feline leukemia viruses (FeLV-T) evolve from FeLV-A in infected animals and demonstrate host cell specificities that are distinct from those of their parent viruses. We recently identified two cellular proteins, FeLIX and Pit1, required for productive infection by these immunodeficiency-inducing FeLV-T variants (M. M. Anderson, A. S. Lauring, C. C. Burns, and J. Overbaugh, Science 287:1828-1830, 2000). FeLV-T is the first example of a naturally occurring type C retrovirus that requires two proteins to gain entry into target cells. FeLIX is an endogenous protein that is highly related to the N-terminal portion of the FeLV envelope protein, which includes the receptor-binding domain. Pit1 is a multiple-transmembrane phosphate transport protein that also functions as a receptor for FeLV-B. The FeLV-B envelope gene is derived by recombination with endogenous FeLV-like sequences, and its product can functionally substitute for FeLIX in facilitating entry through the Pit1 receptor. In the present study, we tested other retrovirus envelope surface units (SUs) with their cognate receptors to determine whether they also could mediate infection by FeLV-T. Cells were engineered to coexpress the transmembrane form of the envelope proteins and their cognate receptors, or SU protein was added as a soluble protein to cells expressing the receptor. Of the FeLV, murine leukemia virus, and gibbon ape leukemia virus envelopes tested, we found that only those with receptor-binding domains derived from endogenous FeLV could render cells permissive for FeLV-T. We also found that there is a strong preference for Pit1 as the transmembrane receptor. Specifically, FeLV-B SUs could efficiently mediate infection of cells expressing the Pit1 receptor but could only inefficiently mediate infection of cells expressing the Pit2 receptor, even though these SUs are able to bind to Pit2. Expression analysis of feline Pit1 and FeLIX suggests that FeLIX is likely the primary determinant of FeLV-T tropism. These results are discussed in terms of current models for retrovirus entry and the interrelationship among FeLV variants that evolve in vivo.", "journal": "Journal of virology", "doi": "10.1128/JVI.75.19.8888-8898.2001", "deposited_data": "Sim", "nuccore_ids": "1676319575, 1653961537", "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11509871", "author": "Pumpens P", "n_authors": 2, "title": "HBV core particles as a carrier for B cell/T cell epitopes.", "abstract": "In the middle 80s, recombinant hepatitis B virus cores (HBc) gave onset to icosahedral virus-like particles (VLPs) as a basic class of non-infectious carriers of foreign immunological epitopes. The recombinant HBc particles were used to display immunodominant epitopes of hepatitis B, C, and E virus, human rhinovirus, papillomavirus, hantavirus, and influenza virus, human and simian immunodeficiency virus, bovine and feline leukemia virus, foot-and-mouth disease virus, murine cytomegalovirus and poliovirus, and other virus proteins, as well as of some bacterial and protozoan protein epitopes. Practical applicability of the HBc particles as carriers was enabled by their ability to high level synthesis and correct self-assembly in heterologous expression systems. The interest in the HBc VLPs was reinforced by the resolution of their fine structure by electron cryomicroscopy and X-ray crystallography, which revealed an unusual alpha-helical organization of dimeric units of HBc shells, alternative packing into icosahedrons with T = 3 and T = 4 symmetry, and the existence of long protruding spikes. The tips of the latter seem to be the optimal targets for the display of foreign sequences up to 238 amino acid residues in length. Combination of numerous experimental data on epitope display with the precise structural information enables a knowledge-based design of diagnostic, and vaccine and gene therapy tools on the basis of the HBc particles.", "journal": "Intervirology", "doi": "10.1159/000050037", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11507228", "author": "Chang Z", "n_authors": 5, "title": "A replication-competent feline leukemia virus, subgroup A (FeLV-A), tagged with green fluorescent protein reporter exhibits in vitro biological properties similar to those of the parental FeLV-A.", "abstract": "We previously established that lymphoid tumors could be induced in cats by intradermal injection of ecotropic feline leukemia virus (FeLV), subgroup A, plasmid DNA. In preparation for in vivo experiments to study the cell-to-cell pathway for the spread of the virus from the site of inoculation, the green fluorescent protein (GFP) transgene fused to an internal ribosome entry site (IRES) was inserted after the last nucleotide of the env gene in the ecotropic FeLV-A Rickard (FRA) provirus. The engineered plasmid was transfected into feline fibroblast cells for production of viruses and determination of GFP expression. The virions produced were highly infectious, and the infected cells could continue to mediate strong expression of GFP after long-term propagation in culture. Similar to parental virus, the transgene-containing ecotropic virus demonstrated recombinogenic activity with endogenous FeLV sequences in feline cells to produce polytropic recombinant FeLV subgroup B-like viruses which also contained the IRES-GFP transgene in the majority of recombinants. To date, the engineered virus has been propagated in cell culture for up to 8 months without diminished GFP expression. This is the first report of a replication-competent FeLV vector with high-level and stable expression of a transgene.", "journal": "Journal of virology", "doi": "10.1128/jvi.75.18.8837-8841.2001", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11507187", "author": "Hanlon L", "n_authors": 11, "title": "Feline leukemia virus DNA vaccine efficacy is enhanced by coadministration with interleukin-12 (IL-12) and IL-18 expression vectors.", "abstract": "The expectation that cell-mediated immunity is important in the control of feline leukemia virus (FeLV) infection led us to test a DNA vaccine administered alone or with cytokines that favored the development of a Th1 immune response. The vaccine consisted of two plasmids, one expressing the gag/pol genes and the other expressing the env gene of FeLV-A/Glasgow-1. The genetic adjuvants were plasmids encoding the feline cytokines interleukin-12 (IL-12), IL-18, or gamma interferon (IFN-gamma). Kittens were immunized by three intramuscular inoculations of the FeLV DNA vaccine alone or in combination with plasmids expressing IFN-gamma, IL-12, or both IL-12 and IL-18. Control kittens were inoculated with empty plasmid. Following immunization, anti-FeLV antibodies were not detected in any kitten. Three weeks after the final immunization, the kittens were challenged by the intraperitoneal inoculation of FeLV-A/Glasgow-1 and were then monitored for a further 15 weeks for the presence of virus in plasma and, at the end of the trial, for latent virus in bone marrow. The vaccine consisting of FeLV DNA with the IL-12 and IL-18 genes conferred significant immunity, protecting completely against transient and persistent viremia, and in five of six kittens protecting against latent infection. None of the other vaccines provided significant protection.", "journal": "Journal of virology", "doi": "10.1128/jvi.75.18.8424-8433.2001", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11503958", "author": "Nagashima N", "n_authors": 6, "title": "Bone marrow colony-forming unit assay in cats with naturally occurring myelodysplastic syndromes.", "abstract": "Feline myelodysplastic syndromes (MDS) has been diagnosed in many cats infected with feline leukemia virus, although the pathogenesis of this hematopoietic deficiency has been unclear. In this study, we assayed the bone marrow erythroid colony-forming units (CFU-E) and granulocyte-machrophage CFUs (CFU-GM) to investigate the pathogenesis of feline MDS. The number of CFU-E colonies was decreased in 4 of 7 cats with MDS, and the number of CFU-GM colonies was also decreased in 4 cats. Furthermore, small colonies of CFU-GM were found in all 7 cases. These findings indicated that refractory cytopenia of feline MDS could be caused by abnormal maturation and differentiation of hematopoietic stem cells in bone marrow, as it is in human MDS. The pathogenesis of feline MDS might be similar to that of human MDS.", "journal": "International journal of hematology", "doi": "10.1007/BF02994006", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11467470", "author": "Kipar A", "n_authors": 4, "title": "Comparative examination of cats with feline leukemia virus-associated enteritis and other relevant forms of feline enteritis.", "abstract": "Cats with feline leukemia virus (FeLV)-associated enteritis (FAE), enteritis of other known viral etiology (parvovirus [PV], enteric coronavirus [CoV]), and enteritis of unknown etiology with histologic features similar to those of FAE and PV enteritis (EUE) and FeLV-negative and FeLV-positive cats without enterocyte alterations were examined. Amount and types of infiltrating leukocytes in the jejunum and activity and cellular constituents of mesenteric lymph nodes, spleen, and bone marrow were determined. PV and CoV infections were confirmed by immunohistologic demonstration of PV and CoV antigen, ultrastructural demonstration of viral particles in the intestinal content, and in situ hybridization for PV genome. FeLV infection was detected by immunohistology for gp70, p27, and p15E. Latent FeLV infection was excluded by polymerase chain reaction methods for exogenous FeLV DNA. Enterocyte lesions involved the crypts in cats with PV enteritis, FAE, and EUE and the villous tips in cats with CoV enteritis. Inflammatory infiltration was generally dominated by mononuclear cells and was moderate in the unaltered intestine and in cats with PV enteritis and marked in cats with FAE, CoV enteritis, and EUE. In cats with EUE, myeloid/histiocyte antigen-positive macrophages were relatively numerous, suggesting recruitment of peripheral blood monocytes. Lymphoid tissues were depleted in cats with PV enteritis and with EUE but were normal or hyperplastic in cats with FAE. Bone marrow activity was decreased in cats with PV enteritis; in cats with FAE or EUE and in FeLV-positive cats without enterocyte alterations, activity was slightly increased. In cats with FAE and PV enteritis, a T-cell-dominated response prevailed. EUE showed some parallels to human inflammatory bowel disease, indicating a potential harmful effect of infiltrating macrophages on the intestinal epithelium.", "journal": "Veterinary pathology", "doi": "10.1354/vp.38-4-359", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11450836", "author": "McCaw DL", "n_authors": 6, "title": "Immunomodulation therapy for feline leukemia virus infection.", "abstract": "Clinically ill feline leukemia virus (FeLV)-infected cats, treated with Staphylococcus protein A (SPA) or oral interferon alpha (IFN), or both, were compared with cats treated with saline (SAL). Nine cats received SPA/SAL, nine received SPA/IFN, 10 received SAL/IFN, and eight received SAL/SAL. Twelve cats survived and completed the 100-week therapy. Significantly more owners of cats treated with SPA/SAL thought their cat's health improved during treatment compared to owners of cats treated with SAL/SAL (P=0.05, pair-wise comparison) or SPA/IFN (P=0.05, pair-wise comparison). No significant differences in body weight, temperature, hematocrit, red blood cell counts, mean corpuscular hemoglobin concentration, reticulocyte counts, white blood cell or neutrophil numbers, lymphocyte concentrations, bone-marrow cytopathology, FeLV status, survival time, activity, or appetite scores were observed. No significant differences in the owners' subjective assessment of their cat's health following treatment with SAL/IFN, SPA/IFN, or SAL/SAL were seen. Therapy with SPA as a single agent results in the owners' subjective impression of improved health of their FeLV-infected cats.", "journal": "Journal of the American Animal Hospital Association", "doi": "10.5326/15473317-37-4-356", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11443600", "author": "Lascelles BD", "n_authors": 2, "title": "Combined omental pedicle grafts and thoracodorsal axial pattern flaps for the reconstruction of chronic, nonhealing axillary wounds in cats.", "abstract": "To assess the results of an omental pedicle graft in combination with a thoracodorsal axial pattern flap for the reconstruction of chronic nonhealing axillary wounds in 10 cats caused by forelimb entrapment within a collar. A prospective, clinical trial. ANIMALS USED: Ten client-owned domestic shorthair cats. Routine biochemical and hematologic evaluation was performed on each cat, and all were tested for feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV). Microbial culture was performed on samples from the wounds. After surgical debridement, omentalization using a vascular pedicle of greater omentum, and closure of the chronic axillary wounds, using a thoracodorsal axial pattern flap, was performed. All excised tissue was examined histologically. The sex distribution was 7 males and 3 females, with a mean age of 3.5 years. The cats had undergone a median number of 3 previous repair attempts over a 1.5- to 25-month period before referral (mean, 10.2 months). No hematologic or biochemical abnormalities were noted apart from moderately elevated creatine kinase and aspartate transaminase concentrations in some cats. All cats were negative for FIV and FeLV. Histologic examination of resected tissue revealed hair (foreign body) in 2 cats and an unidentified foreign-body reaction in 3 other cats. Complete healing occurred in all cats (mean follow-up period of 21.7 months), with 2 cats requiring further surgery: 1 for flap dehiscence at 4 days after surgery, and 1 for donor-site dehiscence at 4 days after surgery. One other cat developed a large seroma in the axilla that resolved by 10 days following surgery. The use of an omental pedicle graft in combination with a thoracodorsal axial pattern flap is the first consistently successful 1-step technique for the management of chronic nonhealing axillary wounds in cats.", "journal": "Veterinary surgery : VS", "doi": "10.1053/jvet.2001.24396", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11435563", "author": "Sugai J", "n_authors": 6, "title": "Identification of envelope determinants of feline leukemia virus subgroup B that permit infection and gene transfer to cells expressing human Pit1 or Pit2.", "abstract": "The retroviral vector systems that are in common use for gene therapy are designed to infect cells expressing either of two widely expressed phosphate transporter proteins, Pit1 or Pit2. Subgroup B feline leukemia viruses (FeLV-Bs) use the gibbon ape leukemia virus receptor, Pit1, as a receptor for entry. Our previous studies showed that some chimeric envelope proteins encoding portions of FeLV-B could also enter cells by using a related receptor protein, Pit2, which serves as the amphotropic murine leukemia virus receptor (S. Boomer, M. Eiden, C. C. Burns, and J. Overbaugh, J. Virol. 71:8116--8123, 1997). Here we show that an arginine at position 73 within variable region A (VRA) of the FeLV-B envelope surface unit (SU) is necessary for viral entry into cells via the human Pit2 receptor. However, C-terminal SU sequences have a dominant effect in determining human Pit2 entry, even though this portion of the protein is outside known receptor binding domains. This suggests that a combination of specific VRA sequences and C-terminal sequences may influence interactions between FeLV-B SU and the human Pit2 receptor. Binding studies suggest that the C-terminal sequences may affect a postbinding step in viral entry via the Pit2 receptor, although in all cases, binding of FeLV-B SU to human Pit2 was weak. In contrast, neither the arginine 73 nor specific C-terminal sequences are required for efficient binding or infection with Pit1. Taken together, these data suggest that different residues in SU may interact with these two receptors. The specific FeLV-Bs described here, which can enter cells using either human Pit receptor, may be useful as envelope pseudotypes for viruses used in gene therapy.", "journal": "Journal of virology", "doi": "10.1128/JVI.75.15.6841-6849.2001", "deposited_data": "Sim", "nuccore_ids": "2592805098, 2592805080, 2592805001, 2592799544, 2501363558, 2501363550, 2501356983, 2501356593, 2462620702, 2462620700, 2462620698, 2462620696, 2462620694, 2462620692, 2462620690, 2462620688, 2462620686, 2462620684, 2462620681, 2462620679, 2462620677, 2217372913, 2217372912, 2217372910, 2217372908, 2217372907, 2217372906, 2217372904, 2217372902, 2217372900, 2217372899, 2217372898, 2217372897, 1907187920, 1907137055, 1907137051, 1890327961, 1676317635, 1519315341, 1519311779, 1370512758, 1243938578", "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11422993", "author": "Herring IP", "n_authors": 6, "title": "Feline leukemia virus detection in corneal tissues of cats by polymerase chain reaction and immunohistochemistry.", "abstract": "To determine the presence of feline leukemia virus (FeLV) in the corneas of FeLV-infected cats. Thirty-four random source cats. Seventeen cats were found positive for FeLV serum p27 antigen by enzyme-linked immunosorbent assay (ELISA). Twelve ELISA positive cats were also positive on peripheral blood samples by immunofluorescent antibody (IFA) testing. Seventeen ELISA negative cats served as negative controls. Full thickness corneal specimens were collected from the left cornea of all cats and analyzed for FeLV proviral DNA and gp70 antigen by polymerase chain reaction (PCR) and immunohistochemical (IHC) testing, respectively. Eleven (64.7%) positive corneal PCR results were obtained from 17 ELISA positive cats. Of 12 cats that were both ELISA and IFA positive on peripheral blood, 10 (83.3%) had positive corneal PCR results. All corneal tissues from ELISA negative cats were PCR negative. IHC staining of corneal sections revealed the presence of FeLV gp70 in corneal tissues of nine (52.9%) ELISA positive cats. Of the 12 cats that were both ELISA and IFA positive on peripheral blood, eight (66.7%) had positive corneal IHC results. Positive IHC staining was localized to the corneal epithelium. Corneal tissues of all ELISA negative cats and all IFA negative cats were negative on IHC testing. FeLV antigens and proviral DNA are present in corneal tissues of some FeLV-infected cats. Screening corneal donors for FeLV infection is warranted.", "journal": "Veterinary ophthalmology", "doi": "10.1046/j.1463-5224.2001.00187.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11413369", "author": "Hofmann-Lehmann R", "n_authors": 6, "title": "Feline leukaemia provirus load during the course of experimental infection and in naturally infected cats.", "abstract": "Feline leukaemia virus (FeLV) infection in domestic cats can vary in its outcome (persistent, transient, no infection) for reasons that are not entirely known. It was hypothesized that the initial virus and provirus load could significantly influence the course of retrovirus infection. To determine the role of provirus loads, two methods of PCR, a nested PCR and a fluorogenic probe-based (TaqMan) real-time quantitative PCR, which were specific to the U3 region of FeLV-A were established. FeLV provirus in naturally and experimentally infected cats was then measured. Only 3 weeks after experimental FeLV-A infection, persistently infected cats demonstrated higher provirus loads and lower humoral immune responses than cats that had overcome antigenaemia. Lower initial provirus loads were associated with successful humoral immune responses. Unexpectedly, provirus in the buffy-coat cells of two cats that tested negative for the p27 antigen (a marker for viraemia) was also detected. In 597 Swiss cats, comparison of p27 antigen levels with PCR results revealed broad agreement. However, similar to the experimental situation, a significant number of animals (10%) was negative for the p27 antigen and FeLV-positive by PCR. These cats had a mean provirus load 300-fold lower than that of animals testing positive for the p27 antigen. In conclusion, an association between the provirus load and the outcome of FeLV infection was found. Detection of provirus carriers should contribute to further the control of FeLV. In addition, quantification of provirus loads will lead to a better understanding of FeLV pathogenesis and anti-retrovirus protective mechanisms.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-82-7-1589", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11352065", "author": "Overbaugh J", "n_authors": 2, "title": "Selection forces and constraints on retroviral sequence variation.", "abstract": "All retroviruses possess a highly error-prone reverse transcriptase, but the extent of the consequent sequence diversity and the rate of evolution differ greatly among retroviruses. Because of the high mutability of retroviruses, it is not the generation of new viral variants that limits the extent of diversity and the rate of evolution of retroviruses, but rather the selection forces that act on these variants. Here, we suggest that two selection forces--the immune response and the limited availability of appropriate target cells during transmission and persistence--are chiefly responsible for the observed sequence diversity in untreated retroviral infections. We illustrate these aspects of positive selection by reference to specific lentiviruses [human and simian immunodeficiency viruses (HIV and SIV)] and oncoviruses [feline leukemia virus (FeLV) and human T cell leukemia virus (HTLV)] that differ in their extent of variation and in disease outcomes.", "journal": "Science (New York, N.Y.)", "doi": "10.1126/science.1059128", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11330598", "author": null, "n_authors": 0, "title": "Feline practitioners recommend new FIV and FeLV testing guidelines, initiate public awareness campaign.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11300595", "author": "Kristal O", "n_authors": 6, "title": "Single agent chemotherapy with doxorubicin for feline lymphoma: a retrospective study of 19 cases (1994-1997).", "abstract": "Medical records of 21 cats with confirmed lymphoma treated with single-agent doxorubicin were reviewed. Nineteen cats met the inclusion criteria for this retrospective study. Doxorubicin was given at a dosage of 25 mg/m2 (n = 8) or 1 mg/kg (n = 11) IV, every 3 weeks for a total of 5 treatments. Four of 16 tested cats were positive for feline leukemia virus (FeLV) and all 16 cats tested negative for feline immunodeficiency virus. Eight of the 19 cats (42%) responded to doxorubicin for a median duration of 64 days (range, 35-575 days). Five cats (26%) achieved a complete response (CR) to doxorubicin for a median duration of 92 days (range, 54-575 days). Partial response was observed in 3 cats. Institution was the only significant prognostic indicator for response, with cats treated at Colorado State University being more likely to achieve CR than cats treated at Tufts University. Cats that achieved CR to doxorubicin and FeLV-negative cats had significantly longer survival times. Loss of appetite was the most common toxicity, observed in 9 cats (47%), and was severe in 5 cats (26%). Other toxicoses were less frequent and included vomiting, diarrhea, and myelosuppression. Doxorubicin was not very effective at inducing and maintaining remission in the cats in this study. Therefore, if doxorubicin is used for the treatment of feline lymphoma, it should be combined with other effective chemotherapeutic drugs in a combination protocol.", "journal": "Journal of veterinary internal medicine", "doi": "10.1892/0891-6640(2001)015<0125:sacwdf>2.3.co;2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11300519", "author": "Brown MR", "n_authors": 2, "title": "Neutropenia in dogs and cats: a retrospective study of 261 cases.", "abstract": "Case records of 232 dogs and 29 cats with neutropenia were reviewed to examine the spectrum of underlying etiologies causing the neutropenia. Six etiological categories included nonbacterial infectious disease; increased demand due to marked inflammation, bacterial sepsis, or endotoxemia; drug-associated neutropenia; primary bone-marrow disease; immune-mediated neutropenia; and diseases of unclear etiology. The largest single category associated with the development of neutropenia was nonbacterial infectious disease (e.g., feline leukemia virus [FeLV], feline immunodeficiency virus [FIV], histoplasmosis, cryptococcosis, and parvovirus), with parvovirus infection accounting for 47.1% of all cases. The least common (0.38%) cause was naturally occurring immune-mediated neutropenia.", "journal": "Journal of the American Animal Hospital Association", "doi": "10.5326/15473317-37-2-131", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11280376", "author": "Madewell BR", "n_authors": 5, "title": "Feline vaccine-associated fibrosarcoma: an ultrastructural study of 20 tumors (1996-1999).", "abstract": "Twenty feline vaccine-associated sarcomas were examined by transmission electron microscopy. Tumors contained pleomorphic spindle cells, histiocytoid cells, and giant cells. Most tumors contained myofibroblasts, which had morphologic features similar to those of fibroblasts. These cells were further distinguished by subplasmalemmal dense plaques and thin cytoplasmic actin myofilaments organized as elongated bundles concentrated at irregular intervals forming characteristic dense bodies. Intracellular crystalline particulate material was found in 5 of the 20 tumors. Energy dispersive X-ray spectroscopy was used to identify the crystalline material within one tumor as aluminum-based. One tumor from a feline leukemia virus-infected cat contained budding and immature retroviral particles.", "journal": "Veterinary pathology", "doi": "10.1354/vp.38-2-196", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11272497", "author": "Sleeman JM", "n_authors": 5, "title": "Feline leukemia virus in a captive bobcat.", "abstract": "An 11-mo-old captive-bred male neutered bobcat (Felis rufus) presented with lethargy, anorexia, leukopenia, neutropenia, lymphopenia, and nonregenerative anemia. The animal was diagnosed as feline leukemia virus (FeLV) positive by immunofluorescent antibody and enzyme-linked immunosorbant assay (ELISA) testing. It died despite supportive care. Pathologic examination revealed multifocal non-suppurative encephalitis, diffuse interstitial pneumonia, multifocal hepatocellular necrosis, non-suppurative peritonitis, and lymphoid depletion. FeLV was isolated from peripheral blood mononuclear cells, bone marrow, spleen, and lymph node. FeLV-specific gag sequences were amplified by DNA polymerase chain reaction (PCR) and aligned with known domestic cat FeLV's. The source of the virus was speculated to be a domestic cat that was a surrogate nurse. Case reports of FeLV in nondomestic felids are few, and FeLV does not appear to be enzootic in wild felids, except European wildcats (Felis silvestris) in France and Scotland. Introduction of FeLV into free-living and captive nondomestic felid populations could have serious consequences for their health and survival. Measures to prevent the introduction of this virus to nondomestic felids are warranted.", "journal": "Journal of wildlife diseases", "doi": "10.7589/0090-3558-37.1.194", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11221568", "author": "Wang J", "n_authors": 4, "title": "Characterisation of lymphosarcomas in Australian cats using polymerase chain reaction and immunohistochemical examination.", "abstract": "To examine tumour tissue of cats with lymphosarcoma for the presence of feline leukaemia virus and feline immunodeficiency virus and analyse the immunophenotype of the tumours. A retrospective study of feline lymphosarcoma cases. Formalin-fixed, paraffin-embedded tumour tissue of 14 feline lymphosarcomas was examined for the presence of feline leukaemia virus and feline immunodeficiency virus by polymerase chain reaction and immunohistochemistry. Using polyclonal and monoclonal antibodies against T and B lymphocytes, the phenotypic expression of the tumours was characterised. No feline leukaemia virus antigen or proviral sequences were detected. Feline immunodeficiency virus proviral sequences were detected in two cases by polymerase chain reaction. Immunophenotyping of all 14 cases resulted in seven cases being classified as B-cell phenotype, four as T-cell phenotype, and the remaining three undetermined. In contrast to previous reports overseas, our results suggest that feline leukaemia virus infection appears to be an infrequent cause of lymphosarcoma in the cats that were necropsied. Feline immunodeficiency virus may have a role in lymphomagenesis. The potential role of feline immunodeficiency virus needs to be explored in more depth. Compared with most previous reports, B-cell tumours were more common than T-cell tumours in this series of cats.", "journal": "Australian veterinary journal", "doi": "10.1111/j.1751-0813.2001.tb10639.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11153990", "author": "McNiel EA", "n_authors": 1, "title": "Vaccine-associated sarcomas in cats: a unique cancer model.", "abstract": "Epidemiologic evidence supports a relationship between vaccination of cats for rabies and feline leukemia virus with the development of soft tissue sarcomas at the site of administration. These tumors are locally invasive and histologically aggressive. As with high-grade soft tissue sarcoma in humans, combination treatment with radiation therapy and surgery provides for optimum tumor control. Feline vaccine-associated sarcoma has become a difficult issue for the veterinary profession for legal, ethical, and clinical reasons. Although most research efforts have focused on therapeutic intervention, this tumor has great potential to provide an informative model for carcinogenesis and genetic susceptibility applicable to cancer in all species, including humans.", "journal": "Clinical orthopaedics and related research", "doi": "10.1097/00003086-200101000-00005", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "12503794", "author": "Lawrence K", "n_authors": 1, "title": "Prevalence of FeLV and antibodies to FIV and FCoV in Falkland Islands cats.", "abstract": null, "journal": "The Veterinary record", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "12479298", "author": "Dorny P", "n_authors": 7, "title": "Serological survey of Toxoplasma gondii, feline immunodeficiency virus and feline leukaemia virus in urban stray cats in Belgium.", "abstract": "Three hundred and forty-six serum samples taken between 1998 and 2000 from urban stray cats in the city of Ghent were tested for antibodies to Toxoplasma gondii and feline immunodeficiency virus (FIV), and antigens of feline leukemia virus (FeLV). Of these 346 samples, 243 (70.2 per cent) were seropositive for Tgondii. Thirty-nine cats (11.3 per cent) had antibodies against FIV and 13 (3.8 per cent) had circulating antigens of FeLV. Fewer of the female cats had FIV and heavier cats had a higher seroprevalence of FIV. Exact logistic regression showed that cats that were infected with FIV were more likely to be infected with T gondii (P = 0.04), and the cats with FIV had a higher titre of Tgondii antibodies than FIV-negative animals. However, FeLV was not associated with either T gondii or FIV.", "journal": "The Veterinary record", "doi": "10.1136/vr.151.21.626", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "12418522", "author": "Hardie EM", "n_authors": 3, "title": "Radiographic evidence of degenerative joint disease in geriatric cats: 100 cases (1994-1997).", "abstract": "To determine prevalence of radiographic evidence of degenerative joint disease (DJD) in geriatric cats. Retrospective study. 100 cats > 12 years of age. One investigator reviewed radiographs and for each articulation (or group of articulations) that was visible assigned a grade of severity (0, 1, 2, 3) for DJD. Another investigator reviewed medical records and recorded signalment, environment, previous disease, diseases evident at time of radiography, FeLV vaccination and infection status, feline immunodeficiency virus serologic status, serum creatinine concentration, serum globulin concentration, and any other important findings. Associations between DJD of grade 2 or 3 and variables recorded from the medical record were determined. Radiographic evidence of DJD was evident in 90% of cats. Neurologic disease was associated with lesions in the lumbosacral portion of the vertebral column. Severe lesions were found in 17% of the elbow joints, but an underlying cause was not determined. Degenerative joint disease was detected radiographically in most geriatric cats and may be an overlooked cause of clinical disease. Clinicians should be alert to the possibility that DJD is associated with neurologic signs.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.2002.220.628", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "12418520", "author": "Lee IT", "n_authors": 5, "title": "Prevalence of feline leukemia virus infection and serum antibodies against feline immunodeficiency virus in unowned free-roaming cats.", "abstract": "To determine prevalence of FeLV infection and serum antibodies against feline immunodeficiency virus (FIV) in unowned free-roaming cats. Cross-sectional serologic survey. 733 unowned free-roaming cats in Raleigh, NC, and 1,143 unowned free-roaming cats in Gainesville, Fla. In Raleigh, overall prevalence of FeLV infection was 5.3%, and overall seroprevalence for FIV was 2.3%. In Gainesville, overall prevalence of FeLV infection was 3.7%, and overall seroprevalence for FIV was 4.3%. Overall, FeLV prevalence was 4.3%, and seroprevalence for FIV was 3.5%. Prevalence of FeLV infection was not significantly different between males (4.9%) and females (3.8%), although seroprevalence for FIV was significantly higher in male cats (6.3%) than in female cats (1.5%). Prevalence of FeLV infection and seroprevalence for FIV in unowned free-roaming cats in Raleigh and Gainesville are similar to prevalence rates reported for owned cats in the United States. Male cats are at increased risk for exposure to FIV, compared with female cats.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.2002.220.620", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "12414980", "author": "Faix PH", "n_authors": 4, "title": "Host range and receptor binding properties of vectors bearing feline leukemia virus subgroup B envelopes can be modulated by envelope sequences outside of the receptor binding domain.", "abstract": "To evaluate host range differences between two different strains of feline leukemia virus subgroup B (FeLV-B), we compared the binding and infectivity patterns of retrovirus vectors bearing either FeLV-B-90Z or FeLV-B-GA envelopes. We report here that the ability of these envelopes to utilize different Pit1 orthologs is mediated primarily by the receptor binding domain; however, in the case of FeLV-B-90Z, the C terminus also contributes to the recognition of certain Pit1 orthologs.", "journal": "Journal of virology", "doi": "10.1128/jvi.76.23.12369-12375.2002", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "12360955", "author": "Abramo F", "n_authors": 4, "title": "Feline cutaneous phaeohyphomycosis due to Cladophyalophora bantiana.", "abstract": "A case of feline cutaneous phaeohyphomycosis due to Cladophyalophora bantiana is described. The cat was presented with breathing difficulty and a swollen, ulcerated nodule on the dorsal nose and left nostril. Histological examination of the nodule revealed a cystic granulomatous dermatitis characterised by neutrophils, macrophages and giant cells. Pigmented, yeast-like fungus cells and hyphal elements were easily identified in haematoxylin-eosin stained tissue sections. Cladophyalophora bantiana was isolated from a tissue specimen. This organism, primarily known to cause cerebral infection in humans and cats, only rarely causes cutaneous infection. Despite anti-fungal chemotherapy two relapses occurred. The cat was feline immunodeficiency virus- and feline leukemia virus-negative and even if the owner was unaware of trauma, the hypothesis of wound contamination is the most likely.", "journal": "Journal of feline medicine and surgery", "doi": "10.1053/jfms.2002.0183", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "12243463", "author": "Carmichael KP", "n_authors": 3, "title": "Feline leukemia virus-associated myelopathy in cats.", "abstract": "Feline leukemia virus (FeLV) infection is associated with distinct neoplastic, hematologic, and immunosuppressive diseases. Here we report on a novel neurologic syndrome in 16 cats infected with FeLV for more than 2 years. Clinical signs consisted of abnormal vocalization, hyperesthesia, and paresis progressing to paralysis. The clinical course of affected cats involved gradually progressive neurologic dysfunction invariably resulting in euthanasia. Microscopically, white-matter degeneration with dilation of myelin sheaths and swollen axons was identified in the spinal cord and brain stem of affected animals. Neither neoplastic nor hematologic diseases commonly associated with FeLV infection were present. Fungal and protozoal infection in one animal was suggestive of impaired immune competence. Immunohistochemical staining of affected tissues revealed consistent expression of FeLV p27 antigens in neurons, endothelial cells, and glial cells. Furthermore, proviral DNA was amplified from multiple sections of spinal cord as well as intestine, spleen, and lymph nodes. These findings suggest that in a proportion of chronically FeLV-infected cats, a virus evolved with cytopathic potential for cells in the central nervous system.", "journal": "Veterinary pathology", "doi": "10.1354/vp.39-5-536", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "12240526", "author": "Gibson KL", "n_authors": 3, "title": "A trap, neuter, and release program for feral cats on Prince Edward Island.", "abstract": "A new program to address the feral cat population on Prince Edward Island was undertaken during the spring and summer of 2001. Feral cats from specific geographic areas were trapped, sedated, and tested for feline leukemia virus and feline immunodeficiency virus. Healthy cats were neutered, dewermed, vaccinated, tattooed, and released to their area of origin. A total of 185 cats and kittens were trapped and tested during a 14-week period; 158 cats and kittens as young as 6 weeks of age were neutered and released. Twenty-three adult cats were positive for feline leukemia virus, feline immunodeficiency virus, or both, and were euthanized.", "journal": "The Canadian veterinary journal = La revue veterinaire canadienne", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "12180842", "author": "Specke V", "n_authors": 8, "title": "Virus safety in xenotransplantation: first exploratory in vivo studies in small laboratory animals and non-human primates.", "abstract": "For xenotransplantation, the transplantation of animal cells, tissues and organs into human recipients, to date, pigs are favored as potential donors. Beside ethical, immunological, physiological and technical problems, the microbiological safety of the xenograft has to be guaranteed. It will be possible to eliminate all of the known porcine microorgansims in the nearby future by vaccinating or specified pathogen-free breeding. Thus, the main risk will come from the porcine endogenous retroviruses (PERVs) which are present in the pig genome as proviruses of different subtypes. PERVs will therefore be transmitted, with the xenograft, to the human recipient. PERVs can infect numerous different types of human primary cells and cell lines in vitro and were shown to adapt to these cells by serial passaging on uninfected cells. Furthermore, PERVs have high homology to other retroviruses, such as feline leukemia virus (FeLV) or murine leukemia virus (MuLV), which are known to induce tumors or immunodeficiencies in the infected host. To evaluate the potential risk of a trans-species transmission of PERV in vivo, naive and immunosuppressed rats, guinea pigs and minks were inoculated with PERV and screened over a period of 3 months for an antibody reaction against PERV proteins or for the integration of proviral DNA into the genomic DNA of the host's cells. Furthermore, we inoculated three different species of non-human primates, rhesus monkey (Macaca mulatta), pig-tailed monkey (Macaca nemestrina) and baboon (Papio hamadryas) with high titers of a human-adapted PERV. To simulate a situation in xenotransplantation, the animals received a daily triple immunosuppression using cyclosporine A, methylprednisolone and RAD, a rapamycin derivative, presently under development by Novartis. None of the small laboratory animals or the non-human primates showed production of antibodies against PERV or evidence of integration of proviral DNA in blood cells or cells of several organs, 3 months after virus inoculation, despite the observation that cells of the animals used in the experiment were infectible in vitro. This apparent difference in the outcome of the in vitro and the in vivo data might be explained by an efficient elimination of the virus by the innate or adaptive immunity of the animals.", "journal": "Transplant immunology", "doi": "10.1016/s0966-3274(02)00039-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "12171173", "author": "George JW", "n_authors": 4, "title": "Effect of preexisting FeLV infection or FeLV and feline immunodeficiency virus coinfection on pathogenicity of the small variant of Haemobartonella felis in cats.", "abstract": "To investigate the effects of preexisting FeLV infection or FeLV and feline immunodeficiency (FIV) coinfection on the pathogenicity of the small variant of Haemobartonella felis (Hfsm, California variant) in cats. 20 FeLV infected, 5 FeLV-FIV coinfected, and 19 retrovirus-free cats. A client-owned cat, coinfected with FeLV and Hfsm, was the source for Hfsm. Inoculum 1 (FeLV free) was obtained by passage of source Hfsm through 4 FeLV-resistant cats. Inoculum 2 was obtained by further passage of Hfsm (inoculum 1) through 2 specific pathogen-free cats. A mild-to-moderate anemia started 21 days after inoculation, with its nadir occurring at 35 to 42 days after inoculation. Infection with Hfsm induced greater decrease in hemoglobin concentration in FeLV infected cats, compared with retrovirus free cats. Reticulocytosis, macrocytosis, and polychromasia of erythrocytes developed in anemic cats regardless of retrovirus infection status. Mean neutrophil counts decreased during the hemolytic episode. For most cats, the anemia was transient. Four FeLV infected cats, 1 of which was also FIV infected, developed fatal FeLV-associated myeloproliferative diseases. Of the surviving cats, 8 died over the next 24 months from other FeLV-related diseases. Hemolysis did not recur after the initial episode. Inoculum 1 induced more severe anemia than inoculum 2. Our results support the clinical observation that cats coinfected with FeLV and H felis develop more severe anemia than cats infected with H felis alone. Infection with Hfsm may induce myeloproliferative disease in FeLV infected cats. The small variant of H felis may lose pathogenicity by passage through FeLV-free cats.", "journal": "American journal of veterinary research", "doi": "10.2460/ajvr.2002.63.1172", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "12164225", "author": "Harrus S", "n_authors": 8, "title": "Retrospective study of 46 cases of feline haemobartonellosis in Israel and their relationships with FeLV and FIV infections.", "abstract": "Forty-six cats with clinical haemobartonellosis were studied; 75 per cent of the cats of known age were two-and-a-half years old or younger, 50 per cent were intact males and 19.5 per cent were castrated males. The predominant signs of the disease were tachypnoea, lethargy, depression, anorexia, infestation with fleas, pale mucous membranes, icterus, emaciation, dehydration, splenomegaly, anaemia, leucocytosis, increased activities of alanine aminotransferase and aspartate aminotransferase, and azotaemia. Thirty-eight per cent of the cats that were tested for feline leukaemia virus (FeLV) antigen were positive, and 22 per cent of those tested for feline immunodeficiency virus (FIV) antibodies were positive. The prevalence of both FeLV and FIV was much higher than in the general Israeli cat population. The cats infected with both Haemobartonella felis and FeLV had a significantly lower body temperature, were more anaemic and the mean cell volume of their erythrocytes was greater than in the cats with haemobartonellosis alone.", "journal": "The Veterinary record", "doi": "10.1136/vr.151.3.82", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "12152818", "author": "Cullen CL", "n_authors": 4, "title": "Lack of detection of feline leukemia and feline sarcoma viruses in diffuse iris melanomas of cats by immunohistochemistry and polymerase chain reaction.", "abstract": "Diffuse iris melanoma was confirmed by light-microscopic examination in 10 formalin-fixed, paraffin-embedded globes from 10 cats. To determine if feline leukemia virus or a replication defective feline leukemia virus, feline sarcoma virus, was present in these anterior uveal melanomas, immunohistochemistry and polymerase chain reaction for feline leukemia virus were utilized. Immunohistochemical staining for feline leukemia virus glycoprotein 70 was performed on all 10 tumors using an avidin-biotin complex technique. The DNA was extracted from each specimen and a 166-base pair region of the feline leukemia virus long terminal repeat was targeted by polymerase chain reaction. Immunohistochemical staining for feline leukemia virus glycoprotein 70 and polymerase chain reaction amplification of a feline leukemia virus long terminal repeat region were negative in all cases. Feline leukemia virus/feline sarcoma virus was not detected in any neoplasms and therefore was unlikely to play a role in the tumorigenesis of these feline diffuse iris melanomas.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/104063870201400414", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "12134012", "author": "Lauring AS", "n_authors": 4, "title": "Genetic and biochemical analyses of receptor and cofactor determinants for T-cell-tropic feline leukemia virus infection.", "abstract": "Entry by retroviruses is mediated through interactions between the viral envelope glycoprotein and the host cell receptor(s). We recently identified two host cell proteins, FeLIX and Pit1, that are necessary for infection by cytopathic, T-cell-tropic feline leukemia viruses (FeLV-T). Pit1 is a classic multiple transmembrane protein used as a receptor by several other simple retroviruses, including subgroup B FeLV (FeLV-B), and FeLIX is a secreted cellular protein expressed from endogenous FeLV-related sequences (enFeLV). FeLIX is nearly identical to FeLV-B envelope sequences that encode the N-terminal half of the viral surface unit (SU), because these FeLV-B sequences are acquired by recombination with enFeLV. FeLV-B SUs can functionally substitute for FeLIX in mediating FeLV-T infection. Both of these enFeLV-derived cofactors can efficiently facilitate FeLV-T infection only of cells expressing Pit1, not of cells expressing the related transport protein Pit2. We therefore have used chimeric Pit1/Pit2 receptors to map the determinants for cofactor binding and FeLV-T infection. Three distinct determinants appear to be required for cofactor-dependent infection by FeLV-T. We also found that Pit1 sequences within these same domains were required for binding by FeLIX to the Pit receptor. In contrast, these determinants were not all required for receptor binding by the FeLV-B SU cofactors used in this study. These data indicate that cofactor binding is not sufficient for FeLV-T infection and suggest that there may be a direct interaction between FeLV-T and the Pit1 receptor.", "journal": "Journal of virology", "doi": "10.1128/jvi.76.16.8069-8078.2002", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "12126896", "author": "Harbour DA", "n_authors": 7, "title": "Protection against oronasal challenge with virulent feline leukaemia virus lasts for at least 12 months following a primary course of immunisation with Leukocell 2 vaccine.", "abstract": "The duration of immunity provided by a feline leukemia virus (FeLV) vaccine, Leukocell 2, was determined. Kittens were vaccinated when 9 and 12 weeks of age and were challenged 12 months later with FeLV-A/Glasgow-1. An oronasal challenge protocol without corticosteroid enhancement was developed in order to induce a persistent viraemia in a high proportion of adult cats. Fourteen of 18 (80%) of the vaccinated cats challenged in this way remained non-viraemic while 9/15 (60%) of age-matched controls became persistently infected, a preventable fraction of 63%. This difference was statistically significant (P=0.038). For comparison, 10 of 12 (83%) 15-17-week-old kittens challenged in the same way became persistently infected, confirming the relative resistance of adult animals to FeLV. Tests for virus neutralising and anti-feline oncornavirus-associated cell membrane antigen (FOCMA) antibodies suggested that the former were more important than the latter in protection. Thus, Leukocell 2 protected a significant proportion of cats from FeLV challenge 1 year after primary vaccination as kittens.", "journal": "Vaccine", "doi": "10.1016/s0264-410x(02)00237-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "12097582", "author": "Farrell KB", "n_authors": 4, "title": "Reassessing the role of region A in Pit1-mediated viral entry.", "abstract": "The mammalian gammaretroviruses gibbon ape leukemia virus (GALV) and feline leukemia virus subgroup B (FeLV-B) can use the same receptor, Pit1, to infect human cells. A highly polymorphic nine-residue sequence within Pit1, designated region A, has been proposed as the virus binding site, because mutations in this region abolish Pit1-mediated cellular infection by GALV and FeLV-B. However, a direct correlation between region A mutations deleterious for infection and loss of virus binding has not been established. We report that cells expressing a Pit1 protein harboring mutations in region A that abolish receptor function retain the ability to bind virus, indicating that Pit1 region A is not the virus binding site. Furthermore, we have now identified a second region in Pit1, comprising residues 232 to 260 (region B), that is required for both viral entry and virus binding. Epitope-tagged Pit1 proteins were used to demonstrate that mutations in region B result in improper orientation of Pit1 in the cell membrane. Compensatory mutations in region A can restore proper orientation and full receptor function to these region B mutants. Based on these results, we propose that region A of Pit1 confers competence for viral entry by influencing the topology of the authentic binding site in the membrane and hence its accessibility to a viral envelope protein. Based on glycosylation studies and results obtained by using N- and C-terminal epitope-tagged Pit1, region A and region B mutants, and the transmembrane helices predicted with the PHD PredictProtein algorithm, we propose a new Pit1 topology model.", "journal": "Journal of virology", "doi": "10.1128/jvi.76.15.7683-7693.2002", "deposited_data": "Sim", "nuccore_ids": "2501363558, 2501363550, 2501356983, 2501356593, 1907137055, 1907137051, 1519311779, 1243938578", "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "12046785", "author": "Muirden A", "n_authors": 1, "title": "Prevalence of feline leukaemia virus and antibodies to feline immunodeficiency virus and feline coronavirus in stray cats sent to an RSPCA hospital.", "abstract": "A total of 517 stray cats at an RSPCA veterinary hospital were tested for feline leukaemia virus (FeLV), feline coronavirus (FCoV) and feline immunodeficiency virus (FIV). The prevalence of FeLV was 3.5 per cent in all the cats, 1.4 per cent in healthy cats and 6.9 per cent in sick cats. FeLV positivity was associated only with disease of non-traumatic origin. Antibodies to FCoV were present in 22.4 per cent of the cats, and their prevalence was significantly higher in cats over two years old and in feral/semiferal cats. The prevalence of antibodies to FIV was 10.4 per cent in all the cats, 4.9 per cent in healthy cats and 16.7 per cent in sick cats. The prevalence of FIV antibodies was significantly higher in entire males and neutered males than in females, in cats over two years old compared with younger cats, and in cats suffering disease of non-traumatic origin rather than in healthy cats or cats suffering only from trauma. Sex, age and health status were each independently highly associated with FIV antibodies.", "journal": "The Veterinary record", "doi": "10.1136/vr.150.20.621", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "12009059", "author": "Carroll EE", "n_authors": 3, "title": "Cats differ from mink and ferrets in their response to commercial vaccines: a histologic comparison of early vaccine reactions.", "abstract": "Early histologic changes in lesions at vaccine sites were compared in cats, mink, and ferrets. Twenty-four 4-month-old cats, 20 4-month-old mink, and 20 12-month-old ferrets were vaccinated with three rabies virus vaccines, two feline leukemia virus vaccines, alum adjuvant, and saline. Injection sites were excised at selected time points up to 21 days postvaccination. Histologic examination of the tissue revealed significant differences among the cats, mink, and ferrets in the local response to the commercial vaccines. When compared with ferrets and mink, cats had more lymphocytes in response to all three rabies vaccines. Production of fibroblasts, collagen, and macrophages differed among the three killed aluminum-adjuvanted vaccines in cats but did not differ significantly in mink or ferrets. Cats produced fewer binucleate cells than did mink or ferrets in response to the two adjuvanted leukemia virus vaccines. Differences seen in early tissue response of cats to commercial vaccines may be related to the increased predisposition of cats to vaccine-associated sarcomas.", "journal": "Veterinary pathology", "doi": "10.1354/vp.39-2-216", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "11988186", "author": "Darkes MJ", "n_authors": 4, "title": "The effect of fusion inhibitors on the phase behaviour of N-methylated dioleoylphosphatidylethanolamine.", "abstract": "The effects of two fusion inhibitors on the lipid polymorphism of N-methylated dioleoylphosphatidylethanolamine were studied using temperature-resolved, small-angle X-ray diffraction. The inhibitory role of the tri-peptide carbobenzoxy-D-phenylalanine-L-phenylalanine-glycine and the lipid 1-lauroyl-2-hydroxy-sn-glycero-3-phosphocholine in the fusion pathway was studied, using the non-lamellar phase behaviour of the lipid as a model. We used p15EK, the N-terminal region of gp41 from feline leukaemia virus as promoter of membrane fusion, and measured the structural parameters of each observed lipid phase as a function of temperature. The fusion inhibitors were found to impede the expression of negative curvature of lipid monolayers even in the presence of fusion peptide. The results of this study are interpreted in relation to models of the membrane fusion mechanism.", "journal": "Biochimica et biophysica acta", "doi": "10.1016/s0005-2736(01)00464-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "11943475", "author": "Lipovich L", "n_authors": 5, "title": "Genomic structure and evolutionary context of the human feline leukemia virus subgroup C receptor (hFLVCR) gene: evidence for block duplications and de novo gene formation within duplicons of the hFLVCR locus.", "abstract": "In this paper we sought to analyze the genomic structure and context of human feline leukemia virus subgroup C receptor (hFLVCR), a human glucarate transporter-like gene at chromosome 1q31, and compare it to that of a paralog (FLVCR14q) at chromosome 14q24. Splicing, polyadenylation, and expression patterns, as estimated by in silico analysis, differed between the two FLVCR genes despite their similar genomic structures, suggesting active and independent evolution of transcriptional and messenger RNA processing patterns after gene duplication. Promoter activity was bi-directional for hFLVCR, but not for its 14q paralog. The upstream 1q transcribed sequences were determined to comprise a novel gene of unknown function, LQK1. Annotation of contigs centered at hFLVCR and FLVCRL14q also revealed highly conserved gene clusters on chromosomes 1 and 14, inferred to result from a duplication. The clusters contained members of the FLVCR, Angel (KIAA0759), JDP, p21SNFT, and TGF- families, as well as two uncharacterized families. The genome-wide locations of both previously recognized and four de novo in silico predicted genes belonging to these seven families were determined. Phylogenetic analyses of these families were consistent with the hypothesis that the 1q/14q duplication occurred early within, or immediately prior to the vertebrate divergence, after the protostome-deuterostome divergence but before the amniote-amphibian divergence.", "journal": "Gene", "doi": "10.1016/s0378-1119(02)00457-2", "deposited_data": "Sim", "nuccore_ids": "1890388947, 1890341961, 1889708428, 1889580205, 1889474596, 1668809122, 1668804594, 1668804592, 1656464214, 1519241939, 224591397, 224591396, 20087014, 20087012, 2462515225, 2462515223, 2462515221, 2462515219, 2462515217, 2462515215, 2462515213, 2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217272165, 2217272163, 2217272161, 2217272160, 2217272159, 2217272158, 2217272157, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1890388947, 1890341961, 1889708428, 1889580205, 1889474596, 1668809122, 1668804594, 1668804592, 1656464214, 1519315556, 1519241939, 224591397, 224591396", "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "11932392", "author": "Farrell KB", "n_authors": 3, "title": "Fusion-defective gibbon ape leukemia virus vectors can be rescued by homologous but not heterologous soluble envelope proteins.", "abstract": "Murine leukemia virus (MLV)-derived envelope proteins containing alterations in or adjacent to the highly conserved PHQ motif present at the N terminus of the envelope surface subunit (SU) are incorporated into vector particles but are not infectious due to a postbinding block to viral entry. These mutants can be rendered infectious by the addition of soluble receptor-binding domain (RBD) proteins in the culture medium. The RBD proteins that rescue the infectivity of these defective MLV vectors can be derived from the same MLV or from other MLVs that use distinct receptors to mediate entry. We have now constructed functional immunologically reactive gibbon ape leukemia virus (GALV) envelope proteins, tagged with a feline leukemia virus (FeLV)-derived epitope tag, which are efficiently incorporated into infectious particles. Tagged GALV envelope proteins bind specifically to cells expressing the phosphate transporter protein Pit1, demonstrating for the first time that Pit1 is the binding receptor for GALV and not a coreceptor or another type of GALV entry factor. We have also determined that GALV particles bearing SU proteins with an insertion C-terminal to the PHQ motif (GALV I(10)) bind Pit1 but fail to infect cells. Incubation with soluble GALV RBD renders GALV I(10) particles infectious, whereas incubation with soluble RBDs from MLV or FeLV-B does not. This finding is consistent with the results obtained by Lauring et al. using FeLV-T, a virus that employs Pit1 as a receptor but requires soluble FeLV RBD for entry. MLV and GALV RBDs are not able to render FeLV-T infectious (A. S. Lauring, M. M. Anderson, and J. Overbaugh, J. Virol. 75:8888-8898, 2001). Together, these results suggest that fusion-defective FeLV-T and GALV are restricted to homologous RBD rescue of infectivity.", "journal": "Journal of virology", "doi": "10.1128/jvi.76.9.4267-4274.2002", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "11907331", "author": "Haviernik P", "n_authors": 7, "title": "Linkage on chromosome 10 of several murine retroviral integration loci associated with leukaemia.", "abstract": "Mml loci have been identified as provirus integration sites among a subset of monocytic tumours induced by murine leukaemia virus (MuLV) infection of BALB/c and DBA/2 mice. These myeloid leukaemias contain a retrovirus integrated on chromosome 10 in proximity to the c-myb locus; however, c-myb expression was not altered. Detailed physical mapping enabled placement of the retroviral integration sites approximately 25 kb (Mml1), approximately 51 kb (Mml2), and approximately 70 kb (Mml3) upstream of the c-myb locus. Furthermore, the Fti1 (fit-1) locus, a common integration site in feline leukaemia virus-induced T cell lymphomas, was mapped upstream of Mml3. Sequence analysis of Mml1, Mml2 and Mml3 loci (39.6, 16.4 and 5.9 kb, respectively) in conjunction with the BLAST (basic local alignment search tool) homology searches against the expressed sequence tag (EST) database and the use of gene/exon prediction programs revealed potential coding sequences that were not confirmed by Northern analysis or RT-PCR. The sequences between c-myb and Fti1, which were shown to include two potential scaffold/matrix attachment regions (S/MARs), are most likely regulatory in nature. An extended search for transcribed sequences far upstream of Mml3 revealed five genes, four of which were expressed in multiple tissues in mice. These genes could not be linked to tumour formation by the virus but their homologous sequences were found on human chromosome 6, thus allowing extension of the syntenic region on mouse chromosome 10 to approximately 250 kb.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-83-4-819", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "11899035", "author": "Teske E", "n_authors": 4, "title": "Chemotherapy with cyclophosphamide, vincristine, and prednisolone (COP) in cats with malignant lymphoma: new results with an old protocol.", "abstract": "This retrospective study in 61 cats with malignant lymphomas examined the efficacy of a well-established chemotherapy protocol (cyclophosphamide, vincristine, and prednisolone [COP]) in the Netherlands, a country with a low prevalence of feline leukemia virus (FeLV). Twenty-two cats (36.1%) had mediastinal lymphoma, 11 (18.0%) had alimentary lymphoma, 7 (11.5%) had peripheral lymphoma, 8 (13.1%) had nasal lymphoma, and 13 (21.3%) had miscellaneous lymphoma (including renal lymphoma in 2 [3.3%]). Of the 54 cats that were tested, only 4 (7.4%) were FeLV positive. Complete remission (CR) was achieved in 46 of the 61 cats (75.4%). The estimated 1- and 2-year disease-free periods (DFPs) in the 46 cats with CR were 51.4 and 37.8%, respectively, whereas the median duration of remission was 251 days. The overall estimated 1-year survival rate in all cats was 48.7%, and the 2-year survival rate was 39.9%, with a median survival of 266 days. The median survival time and the 1-year survival rate for mediastinal lymphoma were 262 days and 49.4%. respectively. Siamese cats had a more favorable prognosis for survival and remission than other breeds. Response to therapy in this study was shown to be a significant prognostic indicator. CR is necessary for long-term survival. Cats that did not achieve CR had little chance of survival for longer than I year. Young Siamese cats in this study had a greater tendency to develop mediastinal malignant lymphoma at a young age, and all were FeLV negative. In comparison with results reported in other studies with different combination chemotherapy protocols, these are among the highest percentages of remission and the longest survival rates for cats with malignant lymphoma.", "journal": "Journal of veterinary internal medicine", "doi": "10.1892/0891-6640(2002)016<0179:cwcvap>2.3.co;2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "11863424", "author": "Bupp K", "n_authors": 2, "title": "Altering retroviral tropism using a random-display envelope library.", "abstract": "Tissue-specific gene delivery is an important aspect of many gene therapy applications. The experiments reported here constitute the first successful demonstration that cell-specific entry can be obtained by screening a random library of retroviral envelope proteins produced from a mammalian cell system. The library consisted of 10(6) different subgroup A feline leukemia virus envelope protein variants with 10 randomly substituted amino acids in the receptor-determining region. Selecting the library for fully functional envelope proteins able to mediate stable gene transfer resulted in the identification of a single envelope protein variant (EF). Subsequent examination of the host range of EF revealed that it was highly specific for D17 canine osteosarcoma cells. This was in contrast to the host ranges of the parental subgroup A and closely related subgroup C envelope proteins. Interference assays on D17 cells further indicated that receptor usage by EF was also altered compared with the A and C envelope proteins. The EF envelope protein thus isolated should be useful for studying gene therapy treatments of osteosarcoma in a large-animal model.", "journal": "Molecular therapy : the journal of the American Society of Gene Therapy", "doi": "10.1006/mthe.2002.0546", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "11836409", "author": "Flynn JN", "n_authors": 4, "title": "Longitudinal analysis of feline leukemia virus-specific cytotoxic T lymphocytes: correlation with recovery from infection.", "abstract": "Feline leukemia virus (FeLV) is a common naturally occurring gammaretrovirus of domestic cats that is associated with degenerative diseases of the hematopoietic system, immunodeficiency, and neoplasia. Although the majority of cats exposed to FeLV develop a transient infection and recover, a proportion of cats become persistently viremic and many subsequently develop fatal diseases. To define the dominant host immune effector mechanisms responsible for the outcome of infection, we studied the longitudinal changes in FeLV-specific cytotoxic T lymphocytes (CTLs) in a group of naïve cats following oronasal exposure to FeLV. Using (51)Cr release assays to measure ex vivo virus-specific cytotoxicity, the emerging virus-specific CTL response was correlated with modulations in viral burden as assessed by detection of infectious virus, FeLV p27 capsid antigen, and proviral DNA in the blood. High levels of circulating FeLV-specific effector CTLs appeared before virus neutralizing antibodies in cats that recovered from exposure to FeLV. In contrast, persistent viremia was associated with a silencing of virus-specific humoral and cell-mediated host immune effector mechanisms. A single transfer of between 2 x 10(7) and 1 x 10(8) autologous, antigen-activated lymphoblasts was associated with a downmodulation in viral burden in vivo. The results suggest an important role for FeLV-specific CTLs in retroviral immunity and demonstrate the potential to modulate disease outcome by the adoptive transfer of antigen-specific T cells in vivo.", "journal": "Journal of virology", "doi": "10.1128/jvi.76.5.2306-2315.2002", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "11817865", "author": "Kerr MG", "n_authors": 1, "title": "Testing for FeLV and FIV infection.", "abstract": null, "journal": "The Veterinary record", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "11815291", "author": "Miyazawa T", "n_authors": 1, "title": "Infections of feline leukemia virus and feline immunodeficiency virus.", "abstract": "Feline retrovirus infections have been extensively studied for more than 30 years as an animal model for the persistent infections and pathogenesis caused by retroviruses in general. Two retroviruses, feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV), have been recognized as causative agents of a variety of diseases including proliferative and degenerative diseases. Recent studies revealed the receptors of FeLV, its variants and FIV. FeLVs utilize at least three distinct receptors, two of which have been successfully cloned and characterized. Furthermore, an FeLV variant which induces severe immunodeficiency, utilizes a truncated envelope of the endogenous FeLV as coreceptor or cofactor for viral entry. FIV utilizes as receptor one of the chemokine receptors, CXCR4 which also is a coreceptor for the T-lymphotropic human immunodeficiency virus. This review provides an overview to the infections of FeLV and FIV, specifically focuses on the viral genomic structures, FeLV variants, the immune responses and recent findings on the receptors for FeLV and FIV. Better understanding of retroviral persistence and pathogenesis will aid the development of prophylactic vaccines and therapeutic medicine to interfere with retrovirus infections.", "journal": "Frontiers in bioscience : a journal and virtual library", "doi": "10.2741/A791", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "11773427", "author": "Nishigaki K", "n_authors": 7, "title": "Analysis of the disease potential of a recombinant retrovirus containing Friend murine leukemia virus sequences and a unique long terminal repeat from feline leukemia virus.", "abstract": "We have molecularly cloned a feline leukemia virus (FeLV) (clone 33) from a domestic cat with acute myeloid leukemia (AML). The long terminal repeat (LTR) of this virus, like the LTRs present in FeLV proviruses from other cats with AML, contains an unusual structure in its U3 region upstream of the enhancer (URE) consisting of three tandem direct repeats of 47 bp. To test the disease potential and specificity of this unique FeLV LTR, we replaced the U3 region of the LTR of the erythroleukemia-inducing Friend murine leukemia virus (F-MuLV) with that of FeLV clone 33. When the resulting virus, F33V, was injected into newborn mice, almost all of the mice eventually developed hematopoietic malignancies, with a significant percentage being in the myeloid lineage. This is in contrast to mice injected with an F-MuLV recombinant containing the U3 region of another FeLV that lacks repetitive URE sequences, none of which developed myeloid malignancies. Examination of tumor proviruses from F33V-infected mice failed to detect any changes in FeLV U3 sequences other than that in the URE. Like F-MuLV-infected mice, those infected with the F-MuLV/FeLV recombinants were able to generate and replicate mink cell focus-inducing viruses. Our studies are consistent with the idea that the presence of repetitive sequences upstream of the enhancer in the LTR of FeLV may favor the activation of this promoter in myeloid cells and contribute to the development of malignancies in this hematopoietic lineage.", "journal": "Journal of virology", "doi": "10.1128/jvi.76.3.1527-1532.2002", "deposited_data": "Sim", "nuccore_ids": "970244998", "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "19003209", "author": "Eto N", "n_authors": 5, "title": "Immuno-chromatographic assay for diagnosis of feline leukemia virus infection.", "abstract": "Feline leukemia virus (FeLV) infectious disease is one of feline infection diseases spreading broadly all over the world. For bedside diagnosis of FeLV infectious disease, an immuno-chromatographic assay was investigated. Five different monoclonal antibodies were developed against the major core protein FeLV-p27. Among them, the combination of FL6 and FL12, which had little epitopic overlap each other, showed the highest sensitivity with no cross-reaction to the other feline virus antigens when they were employed to the immuno-chromatographic assay. The system had a practical detection limit of 0.5 ng of FeLV-p27 per 0.1 ml of feline sera within 15 min. In comparison with clinical standard methods, the system gave rapidly and accurately the same diagnosis with neither false negative nor false positive. Moreover, it did not need any pretreatment of blood specimen.", "journal": "Cytotechnology", "doi": "10.1023/b:cyto.0000039900.04798.d1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "16032339", "author": "Squires RA", "n_authors": 1, "title": "An update on aspects of viral gastrointestinal diseases of dogs and cats.", "abstract": "Viruses commonly cause gastrointestinal illnesses in dogs and cats that range in severity from mild diarrhoea to malignant neoplasia. Perpetual evolution of viruses is reflected in changing disease patterns, so that familiar viruses are sometimes discovered to cause new or unexpected diseases. For example, canine parvovirus (CPV) has regained the ability to infect felids and cause a panleucopenia-like illness. Feline panleucopenia virus (FPV) has been shown to cause fading in young kittens and has recently been implicated as a possible cause of feline idiopathic cardiomyopathy. Molecular scrutiny of viral diseases sometimes permits deeper understanding of pathogenesis and epizootiology. Feline gastrointestinal lymphomas have not, in the past, been strongly associated with retroviral infections, yet some of these tumours harbour retroviral proviruses. Feline leukaemia virus (FeLV) may play a role in lymphomagenesis, even in cats diagnosed as uninfected using conventional criteria. There is strong evidence that feline immunodeficiency virus (FIV) can also be oncogenic. The variant feline coronaviruses that cause invariably-fatal feline infectious peritonitis (FIP) arise by sporadic mutation of an ubiquitous and only mildly pathogenic feline enteric coronavirus (FECV); a finding that has substantial management implications for cat breeders and veterinarians. Conversely, canine enteric coronavirus (CECV) shows considerable genetic and antigenic diversity but causes only mild, self-limiting diarrhoea in puppies. Routine vaccination against this virus is not recommended. Although parvoviruses, coronaviruses and retroviruses are the most important known viral causes of canine and feline gastrointestinal disease, other viruses play a role. Feline and canine rotaviruses have combined with human rotaviruses to produce new, reassortant, zoonotic viruses. Some companion animal rotaviruses can infect humans directly. Undoubtedly, further viral causes of canine and feline gastrointestinal disease await discovery.", "journal": "New Zealand veterinary journal", "doi": "10.1080/00480169.2003.36379", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "16032299", "author": "Thompson JC", "n_authors": 1, "title": "Myelofibrosis in a cat (abstract).", "abstract": "A 2-year-old female domestic shorthair cat was presented with ill-health and marked ascites. Clinically, there was marked pallor of mucous membranes. Two haematological examinations and transudate-exudate analyses of peritoneal fluid were conducted 1 week apart, as well as a coagulation screen and routine serum biochemistry. The haematological examinations revealed a severe persistent non-regenerative anaemia. There were no abnormalities within the neutrophil and lymphocyte cell lines. Very occasional nucleated red blood cells (RBCs) in peripheral circulation and some RBC agglutination were seen. Analysis of peritoneal fluid disclosed a modified transudate, and small numbers of erythroid and myeloid precursors were observed on the second occasion. The cat was FIV/FeLV-negative, and there were no coagulation abnormalities. Following necropsy and histopathological examination, myelofibrosis and extramedullary haematopoiesis were seen. Thoracic masses were hyperplastic lymph nodes in which there was evidence of extramedullary haematopoiesis. The exact cause of the myelofibrosis was not obvious but it may have been a case of myeloid metaplasia, however not all the characteristics of this entity were present.", "journal": "New Zealand veterinary journal", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "14736717", "author": "Levy JK", "n_authors": 8, "title": "Prevalence and risk factors for heartworm infection in cats from northern Florida.", "abstract": "Necropsies were performed on 630 adult cats in northern Florida to determine the prevalence and risk factors for heartworm infection in cats of this region. Heartworms were identified in 4.9% of cats, and serological evidence of heartworm exposure was present in 17% of cats. Not all cats from which heartworms were recovered were seropositive for heartworm antigen or antibody. There was no association between heartworm infection and co-infection with feline leukemia virus (FeLV) or feline immunodeficiency virus (FIV). Male cats were at higher risk of infection with heartworm, FeLV, or FIV than were females. Because even a single heartworm can cause clinical disease or death in cats, the authors conclude that cats in this region should receive heartworm prophylaxis to prevent heartworm infection.", "journal": "Journal of the American Animal Hospital Association", "doi": "10.5326/0390533", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "14708522", "author": "Kurihara T", "n_authors": 8, "title": "Sensitivity to human serum of gammaretroviruses produced from pig endothelial cells transduced with glycosyltransferase genes.", "abstract": "Reduction of pig cell-surface alpha-galactosyl (Gal) epitope, Galalpha1, 3Galbeta1, 4GlcNAc-R, by the introduction of glycosyltransferase genes is effective in suppressing hyperacute rejection (HAR) in pig-to-human xenotransplantation. The transmission of porcine endogenous retroviruses (PERVs) has been recognized as a potential risk factor associated with xenotransplantation. In this study, effects of the introduction of glycosyltransferase genes to pig cells on the sensitivity of gammaretroviruses to human serum were investigated. Pig endothelial cells (PEC), PEC transduced with alpha1,2 fucosyltransferase (FT), alpha2,3 sialyltransferase (ST), or N-acetylglucosaminyltransferase III (GnT-III), and human embryonic kidney (HEK) 293 cells were transduced with the LacZ gene with the packaging signal of murine leukemia virus (MuLV) under the control of the long terminal repeat of MuLV by a pseudotype infection. Then, the cells were further infected with PERV subtype B (PERV-B) or feline leukemia virus subgroup B (FeLV-B). Culture supernatants of the infected cells were mixed with human serum (HS) and then inoculated to HEK293 cells. The inoculated cells were histochemically stained and lacZ-positive blue foci were counted. Glycosyltransferase activity, xenoantigenicity, and alpha-Gal epitope density in the cells were measured at the time of the infection experiments. PERV-B or FeLV-B particles from the parental PEC were efficiently neutralized by HS, while those from PEC transduced with alpha1,2FT, alpha2,3ST or GnT-III were less sensitive to HS. The transduced PEC exhibited high levels of activity of the introduced glycotransferases, and expressed fewer xenoantigens and cell-surface alpha-Gal epitopes. Our results suggest that gammaretroviruses including PERVs produced by transgenic pigs, that are generally modified to reduce the cell-surface alpha-Gal epitope to overcome the HAR in xenotransplantation, are less sensitive to HS.", "journal": "Xenotransplantation", "doi": "10.1034/j.1399-3089.2003.00056.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "14705430", "author": "Pettersson A", "n_authors": 2, "title": "Prevalence of dental resorptive lesions in Swedish cats.", "abstract": "Ninety-six, randomly selected Swedish cats were evaluated for the presence of dental resorptive lesions. All cats were examined while receiving general anesthesia. Diagnosis was based on oral examination and full-mouth, intraoral dental radiographs. Information concerning age, sex, vaccination status, eating habits, food type, environment (indoor or outdoor housing), oral, discomfort, dental care, and medical treatment was recorded. Hematologic samples included analysis for FeLV, FIV, and calcivirus. Of the cats examined in this study, 32% had gross or radiographic signs of dental resorptive lesions. There was a positive relationship between the occurrence of dental resorptive lesions and increasing age.", "journal": "Journal of veterinary dentistry", "doi": "10.1177/089875640302000301", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "14703086", "author": "de Lorimier LP", "n_authors": 3, "title": "T-cell lymphoma of the tympanic bulla in a feline leukemia virus-negative cat.", "abstract": "This report constitutes the first description of a T-cell lymphoma of the tympanic bulla in a cat. This feline leukemia virus (FeLV)-negative cat originally presented with signs referable to middle ear disease; it deteriorated rapidly after definitive diagnosis. Lymphoma of the middle ear is extremely rare in all species.", "journal": "The Canadian veterinary journal = La revue veterinaire canadienne", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "14664208", "author": "Messick JB", "n_authors": 1, "title": "New perspectives about Hemotrophic mycoplasma (formerly, Haemobartonella and Eperythrozoon species) infections in dogs and cats.", "abstract": "The new perspectives about hemotrophic mycoplasma infections in cats and dogs can be summarized as follows: Haemobartonella and Eperythrozoon species infecting the dog and cat have been reclassified as mycoplasmal parasites and given the names M haemofelis (Ohio or large form of H felis), M haemominutum (California or small form of H felis), and M haemocanis (H canis). The prevalence of hemotrophic mycoplasma infections in anemic cats in the United States is about 25% and usually involves M haemofelis. However, nonanemic cats may also be infected most commonly with M haemominutum. Chronic infections with hemotrophic mycoplasmas may promote myeloproliferative disorders in FeLV-infected cats. M haemocanis infection in dogs may be a widespread latent disease in kennel-raised dogs and is being investigated. The PCR assay is exquisitely sensitive for detection of M haemofelis and M haemominutum, and testing of blood donor cats and perhaps dogs should be done regularly. Fleas are involved in the transmission of M haemofelis to the cat, whereas R sanguines may be involved with transmission of M haemocanis to the dog. Treatment with doxycycline effectively controls acute infection in the cat and dog, and enrofloxacin may also be effective in the cat, but none of the antibiotics tested to date consistently clears the parasites.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": "10.1016/j.cvsm.2003.08.002", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "14664201", "author": "Weiss DJ", "n_authors": 1, "title": "New insights into the physiology and treatment of acquired myelodysplastic syndromes and aplastic pancytopenia.", "abstract": "MDS are a diverse group of primary and secondary bone marrow disorders that are characterized by cytopenias in blood, prominent dysplastic features in blood or bone marrow, and normal or hypercellular bone marrow. MDS in cats are typically associated with FeLV infection. Dogs with MDS-RC and MDS-Er seem to respond to erythropoietin administration and have prolonged survival. Dogs with MDS-EB respond poorly to present treatments, and survival is short. Prognosis and probability of progression to acute myelogenous leukemia can be predicted based on the percentage of myeloblasts in bone marrow. Several experimental therapeutic modalities in human beings have been described that may be useful in treating MDS-EB in dogs and cats. Aplastic pancytopenia is a relatively rare disorder in dogs and cats. Causes include Ehrlichia spp, Parvovirus, and FeLV infections; sepsis; chronic renal failure; drug and toxin exposure; and idiopathic causes. Diagnosis is based on identification of multiple cytopenias in the blood and hypoplastic/aplastic bone marrow, with the marrow space replaced by adipose tissue. Treatment and outcome are dependent on determining the underlying cause of the bone marrow failure.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": "10.1016/s0195-5616(03)00094-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "14664197", "author": "Langston CE", "n_authors": 3, "title": "The use of erythropoietin.", "abstract": "EPO is a hematopoietic growth factor produced in the kidney that stimulates erythropoiesis. It effectively treats hypoproliferative anemia associated with CRF, improving quality of life in these patients. Other uses that are poorly characterized in veterinary medicine include treatment of cancer patients on chemotherapy, hematologic disorders, and anemic FeLV-infected cats as well as preoperative conditioning for elective surgeries that may involve significant blood loss. Careful monitoring of therapy is necessary for optimal results. Several complications are associated with rHuEPO therapy. The production of anti-rHuEPO antibodies is the most significant and can be a life-threatening event. Alternatives to human EPO are being sought to provide beneficial effects while avoiding antibody formation.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": "10.1016/s0195-5616(03)00101-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "14658723", "author": "Troxel MT", "n_authors": 9, "title": "Feline intracranial neoplasia: retrospective review of 160 cases (1985-2001).", "abstract": "The purpose of this study was to determine the frequency of different tumor types within a large cohort of cats with intracranial neoplasia and to attempt to correlate signalment, tumor size and location, and survival time for each tumor. Medical records of 160 cats with confirmed intracranial neoplasia evaluated between 1985 and 2001 were reviewed. Parameters evaluated included age, sex, breed, FeLV/FIV status, clinical signs, duration of signs, number of tumors, tumor location(s), imaging results, treatment, survival times, and histopathologic diagnosis. Most of the cats were older (11.3 +/- 3.8 years). Primary tumors accounted for 70.6% of cases. Metastasis and direct extension of secondary tumors accounted for only 5.6 and 3.8% of cases, respectively. Twelve cats (7.5%) had 2 or more discrete tumors of the same type, whereas 16 cats (10.0%) had 2 different types of intracranial tumors. The most common tumor types were meningioma (n = 93, 58.1%), lymphoma (n = 23, 14.4%), pituitary tumors (n = 14, 8.8%), and gliomas (n = 12, 7.5%). The most common neurological signs were altered consciousness (n = 42, 26.2%), circling (n = 36, 22.5%), and seizures (n = 36, 22.5%). Cats without specific neurological signs were common (n = 34, 21.2%). The tumor was considered an incidental finding in 30 (18.8%) cats. In addition to expected relationships (eg, meninges and meningioma, pituitary and pituitary tumors), we found that lesion location was predictive of tumor type with diffuse cerebral or brainstem involvement predictive of lymphoma and third ventricle involvement predictive of meningioma.", "journal": "Journal of veterinary internal medicine", "doi": "10.1111/j.1939-1676.2003.tb02525.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "14637020", "author": "Harroun TA", "n_authors": 4, "title": "The fusion peptide of simian immunodeficiency virus and the phase behaviour of N-methylated dioleoylphosphatidylethanolamine.", "abstract": "Temperature-scan X-ray scattering was used to study the effect of the fusion peptide of simian immunodeficiency virus (SIV) on the lipid polymorphism of N-methylated dioleoylphosphatidylethanolamine (DOPE-Me), in the presence and absence of one or both of the fusion inhibitors carbobenzoxy-D-phenylalanine-L-phenylalanine-glycine and 1-lauroyl-2-hydroxy-sn-glycero-3-phosphocholine (LPC). Using X-ray diffraction at stations 2.1 and 8.2 of the Synchrotron Radiation Source at Daresbury Laboratory, UK, the structure of multilamellar vesicles (MLVs) was probed as the temperature was raised from 20 to 90 degrees C. The results are compared to those of similar studies, reported earlier, that used the fusion peptide of feline leukaemia virus (FeLV) which, at 28 amino acid residues in length, is considerably longer than the SIV peptide (12 amino acid residues). We interpret the results within the framework of current understanding of membrane fusion, and demonstrate how observed lipid polymorphism might describe the fusion process.", "journal": "Biochimica et biophysica acta", "doi": "10.1016/j.bbamem.2003.09.003", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "14609625", "author": "Winslow BJ", "n_authors": 6, "title": "Replication and expression of a swinepox virus vector delivering feline leukemia virus Gag and Env to cell lines of swine and feline origin.", "abstract": "The host range of swinepox virus (SPV) is restricted to swine, although SPV has been shown to infect mammalian, non-swine cells, without recovery of infectious virus. SPV is a reasonable candidate for development as a non-productively replicating viral vector for use in non-swine, mammalian species, such as the cat. A novel SPV gene deletion (SPV 043) was created and found to be non-attenuating. This deletion was utilized to generate a stable recombinant virus expressing the Gag-Pro and Env proteins of feline leukemia virus (FeLV). Expression and replication of this vector was studied in embryonic swine kidney cells (ESK-4), and two feline cell lines, Crandell feline kidney cells (CRFK) and feline skin fibroblasts (FSF). Our results showed that feline cells were susceptible to infection by SPV and supported expression of foreign genes driven by synthetic poxvirus promoters, however, SPV viral DNA was not replicated in feline cells and infectious virus was not recovered. In addition, FeLV Gag virus-like particles were produced from both ESK-4 and CRFK cells and foreign antigens were incorporated into infectious SPV intracellular mature virions (IMV). These results suggest that SPV may have potential as a safe vaccine delivery vector for cats.", "journal": "Virus research", "doi": "10.1016/j.virusres.2003.08.005", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "14567233", "author": "Ostrowski S", "n_authors": 4, "title": "A serologic survey of wild felids from central west Saudi Arabia.", "abstract": "Forty-five wildcats (Felis silvestris), 17 sand cats (Felis margarita), and 17 feral domestic cats were captured in central west Saudi Arabia, between May 1998 and April 2000, with the aim to assess their exposure to feline immunodeficiency virus/puma lentivirus (FIV/PLV), feline leukaemia virus (FeLV), feline herpesvirus (FHV-1), feline calicivirus (FCV), feline coronavirus (FCoV), and feline panleukopenia virus (FPLV). Serologic prevalence in wildcats, sand cats, and feral domestic cats were respectively: 6%, 0%, 8% for FIV/PLV; 3%, 8%, 0% for FeLV; 5%, 0%, 15% for FHV-1; 25%, 0%, 39% for FCV; 10%, 0%, 0% for FCoV; and 5%, 0%, 8% for FPLV. We recorded the first case of FeLV antigenemia in a wild sand cat. Positive results to FIV/PLV in wildcats and feral cats confirmed the occurrence of a feline lentivirus in the sampled population.", "journal": "Journal of wildlife diseases", "doi": "10.7589/0090-3558-39.3.696", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "14567232", "author": "Marker L", "n_authors": 4, "title": "Multicentric T-cell lymphoma associated with feline leukemia virus infection in a captive namibian cheetah (Acinonyx jubatus).", "abstract": "This case report describes a multicentric lymphoma in a 4 yr old female wildborn captive cheetah (Acinonyx jubatus) in Namibia after being housed in an enclosure adjacent to a feline leukemia virus (FeLV) infected cheetah that had previously been in contact with domestic cats. The year prior to the onset of clinical signs, the wild-born cheetah was FeLV antigen negative. The cheetah subsequently developed lymphoma, was found to be infected with FeLV, and then rapidly deteriorated and died. At necropsy, the liver, spleen, lymph nodes, and multiple other organs were extensively infiltrated with neoplastic T-lymphocytes. Feline leukemia virus DNA was identified in neoplastic lymphocytes from multiple organs by polymerase chain reaction and Southern blot analysis. Although the outcome of infection in this cheetah resembles that of FeLV infections in domestic cats, the transmission across an enclosure fence was unusual and may indicate a heightened susceptibility to infection in cheetahs. Caution should be exercised in holding and translocating cheetahs where contact could be made with FeLV-infected domestic, feral, or wild felids.", "journal": "Journal of wildlife diseases", "doi": "10.7589/0090-3558-39.3.690", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "14557874", "author": "Vobis M", "n_authors": 4, "title": "Evidence of horizontal transmission of feline leukemia virus by the cat flea ( Ctenocephalides felis).", "abstract": "The feline leukemia virus (FeLV) is a naturally occurring and widespread retrovirus among domestic cats. The virus is mainly transmitted horizontally through saliva, blood and other body fluids by close contact between cats. Vectors other than cats, e.g. blood-sucking parasites, have not been reported. This study tested the vector potential of the cat flea ( Ctenocephalides felis) for FeLV. In a first feeding, fleas were fed for 24 h with blood from a FeLV-infected cat with persistent viremia. FeLV could be detected in the fleas, as well as in their feces. Fleas were then divided in two populations and fed in a second feeding for 5 h or 24 h with non-infected non-viremic blood. FeLV was again detected in the fleas and their feces. In addition, the two resulting blood samples of the second feeding were subsequently tested for FeLV and both samples were positive for FeLV RNA. The cat flea transmitted the FeLV from one blood sample to another. In a third feeding, the same populations of fleas were fed again with non-infected blood for 5 h or 24 h. This time FeLV was not detected in the fleas, or in the feces or blood samples. Results show that cat fleas are potential vectors for FeLV RNA in vitro and probably also in vivo.", "journal": "Parasitology research", "doi": "10.1007/s00436-003-0949-8", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "14552162", "author": "Richter KP", "n_authors": 1, "title": "Feline gastrointestinal lymphoma.", "abstract": "Gastrointestinal lymphoma is a common cause of anorexia and weight loss in older cats, with or without vomiting or diarrhea. Most cats are feline leukemia virus-negative and feline immunodeficiency virus-negative. Low-grade gastrointestinal lymphoma may be more common than previously thought, and these cats respond better to chemotherapy agents than cats with high-grade lymphoma. The most significant prognostic indicator is initial response to chemotherapy, with cats that survive the initial induction period generally achieving long-term remission. Thus far, investigations into molecular markers and immunophenotyping have failed to identify useful prognostic indicators.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": "10.1016/s0195-5616(03)00054-8", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "14535446", "author": "Riondato F", "n_authors": 5, "title": "Effects of interferon alpha (INF-alpha) therapy on peripheral blood lymphocyte subsets from FIV and FeLV naturally infected cats.", "abstract": null, "journal": "Veterinary research communications", "doi": "10.1023/b:verc.0000014196.13712.69", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "14510328", "author": "Schubach TM", "n_authors": 9, "title": "Haematogenous spread of Sporothrix schenckii in cats with naturally acquired sporotrichosis.", "abstract": "The recovery of Sporothrix schenckii from blood samples is rare, and the diagnosis of systemic sporotrichosis is usually made at necropsy. In this report, S schenckii was isolated from two or more internal organs of nine necropsied cats with naturally acquired sporotrichosis. Haematogenous spread was demonstrated in vivo by the isolation of S schenckii from the peripheral blood of 17 (n = 49, 34.4 per cent) cats. Feline leukaemia virus (FeLV) was not detected, and co-infection with feline immunodeficiency virus (FIV), observed in nine cases (n = 43, 20.9 per cent), apparently did not affect the isolation of S schenckii from peripheral blood or from the internal organs.", "journal": "The Journal of small animal practice", "doi": "10.1111/j.1748-5827.2003.tb00174.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "12969548", "author": "Graham EM", "n_authors": 3, "title": "Development of antibodies to feline IFN-gamma as tools to elucidate the cellular immune responses to FeLV.", "abstract": "An understanding of the nature of immune protection and the role of immune effector products such as interferon-gamma (IFN-gamma) in the control of infectious disease is fundamental to the rational design of effective vaccines and immunotherapeutic reagents. Murine monoclonal and sheep polyclonal antibodies (mAbs and pAbs) to feline IFN-gamma (fIFN-gamma) were generated firstly to facilitate further research into the role of cellular immune responses in the control of feline infectious disease, and secondly to enable evaluation of the efficacy of novel immunotherapeutic approaches. A hybridoma clone, D9, secreting IgG1 antibodies was selected for expansion and the mAbs affinity purified in vitro. Polyclonal antibodies were raised in a sheep against recombinant fIFN-gamma and affinity purified. The sensitivity of the D9 mAb and the sheep anti-fIFN-gamma pAb was determined using an indirect fIFN-gamma enzyme-linked immunosorbent assay (ELISA) and immunoblots. These antibodies were assessed for their ability to detect the production of fIFN-gamma by specific feline T cell populations ex vivo following coculture with mitogen or feline leukaemia virus (FeLV) antigens for 4 h in the presence of the protein secretion inhibitor brefeldin A (BFA). Production of fIFN-gamma was evaluated using flow cytometry to simultaneously detect PE-labelled surface molecules and fluorescein isothiocyanate (FITC)-labelled intracellular fIFN-gamma. Using this approach, our initial studies revealed an upregulation in virus-specific fIFN-gamma-secreting CD4(+)T cells in the lymph nodes of FeLV latently infected cats.", "journal": "Journal of immunological methods", "doi": "10.1016/s0022-1759(03)00244-8", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "12941386", "author": "Nakata R", "n_authors": 6, "title": "Reevaluation of host ranges of feline leukemia virus subgroups.", "abstract": "We reevaluated the host ranges of feline leukemia virus (FeLV) subgroups A, B and C using pseudotype assays based on recombinant NB-tropic murine leukemia virus, which is not usually blocked after viral entry in mammalian cells. Pseudotype viruses of FeLV-B and -C infected a variety of cell lines from many mammalian species. Unexpectedly, FeLV-A pseudotype viruses of two independent isolates from the UK and US also infected a variety of non-feline cell lines including cells from humans, rabbits, pigs and minks. Moreover, both isolates of FeLV-A productively infected human embryonic kidney 293 and mink Mv-1-Lu cells. We conclude that FeLV-A is not strictly ecotropic.", "journal": "Microbes and infection", "doi": "10.1016/s1286-4579(03)00180-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "12934796", "author": "Poulet H", "n_authors": 9, "title": "Efficacy of a canarypox virus-vectored vaccine against feline leukaemia.", "abstract": "Canarypox virus recombinant vaccines have a unique efficacy and safety profile for the vaccinated host because the canarypox virus is non-replicative in mammalian hosts. After the vaccination of a mammalian species, recombinant canarypox viruses express the inserted genes but cannot multiply in the host. They stimulate a strong immune response in the absence of any virus amplification in the host or any viral spread into the environment. A new canarypox-based recombinant vaccine is the canarypox-feline leukaemia virus (FeLV) vaccine (EURIFEL FeLV; Merial) that expresses the FeLV env and gag protective genes. This paper describes experiments which demonstrate that it is effective against any oronasal FeLV challenge. The protection was shown to be solid against an oronasal challenge one year after the initial vaccination, and was effective against a very severe 'in-contact' challenge. Furthermore, the canarypox virus-FeLV vaccine was effective without an adjuvant.", "journal": "The Veterinary record", "doi": "10.1136/vr.153.5.141", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "12928879", "author": "Vobis M", "n_authors": 4, "title": "The feline leukemia virus (FeLV) and the cat flea (Ctenocephalides felis).", "abstract": null, "journal": "Parasitology research", "doi": "10.1007/s00436-003-0915-5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "12910743", "author": "Sykes JE", "n_authors": 1, "title": "Feline hemotropic mycoplasmosis (feline hemobartonellosis).", "abstract": "Hemotropic mycoplasmas represent an important cause of anemia in cats worldwide. Previously known as Haemobartonella species, sequencing of the 16S rRNA genes of these organisms has led to their reclassification as mycoplasmas. Two species have been identified in cats, M haemofelis and \"Candidatus M haemominutum.\" The latter organism alone has not been associated with disease in naturally infected cats but may cause anemia in FeLV-infected cats and accelerate development of FeLV-induced myeloproliferative disease. The mode of transmission of these organisms remains enigmatic. Nevertheless, development of sensitive DNA-based tests for these unculturable organisms has improved the understanding of the epidemiology and pathogenesis of FHM. Cats with clinical signs and laboratory abnormalities consistent with FHM should be treated with doxycycline; enrofloxacin may represent an effective alternative. Transfusion with packed red blood cells after cross-matching may be required for severely anemia cats, and addition of prednisone may be required if the diagnosis of FHM is uncertain, or response to antimicrobials alone is insufficient. Affected cats should be tested for FeLV, the most common concurrent infection in cats with FHM.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": "10.1016/s0195-5616(03)00027-5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "12875824", "author": "Fromont E", "n_authors": 3, "title": "Disease propagation in connected host populations with density-dependent dynamics: the case of the Feline Leukemia Virus.", "abstract": "Spatial heterogeneity is a strong determinant of host-parasite relationships, however local-scale mechanisms are often not elucidated. Generally speaking, in many circumstances dispersal is expected to increase disease persistence. We consider the case when host populations show density-dependent dynamics and are connected through the dispersal of individuals. Taking the domestic cats (Felis catus)--Feline Leukemia Virus (FeLV) as a toy model of host-microparasite system, we predict the disease dynamics when two host populations with distinct or similar structures are connected together and to the surrounding environment by dispersal. Our model brings qualitatively different predictions from one-population models. First, as expected, biologically realistic rates of dispersal may allow FeLV to persist in sets of populations where the virus would have gone extinct otherwise, but a reverse outcome is also possible: eradication of FeLV from a small population by connexion to a larger population where it is not persistent. Second, overall prevalence as well as depression of host population size due to infection are both enhanced by dispersal, even at low dispersal rates when disease persistence is not achieved in the two populations. This unexpected prediction is probably due to the combination of dispersal with density-dependent population dynamics. Third, the dispersal of non-infectious cats has more influence on virus prevalence than the dispersal of infectious. Finally, prevalence and depression of host population size are both related to the rate of dispersion, to the health status of individuals dispersing and to the dynamics of host populations.", "journal": "Journal of theoretical biology", "doi": "10.1016/s0022-5193(03)00122-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "12831069", "author": "Ettinger SN", "n_authors": 1, "title": "Principles of treatment for feline lymphoma.", "abstract": "Lymphoma is the most commonly diagnosed neoplasm in cats. As feline leukemia virus antigenemia has decreased over the past 15 years, there has been a profound shift in the presence, signalment, and frequency of sites of feline lymphoma in North America. There is variation in anatomic classification systems, but most studies have divided lymphoma into four groups: alimentary, mediastinal, multicentric, or extranodal. Clinical signs and common differential diagnoses for each of the forms are described. Staging allows for evaluation of the extent of disease. As in the dog, lymphoma is a systemic disease in the cat, and chemotherapy is the treatment of choice for most forms. Exceptions are described. In contrast to canine lymphoma, feline lymphoma is generally more challenging and frustrating to treat than canine lymphoma. Response rates are lower, and remission duration is shorter. Fortunately, cats treated with chemotherapy tend to have less toxicity than dogs. Positive prognostic factors are feline leukemia virus-negative, clinically well at time of diagnosis, and response to therapy. Achieving a complete remission is prognostic for survival. Unfortunately, response cannot be predicted before treatment.", "journal": "Clinical techniques in small animal practice", "doi": "10.1053/svms.2003.36623", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "12816966", "author": "Fujino Y", "n_authors": 6, "title": "Detection of the integrated feline leukemia viruses in a cat lymphoid tumor cell line by fluorescence in situ hybridization.", "abstract": "Feline leukemia virus (FeLV) is a type-C retrovirus associated with lymphoid and hematopoietic malignancies in cats. The FeLV-induced tumors are thought to be caused, at least in part, by somatically acquired insertional mutagenesis in which the integrated provirus may activate a proto-oncogene or disrupt a tumor suppressor gene. This study was undertaken to enumerate and map the acquired proviral insertions in the genome of a feline thymic lymphoma cell line (FT-1) infected with FeLV. Fluorescence in situ hybridization (FISH) combined with tyramide signal amplification was applied on the chromosome specimen of FT-1 cells and normal cat lymphocytes, with an entire FeLV-A genome used as a probe. Specific hybridization signals were detected from only the metaphases of the FT-1 cells, not from those of normal cat lymphocytes. Statistically based on the Poisson's distribution, at least six loci of chromosomal regions, A2p23-p22, B2p15-p14, B4p15-p14, D4q23-q24, E1p14-p13, and E2p13-p12, appeared to be positive for FeLV integration. Consistently, Southern blot hybridization analysis using an FeLV LTR-U3 probe specific for exogenous FeLV showed the integration of at least six FeLV proviral genomes in FT-1 cells. The cytogenetic technique employed here will provide valuable molecular tags to reveal unidentified tumor-associated genes in FeLV-associated tumor cells.", "journal": "The Journal of heredity", "doi": "10.1093/jhered/esg054", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "12758176", "author": "Abujamra AL", "n_authors": 3, "title": "Mutations that abrogate transactivational activity of the feline leukemia virus long terminal repeat do not affect virus replication.", "abstract": "The U3 region of the LTR of oncogenic Moloney murine leukemia virus (Mo-MuLV) and feline leukemia viruses (FeLV) have been previously reported to activate expression of specific cellular genes in trans, such as MHC class I, collagenase IV, and MCP-1, in an integration-independent manner. It has been suggested that transactivation of these specific cellular genes by leukemia virus U3-LTR may contribute to the multistage process of leukemogenesis. The U3-LTR region, necessary for gene transactivational activity, also contains multiple transcription factor-binding sites that are essential for normal virus replication. To dissect the promoter activity and the gene transactivational activity of the U3-LTR, we conducted mutational analysis of the U3-LTR region of FeLV-A molecular clone 61E. We identified minimal nucleotide substitution mutants on the U3 LTR that did not disturb transcription factor-binding sites but abrogated its ability to transactivate the collagenase gene promoter. To determine if these mutations actually have altered any uncharacterized important transcription factor-binding site, we introduced these U3-LTR mutations into the full-length infectious molecular clone 61E. We demonstrate that the mutant virus was replication competent but could not transactivate cellular gene expression. These results thus suggest that the gene transactivational activity is a distinct property of the LTR and possibly not related to its promoter activity. The cellular gene transactivational activity-deficient mutant FeLV generated in this study may also serve as a valuable reagent for testing the biological significance of LTR-mediated cellular gene activation in the tumorigenesis caused by leukemia viruses.", "journal": "Virology", "doi": "10.1016/s0042-6822(03)00069-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "12724564", "author": "Majzoub M", "n_authors": 6, "title": "Histopathologic and immunophenotypic characterization of extramedullary plasmacytomas in nine cats.", "abstract": "To contribute to the existing body of knowledge in the literature on the apparently rare extramedullary plasmacytoma in cats, lymphoid tumors with plasmacytic cellular morphology taken from nine cats were examined. The paraffin-embedded material was investigated by standard hematoxylin and eosin, and special staining techniques (Giemsa, Congo-red, and periodic acid-Schiff reaction). The tumors also were examined immunohistochemically for the presence of immunoglobulin G, immunoglobulin A, immunoglobulin M, immunoglobulin light chains (lambda, kappa), various amyloid proteins, and FeLV-antigen (p27 protein). An immunoglobulin-producing tumor of plasmacellular origin (extramedullary plasmacytoma [EMP]) could be diagnosed in all cases on the basis of immunohistochemical light-chain expression. All but one of the neoplasms occurred in the skin of older, predominantly male cats. As in humans and dogs, the following types could be identified according to their morphologic features: mature type (two), cleaved type (two), asynchronous type (four), and polymorphous type (one). The tumor tissue of three cats revealed amyloid deposits, which were immunohistochemically diagnosed as ALlambda-amyloid in all three cases.", "journal": "Veterinary pathology", "doi": "10.1354/vp.40-3-249", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "12723802", "author": "Filoni C", "n_authors": 4, "title": "Serosurvey for feline leukemia virus and lentiviruses in captive small neotropic felids in São Paulo state, Brazil.", "abstract": "Feline leukemia virus (FeLV), Gammaretrovirus, and feline immunodeficiency virus, a Lentivirus, are members of the family Retroviridae, and may establish persistent infections in the domestic cat (Felis catus). Cytoproliferative and cytosuppressive disorders may result from infection with these viruses. Morbidity and mortality rates are high in domestic cats worldwide. Infection of endangered neotropic small felids with these viruses could be devastating. To investigate the prevalence of FeLV and feline lentiviruses in neotropic small felids kept in captivity in São Paulo state. Brazil, serum samples from 104 animals belonging to the species Leopardus pardalis, Leopardus tigrinus, Leopardus wiedii, Herpailurus yaguarondi, and Oncifelis geoffroyi were tested for FeLV and feline lentiviruses by commercially available immunoassays. All results were negative, suggesting that retrovirus infection is not an important clinical problem in these populations. Because domestic cats in São Paulo city are naturally infected with these pathogens, and feral cats are commonly found in zoologic facilities in Brazil, preventive measures should be taken to avoid transmission of retroviruses to naive populations of wild and captive neotropic felids in Brazil.", "journal": "Journal of zoo and wildlife medicine : official publication of the American Association of Zoo Veterinarians", "doi": "10.1638/1042-7260(2003)34[0065:SFFLVA]2.0.CO;2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "12713893", "author": "Criado-Fornelio A", "n_authors": 4, "title": "Presence of Mycoplasma haemofelis, Mycoplasma haemominutum and piroplasmids in cats from southern Europe: a molecular study.", "abstract": "Clinical symptoms produced by Mycoplasma spp. and piroplasmids in cats are sometimes similar. Diagnosis of these pathogens is difficult by microscopic procedures and molecular methods have been used as an alternative. We present in this work, the development of new molecular procedures for diagnosis of the aforementioned organisms, together with a molecular characterization of isolates found in southern European cats.A single PCR-RFLP procedure was designed for diagnosis of Mycoplasma spp. and a seminested PCR-RFLP was designed for diagnosis of piroplasmids. The 16S or 18S rRNA genes of isolates found in clinical samples were partially sequenced in all positive cases. Mycoplasma spp. was detected in 9 (30%) out of 30 symptomatic cats from Spain. Sequencing indicated that 66.6% of these isolates can be ascribed to Mycoplasma haemofelis and only 33.3% to Mycoplasma haemominutum. Partial 16S rRNA sequences obtained in Spanish isolates were very similar to those previously published from the UK and the USA. The presence of piroplasmids (Babesia and Theileria spp.) was studied in 16 cats from Spain (n=13) and Portugal (n=3). Animals analyzed were 10 cats with immunosuppressive viral infection (either FeLV or FIV), 5 asymptomatic cats and 1 cat with Babesia-compatible symptoms. Asymptomatic cats were all PCR-negative. Partial sequencing of 18S rRNA gene demonstrated that the Babesia-symptomatic cat was infected with Babesia canis canis whereas 3 (30%) out of the 10 cats with immunosuppressive viral infection were coinfected with piroplasmids (1 with B. canis canis, 1 with Theileria annae, and 1 with B. canis canis and T. annae both).", "journal": "Veterinary microbiology", "doi": "10.1016/s0378-1135(03)00044-0", "deposited_data": "Sim", "nuccore_ids": "30231202, 30231200, 30231199, 30231191", "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "12688127", "author": "Tarello W", "n_authors": 1, "title": "Immunological anomalies and thrombocytopenia in 117 dogs and cats diagnosed with chronic fatigue syndrome (CFS).", "abstract": "Retrospective analysis of immune dysfunctions found in 55 dogs and 62 cats diagnosed with Chronic Fatigue Syndrome (CFS), revealed leukopenia in 11% of dogs (n = 6) and 22.5% of cats (n = 14), lymphopenia in 14.5% of dogs (n = 8) and 10% of cats (n = 6), hypogammaglobulinaemia in 9% of dogs (n = 5) and 13% of cats (n = 8) and thrombocytopenia in 20% of dogs (n = 11) and 68% of cats (n = 42). All patients had creatine kinase enzyme levels above the normal range (CK = 5-100 IU/L) and carried micrococcus-like organisms on erythrocytes. Blood cultures proved positive for Staphylococcus spp. in 16 cases. After low-dosage arsenic-based therapy (thiacetarsamide sodium) all animals experienced complete clinical remission. Subsequent controls demonstrated immune restoration in 4 representative FIV-FeLV negative cats, previously diagnosed with CFS associated with leukopenia, lymphopenia, hypogammaglobulinaemia and thrombocytopenia. The main conclusion is that a CFS-like disease in dogs and cats, characterised by the common hallmarks of high CK levels, absence of known causes of chronic fatigue in animals and presence of micrococcus-like organisms in the blood, can be associated with humoral and/or cellular immune deficiencies in 9-22.5% of cases and with thrombocytopenia in 20-68% of cases. Considerations are made on the possible role of micrococci in the aetiology of the condition and on the similarities with CFS in humans.", "journal": "Acta veterinaria Hungarica", "doi": "10.1556/AVet.51.2003.1.6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "12680718", "author": "Maruyama S", "n_authors": 8, "title": "Seroprevalence of Bartonella henselae, Toxoplasma gondii, FIV and FeLV infections in domestic cats in Japan.", "abstract": "Seroprevalence of Bartonella henselae, Toxoplasma gondii, feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) infections was investigated in 1,447 domestic cats derived from the north (Hokkaido) to the south (Okinawa) prefectures in Japan. Of the cats investigated, 8.8% (128/1,447) were seropositive to B. henselae, 5.4% (78/1,447) to T. gondii, 9.8% (107/1,088) to FIV, and 2.9% (32/1,088) to FeLV, respectively. For B. henselae infection, the positive rate varied from 11.5% in cats of 1 to <2 years old to 7.2% in those over 3 years old. Outdoor cats showed higher positive rate (14.5%) than that (7.0%) in indoor ones. The rate (13.5%) in flea-infested cats was significantly higher than that (7.4%) in flea-negative cats. The positive rates in southern and urban sites were more likely to be higher than those in northern and suburban sites, suggesting that warm and humid environments, density of cat population, and raising status, including hygienic condition and flea infestation in cats may correlate to higher seroprevalence of B. henselae infection. For T. gondii, FIV and FeLV infections, the seroprevalence also tended to be higher in outdoor, flea-infested cats and advanced age groups. For FIV infection, the positive rates in male (14.3%) and outdoor cats (15.0%) were significantly higher than those in female (5.0%) and indoor cats (4.6%). On the other hand, no significant difference in seropositivities was observed in FeLV and T. gondii infections concerning to both genders and raising status.", "journal": "Microbiology and immunology", "doi": "10.1111/j.1348-0421.2003.tb02798.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "12673127", "author": "Pan J", "n_authors": 4, "title": "A potential therapeutic strategy to combat leukemia virus infection.", "abstract": "To test the concept that a replication-competent retrovirus carrying a suicide gene could have potential utility in the control of the natural virus infection in mammalian species, we constructed derivatives of a feline leukemia virus (FeLV) that is commonly associated with leukemia-lymphomas in this species. The FeLV, Rickard strain, subgroup A (FRA) genome contained at the 3' end of the envgene, an insert of an internal ribosomal entry site (IRES) linked to cDNA sequence of either herpes simplex virus thymidine kinase (HSV-TK) or a truncated HSV-TK (HSV-ATK) or yeast cytosine deaminase (CD). These constructs were transfected into feline fibroblast cells (H927). The viruses produced were determined to be replication-competent. The stable propagation of the full-length transgene was, however, dependent on the size of the insert, IRES-CD being the smallest in size (1031 bp) exhibiting maximal stability for at least up to six months. The protein products of the transgenes could be detected, despite the appearance of deleted proviruses at late passages. The transduced cells were susceptible to cytotoxic killing when the appropriate prodrug, ganciclovir (GCV), acyclovir (ACV) or 5-fluorocytosine (5-FC) was added to the culture medium. H927 cells, infected with another subgroup of FeLV, namely, FeLV-B or FeLV-C, could be superinfected by the FRA-suicide gene viruses and thus, subjected to killing. Interestingly, at an early stage of infection by the parental FRA, H927 cells could also be reinfected by the same subgroup FRA constructs to induce the suicide effect. Among the three constructs, the vector with the CD gene was determined to be superior to others in terms of stability, therapeutic index and bystander effect in the cell culture test system. While the in vivo correlates of the therapeutic effect in the feline model remain to be determined, our results do encourage investigation of the same concept in the control of HTLV and, perhaps even, HIV infection in humans.", "journal": "Cancer biology & therapy", "doi": "10.4161/cbt.236", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "12670435", "author": "Sparkes AH", "n_authors": 1, "title": "Feline leukaemia virus and vaccination.", "abstract": null, "journal": "Journal of feline medicine and surgery", "doi": "10.1016/S1098-612X(02)00132-8", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "12571312", "author": "Swenson CL", "n_authors": 2, "title": "Demineralization for inactivation of infectious retrovirus in systemically infected cortical bone: in vitro and in vivo experimental studies.", "abstract": "Clinical and experimental studies have demonstrated viral transmission through the transplantation of fresh-frozen infected bone. While sterilization methods sufficient to inactivate the human immunodeficiency virus (HIV) have been shown to markedly alter osteoconductive and osteoinductive properties of bone allografts, the ability of a process for creating demineralized bone matrix to abrogate transmission of a retrovirus has not been investigated, to our knowledge. We hypothesized that a clinically accepted demineralization procedure would alter the nucleic acids of the feline leukemia virus (FeLV, a retrovirus with a structure and replication cycle similar to those of HIV), inactivating the virus in infected bone and rendering it noninfectious. Bone infected with FeLV was demineralized with a method employed for creating demineralized bone matrix powder. The effects of demineralization on cellular and (pro)viral nucleic acids were examined with use of gel electrophoresis and quantitative polymerase chain reaction, respectively. To compare the infectivity of the demineralized bone matrix with that of mineralized bone particles in cell cultures and in animals in which they had been implanted, we measured FeLV p27 antigen and (pro)viral nucleic acids as well as antiviral antibodies. Demineralization of FeLV-infected bone appeared to inactivate the virus by degradation and fragmentation of the DNA, rendering it noninfectious in both in vitro and in vivo test systems. In contrast, untreated mineralized FeLV-infected bone contained intact nucleic acids and readily transmitted the virus in both test systems. The demineralization process inactivated infectious retrovirus in infected cortical bone, thereby preventing disease transmission.", "journal": "The Journal of bone and joint surgery. American volume", "doi": "10.2106/00004623-200302000-00021", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "12552012", "author": "Barnett AL", "n_authors": 5, "title": "Structure and mechanism of a coreceptor for infection by a pathogenic feline retrovirus.", "abstract": "Infection of T lymphocytes by the cytopathic retrovirus feline leukemia virus subgroup T (FeLV-T) requires FeLIX, a cellular coreceptor that is encoded by an endogenous provirus and closely resembles the receptor-binding domain (RBD) of feline leukemia virus subgroup B (FeLV-B). We determined the structure of FeLV-B RBD, which has FeLIX activity, to a 2.5-A resolution by X-ray crystallography. The structure of the receptor-specific subdomain of this glycoprotein differs dramatically from that of Friend murine leukemia virus (Fr-MLV), which binds a different cell surface receptor. Remarkably, we find that Fr-MLV RBD also activates FeLV-T infection of cells expressing the Fr-MLV receptor and that FeLV-B RBD is a competitive inhibitor of infection under these conditions. These studies suggest that FeLV-T infection relies on the following property of mammalian leukemia virus RBDs: the ability to couple interaction with one of a variety of receptors to the activation of a conserved membrane fusion mechanism. A comparison of the FeLV-B and Fr-MLV RBD structures illustrates how receptor-specific regions are linked to conserved elements critical for postbinding events in virus entry.", "journal": "Journal of virology", "doi": "10.1128/jvi.77.4.2717-2729.2003", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "32214964", "author": "Paltrinieri S", "n_authors": 6, "title": "Expression patterns in feline blood and tissues of α(1)-acid glycoprotein (AGP) and of an AGP-related protein (AGPrP).", "abstract": "α", "journal": "Comparative clinical pathology", "doi": "10.1007/s00580-003-0489-8", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "12502821", "author": "Hanlon L", "n_authors": 9, "title": "Long-range effects of retroviral insertion on c-myb: overexpression may be obscured by silencing during tumor growth in vitro.", "abstract": "The c-myb oncogene is a frequent target for retroviral activation in hemopoietic tumors of avian and mammalian species. While insertions can target the gene directly, numerous clusters of retroviral insertion sites have been identified which map close to c-myb and outside the transcription unit in T-lymphomas (Ahi-1, fit-1, and Mis-2) and monocytic and myeloid leukemias (Mml1, Mml2, Mml3, and Epi-1). Previous analyses showed no consistent effect of these insertions on c-myb expression, raising the possibility that other nearby genes were the true targets. In contrast, our analysis of four cell lines established from lymphomas bearing insertions at fit-1 (fti-1) (feline leukemia virus) and Ahi-1 (Moloney murine leukemia virus) shows that these display higher expression levels of c-myb RNA and protein compared to a panel of phenotypically similar cell lines lacking such insertions. An interesting feature of the cell lines with long-range c-myb insertions was that each also carried an activated Myc allele. The potential for oncogenic synergy between Myb and Myc in T-cell lymphoma was confirmed in transgenic mice overexpressing alleles of both genes in the T-cell compartment, lending further credence to the case for c-myb as the major target for long-range activation. In contrast, mapping and analysis of c-myb neighboring genes (HBS1 and FLJ20069) showed that the expression of these genes did not correlate well with the presence of proviral insertions. A possible explanation for the paradoxical behavior of c-myb was provided by one of the murine T-lymphoma lines bearing an insertion at Ahi-1 (p/m16i) that reproducibly down-regulated c-myb RNA and protein to very low levels or undetectable levels on prolonged culture. Our observations implicate c-myb as a key target of upstream and downstream retroviral insertions. However, overexpression may become dispensable during outgrowth in vitro, and perhaps during tumor progression in vivo, providing a potential rationale for the previously observed discordance between retroviral insertion and c-myb expression levels.", "journal": "Journal of virology", "doi": "10.1128/jvi.77.2.1059-1068.2003", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15984349", "author": "Andersen PR", "n_authors": 2, "title": "Feline immunodeficiency virus diagnosis after vaccination.", "abstract": "Prior to the widespread use of vaccination for the control of feline immunodeficiency virus (FIV) infection, diagnosis was made by the detection of antibodies against FIV. A number of commercial animal side tests perform quite well for this determination, with positive predictive values between 91 and 100% and negative predictive values between 96 and 100%. Furthermore, results of these tests could be confirmed by western blot analysis of FIV test-positive sera. Currently, a killed whole virus FIV vaccine has been made available to practitioners. Vaccinated cats seroconvert by ELISA and western blot, making presently available diagnostic tests, which rely on antibody detection, useless in cats after vaccination. The advisory panels of the American Association of Feline Practitioners and Academy of Feline Medicine both recommend testing for feline leukemia virus antigen and FIV antibody before vaccination.", "journal": "Animal health research reviews", "doi": "10.1079/ahr200493", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15719325", "author": "Grosenbaugh DA", "n_authors": 5, "title": "Comparison of the safety and efficacy of a recombinant feline leukemia virus (FeLV) vaccine delivered transdermally and an inactivated FeLV vaccine delivered subcutaneously.", "abstract": "The efficacy of a new recombinant FeLV vaccine (rFeLV), delivered transdermally via a needle-free delivery device was compared to that of an inactivated FeLV vaccine (FeLV-k), administered subcutaneously, with a conventional needle and syringe. Kittens were immunized with either rFeLV (0.25 ml, transdermal) or FeLV-k (1 ml, subcutaneous); or they were sham-vaccinated with physiologic saline (0.25 ml, transdermal). Two vaccinations were administered 21 days apart. Injection sites were monitored for any acute or subacute reactions relative to vaccine administration. Four weeks following the final vaccination, all cats were subject to oro-nasal FeLV challenge. Blood was collected for determination of FeLV antigenemia (p27) at weekly intervals beginning three weeks post-challenge. All of the vaccinated cats from both groups resisted FeLV challenge; and 90% of the control cats developed persistent FeLV antigenemia in response to challenge. No acute or persistent injection site reactions were observed. The rFeLV, delivered transdermally, provides protection against persistent FeLV antigenemia following a robust challenge that is equivalent to that of FeLV-k.", "journal": "Veterinary therapeutics : research in applied veterinary medicine", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15644613", "author": "Endo Y", "n_authors": 7, "title": "Prevalence of canine distemper virus, feline immunodeficiency virus and feline leukemia virus in captive African lions (Panthera leo) in Japan.", "abstract": "Sero-prevalences of canine distemper virus (CDV), feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) were evaluated in 20 captive lions in two Japanese zoos. Anti-CDV antibody was detected in 13 of 20 lions. We could pursue antibody responses against CDV in three lions back to 1996. Sera collected in 1996 were negative for anti-CDV antibody, therefore, all of them showed sero-conversion in 2000. This result suggested that the epidemic of CDV infection in this zoo might have happened between 1996 and 2000. The lions were also examined for FIV and FeLV infections. We had no evidence for FeLV infection but eight lions were sero-positive for anti-FIV antibody.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.66.1587", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15626222", "author": "Lester SJ", "n_authors": 6, "title": "Clinicopathologic features of an unusual outbreak of cryptococcosis in dogs, cats, ferrets, and a bird: 38 cases (January to July 2003).", "abstract": "To determine clinical and pathologic findings associated with an outbreak of cryptococcosis in an unusual geographic location (British Columbia, Canada). Retrospective study. 1 pink-fronted cockatoo, 2 ferrets, 20 cats, and 15 dogs. A presumptive diagnosis of cryptococcosis was made on the basis of serologic, histopathologic, or cytologic findings, and a definitive diagnosis was made on the basis of culture or immunohistochemical staining. No breed or sex predilections were detected in affected dogs or cats. Eleven cats had neurologic signs, 7 had skin lesions, and 5 had respiratory tract signs. None of 17 cats tested serologically for FeLV yielded positive results; 1 of 17 cats yielded positive results for FIV (western blot). Nine of 15 dogs had neurologic signs, 2 had periorbital swellings, and only 3 had respiratory tract signs initially. Microbiologic culture in 15 cases yielded 2 isolates of Cryptococcus neoformans var grubii (serotype A) and 13 isolates of C. neoformans var gattii (serotype B); all organisms were susceptible to amphotericin B and ketoconazole. Serologic testing had sensitivity of 92% and specificity of 98%. Serologic titers were beneficial in identifying infection in animals with nonspecific signs, but routine serum biochemical or hematologic parameters were of little value in diagnosis. Most animals had nonspecific CNS signs and represented a diagnostic challenge. Animals that travel to or live in this region and have nonspecific malaise or unusual neurologic signs should be evaluated for cryptococcosis.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.2004.225.1716", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15604490", "author": "Penzhorn BL", "n_authors": 3, "title": "Feline babesiosis in South Africa: a review.", "abstract": "Babesia felis, originally identified in wild cats in the Sudan, was subsequently found to cause clinical disease in domestic cats. Although babesiosis in domestic cats has been reported sporadically from various countries, as a significant disease it appears to be a distinctly South African phenomenon. Apart from an inland focus, feline babesiosis is reported regularly only from coastal regions. The infection is assumed to be tick-borne, but the vector has not been identified. Feline babesiosis tends to be an afebrile, chronic, low-grade disease. The most frequently reported complaints by owners are anorexia and lethargy. The main clinical findings are anemia, depression, and occasionally icterus. Concurrent infections (e.g., Mycoplasma haemofelis, FeLV, FIV) may contribute to the clinical picture. Laboratory findings commonly include regenerative anemia, elevation of alanine transaminase (but not alkaline phosphatase) and total bilirubin concentrations, and a variety of electrolyte disturbances. Secondary immune-mediated hemolytic anemia can be seen occasionally. Drugs effective against other Babesia species give variable and questionable results. The drug of choice is primaquine phosphate, which effects a clinical cure but does not sterilize the infection. Repeated or chronic therapy may be required.", "journal": "Annals of the New York Academy of Sciences", "doi": "10.1196/annals.1307.027", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15552647", "author": "O'Brien CR", "n_authors": 5, "title": "Retrospective study of feline and canine cryptococcosis in Australia from 1981 to 2001: 195 cases.", "abstract": "A retrospective study of 155 cats and 40 dogs diagnosed with cryptococcosis between 1981 and 2001 was undertaken. Age, sex, breed, clinical findings, feline immunodeficiency virus and feline leukaemia virus status (in cats), species of Cryptococcus causing disease and region of domicile were recorded. Associations between variables were tested. Male and female cats were affected equally. Age ranged from 1 to 16 years, with a preponderance of cats aged between 2 and 3 years. Siamese, Himalayan and Ragdoll breeds were over-represented. Rural cats were more frequently infected with Cryptococcus gattii. Retroviral infection was not identified as a predisposing condition and was not correlated with either species of Cryptococcus or physical findings. Most cats had signs of nasal cavity infection, which was typically localised for a substantial period before invasion of adjacent structures or dissemination. Male and female dogs were affected equally. A marked preponderance of young, large breed dogs was noted. Border Collies, Boxers, Dalmatians, Dobermann Pinschers, Great Danes and German Shepherds were over-represented. Cryptococcus species involved was not affected by place of domicile. Although nasal cavity involvement was important, the canine cohort had a greater propensity to develop secondary central nervous system involvement and disseminated disease than feline cases. There were no clinical findings in either cats or dogs which could be reliably used to distinguish disease caused by Cryptococcus neoformans variety grubii from disease caused by Cryptococcus gattii. Both Cryptococcus species appear to be primary pathogens of cats and dogs, with the upper respiratory tract presumed to be the predominant primary site of inoculation in most but not all cases.", "journal": "Medical mycology", "doi": "10.1080/13693780310001624547", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15541796", "author": "Fujino Y", "n_authors": 10, "title": "Characterization of a newly established nonproducer lymphoma cell line for feline leukemia virus.", "abstract": "A feline lymphoblastoid cell line (KO-1) was established from a 5-year-old neutered female cat with naturally occurring thymic lymphoma. KO-1 cells had a rearrangement of T-cell receptor beta-chain gene and a germ-line configuration of immunoglobulin heavy chain gene, however, they were devoid of T-cell-specific surface phenotype. Cytogenetically, KO-1 cells showed a hyperploidy (2n = 41) due to the trisomy of B2, F2 and X chromosomes. Although KO-1 cells were shown to be clonally expanded cells integrated with feline leukemia virus (FeLV) proviruses and expressed its structural proteins in their cytoplasm, they did not produce virus particles as shown by transmission electron microscopy and the absence of the viral protein and reverse transcriptase activity in the culture supernatant. The present study showed that the KO-1 cell line established here was a feline T-cell lymphoma cell line having a unique characteristic as an FeLV nonproducer.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2004.08.009", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15517031", "author": "Mendes-de-Almeida F", "n_authors": 8, "title": "Sanitary conditions of a colony of urban feral cats (Felis catus Linnaeus, 1758) in a zoological garden of Rio de Janeiro, Brazil.", "abstract": "The colony of urban stray cats living in the Rio de Janeiro zoological garden was studied in order to develop a population and health control program. As many cats as possible were captured during two months (47 animals) and were classified according to gender, age, weight and coat markings. They were submitted to a general health evaluation, examined for the presence of ectoparasites and sent to a surgical neutering program. All animals had a blood sample drawn for CBC, platelet count, heartworm and retroviruses detection. Capillary blood smears were made for hemoparasites detection. Coat marking and colors were tabby (59.7%), followed by solid black (17%); torbie (10.6%); bicolor (10.6%) and harlequin (2.1%). The only ectoparasites found were fleas, which infested 28% of the animals. The hemoparasites found were Haemobartonella felis (38%) and piroplasmas that could not be differentiated between Cytauxzoon spp. and Babesia spp. (47%). No cat was found infected by Dirofilaria immitis or FeLV (Feline Leukemia Virus), although FIV (Feline Immunodeficiency Virus) antibodies could be detected (21%). There was no correlation between hemoparasites and FIV infections. The estimated total cat population (mark-recapture method) was 59; 68% female and 32% male, suggesting that a neutering program is in fact needed.", "journal": "Revista do Instituto de Medicina Tropical de Sao Paulo", "doi": "10.1590/s0036-46652004000500007", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15507152", "author": "Finstad SL", "n_authors": 4, "title": "Regulation of FeLV-945 by c-Myb binding and CBP recruitment to the LTR.", "abstract": "Feline leukemia virus (FeLV) induces degenerative, proliferative and malignant hematologic disorders in its natural host, the domestic cat. FeLV-945 is a viral variant identified as predominant in a cohort of naturally infected animals. FeLV-945 contains a unique sequence motif in the long terminal repeat (LTR) comprised of a single copy of transcriptional enhancer followed by a 21-bp sequence triplicated in tandem. The LTR is precisely conserved among independent cases of multicentric lymphoma, myeloproliferative disease and anemia in animals from the cohort. The 21-bp triplication was previously shown to act as a transcriptional enhancer preferentially in hematopoietic cells and to confer a replicative advantage. The objective of the present study was to examine the molecular mechanism by which the 21-bp triplication exerts its influence and the selective advantage responsible for its precise conservation. Potential binding sites for the transcription factor, c-Myb, were identified across the repeat junctions of the 21-bp triplication. Such sites would not occur in the absence of the repeat; thus, a requirement for c-Myb binding to the repeat junctions of the triplication would exert a selective pressure to conserve its sequence precisely. Electrophoretic mobility shift assays demonstrated specific binding of c-Myb to the 21-bp triplication. Reporter gene assays showed that the triplication-containing LTR is responsive to c-Myb, and that responsiveness requires the presence of both c-Myb binding sites. Results further indicated that c-Myb in complex with the 21-bp triplication recruits the transcriptional co-activator, CBP, a regulator of normal hematopoiesis. FeLV-945 replication was shown to be positively regulated by CBP in a manner dependent on the presence of the 21-bp triplication. Binding sites for c-Myb across the repeat junctions of the 21-bp triplication may account for its precise conservation in the FeLV-945 LTR. c-Myb binding and CBP recruitment to the LTR positively regulated virus production, and thus may be responsible for the replicative advantage conferred by the 21-bp triplication. Considering that CBP is present in hematopoietic cells in limiting amounts, we hypothesize that FeLV-945 replication in bone marrow may influence CBP availability and thereby alter the regulation of CBP-responsive genes, thus contributing to altered hematopoiesis and consequent hematologic disease.", "journal": "Virology journal", "doi": "10.1186/1743-422X-1-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15460206", "author": "Zoia A", "n_authors": 3, "title": "Pericardial effusion and cardiac tamponade in a cat with extranodal lymphoma.", "abstract": "A five-year-old domestic longhaired cat was evaluated for a seven-day history of worsening respiratory distress. Serum analysis for feline leukaemia virus antigen was positive. Pleural effusion was detected on thoracic radiographs and echocardiography revealed a pericardial effusion and cardiac tamponade. Cytological evaluation of the pleural and pericardial effusions showed lymphoblastic cells indicative of disseminated lymphoma. Following thoracocentesis and pericardiocentesis, the cat was treated for lymphoma using the University of Wisconsin-Madison chemotherapy protocol. The cat was sent home after three days and, at the time of writing (six months after initial presentation), was still symptom free. To the authors' knowledge, this is the first report confirming pericardial effusion and cardiac tamponade in the cat as a direct result of an extranodal lymphoma with cytological evidence of neoplastic cells in the pericardial fluid.", "journal": "The Journal of small animal practice", "doi": "10.1111/j.1748-5827.2004.tb00266.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15448356", "author": "Chandhasin C", "n_authors": 3, "title": "Feline leukaemia virus LTR variation and disease association in a geographical and temporal cluster.", "abstract": "Feline leukaemia virus (FeLV)-945 was previously identified in natural multicentric lymphomas and contains a 21 bp tandem triplication in the LTR. In the present study, FeLV LTR variation was examined in the cohort from which FeLV-945 was identified. The objectives of the study were to evaluate FeLV LTR variation within the cohort, to determine whether the FeLV-945 LTR was associated uniquely with multicentric lymphoma and to evaluate functional attributes that may have contributed selective advantage to the predominant LTR variants observed. T-cell tumours uniformly contained LTRs with duplicated enhancer sequences, although enhancer duplications conferred little transcriptional advantage. Non-T-cell malignant, proliferative and degenerative diseases contained LTRs with two, three or four tandemly repeated copies of the 21 bp sequence originally identified in FeLV-945. While the length and termini of enhancer duplications were variable, the 21 bp repeat unit was invariant. Triplication of the 21 bp repeat conferred the optimal replicative advantage in feline cells.", "journal": "The Journal of general virology", "doi": "10.1099/vir.0.80149-0", "deposited_data": "Sim", "nuccore_ids": "37577257, 37577256, 37577255, 37577254, 37577253, 37577252, 37577251, 37577250, 37577249, 37577248, 37577247, 37577246, 37577245, 37577244, 37577243, 37577242, 37577241, 37577240, 37577239, 37577238, 37577237, 37577236, 37577235, 37577234, 37577233, 37577232, 37577231, 37577230, 37577229, 37577228, 37577227, 37577226, 37577225, 37577224, 37577223, 37577222, 37577221, 37577220, 37577219, 37577218, 37577217, 37577216, 37577215, 37577214", "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15369674", "author": "Quigley JG", "n_authors": 10, "title": "Identification of a human heme exporter that is essential for erythropoiesis.", "abstract": "FLVCR, a member of the major facilitator superfamily of transporter proteins, is the cell surface receptor for feline leukemia virus, subgroup C. Retroviral interference with FLVCR display results in a loss of erythroid progenitors (colony-forming units-erythroid, CFU-E) and severe anemia in cats. In this report, we demonstrate that human FLVCR exports cytoplasmic heme and hypothesize that human FLVCR is required on developing erythroid cells to protect them from heme toxicity. Inhibition of FLVCR in K562 cells decreases heme export, impairs their erythroid maturation and leads to apoptosis. FLVCR is upregulated on CFU-E, indicating that heme export is important in primary cells at this stage. Studies of FLVCR expression in cell lines suggest this exporter also impacts heme trafficking in intestine and liver. To our knowledge, this is the first description of a mammalian heme transporter.", "journal": "Cell", "doi": "10.1016/j.cell.2004.08.014", "deposited_data": "Sim", "nuccore_ids": "2666210344, 1519315556, 322812157, 3382334014, 3382246094, 2666210344, 2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15363760", "author": "Luria BJ", "n_authors": 8, "title": "Prevalence of infectious diseases in feral cats in Northern Florida.", "abstract": "Objectives of this study were to determine prevalence of infection in feral cats in Northern Florida with a select group of infectious organisms and to determine risk factors for infection. Blood samples or sera from 553 cats were tested with a panel of antibody, antigen or PCR assays. Male cats were at higher risk for FIV, Mycoplasma haemofelis, and M. haemominutum. Infection with either FeLV or FIV was associated with increased risk for coinfection with the other retrovirus, M. haemofelis, or M. haemominutum. Bartonella henselae had the highest prevalence and was the only organism that did not have any associated risk for coinfection with other organisms. Feral cats in this study had similar or lower prevalence rates of infections than those published for pet cats in the United States. Thus, feral cats assessed in this study appear to be of no greater risk to human beings or other cats than pet cats.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2003.11.005", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15353861", "author": "Inokuma H", "n_authors": 8, "title": "Molecular survey of Mycoplasma haemofelis and 'Candidatus mycoplasma haemominutum' infection in cats in Yamaguchi and surrounding areas.", "abstract": "A molecular survey of hemoplasma (Mycoplasma haemofelis and 'Candidatus Mycoplasma haemominutum') in Yamaguchi Prefecture and surrounding areas was performed by using molecular methods. PCR-RFLP with HindIII revealed that 2 cats were infected with M. haemofelis, and 16 with 'C. Mycoplasma haemominutum' among 102 randomly selected cats. Partial 16S rRNA gene sequences of M. haemofelis and 'C. Mycoplasma haemominutum' determined in this study showed percent similarities of 98.3-99.8% and 96.4-100%, respectively, with those from other countries. Hemoplasma infections were more frequently detected in free-roaming cats than inside cats. Also, the status of FeLV infection was another significant risk factor for hemoplasma infection.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.66.1017", "deposited_data": "Sim", "nuccore_ids": "42566491, 42566490, 42566488, 42566485, 42566484, 42566483, 42566482, 42566481, 42566479, 42566477, 42566476, 42566475, 42566471, 42566470", "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15347624", "author": "de Lorimier LP", "n_authors": 2, "title": "Anemia associated with 'Candidatus Mycoplasma haemominutum' in a feline leukemia virus-negative cat with lymphoma.", "abstract": "'Candidatus Mycoplasma haemominutum,' previously known as the small form of Haemobartonella felis (California species), is a hemotrophic parasite found on erythrocytes of infected cats. Although fleas are potential vectors, confirmatory studies are lacking. Healthy cats infected with 'Candidatus Mycoplasma haemominutum' generally do not have clinically significant anemia, but concurrent disease or immune suppression may predispose a cat to develop a life-threatening anemia, such as in the case reported here.", "journal": "Journal of the American Animal Hospital Association", "doi": "10.5326/0400423", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15338705", "author": "Philippa JD", "n_authors": 12, "title": "Antibodies to selected pathogens in free-ranging terrestrial carnivores and marine mammals in Canada.", "abstract": "Antibody titres to selected pathogens (canine adenovirus [CAV-2], feline herpesvirus [FHV], phocine herpesvirus [PHV-1], canine distemper virus, dolphin morbillivirus [DMV], phocine distemper virus [PDV], parainfluenza virus type 3 [PI3], rabies virus, dolphin rhabdovirus [DRV], canine coronavirus, feline coronavirus, feline leukaemia virus, Borrelia burgdorferi and Toxoplasma gondii) were determined in whole blood or serum samples from selected free-ranging terrestrial carnivores and marine mammals, including cougars (Fellis concolor), lynxes (Fellis lynx), American badgers (Taxidea taxus), fishers (Martes pennanti), wolverines (Gulo gulo), wolves (Canis lupus), black bears (Ursus americanus), grizzly bears (Ursus arctos), polar bears (Ursus maritimus), walruses (Odobenus rosmarus) and belugas (Delphinapterus leucas), which had been collected at several locations in Canada between 1984 and 2001. Antibodies to a number of viruses were detected in species in which these infections have not been reported before, for example, antibodies to CAV-2 in walruses, to PDV in black bears, grizzly bears, polar bears, lynxes and wolves, to DMV in grizzly bears, polar bears, walruses and wolves, to PI3 in black bears and fishers, and to DRV in belugas and walruses.", "journal": "The Veterinary record", "doi": "10.1136/vr.155.5.135", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15320583", "author": "de Mari K", "n_authors": 5, "title": "Therapeutic effects of recombinant feline interferon-omega on feline leukemia virus (FeLV)-infected and FeLV/feline immunodeficiency virus (FIV)-coinfected symptomatic cats.", "abstract": "The clinical efficacy of a recombinant feline interferon, rFeIFN-omega, was evaluated for the treatment of cats presented with clinical signs associated with feline leukemia virus (FeLV) infection and FeLV/feline immunodeficiency virus (FIV) coinfection in the field. In this multicentric, double-blind, placebo-controlled trial, 81 cats meeting the inclusion criteria were randomly placed into 2 groups and treated subcutaneously with rFelFN-omega (1 million [M]U/kg per day) or placebo once daily for 5 consecutive days in 3 series (day 0, 14, 60). The cats were monitored for up to 1 year for clinical signs and mortality. During the initial 4-month period, interferon (IFN)-treated cats (n = 39) had significantly reduced clinical scores compared with placebo (n = 42), with all cats having received concomitant supportive therapies. Compared with the control, the IFN-treated group showed significantly lower rates of mortality: 39% versus 59% (1.7-fold higher risk of death for controls) at the 9-month time point and 47% versus 59% (1.4-fold higher risk of death for controls) at the 12-month time point. The IFN treatment was associated with minor but consistent improvement in abnormal hematologic parameters (red blood cell count, packed cell volume, and white blood cell count), apparently underlying the positive effects of IFN on clinical parameters. These data demonstrate that rFeIFN-omega initially has statistically significant therapeutic effects on clinical signs and later on survival of cats with clinical signs associated with FeLV infection and FeLV/FIV coinfection.", "journal": "Journal of veterinary internal medicine", "doi": "10.1892/0891-6640(2004)18<477:teorfi>2.0.co;2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15305717", "author": "Mancianti F", "n_authors": 1, "title": "[Feline leishmaniasis: what's the epidemiological role of the cat?].", "abstract": "Feline leishmaniasis (FL) is a quite uncommon feature. Clinical disease has been described in cats since nineties begin. More than 40 reports in world literature have been referred, but the clinical cases have been only recently well defined. Most of the reports focus on infected cats living in endemic areas, even if, more recently FL due to Leishmania infantum was found in Sao Paulo State, in Brazil where autochthonous human or canine leishmaniasis cases have never reported. In Europe clinical cases of FL have been described from Portugal, France, Spain and Italy from 1996 to 2002. When a typing of the etiological agent was performed L. infantum was identified in all reported cases. In some endemic areas serological surveys have also been carried out in cats, using IHAT in Egypt, Western blot in France or IFAT in Italy. Sixty Egyptian cats had low serological antibody titers, from 1/32 to 1/128, in the endemic focus of canine leishmaniasis of Alpes Maritimes 12 out of 97 (12.5%) cats showed antibodies versus antigens 14 and/or 18 kDa of L. infantum. A previous survey by means of IFAT in Liguria and Toscana on 110 and 158 feline sera respectively reports a seroprevalence of 0.9% with low titer, while sera from Sicily seem to be positive at higher dilutions. Animals living in an endemic area can develop specific antibodies against leishmania and, in our experience, they can be evidentiated by means of IFAT. The antibody titers appear to be lower in affected cats than in dogs, even if the number of clinical cases is very scanty. PCR tests on feline blood samples are in progress, but preliminary results confirm the presence of leishmania DNA in such specimens. Cutaneous leishmaniasis is the more frequent form in cats and it was reported from several countries. Typical signs include nodular to ulcer or crusty lesions on the nose, lips, ears, eyelids, alopecia: clinical signs of cutaneous FL are unspecific and in endemic area this infection must be taken into account. Visceral leishmaniasis is not common in cats: this form shows visceral involvement: liver and spleen are interested, with lymph nodes and kidney. The cat probably has to considerate to play an active role in the disease, in contrast to goats, calves and horses who could act as accidental reservoirs of leishmania, while sheep appears to be not susceptible to experimental infection. In endemic foci for kala-azar in Sudan cows, goats and donkeys had a high prevalence of specific antibodies. Recently in Europe sporadic cases of equine leishmaniasis have been reported: L. infantum was the causative agent. Equine leishmaniasis appears as a self-healing skin-dwelling disease, with a massive accumulation of parasites. The animals do not often show detectable specific antibodies and recover without any chemotherapy. Untreated affected cats can frequently die and we also observed lymph nodes and blood involvement indicating a spread of leishmania in feline hosts. The epidemiological role of the cat has never been clarified due also to lack of xenodiagnosis trials. This species is believed to have a high degree of natural resistance, as observed following experimental infection. Some of the affected cats were FIV and/or FeLV positive and these viroses such as stress may induce an impaired cellular immune response, even if leishmania infected cat was not submitted to CD4+, CD8+ lymphocyte counts nor other immunological test. However the resistance of the cat to leishmania infection probably depends on genetic factors, not strictly related to cell mediated immunity, taking into account the high seroprevalence of FIV infections (30%) in our country versus the number of clinical cases.", "journal": "Parassitologia", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15198250", "author": "Nolen RS", "n_authors": 1, "title": "Feline leukemia virus threatens endangered panthers.", "abstract": null, "journal": "Journal of the American Veterinary Medical Association", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15154732", "author": "Schubach TM", "n_authors": 10, "title": "Evaluation of an epidemic of sporotrichosis in cats: 347 cases (1998-2001).", "abstract": "To evaluate characteristics of a large epidemic of sporotrichosis in cats. Retrospective study. 347 cats with naturally acquired infection with Sporothrix schenckii. Medical records were reviewed for data regarding clinical, mycologic, histopathologic, and routine hematologic and serum biochemical findings; assays for FIV-specific antibodies and FeLV antigen; antifungal treatment; and follow-up. Lesions varied from small papules to extensive zones of necrosis. Ten cats had no skin lesions, 114 had skin lesions at a single site, 86 had skin lesions in 2 sites, and 137 had skin lesions in 3 or more sites. Respiratory tract signs were observed in 154 cats and were the most frequent extracutaneous sign. Anemia, leukocytosis with neutrophilia, hypoalbuminemia, and hyperglobulinemia were the main blood abnormalities. Antibodies against FIV were detected in 28 cats, FeLV antigen was detected in 2 cats, and both were detected in 1 cat among 142 cats tested. During the study, 118 cats were lost to follow-up and 124 died. Of 266 cats that were treated, 68 were cured. Complete healing of the lesions was observed regardless of the presence of extracutaneous signs, general condition, treatment schedule, or coinfection with FIV. Feline sporotrichosis was evident in subclinical to severe forms; however, cats can respond well to regular and prolonged antifungal treatment.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.2004.224.1623", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15137485", "author": "Munson L", "n_authors": 6, "title": "Serosurvey of viral infections in free-ranging Namibian cheetahs (Acinonyx jubatus).", "abstract": "Cheetahs (Acinonyx jubatus) in captivity have unusually high morbidity and mortality from infectious diseases, a trait that could be an outcome of population homogeneity or the immunomodulating effects of chronic stress. Free-ranging Namibian cheetahs share ancestry with captive cheetahs, but their susceptibility to infectious diseases has not been investigated. The largest remaining population of free-ranging cheetahs resides on Namibian farmlands, where they share habitat with domestic dogs and cats known to carry viruses that affect cheetah health. To assess the extent to which free-ranging cheetahs are exposed to feline and canine viruses, sera from 81 free-ranging cheetahs sampled between 1992 and 1998 were evaluated for antibodies against canine distemper virus (CDV), feline coronavirus (feline infectious peritonitis virus; FCoV/ FIPV), feline herpesvirus 1 (FHV1), feline panleukopenia virus (FPV), feline immunodeficiency virus (FIV), and feline calicivirus (FCV) and for feline leukemia virus (FeLV) antigens. Antibodies against CDV, FCoV/FIPV, FHV1, FPV, and FCV were detected in 24, 29, 12, 48, and 65% of the free-ranging population, respectively, although no evidence of viral disease was present in any animal at the time of sample collection. Neither FIV antibodies nor FeLV antigens were present in any free-ranging cheetah tested. Temporal variation in FCoV/FIPV seroprevalence during the study period suggested that this virus is not endemic in the free-ranging population. Antibodies against CDV were detected in cheetahs of all ages sampled between 1995 and 1998, suggesting the occurrence of an epidemic in Namibia during the time when CDV swept through other parts of sub-Saharan Africa. This evidence in free-ranging Namibian cheetahs of exposure to viruses that cause severe disease in captive cheetahs should direct future guidelines for translocations, including quarantine of seropositive cheetahs and preventing contact between cheetahs and domestic pets.", "journal": "Journal of wildlife diseases", "doi": "10.7589/0090-3558-40.1.23", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15137484", "author": "Riley SP", "n_authors": 3, "title": "Exposure to feline and canine pathogens in bobcats and gray foxes in urban and rural zones of a national park in California.", "abstract": "Exposure of bobcats (Lynx rufus) and gray foxes (Urocyon cinereoargenteus) to a range of common canine and feline pathogens was assessed in urban and rural zones of Golden Gate National Recreation Area, a National Park in the San Francisco Bay Area, (California, USA) from 1992 to 1995. Testing included serology for canine distemper virus, canine parvovirus (CPV), canine adenovirus, Leptospira interrogans, feline calicivirus (FCV), feline panleukopenia virus, feline herpesvirus, feline enteric coronavirus (FECV), feline immunodeficiency virus, feline leukemia virus, Toxoplasma gondii, and Bartonella henselae. Testing was also performed for Dirofilaria immitis. Significantly more gray foxes were seropositive for CPV in the urban zone than in the rural zone. In addition, radio-tracking of gray foxes in the rural zone indicated that all three of the rural CPV-seropositive foxes had traveled into adjoining small towns, whereas only one of the 11 seronegative animals had done so. Significantly more bobcats were seropositive for FCV in the rural zone than in the urban zone. Individual bobcats with positive FCV antibody titers had patterns of movement that intercepted park inholdings where domestic cats lived. Bobcat samples were seronegative for all five of the other viral feline pathogens, with the exception of a FECV-seropositive bobcat. High seroprevalence was detected for B. henselae and T. gondii in both zones. Variation in the seroprevalence for different pathogens might be related to differences in the exposure of bobcats and foxes to domestic animals: in the urban zone, gray foxes were located in residential areas outside the park, whereas bobcats were not. Although for most of the pathogens examined there was no relationship between urbanization and exposure, our results for CPV in foxes and FCV in bobcats indicated that proximity to urban areas or contact with humans can increase the risk of disease exposure for wild carnivore populations. Combining behavioral information from radio-tracking with data on pathogen exposure or disease incidence can provide valuable insights into the ecology of wildlife disease that might be missed with broad-scale, population-level comparisons alone.", "journal": "Journal of wildlife diseases", "doi": "10.7589/0090-3558-40.1.11", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15123148", "author": "Cave TA", "n_authors": 4, "title": "Risk factors for feline coronavirus seropositivity in cats relinquished to a UK rescue charity.", "abstract": "Two thousand, two hundred and seven cats from 14 shelters of a major UK cat charity were blood tested for feline coronavirus (FCoV) antibodies. Data was collated on breed, sex, age, number of cats at original location, outdoor access, health status, and time spent in the shelter prior to sampling (range 0 to 4 years). Some cats were also tested for feline leukaemia virus antigen, feline immunodeficiency virus, and Toxoplasma gondii antibodies. The effect of these variables on FCoV seropositivity was explored by multivariable logistic regression. FCoV seropositivity in cats that had spent 5 days or less in a shelter at sampling was significantly associated with a multi-cat origin, cats aged 3 years or less, and Persian breed. Whether pet, stray or feral, health status, indoor/outdoor access, and sex had no significant effect. Overall FCoV seropositivity was associated with time spent in a shelter but this association was not linear. Cats that had spent more than 60 days in a shelter were over five times as likely to be seropositive. This may be the result of a change in husbandry from solitary to communal housing for cats remaining in shelters long term. Rescue of cats for less than 60 days was not associated with a significant increasing risk of seropositivity. Significant variation existed in seropositivity between individual shelters overall and in cats rescued for less than 5 days. These findings may reflect inter-shelter variation in cat husbandry and variation in seropositivity of shelter intake respectively.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2004.01.003", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15090371", "author": "Crawford MJ", "n_authors": 5, "title": "Lyophilization does not inactivate infectious retrovirus in systemically infected bone and tendon allografts.", "abstract": "A review of multiple transplantations of human immunodeficiency virus-infected musculoskeletal allografts found that recipients of lyophilized (freeze-dried) bone or tendon from an infected donor all tested negative for human immunodeficiency virus. The finding that 75% of the recipients of fresh-frozen bone from the same donor contracted human immunodeficiency virus has led to speculation that freeze-drying may render retroviral-infected musculoskeletal allografts noninfectious. Lyophilization does not inactivate retrovirus in systemically infected bone and tendon. Controlled laboratory study. Tendons and cortical bone segments from cats systemically infected with feline leukemia virus were used in this study. Feline embryonic fibroblast cells were cultured in the presence of fresh-frozen or freeze-dried cortical bone or tendon segments. At each passage, feline leukemia virus p27 antigen was measured in media by enzyme-linked immunosorbent assay, and feline leukemia virus (pro)viral nucleic acids were quantified by real-time quantitative polymerase chain reaction in the DNA extracted from cells. Enzyme-linked immunosorbent assay results and quantitative polymerase chain reaction results demonstrated retroviral antigen and proviral DNA in all cultured cell replicates after exposure to fresh-frozen or freeze-dried bones or tendons. Freeze-drying (lyophilization) of retroviral-infected cortical bone and tendon does not inactivate retrovirus. These results conclusively demonstrate that freeze-drying should not be relied on to inactivate infectious retrovirus in systemically infected musculoskeletal allografts.", "journal": "The American journal of sports medicine", "doi": "10.1177/0363546504263404", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15077685", "author": "Coronado GS Jr", "n_authors": 2, "title": "Antiretroviral efficacy of a 98% solution of glycerol or ethylene oxide for inactivation of feline leukemia virus in bone.", "abstract": "To determine whether infectious retrovirus was inactivated in bones from FeLV-infected cats after ethylene oxide (ETO) sterilization or preservation in a 98% solution of glycerol in an in vitro cell culture system. Metatarsal bones obtained from 5 FeLV-infected cats and cultured with feline fibroblast cells. Metatarsal bones were treated with 100% ETO, a 98% solution of glycerol, or left untreated. Twenty-five flasks of feline fibroblast cells were assigned to 5 groups: negative control, positive control, ETO-treated bone, glycerol-treated bone, and untreated bone with 5 replicates/group for 4 passages. Media and cell samples were harvested from every flask at each passage to measure FeLV p27 antigen and the number of copies of provirus per 100 ng of DNA, respectively. All negative control and ETO-treated group replicates were negative for FeLV p27 antigen and provirus throughout the study. All positive control group replicates were positive for FeLV p27 antigen and provirus at passages 1 to 4. Untreated bone group replicates were positive for FeLV p27 antigen at passages 3 and 4 and provirus beginning at passage 2. Glycerol-treated group replicates had delayed cell replication and were negative for FeLV p27 antigen and provirus at passages 1 to 4 and 2 to 4, respectively. Ethylene oxide sterilization of bone from FeLV-infected cats appeared to abrogate transmission of infectious retrovirus and effectively sterilized bone allografts. Impact for Human Medicine-Additional studies to confirm effectiveness of ETO treatment of allograft tissues for prevention of pathogen transmission via transplantation are warranted.", "journal": "American journal of veterinary research", "doi": "10.2460/ajvr.2004.65.436", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15047851", "author": "Roca AL", "n_authors": 3, "title": "Genomically intact endogenous feline leukemia viruses of recent origin.", "abstract": "We isolated and sequenced two complete endogenous feline leukemia viruses (enFeLVs), designated enFeLV-AGTT and enFeLV-GGAG. In enFeLV-AGTT, the open reading frames are reminiscent of a functioning FeLV genome, and the 5' and 3' long terminal repeat sequences are identical. Neither endogenous provirus is genetically fixed in cats but polymorphic, with 8.9 and 15.2% prevalence for enFeLV-AGTT and enFeLV-GGAG, respectively, among a survey of domestic cats. Neither provirus was found in the genomes of related species of the Felis genus, previously shown to harbor enFeLVs. The absence of mutational divergence, polymorphic incidence in cats, and absence in related species suggest that these enFeLVs may have entered the germ line more recently than previously believed, perhaps coincident with domestication, and reopens the question of whether some enFeLVs might be replication competent.", "journal": "Journal of virology", "doi": "10.1128/jvi.78.8.4370-4375.2004", "deposited_data": "Sim", "nuccore_ids": "38176357, 38176356", "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "14960820", "author": "Soma T", "n_authors": 2, "title": "Detection of feline coronavirus antibody, feline immunodeficiency virus antibody, and feline leukemia virus antigen in ascites from cats with effusive feline infectious peritonitis.", "abstract": "To investigate the usefulness of ascites as a material for viral tests in cats with effusive feline infectious peritonitis (FIP), we attempted to detect anti-feline coronavirus antibody, anti-feline immunodeficiency virus antibody, and feline leukemia virus antigen in ascites from 88 cats clinically suspected with effusive FIP. In each of these three viral tests, all cats positive for serum antibody/antigen were also positive for ascitic antibody/antigen, while cats negative for serum antibody/antigen were also negative for ascitic antibody/antigen. This finding indicates that ascites is useful for these viral tests.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.66.89", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "14736905", "author": "Madewell BR", "n_authors": 4, "title": "Vaccine site-associated sarcoma and malignant lymphoma in cats: a report of six cases (1997-2002).", "abstract": "Six cats developed malignant lymphoma 3 to 45 months after treatment for vaccine site-associated sarcoma. During the same time period, 184 cats were evaluated in the teaching hospital for vaccine site-associated sarcomas. Feline vaccine site-associated sarcoma is not believed to be associated with feline leukemia virus (FeLV) infection. Five of six cats were negative by enzyme-linked immunosorbent assay for FeLV antigens at the times of diagnosis of both sarcoma and lymphoma, and no cats were infected with feline immunodeficiency virus.", "journal": "Journal of the American Animal Hospital Association", "doi": "10.5326/0400047", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "17315469", "author": "Lickey AL", "n_authors": 4, "title": "Serologic survey of domestic felids in the Petén region of Guatemala.", "abstract": "Blood samples were analyzed from 30 domestic cats (Felis domesticus) from the Petén region of Guatemala to determine the seroprevalence of common pathogens that may pose a potential risk to native wild felids. Eight of the cats had been vaccinated previously; however, owners were unable to fully describe the type of vaccine and date of administration. In addition, blood samples were obtained from two captive margays (Leopardus wiedii). Samples were tested for antibodies to feline immunodeficiency virus, Dirofilaria immitis, feline panleukopenia virus, feline herpesvirus, feline coronavirus, canine distemper virus, and Toxoplasma gondii and for feline leukemia virus (FeLV) antigen. Fifty percent or more of the cats sampled were seropositive for feline herpesvirus (22 of 30), feline panleukopenia (15 of 30), and T. gondii (16 of 30). Five cats were positive for FeLV antigen. Both margays were seropositive for feline coronavirus and one was strongly seropositive to T. gondii. All animals were seronegative for D. immitis. This survey provides preliminary information about feline diseases endemic to the Petén region.", "journal": "Journal of zoo and wildlife medicine : official publication of the American Association of Zoo Veterinarians", "doi": "10.1638/03-059", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "16642721", "author": "Millward IR", "n_authors": 2, "title": "Cryptococcus neoformans granuloma in the lung and spinal cord of a free-ranging cheetah (Acinonyx jubatus). A clinical report and literature review.", "abstract": "A 6-year-old, male, wild-born, free-ranging cheetah (Acinonyx jubatus) was evaluated for acute onset of progressive lameness in the right hind limb. Survey radiographs were unrewarding and myelography indicated an intramedullary compressive mass at the L3-L4 region. A fine needle aspirate of the lesion indicated the presence of Cryptococcus organisms. Necropsy confirmed the presence of granulomas (cryptococcoma) in the lung and the spinal cord (meningomyelitis) caused by Cryptococcus neoformans var. gattii. Cryptococcus neoformans is a yeast-like organism that is a potential pathogen to many species. Initial infection is thought to be of respiratory origin and then it commonly disseminates systemically from the nasal cavity or lungs to the skin, eyes and central nervous system in particular. The cheetah tested negative for both feline leukaemia virus (FeLV) and feline immunodeficiency virus (FIV), as have all the previously reported cheetah cases. C. neoformans is a non-contagious, opportunistic organism and is the most common systemic mycoses in domestic cats and the cheetah.", "journal": "Journal of the South African Veterinary Association", "doi": "10.4102/jsava.v76i4.432", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "16454381", "author": "Little SE", "n_authors": 1, "title": "Feline immunodeficiency virus testing in stray, feral, and client-owned cats of Ottawa.", "abstract": "Feline immunodeficiency virus (FIV) seroprevalence is evaluated in 3 groups of cats. Seventy-four unowned urban strays were tested, as well as 20 cats from a small feral cat colony, and 152 client-owned cats. Of the 246 cats tested, 161 (65%) were male and 85 (35%) were female. Seroprevalence for FIV was 23% in the urban strays, 5% in the feral cat colony, and 5.9% in the client-owned cats. Ten cats (4%) were also positive for Feline leukemia virus (FeLV) antigen, including 2 cats coinfected with FeLV and FIV. Seroprevalence for FIV in cats from Ottawa is similar to that found in other nonrandom studies of cats in North America.", "journal": "The Canadian veterinary journal = La revue veterinaire canadienne", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "16359309", "author": "Favrot C", "n_authors": 6, "title": "Two cases of FeLV-associated dermatoses.", "abstract": "Two cases of feline leukaemia virus (FeLV)-associated dermatosis are described. The first cat was affected by an ulcerative dermatitis identified as a giant-cell dermatosis. The second case was a cutaneous lymphoma. In both cases, FeLV antigens and FeLV genome were demonstrated in the affected skin immunologically and with polymerase chain reaction, respectively. The first case suggests that, like other retroviruses, at least some strains of FeLV can induce syncytium formation. As FeLV antigens and genome were demonstrated in a serologically negative cat, the second case suggests that focal skin FeLV replication may occur. FeLV-associated dermatoses are rare skin conditions that may be under-diagnosed.", "journal": "Veterinary dermatology", "doi": "10.1111/j.1365-3164.2005.00480.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "16276511", "author": "Sander DM", "n_authors": 6, "title": "Seroreactivity to A-type retrovirus proteins in a subset of cats with hyperthyroidism.", "abstract": "The thyroid gland is afflicted in several endocrine, autoimmune, and malignant diseases. Previous studies detected immunoreactivity against proteins of a human intracisternal A-type retroviral particle type-I (HIAP-I) in serum samples from the majority of patients with Graves' disease, an autoimmune disease of the thyroid that can also affect other organs, most prominently the eyes. To determine whether hyperthyroid animals might provide a model for the retroviral involvement in thyroid autoimmunity, serum samples from 32 cats (21 hyperthyroid and 11 controls) and 10 hypothyroid dogs were examined for immunoreactivity with HIAP-I using a Western blot technique. Of the 21 hyperthyroid cats 15 (71.4%) were HIAP-I positive, while only 2 of 11 (11.8%) control animals without endocrine pathology were positive. No significant correlations were seen between HIAP seroreactivity and serum thyroid hormone levels (T3 and T4), age, gender, treatment history, vaccination status, or weight. No seroreactivity to HIAP-I was detected in hypothyroid dogs. An examination of HIAP-I reactivity in feline leukemia virus (FeLV)-seroconverting cats found that 7/9 (78%) animals viremic for FeLV-A showed an alteration in HIAP serology, whereas only 1/7 (14%) nonviremic animals showed a change in HIAP-I serology. These results suggest that it may be possible to develop an animal (feline) model for the role of retroviruses in thyroid autoimmune diseases.", "journal": "Microscopy research and technique", "doi": "10.1002/jemt.20222", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "16245665", "author": "Gray MJ", "n_authors": 1, "title": "Chronic axillary wound repair in a cat with omentalisation and omocervical skin flap.", "abstract": "A mature, neutered male domestic cat was presented with a chronic axillary wound of unknown origin and at least three years' duration. The diagnostic investigation included screening tests for feline leukaemia virus and feline immunodeficiency virus, tissue culture and histological examination. No underlying aetiology or perpetuating cause could be identified. An omental flap was created, passed via a subcutaneous tunnel, and packed into the wound site after excision of all chronic granulation tissue. The skin defect was closed using an omocervical axial pattern skin flap. A small area of the distal edge of the flap became necrotic but the defect healed by second intention. To the author's knowledge, this is the first clinical report of the use of an omocervical skin flap for repair of a chronic axillary wound in a cat. This flap offers a useful alternative where the use of a thoracodorsal axial pattern flap is not possible due to the extent of the lesion.", "journal": "The Journal of small animal practice", "doi": "10.1111/j.1748-5827.2005.tb00279.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "16228264", "author": "Vobis M", "n_authors": 4, "title": "Experimental quantification of the feline leukaemia virus in the cat flea (Ctenocephalides felis) and its faeces.", "abstract": "Cat fleas (Ctenocephalides felis) were fed via artificial membranes and infected with the feline leukaemia virus (FeLV) from cell cultures. After removing the fleas from the blood source, the quantity of virus in the flea and its faeces was measured over a defined period of time. The virus was detectable in the fleas for up to 30 h at room temperature and up to 115 h at 4 degrees C. In the faeces, the amount of virus decreased much more slowly--after 2 weeks half of the initial amount of virus could still be detected. Thus the faeces might be a source of further infections, e.g. for the flea larvae or the cat itself.", "journal": "Parasitology research", "doi": "10.1007/s00436-005-1452-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "16220673", "author": "Milner RJ", "n_authors": 7, "title": "Response rates and survival times for cats with lymphoma treated with the University of Wisconsin-Madison chemotherapy protocol: 38 cases (1996-2003).", "abstract": "To determine response rates and survival times for cats with lymphoma treated with the University of Wisconsin-Madison chemotherapy protocol. Retrospective study. 38 cats with lymphoma. Medical records were reviewed, and information on age, sex, breed, FeLV and FIV infection status, anatomic form, clinical stage, and survival time was obtained. Immunophenotyping was not performed. Mean +/- SD age of the cats was 10.9 +/- 4.4 years. Overall median survival time was 210 days (interquartile range, 90 to 657 days), and overall duration of first remission was 156 days (interquartile range, 87 to 316 days). Age, sex, anatomic form, and clinical stage were not significantly associated with duration of first remission or survival time. Eighteen of the 38 (47%) cats had complete remission, 14 (37%) had partial remission, and 6 (16%) had no response. Duration of first remission was significantly longer for cats with complete remission (654 days) than for cats with partial remission (114 days). Median survival time for cats with complete remission (654 days) was significantly longer than median survival time for cats with partial remission (122 days) and for cats with no response (11 days). Results suggested that a high percentage of cats with lymphoma will respond to treatment with the University of Wisconsin-Madison chemotherapy protocol. Age, sex, anatomic form, and clinical stage were not significantly associated with duration of first response or survival time, but initial response to treatment was.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.2005.227.1118", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "16220130", "author": "Ugarte CE", "n_authors": 6, "title": "Spirometra erinacei / S. erinaceieuropaei in a feral cat in Manawatu with chronic intermittent diarrhoea.", "abstract": "A feral cat captured in the Manawatu region of New Zealand was treated for worms and fleas, and kept confined in a metabolic cage. It showed good appetite and weight gain but had intermittent watery, yellow diarrhoea. Clinical examination under sedation was unremarkable and routine blood tests showed no significant abnormalities. The cat was negative for feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV). Different canned cat foods did not alter the course of the diarrhoea, and the cat was euthanised 6 months after capture. At necropsy, two sections of adult Spirometra tapeworms were found in the jejunum and typical Spirometra eggs were found in colonic contents. Molecular identification of the parasite was undertaken, using the cytochrome-c oxidase subunit-1 gene (cox1) sequence. Chronic intermittent diarrhoea associated with Spirometra erinacei / S. erinaceieuropaei infection. Spirometra has not been reported in New Zealand before but has been associated with gastrointestinal disease in cats in other parts of the world. It requires species targeted treatment to be eliminated effectively, and is zoonotic. Diagnosis could be difficult for clinicians who are not familiar with the parasite and its life cycle.", "journal": "New Zealand veterinary journal", "doi": "10.1080/00480169.2005.36573", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "16218216", "author": "Grevot A", "n_authors": 8, "title": "Leishmaniosis due to Leishmania infantum in a FIV and FelV positive cat with a squamous cell carcinoma diagnosed with histological, serological and isoenzymatic methods.", "abstract": "Leishmaniosis caused by Leishmania infantum is an endemic zoonosis present in the Mediterranean area. Canidae (dog and fox) constitute the main reservoir hosts for the parasite, whilst wild rodents or the cat can be carriers of the protozoan and are considered as secondary potential reservoirs. This paper describes a case of disseminated feline leishmaniosis with cutaneous (ulcerative), visceral (spleen and lymph nodes) and blood involvement in a FIV-FelV positive cat. The microscopic identification of the Leishmania infection was initially made on a skin biopsy of the temporal area, where a squamous cell carcinoma was diagnosed. The diagnosis of the disease was achieved by several serological techniques (ELISA, IFAT and Western-blot). The strain was obtained by blood culture, characterized by electrophoresis of isoenzymes and identified as Leishmania infantum zymodeme MON-1. Since the infection due to L. infantum is a zoonosis, the potential feline reservoir should be more investigated. Serological analysis by Western blot on domestic cats provides a useful tool. In veterinary practice, feline leishmaniosis should be systematically included in the differential diagnosis when compatible cutaneous lesions are present, especially in the endemic areas of canine leishmaniosis.", "journal": "Parasite (Paris, France)", "doi": "10.1051/parasite/2005123271", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "16181751", "author": "Winslow BJ", "n_authors": 5, "title": "Feline B7.1 and B7.2 proteins produced from swinepox virus vectors are natively processed and biologically active: potential for use as nonchemical adjuvants.", "abstract": "Costimulatory ligands, B7.1 and B7.2, have been incorporated into viral and DNA vectors as potential nonchemical adjuvants to enhance CTL and humoral immune responses against viral pathogens. In addition, soluble B7 proteins, minus their transmembrane and cytoplasmic domains, have been shown to block the down regulation of T-cell activation through blockade of B7/CTLA-4 interactions in mouse tumor models. Recently, we developed swinepox virus (SPV) vectors for delivery of feline leukemia antigens for vaccine use in cats [Winslow, B.J., Cochran, M.D., Holzenburg, A., Sun, J., Junker, D.E., Collisson, E.W., 2003. Replication and expression of a swinepox virus vector delivering feline leukemia virus Gag and Env to cell lines of swine and feline origin. Virus Res. 98, 1-15]. To explore the use of feline B7.1 and B7.2 ligands as nonchemical adjuvants, SPV vectors containing full-length feline B7.1 and B7.2 ligands were constructed and analyzed. Full-length feline B7.1 and B7.2 produced from SPV vectors were natively processed and costimulated Jurkat cells to produce IL-2, in vitro. In addition, we explored the feasibility of utilizing SPV as a novel expression vector to produce soluble forms of feline B7.1 (sB7.1) and B7.2 (sB7.2) in tissue culture. The transmembrane and cytoplasmic regions of the B7.1 and B7.2 genes were replaced with a poly-histidine tag and purified via a two-step chromatography procedure. Receptor binding and costimulation activity was measured. Although feline sB7.1-his and sB7.2-his proteins bound to the human homolog receptors, CTLA-4 and CD28, both soluble ligands possessed greater affinity for CTLA-4, compared to CD28. However, both retained the ability to partially block CD28-mediated costimulation in vitro. Results from these studies establish the use of SPV as a mammalian expression vector and suggest that full-length-vectored and purified soluble feline B7 ligands may be valuable, nonchemical immune-modulators.", "journal": "Veterinary microbiology", "doi": "10.1016/j.vetmic.2005.06.008", "deposited_data": "Sim", "nuccore_ids": "1907067119, 1393276475, 1393276474, 530354669, 530354668", "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "16173492", "author": "Reiter AM", "n_authors": 4, "title": "Evaluation of calciotropic hormones in cats with odontoclastic resorptive lesions.", "abstract": "To assess associations between epidemiologic and laboratory variables and calciotropic hormones in cats with odontoclastic resorptive lesions (ORLs). 182 client-owned cats older than 1 year of age with oral disease. Information on medical history, behavior, living environment, and feeding management was assessed by use of a questionnaire. After induction of general anesthesia, oral examination was performed following standardized protocols and included dental probing and full-mouth radiography. Laboratory analyses included evaluation of FeLV-FIV status, serum biochemical analyses, CBC, urinalysis, and serum concentrations of intact parathyroid hormone (iPTH), parathyroid hormone-related peptide (PTHrP), 25-hydroxyvitamin D (25-OHD), free thyroxine (fT4), and ionized calcium (iCa). ORLs were identified in 72.5% of cats. Mandibular third premolars were the most commonly affected teeth. Cats with ORLs were significantly older (mean, 9.2 years) than cats without ORLs (mean, 6.6 years). Multivariate logistic regression analysis revealed that 25-OHD, urine specific gravity, jaw-opening reflex on probing, and missing teeth were significant variables, even after accounting for age. Cats with ORLs had significantly higher mean serum concentration of 25-OHD (112.4 nmol/L) and significantly lower mean urine specific gravity (1.0263), compared with cats without ORLs (89.8 nmol/L and 1.0366, respectively). Results did not indicate associations between iPTH, PTHrP, or fT4 and development of ORLs. In affected cats, the importance of high serum 25-OHD and low urine specific gravity has not been determined.", "journal": "American journal of veterinary research", "doi": "10.2460/ajvr.2005.66.1446", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "16143471", "author": "Pan J", "n_authors": 8, "title": "In vivo expression of GFP transgene delivered via a replicating feline leukemia virus.", "abstract": "We previously described replication-competent feline leukemia virus (FeLV) vectors with high-level and stable expression of a green fluorescent protein (GFP) or a suicide transgene in cell cultures in vitro. Considering that FeLV might potentially be used to deliver therapeutic genes in vivo, we first evaluated the expression of the GFP gene introduced in cats by the FeLV, Rickard subgroup A (FRA) construct. Eight newborn kittens were either inoculated with pFRA-GFP plasmid DNA intradermally, or challenged intraperitoneally with FRA-GFP-infected feline fibroblasts. During a 12-week observation period, five cats were shown to be progressively viremic. Quantitative PCR and RT-PCR analyses of plasma and tissue samples from these cats showed that GFP was retained in FeLV DNA or RNA to a variable degree, ranging from 0.002 to 27.890%. Tissue DNA samples were analyzed by PCR for the status of GFP and the env-transgene complex. While the proviruses carrying the GFP transgene were shown to be minor species, all tissues, however, retained the full-length GFP transgene. Despite the occurrence of predominant species with various deletions in the viral genome, approximately 1-3% of the total cell population was GFP-positive in the lymphoid tissues as visualized by laser confocal microscopy. Co-localization of immunofluorescent cells indicated that CD3-positive T cells, dendritic cells and macrophages were the major targets for GFP expression. These findings on the detectable in vivo expression of GFP for as long as a period of 3 months could be viewed positively for contemplating a therapeutic strategy for control of FeLV infection in the cats.", "journal": "Veterinary microbiology", "doi": "10.1016/j.vetmic.2005.07.015", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "16054243", "author": "Tandon R", "n_authors": 7, "title": "Quantitation of feline leukaemia virus viral and proviral loads by TaqMan real-time polymerase chain reaction.", "abstract": "Feline leukaemia virus (FeLV) infection in cats is not only of veterinary importance but also a well-acknowledged animal model for studying the pathogenesis of retroviral disease. After virus exposure, different courses and outcomes of FeLV infection may prevail; they have been associated with cellular and humoral immune responses and the FeLV proviral load in peripheral blood. We hypothesized that the plasma viral RNA load might be an additional relevant indicator for the infection outcome. To quantify these loads, a real-time reverse transcriptase (RT) polymerase chain reaction (PCR) assay was developed. The assay amplifies FeLV-A, -B, and -C as some naturally infected cats could not be identified with a FeLV-A-based assay previously. The assay was applied to determine plasma FeLV RNA loads in cats infected both naturally and experimentally with FeLV. In addition, an improved real-time PCR assay for quantitation of FeLV proviral loads is described. The assays developed were more sensitive than ELISA and virus isolation in the early phase of infection. In addition, PCR allows the identification of provirus carriers that have overcome antigenaemia. Thus, for most effective detection of FeLV exposure and characterization of the infection in a cat, PCR assays are recommended as diagnostic tools.", "journal": "Journal of virological methods", "doi": "10.1016/j.jviromet.2005.06.017", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "16023797", "author": "Tejerizo G", "n_authors": 5, "title": "Effect of 17beta-estradiol and progesterone on the expression of FeLV in chronically infected cells.", "abstract": "In a previous study, it was found that even though more male cats were infected by feline leukaemia virus (FeLV), females seemed to progress easier to overt disease. To study the effect of female hormones, 17beta-estradiol and progesterone were added in different concentrations (10(-3) M to 10(-12) M) to a culture of persistently FeLV-infected cells. The effect of both hormones was very similar. After 24 h the cell viability was very low at 10(-3) M and 10(-4) M but similar to controls at the remaining concentrations. Liberation of viral particles was estimated by the reverse transcriptase activity (RT), which was the lowest also at 10(-3) M and 10(-4) M. However, low viability could not account for this low RT, as when cells were lysed with lysis buffer RT was high. Thus, cells were dying without freeing viral particles, suggestive of apoptosis. This possibility was confirmed by staining hormone-treated cells with annexin V and propidium iodide. The FeLV antigen p27 measured in the cultures had a maximum at 10(-3) M and 10(-4) M, higher than controls and lysed cells, so the presence of p27 in the supernatant was not only due to cell lysis but a consequence of hormone effect. In conclusion, 17beta-estradiol and progesterone induce death of FeLV-infected cells at high concentrations, probably through a process of apoptosis, which might limit the spread of the infection, as infective viral particles would be hampered from budding.", "journal": "Veterinary microbiology", "doi": "10.1016/j.vetmic.2005.06.005", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15989127", "author": "Hoffmann-Jagielska M", "n_authors": 6, "title": "Influence of naturally acquired feline leukemia virus (FeLV) infection on the phagocytic and respiratory burst activity of neutrophils and monocytes of peripheral blood.", "abstract": "The purpose of this study was cytometric evaluation of phagocytic and oxidative burst activity of neutrophils and monocytes in cats naturally infected with FeLV. To conduct the study, the peripheral blood was obtained from 33 cats naturally infected with FeLV. The control group consisted of 30 FeLV-, FIV-, clinically healthy cats. The percentage of phagocytizing neutrophils of peripheral blood was lower in FeLV+ than in FeLV- cats. The percentage of neutrophils and monocytes in which an oxidative burst occurred was lower in FeLV+ than in FeLV-animals. Also an oxidative product formation in neutrophils after E. coli and PMA stimulation was lower in FeLV+ than in FeLV-animals. Obtained results allow to conclude that diminished phagocytic and oxidative burst activity of peripheral blood leukocytes may cause impairment of innate immunity in cats infected with FeLV.", "journal": "Polish journal of veterinary sciences", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15982476", "author": "Pocacqua V", "n_authors": 6, "title": "Glycan moiety modifications of feline alpha1-acid glycoprotein in retrovirus (FIV, FeLV) affected cats.", "abstract": "alpha1-Acid glycoprotein (AGP) is considered one of the major acute phase proteins in cats. In humans, AGP is a heavily glycosylated protein that undergoes several modifications of its glycan moiety during acute and chronic inflammatory pathologies. In this paper we present the feline AGPs (fAGP) glycan moiety modifications in the course of two prevalent feline diseases, the FIV (feline immunodeficiency virus) dependent feline acquired viral immunodeficiency and the feline leukemia virus (FeLV) associated lymphoma. The glycan moiety of fAGP was investigated by means of the binding of its oligosaccharides residues with specific lectins. Four lectins were used: Sambucus nigra agglutinin I and Maackia amurensis agglutinin lectins were used to detect sialic acid residues, Aleuria aurantia lectin was used to detect L-fucose residues and Concanavalin A was used to evaluate the degree of branching. It was found that fAGP undergoes several post-translational modifications of its glycan pattern: in particular the degree of sialylation is increased in FeLV-positive cats diagnosed with lymphoma, while FeLV-positive that did not presented any specific clinical signs cats do not present any increase of expression of sialic acid on the surface. Furthermore, FIV induced a modification of the glycan moiety of fAGP, which however varied widely among individuals. In order to determine the number and the position of oligosaccharide chains, the cDNA sequence of fAGP was also determined. The translation of the mature fAGP coding sequence gave rise to a sequence of 183 residues, with five potential N-glycosylation sites, but also with seven potential phosphorylation sites.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2005.02.021", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15954547", "author": "Louwerens M", "n_authors": 4, "title": "Feline lymphoma in the post-feline leukemia virus era.", "abstract": "Lymphoma (lymphosarcoma or malignant lymphoma) is the most common neoplasm of the hematopoietic system of cats and reportedly the cat has the highest incidence for lymphoma of any species. A 21-year retrospective survey of feline lymphoma covering the period 1983-2003 was conducted with the patient database at the Veterinary Medicine Teaching Hospital (VMTH) at the University of California, Davis, School of Veterinary Medicine. This period comprises the post-feline leukemia virus (FeLV) era. Feline lymphoma historically has been highly associated with retrovirus infection. Mass testing and elimination and quarantine programs beginning in the 1970s and vaccination programs in the 1980s dramatically reduced the subsequent FeLV infection rate among pet cats. The results of this survey confirm a significant decrease in the importance of FeLV-associated types of lymphoma in cats. In spite of this decrease in FeLV infection, the incidence of lymphoma in cats treated at the VMTH actually increased from 1982 to 2003. This increase was due largely to a rise in the incidence of intestinal lymphoma, and to a lesser degree, of atypical lymphoma. A high incidence of mediastinal lymphomas in young Siamese or Oriental breeds also was observed, supporting previous studies. Associations of intestinal lymphoma and inflammatory bowel disease and diet should be further considered.", "journal": "Journal of veterinary internal medicine", "doi": "10.1892/0891-6640(2005)19[329:flitpl]2.0.co;2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15948426", "author": "Colitz CM", "n_authors": 1, "title": "Feline uveitis: diagnosis and treatment.", "abstract": "Uveitis is the inflammation of any or all parts of the vascular tunic of the eye; the vascular tunic includes the iris, the ciliary body, and choroid. A good knowledge base, up-to-date reference materials, and good instruments will improve the diagnosis of uveitis. Feline uveitis can be caused by numerous infectious agents in addition to neoplasia and less likely trauma. The infectious causes most commonly associated with feline uveitis include feline leukemia virus, feline immunodeficiency virus, feline infectious peritonitis, systemic fungal infections, toxoplasmosis, and bartonellosis. Neoplastic causes of uveitis can be primary or secondary. Iris melanoma is the most common primary uveal neoplasia and trauma-associated sarcoma is the second most common primary uveal neoplasia. Treatment for the clinical signs of anterior uveitis include topical steroidal or non-steroidal anti-inflammatory agents, parasympatholytic agents for ciliary spasm, to keep the pupil dilated, and to prevent posterior synechia. Posterior uveitis should be treated with systemic medications that will address the underlying cause. Enucleation of blind, painful eyes not responsive to medications is a means to alleviate the animal's discomfort and to further diagnose the underlying cause.", "journal": "Clinical techniques in small animal practice", "doi": "10.1053/j.ctsap.2004.12.016", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15893619", "author": "O'Donovan LH", "n_authors": 12, "title": "A vector expressing feline mature IL-18 fused to IL-1beta antagonist protein signal sequence is an effective adjuvant to a DNA vaccine for feline leukaemia virus.", "abstract": "DNA vaccination using vectors expressing the gag/pol and env genes of feline leukaemia virus (FeLV) and plasmids encoding feline interleukin-12 (IL-12) and IL-18 completely protected cats from viraemia following challenge [Hanlon L, Argyle D, Bain D, Nicolson L, Dunham S, Golder MC, et al. Feline leukaemia virus DNA vaccine efficacy is enhanced by coadministration with interleukin-12 (IL-12) and IL-18 expression vectors. J Virol 2001;75:8424-33]. However, the relative contribution of each cytokine gene towards protection is unknown. This study aimed to resolve this issue. IL-12 and IL-18 constructs were modified to ensure effective expression, and bioactivity was demonstrated using specific assays. Kittens were immunised intramuscularly with FeLV DNA and various cytokine constructs. Together with control kittens, these were challenged oronasally with FeLV and monitored for 15 weeks. All six kittens given FeLV, IL-12 and IL-18 were protected from the establishment of persistent viraemia and four from latent infection. Of six kittens immunised with FeLV DNA and IL-18, all were protected from viraemia and five from latent infection. In contrast, three of five kittens given FeLV DNA and IL-12 became persistently viraemic. Therefore, the adjuvant effect on the FeLV DNA vaccine appears to reside in the expression of IL-18.", "journal": "Vaccine", "doi": "10.1016/j.vaccine.2005.02.026", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15876545", "author": "Watanabe R", "n_authors": 3, "title": "Cell-binding properties of the envelope proteins of porcine endogenous retroviruses.", "abstract": "To examine the binding properties of the envelope glycoproteins of porcine endogenous retrovirus subgroups A and B (PERV-A and PERV-B), we produced two forms of soluble envelope proteins, termed Env-ST and Env-SU, using a baculovirus expression system. Env-ST and Env-SU encompass one-third of the N-terminal and the entire surface unit (SU) of the envelope protein, respectively. Using these proteins, binding assays were performed in various mammalian cell lines. The binding properties of the Env-STs that contain the putative receptor binding domain (RBD) did not correlate with the susceptibility to the pseudotype viruses having PERV envelopes, whereas those of the Env-SUs correlated fairly well. These results suggested that the Env-SUs but not Env-STs interacted with their receptors in various cell lines. Interestingly, PERV-A Env-SU did not bind to a mink cell line (Mv1-Lu cells) that is highly susceptible to the PERV-A pseudotype virus. In addition, PERV-B Env-SU did not interfere with the PERV-B pseudotype virus on Mv1-Lu cells. These results suggest the existence of a cognate receptor-independent entry pathway as demonstrated in an immunodeficiency-inducing variant of feline leukemia virus FeLV.", "journal": "Microbes and infection", "doi": "10.1016/j.micinf.2005.01.008", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15856037", "author": "Rao S", "n_authors": 9, "title": "Phase III study of 5FU, etoposide and leucovorin (FELV) compared to epirubicin, cisplatin and 5FU (ECF) in previously untreated patients with advanced biliary cancer.", "abstract": "The purpose of this study was to determine whether epirubicin, cisplatin and infused 5FU (ECF) improves overall survival (OS) compared to 5FU, etoposide and leucovorin (FELV) in patients with previously untreated advanced biliary cancer in a prospective randomised study. Patients were randomly assigned to receive epirubicin, cisplatin and infused 5FU ECF or bolus 5FU etoposide and leucovorin (FELV). The primary end point was OS with secondary end points of objective response rate (ORR), failure-free survival (FFS), quality of life (QOL) and toxicity. In all, 54 patients were recruited with 27 randomly assigned to each arm. The median OS for ECF was 9.02 months (95% confidence interval (CI): 6.46-11.51) and FELV 12.03 months (95% CI: 9.3-14.7), P=0.2059. Objective response rates were similar for both arms: ECF 19.2% (95% CI: 6.55-39.3); FELV 15% (95% CI: 3.2-37.9), P=0.72. There was significantly increased grade 3/4 neutropenia with FELV vs ECF (53.8 vs 29.5%, respectively, P=0.020). Symptom resolution was impressive for both regimens. This is the largest reported randomised study to date in this setting. ECF did not improve OS compared to FELV, but was associated with less acute toxicity. These data suggest that chemotherapy can prolong OS and achieve good symptomatic relief in advanced biliary cancer.", "journal": "British journal of cancer", "doi": "10.1038/sj.bjc.6602576", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15842545", "author": "Anfray P", "n_authors": 6, "title": "Feline cutaneous toxoplasmosis: a case report.", "abstract": "A 9-year-old female, domestic short hair cat was presented with sudden onset of polyuria/polydipsia, and hundreds of cutaneous nodules. Prior to referral, the cat had had four skin nodules that were treated with steroids. The four skin nodules then multiplied to form more than 100 ulcerated and nonulcerated nodules located all over the trunk. Clinical evaluation revealed hypothermia and respiratory distress. Cytology from both skin nodules and bronchoalveolar lavage showed macrophages and small organisms whose shape and size were indicative of Toxoplasma spp., or similar organisms. Feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV) serology results were negative. The cat was seropositive for Toxoplasma (IgG 1 : 640) and Neospora (1 : 80) infections. The cat died soon after referral. Necropsy revealed pyothorax, necrotic/purulent pneumonia, haemorrhagic spots on kidneys and mesentery. Histopathology from skin nodules showed diffuse, deep necrotic dermatitis/panniculitis, vasculitis and disseminated free and grouped protozoa. The parasites were found in lungs, spleen, kidneys and liver. Immunohistochemistry on skin tissue with anti-Toxoplasma gondii and Neospora caninum antibodies gave positive results with both. Electron microscopy showed single and grouped tachyzoites with morphological features of T. gondii, often within macrophages. Samples of cutaneous nodules and bronchoalveolar fluid were examined by a polymerase chain reaction (PCR) assay for detecting apicomplexa coccidia. PCR results were consistent only with T. gondii infection. Therefore, immunohistochemistry positivity for N. caninum was considered a cross-reaction and a diagnosis of cutaneous and visceral toxoplasmosis was made.", "journal": "Veterinary dermatology", "doi": "10.1111/j.1365-3164.2005.00434.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15837241", "author": "Langhammer S", "n_authors": 4, "title": "Neutralising antibodies against the transmembrane protein of feline leukaemia virus (FeLV).", "abstract": "Neutralising antibodies specific for feline leukaemia virus (FeLV) were induced by immunisation with recombinant FeLV transmembrane envelope protein p15E. Epitope mapping revealed two epitopes located in similar regions to those previously identified for the porcine endogenous retrovirus (PERV). One of the epitopes has partial homology and both are located in regions corresponding to epitopes recognised by neutralising antibodies in patients infected with HIV-1.", "journal": "Vaccine", "doi": "10.1016/j.vaccine.2005.01.091", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15827211", "author": "Ryser-Degiorgis MP", "n_authors": 7, "title": "Epizootiologic investigations of selected infectious disease agents in free-ranging Eurasian lynx from Sweden.", "abstract": "Serum samples from 106 Eurasian lynx (Lynx lynx) from across Sweden, found dead or shot by hunters in 1993-99, were investigated for presence of antibodies to feline parvovirus (FPV), feline coronavirus, feline calicivirus, feline herpesvirus, feline immunodeficiency virus, Francisella tularensis, and Anaplasma phagocytophila, and for feline leukemia virus antigen. In addition, tissue samples from 22 lynx submitted in 1999 were analyzed by real-time polymerase chain reaction (PCR) to detect nucleic acids specific for viral agents and A. phagocytophila. Except for FPV antibodies in one lynx and A. phagocytophila in four lynx, all serology was negative. All PCR results also were negative. It was concluded that free-ranging Swedish lynx do not have frequent contact with the infectious agents considered in this study.", "journal": "Journal of wildlife diseases", "doi": "10.7589/0090-3558-41.1.58", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15827142", "author": "Chandhasin C", "n_authors": 7, "title": "Unique long terminal repeat and surface glycoprotein gene sequences of feline leukemia virus as determinants of disease outcome.", "abstract": "The outcome of feline leukemia virus (FeLV) infection in nature is variable, including malignant, proliferative, and degenerative disorders. The determinants of disease outcome are not well understood but are thought to include viral, host, and environmental factors. In particular, genetic variations in the FeLV long terminal repeat (LTR) and SU gene have been linked to disease outcome. FeLV-945 was previously identified as a natural isolate predominant in non-T-cell neoplastic and nonneoplastic diseases in a geographic cohort. The FeLV-945 LTR was shown to contain unique repeat elements, including a 21-bp triplication downstream of the enhancer. The FeLV-945 SU gene was shown to encode mutational changes in functional domains of the protein. The present study details the outcomes of infection with recombinant FeLVs in which the LTR and envelope (env) gene of FeLV-945, or the LTR only, was substituted for homologous sequences in a horizontally transmissible prototype isolate, FeLV-A/61E. The results showed that the FeLV-945 LTR determined the kinetics of disease. Substitution of the FeLV-945 LTR into FeLV-A/61E resulted in a significantly more rapid disease onset but did not alter the tumorigenic spectrum. In contrast, substitution of both the FeLV-945 LTR and env gene changed the disease outcome entirely. Further, the impact of FeLV-945 env on the disease outcome was dependent on the route of inoculation. Since the TM genes of FeLV-945 and FeLV-A/61E are nearly identical but the SU genes differ significantly, FeLV-945 SU is implicated in the outcome. These findings identify the FeLV-945 LTR and SU gene as determinants of disease.", "journal": "Journal of virology", "doi": "10.1128/JVI.79.9.5278-5287.2005", "deposited_data": "Sim", "nuccore_ids": "54112485, 54112484, 54112483, 54112482, 54112481, 54112480, 54112479, 54112478, 54112477, 54112476, 54112475, 54112474, 54112473, 54112472, 54112471, 54112470, 54112469, 54112468, 54112467, 54112466, 54112465, 54112463, 54112461, 54112459, 54112457, 54112456, 54112454, 54112452, 54112450, 54112449, 54112447, 54112445, 54112444, 54112442, 54112441, 54112440, 54112438, 54112436, 54112434, 54112433", "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15823610", "author": "Operario DJ", "n_authors": 3, "title": "Comparison of DNA polymerase activities between recombinant feline immunodeficiency and leukemia virus reverse transcriptases.", "abstract": "In this study, we present enzymatic differences found between recombinant RTs derived from feline leukemia virus and feline immunodeficiency virus. Firstly, FIV RT showed low steady state K(m) values for dNTPs compared to FeLV RT. Consistent with this, FIV RT synthesized DNA more efficiently than FeLV RT at low dNTP concentrations. We observed similar concentration-dependent activity differences between other lentiviral (HIV-1 and SIV) and non-lentiviral (MuLV and AMV) RTs. Second, FeLV RT showed less efficient misincorporation with biased dNTP pools and mismatch primer extension capabilities, compared to FIV RT. In M13mp2 lacZalpha forward mutation assays, FeLV RT displayed approximately 11-fold higher fidelity than FIV RT. Finally, FeLV RT was less sensitive to 3TCTP and ddATP than FIV RT. This study represents the comprehensive enzymatic characterization of RTs from a lentivirus and a non-lentivirus retrovirus from the same host species. The data presented here support enzymatic divergences seen among retroviral RTs.", "journal": "Virology", "doi": "10.1016/j.virol.2005.02.010", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15774617", "author": "Lucas ML", "n_authors": 9, "title": "Improved transduction of human sheep repopulating cells by retrovirus vectors pseudotyped with feline leukemia virus type C or RD114 envelopes.", "abstract": "Gene therapy for hematopoietic diseases has been hampered by the low frequency of transduction of human hematopoietic stem cells (HSCs) with retroviral vectors pseudotyped with amphotropic envelopes. We hypothesized that transduction could be increased by the use of retroviral vectors pseudotyped with envelopes that recognize more abundant cellular receptors. The levels of mRNA encoding the receptors of the feline retroviruses, RD114 and feline leukemia virus type C (FeLV-C), were significantly higher than the level of gibbon ape leukemia virus (GaLV) receptor mRNA in cells enriched for human HSCs (Lin- CD34+ CD38-). We cotransduced human peripheral blood CD34+ cells with equivalent numbers of FeLV-C and GALV or RD114 and GALV-pseudotyped retroviruses for injection into fetal sheep. Analysis of DNA from peripheral blood and bone marrow from recipient sheep demonstrated that FeLV-C- or RD114-pseudotyped vectors were present at significantly higher levels than GALV-pseudotyped vectors. Analysis of individual myeloid colonies demonstrated that retrovirus vectors with FeLV-C and RD114 pseudotypes were present at 1.5 to 1.6 copies per cell and were preferentially integrated near known genes We conclude that the more efficient transduction of human HSCs with either FeLV-C- or RD114-pseudotyped retroviral particles may improve gene transfer in human clinical trials.", "journal": "Blood", "doi": "10.1182/blood-2004-11-4491", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1676325246, 1676318081, 1519315556, 1519241848", "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15767400", "author": "Roca AL", "n_authors": 5, "title": "Insertional polymorphisms of endogenous feline leukemia viruses.", "abstract": "The number, chromosomal distribution, and insertional polymorphisms of endogenous feline leukemia viruses (enFeLVs) were determined in four domestic cats (Burmese, Egyptian Mau, Persian, and nonbreed) using fluorescent in situ hybridization and radiation hybrid mapping. Twenty-nine distinct enFeLV loci were detected across 12 of the 18 autosomes. Each cat carried enFeLV at only 9 to 16 of the loci, and many loci were heterozygous for presence of the provirus. Thus, an average of 19 autosomal copies of enFeLV were present per cat diploid genome. Only five of the autosomal enFeLV sites were present in all four cats, and at only one autosomal locus, B4q15, was enFeLV present in both homologues of all four cats. A single enFeLV occurred in the X chromosome of the Burmese cat, while three to five enFeLV proviruses occurred in each Y chromosome. The X chromosome and nine autosomal enFeLV loci were telomeric, suggesting that ectopic recombination between nonhomologous subtelomeres may contribute to enFeLV distribution. Since endogenous FeLVs may affect the infectiousness or pathogenicity of exogenous FeLVs, genomic variation in enFeLVs represents a candidate for genetic influences on FeLV leukemogenesis in cats.", "journal": "Journal of virology", "doi": "10.1128/JVI.79.7.3979-3986.2005", "deposited_data": "Sim", "nuccore_ids": "38176360, 38176359, 38176358", "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15661159", "author": "Torres AN", "n_authors": 3, "title": "Re-examination of feline leukemia virus: host relationships using real-time PCR.", "abstract": "The mechanisms responsible for effective vs. ineffective viral containment are central to immunoprevention and therapies of retroviral infections. Feline leukemia virus (FeLV) infection is unique as a naturally occurring, diametric example of effective vs. ineffective retroviral containment by the host. We developed a sensitive quantitative real-time DNA PCR assay specific for exogenous FeLV to further explore the FeLV-host relationship. By assaying p27 capsid antigen in blood and FeLV DNA in blood and tissues of successfully vaccinated, unsuccessfully vaccinated, and unvaccinated pathogen-free cats, we defined four statistically separable classes of FeLV infection, provisionally designated as abortive, regressive, latent, and progressive. These host-virus relationships were established by 8 weeks post-challenge and could be maintained for years. Real-time PCR methods offer promise in gaining deeper insight into the mechanisms of FeLV infection and immunity.", "journal": "Virology", "doi": "10.1016/j.virol.2004.10.050", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15650172", "author": "Bupp K", "n_authors": 3, "title": "Probing sequence variation in the receptor-targeting domain of feline leukemia virus envelope proteins with peptide display libraries.", "abstract": "Determinants of cellular tropism and receptor targeting lie within a short peptide in the Vr1 region of the envelope (Env) proteins of feline leukemia virus (FeLV) subgroups A and C. Libraries of FeLV Env proteins with random amino acid substitutions in the peptide were screened for their ability to deliver a marker gene to D17 and AH927 cells. Screening on D17 canine cells yielded D17-specific Env proteins that used the FeLV-C receptor. Screening on AH927 cells yielded Env proteins with a broader host range, with maximal titers on AH927 cells and similar or lower titers on other cells. These Env proteins used an unidentified non-FeLV receptor for entry. The A5 isolate obtained from the AH927 screen was readily concentrated to yield titers of 10(5) on human PC-3 prostate tumor cells. The sequence divergence observed among targeting peptides of library-selected Env proteins was greater than that found in parental FeLV isolates. Substitution analyses of a conserved R in the middle of the targeting peptide held constant during screening indicated that maximal titers were obtained only when R was present in both a D17 selected isolate and an AH927 selected isolate. The ability to isolate Env proteins with unique tropisms dependent on the cells on which the library is screened has direct implications for targeting gene delivery vectors.", "journal": "Journal of virology", "doi": "10.1128/JVI.79.3.1463-1469.2005", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15650161", "author": "Chandhasin C", "n_authors": 3, "title": "Subtle mutational changes in the SU protein of a natural feline leukemia virus subgroup A isolate alter disease spectrum.", "abstract": "FeLV-945 is a representative isolate of the natural feline leukemia virus (FeLV) variant predominant in non-T-cell malignant, proliferative, and degenerative diseases in a geographic cohort. The FeLV-945 surface glycoprotein (SU) is closely related to natural horizontally transmissible FeLV subgroup A (FeLV-A) but was found to differ from a prototype to a larger extent than the members of FeLV-A differ among themselves. The sequence differences included point mutations restricted largely to the functional domains of SU, i.e., VRA, VRB, and PRR. Despite the sequence differences in these critical domains, measurements of receptor utilization, including host range and superinfection interference, confirmed the assignment of FeLV-945 to subgroup A. Other proviruses isolated from the cohort contained similar sequence hallmarks and were assigned to FeLV subgroup A. A provirus from cat 1046 contained a histidine-to-proline change at SU residue 6 within an SPHQ motif that was previously identified as a critical mediator of fusion events during virus entry. The 1046 pseudotype virus entered cells only in the presence of the soluble cofactor FeLIX provided in trans, but it retained an ecotropic host range even in the presence of FeLIX. The mutational changes in FeLV-945 were shown to confer significant functional differences compared to prototype FeLV-A viruses. The substitution of FeLV-945 envelope gene sequences for FeLV-A/61E sequences conferred a small but statistically significant replicative advantage in some feline cells. Moreover, substitution of the unique FeLV-945 long terminal repeat and envelope gene for those of FeLV-A/61E altered the disease spectrum entirely, from a thymic lymphoma of a T-cell origin to an as yet uncharacterized multicentric lymphoma that did not contain T cells.", "journal": "Journal of virology", "doi": "10.1128/JVI.79.3.1351-1360.2005", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15596801", "author": "Johnson C", "n_authors": 4, "title": "Substitution of feline leukemia virus long terminal repeat sequences into murine leukemia virus alters the pattern of insertional activation and identifies new common insertion sites.", "abstract": "The recombinant retrovirus, MoFe2-MuLV (MoFe2), was constructed by replacing the U3 region of Moloney murine leukemia virus (M-MuLV) with homologous sequences from the FeLV-945 LTR. NIH/Swiss mice neonatally inoculated with MoFe2 developed T-cell lymphomas of immature thymocyte surface phenotype. MoFe2 integrated infrequently (0 to 9%) near common insertion sites (CISs) previously identified for either parent virus. Using three different strategies, CISs in MoFe2-induced tumors were identified at six loci, none of which had been previously reported as CISs in tumors induced by either parent virus in wild-type animals. Two of the newly identified CISs had not previously been implicated in lymphoma in any retrovirus model. One of these, designated 3-19, encodes the p101 regulatory subunit of phosphoinositide-3-kinase-gamma. The other, designated Rw1, is predicted to encode a protein that functions in the immune response to virus infection. Thus, substitution of FeLV-945 U3 sequences into the M-MuLV long terminal repeat (LTR) did not alter the target tissue for M-MuLV transformation but significantly altered the pattern of CIS utilization in the induction of T-cell lymphoma. These observations support a growing body of evidence that the distinctive sequence and/or structure of the retroviral LTR determines its pattern of insertional activation. The findings also demonstrate the oligoclonal nature of retrovirus-induced lymphomas by demonstrating proviral insertions at CISs in subdominant populations in the tumor mass. Finally, the findings demonstrate the utility of novel recombinant retroviruses such as MoFe2 to contribute new genes potentially relevant to the induction of lymphoid malignancy.", "journal": "Journal of virology", "doi": "10.1128/JVI.79.1.57-66.2005", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15563922", "author": "Nagashima N", "n_authors": 6, "title": "In vitro selective suppression of feline myeloid colony formation is attributable to molecularly cloned strain of feline leukemia virus with unique long terminal repeat.", "abstract": "Molecularly cloned feline leukemia virus (FeLV)-clone 33 (C-33), derived from a cat with acute myelocytic leukemia (AML), was examined to assess its relation to the pathogenesis of AML and myelodysplastic syndrome (MDS). To evaluate in vitro pathogenicity of FeLV C-33, bone marrow colony-forming assay was performed on marrow cells infected with FeLV C-33 or an FeLV subgroup A strain (61E, a molecularly cloned strain with minimal pathogenicity). The myeloid colony-forming activity of feline bone marrow mononuclear cells infected with FeLV C-33 was significantly lower than that of cells infected with 61E. This suggests that FeLV C-33 has myeloid lineage-specific pathogenicity for cats, and that FeLV C-33 infection is useful as an experimental model for investigating pathogenesis of MDS and AML.", "journal": "Research in veterinary science", "doi": "10.1016/j.rvsc.2004.07.003", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "17123256", "author": "Grondin TM", "n_authors": 4, "title": "Blood smear from a cat: features to \"dys\"cover.", "abstract": "A 4-year-old, spayed female, domestic shorthair cat was presented for lethargy, nonregenerative anemia, and inappetence. Results of a CBC included macrocytic, normochromic, nonregenerative anemia and a glucocorticoid-associated leukogram. On blood smear examination, neutrophils had abnormal features including hyposegmentation and a diffuse chromatin pattern with nuclear filament formation and nuclear blebbing. Microscopic examination of a roll preparation of bone marrow revealed hypolobulated megakaryocytes with asynchronous maturation of nuclei. The granulocytic to erythrocyte (G:E) ratio was 76. Segmented neutrophils had asynchronous maturation and dysplastic features. The entire erythroid lineage was markedly decreased for the degree of anemia and rare dysplastic features were noted in erythroid precursor cells. The interpretation of bone marrow findings was erythroid hypoplasia, megakaryocytic dysplasia, and granulocytic hyperplasia with dysplasia. Histopathologic examination of a bone marrow core sample also revealed myeloid hyperplasia and erythroid hypoplasia. The result of a direct immunofluorescence assay for FeLV performed on the bone marrow roll preparation was positive. A diagnosis of dysmyelopoiesis associated with FeLV infection was made. This case was unique in that the dysplastic changes occurred in cell lines that did not have associated cytopenias. The dysmyelopoiesis most closely resembled myelodysplastic syndrome with refractory cytopenia (MDS-RC); however, secondary dysmyelopoiesis could not be ruled out.", "journal": "Veterinary clinical pathology", "doi": "10.1111/j.1939-165x.2006.tb00166.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "17123254", "author": "Gelain ME", "n_authors": 5, "title": "Chronic eosinophilic leukemia in a cat: cytochemical and immunophenotypical features.", "abstract": "A 3-year-old, male, domestic shorthaired cat was presented with a 3-day history of anorexia and depression. The cat was moderately dehydrated, had pale, slightly icteric, mucous membranes, oral ulcerations, and mild hepatosplenomegaly. A feline leukemia virus (FeLV) antigen test was positive. CBC results obtained at initial presentation included severe normocytic, normochromic, nonregenerative anemia, severe thrombocytopenia, and marked leukocytosis (>100,000/microL) with 77% eosinophils. After 15 days of treatment with prednisone and doxycycline, the cat had persistent severe nonregenerative anemia (HCT 3.4%), thrombocytopenia (28,000/microL), and extreme eosinophilia (total eosinophils, 123.1 x 10(3)/microL; segmented 103.0 x 10(3)/microL; immature 20.1 X 10(3)/microL). Cytologic examination of aspirates from bone marrow, liver, lymph nodes, and spleen revealed a predominance of mature and immature eosinophils, many with dysplastic changes. The M:E ratio was 96.4. On histopathologic examination, multiple organs were infiltrated by eosinophilic granulocytes. Neoplastic cells in blood and bone marrow stained positive for alkaline phosphatase and were negative for myeloperoxidase, chloroacetate esterase, and alpha-naphthyl acetate esterase. On flow cytometric analysis of peripheral blood, the neoplastic cells were positive for CD11b and CD14. These findings were consistent with chronic eosinophilic leukemia. To our knowledge, this is the first report of chronic eosinophilic leukemia in a cat associated with naturally acquired FeLV infection, in which flow cytometry was used to characterize the neoplastic cells.", "journal": "Veterinary clinical pathology", "doi": "10.1111/j.1939-165x.2006.tb00164.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "17092900", "author": "Driciru M", "n_authors": 8, "title": "A serosurvey of viral infections in lions (Panthera leo), from Queen Elizabeth National Park, Uganda.", "abstract": "Serum samples from 14 lions (Panthera leo) from Queen Elizabeth National Park, Uganda, were collected during 1998 and 1999 to determine infectious disease exposure in this threatened population. Sera were analyzed for antibodies against feline immunodeficiency virus (FIV), feline calicivirus (FCV), feline herpesvirus 1 (feline rhinotracheitis: FHV1), feline/canine parvovirus (FPV/CPV), feline infectious peritonitis virus (feline coronavirus: FIPV), and canine distemper virus (CDV) or for the presence of feline leukemia virus (FeLV) antigens. Ten lions (71%) had antibodies against FIV, 11 (79%) had antibodies against CDV, 11 (79%) had antibodies against FCV, nine (64%) had antibodies against FHV1, and five (36%) had antibodies against FPV. Two of the 11 CDV-seropositive lions were subadults, indicating recent exposure of this population to CDV or a CDV-like virus. No lions had evidence of exposure to FeLV or FIPV. These results indicate that this endangered population has extensive exposure to common feline and canine viruses.", "journal": "Journal of wildlife diseases", "doi": "10.7589/0090-3558-42.3.667", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "17063707", "author": "Ottenjann M", "n_authors": 4, "title": "Characterization of the anemia of inflammatory disease in cats with abscesses, pyothorax, or fat necrosis.", "abstract": "The purpose of this study was to describe the anemia of inflammatory disease (AID) in cats with naturally-occurring inflammatory diseases, such as abscesses (n = 12), pyothorax (n = 6), and fat necrosis (n = 3). Exclusion criteria were positive FeLV/FIV tests, neoplasia, nephro-, hepato- or endocrinopathies, and blood loss anemia. CBC, clinical biochemistry, measurements of serum erythropoietin, iron, total iron-binding capacity (TIBC), ferritin, acute phase proteins, erythrocytic osmotic fragility (OF), and Coombs' tests were performed. A decrease in hematocrit of 1-28% (median, 10%) occurred within 3-16 days (median, 8 days). The anemia was mild (n = 11), moderate (n = 8), or severe (n = 2). In most cases it was normocytic normochromic, non-regenerative (n = 18), or mildly regenerative (n = 3). Sixteen cats had leukocytosis and 5 mild hyperbilirubinemia. The Coombs' test results were negative for 8 cats and positive for 1 cat. OF was increased in 2 out of 14 cats. Hypoalbuminemia (n = 18) and hyperglobulinemia (n = 16) resulted in a lowered albumin/globulin-ratio in 19 cats. Iron and TIBC were low in 2/19 and 6 /19 cats, respectively. The ferritin concentrations were normal in 7 cats and increased in 12 cats. The acute phase proteins alpha1-acid-glycoprotein and haptoglobin were increased in 14/14 and 13/14 cats, respectively. Erythropoietin was normal (n = 4), mildly increased (n = 7) or severely increased (1). Two cats were euthanized due to their underlying disease, 3 cats needed blood transfusions. AID in cats is usually mild to moderate, non-regenerative, and normocytic normochromic. It can be clinically relevant causing severe and transfusion-dependent anemia. AID seems to be multifactorial with evidence of iron sequestration, decreased RBC survival, and insufficient erythropoietin production and bone marrow response. Specific and supportive therapy, including transfusions, can reverse these processes.", "journal": "Journal of veterinary internal medicine", "doi": "10.1892/0891-6640(2006)20[1143:cotaoi]2.0.co;2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16919405", "author": "Solano-Gallego L", "n_authors": 5, "title": "Serological and molecular evidence of exposure to arthropod-borne organisms in cats from northeastern Spain.", "abstract": "One hundred sixty-eight cat sera from Spain were tested for IgG antibodies to Rickettsia conorii (Rc), Ehrlichia canis (Ec), Anaplasma phagocytophilum (Ap) and Bartonella henselae (Bh) antigens using IFA and for FeLV antigen and FIV antibody by ELISA. For 47 whole blood samples, PCR testing was performed for Rickettsia, Ehrlichia and Bartonella. Seroprevalences were: Bh (71.4%), Rc (44%), Ec (11.3%), FeLV (8.5%), FIV (7.4%) and Ap (1.8%). Bh antibodies were associated with seroreactivity to both Ec and Rc antigens. FIV antibodies were associated with illness and cats older than 2 years. Bartonella henselae and B. clarridgeiae (Bcl) DNA was amplified from seven and one sample, respectively.", "journal": "Veterinary microbiology", "doi": "10.1016/j.vetmic.2006.07.010", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16870878", "author": "Filoni C", "n_authors": 7, "title": "First evidence of feline herpesvirus, calicivirus, parvovirus, and Ehrlichia exposure in Brazilian free-ranging felids.", "abstract": "Serum samples from 18 pumas (Puma concolor), one ocelot (Leopardus pardalis), and two little spotted cats (Leopardus tigrinus) collected from free-ranging animals in Brazil between 1998 and 2004 were tested by indirect immunofluorescence (IFA) for antibodies to feline herpesvirus 1 (FHV 1), calicivirus (FCV), coronavirus (FCoV), parvo-virus (FPV), Ehrlichia canis, Anaplasma pha-gocytophilum, and Bartonella henselae. Serum samples also were tested, by Western blot and ELISA, for feline leukemia virus (FeLV) specific antibodies and antigen, respectively, by Western blot for antibodies to feline immunodeficiency virus (FIV), and by indirect ELISA for antibodies to puma lentivirus (PLV). Antibodies to FHV 1, FCV, FCoV, FPV, FeLV, FIV, PLV or related viruses, and to B. henselae were detected. Furthermore, high-titered antibodies to E. canis or a closely related agent were detected in a puma for the first time.", "journal": "Journal of wildlife diseases", "doi": "10.7589/0090-3558-42.2.470", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16730653", "author": "Shojima T", "n_authors": 3, "title": "Host cell range of T-lymphotropic feline leukemia virus in vitro.", "abstract": "We compared the host cell range of T-lymphotropic feline leukemia virus (FeLV-T) with that of FeLV subgroup B (FeLV-B) by pseudotype assay in the presence of FeLIX, a truncated envelope glycoprotein of endogenous FeLV. Although both viruses use Pit1 as a receptor and FeLIX does not hamper FeLV-B infection by receptor interference, the host ranges of FeLV-T and -B were not exactly the same, suggesting a different Pit1 usage at the post-binding level. A comparison of Pit1 sequences of various mammalian species indicated that extracellular loop 1 in a topology model deduced with the PHD PredictProtein algorism may be one of the regions responsible for efficient infection by FeLV-T.", "journal": "Biochemical and biophysical research communications", "doi": "10.1016/j.bbrc.2006.05.039", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16678875", "author": "Bupp K", "n_authors": 3, "title": "Selection of feline leukemia virus envelope proteins from a library by functional association with a murine leukemia virus envelope.", "abstract": "Libraries of feline leukemia virus subgroup A (FeLV-A)-derived envelope (Env) proteins with random peptides incorporated into the cell-targeting region were screened for productive gene delivery to the PC-3 human prostate cell line. In order to increase the efficiency of recovering and testing functional clones, the screen was performed in the presence of a replication-competent 4070A Env-expressing virus under conditions of viral interference. The Env proteins resulting from this library screen were able to mediate gene delivery to 4070A-infected human PC-3, DU145 prostate and TE671 rhabdomyosarcoma cells in the presence, but not absence, of 4070A helper virus. FeLV-A, FeLV-B and Moloney murine leukemia virus (Mo-MuLV) Env proteins were unable to substitute for 4070A Env. Flow cytometry and Western blot analyses indicated increased cell-surface expression and virion incorporation of library-derived Env proteins in the presence of 4070A Env. Interference assays on cells infected with both 4070A and FeLV-B are consistent with the combination of library-derived and 4070A Env proteins utilizing the Pit1 receptor.", "journal": "Virology", "doi": "10.1016/j.virol.2006.03.040", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16645348", "author": "Seo KW", "n_authors": 7, "title": "Mediastinal lymphoma in a young Turkish Angora cat.", "abstract": "An 8-month old intact male Turkish Angora cat was referred to the veterinary Medical Teaching Hospital (VMTH), Seoul National University, for an evaluation of anorexia and severe dyspnea. The thoracic radiographs revealed significant pleural effusion. A cytology evaluation of the pleural fluid strongly suggested a lymphoma containing variable sized lymphocytes with frequent mitotic figures and prominent nucleoli. The feline leukemia virus and feline immunodeficiency virus tests were negative. The cat was euthanized at his owner's request and a necropsy was performed. A mass was detected on the mediastinum and lung lobes. A histopathology evaluation confirmed the mass to be a lymphoma. Immunohistochemistry revealed the mass to be CD3 positive. In conclusion, the cat was diagnosed as a T-cell mediastinal lymphoma.", "journal": "Journal of veterinary science", "doi": "10.4142/jvs.2006.7.2.199", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16632529", "author": "Bandecchi P", "n_authors": 5, "title": "Feline leukaemia virus (FeLV) and feline immunodeficiency virus infections in cats in the Pisa district of Tuscany, and attempts to control FeLV infection in a colony of domestic cats by vaccination.", "abstract": "The seroprevalence of feline immunodeficiency virus (FIV) in 203 apparently healthy domestic cats living in the district of Pisa, central Italy, was 11.3 per cent, and the prevalence of feline leukaemia virus (FeLV) was 8.4 per cent. The prevalence of FIV depended significantly on the lifestyle and age of the cats; cats living outdoors were more likely to be FIV-positive than cats living indoors, and the proportion of FIV-positive cats increased with age. In contrast, there was no significant relationship between these variables and the prevalence of FeLV. There was no significant relationship between the cats' seropositivity for FIV and FeLV. The results of a five-year field study to control FeLV infection by vaccination in a colony of 30 domestic adult cats naturally exposed to the infection suggest that the vaccination was effective in FIV-negative cats, but failed to protect FIV-positive cats against FeLV.", "journal": "The Veterinary record", "doi": "10.1136/vr.158.16.555", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16616569", "author": "Kohn B", "n_authors": 3, "title": "Platelet-bound antibodies detected by a flow cytometric assay in cats with thrombocytopenia.", "abstract": "In cats, primary or secondary immune-mediated thrombocytopenia have rarely been described or characterised. The objective of this study was to determine platelet-bound antibodies (PBA) by a flow cytometric assay in both healthy and thrombocytopenic cats. Direct PBA testing was performed in 42 thrombocytopenic cats (platelet counts 6-179 x 10(9)/l, median 56 x 10(9)/l). Of these 42 cats, 19 had positive PBA test results, 17 of which were considered to have secondary immune-mediated thrombocytopenia (sITP). Underlying diseases included fat necroses (four cases), feline infectious peritonitis (three), feline leukaemia virus (two) or feline immunodeficiency virus (two) infections, lymphoma (two), leukaemia (one), hepatitis (one), pyelonephritis (one), or hyperthyroidism (one). In two cats, no underlying disease was found suggesting a primary immune-mediated thrombocytopenia (pITP). The PBA test was negative in 23 cats diagnosed with varying underlying diseases and in 47 healthy control cats with platelet values within the reference range. Only seven of the 42 cats with thrombocytopenia (platelet count 10-57 x 10(9)/l, median 34 x 10(9)/l) had spontaneous bleeding. This study suggests that immune-mediated destruction of platelets might be an important pathological mechanism for feline thrombocytopenia caused by various underlying diseases. In cats, pITP appears to be rarely diagnosed.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2006.01.006", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16562725", "author": "Willi B", "n_authors": 8, "title": "[Feline hemoplasmas in Switzerland: identification of a novel species, diagnosis, prevalence, and clinical importance].", "abstract": "Two feline hemotropic mycoplasma spp. (aka hemoplasma) have previously been recognized. We recently discovered a third novel species in a cat with hemolytic anemia, designated 'Candidatus Mycoplasma turicensis', which is closely related to rodent haemoplasmas. This novel species induced anemia after experimental transmission to two SPF cats. Three quantitative real-time PCR assays were newly designed and applied to an epidemiological study surveying the Swiss pet cat population. Blood samples from 713 healthy and ill cats were analyzed. Up to 104 parameters per cat (detailed questionnaire, case history, laboratory parameters and retroviral infections) were evaluated. 'Candidatus Mycoplasma haemominutum' infection was more prevalent (8.5%) than Mycoplasma haemofelis (0.5%) and 'Candidatus Mycoplasma turicensis' (1%). Hemoplasma infections were associated with male gender, outdoor access, and old age, but not with disease or anemia. Infections were more frequently found in the South and West of Switzerland. Several hemoplasma infected cats, some acutely infected, others co-infected with FIV or FeLV, showed hemolytic anemia indicating that additional factors might play a role in the pathogenesis of the disease.", "journal": "Schweizer Archiv fur Tierheilkunde", "doi": "10.1024/0036-7281.148.3.139", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16537605", "author": "Mendoza R", "n_authors": 3, "title": "A putative thiamine transport protein is a receptor for feline leukemia virus subgroup A.", "abstract": "Feline leukemia virus (FeLV) is a horizontally transmitted virus that causes a variety of proliferative and immunosuppressive diseases in cats. There are four subgroups of FeLV, A, B, C, and T, each of which has a distinct receptor requirement. The receptors for all but the FeLV-A subgroup have been defined previously. Here, we report the identification of the cellular receptor for FeLV-A, which is the most transmissible form of FeLV. The receptor cDNA was isolated using a gene transfer approach, which involved introducing sequences from a feline cell line permissive to FeLV-A into a murine cell line that was not permissive. The feline cDNA identified by this method was approximately 3.5 kb, and included an open reading frame predicted to encode a protein of 490 amino acids. This feline cDNA conferred susceptibility to FeLV-A when reintroduced into nonpermissive cells, but it did not render these cells permissive to any other FeLV subgroup. Moreover, these cells specifically bound FeLV-A-pseudotyped virus particles, indicating that the cDNA encodes a binding receptor for FeLV-A. The feline cDNA shares approximately 93% amino acid sequence identity with the human thiamine transport protein 1 (THTR1). The human THTR1 receptor was also functional as a receptor for FeLV-A, albeit with reduced efficiency compared to the feline orthologue. On the basis of these data, which strongly suggest the feline protein is the orthologue of human THTR1, we have named the feline receptor feTHTR1. Identification of this receptor will allow more detailed studies of the early events in FeLV transmission and may provide insights into FeLV pathogenesis.", "journal": "Journal of virology", "doi": "10.1128/JVI.80.7.3378-3385.2006", "deposited_data": "Sim", "nuccore_ids": "90403621, 89112747, 2131068042, 90403621", "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16517884", "author": "Willi B", "n_authors": 10, "title": "Prevalence, risk factor analysis, and follow-up of infections caused by three feline hemoplasma species in cats in Switzerland.", "abstract": "Recently, a third novel feline hemotropic Mycoplasma sp. (aka hemoplasma), \"Candidatus Mycoplasma turicensis,\" in a cat with hemolytic anemia has been described. This is the first study to investigate the prevalence, clinical manifestations, and risk factors for all three feline hemoplasma infections in a sample of 713 healthy and ill Swiss cats using newly designed quantitative real-time PCR assays. \"Candidatus Mycoplasma haemominutum\" infection was detected in 7.0% and 8.7% and Mycoplasma haemofelis was detected in 2.3% and 0.2% of healthy and ill cats, respectively. \"Candidatus Mycoplasma turicensis\" was only detected in six ill cats (1.1%); three of them were coinfected with \"Candidatus Mycoplasma haemominutum.\" The 16S rRNA gene sequence of 12 Swiss hemoplasma isolates revealed >98% similarity with previously published sequences. Hemoplasma infection was associated with male gender, outdoor access, and old age but not with retrovirus infection and was more frequent in certain areas of Switzerland. \"Candidatus Mycoplasma haemominutum\"-infected ill cats were more frequently diagnosed with renal insufficiency and exhibited higher renal blood parameters than uninfected ill cats. No correlation between hemoplasma load and packed cell volume was found, although several hemoplasma-infected cats, some coinfected with feline immunodeficiency virus or feline leukemia virus, showed hemolytic anemia. High M. haemofelis loads (>9 x 10(5) copies/ml blood) seem to lead to anemia in acutely infected cats but not in recovered long-term carriers. A repeated evaluation of 17 cats documented that the infection was acquired in one case by blood transfusion and that there were important differences among species regarding whether or not antibiotic administration led to the resolution of bacteremia.", "journal": "Journal of clinical microbiology", "doi": "10.1128/JCM.44.3.961-969.2006", "deposited_data": "Sim", "nuccore_ids": "946542397, 77737031, 77737030, 77737029, 77737028, 77737027, 77737026, 77737025, 77737023, 77737022, 77737021, 77737020, 77737019, 77737018, 77737017, 77737016, 77737015, 77737014, 77737013, 77737012", "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16517876", "author": "Gomes-Keller MA", "n_authors": 7, "title": "Detection of feline leukemia virus RNA in saliva from naturally infected cats and correlation of PCR results with those of current diagnostic methods.", "abstract": "A novel diagnostic test for feline leukemia virus (FeLV) RNA in saliva from naturally infected cats is described in this study. We evaluated different diagnostic tests and compared them with the widely used enzyme-linked immunosorbent assay (ELISA) for the detection of p27 in the diagnosis of FeLV. Blood samples from 445 cats were tested for the presence of provirus by real-time PCR and plasma and saliva specimens from those cats were tested for the presence of viral RNA by real-time reverse transcription (RT)-PCR and for the presence of p27 by ELISA. In comparison to conventional ELISA, the diagnostic sensitivity and specificity of the detection of salivary FeLV RNA by real-time RT-PCR were found to be 98.1 and 99.2%, respectively. Detection of viral RNA in saliva had a positive predictive value of 94.6% and a negative predictive value of 99.7%. The kappa value was 0.96, demonstrating an almost perfect agreement between both tests. Furthermore, we confirmed previous results showing that a number of cats which tested negative for the presence of p27 in plasma were in fact positive for the presence of DNA provirus in blood specimens (5.4%). However, 96.4% of these latently infected cats did not shed viral RNA in saliva; therefore, we assume that these cats are of relatively low clinical importance at the time of testing. This study shows considerable diagnostic value of the detection of saliva FeLV RNA in naturally infected cats. This new diagnostic method has advantages over the conventional ELISA, such as less invasive sample collection and no requirement for trained personnel.", "journal": "Journal of clinical microbiology", "doi": "10.1128/JCM.44.3.916-922.2006", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16506935", "author": "Grosenbaugh DA", "n_authors": 3, "title": "Protection from challenge following administration of a canarypox virus-vectored recombinant feline leukemia virus vaccine in cats previously vaccinated with a killed virus vaccine.", "abstract": "To compare protection against FeLV challenge obtained following administration of 2 doses of an adjuvanted, chemically inactivated, whole FeLV (FeLV-k) vaccine with protection obtained following administration of 1 dose of an FeLV-k vaccine followed by 1 dose of a canarypox virus-vectored recombinant FeLV (rCP-FeLV) vaccine. Prospective study. Thirty-two 9-week-old domestic shorthair cats. Cats received 2 doses of the FeLV-k vaccine SC, 21 days apart (n = 11); 1 dose of the FeLV-k vaccine SC and, 21 days later, 1 dose of the rCP-FeLV vaccine transdermally (11); or 2 doses of physiologic saline (0.9% NaCl) solution (control; 10). Four weeks after the second vaccine dose, all cats were challenged with FeLV by means of oronasal administration. Blood samples were collected at weekly intervals beginning 21 days after challenge, and serum was tested for FeLV antigen. All 10 control cats became persistently infected (ie, FeLV antigen detected in > or = 3 consecutive serum samples) following FeLV challenge, whereas only 1 of 11 cats that received 2 doses of the FeLV-k vaccine and none of the 11 cats that received 1 dose of the FeLV-k vaccine and 1 dose of the rCP-FeLV vaccine did. Results suggest that protection against FeLV challenge obtained following SC administration of a single dose of an FeLV-k vaccine followed, 21 days later, by transdermal administration of a single dose of an rCP-FeLV vaccine was similar to that obtained following SC administration of 2 doses of the FeLV-k vaccine 21 days apart.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.228.5.726", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16496936", "author": "Kohn B", "n_authors": 5, "title": "Primary immune-mediated hemolytic anemia in 19 cats: diagnosis, therapy, and outcome (1998-2004).", "abstract": "Immune-mediated hemolytic anemia (IMHA) occurs less frequently in cats than in dogs. The value of the Coombs' test (CT) has been questioned, but detailed surveys of its use are lacking. The objective of this study was to describe 19 cats with primary IMHA (pIMHA) and to examine the diagnostic value of the direct CT. The CT was performed in 92 cats; it was negative in 5 healthy, in 9 sick nonanemic, and in 55 cats with different types of anemia. The CT was positive in 18 anemic cats (2 feline leukemia virus (FeLV) positive, 1 with cholangiohepatitis, 15 with no underlying disease). Moreover, agglutination persisted after saline washing in 5 anemic cats (1 lymphoma, 4 pIMHA). Inclusion criteria for pIMHA were a positive CT (15) or persistent agglutination (4), and the exclusion of other diseases. The age of the 19 cats ranged from 0.5 to 9 years (median, 2 years); male cats were overrepresented. The PCV on admission was 6-22% (median, 12%). The anemia was nonregenerative in 11 cats. Additional abnormal laboratory results were leukocytosis (2), lymphocytosis (6), hyperbilirubinemia (13), hyperglobulimemia (10), and increased liver enzyme activities (10). Initial treatment consisted of blood transfusions (10), crystalloids (11), prednisolone (19), antibiotics (19), and H2-blockers (11). Four of 17 cats were euthanized 9, 63, 240 and 2,160 days after initial presentation (mortality rate, 23.5%). Relapses were reported in 5 of 16 cases (31%). Thus, pIMHA appears to occur more frequently than recognized previously, with a more favorable prognosis in cats than in dogs. The CT was useful in identifying immune-mediated pathogenesis.", "journal": "Journal of veterinary internal medicine", "doi": "10.1892/0891-6640(2006)20[159:pihaic]2.0.co;2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16488115", "author": "Cattori V", "n_authors": 5, "title": "Rapid detection of feline leukemia virus provirus integration into feline genomic DNA.", "abstract": "Feline leukemia virus (FeLV) is a gamma retrovirus that induces fatal diseases in domestic cats. Efficacious FeLV vaccines prevent persistent viremia and development of FeLV-related disease after virus exposure, but not minimal viral replication and a provirus-positive state as recently demonstrated using sensitive real-time PCR assays. Proviral integration is an important parameter of latent infection and persistence of retroviruses in infected cells. So far, FeLV-specific real-time PCR assays could not distinguish between the integrated and episomal forms of the provirus. Thus, it was the aim of the present study to develop a rapid assay for the detection of FeLV proviral integration. The test combines conventional and quantitative real-time PCR that use virus-specific primers and primers specific for cat genomic small interspersed nuclear elements. It was applied to analyze the time course of proviral integration into the genome of a feline fibroblast cell line and detect provirus integration in peripheral white blood cells from vaccinated and unvaccinated, FeLV-exposed cats. The newly developed rapid test will essentially contribute to a better understanding of the mechanisms involved in the pathogenesis of FeLV infection and be especially useful in the development of antiretroviral vaccines and therapies aimed at the inhibition of proviral integration.", "journal": "Molecular and cellular probes", "doi": "10.1016/j.mcp.2005.11.007", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16448357", "author": "Levy JK", "n_authors": 4, "title": "Seroprevalence of feline leukemia virus and feline immunodeficiency virus infection among cats in North America and risk factors for seropositivity.", "abstract": "To determine seroprevalence of FeLV and FIV infection among cats in North America and risk factors for seropositivity. Prospective cross-sectional survey. 18,038 cats tested at 345 veterinary clinics (n=9,970) and 145 animal shelters (8,068) between August and November 2004. Cats were tested with a point-of-care ELISA for FeLV antigen and FIV antibody. A multivariable random effects logistic regression model was used to identify risk factors significantly associated with seropositivity while accounting for clinic-to-clinic (or shelter) variability. 409 (2.3%) cats were seropositive for FeLV antigen, and 446 (2.5%) cats were seropositive for FIV antibody; 58 (0.3%) cats were seropositive for infection with both viruses. Multivariable analysis indicated that age, sex, health status, and cat lifestyle and source were significantly associated with risk of seropositivity, with adults more likely to be seropositive than juveniles (adjusted odds ratios [ORs], 2.5 and 2.05 for FeLV and FIV seropositivity, respectively), sexually intact adult males more likely to be seropositive than sexually intact adult females (adjusted ORs, 2.4 and 4.66), and outdoor cats that were sick at the time of testing more likely to be seropositive than healthy indoor cats (adjusted ORs, 8.89 and 11.3). Results suggest that certain characteristics, such as age, sex, health status, and lifestyle, are associated with risk of FeLV and FIV seropositivity among cats in North America. However, cats in all categories were found to be at risk for infection, and current guidelines to test all cats at the time of acquisition and again during illness should be followed.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.228.3.371", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16439531", "author": "Brown JK", "n_authors": 3, "title": "Comprehensive mapping of receptor-functioning domains in feline leukemia virus subgroup C receptor FLVCR1.", "abstract": "Infection of cells by the highly anemogenic feline leukemia virus subgroup C (FeLV-C) is mediated by the heme exporter FLVCR1, a cell surface protein containing 12 potential transmembrane segments with six presumptive extracellular loops (ECLs). To identify FLVCR1 residues critical for mediating FeLV-C infection, we first independently isolated a human cDNA encoding the FLVCR2 protein that shares 52% identity to human FLVCR1, and we show that FLVCR2 does not function as a receptor for FeLV-C. Then, by generating specific hybrids between FLVCR1 and FLVCR2 and testing susceptibility of mouse cells expressing these hybrids to beta-galactosidase encoding FeLV-C, we identify FLVCR1 ECLs 1 and 6 as critical for mediating FeLV-C infection. Mouse cells expressing a hybrid protein containing FLVCR2 backbone with the ECL6 sequence from FLVCR1 were highly susceptible to FeLV-C infection. Using site-directed mutagenesis, we show that a single mutation of Asn463 in FLVCR2 ECL6 to an acidic Asp residue (a residue present in the corresponding position 487 in FLVCR1 ECL6) is sufficient to render FLVCR2 functional as an FeLV-C receptor. However, an Asp487Asn mutation in FLVCR1 ECL6 or substitution of the entire FLVCR1 ECL6 sequence for FLVCR2 ECL6 sequence does not disrupt receptor function. Subsequent substitutions show that residues within FLVCR1 ECL1 also contribute to mediating FeLV-C infection. Furthermore, our results suggest that FLVCR1 regions that mediate FeLV-C surface unit binding are distinct from ECL1 and ECL6. Our results are consistent with previous conclusions that infection of cells by gammaretroviruses involves interaction of virus with multiple receptor regions.", "journal": "Journal of virology", "doi": "10.1128/JVI.80.4.1742-1751.2006", "deposited_data": "Sim", "nuccore_ids": "1675021395, 1519316194, 306518570, 27462641, 2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1675021395, 1519316194, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16439518", "author": "Cheng HH", "n_authors": 6, "title": "Envelope determinants for dual-receptor specificity in feline leukemia virus subgroup A and T variants.", "abstract": "Gammaretroviruses, including the subgroups A, B, and C of feline leukemia virus (FeLV), use a multiple-membrane-spanning transport protein as a receptor. In some cases, such as FeLV-T, a nonclassical receptor that includes both a transport protein (Pit1) and a soluble cofactor (FeLIX) is required for entry. To define which regions confer specificity to classical versus nonclassical receptor pathways, we engineered mutations found in either FeLV-A/T or FeLV-T, individually and in combination, into the backbone of the transmissible form of the virus, FeLV-A. The receptor specificities of these viruses were tested by measuring infection and binding to cells expressing the FeLV-A receptor or the FeLV-T receptors. FeLV-A receptor specificity was maintained when changes at amino acid position 6, 7, or 8 of the mature envelope glycoprotein were introduced, although differences in infection efficiency were observed. When these N-terminal mutations were introduced together with a C-terminal 4-amino-acid insertion and an adjacent amino acid change, the resulting viruses acquired FeLV-T receptor specificity. Additionally, a W-->L change at amino acid position 378, although not required, enhanced infectivity for some viruses. Thus, we have found that determinants in the N and C termini of the envelope surface unit can direct entry via the nonclassical FeLV-T receptor pathway. The region that has been defined as the receptor binding domain of gammaretroviral envelope proteins determined entry via the FeLV-A receptor independently of the presence of the N- and C-terminal FeLV-T receptor determinants.", "journal": "Journal of virology", "doi": "10.1128/JVI.80.4.1619-1628.2006", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16434225", "author": "Weiss DJ", "n_authors": 1, "title": "Aplastic anemia in cats - clinicopathological features and associated disease conditions 1996-2004.", "abstract": "A retrospective study of 128 feline bone marrow reports identified 13 cases of aplastic anemia. Clinical diagnoses included chronic renal failure (n=5), feline leukemia virus infection (n=2), hyperthyroidism treated with methimazole (n=1) and idiopathic aplastic anemia (n=5). In some cats, starvation may play a role in the development of marrow aplasia. Some cats with aplastic anemia can have prolonged survival without resolution of the pancytopenia.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2005.11.002", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16423059", "author": "Langhammer S", "n_authors": 4, "title": "Antibodies neutralizing feline leukaemia virus (FeLV) in cats immunized with the transmembrane envelope protein p15E.", "abstract": "The feline leukaemia virus (FeLV) vaccines that are currently in wide use are generally poor inducers of virus-neutralizing antibodies, although such antibodies appear after recovering from challenge. However, the presence of neutralizing antibodies in cats recovering from natural FeLV infection clearly correlates with resistance to subsequent infection and passive transfer of antibodies can protect other animals. After demonstrating the induction of neutralizing antibodies in rats and goats immunized with the transmembrane envelope protein p15E of FeLV, cats were immunized with the same antigen. High titres of neutralizing antibodies specific for FeLV were induced and epitope mapping revealed a pattern of recognition similar to that seen following immunization of rats and goats. These epitopes are highly related to epitopes recognized after immunization with porcine endogenous retrovirus (PERV) p15E and to epitopes recognized by neutralizing antibodies in patients infected with human immunodeficiency virus type 1. The ability of p15E to induce neutralizing antibodies in cats suggests that it should be included in the next generation of vaccines. In contrast, sera from FeLV-infected animals usually fail to recognize the neutralization-relevant epitopes in p15E. Since homologous epitope sequences are present in feline endogenous retroviruses, it appears that tolerance against these sequences is not induced.", "journal": "Immunology", "doi": "10.1111/j.1365-2567.2005.02291.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16343700", "author": "Brunner C", "n_authors": 8, "title": "Antibody induction after combined application of an adjuvanted recombinant FeLV vaccine and a multivalent modified live virus vaccine with a chlamydial component.", "abstract": "The compatibility, safety and interaction on antibody induction of a combined vaccine application were assessed. Specific pathogen-free cats were vaccinated with either a modified live virus vaccine containing feline calici- (FCV), herpes- (FHV-1), parvovirus (FPV) and Chlamydophila felis (C. felis), an adjuvanted recombinant feline leukaemia virus (FeLV) vaccine or both vaccines in one syringe. After combined application, FeLV ELISA antibody titres were unaltered, However antibody production based on indirect immunofluorescence assay was remarkably enhanced for FCV and was at selected time points also enhanced for FHV-1 and C. felis but diminished for FPV. The use of these vaccines in combination was safe and will simplify vaccination schedules in veterinary practice.", "journal": "Vaccine", "doi": "10.1016/j.vaccine.2005.10.030", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16303261", "author": "Gomes-Keller MA", "n_authors": 6, "title": "Shedding of feline leukemia virus RNA in saliva is a consistent feature in viremic cats.", "abstract": "The purpose of this investigation was to characterize the shedding pattern of feline leukemia virus (FeLV) RNA in saliva, and to correlate it with the proviral load in whole blood, viral load in plasma, levels of p27 in saliva and plasma, the isolation of infectious FeLV from saliva, and the titers of FeLV-specific antibodies of the IgG and IgA isotypes. We evaluated 24 experimentally FeLV-infected cats for these parameters using real-time RT-PCR and PCR, cell culture assay and sandwich ELISA. We observed that shedding of viral RNA in saliva was a consistent feature in viremic cats. Latently FeLV-infected cats, displaying a very low proviral load, did not shed infectious virus in saliva, but occasionally shed viral RNA. Consequently, salivary shedding of FeLV RNA may not necessarily indicate a transmission potential for susceptible cats. This study also confirmed previous results from our laboratory, showing that a negative result for p27 in plasma, or for viral RNA in plasma or saliva does not exclude FeLV infection, considering that blood cells from those cats contained provirus. We also showed that FeLV RNA and DNA were stable for more than 64 days in saliva samples stored at room temperature. We conclude that the detection of FeLV RNA in saliva may be a useful indicator of viremia, and that the detection of salivary viral RNA by RT-PCR could become a reliable tool for the diagnosis of FeLV infection, which is facilitated by the low invasive method of collection of the samples.", "journal": "Veterinary microbiology", "doi": "10.1016/j.vetmic.2005.10.027", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16289658", "author": "Abujamra AL", "n_authors": 6, "title": "Leukemia virus long terminal repeat activates NFkappaB pathway by a TLR3-dependent mechanism.", "abstract": "The long terminal repeat (LTR) region of leukemia viruses plays a critical role in tissue tropism and pathogenic potential of the viruses. We have previously reported that U3-LTR from Moloney murine and feline leukemia viruses (Mo-MuLV and FeLV) upregulates specific cellular genes in trans in an integration-independent way. The U3-LTR region necessary for this action does not encode a protein but instead makes a specific RNA transcript. Because several cellular genes transactivated by the U3-LTR can also be activated by NFkappaB, and because the antiapoptotic and growth promoting activities of NFkappaB have been implicated in leukemogenesis, we investigated whether FeLV U3-LTR can activate NFkappaB signaling. Here, we demonstrate that FeLV U3-LTR indeed upregulates the NFkappaB signaling pathway via activation of Ras-Raf-IkappaB kinase (IKK) and degradation of IkappaB. LTR-mediated transcriptional activation of genes did not require new protein synthesis suggesting an active role of the LTR transcript in the process. Using Toll-like receptor (TLR) deficient HEK293 cells and PKR(-/-) mouse embryo fibroblasts, we further demonstrate that although dsRNA-activated protein kinase R (PKR) is not necessary, TLR3 is required for the activation of NFkappaB by the LTR. Our study thus demonstrates involvement of a TLR3-dependent but PKR-independent dsRNA-mediated signaling pathway for NFkappaB activation and thus provides a new mechanistic explanation of LTR-mediated cellular gene transactivation.", "journal": "Virology", "doi": "10.1016/j.virol.2005.10.003", "deposited_data": "Sim", "nuccore_ids": "2462597399, 2462597397, 2462597394, 2462597392, 2462597390, 2217350803, 2217350801, 2217350800, 2217350798, 1843419885, 1843419864, 1843419817, 1843419786, 1777425344, 1675096365, 1674985997, 1519314697, 1370486991", "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16266755", "author": "Wilhelm S", "n_authors": 2, "title": "Real-time reverse transcription polymerase chain reaction assay to detect a broad range of feline calicivirus isolates.", "abstract": "This report describes a real-time reverse transcription polymerase chain reaction (RT-PCR) assay with SYBR Green targeting the VP2 (ORF 3) of feline caliciviruses. All of the 44 feline calicivirus isolates tested were detected, whereas neither feline herpesvirus, feline panleukopenia virus, feline immunodeficiency virus and feline leukemia virus nor other calicivirus like rabbit hemorrhagic disease virus and a canine calicivirus isolate showed specific amplification products. The sensitivity of the SYBR Green reaction was shown to be equivalent to 5 x 10(1) to 5 x 10(2) copies/reaction and the overall sensitivity equivalent to a feline calicivirus titer of 10(0.6) TCID(50)/100 microl in Crandell Reese Feline Kidney (CRFK) cells.", "journal": "Journal of virological methods", "doi": "10.1016/j.jviromet.2005.10.011", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16226469", "author": "Baral RM", "n_authors": 12, "title": "Disseminated Mycobacterium avium infection in young cats: overrepresentation of Abyssinian cats.", "abstract": "Disseminated Mycobacterium avium-intracellulare complex (MAC) infection was diagnosed in 10 young cats (1-5 years of age) from Australia or North America between 1995 and 2004. A further two cats with disseminated mycobacteriosis (precise agent not identified) were recognised during this period. Of the 12, 10 were Abyssinian cats, one was a Somali cat and one was a domestic shorthair cat. None of the cats tested positive for either FeLV antigen or FIV antibody. The clinical course of these infections was indolent, with cats typically presenting for weight loss, initially in the face of polyphagia, with a chronicity of up to several months. Additional clinical features included lower respiratory tract signs and peripheral lymphadenomegaly. A marked diffuse interstitial pattern was evident in thoracic radiographs, even in cats without overt respiratory involvement. Hair clipped to perform diagnostic procedures tended to regrow slowly, if at all. Diagnosis was generally made by obtaining representative tissue specimens from mesenteric lymph nodes, liver or kidney at laparotomy, or from a popliteal lymph node. The primary antecedent event was most likely colonisation of either the alimentary or respiratory tract, followed by local invasion and eventual lymphatic and haematogenous dissemination. Nine cases were treated using combination therapy with agents effective for MAC infection in human patients. Two cats are still undergoing initial therapy and have responded. Of the remaining seven, all responded during long courses (5-14 months) of clarithromycin combined with either clofazimine or rifampicin, and a fluoroquinolone or doxycycline. Of these, three cats remain well (with durations between 2 months and 2 years following therapy); two developed recurrent disease (at 3 months and 2 years, respectively, following therapy) and have restarted therapy. The remaining two cats improved 1 year and 5 months, respectively, after diagnosis but ultimately succumbed. The two cats in which therapy was restarted have improved dramatically. Certain lines of Abyssinian and Somali cats likely suffer from a familial immunodeficiency that predisposes them to infection with slow-growing mycobacteria such as MAC.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2005.06.004", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16198454", "author": "Hofmann-Lehmann R", "n_authors": 11, "title": "Reassessment of feline leukaemia virus (FeLV) vaccines with novel sensitive molecular assays.", "abstract": "We previously described antigen negative, provirus positive cats. Subsequently, we hypothesized that efficacious FeLV vaccines cannot prevent minimal viral replication. Thus, we vaccinated cats with either a canarypox-vectored live or a killed virus vaccine and analyzed the challenge outcome with quantitative PCR and a newly established real-time RT-PCR. When judged by conventional parameters (antigenaemia, virus isolation), most of the vaccinated cats were, as expected, protected from persistent viraemia. However, all cats were found to be plasma viral RNA positive. The loads were significantly associated with the infection outcome. Thus, commonly used FeLV vaccines understood to be successful model antiretroviral vaccines protecting against FeLV-related diseases do not confer sterilizing immunity.", "journal": "Vaccine", "doi": "10.1016/j.vaccine.2005.09.010", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17939348", "author": "Ramanathan A", "n_authors": 3, "title": "Seroepizootiological survey for selected viral infections in captive Asiatic lions (Panthera leo persica) from western India.", "abstract": "Infectious diseases have been responsible for large-scale declines in many endangered animals. Disease outbreaks in small populations have probably led to the eventual extinction of such endangered animals in the wild. The endangered Asiatic lion (Panthera leo persica) population may also face such threats. This was evident from this study on captive Asiatic lions from western India, which were sampled from December 1998 to March 1999. Fifty-six Asiatic lions, including 17 hybrid lions (Afro-Asian crosses) from six captive centers in western India, were tested for antibodies against canine distemper virus (CDV), feline parvovirus (FPV), feline immunodeficiency virus (FIV), and feline leukemia viral (FeLV) antigen. Agar gel immunodiffusion test and dot immunobinding assay were employed for CDV and FPV antibody detection. Commercial enzyme-linked immunosorbent assay kits were used for FIV antibody and FeLV antigen detection. Forty-nine of 56 lions (87.5%) were positive for CDV. All 56 (100%) lions were positive for FPV antibodies. There were no detectable levels of FIV antibodies and FeLV antigens. It was observed that CDV and FPV, two viruses known to cause high mortality in captive carnivores, were widely prevalent in these captive Asiatic lions. It is suggested that these seropositive animals will have the potential to pose a risk of infection to other seronegative animals. Hence, it is imperative to carefully consider any movement, translocation, or reintroduction of these animals to new regions. It is also recommended that these animals be required to undergo standard quarantine and disease screening protocols. The lack of exposure to pathogens, such as FIV and FeLV, would also be a risk, and, hence, identification of reservoirs and screening of in-contact animals is highly recommended. Vaccinations must be considered, using killed or other suitable viral vaccines, which have been proved to be safe, effective, and efficacious in endangered felids.", "journal": "Journal of zoo and wildlife medicine : official publication of the American Association of Zoo Veterinarians", "doi": "10.1638/2007-0006.1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17873276", "author": "Brown R", "n_authors": 1, "title": "FeLV and FIV in a cat population.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.161.11.396", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17824830", "author": "Di Nunzio F", "n_authors": 5, "title": "Transduction of human hematopoietic stem cells by lentiviral vectors pseudotyped with the RD114-TR chimeric envelope glycoprotein.", "abstract": "Lentiviral vectors are efficiently pseudotyped with RD114-TR, a chimeric envelope glycoprotein made of the extracellular and transmembrane domains of the feline leukemia virus RD114 and the cytoplasmic tail of the murine leukemia virus amphotropic envelope. RD114-TR-pseudotyped vectors may be concentrated by centrifugation, are resistant to complement inactivation, and are suitable for both ex vivo and in vivo gene therapy applications. We analyzed RD114-TR-pseudotyped, HIV-1-derived lentiviral vectors for their ability to transduce human cord blood, bone marrow, and peripheral blood mobilized CD34(+) hematopoietic stem/progenitor cells. Transduction efficiency was analyzed in CD34(+) cells in liquid culture, in CD34(+) clonogenic progenitors in semisolid culture, and in CD34(+) repopulating stem cells after xenotransplantation in NOD-SCID mice. Compared with a standard VSV-G-based packaging system, RD114-TR-pseudotyped particles transduced hematopoietic stem/progenitor cells at lower multiplicity of infection, with lower toxicity and less pseudo-transduction at comparable vector copy number per genome. Potential changes in the CD34(+) cell transcription profile and phenotype on transduction with RD114-TR-pseudotyped vectors was comparatively investigated by microarray analysis. Our study shows that the biology of repopulating hematopoietic stem cells and their progeny is not affected by transduction with RD114-TR-pseudotyped lentiviral vectors. RD114-TR is compatible with the development of lentiviral stable packaging cell lines, and may become the envelope of choice for clinical studies aiming at safe and efficient genetic modification of human hematopoietic stem cells.", "journal": "Human gene therapy", "doi": "10.1089/hum.2006.138", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17768202", "author": "Arnoczky SP", "n_authors": 6, "title": "The location in cartilage of infectious retrovirus in cats infected with feline leukemia virus.", "abstract": "Previous studies have suggested that articular cartilage allografts were not likely to transmit infectious retrovirus since viral DNA could not be isolated from chondrocytes of infected individuals. However, the ability of the extracellular matrix of articular cartilage to harbor and transmit a retrovirus has not been examined. We hypothesized that articular cartilage fragments, but not isolated chondrocytes, from cats systemically infected with feline leukemia virus (FeLV) are capable of transmitting infectious retrovirus. Fresh cartilage segments and chondrocytes isolated from cats systemically infected with feline leukemia virus were used in this study. Feline embryonic fibroblast cells were cocultured with segments of cartilage, isolated chondrocytes, or fragments of cortical bone from each infected cat. The FeLV p27 antigen was measured in the coculture media by enzyme-linked immunosorbent assay. In addition, FeLV proviral nucleic acids were quantified by real-time quantitative polymerase chain reaction with use of DNA extracted from feline embryonic fibroblast cell cocultures as well as isolated chondrocytes. Immunohistochemistry was used to assess for FeLV p27 antigen in both intact cartilage fragments and isolated chondrocytes. Feline embryonic fibroblast cells cocultured with cartilage fragments from each of the five FeLV-infected cats all demonstrated high levels of proviral DNA, indicating transmission of infective virus. In addition, media from all cocultures of feline embryonic fibroblast cells and chondral fragments became positive for p27 antigen, indicating active viral replication. In contrast, cocultures of feline embryonic fibroblast cells and isolated chondrocytes from all FeLV-infected cats were negative for proviral DNA and p27 antigen. Likewise, no proviral nucleic acids could be detected in isolated chondrocytes from any infected cats. Cocultures of feline embryonic fibroblast cells with cortical bone fragments were positive for proviral DNA and p27 antigen. Immunohistochemical staining of cartilage fragments from FeLV-infected cats demonstrated the presence of p27 antigen throughout the extracellular matrix, but the p27 antigen was not detected in isolated chondrocytes. Articular cartilage fragments can readily transmit infectious retrovirus, but isolated chondrocytes were likely not the source of the infectious virus because they did not harbor proviral DNA or p27 antigen.", "journal": "The Journal of bone and joint surgery. American volume", "doi": "10.2106/JBJS.G.00054", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17669677", "author": "Sharifi H", "n_authors": 4, "title": "Eosinophilic leukaemia in a cat.", "abstract": "A 14-year-old female domestic shorthair cat was presented to Tehran University Veterinary Teaching Hospital for a persistent fever, anorexia, intermittent vomiting, weight loss and weakness. The main clinical signs were pale mucous membranes, dehydration and splenomegaly. The complete blood count and serum biochemistry tests revealed non-regenerative anaemia, thrombocytopenia and increased alkaline phosphatase (ALP) activity. An enzyme-linked immunosorbent assay (ELISA) test for feline leukaemia virus was negative. Blood film and bone marrow examination revealed a large number of immature eosinophils with variable sizes and numbers of faintly azurophilic granules. Cytochemical staining of blood film demonstrated 70% positive cells for ALP activity. Four percent CD34 positive cells were detected by flow cytometry. As eosinophilic leukaemia is difficult to identify by light microscopy, well-defined diagnostic criteria and the use of flow cytometry and cytochemical staining can improve the ability to correctly diagnose this type of leukaemia in cats.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2007.05.004", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17641147", "author": "Banerji N", "n_authors": 3, "title": "Association of germ-line polymorphisms in the feline p53 gene with genetic predisposition to vaccine-associated feline sarcoma.", "abstract": "A case-control study was conducted in order to investigate the association of polymorphisms in the genomic sequence of the feline p53 gene with a predisposition to vaccine-associated feline sarcoma (VAFS). In the study, 50 domestic short hair cats with a confirmed histopathologic diagnosis of VAFS were matched to disease-free controls (1:2) by age, sex, and breed. Cats from both the diseased (case) and control groups were also negative for feline leukemia virus and feline immunodeficiency virus. Germ-line DNA was prepared from blood samples from cats in both groups and analyzed for sequence variation at 8 polymorphic sites in the p53 gene. A strong association was found between VAFS and the presence of specific nucleotides at 2 of the polymorphic sites. The strongest association was observed for a single-base insertion in intron 7 of the gene with an odds ratio of 8.99 (95% confidence interval = 3.42-23.57, P < 0.0001). The results of the study indicate that analysis of the presence or absence of the identified genetic markers in apparently healthy disease-free cats may help in predicting which individual animals are at greater risk of developing the disease.", "journal": "The Journal of heredity", "doi": "10.1093/jhered/esm057", "deposited_data": "Sim", "nuccore_ids": "57163822, 57163822", "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17630887", "author": "Levy JK", "n_authors": 6, "title": "Seroprevalence of Dirofilaria immitis, feline leukemia virus, and feline immunodeficiency virus infection among dogs and cats exported from the 2005 Gulf Coast hurricane disaster area.", "abstract": "To determine seroprevalence of dirofilariasis in dogs and seroprevalences of dirofilariasis, FeLV infection, and FIV infection in cats exported from the Gulf Coast region following the 2005 hurricanes. Seroprevalence survey. 1,958 dogs and 1,289 cats exported from Louisiana, Mississippi, and Texas between August 20 and December 31, 2005. 141 animal welfare groups in 37 states and Alberta, Canada, reported results of serologic testing. Risk factors for infection, including age, sex, neuter status, breed, and state of rescue, were examined by means of univariate and multivariate logistic regression. Seroprevalence of dirofilariasis in dogs was 48.8%. Sexually intact dogs were 1.6 times as likely to have dirofilariasis as were neutered dogs, dogs in the ancient breed group were 2.2 times as likely and dogs in the guarding breed group were 1.7 times as likely to have dirofilariasis as were dogs in the herding breed group, and dogs from Mississippi were significantly less likely to have dirofilariasis than were dogs from Texas. Seroprevalences of dirofilariasis, FeLV infection, and FIV infection in cats were 4.0%, 2.6%, and 3.6%, respectively. Seroprevalence of FIV infection was significantly higher in adult cats than in juveniles and in males than in females. Results suggest that dogs and cats exported from the 2005 Gulf Coast hurricane disaster area had disease rates similar to those for animals in the region prior to the hurricanes.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.231.2.218", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17604205", "author": "Hartmann K", "n_authors": 7, "title": "Quality of different in-clinic test systems for feline immunodeficiency virus and feline leukaemia virus infection.", "abstract": "Many new diagnostic in-house tests for identification of feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV) infection have been licensed for use in veterinary practice, and the question of the relative merits of these kits has prompted comparative studies. This study was designed to define the strengths and weaknesses of seven FIV and eight FeLV tests that are commercially available. In this study, 536 serum samples from randomly selected cats were tested. Those samples reacting FIV-positive in at least one of the tests were confirmed by Western blot, and those reacting FeLV-positive were confirmed by virus isolation. In addition, a random selection of samples testing negative in all test systems was re-tested by Western blot (100 samples) and by virus isolation (81 samples). Specificity, sensitivity, positive and negative predictive values of each test and the quality of the results were compared.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2007.04.003", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17581869", "author": "Sarangi A", "n_authors": 3, "title": "Identification of a retroviral receptor used by an envelope protein derived by peptide library screening.", "abstract": "This study demonstrates the power of a genetic selection to identify a variant virus that uses a new retroviral receptor protein. We screened a random peptide library within the receptor-binding domain of a feline leukemia virus retroviral Envelope (FeLV Env) protein for productive infection of feline AH927 cells. One variant, A5, obtained with altered tropic properties acquired the ability to use the solute carrier protein family 35 member F2 (SLC35F2) as a receptor. The SLC35F2 protein is a presumed transporter of unknown function predicted to encode 8 to 10 transmembrane-spanning regions and is not homologous to any identified retroviral receptor. Expression of the feline SLC35F2 cDNA in nonpermissive cells renders the cells susceptible to infection by A5 virus, with remarkably high titers in the range of 10(5) infectious units per ml. The human SLC35F2 ORF also functioned as the retroviral receptor, albeit at lower efficiency than the feline homologue. The successful selection of a novel molecule, the SLC35F2 transporter/channel-type protein, as a receptor by the FeLV Env backbone suggests that multipass transmembrane proteins may be particularly suited for use in productive viral entry and fusion. The analysis of retroviral Env libraries randomized in the receptor-binding domain offers a viable means to develop viral vectors targeted to specific cell types in the absence of known targeting ligands.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.0704182104", "deposited_data": "Sim", "nuccore_ids": "156071440, 114329249, 2462525994, 2217283440, 2131023378, 2131023376, 2131023374, 2131023372, 2131023371, 2131023370, 1519242653, 156071440", "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17555038", "author": "Just F", "n_authors": 2, "title": "[Detection frequency of haemoplasma infections of the domestic cat in Germany].", "abstract": "We present epidemiological data on the frequency of infections with haemotrophic Mycoplasma spp. (feline haemoplasmas) in domestic cats in Germany. From November 2004 to October 2006 135 blood samples of anaemic patients and cats without clinical symptoms were examined with conventional and real-time PCR methods. In 15,6 % of the samples DNA of one or more haemoplasma species could be detected. 8,9 % of the samples (12 cats) were infected with \"Candidatus Mycoplasma haemominutum, whereas 7,4 % (10 cats) were infected with Mycoplasma haemofelis. Out of these, one cat harboured both species. The recently described species \"Candidatus Mycoplasma turicensis\" was found in 2.2 % of all samples (3 cats) and was restricted to animals coinfected with M. haemofelis. No correlation could be detected between the infection with haemotrophic Mycoplasma spp. and clinical signs of anaemia or disease. Infections were significantly correlated with age, male gender or coinfections with retroviruses (FIV, FeLV). Our data indicate, that chronically infected carriers without clinical symptoms are frequent in the investigated cat populations in Germany and that the screening of blood-donors for the presence of Mycoplasma spp. infections is advisable before clinical use.", "journal": "Berliner und Munchener tierarztliche Wochenschrift", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17523087", "author": "Pinches MD", "n_authors": 6, "title": "An update on FIV and FeLV test performance using a Bayesian statistical approach.", "abstract": "Screening tests for feline retroviruses are thought to have high sensitivity and specificity, although previous studies that evaluated these tests have limitations. Novel statistical approaches have been developed that allow the estimation of sensitivity and specificity in situations where the true state of the disease in individual animals cannot be assured. The purpose of this study was to evaluate the sensitivity and specificity of a variety of retrovirus tests, including some screening tests, in a population of cats potentially infected with either feline leukemia virus (FeLV) and/or feline immunodeficiency virus (FIV) by using a Bayesian statistical approach. Four hundred and ninety blood samples from cats being evaluated for FIV infection were tested by 2 rapid immunomigration tests (Witness single [WS], Witness combi [WC]) and a plate-based ELISA (Petcheck) for FIV antibody, and by a newly designed real-time polymerase chain reaction (PCR) assay for FIV provirus. Four hundred and ninety-five blood samples from cats being evaluated for FeLV infection were tested by 2 rapid immunomigration tests (WS, WC) and a plate-based ELISA (Petcheck) for FeLV antigen, and by a FeLV virus isolation technique. Results were then analyzed by using a Bayesian statistical method. For FIV tests, median sensitivity estimates were 0.98 for WS, 0.97 for WC, 0.98 for ELISA, and 0.92 for PCR. Median specificity estimates were 0.96 for WS, 0.96 for WC, 0.93 for ELISA, and 0.99 for PCR. For FeLV tests, median sensitivity estimates were 0.97 for WS, 0.97 for WC, 0.98 for ELISA, and 0.91 for virus isolation. Median specificity estimates were 0.96 for WS, 0.96 for WC, 0.98 for ELISA, and 0.99 for virus isolation. The use of Bayesian statistical methods overcomes a variety of methodologic problems associated with diagnostic test evaluations, including the lack of a definitive reference test. The sensitivity and the specificity of all 6 evaluated screening tests was high: however, specificity estimates were slightly lower than those reported by most recent studies.", "journal": "Veterinary clinical pathology", "doi": "10.1111/j.1939-165x.2007.tb00200.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17507184", "author": "Collado VM", "n_authors": 7, "title": "Effect of type I interferons on the expression of feline leukaemia virus.", "abstract": "The efficacy of interferons (IFNs), used empirically to treat retrovirus-infected cats has been shown in vivo, but the direct effect on infected cells is largely unknown. Ten-fold serial dilutions of three recombinant IFNs available for therapy, human IFNalpha(2a), IFNalpha(A/D) and feline IFNomega were added to the chronically FeLV-infected cell line FL74. IFNs did not apparently affect viral protein expression. However, reverse transcriptase activity (RT), directly proportional to the amount of infectious free virions, decreased with increasing concentrations of IFN and longer treatment times. The induction of apoptosis by IFN was suspected. Results of its evaluation by annexin V-Fluos staining showed that IFNs decreased the viability of treated FeLV-infected cells, and increased apoptosis, but not of non-infected cells. According to the IC(50), rHuIFNalpha(A/D) appeared to be the most effective IFN in inhibiting RT.", "journal": "Veterinary microbiology", "doi": "10.1016/j.vetmic.2007.03.008", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17495320", "author": "Danner RM", "n_authors": 4, "title": "Evidence of feline immunodeficiency virus, feline leukemia virus, and Toxoplasma gondii in feral cats on Mauna Kea, Hawaii.", "abstract": "We determined prevalence to feline immunodeficiency virus (FIV) antibodies, feline leukemia virus (FeLV) antigen, and Toxoplasma gondii antibodies in feral cats (Felis catus) on Mauna Kea Hawaii from April 2002 to May 2004. Six of 68 (8.8%) and 11 of 68 (16.2%) cats were antibody positive to FIV and antigen positive for FeLV, respectively; 25 of 67 (37.3%) cats were seropositive to T. gondii. Antibodies to FeLV and T. gondii occurred in all age and sex classes, but FIV occurred only in adult males. Evidence of current or previous infections with two of these infectious agents was detected in eight of 64 cats (12.5%). Despite exposure to these infectious agents, feral cats remain abundant throughout the Hawaiian Islands.", "journal": "Journal of wildlife diseases", "doi": "10.7589/0090-3558-43.2.315", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17493167", "author": "Miró G", "n_authors": 7, "title": "Plasma electrophoretogram in feline immunodeficiency virus (FIV) and/or feline leukaemia virus (FeLV) infections.", "abstract": "The electrophoretogram of 89 cats, including those infected by feline immunodeficiency virus (FIV+), feline leukaemia virus (FeLV+) and non-infected, showed statistically significant differences in several of the fractions. FIV+ cats had very high protein values (mean, 8.10 g/dl), mostly because of hypergammaglobulinemia (mean, 2.81 g/dl) as compared with non-infected animals and FeLV+. In addition, in these FIV+ animals, the albumin/globulins ratio (A/G) was very low (mean, 0.72). Statistically significant differences in A/G and alpha2-globulin fraction were observed in FeLV+ group (A/G mean, 0.88 +/- 0.08; alpha2-globulin, mean, 0.84 +/- 0.07 g/dl) when compared with non-infected group (A/G mean, 1.06 +/- 0.08; alpha2-globulin mean, 0.68 +/- 0.04 g/dl). The alpha1-globulin fraction was higher in double infected animals (FIV and FeLV positive, F-F) (3.55 g/dl), than in FeLV+ or FIV+ cats (3.10 and 3.07 g/dl respectively), but no statistical conclusions may be drawn from this fact because of the low number of F-F animals. This technique may help to assess the initial clinical status of retrovirus-infected cats, and the clinical course of these chronic diseases, specifically during and after suitable therapy.", "journal": "Journal of veterinary medicine. A, Physiology, pathology, clinical medicine", "doi": "10.1111/j.1439-0442.2007.00902.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17481822", "author": "Mendes-de-Almeida F", "n_authors": 8, "title": "Follow-up of the health conditions of an urban colony of free-roaming cats (Felis catus Linnaeus, 1758) in the city of Rio de Janeiro, Brazil.", "abstract": "Similar to other urban areas where food and shelter are abundant, the zoological garden of Rio de Janeiro has dealt for years with a colony of feral or semi-feral domestic cats. A survey was conducted during 2002-2004 as a follow-up to a previous study in 2001 of the cat colony to identify pathogens circulating among the population and to annually follow the status of the cats to analyze morbidity coefficients and associations among infections and infestations identified in the colony. During the 3 years of the present study, 75 cats were sampled at least once, including 44 that were caught and examined only once, 14 that were examined twice, and 17 that were examined three times. For each cat that was caught, records were kept regarding sex, age, general health, and the presence of ectoparasites. Each year, a blood sample was taken for hematologic testing, platelet count, hemoparasite detection, antibodies to Toxoplasma gondii, and retrovirus detection. Blood counts were within normal range for the majority of cats tested. Feline immunodeficiency virus, fleas, and lice were detected in all years; however, incidence rates for each of these varied significantly throughout the years. Prevalence of Cytauxzoon spp., Mycoplasma spp., T. gondii infections were variable among the 3 years, although differences were not significant. Prevalence of feline leukemia virus increased significantly over the 3 years. Mycoplasma spp. and flea infestations were significantly associated, but no other associations among the pathogens were detected. Over the 3 years, the rate of new cat introductions decreased, and the pathogens showed a tendency to disseminate throughout the colony; however, there was virtually no evidence of clinically detectable disease. Therefore, it seems that stabilizing the population by a judicious control program facilitated the distribution of the pathogens throughout the colony, while the general well-being of the cats was not seriously affected.", "journal": "Veterinary parasitology", "doi": "10.1016/j.vetpar.2007.03.035", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17479775", "author": "van den Heuvel MJ", "n_authors": 5, "title": "Defibrinated bovine plasma inhibits retroviral transcription by blocking p52 activation of the NFkappaB element in the long terminal repeat.", "abstract": "Bovine leukemia virus (BLV) induces a persistent but latent infection in cattle. Viral latency is invoked by a protein known as plasma blocking factor (PBF) that is found in both bovine and human plasma. We report here on pathways that mediate latency in the presence of PBF. Reporter-gene constructs driven by the promoters of 6 retroviruses were used to measure the production of chloramphenicol acetyl transferase (CAT) in cell lines cultured with or without defibrinated bovine plasma. Plasma inhibited CAT production only in constructs containing an NFkappaB-binding element proximal to the initiation site (BLV, human immunodeficiency virus, and human T-cell leukemia virus). The promoters of Bovine immunodeficiency virus, Feline immunodeficiency virus, or Feline leukemia virus were not inhibited in the presence of bovine plasma. Using gel mobility shift assays, we demonstrated that activation of viral transcription upon stimulation with phorbol esters and ionomycin was mediated through the NFkappaB element and that this was abrogated in the presence of plasma. Furthermore, analysis of individual NFkappaB proteins in nuclear extracts of mononuclear cells or Jurkat cells showed that all 5 members of the NFkappaB family were upregulated in response to stimulation, but only p52 was significantly downregulated in the presence of bovine plasma. Thus, we infer that plasma effects are mediated through interference with either p52 translocation to the nucleus or p52 synthesis.", "journal": "Canadian journal of veterinary research = Revue canadienne de recherche veterinaire", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17460117", "author": "Ramsauer S", "n_authors": 5, "title": "Seroprevalence of selected infectious agents in a free-ranging, low-density lion population in the Central Kalahari Game Reserves in Botswana.", "abstract": "Twenty-one free-ranging Central Kalahari lions (Panthera leo) exhibited a high prevalence rate of feline herpesvirus (100%) and feline immunodeficiency virus (71.4%). Canine distemper virus and feline calicivirus occurred with a low prevalence. All individuals tested negative for feline coronavirus, feline parvovirus, feline leukemia virus, Ehrlichia canis, and Anaplasma phagocytophilum.", "journal": "Clinical and vaccine immunology : CVI", "doi": "10.1128/CVI.00307-06", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17434224", "author": "Pepin AC", "n_authors": 8, "title": "Cellular segregation of feline leukemia provirus and viral RNA in leukocyte subsets of long-term experimentally infected cats.", "abstract": "Cats exposed to feline leukemia virus (FeLV) may develop different outcomes of the infection. However, during acute infection blood proviral and viral RNA loads of cats with progressive and regressive infection are not significantly different. Thus, not the overall loads but rather those of specific leukocyte subsets may influence the infection outcome. By combining fluorescence activated cell sorting (FACS) with sensitive real-time TaqMan PCR and reverse transcriptase (RT) PCR, we established in the present study the methods to determine FeLV proviral and viral RNA loads in specific leukocyte subsets. In addition, they were applied to analyze long-term persistently FeLV-infected (p27-positive) and FeLV exposed but nonantigenemic (p27-negative), nonviremic cats. In the latter animals, CD4(+) and B lymphocytes exhibited the highest proviral loads, whereas in p27-positive cats, all leukocyte subsets showed similar high loads. In p27-positive cats, monocytes and granulocytes bore the highest viral RNA loads, whereas only one p27-negative cat was positive for viral RNA in T lymphocytes. To our knowledge, this is the first study to investigate FeLV proviral and viral RNA loads in leukocyte subsets of FeLV exposed cats. The herein described methods are important prerequisites to gain a deeper insight into the pathogenesis of FeLV infection.", "journal": "Virus research", "doi": "10.1016/j.virusres.2007.03.008", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17426169", "author": "Solano-Gallego L", "n_authors": 8, "title": "Cross-sectional serosurvey of feline leishmaniasis in ecoregions around the Northwestern Mediterranean.", "abstract": "A cross-sectional serosurvey using Leishmania infantum ELISA was performed on 445 cats living in ecoregions around the Northwestern Mediterranean basin; 58 cats from an area of the US where leishmaniasis is not endemic were used as negative controls. ELISA results were further confirmed in 69 cats by Western blot (WB). Finally, 76 of them were also tested for FeLV and FIV. Seroprevalence by ELISA-prot A was 6.29%, and that by ELISA-IgG was 5.25%. Positive cat sera recognized patterns of polypeptides in WB, including L. infantum-specific antigenic fractions. There was no association with retroviruses. Leishmania-specific antibodies are prevalent in cats living in ecoregions around the Northwestern Mediterranean basin; thus, leishmaniasis must be included in the differential diagnosis of diseases in cats living in these ecoregions. Their role as peridomestic reservoirs for L. infantum needs further characterization, but it could be hypothesized that the cat is a secondary reservoir host, rather than an accidental one.", "journal": "The American journal of tropical medicine and hygiene", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17416134", "author": "Adler K", "n_authors": 5, "title": "[Bacteriological and virological status in upper respiratory tract infections of cats (cat common cold complex)].", "abstract": "Between October 2002 and January 2005,460 bacteriological samples from cats with an acute upper respiratory tract infection were analysed in clinical field studies in two accredited laboratories in Germany. Oropharyngeal swabs were taken from these cats and sent to the laboratories for routine diagnostics. In the swab samples of 460 cats 382 bacteria strains were isolated. The following bacteria were isolated most frequently: Pasteurella spp. (32.5 %), Staphylococcus spp. (18.5 %), Escherichia coli (17.0 %), Streptococcus spp. (9.1 %), Pseudomonas spp. (6.9 %) and Klebsiella spp. (3.0 %). Bordetella bronchiseptica was found in 0.4 % of the animals To evaluate possible regional and time influences, the animals were split into three populations: 1: Germany, laboratory A; 2: Germany, laboratory B; 3: France and Belgium, laboratory B. In population 1 an 2 Pasteurella spp. were found most frequently with 42.2 % and 36.5 %, respectively. The second most frequently isolated bacterial species were Staphylococcus spp. with 14.1 % and 21.4 % and E. coli with 13.6 % and 17.5 % respectively. In population 3 Staphylococcus spp., E. coli (20 % each) and Pasteurella spp. (18.5 %) were isolated at almost the same frequency. Virological parameter were additionally analysed in 328 cats (population 2 and 3). Serum samples were analysed for antibodies specific for Feline Calicivirus (FCV) and Feline Immunodeficiency Virus (FIV) and for Feline Leukaemia Virus (FeLV) antigen. Oropharyngeal swabs were analysed for Feline Herpesvirus (FHV) by using PCR. Calicivirus-specific antibodies were found in 99.6 % of the cats of population 2 and in 100 % of the animals in population 3. Herpesvirus was detected in 15.3 % and 23.3 % of the cats, respectively. FeLV-Antigen was found in 0.4 % of the animals in population 2 and in 10.1 % of the cats in population 3, while FIV-antibodies were identified in 8.7 % of the animals of population 2 and in 6.1 % of the cats of population 3. In total FHV was found in 19.3 % and FCV-specific antibodies in 99.7 % of the animals. 5.3 % of the cats carried FeLV-Antigen, and 7.4 % FIV-specific antibodies. The results of the bacteriological analysis as well as the results of the virological examination confirm previously published data. In this study Pasteurella spp. were most frequently isolated (32.5 %).", "journal": "Berliner und Munchener tierarztliche Wochenschrift", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17409007", "author": "Norris JM", "n_authors": 8, "title": "Prevalence of feline immunodeficiency virus infection in domesticated and feral cats in eastern Australia.", "abstract": "Serum samples from 340 pet cats presented to three inner city clinics in Sydney Australia, 68 feral cats from two separate colonies in Sydney, and 329 cattery-confined pedigree and domestic cats in eastern Australia, were collected over a 2-year period and tested for antibodies directed against feline immunodeficiency virus (FIV) using immunomigration (Agen FIV Rapid Immunomigration test) and enzyme-linked immunosorbent assay methods (Snap Combo feline leukaemia virus antigen/FIV antibody test kit, IDEXX Laboratories). Western blot analysis was performed on samples in which there was discrepancy between the results. Information regarding breed, age, gender, housing arrangement and health status were recorded for all pet and cattery-confined cats, while the estimated age and current physical condition were recorded for feral cats. The FIV prevalence in the two feral cat populations was 21% and 25%. The majority of FIV-positive cats were male (60-80%). The FIV prevalence in cattery-confined cats was nil. The prevalence of FIV in the pet cat sample population was 8% (27/340) with almost equal prevalence in 'healthy' (13/170) and 'systemically unwell' (14/170) cats. The age of FIV-positive pet cats ranged from 3 to 19 years; all FIV-positive cats were domestic shorthairs with outside access. The median age of FIV-positive pet cats (11 years) was significantly greater than the median age of FIV-negative pet cats (7.5 years: P<0.05). The prevalence of FIV infection in male pet cats (21/172; 12%) was three times that in female pet cats (6/168; 4%; P<0.05). With over 80% of this pet cat population given outside access and continued FIV infection present in the feral population, this study highlights the need to develop rapid, accurate and cost-effective diagnostic methods that are not subject to false positives created by concurrent vaccination against FIV. This is especially important in re-homing stray cats within animal shelters and monitoring the efficacy of the new vaccine, which has not been challenged against Australian strains. The absence of FIV within cattery-confined cats highlights the value in routine screening and indoor lifestyles. This study provides cogent baseline FIV prevalences in three cat subpopulations which can be used for appraising potential disease associations with FIV in Australia.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2007.01.007", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17397342", "author": "Zini E", "n_authors": 4, "title": "Immune-mediated erythroid and megakaryocytic aplasia in a cat.", "abstract": "A 6-month-old domestic shorthair cat was evaluated because of acute lethargy. Severe nonregenerative anemia and thrombocytopenia were identified. Cytologic examination of a bone marrow aspirate revealed selective erythroid and mega-karyocytic aplasia and a high number of apparently normal small lymphocytes. Infectious agents implicated in feline hematologic disorders were excluded on the basis of serologic tests or PCR amplification, including FeLV, Ehrlichia canis, Anaplasma phagocytophilum, Mycoplasma haemofelis, Candidatus Mycoplasma haemominutum, and Candidatus Myco-plasma turicensis. A 10-day course of prednisolone administration did not improve the hematologic disorder. Administration of human polyclonal immunoglobulins preceded increased reticulocyte count by 3 days. A second bone marrow examination confirmed restoration of erythroblasts and megakaryocytes. After 1 relapse, the disease was successfully controlled with prednisolone for > 3 years. Immune-mediated bone marrow aplasia is rare in cats and usually affects only erythrocyte progenitors. Concomitant involvement of erythroid and megakaryocytic cell lines can be successfully treated via immunosuppressive therapy. Human immunoglobulins seem to be well tolerated in cats; however, proof of a beneficial effect requires further study.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.230.7.1024", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17387028", "author": "Rizzo F", "n_authors": 3, "title": "Thrombocytosis in cats: a retrospective study of 51 cases (2000-2005).", "abstract": "Feline haematology profiles of patients presented to the University of Bristol Small Animal Hospital from January 2000 to October 2005 were evaluated for thrombocytosis (defined as a platelets count of >700x10(9)/l and confirmed on smear evaluation). Thrombocytosis was found in 79 cats (4.64% of the hospital feline population), with values ranging from 703 to 1895x10(9)/l. Signalment, clinical presentation, concurrence of other haematological abnormalities, diagnoses and outcome were evaluated in 51 cases in which complete medical records were available. Other variables (feline immunodeficiency virus/feline leukaemia virus status, thyroxine level, haemoplasma PCR, toxoplasma antibody titres) were also evaluated. No association was found between the presence of thrombocytosis and breed or gender. Gastrointestinal signs were the most common clinical presentation. Lymphopenia was the most common concurrent haematological abnormality. Based on final diagnosis reached, cats were grouped both according to the DAMNITV classification and according to the body system affected. Amongst the DAMNITV classification, inflammatory/infectious conditions were most commonly associated with thrombocytosis. According to body systems, gastrointestinal involvement was most represented, followed by endocrine cases. No association was found between the severity of thrombocytosis and outcome.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2007.01.008", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17329079", "author": "Tandon R", "n_authors": 7, "title": "Copy number polymorphism of endogenous feline leukemia virus-like sequences.", "abstract": "In the cat genome, endogenous feline leukemia virus (enFeLV) exists as multiple, nearly full-length proviral sequences. Even though no infectious virus is produced from enFeLV sequences, transcription and translation have been demonstrated in tissues of healthy cats and in feline cell lines. To test the hypothesis that the enFeLV loads play a role in exogenous FeLV-A infection and pathogenesis, we designed three real-time PCR assays to quantify U3 and env enFeLV loads (two within U3 amplifying different sequences; one within env). Applying these assays, we investigated the loads in blood samples derived from Swiss privately owned domestic cats, specific pathogen-free (SPF) cats and European wildcats (Felis silvestris silvestris). Significant differences in enFeLV loads were observed between privately owned cats and SPF cats as well as among SPF cats originating from different catteries and among domestic cats of different breeds. Within privately owned cats, FeLV-infected cats had higher loads than uninfected cats. In addition, higher enFeLV loads were found in wildcats compared to domestic cats. The assays described herein are important prerequisites to quantify enFeLV loads and thus to investigate the influence of enFeLV loads on the course of FeLV infection.", "journal": "Molecular and cellular probes", "doi": "10.1016/j.mcp.2007.01.003", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17301277", "author": "Willi B", "n_authors": 12, "title": "Worldwide occurrence of feline hemoplasma infections in wild felid species.", "abstract": "While hemoplasma infections in domestic cats are well studied, almost no information is available on their occurrence in wild felids. The aims of the present study were to investigate wild felid species as possible reservoirs of feline hemoplasmas and the molecular characterization of the hemoplasma isolates. Blood samples from the following 257 wild felids were analyzed: 35 Iberian lynxes from Spain, 36 Eurasian lynxes from Switzerland, 31 European wildcats from France, 45 lions from Tanzania, and 110 Brazilian wild felids, including 12 wild felid species kept in zoos and one free-ranging ocelot. Using real-time PCR, feline hemoplasmas were detected in samples of the following species: Iberian lynx, Eurasian lynx, European wildcat, lion, puma, oncilla, Geoffroy's cat, margay, and ocelot. \"Candidatus Mycoplasma haemominutum\" was the most common feline hemoplasma in Iberian lynxes, Eurasian lynxes, Serengeti lions, and Brazilian wild felids, whereas \"Candidatus Mycoplasma turicensis\" was the most prevalent in European wildcats; hemoplasma coinfections were frequently observed. Hemoplasma infection was associated with species and free-ranging status of the felids in all animals and with feline leukemia virus provirus-positive status in European wildcats. Phylogenetic analyses of the 16S rRNA and the partial RNase P gene revealed that most hemoplasma isolates exhibit high sequence identities to domestic cat-derived isolates, although some isolates form different subclusters within the phylogenetic tree. In conclusion, 9 out of 15 wild felid species from three different continents were found to be infected with feline hemoplasmas. The effect of feline hemoplasma infections on wild felid populations needs to be further investigated.", "journal": "Journal of clinical microbiology", "doi": "10.1128/JCM.02005-06", "deposited_data": "Sim", "nuccore_ids": "114223773, 114223772, 114223771, 114223770, 114223769, 114223768, 114223767, 111434172, 111434171, 111434170, 111434169, 111434168, 111434167, 111434166, 111434165, 111434164, 111434163, 111434162, 111434161, 111434160, 111434159, 111434158, 111434157, 111434156, 111434155, 111434154, 111434153, 111434152", "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17275833", "author": "Schwab S", "n_authors": 7, "title": "Non-suppurative meningoencephalitis of unknown origin in cats and dogs: an immunohistochemical study.", "abstract": "Non-suppurative meningoencephalitis of unknown cause is a frequent finding in dogs and cats. Fifty-three dogs and 33 cats with non-suppurative meningoencephalitis of unknown aetiology were examined immunohistochemically for 18 different infectious agents, including viruses, bacteria and prion protein(Sc). In 14 (26%) of the dogs and 13 (39%) of the cats a causative agent was identified in the central nervous system (CNS), two dogs and one cat giving positive results for two infectious agents simultaneously. The study revealed infections with known causative agents (porcine herpes virus 1, feline infectious peritonitis virus, Escherichia coli) and a new disease pattern of parvovirus infection in the CNS of dogs and cats. Infection of the CNS with feline leukaemia virus was found in a cat. Five dogs and four cats gave positive results for West Nile virus (WNV) antigen. In one dog, canine parainfluenza virus antigen was detected in the brain. Four dogs and four cats gave positive results for encephalomyocarditis virus (EMCV). The significance of the detection of WNV and EMCV antigen requires further study. The aetiology remained undetermined in 39 dogs (74%) and 20 cats (61%). Although it is possible that non-infectious causes play a more important role than previously thought, infections with hitherto unrecognized agents cannot be ruled out.", "journal": "Journal of comparative pathology", "doi": "10.1016/j.jcpa.2006.11.006", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17240486", "author": "Hofmann-Lehmann R", "n_authors": 10, "title": "Vaccination against the feline leukaemia virus: outcome and response categories and long-term follow-up.", "abstract": "Feline leukaemia virus (FeLV) is a pathogen inducing fatal disease in cats worldwide. By applying sensitive molecular assays, efficacious commonly used FeLV vaccines that protect cats from antigenaemia were found not to prevent proviral integration and minimal viral replication after challenge. Nonetheless, vaccines protected cats from FeLV-associated disease and prolonged life expectancy. The spectrum of host response categories was refined by investigating plasma viral RNA loads. All cats initially fought similar virus loads, although subsequently loads were associated with infection outcomes. Persistence of plasma viral RNA was moderately associated with reactivation of FeLV infection. In conclusion, sensitive molecular assays are important tools for reviewing pathogenesis of FeLV infection.", "journal": "Vaccine", "doi": "10.1016/j.vaccine.2006.12.022", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17239641", "author": "Courtin F", "n_authors": 5, "title": "A case of feline leprosy caused by Mycobacterium lepraemurium originating from the island of Kythira (Greece): diagnosis and treatment.", "abstract": "A 2-year-old, 4 kg, healthy, domestic shorthair female cat presented with ulcerated subcutaneous nodules on the commissures of its mouth. The cat was negative for feline leukaemia virus and feline immunodeficiency virus. Skin mycobacteriosis was diagnosed after detection of numerous acid-fast bacilli in Ziehl Neelsen-stained smears from the ulcers. Feline leprosy was suspected following preliminary polymerase chain reaction results: positive for Mycobacterium genus but negative for Mycobacterium tuberculosis and Mycobacterium avium complexes. Mycobacterium lepraemurium was later identified following DNA sequence analysis of the 5' end of the 16S rRNA gene and the 16S-23S internal transcribed spacer region. Microscopic lesions consisted of pyogranulomas containing mainly large foamy macrophages with 10-100 intra-cellular acid-fast bacilli per field. The cat was cured after surgery and a 14-week course of clofazimine (30 mg daily) and clarithromycin (50 mg twice daily).", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2006.11.007", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17199493", "author": "Fischer SM", "n_authors": 9, "title": "Response of feral cats to vaccination at the time of neutering.", "abstract": "To determine whether administration of inactivated virus or modified-live virus (MLV) vaccines to feral cats at the time of neutering induces protective serum antiviral antibody titers. Prospective study. 61 feral cats included in a trap-neuter-return program in Florida. Each cat received vaccines against feline panleukopenia virus (FPV), feline herpes virus (FHV), feline calicivirus (FCV), FeLV, and rabies virus (RV). Immediately on completion of surgery, vaccines that contained inactivated RV and FeLV antigens and either MLV or inactivated FPV, FHV, and FCV antigens were administered. Titers of antiviral antibodies (except those against FeLV) were assessed in serum samples obtained immediately prior to surgery and approximately 10 weeks later. Prior to vaccination, some of the cats had protective serum antibody titers against FPV (33%), FHV (21%), FCV (64%), and RV (3%). Following vaccination, the overall proportion of cats with protective serum antiviral antibody titers increased (FPV [90%], FHV [56%], FCV [93%], and RV [98%]). With the exception of the FHV vaccine, there were no differences in the proportions of cats protected with inactivated virus versus MLV vaccines. Results suggest that exposure to FPV, FHV, and FCV is common among feral cats and that a high proportion of cats are susceptible to RV infection. Feral cats appeared to have an excellent immune response following vaccination at the time of neutering. Incorporation of vaccination into trap-neuter-return programs is likely to protect the health of individual cats and possibly reduce the disease burden in the community.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.230.1.52", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17157440", "author": "Martín-Sánchez J", "n_authors": 6, "title": "Infection by Leishmania infantum in cats: epidemiological study in Spain.", "abstract": "More than 40 cases of feline leishmaniasis have been reported in the scientific literature. The influence of some immunodepressive conditions of viral origin, such as leukemia and feline immunodeficiency, are still unknown. The purpose of this study was to assess the prevalence of Leishmania infection in cats and possible relations with these viral infections. Markers of Leishmania infection were searched in 183 cats from Southern Spain by IFAT, PCR, Giemsa stain and culture, with a follow-up of positive cats. Seropositivity was 60.0% (Ab titer > or =10) and 28.3% of animals presented Ab titers > or =40. Around 25.7% of the cats studied were parasitemic and some of them remained positive for months. Combining both data, 70.6% of the feline population was, or could be, infected. We observed a negative association between seropositivity to Leishmania and infection by FeLV. Hence, production of antibodies against the parasite appears to be compromised in cats with leukemia, which have a prevalence of 36% in our study. In contrast, we found no association with feline immunodeficiency. The results makes us doubt the value of conventional serological methods to detect active Leishmania infection in cats.", "journal": "Veterinary parasitology", "doi": "10.1016/j.vetpar.2006.11.005", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17046042", "author": "Cheng HH", "n_authors": 3, "title": "Feline leukemia virus T entry is dependent on both expression levels and specific interactions between cofactor and receptor.", "abstract": "Feline leukemia virus (FeLV) subgroup T uses both a multiple membrane-spanning receptor, FePit1, and a soluble cofactor, FeLIX, to enter feline cells. FeLIX is expressed from endogenous FeLV-related sequence and resembles the receptor binding domain (RBD) of the viral envelope protein. It remains unclear whether FeLV-T receptor activity requires specific residues within FePit1 and FeLIX and/or a threshold level of receptor/cofactor expression. To address this, we examined FeLV-T infection of cells expressing variable levels of FePit1 and other gammaretroviral receptors in the presence of variable amounts of soluble cofactor, either RBD or the envelope surface subunit (SU). Cofactor-receptor pairs fall into three groups with regard to mediating FeLV-T infection: those that are efficient at all concentrations tested, such as FePit1 and FeLIX; those requiring high expression of both cofactor and receptor; and those that are non-functional as receptors even at high expression. This suggests that both expression levels and specific interactions with receptor and cofactor are critical for mediating entry of FeLV-T.", "journal": "Virology", "doi": "10.1016/j.virol.2006.09.004", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "16863698", "author": "Arjona A", "n_authors": 8, "title": "Evaluation of a novel nested PCR for the routine diagnosis of feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV).", "abstract": "Laboratory diagnosis of feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) usually involves both viruses, as the clinical signs are similar and coinfection may occur. Serological methods may not represent an accurate diagnosis: maternal antibodies or cross-reactions may give false positive results to FIV, and false negative results may occur in latent FeLV status, or in certain FIV infection stages. A nested polymerase chain reaction (PCR) technique was designed to detect FeLV, FIV and feline endogenous retrovirus simultaneously. The detection of endogenous sequences was considered indicative of successful DNA extraction. The technique was used to diagnose FIV and FeLV in the blood cells of 179 cats. The kappa value with the serological data was 0.69 for FeLV and 0.87 for FIV. The joint detection of FeLV and FIV by this novel nested PCR is sensitive, specific, fast and convenient, and its applicability for clinical diagnosis is promising, as the direct evidence of the presence of the virus is more realistic than the indirect data provided by the serological detection.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2006.05.009", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "16861024", "author": "Pinches MD", "n_authors": 6, "title": "Diagnosis of feline leukaemia virus infection by semi-quantitative real-time polymerase chain reaction.", "abstract": "In this paper the design and use of a semi-quantitative real-time polymerase chain reaction assay (RT-PCR) for feline leukaemia virus (FeLV) provirus is described. Its performance is evaluated against established methods of FeLV diagnosis, including virus isolation and enzyme-linked immunoassay (ELISA) in a population of naturally infected cats. The RT-PCR assay is found to have both a high sensitivity (0.92) and specificity (0.99) when examined by expectation maximisation methods and is also able to detect a large number of cats with low FeLV proviral loads that were negative by other conventional test methods.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2006.05.008", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "19228920", "author": "Snowden K", "n_authors": 12, "title": "Vertically integrated educational collaboration between a college of veterinary medicine and a non-profit animal shelter.", "abstract": "The College of Veterinary Medicine and Biomedical Sciences (CVMBS) at Texas A&M University (TAMU) has developed a multifaceted program in partnership with the Brazos Animal Shelter to provide teaching opportunities with shelter animals during all four years of the professional curriculum. In the first three semesters of the professional program, students working in small groups spend two hours per semester at the shelter performing physical examinations, administering vaccinations and anthelmintics, completing heartworm or FeLV/FIV testing, and performing simple medical treatments. In an expanded fourth-year program, groups of six students spend 16 contact hours at the shelter during two-week rotations, completing similar tasks. Through this program, each student practices animal-handling skills and routine procedures on an average of 150 to 200 dogs and cats. In addition, during third- and fourth-year surgery courses, student teams spay or neuter an average of 12 to 18 dogs or cats each week. More than 800 animals are spayed/neutered annually through this program, and each student directly participates in 12 to 15 spay/neuter survival surgeries. The program represents a creative approach to veterinary training that conscientiously uses animal resources in a positive fashion. We believe that this is a successful partnership between a state-supported veterinary college and a non-profit shelter that benefits both agencies. We encourage other veterinary colleges to explore similar partnership opportunities to provide optimal training for professional students while using animal resources efficiently.", "journal": "Journal of veterinary medical education", "doi": "10.3138/jvme.35.4.637", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "19178669", "author": "Krick EL", "n_authors": 7, "title": "Description of clinical and pathological findings, treatment and outcome of feline large granular lymphocyte lymphoma (1996-2004).", "abstract": "Feline large granular lymphocyte (LGL) lymphoma is an uncommon, morphologically distinct variant of feline lymphoma. Limited information exists in the literature regarding pathological and immunohistochemical descriptions, clinical findings, treatment and survival times. The purpose of this study was to describe clinical features, treatment and outcome in feline LGL lymphoma. Medical records of 45 cats with LGL lymphoma were retrospectively evaluated. Decreased appetite/anorexia, weight loss, lethargy and vomiting were the most commonly reported clinical signs. All cats tested for feline leukaemia virus and feline immunodeficiency virus infection were negative. The mesenteric lymph nodes and small intestine were the most commonly affected organs. One complete response and six partial responses were noted in the 23 cats that received chemotherapy as their initial treatment. Median survival time for cats that were treated was 57 days. Based on these results, feline LGL lymphoma appears to be minimally responsive to chemotherapy and is associated with a grave prognosis.", "journal": "Veterinary and comparative oncology", "doi": "10.1111/j.1476-5829.2007.00146.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "19055577", "author": "Carter JE", "n_authors": 6, "title": "Erythrophagocytic low-grade extranodal T-cell lymphoma in a cat.", "abstract": "A 13-year-old male castrated domestic shorthair cat was presented to the referring veterinarian with a 2-month history of weight loss and lethargy. Splenomegaly, hepatomegaly, nonregenerative anemia, neutropenia, and hyperbilirubinemia were noted. Results of testing for feline immunodeficiency virus, feline leukemia virus, Toxoplasma gondii, and Mycoplasma sp. were negative. On cytologic examination of aspirates from the enlarged spleen and liver, a population of erythrophagocytic round cells was observed. Splenectomy and a liver biopsy were done which revealed a population of CD3+/CD79a- erythrophagocytic mononuclear round cells localized in the hepatic and splenic sinusoids. T-cell PARR (PCR for antigen receptor gene rearrangements) analysis of bone marrow and spleen demonstrated a single band indicative of a clonal proliferation of T cells. Based on the marked splenomegaly, sinusoidal infiltration, lack of lymphadenopathy, and results of cytology, PARR, and immunophenotyping, a diagnosis of low-grade extranodal T-cell lymphoma was made. The cat was treated with chlorambucil and prednisolone; clinical and laboratory abnormalities resolved and the cat has remained clinically normal for 2.5 years. To our knowledge, this report documents the first case of an erythrophagocytic T-cell lymphoma in a cat. The clinicopathologic findings were suggestive of hepatosplenic T-cell lymphoma, a neoplasm described previously only in humans and dogs.", "journal": "Veterinary clinical pathology", "doi": "10.1111/j.1939-165X.2008.00073.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18931078", "author": "Coelho FM", "n_authors": 9, "title": "Naturally occurring feline leukemia virus subgroup A and B infections in urban domestic cats.", "abstract": "A nested-PCR (n-PCR) was used to detect feline leukemia virus (FeLV) proviral DNA in blood samples from 464 sick and 608 healthy domestic cats (Felis catus) selected by convenience, and a significantly high prevalence of FeLV infection was observed. n-PCR results revealed the presence of FeLV proviral DNA in 47.2 % of sick cats and 47.4 % of healthy cats. Phylogenetic analysis revealed that FeLV samples from healthy or sick cats were grouped into separate clades. We determined FeLV subgroups by an n-PCR based on the envelope (env) gene. The partial env gene of FeLV Minas Gerais (MG) samples were compared to various exogenous FeLV isolates and endogenous (enFeLV) provirus from the same region. FeLV-B MG samples were more similar to endogenous sequences and to natural FeLV-B isolates than to either FeLV-A or FeLV-C. The results revealed the circulation of FeLV-B in large populations of urban domestic cats in Brazil.", "journal": "The Journal of general virology", "doi": "10.1099/vir.0.2008/003855-0", "deposited_data": "Sim", "nuccore_ids": "197359152, 197359150, 197359148, 197359146, 197359144, 197359142, 194294255, 194294253, 194294251, 194294250, 194294248, 194294246, 189491029, 167047999, 156254635, 156254633, 156254631, 156254629, 156254627, 156254625, 155604121, 155604120, 155604119, 155604118, 155604116, 154980999, 154980997, 154980995, 154980993, 154980991, 154980989, 154980987, 154980985, 154980983, 154980981, 154980979, 154980977, 154980975, 154980973, 154980971, 154980969, 154980967, 154980965, 154980963, 154980961, 154980959, 154980957, 154980955, 154980953, 113013728, 113013716, 53831047", "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18922639", "author": "Lorentzen L", "n_authors": 2, "title": "Incidence of positive heartworm antibody and antigen tests at IDEXX Laboratories: trends and potential impact on feline heartworm awareness and prevention.", "abstract": "Data from the IDEXX Laboratories Reference Laboratory Network were retrospectively examined for feline heartworm testing trends in testing frequency, geographic bias, and prevalence for the years 2000--2006. Examination of the data supports the commonly held view that veterinarians do not embrace heartworm disease testing or prevention in cats to the same degree they do in dogs. Despite significant awareness and adoption of heartworm testing and prevention in dogs, we hypothesized that heartworm testing rates are lower for cats than for dogs despite a significant prevalence of feline infection. This is important because a perceived low rate of infection in cats is likely to manifest in a low adoption of testing and prevention. In reality, the overall feline heartworm antigen-positive rate is significant--on average 0.9% over the period studied--and in some regions was estimated to be as high as 4.6%. This compares with an average canine heartworm prevalence rate of 1.2%, a feline leukemia virus prevalence of 1.9%, and a feline immunodeficiency prevalence of 1.0%. Based on the low rate of testing and these prevalence rates, practitioners are routinely missing cases of adult feline heartworm infections and the recently defined heartworm-associated respiratory disease (H.A.R.D). Increased antigen testing would result in detection of a significant number of positive cases. In addition, this population of infected cats would represent the \"tip of the iceberg\" relative to the greater number of cats that have early infection or are at risk for infection.", "journal": "Veterinary parasitology", "doi": "10.1016/j.vetpar.2008.09.006", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18783789", "author": "Belluco S", "n_authors": 7, "title": "Spinal cryptococcoma in an immunocompetent cat.", "abstract": "This report describes an unusual case of primary cryptococcoma in the proximal thoracic spinal cord of an 11-year-old immunocompetent cat from a farm on which there were large numbers of pigeons. This animal was referred for examination with progressive paralysis and shown to be free from feline immunodeficiency virus, feline leukaemia virus, feline coronavirus and Toxoplasma gondii. It died 2 months later. At necropsy, the only lesion detected was a malacic area, 4cm in length, in the spinal cord. Histopathological examination of the spinal cord revealed severe granulomatous inflammation associated with large numbers of encapsulated yeast cells. In addition to the granulomatous host response, necrosis, digestion chambers, Gitter cells, spheroids and lymphocytic perivascular cuffs were features of the malacic areas. Immunohistochemistry confirmed the presence of Cryptococcus neoformans var. grubii yeast cells.", "journal": "Journal of comparative pathology", "doi": "10.1016/j.jcpa.2008.06.007", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18695960", "author": "Cattori V", "n_authors": 2, "title": "Absolute quantitation of feline leukemia virus proviral DNA and viral RNA loads by TaqMan real-time PCR and RT-PCR.", "abstract": "Sensitive TaqMan real-time polymerase chain reaction (PCR)-based methods have been developed recently for the detection and quantitation of feline leukemia virus (FeLV) proviral DNA in infected cats. In this chapter, we outline the design and implementation of a TaqMan real-time PCR assay to quantify total FeLV proviral and viral RNA loads in infected cats. The assay is designed to amplify all three FeLV subtypes (A-C), but not FeLV-related endogenous retroviral sequences. The system is tested and optimized using proviral DNA or viral RNA from cells infected with reference strains. The sequence used to produce the standard DNA and RNA is amplified, subcloned into a vector, and sequenced. cRNA is synthesized from the linearized plasmid DNA. Standard DNA and RNA are quantified, diluted and used to determine efficiency, sensitivity, linear amplification range, and precision of the quantitative TaqMan real-time PCR assays.", "journal": "Methods in molecular biology (Clifton, N.J.)", "doi": "10.1007/978-1-60327-040-3_6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18689668", "author": "Franklin SP", "n_authors": 6, "title": "Ocelots on Barro Colorado Island are infected with feline immunodeficiency virus but not other common feline and canine viruses.", "abstract": "Transmission of pathogens from domestic animals to wildlife populations (spill-over) has precipitated local wildlife extinctions in multiple geographic locations. Identifying such events before they cause population declines requires differentiating spillover from endemic disease, a challenge complicated by a lack of baseline data from wildlife populations that are isolated from domestic animals. We tested sera collected from 12 ocelots (Leopardus pardalis) native to Barro Colorado Island, Panama, which is free of domestic animals, for antibodies to feline herpes virus, feline calicivirus, feline corona virus, feline panleukopenia virus, canine distemper virus, and feline immunodeficiency virus (FIV), typically a species-specific infection. Samples also were tested for feline leukemia virus antigens. Positive tests results were only observed for FIV; 50% of the ocelots were positive. We hypothesize that isolation of this population has prevented introduction of pathogens typically attributed to contact with domestic animals. The high density of ocelots on Barro Colorado Island may contribute to a high prevalence of FIV infection, as would be expected with increased contact rates among conspecifics in a geographically restricted population.", "journal": "Journal of wildlife diseases", "doi": "10.7589/0090-3558-44.3.760", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18689639", "author": "Cunningham MW", "n_authors": 14, "title": "Epizootiology and management of feline leukemia virus in the Florida puma.", "abstract": "Feline leukemia virus (FeLV) was not detected in Florida pumas (Puma concolor coryi) in almost 20 yr of surveillance; however, the finding of two FeLV antigen-positive pumas during the 2002-2003 capture season led to an investigation of FeLV in the population. Between January 1990 and April 2007, the proportion of pumas testing FeLV antibody positive increased, with antibody-positive pumas concentrated in the northern portion of puma range. Five of 131 (4%) pumas sampled between July 2000 and April 2007 were viremic, with all cases clustered in Okaloacoochee Slough (OKS). Clinical signs and clinical pathology at capture were absent or included lymphadenopathy, moderate-to-severe anemia, and lymphopenia. All viremic pumas died; causes of death were septicemia (n=2), intraspecific aggression (n=2), and anemia/dehydration (n=1). Outcome after FeLV exposure in pumas was similar to that in domestic cats, with evidence of regressive, latent, and persistent infections. Management of the epizootic included vaccination, and as of April 2007, 52 free-ranging pumas had received one or more inoculations. Vaccinations were concentrated in OKS and in a band between OKS and the remainder of the puma population. There have been no new cases since July 2004; however, the potential for reintroduction of the virus remains.", "journal": "Journal of wildlife diseases", "doi": "10.7589/0090-3558-44.3.537", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18602323", "author": "Axnér E", "n_authors": 4, "title": "Infertility in the cycling queen: seven cases.", "abstract": "In this study we examined seven queens with normal oestrous cycles and a history of infertility after normal matings. We performed clinical examination, vaginal cytology, evaluation of oestradiol, progesterone and total T4 levels, vaginal bacterial culture, ultrasonography, and serum analyses for detection of antibodies against chlamydia and feline leukaemia virus (FeLV) antigenemia. Ovariohysterectomy (OHE) was recommended for 1/7 queens because of pathological uterine changes detected at ultrasonography and clinical examination. Four out of seven queens were treated with antibiotics and two of these had more litters. One of the queens that were treated was not mated again and one was mated without conceiving and was at a later OHE found to have degenerative uterine changes. No treatment was given and no diagnosis could be established in 2/7 queens. Both of them were later ovariohysterectomised and one showed degenerative uterine changes while the uterus of the other queen could not be obtained for follow-up. In summary, 4/7 cats were diagnosed with uterine pathology and no definitive diagnosis could be established for 3/7 queens.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2008.04.005", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18571327", "author": "Lopes AP", "n_authors": 3, "title": "Serological survey of Toxoplasma gondii infection in domestic cats from northeastern Portugal.", "abstract": "Cats are very important hosts in the epidemiological cycle of Toxoplasma gondii, a zoonotic protozoan parasite that can infect humans and many other animal species worldwide. We report a serological survey of antibodies to T. gondii in domestic cats from northeastern Portugal, by means of the modified agglutination test. Three cats had titres of 20 (3.9%), 18 had titres of 40 (23.7%) and 55 animals had titres of > or =800 (72.4%). Results of three seropositive kittens with less than 4 months were not considered for determining the seroprevalence of infection, which was found to be 35.8% (73/204). Differences in the seroprevalence levels were not statistically significant between males (35.6%) and females (36.0%) or pure non-European (26.7%) and European or mixed-breed cats (39.6%). Animals aged 36-71 months and 72-180 months had the highest seroprevalences of infection, i.e. 51.7% and 51.2%, respectively, which significantly differ from the values observed in cats with 2-11 months (14.6%) and 12-35 months (26.3%). Infection levels were also significantly different between cats that lived totally indoors (7.7%) and those that had access to outdoors (45.4%), as well as between cats living alone (13.8%) and those that had contact with other cats (39.4%). Seroprevalence values in cats fed only commercial canned or dried food (22.9%) and animals whose diet included raw or undercooked viscera and/or meat (53.5%) were also significantly different. Furthermore, considering only 108 cats, differences of seropositivity to T. gondii were significant between feline immunodeficiency virus infected and non-infected animals, but this was not observed for feline leukaemia virus. Age, habitat and diet were identified as risk factors for the feline T. gondii infection by logistic regression analysis. Some control measures are suggested based on these findings.", "journal": "Veterinary parasitology", "doi": "10.1016/j.vetpar.2008.05.007", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18503070", "author": "Guiot AL", "n_authors": 5, "title": "Compatibility between a rabies vaccine and a combined vaccine against feline rhinotracheitis, FCV, FPLV and FeLV, and Chlamydophila felis.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.162.21.690", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18501285", "author": "Dunham SP", "n_authors": 2, "title": "Retroviral infections of small animals.", "abstract": "Retroviral infections are particularly important in cats, which are commonly infected with feline leukemia virus and feline immunodeficiency virus. This article describes the biology of these viruses and explores current issues regarding vaccination and diagnosis. The seeming lack of a recognized retrovirus infection in dogs is speculated on, and current and potential future therapies are discussed.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": "10.1016/j.cvsm.2008.03.005", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18498558", "author": "Mylonakis ME", "n_authors": 6, "title": "Acute myelomonocytic leukaemia with short-term spontaneous remission in a cat.", "abstract": "A 2-year-old, spayed female domestic shorthair cat was referred with a history of anorexia and depression of 1 week duration. On physical examination, the cat was lethargic and febrile, with splenomegaly, anisocoria and ulcerative stomatitis. A complete blood count (CBC) and a biochemistry profile showed leukocytosis, numerous blast cells in the peripheral blood, thrombocytopenia, hyperglobulinaemia and a positive test for feline leukaemia virus antigen. A diagnosis of acute myelomonocytic leukaemia was made on the basis of the results of bone marrow cytology, histopathology, and immunochemistry (CD3, CD79a, lysozyme, and myeloperoxidase) tests. Following an unexpected 1-month period of clinical and clinicopathological remission without chemotherapy, the cat relapsed and died 1 week later.", "journal": "Australian veterinary journal", "doi": "10.1111/j.1751-0813.2008.00304.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18460634", "author": "Luaces I", "n_authors": 9, "title": "Detection of Feline leukemia virus in the endangered Iberian lynx (Lynx pardinus).", "abstract": "Feline retroviruses are rarely reported in lynx species. Twenty-one Iberian lynx (Lynx pardinus) blood and tissue samples collected from Doñana National Park and Los Villares (Sierra Morena) in southern Spain during 1993-2003 were analyzed by polymerase chain reaction to amplify nucleic acids from feline retroviruses. Six samples were positive for Feline leukemia virus (FeLV), but no samples tested positive for Feline immunodeficiency virus. The BLAST analysis indicated that 5 of the 6 sequences were closely related to FeLV strain Rickard subgroup A, whereas 1 sequence was identical to FeLV. To the authors' knowledge, this is the first report of FeLV in the endangered Iberian lynx.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/104063870802000325", "deposited_data": "Sim", "nuccore_ids": "126013682, 126013680, 126013678, 126013676, 126013674, 126013672", "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18455463", "author": "Levy J", "n_authors": 7, "title": "2008 American Association of Feline Practitioners' feline retrovirus management guidelines.", "abstract": "Feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) are among the most common infectious diseases of cats. Although vaccines are available for both viruses, identification and segregation of infected cats form the cornerstone for preventing new infections. Guidelines in this report have been developed for diagnosis, prevention, treatment, and management of FeLV and FIV infections. All cats should be tested for FeLV and FIV infections at appropriate intervals based on individual risk assessments. This includes testing at the time of acquisition, following exposure to an infected cat or a cat of unknown infection status, prior to vaccination against FeLV or FIV, prior to entering group housing, and when cats become sick. No test is 100% accurate at all times under all conditions; results should be interpreted along with the patient's health and risk factors. Retroviral tests can diagnose only infection, not clinical disease, and cats infected with FeLV or FIV may live for many years. A decision for euthanasia should never be based solely on whether or not the cat is infected. Vaccination against FeLV is highly recommended in kittens. In adult cats, antiretroviral vaccines are considered non-core and should be administered only if a risk assessment indicates they are appropriate. Few large controlled studies have been performed using antiviral or immunomodulating drugs for the treatment of naturally infected cats. More research is needed to identify best practices to improve long-term outcomes following retroviral infections in cats.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2008.03.002", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18448375", "author": "Kanellos T", "n_authors": 4, "title": "Combined administration in a single injection of a feline multivalent modified live vaccine against FHV, FCV, and FPLV together with a recombinant FeLV vaccine is both safe and efficacious for all four major feline viral pathogens.", "abstract": "Nobivac Tricat, a lyophilised trivalent modified live attenuated vaccine is routinely used to protect cats against three commonly diagnosed feline viral pathogens namely herpesvirus, calicivirus and panleukopenia virus. The recognition of feline leukaemia virus (FeLV) as an important viral pathogen has prompted the development of an efficacious liquid recombinant subunit FeLV vaccine (p45 envelope protein). Lyophilised Tricat vaccine was dissolved in the liquid FeLV vaccine and no detectable deleterious effect on the titre of any of the live virus components was observed after 2h incubation. In vivo studies where the vaccines were mixed in the same syringe prior to inoculation showed no alteration to the safety profile assessed by repeat and overdose studies. Serological comparisons of the modified live viral antibody titres showed no evidence of reduced responses following administration of the mixed products. Challenge studies using pathogenic herpesvirus and FeLV revealed no difference in the degree of clinical protection. This paper shows that neither safety nor efficacy is adversely affected as a result of mixing the two vaccines.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2008.02.001", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18412524", "author": "Goldkamp CE", "n_authors": 4, "title": "Seroprevalences of feline leukemia virus and feline immunodeficiency virus in cats with abscesses or bite wounds and rate of veterinarian compliance with current guidelines for retrovirus testing.", "abstract": "To determine the seroprevalences of and seroconversion rates for FeLV and FIV infection in cats treated for bite wounds and cutaneous abscesses and to evaluate compliance with recommendations to determine the retrovirus infection status of cats at acquisition and 60 days after a high-risk event. Prospective study. 967 cats from 134 veterinary practices in 30 states. Cats with bite wounds or abscesses were evaluated by use of a point-of-care immunoassay for blood-borne FeLV antigen and FIV antibody. Veterinarians were asked to retest cats approximately 60 days later to determine whether seronegative cats had seroconverted after injury. The combined FeLV-FIV status of only 96 (9.9%) cats was known prior to wound treatment. At the time of treatment, 187 (19.3%) cats were seropositive for 1 or both viruses. Age (adult), sex (male), history of cutaneous wounds, and outdoor access were significantly associated with seropositivity. At 73 of 134 (54.5%) veterinary practices, retesting of cats for retrovirus infection status was recommended to owners of 478 cats. Only 64 (13.4%) cats were retested; of these, 3 of 58 (5.2%) cats that were initially seronegative for FIV antibody seroconverted. A high proportion of cats with abscesses or bite wounds were seropositive for FeLV antigen or FIV antibody. Compliance with recommendations to test cats for retrovirus infection status at acquisition or after treatment for injury was low. The FeLV-FIV infection status of cats with potential fight wounds should be determined at time of treatment and again 60 days later.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.232.8.1152", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18407367", "author": "Tandon R", "n_authors": 9, "title": "Association between endogenous feline leukemia virus loads and exogenous feline leukemia virus infection in domestic cats.", "abstract": "Recently, we demonstrated that endogenous feline leukemia virus (enFeLV) loads may vary among cats of different populations and that FeLV-infected cats have higher enFeLV loads than uninfected cats. Thus, we hypothesized that enFeLV might influence the pathogenesis and outcome of FeLV infection. No significant difference in the infection outcome (regressive versus progressive infection) was observed between groups of cats with high or low enFeLV loads following FeLV-A challenge. However, cats with high enFeLV loads showed higher viral replication (plasma viral RNA and p27 antigen levels) than cats with low enFeLV loads in the early phase of the infection. The enFeLV transcription level varied at different time points, but no clear-cut pattern was observed. In conclusion, our results demonstrated an association between enFeLV loads and FeLV replication but not outcome of infection. enFeLV should be considered as an important confounder in experimental FeLV infection or vaccination studies.", "journal": "Virus research", "doi": "10.1016/j.virusres.2008.02.016", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18384012", "author": "de Lange K", "n_authors": 1, "title": "[FELV infection, the kiss of death].", "abstract": null, "journal": "Tijdschrift voor diergeneeskunde", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18321595", "author": "Torres AN", "n_authors": 5, "title": "Development and application of a quantitative real-time PCR assay to detect feline leukemia virus RNA.", "abstract": "We previously defined four categories of feline leukemia virus (FeLV) infection, designated as abortive, regressive, latent, and progressive. To determine if detectable viral DNA is transcriptionally active in the absence of antigenemia, we developed and validated a real-time viral RNA qPCR assay. This assay proved to be highly sensitive, specific, reproducible, and allowed reliable quantitation. We then applied this methodology, together with real-time DNA qPCR and p27 capsid antigen capture ELISA, to examine cats challenged with FeLV. We found that circulating viral RNA and DNA levels were highly correlated and the assays were almost in perfect agreement. This indicates that the vast majority of viral DNA is transcriptionally active, even in the absence of antigenemia. The real-time qPCR assays are more sensitive than the most commonly used FeLV diagnostic assay, the p27 capsid antigen capture ELISA. Application of qPCR assays may add greater depth in understanding of FeLV-host relationships.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2008.01.013", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18315870", "author": "Münk C", "n_authors": 12, "title": "Functions, structure, and read-through alternative splicing of feline APOBEC3 genes.", "abstract": "Over the past years a variety of host restriction genes have been identified in human and mammals that modulate retrovirus infectivity, replication, assembly, and/or cross-species transmission. Among these host-encoded restriction factors, the APOBEC3 (A3; apolipoprotein B mRNA-editing catalytic polypeptide 3) proteins are potent inhibitors of retroviruses and retrotransposons. While primates encode seven of these genes (A3A to A3H), rodents carry only a single A3 gene. Here we identified and characterized several A3 genes in the genome of domestic cat (Felis catus) by analyzing the genomic A3 locus. The cat genome presents one A3H gene and three very similar A3C genes (a-c), probably generated after two consecutive gene duplications. In addition to these four one-domain A3 proteins, a fifth A3, designated A3CH, is expressed by read-through alternative splicing. Specific feline A3 proteins selectively inactivated only defined genera of feline retroviruses: Bet-deficient feline foamy virus was mainly inactivated by feA3Ca, feA3Cb, and feA3Cc, while feA3H and feA3CH were only weakly active. The infectivity of Vif-deficient feline immunodeficiency virus and feline leukemia virus was reduced only by feA3H and feA3CH, but not by any of the feA3Cs. Within Felidae, A3C sequences show significant adaptive selection, but unexpectedly, the A3H sequences present more sites that are under purifying selection. Our data support a complex evolutionary history of expansion, divergence, selection and individual extinction of antiviral A3 genes that parallels the early evolution of Placentalia, becoming more intricate in taxa in which the arms race between host and retroviruses is harsher.", "journal": "Genome biology", "doi": "10.1186/gb-2008-9-3-r48", "deposited_data": "Sim", "nuccore_ids": "411147414, 176865757, 158937937, 158603286, 158603267, 157966949, 157780898, 157780896, 157503535, 157503533, 157503531, 157503529, 157503527, 157503525, 157503523, 157503521, 157503519, 157503517, 157503515, 157422420, 77158589, 68726575, 3369958363, 3369958361, 3369958358, 3369958354, 3369958351, 2450877505, 2080370807, 411147414, 176865757", "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18313764", "author": "Fujino Y", "n_authors": 3, "title": "Molecular pathogenesis of feline leukemia virus-induced malignancies: insertional mutagenesis.", "abstract": "Feline leukemia virus (FeLV), which is subclassified into three subgroups of A, B and C, is a pathogenic retrovirus in cats. FeLV-A is minimally pathogenic, FeLV-C can cause pure red cell aplasia, and FeLV-B is associated with a variety of pathogenic properties such as lymphoma, leukemia and anemia. FeLV-induced neoplasms are caused, at least in part, by somatically acquired insertional mutagenesis in which the integrated provirus may activate a proto-oncogene or disrupt a tumor suppressor gene. The common integration sites for FeLV have been identified in six loci with feline lymphomas: c-myc, flvi-1, flvi-2 (contains bmi-1), fit-1, pim-1 and flit-1. Oncogenic association of the loci includes that c-myc is known as a proto-oncogene, bmi-1 and pim-1 have been recognized as myc-collaborators, fit-1 appears to be closely linked to myb, and flit-1 insertion is shown to be associated with over-expression of a cellular gene, e.g. ACVRL1. Thus, identification of common integration sites for FeLV is a tenable model to clarify oncogenesis. Recent advances in molecular biology and cytogenetics have developed to rapidly detect numbers of retroviral integration sites by genome-wide large-scale analyses. Especially, polymerase chain reaction (PCR)-based strategies and chromosome analyses with fluorescence in situ hybridization (FISH) will be applicable for studies on FeLV.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2008.01.019", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18304650", "author": "Cattori V", "n_authors": 8, "title": "Real-time PCR investigation of feline leukemia virus proviral and viral RNA loads in leukocyte subsets.", "abstract": "Cats exposed to feline leukemia virus (FeLV), a naturally occurring gammaretrovirus develop either progressive or regressive infection. Recent studies using analyses with enhanced sensitivity have correlated loads throughout FeLV with the clinical outcome, though remarkably, during the acute phase of infection, proviral and viral RNA burdens in the peripheral blood do not differ between groups. We hypothesized that viral loads in specific leukocyte subsets influence the infection outcome. Using a method established to determine the proviral and cell-associated viral RNA loads in specific leukocyte subsets, we evaluated viral loads in eleven FeLV-exposed specific pathogen-free (SPF) cats 2.5 years post-infection. Six cats had undergone regressive infection whereas five were persistently viremic. Aviremic cats had lower total proviral blood loads than the persistently infected cats and FeLV proviral DNA was shown to be integrated into genomic DNA in four out of four animals. Lymphocytes were predominantly infected vs. moncytes and granulocytes in aviremic cats. In contrast, persistently viremic cats were provirus-positive in all leukocyte subsets. The acute phase kinetics of FeLV infection were analyzed in two additional cats; an early lymphoreticular phase with productive infection in lymphocytes in both cats and in monocytes in one cat was followed by infection of the granulocytes; both cats became persistently infected. These results indicate that FeLV persistent viremia is associated with secondary viremia of bone marrow origin, whereas regressive cats only sustain a non-productive infection in low numbers of lymphocytes.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2008.01.018", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18296895", "author": "Prihirunkit K", "n_authors": 3, "title": "Acute monoblastic leukemia in a FeLV-positive cat.", "abstract": "A 1.6-year-old male domestic short hair cat was brought to the Veterinary Medical Teaching Hospital, Kasetsart University, with signs of severe anemia, depression, and general lymph node enlargement. Complete blood count revealed leukocytosis and massive undifferentiated blasts. Testing for antibodies specific to feline leukemia virus (FeLV) was positive, and FeLV nucleic acid was confirmed by nested polymerase chain reaction. Base on cytochemistry and ultrastructure, the cat was diagnosed with acute monoblastic leukemia.", "journal": "Journal of veterinary science", "doi": "10.4142/jvs.2008.9.1.109", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18295346", "author": "Hofmann-Lehmann R", "n_authors": 7, "title": "How molecular methods change our views of FeLV infection and vaccination.", "abstract": "FeLV was discovered 40 years ago and vaccines have been commercially available for almost two decades. So far, most FeLV pathogenesis and vaccine studies were conducted assaying parameters, such as virus isolation and antigen detection. Accordingly, regressive infection was characterized by transient or undetectable viremia, while persistent viremia is typically observed in cats with progressive infection. Using real-time polymerase chain reaction assays, the spectrum of host response categories to FeLV infection was recently refined by investigating proviral and plasma viral RNA loads. Cats believed to be immune to FeLV infection were found to turn provirus-positive after virus exposure. Moreover, efficacious FeLV vaccines were found unable to prevent provirus-integration and minimal viral replication. Remarkably, no difference was found in initial proviral and plasma viral RNA loads between cats with different infection outcomes. Only subsequently, the infection outcome is associated with FeLV loads. FeLV provirus was found to persist for years; reoccurrence of viremia and disease development was observed in some cats. Thus, aviremic provirus-positive cats are FeLV carriers and, following reactivation, may act as an infection source. However, integrated viral DNA may also be essential for solid protection and long-lasting maintenance of protective immunity. In conclusion, real-time TaqMan PCR and RT-PCR assays are highly sensitive and specific. They yield a more sensitive measure for FeLV exposure than antigen detection, virus isolation or immunofluoresence assays. We recommend the use of real-time PCR assays to identify FeLV exposed cats, particularly in catteries, and investigate obscure clinical cases that may be FeLV-associated. The use of sensitive molecular methods will contribute to a more in-depth understanding of the FeLV pathogenesis.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2008.01.017", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18295344", "author": "Tandon R", "n_authors": 5, "title": "Quantification of endogenous and exogenous feline leukemia virus sequences by real-time PCR assays.", "abstract": "Endogenous retroviruses are integrated in the genome of most vertebrates. They represent footprints of ancient retroviral infection and are vertically transmitted from parents to their offspring. In the genome of all domestic cats, sequences closely related to exogenous FeLV known as endogenous feline leukemia virus (enFeLV), are present. enFeLV are incapable of giving rise to infectious virus particles. However, transcription and translation of enFeLV have been demonstrated in tissues of healthy cats and in feline cell lines. The presence of enFeLV-env has been shown in specific embryonic tissues and adult thymic cells. In addition, the enFeLV-env region recombines with FeLV subgroup A giving rise to an infectious FeLV-B virus. enFeLV envelope protein, FeLIX (FeLV infectivity X-essory protein) is also involved in mediating FeLV-T infection. In order to test the hypothesis that the enFeLV loads play a role in exogenous FeLV-A infection and pathogenesis, quantitative real-time PCR and RT-PCR assays were developed. An assay, specific to U3 region of all different subtypes of exogenous FeLV, was designed and applied to quantify exogenous FeLV proviral or viral load in cats, while three real-time PCR assays were designed to quantify U3 and env enFeLV loads (two within U3 amplifying different sequences; one within env). enFeLV loads were investigated in blood samples derived from Swiss privately owned domestic cats, specific pathogen-free (SPF) cats and European wildcats (Felis silvestris silvestris). Significant differences in enFeLV loads were observed between privately owned cats and SPF cats as well as among SPF cats originating from different catteries and among domestic cats of different breeds. When privately owned cats were compared, FeLV-infected cats had higher loads than uninfected cats. In addition, wildcats had higher enFeLV loads than domestic cats. In conclusion, the quantitative real-time PCR assays described herein are important prerequisites to quantify enFeLV proviral loads in felids and thus are important tools to investigate the role of enFeLV loads in FeLV infection.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2008.01.027", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18289704", "author": "Levy LS", "n_authors": 1, "title": "Advances in understanding molecular determinants in FeLV pathology.", "abstract": "Feline leukemia virus (FeLV) occurs in nature not as a single genomic species but as a family of closely related viruses. The disease outcome of natural FeLV infection is variable and likely reflects genetic variation both in the virus and the naturally outbreeding host population. A series of studies have been undertaken with the objectives of examining natural FeLV genetic variation, the selective pressures operative in FeLV infection that lead to predominance of natural variants, and the consequences for infection and disease progression. Genetic variation among FeLV isolates was examined in a cohort of naturally infected cats with thymic lymphoma of T-cell origin, non-T-cell multicentric lymphoma, myeloproliferative disorder or anemia. The predominant isolate in the cohort, designated FeLV-945, was identified exclusively in disorders of non-T-cell origin. The FeLV-945 LTR was shown to contain a unique 21-bp repeat element, triplicated in tandem downstream of enhancer. The 21-bp triplication was shown to act as a transcriptional enhancer and to confer a replicative advantage through the assembly of a distinctive transcription factor complex. Oncogene utilization during tumor induction by FeLV-945 was studied using a recombinant Moloney murine leukemia virus containing the FeLV-945 LTR. This approach identified novel loci of common proviral integration in tumors, including the regulatory subunit of PI-3Kgamma. Mutational changes identified in FeLV-945 SU were shown not to alter receptor usage as measured by host range and superinfection interference, but to significantly increase the efficiency of receptor binding. To determine whether the unique sequence elements of FeLV-945 influence the course of infection and disease in vivo, recombinant viruses were constructed in which the FeLV-945 LTR alone, or the FeLV-945 SU gene and LTR were substituted into the prototype isolate FeLV-A/61E. Longitudinal studies of infected animals showed that substitution of the FeLV-945 LTR into FeLV-A/61E resulted in a significantly more rapid disease onset, but did not alter the tumorigenic spectrum. In contrast, substitution of both the FeLV-945 LTR and SU gene changed the disease outcome entirely. Together, these observations indicate that the distinctive LTR and SU gene of FeLV-945 mediate a rapid pathogenesis with distinctive clinical features and oncogenic mechanisms.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2008.01.008", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18289290", "author": "Levy JK", "n_authors": 8, "title": "Infectious diseases of dogs and cats on Isabela Island, Galapagos.", "abstract": "Vaccination and importation of dogs and cats are prohibited in the Galapagos, resulting in a uniquely isolated population. The purpose of this study was to determine the prevalence of infectious diseases of dogs and cats that impact their health, could spill over to native wildlife, or sentinel diseases of concern to humans. The isolation of dogs and cats in the Galapagos protects them from diseases common in mainland populations. Ninety-five dogs and 52 cats presented during a neutering campaign. A prospective cross-sectional study was performed. Blood was collected for serological and DNA evaluation of a panel of infectious diseases. Antibodies against parvovirus (100%), parainfluenza virus (100%), adenovirus 1/2 (66-67%), and distemper virus (22%) were present in dogs. Dirofilaria immitis was also common in dogs (34%), with lower prevalences of Wolbachia pipiens (22%), Bartonella sp. (13%), Ehrlichia/Anaplasma spp. (1%), and Mycoplasma haemocanis (1%) observed. Antibodies against panleukopenia virus (67%), Toxoplasma gondii (63%), calicivirus (44%), and herpesvirus 1 (10%) were detected in cats. Feline leukemia virus antigen, feline immunodeficiency virus antibody, or coronavirus antibodies were not detected. Bartonella sp. (44%) infections were common in cats, but only one was infected with M. haemofelis. Despite their relative seclusion from the rest of the world, cats and dogs of Isabela were exposed to many pathogens found in mainland South America. Parasite prophylaxis, neutering, and strict enforcement of animal movement restrictions would control a majority of the diseases. In the absence of vaccination, a reservoir of susceptible animals remains vulnerable to new disease introductions.", "journal": "Journal of veterinary internal medicine", "doi": "10.1111/j.1939-1676.2007.0034.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18276180", "author": "Bauer N", "n_authors": 4, "title": "Prevalence of feline haemotropic mycoplasmas in convenience samples of cats in Germany.", "abstract": "The aim of this prospective study was to evaluate the prevalence of feline haemotropic mycoplasmas in Germany, to determine probable risk factors for these infections and to compare the diagnostic value of microscopic examination of blood smears to polymerase chain reaction (PCR). For the prevalence study, convenience samples (Ethylene diamine-tetraacetic acid (EDTA) blood) from 262 (64.5% male and 35.5% female) cats were included. A PCR for the detection of Mycoplasma haemofelis (MHF) and 'Candidatus Mycoplasma haemominutum' (CMH) as well as a feline leukaemia virus (FeLV)/feline immunodeficiency virus (FIV) enzyme-linked immunoassay was performed. Blood smears from 224 cats were examined and the sensitivity and specificity of the microscopic diagnosis were determined. The prevalence of CMH, MHF, and CMH/MHF co-infection was 22.5%, 4.5%, and 0.8%, respectively. CMH was significantly associated with male gender (P=0.047), older age (P=0.0015) and both FeLV (P=0.002) and FIV infections (P<0.0001). However, there was no association between the presence of anaemia and CMH/MHF infection. The respective sensitivity and specificity of the microscopic diagnosis were 10.3% and 87.1% for a CMH infection and 0.0% and 98.0% for MHF infection.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2007.12.004", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18258918", "author": "Keel SB", "n_authors": 12, "title": "A heme export protein is required for red blood cell differentiation and iron homeostasis.", "abstract": "Hemoproteins are critical for the function and integrity of aerobic cells. However, free heme is toxic. Therefore, cells must balance heme synthesis with its use. We previously demonstrated that the feline leukemia virus, subgroup C, receptor (FLVCR) exports cytoplasmic heme. Here, we show that FLVCR-null mice lack definitive erythropoiesis, have craniofacial and limb deformities resembling those of patients with Diamond-Blackfan anemia, and die in midgestation. Mice with FLVCR that is deleted neonatally develop a severe macrocytic anemia with proerythroblast maturation arrest, which suggests that erythroid precursors export excess heme to ensure survival. We further demonstrate that FLVCR mediates heme export from macrophages that ingest senescent red cells and regulates hepatic iron. Thus, the trafficking of heme, and not just elemental iron, facilitates erythropoiesis and systemic iron balance.", "journal": "Science (New York, N.Y.)", "doi": "10.1126/science.1151133", "deposited_data": "Sim", "nuccore_ids": "2666210344, 924181778, 924181484, 124486924, 3382334014, 3382246094, 2666210344, 924181778, 924181484, 124486924", "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18258118", "author": "Brown MA", "n_authors": 6, "title": "Genetic characterization of feline leukemia virus from Florida panthers.", "abstract": "From 2002 through 2005, an outbreak of feline leukemia virus (FeLV) occurred in Florida panthers (Puma concolor coryi). Clinical signs included lymphadenopathy, anemia, septicemia, and weight loss; 5 panthers died. Not associated with FeLV outcome were the genetic heritage of the panthers (pure Florida vs. Texas/Florida crosses) and co-infection with feline immunodeficiency virus. Genetic analysis of panther FeLV, designated FeLV-Pco, determined that the outbreak likely came from 1 cross-species transmission from a domestic cat. The FeLV-Pco virus was closely related to the domestic cat exogenous FeLV-A subgroup in lacking recombinant segments derived from endogenous FeLV. FeLV-Pco sequences were most similar to the well-characterized FeLV-945 strain, which is highly virulent and strongly pathogenic in domestic cats because of unique long terminal repeat and envelope sequences. These unique features may also account for the severity of the outbreak after cross-species transmission to the panther.", "journal": "Emerging infectious diseases", "doi": "10.3201/eid1402.070981", "deposited_data": "Sim", "nuccore_ids": "158523425, 158523424, 158523423, 158523422, 158523420, 158523418, 158523416, 158523414, 158523412, 158523410", "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18241101", "author": "Sykes JE", "n_authors": 4, "title": "Prevalences of various hemoplasma species among cats in the United States with possible hemoplasmosis.", "abstract": "To determine prevalences of various hemoplasma species among cats in the United States with possible hemoplasmosis and identify risk factors for and clinicopathologic abnormalities associated with infection with each species. Cross-sectional study. Animals-310 cats with cytologic evidence of hemoplasmosis (n = 9) or acute or regenerative anemia (309). Blood samples were tested by means of a broad-spectrum conventional PCR assay for hemoplasma DNA and by means of 3 separate species-specific real-time PCR assays for DNA from \"Candidatus Mycoplasma haemominutum\" (Mhm), Mycoplasma haemofelis (Mhf), and \"Candidatus Mycoplasma turicensis\" (Mtc). Overall prevalences of Mhm, Mhf, and Mtc infection were 23.2% (72/310), 4.8% (15/310), and 6.5% (20/310), respectively. Mixed infections were detected in 20 (6.5%) cats. Cats infected with hemoplasmas were more likely to be male than were uninfected cats. Infection with FeLV or FIV was significantly associated with infection with Mhf. Compared with uninfected cats, cats infected with Mhf had higher reticulocyte counts, nucleated RBC counts, and mean corpuscular volume; cats infected with Mhm had higher mean corpuscular volume; and cats infected with Mtc had higher monocyte counts. Results supported the suggestion that these 3 hemoplasma species commonly occur among cats in the United States and that pathogenicity of the 3 species varies.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.232.3.372", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "32214935", "author": "Roelke ME", "n_authors": 11, "title": "Exposure to disease agents in the endangered Iberian lynx (Lynx pardinus).", "abstract": "The Iberian lynx (", "journal": "European journal of wildlife research", "doi": "10.1007/s10344-007-0122-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "17945326", "author": "Rey MA", "n_authors": 3, "title": "The C domain in the surface envelope glycoprotein of subgroup C feline leukemia virus is a second receptor-binding domain.", "abstract": "The receptor-binding domain (RBD) in the surface (SU) subunit of gammaretrovirus envelope glycoprotein is critical for determining the host receptor specificity of the virus. This domain is separated from the carboxy terminal C domain (Cdom) of SU by a proline-rich region. In this study, we show that the Cdom region in the SU from subgroup C feline leukemia virus (FeLV-C) forms a second receptor-binding domain that is distinct from its RBD, and which can independently bind to its host receptor FLVCR1, in the absence of RBD. Furthermore, our results suggest that residues located in the C2 disulfide-bonded loop in FeLV-C Cdom are critical for SU binding to FLVCR1 and for virus infection. We propose that binding of FeLV-C SU to FLVCR1 involves interaction of two receptor-binding domains (RBD and Cdom) with FLVCR1, and that this mechanism of interaction is conserved for other gammaretroviruses. Our results could have important implications for designing gammaretrovirus vectors that can efficiently infect specific target cells.", "journal": "Virology", "doi": "10.1016/j.virol.2007.09.011", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "17913532", "author": "Gradner G", "n_authors": 5, "title": "Use of latissimus dorsi and abdominal external oblique muscle for reconstruction of a thoracic wall defect in a cat with feline osteochondromatosis.", "abstract": "A 4-year-old, male castrated European shorthair cat was presented with a firm mass palpable on the right caudal rib cage. Lateral and ventrodorsal radiographs of the thorax revealed a 4x3x2cm large, expansile and radiodense mass originating from the distal part of the 13th rib. After removal of the tumour, which was histopathologically confirmed as feline osteochondromatosis, the diaphragm, omentum, external abdominal oblique and latissimus dorsi muscles were used to reconstruct the defect. Feline osteochondromatosis is induced by retroviruses, eg, feline leukaemia virus, for which the cat tested positive. The tumour was removed for palliative reasons, because such tumours have the tendency to transform into osteosarcomas. Six months after the surgical excision the cat showed no clinical signs of reoccurrence.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2007.06.005", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "17905624", "author": "Macieira DB", "n_authors": 7, "title": "Prevalence and risk factors for hemoplasmas in domestic cats naturally infected with feline immunodeficiency virus and/or feline leukemia virus in Rio de Janeiro--Brazil.", "abstract": "The aim of this study was to determine the prevalence and risk factors for Mycoplasma haemofelis (Mhf) and 'Candidatus Mycoplasma haemominutum' (Mhm) infections in domestic cats tested for feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) with a commercial enzyme-linked immunosorbent assay (ELISA) kit. Based on serological testing, cats were grouped as i) FIV-positive (n=25); ii) FeLV-positive (n=39); iii) FIV/FeLV-positive (n=8); and iv) FIV/FeLV-negative (n=77). Complete blood counts were followed by DNA extraction, species-specific polymerase chain reaction (16S rRNA gene) for Mhf and Mhm and Southern blotting for all animals. Mhf DNA was found in 4.0, 2.6, 12.5 and 7.8% of the cats from groups i, ii, iii and iv, respectively, while 32, 5.1, 50 and 5.2% of these animals had an Mhm infection. Cats with FIV (OR=4.25, P=0.009) and both FIV and FeLV (OR=7.56, P=0.014) were at greater risk of being hemoplasma infected than retroviral-negative cats, mainly due to Mhm infection (OR=8.59, P=0.001 and OR=18.25, P=0.001, respectively). Among pure-breed cats, FIV-positive status was associated with hemoplasma infection (OR 45.0, P=0.001).", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2007.08.002", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "17766156", "author": "Quimby JM", "n_authors": 6, "title": "Evaluation of the association of Bartonella species, feline herpesvirus 1, feline calicivirus, feline leukemia virus and feline immunodeficiency virus with chronic feline gingivostomatitis.", "abstract": "Gingivostomatitis (GS) is a significant condition in cats because of oral discomfort and associated periodontal disease. Several infectious agents have been associated with the presence of GS, but a causal relationship is unclear. The cats in this study were housed together, had a history of flea exposure, and were vaccinated with a modified live FVRCP product. There were nine cats with active GS and 36 unaffected cats at the time of sample collection. Serum was tested for feline leukemia virus (FeLV) antigen and antibodies against feline immunodeficiency virus, feline calicivirus (FCV), feline herpesvirus 1 (FHV-1), and Bartonella species (enzyme-linked immunosorbent assay and Western blot immunoassay). PCR assays for Bartonella species and FHV-1 and a reverse transcriptase PCR assay for FCV were performed on blood and throat swabs. All cats were negative for FeLV. Assay results failed to correlate to the presence of GS in the group of cats studied.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2007.05.007", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "20218331", "author": "Miyazawa T", "n_authors": 1, "title": "[Receptors for animal retroviruses].", "abstract": "Diseases caused by animal retroviruses have been recognized since 19th century in veterinary field. Most livestock and companion animals have own retroviruses. To disclose the receptors for these retroviruses will be useful for understanding retroviral pathogenesis, developments of anti-retroviral drugs and vectors for human and animal gene therapies. Of retroviruses in veterinary field, receptors for the following viruses have been identified; equine infectious anemia virus, feline immunodeficiency virus, feline leukemia virus subgroups A, B, C, and T, Jaagsiekte sheep retrovirus, enzootic nasal tumor virus, avian leukosis virus subgroups A, B, C, D, E, and J, reticuloendotheliosis virus, RD-114 virus (a feline endogenous retrovirus), and porcine endogenous retrovirus subgroup A. Primate lentiviruses require two molecules (CD4 and chemokine receptors such as CXCR4) as receptors. Likewise, feline immunodeficiency virus also requires two molecules, i.e., CD134 (an activation marker of CD4 T cells) and CXCR4 in infection. Gammaretroviruses utilize multi-spanning transmembrane proteins, most of which are transporters of amino acids, vitamins and inorganic ions. Betaretroviruses and alpharetroviruses utilize transmembrane and/or GPI-anchored proteins as receptors. In this review, I overviewed receptors for animal retroviruses in veterinary field.", "journal": "Uirusu", "doi": "10.2222/jsv.59.223", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "20003366", "author": "Kessler Y", "n_authors": 10, "title": "Quantitative TaqMan real-time PCR assays for gene expression normalisation in feline tissues.", "abstract": "Gene expression analysis is an important tool in contemporary research, with real-time PCR as the method of choice for quantifying transcription levels. Co-analysis of suitable reference genes is crucial for accurate expression normalisation. Reference gene expression may vary, e.g., among species or tissues; thus, candidate genes must be tested prior to use in expression studies. The domestic cat is an important study subject in both medical research and veterinary medicine. The aim of the present study was to develop TaqMan real-time PCR assays for eight potential reference genes and to test their applicability for feline samples, including blood, lymphoid, endocrine, and gastrointestinal tissues from healthy cats, and neoplastic tissues from FeLV-infected cats. RNA extraction from tissues was optimised for minimal genomic DNA (gDNA) contamination without use of a DNase treatment. Real-time PCR assays were established and optimised for v-abl Abelson murine leukaemia viral oncogene homolog (ABL), beta-actin (ACTB), beta-2-microglobulin (B2M), beta-glucuronidase (GUSB), hydroxymethyl-bilane synthase (HMBS), hypoxanthine phosphoribosyltransferase (HPRT), ribosomal protein S7 (RPS7), and tryptophan 5-monooxygenase activation protein, zeta polypeptide (YWHAZ). The presence of pseudogenes was confirmed for four of the eight investigated genes (ACTB, HPRT, RPS7, and YWHAZ). The assays were tested together with previously developed TaqMan assays for feline glyceraldehyde-3-phosphate dehydrogenase (GAPDH) and the universal 18S rRNA gene. Significant differences were found among the expression levels of the ten candidate reference genes, with a ~106-fold expression difference between the most abundant (18S rRNA) and the least abundant genes (ABL, GUSB, and HMBS). The expression stability determined by the geNorm and NormFinder programs differed significantly. Using the ANOVA-based NormFinder program, RPS7 was the most stable gene in the tissues studied, followed by ACTB and ABL; B2M, HPRT, and the 18S rRNA genes were the least stable ones. The reference gene expression stability varied considerably among the feline tissues investigated. No tested gene was optimal for normalisation in all tissues. For the majority of the tissues, two to three reference genes were necessary for accurate normalisation. The present study yields essential information on the correct choice of feline reference genes depending on the tissues analysed.", "journal": "BMC molecular biology", "doi": "10.1186/1471-2199-10-106", "deposited_data": "Sim", "nuccore_ids": "283444940", "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "21994560", "author": "Gómez-Lucía E", "n_authors": 4, "title": "Effect of type-I interferon on retroviruses.", "abstract": "Type-I interferons (IFN-I) play an important role in the innate immune response to several retroviruses. They seem to be effective in controlling the in vivo infection, though many of the clinical signs of retroviral infection may be due to their continual presence which over-stimulates the immune system and activates apoptosis. IFN-I not only affect the immune system, but also operate directly on virus replication. Most data suggest that the in vitro treatment with IFN-I of retrovirus infected cells inhibits the final stages of virogenesis, avoiding the correct assembly of viral particles and their budding, even though the mechanism is not well understood. However, in some retroviruses IFN-I may also act at a previous stage as some retroviral LTRs posses sequences homologous to the IFN-stimulated response element (ISRE). When stimulated, ISREs control viral transcription. HIV-1 displays several mechanisms for evading IFN-I, such as through Tat and Nef. Besides IFN-α and IFN-β, some other type I IFN, such as IFN-τ and IFN-ω, have potent antiviral activity and are promising treatment drugs.", "journal": "Viruses", "doi": "10.3390/v1030545", "deposited_data": "Sim", "nuccore_ids": "2462584046, 2462584044, 2462584042, 2462528378, 2462528376, 2462528375, 2462528373, 2462528372, 2462528371, 2462528370, 2462528369, 2462528367, 2462528366, 2462528364, 2462528362, 2462528360, 2462528358, 2462528356, 2287780780, 2217339105, 2217339103, 2217339101, 2217285262, 2217285261, 2217285260, 2217285258, 2217285256, 2217285255, 2217285254, 2217285252, 2217285251, 2217285250, 2217285249, 2217285248, 2217285247, 2217285246, 2217285245, 1890529932, 1889492917, 1889459598, 1889455422, 1889451272, 1700660493, 1676355477, 1675034452, 1653962426, 1653962420, 1519314687, 1519312460, 1519245841, 1394338294, 1159731398", "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "19901342", "author": "Grant CK", "n_authors": 5, "title": "Improved health and survival of FIV-infected cats is associated with the presence of autoantibodies to the primary receptor, CD134.", "abstract": "We analyzed antibody responses in sera from feline immunodeficiency virus (FIV)-infected and uninfected cats. A strong antiviral response to the viral surface glycoprotein (SU) was noted in both natural and experimental infections. In addition, 143 of 226 FIV-infected animals (63%) also expressed antibodies to the primary binding receptor, CD134, whereas cats infected with other feline RNA viruses, including calicivirus, coronavirus, herpesvirus, and feline leukemia virus, did not. Both affinity-purified anti-CD134 and anti-SU antibodies blocked FIV infection ex vivo. FACS analyses revealed that the anti-CD134 antibodies bound to a cryptic epitope on the receptor that was only exposed when SU bound to CD134. Anti-CD134 binding caused displacement of SU from the surface of the cell and inhibition of infection. The presence of antibodies to CD134 correlated with lower virus loads and a better overall health status in FIV(+) cats, whereas anti-SU antibodies were present independent of health status. The findings are consistent with a role for antireceptor antibodies in protection from virus spread and disease progression.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.0911307106", "deposited_data": "Sim", "nuccore_ids": "57163732, 57163732", "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "19721785", "author": "Little S", "n_authors": 4, "title": "Seroprevalence of feline leukemia virus and feline immunodeficiency virus infection among cats in Canada.", "abstract": "The purposes of this study were to determine the seroprevalence of feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) infection among cats in Canada and to identify risk factors for seropositivity. Signalment, lifestyle factors, and test results for FeLV antigen and FIV antibody were analyzed for 11 144 cats from the 10 Canadian provinces. Seroprevalence for FIV antibody was 4.3% and seroprevalence for FeLV antigen was 3.4%. Fifty-eight cats (0.5%) were seropositive for both viruses. Seroprevalence varied geographically. Factors such as age, gender, health status, and lifestyle were significantly associated with risk of FeLV and FIV seropositivity. The results suggest that cats in Canada are at risk of retrovirus infection and support current recommendations that the retrovirus status of all cats should be known.", "journal": "The Canadian veterinary journal = La revue veterinaire canadienne", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "23966534", "author": "Ray JD", "n_authors": 4, "title": "A treatment of stomatitis and treatment in cats.", "abstract": "A three-year old spayed female Domestic Shorthair was diagnosed with chronic plasmacytic stomatitis involving the mandibular gingiva caudal to the canine teeth. The cat presented with excessive drooling and bleeding from the gums. The definitive diagnosis was made on oral tissue samples obtained by biopsy and submitted for histopathology. The management included bilateral extraction of the mandibular and maxillary premolars and molars with closure of the defects utilizing a single mucosal flap in each quadrant. Preoperative laboratory evaluation and negative feline leukemia virus and/or feline immunodeficiency virus testing were performed. Following surgical removal of the teeth, the inflammation improved for eight months before returning. The cat now maintains comfort with parenteral injections of corticosteroid approximately every three to five months. Compounding pharmacists play a vital role in the treatment of felines due to their small size concerns with toxicity and sensitivity to certain medications and their reluctance to be dosed. Even in medical cases where a surgical procedure is the final resolution to an issue, compounded preparations are often required prior to surgery, during surgery, and post surgery for the purpose of eliminating pain and discomfort in the feline patient.", "journal": "International journal of pharmaceutical compounding", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "19717569", "author": "Farrell KB", "n_authors": 3, "title": "New structural arrangement of the extracellular regions of the phosphate transporter SLC20A1, the receptor for gibbon ape leukemia virus.", "abstract": "Infection of a host cell by a retrovirus requires an initial interaction with a cellular receptor. For numerous gammaretroviruses, such as the gibbon ape leukemia virus, woolly monkey virus, feline leukemia virus subgroup B, feline leukemia virus subgroup T, and 10A1 murine leukemia virus, this receptor is the human type III sodium-dependent inorganic phosphate transporter, SLC20A1, formerly known as PiT1. Understanding the critical receptor functionalities and interactions with the virus that lead to successful infection requires that we first know the surface structure of the cellular receptor. Previous molecular modeling from the protein sequence, and limited empirical data, predicted a protein with 10 transmembrane helices. Here we undertake the biochemical approach of substituted cysteine accessibility mutagenesis to resolve the topology of this receptor in live cells. We discover that there are segments of the protein that are unexpectedly exposed to the outside milieu. By using information determined by substituted cysteine accessibility mutagenesis to set constraints in HMMTOP, a hidden Markov model-based transmembrane topology prediction method, we now propose a comprehensive topological model for SLC20A1, a transmembrane protein with 12 transmembrane helices and 7 extracellular regions, that varies from previous models and should permit approaches that define both virus interaction and transport function.", "journal": "The Journal of biological chemistry", "doi": "10.1074/jbc.M109.022566", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "19645840", "author": "Gleich S", "n_authors": 2, "title": "Hematology and serum biochemistry of feline immunodeficiency virus-infected and feline leukemia virus-infected cats.", "abstract": "Hematological and biochemical values in cats naturally infected by feline immunodeficiency virus (FIV) or feline leukemia virus (FeLV) are not completely documented. Report differences in laboratory values between FIV- or FeLV-infected and noninfected and between FIV- and FeLV-infected cats. Three thousand seven hundred and eighty client-owned cats tested for FIV and FeLV. Retrospective study. Evaluation of clinicopathologic changes in cats with defined FIV and FeLV status and for which laboratory data were available. FIV-infected cats were more likely to be neutropenic (odds ratio [OR]=3.6, 95% confidence interval [95% CI] 2.1-6.2, P < .0001) and had lower serum activities of aspartate aminotransferase and glutamate dehydrogenase than control cats; serum total protein (8.1 +/- 1.1 versus 7.6 +/- 1.3 g/dL, P < .001) and gamma-globulin concentrations (2.2 +/- 1.1 versus 1.7 +/- 1.3 g/dL, P < .001) were higher than in uninfected cats. Compared with controls, FeLV-infected cats had a higher risk of anemia (OR = 3.8, 95% CI 2.4-6.0, P < .0001), thrombocytopenia (OR = 5.0, 95% CI 3.0-8.4, P < .0001), neutropenia (OR = 3.6, 95% CI 2.1-6.1, P < .0001), lymphocytosis (OR = 2.8, 95% CI 1.6-4.8, P= .0002), and lower erythrocyte counts (6.13 +/- 2.95 x 10(3) versus 8.72 +/- 2.18 x 10(3)/microL, P < .001), thrombocyte counts (253.591 +/- 171.841 x 10(3) versus 333.506 +/- 156.033 x 10(3)/microL, P < .001), hematocrit (28.72 +/- 12.86 versus 37.67 +/- 8.90%, P < .001), hemoglobin and creatinine concentration. Hematologic abnormalities are common in FeLV-infected but not in FIV-infected cats. Clinicopathologic abnormalities are less frequent in FIV-infected cats and might reflect an unspecific immunologic response.", "journal": "Journal of veterinary internal medicine", "doi": "10.1111/j.1939-1676.2009.0303.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "19616984", "author": "Gleich SE", "n_authors": 3, "title": "Prevalence of feline immunodeficiency virus and feline leukaemia virus among client-owned cats and risk factors for infection in Germany.", "abstract": "This study was conducted to determine prevalence and risk factors for retrovirus infection of infected cats in a large cat population in Germany by evaluation of 17,462 client-owned cats that were tested for the presence of feline immunodeficiency virus (FIV) antibodies or feline leukaemia virus (FeLV) antigen. The owners of a subset of 100 cats were contacted to determine their cat's survival times. Prevalence of FIV and FeLV was 3.2% and 3.6%, respectively, remaining stable for FIV, but decreasing for FeLV (6-1%) over 10 years. Median age was 6 years in FIV- and 3 years in FeLV-infected cats. Risk factors for FIV infection were male gender, older age, mixed breed, access to outdoor, aggressive behaviour, and FeLV co-infection; and for FeLV infection contact to other cats, aggressive behaviour, and FIV co-infection. Median survival time of FIV-infected cats was not significantly different to non-infected cats, whereas FeLV-infected cats had significantly shorter median survival times than non-infected cats.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2009.05.019", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "19569487", "author": "Guimaraes AM", "n_authors": 19, "title": "Survey of feline leukemia virus and feline coronaviruses in captive neotropical wild felids from Southern Brazil.", "abstract": "A total of 57 captive neotropical felids (one Leopardus geoffroyi, 14 Leopardus pardalis, 17 Leopardus wiedii, 22 Leopardus tigrinus, and three Puma yagouaroundi) from the Itaipu Binacional Wildlife Research Center (Refúgio Bela Vista, Southern Brazil) were anesthetized for blood collection. Feces samples were available for 44 animals, including one L. geoffroyi, eight L. pardalis, 14 L. wiedii, 20 L. tigrinus, and one P. yagouaroundi. Total DNA and RNA were extracted from blood and feces, respectively, using commercial kits. Blood DNA samples were evaluated by polymerase chain reaction (PCR) for feline leukemia virus (FeLV) proviral DNA, whereas reverse transcriptase-PCR was run on fecal samples for detection of coronavirus RNA. None of the samples were positive for coronaviruses. A male L. pardalis and a female L. tigrinus were positive for FeLV proviral DNA, and identities of PCR products were confirmed by sequencing. This is the first evidence of FeLV proviral DNA in these species in Southern Brazil.", "journal": "Journal of zoo and wildlife medicine : official publication of the American Association of Zoo Veterinarians", "doi": "10.1638/2008-0067.1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "19498296", "author": "Blanco K", "n_authors": 5, "title": "Seroprevalence of viral infections in domestic cats in Costa Rica.", "abstract": "A cross-sectional survey of a convenient sample of domestic cats from Costa Rica's greater metropolitan area was carried out to determine the prevalence of antibodies against feline herpesvirus type 1 (FHV-1), feline parvovirus (FPV), feline immunodeficiency virus (FIV) and antigens of feline leukemia virus (FeLV). Blood samples were collected from at least 96 cats from June 1998 to December 2001; data related to the individual cats and household variables were obtained using a questionnaire. Antibodies against FHV-1 were found in 71.9% of the cats sampled, but only 25.0% of them had a history of previous vaccination. The prevalence of FPV was 92.8%, and all positive cats showed protective antibodies titres; however, only 16.5% of them were previously vaccinated. Antigens of FeLV were detected in 16.7% of the sampled cats; 11 (64.7%) of the 17 positive cats were older than 1 year at the time of testing. No differences were found between the percentage of seropositive males and females. Antibodies against FIV were detected in 8.8% of the samples tested; 8 (88.8%) of the seropositive cats were older than 1 year of age, and a greater proportion of seropositive males (66.6%) was found.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.71.661", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "19481036", "author": "Lutz H", "n_authors": 16, "title": "Feline leukaemia. ABCD guidelines on prevention and management.", "abstract": "Feline leukaemia virus (FeLV) is a retrovirus that may induce depression of the immune system, anaemia and/or lymphoma. Over the past 25 years, the prevalence of FeLV infection has decreased considerably, thanks both to reliable tests for the identification of viraemic carriers and to effective vaccines. Transmission between cats occurs mainly through friendly contacts, but also through biting. In large groups of non-vaccinated cats, around 30-40% will develop persistent viraemia, 30-40% show transient viraemia and 20-30% seroconvert. Young kittens are especially susceptible to FeLV infection. The most common signs of persistent FeLV viraemia are immune suppression, anaemia and lymphoma. Less common signs are immune-mediated disease, chronic enteritis, reproductive disorders and peripheral neuropathies. Most persistently viraemic cats die within 2-3 years. In low-prevalence areas there may be a risk of false-positive results; a doubtful positive test result in a healthy cat should therefore be confirmed, preferably by PCR for provirus. Asymptomatic FeLV-positive cats should be retested. Supportive therapy and good nursing care are required. Secondary infections should be treated promptly. Cats infected with FeLV should remain indoors. Vaccination against common pathogens should be maintained. Inactivated vaccines are recommended. The virus does not survive for long outside the host. All cats with an uncertain FeLV status should be tested prior to vaccination. All healthy cats at potential risk of exposure should be vaccinated against FeLV. Kittens should be vaccinated at 8-9 weeks of age, with a second vaccination at 12 weeks, followed by a booster 1 year later. The ABCD suggests that, in cats older than 3-4 years of age, a booster every 2-3 years suffices, in view of the significantly lower susceptibility of older cats.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2009.05.005", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "19425174", "author": "Henke D", "n_authors": 3, "title": "Polyganglioradiculoneuritis in a young cat: clinical and histopathological findings.", "abstract": "An 18-month-old European shorthair cat was presented with a two week history of progressive decrease in consciousness, ambulatory tetraparesis, moderate ataxia and generalised decreased-to-absent postural reactions. Bilateral facial and nasal hypalgesia, absent menace response and anisocoria were found, and segmental spinal reflexes were normal. Neurological signs progressed to nonambulatory tetraparesis, tremor and spinal hyperalgesia. Histopathological examination revealed a mild-to-moderate lymphoplasmacytic and histiocytic infiltration, predominantly in the dorsal spinal roots, cranial nerves and ganglia in association with marked demyelination and proliferation of Schwann cells. Neurons and axons were preserved. Lesions were multi-focal and varied in severity. A predominantly sensory polyganglioradiculoneuritis was diagnosed. This lesion has not been reported previously in cats. Rabies, herpesviruses, feline infectious peritonitis, feline immunodeficiency virus, Toxoplasma gondii and feline leukaemia virus were excluded as possible aetiologies. Infections by other viruses or an autoimmune disease are discussed.", "journal": "The Journal of small animal practice", "doi": "10.1111/j.1748-5827.2009.00703.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "19385716", "author": "Dubey JP", "n_authors": 10, "title": "Seroprevalence of Toxoplasma gondii and concurrent Bartonella spp., feline immunodeficiency virus, and feline leukemia virus infections in cats from Grenada, West Indies.", "abstract": "Toxoplasma gondii and Bartonella spp. are zoonotic pathogens of cats. Feline immunodeficiency virus (FIV) and feline leukemia virus (FeLv) are related to human immunodeficiency virus, and human leukemia virus, respectively; all of these viruses are immunosuppressive. In the present study, the prevalence of antibodies to T. gondi, Bartonella spp., FIV, as well as FeLv antigen were determined in sera from 75 domestic and 101 feral cats (Felis catus) from the Caribbean island of Grenada, West Indies. Using a modified agglutination test, antibodies to T. gondii were found in 23 (30.6%) of the 75 pet cats with titers of 1:25 in 1, 1:50 in 3, 1:400 in 4, 1:500 in 12, 1:800 in 2, and 1:1,600 in 1, and 28 (27.7%) of 101 feral cats with titers of 1:25 in 4, 1:50 in 7, 1:200 in 4, 1:400 in 1, 1:500 in 3, 1:800 in 2, 1:1,600 in 3, and 1:3,200 in 4. Overall, in both pet and feral cats, the seroprevalence increased with age. Antibodies to Bartonella spp. were found in 38 (50.6%) of the 75 pet cats and 52.4% of 101 feral cats. Antibodies to FIV were found in 6 domestic and 22 feral cats. None of the 176 cats was positive for FeLv antigen. There was no correlation among T. gondii, Bartonella spp., and FIV seropositivity.", "journal": "The Journal of parasitology", "doi": "10.1645/GE-2114.1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "19369334", "author": "Shalev Z", "n_authors": 7, "title": "Identification of a feline leukemia virus variant that can use THTR1, FLVCR1, and FLVCR2 for infection.", "abstract": "The pathogenic subgroup C feline leukemia virus (FeLV-C) arises in infected cats as a result of mutations in the envelope (Env) of the subgroup A FeLV (FeLV-A). To better understand emergence of FeLV-C and potential FeLV intermediates that may arise, we characterized FeLV Env sequences from the primary FY981 FeLV isolate previously derived from an anemic cat. Here, we report the characterization of the novel FY981 FeLV Env that is highly related to FeLV-A Env but whose variable region A (VRA) receptor recognition sequence partially resembles the VRA sequence from the prototypical FeLV-C/Sarma Env. Pseudotype viruses bearing FY981 Env were capable of infecting feline, human, and guinea pig cells, suggestive of a subgroup C phenotype, but also infected porcine ST-IOWA cells that are normally resistant to FeLV-C and to FeLV-A. Analysis of the host receptor used by FY981 suggests that FY981 can use both the FeLV-C receptor FLVCR1 and the feline FeLV-A receptor THTR1 for infection. However, our results suggest that FY981 infection of ST-IOWA cells is not mediated by the porcine homologue of FLVCR1 and THTR1 but by an alternative receptor, which we have now identified as the FLVCR1-related protein FLVCR2. Together, our results suggest that FY981 FeLV uses FLVCR1, FLVCR2, and THTR1 as receptors. Our findings suggest the possibility that pathogenic FeLV-C arises in FeLV-infected cats through intermediates that are multitropic in their receptor use.", "journal": "Journal of virology", "doi": "10.1128/JVI.02317-08", "deposited_data": "Sim", "nuccore_ids": "2553878297, 218664486, 217416477, 214003739, 214003737, 214003735, 214003733, 3348212564, 3348212563, 3348212562, 3348189445, 3348189444, 3348189442, 3348141379, 2553878297, 2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556, 218664486, 217416477", "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "19336234", "author": "Forman LW", "n_authors": 5, "title": "Identification of LTR-specific small non-coding RNA in FeLV infected cells.", "abstract": "The U3-LTR region of leukemia viruses transactivates cancer-related signaling pathways through the production of a non-coding RNA transcript although the role of this transcript in virus infection remains unknown. In this study we demonstrate for the first time that an long terminal repeat (LTR)-specific small non-coding RNA is produced from a feline leukemia virus (FeLV)-infected feline cell line. RNA cloning identified this as a 104 base transcript that originates from the U3-LTR region. We also demonstrate that in in vitro assays this LTR-RNA transcript activates NF kappaB signaling. Taken together, our findings suggest a possible role for this LTR transcript in FeLV pathogenesis.", "journal": "FEBS letters", "doi": "10.1016/j.febslet.2009.03.056", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "19307586", "author": "Mazari PM", "n_authors": 5, "title": "Single-round selection yields a unique retroviral envelope utilizing GPR172A as its host receptor.", "abstract": "The recognition by a viral envelope of its cognate host-cell receptor is the initial critical step in defining the viral host-range and tissue specificity. This study combines a single-round of selection of a random envelope library with a parallel cDNA screen for receptor function to identify a distinct retroviral envelope/receptor pair. The 11-aa targeting domain of the modified feline leukemia virus envelope consists of a constrained peptide. Critical to the binding of the constrained peptide envelope to its cellular receptor are a pair of internal cysteines and an essential Trp required for maintenance of titers >10(5) lacZ staining units per milliliter. The receptor used for viral entry is the human GPR172A protein, a G-protein-coupled receptor isolated from osteosarcoma cells. The ability to generate unique envelopes capable of using tissue- or disease-specific receptors marks an advance in the development of efficient gene-therapy vectors.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.0809741106", "deposited_data": "Sim", "nuccore_ids": "2960097062, 2960097048, 2960097020, 2960097018, 2960096875, 2960096863, 2956823554, 2287780768, 1747200850, 1700447900, 1677531722, 1677530828, 1677530788, 1677530357, 1677499065, 1677498262", "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "19270739", "author": "Meli ML", "n_authors": 15, "title": "Feline leukemia virus and other pathogens as important threats to the survival of the critically endangered Iberian lynx (Lynx pardinus).", "abstract": "The Iberian lynx (Lynx pardinus) is considered the most endangered felid species in the world. In order to save this species, the Spanish authorities implemented a captive breeding program recruiting lynxes from the wild. In this context, a retrospective survey on prevalence of selected feline pathogens in free-ranging lynxes was initiated. We systematically analyzed the prevalence and importance of seven viral, one protozoan (Cytauxzoon felis), and several bacterial (e.g., hemotropic mycoplasma) infections in 77 of approximately 200 remaining free-ranging Iberian lynxes of the Doñana and Sierra Morena areas, in Southern Spain, between 2003 and 2007. With the exception of feline immunodeficiency virus (FIV), evidence of infection by all tested feline pathogens was found in Iberian lynxes. Fourteen lynxes were feline leukemia virus (FeLV) provirus-positive; eleven of these were antigenemic (FeLV p27 positive). All 14 animals tested negative for other viral infections. During a six-month period in 2007, six of the provirus-positive antigenemic lynxes died. Infection with FeLV but not with other infectious agents was associated with mortality (p<0.001). Sequencing of the FeLV surface glycoprotein gene revealed a common origin for ten of the eleven samples. The ten sequences were closely related to FeLV-A/61E, originally isolated from cats in the USA. Endogenous FeLV sequences were not detected. It was concluded that the FeLV infection most likely originated from domestic cats invading the lynx's habitats. Data available regarding the time frame, co-infections, and outcome of FeLV-infections suggest that, in contrast to the domestic cat, the FeLV strain affecting the lynxes in 2007 is highly virulent to this species. Our data argue strongly for vaccination of lynxes and domestic cats in and around lynx's habitats in order to prevent further spread of the virus as well as reduction the domestic cat population if the lynx population is to be maintained.", "journal": "PloS one", "doi": "10.1371/journal.pone.0004744", "deposited_data": "Sim", "nuccore_ids": "167650792, 167650790, 167650788, 167650786, 167650784, 167650782, 167650780, 167650778, 167650776, 167650774, 167650772, 167650770, 167650768, 167650766, 167650764, 167650762, 167650760, 167650758, 167650756, 167650754", "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "19254857", "author": "Ström Holst B", "n_authors": 2, "title": "The Swedish breeding cat: population description, infectious diseases and reproductive performance evaluated by a questionnaire.", "abstract": "The questionnaire based study gives a combined description of management, infectious diseases and reproductive performance in breeding catteries during 1 year. The mean number of cats per cattery was 6.1, and 25% of the breeders let some of their cats have free access to outdoors. Breeders reported that infection with feline panleukopenia virus, feline immunodeficiency virus or feline leukaemia virus was uncommon, but 8% of the breeders had sold or had themselves owned a cat that died of feline infectious peritonitis. Presence of conjunctivitis was reported by 33.3% of the breeders. Mean litter size was 3.7+/-1.5, with 9.7% stillbirths and 8.3% kitten mortality week 1-12. The percentage of stillborn kittens increased with the age of the queen and litter size, and also differed among breeds. Kitten mortality differed among breeds, but did not increase with age of the queen. Seven percent of the litters were delivered by caesarean section, significantly more during winter and positively associated with presence of stillborn kittens.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2009.01.008", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "19203775", "author": "Fujino Y", "n_authors": 9, "title": "Identification of a novel common proviral integration site, flit-1, in feline leukemia virus induced thymic lymphoma.", "abstract": "A new proviral integration site for feline leukemia virus (FeLV), termed flit-1, was identified from feline thymic lymphoma. Among 35 FeLV-related tumors examined, 5 of 25 thymic lymphomas demonstrated proviral insertion within flit-1 locus whereas none of four alimentary and five multicentric lymphomas and one T-lymphoid leukemia examined had rearrangement in this region. Extensive sequence analysis has shown that flit-1, which is noncoding, is conserved on human chromosome 12 and mouse chromosome 15. The human and murine homologs of flit-1 are positioned approximately 30-kb upstream to activin-A receptor type II-like 1 (ACVRL1/ALK1) gene. Expression of ACVRL1 mRNA was examined in two of five lymphomas with flit-1 rearrangement and detected in both of the two whereas normal thymuses and seven lymphoid tumors without flit-1 rearrangement had no detectable expression. Therefore, flit-1 appears to represent a novel FeLV proviral common integration domain that may influence lymphomagenesis as insertional mutagenesis.", "journal": "Virology", "doi": "10.1016/j.virol.2009.01.021", "deposited_data": "Sim", "nuccore_ids": "166788434, 166788433, 166788432, 57163856, 16580804, 2130998586, 2130998584, 2130998582, 2130998580, 2130998579, 57163856", "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "32214938", "author": "Millán J", "n_authors": 2, "title": "A serological survey of common feline pathogens in free-living European wildcats (Felis silvestris) in central Spain.", "abstract": "Twenty-five serum samples of 22 free-living European wildcats (", "journal": "European journal of wildlife research", "doi": "10.1007/s10344-008-0246-z", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "19035458", "author": "Hisasue M", "n_authors": 10, "title": "Myelodysplastic syndromes and acute myeloid leukemia in cats infected with feline leukemia virus clone33 containing a unique long terminal repeat.", "abstract": "Feline leukemia virus (FeLV) clone33 was obtained from a domestic cat with acute myeloid leukemia (AML). The long terminal repeat (LTR) of this virus, like the LTRs present in FeLV from other cats with AML, differs from the LTRs of other known FeLV in that it has 3 tandem direct 47-bp repeats in the upstream region of the enhancer (URE). Here, we injected cats with FeLV clone33 and found 41% developed myelodysplastic syndromes (MDS) characterized by peripheral blood cytopenias and dysplastic changes in the bone marrow. Some of the cats with MDS eventually developed AML. The bone marrow of the majority of cats with FeLV clone33 induced MDS produced fewer erythroid and myeloid colonies upon being cultured with erythropoietin or granulocyte-macrophage colony-stimulating factor (GM-SCF) than bone marrow from normal control cats. Furthermore, the bone marrow of some of the cats expressed high-levels of the apoptosis-related genes TNF-alpha and survivin. Analysis of the proviral sequences obtained from 13 cats with naturally occurring MDS reveal they also bear the characteristic URE repeats seen in the LTR of FeLV clone33 and other proviruses from cats with AML. Deletions and mutations within the enhancer elements are frequently observed in naturally occurring MDS as well as AML. These results suggest that FeLV variants that bear URE repeats in their LTR strongly associate with the induction of both MDS and AML in cats.", "journal": "International journal of cancer", "doi": "10.1002/ijc.24050", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "18842363", "author": "Gomes-Keller MA", "n_authors": 6, "title": "Fecal shedding of infectious feline leukemia virus and its nucleic acids: a transmission potential.", "abstract": "Although it is assumed that fecal shedding of feline leukemia virus (FeLV) constitutes a transmission potential, no study has been performed showing that feces of infected cats can be a source of infection. In this study, we investigated fecal viral shedding of FeLV and its role in viral pathogenesis with the goal to improve infection control. FeLV RNA and DNA levels were determined in rectal swabs of experimentally infected cats by real-time PCR, and the results were correlated with proviral and viral loads in whole blood and plasma, respectively, and plasma p27 levels. All antigenemic cats shed FeLV RNA and DNA in feces. To determine whether the viral RNA detected was infectious, virus isolation from feces was also performed. Infectious virus was isolated from feces of antigenemic cats, and these results perfectly correlated with the isolation of virus from plasma. Naïve cats exposed to these feces seroconverted, showing that infection through feces took place, but remained negative for the presence of FeLV provirus and p27 in blood, an outcome so far not described. Some of the organs collected after euthanasia were provirus positive at low copy numbers. From these results it is concluded that fecal shedding of FeLV plays a role in transmission, but it is probably of secondary importance in viral pathogenesis. Nevertheless, sharing of litter pans by susceptible and viremic cats could increase the environmental infectious pressure and appropriate measures should be taken to avoid unnecessary viral exposure.", "journal": "Veterinary microbiology", "doi": "10.1016/j.vetmic.2008.08.011", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "18774240", "author": "Cattori V", "n_authors": 6, "title": "The kinetics of feline leukaemia virus shedding in experimentally infected cats are associated with infection outcome.", "abstract": "Feline leukaemia virus (FeLV) infection in felids results mainly from oronasal exposure to infectious saliva and nasal secretions, but the potential for viral transmission through faeces and urine has not been completely characterized. In order to assess and compare potential FeLV transmission routes, we determined the viral kinetics in plasma, saliva, faeces and urine during early experimental FeLV infection (up to week 15 post-exposure) in specific pathogen-free cats. In addition to monitoring p27 antigen levels measured by ELISA, we evaluated the presence of infectious particles by cell culture assays and quantified viral RNA loads by a quantitative real-time TaqMan polymerase chain reaction. RNA load was associated with infection outcome (high load-progressive infection; low load-regressive infection) not only in plasma, but also in saliva, faeces and urine. Infectious virus was isolated from the saliva, faeces and urine of infected cats with progressive infection as early as 3-6 weeks post-infection, but usually not in cats with regressive infection. In cats with progressive infection, therefore, not only saliva but also faeces and to some extent urine might represent potential FeLV transmission routes. These results should be taken into account when modelling FeLV-host interactions and assessing FeLV transmission risk. Moreover, during early FeLV infection, detection of viral RNA in saliva may be used as an indicator of recent virus exposure, even in cats without detectable antigenaemia/viraemia. To determine the clinically relevant outcome of FeLV infection in exposed cats, however, p27 antigen levels in the peripheral blood should be measured.", "journal": "Veterinary microbiology", "doi": "10.1016/j.vetmic.2008.07.001", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "18555712", "author": "Millán J", "n_authors": 9, "title": "Disease threats to the endangered Iberian lynx (Lynx pardinus).", "abstract": "The Iberian lynx, (Lynx pardinus), is the most endangered felid in the world. To determine whether sympatric carnivores are reservoirs of pathogens posing a disease risk for the lynx, evidence of exposure to 17 viral, bacterial and protozoan agents was investigated in 176 carnivores comprising 26 free-living lynx, 53 domestic cats, 28 dogs, 33 red foxes (Vulpes vulpes), 24 Egyptian mongooses (Herpestes ichneumon), 10 common genets (Genetta genetta) and 2 Eurasian badgers (Meles meles) in the areas inhabited by the last two populations of Iberian lynx, both in Andalusia (South-Western Spain). The results indicated that the lynx had low rates of contact with viral pathogens, with one seropositive finding each for feline leukemia virus, parvovirus and canine adenovirus-1, whereas contact with bacteria and protozoa appeared more frequent. Active infections with parvovirus, Ehrlichia spp., Mycobacterium bovis, Leptospira interrogans and Cytauxzoon spp. were confirmed. In contrast, 53% of the domestic cats were exposed to some infectious agent (prevalence range 4.5-11.4%). Antibodies to canine distemper virus and parvovirus were frequently found in dogs (32% and 42%, respectively) and foxes (30% and 12%). Past or present infections with parvovirus, Ehrlichia spp., Chlamydophila spp., M. bovis, Salmonella enterica, L. interrogans, Toxoplasma gondii, and Neospora caninum were also detected in these and other species surveyed. Questionnaires to owners revealed that 14% of the dogs but none of the cats had been vaccinated, and no cat had been neutered. Based on the apparent absence of acquired immunity of the lynx against infectious agents, the frequent detection of agents among sympatric carnivores, and the reported lack of immunocompetence of the Iberian lynx, a disease outbreak among the local abundant carnivores may pose a serious disease risk for lynx conservation.", "journal": "Veterinary journal (London, England : 1997)", "doi": "10.1016/j.tvjl.2008.04.005", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "21126679", "author": "Weiss A", "n_authors": 1, "title": "FeLV-associated chronic lymphocytic leukemia.", "abstract": null, "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2010.09.016", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "21070897", "author": "Rajadhyaksha AM", "n_authors": 12, "title": "Mutations in FLVCR1 cause posterior column ataxia and retinitis pigmentosa.", "abstract": "The study of inherited retinal diseases has advanced our knowledge of the cellular and molecular mechanisms involved in sensory neural signaling. Dysfunction of two specific sensory modalities, vision and proprioception, characterizes the phenotype of the rare, autosomal-recessive disorder posterior column ataxia and retinitis pigmentosa (PCARP). Using targeted DNA capture and high-throughput sequencing, we analyzed the entire 4.2 Mb candidate sequence on chromosome 1q32 to find the gene mutated in PCARP in a single family. Employing comprehensive bioinformatic analysis and filtering, we identified a single-nucleotide coding variant in the feline leukemia virus subgroup C cellular receptor 1 (FLVCR1), a gene encoding a heme-transporter protein. Sanger sequencing confirmed the FLVCR1 mutation in this family and identified different homozygous missense mutations located within the protein's transmembrane channel segment in two other unrelated families with PCARP. To determine whether the selective pathologic features of PCARP correlated with FLVCR1 expression, we examined wild-type mouse Flvcr1 mRNA levels in the posterior column of the spinal cord and the retina via quantitative real-time reverse-transcriptase PCR. The Flvcr1 mRNA levels were most abundant in the retina, followed by the posterior column of the spinal cord and other brain regions. These results suggest that aberrant FLVCR1 causes a selective degeneration of a subpopulation of neurons in the retina and the posterior columns of the spinal cord via dysregulation of heme or iron homeostasis. This finding broadens the molecular basis of sensory neural signaling to include common mechanisms that involve proprioception and vision.", "journal": "American journal of human genetics", "doi": "10.1016/j.ajhg.2010.10.013", "deposited_data": "Sim", "nuccore_ids": "1519315556, 322812157, 2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "21038808", "author": "Belgard S", "n_authors": 5, "title": "Relevance of feline calicivirus, feline immunodeficiency virus, feline leukemia virus, feline herpesvirus and Bartonella henselae in cats with chronic gingivostomatitis.", "abstract": "Despite its common occurrence, the aetiology of chronic gingivostomatitis in cats remains uncertain. Aetiology is likely multifactorial, and several infectious agents may be associated with chronic gingivostomatitis. The purpose of this study was to investigate the prevalence of feline calicivirus (FCV), feline immunodeficiency virus (FIV), feline leukemia virus (FeLV), feline herpesvirus (FHV), and Bartonella henselae (B. henselae) in cats with chronic gingivostomatitis and in an age-matched control group. In addition, other factors, e. g., environmental conditions were investigated. In 52 cats with chronic gingivostomatitis and 50 healthy age-matched control cats, the presence of FCV ribonucleic acid (RNA), and FHV deoxyribonucleic acid (DNA) (polymerase chain reaction [PCR] from oropharyngeal swabs), and B. henselae DNA (PCR from oropharyngeal swabs and blood), as well as FeLV antigen (serum), and antibodies against FCV, B. henselae, and FIV (serum) were examined. FCV RNA was significantly more common in cats with chronic gingivostomatitis (53.8%, p < 0.001) than in controls (14.0%); a significant difference was also found in the prevalence of antibodies to FCV between the cats with chronic gingivostomatitis (78.8%, p = 0.023) and controls (58.0%). Of the other infectious agents investigated, there was no significant difference in the prevalence between the cats with chronic gingivostomatitis and the controls. The results of this study allow the conclusion that FCV, but no other infectious agents, is commonly associated with chronic gingivostomatitis in cats.", "journal": "Berliner und Munchener tierarztliche Wochenschrift", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "21036089", "author": "Weiss AT", "n_authors": 3, "title": "Prevalence of feline leukaemia provirus DNA in feline lymphomas.", "abstract": "A significant drop in the prevalence of feline leukaemia virus (FeLV) antigenaemic cats and antigen-associated lymphomas has been observed after the introduction of FeLV vaccination and antigen-testing with removal of persistently antigenaemic cats. However, recent reports have indicated that regressively infected cats may contain FeLV provirus DNA and that lymphoma development may be associated with the presence of provirus alone. In the present study, we investigated the presence of FeLV antigen and provirus DNA in 50 lymphomas by immunohistochemistry and semi-nested polymerase chain reaction, respectively. Interestingly, almost 80% of T-cell lymphomas and 60% of B-cell lymphomas contained provirus DNA while only 21% of T-cell lymphomas and 11% of B-cell lymphomas expressed FeLV antigen. In conclusion, our results support previous hypotheses that vaccination and removal of persistently antigenaemic cats have led to a drop in FeLV antigen-expressing lymphomas. However, FeLV provirus DNA is still present in a high percentage of feline lymphomas.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2010.07.006", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20957616", "author": "Jirjis FF", "n_authors": 7, "title": "Protection against feline leukemia virus challenge for at least 2 years after vaccination with an inactivated feline leukemia virus vaccine.", "abstract": "Twelve cats were vaccinated at 8 and 11 weeks of age with a commercially available inactivated FeLV vaccine (Nobivac FeLV, Intervet/Schering-Plough Animal Health). Eleven cats served as age-matched, placebo-vaccinated controls. All cats were kept in isolation for 2 years after vaccination and were then challenged with virulent FeLV to evaluate vaccine efficacy and duration of immunity. Cats were monitored for 12 weeks after challenge for development of persistent viremia using a commercial FeLV p27 ELISA. Persistent viremia developed in all 11 (100%) of the control cats, whereas 10 of 12 (83%) vaccinated cats were fully protected from persistent viremia following challenge. The results demonstrate that the vaccine used in this study protects cats from persistent FeLV viremia for at least 2 years after vaccination.", "journal": "Veterinary therapeutics : research in applied veterinary medicine", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20823265", "author": "Duffy SP", "n_authors": 7, "title": "The Fowler syndrome-associated protein FLVCR2 is an importer of heme.", "abstract": "Mutations in FLVCR2, a cell surface protein related by homology and membrane topology to the heme exporter/retroviral receptor FLVCR1, have recently been associated with Fowler syndrome, a vascular disorder of the brain. We previously identified FLVCR2 to function as a receptor for FY981 feline leukemia virus (FeLV). However, the cellular function of FLVCR2 remains unresolved. Here, we report the cellular function of FLVCR2 as an importer of heme, based on the following observations. First, FLVCR2 binds to hemin-conjugated agarose, and binding is competed by free hemin. Second, mammalian cells and Xenopus laevis oocytes expressing FLVCR2 display enhanced heme uptake. Third, heme import is reduced after the expression of FLVCR2-specific small interfering RNA (siRNA) or after the binding of the FY981 FeLV envelope protein to the FLVCR2 receptor. Finally, cells overexpressing FLVCR2 are more sensitive to heme toxicity, a finding most likely attributable to enhanced heme uptake. Tissue expression analysis indicates that FLVCR2 is expressed in a broad range of human tissues, including liver, placenta, brain, and kidney. The identification of a cellular function for FLVCR2 will have important implications in elucidating the pathogenic mechanisms of Fowler syndrome and of phenotypically associated disorders.", "journal": "Molecular and cellular biology", "doi": "10.1128/MCB.00690-10", "deposited_data": "Sim", "nuccore_ids": "1937909537, 1675021395, 1519316194, 2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1937909537, 1675021395, 1519316194, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20817587", "author": "Powell CC", "n_authors": 4, "title": "Bartonella species, feline herpesvirus-1, and Toxoplasma gondii PCR assay results from blood and aqueous humor samples from 104 cats with naturally occurring endogenous uveitis.", "abstract": "Toxoplasma gondii, Bartonella henselae and feline herpesvirus-1 (FHV-1) have been implicated as causative agents in feline uveitis. The usefulness of serum and aqueous humor (AH) antibody testing for these agents is limited as antibodies can be detected in both healthy cats and cats with uveitis. Very few studies using polymerase chain reaction (PCR) assays to amplify organism DNA from samples from cats with uveitis have been performed. In this study, assays to detect T gondii antibodies, feline leukemia virus antigen, feline immunodeficiency virus antibody, and Bartonella species antibodies were performed on serum and PCR assays for amplification of T gondii, Bartonella species, and FHV-1 DNA were performed on blood and AH samples from 104 cats with endogenous uveitis and 19 healthy cats. Results suggest the addition of the PCR assay to the diagnostic work-up for cats with uveitis will increase the detection of T gondii and FHV-1; however, the diagnostic usefulness of these additional data is not clear.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2010.07.003", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20676160", "author": "Farnworth MJ", "n_authors": 3, "title": "Public awareness in New Zealand of animal welfare legislation relating to cats.", "abstract": "To ascertain the levels of awareness of legislation governing the welfare of cats, and provision of basic care, including vaccination, by cat owners within two locations in New Zealand. To assess the ability of respondents to differentiate between the terms 'stray' and 'feral'. A face-to-face questionnaire, consisting of 12 questions in three sections, was distributed by volunteers within Auckland (n=255) and Kaitaia (n=99) to gather information pertinent to the study's aims. Section 1 covered respondents' personal details; Section 2, ownership and care of cats, including whether or not the cats were vaccinated against feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV); and Section 3, awareness of legislation and differences between the terms 'stray' and 'feral'. Overall, fewer than half of respondents were aware of the animal welfare legislation within New Zealand or the semantic differences between the terms 'stray' and 'feral' as they appear in the dictionary. Respondents >or=41 years old, and individuals employed in the animal-related sector, were significantly more likely to be aware of the legislation and make the correct distinction between the terms compared with those aged <or=40, and those working in a non-animal-related profession. A significantly greater percentage of cat owners (42%) provided care for cats they did not own compared with non-owners (26%). Results also indicated a large majority of cat owners may consider standard annual vaccinations to include vaccination against FIV and FeLV. Dissemination of information about animal welfare legislation is important for the care of cats within New Zealand, and the definitions of the terms 'stray' and 'feral' need to be more clearly stated in order to prevent confusion. This is especially important when cats may be controlled using lethal measures under different legislative precedents that are not necessarily consistent with one another. Veterinary clinics may act as a primary source for the dissemination of information about relevant welfare acts as well as preventative health care, thus improving the welfare of cats. Cat owners need to be better educated about the diseases covered by annual vaccination.", "journal": "New Zealand veterinary journal", "doi": "10.1080/00480169.2010.68624", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20615520", "author": "Polani S", "n_authors": 5, "title": "Evolutionary dynamics of endogenous feline leukemia virus proliferation among species of the domestic cat lineage.", "abstract": "Endogenous feline leukemia viruses (enFeLVs) occur in the germ lines of the domestic cat and related wild species (genus Felis). We sequenced the long terminal repeats and part of the env region of enFeLVs in domestic cats and five wild species. A total of 305 enFeLV sequences were generated across 17 individuals, demonstrating considerable diversity within two major clades. Distinct proliferations of enFeLVs occurred before and after the black-footed cat diverged from the other species. Diversity of enFeLVs was limited for the sand cat and jungle cat suggesting that proliferation of enFeLVs occurred within these species after they diverged. Relationships among enFeLVs were congruent with host species relationships except for the jungle cat, which carried only enFeLVs from a lineage that recently invaded the germline (enFeLV-AGTT). Comparison of wildcat and domestic cat enFeLVs indicated that a distinctive germ line invasion of enFeLVs has not occurred since the cat was domesticated.", "journal": "Virology", "doi": "10.1016/j.virol.2010.06.010", "deposited_data": "Sim", "nuccore_ids": "304360592, 304360591, 304360590, 304360589, 304360588, 304360587, 304360586, 304360585, 304360584, 304360583, 304360582, 304360581, 304360580, 304360579, 304360578, 304360577, 304360576, 304360575, 304360574, 304360573, 304360572, 304360571, 304360570, 304360569, 304360568, 304360567, 304360566, 304360565, 304360564, 304360563, 304360562, 304360561, 304360560, 304360559, 304360558, 304360557, 304360556, 304360555, 304360554, 304360553, 304360552, 304360551, 304360550, 304360549, 304360548, 304360547, 304360546, 304360545, 304360544, 304360543, 304360542, 304360541, 304360540, 304360539, 304360538, 304360537, 304360536, 304360535, 304360534, 304360533, 304360532, 304360531, 304360530, 304360529, 304360528, 304360527, 304360526, 304360525, 304360524, 304360523, 304360522, 304360521, 304360520, 304360519, 304360518, 304360517, 304360516, 304360515, 304360514, 304360513, 304360512, 304360511, 304360510, 304360509, 304360508, 304360507, 304360506, 304360505, 304360504, 304360503, 304360502, 304360501, 304360500, 304360499, 304360498, 304360497, 304360496, 304360495, 304360494, 304360493, 304360492, 304360491, 304360490, 304360489, 304360488, 304360487, 304360486, 304360485, 304360484, 304360483, 304360482, 304360481, 304360480, 304360479, 304360478, 304360477, 304360476, 304360475, 304360474, 304360473, 304360472, 304360471, 304360470, 304360469, 304360468, 304360467, 304360466, 304360465, 304360464, 304360463, 304360462, 304360461, 304360460, 304360459, 304360458, 304360457, 304360456, 304360455, 304360454, 304360453, 304360452, 304360451, 304360450, 304360449, 304360448, 304360447, 304360446, 304360445, 304360444, 304360443, 304360442, 304360441, 304360440, 304360439, 304360438, 304360437, 304360436, 304360435, 304360434, 304360433, 304360432, 304360431, 304360430, 304360429, 304360428, 304360427, 304360426, 304360425, 304360424, 304360423, 304360422, 304360421, 304360420, 304360419, 304360418, 304360417, 304360416, 304360415, 304360414, 304360413, 304360412, 304360411, 304360410, 304360409, 304360408, 304360407, 304360406, 304360405, 304360404, 304360403, 304360402, 304360401, 304360400, 304360399, 304360398, 304360397, 304360396, 304360395, 304360394, 304360393, 304360392, 304360391, 304360390, 304360389, 304360388, 304360387, 304360386, 304360385, 304360384, 304360383, 304360382, 304360381, 304360380, 304360379, 304360378, 304360377, 304360376, 304360375, 304360374, 304360373, 304360372, 304360371, 304360370, 304360369, 304360368, 304360367, 304360366, 304360365, 304360364, 304360363, 304360362, 304360361, 304360360, 304360359, 304360358, 304360357, 304360356, 304360355, 304360354, 304360353, 304360352, 304360351, 304360350, 304360349, 304360348, 304360347, 304360346, 304360345, 304360344, 304360343, 304360342, 304360341, 304360340, 304360339, 304360338, 304360337, 304360336, 304360335, 304360334, 304360333, 304360332, 304360331, 304360330", "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20610770", "author": "Harrison TM", "n_authors": 10, "title": "Malignant lymphoma in african lions (panthera leo).", "abstract": "Malignant lymphoma has become an increasingly recognized problem in African lions (Panthera leo). Eleven African lions (9 male and 2 female) with clinical signs and gross and microscopic lesions of malignant lymphoma were evaluated in this study. All animals were older adults, ranging in age from 14 to 19 years. Immunohistochemically, 10 of the 11 lions had T-cell lymphomas (CD3(+), CD79a(-)), and 1 lion was diagnosed with a B-cell lymphoma (CD3(-), CD79a(+)). The spleen appeared to be the primary site of neoplastic growth in all T-cell lymphomas, with involvement of the liver (6/11) and regional lymph nodes (5/11) also commonly observed. The B-cell lymphoma affected the peripheral lymph nodes, liver, and spleen. According to the current veterinary and human World Health Organization classification of hematopoietic neoplasms, T-cell lymphoma subtypes included peripheral T-cell lymphoma (4/11), precursor (acute) T-cell lymphoblastic lymphoma/leukemia (2/11), chronic T-cell lymphocytic lymphoma/leukemia (3/11), and T-zone lymphoma (1/11). The single B-cell lymphoma subtype was consistent with diffuse large B-cell lymphoma. Feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) testing by immunohistochemistry on sections of malignant lymphoma was negative for all 11 lions. One lion was seropositive for FeLV. In contrast to domestic and exotic cats, in which B-cell lymphomas are more common than T-cell lymphomas, African lions in this study had malignant lymphomas that were primarily of T-cell origin. Neither FeLV nor FIV, important causes of malignant lymphoma in domestic cats, seems to be significant in the pathogenesis of malignant lymphoma in African lions.", "journal": "Veterinary pathology", "doi": "10.1177/0300985810375054", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20610682", "author": "Buchmann AU", "n_authors": 4, "title": "Does a feline leukemia virus infection pave the way for Bartonella henselae infection in cats?", "abstract": "Domestic cats serve as the reservoir hosts of Bartonella henselae and may develop mild clinical symptoms or none after experimental infection. In humans, B. henselae infection can result in self-limiting cat scratch disease. However, immunocompromised patients may suffer from more-severe courses of infection or may even develop the potentially lethal disease bacillary angiomatosis. It was reasoned that cats with immunocompromising viral infections may react similarly to B. henselae infection. The aim of our study was to investigate the influence of the most important viruses known to cause immunosuppression in cats-Feline leukemia virus (FeLV), Feline immunodeficiency virus (FIV), and Feline panleukopenia virus (FPV)-on natural B. henselae infection in cats. Accordingly, 142 cats from animal shelters were necropsied and tested for B. henselae and concurrent infections with FeLV, FIV, or FPV by PCR and immunohistochemistry. A significant association was found between B. henselae and FeLV infections (P = 0.00028), but not between B. henselae and FIV (P = 1.0) or FPV (P = 0.756) infection, age (P = 0.392), or gender (P = 0.126). The results suggest that susceptibility to B. henselae infection is higher in cats with concurrent FeLV infections, regardless of whether the infection is latent or progressive. Histopathology and immunohistochemistry for B. henselae failed to identify lesions that could be attributed specifically to B. henselae infection. We conclude that the course of natural B. henselae infection in cats does not seem to be influenced by immunosuppressive viral infections in general but that latent FeLV infection may predispose cats to B. henselae infection or persistence.", "journal": "Journal of clinical microbiology", "doi": "10.1128/JCM.00750-10", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20610401", "author": "Yang Z", "n_authors": 8, "title": "Kinetics and specificity of feline leukemia virus subgroup C receptor (FLVCR) export function and its dependence on hemopexin.", "abstract": "The feline leukemia virus subgroup C receptor (FLVCR) is a heme export protein that is required for proerythroblast survival and facilitates macrophage heme iron recycling. However, its mechanism of heme export and substrate specificity are uncharacterized. Using [(55)Fe]heme and the fluorescent heme analog zinc mesoporphyrin, we investigated whether export by FLVCR depends on the availability and avidity of extracellular heme-binding proteins. Export was 100-fold more efficient when the medium contained hemopexin (K(d) < 1 pm) compared with albumin (K(d) = 5 nm) at the same concentration and was not detectable when the medium lacked heme-binding proteins. Besides heme, FLVCR could export other cyclic planar porphyrins, such as protoporphyrin IX and coproporphyrin. However, FLVCR has a narrow substrate range because unconjugated bilirubin, the primary breakdown product of heme, was not transported. As neither protoporphyrin IX nor coproporphyrin export improved with extracellular hemopexin (versus albumin), our observations further suggest that hemopexin, an abundant protein with a serum concentration (6.7-25 mum) equivalent to that of the iron transport protein transferrin (22-31 mum), by accepting heme from FLVCR and targeting it to the liver, might regulate macrophage heme export and heme iron recycling in vivo. Final studies show that hemopexin directly interacts with FLVCR, which also helps explain why FLVCR, in contrast to some major facilitator superfamily members, does not function as a bidirectional gradient-dependent transporter. Together, these data argue that hemopexin has a role in assuring systemic iron balance during homeostasis in addition to its established role as a scavenger during internal bleeding or hemolysis.", "journal": "The Journal of biological chemistry", "doi": "10.1074/jbc.M110.119131", "deposited_data": "Sim", "nuccore_ids": "2666210344, 3382334014, 3382246094, 2666210344, 2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556, 1519313995", "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20580298", "author": "Maher IE", "n_authors": 7, "title": "Polymerase chain reaction survey of feline haemoplasma infections in Greece.", "abstract": "The aim of this study was to use real-time polymerase chain reaction assays to determine the prevalence of three haemoplasma species in cats from Greece and to evaluate possible associations between haemoplasma infection and age, gender, feline immunodeficiency virus/feline leukaemia virus (FIV/FeLV) status and packed cell volume (PCV). Ninety-seven cats (24 ill anaemic, 55 ill non-anaemic, 18 healthy non-anaemic) were included in the study. Twenty cats (20.6%) were haemoplasma positive; seven cats were infected only with Mycoplasma haemofelis, 10 were infected only with 'Candidatus Mycoplasma haemominutum' and three were co-infected with M haemofelis and 'Candidatus M haemominutum'. 'Candidatus Mycoplasma turicensis' was not detected. Haemoplasma infection was associated with older age (P=0.019). M haemofelis infection tended to be more common in anaemic cats (P=0.058). No association between gender and haemoplasma infection, or haemoplasma relative copy number and PCV, was detected. Retroviral infection rates were very low with only one FeLV proviral positive cat found.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2010.02.004", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20576142", "author": "Mullikin JC", "n_authors": 20, "title": "Light whole genome sequence for SNP discovery across domestic cat breeds.", "abstract": "The domestic cat has offered enormous genomic potential in the veterinary description of over 250 hereditary disease models as well as the occurrence of several deadly feline viruses (feline leukemia virus--FeLV, feline coronavirus--FECV, feline immunodeficiency virus--FIV) that are homologues to human scourges (cancer, SARS, and AIDS respectively). However, to realize this bio-medical potential, a high density single nucleotide polymorphism (SNP) map is required in order to accomplish disease and phenotype association discovery. To remedy this, we generated 3,178,297 paired fosmid-end Sanger sequence reads from seven cats, and combined these data with the publicly available 2X cat whole genome sequence. All sequence reads were assembled together to form a 3X whole genome assembly allowing the discovery of over three million SNPs. To reduce potential false positive SNPs due to the low coverage assembly, a low upper-limit was placed on sequence coverage and a high lower-limit on the quality of the discrepant bases at a potential variant site. In all domestic cats of different breeds: female Abyssinian, female American shorthair, male Cornish Rex, female European Burmese, female Persian, female Siamese, a male Ragdoll and a female African wildcat were sequenced lightly. We report a total of 964 k common SNPs suitable for a domestic cat SNP genotyping array and an additional 900 k SNPs detected between African wildcat and domestic cats breeds. An empirical sampling of 94 discovered SNPs were tested in the sequenced cats resulting in a SNP validation rate of 99%. These data provide a large collection of mapped feline SNPs across the cat genome that will allow for the development of SNP genotyping platforms for mapping feline diseases.", "journal": "BMC genomics", "doi": "10.1186/1471-2164-11-406", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20518025", "author": "Lalonde E", "n_authors": 9, "title": "Unexpected allelic heterogeneity and spectrum of mutations in Fowler syndrome revealed by next-generation exome sequencing.", "abstract": "Protein coding genes constitute approximately 1% of the human genome but harbor 85% of the mutations with large effects on disease-related traits. Therefore, efficient strategies for selectively sequencing complete coding regions (i.e., \"whole exome\") have the potential to contribute our understanding of human diseases. We used a method for whole-exome sequencing coupling Agilent whole-exome capture to the Illumina DNA-sequencing platform, and investigated two unrelated fetuses from nonconsanguineous families with Fowler Syndrome (FS), a stereotyped phenotype lethal disease. We report novel germline mutations in feline leukemia virus subgroup C cellular-receptor-family member 2, FLVCR2, which has recently been shown to cause FS. Using this technology, we identified three types of genetic abnormalities: point-mutations, insertions-deletions, and intronic splice-site changes (first pathogenic report using this technology), in the fetuses who both were compound heterozygotes for the disease. Although revealing a high level of allelic heterogeneity and mutational spectrum in FS, this study further illustrates the successful application of whole-exome sequencing to uncover genetic defects in rare Mendelian disorders. Of importance, we show that we can identify genes underlying rare, monogenic and recessive diseases using a limited number of patients (n=2), in the absence of shared genetic heritage and in the presence of allelic heterogeneity.", "journal": "Human mutation", "doi": "10.1002/humu.21293", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20514250", "author": "Ravi M", "n_authors": 4, "title": "Naturally acquired feline immunodeficiency virus (FIV) infection in cats from western Canada: Prevalence, disease associations, and survival analysis.", "abstract": "This retrospective study evaluated epidemiologic features and disease associations of feline immunodeficiency virus (FIV) infection in client owned cats from western Canada. Among 1205 cats that were tested 66 (5.5%) were positive for FIV antibody (FIV(+)) with a higher prevalence in males than females. FIV(+) cats were older than the overall population. Epidemiologic features and disease associations were compared between 58 FIV(+), but feline leukemia virus negative (FeLV(-)) cats and 58 age and sex matched FIV-negative (FIV(-)), FeLV(-) cats. FIV positivity was associated with a history of bite wounds, increasing age, and male gender. Lethargy and oral diseases were significantly associated with FIV positivity. Although several FIV(+) cats were euthanized, the survival time of FIV(+) cats after diagnosis was not significantly different from that of FIV(-) cats. In summary, FIV prevalence was low in cats from western Canada, clinical signs/diseases were mild, and lifespan was not different in FIV(+) cats.", "journal": "The Canadian veterinary journal = La revue veterinaire canadienne", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20471525", "author": "Sykes JE", "n_authors": 1, "title": "Immunodeficiencies caused by infectious diseases.", "abstract": "Immunodeficiencies caused by infectious agents may result from disruption of normal host barriers or dysregulation of cellular immunity, the latter serving to promote survival of the infectious agent through immune evasion. Such infections may be followed by opportunistic infections with a variety of other microorganisms. Classic infectious causes of immunodeficiency in companion animals are the immunodeficiency retroviruses, including feline immunodeficiency virus and feline leukemia virus. Other important causes include canine distemper virus; canine parvovirus 2; feline infectious peritonitis virus; rickettsial organisms that infect leukocytes; Leishmania; and fungal pathogens, such as Cryptococcus. Considerable research effort has been invested in understanding the mechanisms of pathogen-induced immunosuppression, with the hope that effective therapies may be developed that reverse the immunodeficiencies developed and in turn assist the host to clear persistent or life-threatening infectious diseases.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": "10.1016/j.cvsm.2010.01.006", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20466573", "author": "Duarte A", "n_authors": 9, "title": "Survey of infectious and parasitic diseases in stray cats at the Lisbon Metropolitan Area, Portugal.", "abstract": "A survey of infectious and parasitic diseases of stray cats was carried out using biological samples collected from animals captured during a catch-neuter-release programme in four counties of the Lisbon Metropolitan Area. The main objective was to investigate the potential threat of stray cats for animal and public health. Samples of blood, stool, hair and auricular swabs were collected from 231 cats in 27 colonies. Anti-Toxoplasma gondii antibodies were detected in 47/194 samples (24.2%); anti-Leishmania infantum antibodies in 1/180 cats (0.6%); intestinal parasites in 23/74 samples (Toxocara cati, Isospora felis, Ancylostoma tubaeforme, Dipylidium caninum, Uncinaria stenocephala, Toxascaris leonina) and Otodectes cynotis in 4/182 cats (2.2%); dermatophyte fungi were isolated in 40/136 samples (29.4%); feline immunodeficiency virus antibodies were detected in 23/226 samples (10.2%); feline leukaemia virus antigen in 14/198 samples (7.1%); and feline coronavirus RNA in 9/127 samples (7.1%). Our results revealed that zoonotic agents, namely dermatophyte fungi and Toxocara cati were present in stray cat colonies in the investigated counties. Overall the low frequency of major pathogens suggests a balanced relationship between host and agents.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2009.11.003", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20454576", "author": "Chiabrando D", "n_authors": 2, "title": "Diamond Blackfan Anemia at the Crossroad between Ribosome Biogenesis and Heme Metabolism.", "abstract": "Diamond-Blackfan anemia (DBA) is a rare, pure red-cell aplasia that presents during infancy. Approximately 40% of cases are associated with other congenital defects, particularly malformations of the upper limb or craniofacial region. Mutations in the gene coding for the ribosomal protein RPS19 have been identified in 25% of patients with DBA, with resulting impairment of 18S rRNA processing and 40S ribosomal subunit formation. Moreover, mutations in other ribosomal protein coding genes account for about 25% of other DBA cases. Recently, the analysis of mice from which the gene coding for the heme exporter Feline Leukemia Virus subgroup C Receptor (FLVCR1) is deleted suggested that this gene may be involved in the pathogenesis of DBA. FLVCR1-null mice show a phenotype resembling that of DBA patients, including erythroid failure and malformations. Interestingly, some DBA patients have disease linkage to chromosome 1q31, where FLVCR1 is mapped. Moreover, it has been reported that cells from DBA patients express alternatively spliced isoforms of FLVCR1 which encode non-functional proteins. Herein, we review the known roles of RPS19 and FLVCR1 in ribosome function and heme metabolism respectively, and discuss how the deficiency of a ribosomal protein or of a heme exporter may result in the same phenotype.", "journal": "Advances in hematology", "doi": "10.1155/2010/790632", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20451235", "author": "Ahmad S", "n_authors": 2, "title": "The frequency of occurrence and nature of recombinant feline leukemia viruses in the induction of multicentric lymphoma by infection of the domestic cat with FeLV-945.", "abstract": "During feline leukemia virus (FeLV) infection in the domestic cat, viruses with a novel envelope gene arise by recombination between endogenous FeLV-related elements and the exogenous infecting species. These recombinant viruses (FeLV-B) are of uncertain disease association, but have been linked to the induction of thymic lymphoma. To assess the role of FeLV-B in the induction of multicentric lymphoma and other non-T-cell disease, the frequency of occurrence and nature of FeLV-B were examined in diseased tissues from a large collection of FeLV-infected animals. Diseased tissues were examined by Southern blot and PCR amplification to detect the presence of FeLV-B. Further analysis was performed to establish the recombination junctions and infectivity of FeLV-B in diseased tissues. The results confirmed the frequent association of FeLV-B with thymic lymphoma but showed infrequent generation, low levels and lack of infectivity of FeLV-B in non-T-cell diseases including multicentric lymphoma.", "journal": "Virology", "doi": "10.1016/j.virol.2010.04.011", "deposited_data": "Sim", "nuccore_ids": "289976733, 289976730, 289976727, 289976724, 289976722, 289976719, 289976716, 289976712, 289976708, 289976706, 289976703", "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20412434", "author": "Raith K", "n_authors": 4, "title": "Encephalomyelitis resembling human and ruminant rhombencephalitis caused by Listeria monocytogenes in a feline leukemia virus-infected cat.", "abstract": null, "journal": "Journal of veterinary internal medicine", "doi": "10.1111/j.1939-1676.2010.0518.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20398945", "author": "Suntz M", "n_authors": 5, "title": "High prevalence of non-productive FeLV infection in necropsied cats and significant association with pathological findings.", "abstract": "Applying a combination of semi-nested PCR and immunohistology (IHC), the presence of exogenous feline leukemia virus infection was studied in 302 necropsied cats with various disorders. 9% showed the classical outcome of persistent productive FeLV infection which was represented by FeLV antigen expression in different organs. 152 cats (50%) harboured exogenous FeLV-specific proviral sequences in the bone marrow but did not express viral antigen. These cats were considered as horizontally but non-productively infected. Statistical evaluation showed a significant association of non-productive horizontal FeLV infection with a variety of parameters. Non-productively infected cats were statistically significantly older and more often originated from animal shelters than cats without exogenous FeLV infection. Furthermore, some pathological disorders like anemia, panleukopenia, and purulent inflammation showed significant association with non-productive FeLV infection. No significant association was found with lymphosarcoma, known for a long time to be induced by productive FeLV infection.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2010.02.014", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20372106", "author": "Kim YS", "n_authors": 7, "title": "Transduction of human primitive repopulating hematopoietic cells with lentiviral vectors pseudotyped with various envelope proteins.", "abstract": "Lentiviral vectors are useful for transducing primitive hematopoietic cells. We examined four envelope proteins for their ability to mediate lentiviral transduction of mobilized human CD34(+) peripheral blood cells. Lentiviral particles encoding green fluorescent protein (GFP) were pseudotyped with the vesicular stomatitis virus envelope glycoprotein (VSV-G), the amphotropic (AMPHO) murine leukemia virus envelope protein, the endogenous feline leukemia viral envelope protein or the feline leukemia virus type C envelope protein. Because the relative amount of genome RNA per ml was similar for each pseudotype, we transduced CD34(+) cells with a fixed volume of each vector preparation. Following an overnight transduction, CD34(+) cells were transplanted into immunodeficient mice which were sacrificed 12 weeks later. The average percentages of engrafted human CD45(+) cells in total bone marrow were comparable to that of the control, mock-transduced group (37-45%). Lenti-particles pseudotyped with the VSV-G envelope protein transduced engrafting cells two- to tenfold better than particles pseudotyped with any of the gamma-retroviral envelope proteins. There was no correlation between receptor mRNA levels for the gamma-retroviral vectors and transduction efficiency of primitive hematopoietic cells. These results support the use of the VSV-G envelope protein for the development of lentiviral producer cell lines for manufacture of clinical-grade vector.", "journal": "Molecular therapy : the journal of the American Society of Gene Therapy", "doi": "10.1038/mt.2010.48", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20362315", "author": "Akhtardanesh B", "n_authors": 4, "title": "Feline immunodeficiency virus, feline leukemia virus and Toxoplasma gondii in stray and household cats in Kerman-Iran: seroprevalence and correlation with clinical and laboratory findings.", "abstract": "This study was carried out to determine the seroprevalence of feline leukemia virus (FeLV), feline immunodeficiency virus (FIV) and Toxoplasma gondii (T. gondii) infection among stray and owned cats in southeastern Iran and to identify the influence of age, sex, lifestyle, health status, and laboratory findings on seropositivity. The overall infection rate for FIV, FeLV, and T. gondii was 19.2%, 14.2%, and 32.1% respectively. Results of the multivariate logistic regression analysis showed that old adults more likely to be seropositive than juveniles for FIV, FeLV, and T. gondii (adjusted odds ratios [ORs], 1.84, 1.56, and 2.57 respectively). Anemic and diseased cats ([ORs], 6.62 and 0.9) were at a greater risk of testing positive for FeLV. Male cats were 4.91 times as likely to have FIV as were female and hyperglobulinemia was significantly more prevalent in FIV-infected cats ([ORs], 3.4). In conclusion, FIV and FeLV seem to be endemic in Iran and retroviral-associated immunosuppression may be a risk factor for active toxoplasmosis in infected cats.", "journal": "Research in veterinary science", "doi": "10.1016/j.rvsc.2010.03.015", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20237508", "author": "Métais JY", "n_authors": 8, "title": "Feline leukemia virus integrase and capsid packaging functions do not change the insertion profile of standard Moloney retroviral vectors.", "abstract": "Adverse events linked to perturbations of cellular genes by vector insertion reported in gene therapy trials and animal models have prompted attempts to better understand the mechanisms directing viral vector integration. The integration profiles of vectors based on MLV, ASLV, SIV and HIV have all been shown to be non-random, and novel vectors with a safer integration pattern have been sought. Recently, we developed a producer cell line called CatPac that packages standard MoMLV vectors with feline leukemia virus (FeLV) gag, pol and env gene products. We now report the integration profile of this vector, asking if the FeLV integrase and capsid proteins could modify the MoMLV integration profile, potentially resulting in a less genotoxic pattern. We transduced rhesus macaque CD34+ hematopoietic progenitor cells with CatPac or standard MoMLV vectors, and determined their integration profile by LAM-PCR. We obtained 184 and 175 unique integration sites (ISs) respectively for CatPac and standard MoMLV vectors, and these were compared with 10 000 in silico-generated random IS. The integration profile for CatPac vector was similar to MoMLV and equally non-random, with a propensity for integration near transcription start sites and in highly dense gene regions. We found an IS for CatPac vector localized 715 nucleotides upstream of LMO-2, the gene involved in the acute lymphoblastic leukemia developed by X-SCID patients treated by gene therapy using MoMLV vectors. In conclusion, we found that replacement of MoMLV env, gag and pol gene products with FeLV did not alter the basic integration profile. Thus, there appears to be no safety advantage for this packaging system. However, considering the stability and efficacy of CatPac vectors, further development is warranted, using potentially safer vector backbones, for instance those with a SIN configuration.", "journal": "Gene therapy", "doi": "10.1038/gt.2010.24", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20230573", "author": "Salakij C", "n_authors": 3, "title": "Molecular characterization of Hepatozoon species in a Leopard Cat (Prionailurus bengalensis) from Thailand.", "abstract": "Hepatozoon gamonts were observed by light microscopy in neutrophils of a male, wild-caught Leopard Cat. Complete blood counts at presentation and 6 months later were unremarkable. Serologic tests were negative for both FIV and FeLV. A partial sequence of the 18S rRNA gene from the Hepatozoon found in the cat indicated that, compared with all species examined, the protozoan had the closest relationship (99.2% sequence similarity) with the Hepatozoon of the water python (Stegonotus cucullatus). The cat was clinically healthy at last report. Although Hepatozoon has been found in another wild cat in Thailand, this is the first report in a Leopard Cat. The pathogenicity of Hepatozoon in these cats remains uncertain.", "journal": "Veterinary clinical pathology", "doi": "10.1111/j.1939-165X.2010.00216.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20224091", "author": "Roura X", "n_authors": 10, "title": "Prevalence of hemotropic mycoplasmas in healthy and unhealthy cats and dogs in Spain.", "abstract": "The aims of the present study were to determine the prevalence of hemoplasmas in cats and dogs from the Barcelona area of Spain with the use of species-specific quantitative polymerase chain reaction (qPCR) assays and to evaluate any associations between hemoplasma infection, clinical presentation, and vector-borne infections. Blood samples from cats (191) and dogs (182) were included and were classified as healthy (149) or unhealthy (224). Ethylenediamine tetra-acetic acid blood samples underwent DNA extraction and qPCR analysis. Mycoplasma haemofelis, 'Candidatus Mycoplasma haemominutum', and 'Candidatus Mycoplasma turicensis' were detected in cats, whereas Mycoplasma haemocanis and 'Candidatus Mycoplasma haematoparvum' were detected in dogs, with prevalences of 3.7%, 9.9%, 0.5%, 14.3%, and 0.6%, respectively. In cats, no association between hemoplasma infection and health status, age, breed, presence of anemia, Feline leukemia virus status, and other vector-borne infections was found, but outdoor access (P = 0.009), male sex (P = 0.01), and Feline immunodeficiency virus status (P < 0.001) were significantly associated with hemoplasma infection. In dogs, sex, age, health status, presence of anemia, and breed were not significantly associated with hemoplasma infection, but a significant association was found between hemoplasma infection and vector-borne infections (P < 0.001). The present report documents the occurrence of feline 'Candidatus M. turicensis' and canine 'Candidatus M. haematoparvum' infections in Spain.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/104063871002200219", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20222826", "author": "Doty RT", "n_authors": 5, "title": "An all-feline retroviral packaging system for transduction of human cells.", "abstract": "Abstract The subgroup C feline leukemia virus (FeLV-C) receptor FLVCR is a widely expressed 12-transmembrane domain transporter that exports cytoplasmic heme and is a promising target for retrovirus-mediated gene delivery. Previous studies demonstrated that FeLV-C pseudotype vectors were more efficient at targeting human hematopoietic stem cells than those pseudotyped with gibbon ape leukemia virus (GALV), and thus we developed an all FeLV-C-based packaging system, termed CatPac. CatPac is helper-virus free and can produce higher titer vectors than existing gammaretroviral packaging systems, including systems mixing Moloney murine leukemia virus (MoMLV) Gag-Pol and FeLV-C Env proteins. The vectors can be readily concentrated (>30-fold), refrozen (three to five times), and held on ice (>2 days) with little loss of titer. Furthermore, we demonstrate that CatPac pseudotype vectors efficiently target early CD34(+)CD38(-) stem/progenitor cells, monocytic and erythroid progenitors, activated T cells, mature macrophages, and cancer cell lines, suggesting utility for human cell and cell line transduction and possibly gene therapy.", "journal": "Human gene therapy", "doi": "10.1089/hum.2010.032", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20167134", "author": "Helfer-Hungerbuehler AK", "n_authors": 13, "title": "Dominance of highly divergent feline leukemia virus A progeny variants in a cat with recurrent viremia and fatal lymphoma.", "abstract": "In a cat that had ostensibly recovered from feline leukemia virus (FeLV) infection, we observed the reappearance of the virus and the development of fatal lymphoma 8.5 years after the initial experimental exposure to FeLV-A/Glasgow-1. The goals of the present study were to investigate this FeLV reoccurrence and molecularly characterize the progeny viruses. The FeLV reoccurrence was detected by the presence of FeLV antigen and RNA in the blood and saliva. The cat was feline immunodeficiency virus positive and showed CD4+ T-cell depletion, severe leukopenia, anemia and a multicentric monoclonal B-cell lymphoma. FeLV-A, but not -B or -C, was detectable. Sequencing of the envelope gene revealed three FeLV variants that were highly divergent from the virus that was originally inoculated (89-91% identity to FeLV-A/Glasgow-1). In the long terminal repeat 31 point mutations, some previously described in cats with lymphomas, were detected. The FeLV variant tissue provirus and viral RNA loads were significantly higher than the FeLV-A/Glasgow-1 loads. Moreover, the variant loads were significantly higher in lymphoma positive compared to lymphoma negative tissues. An increase in the variant provirus blood load was observed at the time of FeLV reoccurrence. Our results demonstrate that ostensibly recovered FeLV provirus-positive cats may act as a source of infection following FeLV reactivation. The virus variants that had largely replaced the inoculation strain had unusually heavily mutated envelopes. The mutations may have led to increased viral fitness and/or changed the mutagenic characteristics of the virus.", "journal": "Retrovirology", "doi": "10.1186/1742-4690-7-14", "deposited_data": "Sim", "nuccore_ids": "256808074, 256808073, 256808072, 256808071, 256808070, 256808069", "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20156698", "author": "Reche A Jr", "n_authors": 9, "title": "Cutaneous mycoflora and CD4:CD8 ratio of cats infected with feline immunodeficiency virus.", "abstract": "This study was designed to compare cutaneous mycoflora isolation and CD4+:CD8+ ratio in feline immunodeficiency virus (FIV)-infected cats with that in FIV-uninfected cats. Sixty cats were examined. Twenty-five were FIV-infected cats and 35 were FIV-uninfected cats. All 60 cats were FeLV-negative. Fungi were speciated and immunophenotyping of peripheral CD4+ and CD8+ T lymphocytes was performed. At least one fungal colony was isolated from 22/25 (88%) FIV-infected cats. Among the FIV-uninfected cats fungal colonies were recovered from 13/35 (37%) specimens. Dermatophytes were recovered from 2/25 (8%) FIV-infected cats (one Microsporum gypseum, one Microsporum canis) and 3/35 (8.5%) FIV-uninfected cats (M gypseum). Malassezia species was the most commonly isolated organism from both groups of cats (51.6%). Malassezia species was more commonly isolated from FIV-infected cats than FIV-uninfected cats (84% vs 28.6%). The CD4+ to CD8+ lymphocyte ratio for FIV-infected cats was significantly lower than the CD4+ to CD8+ ratio in the FIV-uninfected cats. The CD4+ to CD8+ lymphocyte ratio for FIV-infected cats with cutaneous overall fungal isolation was significantly lower than the CD4:CD8 lymphocyte ratio in the FIV-infected cats but without cutaneous fungal isolation. We can conclude that immunologic depletion due to retroviral infection might represent a risk factor to cutaneous fungal colonization in cats.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2009.12.017", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20138558", "author": "Kelly PJ", "n_authors": 9, "title": "Feline immunodeficiency virus, feline leukemia virus and Bartonella species in stray cats on St Kitts, West Indies.", "abstract": "Stray cats trapped in various areas of Basseterre, the capital of St Kitts in the West Indies, were tested for infection with feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) using commercial kits. Of 99 (51 male and 48 female) cats trapped in 2006/7, 15% (12 males and three females) were positive for FIV while none were positive for FeLV. Of 72 (41 males and 31 females) cats trapped in 2009, 14% (nine males and one female) were positive for FIV while none were positive for FeLV. Polymerase chain reaction analysis revealed DNA of Bartonella species in whole blood collected from 60/95 (63%) cats trapped in 2006/7. Sequencing of the 16S-23S rRNA gene intergenic transcribed spacer (ITS) region of a convenience sample of nine amplicons and the 11 isolates made from 43 blood samples which were cultured using Bartonella alpha Proteobacteria (BAPGM) enrichment medium revealed B henselae (14) and B clarridgeiae (six).", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2009.12.015", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20135909", "author": "Laberke S", "n_authors": 4, "title": "Prevalence of feline haemoplasma infection in cats in Southern Bavaria, Germany, and infection risk factor analysis.", "abstract": "In this prospective study performed from samples of 296 cats from Southern Bavaria, Germany, a conventional PCR (polymerase chain reaction) assay for detection of Mycoplasma haemofelis and \"Candidatus Mycoplasma haemominutum\" and a real-time PCR for \"Candidatus Mycoplasma turicensis\" were used to test blood samples from ill cats with anaemia (n = 79), ill cats with a normal haematocrit (n = 98), and healthy cats (n = 119). The aim of the study was to investigate the prevalence of feline haemoplasma infection and associated risk factors in cats in Southern Bavaria, Germany. Thirty-six cats (12.2%) were PCR positive: 9.5% were infected with \"Candidatus M. haemominutum, 1.4% with M. haemofelis, and 0.3% with \"Candidatus M. turicensis\". Three cats (1.0%) were coinfected with two haemoplasma species (one cat with \"Candidatus M. haemominutum\"and M. haemofelis, and two cats with \"Candidatus M. haemominutum\"and \"Candidatus M. turicensis\"). Risk factors for infection were outdoor access, male gender, coinfection with feline leukaemia virus (FeLV), and domestic shorthair breed. There was no significant difference in the prevalence of haemoplasma infection between the three groups and none of the positive cats had clinical signs of haemoplasma infection. The authors conclude that feline haemoplasma infection does not appear to be a common cause of anaemia in cats in Southern Bavaria, Germany.", "journal": "Berliner und Munchener tierarztliche Wochenschrift", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20124765", "author": "Nakamura M", "n_authors": 6, "title": "Differential diagnosis of feline leukemia virus subgroups using pseudotype viruses expressing green fluorescent protein.", "abstract": "Feline leukemia virus (FeLV) is classified into three receptor interference subgroups, A, B and C. In this study, to differentiate FeLV subgroups, we developed a simple assay system using pseudotype viruses expressing green fluorescent protein (GFP). We prepared gfp pseudotype viruses, named gfp(FeLV-A), gfp(FeLV-B) and gfp(FeLV-C) harboring envelopes of FeLV-A, B and C, respectively. The gfp pseudotype viruses completely interfered with the same subgroups of FeLV reference strains on FEA cells (a feline embryonic fibroblast cell line). We also confirmed that the pseudotype viruses could differentiate FeLV subgroups in field isolates. The assay will be useful for differential diagnosis of FeLV subgroups in veterinary diagnostic laboratories in the future.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.09-0214", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20070499", "author": "Tasker S", "n_authors": 4, "title": "Coombs', haemoplasma and retrovirus testing in feline anaemia.", "abstract": "To investigate the associations between Coombs' testing, haemoplasma and retroviral infections, and feline anaemia. Haematology, Coombs' testing (including assessment of persistent autoagglutination) and selected infection testing (haemoplasma, feline leukaemia virus/feline immunodeficiency virus provirus) were performed in blood samples collected from 60 anaemic and 60 non-anaemic cats. No association between infection and anaemia or Coombs' positivity existed. Anaemic cats (21.7%) were significantly more likely than non-anaemic cats (0%) to have cold autoagglutination (P<0.0001), but significance (set at <or=0.0025 due to multiple testing) was not quite reached when Coombs' positivity was compared between anaemic (40.4% and 21.7% positive at 4 degrees C and 37 degrees C, respectively) and non-anaemic (20% and 3.3% positive, P=0.021 and P=0.004, at 4 degrees C and 37 degrees C, respectively) cats. Cats with immune-mediated haemolytic anaemia were significantly more likely to have persistent cold autoagglutination (P<0.0001) and be Coombs' positive at 37 degrees C with polyvalent (P<0.0001), immunoglobulin (Ig)G (P<0.0001) or any antiserum (P<0.0001). Haemoplasmas and retroviruses were uncommonly detected. Cats suspected of having immune-mediated haemolytic anaemia should be evaluated for persistent autoagglutination at 4 degrees C as well as performing Coombs' testing at 37 degrees C, but positive results may occur in with other forms of anaemia. Testing for erythrocyte-bound antibodies should always be interpreted in parallel with documentation of haemolysis in anaemic cats.", "journal": "The Journal of small animal practice", "doi": "10.1111/j.1748-5827.2009.00869.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20009422", "author": "Oohashi E", "n_authors": 4, "title": "Chronic progressive polyarthritis in a female cat.", "abstract": "Feline chronic progressive polyarthritis is a rare immune-mediated disease that has only previously been reported in male cats. A one-year-old female cat was presented with anorexia, lassitude and lameness. The tarsal, carpal and elbow joints revealed swelling, pain, stiffness, crepitus and regional lymphadenopathy, and fever was present. The cat was clinically diagnosed with chronic progressive polyarthritis based on the fever, swelling of joints, imaging of erosive proliferative periosteal polyarthritis, positivity for antinuclear antibody, synovial fluid analyses and urinalyses. Both feline leukemia virus antigen and feline immunodeficiency virus antibody were positive. Using hair root DNA, polymerase chain reaction amplification targeting the sex-determining region on the Y chromosome gene amplified the fragment of DNA from a normal male cat, but not amplified from a normal female cat or the present cat. Accordingly, the present cat was classified as genetically female. Cyclosporine treatment was started, and the general condition and movement quickly improved and continued for 8 months post-diagnosis. This is the first report of chronic progressive polyarthritis in a female cat.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.09-0261", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20004483", "author": "Torres AN", "n_authors": 5, "title": "Feline leukemia virus immunity induced by whole inactivated virus vaccination.", "abstract": "A fraction of cats exposed to feline leukemia virus (FeLV) effectively contain virus and resist persistent antigenemia/viremia. Using real-time PCR (qPCR) to quantitate circulating viral DNA levels, previously we detected persistent FeLV DNA in blood cells of non-antigenemic cats considered to have resisted FeLV challenge. In addition, previously we used RNA qPCR to quantitate circulating viral RNA levels and determined that the vast majority of viral DNA is transcriptionally active, even in the absence of antigenemia. A single comparison of all USDA-licensed commercially available FeLV vaccines using these modern sensitive methods has not been reported. To determine whether FeLV vaccination would prevent nucleic acid persistence, we assayed circulating viral DNA, RNA, antigen, infectious virus, and virus neutralizing (VN) antibody in vaccinated and unvaccinated cats challenged with infectious FeLV. We identified challenged vaccinates with undetectable antigenemia and viremia concomitant with persistent FeLV DNA and/or RNA. Moreover, these studies demonstrated that two whole inactivated virus (WIV) adjuvanted FeLV vaccines (Fort Dodge Animal Health's Fel-O-Vax Lv-K) and Schering-Plough Animal Health's FEVAXYN FeLV) provided effective protection against FeLV challenge. In nearly every recipient of these vaccines, neither viral DNA, RNA, antigen, nor infectious virus could be detected in blood after FeLV challenge. Interestingly, this effective viral containment occurred despite a weak to undetectable VN antibody response. The above findings reinforce the precept of FeLV infection as a unique model of effective retroviral immunity elicited by WIV vaccination, and as such holds valuable insights into retroviral immunoprevention and therapy.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2009.10.017", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "19955325", "author": "Thalwitzer S", "n_authors": 10, "title": "Seroprevalences to viral pathogens in free-ranging and captive cheetahs (Acinonyx jubatus) on Namibian Farmland.", "abstract": "Cheetah populations are diminishing rapidly in their natural habitat. One reason for their decline is thought to be a high susceptibility to (infectious) diseases because cheetahs in zoos suffer from high disease-induced mortality. Data on the health status of free-ranging cheetahs are scarce, and little is known about their exposure and susceptibility to infectious diseases. We determined seroprevalences to nine key viruses (feline herpesvirus 1, feline calicivirus, feline parvovirus, feline coronavirus, canine distemper virus, feline immunodeficiency virus [FIV], puma lentivirus, feline leukemia virus, and rabies virus) in 68 free-ranging cheetahs on east-central Namibian farmland, 24 nonvaccinated Namibian captive cheetahs, and several other wild carnivore species and conducted necropsies of cheetahs and other wild carnivores. Eight of 11 other wild carnivores were seropositive for at least one of the viruses, including the first record of an FIV-like infection in a wild felid west of the Kalahari, the caracal (Felis caracal). Seroprevalences of the free-ranging cheetahs were below 5% for all nine viruses, which is significantly lower than seroprevalences in nonvaccinated captive cheetahs and those for five of seven viruses in previously studied free-ranging cheetahs from north-central Namibia (L. Munson, L. Marker, E. Dubovi, J. A. Spencer, J. F. Evermann, and S. J. O'Brien, J. Wildl. Dis. 40:23-31, 2004). There was no clinical or pathological evidence of infectious diseases in living or dead cheetahs. The results suggest that while free-ranging wild carnivores may be a source of pathogens, the distribution of seroprevalences across studies mirrored local human population density and factors associated with human habitation, probably reflecting contact opportunities with (nonvaccinated) domestic and feral cats and dogs. They also suggest that Namibian cheetahs respond effectively to viral challenges, encouraging consistent and sustainable conservation efforts.", "journal": "Clinical and vaccine immunology : CVI", "doi": "10.1128/CVI.00345-09", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "19945894", "author": "Kyle KN", "n_authors": 2, "title": "Apparent feline leukemia virus-induced chronic lymphocytic leukemia and response to treatment.", "abstract": "Chylothorax secondary to chronic lymphocytic leukemia (CLL) was diagnosed in a feline leukemia virus (FeLV)-positive 8-year-old castrated male domestic shorthair feline. The leukemia resolved following therapy with chlorambucil, prednisone, cyclophosphamide, doxorubicin, and lomustine. To our knowledge, this is the first reported case of CLL in an FeLV-positive cat. Although a causative relationship cannot be proven, patients diagnosed with either disease may benefit from diagnostics to rule out the presence of the other concurrent condition.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2009.10.009", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "19930142", "author": "Sand C", "n_authors": 5, "title": "Evaluation of a new in-clinic test system to detect feline immunodeficiency virus and feline leukemia virus infection.", "abstract": "Many in-house tests for the diagnosis of feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) infection are licensed for use in veterinary practice. A new test with unknown performance has recently appeared on the market. The aims of this study were to define the efficacy of a new in-clinic test system, the Anigen Rapid FIV Ab/FeLV Ag Test, and to compare it with the current leading in-clinic test, the SNAP Kombi Plus FeLV Antigen/FIB Antibody Test. Three-hundred serum samples from randomly selected healthy and diseased cats presented to the Clinic of Small Animal Medicine at Ludwig Maximilian University were tested using both the Anigen Rapid Test and the SNAP Kombi Plus Test. Diagnostic sensitivity, specificity, and positive and negative predictive values were calculated for both tests using Western blot as the gold standard for verification of FIV infection and PCR as the gold standard for FeLV infection. The presence of antibodies against FIV was confirmed by Western blot in 9/300 samples (prevalence 3%). FeLV DNA was detected by PCR in 15/300 samples (prevalence 5%). For FIV infection the Anigen Rapid Test had a sensitivity of 88.9%, specificity of 99.7%, positive predictive value of 88.9%, and negative predictive value of 99.7%. For FeLV infection, the Anigen Rapid Test had a sensitivity of 40.0%, specificity of 100%, positive predictive value of 100%, and negative predictive value of 96.9%. Diagnostic accuracy was similar to that of the SNAP Kombi Plus Test. The new Anigen Rapid FIV Ab/FeLV Ag Test performed very well and can be recommended for use in veterinary practice.", "journal": "Veterinary clinical pathology", "doi": "10.1111/j.1939-165X.2009.00196.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "19925574", "author": "Stützer B", "n_authors": 7, "title": "Role of latent feline leukemia virus infection in nonregenerative cytopenias of cats.", "abstract": "Nonregenerative cytopenias such as nonregenerative anemia, neutropenia, and thrombocytopenia in cats with feline leukemia virus (FeLV) antigen are assumed to be caused by the underlying FeLV infection. In addition, cats with negative FeLV antigen-test results that have cytopenias of unknown etiology often are suspected to suffer from latent FeLV infection that is responsible for the nonregenerative cytopenias. The purpose of this study was to assess the role of latent FeLV infection by polymerase chain reaction (PCR) in bone marrow of cats with nonregenerative cytopenias that had negative FeLV antigen test results in blood. Thirty-seven cats were included in the patient group. Inclusion criteria were (1) nonregenerative cytopenia of unknown origin and (2) negative FeLV antigen test result. Antigenemia was determined by detection of free FeLV p27 antigen by ELISA in serum. Furthermore, 7 cats with positive antigen test results with nonregenerative cytopenia were included as control group I, and 30 cats with negative antigen test results without nonregenerative cytopenia were included as control group II. Whole blood and bone marrow samples were tested by 2 different PCR assays detecting sequences of the envelope or long terminal repeat genes. FeLV immunohistochemistry was performed in bone marrow samples. Two of the 37 cats (5.4%) in the patient group were positive on the bone marrow PCR results and thus were latently infected with FeLV. The findings of this study suggest that FeLV latency is rare in cats with nonregenerative cytopenias.", "journal": "Journal of veterinary internal medicine", "doi": "10.1111/j.1939-1676.2009.0417.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "19915325", "author": "Nakaya Y", "n_authors": 4, "title": "Focus assay on FeLIX-dependent feline leukemia virus.", "abstract": "T-lymphotropic feline leukemia virus (FeLV-T) induces immunodeficiency in cats. FeLV-T is fusion-defective and requires a cofactor, termed FeLIX, for infection. FeLIX is a truncated envelope glycoprotein of an endogenous FeLV and mediates infection by binding a phosphate transporter Pit-1. In this study, we established a feline sarcoma-positive leukemia-negative cell line expressing FeLIX, named QN/FeLIX cells. Upon infection, FeLV-T induced prominent foci with syncytia in QN/FeLIX cells and could be titrated by the focus assay. In addition, we established a FeLIX-expressing feline fibroblast cell line, named AH/FeLIX cells. FeLV-T productively infected AH/FeLIX cells and induced severe CPE with syncytia. QN/FeLIX and AH/FeLIX cells will be useful for the study of FeLIX-dependent mutants in FeLV-infected cats.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.09-0194", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "19896221", "author": "Meli ML", "n_authors": 9, "title": "Feline leukemia virus infection: a threat for the survival of the critically endangered Iberian lynx (Lynx pardinus).", "abstract": "The Iberian lynx (Lynx pardinus) is considered the most endangered felid species in the world. To date, less than 200 animals remain in the wild. Low numbers and genetic uniformity may contribute to render this species particularly susceptible to infectious diseases. Different pathogens have been identified in Iberian lynxes; including several feline bacterial and viral agents. Within a 6-month period starting in December 2006, 12 lynxes living in the northern part of the Doñana area were found to be infected with feline leukemia virus (FeLV). Eleven of these animals were antigenemic, and four of them died in the wild in less than 6 months since the first infected animal had been discovered. The remaining viremic lynxes were captured and allocated to a quarantine center to stop the spread of the infection. An additional three animals died shortly in the quarantine center due to acute anemic disease. Sequencing of the envelope surface unit gene revealed a common origin for the FeLV found in all lynxes. The sequences were closely related to FeLV-A/61E, originally isolated from cats in the USA. Our data demonstrate that, similarly to FeLV, the introduction of a new or particularly pathogenic infection brought into the small population of Iberian lynxes by other wild carnivores or feral cats and dogs roaming in the same habitats have severe consequences. It could result in epidemics that have the potential to eradicate the entire lynx population.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2009.10.010", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "19879301", "author": "Fujino Y", "n_authors": 4, "title": "Molecular cytogenetic analysis of feline leukemia virus insertions in cat lymphoid tumor cells.", "abstract": "This study was conducted to map the acquired proviral insertions in the chromosomal genome of feline lymphoid tumors induced by feline leukemia virus (FeLV). Chromosome specimens of the lymphoid tumor-derived cell lines and normal cat lymphocytes were subjected to fluorescence in situ hybridization and tyramide signal amplification, using an exogenous FeLV-A genome as a probe. Specific hybridization signals were detected only on the metaphase chromosomes of the tumor cells. Poisson's distribution-based statistics indicated that 6 chromosomal loci in each cell line showed FeLV integration. In the examination of metaphase chromosomes of FL-74, FT-1 and KO-1 cells, significant signals were detected on B2p15-p14, B2q11, D1p14, E1p14-p13, E1q12 and F2q16; A2p23-p22, B2p15-p14, B4p15-p14, D4q23-q24, E1p14-p13 and E2p13-p12; and A2p22, A3q22, B1p13, B1q13, D1p13 and D3p15-p14, respectively. Consistently, Southern blot hybridization using an FeLV LTR-U3 probe specific for exogenous FeLV revealed the presence of at least 6 copies of exogenous FeLV proviruses at different integration sites in each cell line. These results indicate that there may be common FeLV integration sites at least in A2p22 and B2p15-p14. The cytogenetic analysis used in this study can promptly screen FeLV insertions and provide tags for identifying the novel common integration site.", "journal": "Journal of virological methods", "doi": "10.1016/j.jviromet.2009.10.021", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "19879052", "author": "García-Bocanegra I", "n_authors": 8, "title": "Factors affecting seroprevalence of Toxoplasma gondii in the endangered Iberian lynx (Lynx pardinus).", "abstract": "Wild felids are considered important in maintaining the sylvatic cycle of Toxoplasma gondii. Although, T. gondii antibodies have been reported in several species of wild felids, little is known of the epidemiology and risk factors associated with T. gondii infection in wild cats. The Iberian lynx (Lynx pardinus) is the most endangered felid species in the world. In the present study, seroprevalence and associated risk factors for T. gondii infection in a large population of Iberian lynx in Spain were determined. Serum samples from 129 Iberian lynx collected from 2005 to 2009 and 85 wild rabbits (Oryctolagus cuniculus), sharing the habitat with the Iberian lynx, were tested for antibodies to T. gondii by the modified agglutination test (MAT) using a cut-off value of 1:25. Antibodies to T. gondii were found in 81 of 129 (62.8%) Iberian lynx. Seroprevalence to T. gondii in Iberian lynx significantly increased with age (P<0.001). T. gondii seroprevalences were similar in free-ranging (66.7% of 93) and wild-caught captive lynx (69% of 84) but significantly lower in captive-born lynx (22.5% of 40). Seroprevalence was higher in lynx with concurrent Cytauxzoonfelis (88% of 25) but not with concurrent Feline Leukemia Virus (FeLV) infection (53.8% of 13). There were no significant differences in seroprevalence between sexes, geographic region and year of sample collection (2005-2009). Oocysts of T. gondii were not detected microscopically in fecal samples from 58 lynx. Wild rabbits are considered the most important food for the lynx. Antibodies to T. gondii were found in 14 (11.9%) of 85 rabbits tested. The present results indicate that T. gondii infection is widespread in the two areas where Iberian lynx survive in Spain. The fact that four captive-born lynx seroconverted was indication of contact with T. gondii also in the Captive Breeding Centers, hence, control measures to prevent T. gondii infection would be necessary in these centers.", "journal": "Veterinary parasitology", "doi": "10.1016/j.vetpar.2009.09.044", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "19861115", "author": "Major A", "n_authors": 8, "title": "Exposure of cats to low doses of FeLV: seroconversion as the sole parameter of infection.", "abstract": "In felids, feline leukemia virus (FeLV) infection results in a variety of outcomes that range from abortive (virus readily eliminated and never detectable) to progressive infection (persistent viremia and viral shedding). Recently, a novel outcome was postulated for low FeLV infectious doses. Naïve cats exposed to faeces of persistently infected cats seroconverted, indicating infection, but remained negative for provirus and p27 antigen in blood. FeLV provirus was found in some tissues but not in the bone marrow, infection of which is usually considered a necessary stage for disease progression. To investigate the impact of low FeLV doses on young cats and to test the hypothesis that low dose exposure may lead to an unknown pathogenesis of infection without involvement of the bone marrow, 21 cats were infected oronasally with variable viral doses. Blood p27, proviral and viral loads were followed until week 20 post-infection. Tissue proviral loads were determined as well. The immune response was monitored by measuring FeLV whole virus and p45 antibodies; and feline oncornavirus-associated cell membrane antigen (FOCMA) assay. One cat showed regressive infection (transient antigenemia, persistent provirus-positivity, and seroconversion) with provirus only found in some organs at sacrifice. In 7 of the 20 remaining cats FOCMA assay positivity was the only sign of infection, while all other tests were negative. Overall, the results show that FeLV low dose exposure can result in seroconversion during a presumed abortive infection. Therefore, commonly used detection methods do not detect all FeLV-infected animals, possibly leading to an underestimation of the prevalence of infection.", "journal": "Veterinary research", "doi": "10.1051/vetres/2009065", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "19793908", "author": "Wardini AB", "n_authors": 9, "title": "Characterization of neutrophil extracellular traps in cats naturally infected with feline leukemia virus.", "abstract": "Feline leukemia virus (FeLV), a common, naturally occurring gammaretrovirus in domestic cats, is associated with degenerative diseases of the haematopoietic system, immunodeficiency and neoplasia. FeLV infection causes an important suppression of neutrophil function, leading to opportunistic infections. Recently, a new microbicidal mechanism named NETosis was described in human, bovine and fish neutrophils, as well as in chicken heterophils. The purpose of the present study was to characterize NETosis in feline neutrophils, as well as to evaluate neutrophil function in FeLV naturally infected symptomatic and asymptomatic cats through the phagocytosis process, release of neutrophil extracellular traps (NETs) and myeloperoxidase (MPO) activity. The results showed that feline neutrophils stimulated with protozoa parasites released structures comprising DNA and histones, which were characterized as NETs by immunofluorescence. Quantification of NETs after neutrophil stimulation showed a significant increase in NET release by neutrophils from FeLV(-) and FeLV(+) asymptomatic cats compared with FeLV(+) symptomatic cats. Moreover, the number of released NETs and MPO activity in unstimulated neutrophils of FeLV(+) symptomatic cats were higher than those in unstimulated neutrophils from FeLV(-) and FeLV(+) asymptomatic cats. This study reports, for the first time, NET release by feline neutrophils, along with the fact that NET induction may be modulated by a viral infection. The results indicate that the NET mechanism appears to be overactivated in FeLV(+) cats and that this feature could be considered a marker of disease progression in FeLV infection.", "journal": "The Journal of general virology", "doi": "10.1099/vir.0.014613-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "22547834", "author": "Ravi M", "n_authors": 4, "title": "Feline leukemia virus and feline immunodeficiency virus article - a comment.", "abstract": null, "journal": "The Canadian veterinary journal = La revue veterinaire canadienne", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "22379197", "author": "Stojanovic V", "n_authors": 2, "title": "Infectious disease prevalence in a feral cat population on Prince Edward Island, Canada.", "abstract": "Ninety-six feral cats from Prince Edward Island were used to determine the prevalence of selected infectious agents. The prevalence rates were 5.2% for feline immunodeficiency virus, 3.1% for feline leukemia virus, 3.1% for Mycoplasma haemofelis, 8.4% for Candidatus Mycoplasma haemominutum, 2.1% for Bartonella spp. and 29.8% for exposure to Toxoplasma gondii. Oocysts of T. gondii were detected in 1.3% of the fecal samples that were collected. Gender and retroviral status of the cats were significantly correlated with hemoplasma infections. Use of a flea comb showed that 9.6% of the cats had fleas; however, flea infestation was not associated with any of the infectious agents.", "journal": "The Canadian veterinary journal = La revue veterinaire canadienne", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "22294790", "author": "Little S", "n_authors": 6, "title": "Feline leukemia virus and feline immunodeficiency virus in Canada: recommendations for testing and management.", "abstract": "Feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) are common and important infectious disease agents of cats in Canada. Seroprevalence data for FeLV and FIV in various populations of Canadian cats are reviewed and recommendations for testing and management of infections by these viruses in cats in Canada are presented. Retrovirus testing in Canada is infrequent in comparison with the United States, and efforts should be focused on reducing physical and other barriers to testing, and on education of veterinarians, veterinary team members, and cat owners regarding the importance of testing. New test methodologies for FeLV and FIV are emerging, and should be independently evaluated in order to provide practitioners with information on test reliability. Finally, more information is needed on FIV subtypes in Canada to improve diagnostics and vaccines, and to provide information on disease outcomes.", "journal": "The Canadian veterinary journal = La revue veterinaire canadienne", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "22232645", "author": "Cho SJ", "n_authors": 4, "title": "Uterine adenocarcinoma with feline leukemia virus infection.", "abstract": "Feline endometrial adenocarcinomas are uncommon malignant neoplasms that have been poorly characterized to date. In this study, we describe a uterine adenocarcinoma in a Persian cat with feline leukemia virus infection. At the time of presentation, the cat, a female Persian chinchilla, was 2 years old. The cat underwent surgical ovariohystectomy. A cross-section of the uterine wall revealed a thickened uterine horn. The cat tested positive for feline leukemia virus as detected by polymerase chain reaction. Histopathological examination revealed uterine adenocarcinoma that had metastasized to the omentum, resulting in thickening and the formation of inflammatory lesions. Based on the histopathological findings, this case was diagnosed as a uterine adenocarcinoma with abdominal metastasis. To the best of our knowledge, this is the first report of a uterine adenocarcinoma with feline leukemia virus infection.", "journal": "Laboratory animal research", "doi": "10.5625/lar.2011.27.4.347", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "22160079", "author": "Ball S", "n_authors": 1, "title": "Diamond Blackfan anemia.", "abstract": "Mutations affecting genes encoding ribosomal proteins cause Diamond Blackfan anemia (DBA), a rare congenital syndrome associated with physical anomalies, short stature, red cell aplasia, and an increased risk of malignancy. p53 activation has been identified as a key component in the pathophysiology of DBA after cellular and molecular studies of knockdown cellular and animal models of DBA and other disorders affecting ribosomal assembly or function. Other potential mechanisms that warrant further investigation include impaired translation as the result of ribosomal insufficiency, which may be ameliorated by leucine supplementation, and alternative splicing leading to reduced expression of a cytoplasmic heme exporter, the human homolog of the receptor for feline leukemia virus C (FVLCR). However, the molecular basis for the characteristic steroid responsiveness of the erythroid failure in DBA remains unknown. This review explores the clinical and therapeutic implications of the current state of knowledge and delineates important but as-yet-unanswered questions.", "journal": "Hematology. American Society of Hematology. Education Program", "doi": "10.1182/asheducation-2011.1.487", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "22079343", "author": "Gunn-Moore DA", "n_authors": 7, "title": "Mycobacterial disease in cats in Great Britain: I. Culture results, geographical distribution and clinical presentation of 339 cases.", "abstract": "This study investigated 339 cases of feline mycobacterial disease from cats with cutaneous lesions or masses found at exploratory laparotomy. Tissue samples were submitted to the Veterinary Laboratories Agency for mycobacterial culture over a 4-year period to December 2008. The study assessed which species of culturable mycobacteria were involved, where the cats lived, and their clinical presentation (physical findings, serum biochemistry, radiography, feline leukaemia virus and feline immunodeficiency virus status). Mycobacterium microti was cultured from 19%, Mycobacterium bovis 15%, Mycobacterium avium 7%, non-M avium non-tuberculous mycobacteria 6%, with no growth in 53% of samples. M microti, M bovis and M avium were found in almost mutually exclusive clusters within Great Britain (GB) (ie, M bovis in South-West England/Wales/Welsh Border, M avium in eastern England and M microti south of London and in South-West Scotland). While differences were seen in the clinical presentation and distribution of lesions caused by the different infections, these were not sufficiently different to be diagnostic. Cats commonly presented with single or multiple cutaneous lesions (74%), which were sometimes ulcerated or discharging, located most frequently on the head (54%). Lymph nodes were usually involved (47%); typically the submandibular nodes. Systemic or pulmonary signs were rarely seen (10-16%). When a cat is suspected of having mycobacteriosis, accurate identification of the species involved helps to determine appropriate action. Our findings show that knowing the cat's geographic location can be helpful, while the nature of the clinical presentation is less useful. Most cases of feline mycobacterial disease in GB are cutaneous.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2011.07.012", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "22063207", "author": "Gunn-Moore DA", "n_authors": 2, "title": "CNS disease in the cat: current knowledge of infectious causes.", "abstract": "Neurological disease is a relatively common reason for referral, constituting approximately 10% of the feline referral caseload. Nearly one-third to one-half of these cases may be infectious in origin. As such, an awareness of infectious diseases causing central nervous system (CNS) signs in cats, and their clinical diagnosis and management, is relevant to anyone dealing with cats on a regular basis. Some conditions (eg, rabies) are more common in certain countries than others. Conditions such as feline infectious peritonitis (FIP) and toxoplasmosis are of global significance. Many infectious diseases may affect any feline population. Some, such as FIP, are more common in pedigree households, whereas others such as toxoplasmosis, feline immunodeficiency virus (FIV) or feline leukaemia virus (FeLV) infections, are more likely to affect a single cat with an outdoor lifestyle. All patients benefit from thorough history taking and clinical, neurological and ophthalmic examinations, which all require minimal equipment. Infectious diseases may often be diagnosed on blood samples; however, definitive diagnosis may require more extensive investigation involving cerebrospinal fluid analysis or advanced imaging necessitating access to computed tomography or magnetic resonance imaging. The information in this review, which summarises current knowledge of infectious diseases affecting the CNS, is collated from publications on the infectious diseases comprising previous research papers, review articles, case series, case reports and textbooks, supplemented by the clinical experience of the authors.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2011.09.004", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "22045454", "author": "Boretti FS", "n_authors": 3, "title": "[FeLV infection in the cat: clinically relevant aspects].", "abstract": "The feline leukemia virus (FeLV) is a retrovirus of the domestic cat that was described almost 50 years ago. The FeLV-infection may lead to fatal diseases in domestic and small wild cats. The use of efficacious diagnostics assays and vaccines led to a reduction of the FeLV prevalence; however, FeLV still poses a problem for the cat presented with the infection. This article aims to describe recent developments in diagnostics and findings in the infection pathogenesis that are clinically relevant.", "journal": "Schweizer Archiv fur Tierheilkunde", "doi": "10.1024/0036-7281/a000260", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21923822", "author": "Benz P", "n_authors": 7, "title": "Detection of Encephalitozoon cuniculi in the feline cataractous lens.", "abstract": "Identification of Encephalitozoon cuniculi (E. cuniculi) as a possible causative agent for cataracts and uveitis in cats. Within a 12-month study period, cats that were presented with focal anterior cortical or mature cataract and secondary uveitis underwent a complete ophthalmic examination, complete blood count, serum biochemistry, serologic tests for E. cuniculi and tests for feline immunodeficiency virus (FIV), feline infectious peritonitis (FIP), feline leukemia virus (FeLV) and Toxoplasma gondii (T. gondii). PCR for DNA detection of E. cuniculi and T. gondii as well as cytologic examination of aqueous humor after paracentesis and phacoemulsified lens material were also performed. In addition histopathologic examination of the resected anterior lens capsule and attached lens epithelial cells was performed. Serologic testing for antibodies against E. cuniculi was also performed in 100 ophthalmologically healthy cats. Eleven (19 eyes) European shorthair cats with a median age of 3.5 years were included. Nine of 11 cats had bilateral cataracts, with 12/19 eyes having focal anterior cortical cataracts and 7/19 eyes having mature cataracts. In 14/19 eyes anterior uveitis was present. All cats had a positive antibody titer (1:80-1:10,000) for E. cuniculi. Encephalitozoon cuniculi DNA was detected by PCR and sequencing in 18/19 lenses and in 10/19 aqueous samples. Five tentative positive results were detected by cytologic examination. Spores were detected in 15/19 samples of lens material with histopathologic staining. Only 2/100 ophthalmologically healthy cats showed a positive antibody titer for E. cuniculi. Encephalitozoon cuniculi is a cause of focal anterior cortical cataract and anterior uveitis in cats.", "journal": "Veterinary ophthalmology", "doi": "10.1111/j.1463-5224.2011.00873.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21994802", "author": "Bolin LL", "n_authors": 2, "title": "Viral determinants of FeLV infection and pathogenesis: lessons learned from analysis of a natural cohort.", "abstract": "Detailed analysis has been performed over many years of a geographic and temporal cohort of cats naturally infected with feline leukemia virus (FeLV). Molecular analysis of FeLV present in the diseased tissues and application of those viruses to experimental systems has revealed unique isolates with distinctive disease potential, previously uncharacterized virus-receptor interactions, information about the role of recombinant viruses in disease induction, and novel viral and cellular oncogenes implicated in pathogenesis, among other findings. The studies have contributed to an understanding of the selective forces that lead to predominance of distinctive FeLV isolates and disease outcomes in a natural population.", "journal": "Viruses", "doi": "10.3390/v3091681", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21957297", "author": "Wang J", "n_authors": 6, "title": "Identification of a Cullin5-ElonginB-ElonginC E3 complex in degradation of feline immunodeficiency virus Vif-mediated feline APOBEC3 proteins.", "abstract": "Various feline APOBEC3 (fA3) proteins exhibit broad antiviral activities against a wide range of viruses, such as feline immunodeficiency virus (FIV), feline foamy virus (FFV), and feline leukemia virus (FeLV), as well as those of other species. This activity can be counteracted by the FIV Vif protein, but the mechanism by which FIV Vif suppresses fA3s is unknown. In the present study, we demonstrated that FIV Vif could act via a proteasome-dependent pathway to overcome fA3s. FIV Vif interacted with feline cellular proteins Cullin5 (Cul5), ElonginB, and ElonginC to form an E3 complex to induce degradation of fA3s. Both the dominant-negative Cul5 mutant and a C-terminal hydrophilic replacement ElonginC mutant potently disrupted the FIV Vif activity against fA3s. Furthermore, we identified a BC-box motif in FIV Vif that was essential for the recruitment of E3 ubiquitin ligase and also required for FIV Vif-mediated degradation of fA3s. Moreover, despite the lack of either a Cul5-box or a HCCH zinc-binding motif, FIV Vif specifically selected Cul5. Therefore, FIV Vif may interact with Cul5 via a novel mechanism. These finding imply that SOCS proteins may possess distinct mechanisms to bind Cul5 during formation of the Elongin-Cullin-SOCS box complex.", "journal": "Journal of virology", "doi": "10.1128/JVI.05218-11", "deposited_data": "Sim", "nuccore_ids": "350536168, 350536148, 334848056, 334848054, 350536168, 350536148", "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21917946", "author": "Hussain N", "n_authors": 5, "title": "Feline leukemia virus infection requires a post-receptor binding envelope-dependent cellular component.", "abstract": "Gammaretrovirus receptors have been suggested to contain the necessary determinants to mediate virus binding and entry. Here, we show that murine NIH 3T3 and baby hamster kidney (BHK) cells overexpressing receptors for subgroup A, B, and C feline leukemia viruses (FeLVs) are weakly susceptible (10(1) to 10(2) CFU/ml) to FeLV pseudotype viruses containing murine leukemia virus (MLV) core (Gag-Pol) proteins, whereas FeLV receptor-expressing murine Mus dunni tail fibroblast (MDTF) cells are highly susceptible (10(4) to 10(6) CFU/ml). However, NIH 3T3 cells expressing the FeLV subgroup B receptor PiT1 are highly susceptible to gibbon ape leukemia virus pseudotype virus, which differs from the FeLV pseudotype viruses only in the envelope protein. FeLV resistance is not caused by a defect in envelope binding, low receptor expression levels, or N-linked glycosylation. Resistance is not alleviated by substitution of the MLV core in the FeLV pseudotype virus with FeLV core proteins. Interestingly, FeLV resistance is alleviated by fusion of receptor-expressing NIH 3T3 and BHK cells with MDTF or human TE671 cells, suggesting the absence of an additional cellular component in NIH 3T3 and BHK cells that is required for FeLV infection. The putative FeLV-specific cellular component is not a secreted factor, as MDTF conditioned medium does not alleviate the block to FeLV infection. Together, our findings suggest that FeLV infection requires an additional envelope-dependent cellular component that is absent in NIH 3T3 and BHK cells but that is present in MDTF and TE671 cells.", "journal": "Journal of virology", "doi": "10.1128/JVI.00822-11", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1676319575, 1653961537, 1519315556, 451172078, 451172076", "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21908376", "author": "Gumber S", "n_authors": 2, "title": "Vaccine-associated fibrosarcoma with keloidal differentiation in a cat.", "abstract": "A 6-year-old Domestic Shorthair cat was presented with a history of subcutaneous mass of the lateral left hind limb. The subcutaneous mass developed over a period of approximately 16 months subsequent to administration of Feline leukemia virus vaccines. Based on the histopathological and immunohistochemical examination, the subcutaneous mass was diagnosed as vaccine-associated fibrosarcoma with keloidal differentiation.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/1040638711416617", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21900723", "author": "Boenzli E", "n_authors": 10, "title": "In vitro inhibition of feline leukaemia virus infection by synthetic peptides derived from the transmembrane domain.", "abstract": "The feline leukaemia virus (FeLV) is a gammaretrovirus commonly affecting cats. Infection with this virus often leads to fatal outcomes and, so far, no cure is available for this disease. Synthetic peptides with structures mimicking the transmembrane protein of the viral surface proteins hold the potential to effectively interfere with viral entry by hampering the fusion of viral and host cell membranes and constitute a novel approach for the treatment of infections with retroviruses. We identified and synthetically produced 11 FeLV peptides and evaluated their potential to block FeLV infection in vitro. Cell cultures were exposed to FeLV subgroup A prior to the addition of the peptides. The inhibitory effect of the peptides was assessed by measuring FeLV gag protein in the supernatant of peptide versus mock-treated cell cultures using an ELISA. A peptide (EPK364) of 37 amino acids in length, with sequence homology to the HIV fusion inhibitor T-20, significantly suppressed viral replication by 88%, whereas no effects were found for shorter peptides. Two structurally modified variants of EPK364 also inhibited viral replication by up to 58% (EPK397) and 27% (EPK398). Our data support the identification of synthetic FeLV peptides that have the potential for a curative short-term therapy of viraemic cats. In addition, these peptides might become an important tool in xenotransplantation, where endogenous gammaretroviruses of the donor species might be able to infect the host.", "journal": "Antiviral therapy", "doi": "10.3851/IMP1850", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21889617", "author": "Katrin Helfer-Hungerbuehler A", "n_authors": 8, "title": "Quantification and molecular characterization of the feline leukemia virus A receptor.", "abstract": "Virus receptors and their expression patterns on the cell surface determine the cell tropism of the virus, host susceptibility and the pathogenesis of the infection. Feline thiamine transport protein 1 (fTHTR1) has been identified as the receptor for feline leukemia virus (FeLV) A. The goal of the present study was to develop a quantitative, TaqMan real-time PCR assay to investigate fTHTR1 mRNA expression in tissues of uninfected and FeLV-infected cats, cats of different ages, in tumor tissues and leukocyte subsets. Moreover, the receptor was molecularly characterized in different feline species. fTHTR1 mRNA expression was detected in all 30 feline tissues investigated, oral mucosa scrapings and blood. Importantly, identification of significant differences in fTHTR1 expression relied on normalization with an appropriate reference gene. The lowest levels were found in the blood, whereas high levels were measured in the oral mucosa, salivary glands and the musculature. In the blood, T lymphocytes showed significantly higher fTHTR1 mRNA expression levels than neutrophil granulocytes. In vitro activation of peripheral blood mononuclear cells with concanavalin A alone or followed by interleukin-2 led to a transient increase of fTHTR1 mRNA expression. In the blood, but not in the examined tissues, FeLV-infected cats tended to have lower fTHTR1 mRNA levels than uninfected cats. The fTHTR1 mRNA levels were not significantly different between tissues with lymphomas and the corresponding non-neoplastic tissues. fTHTR1 was highly conserved among different feline species (Iberian lynx, Asiatic and Indian lion, European wildcat, jaguarundi, domestic cat). In conclusion, while ubiquitous fTHTR1 mRNA expression corresponded to the broad target tissue range of FeLV, particularly high fTHTR1 levels were found at sites of virus entry and shedding. The differential susceptibility of different species to FeLV could not be attributed to variations in the fTHTR1 sequence.", "journal": "Infection, genetics and evolution : journal of molecular epidemiology and evolutionary genetics in infectious diseases", "doi": "10.1016/j.meegid.2011.08.015", "deposited_data": "Sim", "nuccore_ids": "342360140, 342360138, 342360136, 342360134, 2020824204, 2020824202", "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21880527", "author": "Beatty JA", "n_authors": 9, "title": "Markers of feline leukaemia virus infection or exposure in cats from a region of low seroprevalence.", "abstract": "Molecular techniques have demonstrated that cats may harbour feline leukaemia virus (FeLV) provirus in the absence of antigenaemia. Using quantitative real-time polymerase chain reaction (qPCR), p27 enzyme-linked immunosorbent assay (ELISA), anti-feline oncornavirus-associated cell-membrane-antigen (FOCMA) antibody testing and virus isolation (VI) we investigated three groups of cats. Among cats with cytopenias or lymphoma, 2/75 were transiently positive for provirus and anti-FOCMA antibodies were the only evidence of exposure in another. In 169 young, healthy cats, all tests were negative. In contrast, 3/4 cats from a closed household where FeLV was confirmed by isolation, had evidence of infection. Our results support a role for factors other than FeLV in the pathogenesis of cytopenias and lymphoma. There was no evidence of exposure in young cats. In regions of low prevalence, where the positive predictive value of antigen testing is low, qPCR may assist with diagnosis.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2011.07.011", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21812756", "author": "Wurm M", "n_authors": 9, "title": "Improved lentiviral gene transfer into human embryonic stem cells grown in co-culture with murine feeder and stroma cells.", "abstract": "Genetic modification of human embryonic stem cells (hESCs) using biophysical DNA transfection methods are hampered by the very low single cell survival rate and cloning efficiency of hESCs. Lentiviral gene transfer strategies are widely used to genetically modify hESCs but limited transduction efficiencies in the presence of feeder or stroma cells present problems, particularly if vesicular stomatitis virus glycoprotein (VSV-G) pseudotyped viral particles are applied. Here, we investigated whether the recently described semen derived enhancer of virus infection (SEVI) and alternative viral envelope proteins derived from either Gibbon ape leukaemia virus (GALV) or feline leukaemia virus (RD114) are applicable for transducing hESCs during co-culture with feeder or stroma cells. Our first set of experiments demonstrates that SEVI has no toxic effect on murine or hESCs and that exposure to SEVI does not interfere with the pluripotency-associated phenotype. Focusing on hESCs, we were able to further demonstrate that SEVI increases the transduction efficiencies of GALV and RD114 pseudotyped lentiviral vectors. More importantly, aiming at targeted differentiation of hESCs into functional somatic cell types, GALV pseudotyped lentiviral particles could efficiently and exclusively transduce hESCs grown in co-culture with OP9-GFP stroma cells (which were often used to induce differentiation into haematopoietic derivatives).", "journal": "Biological chemistry", "doi": "10.1515/BC.2011.085", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21807418", "author": "Hartmann K", "n_authors": 1, "title": "Clinical aspects of feline immunodeficiency and feline leukemia virus infection.", "abstract": "Feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) are retroviruses with a global impact on the health of domestic cats. The two viruses differ in their potential to cause disease. FIV can cause an acquired immunodeficiency syndrome that increases the risk of developing opportunistic infections, neurological diseases, and tumors. In most naturally infected cats, however, FIV itself does not cause severe clinical signs, and FIV-infected cats may live many years without any health problems. FeLV is more pathogenic, and was long considered to be responsible for more clinical syndromes than any other agent in cats. FeLV can cause tumors (mainly lymphoma), bone marrow suppression syndromes (mainly anemia) and lead to secondary infectious diseases caused by suppressive effects of the virus on bone marrow and the immune system. Today, FeLV is less important as a deadly infectious agent as in the last 20 years prevalence has been decreasing in most countries.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2011.06.003", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21764142", "author": "Bolin LL", "n_authors": 3, "title": "The surface glycoprotein of a natural feline leukemia virus subgroup A variant, FeLV-945, as a determinant of disease outcome.", "abstract": "Feline leukemia virus (FeLV) is a natural retrovirus of domestic cats associated with degenerative, proliferative and malignant diseases. Studies of FeLV infection in a cohort of naturally infected cats were undertaken to examine FeLV variation, the selective pressures operative in FeLV infection that lead to predominance of natural variants, and the consequences for infection and disease progression. A unique variant, designated FeLV-945, was identified as the predominant isolate in the cohort and was associated with non-T-cell diseases including multicentric lymphoma. FeLV-945 was assigned to the FeLV-A subgroup based on sequence analysis and receptor utilization, but was shown to differ in sequence from a prototype member of FeLV-A, designated FeLV-A/61E, in the long terminal repeat (LTR) and the surface glycoprotein gene (SU). A unique sequence motif in the FeLV-945 LTR was shown to function as a transcriptional enhancer and to confer a replicative advantage. The FeLV-945 SU protein was observed to differ in sequence as compared to FeLV-A/61E within functional domains known to determine receptor selection and binding. Experimental infection of newborn cats was performed using wild type FeLV-A/61E or recombinant FeLV-A/61E in which the LTR (61E/945L) or LTR and SU (61E/945SL) were exchanged for that of FeLV-945. Infection with either FeLV-A/61E or 61E/945L resulted in T-cell lymphoma of the thymus, although 61E/945L caused disease significantly more rapidly. In contrast, infection with 61E/945SL resulted in the rapid induction of a multicentric lymphoma of B-cell origin, thus recapitulating the outcome of natural infection and implicating FeLV-945 SU as a determinant of disease outcome. Recombinant FeLV-B was detected infrequently and at low levels in multicentric lymphomas, and was thereby not implicated in disease induction. Preliminary studies of receptor interaction indicated that virus particles bearing FeLV-945 SU bind to the FeLV-A receptor more efficiently than do particles bearing FeLV-A/61E SU, and that soluble SU proteins expressed from the viruses demonstrate the same differential binding phenotype. Preliminary mutational analysis of FeLV-945 was performed by exchanging regions containing either the primary receptor binding determinant, VRA, the secondary determinant, VRB, or a proline-rich region, PRR, with that of FeLV-A/61E. Results implicated a region containing VRA as a minor contributor, while a region containing VRB largely conferred increased binding efficiency.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2011.06.015", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21757241", "author": "Little S", "n_authors": 1, "title": "A review of feline leukemia virus and feline immunodeficiency virus seroprevalence in cats in Canada.", "abstract": "Feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) are common and important infectious diseases of cats in Canada. Prevalence data are necessary to define prophylactic, management, and therapeutic measures for stray, feral and owned cats. Recently, comprehensive data on the seroprevalence of retrovirus infections of cats in Canada have become available and are reviewed. Further investigation into geographic variations in retrovirus seroprevalence within Canada is warranted, and may provide information to improve recommendations for testing and prevention. As well, more information is needed on FIV subtypes in Canada to improve diagnostics and vaccines, as well as to provide information on disease outcomes.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2011.06.018", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21719116", "author": "Doménech A", "n_authors": 8, "title": "Use of recombinant interferon omega in feline retrovirosis: from theory to practice.", "abstract": "Type-I interferons (IFNs) are cytokines that have non-specific antiviral activity, participating mostly in innate defense mechanisms. Their administration has been proposed to treat several viral and immunomediated diseases as an immunomodulatory therapy. Due to its availability, recombinant human interferon-alpha (rHuIFN-α) has been studied in relation to feline retrovirosis, both in vitro and in vivo. However, IFNs are species-specific and antibodies have been shown to develop in response to the high rHuIFN-α doses necessary for an effective therapy. A recombinant feline IFN has been developed, which has been characterized as interferon-omega (rFeIFN-ω), designed to overcome these problems. Nonetheless, very few studies have been undertaken to evaluate its efficacy in cats naturally infected with FIV or FeLV. In an initial study, we here demonstrated that rFeIFN-ω can dramatically improve the clinical condition of infected cats, and induce improvement of hematologic parameters. Minor changes or no change was observed for hypergammaglobulinemia, CD4/CD8 ratio, proviral load, viremia and RT activity, suggesting that the overall effect of IFN was on innate immunity. More studies are needed in order to better understand its in vivo mechanisms.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2011.06.008", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21719112", "author": "Robert-Tissot C", "n_authors": 11, "title": "The innate antiviral immune system of the cat: molecular tools for the measurement of its state of activation.", "abstract": "The innate immune system plays a central role in host defence against viruses. While many studies portray mechanisms in early antiviral immune responses of humans and mice, much remains to be discovered about these mechanisms in the cat. With the objective of shedding light on early host-virus interactions in felids, we have developed 12 real-time TaqMan(®) qPCR systems for feline genes relevant to innate responses to viral infection, including those encoding for various IFNα and IFNω subtypes, IFNβ, intracellular antiviral factor Mx, NK cell stimulator IL-15 and effectors perforin and granzyme B, as well as Toll-like receptors (TLRs) 3 and 8. Using these newly developed assays and others previously described, we measured the relative expression of selected markers at early time points after viral infection in vitro and in vivo. Feline embryonic fibroblasts (FEA) inoculated with feline leukemia virus (FeLV) indicated peak levels of IFNα, IFNβ and Mx expression already 6h after infection. In contrast, Crandell-Rees feline kidney (CrFK) cells inoculated with feline herpes virus (FHV) responded to infection with high levels of IFNα and IFNβ only after 24h, and no induction of Mx could be detected. In feline PBMCs challenged in vitro with feline immunodeficiency virus (FIV), maximal expression levels of IFNα, β and ω subtype genes as well as IL-15 and TLRs 3, 7 and 8 were measured between 12 and 24h after infection, whereas expression levels of proinflammatory cytokine gene IL-6 were consistently downregulated until 48h post inoculation. A marginal upregulation of granzyme B was also observed within 3h after infection. In an in vivo experiment, cats challenged with FIV exhibited a 2.4-fold increase in IFNα expression in blood 1 week post infection. We furthermore demonstrate the possibility of stimulating feline immune cells in vitro with various immune response modifiers (IRMs) already known for their immunostimulatory properties in mice and humans, namely Poly IC, Resiquimod (R-848) and dSLIM™, a synthetic oligonucleotide containing several unmethylated CpG motifs. Stimulation of feline PBMCs with dSLIM™ and R-848 effectively enhanced expression of IFNα within 12h by factors of 6 and 12, respectively, and Poly IC induced an increase in Mx mRNA expression of 28-fold. Altogether, we describe new molecular tools and their successful use for the characterization of innate immune responses against viruses in the cat and provide evidence that feline cells can be stimulated by synthetic molecules to enhance their antiviral defence mechanisms.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2011.06.005", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21715022", "author": "Stewart H", "n_authors": 4, "title": "Are endogenous feline leukemia viruses really endogenous?", "abstract": "Full length endogenous feline leukemia virus (FeLV) proviruses exist within the genomes of many breeds of domestic cat raising the possibility that they may also exist in a transmissible exogenous form. Such viruses would share receptor usage with the recombinant FeLV-B subgroup, a viral subgroup that arises in vivo by recombination between exogenous subgroup A virus (FeLV-A) and endogenous FeLV. Accordingly, all isolates of FeLV-B made to date have contained a \"helper\" FeLV-A, consistent with their recombinatorial origin. In order to assess whether endogenous viruses are transmitted between cats, we examined primary isolates of FeLV for which the viral subgroup had been determined for the presence of a subgroup B virus that lacked an FeLV-A. Here we describe the identification of two primary field isolates of FeLV (2518 and 4314) that appeared to contain subgroup B virus only by classical interference assays, raising the possibility of between-host transmission of endogenous FeLV. Sequencing of the env gene and U3 region of the 3' long terminal repeat (LTR) confirmed that both viral genomes contained endogenous viral env genes. However the viral 3' LTRs appeared exogenous in origin with a putative 3' recombination breakpoint residing at the 3' end of the env gene. Further, the FeLV-2518 virions also co-packaged a truncated FeLV-A genome containing a defective env gene, termed FeLV-2518(A) whilst no helper subgroup A viral genome was detected in virions of FeLV-4314. The acquisition of an exogenous LTR by the endogenous FeLV in 4314 may have allowed a recombinant FeLV variant to outgrow an exogenous FeLV-A virus that was presumably present during first infection. Given time, a similar evolution may also occur within the 2518 isolate. The data suggest that endogenous FeLVs may be mobilised by acquisition of exogenous LTRs yielding novel viruses that type biologically as FeLV-B.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2011.06.011", "deposited_data": "Sim", "nuccore_ids": "407809837, 407809834, 339461609", "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21705099", "author": "Hellard E", "n_authors": 9, "title": "When cats' ways of life interact with their viruses: a study in 15 natural populations of owned and unowned cats (Felis silvestris catus).", "abstract": "In natural populations, virus circulation is influenced by host behavior and physiological characteristics. Cat populations exhibit a great variability in social and spatial structure, the existence of different ways of life within a same population may also result in different epidemiological patterns. To test this hypothesis, we used a logistic regression to analyze the risk factors of Feline immunodeficiency virus (FIV), feline herpes virus (FHV), feline calicivirus (FCV), and feline parvovirus (FPV) infection in owned (fed and sheltered) and unowned (neither fed nor sheltered, unsocialized) cats living in a rural environment in the North Eastern part of France. A serological survey was carried out in 492 non-vaccinated and non-sterilized individuals from 15 populations living in the same area. The prevalence of feline leukemia virus (FeLV) was also studied, but too few were infected to analyze the risk factors of this virus. For each virus, the epidemiological pattern was different in owned and unowned cats. Unowned cats were more frequently infected by directly transmitted viruses like FIV, FHV and FCV (21.22%, 67.66%, 86.52% in unowned cats vs 9.55%, 53.88%, 77.18% in owned cats, respectively), a difference that may be explained by a more solitary and more aggressive behavior in unowned adults, and/or possibly by a higher sensitivity related to a more stressful life. On the contrary, owned cats were more frequently infected with FPV (36.41% in owned cats vs 15.61% in unowned cats), possibly as a result of their concentration around human settlements. The present study showed that owned and unowned cats living in a same area have behavioral and physiological characteristics sufficiently different to influence virus circulation. Pooling different types of cats in a single sample without taking it into account could give a wrong picture of the epidemiology of their viruses. The conclusion of this work can be extended to any epidemiological studies led in wildlife species with flexible behavior as any variations in social or spatial structure, between or within populations, could result in different virus circulation.", "journal": "Preventive veterinary medicine", "doi": "10.1016/j.prevetmed.2011.04.020", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21626423", "author": "Coelho WM", "n_authors": 7, "title": "Seroepidemiology of Toxoplasma gondii, Neospora caninum, and Leishmania spp. infections and risk factors for cats from Brazil.", "abstract": "The seroprevalence of infection by Toxoplasma gondii, Neospora caninum, and Leishmania spp. was detected through an indirect immunofluorescence in 70 cats from the Andradina Municipality, São Paulo State, Brazil. Anti-T. gondii antibodies (titer >64) were detected in 15.7% (11/70) of animals, whereas positivity for N. caninum (titer 16) was not observed in any animal. Of the cats from urban and rural areas, 10.4% (5/48) and 27.2% (6/22) were positive for T. gondii, respectively. Breed, age, food, and contact with animals of other species were significant for considering the positivity for T. gondii (P ≤ 0.0001). Cats having access to streets (17.1%, 11/64), cats cohabiting with rats (19.6%, 10/51), and cats feeding on homemade food and raw milk (27.2%, 6/22) were positive for T. gondii. In addition, 4.2% (3/70) of the cats were positive for Leishmania spp. by ELISA technique and negative by IFAT without coinfection with T. gondii and Leishmania spp. There was no serological positivity against feline immunodeficiency virus or feline leukemia virus. In conclusion, T. gondii infection in part of the feline population from Andradina is not linked to immunosuppressions or coinfections but probably to postnatal infection in association with the type of diet and presence of rats.", "journal": "Parasitology research", "doi": "10.1007/s00436-011-2461-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21593354", "author": "Jaacks LM", "n_authors": 11, "title": "Placental expression of the heme transporter, feline leukemia virus subgroup C receptor, is related to maternal iron status in pregnant adolescents.", "abstract": "Little is known about the expression of heme transporters in human placenta and possible associations between these transporters and maternal or neonatal iron status. To address this area of research, relative protein expression of 2 heme transporters, Feline Leukemia Virus, Subgroup C, Receptor 1 (FLVCR1) and Breast Cancer Resistance Protein (BCRP), was assessed using Western-blot analysis in human placental tissue in relation to maternal/neonatal iron status and placental iron concentration. Placental FLVCR1 (n = 71) and BCRP (n = 83) expression were assessed at term (36.6-41.7 wk gestation) in a cohort of pregnant adolescents (13-18 y of age) at high-risk of iron deficiency. Both FLVCR1 and BCRP were detected in all placental samples assayed. Placental FLVCR1 expression was positively related to placental BCRP expression (n = 69; R(2) = 0.104; P < 0.05). Adolescents that were anemic at delivery had lower placental FLVCR1 expression (n = 49; P < 0.05). Placental FLVCR1 expression was positively associated with placental iron concentration at delivery (n = 61; R(2) = 0.064; P < 0.05). In contrast, placental BCRP expression was not significantly associated with maternal iron status or placental iron content. Both FLVCR1 and BCRP are highly expressed in human placental tissue, but only FLVCR1 was significantly inversely associated with maternal iron status and placental iron concentration. Further analysis is needed to explore potential functional roles of FLVCR1 in human placental iron transport.", "journal": "The Journal of nutrition", "doi": "10.3945/jn.110.135798", "deposited_data": "Sim", "nuccore_ids": "2992366869, 2992366690, 2992366613, 2992366579, 2992366569, 2992366523, 2991388172, 2462599825, 2462599823, 2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217352715, 2217352714, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1890334085, 1519315556, 1519311581, 1149890118, 1149890103, 1149890095, 1149890079", "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21570781", "author": "Cattori V", "n_authors": 3, "title": "Inhibition of Feline leukemia virus replication by the integrase inhibitor Raltegravir.", "abstract": "The oncogenic gammaretrovirus Feline leukemia virus (FeLV) has been the leading cause of death among domestic cats until the introduction of efficient diagnostics and vaccines in the late 1980s. So far, no efficient treatment for viremic animals is available. Hence, use of the FeLV model to evaluate antiretroviral therapies applied to HIV is a timely task. The efficacy of the integrase inhibitor Raltegravir, which is widely used for the treatment of HIV in humans, has been assessed in vitro for the FeLV-A/Glasgow-1 strain. EC(50) values for FeLV-A inhibition in feline cell lines are in the range of that observed for HIV and xenotropic murine leukemia virus-related gammaretrovirus. Therefore, Raltegravir may be a potential therapeutical agent for felids with progressive FeLV infection.", "journal": "Veterinary microbiology", "doi": "10.1016/j.vetmic.2011.03.039", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21569491", "author": "Bolin LL", "n_authors": 5, "title": "Distinctive receptor binding properties of the surface glycoprotein of a natural feline leukemia virus isolate with unusual disease spectrum.", "abstract": "Feline leukemia virus (FeLV)-945, a member of the FeLV-A subgroup, was previously isolated from a cohort of naturally infected cats. An unusual multicentric lymphoma of non-T-cell origin was observed in natural and experimental infection with FeLV-945. Previous studies implicated the FeLV-945 surface glycoprotein (SU) as a determinant of disease outcome by an as yet unknown mechanism. The present studies demonstrate that FeLV-945 SU confers distinctive properties of binding to the cell surface receptor. Virions bearing the FeLV-945 Env protein were observed to bind the cell surface receptor with significantly increased efficiency, as was soluble FeLV-945 SU protein, as compared to the corresponding virions or soluble protein from a prototype FeLV-A isolate. SU proteins cloned from other cohort isolates exhibited increased binding efficiency comparable to or greater than FeLV-945 SU. Mutational analysis implicated a domain containing variable region B (VRB) to be the major determinant of increased receptor binding, and identified a single residue, valine 186, to be responsible for the effect. The FeLV-945 SU protein binds its cell surface receptor, feTHTR1, with significantly greater efficiency than does that of prototype FeLV-A (FeLV-A/61E) when present on the surface of virus particles or in soluble form, demonstrating a 2-fold difference in the relative dissociation constant. The results implicate a single residue, valine 186, as the major determinant of increased binding affinity. Computational modeling suggests a molecular mechanism by which residue 186 interacts with the receptor-binding domain through residue glutamine 110 to effect increased binding affinity. Through its increased receptor binding affinity, FeLV-945 SU might function in pathogenesis by increasing the rate of virus entry and spread in vivo, or by facilitating entry into a novel target cell with a low receptor density.", "journal": "Retrovirology", "doi": "10.1186/1742-4690-8-35", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21547230", "author": "Blanco K", "n_authors": 7, "title": "Serological detection of viral infections in captive wild cats from costa rica.", "abstract": "Serum samples from a total of 44 wildcats, 28 margays (Leopardus wiedii), 10 ocelots (Leopardus pardalis), four jaguaroundis (Herpailurus yaguaroundi), one oncilla (Leopardus tigrina), and one jaguar (Panthera onca) were obtained between January 2001 and August 2002 from the Profelis Centre for rehabilitation of wild felids, located in the northwestern region of Costa Rica. Forty three samples were tested for antibodies against feline immunodeficiency virus (FIV) and p27 antigen of feline leukemia virus (FeLV), 42 samples for antibodies against feline parvovirus (FPV), and 30 for antibodies against feline calicivirus (FCV). None of the samples contained detectable antibodies against FIV or p27 antigen of FeLV, all samples contained antibodies against FPV, and one sample contained antibodies against FCV.", "journal": "Veterinary medicine international", "doi": "10.4061/2011/879029", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21509446", "author": "Miró G", "n_authors": 9, "title": "First description of naturally acquired Tritrichomonas foetus infection in a Persian cattery in Spain.", "abstract": "Tritrichomonas foetus has been identified as the causative agent of feline intestinal trichomonosis, characterized by clinical signs of chronic large bowel diarrhoea. This disease has been reported in cats from the USA, Europe and Australia. However, its epidemiology is still unclear. The aim of the present study was to describe T. foetus infection in a Persian cattery in Spain. T. foetus infection was sequentially diagnosed in 20 cats by direct faecal smear examined under the microscope, specific culture (In Pouch TF medium) and PCR. A standard coprological sedimentation method was also performed in order to screen for other intestinal parasites in all the cats included. In addition, sera were tested for IgG antibodies against Leishmania infantum, Toxoplasma gondii, and for the detection of feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV). Five out of 20 cats were positive for T. foetus (25%), two of them by microscopy, culture and PCR and three by culture and PCR. No association was found between T. foetus infection and age or sex. L. infantum and T. gondii seroprevalence rates were 15% and 10%, respectively. The prevalence of FeLV p27 antigen and of FIV antibodies in the study population was zero. Cystoisospora spp. oocysts were detected in one cat. These preliminary results show that the transmission of T. foetus infection in cluster conditions may occur between asymptomatic cats and young or immunocompromised animals.", "journal": "Parasitology research", "doi": "10.1007/s00436-011-2359-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21506874", "author": "Al-Kappany YM", "n_authors": 6, "title": "Seroprevalence of Toxoplasma gondii and concurrent Bartonella spp., feline immunodeficiency virus, feline leukemia virus, and Dirofilaria immitis infections in Egyptian cats.", "abstract": "Toxoplasma gondii and Bartonella spp. are zoonotic pathogens of cats. Feline immunodeficiency virus (FIV) and feline leukemia virus (FeLv) are related to human immunodeficiency virus and human leukemia virus, respectively, and these viruses are immunosuppressive. In the present study, the prevalence of antibodies to T. gondii , Bartonella spp., FIV, as well as FeLv and Dirofilaria immitis antigens was determined in sera from feral cats (Felis catus) from Cairo, Egypt. Using a modified agglutination test, antibodies to T. gondii were found in 172 (95.5%) of the 180 cats with titers of 1∶5 in 9, 1∶10 in 9, 1∶20 in 3, 1∶40 in 5, 1∶80 in 5, 1∶160 in 15, 1∶320 in 22, and 1∶640 or higher in 104. Thus, 57.4% had high T. gondii titers. Antibodies to Bartonella spp. were found in 105 (59.6%) of 178, with titers of 1∶64 in 45, 1∶128 in 39, 1∶256 in 13, 1∶512 in 3, 1∶1,024 in 4, and 1∶2,048 in 1 cat. Antibodies to FIV were detected in 59 (33.9%) of 174 cats. Of 174 cats tested, antigens to FeLv, and D. immitis were detected in 8 (4.6%) and 6 (3.4%) cats, respectively. The results indicate a high prevalence of T. gondii, Bartonella spp., and FIV infections in cats from Cairo, Egypt. This is the first report of Bartonella spp., and D. immitis infection in cats in Egypt.", "journal": "The Journal of parasitology", "doi": "10.1645/GE-2654.1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21498236", "author": "Juvet F", "n_authors": 3, "title": "Assessment of feline blood for transfusion purposes in the Dublin area of Ireland.", "abstract": "The prevalence of A, B and AB blood types and of feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV) infection was determined in cats in Ireland, in order to determine risk factors for blood taken for transfusion purposes. EDTA blood samples were available from 137 non-pedigree cats and 39 pedigree cats (91 females and 85 males, aged four months to 15.0 years) in the Dublin area of Ireland. Of the 176 EDTA blood samples obtained, 112 (from 92 healthy cats and 20 sick cats) were tested for the presence of both FIV antibodies and FeLV antigens. Blood typing was performed using an immunochromatographic cartridge (CHROM; Alvedia). Testing for FIV and FeLV was performed by ELISA (SNAP FIV/FeLV Combo Test; Idexx Laboratories). Of the 39 pedigree cats, the majority (38 [97.4 per cent]) was type A, and only one (2.6 per cent) was type B. Of the 137 non-pedigree cats, the majority (116 [84.7 per cent]) was type A, 20 (14.6 per cent) were type B, and one (0.7 per cent) was type AB. Of the 92 healthy cats tested, the prevalence of FIV and FeLV positivity was 4.35 and 1.09 per cent, respectively. None of the 20 sick cats tested was FIV-positive; two (10 per cent) of the 20 sick cats were FeLV-positive.", "journal": "The Veterinary record", "doi": "10.1136/vr.c6879", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21490095", "author": "Dietrich I", "n_authors": 9, "title": "Feline tetherin efficiently restricts release of feline immunodeficiency virus but not spreading of infection.", "abstract": "Domestic cats endure infections by all three subfamilies of the retroviridae: lentiviruses (feline immunodeficiency virus [FIV]), gammaretroviruses (feline leukemia virus [FeLV]), and spumaretroviruses (feline foamy virus [FFV]). Thus, cats present an insight into the evolution of the host-retrovirus relationship and the development of intrinsic/innate immune mechanisms. Tetherin (BST-2) is an interferon-inducible transmembrane protein that inhibits the release of enveloped viruses from infected cells. Here, we characterize the feline homologue of tetherin and assess its effects on the replication of FIV. Tetherin was expressed in many feline cell lines, and expression was induced by interferons, including alpha interferon (IFN-α), IFN-ω, and IFN-γ. Like human tetherin, feline tetherin displayed potent inhibition of FIV and HIV-1 particle release; however, this activity resisted antagonism by either HIV-1 Vpu or the FIV Env and \"OrfA\" proteins. Further, as overexpression of complete FIV genomes in trans could not overcome feline tetherin, these data suggest that FIV lacks a functional tetherin antagonist. However, when expressed stably in feline cell lines, tetherin did not abrogate the replication of FIV; indeed, syncytium formation was significantly enhanced in tetherin-expressing cells infected with cell culture-adapted (CD134-independent) strains of FIV (FIV Fca-F14 and FIV Pco-CoLV). Thus, while tetherin may prevent the release of nascent viral particles, cell-to-cell spread remains efficient in the presence of abundant viral receptors and tetherin upregulation may enhance syncytium formation. Accordingly, tetherin expression in vivo may promote the selective expansion of viral variants capable of more efficient cell-to-cell spread.", "journal": "Journal of virology", "doi": "10.1128/JVI.00071-11", "deposited_data": "Sim", "nuccore_ids": "340545528, 1519313265, 340545528", "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21479142", "author": "Greggs WM 3rd", "n_authors": 4, "title": "Broadening the use of antiretroviral therapy: the case for feline leukemia virus.", "abstract": "Antiretroviral drugs have saved and extended the lives of millions of individuals infected with HIV. The major classes of anti-HIV drugs include reverse transcriptase inhibitors, protease inhibitors, integrase inhibitors, and entry/fusion inhibitors. While antiretroviral drug regimens are not commonly used to treat other types of retroviral infections, there are instances where there is a perceived need for re-evaluation of the benefits of antiretroviral therapy. One case in point is that of feline leukemia virus (FeLV), an infection of companion felines. While vaccines exist to prevent FeLV infection and spread, they have not eliminated FeLV infection. For FeLV-infected felines and their human companions, antiretroviral therapy would be desirable and of practical importance if good options were available. Here, we discuss FeLV biology and current treatment options, and propose that there is a need for antiretroviral treatment options for FeLV infection. The comparative use and analysis of antiretroviral therapy can provide new insights into the mechanism of antiretroviral drug action.", "journal": "Therapeutics and clinical risk management", "doi": "10.2147/TCRM.S17731", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21302124", "author": "Geret CP", "n_authors": 11, "title": "Feline leukemia virus outbreak in the critically endangered Iberian lynx (Lynx pardinus): high-throughput sequencing of envelope variable region A and experimental transmission.", "abstract": "The Iberian lynx is the most endangered felid species. During winter/spring 2006/7, a feline leukemia virus (FeLV) outbreak of unexpected virulence killed about 2/3 of the infected Iberian lynxes. All FeLV-positive animals were co-infected with feline hemoplasmas. To further characterize the Iberian lynx FeLV strain and evaluate its potential virulence, the FeLV envelope gene variable region A (VRA) mutant spectrum was analyzed using the Roche 454 sequencing technology, and an in vivo transmission study of lynx blood to specified-pathogen-free cats was performed. VRA mutations indicated weak apolipoprotein B mRNA editing enzyme and catalytic polypeptide-like cytidine deaminase (APOBEC) restriction of FeLV replication, and variants characteristic of aggressive FeLV strains, such as FeLV-C or FeLV-A/61C, were not detected. Cats exposed to FeLV/Candidatus Mycoplasma haemominutum-positive lynx blood did not show a particularly severe outcome of infection. The results underscore the special susceptibility of Iberian lynxes to infectious diseases.", "journal": "Archives of virology", "doi": "10.1007/s00705-011-0925-z", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21281194", "author": "Seth M", "n_authors": 3, "title": "Comparison of five blood-typing methods for the feline AB blood group system.", "abstract": "Objective-To compare the ease of use and accuracy of 5 feline AB blood-typing methods: card agglutination (CARD), immunochromatographic cartridge (CHROM), gel-based (GEL), and conventional slide (SLIDE) and tube (TUBE) agglutination assays. Sample Population-490 anticoagulated blood samples from sick and healthy cats submitted to the Transfusion or Clinical Laboratory at the Veterinary Hospital of the University of Pennsylvania. Procedures-Sample selection was purposely biased toward those from anemic, type B, or type AB cats or those with autoagglutination. All blood samples were tested by use of GEL, SLIDE, and TUBE methods. Fifty-eight samples were also tested by use of CARD and CHROM methods. The presence of alloantibodies in all cats expressing the B antigen as detected by use of any method was also assessed. Results-Compared with the historical gold-standard TUBE method, good to excellent agreement was achieved with the other typing tests: CARD, 53 of 58 (91% agreement); CHROM, 55 of 58 (95%); GEL, 487 of 490 (99%); and SLIDE, 482 of 487 (99%; 3 samples were excluded because of autoagglutination). Four of the samples with discordant test results originated from cats with FeLV-related anemia. Conclusions and Clinical Relevance-Current laboratory and in-clinic methods provide simple and accurate typing for the feline AB blood group system with few discrepancies. Retyping after in-clinic typing with the GEL or TUBE laboratory methods is recommended to confirm any type B or AB cats.", "journal": "American journal of veterinary research", "doi": "10.2460/ajvr.72.2.203", "deposited_data": "Sim", "nuccore_ids": "350529346, 2130962678, 2130962676, 2130962675, 2130962673, 2130962671, 2130962669, 2130962667, 2130962664, 350529346", "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21272942", "author": "Mochizuki H", "n_authors": 13, "title": "Establishment of a novel feline leukemia virus (FeLV)-negative B-cell cell line from a cat with B-cell lymphoma.", "abstract": "We established a novel feline B-cell line, MS4, from the neoplastic pleural effusion of a cat with cutaneous B-cell lymphoma. Immunophenotype staining of the MS4 cells was positive for CD20, CD79α, and IgA and negative for CD3, CD4, CD5, CD8α, CD18, CD21, CD22, IgM, IgG, Ig light chain, and MHC class II. PCR analysis for immunoglobulin heavy chain gene rearrangements revealed a monoclonal rearrangement, whereas no clonal rearrangement of the T-cell receptor γ gene was detected. Southern blotting with an exogenous feline leukemia virus (FeLV) U3 probe revealed no integration of exogenous FeLV provirus. The MS4 cell line is the first FeLV-negative feline B-cell lymphoma cell line, and may be used to investigate the pathogenesis of spontaneously occurring feline lymphoma and the development of new therapies.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2010.12.010", "deposited_data": "Sim", "nuccore_ids": "312063865", "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21266839", "author": "Denner J", "n_authors": 1, "title": "Towards an AIDS vaccine: the transmembrane envelope protein as target for broadly neutralizing antibodies.", "abstract": "Although the development of an effective vaccine is the main goal in the fight against AIDS, all attempts by numerous laboratories to develop a vaccine have failed so far. In addition, it is still unclear whether cytotoxic T cells or neutralizing antibodies or both should be induced. The major advantage of neutralizing antibodies is their ability to prevent infection and subsequent integration of the provirus into the cellular genome where it may persist in a form invisible to the immune system. Broadly neutralizing antibodies have been found in HIV infected individuals, including antibodies directed against a highly conserved region in the membrane proximal external region (MPER) of the transmembrane envelope (TM) protein gp41 of HIV-1. We successfully induced neutralizing antibodies against different gammaretroviruses by immunization with their respective TM proteins. These antibodies recognized epitopes not only in the MPER but also in the fusion peptide proximal region of the TM protein. In the case of feline leukaemia virus (FeLV), these antibodies protected cats from antigenemia following challenge. To understand the mechanism of neutralization, the interactions between neutralizing antibodies and their corresponding epitopes in the TM protein of gammaretroviruses and HIV-1 were analysed. These data may help to design antigens able to induce specific broadly neutralizing antibodies.", "journal": "Human vaccines", "doi": "10.4161/hv.7.0.14555", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21217037", "author": "Spycher A", "n_authors": 10, "title": "Isolation and genotyping of Toxoplasma gondii causing fatal systemic toxoplasmosis in an immunocompetent 10-year-old cat.", "abstract": "A 10-year-old male, neutered domestic shorthair cat was presented with fever, anorexia, vomiting, and diarrhea. Serologic testing for Feline immunodeficiency virus and Feline leukemia virus were negative. Fine-needle aspirates of mesenteric lymph nodes revealed the presence of banana-shaped apicomplexan parasites. The cat died after 4 days of hospitalization. Postmortem polymerase chain reaction (PCR) analysis confirmed the presence of Toxoplasma gondii in all examined organs. Parasites were ex vivo isolated in outbred mice and subsequently transferred into cell culture. Genotyping, using genetic markers for SAG2, SAG3, BTUB, GRA6, c22-8, c29-2, L358, PK1, and Apico for PCR-restriction fragment length polymorphism, revealed infection with type II T. gondii displaying type II alleles at all loci except Apico, which exhibited a type I allele. This is the most frequently identified genotype among cats acting as definitive hosts in central Europe, but to the authors' knowledge, it has never been associated with systemic toxoplasmosis in an adult, immunocompetent cat.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/104063871102300117", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21131219", "author": "Stützer B", "n_authors": 8, "title": "Incidence of persistent viraemia and latent feline leukaemia virus infection in cats with lymphoma.", "abstract": "In the past, feline leukaemia virus (FeLV) infection, and also latent FeLV infection, were commonly associated with lymphoma and leukaemia. In this study, the prevalence of FeLV provirus in tumour tissue and bone marrow in FeLV antigen-negative cats with these tumours was assessed. Seventy-seven diseased cats were surveyed (61 antigen-negative, 16 antigen-positive). Blood, bone marrow, and tumour samples were investigated by two polymerase chain reaction (PCR) assays detecting deoxyribonucleic acid (DNA) sequences of the long terminal repeats (LTR) and the envelope (env) region of the FeLV genome. Immunohistochemistry (IHC) was performed in bone marrow and tumour tissue. None of the antigen-negative cats with lymphoma was detectably infected with latent FeLV. The prevalence of FeLV viraemia in cats with lymphoma was 20.8%. This suggests that causes other than FeLV play a role in tumorigenesis, and that latent FeLV infection is unlikely to be responsible for most feline lymphomas and leukaemias.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2010.09.015", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21108970", "author": "Langhammer S", "n_authors": 5, "title": "Immunization with the transmembrane protein of a retrovirus, feline leukemia virus: absence of antigenemia following challenge.", "abstract": "A major challenge in the development of vaccines against retroviruses is the induction of neutralizing antibodies since they prevent infection of the cells where the virus may persist. The transmembrane envelope (TM) protein contains highly conserved domains and seems to be a suitable target. To study whether vaccinating with a TM protein of a retrovirus could protect from infection in vivo, cats were immunized with the TM protein p15E of feline leukemia virus (FeLV) and subsequently challenged. For the first time we show that immunization with a retroviral TM protein prevented antigenemia. The level of neutralizing antibodies after the boost immunization correlated with the outcome of FeLV infection.", "journal": "Antiviral research", "doi": "10.1016/j.antiviral.2010.11.011", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "20829603", "author": "Langhammer S", "n_authors": 4, "title": "Increased neutralizing antibody response after simultaneous immunization with leucogen and the feline leukemia virus transmembrane protein.", "abstract": "To develop improved vaccination strategies against feline leukemia virus (FeLV), rats were immunized with the transmembrane envelope protein p15E of FeLV alone or in combination with the commercial vaccine Leucogen® comprising the nonglycosylated FeLV surface envelope protein. Binding and neutralizing antibodies were induced in both groups and in the group immunized with Leucogen alone. Higher titers of antibodies neutralizing FeLV were induced by simultaneous immunization with Leucogen and p15E compared to the responses using Leucogen or p15E alone, suggesting that combination vaccines should be used in the future. Epitope mapping of p15E-specific antibodies induced by simultaneous immunization with Leucogen and p15E revealed the same pattern of response as obtained after immunization with p15E alone: one epitope was localized in the membrane-proximal external region (MPER) and the other in the fusion peptide-proximal region, and they are related to the epitopes detected after immunization with p15E of the porcine endogenous retrovirus and the koala retrovirus. The data indicate that these epitopes in the MPER are an effective target for neutralization and that antigens containing them may therefore prove to be a useful component of vaccines against retroviruses, including HIV-1.", "journal": "Intervirology", "doi": "10.1159/000318892", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "20804432", "author": "Sherry K", "n_authors": 9, "title": "A serological and molecular study of Leishmania infantum infection in cats from the Island of Ibiza (Spain).", "abstract": "The aim of this study was to evaluate the prevalence of Leishmania infantum infection within a feline population by serologic and molecular methods and to identify associated risk factors. One hundred five cats living outdoors were studied. Sera were tested for IgG antibodies against L. infantum, Toxoplasma gondii, and feline immunodeficiency virus (FIV) and for the detection of feline leukemia virus (FeLV) p27 antigen by enzyme-linked immunosorbent assay (ELISA). L. infantum real-time polymerase chain reaction (PCR) was performed on DNA extracted from blood. L. infantum and T. gondii seroprevalence rates were 13.2% and 55.2%, respectively. The prevalence of L. infantum by PCR was 8.7%. The total rate of L. infantum infection derived from seroreactivity and/or positive PCR was 15.4%. Serology and PCR results were positively associated, and moderate agreement (kappa = 0.489) was found between Leishmania ELISA and PCR. No statistical association was found between positive Leishmania PCR results and gender, clinical status, or T. gondii seropositivity. Six of the 105 cats (5.7%) displayed clinical signs compatible with feline cutaneous leishmaniosis, and 4 out of these 6 cats (66.7%) were found to have Leishmania infection by means of serology and/or PCR. Leishmania seropositivity was associated with clinical signs of feline cutaneous leishmaniosis (p = 0.029). The prevalence of FeLV p27 antigen was 16.2% (17/105) and of FIV antibody was 20.9% (22/105), with coinfection found in 9.5% (10/105) of the cats. Leishmania ELISA seroreactivity and positive PCR results were statistically associated with FeLV infection and with coinfection of both retroviruses but not with a positive FIV status. The high seroprevalence and molecular rates of Leishmania infection observed indicate that cats are frequently infected with L. infantum, and the association with FeLV suggests a potential role for this retrovirus in feline Leishmania infection in endemic areas.", "journal": "Vector borne and zoonotic diseases (Larchmont, N.Y.)", "doi": "10.1089/vbz.2009.0251", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "20510635", "author": "Martano M", "n_authors": 3, "title": "Feline injection-site sarcoma: past, present and future perspectives.", "abstract": "Feline injection-site sarcomas (FISS) have been known since the early 1990s. After an initial correlation with rabies and feline leukaemia virus vaccination, subsequent studies have demonstrated that an abnormal reaction of feline tissues to chronic inflammation was mainly responsible for the disease. The low incidence of FISS in the population is explained by its multifactorial aetiology, since individual genetic characteristics are also implicated. FISS is an infiltrative tumour with low metastatic potential but local recurrence is common. Multimodal treatment (extensive surgery, radiotherapy, chemotherapy) is recommended. The use of sophisticated imaging techniques can improve diagnosis and help in surgical planning. After the initial enthusiasm in understanding the disease, only few advances have been made in the last few years. New promising therapies may arise from a better knowledge of the molecular pathogenesis of FISS and the successful development of drugs modulating the immune system.", "journal": "Veterinary journal (London, England : 1997)", "doi": "10.1016/j.tvjl.2010.04.025", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22958254", "author": "Jiménez-Coello M", "n_authors": 5, "title": "Epidemiological survey of Trypanosoma cruzi infection in domestic owned cats from the tropical southeast of Mexico.", "abstract": "American trypanosomiasis is an infectious disease of importance for public health and caused by the protozoa Trypanosoma cruzi mainly transmitted by triatomine bugs. The precise role of cats in the peridomestic transmission of T. cruzi and the mechanism by which cats become infected remain uncertain. The objective of this work was to determine the prevalence of T. cruzi infection in domestic cats from an urban area of tropical Mexico by serological and molecular methods and evaluate associated risk factors. A total of 220 domestic cats from Merida Yucatan, Mexico, were studied. Animals older than 3 months were blood sampled. Serum and DNA were obtained. Specific T. cruzi IgG antibodies were detected using a commercial indirect ELISA with an anti-cat antibody HRP labelled. Positive cases were confirmed by Western blot (WB). Polymerase chain reaction (PCR) was also performed using the primers TC1 and TC2. From the 220 cats, 8.6% had antibodies against T. cruzi using ELISA test and later confirmed by WB. In 75 cats (34%), the sequence of ADNk of T. cruzi was amplified. The bad-regular body condition was the only risk factor associated with PCR positive to T.cruzi (P < 0.001). In Mexico, there are no previous epidemiological reports that demonstrate the importance of the cat as a reservoir of T. cruzi. Few individuals were identified with a serological response because they were probably at an early stage of infection or antibodies were not detected because they could be immunocompromised (FIV, FeLV or others). It is necessary to monitor PCR-positive patients and conduct further studies for better understanding of the epidemiology and pathogenesis of Chagas disease in domestic cats.", "journal": "Zoonoses and public health", "doi": "10.1111/j.1863-2378.2012.01463.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "23327142", "author": "Rosa C", "n_authors": 2, "title": "Extraskeletal osteochondroma on a cat´s elbow.", "abstract": "A solitary extraskeletal osteochondroma was diagnosed in a 6-year-old, castrated male Burmese cat, positive for feline leukaemia virus (FeLV). The cat presented with a rapidly growing, solid, non-painful mass on the craniolateral aspect of the left elbow. Radiographs revealed an oval, well circumscribed 2.0 cm × 1.5 cm × 1.5 cm mineralised mass separated from the underlying bone. Surgical excisional biopsy confirmed the diagnosis. Feline extraskeletal osteochondromas are benign tumours frequently seen in FeLV-positive cats which can transform into osteosarcomas or chondrosarcomas. Radiographically, they cannot be distinguished from a parosteal or an extraskeletal osteosarcoma.", "journal": "Journal of the South African Veterinary Association", "doi": "10.4102/jsava.v83i1.104", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "23202500", "author": "Hartmann K", "n_authors": 1, "title": "Clinical aspects of feline retroviruses: a review.", "abstract": "Feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) are retroviruses with global impact on the health of domestic cats. The two viruses differ in their potential to cause disease. FeLV is more pathogenic, and was long considered to be responsible for more clinical syndromes than any other agent in cats. FeLV can cause tumors (mainly lymphoma), bone marrow suppression syndromes (mainly anemia), and lead to secondary infectious diseases caused by suppressive effects of the virus on bone marrow and the immune system. Today, FeLV is less commonly diagnosed than in the previous 20 years; prevalence has been decreasing in most countries. However, FeLV importance may be underestimated as it has been shown that regressively infected cats (that are negative in routinely used FeLV tests) also can develop clinical signs. FIV can cause an acquired immunodeficiency syndrome that increases the risk of opportunistic infections, neurological diseases, and tumors. In most naturally infected cats, however, FIV itself does not cause severe clinical signs, and FIV-infected cats may live many years without any health problems. This article provides a review of clinical syndromes in progressively and regressively FeLV-infected cats as well as in FIV-infected cats.", "journal": "Viruses", "doi": "10.3390/v4112684", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "23187133", "author": "Fleming MD", "n_authors": 2, "title": "Mitochondrial heme: an exit strategy at last.", "abstract": "The transport of heme across membranes is critical for iron absorption, the formation of hemoglobin and other hemoproteins, and iron recycling in macrophages. However, the identity of heme transport proteins has been elusive. In this issue of the JCI, Chiabrando et al. reveal that an isoform of the feline leukemia virus subgroup C receptor (FLVCR1) exports heme from the mitochondria and is critical for erythroid differentiation.", "journal": "The Journal of clinical investigation", "doi": "10.1172/JCI66607", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "23187127", "author": "Chiabrando D", "n_authors": 15, "title": "The mitochondrial heme exporter FLVCR1b mediates erythroid differentiation.", "abstract": "Feline leukemia virus subgroup C receptor 1 (FLVCR1) is a cell membrane heme exporter that maintains the balance between heme levels and globin synthesis in erythroid precursors. It was previously shown that Flvcr1-null mice died in utero due to a failure of erythropoiesis. Here, we identify Flvcr1b, a mitochondrial Flvcr1 isoform that promotes heme efflux into the cytoplasm. Flvcr1b overexpression promoted heme synthesis and in vitro erythroid differentiation, whereas silencing of Flvcr1b caused mitochondrial heme accumulation and termination of erythroid differentiation. Furthermore, mice lacking the plasma membrane isoform (Flvcr1a) but expressing Flvcr1b had normal erythropoiesis, but exhibited hemorrhages, edema, and skeletal abnormalities. Thus, FLVCR1b regulates erythropoiesis by controlling mitochondrial heme efflux, whereas FLVCR1a expression is required to prevent hemorrhages and edema. The aberrant expression of Flvcr1 isoforms may play a role in the pathogenesis of disorders characterized by an imbalance between heme and globin synthesis.", "journal": "The Journal of clinical investigation", "doi": "10.1172/JCI62422", "deposited_data": "Sim", "nuccore_ids": "2666210344, 924181778, 924181484, 124486924, 3382334014, 3382246094, 2972057995, 2972057928, 2972057901, 2972057847, 2666210344, 2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556, 924181778, 924181484, 195947362, 124486924", "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "23070430", "author": "de Bortoli CP", "n_authors": 6, "title": "Detection of hemoplasma and Bartonella species and co-infection with retroviruses in cats subjected to a spaying/neutering program in Jaboticabal, SP, Brazil.", "abstract": "Hemotrophic mycoplasmas and Bartonella species are important pathogens that circulate between cats and invertebrate hosts, occasionally causing diseases in humans. Nevertheless, there are few reports on occurrences of these agents in cats in Brazil. The present study aimed to detect the presence of hemoplasma and Bartonella DNA by means of PCR and sequencing. FIV antigens and anti-FeLV antibodies, were studied by using a commercial kit on blood and serum samples, respectively, among 46 cats that were sampled during a spaying/neutering campaign conducted in Jaboticabal, SP. Three (6.5%) cats were positive for hemoplasmas: two (4.3%) for 'Candidatus M. haemominutum' and one (2.2%) for both M. haemofelis and 'Candidatus M. turicensis'. One of the two 'Candidatus M. haemominutum'-infected cats was also positive for FeLV antigens and showed antibodies for FIV. Two cats (4.3%) were positive for B. henselae. One of them was also positive for FeLV antigens. Eight cats (17.4%) were positive for FeLV, and just one (2.2%) showed anti-FIV antibodies. Bartonella species and hemoplasmas associated with infection due to retroviruses can circulate among apparently healthy cats.", "journal": "Revista brasileira de parasitologia veterinaria = Brazilian journal of veterinary parasitology : Orgao Oficial do Colegio Brasileiro de Parasitologia Veterinaria", "doi": "10.1590/s1984-29612012000300008", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "23060491", "author": "Uhart MM", "n_authors": 5, "title": "Exposure to selected Pathogens in to selected pathogens in Geoffroy's cats and domestic carnivores from central Argentina.", "abstract": "Wild carnivores share a high percentage of parasites and viruses with closely related domestic carnivores. Because of increased overlap and potential contact with domestic species, we conducted a retrospective serosurvey for 11 common carnivore pathogens in 40 Geoffroy's cats (Leopardus geoffroyi) sampled between 2000 and 2008 within or near two protected areas in central Argentina (Lihué Calel National Park, La Pampa, and Campos del Tuyú National Park, Buenos Aires), as well as five domestic cats and 11 domestic dogs from catde ranches adjacent to Lihué Calel Park. Geoffroy's cats had detectable antibody to canine distemper virus (CDV), feline calicivirus (FCV), feline coronavirus, feline panleukopenia virus (FPV), Toxoplasma gondii, Leptospira interrogans (serovars Ictero/Icter and Ballum), and Dirofilaria immitis. None of the wild cats had antibodies to feline herpesvirus, feline immunodeficiency virus (FIV), feline leukemia virus, or rabies virus. Domestic dogs had antibodies to CDV, canine adenovirus, canine herpesvirus, and canine parvovirus. Antibodies to FPV, FCV, FIV, and T. gondii were found in domestic cats. We provide the first data on exposure of free-ranging Geoffroy's cats to pathogens at two sites within the core area of the species distribution range, including the first report of antibodies to CDV in this species. We encourage continued monitoring for diseases in wild and domestic carnivores as well as preventive health care for domestic animals, particularly in park buffer zones where overlap is greatest.", "journal": "Journal of wildlife diseases", "doi": "10.7589/2011-05-137", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22964430", "author": "Mandrioli L", "n_authors": 5, "title": "A case of feline neurolymphomatosis: pathological and molecular investigations.", "abstract": "Neurolymphomatosis is a very rare form of nervous system infiltration by lymphoma that can affect cranial and peripheral nerves and spinal nerve roots. The clinical appearance can mimic autoimmune or paraneoplastic neuropathies. To date, only 2 cases of neurolymphomatosis have been reported in the veterinary literature (1 dog and 1 cat). A case of neurolymphomatosis in a 5-year-old female Domestic Shorthair cat is reported. Two, whitish, bosselated, non-symmetric masses (1 cm × 1.2 cm × 0.5 cm) that incorporated almost all cranial nerves and semilunar ganglia occupying the basisphenoid depression were histologically composed of a proliferation of monomorphic lymphocytes. These lymphoid cells were positive for CD3 (T-cell lymphoma). Nested polymerase chain reaction detected feline leukemia provirus. Fragment analysis of feline T-cell receptor (TCR) gene rearrangements evidenced an oligoclonal pattern with few peaks of similar height. The integration of pathologic with biomolecular findings adds to the information concerning the role of Feline leukemia virus on TCRγ rearrangements in cases of feline lymphoma.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/1040638712460674", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "32327861", "author": "Nicholson KL", "n_authors": 3, "title": "Serosurvey of mountain lions in southern Arizona.", "abstract": "An understanding of the prevalence of diseases in free-ranging populations of felids is limited, and there is even less known about the overall health and diseases of wild felids that inhabit or utilize urban areas. We collected serum samples from 9 radiocollared mountain lions (", "journal": "Wildlife Society bulletin", "doi": "10.1002/wsb.155", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22915682", "author": "Meichner K", "n_authors": 4, "title": "Changes in prevalence of progressive feline leukaemia virus infection in cats with lymphoma in Germany.", "abstract": "Progressive infection with feline leukaemia virus (FeLV) is considered one of the major risk factors for development of feline lymphoma. The aim of this study was to compare cats with lymphoma between 1980 and 1994 (first period) and between 1995 and 2009 (second period) concerning FeLV antigenaemia and age distribution. In addition, differences between FeLV antigen-positive and antigen-negative cats with lymphoma regarding patients' characteristics, tumour location and outcome were evaluated. There was a significant decrease in the percentage of lymphoma cases associated with progressive FeLV infection from the first (59 per cent) to the second (13 per cent) observation period. FeLV antigen-positive cats were significantly younger (median 3.7 v 11.3 years), and had significantly shorter response duration (median 25 days v 472 days) with therapy. In the cats of the second period, gastrointestinal and extranodal lymphomas were the most common anatomical sites, and the majority of those cats were FeLV antigen-negative. Thus, other aetiologies than progressive FeLV infection must have a greater impact on cancerogenesis among affected cats with lymphoma to date.", "journal": "The Veterinary record", "doi": "10.1136/vr.100813", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22839692", "author": "Wilson S", "n_authors": 9, "title": "Difficulties in demonstrating long term immunity in FeLV vaccinated cats due to increasing age-related resistance to infection.", "abstract": "Feline leukaemia virus (FeLV) is a pathogen causing fatal illness in cats worldwide, and as such there is a high demand for products to protect against disease. The duration of immunity provided by an inactivated FeLV vaccine, Versifel FeLV, when administered to cats of the target age was determined. Kittens received two vaccinations when aged 7 to 9 weeks old, and were subsequently challenged up to 36 months later with the FeLV-A Glasgow isolate. In all studies, all of the younger aged control kittens showed persistent FeLV p27 antigenaemia confirming that the challenge virus was severe and efficacious. In contrast, the control cats did not show the required level of persistent antigenaemia, with a maximum of 45% cats affected in the middle duration study and only 10% in the longer study. However, apart from one animal in the short duration study, all of the cats vaccinated with Versifel FeLV were negative for persistent antigenaemia and can be considered treatment successes. In conclusion, we have shown that although age-related resistance to infection with a virulent FeLV challenge is evident from as early as 10 months of age, vaccination with Versifel FeLV may aid in the protection of cats from FeLV related disease up to three years after primary vaccination as kittens.", "journal": "BMC veterinary research", "doi": "10.1186/1746-6148-8-125", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22805872", "author": "Sharma V", "n_authors": 7, "title": "A novel population of α-smooth muscle actin-positive cells activated in a rat model of stroke: an analysis of the spatio-temporal distribution in response to ischemia.", "abstract": "In a rat model of stroke, the spatio-temporal distribution of α-smooth muscle actin-positive, (αSMA+) cells was investigated in the infarcted hemisphere (ipsilateral) and compared with the contralateral hemisphere. At day 3 postischemia, αSMA+ cells were concentrated in two main loci within the ipsilateral hemisphere (Area A) in the medial corpus callosum and (Area B) midway through the striatum adjacent to the lateral ventricle. By day 7 and further by day 14, fewer αSMA+ cells remained in Areas A and B but a steady increase in the peri-infarct was observed. αSMA+ cells also expressed glial acidic fibrillary protein [GFAP: αSMA+/GFAP+ (29%); αSMA+/GFAP- (71%) phenotypes] and feline leukemia virus C receptor 2 (FLVCR2), but not ED1(microglia) and established markers of pericytes normally located in vascular wall. αSMA+ cells were also located close to the subventricular zones (SVZ) adjacent to Areas A and B. In conclusion, αSMA+ cells have been identified in a spatial and temporal sequence from the SVZ, at intermediate loci and in the vicinity of the peri-infarct. It is hypothesized that novel populations of αSMA+ precursors of pericytes are born on the SVZ, migrate into the peri-infarct region and are incorporated into new vessels of the peri-infarct regions.", "journal": "Journal of cerebral blood flow and metabolism : official journal of the International Society of Cerebral Blood Flow and Metabolism", "doi": "10.1038/jcbfm.2012.107", "deposited_data": "Sim", "nuccore_ids": "148298812", "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22779227", "author": "Risi E", "n_authors": 6, "title": "Antibody response to vaccines for rhinotracheitis, caliciviral disease, panleukopenia, feline leukemia, and rabies in tigers (Panthera tigris) and lions (Panthera leo).", "abstract": "This article presents the results of a study of captive tigers (Panthera tigris) and lions (Panthera leo) vaccinated with a recombinant vaccine against feline leukemia virus; an inactivated adjuvanted vaccine against rabies virus; and a multivalent modified live vaccine against feline herpesvirus, calicivirus, and panleukopenia virus. The aim of the study was to assess the immune response and safety of the vaccines and to compare the effects of the administration of single (1 ml) and double (2 ml) doses. The animals were separated into two groups and received either single or double doses of vaccines, followed by blood collection for serologic response for 400 days. No serious adverse event was observed, with the exception of abortion in one lioness, potentially caused by the incorrect use of the feline panleukopenia virus modified live vaccine. There was no significant difference between single and double doses for all vaccines. The recombinant vaccine against feline leukemia virus did not induce any serologic response. The vaccines against rabies and feline herpesvirus induced a significant immune response in the tigers and lions. The vaccine against calicivirus did not induce a significant increase in antibody titers in either tigers or lions. The vaccine against feline panleukopenia virus induced a significant immune response in tigers but not in lions. This report demonstrates the value of antibody titer determination after vaccination of nondomestic felids.", "journal": "Journal of zoo and wildlife medicine : official publication of the American Association of Zoo Veterinarians", "doi": "10.1638/2010-0166.1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22674983", "author": "Anai Y", "n_authors": 7, "title": "Infectious endogenous retroviruses in cats and emergence of recombinant viruses.", "abstract": "Endogenous retroviruses (ERVs) comprise a significant percentage of the mammalian genome, and it is poorly understood whether they will remain as inactive genomes or emerge as infectious retroviruses. Although several types of ERVs are present in domestic cats, infectious ERVs have not been demonstrated. Here, we report a previously uncharacterized class of endogenous gammaretroviruses, termed ERV-DCs, that is present and hereditary in the domestic cat genome. We have characterized a subset of ERV-DC proviral clones, which are numbered according to their genomic insertions. One of these, ERV-DC10, located in the q12-q21 region on chromosome C1, is an infectious gammaretrovirus capable of infecting a broad range of cells, including human. Our studies indicate that ERV-DC10 entered the genome of domestic cats in the recent past and appeared to translocate to or reintegrate at a distinct locus as infectious ERV-DC18. Insertional polymorphism analysis revealed that 92 of 244 domestic cats had ERV-DC10 on a homozygous or heterozygous locus. ERV-DC-like sequences were found in primate and rodent genomes, suggesting that these ERVs, and recombinant viruses such as RD-114 and BaEV, originated from an ancestor of ERV-DC. We also found that a novel recombinant virus, feline leukemia virus subgroup D (FeLV-D), was generated by ERV-DC env transduction into feline leukemia virus in domestic cats. Our results indicate that ERV-DCs behave as donors and/or acceptors in the generation of infectious, recombinant viruses. The presence of such infectious endogenous retroviruses, which could be harmful or beneficial to the host, may affect veterinary medicine and public health.", "journal": "Journal of virology", "doi": "10.1128/JVI.00280-12", "deposited_data": "Sim", "nuccore_ids": "396077194, 396077193, 396077192, 396077191, 396077190, 396077189, 396077188, 396077186, 396077185, 396077183, 396077181, 396077179, 396077176, 396077174, 396077171, 396077168, 396077165, 396077164, 396077162, 396077161, 396077160, 396077158, 396077156, 396077154, 396077152, 396077150, 396077148, 396077146", "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22650160", "author": "Stewart H", "n_authors": 5, "title": "Identification of novel subgroup A variants with enhanced receptor binding and replicative capacity in primary isolates of anaemogenic strains of feline leukaemia virus.", "abstract": "The development of anaemia in feline leukaemia virus (FeLV)-infected cats is associated with the emergence of a novel viral subgroup, FeLV-C. FeLV-C arises from the subgroup that is transmitted, FeLV-A, through alterations in the amino acid sequence of the receptor binding domain (RBD) of the envelope glycoprotein that result in a shift in the receptor usage and the cell tropism of the virus. The factors that influence the transition from subgroup A to subgroup C remain unclear, one possibility is that a selective pressure in the host drives the acquisition of mutations in the RBD, creating A/C intermediates with enhanced abilities to interact with the FeLV-C receptor, FLVCR. In order to understand further the emergence of FeLV-C in the infected cat, we examined primary isolates of FeLV-C for evidence of FeLV-A variants that bore mutations consistent with a gradual evolution from FeLV-A to FeLV-C. Within each isolate of FeLV-C, we identified variants that were ostensibly subgroup A by nucleic acid sequence comparisons, but which bore mutations in the RBD. One such mutation, N91D, was present in multiple isolates and when engineered into a molecular clone of the prototypic FeLV-A (Glasgow-1), enhanced replication was noted in feline cells. Expression of the N91D Env on murine leukaemia virus (MLV) pseudotypes enhanced viral entry mediated by the FeLV-A receptor THTR1 while soluble FeLV-A Env bearing the N91D mutation bound more efficiently to mouse or guinea pig cells bearing the FeLV-A and -C receptors. Long-term in vitro culture of variants bearing the N91D substitution in the presence of anti-FeLV gp70 antibodies did not result in the emergence of FeLV-C variants, suggesting that additional selective pressures in the infected cat may drive the subsequent evolution from subgroup A to subgroup C. Our data support a model in which variants of FeLV-A, bearing subtle differences in the RBD of Env, may be predisposed towards enhanced replication in vivo and subsequent conversion to FeLV-C. The selection pressures in vivo that drive the emergence of FeLV-C in a proportion of infected cats remain to be established.", "journal": "Retrovirology", "doi": "10.1186/1742-4690-9-48", "deposited_data": "Sim", "nuccore_ids": "1519312754, 985567533", "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22588083", "author": "Wolf-Jäckel GA", "n_authors": 9, "title": "Quantification of the humoral immune response and hemoplasma blood and tissue loads in cats coinfected with 'Candidatus Mycoplasma haemominutum' and feline leukemia virus.", "abstract": "'Candidatus Mycoplasma haemominutum' (CMhm) is a hemotropic mycoplasma (aka hemoplasma) of domestic cats and wild felids. In a transmission study, we exposed eight specified pathogen-free cats to blood from Iberian lynxes (Lynx pardinus) infected with CMhm. The cats were coinfected with feline leukemia virus (FeLV) from an Iberian lynx or with a prototype FeLV. The goal of the present study was to quantify the humoral immune response to CMhm and to identify potential target tissues and sequestration sites. Antibodies were measured by a recombinant antigen-based enzyme-linked immunosorbent assay, and blood and tissue loads were quantified using real-time PCR. Seven out of eight cats became CMhm-infected; all of these cats seroconverted between 3 and 13 weeks after inoculation. Antibody levels correlated with the CMhm blood loads. The peak CMhm blood loads were inversely correlated with the incubation period. PCR-positive results were found in all 24 tissues tested but not for all samples. Although all tissues were PCR-positive in one cat euthanized ten weeks after infection, many tissues tested negative in six cats euthanized at week 20 after infection. In several cats, the spleen, lung, liver, heart and aorta contained more copies than expected given the tissue's blood supply, but most tissues contained fewer copies than expected. In conclusion, this is the first study to quantify the humoral immune response and tissue loads in CMhm-FeLV-coinfected cats. The tissue loads appeared to correlate with the duration of infection and with the blood loads, but no evidence of significant CMhm tissue sequestration was found.", "journal": "Microbial pathogenesis", "doi": "10.1016/j.micpath.2012.05.003", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22497870", "author": "Sukhumavasi W", "n_authors": 11, "title": "Serological survey of Toxoplasma gondii, Dirofilaria immitis, Feline Immunodeficiency Virus (FIV) and Feline Leukemia Virus (FeLV) infections in pet cats in Bangkok and vicinities, Thailand.", "abstract": "The seroprevalence of Toxoplasma gondii, Dirofilaria immitis (heartworm), feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) infections was examined using serum or plasma samples from 746 pet cats collected between May and July 2009 from clinics and hospitals located in and around Bangkok, Thailand. The samples were tested for heartworm, FIV, and FeLV using a commercial ELISA. Of the 746 samples, 4.6% (34/746) were positive for heartworm antigen, 24.5% (183/746) had circulating FeLV antigen, and 20.1% (150/746) had antibodies against FIV. In addition, the first 348 submitted samples were tested for T. gondii antibodies using a modified agglutination test (MAT, cut off 1:25); 10.1% (35/348) were seropositive. Of the 348 cats sampled for all four pathogens, 11, 10, and 1 were positive for T. gondii antibodies and FIV antibodies, FeLV antigen, or D. immitis antigen, respectively. Of the 35 T. gondii-seropositive cats, 42.9% (15/35) were co-infected with at least one of the other three pathogens. The presence of antibodies to FIV was significantly associated with both age and gender, while FeLV antigen presence was only associated with age. In the case of FIV, males were twice as likely to be infected as females, and cats over 10 years of age were 13.5 times more likely to be infected than cats less than 1 year of age. FeLV antigen was more common in younger cats, with cats over 10 years of age being 10 times less likely to be FeLV positive than cats under 1 year of age. This is the first survey for these four pathogens affecting feline health in Thailand.", "journal": "Veterinary parasitology", "doi": "10.1016/j.vetpar.2012.02.021", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22492347", "author": "de Almeida NR", "n_authors": 5, "title": "Prevalence of feline leukemia virus infection in domestic cats in Rio de Janeiro.", "abstract": "Peripheral blood smears of 1094 domestic cats were collected and tested by indirect immunofluorescence antibody assay for p27 antigen in cells to study the prevalence and risk factors for feline leukemia virus (FeLV) in the state of Rio de Janeiro. Sex, age, breed, outdoor access, neutering status, type of habitation (household, shelter, veterinary clinics and other places), number of household cats and clinical signs were registered on a form. Among the tested samples, 11.52% were positive. Risk factors for FeLV infection included outdoor access, age range between 1 and 5 years old, and cohabitation with numerous cats.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X12444693", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22483575", "author": "Yanatori I", "n_authors": 4, "title": "Mutations of FLVCR1 in posterior column ataxia and retinitis pigmentosa result in the loss of heme export activity.", "abstract": "The feline leukemia virus subgroup C receptor 1 (FLVCR1) is a heme exporter that maintains the intracellular heme concentration. FLVCR1 was previously assumed to be involved in Diamond-Blackfan anemia, and it was recently reported that mutations in the FLVCR1 gene are found in patients with posterior column ataxia and retinitis pigmentosa (PCARP). Four mutations in FLVCR1 (Asn121Asp, Cys192Arg, Ala241Thr, and Gly493Arg) are located within putative transmembrane domains; however, the effects of FLVCR1 mutations on PCARP are unclear. In this study, we analyzed the function of FLVCR1 mutants by using a fluorescent heme analog as a transporter substrate, and found that all 4 FLVCR1 mutants lost their heme export activity. To investigate the mechanism responsible for this loss of activity, we determined the subcellular localization of FLVCR1 mutants. FLVCR1 mutants did not localize to the plasma membrane and were observed in intracellular structures, including lysosomes. We hypothesize that the loss of function of FLVCR1 mutants is caused by their mislocation. We examined the half-life of FLVCR1 in cells, which was >16h for wild-type FLVCR1 compared with 2-4h for the mutants. Based on these results, we propose that FLVCR1 mutants failed to fold properly in the ER, were rapidly degraded in the lysosomes, and therefore, could not export heme out of cells. Thus, accumulation of heme in FLVCR1-mutant cells could cause cellular toxicity.", "journal": "Blood cells, molecules & diseases", "doi": "10.1016/j.bcmd.2012.03.004", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22477652", "author": "Hässig M", "n_authors": 4, "title": "[The influence of colostral antibodies on the postvaccination humoral immune response in neonatal calves].", "abstract": "The aim of this study was to evaluate the efficiency of vaccination of young calves and to see whether maternal antibodies may influence the immunological response in calves. For this project 20 matched-pairs of cows and their offspring were selected. Of each pair, one cow received a placebo 8 and 4 weeks before term (group A) and the other was vaccinated against Feline Leucose Virus, FeLV, with Leucogen® (group B). All calves received colostrum from their respective mother shortly after birth and all calves were vaccinated with Leucogen® 10 days after birth. Blood samples from the cows and calves were taken during the whole study period (till four weeks after calf vaccination). An ELISA test was done in the lab to define the FeLV antibody concentration. 30 % of the vaccinated cows showed a seroconversion, 13 out of 20 vaccinated cows passed the antibodies onto their calves. 11 calves of group B did not convert in comparation of only 4 of group A. All seroconverted calves had low antibody concentration before their vaccination. Calves of group B with a low passive antibody level at the beginning showed a higher seroconversion as compared to calves with higher antibody concentrations of the same group. Two thirds of the calves without maternal antibodies reacted adequately to the vaccination. Therefore, an early vaccination of calves can be recommended.", "journal": "Schweizer Archiv fur Tierheilkunde", "doi": "10.1024/0036-7281/a000317", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22470834", "author": "O'Brien SJ", "n_authors": 7, "title": "Emerging viruses in the Felidae: shifting paradigms.", "abstract": "The domestic cat is afflicted with multiple viruses that serve as powerful models for human disease including cancers, SARS and HIV/AIDS. Cat viruses that cause these diseases have been studied for decades revealing detailed insight concerning transmission, virulence, origins and pathogenesis. Here we review recent genetic advances that have questioned traditional wisdom regarding the origins of virulent Feline infectious peritonitis (FIP) diseases, the pathogenic potential of Feline Immunodeficiency Virus (FIV) in wild non-domestic Felidae species, and the restriction of Feline Leukemia Virus (FeLV) mediated immune impairment to domestic cats rather than other Felidae species. The most recent interpretations indicate important new evolutionary conclusions implicating these deadly infectious agents in domestic and non-domestic felids.", "journal": "Viruses", "doi": "10.3390/v4020236", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22439903", "author": "Bande F", "n_authors": 7, "title": "Prevalence and risk factors of feline leukaemia virus and feline immunodeficiency virus in peninsular Malaysia.", "abstract": "Feline leukaemia virus (FeLV) and feline immunodeficiency virus (FIV) are major causes of morbidity and mortality in domestic and wild felids. Despite the clinical importance of feline retroviruses and the growing interest in cats as pets, information about FeLV and FIV in Malaysia is presently insufficient to properly advise veterinarians and pet owners. A cross-sectional study was carried out from January 2010 to December 2010 to determine the prevalence and risk factors associated with FeLV and FIV among domestic cats in peninsular Malaysia. Plasma samples were harvested from the blood of 368 domestic cats and screened for evidence of FeLV p27 antigen and FIV antibodies, using an immunochromatographic kit. Additionally, data on cat demographics and health were collected using a structured questionnaire, and were evaluated as potential risk factors for FeLV or FIV status. Of the 368 cats that were evaluated in this study, 12.2% (45/368; 95% CI = 8.88 - 15.58) were positive for FeLV p27 antigen, 31.3%, (115/368; 95% CI = 26.51 - 35.99) were seropositive to FIV antibodies, and 4.3% (16/368; 95% CI = 2.27 - 6.43) had evidence of both viruses. Factors found to significantly increase the risk for FeLV seropositivity include sex, age, behaviour, sickness, and living in a multi-cat household. Seropositive response to FIV was significantly associated with sex, neuter status, age, behaviour, and health status. The present study indicates that FeLV and FIV are common among domestic cats in peninsular Malaysia, and that factors related to cat demographics and health such as age, sex, behaviour, health status and type of household are important predictors for seropositive status to FeLV or FIV in peninsular Malaysia. High prevalence of FeLV or FIV observed in our study is of concern, in view of the immunosuppressive potentials of the two pathogens. Specific measures for control and prevention such as screening and routine vaccination are needed to ensure that FeLV and FIV are controlled in the cat population of peninsular Malaysia.", "journal": "BMC veterinary research", "doi": "10.1186/1746-6148-8-33", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22424865", "author": "Duarte A", "n_authors": 4, "title": "Virological Survey in free-ranging wildcats (Felis silvestris) and feral domestic cats in Portugal.", "abstract": "To determine the presence of viral pathogens in natural areas a survey was conducted on an opportunistic sample of fifty eight wild (Felis silvestris silvestris) and feral cats (F. s. catus). The biological materials included serum, lung tissue extract and stool. Feline leukemia virus p27 antigen was detected in 13/50 serum/lung tissue extract samples (26%), canine distemper virus antibodies were detected in 2/26 serum/lung tissue extract samples (7.7%), feline coronavirus RNA was present in 6/29 stool samples (20.7%) and feline parvovirus DNA in 2/29 stool samples (6.9%). Canine distemper virus RNA was not detected. Feline immunodeficiency virus and feline coronavirus antibodies were not detected. Evidence of exposure to feline leukemia virus, canine distemper virus, feline coronavirus and feline parvovirus was found in wild and feral cats raising the importance of performing a comprehensive survey to correctly evaluate the potential threat of infectious diseases to endangered species, namely to the wildcat and to the Iberian lynx, which is meant to be reintroduced after 2012 in Portugal.", "journal": "Veterinary microbiology", "doi": "10.1016/j.vetmic.2012.02.033", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22412166", "author": "Thomason JD", "n_authors": 7, "title": "Doppler echocardiographic diagnosis and surgical therapy of constrictive pericarditis in a cat.", "abstract": "A 4-year-old Ragdoll cat presented for dyspnea secondary to chylous pleural effusion to the University of Georgia Veterinary Teaching Hospital. Physical examination, complete blood count, serum chemistries, urinalysis, thoracic radiographs, abdominal radiographs, and thoracic fluid cytology and culture failed to identify an etiology for the chylous effusion. The patient tested negative for feline leukemia virus, feline immunodeficiency virus and heartworm disease. Respiration phasic influences on early diastolic trans-mitral, trans-tricuspid and pulmonary vein blood flow velocities during Doppler echocardiography were consistent with constrictive pericarditis. The cat underwent subtotal pericardectomy. The patient recovered without complication and is overtly healthy without radiographic or echocardiographic abnormalities 6-months post-surgery. Constrictive pericarditis should be considered in cats with idiopathic pleural effusion, with or without ascites, in which standard echocardiographic assessment is not suggestive of structural heart disease. If constrictive pericarditis is present, the Doppler characteristics outlined here may allow for this diagnosis to be made. Pericardectomy may be highly rewarding, although the specific etiology of the constrictive pericarditis may remain unknown.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X11435041", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22405627", "author": "Mazari PM", "n_authors": 8, "title": "Comparison of the convergent receptor utilization of a retargeted feline leukemia virus envelope with a naturally-occurring porcine endogenous retrovirus A.", "abstract": "In vitro screening of randomized FeLV Envelope libraries identified the CP isolate, which enters cells through HuPAR-1, one of two human receptors utilized by porcine endogenous retrovirus-A (PERV-A), a distantly related gammaretrovirus. The CP and PERV-A Envs however, share little amino acid homology. Their receptor utilization was examined to define the common receptor usage of these disparate viral Envs. We demonstrate that the receptor usage of CP extends to HuPAR-2 but not to the porcine receptor PoPAR, the cognate receptor for PERV-A. Reciprocal interference between virus expressing CP and PERV-A Envs was observed on human cells. Amino acid residues localized to within the putative second extracellular loop (ECL-2) of PAR-1 and PAR-2 are found to be critical for CP envelope function. Through a panel of receptor chimeras and point mutations, this area was also found to be responsible for the differential usage of the PoPAR receptor between CP and PERV-A.", "journal": "Virology", "doi": "10.1016/j.virol.2012.02.012", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22403413", "author": "Englert T", "n_authors": 4, "title": "Survey of the feline leukemia virus infection status of cats in Southern Germany.", "abstract": "Most studies that investigate the prevalence of infections with feline leukemia virus (FeLV) are based on the detection of p27 antigen in blood, but they do not detect proviral DNA to identify the prevalence of regressive FeLV infections. The aim of the present study was to assess the prevalence and status of FeLV infection in cats in Southern Germany. P27 antigen enzyme-linked immunosorbent assay (ELISA), anti-p45 antibody ELISA, DNA polymerase chain reaction (PCR) of blood and RNA PCR of saliva were performed. Nine out of 495 cats were progressively (persistently) infected (1.8%) and six were regressively (latently) infected (1.2%). Cats with regressive infections are defined as cats that have been able to overcome antigenemia but provirus can be detected by PCR. Twenty-two unvaccinated cats likely had abortive infections (regressor cats), testing FeLV antigen- and provirus-negative but anti-p45 antibody-positive. Most of the FeLV-vaccinated cats did not have anti-FeLV antibodies. Both progressive, as well as regressive infections seem to be rare in Germany today.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X12440531", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22318850", "author": "Spada E", "n_authors": 9, "title": "Seroprevalence of feline immunodeficiency virus, feline leukaemia virus and Toxoplasma gondii in stray cat colonies in northern Italy and correlation with clinical and laboratory data.", "abstract": "Stray cat colonies in urban and rural areas of Lombardy, northern Italy, were surveyed for seroprevalence of feline immunodeficiency virus (FIV) antibodies, feline leukaemia virus (FeLV) antigen and Toxoplasma gondii IgG. Of 316 cats tested, 6.6% were positive for FIV and 3.8% were positive for FeLV infection; 203 cats were tested for T gondii IgG antibodies and a prevalence of 30.5% was detected. Statistical analysis tested the influence of provenience, age, gender, health status and laboratory results on seroprevalence and found male gender and adult age were risk factors for FIV infection. FIV-infected cats were more likely to have a decreased red blood cell count than FIV seronegative cats. No predictors were significantly associated with FeLV and T gondii seropositivity. Colony cats in this study posed a limited risk for retrovirus infection to pet cats allowed outdoors, whereas toxoplasmosis exposure was comparable with the worldwide data.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X12437352", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22314086", "author": "de Oliveira Lemos F", "n_authors": 4, "title": "Cryptosporidium species screening using Kinyoun technique in domestic cats with diarrhea.", "abstract": "Cryptosporidium is a coccidian that can lead to diarrhea, especially in immunosuppressed individuals. Retroviruses are considered a primary cause of immunosuppression in cats. Fecal specimens and blood collected from the 60 cats were evaluated for the presence of acid-fast cryptosporidia in three consecutive stool samples and for feline leukemia virus (FeLV) antigen and feline immunodeficiency virus (FIV) antibody by ELISA testing. Five animals (8.33%) shedding oocysts were found, one was both FIV- and FeLV-negative and four were FeLV-positive.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X11429221", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22313965", "author": "Iwanaga T", "n_authors": 5, "title": "Abnormal erythroid cell proliferation and myelofibrosis in a cat.", "abstract": "A cat was presented with severe progressive anemia despite marked erythroblastosis. The cat was negative for feline leukemia virus antigen and feline immunodeficiency virus antibody. Bone marrow cytology revealed an excess of erythroid cells with a predominance of prorubricytes and basophilic rubricytes. No response to immunosuppressive therapy was obtained, and a tentative diagnosis of myelodysplastic syndrome was made. The cat showed a partial response to low-dose cytarabine (20 mg/m(2) subcutaneously q24) but died 51 days after the 1st admission. Histopathological examination revealed fibrosis in the bone marrow and marked infiltration of erythroid cells into other organs.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.11-0268", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22285010", "author": "Sobrinho LS", "n_authors": 13, "title": "Coinfection of Leishmania chagasi with Toxoplasma gondii, Feline Immunodeficiency Virus (FIV) and Feline Leukemia Virus (FeLV) in cats from an endemic area of zoonotic visceral leishmaniasis.", "abstract": "The aim of the present study was to determine the coinfection of Leishmania sp. with Toxoplasma gondii, Feline Immunodeficiency Virus (FIV) and Feline Leukemia Virus (FeLV) in a population of cats from an endemic area for zoonotic visceral leishmaniasis. An overall 66/302 (21.85%) cats were found positive for Leishmania sp., with infection determined by direct parasitological examination in 30/302 (9.93%), by serology in 46/302 (15.23%) and by both in 10/302 (3.31%) cats. Real time PCR followed by amplicon sequencing successfully confirmed Leishmania infantum (syn Leishmania chagasi) infection. Out of the Leishmania infected cats, coinfection with FIV was observed in 12/66 (18.18%), with T. gondii in 17/66 (25.75%) and with both agents in 5/66 (7.58%) cats. FeLV was found only in a single adult cat with no Leishmania infection. A positive association was observed in coinfection of Leishmania and FIV (p<0.0001), but not with T. gondii (p>0.05). In conclusion, cats living in endemic areas of visceral leishmaniasis are significantly more likely to be coinfected with FIV, which may present confounding clinical signs and therefore cats in such areas should be always carefully screened for coinfections.", "journal": "Veterinary parasitology", "doi": "10.1016/j.vetpar.2012.01.010", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22258856", "author": "Greggs WM", "n_authors": 4, "title": "Discovery of drugs that possess activity against feline leukemia virus.", "abstract": "Feline leukemia virus (FeLV) is a gammaretrovirus that is a significant cause of neoplastic-related disorders affecting cats worldwide. Treatment options for FeLV are limited, associated with serious side effects, and can be cost-prohibitive. The development of drugs used to treat a related retrovirus, human immunodeficiency virus type 1 (HIV-1), has been rapid, leading to the approval of five drug classes. Although structural differences affect the susceptibility of gammaretroviruses to anti-HIV drugs, the similarities in mechanism of replication suggest that some anti-HIV-1 drugs may also inhibit FeLV. This study demonstrates the anti-FeLV activity of four drugs approved by the US FDA (Food and Drug Administration) at non-toxic concentrations. Of these, tenofovir and raltegravir are anti-HIV-1 drugs, while decitabine and gemcitabine are approved to treat myelodysplastic syndromes and pancreatic cancer, respectively, but also have anti-HIV-1 activity in cell culture. Our results indicate that these drugs may be useful for FeLV treatment and should be investigated for mechanism of action and suitability for veterinary use.", "journal": "The Journal of general virology", "doi": "10.1099/vir.0.039909-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22256844", "author": "Fischer C", "n_authors": 3, "title": "Erythroleukemia in a retrovirus-negative cat.", "abstract": "A 5-year-old spayed female cat was evaluated because of lethargy of 3 days' duration, acute respiratory distress, and anemia. Physical examination revealed the cat was in good body condition but had pale mucous membranes and elevated heart and respiratory rates. Results of hematologic analysis indicated the cat had severe anemia (Hct, 0.07 L/L; reference range, 0.28 to 0.49 L/L) and marked rubricytosis (19.0 × 10(9) cells/L; reference value, 0 cells/L). Results of serologic and PCR assays for detection of FeLV and FIV and PCR assays for detection of Mycoplasma spp were negative. Cytologic evaluation of a bone marrow aspirate and histologic evaluation of a biopsy specimen revealed a predominance of rubriblasts and rubricytes with granulocytopenia. Cytologic evaluation of fine-needle aspirates of the spleen and liver also revealed numerous rubriblasts. The cat received transfusions of packed RBCs, and supportive treatment was administered. Analysis of test results yielded a diagnosis of acute myeloid leukemia (erythroid subtype). Because of continued hemolysis and anemia in combination with the diagnosis of erythroleukemia (which has a poor prognosis), the cat was euthanized. To the authors' knowledge, erythroleukemia has only been reported in cats infected with FeLV. However, results of all diagnostic assays for FeLV were negative in the cat reported here, which suggested that erythroleukemia can develop in cats in the absence of FeLV infection.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.240.3.294", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22247389", "author": "Goodrich JM", "n_authors": 11, "title": "Serosurvey of free-ranging Amur tigers in the Russian Far East.", "abstract": "Wild Amur tigers (Panthera tigris altaica, n=44) from the Russian Far East were tested for antibodies to feline leukemia virus, feline corona virus (FCoV), feline immunodeficiency virus, feline parvovirus (FPV), canine distemper virus (CDV), Toxoplasma gondii, and Bartonella henselae. Antibodies to FCoV, CDV, FPV, and T. gondii were detected in 43, 15, 68, and 42% of tigers, respectively. No differences were detected in antibody prevalence estimates between tigers captured as part of a research program and those captured to mitigate human-tiger conflicts. Domestic dogs (Canis familiaris) were tested as a potential source for CDV; 16% were vaccinated against CDV and 58% of unvaccinated dogs were antibody positive for CDV. A high percentage of tigers were exposed to potential pathogens that could affect the survival of this species. We recommend continued monitoring of wild tigers throughout Asia, development of standardized sampling and postmortem examination procedures, and additional research to better understand potential domestic and wild animal sources for these pathogens.", "journal": "Journal of wildlife diseases", "doi": "10.7589/0090-3558-48.1.186", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "32214774", "author": "Goncharuk MS", "n_authors": 4, "title": "Prevalence of seropositivity to pathogens in small carnivores in adjacent areas of Lazovskii Reserve.", "abstract": "The prevalence of infectious diseases in wild and feral carnivores is poorly known in Primorsky Krai, where rare species such as the Amur tiger and the Far East leopard roam. In this study we evaluated the prevalence of seropositivity in feral (cats, dogs) and wild (raccoon dog, badger, American mink, Far Eastern wild cat) carnivores to various pathogens: distemper virus, parvovirus, feline immunodeficiency and feline leukemia virus, feline coronavirus, ", "journal": "Biology bulletin of the Russian Academy of Sciences", "doi": "10.1134/S1062359012080067", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22177694", "author": "Tejerizo G", "n_authors": 5, "title": "Altered plasma concentrations of sex hormones in cats infected by feline immunodeficiency virus or feline leukemia virus.", "abstract": "Gender differences may affect human immunodeficiency virus (HIV) infection in humans and may be related to fluctuations in sex hormone concentration. The different percentage of male and female cats observed to be infected by feline leukemia virus (FeLV) or feline immunodeficiency virus (FIV) has been traditionally explained through the transmission mechanisms of both viruses. However, sexual hormones may also play a role in this different distribution. To study this possibility, 17β-estradiol, progesterone, testosterone, and dehydroepiandrosterone (DHEA) concentrations were analyzed using a competitive enzyme immunoassay in the plasma of 258 cats naturally infected by FIV (FIV(+)), FeLV (FeLV(+)), or FeLV and FIV (F(-)F(+)) or negative for both viruses, including both sick and clinically healthy animals. Results indicated that the concentrations of 17β-estradiol and testosterone were significantly higher in animals infected with FIV or FeLV (P < 0.05) than in negative cats. Plasma concentrations of DHEA in cats infected by either retrovirus were lower than in negative animals (P < 0.05), and F(-)F(+) cats had significantly lower plasma values than monoinfected cats (P < 0.05). No significant differences were detected in the plasma concentration of progesterone of the four groups. No relevant differences were detected in the hormone concentrations between animal genders, except that FIV(+) females had higher DHEA concentrations than the corresponding males (P < 0.05). In addition, no differences were observed in the hormone concentrations between retrovirus-infected and noninfected animals with and without clinical signs. These results suggest that FIV and FeLV infections are associated with an important deregulation of steroids, possibly from early in the infection process, which might have decisive consequences for disease progression.", "journal": "Domestic animal endocrinology", "doi": "10.1016/j.domaniend.2011.11.001", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "21908268", "author": "Filoni C", "n_authors": 16, "title": "Surveillance using serological and molecular methods for the detection of infectious agents in captive Brazilian neotropic and exotic felids.", "abstract": "The aim of the current study was to investigate the exposure of captive wild felids to various infectious pathogens using serological and molecular methods. One hundred and fifty-nine neotropic felids and 51 exotic felids from 28 captive settings in Brazil were tested. While antibodies against Feline parvovirus and Feline coronavirus (FCoV), Feline calicivirus and Bartonella spp. were frequently detected by serologic tests, antibodies against Felid herpesvirus 1 or infection with hemotropic mycoplasmas were less prevalent. Serologic evidence of exposure to Ehrlichia spp., Feline immunodeficiency virus, and Feline leukemia virus (FeLV) was detected rarely, and infections with FeLV, Ehrlichia spp., and Cytauxzoon spp. were found infrequently. The detected Bartonella sequence was molecularly similar to B. koehlerae and B. henselae; for Cytauxzoon, the sequence resembled those from domestic cats. No Anaplasma phagocytophilum and Theileria spp. infections were detected. The positive test results varied significantly among different facilities and species. Additionally, FCoV seropositivity was more prevalent in captivity than in free-ranging populations. Results suggest that testing is appropriate prior to relocation of felids.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/1040638711407684", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "21839583", "author": "Carli E", "n_authors": 10, "title": "Cytauxzoon sp. infection in the first endemic focus described in domestic cats in Europe.", "abstract": "Information about epidemiological and clinicopathological aspects of domestic cat infection by species of Cytauxzoon other than Cytauxzoon felis is limited and it has rarely been reported. Following the detection of clinical cytauxzoonosis in three cats from Trieste (Italy), an epidemiological study was carried out in colony (n=63) and owned (n=52) cats from the same city to investigate the presence of Cytauxzoon sp. infection and to assess clinicopathological findings and variables associated with this infection. Cytauxzoon sp. infection was detected by 18S rRNA gene PCR in 23% (27/118) and by blood smear examination in 15% (18/118) of domestic cats. The 18S rRNA gene sequences obtained were 99% identical to the Cytauxzoon sp. sequences deposited in GenBank(®) from Spanish, French and Mongolian wild and domestic cats. Erythroparasitemia was observed mainly in apparently healthy cats. Cytauxzoon sp. infection was statistically associated with the colony group and the outdoor life style. No statistical association was found between positivity by PCR and breed, gender, age, presence of ticks and/or fleas, clinical status, laboratory findings such as anemia, FIV and/or FeLV status and mortality rate. Persistence of the infection was monitored and documented in four clinical cases. We reported the first clinicopathological description of naturally occurring Cytauxzoon sp. infection in domestic cats living in Italy. The predominance of subclinical erythroparasitemia and the evidence of persistent infection support the hypothesis that the domestic cat might serve as a reservoir host for this infection.", "journal": "Veterinary parasitology", "doi": "10.1016/j.vetpar.2011.07.025", "deposited_data": "Sim", "nuccore_ids": "299033176, 299033175, 299033174, 299033173, 299033172, 299033171, 299033170", "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "21665236", "author": "Mabasa L", "n_authors": 6, "title": "Lipotropes (methyl nutrients) inhibit growth of feline lymphoma in vitro.", "abstract": "Feline lymphoma is one of the most frequently diagnosed tumors in cats. Lipotropes are dietary methyl donors that may modulate DNA methylation status and the expression of genes involved in growth and apoptosis of feline lymphoma cells. The specific objective of the study was to determine if lipotropes affect the growth of feline lymphoma cells, which entailed examining a correlation between lymphoma cell proliferation and apoptosis. F1B and FeLV-3281 cells were cultured and treated with 20 times the level of lipotropes contained in the basal culture medium. Cell growth and death and caspase 3 and tumor protein p53 activity were measured. Lipotropes were found to significantly reduce cell growth; increased cell death and caspase 3 and p53 activity was seen in F1B cells after 72 h, but the effect was minimal on FeLV-3281. These results could be useful in the development of dietary strategies for treating and preventing feline lymphoma.", "journal": "Research in veterinary science", "doi": "10.1016/j.rvsc.2011.05.015", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "24260809", "author": "Abdou NE", "n_authors": 5, "title": "Enteric protozoan parasites in stray cats in Kuwait with special references to toxoplasmosis and risk factors affecting its occurrence.", "abstract": "In Kuwait, stray cats were surveyed for enteric protozoan infection using fecal examination and their sera were tested for Toxoplasma gondii IgG using indirect hemagglutination test (IHAT) as well as for feline immunodeficiency virus (FIV) antibodies and feline leukaemia virus (FeLV) antibodies using ELISA. Out of 240 fecal samples examined 22 (9.2%) were found to be infected with oocysts of four species of coccidian protozoa. Isopspora felis was the most predominant enteric protozoan parasite (7.1%), followed by T. gondii (2.1%), I. rivolta (1.6), Sarcocystis was only found in one case (0.4%). Juvenile cats ( 6 months old) had higher infection rate with oocyst of enteric protozoa than older cats (p-value 0.001). Sero-survey of 240 stray cats revealed that 19.6% were positive to T. gondii IgG. Toxoplasma sero-positivity was observed in higher number of adults compared to young cats suggests that with age the risk of exposure to T. gondii increases. While concurrent retroviral infections were not found to be associated with increased risk for developing T. gondii antibodies.", "journal": "Journal of the Egyptian Society of Parasitology", "doi": "10.12816/0006387", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "24235220", "author": "Li G", "n_authors": 6, "title": "Comparison of protoporphyrin IX content and related gene expression in the tissues of chickens laying brown-shelled eggs.", "abstract": "Protoporphyrin IX (PpIX), an immediate precursor of heme, is the main pigment resulting in the brown coloration of eggshell. The brownness and uniformity of the eggshell are important marketing considerations. In this study, 9 chickens laying darker brown shelled eggs and 9 chickens laying lighter brown shelled eggs were selected from 464 individually caged layers in a Rhode Island Red pureline. The PpIX contents were measured with a Microplate Reader at the wavelength of 412 nm and were compared in different tissues of the 2 groups. Although no significant difference in serum, bile, and excreta was found between the 2 groups, PpIX content in the shell gland and eggshell of the darker group was higher than in those of the lighter group, suggesting that PpIX was synthesized in the shell gland. We further determined the expression levels of 8 genes encoding enzymes involved in the heme synthesis and transport in the liver and shell gland at 6 h postoviposition by quantitative PCR. The results showed that expression of aminolevulinic acid synthase-1 (ALAS1) was higher in the liver of hens laying darker brown shelled eggs, whereas in the shell gland the expression levels of ALAS1, coproporphyrinogen oxidase (CPOX), ATP-binding cassette family members ABCB7 and ABCG2, and receptor for feline leukemia virus, subgroup C (FLVCR) were significantly higher in the hens laying darker brown shelled eggs. Our results demonstrated that hens laying darker brown shelled eggs could deposit more PpIX onto the eggshell and the brownness of the eggshell was dependent on the total quantity of PpIX in the eggshell. More heme was synthesized in the liver and shell gland of hens laying darker brown shelled eggs than those of hens laying lighter brown shelled eggs. High expression level of ABCG2 might facilitate the accumulation of PpIX in the shell gland.", "journal": "Poultry science", "doi": "10.3382/ps.2013-03484", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "24148555", "author": "Denner J", "n_authors": 2, "title": "Koala retroviruses: characterization and impact on the life of koalas.", "abstract": "Koala retroviruses (KoRV) have been isolated from wild and captive koalas in Australia as well as from koala populations held in zoos in other countries. They are members of the genus Gammaretrovirus, are most closely related to gibbon ape leukemia virus (GaLV), feline leukemia virus (FeLV) and porcine endogenous retrovirus (PERV) and are likely the result of a relatively recent trans-species transmission from rodents or bats. The first KoRV to be isolated, KoRV-A, is widely distributed in the koala population in both integrated endogenous and infectious exogenous forms with evidence from museum specimens older than 150 years, indicating a relatively long engagement with the koala population. More recently, additional subtypes of KoRV that are not endogenized have been identified based on sequence differences and host cell receptor specificity (KoRV-B and KoRV-J). A specific association with fatal lymphoma and leukemia has been recently suggested for KoRV-B. In addition, it has been proposed that the high viral loads found in many animals may lead to immunomodulation resulting in a higher incidence of diseases such as chlamydiosis. Although the molecular basis of this immunomodulation is still unclear, purified KoRV particles and a peptide corresponding to a highly conserved domain in the envelope protein have been shown to modulate cytokine expression in vitro, similar to that induced by other gammaretroviruses. While much is still to be learned, KoRV induced lymphoma/leukemia and opportunistic disease arising as a consequence of immunomodulation are likely to play an important role in the stability of koala populations both in the wild and in captivity.", "journal": "Retrovirology", "doi": "10.1186/1742-4690-10-108", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "24021674", "author": "Byon JC", "n_authors": 4, "title": "FLVCR is necessary for erythroid maturation, may contribute to platelet maturation, but is dispensable for normal hematopoietic stem cell function.", "abstract": "Heme is a pleiotropic molecule that is important for oxygen and oxidative metabolism, most notably as the prosthetic group of hemoglobin and cytochromes. Because excess free intracellular heme is toxic, organisms have developed mechanisms to tightly regulate its concentration. One mechanism is through active heme export by the group C feline leukemia virus receptor (FLVCR). Previously, we have shown that FLVCR is necessary for embryonic and postnatal erythropoiesis. However, FLVCR is also expressed in numerous other tissues, including hematopoietic stem cells (HSCs). To explore a possible role for FLVCR in HSC function, we performed serial, competitive repopulation transplant experiments using FLVCR-deleted and control bone marrow cells, along with wild-type competitor cells. Loss of FLVCR did not impact HSC function under steady-state or myelotoxic stress conditions (such as arsenic or radiation exposure), nor did FLVCR deletion result in alterations in the various progenitor compartments. However, even when 95% of the donor bone marrow cells lacked FLVCR, all red cells in recipient mice were wild type. This is due to the increased apoptosis of FLVCR-deleted proerythroblasts. Also, remarkably, loss of FLVCR increased megakaryocyte ploidy. Together, these findings show FLVCR is redundant in stem cells but has critical and contrasting stage-specific roles in discrete hematopoietic lineages.", "journal": "Blood", "doi": "10.1182/blood-2012-10-465104", "deposited_data": "Sim", "nuccore_ids": "924181778, 924181484, 124486924, 924181778, 924181484, 124486924", "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23966402", "author": "Ito J", "n_authors": 8, "title": "Refrex-1, a soluble restriction factor against feline endogenous and exogenous retroviruses.", "abstract": "The host defense against viral infection is acquired during the coevolution or symbiosis of the host and pathogen. Several cellular factors that restrict retroviral infection have been identified in the hosts. Feline leukemia virus (FeLV) is a gammaretrovirus that is classified into several receptor interference groups, including a novel FeLV-subgroup D (FeLV-D) that we recently identified. FeLV-D is generated by transduction of the env gene of feline endogenous gammaretrovirus of the domestic cat (ERV-DCs) into FeLV. Some ERV-DCs are replication competent viruses which are present and hereditary in cats. We report here the determination of new viral receptor interference groups and the discovery of a soluble antiretroviral factor, termed Refrex-1. Detailed analysis of FeLV-D strains and ERV-DCs showed two receptor interference groups that are distinct from other FeLV subgroups, and Refrex-1 specifically inhibited one of them. Refrex-1 is characterized as a truncated envelope protein of ERV-DC and includes the N-terminal region of surface unit, which is a putative receptor-binding domain, but lacks the transmembrane region. Refrex-1 is efficiently secreted from the cells and appears to cause receptor interference extracellularly. Two variants of Refrex-1 encoded by provirus loci, ERV-DC7 and DC16, are expressed in a broad range of feline tissues. The host retains Refrex-1 as an antiretroviral factor, which may potentially prevent reemergence of the ERVs and the emergence of novel ERV-related viruses in cats. Refrex-1 may have been acquired during endogenization of ERV-DCs and may play an important role in retroviral restriction and antiviral defense in cats.", "journal": "Journal of virology", "doi": "10.1128/JVI.01267-13", "deposited_data": "Sim", "nuccore_ids": "543583510, 543583508, 543583506, 543583504, 543583503, 543583502, 2131078298, 2130975037, 2130975034, 2130975031, 2130975028, 2130975025, 2130907928", "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23903838", "author": "Bolin LL", "n_authors": 7, "title": "The surface glycoprotein of feline leukemia virus isolate FeLV-945 is a determinant of altered pathogenesis in the presence or absence of the unique viral long terminal repeat.", "abstract": "Feline leukemia virus (FeLV) is a naturally transmitted gammaretrovirus that infects domestic cats. FeLV-945, the predominant isolate associated with non-T-cell disease in a natural cohort, is a member of FeLV subgroup A but differs in sequence from the FeLV-A prototype, FeLV-A/61E, in the surface glycoprotein (SU) and long terminal repeat (LTR). Substitution of the FeLV-945 LTR into FeLV-A/61E resulted in pathogenesis indistinguishable from that of FeLV-A/61E, namely, thymic lymphoma of T-cell origin. In contrast, substitution of both FeLV-945 LTR and SU into FeLV-A/61E resulted in multicentric lymphoma of non-T-cell origin. These results implicated the FeLV-945 SU as a determinant of pathogenic spectrum. The present study was undertaken to test the hypothesis that FeLV-945 SU can act in the absence of other unique sequence elements of FeLV-945 to determine the disease spectrum. Substitution of FeLV-A/61E SU with that of FeLV-945 altered the clinical presentation and resulted in tumors that demonstrated expression of CD45R in the presence or absence of CD3. Despite the evident expression of CD45R, a typical B-cell marker, T-cell receptor beta (TCRβ) gene rearrangement indicated a T-cell origin. Tumor cells were detectable in bone marrow and blood at earlier times during the disease process, and the predominant SU genes from proviruses integrated in tumor DNA carried markers of genetic recombination. The findings demonstrate that FeLV-945 SU alters pathogenesis, although incompletely, in the absence of FeLV-945 LTR. Evidence demonstrates that FeLV-945 SU and LTR are required together to fully recapitulate the distinctive non-T-cell disease outcome seen in the natural cohort.", "journal": "Journal of virology", "doi": "10.1128/JVI.01130-13", "deposited_data": "Sim", "nuccore_ids": "409245542, 409245541, 409245540, 409245539, 409245538, 409245537, 409245536", "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23813812", "author": "Möstl K", "n_authors": 17, "title": "Prevention of infectious diseases in cat shelters: ABCD guidelines.", "abstract": "Recommendations are given in relation to infectious diseases in rescue shelters. The ABCD recognises that there is a wide variation in the design and management of shelters, and that these largely reflect local pressures. These guidelines are written with this diverse audience in mind; they point to the ideal, and also provide for some level of compromise where this ideal cannot immediately be attained. In addition consideration should be given to general requirements in order to optimise overall health and wellbeing of cats within the shelter. HOUSING: Compartmentalisation of the shelter into at least three individual sections (quarantine area for incoming cats, isolation facilities for sick or potentially infectious cats, and accommodation for clinically healthy, retrovirus-negative cats) can facilitate containment of a disease outbreak, should it occur. STANDARD OF CARE: Incoming cats should receive a full health check by a veterinary surgeon, should be dewormed and tested for retrovirus infections (feline leukaemia virus [FeLV] and/or feline immunodeficiency virus [FIV]) in regions with high prevalence and in shelters that allow contact between cats. Cats which are not rehomed should receive a regular veterinary check-up at intervals recommended by their veterinarian. Each cat should be vaccinated as soon as possible against feline panleukopenia virus (FPV), feline herpesvirus (FHV-1) and feline calicivirus (FCV) infections. HYGIENE: Adequate hygiene conditions should ensure that contact between shedders of infectious agents and susceptible animals is reduced as efficiently as possible by movement control, hygiene procedures of care workers, barrier nursing, cleaning and disinfection. STRESS REDUCTION: Stress reduction is important for overall health and for minimising the risk of recrudescence and exacerbation of infectious diseases. In general, a special effort should be made to rehome cats as soon as possible.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X13489210", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23778599", "author": "Furtado MM", "n_authors": 12, "title": "Serosurvey for selected viral infections in free-ranging jaguars (Panthera onca) and domestic carnivores in Brazilian Cerrado, Pantanal, and Amazon.", "abstract": "We investigated the exposure of jaguar (Panthera onca) populations and domestic carnivores to selected viral infections in the Cerrado, Amazon, and Pantanal biomes of Brazil. Between February 2000 and January 2010, we collected serum samples from 31 jaguars, 174 dogs (Canis lupus familiaris), and 35 domestic cats (Felis catus). Serologic analyses for antibodies to rabies virus, canine distemper virus (CDV), feline immunodeficiency virus (FIV), and for feline leukemia virus (FeLV) antigen were conducted. The jaguars from Cerrado and Pantantal were exposed to rabies virus, while the jaguars from the Pantanal and the dogs from all three areas were exposed to CDV. Two cats from the Amazonian site were antigen-positive for FeLV, but no jaguars had FeLV antigen or FIV antibody. Canine distemper and rabies viruses should be carefully monitored and considered potential threats to these jaguar populations. Currently FIV and FeLV do not appear to represent a health threat for jaguar populations in this area. Domestic dogs and cats in these areas should be vaccinated, and the movement of domestic animals around protected areas should be restricted.", "journal": "Journal of wildlife diseases", "doi": "10.7589/2012-02-056", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23777533", "author": "Nieuwenhuizen L", "n_authors": 8, "title": "Identification and expression of iron regulators in human synovium: evidence for upregulation in haemophilic arthropathy compared to rheumatoid arthritis, osteoarthritis, and healthy controls.", "abstract": "Recurrent joint bleeding is the most common manifestation of severe haemophilia resulting in haemophilic arthropathy (HA). Iron plays a central role in the pathogenesis of the two main features of HA: synovitis and cartilage destruction. The aim of this study was to investigate the synovial presence of the iron regulator proteins ferroportin (FPN), hepcidin, haemoglobin scavenger receptor CD163 (CD163), feline leukaemia virus subgroup C (FLVCR), and heme carrier protein 1 (HCP-1). A comparison of the expression in HA with rheumatoid arthritis (RA), osteoarthritis (OA), and healthy controls (HC) is made. Synovial expression of iron regulators was investigated by immunohistochemistry in human synovial tissue and in a murine haemophilia model. We demonstrate for the first time the synovial presence of the investigated iron regulator proteins. Expression of the iron regulator proteins FPN, CD163, FLVCR, and HCP-1 was enhanced in HA in comparison to RA, OA, and HC synovium. In addition, in a murine haemophilia model of acute joint bleeding, synovial expression of FPN, CD163, and HCP-1 was increased. In both human and murine experiment, synovial expression of hepcidin was not altered. These findings indicate the presence of iron regulator proteins in the synovium, demonstrate an enhanced expression of FPN, CD163, FLVCR, and HCP-1 in HA, and suggest a synovial adaptation mechanism to maintain synovial iron homeostasis in HA.", "journal": "Haemophilia : the official journal of the World Federation of Hemophilia", "doi": "10.1111/hae.12208", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23767896", "author": "Zhang X", "n_authors": 5, "title": "Gene delivery in a mouse xenograft of a retargeted retrovirus to a solid 143B osteosarcoma.", "abstract": "Osteosarcomas are the most common primary bone malignancies found in children and adolescents. An optimized system was developed for efficient retroviral gene delivery into solid 143B osteosarcoma tumors in mice using a retargeted Env. In these studies, the viral Env CP was isolated from an in vitro screen of a library of feline leukemia virus Env randomized in the receptor-binding domain and maintained high titer on human 143B osteosarcoma cell line. The vector developed to express the random Env libraries encoded the drug selectable marker neo. To adapt this for studies in live animals, the murine based vector was modified to express the luciferase gene. The bicistronic vector developed expressed both the CP Env and luciferase in the presence of either the MPMV CTE or a WPRE element. Virus bearing the CP FeLV Env variant maintained high titers after concentration allowing for direct visualization of delivery of the luciferase gene in subcutaneous 143B osteosarcoma tumors. This system serves as a proof-of-concept for the use of novel FeLV Env pseudotyped MLV particles for in vivo gene delivery. Gene delivery and expression of lucerifase from viral particles bearing the CP Env was readily detected in live mice after a single round of intratumor injection.", "journal": "Virology journal", "doi": "10.1186/1743-422X-10-194", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23718784", "author": "Nagel SS", "n_authors": 3, "title": "Fatal disseminated toxoplasmosis in an immunocompetent cat.", "abstract": "A 10-year-old domestic short hair cat was referred for investigation of anorexia and polydipsia of 3 days' duration. Clinically the cat was obese, pyrexic (39.8 °C), had acute abdominal pain and severe bilirubinuria. Haematology and serum biochemistry revealed severe panleukopenia, thrombocytopenia, markedly elevated alanine aminotransferase (ALT) and five-fold increased pre-prandial bile acids. Ultrasonographic evaluation of the abdomen did not identify any abnormalities. Serum tests for feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV) were negative. Broad-spectrum antibiotic treatment for infectious hepatitis was to no avail; the cat deteriorated and died 72 h after admission. Necropsy revealed mild icterus and anaemia, severe multifocal hepatic necrosis, serofibrinous hydrothorax, pulmonary oedema and interstitial pneumonia. Histopathology confirmed the macroscopic findings and revealed multifocal microgranulomata in the brain and myocardium, as well as areas of necrosis in lymph nodes and multifocally in splenic red pulp. Long bone shaft marrow was hyperplastic with a predominance of leukocyte precursors and megakaryocytes and splenic red pulp showed mild extramedullary haemopoiesis. Immunohistochemical staining for Toxoplasma gondii was strongly positive, with scattered cysts and tachyzoites in the liver, lymph nodes, spleen, lungs, brain, salivary glands and intracellularly in round cells in occasional blood vessels. Immunohistochemical staining for corona virus on the same tissues was negative, ruling out feline infectious peritonitis (FIP). Polymerase chain reaction (PCR) on formalin-fixed paraffin-wax embedded tissues was positive for Toxoplasma sp., but attempts at sequencing were unsuccessful. This was the first case report of fulminant disseminated toxoplasmosis in South Africa, in which detailed histopathology in an apparently immunocompetent cat was described.", "journal": "Journal of the South African Veterinary Association", "doi": "10.4102/jsava.v84i1.299", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23677843", "author": "Nagata M", "n_authors": 2, "title": "Cutaneous viral dermatoses in dogs and cats.", "abstract": "Cutaneous viral dermatoses are often underdiagnosed in dogs and cats because they are rare, and because it is difficult to identify an exact causative agent. Even so, practitioners in primary care may encounter some characteristic clinical features. This article reviews commonly encountered dermatoses, particularly papillomavirus-associated dermatoses in dogs and cats. It also provides a brief overview of several other dermatoses associated with feline herpesvirus, feline calicivirus, FeLV, and feline poxvirus.", "journal": "Compendium (Yardley, PA)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23666110", "author": "Jenkins KS", "n_authors": 4, "title": "Prevalence and risk factor analysis of feline haemoplasma infection in New Zealand domestic cats using a real-time PCR assay.", "abstract": "Haemotropic mycoplasmas (haemoplasmas) are small epierythrocytic bacteria that have the potential to cause severe, life-threatening haemolytic anaemia. The aim of the current study was to evaluate feline haemoplasma prevalence using real-time polymerase chain reaction (PCR) from a convenience sample of New Zealand domestic cats, including blood film examination and a risk factor analysis. DNA was extracted from 200 blood samples submitted to a diagnostic laboratory for routine haematology over a 12-month period. Species-specific real-time PCR assays identified 62 cats that were positive for haemoplasma DNA, giving an overall prevalence of 31%. Twelve of the positive cats had dual infections. The prevalence of the three feline haemoplasmas was 25% for 'Candidatus Mycoplasma haemominutum', 7.5% for Mycoplasma haemofelis and 4.5% for 'Candidatus Mycoplasma turicensis' (CMt). All samples were positive for an internal control (feline 28S rDNA) by real-time PCR. Sensitivity and specificity of blood smear examination for haemoplasma infection in this study was 9.7% and 97.8%, respectively. Retroviral infection was tested using the Idexx Snap Feline Triple test on all samples. Twenty cats (10%) were feline immunodeficiency virus (FIV) positive and 11 cats (5.5%) were feline leukaemia virus (FeLV) positive. Statistical comparisons, using multivariate logistic regression, indicated that positive FIV status, male gender and non-pedigree breed were significantly (P <0.05) associated with haemoplasma infection, with odds ratios of 10.16, 5.04 and 3.03, respectively. The results of this study demonstrate the prevalence of the three main feline haemoplasma species in New Zealand for the first time, with prevalences correlating with previous overseas studies. This is the first report of CMt in New Zealand.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X13488384", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23593376", "author": "Watanabe S", "n_authors": 9, "title": "Phylogenetic and structural diversity in the feline leukemia virus env gene.", "abstract": "Feline leukemia virus (FeLV) belongs to the genus Gammaretrovirus, and causes a variety of neoplastic and non-neoplastic diseases in cats. Alteration of viral env sequences is thought to be associated with disease specificity, but the way in which genetic diversity of FeLV contributes to the generation of such variants in nature is poorly understood. We isolated FeLV env genes from naturally infected cats in Japan and analyzed the evolutionary dynamics of these genes. Phylogenetic reconstructions separated our FeLV samples into three distinct genetic clusters, termed Genotypes I, II, and III. Genotype I is a major genetic cluster and can be further classified into Clades 1-7 in Japan. Genotypes were correlated with geographical distribution; Genotypes I and II were distributed within Japan, whilst FeLV samples from outside Japan belonged to Genotype III. These results may be due to geographical isolation of FeLVs in Japan. The observed structural diversity of the FeLV env gene appears to be caused primarily by mutation, deletion, insertion and recombination, and these variants may be generated de novo in individual cats. FeLV interference assay revealed that FeLV genotypes did not correlate with known FeLV receptor subgroups. We have identified the genotypes which we consider to be reliable for evaluating phylogenetic relationships of FeLV, which embrace the high structural diversity observed in our sample. Overall, these findings extend our understanding of Gammaretrovirus evolutionary patterns in the field, and may provide a useful basis for assessing the emergence of novel strains and understanding the molecular mechanisms of FeLV transmission in cats.", "journal": "PloS one", "doi": "10.1371/journal.pone.0061009", "deposited_data": "Sim", "nuccore_ids": "1737725643, 1669280704, 407725321, 381214339, 338747546, 338747544, 338747543, 338747541, 338747539, 338747537, 338747535, 338747533, 338747531, 338747529, 338747527, 338747525, 338747523, 338747522, 338747520, 338747518, 338747516, 338747514, 338747512, 338747510, 338747508, 338747506, 338747505, 338747503, 338747502, 338747501, 338747499, 338747497, 338747495, 338747493, 338747491, 338747489, 338747487, 338747485, 338747483, 338747481, 338747479, 338747478, 338747476, 338747474, 338747472, 338747470, 338747468, 338747466, 338747464, 338747462, 338747460, 338747458, 338747456, 338747454, 338747452, 338747451, 338747450, 338747448, 338747446, 338747444, 338747442, 338747440, 338747438, 338747436, 338747434, 338747432, 338747430, 338747428, 338747427, 338747426, 338747425, 338747423, 338747421, 338747420, 338747419, 338747417, 338747416, 338747415, 338747414, 338747412, 338747410, 338747408, 338747406, 338747404, 338747403, 338747401, 338747399, 338747397, 338747395, 338747393, 338747391, 338747389, 338747388, 338747386, 338747385, 338747383, 338747381, 338747379, 338747377, 338747375, 338747373, 338747372, 338747370, 338747368, 338747366, 338747364, 338747362, 338747360, 338747358, 338747356, 338747354, 338747352, 338747350, 338747348, 338747346, 338747344, 338747342, 338747340, 338747339, 338747338, 338747336, 338747334, 338747332, 338747330, 338747328, 338747327, 338747326, 338747324, 338747322, 338747320, 338747318, 338747316, 338747314, 338747312, 338747310, 338747308, 338747306, 338747304, 338747302, 338747300, 338747298, 338747296, 338747295, 338747294, 338747292, 338747290, 338747288, 338747287, 338747285, 338747283, 338747282, 338747280, 338747278, 338747276, 338747275, 338747273, 338747271, 338747269, 338747268, 338747266, 338747264, 338747262, 338747261, 338747259, 338747257, 338747255, 338747253, 338747251, 338747249, 338747248, 338747246, 338747244, 338747242, 338747240, 338747238, 338747236, 338747234, 338747232, 338747230, 338747228, 338747226, 338747225, 338747223, 338747222, 338747220, 338747218, 338747216, 338747214, 338747212, 338747211, 338747209, 338747207, 338747205, 338747203, 338747201, 338747199, 338747197, 338747195, 338747193, 338747191, 338747189, 338747187, 338747185, 338747183, 338747181, 338747179, 338747177, 338747175, 338747174, 338747172, 338747170, 338747168, 338747165, 338747162, 338747161, 338747160, 338747159, 338747157, 338747156, 338747154, 338747152, 338747151, 338747149, 338747148, 338747146, 338747144, 338747142, 338747140, 338747138, 338747137, 338747136, 338747135, 338747133, 338747131, 338747129, 338747128, 338747126, 338747124, 338747122, 338747120, 338747118, 338747116, 338747114, 338747111, 338747108, 338747106, 338747104, 338747102, 338747101, 338747099, 338747097, 338747095, 338747093, 338747091, 338747089, 338747087, 338747085, 338747083, 338747081, 338747080, 338747078, 338747077, 338747076, 338747075, 338747073, 338747072, 338747070, 338747069, 338747067, 338747065, 338747063, 338747061, 338747060, 338747058, 338747056, 338747055, 338747054, 338747052, 338747050, 338747048, 338747046, 338747044, 338747042, 338747040, 338747038, 338747036, 338747035, 338747033, 338747031, 338747029, 338747027, 338747026, 338747025, 338747024, 338746816, 338746814, 338746813, 338746811, 338746810, 338746808, 338746806, 338746804, 338746802, 338746800, 338746798, 338746796, 338746795, 338746793, 338746791, 338746789, 338746788, 338746786, 338746784, 338746782, 338746780, 338746778, 338746776, 338746775, 338746773, 338746771, 338746769, 338746767, 338746765, 338746763, 338746762, 338746760, 338746758, 338746757, 338746755, 338746753, 338746752, 338746751, 338746749, 338746748, 338746746, 338746744, 338746742, 338746740, 338746739, 338746737, 338746735, 338746733, 338746731, 338746730, 338746728, 338746726, 338746725, 338746723, 338746721, 338746719, 338746717, 338746715, 338746714, 338746712, 338746710, 338746708, 338746707, 338746705, 338746703, 338746701, 338746699, 338746697, 338746695, 338746693, 338746691, 338746690, 338746688, 338746686, 338746684, 338746682, 338746680, 338746678, 338746677, 338746676, 338746675, 338746673, 338746671, 338746669, 338746667", "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23568903", "author": "Foley JE", "n_authors": 6, "title": "Risk factors for exposure to feline pathogens in California mountain lions (Puma concolor).", "abstract": "The primary challenge to mountain lion population viability in California is habitat loss and fragmentation. These habitat impacts could enhance disease risk by increasing contact with domestic animals and by altering patterns of exposure to other wild felids. We performed a serologic survey for feline pathogens in California mountain lions (Puma concolor) using 490 samples from 45 counties collected from 1990 to 2008. Most mountain lions sampled were killed because of depredation or public safety concerns and 75% were adults. Pathogens detected by serosurvey in sampled mountain lions included feline panleukopenia virus (39.0%), feline calicivirus (33.0%), feline coronavirus (FCoV, 15.1%), feline herpesvirus (13.0%), heartworm (12.4%), feline leukemia virus (5.4%), and canine distemper virus (3%). An outbreak of heartworm exposure occurred from 1995 to 2003 and higher than expected levels of FCoV-antibody-positive mountain lions were observed from 2005 to 2008, with foci in southern Mendocino and eastern Lake counties. We show that the majority of mountain lions were exposed to feline pathogens and may be at risk of illness or fatality, particularly kittens. Combined with other stressors, such as ongoing habitat loss, infectious disease deserves recognition for potential negative impact on mountain lion health and population viability.", "journal": "Journal of wildlife diseases", "doi": "10.7589/2012-08-206", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23506900", "author": "Khan AA", "n_authors": 2, "title": "Heme and FLVCR-related transporter families SLC48 and SLC49.", "abstract": "Heme is critical for a variety of cellular processes, but excess intracellular heme may result in oxidative stress and membrane injury. Feline leukemia virus subgroup C receptor (FLVCR1), a member of the SLC49 family of four paralogous genes, is a cell surface heme exporter, essential for erythropoiesis and systemic iron homeostasis. Disruption of FLVCR1 function blocks development of erythroid progenitors, likely due to heme toxicity. Mutations of SLC49A1 encoding FLVCR1 are noted in patients with a rare neurodegenerative disorder: posterior column ataxia with retinitis pigmentosa. FLVCR2 is highly homologous to FLVCR1 and may function as a cellular heme importer. Mutations of SLC49A2 encoding FLVCR2 are observed in Fowler syndrome, a rare proliferative vascular disorder of the brain. The functions of the remaining members of the SLC49 family, MFSD7 and DIRC2 (encoded by the SLC49A3 and SLC49A4 genes), are unknown, although the latter is implicated in hereditary renal carcinomas. SLC48A1 (heme responsive gene-1, HRG-1), the sole member of the SLC48 family, is associated with the endosome and appears to transport heme from the endosome into the cytosol.", "journal": "Molecular aspects of medicine", "doi": "10.1016/j.mam.2012.07.013", "deposited_data": "Sim", "nuccore_ids": "1802446929, 1802446927, 1802446894, 1802446883, 1677538798, 1677531304, 1677500057, 2462599311, 2462599310, 2462599308, 2462599307, 2462599305, 2462599303, 2462599301, 2462599299, 2462599297, 2462599295, 2462599293, 2462599291, 2462599289, 2462599287, 2462599285, 2462599283, 2462599281, 2462599279, 2462599277, 2462532944, 2462532942, 2462532940, 2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217352341, 2217352340, 2217352339, 2217352337, 2217352335, 2217352333, 2217352331, 2217352330, 2217352328, 2217352326, 2217352324, 2217352323, 2217352321, 2217352319, 2217352317, 2217352315, 2217352313, 2217289914, 2217289912, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1802446929, 1802446927, 1802446894, 1802446883, 1677538798, 1677531304, 1677500057, 1675021395, 1519316194, 1519315556, 1519311386, 1034580522", "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23482254", "author": "Martínez-Díaz VL", "n_authors": 6, "title": "Prevalence and co-infection of haemotropic mycoplasmas in Portuguese cats by real-time polymerase chain reaction.", "abstract": "The diagnosis of feline haemoplasmosis has improved over the years, with several techniques enabling a clear and specific diagnosis, and where polymerase chain reaction (PCR) is considered as the 'gold standard'. The aim of this study was to survey the prevalence of feline haemoplasmas in 320 cats from the north-central region of Portugal by the use of real-time PCR, as well as to evaluate any associations between infection, clinical presentation and risk factors. The overall prevalence of infection by feline haemoplasmas was 43.43% (139/320), where 41.56% (133/320) corresponded to Candidatus Mycoplasma haemominutum (CMhm), 12.81% (41/320) to Mycoplasma haemofelis (Mhf), 4.38% (14/320) to Candidatus Mycoplasma haematoparvum and 1.25% (4/320) to Candidatus Mycoplasma turicensis. Almost 13% (47/320) of the samples were co-infected, with the most common co-infection being CMhm and Mhf (23.74%). Infection was found statistically significant with feline immunodeficiency/feline leukaemia virus status (P = 0.034), but no significant association was found for breed, sex, fertility status (neutered/spayed/entire), age, clinical status, living conditions (in/outdoor), anaemia status, or the presence/absence of ticks or fleas. Cats from north-central Portugal are infected with all the known feline haemoplasma species, with CMhm being the most common one. Prevalence of all feline haemoplasmas was higher than that reported previously in cats from other European countries, but similar to that described in Portugal for dogs. These data provide a better perspective regarding Mycoplasma species infection in Europe, and new information that helps us better understand feline haemoplasmosis.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X13480985", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23405366", "author": "Stewart H", "n_authors": 4, "title": "Complete genome sequences of two feline leukemia virus subgroup B isolates with novel recombination sites.", "abstract": "It is generally accepted that all primary isolates of feline leukemia virus (FeLV) contain a subgroup A virus (FeLV-A) that is essential for transmission. In contrast, FeLV-B is thought to arise de novo in the infected animal through RNA recombination events with endogenous FeLV transcripts, presumably through copackaging of RNA from endogenous FeLV and exogenous FeLV-A. Here, we report the complete genome sequences of two novel strains of FeLV-B (FeLV-2518 and FeLV-4314) that were isolated in the absence of FeLV-A. The env genes of these isolates have been characterized previously, and the 3' recombination sites have been identified. We describe herein the 5' recombination breakpoints of each virus. These breakpoints were found to be within the signal peptide of the env gene and the reverse transcriptase-coding region, respectively. This is the first report of a recombination site within the pol gene of an FeLV-B genome and the first genetic characterization of multiple independently arising FeLV-B isolates that have been identified without a functional FeLV-A ancestral virus.", "journal": "Genome announcements", "doi": "10.1128/genomeA.00036-12", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23321692", "author": "Stuetzer B", "n_authors": 4, "title": "A trial with 3'-azido-2',3'-dideoxythymidine and human interferon-α in cats naturally infected with feline leukaemia virus.", "abstract": "Feline leukaemia virus (FeLV) infection is still one of the leading causes of infection-related deaths in domestic cats. Treatment with various drugs has been attempted, but none has resulted in cure or complete virus elimination. Human interferon-α2a (huIFN-α2a) and 3'-azido-2',3'-dideoxythymidine (AZT) have been proven to decrease antigenaemia in cats infected experimentally with FeLV. The purpose of this study was to assess the efficacy of huIFN-α2a, AZT and a combination of both drugs in cats infected naturally with FeLV in a placebo-controlled double-blinded trial. Fourty-four FeLV-infected cats in which free FeLV p27 antigen was detected in serum by enzyme-linked immunosorbent assay were included in the study. Cats were assigned to one of four treatment groups that received either high dose huIFN-α2a (10(5) IU/kg q24h; 12 cats), AZT (5 mg/kg q12h; 10 cats, both of these treatments (12 cats) or placebo (10 cats). All cats were treated for 6 weeks. Clinical variables, including stomatitis, and laboratory parameters, such as CD4(+) and CD8(+) counts and serum FeLV p 27 antigen concentration, were recorded throughout the treatment period. No significant difference among the groups was observed during the treatment period for any of the parameters. Aside from anaemia in one cat treated with AZT, no adverse effects were observed. It was not possible to demonstrate efficacy of huIFN-α2a or AZT alone or together in cats infected naturally with FeLV when given according to this regimen for 6 weeks; however, no notable side effects were detected.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X12473468", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23290868", "author": "Magden E", "n_authors": 7, "title": "Acute virulent infection with feline immunodeficiency virus (FIV) results in lymphomagenesis via an indirect mechanism.", "abstract": "Four cats (24%) experimentally infected with FIV unexpectedly developed neoplastic changes within four months of inoculation. While FIV has previously been associated with neoplasia, the rapidity and high attack rate seen here is highly unusual. PCR for antigen receptor rearrangements (PARR) detected clonally rearranged T cells in two animals diagnosed with B cell follicular lymphoma by classical means. All cats were negative for feline leukemia virus; gamma-herpesvirus DNA was not amplified using degenerate primers. FIV proviral load in neoplastic tissue was two orders of magnitude lower than in the periphery, lower in neoplastic vs non-neoplastic lymph node, and clonal integration was not detected. We hypothesize that neoplasia was secondary to FIV immune dysregulation, and show that PARR can augment our capacity to phenotype these tumors and distinguish follicular hyperplasia from lymphoma. Age of exposure and relative virulence of the inoculum likely contributed to this unusual presentation of FIV infection.", "journal": "Virology", "doi": "10.1016/j.virol.2012.12.003", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23289366", "author": "Chhetri BK", "n_authors": 4, "title": "Comparison of the geographical distribution of feline immunodeficiency virus and feline leukemia virus infections in the United States of America (2000-2011).", "abstract": "Although feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) have similar risk factors and control measures, infection rates have been speculated to vary in geographic distribution over North America. Since both infections are endemic in North America, it was assumed as a working hypothesis that their geographic distributions were similar. Hence, the purpose of this exploratory analysis was to investigate the comparative geographical distribution of both viral infections. Counts of FIV (n=17,108) and FeLV (n=30,017) positive serology results (FIV antibody and FeLV ELISA) were obtained for 48 contiguous states and District of Columbia of the United States of America (US) from the IDEXX Laboratories website. The proportional morbidity ratio of FIV to FeLV infection was estimated for each administrative region and its geographic distribution pattern was visualized by a choropleth map. Statistical evidence of an excess in the proportional morbidity ratio from unity was assessed using the spatial scan test under the normal probability model. This study revealed distinct spatial distribution patterns in the proportional morbidity ratio suggesting the presence of one or more relevant and geographically varying risk factors. The disease map indicates that there is a higher prevalence of FIV infections in the southern and eastern US compared to FeLV. In contrast, FeLV infections were observed to be more frequent in the western US compared to FIV. The respective excess in proportional morbidity ratio was significant with respect to the spatial scan test (p < 0.05). The observed variability in the geographical distribution of the proportional morbidity ratio of FIV to FeLV may be related to the presence of an additional or unique, but yet unknown, spatial risk factor. Putative factors may be geographic variations in specific virus strains and rate of vaccination. Knowledge of these factors and the geographical distributions of these infections can inform recommendations for testing, management and prevention. However, further studies are required to investigate the potential association of these factors with FIV and FeLV.", "journal": "BMC veterinary research", "doi": "10.1186/1746-6148-9-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23269813", "author": "Mendoza R", "n_authors": 3, "title": "Disruption of thiamine uptake and growth of cells by feline leukemia virus subgroup A.", "abstract": "Feline leukemia virus (FeLV) is still a major cause of morbidity and mortality in domestic cats and some wild cats despite the availability of relatively effective vaccines against the virus. FeLV subgroup A (FeLV-A) is transmitted in natural infections, and FeLV subgroups B, C, and T can evolve directly from FeLV-A by mutation and/or recombination with endogenous retroviruses in domestic cats, resulting in a variety of pathogenic outcomes. The cell surface entry receptor for FeLV-A is a putative thiamine transporter (THTR1). Here, we have addressed whether FeLV-A infection might disrupt thiamine uptake into cells and, because thiamine is an essential nutrient, whether this disruption might have pathological consequences. First, we cloned the cat ortholog of the other of the two known thiamine transporters in mammals, THTR2, and we show that feline THTR1 (feTHTR1) and feTHTR2 both mediate thiamine uptake, but feTHTR2 does not function as a receptor for FeLV-A. We found that feTHTR1 is widely expressed in cat tissues and in cell lines, while expression of feTHTR2 is restricted. Thiamine uptake mediated by feTHTR1 was indeed blocked by FeLV-A infection, and in feline fibroblasts that naturally express feTHTR1 and not feTHTR2, this blockade resulted in a growth arrest at physiological concentrations of extracellular thiamine. The growth arrest was reversed at high extracellular concentrations of thiamine. Our results show that FeLV-A infection can indeed disrupt thiamine uptake with pathological consequences. A prediction of these experiments is that raising the plasma levels of thiamine in FeLV-infected cats may ameliorate the pathogenic effects of infection.", "journal": "Journal of virology", "doi": "10.1128/JVI.03203-12", "deposited_data": "Sim", "nuccore_ids": "523704407, 410695830, 90403621, 89112747, 2131068042, 2131002666, 2131002664, 2131002662, 2131002661, 2131002660, 2131002659, 2131002657, 2131002656, 2131002654, 2131002653, 2131002652, 2131002651, 523704407, 90403621", "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23249763", "author": "Denner J", "n_authors": 1, "title": "Immunising with the transmembrane envelope proteins of different retroviruses including HIV-1: a comparative study.", "abstract": "The induction of neutralizing antibodies is a promising way to prevent retrovirus infections. Neutralizing antibodies are mainly directed against the envelope proteins, which consist of two molecules, the surface envelope (SU) protein and the transmembrane envelope (TM) protein. Antibodies broadly neutralizing the human immunodeficiencvy virus-1 (HIV-1) and binding to the TM protein gp41 of the virus have been isolated from infected individuals. Their epitopes are located in the membrane proximal external region (MPER). Since there are difficulties to induce such neutralizing antibodies as basis for an effective AIDS vaccine, we performed a comparative analysis immunising with the TM proteins of different viruses from the family Retroviridae. Both subfamilies, the Orthoretrovirinae and the Spumaretrovirinae were included. In this study, the TM proteins of three gammaretroviruses including (1) the porcine endogenous retrovirus (PERV), (2) the Koala retrovirus (KoRV), (3) the feline leukemia virus (FeLV), of two lentiviruses, HIV-1, HIV-2, and of two spumaviruses, the feline foamy virus (FFV) and the primate foamy virus (PFV) were used for immunisation. Whereas in all immunisation studies binding antibodies were induced, neutralizing antibodies were only found in the case of the gammaretroviruses. The induced antibodies were directed against the MPER and the fusion peptide proximal region (FPPR) of their TM proteins; however only the antibodies against the MPER were neutralizing. Most importantly, the epitopes in the MPER were localized in the same position as the epitopes of the antibodies broadly neutralizing HIV-1 in the TM protein gp41 of HIV-1, indicating that the MPER is an effective target for the neutralization of retroviruses.", "journal": "Human vaccines & immunotherapeutics", "doi": "10.4161/hv.23221", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23122808", "author": "Gil S", "n_authors": 9, "title": "Relevance of feline interferon omega for clinical improvement and reduction of concurrent viral excretion in retrovirus infected cats from a rescue shelter.", "abstract": "Feline Immnunodeficiency (FIV) and Feline Leukemia (FeLV) viruses are common infectious agents in stray cats and shelter environments. Recombinant feline interferon-ω (rFeIFNω) has shown an antiviral action not only against FIV and FeLV but also against herpesvirus (FHV-1) and calicivirus (FCV). Sixteen naturally infected FIV/FeLV cats were followed during rFeIFNω therapy in order to monitor clinical signs and to correlate with excretion of concomitant viruses (FCV, FHV-1, feline coronavirus (FCoV) and parvovirus (FPV)). Cats were submitted to clinical evaluations and concomitant virus excretion assessement. Comparing D0-D65, 10/16 cats improved clinical scores. Of the 10 cats positive for FHV-1 on D0, 4 were negative and 6 reduced viral loads. Of the 11 FCoV positive cats, 9 reduced viral loads. The 13 FCV positive cats and the FPV positive cat were negative on D65. In conclusion, rFeIFNω improves clinical signs and reduces concurrent viral excretion in naturally infected retroviral cats.", "journal": "Research in veterinary science", "doi": "10.1016/j.rvsc.2012.09.025", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "22992020", "author": "Starzyński RR", "n_authors": 10, "title": "Ferroportin expression in haem oxygenase 1-deficient mice.", "abstract": "HO1 (haem oxygenase 1) and Fpn (ferroportin) are key proteins for iron recycling from senescent red blood cells and therefore play a major role in controlling the bioavailability of iron for erythropoiesis. Although important aspects of iron metabolism in HO1-deficient (Hmox1-/-) mice have already been revealed, little is known about the regulation of Fpn expression and its role in HO1 deficiency. In the present study, we characterize the cellular and systemic factors influencing Fpn expression in Hmox1-/- bone marrow-derived macrophages and in the liver and kidney of Hmox1-/- mice. In Hmox1-/- macrophages, Fpn protein was relatively highly expressed under high levels of hepcidin in culture medium. Similarly, despite high hepatic hepcidin expression, Fpn is still detected in Kupffer cells and is also markedly enhanced at the basolateral membrane of the renal tubules of Hmox1-/- mice. Through the activity of highly expressed Fpn, epithelial cells of the renal tubules probably take over the function of impaired system of tissue macrophages in recycling iron accumulated in the kidney. Moreover, although we have found increased expression of FLVCR (feline leukaemia virus subgroup C receptor), a haem exporter, in the kidneys of Hmox1-/- mice, haem level was increased in these organs. Furthermore, we show that iron/haem-mediated toxicity are responsible for renal injury documented in the kidneys of Hmox1-/- mice.", "journal": "The Biochemical journal", "doi": "10.1042/BJ20121139", "deposited_data": "Sim", "nuccore_ids": "1907069747, 1907069746, 195947362, 124248584", "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "22867855", "author": "Willett BJ", "n_authors": 2, "title": "Feline leukaemia virus: half a century since its discovery.", "abstract": "In the early 1960s, Professor William (Bill) F.H. Jarrett was presented with a time-space cluster of cats with lymphoma identified by a local veterinary practitioner, Harry Pfaff, and carried out experiments to find if the condition might be caused by a virus, similar to lymphomas noted previously in poultry and mice. In 1964, the transmission of lymphoma in cats and the presence of virus-like particles that resembled 'the virus of murine leukaemias' in the induced tumours were reported in Nature. These seminal studies initiated research on feline leukaemia virus (FeLV) and launched the field of feline retrovirology. This review article considers the way in which some of the key early observations made by Bill Jarrett and his coworkers have developed in subsequent years and discusses progress that has been made in the field since FeLV was first discovered.", "journal": "Veterinary journal (London, England : 1997)", "doi": "10.1016/j.tvjl.2012.07.004", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "22857007", "author": "Tiao N", "n_authors": 10, "title": "An investigation into the seroprevalence of Toxoplasma gondii, Bartonella spp., feline immunodeficiency virus (FIV), and feline leukaemia virus (FeLV) in cats in Addis Ababa, Ethiopia.", "abstract": "Toxoplasma gondii and Bartonella spp. are zoonotic pathogens of cats. Feline immunodeficiency virus (FIV), and feline leukaemia virus (FeLV) are immunosuppressive viruses of cats that can affect T. gondii oocyst shedding. In this study, the prevalence of antibodies to T. gondii, Bartonella spp., FIV, as well as FeLV antigens were determined in sera from feral cats (Felis catus) from Addis Ababa, Ethiopia. Using the modified agglutination test, IgG antibodies to T. gondii were found in 41 (85.4%) of the 48 cats with titres of 1:25 in one, 1:50 in one, 1:200 in six, 1:400 in six, 1:800 in six, 1:1600 in eight, and 1:3200 in 13 cats. Toxoplasma gondii IgM antibodies were found in 11/46 cats tested by ELISA, suggesting recent infection. Antibodies to Bartonella spp. were found in five (11%) of 46 cats tested. Antibodies to FIV or FeLV antigen were not detected in any of the 41 cats tested. The results indicate a high prevalence of T. gondii and a low prevalence of Bartonella spp. infection in cats in Ethiopia.", "journal": "Epidemiology and infection", "doi": "10.1017/S0950268812001707", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "25686080", "author": "Muchaamba F", "n_authors": 5, "title": "A survey of feline leukaemia virus infection of domestic cats from selected areas in Harare, Zimbabwe.", "abstract": "A cross-sectional study was conducted to detect the feline leukaemia virus (FeLV) p27 antigen and to determine risk factors and the haematological changes associated with infection in domestic cats in Zimbabwe. Sera were collected for detection of the p27 antigen, urea, creatinine, alanine aminotransferase and gamma-glutamyl transferase levels, whilst whole blood was collected for haematology. FeLV p27 antigen was detected using a rapid enzyme-linked immunosorbent assay (ELISA) test kit. Data on risk factors were analysed using a logistic regression model. Of the 100 cats tested, 41% (95% CI: 31.19% - 50.81%) (41/100) were positive for the FeLV p27 antigen. Sex and health status of cats were not significantly (p &gt; 0.05) associated with infection. Intact cats (OR = 9.73), those living in multicat housing (OR = 5.23) and cats that had access to outdoor life (OR = 35.5) were found to have higher odds of infection compared with neutered cats, those living in single-cat housing, and without access to outdoor life, respectively. Biochemistry and haematology revealed no specific changes. The results showed that FeLV infection was high in sampled cats, providing evidence of active infection. Thus, it would be prudent to introduce specific control measures for FeLV infection in Zimbabwe.", "journal": "Journal of the South African Veterinary Association", "doi": "10.4102/jsava.v85i1.1126", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "25610576", "author": "Najafi H", "n_authors": 5, "title": "Molecular and clinical study on prevalence of feline herpesvirus type 1 and calicivirus in correlation with feline leukemia and immunodeficiency viruses.", "abstract": "Upper respiratory tract diseases (URTD) are common clinical problem in cats worldwide. Feline calicivirus (FCV) and feline herpesvirus type 1 (FHV-1) are the main primary pathogens. Feline immunodeficiency virus (FIV) and Feline leukemia virus (FeLV) are also among the most common infectious diseases of cats which suppress the immunity. Oropharyngeal and conjunctival swabs and blood samples were taken from 16 cats with clinical signs of URTD and 26 clinically healthy cats. PCR and RT-PCR were used to detect FHV/FIV or FCV/FeLV infections, respectively. Feline calicivirus was detected in all cats with URTD and 87.00% and 93.00% of them were positive for FIV and FeLV, respectively. Feline herpesvirus rate of infection was 43.00% in sick cats. In clinically normal cats, prevalence rates of FCV and FHV were about 50.00%, but FIV and FeLV rates (42.00% and 65.00% respectively) were higher compared to other studies. Stomatitis was observed in 50.00% of cats with URTD. The main causative agent of corneal ulcers is FHV-1, but in 50.00% of cats with corneal ulcers, FCV was detected alone. It seems new variants of Caliciviruses are the main causative agents to attack uncommon tissues like cornea, although retroviral infections may be in the background of these various signs. The high retroviral prevalence may be due to existence of large population of stray cats. This is the first molecular study of FeLV and FCV in Iran and seems that FCV and FHV prevalence rates in FIV or FeLV infected cats is more than other non-infected ones.", "journal": "Veterinary research forum : an international quarterly journal", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "25506469", "author": "Bande F", "n_authors": 4, "title": "Molecular detection, phylogenetic analysis, and identification of transcription motifs in feline leukemia virus from naturally infected cats in malaysia.", "abstract": "A nested PCR assay was used to determine the viral RNA and proviral DNA status of naturally infected cats. Selected samples that were FeLV-positive by PCR were subjected to sequencing, phylogenetic analysis, and motifs search. Of the 39 samples that were positive for FeLV p27 antigen, 87.2% (34/39) were confirmed positive with nested PCR. FeLV proviral DNA was detected in 38 (97.3%) of p27-antigen negative samples. Malaysian FeLV isolates are found to be highly similar with a homology of 91% to 100%. Phylogenetic analysis revealed that Malaysian FeLV isolates divided into two clusters, with a majority (86.2%) sharing similarity with FeLV-K01803 and fewer isolates (13.8%) with FeLV-GM1 strain. Different enhancer motifs including NF-GMa, Krox-20/WT1I-del2, BAF1, AP-2, TBP, TFIIF-beta, TRF, and TFIID are found to occur either in single, duplicate, triplicate, or sets of 5 in different positions within the U3-LTR-gag region. The present result confirms the occurrence of FeLV viral RNA and provirus DNA in naturally infected cats. Malaysian FeLV isolates are highly similar, and a majority of them are closely related to a UK isolate. This study provides the first molecular based information on FeLV in Malaysia. Additionally, different enhancer motifs likely associated with FeLV related pathogenesis have been identified.", "journal": "Veterinary medicine international", "doi": "10.1155/2014/760961", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "25307685", "author": "Chatzis MK", "n_authors": 11, "title": "Evaluation of indirect immunofluorescence antibody test and enzyme-linked immunosorbent assay for the diagnosis of infection by Leishmania infantum in clinically normal and sick cats.", "abstract": "Cats that live in areas where canine and human leishmaniosis due to Leishmania infantum is endemic may become infected and may develop anti-Leishmania antibodies. In this study 50 clinically normal and 50 cats with cutaneous and/or systemic signs that lived in an endemic area and had been previously examined for infection by L. infantum using PCR in four different tissues were serologically tested for the presence of anti-Leishmania IgG (IFAT and ELISA) and IgM (IFAT). The aim was to compare the results of IFAT, ELISA and PCR and to investigate the possible associations between seropositivity to Leishmania spp and signalment, living conditions, season of sampling, health status of the cats, and seropositivity to other infectious agents. Low concentrations of anti-Leishmania IgG were detected by IFAT in 10% of the cats and by ELISA in 1%, whereas anti-Leishmania IgM were detected by IFAT in 1%. There was disagreement between the results of IFAT and ELISA for anti-Leishmania IgG (P = 0.039) and between all serological tests and PCR (P < 0.001). The diagnostic sensitivity of all serological tests, using PCR as the gold standard, was very low, but ELISA and IFAT for anti-Leishmania IgM had 100% specificity. The diagnostic sensitivity of all serological tests could not be improved by changing the cut-off values. Seropositivity for Leishmania spp was not associated with signalment, living conditions, season of sampling and health status of the cats or with seropositivity to feline leukemia virus, feline immunodeficiency virus, feline coronavirus, Toxoplasma gondii and Bartonella henselae. In conclusion, because of their low sensitivity and very high specificity two of the evaluated serological tests (ELISA for anti-Leishmania IgG and IFAT for anti-Leishmania IgM) may be useless as population screening tests but valuable for diagnosing feline infection by L. infantum.", "journal": "Experimental parasitology", "doi": "10.1016/j.exppara.2014.10.004", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "25285933", "author": "Kornya MR", "n_authors": 5, "title": "Association between oral health status and retrovirus test results in cats.", "abstract": "To determine associations between oral health status and seropositivity for FIV or FeLV in cats. Cross-sectional survey. 5,179 cats. Veterinarians at veterinary clinics and animal shelters completed online training on oral conditions in cats and then scored oral health status of cats with no known history of vaccination against FIV. Age, sex, and results of an ELISA for retroviruses were recorded. Results were analyzed by means of standard logistic regression with binary outcome. Of 5,179 cats, 237 (4.6%) and 186 (3.6%) were seropositive for FIV and FeLV, respectively, and of these, 12 (0.2%) were seropositive for FIV and FeLV. Of all 5,179 cats, 1,073 (20.7%) had gingivitis, 576 (11.1%) had periodontitis, 203 (3.9%) had stomatitis, and 252 (4.9%) had other oral conditions (overall oral disease prevalence, 2,104/5,179 [40.6%]). Across all age categories, inflammatory oral disease was associated with a significantly higher risk of a positive test result for FIV, compared with the seropositivity risk associated with other oral diseases or no oral disease. Stomatitis was most highly associated with risk of FIV seropositivity. Cats with any oral inflammatory disease were more likely than orally healthy cats to have a positive test result for FeLV. Increasing age was associated with a higher prevalence of oral disease in retrovirus-seronegative cats. Inflammatory oral disease was associated with an increased risk of seropositivity for retroviruses in naturally infected cats. Therefore, retroviral status of cats with oral inflammatory disease should be determined and appropriate management initiated.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.245.8.916", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "25281810", "author": "Biegańska M", "n_authors": 3, "title": "Fungal colonization - an additional risk factor for diseased dogs and cats?", "abstract": "The aim of the presented mini-review is to review the literature data referring to opportunistic mycoses in pet dogs and cats suffering from other concurrent diseases, comparable to human medical disorders with high risk of secondary mycoses. This review also presents the preliminary results of a project aimed at understanding the fungal colonization and occurrence of secondary mycoses in pets suffering from metabolic disorders, neoplasms and viral infections. The incidence of opportunistic mycoses is higher in such individuals, mostly because of their impaired immunity. The main risk factors are primary and secondary types of immunodeficiency connected with anti-cancer treatment or neoplastic disease itself. Moreover, literature data and the results of our investigations show that Candida yeasts are prevalent among diabetic animals and indicate that these fungi are the main etiological agents of secondary infections of the oral cavity, GI and urogenital tracts. Other important conditions possibly favoring the development of mycoses are concurrent infections of cats with FeLV and FIV viruses. Thus, in all cases of the mentioned underlying diseases, animals should be carefully monitored by repeated mycological examination, together with inspection of other parameters. Also, the prophylaxis of opportunistic mycoses should be carefully considered alike other factors influencing the prognosis and the outcome of primary diseases.", "journal": "Annals of parasitology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "25173082", "author": "de Castro FL", "n_authors": 10, "title": "Analysis of single-nucleotide polymorphisms in the APOBEC3H gene of domestic cats (Felis catus) and their association with the susceptibility to feline immunodeficiency virus and feline leukemia virus infections.", "abstract": "Feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) are widely distributed retroviruses that infect domestic cats (Felis catus). Restriction factors are proteins that have the ability to hamper retroviruses' replication and are part of the conserved mechanisms of anti-viral immunity of mammals. The APOBEC3 protein family is the most studied class of restriction factors; they are cytidine deaminases that generate hypermutations in provirus DNA during reverse transcription, thus causing hypermutations in the viral genome, hindering virus replication. One of the feline APOBEC3 genes, named APOBEC3H, encodes two proteins (APOBEC3H and APOBEC3CH). In other mammals, APOBEC3H single-nucleotide polymorphisms (SNPs) can alter the stability and cellular localization of the encoded protein, thus influencing its subcellular localization and reducing its anti-viral effect. In cats, the association of APOBEC3H SNPs with susceptibility to retroviral infections was not yet demonstrated. Therefore, this study aimed the investigation on the variability of APOBEC3H and the possible association with FIV/FeLV infections. DNA obtained from whole blood of fifty FIV- and/or FeLV-infected cats and fifty-nine FIV- and/or FeLV-uninfected cats were used as templates to amplify two different regions of the APOBEC3H, with subsequent sequencing and analysis. The first region was highly conserved among all samples, while in the second, six single-nucleotide variation points were identified. One of the SNPs, A65S (A65I), was significantly correlated with the susceptibility to FIV and/or FeLV infections. On the other hand, the haplotype analysis showed that the combination \"GGGGCC\" was positively correlated with the lack of FIV and/or FeLV infections. Our results indicate that, as previously shown in other mammals, variability of restriction factors may contribute to susceptibility of domestic cats to retroviral infections; however, these results should be confirmed by more extensive analysis and in vitro experiments.", "journal": "Infection, genetics and evolution : journal of molecular epidemiology and evolutionary genetics in infectious diseases", "doi": "10.1016/j.meegid.2014.08.024", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "25143822", "author": "Tamazian G", "n_authors": 25, "title": "Annotated features of domestic cat - Felis catus genome.", "abstract": "Domestic cats enjoy an extensive veterinary medical surveillance which has described nearly 250 genetic diseases analogous to human disorders. Feline infectious agents offer powerful natural models of deadly human diseases, which include feline immunodeficiency virus, feline sarcoma virus and feline leukemia virus. A rich veterinary literature of feline disease pathogenesis and the demonstration of a highly conserved ancestral mammal genome organization make the cat genome annotation a highly informative resource that facilitates multifaceted research endeavors. Here we report a preliminary annotation of the whole genome sequence of Cinnamon, a domestic cat living in Columbia (MO, USA), bisulfite sequencing of Boris, a male cat from St. Petersburg (Russia), and light 30× sequencing of Sylvester, a European wildcat progenitor of cat domestication. The annotation includes 21,865 protein-coding genes identified by a comparative approach, 217 loci of endogenous retrovirus-like elements, repetitive elements which comprise about 55.7% of the whole genome, 99,494 new SNVs, 8,355 new indels, 743,326 evolutionary constrained elements, and 3,182 microRNA homologues. The methylation sites study shows that 10.5% of cat genome cytosines are methylated. An assisted assembly of a European wildcat, Felis silvestris silvestris, was performed; variants between F. silvestris and F. catus genomes were derived and compared to F. catus. The presented genome annotation extends beyond earlier ones by closing gaps of sequence that were unavoidable with previous low-coverage shotgun genome sequencing. The assembly and its annotation offer an important resource for connecting the rich veterinary and natural history of cats to genome discovery.", "journal": "GigaScience", "doi": "10.1186/2047-217X-3-13", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "25115222", "author": "Deshuillers P", "n_authors": 3, "title": "Pelger-Huët anomaly in a cat.", "abstract": "A 14-year-old, spayed female Domestic Shorthair cat was referred to the Purdue University Veterinary Teaching Hospital (PUVTH) for iodine 131 treatment of hyperthyroidism. Upon arrival, a biochemistry profile and a CBC were performed. Approximately 50% of the neutrophils and all the eosinophils observed were hyposegmented with a mature, condensed chromatin pattern. Nuclei had a band to \"dumbbell\" shape, and rarely a round shape, suggesting a Pelger-Huët anomaly or a pseudo Pelger-Huët. Based on both a negative FeLV and FIV tests, the absence of any clinical signs to support an inflammatory process, and the persistence of this granulocytic morphology 6 months after its previous admission to the PUVTH, a diagnosis of Pelger-Huët anomaly was established in this cat.", "journal": "Veterinary clinical pathology", "doi": "10.1111/vcp.12176", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "25075825", "author": "Hoehne SN", "n_authors": 6, "title": "Placement of a caudal vena cava stent for treatment of Budd-Chiari-like syndrome in a 4-month-old Ragdoll cat.", "abstract": "A 16-week-old 1.5-kg (3.3-lb) sexually intact male Ragdoll kitten that had a 9-week history of marked modified transudate ascites was evaluated. A membranous obstruction of the caudal vena cava at the cranial aspect of the liver was identified via CT angiography. Physical examination findings included a markedly distended abdomen and panting. Testing for circulating FIV antibody and FeLV antigen, a PCR assay for feline coronavirus performed on a sample of peritoneal fluid, and fecal flotation yielded negative results. A diagnosis of Budd-Chiari-like syndrome secondary to a membranous obstruction of the caudal vena cava was made. The cat was anesthetized, and the subhepatic portion of the caudal vena cava was identified and accessed via median celiotomy and direct venipuncture. A 6F 8 × 24-mm balloon-expandable nitinol biliary stent was placed across the stenotic area under fluoroscopic guidance. The patient remained free of clinical signs at the last follow-up 13 months following the procedure. Budd-Chiari-like syndrome is a rare phenomenon in veterinary medicine, and congenital malformations should be considered in young feline patients with ascites. Computed tomography angiography proved to be a helpful adjunctive imaging technique to establish a diagnosis in this case. To the authors' knowledge, this is the first report of successful treatment of a congenital caudal vena cava obstruction by means of stent placement in a juvenile cat.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.245.4.414", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "25055815", "author": "Becker DJ", "n_authors": 2, "title": "Too much of a good thing: resource provisioning alters infectious disease dynamics in wildlife.", "abstract": "Provisioning of abundant food resources in human-altered landscapes can have profound effects on wildlife ecology, with important implications for pathogen transmission. While empirical studies have quantified the effects of provisioning on host behaviour and immunology, the net interactive effect of these components on host-pathogen dynamics is unknown. We use simple compartmental models to investigate how provisioning-induced changes to host demography, contact behaviour and immune defence influence pathogen invasion and persistence. We show that pathogen invasion success and equilibrium prevalence depend critically on how provisioning affects host immune defence and that moderate levels of provisioning can lead to drastically different outcomes of pathogen extinction or maximizing prevalence. These results highlight the need for further empirical studies to fully understand how provisioning affects pathogen transmission in urbanized environments.", "journal": "Biology letters", "doi": "10.1098/rsbl.2014.0309", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "25010275", "author": "Beatty JA", "n_authors": 11, "title": "Felis catus gammaherpesvirus 1; a widely endemic potential pathogen of domestic cats.", "abstract": "Felis catus gammaherpesvirus 1 (FcaGHV1), recently discovered in the USA, was detected in domestic cats in Australia (11.4%, 95% confidence interval 5.9-19.1, n=110) and Singapore (9.6%, 95% confidence interval 5.9-14.6, n=176) using qPCR. FcaGHV1 qPCR positive cats were 2.8 times more likely to be sick than healthy. Risk factors for FcaGHV1 detection included being male, increasing age and coinfection with pathogenic retroviruses, feline immunodeficiency virus (FIV) or feline leukaemia virus. FcaGHV1 DNA was detected in multiple tissues from infected cats with consistently high virus loads in the small intestine. FcaGHV1 viral load was significantly higher in FIV-infected cats compared with matched controls, mimicking increased Epstein-Barr virus loads in human immunodeficiency virus-infected humans. FcaGHV1 is endemic in distant geographic regions and is associated with being sick and with coinfections. Horizontal transmission of FcaGHV1 is supported, with biting being a plausible route. A pathogenic role for FcaGHV1 in domestic cats is supported.", "journal": "Virology", "doi": "10.1016/j.virol.2014.05.007", "deposited_data": "Sim", "nuccore_ids": "662862676, 662862674", "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24947444", "author": "Cao C", "n_authors": 6, "title": "Placental heme receptor LRP1 correlates with the heme exporter FLVCR1 and neonatal iron status.", "abstract": "LDL receptor-related protein 1 (LRP1) is a transmembrane receptor highly expressed in human placenta. It was recently found to be the receptor for heme and its plasma-binding protein hemopexin (Hx) and is integral to systemic heme clearance. Little is known about systemic concentrations of Hx during pregnancy and whether maternal Hx and placental LRP1 contributes to fetal iron (Fe) homeostasis during pregnancy. We hypothesized that placental LRP1 would be upregulated in maternal/neonatal Fe insufficiency and would be related to maternal circulating Hx. Placental LRP1 expression was assessed in 57 pregnant adolescents (14-18 years) in relationship with maternal and cord blood Fe status indicators (hemoglobin (Hb), serum ferritin, transferrin receptor), the Fe regulatory hormone hepcidin and serum Hx. Hx at mid-gestation correlated positively with Hb at mid-gestation (r=0.35, P=0.02) and Hx at delivery correlated positively with cord hepcidin (r=0.37, P=0.005). Placental LRP1 protein expression was significantly higher in women who exhibited greater decreases in serum Hx from mid-gestation to term (r=0.28, P=0.04). Significant associations were also found between placental LRP1 protein with cord hepcidin (r=-0.29, P=0.03) and placental heme exporter feline leukemia virus C receptor 1 (r=0.34, P=0.03). Our data are consistent with a role for placental heme Fe utilization in supporting fetal Fe demands.", "journal": "Reproduction (Cambridge, England)", "doi": "10.1530/REP-14-0053", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1653960851, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24934262", "author": "Polak KC", "n_authors": 5, "title": "Infectious diseases in large-scale cat hoarding investigations.", "abstract": "Animal hoarders accumulate animals in over-crowded conditions without adequate nutrition, sanitation, and veterinary care. As a result, animals rescued from hoarding frequently have a variety of medical conditions including respiratory infections, gastrointestinal disease, parasitism, malnutrition, and other evidence of neglect. The purpose of this study was to characterize the infectious diseases carried by clinically affected cats and to determine the prevalence of retroviral infections among cats in large-scale cat hoarding investigations. Records were reviewed retrospectively from four large-scale seizures of cats from failed sanctuaries from November 2009 through March 2012. The number of cats seized in each case ranged from 387 to 697. Cats were screened for feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) in all four cases and for dermatophytosis in one case. A subset of cats exhibiting signs of upper respiratory disease or diarrhea had been tested for infections by PCR and fecal flotation for treatment planning. Mycoplasma felis (78%), calicivirus (78%), and Streptococcus equi subspecies zooepidemicus (55%) were the most common respiratory infections. Feline enteric coronavirus (88%), Giardia (56%), Clostridium perfringens (49%), and Tritrichomonas foetus (39%) were most common in cats with diarrhea. The seroprevalence of FeLV and FIV were 8% and 8%, respectively. In the one case in which cats with lesions suspicious for dermatophytosis were cultured for Microsporum canis, 69/76 lesional cats were culture-positive; of these, half were believed to be truly infected and half were believed to be fomite carriers. Cats from large-scale hoarding cases had high risk for enteric and respiratory infections, retroviruses, and dermatophytosis. Case responders should be prepared for mass treatment of infectious diseases and should implement protocols to prevent transmission of feline or zoonotic infections during the emergency response and when transferring the rescued cats to other shelters or to adopters.", "journal": "Veterinary journal (London, England : 1997)", "doi": "10.1016/j.tvjl.2014.05.020", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24928422", "author": "Beatty J", "n_authors": 1, "title": "Viral causes of feline lymphoma: retroviruses and beyond.", "abstract": "The most widely recognised cause of feline lymphoma is the gammaretrovirus feline leukaemia virus (FeLV). Research into the mechanisms of cellular transformation employed by FeLV and other oncogenic retroviruses has provided as much information on the regulation of eukaryotic cell growth and differentiation as it has about cancer. The recognition that a cancer has a viral cause opens up the possibility of novel treatments that spare the host from cytotoxic side-effects by specifically targeting the virus, or the host's immune response to it. The ultimate prize for viral-associated cancers is their prevention. Vaccination and changes in management practices have seen the global prevalence of FeLV infection fall and, with it, the incidence of FeLV-related cancers. Remarkably, in the face of this success, the prevalence of feline lymphoma remains high. At least one other virus, the lentivirus feline immunodeficiency virus (FIV), accounts for some of these cases. Transformation by FIV involves incompletely understood mechanisms that are distinct from those employed by FeLV. This review will focus on the current understanding of FeLV-associated and FIV-associated lymphoma and consider whether yet more viral aetiologies could be waiting to be discovered.", "journal": "Veterinary journal (London, England : 1997)", "doi": "10.1016/j.tvjl.2014.05.026", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24909033", "author": "De Bosschere H", "n_authors": 2, "title": "[Essential thrombocythemia in a cat, associated with feline leukemia virus].", "abstract": null, "journal": "Tijdschrift voor diergeneeskunde", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24871066", "author": "Burr HD", "n_authors": 4, "title": "Cutaneous lymphoma of the tarsus in cats: 23 cases (2000-2012).", "abstract": "To determine features of lymphoma of the tarsus in cats. Multi-institutional retrospective study. 23 cats with cutaneous lymphoma of the tarsus. Veterinary oncologists were requested to submit cases fitting the following criteria: histologically or cytologically confirmed lymphoma with a location at or near the tarsus and described as subcutaneous or mass-like. Data regarding breed, sex, age, FeLV and FIV status, and reason for evaluation were collected. Results of staging tests, location of the tumor, immunophenotype, and histopathologic description were recorded. Type of treatments, outcome, survival time, presence or absence of progressive disease, and cause of death or reason for euthanasia were also recorded. Most cats were older, with a median age of 12 years (range, 7 to 18 years). No association with positive retroviral status was found. Popliteal lymph node involvement at diagnosis was reported in 5 cats, and a suspicion of lymphoma at a different site on the basis of results of abdominal ultrasonography was reported in 4 cats. Treatments were variable and included corticosteroids alone (n = 2), chemotherapy (9), radiation and chemotherapy (7), or surgery with or without chemotherapy (5). Thirteen cats were reported to have lymphoma at a different site at the time of last follow-up, death, or euthanasia. Median survival time for all cats in the study was 190 days (range, 17 to 1,011 days). Results suggested that tarsal lymphoma is an uncommon manifestation of lymphoma in cats, and in this study was most commonly nonepitheliotropic and of high grade as determined on histologic evaluation. Systemic involvement was identified; therefore, thorough staging is recommended prior to initiating treatment. Future studies are warranted to evaluate effective treatment protocols.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.244.12.1429", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24867242", "author": "Richter", "n_authors": 3, "title": "Ocular signs, diagnosis and long-term treatment with allopurinol in a cat with leishmaniasis.", "abstract": "A case of leishmaniasis with predominantly ocular signs in a cat living in Switzerland and it's treatment is reported. The cat was imported from Spain 4 years earlier and was initially presented with chronic uveitis. Laboratory test results were negative for feline immunodeficiency virus (FIV), feline infectious peritonitis (FIP), feline leukaemia virus (FeLV) and Toxoplasma gondii, as well as for Bartonella haenselae and Leishmania spp. Twenty-one months later the cat was presented again because of development of keratitis and granulomatous blepharitis. Blood cell count revealed severe Pancytopenia; Cytology of fine needle aspirates of granulomatous lesions on both upper eyelids and of a corneal smear revealed intracytoplasmatic microorganisms. A preliminary diagnosis of leishmaniasis was supported by positive polymerase chain reaction from bone marrow and eyelid samples for Leishmania infantum DNA and by a high serum antibody titer for Leishmania spp. Treatment with Allopurinol (10 mg/kg, BID) orally led to rapid improvement of ocular signs, general condition and blood cell count with complete remission of lid and corneal lesions within 2 months of treatment.", "journal": "Schweizer Archiv fur Tierheilkunde", "doi": "10.1024/0036-7281/a000593", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24842287", "author": "Ho CF", "n_authors": 7, "title": "Development of a multiplex amplification refractory mutation system reverse transcription polymerase chain reaction assay for the differential diagnosis of Feline leukemia virus vaccine and wild strains.", "abstract": "A multiplex amplification refractory mutation system reverse transcription polymerase chain reaction (ARMS RT-PCR) was developed for the differential diagnosis of Feline leukemia virus (FeLV) vaccine and wild-type strains based on a point mutation between the vaccine strain (S) and the wild-type strain (T) located in the p27 gene. This system was further upgraded to obtain a real-time ARMS RT-PCR (ARMS qRT-PCR) with a high-resolution melt analysis (HRMA) platform. The genotyping of various strains of FeLV was determined by comparing the HRMA curves with the defined wild-type FeLV (strain TW1), and the results were expressed as a percentage confidence. The detection limits of ARMS RT-PCR and ARMS qRT-PCR combined with HRMA were 100 and 1 copies of transcribed FeLV RNA per 0.5 ml of sample, respectively. No false-positive results were obtained with 6 unrelated pathogens and 1 feline cell line. Twelve FeLV Taiwan strains were correctly identified using ARMS qRT-PCR combined with HRMA. The genotypes of the strains matched the defined FeLV wild-type strain genotype with at least 91.17% confidence. A higher degree of sequence polymorphism was found throughout the p27 gene compared with the long terminal repeat region. In conclusion, the current study describes the phylogenetic relationship of the FeLV Taiwan strains and demonstrates that the developed ARMS RT-PCR assay is able to be used to detect the replication of a vaccine strain that has not been properly inactivated, thus acting as a safety check for the quality of FeLV vaccines.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/1040638714534850", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24837550", "author": "Pedersen NC", "n_authors": 1, "title": "An update on feline infectious peritonitis: virology and immunopathogenesis.", "abstract": "Feline infectious peritonitis (FIP) continues to be one of the most researched infectious diseases of cats. The relatively high mortality of FIP, especially for younger cats from catteries and shelters, should be reason enough to stimulate such intense interest. However, it is the complexity of the disease and the grudging manner in which it yields its secrets that most fascinate researchers. Feline leukemia virus infection was conquered in less than two decades and the mysteries of feline immunodeficiency virus were largely unraveled in several years. After a half century, FIP remains one of the last important infections of cats for which we have no single diagnostic test, no vaccine and no definitive explanations for how virus and host interact to cause disease. How can a ubiquitous and largely non-pathogenic enteric coronavirus transform into a highly lethal pathogen? What are the interactions between host and virus that determine both disease form (wet or dry) and outcome (death or resistance)? Why is it so difficult, and perhaps impossible, to develop a vaccine for FIP? What role do genetics play in disease susceptibility? This review will explore research conducted over the last 5 years that attempts to answer these and other questions. Although much has been learned about FIP in the last 5 years, the ultimate answers remain for yet more studies.", "journal": "Veterinary journal (London, England : 1997)", "doi": "10.1016/j.tvjl.2014.04.017", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24698667", "author": "Litster AL", "n_authors": 1, "title": "Transmission of feline immunodeficiency virus (FIV) among cohabiting cats in two cat rescue shelters.", "abstract": "Conflicting accounts have been published in the veterinary literature regarding transmission of feline immunodeficiency virus (FIV) between cohabiting cats in mixed households, and the mechanics of possible casual transmission, if it occurs, are poorly understood. Similarly, there are conflicting reports of vertical transmission of FIV. The aim of the present study was to document the FIV serological status of cats taken into two rescue shelters. At rescue shelter 1 (Rescue 1), cats cohabited in a multi-cat household of FIV-negative and naturally-infected, FIV-positive cats. A study was performed that combined a retrospective review of records of FIV serological status at intake (Test 1) and prospective FIV serological testing (Tests 2 and 3). Retrospective records were analyzed at rescue shelter 2 (Rescue 2), where FIV-positive queens with litters of nursing kittens were taken into the shelter, before being rehomed. FIV serology was performed on all kittens after weaning. Initial test results (Test 1) for 138 cohabiting cats from Rescue 1 showed that there were 130 FIV-negative cats and eight FIV-positive cats (six male neutered and two female spayed). A second test (Test 2), performed in 45 of the FIV-negative and five of the FIV-positive cats at median 28 months after Test 1 (range, 1 month to 8.8 years) showed that results were unchanged. Similarly, a third test (Test 3), performed in four of the original FeLV-negative cats and one remaining FIV-positive cat at median 38 months after Test 1 (range, 4 months to 4 years), also showed that results were unchanged. These results show a lack of evidence of FIV transmission, despite years of exposure to naturally-infected, FIV-positive cats in a mixed household. At Rescue 2, records were available from five FIV-positive queens with 19 kittens. All 19 kittens tested FIV-negative, suggesting that vertical transmission had not occurred.", "journal": "Veterinary journal (London, England : 1997)", "doi": "10.1016/j.tvjl.2014.02.030", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24696026", "author": "Boenzli E", "n_authors": 6, "title": "Detection of antibodies to the feline leukemia Virus (FeLV) transmembrane protein p15E: an alternative approach for serological FeLV detection based on antibodies to p15E.", "abstract": "The aim of this report was to investigate whether the diagnosis of feline leukemia virus (FeLV) infection by serology might be feasible and useful. Among the various viral proteins, the FeLV env-gene product (SU) and the envelope transmembrane protein p15E were considered promising candidates for the serological diagnosis of FeLV infection. Thus, we evaluated p15E and three other FeLV antigens, namely, a recombinant env-gene product, whole FeLV, and a short peptide from the FeLV transmembrane protein, for their potential to detect FeLV infection. To evaluate possible exposure of cats to FeLV, we tested serum and plasma samples from experimentally and naturally infected and vaccinated cats for the presence of antibodies to these antigens by enzyme-linked immunosorbent assays (ELISAs). The serological results were compared with the p27 and proviral real-time PCR results. We found that p15E displayed a diagnostic sensitivity of 95.7% and a specificity of 100% in experimentally infected cats. In naturally infected cats, p15E showed a diagnostic sensitivity of 77.1% and a specificity of 85.6%. Vaccinated cats displayed minimal antibody levels to p15E, suggesting that anti-p15E antibodies indicate infection rather than vaccination. The other antigens turned out to be too unspecific. The lower specificity in cats exposed to FeLV under field conditions may be explained by the fact that some cats become infected and seroconvert in the absence of detectable viral nucleic acids in plasma. We conclude that p15E serology may become a valuable tool for diagnosing FeLV infection; in some cases, it may replace PCR.", "journal": "Journal of clinical microbiology", "doi": "10.1128/JCM.02584-13", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24693663", "author": "Rypuła K", "n_authors": 5, "title": "Prevalence of viral infections in cats in southwestern Poland in the years 2006 to 2010.", "abstract": "This study included data from 676 cats in southwestern Poland examined between 2006 and 2010. Examinations were performed to diagnose the following infections: feline leukemia virus (FeLV), feline immunodeficiency virus (FIV), feline coronavirus (FCoV), feline calicivirus (FCV), and feline herpesvirus (FHV). The presence of antibodies or antigens was assessed in samples from all cats. Among examined cats, 46.9% were positive for FCV, 50% for FHV, and 38.5% for FCoV. Retroviral infections were detected more rarely: FeLV in 6.4% and FIV in 4.3% of cases.", "journal": "Berliner und Munchener tierarztliche Wochenschrift", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24688176", "author": "Munro HJ", "n_authors": 5, "title": "Seroprevalence of feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) in shelter cats on the island of Newfoundland, Canada.", "abstract": "Feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) are retroviruses found within domestic and wild cat populations. These viruses cause severe illnesses that eventually lead to death. Housing cats communally for long periods of time makes shelters at high risk for virus transmission among cats. We tested 548 cats from 5 different sites across the island of Newfoundland for FIV and FeLV. The overall seroprevalence was 2.2% and 6.2% for FIV and FeLV, respectively. Two sites had significantly higher seroprevalence of FeLV infection than the other 3 sites. Analysis of sequences from the FeLV env gene (envelope gene) from 6 positive cats showed that 4 fell within the FeLV subtype-A, while 2 sequences were most closely related to FeLV subtype-B and endogenous feline leukemia virus (en FeLV). Varying seroprevalence and the variation in sequences at different sites demonstrate that some shelters are at greater risk of FeLV infections and recombination can occur at sites of high seroprevalence.", "journal": "Canadian journal of veterinary research = Revue canadienne de recherche veterinaire", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24662705", "author": "Stuke K", "n_authors": 6, "title": "Efficacy of an inactivated FeLV vaccine compared to a recombinant FeLV vaccine in minimum age cats following virulent FeLV challenge.", "abstract": "The aim of the study was to determine the efficacy of an inactivated feline leukemia virus (FeLV) vaccine (Versifel(®) FeLV, Zoetis.) compared to a recombinant FeLV vaccine (Purevax(®) FeLV, Merial Animal Health) in young cats, exposed under laboratory conditions to a highly virulent challenge model. The study was designed to be consistent with the general immunogenicity requirements of the European Pharmacopoeia 6.0 Monograph 01/2008:1321-Feline Leukaemia Vaccine (Inactivated) with the exception that commercial-strength vaccines were assessed. Fifty seronegative cats (8-9 weeks old) were vaccinated subcutaneously on two occasions, three weeks apart, with either placebo (treatment group T01), Versifel FeLV Vaccine (treatment group T02), or Purevax FeLV Vaccine (treatment group T03) according to the manufacturer's directions. Cats were challenged three weeks after the second vaccination with a virulent FeLV isolate (61E strain). Persistent FeLV antigenemia was determined from 3 to 15 weeks postchallenge. Bone marrow samples were tested for the presence of FeLV proviral DNA to determine FeLV latent infection. At week 15 after challenge with the virulent FeLV 61E strain, the Versifel FeLV Vaccine conferred 89.5% protection against FeLV persistent antigenemia and 94.7% protection against FeLV proviral DNA integration in bone marrow cells. In comparison, the Purevax FeLV Vaccine conferred 20% protection against FeLV persistent antigenemia and 35% protection against FeLV proviral DNA integration in bone marrow cells following challenge. The data from this study show that the Versifel FeLV Vaccine was efficacious in preventing both FeLV persistent p27 antigenemia and FeLV proviral DNA integration in bone marrow cells of cats challenged with this particular challenge model under laboratory conditions and provided better protection than Purevax FeLV in this experimental challenge model with highly virulent FeLV.", "journal": "Vaccine", "doi": "10.1016/j.vaccine.2014.03.016", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24655361", "author": "Miró G", "n_authors": 9, "title": "Current status of L. infantum infection in stray cats in the Madrid region (Spain): implications for the recent outbreak of human leishmaniosis?", "abstract": "Since 2009, the incidence of human leishmaniosis in the SW of the Madrid region has been unusually high. Although dogs are the main reservoir for this disease, a role played by dogs in this outbreak has been ruled out and investigators are now considering other hosts (eg. cats, rabbits, hares) as possible alternative reservoirs.This study was designed to examine the Leishmania infantum status of stray cats in Madrid to assess its possible implications in the human leishmaniosis outbreak. 346 captured stray cats were tested for antibodies against L. infantum by the indirect fluorescent antibody technique (IFAT) and nested-PCR methods were used to detect Leishmania DNA in blood samples of cats testing seropositive for L. infantum and/or retroviruses infection. Cats were also tested for Toxoplasma gondii using the direct agglutination test (DAT) and feline leukemia virus (FeLV) antigen and feline immunodeficiency virus (FIV) antibodies (PetChek* FIV/FeLV). The presence of intestinal parasites was determined using a routine coprological method. The seroprevalence of L. infantum infection (cut off ≥ 1/100) was 3.2% (11/346). However, it was not possible to amplify Leishmania DNA in any of the blood samples. Seropositivity was not associated with sex, age, capture site, clinical status, retrovirus infection or T. gondii seropositivity. Of the 11 cats seropositive for L. infantum, 3 also tested positive for FIV, none for FeLV and 6 for T. gondii. It should be mentioned that the prevalence of FeLV p27 antigen was 4% and of FIV antibody was 9.2%. Although the seroprevalence of T. gondii was quite high at 53.5%, no T. gondii oocysts were found in any of the faeces samples analysed (n = 287). In contrast, intestinal parasites were detected in 76 (26.5%) samples, Toxocara cati being the most prevalent. Our results suggest a stable L. infantum infection situation among the stray cats of the Madrid area; the disease is uncommon and no clinical cases have been reported to date. The detection of other zoonotic parasites such as T. gondii and T. cati in stray cats indicates a need to adopt strict control measures in this population.", "journal": "Parasites & vectors", "doi": "10.1186/1756-3305-7-112", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24612318", "author": "Zheng C", "n_authors": 4, "title": "Quantitative expression of candidate genes affecting eggshell color.", "abstract": "There are three pigments that affect the color of an eggshell: protoporphyrin, biliverdin and biliverdin-zinc chelate. Protoporphyrin is the main pigment in brown and light-brown eggshells, whereas very little protoporphyrin is found in white eggshells. Eggshell protoporphyrin is derived from the heme formation in birds. Coproporphyrinogen III oxidase (CPOX) and ferrochelatase (FECH) represent rate-limiting enzymes for the heme-biosynthetic pathway. Breast cancer resistance protein (BCRP), feline leukemia virus receptor (FLVCR), and heme-responsive gene-1 (HRG1) serve as primary transporters for both protoporphyrinogen and heme. Finally, four organic anion transporting polypeptide family members (including solute carrier organic anion transporter family, SLCO1C1, SLCO1A2, SLCO1B3 and LOC418189) may affect pigment transport within eggshells. Here we measured gene expression levels in key tissues of egg-producing hens. We analyzed three different types of hens that generated distinct eggshell colors: white, pink or brown. Our data revealed three ways in which eggshell color was genetically influenced. First, high-level expression of CPOX generated more protoporphyrinogen and a brown eggshell color. In contrast, high expression of FECH likely converted more protoporphyrinogen into heme, reduced protoporphyrinogen levels within the eggshell and generated a light color. Second, heme transporters also affected eggshell color. High-level expression of BCRP, HRG1 and FLVCR were associated with brown, white and generally lighter eggshell colors, respectively. Finally, protoporphyrin precipitation also affected eggshell color, as high expression of both SLCO1A2 and SLCO1C1 were associated with brown eggshell color. As such, we have identified seven genes in which expression levels in different tissues were associated with eggshell color.", "journal": "Animal science journal = Nihon chikusan Gakkaiho", "doi": "10.1111/asj.12182", "deposited_data": "Sim", "nuccore_ids": "2160900767, 2153204798, 2153204696, 2129430528, 2128671929, 2128671905, 2128671899, 2128671893, 2128671863, 2128671814, 2128671810, 2099395659, 2201822554, 2201806879, 2201806877, 2201806875, 2201791219, 2201791218, 2201791216, 2201714878, 2201710894, 2201710893, 2201710891, 2201710890, 2201710889, 2201710888, 2201710887, 2201710885, 2201707505, 2201699011, 2201686164, 2201686163, 2201686162, 2201672441, 2201672440, 2201672439, 2201570466, 2201569814, 2201569811, 2201569809, 2201569808, 2201569805, 2201569802, 2201569801, 2201569795, 2160900767, 2153204798, 2153204696, 2129430528, 2128671929, 2128671905, 2128671899, 2128671893, 2128671863, 2128671814, 2128671810, 2099395659", "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24597712", "author": "Burton AG", "n_authors": 4, "title": "Degenerative left shift as a prognostic tool in cats.", "abstract": "A degenerative left shift (DLS) is reported to be a poor prognostic indicator in dogs and cats. Limited data in dogs and no studies in cats have been published to investigate this claim. To characterize the feline population affected by DLS and to determine if the presence and severity of DLS are associated with increased risk of euthanasia or death. One hundred and eight cats with DLS (cases) and 322 cats without DLS (controls) presented to the University of California, Davis Veterinary Medical Teaching Hospital between April 1, 1995 and April 1, 2010. Retrospective case-control study. All cases had a CBC performed within 24 hours of presentation in which immature granulocytic precursors exceeded mature neutrophils. Controls were matched by year of presentation and primary diagnosis. Survival analysis was used to determine risk of death or euthanasia from DLS and other potential predictors of outcome. Cases were more likely to die or be euthanized in hospital compared to controls (60/108 [56%] versus 107/322 [33%]). DLS was a significant predictor of death or euthanasia in hospitalized cats in both univariate and multivariate analysis (hazard ratio, 1.57; 95% confidence interval, 1.13-2.18). Trend analysis showed an increasing trend in the hazard of euthanasia or death with increasing severity of DLS. Cats with DLS are 1.57 times more likely to die or be euthanized in hospital than cats without DLS. In addition, increasing severity of DLS is associated with increased likelihood of death or euthanasia.", "journal": "Journal of veterinary internal medicine", "doi": "10.1111/jvim.12338", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24576667", "author": "Fiorito V", "n_authors": 7, "title": "Hypoxia controls Flvcr1 gene expression in Caco2 cells through HIF2α and ETS1.", "abstract": "The tissue-specific gene expression changes mediated by the hypoxia inducible factors (HIFs) allow the adaptation of cells to low oxygen tension and control several processes including erythropoiesis, angiogenesis and vasculogenesis. The Feline Leukemia Virus, subgroup C, Receptor 1 (Flvcr1) gene encodes for two isoforms, Flvcr1a and 1b, involved in the export of heme out of the cell and of mitochondria respectively. Studies in mouse models demonstrated a crucial role of Flvcr1 isoforms in erythropoiesis and during embryo development. Here, we showed the modulation of Flvcr1 gene expression in different tissues and cell lines in response to hypoxia. Chromatin immunoprecipitation analysis demonstrated that HIF2α and HIF-dependent transcription factor ETS1 (v-ets avian erythroblastosis virus E26 oncogene homolog 1) bind at the region -318/+39 of the Flvcr1 promoter. Analysis of Caco2 cells in which HIF2α or ETS1 were silenced or overexpressed demonstrated that, both HIF2α and ETS1 are involved in the transcriptional regulation of Flvcr1a and that HIF2α is absolutely required for Flvcr1a induction upon hypoxia. The inclusion of the Flvcr1 gene in the group of HIF2α-responsive genes strengthens its role in hypoxia-stimulated processes like erythropoiesis, vasculogenesis and heme absorption.", "journal": "Biochimica et biophysica acta", "doi": "10.1016/j.bbagrm.2014.02.010", "deposited_data": "Sim", "nuccore_ids": "2462523552, 2462523550, 2462523548, 2462523546, 2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217281603, 2217281601, 2217281600, 2217281599, 2217281598, 2217281596, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1907197559, 1907122316, 1889540342, 1734342275, 1734342257, 1734342230, 1734342170, 1734342146, 1734342135, 1676319629, 1676319366, 1519315556, 1519245457, 924181778, 924181484, 178057355, 124486924", "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24518948", "author": "Nolff MC", "n_authors": 4, "title": "Feline osteochondromatosis in a FELV-negative European shorthair cat.", "abstract": "To report palliative treatment in a case of multifocal feline osteochondromatosis in a feline leukaemia virus (FeLV) negative European shorthair cat. A 6-year-old spayed female European shorthair cat was presented because of a right forelimb lameness caused by an osteochondromatous lesion which had trapped tendons, vessels and nerves of the antebrachium. Several other lesions were present which did not cause the animal discomfort. The cat was tested negative for FeLV. Palliative surgical removal of the mass was performed, resulting in a marked improvement of mobility with no local recurrence. The cat developed a non-regenerative anaemia after surgery, however the underlying cause was not identified upon request of the owner. Overall survival after surgery was only 2 months. The cat was then euthanised due to severe progression of the anaemia. Palliative surgical removal of osteochondromas may result in local improvement. However, owners need to be aware that it does not increase overall survival and that the prognosis is poor. Infection with FeLV is not necessarily associated with such lesions.", "journal": "Tierarztliche Praxis. Ausgabe K, Kleintiere/Heimtiere", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24486949", "author": "Vinchi F", "n_authors": 8, "title": "Heme exporter FLVCR1a regulates heme synthesis and degradation and controls activity of cytochromes P450.", "abstract": "The liver has one of the highest rates of heme synthesis of any organ. More than 50% of the heme synthesized in the liver is used for synthesis of P450 enzymes, which metabolize exogenous and endogenous compounds that include natural products, hormones, drugs, and carcinogens. Feline leukemia virus subgroup C cellular receptor 1a (FLVCR1a) is plasma membrane heme exporter that is ubiquitously expressed and controls intracellular heme content in hematopoietic lineages. We investigated the role of Flvcr1a in liver function in mice. We created mice with conditional disruption of Mfsd7b, which encodes Flvcr1a, in hepatocytes (Flvcr1a(fl/fl);alb-cre mice). Mice were analyzed under basal conditions, after phenylhydrazine-induced hemolysis, and after induction of cytochromes P450 synthesis. Livers were collected and analyzed by histologic, quantitative real-time polymerase chain reaction, and immunoblot analyses. Hepatic P450 enzymatic activities were measured. Flvcr1a(fl/fl);alb-cre mice accumulated heme and iron in liver despite up-regulation of heme oxygenase 1, ferroportin, and ferritins. Hepatic heme export activity of Flvcr1a was closely associated with heme biosynthesis, which is required to sustain cytochrome induction. Upon cytochromes P450 stimulation, Flvcr1a(fl/fl);alb-cre mice had reduced cytochrome activity, associated with accumulation of heme in hepatocytes. The expansion of the cytosolic heme pool in these mice was likely responsible for the early inhibition of heme synthesis and increased degradation of heme, which reduced expression and activity of cytochromes P450. In livers of mice, Flvcr1a maintains a free heme pool that regulates heme synthesis and degradation as well as cytochromes P450 expression and activity. These findings have important implications for drug metabolism.", "journal": "Gastroenterology", "doi": "10.1053/j.gastro.2014.01.053", "deposited_data": "Sim", "nuccore_ids": "924181778, 924181484, 124486924, 2697292347, 2697292226, 2697292200, 2697292197, 2697292190, 2697292183, 2199610746, 2199610745, 2199610739, 2199610697, 2199610589, 2199610575, 1907148755, 1907148752, 1907148749, 1907148747, 1907148745, 1907148743, 1907148740, 1907148738, 1907148736, 1907148733, 924181778, 924181484, 195947362, 124486924", "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24484481", "author": "Naidenko SV", "n_authors": 3, "title": "Detection of seasonal weight loss and a serologic survey of potential pathogens in wild Pallas' cats (Felis [Otocolobus] manul) of the Daurian Steppe, Russia.", "abstract": "We measured seasonal changes in body mass and pathogen exposure in wild Pallas' cats (Felis [Otocolobus] manul) in the Daurian Steppe of Russia in 2010-11. Pallas' cats lost about 30% of body mass over winter. Tests for antibodies to 15 potential pathogens showed that Pallas' cats were exposed to four pathogens. Two of 16 cats had antibodies to Toxoplasma gondii. Two had antibodies to Mycoplasma sp., and one each had antibodies to Influenza A virus and Feline leukemia virus. The percentage of antibody-positive wild Pallas' cats was lower than results reported for other wild felids in the Russian Far East.", "journal": "Journal of wildlife diseases", "doi": "10.7589/2013-03-068", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24461645", "author": "Stiles J", "n_authors": 1, "title": "Ocular manifestations of feline viral diseases.", "abstract": "Feline viral diseases are common and cats can be presented with a variety of clinical manifestations. Ocular disease associated with viral pathogens is not unusual, particularly with viruses causing upper respiratory tract disease in cats, such as feline herpesvirus type 1 and feline calicivirus. These agents mainly cause ocular surface disease. Other viruses, such as feline immunodeficiency virus and feline coronavirus, can cause uveitis, while feline leukemia virus can induce ocular lymphosarcoma. This review covers the most common viral pathogens of cats that cause ocular manifestations, the specific features of the ocular diseases caused by these viruses and therapeutic recommendations.", "journal": "Veterinary journal (London, England : 1997)", "doi": "10.1016/j.tvjl.2013.11.018", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "26464932", "author": "Chhetri BK", "n_authors": 4, "title": "Disparities in Spatial Prevalence of Feline Retroviruses due to Data Aggregation: A Case of the Modifiable Areal Unit Problem.", "abstract": "The knowledge of the spatial distribution feline immunodeficiency virus and feline leukemia virus infections, which are untreatable, can inform on their risk factors and high-risk areas to enhance control. However, when spatial analysis involves aggregated spatial data, results may be influenced by the spatial scale of aggregation, an effect known as the modifiable areal unit problem (MAUP). In this study, area level risk factors for both infections in 28,914 cats tested with ELISA were investigated by multivariable spatial Poisson regression models along with MAUP effect on spatial clustering and cluster detection (for postal codes, counties, and states) by Moran's I test and spatial scan test, respectively. The study results indicate that the significance and magnitude of the association of risk factors with both infections varied with aggregation scale. Further more, Moran's I test only identified spatial clustering at postal code and county levels of aggregation. Similarly, the spatial scan test indicated that the number, size, and location of clusters varied over aggregation scales. In conclusion, the association between infection and area was influenced by the choice of spatial scale and indicates the importance of study design and data analysis with respect to specific research questions.", "journal": "Journal of veterinary medicine", "doi": "10.1155/2014/424138", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24366846", "author": "Fabrizio F", "n_authors": 8, "title": "Feline mediastinal lymphoma: a retrospective study of signalment, retroviral status, response to chemotherapy and prognostic indicators.", "abstract": "Historically, feline mediastinal lymphoma has been associated with young age, positive feline leukaemia virus (FeLV) status, Siamese breed and short survival times. Recent studies following widespread FeLV vaccination in the UK are lacking. The aim of this retrospective multi-institutional study was to re-evaluate the signalment, retroviral status, response to chemotherapy, survival and prognostic indicators in feline mediastinal lymphoma cases in the post-vaccination era. Records of cats with clinical signs associated with a mediastinal mass and cytologically/histologically confirmed lymphoma were reviewed from five UK referral centres (1998-2010). Treatment response, survival and prognostic indicators were assessed in treated cats with follow-up data. Fifty-five cases were reviewed. The median age was 3 years (range, 0.5-12 years); 12 cats (21.8%) were Siamese; and the male to female ratio was 3.2:1.0. Five cats were FeLV-positive and two were feline immunodeficiency-positive. Chemotherapy response and survival was evaluated in 38 cats. Overall response was 94.7%; complete (CR) and partial response (PR) rates did not differ significantly between protocols: COP (cyclophosphamide, vincristine, prednisone) (n = 26, CR 61.5%, PR 34.0%); Madison-Wisconsin (MW) (n = 12, CR 66.7%, PR 25.0%). Overall median survival was 373 days (range, 20-2015 days) (COP 484 days [range, 20-980 days]; MW 211 days [range, 24-2015 days] [P = 0.892]). Cats achieving CR survived longer (980 days vs 42 days for PR; P = 0.032). Age, breed, sex, location (mediastinal vs mediastinal plus other sites), retroviral status and glucocorticoid pretreatment did not affect response or survival. Feline mediastinal lymphoma cases frequently responded to chemotherapy with durable survival times, particularly in cats achieving CR. The prevalence of FeLV-antigenaemic cats was low; males and young Siamese cats appeared to be over-represented.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X13516621", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24319060", "author": "Spada E", "n_authors": 7, "title": "Molecular study on selected vector-borne infections in urban stray colony cats in northern Italy.", "abstract": "Feline vector-borne diseases can be caused by a range of pathogens transmitted by arthropods. Many of these infections have zoonotic implications, and stray cats are potential sentinels for human and pet health. This study investigated the prevalence of selected vector-borne infections in stray colony cats in Milan. Blood samples from 260 stray cats were evaluated, using conventional polymerase chain reaction tests (cPCRs), for the presence of DNA associated with Rickettsia species, Anaplasma phagocytophilum and Ehrlichia species. Positive cPCR results occurred in 127/260 subjects (48.9%; 95% confidence interval [CI] = 40.7-58.1), with a prevalence of 31.9% (83/260, 95% CI = 25.4-39.6) for Rickettsia species, 17.7% (46/260, 95% CI= 13.0-23.6) for A phagocytophilum, and 5.4% (14/260, 95% CI = 2.9-9.0) for Ehrlichia species. There was no statistical association between a positive PCR test for vector-borne infections surveyed and colony location, age, gender, body condition score or complete blood count abnormalities, nor feline immunodeficiency virus, feline leukaemia virus or Toxoplasma gondii status. The only variable linked to positive PCR results was detection of signs of ocular infection and PCR positivity for Rickettsia species (P = 0.04, odds ratio [OR] = 2.2, 95% CI = 1.1-4.4, P = 0.02). There is a significant prevalence of vector-borne infections with zoonotic potential in urban stray cats in Milan. Thus, dogs and pet cats with outdoor access should be monitored and treated for ectoparasites on a regular basis to minimise risks of disease and the potential transmission of zoonotic agents to people.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X13514422", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24317268", "author": "Watanabe S", "n_authors": 10, "title": "Notch2 transduction by feline leukemia virus in a naturally infected cat.", "abstract": "Feline leukemia virus (FeLV) induces neoplastic and nonneoplastic diseases in cats. The transduction of cellular genes by FeLV is sometimes observed and associated with neoplastic diseases including lymphoma and sarcoma. Here, we report the first natural case of feline Notch2 transduction by FeLV in an infected cat with multicentric lymphoma and hypercalcemia. We cloned recombinant FeLVs harboring Notch2 in the env gene. Notch2 was able to activate expression of a reporter gene, similar to what was previously reported in cats with experimental FeLV-induced thymic lymphoma. Our findings suggest that the transduction of Notch2 strongly correlates with FeLV-induced lymphoma.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.13-0344", "deposited_data": "Sim", "nuccore_ids": "507415039, 507415037, 2131003507, 2131003506", "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24279640", "author": "Leal RO", "n_authors": 7, "title": "Monitoring acute phase proteins in retrovirus infected cats undergoing feline interferon-ω therapy.", "abstract": "Recombinant feline interferon-ω therapy is an immunomodulator currently used in the treatment of different retroviral diseases including feline immune deficiency virus and feline leukaemia virus. Although its mechanism of action remains unclear, this drug appears to potentiate the innate response. Acute phase proteins are one of the key components of innate immunity and studies describing their use as a monitoring tool for the immune system in animals undergoing interferon-ω therapy are lacking. This study aimed to determine whether interferon-ω therapy influences acute phase protein concentrations namely serum amyloid-A, α-1-glycoprotein and C-reactive protein. A single-arm study was performed using 16 cats, living in an animal shelter, naturally infected with retroviruses and subjected to the interferon-ω therapy licensed protocol. Samples were collected before (D0), during (D10 and D30) and after therapy (D65). Serum amyloid-A and C-reactive protein were measured by specific enzyme-linked immunosorbent assay kits and α-1-glycoprotein by single radial immunodiffusion. All the acute phase proteins significantly increased in cats undergoing interferon-ω therapy (D0/D65: P<0·05) CLINICAL SIGNIFICANCE: Acute phase proteins appear to be reasonable predictors of innate-immune stimulation and may be useful in the individual monitoring of naturally retroviral infected cats undergoing interferon-ω therapy.", "journal": "The Journal of small animal practice", "doi": "10.1111/jsap.12160", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24198407", "author": "Schlecht-Louf G", "n_authors": 6, "title": "A targeted mutation within the feline leukemia virus (FeLV) envelope protein immunosuppressive domain to improve a canarypox virus-vectored FeLV vaccine.", "abstract": "We previously delineated a highly conserved immunosuppressive (IS) domain within murine and primate retroviral envelope proteins that is critical for virus propagation in vivo. The envelope-mediated immunosuppression was assessed by the ability of the proteins, when expressed by allogeneic tumor cells normally rejected by engrafted mice, to allow these cells to escape, at least transiently, immune rejection. Using this approach, we identified key residues whose mutation (i) specifically abolishes immunosuppressive activity without affecting the \"mechanical\" function of the envelope protein and (ii) significantly enhances humoral and cellular immune responses elicited against the virus. The objective of this work was to study the immunosuppressive activity of the envelope protein (p15E) of feline leukemia virus (FeLV) and evaluate the effect of its abolition on the efficacy of a vaccine against FeLV. Here we demonstrate that the FeLV envelope protein is immunosuppressive in vivo and that this immunosuppressive activity can be \"switched off\" by targeted mutation of a specific amino acid. As a result of the introduction of the mutated envelope sequence into a previously well characterized canarypox virus-vectored vaccine (ALVAC-FeLV), the frequency of vaccine-induced FeLV-specific gamma interferon (IFN-γ)-producing cells was increased, whereas conversely, the frequency of vaccine-induced FeLV-specific interleukin-10 (IL-10)-producing cells was reduced. This shift in the IFN-γ/IL-10 response was associated with a higher efficacy of ALVAC-FeLV against FeLV infection. This study demonstrates that FeLV p15E is immunosuppressive in vivo, that the immunosuppressive domain of p15E can modulate the FeLV-specific immune response, and that the efficacy of FeLV vaccines can be enhanced by inhibiting the immunosuppressive activity of the IS domain through an appropriate mutation.", "journal": "Journal of virology", "doi": "10.1128/JVI.02234-13", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24196568", "author": "Ortega-Pacheco A", "n_authors": 6, "title": "Seroprevalence of feline leukemia virus, feline immunodeficiency virus and heartworm infection among owned cats in tropical Mexico.", "abstract": "Several infectious agents may be distributed within a healthy population of cats where diverse risk factors predispose them to come into contact with pathogens. Blood samples from 227 owned cats in Merida, Mexico, were collected with the objective of determining the seroprevalence and associated risk factors of feline leukemia virus (FeLV) and Dirofilaria immitis antigen, and feline immunodeficiency virus (FIV) antibody. Serological detection of FeLV and D immitis antigens, and FIV antibodies was performed using the commercial kit SNAP Feline Triple Test. The prevalence was found to be 7.5% for FeLV, 2.5% for FIV and 0% for D immitis. Adult cats were at a higher risk of coming into contact with FeLV (P <0.01) than younger cats. Owing to its low prevalence, a risk factor analysis was not performed for FIV. The prevalence of retroviral infections found in this study was low, but within the limits reported in the different geographical areas of the world. Cases of filariosis in the domestic cats of Merida, Mexico, may be absent or very low; however, the low sample size may have influenced these results.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X13509995", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24136209", "author": "Kim WS", "n_authors": 9, "title": "Development and clinical evaluation of a rapid diagnostic kit for feline leukemia virus infection.", "abstract": "Feline leukemia virus (FeLV) causes a range of neoplastic and degenerative diseases in cats. To obtain a more sensitive and convenient diagnosis of the disease, we prepared monoclonal antibodies specific for the FeLV p27 to develop a rapid diagnostic test with enhanced sensitivity and specificity. Among these antibodies, we identified two clones (hybridomas 8F8B5 and 8G7D1) that specifically bound to FeLV and were very suitable for a diagnostic kit. The affinity constants for 8F8B5 and 8G7D1 were 0.35 × 10⁸ and 0.86 × 10⁸, respectively. To investigate the diagnostic abilities of the rapid kit using these antibodies, we performed several clinical studies. Assessment of analytical sensitivity revealed that the detection threshold of the rapid diagnostic test was 2 ng/mL for recombinant p27 and 12.5 × 10⁴ IU/mL for FeLV. When evaluating 252 cat sera samples, the kit was found to have a kappa value of 0.88 compared to polymerase chain reaction (PCR), indicating a significant correlation between data from the rapid diagnostic test and PCR. Sensitivity and specificity of the kit were 95.2% (20/21) and 98.5% (257/261), respectively. Our results demonstrated that the rapid diagnostic test would be a suitable diagnostic tool for the rapid detection of FeLV infection in cats.", "journal": "Journal of veterinary science", "doi": "10.4142/jvs.2014.15.1.91", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24127458", "author": "Kitada AA", "n_authors": 9, "title": "Detection of serum antibodies against Bartonella species in cats with sporotrichosis from Rio de Janeiro, Brazil.", "abstract": "Cat scratch disease is a zoonosis caused by Bartonella species, transmitted to humans through scratches or bites from infected cats and via direct contact with infected feces. Sporotrichosis, caused by the fungal complex Sporothrix, is transmitted by traumatic inoculation of the fungus. Cats are important in zoonotic transmission. Serum samples from 112 domestic cats with sporotrichosis and 77 samples from healthy cats were analyzed by indirect immunofluorescence assay (IFA), using the commercial kit Bartonella henselae IFA IgG (Bion). The presence of antibodies against feline leukemia virus (FeLV) and of feline immunodeficiency virus (FIV) core antigens was detected using the commercial kit Snap Combo FIV-FeLV (Idexx). The group of animals with sporotrichosis contained 93 males with a median age of 22 months, eight (7.1%) of which were positive for FIV and 15 (13.4%) for FeLV. The group of animals without sporotrichosis contained 36 males with a median age 48 months, 10 (13.0%) of which were positive for FIV and eight (10.4%) for FeLV. Of the 112 cats with sporotrichosis and 77 cats without mycosis, 72 (64.3%) and 35 (45.5%), respectively, were IFA reactive. No association was found between age, sex, FIV/FeLV and the presence of antibodies to Bartonella species. The results suggest that the study population can be considered a potential source of zoonotic infection for both diseases.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X13508193", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "26719270", "author": "Valdivieso-Torres L", "n_authors": 5, "title": "Role of Cysteines in Stabilizing the Randomized Receptor Binding Domains within Feline Leukemia Virus Envelope Proteins.", "abstract": "Retargeting of gammaretroviral envelope proteins has shown promising results in the isolation of novel isolates with therapeutic potential. However, the optimal conditions required to obtain high-affinity retargeted envelope proteins with narrow tropism are not understood. This study highlights the advantage of constrained peptides within receptor binding domains and validates the random library screening technique of obtaining novel retargeted Env proteins. Using a modified vector backbone to screen the envelope libraries on 143B osteosarcoma cells, three novel and unique retargeted envelopes were isolated. The use of complex disulfide bonds within variable regions required for receptor binding is found within natural gammaretroviral envelope isolates. Interestingly, two of the isolates, named AII and BV2, have a pair of cysteines located within the randomized region of 11 amino acids similar to that identified within the CP Env, an isolate identified in a previous Env library screen on the human renal carcinoma Caki-1 cell line. The amino acids within the randomized region of AII and BV2 envelopes that are essential for viral infection have been identified in this study and include these cysteine residues. Through mutagenesis studies, the putative disulfide bond pairs including and beyond the randomized region were examined. In parallel, the disulfide bonds of CP Env were identified using mass spectrometry. The results indicate that this pair of cysteines creates the structural context to position key hydrophobic (F and W) and basic (K and H) residues critical for viral titer and suggest that AII, BV2, and CP internal cysteines bond together in distinct ways. Retargeted gammaretroviral particles have broad applications for therapeutic use. Although great advances have been achieved in identifying new Env-host cell receptor pairs, the rules for designing optimal Env libraries are still unclear. We have found that isolates with an additional pair of cysteines within the randomized region have the highest transduction efficiencies. This emphasizes the importance of considering cysteine pairs in the design of new libraries. Furthermore, our data clearly indicate that these cysteines are essential for viral infectivity by presenting essential residues to the host cell receptor. These studies facilitate the screening of Env libraries for functional entry into target cells, allowing the identification of novel gammaretroviral Envs targeting alternative host cell receptors for gene and protein delivery.", "journal": "Journal of virology", "doi": "10.1128/JVI.02544-15", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "26689419", "author": "Nesina S", "n_authors": 8, "title": "Retroviral DNA--the silent winner: blood transfusion containing latent feline leukemia provirus causes infection and disease in naïve recipient cats.", "abstract": "The feline leukemia virus (FeLV) is a gamma-retrovirus of domestic cats that was discovered half a century ago. Cats that are infected with FeLV may develop a progressive infection resulting in persistent viremia, immunodeficiency, tumors, anemia and death. A significant number of cats mount a protective immune response that suppresses viremia; these cats develop a regressive infection characterized by the absence of viral replication and the presence of low levels of proviral DNA. The biological importance of these latter provirus carriers is largely unknown. Here, we demonstrate that ten cats that received a transfusion of blood from aviremic provirus carriers developed active FeLV infections, some with a progressive outcome and the development of fatal FeLV-associated disease. The infection outcome, disease spectrum and evolution into FeLV-C in one cat mirrored those of natural infection. Two cats developed persistent antigenemia; six cats were transiently antigenemic. Reactivation of infection occurred in some cats. One recipient developed non-regenerative anemia associated with FeLV-C, and four others developed a T-cell lymphoma, one with secondary lymphoblastic leukemia. Five of the ten recipient cats received provirus-positive aviremic blood, whereas the other five received provirus- and viral RNA-positive but aviremic blood. Notably, the cats that received blood containing only proviral DNA exhibited a later onset but graver outcome of FeLV infection than the cats that were transfused with blood containing proviral DNA and viral RNA. Leukocyte counts and cytokine analyses indicated that the immune system of the latter cats reacted quicker and more efficiently. Our results underline the biological and epidemiological relevance of FeLV provirus carriers and the risk of inadvertent FeLV transmission via blood transfusion and demonstrate the replication capacity of proviral DNA if uncontrolled by the immune system. Our results have implications not only for veterinary medicine, such as the requirement for testing blood donors and blood products for FeLV provirus by sensitive polymerase chain reaction, but are also of general interest by revealing the importance of latent retroviral DNA in infected hosts. When aiming to eliminate a retroviral infection from a population, provirus carriers must be considered.", "journal": "Retrovirology", "doi": "10.1186/s12977-015-0231-z", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "26667562", "author": "Lindemann DM", "n_authors": 6, "title": "MULTICENTRIC T-CELL LYMPHOMA AND CUTANEOUS HEMANGIOSARCOMA IN A CAPTIVE CHEETAH (ACINONYX JUBATUS).", "abstract": "A 13-yr-old intact male cheetah (Acinonyx jubatus) presented for evaluation after a 4-mo history of intermittent lethargy and increased expiratory effort. The clinical signs were initially noted after the diagnosis and death of its 13-yr-old male sibling with solitary hepatic T-cell lymphoma. Physical examination findings included thin body condition, harsh lung sounds, peripheral lymphadenopathy, and a cutaneous mass on the right medial tarsus and scrotum. Excisional biopsies diagnosed well-differentiated cutaneous hemangiosarcomas. Thoracic radiographs revealed a cranial mediastinal mass. Complete blood count and serum biochemical analyses showed a leukocytosis with persistent lymphocytosis, progressive azotemia, and markedly elevated alkaline phosphatase. Because of the cheetah's declining quality of life, euthanasia was elected. Postmortem examination, histopathology, and immunohistochemical staining revealed multicentric T-cell lymphoma. Feline leukemia virus (FeLV) enzyme-linked immunosorbent assay, FeLV polymerase chain reaction (whole blood), and viral metagenomic analysis were negative. This is the first case of cutaneous hemangiosarcoma and multicentric T-cell lymphoma reported in a FeLV-negative cheetah.", "journal": "Journal of zoo and wildlife medicine : official publication of the American Association of Zoo Veterinarians", "doi": "10.1638/2015-0118.1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "26604265", "author": "Patel M", "n_authors": 6, "title": "Reply to \"Immunosuppression in a Comparative Study of Feline Leukemia Virus Vaccines\".", "abstract": null, "journal": "Clinical and vaccine immunology : CVI", "doi": "10.1128/CVI.00504-15", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "26604264", "author": "Poulet H", "n_authors": 3, "title": "Immunosuppression in a Comparative Study of Feline Leukemia Virus Vaccines.", "abstract": null, "journal": "Clinical and vaccine immunology : CVI", "doi": "10.1128/CVI.00497-15", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "26581999", "author": "Ito J", "n_authors": 4, "title": "Ancestral Mutations Acquired in Refrex-1, a Restriction Factor against Feline Retroviruses, during its Cooption and Domestication.", "abstract": "Endogenous retroviruses (ERVs) are remnants of ancestral retroviral infections of germ cells. Retroviral endogenization is an adaptation process for the host genome, and ERVs are gradually attenuated or inactivated by mutation. However, some ERVs that have been \"domesticated\" by their hosts eventually gain physiological functions, such as placentation or viral resistance. We previously reported the discovery of Refrex-1, a soluble antiretroviral factor in domestic cats that specifically inhibits infection by feline leukemia virus subgroup D (FeLV-D), a chimeric virus of FeLV, and a feline ERV, ERV-DC. Refrex-1 is a truncated envelope protein (Env) encoded by both ERV-DC7 and ERV-DC16 proviral loci. Here, we reconstituted ancestral and functional Env from ERV-DC7 and ERV-DC16 envelope genes (env) by inducing reverse mutations. Unexpectedly, ERV-DC7 and ERV-DC16 full-length Env (ERV-DC7 fl and ERV-DC16 fl), reconstructed by removing stop codons, did not produce infectious viral particles. ERV-DC7 fl and ERV-DC16 fl were highly expressed in cells but were not cleaved into surface subunits (SU) and transmembrane subunits, nor were they incorporated into virions. G407R/N427I-A429T and Y431D substitutions within the SU C-terminal domain of ERV-DC7 fl and ERV-DC16 fl, respectively, caused these dysfunctions. The residues glycine 407 and tyrosine 431 are relatively conserved among infectious gammaretroviruses, and their substitution causes the same dysfunctions as the tested retroviruses. Our results reveal that specific mutations within the SU C-terminal domain suppressed Env cleavage and incorporation into virions and indicate that these mutations contributed to the domestication of Refrex-1 through multistep events that occurred in the postintegration period. Domestic cats are colonized with various exogenous retroviruses (exRVs), such as feline leukemia virus (FeLV), and their genomes contain numerous ERVs, some of which are replication-competent proviruses. The feline hosts, exRVs, and ERVs have complicated genetic interactions and provide an interesting field model for triangular relationships: recombination between FeLV and ERV-DC, which is a feline ERV, generated FeLV-D, a chimeric virus, and FeLV-D is restricted by Refrex-1, an antiretroviral factor corresponding to truncated Env of ERV-DC7 and ERV-DC16. Here, we reconstructed ancestral, functional Env from ERV-DC7 and ERV-DC16 env by inducing reverse mutations to elucidate how Refrex-1 was generated from its ancestor. Our results reveal that they were repeatedly inactivated by mutations preventing Env maturation. Our results provide insights into how ERVs were \"domesticated\" by their hosts and identify the mutations that mediated these evolutions. Notably, experiments that restore inactivated ERVs might uncover previously unrecognized features or properties of retroviruses.", "journal": "Journal of virology", "doi": "10.1128/JVI.01904-15", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "26486979", "author": "Hartmann K", "n_authors": 1, "title": "Efficacy of antiviral chemotherapy for retrovirus-infected cats: What does the current literature tell us?", "abstract": "The two feline retroviruses, feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV), are global and widespread, but differ in their potential to cause disease. FIV, a lentivirus that shares many properties with human immunodeficiency virus (HIV), can cause an acquired immune deficiency syndrome, which predisposes cats to other infections, stomatitis, neurological disorders and tumours. Although secondary infections are common, specific opportunistic infections or acquired immunodeficiency virus-defining infections, such as those that occur with HIV, are not commonly reported in FIV-infected cats. In most naturally infected cats, FIV does not cause a severe clinical syndrome; with appropriate care, FIV-infected cats can live many years before succumbing to conditions unrelated to their FIV infection. Thus, overall survival time is not necessarily shorter than in uninfected cats, and quality of life is usually high over many years or lifelong. FeLV, an oncornavirus, is more pathogenic than FIV. Historically, it was considered to account for more disease-related deaths and clinical syndromes in cats than any other infectious agent. Recently, the prevalence and importance of FeLV have been decreasing, mainly because of testing and eradication programmes and the use of FeLV vaccines. Progressive FeLV infection can cause tumours, bone marrow suppression and immunosuppression, as well as neurological and other disorders, and leads to a decrease in life expectancy. However, with appropriate care, many FeLV-infected cats can also live several years with a good quality of life. A decision regarding treatment or euthanasia should never be based solely on the presence or absence of a retrovirus infection. Antiviral chemotherapy is of increasing interest in veterinary medicine, but is still not used commonly. This article reviews the current literature on antiviral chemotherapy in retrovirus-infected cats, focusing on drugs that are currently available on the market and, thus, could potentially be used in cats.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X15610676", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "26459979", "author": "Westman ME", "n_authors": 5, "title": "Determining the feline immunodeficiency virus (FIV) status of FIV-vaccinated cats using point-of-care antibody kits.", "abstract": "This study challenges the commonly held view that the feline immunodeficiency virus (FIV) infection status of FIV-vaccinated cats cannot be determined using point-of-care antibody test kits due to indistinguishable antibody production in FIV-vaccinated and naturally FIV-infected cats. The performance of three commercially available point-of-care antibody test kits was compared in a mixed population of FIV-vaccinated (n=119) and FIV-unvaccinated (n=239) cats in Australia. FIV infection status was assigned by considering the results of all antibody kits in concert with results from a commercially available PCR assay (FIV RealPCR™). Two lateral flow immunochromatography test kits (Witness FeLV/FIV; Anigen Rapid FIV/FeLV) had excellent overall sensitivity (100%; 100%) and specificity (98%; 100%) and could discern the true FIV infection status of cats, irrespective of FIV vaccination history. The lateral flow ELISA test kit (SNAP FIV/FeLV Combo) could not determine if antibodies detected were due to previous FIV vaccination, natural FIV infection, or both. The sensitivity and specificity of FIV RealPCR™ for detection of viral and proviral nucleic acid was 92% and 99%, respectively. These results will potentially change the way veterinary practitioners screen for FIV in jurisdictions where FIV vaccination is practiced, especially in shelter scenarios where the feasibility of mass screening is impacted by the cost of testing.", "journal": "Comparative immunology, microbiology and infectious diseases", "doi": "10.1016/j.cimid.2015.07.004", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "26387062", "author": "Bergmann M", "n_authors": 6, "title": "Prevalence of selected rickettsial infections in cats in Southern Germany.", "abstract": "Prevalence of Anaplasma, Ehrlichia, Neorickettsia, and Wolbachia DNA in blood of 479 cats collected in different veterinary clinics in Southern Germany was determined using a previously published conventional PCR using 16S-23S intergenic spacer primers (5' CTG GGG ACT ACG GTC GCA AGA C 3' - forward; 5' CTC CAG TTT ATC ACT GGA AGT T 3' - reverse). Purified amplicons were sequenced to confirm genus and species. Associations between rickettsial infections, and feline immunodeficiency virus (FIV), as well as feline leukemia virus (FeLV) status were evaluated. Rickettsial prevalence was 0.4% (2/479; CI: 0.01-1.62%). In the two infected cats, Anaplasma phagocytophilum DNA was amplified. These cats came from different environment and had outdoor access. Both were ill with many of their problems likely related to other diseases. However, one cat had neutrophilia with left shift and the other thrombocytopenia potentially caused by their A. phagocytophilum infection. There was no significant difference in the FIV and FeLV status between A. phagocytophilum-negative and -positive cats. A. phagocytophilum can cause infection in cats in Southern Germany, and appropriate tick control is recommended.", "journal": "Comparative immunology, microbiology and infectious diseases", "doi": "10.1016/j.cimid.2015.08.003", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "28491382", "author": "Breitschwerdt EB", "n_authors": 3, "title": "Bartonella henselae as a cause of acute-onset febrile illness in cats.", "abstract": "At different time points spanning 6 months, three adopted feral flea-infested cats, residing in the household of a veterinary technician, became acutely anorexic, lethargic and febrile. Enrichment blood culture/PCR using  We conclude that microbiological diagnosis and treatment of ", "journal": "JFMS open reports", "doi": "10.1177/2055116915600454", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "26277567", "author": "Paşa S", "n_authors": 11, "title": "Detection of Leishmania major and Leishmania tropica in domestic cats in the Ege Region of Turkey.", "abstract": "Leishmaniosis is a group of diseases caused by different species of Leishmania parasites in mammalian species. The aim of the present study was to investigate the presence of Leishmania spp. DNA in cats using real time polymerase chain reaction (RT-PCR) assays targeting internal transcribed spacer (ITS1) and heat-shock protein 70 gene (Hsp70) regions with Leishmania species-specific primers and probes. Blood samples were collected from 147 cats (73 female; 74 male) in the endemic regions for zoonotic visceral leishmaniasis in the western provinces of Turkey and analyzed using two RT-PCR assays. Additionally, Hsp70 RT-PCR products were sequenced. ELISA assays for feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) were also carried out for 145 of the 147 samples. Overall, 13/147 (8.84%) cats were positive for Leishmania by RT-PCR (4 L. major and 9 L. tropica). FIV and FeLV antibody and/or antigen was detected in 4 and 5 cats among Leishmania DNA positives, respectively. To the best of our knowledge, this study is the first to investigate and report the presence of L. major and L. tropica infections in a large group of domestic cats in Turkey. The results obtained indicate that species identification of Leishmania is essential for epidemiological understanding and that clinical signs alone are not indicative for leishmaniosis in cats, as it is in dogs. This study suggests that extensive research should be carried out in cat populations in order to fully understand the role of cats in the epidemiology of the disease.", "journal": "Veterinary parasitology", "doi": "10.1016/j.vetpar.2015.07.042", "deposited_data": "Sim", "nuccore_ids": "920686169, 920686167, 920686165, 920686163, 920686161, 920686159, 920686157", "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "28491381", "author": "Camps T", "n_authors": 6, "title": "A case of spongiform polioencephalomyelopathy in a cat with a history of behavioural problems.", "abstract": "A 7-month-old, entire female, domestic shorthair cat was referred to our behavioural service owing to soiling in the house and a play-related problem. The owners' complaints were that the cat had never used the litter tray, and it did not know how to play. After reviewing the behavioural history, a problem of substrate preferences acquisition was suspected with regard to the elimination problem. During the consultation, the physical examination was unremarkable, but the neurological examination revealed a moderate and hypermetric ataxic gait, and a bilateral lack of menace response. Some degree of visual impairment was suspected. The problem was located in the central nervous system (CNS); specifically, an intracranial and multifocal problem was diagnosed. After a complete work-up (complete ophthalmological examination, complete blood count and a complete biochemistry panel, feline immunodeficiency virus/feline leukaemia virus test, thorax radiographs, abdominal ultrasound, brain magnetic resonance imaging [0.2 T], cerebrospinal fluid analysis and a urinary metabolic screen test), a degenerative CNS problem was suspected. No treatment was prescribed for the neurological problem. Regarding the problem of soiling in the house, reward-based training with a clicker was used, and the cat partially improved in a few weeks. Three months later, the cat was referred to the neurology service in status epilepticus. A symptomatic treatment was prescribed, with a mild response. After 2 years of treatment and a progressive worsening, the cat was euthanased. Necropsy revealed spongiform polioencephalomyelopathy. In order to rule out prion aetiology a PrPsc inmunohistochemistry assay was performed, and the results were negative. Congenital spongiform polioencephalomyelopathy (CSP) was diagnosed. We strongly suggest that the cat's behavioural clinical signs were caused by the CSP, causing learning impairment. To the best of our knowledge, this would be the first case in which a congenital degenerative disease affected a cat's capability to learn, leading to behavioural signs as the main complaint of the owners, even before neurological signs are detected by the owners.", "journal": "JFMS open reports", "doi": "10.1177/2055116915599172", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "28491380", "author": "Firth CL", "n_authors": 2, "title": "A survey of feline leukaemia virus antigenaemia among cats in eastern Austria: a retrospective analysis of serum samples routinely tested between 1996 and 2011.", "abstract": "The aim of this retrospective analysis was to determine the seroprevalence of feline leukaemia virus (FeLV) antigenaemia among owned cats in Vienna and the surrounding area. Samples were tested between 1996 and 2011 by the Department of Clinical Virology at the University of Veterinary Medicine, Vienna, Austria. All samples were sent to the university as part of routine diagnostic procedures, either to determine infection in clinically symptomatic individuals or to rule out infection prior to vaccination. To allow for statistical comparison, samples analysed between 2008 and 2011 were pooled into one population (n = 444) and evaluated against samples tested in 1996 (n = 840). Furthermore, analyses of subgroups were undertaken to determine the effect of sex and age on the prevalence of FeLV antigenaemia. With respect to the samples tested at the University of Veterinary Medicine in Vienna, it was determined that the level of FeLV antigenaemia in eastern Austria between 1996 and 2011 was 5.6%. The proportion of FeLV antigenaemic cats was highly variable and has not fallen significantly over this period, despite advances in vaccination, and the education of pet owners and animal welfare charities. This study confirms the importance of continued and regular vaccination against FeLV among Austrian cats, particularly those allowed access to the outdoors. Within the remit of this retrospective study, it was not possible to follow-up results of repeat testing or of other assays (PCR) of individual cats. As a result of this, no conclusions can be drawn as to the possibility of transient antigenaemic cats or false-positive enzyme-linked immunosorbent assay results.", "journal": "JFMS open reports", "doi": "10.1177/2055116915598336", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "26185125", "author": "Wilkes RP", "n_authors": 8, "title": "Rapid and sensitive detection of Feline immunodeficiency virus using an insulated isothermal PCR-based assay with a point-of-need PCR detection platform.", "abstract": "Feline immunodeficiency virus (FIV) is an important infectious agent of cats. Clinical syndromes resulting from FIV infection include immunodeficiency, opportunistic infections, and neoplasia. In our study, a 5' long terminal repeat/gag region-based reverse transcription insulated isothermal polymerase chain reaction (RT-iiPCR) was developed to amplify all known FIV strains to facilitate point-of-need FIV diagnosis. The RT-iiPCR method was applied in a point-of-need PCR detection platform--a field-deployable device capable of generating automatically interpreted RT-iiPCR results from nucleic acids within 1 hr. Limit of detection 95% of FIV RT-iiPCR was calculated to be 95 copies standard in vitro transcription RNA per reaction. Endpoint dilution studies with serial dilutions of an ATCC FIV type strain showed that the sensitivity of lyophilized FIV RT-iiPCR reagent was comparable to that of a reference nested PCR. The established reaction did not amplify any nontargeted feline pathogens, including Felid herpesvirus 1, feline coronavirus, Feline calicivirus, Feline leukemia virus, Mycoplasma haemofelis, and Chlamydophila felis. Based on analysis of 76 clinical samples (including blood and bone marrow) with the FIV RT-iiPCR, test sensitivity was 97.78% (44/45), specificity was 100.00% (31/31), and agreement was 98.65% (75/76), determined against a reference nested-PCR assay. A kappa value of 0.97 indicated excellent correlation between these 2 methods. The lyophilized FIV RT-iiPCR reagent, deployed on a user-friendly portable device, has potential utility for rapid and easy point-of-need detection of FIV in cats.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/1040638715593597", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "26164289", "author": "Hashimoto-Gotoh A", "n_authors": 3, "title": "Comparison between S+L- assay and LacZ marker rescue assay for detecting replication-competent gammaretroviruses.", "abstract": "To avoid contamination of adventitious gammaretroviruses in biological products such as vaccines, it is necessary to check the master seed cells for manufacturing. There are several assays to detect infectious gammaretroviruses. Among these, sarcoma-positive, leukemia-negative (S+L-) assay is a classical infectivity assay, which is often recommended in governmental guidelines. The S+L- cells used in S+L- assay generate unique focus upon the infection of replication-competent gammaretroviruses. Although S+L- assay is well recognized for the detection, their applicability is questionable in some cases. On the other hand, LacZ marker rescue (LMR) assay detects infectious gammaretroviruses by transducing LacZ marker gene to the target cells, which shows lacZ-positive foci if the infectious virus is present. In this study, we compared LMR and S+L- assays for detection of a variety of endogenous and exogenous gammaretroviruses. As results, LMR assay could detect all gammaretroviruses examined. On the other hand, S+L- assay using feline S+L- cells, termed QN10S, could not detect porcine endogenous retrovirus (PERV) subgroups A/B. Further, S+L- mink cells could not detect feline leukemia virus subgroups B in addition to PERV-A/B. These data indicate that LMR assay is better suited to detect wider range of gammaretroviruses.", "journal": "Biologicals : journal of the International Association of Biological Standardization", "doi": "10.1016/j.biologicals.2015.06.007", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "28491370", "author": "Santagostino SF", "n_authors": 7, "title": "Primary angiocentric/angioinvasive T-cell lymphoma of the tympanic bulla in a feline leukaemia virus-positive cat.", "abstract": null, "journal": "JFMS open reports", "doi": "10.1177/2055116915593966", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "26101310", "author": "Pennisi MG", "n_authors": 17, "title": "Blood transfusion in cats: ABCD guidelines for minimising risks of infectious iatrogenic complications.", "abstract": "The availability of blood components has increased the number of indications for transfusing cats, and fresh whole blood is readily accessible to clinicians because it can be taken from in-house donor cats or 'volunteer' feline blood donors. A certain amount of risk remains to the recipient cat, as immediate or delayed adverse reactions can occur during or after transfusion, related to immunemediated mechanisms. This article, however, focuses on adverse events caused by infectious agents, which may originate either from contamination of blood following incorrect collection, storage or transfusion, or from transfusion of contaminated blood obtained from an infected donor. In cats, blood cannot be collected through a closed system and, therefore, collection of donor blood requires a multi-step manipulation of syringes and other devices. It is crucial that each step of the procedure is performed under the strictest aseptic conditions and that bacterial contamination of blood bags is prevented, as bacterial endotoxins can cause an immediate febrile reaction or even fatal shock in the recipient cat. With a view to preventing transmission of blood-borne infectious diseases, the American College of Veterinary Internal Medicine has adopted basic criteria for selecting pathogens to be tested for in donor pets. The worldwide core screening panel for donor cats includes feline leukaemia virus, feline immunodeficiency virus, Bartonella species and feline haemoplasma. The list should be adapted to the local epidemiological situation concerning other vector-borne feline infections. The most practical, rapid and inexpensive measure to reduce transfusion risk is to check the risk profile of donor cats on the basis of a written questionnaire. Blood transfusion can never, however, be considered entirely safe.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X15588449", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "26088340", "author": "Overy DP", "n_authors": 6, "title": "Cutaneous Phaeohyphomycosis Caused by Exophiala attenuata in a Domestic Cat.", "abstract": "A 7-year-old female-spayed, domestic short-haired cat was presented to her veterinarian with a mass on the hind paw. Histopathologic examination of a tissue biopsy revealed nodular pyogranulomatous panniculitis with intralesional pigmented fungal hyphae. A dematiaceous fungal isolate was isolated with a micromorphological phenotype consistent with the anamorphic genus Exophiala: budding cells, torulose mycelium and annellidic conidiogenesis from simple conidiophores consisting of terminal and lateral cells that tapered to a short beak at the apex. Sequence homology of the internal transcribed spacer region of the rDNA gene confirmed the identification of the isolate as Exophiala attenuata. Reported here is the first confirmed case of feline phaeohyphomycosis caused by E. attenuata in North America. Similar to historical cases of feline phaeohyphomycosis caused by Exophiala spp., there was no history or postmortem evidence to suggest the patient was in an immunocompromised state (e.g., suffering from FeLV or FIV). Although aggressive surgical excision of local lesions is recommended prior to drug treatment when dealing with subcutaneous phaeohyphomycosis, surgery followed by itraconazole treatment did not resolve the E. attenuata infection in this cat.", "journal": "Mycopathologia", "doi": "10.1007/s11046-015-9909-y", "deposited_data": "Sim", "nuccore_ids": "848510286, 848510285", "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "26067085", "author": "Fiorito V", "n_authors": 5, "title": "Crucial Role of FLVCR1a in the Maintenance of Intestinal Heme Homeostasis.", "abstract": "The maintenance of heme homeostasis, mucosa cell renewal, and redox environment in the intestine is essential to permit digestion, absorption, cell proliferation, cell apoptosis, and immune response and to avoid the development of gut disorders. The feline leukemia virus, subgroup C, receptor 1a (FLVCR1a) is a heme exporter expressed in almost all cell types, including intestinal cells. This work investigates the role of FLVCR1a in the intestine, taking advantage of an intestine-specific conditional Flvcr1a-knockout mouse and of FLVCR1a-depleted Caco2 cells. The data show that FLVCR1a does not participate in the absorption of dietary heme, whereas it is involved in the export of de novo synthesized heme from intestinal cells. The loss of Flvcr1a is associated with a decrease of intestinal cell proliferation and with alterations in the peculiar homeostasis of proliferating cells, including the maintenance of their redox status. The involvement of FLVCR1a in these processes renders this exporter crucial for the survival of mice in a model of ulcerative colitis. These findings shed light on the role of heme export in the dietary heme absorption process and unravel a new role for heme export in the control of mucosal renewal and in proliferating cell redox status and metabolic activity, demonstrating a crucial role for FLVCR1a in maintaining intestinal homeostasis in both physiologic and pathologic situations. By exporting the excess of de novo synthesized heme from intestinal cells, FLVCR1a participates in the control of intestinal mucosa homeostasis.", "journal": "Antioxidants & redox signaling", "doi": "10.1089/ars.2014.6216", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556, 924181778, 924181484, 124486924", "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "26056904", "author": "Lindemann DM", "n_authors": 6, "title": "SOLITARY T-CELL HEPATIC LYMPHOMA WITH LARGE GRANULAR LYMPHOCYTE MORPHOLOGY IN A CAPTIVE CHEETAH (ACINONYX JUBATUS).", "abstract": "A 13-yr-old male cheetah (Acinonyx jubatus) presented for an acute history of lateral recumbency and anorexia. Upon physical examination under general anesthesia, severe icterus was noted. A serum biochemical profile confirmed markedly elevated total bilirubin and alanine transaminase. Based on ultrasound-guided liver aspirates and cytology, a presumptive diagnosis of large granular lymphocyte hepatic lymphoma was reached. Abdominal and thoracic radiographs did not assist in reaching an antemortem diagnosis. Postmortem examination and histopathology provided a definitive diagnosis of hepatic lymphoma with acute massive hepatocelluar necrosis and hemorrhage, as well as concurrent lesions of gastric ulcers, ulcerative and sclerosing enteritis, myocardial hypertrophy, and splenic myelolipomas. Immunohistochemistry of the liver yielded CD-3 positive and CD-20 negative results, confirming lymphocytes of a T-cell lineage. Due to concern for possible retrovirus-associated disease, enzyme-linked immunosorbent assays for feline leukemia virus and feline immunodeficiency virus were performed retrospectively on a banked serum sample and yielded negative results, thus diminishing concern for the male conspecific housed in the same exhibit.", "journal": "Journal of zoo and wildlife medicine : official publication of the American Association of Zoo Veterinarians", "doi": "10.1638/2014-0199R.1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "26054227", "author": "Lehmann M", "n_authors": 7, "title": "[Efficacy of siRNA on feline leukemia virus replication in vitro].", "abstract": "Feline leukemia virus (FeLV) can lead to severe clinical signs in cats. Until now, there is no effective therapy for FeLV-infected cats. RNA interference-based antiviral therapy is a new concept. Specific small interfering RNA (siRNA) are designed complementary to the mRNA of a target region, and thus inhibit replication. Several studies have proven efficacy of siRNAs in inhibiting virus replication. The aim of this study was to evaluate the inhibitory potential of siRNAs against FeLV replication in vitro. siRNAs against the FeLV env gene and the host cell surface receptor (feTHTR1) which is used by FeLV-A for entry as well as siRNA that were not complementary to the FeLV or cat genome, were tested. Crandell feline kidney cells (CrFK cells) were transfected with FeLV-A/Glasgow-1. On day 13, infected cells were transfected with siRNAs. As control, cells were mock-transfected or treated with azidothymidine (AZT) (5 μg/ml). Culture supernatants were analyzed for FeLV RNA using quantitative real-time RT-PCR and for FeLV p27 by ELISA every 24 hours for five days. All siRNAs significantly reduced viral RNA and p27 production, starting after 48 hours. The fact that non-complementary siRNAs also inhibited virus replication may lead to the conclusion that unspecific mechanisms rather than specific binding lead to inhibition.", "journal": "Berliner und Munchener tierarztliche Wochenschrift", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25972402", "author": "Patel M", "n_authors": 6, "title": "Comparative Efficacy of Feline Leukemia Virus (FeLV) Inactivated Whole-Virus Vaccine and Canarypox Virus-Vectored Vaccine during Virulent FeLV Challenge and Immunosuppression.", "abstract": "Four vaccines for feline leukemia virus (FeLV) are available in the United States. This study's purpose was to compare the efficacy of Nobivac feline 2-FeLV (an inactivated, adjuvanted whole-virus vaccine) and PureVax recombinant FeLV (a live, canarypox virus-vectored vaccine) following FeLV challenge. Cats were vaccinated at 9 and 12 weeks with Nobivac feline 2-FeLV (group A, n = 11) or PureVax recombinant FeLV (group B, n = 10). Group C (n = 11) comprised unvaccinated controls. At 3 months postvaccination, cats were immunosuppressed and challenged with FeLV-A/61E. The outcomes measured were persistent antigenemia at 12 weeks postchallenge (PC) and proviral DNA and viral RNA at 3 to 9 weeks PC. Persistent antigenemia was observed in 0 of 11 cats in group A, 5 of 10 cats in group B, and 10 of 11 cats in group C. Group A was significantly protected compared to those in groups B (P < 0.013) and C (P < 0.0001). No difference was found between groups B and C (P > 0.063). The preventable fraction was 100% for group A and 45% for group B. At 9 weeks PC, proviral DNA and viral RNA were detected 1 of 11 cats in group A, 6 of 10 cats in group B, and 9 of 11 cats in group C. Nucleic acid loads were significantly lower in group A than in group C (P < 0.01). Group A had significantly lower proviral DNA loads than group B at weeks 6 to 9 (P < 0.02). The viral RNA loads were significantly lower in group A than in group B at weeks 7 to 9 (P < 0.01). The results demonstrate that Nobivac feline 2-FeLV-vaccinated cats were fully protected against persistent antigenemia and had significantly smaller amounts of proviral DNA and plasma viral RNA loads than PureVax recombinant FeLV-vaccinated cats and unvaccinated controls.", "journal": "Clinical and vaccine immunology : CVI", "doi": "10.1128/CVI.00034-15", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25913257", "author": "Koba R", "n_authors": 3, "title": "Overexpression of feline tripartite motif-containing 25 interferes with the late stage of feline leukemia virus replication.", "abstract": "Tripartite motif-containing 25 (TRIM25) regulates various cellular processes through E3 ubiquitin ligase activity. Previous studies have revealed that the expression of TRIM25 is induced by type I interferon and that TRIM25 is involved in the host cellular innate immune response against retroviral infection. Although retroviral infection is prevalent in domestic cats, the roles of feline TRIM25 in the immune response against these viral infections are poorly understood. Because feline TRIM25 is expected to modulate the infection of feline leukemia virus (FeLV), we investigated its effects on early- and late-stage FeLV replication. This study revealed that ectopic expression of feline TRIM25 in HEK293T cells reduced viral protein levels leading to the inhibition of FeLV release. Our findings show that feline TRIM25 has a potent antiviral activity and implicate an antiviral mechanism whereby feline TRIM25 interferes with late-stage FeLV replication.", "journal": "Virus research", "doi": "10.1016/j.virusres.2015.04.017", "deposited_data": "Sim", "nuccore_ids": "2695932948, 2695932948, 2131049019", "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25892717", "author": "Kawamura M", "n_authors": 7, "title": "Genetic diversity in the feline leukemia virus gag gene.", "abstract": "Feline leukemia virus (FeLV) belongs to the Gammaretrovirus genus and is horizontally transmitted among cats. FeLV is known to undergo recombination with endogenous retroviruses already present in the host during FeLV-subgroup A infection. Such recombinant FeLVs, designated FeLV-subgroup B or FeLV-subgroup D, can be generated by transduced endogenous retroviral env sequences encoding the viral envelope. These recombinant viruses have biologically distinct properties and may mediate different disease outcomes. The generation of such recombinant viruses resulted in structural diversity of the FeLV particle and genetic diversity of the virus itself. FeLV env diversity through mutation and recombination has been studied, while gag diversity and its possible effects are less well understood. In this study, we investigated recombination events in the gag genes of FeLVs isolated from naturally infected cats and reference isolates. Recombination and phylogenetic analyses indicated that the gag genes often contain endogenous FeLV sequences and were occasionally replaced by entire endogenous FeLV gag genes. Phylogenetic reconstructions of FeLV gag sequences allowed for classification into three distinct clusters, similar to those previously established for the env gene. Analysis of the recombination junctions in FeLV gag indicated that these variants have similar recombination patterns within the same genotypes, indicating that the recombinant viruses were horizontally transmitted among cats. It remains to be investigated whether the recombinant sequences affect the molecular mechanism of FeLV transmission. These findings extend our understanding of gammaretrovirus evolutionary patterns in the field.", "journal": "Virus research", "doi": "10.1016/j.virusres.2015.04.008", "deposited_data": "Sim", "nuccore_ids": "675822143, 675822142, 675821855, 675821853, 675821852, 675821851, 675821849, 675821848, 675821846, 675821844, 675821842, 675821841, 675821840, 675821838, 675821837, 675821836, 675821835, 675821834, 675821833, 675821832, 675821831, 675821830, 675821829, 675821828, 675821827, 675821826, 675821825, 675821824, 675821823, 675821822, 675821821, 675821820, 675821819, 675821818, 675821817, 675821816, 675821815, 675821814, 675821813, 675821812, 675821811, 675821810, 675821809, 675821808, 675821807, 675821806, 675821805, 675821804, 675821803, 675821801, 675821800, 675821798, 675821796, 675821794, 675821792, 675821790, 675821789, 675821787, 675821785, 675821783, 675821781, 675821780, 675821778, 675821776, 675821774, 675821772, 675821770, 675821768, 675821766, 675821764, 675821762, 675821760, 675821758, 675821756, 675821754, 675821752, 675821750, 675821748, 675821746, 675821744, 675821742, 675821741, 675821739, 675821737, 675821735, 675821733, 675821731, 675821729, 675821727, 675821725, 675821723, 675821721, 675821719, 675821717, 675821715, 675821713, 675821711, 675821709, 675821707, 675821706, 675821704, 675821702, 675821700, 675821698, 675821696, 675821694, 675821692, 675821691, 675821689, 675821687, 675821685, 675821684, 675821683, 675821681, 675821679, 675821677, 675821675, 675821673, 675821671, 675821669, 675821667, 675821665, 675821664, 675821662, 675821660, 675821658, 675821656, 675821654, 675821652, 675821650, 675821648, 675821647, 675821645, 675821643, 675821641, 675821639, 675821637, 675821635, 675821633, 675821631, 675821629, 675821627, 675821625, 675821623, 675821622, 675821620, 675821619, 675821617", "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25889006", "author": "Chhetri BK", "n_authors": 4, "title": "Comparison of risk factors for seropositivity to feline immunodeficiency virus and feline leukemia virus among cats: a case-case study.", "abstract": "Feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) are reported to have similar risk factors and similar recommendations apply to manage infected cats. However, some contrasting evidence exists in the literature with regard to commonly reported risk factors. In this study, we investigated whether the known risk factors for FIV and FeLV infections have a stronger effect for either infection. This retrospective study included samples from 696 cats seropositive for FIV and 593 cats seropositive for FeLV from the United States and Canada. Data were collected during two cross sectional studies, where cats were tested using IDEXX FIV/FeLV ELISA kits. To compare the effect of known risk factors for FIV infection compared to FeLV, using a case-case study design, random intercept logistic regression models were fit including cats' age, sex, neuter status, outdoor exposure, health status and type of testing facility as independent variables. A random intercept for testing facility was included to account for clustering expected in testing practices at the individual clinics and shelters. In the multivariable random intercept model, the odds of FIV compared to FeLV positive ELISA results were greater for adults (OR = 2.09, CI: 1.50-2.92), intact males (OR = 3.14, CI: 1.85-3.76), neutered males (OR = 2.68, CI: 1.44- 3.14), cats with outdoor access (OR = 2.58, CI: 1.85-3.76) and lower for cats with clinical illness (OR = 0.60, 95% CI: 0.52-0.90). The variance components obtained from the model indicated clustering at the testing facility level. Risk factors that have a greater effect on FIV seropositivity include adulthood, being male (neutered or not) and having access to outdoors, while clinical illness was a stronger predictor for FeLV seropositivity. Further studies are warranted to assess the implications of these results for the management and control of these infections.", "journal": "BMC veterinary research", "doi": "10.1186/s12917-015-0339-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25879730", "author": "Krunic M", "n_authors": 7, "title": "Decreased expression of endogenous feline leukemia virus in cat lymphomas: a case control study.", "abstract": "Cats infected with exogenous feline leukemia virus (exFeLV) have a higher chance of lymphoma development than uninfected cats. Furthermore, an increased exFeLV transcription has been detected in lymphomas compared to non-malignant tissues. The possible mechanisms of lymphoma development by exFeLV are insertional mutagenesis or persistent stimulation of host immune cells by viral antigens, bringing them at risk for malignant transformation. Vaccination of cats against exFeLV has in recent years decreased the overall infection rate in most countries. Nevertheless, an increasing number of lymphomas have been diagnosed among exFeLV-negative cats. Endogenous feline leukemia virus (enFeLV) is another retrovirus for which transcription has been observed in cat lymphomas. EnFeLV provirus elements are present in the germline of various cat species and share a high sequence similarity with exFeLV but, due to mutations, are incapable of producing infectious viral particles. However, recombination between exFeLV and enFeLV could produce infectious particles. We examined the FeLV expression in cats that have developed malignant lymphomas and discussed the possible mechanisms that could have induced malignant transformation. For expression analysis we used next-generation RNA-sequencing (RNA-Seq) and for validation reverse transcription quantitative PCR (RT-qPCR). First, we showed that there was no expression of exFeLV in all samples, which eliminates the possibility of recombination between exFeLV and enFeLV. Next, we analyzed the difference in expression of three enFeLV genes between control and lymphoma samples. Our analysis showed an average of 3.40-fold decreased viral expression for the three genes in lymphoma compared to control samples. The results were confirmed by RT-qPCR. There is a decreased expression of enFeLV genes in lymphomas versus control samples, which contradicts previous observations for the exFeLV. Our results suggest that a persistent stimulation of host immune cells is not an appropriate mechanism responsible for malignant transformation caused by feline endogenous retroviruses.", "journal": "BMC veterinary research", "doi": "10.1186/s12917-015-0378-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25824128", "author": "Jas D", "n_authors": 5, "title": "Three-year duration of immunity for feline herpesvirus and calicivirus evaluated in a controlled vaccination-challenge laboratory trial.", "abstract": "Feline vaccination guidelines recommend less frequent boosters for the core vaccines (rhinotracheitis, calicivirosis and infectious panleucopenia). Most guidelines recommend boosters at 3-yearly intervals after a basic vaccination including primary vaccination and revaccination one year later. The objective of this study was to assess the duration of immunity induced by PUREVAX(®) RCPCh FeLV, a non-adjuvanted vaccine against feline rhinotracheitis, calicivirosis, infectious panleucopenia, chlamydiosis and leukemia. After primary vaccination followed by revaccination one year later with a vaccine formulated at minimum dose, the cats were kept in a confined environment and challenged 3 years later with a virulent heterologous strain of feline calicivirus (FCV) and subsequently a virulent strain of feline herpesvirus (FHV). Clinical signs and viral excretion were recorded for two weeks after each viral inoculation. Contemporary unvaccinated cats and new animals added at the time of challenge were used as controls. The vaccination regimen induced a stable and long-lasting humoral response. Vaccination resulted in a significant reduction in the severity of the disease after FHV challenge and in the frequency of cats showing a severe calicivirosis (defined as a combination of systemic clinical symptoms and oronasal ulcers). As opposed to the significant reduction of excretion observed a few weeks after primo-vaccination or even one year after vaccination for FCV, viral shedding was not reduced 3 years after revaccination. This study showed that primary vaccination and revaccination one year later with PUREVAX(®) RCPCh FeLV was able to induce 3-year duration of immunity against FCV and FHV. The results and conclusion of this study are consistent with current vaccination guidelines and will allow the veterinarian to adapt the vaccination regimen to the way of life of the cat.", "journal": "Veterinary microbiology", "doi": "10.1016/j.vetmic.2015.03.009", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25809630", "author": "Krengel A", "n_authors": 12, "title": "Gammaretrovirus-specific antibodies in free-ranging and captive Namibian cheetahs.", "abstract": "The cheetah population in Namibia is the largest free-ranging population in the world and a key population for research regarding the health status of this species. We used serological methods and quantitative real-time PCR to test free-ranging and captive Namibian cheetahs for the presence of feline leukemia virus (FeLV), a gammaretrovirus that can be highly aggressive in populations with low genetic diversity, such as cheetahs. We also assessed the presence of antibodies to other gammaretroviruses and the responses to a FeLV vaccine developed for domestic cats. Up to 19% of the free-ranging cheetahs, 27% of the captive nonvaccinated cheetahs, and 86% of the captive vaccinated cheetahs tested positive for FeLV antibodies. FeLV-antibody-positive free-ranging cheetahs also tested positive for Rauscher murine leukemia virus antibodies. Nevertheless, FeLV was not detectable by quantitative real-time PCR and no reverse transcriptase activity was detectable by product-enhanced reverse transcriptase assay in the plasma of cheetahs or the supernatants from cultures of peripheral blood mononuclear cells. The presence of antibodies to gammaretroviruses in clinically healthy specimens may be caused either by infection with a low-pathogenic retrovirus or by the expression of endogenous retroviral sequences. The strong humoral immune responses to FeLV vaccination demonstrate that cheetahs can respond to the vaccine and that vaccination against FeLV infection may be beneficial should FeLV infection ever become a threat, as was seen in Iberian lynx and Florida panthers.", "journal": "Clinical and vaccine immunology : CVI", "doi": "10.1128/CVI.00705-14", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25795718", "author": "Mercurio S", "n_authors": 14, "title": "The heme exporter Flvcr1 regulates expansion and differentiation of committed erythroid progenitors by controlling intracellular heme accumulation.", "abstract": "Feline leukemia virus subgroup C receptor 1 (Flvcr1) encodes two heme exporters: FLVCR1a, which localizes to the plasma membrane, and FLVCR1b, which localizes to mitochondria. Here, we investigated the role of the two Flvcr1 isoforms during erythropoiesis. We showed that, in mice and zebrafish, Flvcr1a is required for the expansion of committed erythroid progenitors but cannot drive their terminal differentiation, while Flvcr1b contributes to the expansion phase and is required for differentiation. FLVCR1a-down-regulated K562 cells have defective proliferation, enhanced differentiation, and heme loading in the cytosol, while FLVCR1a/1b-deficient K562 cells show impairment in both proliferation and differentiation, and accumulate heme in mitochondria. These data support a model in which the coordinated expression of Flvcr1a and Flvcr1b contributes to control the size of the cytosolic heme pool required to sustain metabolic activity during the expansion of erythroid progenitors and to allow hemoglobinization during their terminal maturation. Consistently, reduction or increase of the cytosolic heme rescued the erythroid defects in zebrafish deficient in Flvcr1a or Flvcr1b, respectively. Thus, heme export represents a tightly regulated process that controls erythropoiesis.", "journal": "Haematologica", "doi": "10.3324/haematol.2014.114488", "deposited_data": "Sim", "nuccore_ids": "2992366784, 3377526273, 3377526270, 2992366784, 2973648576, 2973648575, 2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556, 1450320932, 1450320925, 1450320892", "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25698488", "author": "Helfer-Hungerbuehler AK", "n_authors": 6, "title": "No benefit of therapeutic vaccination in clinically healthy cats persistently infected with feline leukemia virus.", "abstract": "Therapeutic vaccinations have a potential application in infections where no curative treatment is available. In contrast to HIV, efficacious vaccines for a cat retrovirus, feline leukemia virus (FeLV), are commercially available. However, the infection is still prevalent, and no effective treatment of the infection is known. By vaccinating persistently FeLV-infected cats and presenting FeLV antigens to the immune system of the host, e.g., in the form of recombinant and/or adjuvanted antigens, we intended to shift the balance toward an advantage of the host so that persistent infection could be overcome by the infected cat. Two commercially available FeLV vaccines efficacious in protecting naïve cats from FeLV infection were tested in six experimentally and persistently FeLV-infected cats: first, a canarypox-vectored vaccine, and second, an adjuvanted, recombinant envelope vaccine was repeatedly administered with the aim to stimulate the immune system. No beneficial effects on p27 antigen and plasma viral RNA loads, anti-FeLV antibodies, or life expectancy of the cats were detected. The cats were unable to overcome or decrease viremia. Some cats developed antibodies to FeLV antigens although not protective. Thus, we cannot recommend vaccinating persistently FeLV-infected cats as a means of improving their FeLV status, quality of life or life expectancy. We suggest testing of all cats for FeLV infection prior to FeLV vaccination.", "journal": "Vaccine", "doi": "10.1016/j.vaccine.2015.02.009", "deposited_data": "Sim", "nuccore_ids": "881837009", "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25687627", "author": "Tekelioglu BK", "n_authors": 6, "title": "A retrospective clinical and epidemiological study on feline coronavirus (FCoV) in cats in Istanbul, Turkey.", "abstract": "The presence of antibodies to feline coronavirus (FCoV) and feline immunodeficiency virus (FIV), together with feline leukemia virus (FeLV) antigen was investigated in 169 ill household and stray cats attending a veterinary surgery in Istanbul in 2009-14. The estimated FCoV and FIV seroprevalence (95% confidence intervals) were 37% (30-45%) and 11% (6-16%), respectively and FeLV prevalence was 1% (0-3%). FCoV seroprevalence increased until 2 years of age, was highest in 2014 and among household cats living with other cats and with outdoor access, and was lower in FIV seropositive compared to seronegative cats. Symptoms typically associated with wet feline infectious peritonitis (FIP) including ascites, abdominal distention or pleural effusion, coupled in many cases with non-antibiotic responsive fever, were observed in 19% (32/169) of cats, and 75% (24/32) of these cats were FCoV seropositive. FCoV seropositivity was also associated with a high white blood cell count, high plasma globulin, low plasma albumin and low blood urea nitrogen. The percentage of FCoV seropositive and seronegative cats that died in spite of supportive veterinary treatment was 33% (21/63) and 12% (13/106), respectively. These results indicate that FCoV is widespread and has a severe clinical impact in cats from Istanbul. Moreover, the incidence of FCoV infections could be rising, and in the absence of effective vaccination cat owners need to be made aware of ways to minimize the spread of this virus.", "journal": "Preventive veterinary medicine", "doi": "10.1016/j.prevetmed.2015.01.017", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25681660", "author": "Stuke K", "n_authors": 6, "title": "In response to letter to the editor (Regina Hofmann-Lehmann, Laura S. Levy and Brian Willett)--Comparing the efficacy of FeLV vaccines.", "abstract": null, "journal": "Vaccine", "doi": "10.1016/j.vaccine.2015.01.066", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25650060", "author": "Mori H", "n_authors": 3, "title": "The widely distributed hard tick, Haemaphysalis longicornis, can retain canine parvovirus, but not be infected in laboratory condition.", "abstract": "Ticks are known to transmit various pathogens, radically threatening humans and animals. Despite the close contact between ticks and viruses, our understanding on their interaction and biology is still lacking. The aim of this study was to experimentally assess the interaction between canine parvovirus (CPV) and a widely distributed hard tick, Haemaphysalis longicornis, in laboratory condition. After inoculation of CPV into the hemocoel of the ticks, polymerase chain reaction assay revealed that CPV persisted in inoculated unfed adult female ticks for 28 days. Canine parvovirus was recovered from the inoculated ticks using a cell culture, indicating that the virus retained intact in the ticks after inoculation, but significant positive reaction indicating virus infection was not detected in the tick organs by immunofluorescence antibody test using a monoclonal antibody. In the case of ticks inoculated with feline leukemia virus, the virus had shorter persistence in the ticks compared to CPV. These findings provide significant important information on the characteristic interaction of tick with non-tick-borne virus.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.14-0199", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25613718", "author": "Bęczkowski PM", "n_authors": 6, "title": "Neutralising antibody response in domestic cats immunised with a commercial feline immunodeficiency virus (FIV) vaccine.", "abstract": "Across human and veterinary medicine, vaccines against only two retroviral infections have been brought to market successfully, the vaccines against feline leukaemia virus (FeLV) and feline immunodeficiency virus (FIV). FeLV vaccines have been a global success story, reducing virus prevalence in countries where uptake is high. In contrast, the more recent FIV vaccine was introduced in 2002 and the degree of protection afforded in the field remains to be established. However, given the similarities between FIV and HIV, field studies of FIV vaccine efficacy are likely to advise and inform the development of future approaches to HIV vaccination. Here we assessed the neutralising antibody response induced by FIV vaccination against a panel of FIV isolates, by testing blood samples collected from client-owned vaccinated Australian cats. We examined the molecular and phenotypic properties of 24 envs isolated from one vaccinated cat that we speculated might have become infected following natural exposure to FIV. Cats vaccinated against FIV did not display broadly neutralising antibodies, suggesting that protection may not extend to some virulent recombinant strains of FIV circulating in Australia.", "journal": "Vaccine", "doi": "10.1016/j.vaccine.2015.01.028", "deposited_data": "Sim", "nuccore_ids": "751136943, 751136941, 751136939, 751136937, 751136935, 751136933, 751136931, 751136929, 751136927, 751136925, 751136923, 751136921, 751136919, 751136917, 751136915, 751136913, 751136911, 751136909, 751136907, 751136905, 751136903, 751136901", "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25582857", "author": "Philip M", "n_authors": 8, "title": "Heme exporter FLVCR is required for T cell development and peripheral survival.", "abstract": "All aerobic cells and organisms must synthesize heme from the amino acid glycine and the tricarboxylic acid cycle intermediate succinyl CoA for incorporation into hemoproteins, such as the cytochromes needed for oxidative phosphorylation. Most studies on heme regulation have been done in erythroid cells or hepatocytes; however, much less is known about heme metabolism in other cell types. The feline leukemia virus subgroup C receptor (FLVCR) is a 12-transmembrane domain surface protein that exports heme from cells, and it was shown to be required for erythroid development. In this article, we show that deletion of Flvcr in murine hematopoietic precursors caused a complete block in αβ T cell development at the CD4(+)CD8(+) double-positive stage, although other lymphoid lineages were not affected. Moreover, FLVCR was required for the proliferation and survival of peripheral CD4(+) and CD8(+) T cells. These studies identify a novel and unexpected role for FLVCR, a major facilitator superfamily metabolite transporter, in T cell development and suggest that heme metabolism is particularly important in the T lineage.", "journal": "Journal of immunology (Baltimore, Md. : 1950)", "doi": "10.4049/jimmunol.1402172", "deposited_data": "Sim", "nuccore_ids": "924181778, 924181484, 133778932, 124486924", "bioproject_ids": "217178", "sra_ids": null}, {"year": 2015, "pmid": "25553598", "author": "Helfer-Hungerbuehler AK", "n_authors": 8, "title": "Long-term follow up of feline leukemia virus infection and characterization of viral RNA loads using molecular methods in tissues of cats with different infection outcomes.", "abstract": "It is a remarkable feature for a retrovirus that an infection with feline leukemia virus (FeLV) can result in various outcomes. Whereas some cats contain the infection and show a regressive course, others stay viremic and succumb to the infection within a few years. We hypothesized, that differences in the infection outcome might be causally linked to the viral RNA and provirus loads within the host and these loads therefore may give additional insight into the pathogenesis of the virus. Thus, the goals of the present study were to follow-up on experimentally infected cats and investigate tissues from cats with different infection outcomes using sensitive, specific TaqMan real-time PCR and reverse transcriptase (RT)-PCR. Nineteen experimentally FeLV-A/Glasgow-1-infected cats were categorized into having regressive, progressive or reactivated FeLV infection according to follow-up of FeLV p27 antigen detection in the blood. Remarkably, regressively infected cats showed detectable provirus and viral RNA loads in almost all of the 27 tested tissues, even many years after virus exposure. Moreover, some regressively infected cats reactivated the infection, and these cats had intermediate to high viral RNA and provirus tissue loads. The highest loads were found in viremic cats, independent of their health status. Tissues that represented sites of virus replication and shedding revealed the highest viral RNA and provirus loads, while the lowest loads were present in muscle and nerve tissues. A supplementary analysis of 20 experimentally infected cats with progressive infection revealed a median survival time of 3.1 years (range from 0.6 to 6.5 years); ∼70% (n=14) of these cats developed lymphoma, while leukemia and non-regenerative anemia were observed less frequently. Our results demonstrate that the different infection outcomes are associated with differences in viral RNA and provirus tissue loads. Remarkably, no complete clearance of FeLV viral RNA or provirus was detected in cats with regressive infection, even up to 12 years after exposure. In several cases FeLV reactivation could be observed. Thus, retroviruses integrated as provirus into the host's genome, could not be eliminated completely by the host and maintained their full potential for replication and reactivation.", "journal": "Virus research", "doi": "10.1016/j.virusres.2014.12.025", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25500005", "author": "Boesch A", "n_authors": 9, "title": "Evaluation of the effect of short-term treatment with the integrase inhibitor raltegravir (Isentress) on the course of progressive feline leukemia virus infection.", "abstract": "Cats persistently infected with the gammaretrovirus feline leukemia virus (FeLV) are at risk to die within months to years from FeLV-associated disease, such as immunosuppression, anemia or lymphoma/leukemia. The integrase inhibitor raltegravir has been demonstrated to reduce FeLV replication in vitro. The aim of the present study was to investigate raltegravir in vivo for its safety and efficacy to suppress FeLV replication. The safety was tested in three naïve specified pathogen-free (SPF) cats during a 15 weeks treatment period (initially 20mg then 40mg orally b.i.d.). No adverse effects were noted. The efficacy was tested in seven persistently FeLV-infected SPF cats attained from 18 cats experimentally exposed to FeLV-A/Glasgow-1. The seven cats were treated during nine weeks (40mg then 80mg b.i.d.). Raltegravir was well tolerated even at the higher dose. A significant decrease in plasma viral RNA loads (∼5×) was found; however, after treatment termination a rebound effect was observed. Only one cat developed anti-FeLV antibodies and viral RNA loads remained decreased after treatment termination. Of note, one of the untreated FeLV-A infected cats developed fatal FeLV-C associated anemia within 5 weeks of FeLV-A infection. Moreover, progressive FeLV infection was associated with significantly lower enFeLV loads prior to infection supporting that FeLV susceptibility may be related to the genetic background of the cat. Overall, our data demonstrate the ability of raltegravir to reduce viral replication also in vivo. However, no complete control of viremia was achieved. Further investigations are needed to find an optimized treatment against FeLV. (250 words).", "journal": "Veterinary microbiology", "doi": "10.1016/j.vetmic.2014.10.031", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25462351", "author": "Argaw T", "n_authors": 2, "title": "Mutations altering the gammaretrovirus endoproteolytic motif affect glycosylation of the envelope glycoprotein and early events of the virus life cycle.", "abstract": "Previously, we found that mutation of glutamine to proline in the endoproteolytic cleavage signal of the PERV-C envelope (RQKK to RPKK) resulted in non-infectious vectors. Here, we show that RPKK results in a non-infectious vector when placed in not only a PERV envelope, but also the envelope of a related gammaretrovirus, FeLV-B. The amino acid substitutions do not prevent envelope precursor cleavage, viral core and genome assembly, or receptor binding. Rather, the mutations result in the formation of hyperglycosylated glycoprotein and a reduction in the reverse transcribed minus strand synthesis and undetectable 2-LTR circular DNA in cells exposed to vectors with these mutated envelopes. Our findings suggest novel functions associated with the cleavage signal sequence that may affect trafficking through the glycosylation machinery of the cell. Further, the glycosylation status of the envelope appears to impact post-binding events of the viral life cycle, either membrane fusion, internalization, or reverse transcription.", "journal": "Virology", "doi": "10.1016/j.virol.2014.11.010", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25444783", "author": "Hofmann-Lehmann R", "n_authors": 3, "title": "Comparing the efficacy of FeLV vaccines: comment on: Stuke, K. et al. Efficacy of an inactivated FeLV vaccine compared to a recombinant FeLV vaccine in minimum age cats following virulent FeLV challenge. Vaccine 2014;32(22):2599-603.", "abstract": null, "journal": "Vaccine", "doi": "10.1016/j.vaccine.2014.10.038", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25395593", "author": "Sakaguchi S", "n_authors": 4, "title": "A soluble envelope protein of endogenous retrovirus (FeLIX) present in serum of domestic cats mediates infection of a pathogenic variant of feline leukemia virus.", "abstract": "T-lymphotropic feline leukemia virus (FeLV-T), a highly pathogenic variant of FeLV, induces severe immunosuppression in cats. FeLV-T is fusion defective because in its PHQ motif, a gammaretroviral consensus motif in the N terminus of an envelope protein, histidine is replaced with aspartate. Infection by FeLV-T requires FeLIX, a truncated envelope protein encoded by an endogenous FeLV, for transactivation of infectivity and Pit1 for binding FeLIX. Although Pit1 is present in most tissues in cats, the expression of FeLIX is limited to certain cells in lymphoid organs. Therefore, the host cell range of FeLV-T was thought to be restricted to cells expressing FeLIX. However, because FeLIX is a soluble factor and is expressed constitutively in lymphoid organs, we presumed it to be present in blood and evaluated its activities in sera of various mammalian species using a pseudotype assay. We demonstrated that cat serum has FeLIX activity at a functional level, suggesting that FeLIX is present in the blood and that FeLV-T may be able to infect cells expressing Pit1 regardless of the expression of FeLIX in vivo. In addition, FeLIX activities in sera were detected only in domestic cats and not in other feline species tested. To our knowledge, this is the first report to prove that a large amount of truncated envelope protein of endogenous retrovirus is circulating in the blood to facilitate the infection of a pathogenic exogenous retrovirus.", "journal": "The Journal of general virology", "doi": "10.1099/vir.0.071688-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25380363", "author": "Mora M", "n_authors": 5, "title": "Feline immunodeficiency virus and feline leukemia virus infection in free-ranging guignas (Leopardus guigna) and sympatric domestic cats in human perturbed landscapes on Chiloé Island, Chile.", "abstract": "Feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) are two of the most common viruses affecting domestic cats (Felis catus). During the last two decades, reports show that both viruses also infect or affect other species of the family Felidae. Human landscape perturbation is one of the main causes of emerging diseases in wild animals, facilitating contact and transmission of pathogens between domestic and wild animals. We investigated FIV and FeLV infection in free-ranging guignas (Leopardus guigna) and sympatric domestic cats in human perturbed landscapes on Chiloé Island, Chile. Samples from 78 domestic cats and 15 guignas were collected from 2008 to 2010 and analyzed by PCR amplification and sequencing. Two guignas and two domestic cats were positive for FIV; three guignas and 26 domestic cats were positive for FeLV. The high percentage of nucleotide identity of FIV and FeLV sequences from both species suggests possible interspecies transmission of viruses, facilitated by increased contact probability through human invasion into natural habitats, fragmentation of guigna habitat, and poultry attacks by guignas. This study enhances our knowledge on the transmission of pathogens from domestic to wild animals in the global scenario of human landscape perturbation and emerging diseases.", "journal": "Journal of wildlife diseases", "doi": "10.7589/2014-04-114", "deposited_data": "Sim", "nuccore_ids": "1191077519", "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25367344", "author": "Linek M", "n_authors": 10, "title": "Nonthymoma-associated exfoliative dermatitis in 18 cats.", "abstract": "Exfoliative dermatitis has been described in cats as a paraneoplastic skin disease associated with thymoma. There are anecdotal reports of cases without thymoma, with various suspected aetiologies. To identify common features, underlying causes, response to therapy and outcome of nonthymoma-associated exfoliative dermatitis in cats. Retrospective analysis was carried out of cases presented to dermatology referral centres or cases submitted for histopathological examination. Detailed historical and clinical data were obtained and evaluated statistically. Histopathology was reviewed in a blinded fashion by three dermatopathologists, and PCR for herpesvirus was performed. Eighteen cats fulfilled all inclusion criteria. There was no sex, age or breed predisposition. All cats presented with severe generalized (77%) or multifocal exfoliation (23%); 12 cats were severely depressed. In all cats, thymoma was excluded radiographically and feline leukaemia virus tests were negative. Additional imaging procedures in 14 cats and postmortem examination in two cats did not detect neoplasia. Histopathology revealed interface dermatitis, mural interface folliculitis and sebaceous adenitis indistinguishable from findings in thymoma-associated cases. PCR for herpes DNA was negative. No aetiology was identified. Treatment in 12 cases consisted of immunosuppressive doses of corticosteroids and/or ciclosporin; one responded to antibiotics, one to shampoo, two went into spontaneous remission, and two did not receive any therapy and were euthanized. Nonthymoma-associated exfoliative dermatitis in cats is clinically and histopathologically indistinguishable from thymoma-associated cases. Most cases benefit from immunosuppressive therapy; therefore, an immunopathological response to an undefined trigger is suspected.", "journal": "Veterinary dermatology", "doi": "10.1111/vde.12169", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25228167", "author": "Duarte A", "n_authors": 11, "title": "Molecular detection of haemotropic Mycoplasma species in urban and rural cats from Portugal.", "abstract": "The aim of the present study was to evaluate the prevalence of haemoplasma infection in cats in Portugal and to assess risk factors for infection. Real-time polymerase chain reaction techniques were used to assess 236 urban and rural cats from central and southern Portugal. The overall prevalence of haemoplasma in the target population was 27.1% (64/236), with individual species' prevalences as follows: 17.8% (42/236) 'Candidatus Mycoplasma haemominutum' (CMhm), 14.4% (34/236) Mycoplasma haemofelis (Mhf) and only 5.9% (14/236) 'Candidatus Mycoplasma turicensis' (CMt). Multiple infections were detected in 8.1% (19/236) of the samples, with triple and double infections with Mhf and CMhm being most commonly detected (5.9% [14/236] of cats). Haemoplasma infection was significantly higher in shelter cats (P = 0.015) than in cats with other lifestyles (eg, free-roaming/house pet/blood donors). Haemoplasma prevalence was also higher in cats with feline immunodeficiency virus infection (FIV; P = 0.011). Although sex was not significantly associated with haemoplasma infection (P = 0.050), CMt was predominantly found in males (P = 0.032). Also, the presence of haemoplasma multiple infections was statistically associated with being in a shelter (P = 0.021), male (P = 0.057) and with FIV co-infection (P = 0.004). No evidence of an association between haemoplasma infection and geographical location, age or feline leukaemia virus co-infection was found. The results obtained in our study are consistent with the documented worldwide prevalence of feline haemoplasma infections, suggesting that the three main feline haemoplasma species are common in Portugal.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X14550172", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "24903757", "author": "Santagostino SF", "n_authors": 7, "title": "Feline upper respiratory tract lymphoma: site, cyto-histology, phenotype, FeLV expression, and prognosis.", "abstract": "Lymphoma is the most common feline upper respiratory tract (URT) tumor. Primary nasal and nasopharyngeal lymphomas have been evaluated as distinct pathological entities; however, data on their differing clinical behavior are missing. A total of 164 endoscopic- guided URT pinch biopsies were formalin fixed and routinely processed. Imprint cytological specimens were stained with May Grünwald-Giemsa. Immunohistochemistry for anti-CD20, CD3, FeLVp27, and FeLVgp70 was performed. Prognostic significance of clinicopathological variables was investigated by univariate and multivariate analysis. Lymphoma was diagnosed in 39 cats (24%). Most cats with lymphoma were domestic shorthair (32 [82%]), were male (F/M = 0.56), and had a mean age of 10.3 years (range, 1-16 years). Lymphomas were primary nasal in 26 cats (67%), nasopharyngeal in 6 (15%), and in both locations (combined lymphomas) in 7 cats (18%). Neoplastic growth pattern was diffuse in 35 cases (90%) and nodular in 4 (10%). Epitheliotropism was observed in 10 cases (26%). Tumor cells were large in 15 cases, were small and medium in 11 cases each, and 2 had mixed cell size. Submucosal lymphoplasmacytic inflammation was observed in 23 cases (59%). Cytology was diagnostic for lymphoma in 12 of 25 cases (48%). A B-cell origin prevailed (34 [87%]). Feline leukemia virus (FeLV) p27 or gp70 antigen was detected in 21 lymphomas (54%). URT lymphomas were aggressive, with survival varying from 0 to 301 days (mean, 53 days). Epitheliotropism in 8 B-cell lymphomas (80%) and in 2 T-cell lymphomas (20%) correlated with prolonged survival. Age younger or older than 10 years had a negative prognostic value. Lymphoplasmacytic inflammation and FeLV infection may represent favoring factors for URT lymphoma development.", "journal": "Veterinary pathology", "doi": "10.1177/0300985814537529", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "24820998", "author": "Roberts ES", "n_authors": 4, "title": "Effect of high-dose ciclosporin on the immune response to primary and booster vaccination in immunocompetent cats.", "abstract": "Ciclosporin (Atopica oral solution for cats 100 mg/ml; Novartis Animal Health) was recently approved for use in cats with feline hypersensitivity dermatitis. The immunosuppressant effect of ciclosporin on the ability of cats to mount an immune response following vaccination was determined. Thirty-two healthy, immunocompetent adult cats (16 cats/group) were treated with either ciclosporin for 56 days at a dose of 24 mg/kg once daily or sham dosed. Prior to treatment, cats had an adequate antibody response to primary vaccination against feline calicivirus (FCV), feline herpesvirus-1 (FHV-1), feline panleukopenia virus (FPV), feline leukemia virus (FeLV) and rabies. Booster vaccination or novel vaccination with feline immunodeficiency virus (FIV) was administered 28 days after initiation of treatment with ciclosporin. There were no differences between the ciclosporin-treated and control cats for FCV and FPV antibody titers following booster vaccination. There were delays/reductions in antibody response to FHV-1, FeLV and rabies in treated cats; however, adequate protection was achieved in response to all booster vaccinations. Following primary vaccination with FIV, control cats showed a response, but treated cats showed no antibody production. Adverse events commonly associated with ciclosporin treatment, including diarrhea/loose stool, vomiting, salivation and regurgitation, were reported. In adult cats treated with 24 mg/kg/day of ciclosporin (more than three times the therapeutic dose), vaccine titer levels were adequate for protection following booster vaccination. In contrast, treated cats failed to mount a humoral response to a novel (FIV) vaccination, suggesting that memory B-cell immune responses remain intact during repeated high-dose ciclosporin administration in cats, but that primary immune responses are impaired.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X14533550", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "28491434", "author": "Mosca A", "n_authors": 2, "title": "Life-threatening haematological complication occurring in a cat after chronic carbimazole administration.", "abstract": "An 11-year-old spayed female domestic shorthair cat with a history of hyperthyroidism treated with carbimazole for 7 months was presented for a check-up after a few episodes of vomiting. The cat had been receiving prednisolone at 0.5 mg/kg PO q12h for recent pancreatitis and concurrent inflammation of liver and small intestines confirmed by biopsies. Clinical examination revealed pale mucous membranes with a capillary refill time of <2 s. Haematology showed severely decreased packed cell volume (16%), and increased prothrombin time (42 s), partial thromboplastin time (>120 s) and fibrinogen serum concentration (3.5 g/l). Morphological changes of thrombocytes in the absence of thrombocytopenia were also noted. In-saline agglutination test was positive. Abdominal radiographic and ultrasonographic examinations excluded the presence of organ abnormalities and peritoneal effusion. Blood biochemistry was unremarkable. Feline leukaemia virus and feline immunodeficiency virus tests were negative. On the basis of these findings, immune-mediated anaemia secondary to chronic carbimazole administration was suspected. Prednisolone was increased to 2 mg/kg PO q24h and carbimazole tablets were stopped. Despite close monitoring and intensive care, the cat died the same evening of admission to the hospital. This report suggests that severe haemotoxicity may occur as a sequel of chronic carbimazole administration in cats. Routine bloodwork and accurate follow-up of cats under treatment with thyrotoxic therapy may be advisable, in order to detect haematological changes before lethal complications occur.", "journal": "JFMS open reports", "doi": "10.1177/2055116916668198", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "28491433", "author": "Liu J", "n_authors": 5, "title": "Evaluation of rapid diagnostic test kits for feline leukemia virus infection using samples from naturally infected cats.", "abstract": "Feline leukemia virus (FeLV) is a potentially life-threatening oncogenic retrovirus. The p27 viral core protein is produced by the virus in infected feline cells, is found in the cytoplasm in several blood cells and can be free in the serum and plasma. ELISA or particle-based immunoassay are commonly used to detect the presence of the p27 core protein in samples obtained from blood. The objective of this study was to compare the performance of several in-clinic tests: the SNAP Feline Triple Test (IDEXX Laboratories), the WITNESS FeLV-FIV Test (Zoetis) and the VetScan Feline FeLV/FIV Rapid Test (Abaxis). The sample population (100 positive, 105 negative samples) consisted of serum and plasma samples submitted to IDEXX's worldwide reference laboratory for feline retrovirus testing. Virus isolation and reverse transcriptase PCR results were not available and so samples were judged to be positive or negative based on the results of the ViraCHEK FeLV (Zoetis) microtiter plate assay. The percentage of samples positive and negative for FeLV p27 antigen using the three in-clinic tests compared with the ViraCHEK method were as follows: IDEXX Feline Triple (positive 98.0%, negative 100%); Zoetis WITNESS (positive 79.0%, negative 97.1%); Abaxis VetScan (positive 73.0%, negative 97.1%). The SNAP Feline Triple Test demonstrated a high level of agreement for FeLV-positive and FeLV-negative samples when assessed in this model. Results of FeLV assays can vary among tests.", "journal": "JFMS open reports", "doi": "10.1177/2055116916667757", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "28491420", "author": "Westman ME", "n_authors": 7, "title": "Seroprevalence of feline immunodeficiency virus and feline leukaemia virus in Australia: risk factors for infection and geographical influences (2011-2013).", "abstract": "Our aim was to: (i) determine the current seroprevalence of feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV) in three large cohorts of cats from Australia; and (ii) investigate potential risk factors for retroviral infection. Cohort 1 (n = 2151 for FIV, n = 2241 for FeLV) consisted of cats surrendered to a shelter on the west coast of Australia (Perth, Western Australia [WA]). Cohort 2 (n = 2083 for FIV, n = 2032 for FeLV) consisted of client-owned cats with outdoor access recruited from around Australia through participating veterinary clinics. Cohort 3 (n = 169 for FIV, n = 166 for FeLV) consisted of cats presenting to Murdoch University Veterinary Hospital for a variety of reasons. Fresh whole blood was collected and tested using a commercially available point-of-care lateral flow ELISA kit that detects p27 FeLV antigen and antibodies to FIV antigens (p15 and p24) (cohorts 1 and 2), or one of two lateral flow immunochromatography kits that detect p27 antigen and antibodies to FIV antigen (p24 and/or gp40) (cohort 3). Data recorded for cats in cohort 2 included signalment, presenting complaint and postcode, allowing investigation of risk factors for FIV or FeLV infection, as well as potential geographical 'hot spots' for infection. The seroprevalence of FIV was 6% (cohort 1), 15% (cohort 2) and 14% (cohort 3), while the seroprevalence of FeLV was 1%, 2% and 4% in the same respective cohorts. Risk factors for FIV infection among cats in cohort 2 included age (>3 years), sex (male), neutering status (entire males) and location (WA had a significantly higher FIV seroprevalence compared with the Australian Capital Territory, New South Wales and Victoria). Risk factors for FeLV infection among cats in cohort 2 included health status ('sick') and location (WA cats were approximately three times more likely to be FeLV-infected compared with the rest of Australia). No geographical hot spots of FIV infection were identified. Both FIV and FeLV remain important infections among Australian cats. WA has a higher seroprevalence of both feline retroviruses compared with the rest of Australia, which has been noted in previous studies. A lower neutering rate for client-owned male cats is likely responsible for the higher seroprevalence of FIV infection in WA cats, while the reason for the higher seroprevalence of FeLV in WA cats is currently unknown.", "journal": "JFMS open reports", "doi": "10.1177/2055116916646388", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "27923065", "author": "Chiabrando D", "n_authors": 14, "title": "Mutations in the Heme Exporter FLVCR1 Cause Sensory Neurodegeneration with Loss of Pain Perception.", "abstract": "Pain is necessary to alert us to actual or potential tissue damage. Specialized nerve cells in the body periphery, so called nociceptors, are fundamental to mediate pain perception and humans without pain perception are at permanent risk for injuries, burns and mutilations. Pain insensitivity can be caused by sensory neurodegeneration which is a hallmark of hereditary sensory and autonomic neuropathies (HSANs). Although mutations in several genes were previously associated with sensory neurodegeneration, the etiology of many cases remains unknown. Using next generation sequencing in patients with congenital loss of pain perception, we here identify bi-allelic mutations in the FLVCR1 (Feline Leukemia Virus subgroup C Receptor 1) gene, which encodes a broadly expressed heme exporter. Different FLVCR1 isoforms control the size of the cytosolic heme pool required to sustain metabolic activity of different cell types. Mutations in FLVCR1 have previously been linked to vision impairment and posterior column ataxia in humans, but not to HSAN. Using fibroblasts and lymphoblastoid cell lines from patients with sensory neurodegeneration, we here show that the FLVCR1-mutations reduce heme export activity, enhance oxidative stress and increase sensitivity to programmed cell death. Our data link heme metabolism to sensory neuron maintenance and suggest that intracellular heme overload causes early-onset degeneration of pain-sensing neurons in humans.", "journal": "PLoS genetics", "doi": "10.1371/journal.pgen.1006461", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "27870069", "author": "Weeden AL", "n_authors": 5, "title": "Suspected myelodysplastic/myeloproliferative neoplasm in a feline leukemia virus-negative cat.", "abstract": "A 10-year-old castrated Domestic Short-Haired cat was presented to a primary care veterinarian for a wellness examination and laboratory examination for monitoring of diabetes mellitus. The CBC revealed marked thrombocytosis, leukopenia and macrocytic, normochromic anemia. The cat tested negative for FeLV and feline immunodeficiency virus, but was positive for Mycoplasma haemominutum by PCR. Hematologic abnormalities were not responsive to therapy, so a repeat CBC and a bone marrow aspiration for cytology were performed. Additional blood smear findings included anisocytosis with megaloblastic erythroid precursors, large platelets, eosinophilic myelocytes and metamyelocytes, and rare unidentified blasts. The bone marrow smear was highly cellular, and the cytologic pattern was consistent with myelodysplastic syndrome with an erythroid predominance. At that time, 15% blasts were present. The cat was treated with a vitamin K", "journal": "Veterinary clinical pathology", "doi": "10.1111/vcp.12426", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "27825735", "author": "Galdo Novo S", "n_authors": 4, "title": "Viral diagnostic criteria for Feline immunodeficiency virus and Feline leukemia virus infections in domestic cats from Buenos Aires, Argentina.", "abstract": "A cross-sectional study was carried out on cats attending the Small Animal Hospital at the Faculty of Veterinary Sciences of the University of Buenos Aires to assess the prevalence and associated risk factors of Feline immunodeficiency virus (FIV) and Feline leukemia virus (FeLV) in the city of Buenos Aires, Argentina. Blood samples from 255 cats with symptoms compatible with FIV or FeLV infection, collected between 2009 and 2013 were analyzed by serology (immunochromatography, IA) and by hemi-nested PCR (n-PCR). The IA and n-PCR assays showed similar percentages of positivity for FIV while the n-PCR test was more sensitive for FeLV. Differences between the diagnostic tests and their choice according to the age of the animal are discussed. The clinical histories of ninety of the 255 cats showed blood profiles similar to others previously reported and revealed a higher risk of infection in male adult cats with outdoor access.", "journal": "Revista Argentina de microbiologia", "doi": "10.1016/j.ram.2016.07.003", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "27436441", "author": "Rydzewski L", "n_authors": 9, "title": "Identification of a novel feline large granular lymphoma cell line (S87) as non-MHC-restricted cytotoxic T-cell line and assessment of its genetic instability.", "abstract": "Feline large granular lymphocyte lymphomas are rare but very aggressive tumors with a poor prognosis. In this study, a cell line from an abdominal effusion of a cat with large granular lymphoma was characterized. Immunophenotype staining was positive for CD3 and CD45R, and negative for CD4, CD8, CD56, CD79α, BLA.36 and NK1. A TCR γ gene rearrangement was detectable by PARR. Neither FeLV antigen nor exogenous FeLV provirus could be detected. A chromosomal instability associated with a centrosome hyperamplification could also be determined. The cell line is able to lyse target cells without antigen presentation or interaction with antigen presenting cells. Therefore, these cells were classified as genetically instable non-MHC-restricted cytotoxic T cells with large granular lymphocyte morphology.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2016.05.012", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "27402672", "author": "Best CM", "n_authors": 9, "title": "Maternal iron status during pregnancy compared with neonatal iron status better predicts placental iron transporter expression in humans.", "abstract": "The placenta richly expresses nonheme and heme Fe transport proteins. To address the impact of maternal and neonatal Fe status and hepcidin on the regulation of these proteins, mRNA expression and protein abundance of nonheme and heme Fe transport proteins were evaluated in placental tissue from 154 adolescents. Regression analyses found maternal Fe status was significantly associated with multiple placental nonheme and heme transporters, whereas neonatal Fe status was related to only 3 heme transporters. Across statistical analyses, maternal Fe status was consistently associated with the placental nonheme Fe importer transferrin receptor 1 (TfR1). Protein abundance of TfR1 was related to midgestation maternal serum ferritin (SF) (β = -0.32; P = 0.005) and serum TfR (β = 0.25; P = 0.024). Protein abundance of the heme importer, proton-coupled folate transporter, was related to neonatal SF (β = 0.30; P = 0.016) and serum TfR (β = -0.46; P < 0.0001). Neonatal SF was also related to mRNA expression of the heme exporter feline leukemia virus subgroup C receptor 1 (β = -0.30; P = 0.004). In summary, maternal Fe insufficiency during pregnancy predicts increased expression of the placental nonheme Fe transporter TfR1. Associations between placental heme Fe transporters and neonatal Fe status require further study.-Best, C. M., Pressman, E. K., Cao, C., Cooper, E., Guillet, R., Yost, O. L., Galati, J., Kent, T. R., O'Brien, K. O. Maternal iron status during pregnancy compared with neonatal iron status better predicts placental iron transporter expression in humans.", "journal": "FASEB journal : official publication of the Federation of American Societies for Experimental Biology", "doi": "10.1096/fj.201600069R", "deposited_data": "Sim", "nuccore_ids": "2462592181, 2462592179, 2462592178, 2462592177, 2462592176, 2462592175, 2462592174, 2462592173, 2462592171, 2462592169, 2462592167, 2462592166, 2217345685, 1676362562, 1676317495, 1675178475, 1519315083", "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "27374905", "author": "Hernandez LA", "n_authors": 3, "title": "Particle and subunit-based hemagglutinin vaccines provide protective efficacy against H1N1 influenza in pigs.", "abstract": "The increasing diversity of influenza strains circulating in swine herds escalates the potential for the emergence of novel pandemic viruses and highlights the need for swift development of new vaccines. Baculovirus has proven to be a flexible platform for the generation of recombinant forms of hemagglutinin (HA) including subunit, VLP-displayed, and baculovirus-displayed antigens. These presentations have been shown to be efficacious in mouse, chicken, and ferret models but little is known about their immunogenicity in pigs. To assess the utility of these HA presentations in swine, Baculovirus constructs expressing HA fused to swine IgG2a Fc, displayed in a FeLV gag VLP, or displayed in the baculoviral envelope were generated. Vaccines formulated with these antigens wer The e administered to groups of pigs who were subsequently challenged with H1α cluster H1N1 swine influenza virus (SIV) A/Swine/Indiana/1726/88. Our results demonstrate that vaccination with any of these three vaccines elicits robust hemagglutinin inhibition titers in the serum and decreased the severity of SIV-associated lung lesions after challenge when compared to placebo-vaccinated controls. In addition, the number of pigs with virus detected in the lungs and nasal passages was reduced. Taken together, the results demonstrate that these recombinant approaches expressed with the baculovirus expression vector system may be viable options for development of SIV vaccines for swine.", "journal": "Veterinary microbiology", "doi": "10.1016/j.vetmic.2016.05.011", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "27260813", "author": "Westman ME", "n_authors": 4, "title": "Diagnosing feline immunodeficiency virus (FIV) infection in FIV-vaccinated and FIV-unvaccinated cats using saliva.", "abstract": "We recently showed that two immunochromatography point-of-care FIV antibody test kits (Witness FeLV/FIV and Anigen Rapid FIV/FeLV) were able to correctly assign FIV infection status, irrespective of FIV vaccination history, using whole blood as the diagnostic specimen. A third FIV antibody test kit, SNAP FIV/FeLV Combo (an enzyme-linked immunosorbent assay [ELISA]), was unable to differentiate antibodies produced in response to FIV vaccination from those incited by FIV infection. The aim of this study was to determine if saliva is a suitable diagnostic specimen using the same well characterized feline cohort. FIV infection status of these cats had been determined previously using a combination of serology, polymerase chain reaction (PCR) testing and virus isolation. This final assignment was then compared to results obtained using saliva as the diagnostic specimen utilizing the same three point-of-care FIV antibody test kits and commercially available PCR assay (FIV RealPCR). In a population of cats where one third (117/356; 33%) were FIV-vaccinated, both immunochromatography test kits accurately diagnosed FIV infection using saliva via a centrifugation method, irrespective of FIV vaccination history. For FIV diagnosis using saliva, the specificity of Anigen Rapid FIV/FeLV and Witness FeLV/FIV was 100%, while the sensitivity of these kits was 96% and 92% respectively. SNAP FIV/FeLV Combo respectively. SNAP FIV/FeLV Combo had a specificity of 98% and sensitivity of 44%, while FIV RealPCR testing had a specificity of 100% and sensitivity of 72% using saliva. A revised direct method of saliva testing was trialed on a subset of FIV-infected cats (n=14), resulting in 14, 7 and 0 FIV positive results using Anigen Rapid FIV/FeLV, Witness FeLV/FIV and SNAP FIV/FeLV Combo, respectively. These results demonstrate that saliva can be used to diagnose FIV infection, irrespective of FIV vaccination history, using either a centrifugation method (Anigen Rapid FIV/FeLV and Witness FeLV/FIV) or a direct method (Anigen Rapid FIV/FeLV). Collection of a saliva specimen therefore provides an acceptable alternative to venipuncture (i) in fractious cats where saliva may be easier to obtain than whole blood, (ii) in settings when a veterinarian or trained technician is unavailable to collect blood and (iii) in shelters where FIV testing is undertaken prior to adoption but additional blood testing is not required.", "journal": "Comparative immunology, microbiology and infectious diseases", "doi": "10.1016/j.cimid.2016.03.006", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "27097319", "author": "Gilroy KL", "n_authors": 12, "title": "Gamma-Retrovirus Integration Marks Cell Type-Specific Cancer Genes: A Novel Profiling Tool in Cancer Genomics.", "abstract": "Retroviruses have been foundational in cancer research since early studies identified proto-oncogenes as targets for insertional mutagenesis. Integration of murine gamma-retroviruses into the host genome favours promoters and enhancers and entails interaction of viral integrase with host BET/bromodomain factors. We report that this integration pattern is conserved in feline leukaemia virus (FeLV), a gamma-retrovirus that infects many human cell types. Analysis of FeLV insertion sites in the MCF-7 mammary carcinoma cell line revealed strong bias towards active chromatin marks with no evidence of significant post-integration growth selection. The most prominent FeLV integration targets had little overlap with the most abundantly expressed transcripts, but were strongly enriched for annotated cancer genes. A meta-analysis based on several gamma-retrovirus integration profiling (GRIP) studies in human cells (CD34+, K562, HepG2) revealed a similar cancer gene bias but also remarkable cell-type specificity, with prominent exceptions including a universal integration hotspot at the long non-coding RNA MALAT1. Comparison of GRIP targets with databases of super-enhancers from the same cell lines showed that these have only limited overlap and that GRIP provides unique insights into the upstream drivers of cell growth. These observations elucidate the oncogenic potency of the gamma-retroviruses and support the wider application of GRIP to identify the genes and growth regulatory circuits that drive distinct cancer types.", "journal": "PloS one", "doi": "10.1371/journal.pone.0154070", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "27037112", "author": "Silva CP", "n_authors": 5, "title": "Molecular detection of Feline Leukemia Virus in free-ranging jaguars (Panthera onca) in the Pantanal region of Mato Grosso, Brazil.", "abstract": null, "journal": "The Brazilian journal of infectious diseases : an official publication of the Brazilian Society of Infectious Diseases", "doi": "10.1016/j.bjid.2016.01.005", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "27034392", "author": "Kaye S", "n_authors": 8, "title": "Role of Feline Immunodeficiency Virus in Lymphomagenesis--Going Alone or Colluding?", "abstract": "Feline immunodeficiency virus (FIV) is a naturally occurring lentivirus of domestic and nondomestic feline species. Infection in domestic cats leads to immune dysfunction via mechanisms similar to those caused by human immunodeficiency virus (HIV) and, as such, is a valuable natural animal model for acquired immunodeficiency syndrome (AIDS) in humans. An association between FIV and an increased incidence of neoplasia has long been recognized, with frequencies of up to 20% in FIV-positive cats recorded in some studies. This is similar to the rate of neoplasia seen in HIV-positive individuals, and in both species neoplasia typically requires several years to arise. The most frequently reported type of neoplasia associated with FIV infection is lymphoma. Here we review the possible mechanisms involved in FIV lymphomagenesis, including the possible involvement of coinfections, notably those with gamma-herpesviruses.", "journal": "ILAR journal", "doi": "10.1093/ilar/ilv047", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "27012922", "author": "Spada E", "n_authors": 7, "title": "Prevalence of Leishmania infantum and co-infections in stray cats in northern Italy.", "abstract": "Stray cats in the city of Milan, Italy, were tested for Leishmania infantum and other selected infections. Twenty-seven cats (30.0%) were seroreactive by indirect fluorescent antibody test (IFAT), with an antibody titer of 1:40 for 16 (17.7%) cats and 1:80 (cut-off for feline L. infantum infection) for 11 (12.2%) cats. One blood (1.1%) and one popliteal lymph node (1.1%) sample tested positive by real-time polymerase chain reaction; no oculoconjunctival swabs tested positive. Feline immunodeficiency virus, feline leukemia virus, and feline coronavirus (FCoV) seroprevalence determined by enzyme-linked immunosorbent assay was 6.1, 6.1, and 39.0%, respectively. Toxoplasma gondii, Bartonella henselae, and Chlamydophila felis prevalence determined by IFAT was 29.3, 17.1, and 17.1%, respectively. The frequency of seroreactivity to L. infantum was significantly higher in FCoV-seropositive cats (OR=4.4, P=0.04). L. infantum-infected stray cats in Milan have a high seropositivity rate, comparable to that of cats in areas endemic for leishmaniosis.", "journal": "Comparative immunology, microbiology and infectious diseases", "doi": "10.1016/j.cimid.2016.03.001", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "27006955", "author": "Philip M", "n_authors": 4, "title": "TLR Stimulation Dynamically Regulates Heme and Iron Export Gene Expression in Macrophages.", "abstract": "Pathogenic bacteria have evolved multiple mechanisms to capture iron or iron-containing heme from host tissues or blood. In response, organisms have developed defense mechanisms to keep iron from pathogens. Very little of the body's iron store is available as free heme; rather nearly all body iron is complexed with heme or other proteins. The feline leukemia virus, subgroup C (FeLV-C) receptor, FLVCR, exports heme from cells. It was unknown whether FLVCR regulates heme-iron availability after infection, but given that other heme regulatory proteins are upregulated in macrophages in response to bacterial infection, we hypothesized that macrophages dynamically regulate FLVCR. We stimulated murine primary macrophages or macrophage cell lines with LPS and found that Flvcr is rapidly downregulated in a TLR4/MD2-dependent manner; TLR1/2 and TLR3 stimulation also decreased Flvcr expression. We identified several candidate TLR-activated transcription factors that can bind to the Flvcr promoter. Macrophages must balance the need to sequester iron from systemic circulating or intracellular pathogens with the macrophage requirement for heme and iron to produce reactive oxygen species. Our findings underscore the complexity of this regulation and point to a new role for FLVCR and heme export in macrophages responses to infection and inflammation.", "journal": "Journal of immunology research", "doi": "10.1155/2016/4039038", "deposited_data": "Sim", "nuccore_ids": "1907155394, 927442692, 924181778, 924181484, 228008384, 228008383, 195947362, 124486924", "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "26933095", "author": "Roccabianca P", "n_authors": 9, "title": "Cutaneous Lymphoma at Injection Sites: Pathological, Immunophenotypical, and Molecular Characterization in 17 Cats.", "abstract": "Feline primary cutaneous lymphomas (FPCLs) account for 0.2% to 3% of all lymphomas in cats and are more frequently dermal nonepitheliotropic small T-cell tumors. Emergence of FPCL seems unrelated to feline leukemia virus (FeLV) serological positivity or to skin inflammation. A total of 17 cutaneous lymphomas with a history of vaccine injection at the site of tumor development were selected from 47 FPCLs. Clinical presentation, histology, immunophenotype, FeLV p27 and gp70 expression, and clonality were assessed. A majority of male (12/17), domestic short-haired (13/17) cats with a mean age of 11.3 years was reported. Postinjection time of development ranged from 15 days to approximately 9 years in 5 cats. At diagnosis, 11 of 17 cats had no evidence of internal disease. Lymphomas developed in interscapular (8/17), thoracic (8/17), and flank (1/17) cutaneous regions; lacked epitheliotropism; and were characterized by necrosis (16/17), angiocentricity (13/17), angioinvasion (9/17), angiodestruction (8/17), and peripheral inflammation composed of lymphoid aggregates (14/17). FeLV gp70 and/or p27 proteins were expressed in 10 of 17 tumors. By means of World Health Organization classification, immunophenotype, and clonality, the lesions were categorized as large B-cell lymphoma (11/17), anaplastic large T-cell lymphoma (3/17), natural killer cell-like (1/17) lymphoma, or peripheral T-cell lymphoma (1/17). Lineage remained uncertain in 1 case. Cutaneous lymphomas at injection sites (CLIS) shared some clinical and pathological features with feline injection site sarcomas and with lymphomas developing in the setting of subacute to chronic inflammation reported in human beings. Persistent inflammation induced by the injection and by reactivation of FeLV expression may have contributed to emergence of CLIS.", "journal": "Veterinary pathology", "doi": "10.1177/0300985815623620", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "28491415", "author": "Ravicini S", "n_authors": 7, "title": "Prevalence of selected infectious disease agents in stray cats in Catalonia, Spain.", "abstract": "The objective of the current study was to investigate the prevalence rates of the following infectious agents in 116 stray cats in the Barcelona area of Spain:  Serum antibodies were used to estimate the prevalence of exposure to  Of the 116 cats, 63 (54.3%) had evidence of infection by  This study documents that shelter cats in Catalonia are exposed to many infectious agents with clinical and zoonotic significance, and that flea control is indicated for cats in the region.", "journal": "JFMS open reports", "doi": "10.1177/2055116916634109", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "26897097", "author": "Southard TL", "n_authors": 4, "title": "Holoprosencephaly and Pure Red Cell Aplasia in a Feline Leukaemia Virus-Positive Kitten.", "abstract": "A 9-month-old, female, domestic longhair cat with severe anaemia tested positive for feline leukaemia virus (FeLV) and was humanely destroyed and submitted for necropsy examination. Gross findings included a non-divided rostral telencephalon, consistent with semilobar holoprosencephaly. Histological examination of the bone marrow revealed an almost complete absence of erythroid precursor cells, consistent with pure red cell aplasia, and mild to moderate myelofibrosis. This case demonstrates a very unusual central nervous system defect, as well as an atypical presentation of pure red cell aplasia, in a FeLV-positive kitten.", "journal": "Journal of comparative pathology", "doi": "10.1016/j.jcpa.2016.01.006", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "26889025", "author": "Miyake A", "n_authors": 10, "title": "Novel Feline Leukemia Virus Interference Group Based on the env Gene.", "abstract": "Feline leukemia virus (FeLV) subgroups have emerged in infected cats via the mutation or recombination of the env gene of subgroup A FeLV (FeLV-A), the primary virus. We report the isolation and characterization of a novel env gene, TG35-2, and report that the TG35-2 pseudotype can be categorized as a novel FeLV subgroup. The TG35-2 envelope protein displays strong sequence identity to FeLV-A Env, suggesting that selection pressure in cats causes novel FeLV subgroups to emerge.", "journal": "Journal of virology", "doi": "10.1128/JVI.03229-15", "deposited_data": "Sim", "nuccore_ids": "1002623166, 1002623164", "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "28491412", "author": "Mari L", "n_authors": 3, "title": "Distal polyneuropathy in an adult Birman cat with toxoplasmosis.", "abstract": "A 6-year-old female spayed Birman cat presented with a history of weight loss, stiff and short-strided gait in the pelvic limbs and reluctance to jump, progressing to non-ambulatory tetraparesis over 6 weeks. Poor body condition, dehydration and generalised muscle wastage were evident on general examination. Neurological examination revealed mildly depressed mental status, non-ambulatory flaccid tetraparesis and severely decreased proprioception and spinal reflexes in all four limbs. The neuroanatomical localisation was to the peripheral nervous system. Haematology, feline immunodeficiency virus/feline leukaemia virus serology, serum biochemistry, including creatine kinase and thyroxine, thoracic radiographs and abdominal ultrasound did not reveal significant abnormalities. Electromyography revealed fibrillation potentials and positive sharp waves in axial and appendicular muscles. Decreased motor conduction velocities and compound muscle action potential amplitudes were detected in ulnar and sciatic-tibial nerves. Residual latency was increased in the sciatic-tibial nerve. Histologically, several intramuscular nerve branches were depleted of myelinated fibres and a few showed mononuclear infiltrations.  To our knowledge, this is the first report of distal polyneuropathy associated with toxoplasmosis in a cat. This case suggests the inclusion of toxoplasmosis as a possible differential diagnosis for acquired polyneuropathies in cats.", "journal": "JFMS open reports", "doi": "10.1177/2055116916630335", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "28491411", "author": "Basso MA", "n_authors": 11, "title": "Successful treatment of feline leishmaniosis using a combination of allopurinol and N-methyl-glucamine antimoniate.", "abstract": "This work describes the diagnosis and successful treatment of a 2-year-old domestic cat infected with  Considering the increasing number of feline leishmaniosis cases and the inconsistent results of most therapeutic protocols described in the literature, the use of new approaches, especially in refractory cases, is essential. Although the use of allopurinol and N-methyl-glucamine antimoniate is off-label in cats, in this case the combination treatment was followed by an extensive analytical monitoring, supporting their safety and effectiveness.", "journal": "JFMS open reports", "doi": "10.1177/2055116916630002", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "26797583", "author": "Rolim VM", "n_authors": 5, "title": "Myocarditis caused by Feline Immunodeficiency Virus in Five Cats with Hypertrophic Cardiomyopathy.", "abstract": "Viral infections have been implicated as the cause of cardiomyopathy in several mammalian species. This study describes hypertrophic cardiomyopathy (HCM) and myocarditis associated with feline immunodeficiency virus (FIV) infection in five cats aged between 1 and 4 years. Clinical manifestations included dyspnoea in four animals, one of which also exhibited restlessness. One animal showed only lethargy, anorexia and vomiting. Necropsy examination revealed marked cardiomegaly, marked left ventricular hypertrophy and pallor of the myocardium and epicardium in all animals. Microscopical and immunohistochemical examination showed multifocal infiltration of the myocardium with T lymphocytes and fewer macrophages, neutrophils and plasma cells. An intense immunoreaction for FIV antigen in the cytoplasm and nucleus of lymphocytes and the cytoplasm of some macrophages was observed via immunohistochemistry (IHC). IHC did not reveal the presence of antigen from feline calicivirus, coronavirus, feline leukaemia virus, feline parvovirus, Chlamydia spp. or Toxoplasma gondii. The results demonstrate the occurrence of FIV infection in inflammatory cells in the myocardium of five cats with myocarditis and HCM.", "journal": "Journal of comparative pathology", "doi": "10.1016/j.jcpa.2015.10.180", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "26747244", "author": "Ramírez H", "n_authors": 6, "title": "Genotyping of feline leukemia virus in Mexican housecats.", "abstract": "Feline leukemia virus (FeLV) is a retrovirus with variable rates of infection globally. DNA was obtained from cats' peripheral blood mononuclear cells, and proviral DNA of pol and env genes was detected using PCR. Seventy-six percent of cats scored positive for FeLV using env-PCR; and 54 %, by pol-PCR. Phylogenetic analysis of both regions identified sequences that correspond to a group that includes endogenous retroviruses. They form an independent branch and, therefore, a new group of endogenous viruses. Cat gender, age, outdoor access, and cohabitation with other cats were found to be significant risk factors associated with the disease. This strongly suggests that these FeLV genotypes are widely distributed in the studied feline population in Mexico.", "journal": "Archives of virology", "doi": "10.1007/s00705-015-2740-4", "deposited_data": "Sim", "nuccore_ids": "927348086, 927348085, 927348083, 927348082, 927348080, 927348078, 927348076, 927348074, 927348072, 927348070, 927348068, 927348066, 927348064, 927348062, 927348060, 927348058, 927348056, 927348054, 927348052, 927348050, 927348048, 927348046, 927348044, 927348042, 927348040, 927348038, 927348036, 927348034, 927348032, 927348030, 927348028, 927348026, 927348024, 927348022, 927348020, 927348018, 927348016, 927348014, 927348012, 927348010, 927348008, 927348006, 927348004, 927348002, 927348000, 927347998, 927347996, 927347994, 927347992, 927347990, 927347988, 927347986, 927347984, 927347982, 927347980, 927347978, 927347976", "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "26744011", "author": "Garigliany M", "n_authors": 13, "title": "Risk factors and effect of selective removal on retroviral infections prevalence in Belgian stray cats.", "abstract": "The aim of this study was to evaluate the effect of several risk/protective factors and predictors on the prevalence of feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV) infections in 302 stray cats captured during a trap-neuter-release programme in a mixed urban-rural area from Belgium, from 2010 to 2012. The impact of selective removal of FIV-positive cats on the apparent prevalence in the remaining population over this three-year period was also assessed. The seroprevalences over three years were 18.8 per cent for FIV and 0.7 per cent for FeLV. For FIV, the seroprevalence decreased significantly from the first year of the programme (2010; 30.5 per cent) to the last (2012; 13.1 per cent). Sex (male) and age (adult and old cats) were risk factors, while the year of sampling (years 2011 and 2012) was a protective factor. Age, sex and location were the most relevant predictors of FIV status. The data presented in this study revealed a very high FIV seroprevalence in Belgian stray cats, while FeLV was almost absent. The selective removal of positive cats had a drastic effect on the FIV seroprevalence in the remaining cat population.", "journal": "The Veterinary record", "doi": "10.1136/vr.103314", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "26711049", "author": "Willi B", "n_authors": 16, "title": "Molecular characterization and virus neutralization patterns of severe, non-epizootic forms of feline calicivirus infections resembling virulent systemic disease in cats in Switzerland and in Liechtenstein.", "abstract": "Feline calicivirus (FCV) infections are associated with oral ulceration, chronic stomatitis and a limping syndrome. Epizootic outbreaks of virulent systemic disease (VSD) have been reported in the USA and Europe. Here, the molecular characterization and neutralization patterns of FCV isolates from cases of severe, non-epizootic infection associated with skin ulceration and edema are presented. Samples from eleven symptomatic cats, four in-contact cats and 27 cats with no contact with symptomatic cats were collected and tested for FCV, feline herpesvirus-1 (FHV-1), feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV). Phylogenetic analyses based on the capsid (VP1) gene of FCV and virus neutralization with antisera raised against four FCV vaccine strains were performed. Nine kittens and two adult cats in two shelters and two veterinary clinics in four geographically distinct locations in Switzerland and Liechtenstein were affected. The cats showed fever, tongue and skin ulceration, head and paw edema, and occasionally jaundice, generalized edema and dyspnea. All symptomatic cats tested FCV-positive but were negative for FHV-1, FeLV and FIV, with the exception of one FIV-positive kitten. All kittens of one litter and both adult cats died. The disease did not spread to cats in the environment. Cats in the environment displayed phylogenetically distinct, but related, FCV strains. Virus neutralization patterns suggested that some cases might have been potentially prevented by vaccination with the optimal vaccine strain. In conclusion, clinicians should be aware of severe, non-epizootic forms of FCV infections with initial clinical presentations similar to VSD.", "journal": "Veterinary microbiology", "doi": "10.1016/j.vetmic.2015.10.015", "deposited_data": "Sim", "nuccore_ids": "971493089, 971493087, 971493085, 971493083, 971493081, 971493079, 971493077, 971493075, 971493073, 971493071, 971493069, 971493067, 971493065, 971493063, 971493061, 971493059, 971493057, 971493055", "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "26559384", "author": "Jinks MR", "n_authors": 3, "title": "Causes of endogenous uveitis in cats presented to referral clinics in North Carolina.", "abstract": "To investigate the causes of endogenous uveitis in cats presenting to referral ophthalmology clinics in North Carolina. Medical records of cats diagnosed with endogenous uveitis at North Carolina State University's College of Veterinary Medicine (NCSU-CVM) or Animal Eye Care Associates of Cary, NC between 2003 and 2015 were reviewed. Inclusion criteria were cats that had complete diagnostic workups, including clinical, clinicopathological, serological, and histopathological data, as well as imaging modalities. Serology was consistently completed for feline leukemia virus (FeLV), feline immunodeficiency virus (FIV), feline coronavirus (FCoV), Toxoplasma gondii, and Bartonella spp. One hundred and twenty cats met the inclusion criteria. Seroprevalence of FeLV (2.7%), FIV (7.3%), FCoV (34.7%), T. gondii (23.7%), and Bartonella spp. (43.2%) was observed, with a combined seroprevalence of 59.2%. Nineteen cats (15.8%) were diagnosed with feline infectious peritonitis (FIP) based on clinical, hematological, serological, histopathological, and necropsy findings. The average age of all cases was 7.62 years, while the average age of cats diagnosed with FIP was 1.82 years. Neoplasia was diagnosed in six cats (5.0%). No underlying etiology was found in 49 cats (40.8%). Both idiopathic and neoplastic causes of uveitis were less prevalent than previously reported in studies, while seropositivity was higher than previously reported for the study area. This may be due to improved diagnostic capabilities or that cats with infectious disease were more likely to be referred. Because of the high prevalence of FIP, young cats with uveitis should be evaluated for hyperglobulinemia and FCoV serology should be performed as minimal diagnostics.", "journal": "Veterinary ophthalmology", "doi": "10.1111/vop.12324", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "26362646", "author": "Cong W", "n_authors": 6, "title": "Toxoplasma gondii, Dirofilaria immitis, feline immunodeficiency virus (FIV), and feline leukemia virus (FeLV) infections in stray and pet cats (Felis catus) in northwest China: co-infections and risk factors.", "abstract": "This study was conducted to estimate the prevalence of Toxoplasma gondii, Dirofilaria immitis, feline immunodeficiency virus (FIV), and feline leukemia virus (FeLV) infections among stray and pet cats in Lanzhou, northwest China, and to identify the influence of age, gender, and regions on seropositivity. T. gondii antibodies were examined in cat sera by the modified agglutination test (MAT). The circulating antigens of D. immitis and FeLV and specific antibodies to FIV were examined using kits commercially available. The overall prevalence of T. gondii, FIV, FeLV, and D. immitis was 19.34, 9.12, 11.33, and 3.04 %, respectively. For the genetic characterization of T. gondii genotypes in cats, genomic DNA was extracted from the seropositive cats and the T. gondii B1 gene was amplified using a semi-nested PCR. DNA samples giving positive B1 amplification were then genotyped using multilocus PCR-RFLP. Two T. gondii genotypes (ToxoDB#9 and ToxoDB#1) were identified. Results of the multivariate logistic regression analysis showed that older cats are more likely to be seropositive than juveniles for T. gondii, FIV, FeLV, and D. immitis. This is the first report of T. gondii genotypes in cats in northwest China. Moreover, the present study is the first study of retrovirus and D. immitis seroprevalence in cats in China. The results revealed that T. gondii, FIV, and FeLV infections are common in stray and pet cats in northwest China.", "journal": "Parasitology research", "doi": "10.1007/s00436-015-4738-y", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "26058344", "author": "Mercurio S", "n_authors": 6, "title": "Alteration of heme metabolism in a cellular model of Diamond-Blackfan anemia.", "abstract": "Diamond-Blackfan anemia (DBA) is a congenital pure red cell aplasia often associated with skeletal malformations. Mutations in ribosomal protein coding genes, mainly in RPS19, account for the majority of DBA cases. The molecular mechanisms underlying DBA pathogenesis are still not completely understood. Alternative spliced isoforms of FLVCR1 (feline leukemia virus subgroup C receptor 1) transcript coding for non-functional proteins have been reported in some DBA patients. Consistently, a phenotype very close to DBA has been described in animal models of FLVCR1 deficiency. FLVCR1 gene codes for two proteins: the plasma membrane heme exporter FLVCR1a and the mitochondrial heme exporter FLVCR1b. The coordinated expression of both FLVCR1 isoforms regulates an intracellular heme pool, necessary for proper expansion and differentiation of erythroid precursors. Here, we investigate the role of FLVCR1 isoforms in a cellular model of DBA. RPS19-downregulated TF1 cells show reduced FLVCR1a and FLVCR1b mRNA levels associated with heme overload. The downregulation of FLVCR1 isoforms affects cell cycle progression and apoptosis in differentiating K562 cells, a phenotype similar to DBA. Taken together, these data suggest that alteration of heme metabolism could play a role in the pathogenesis of DBA.", "journal": "European journal of haematology", "doi": "10.1111/ejh.12599", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1676440127, 1676325127, 1674986339, 1653961181, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "26018551", "author": "Hwang J", "n_authors": 5, "title": "Evaluation of biochemical and haematological parameters and prevalence of selected pathogens in feral cats from urban and rural habitats in South Korea.", "abstract": "In this study, we evaluated the potential association between the habitat types of feral cats and the prevalence of selected infectious pathogens and health status based on a set of blood parameters. We live-trapped 72 feral cats from two different habitat types: an urban area (n = 48) and a rural agricultural area (n = 24). We compared blood values and the prevalence of feline immunodeficiency virus (FIV), feline leukaemia virus (FeLV) and haemotropic Mycoplasma infection in feral cats from the two contrasting habitats. Significant differences were observed in several blood values (haematocrit, red blood cells, blood urea nitrogen, creatinine) depending on the habitat type and/or sex of the cat. Two individuals from the urban area were seropositive for FIV (3.0%), and eight (12.1%) were positive for FeLV infection (five from an urban habitat and three from a rural habitat). Haemoplasma infection was more common. Based on molecular analysis, 38 cats (54.3%) were positive for haemoplasma, with a significantly higher infection rate in cats from rural habitats (70.8%) compared with urban cats (47.8%). Our study recorded haematological and serum biochemical values, and prevalence of selected pathogens in feral cat populations from two different habitat types. A subset of important laboratory parameters from rural cats showed values under or above the corresponding reference intervals for healthy domestic cats, suggesting potential differences in the health status of feral cats depending on the habitat type. Our findings provide information about the association between 1) blood values (haematological and serum biochemistry parameters) and 2) prevalence of selected pathogen infections and different habitat types; this may be important for veterinarians who work with feral and/or stray cats and for overall cat welfare management.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X15587572", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "30202540", "author": "Luckman C", "n_authors": 2, "title": "Epidemiology and clinical outcomes of feline immunodeficiency virus and feline leukaemia virus in client-owned cats in New Zealand.", "abstract": "The objectives were to collect baseline data on the occurrence, testing and vaccination practices, and clinical outcomes of feline leukaemia virus (FeLV) and feline immunodeficiency virus (FIV) in New Zealand. A cross-sectional survey of 423 veterinary practices in New Zealand was performed to collect data on FeLV and FIV testing and vaccination during the 2015 calendar year. Clinical records from 572 cats tested using a point-of-care ELISA at a first-opinion veterinary practice between 7 April 2010 and 23 June 2016 were also obtained and multivariable logistic regression models were constructed to identify risk factors for test positivity. Survival times were estimated using Kaplan-Meier methods. The survey was completed by 112 clinics (26.4%) of which 72 performed in-house testing. Of the 2125 tests performed, 56 (2.6%) were positive for FeLV and 393 (18.5%) were positive for FIV. Fewer than 1% of cats were vaccinated for FeLV, with veterinarians citing low perceived prevalence as the primary reason for not vaccinating. Being male compared with being female and having clinical evidence of immunosuppression were significant risk factors for both FeLV and FIV test positivity. The median survival times of FeLV and FIV test-positive cats were 10 days (95% confidence interval [CI] 0-16) and 650 days (95% CI 431-993), respectively. Testing and vaccination for FeLV and FIV in New Zealand appears targeted towards high-risk animals, which may bias prevalence estimates. Baseline data should be monitored for changes in FeLV epidemiology now commercial vaccines are no longer available.", "journal": "JFMS open reports", "doi": "10.1177/2055116917729311", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "29149857", "author": "Filoni C", "n_authors": 7, "title": "Putative progressive and abortive feline leukemia virus infection outcomes in captive jaguarundis (Puma yagouaroundi).", "abstract": "Feline leukemia virus (FeLV) is an exogenous gammaretrovirus of domestic cats (Felis catus) and some wild felids. The outcomes of FeLV infection in domestic cats vary according to host susceptibility, virus strain, and infectious challenge dose. Jaguarundis (Puma yagouaroundi) are small wild felids from South and Central America. We previously reported on FeLV infections in jaguarundis. We hypothesized here that the outcomes of FeLV infection in P. yagouaroundi mimic those observed in domestic cats. The aim of this study was to investigate the population of jaguarundis at Fundação Parque Zoológico de São Paulo for natural FeLV infection and resulting outcomes. We investigated the jaguarundis using serological and molecular methods and monitored them for FeLV-related diseases for 5 years. We retrieved relevant biological and clinical information for the entire population of 23 jaguarundis held at zoo. Post-mortem findings from necropsies were recorded and histopathological and immunohistopathological analyses were performed. Sequencing and phylogenetic analyses were performed for FeLV-positive samples. For sample prevalence, 95% confidence intervals (CI) were calculated. Fisher's exact test was used to compare frequencies between infected and uninfected animals. P-values <0.05 were considered significant. In total, we detected evidence of FeLV exposure in four out of 23 animals (17%; 95% CI 5-39%). No endogenous FeLV (enFeLV) sequences were detected. An intestinal B-cell lymphoma in one jaguarundi was not associated with FeLV. Two jaguarundis presented FeLV test results consistent with an abortive FeLV infection with seroconversion, and two other jaguarundis had results consistent with a progressive infection and potentially FeLV-associated clinical disorders and post-mortem changes. Phylogenetic analysis of env revealed the presence of FeLV-A, a common origin of the virus in both animals (100% identity) and the closest similarity to FeLV-FAIDS and FeLV-3281 (98.4% identity), originally isolated from cats in the USA. We found evidence of progressive and abortive FeLV infection outcomes in jaguarundis, and domestic cats were probably the source of infection in these jaguarundis.", "journal": "Virology journal", "doi": "10.1186/s12985-017-0889-z", "deposited_data": "Sim", "nuccore_ids": "881841304", "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "29056701", "author": "Scorza AV", "n_authors": 2, "title": "Prevalence of Selected Zoonotic and Vector-Borne Agents in Dogs and Cats on the Pine Ridge Reservation.", "abstract": "The prevalence of intestinal parasites and vector-borne agents of dogs and cats in the Pine Ridge Reservation, South Dakota were determined. Fecal samples (84 dogs, 9 cats) were examined by centrifugal floatation and by immunofluorescence assay (FA) for ", "journal": "Veterinary sciences", "doi": "10.3390/vetsci4030043", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "29056675", "author": "McLuckie AJ", "n_authors": 5, "title": "Felis Catus Gammaherpesvirus 1 DNAemia in Whole Blood from Therapeutically Immunosuppressed or Retrovirus-Infected Cats.", "abstract": "Gammaherpesviruses are major co-pathogens of human immunodeficiency virus (HIV) infection, making the interactions between feline immunodeficiency virus (FIV) and ", "journal": "Veterinary sciences", "doi": "10.3390/vetsci4010016", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "29017551", "author": "Almeras T", "n_authors": 8, "title": "Comparative efficacy of the Leucofeligen™ FeLV/RCP and Purevax™ RCP FeLV vaccines against infection with circulating feline Calicivirus.", "abstract": "Feline calicivirus (FCV) is a common virus, found worldwide, mainly responsible for chronic ulceroproliferative faucitis and periodontitis. This virus has a high mutation rate, leading to the presence of numerous FCV strains in the field. The objectives of this study was to evaluate and compare the efficacy of two vaccines (Leucofeligen™ FeLV/RCP and Purevax™ RCP FeLV), which differ by their nature (live vs. inactivated) and the vaccinal strains, against circulating FCV strains. Thirty 9-week-old specific pathogen free (SPF) kittens were thus randomised into 3 groups and were either not vaccinated (control) or vaccinated (2 injections, 3 weeks apart) with one of the vaccines. Four weeks after the second injection of primary vaccination, the cats were inoculated with a pathogenic strain representative of the ones circulating in Europe (FCV-FR4_01) and followed for 2 weeks. After challenge, significant differences (p < 0.05) between control cats and cats vaccinated with Leucofeligen™ FeLV/RCP or Purevax™ RCP FeLV were observed for body weight variation, rectal temperature rise and maximum clinical scores, reflecting the intensity of the signs (83% and 67% lower in the respective vaccinated groups than in the control group). Significant differences were observed between the vaccinated groups, as cats vaccinated with Leucofeligen™ FeLV/RCP had a lower temperature rise (p < 0.05 at days post-challenge 3 to 5) and lower virus shedding titres (p < 0.05 at days post-challenge 8, 9 and 11) than cats vaccinated with Purevax™ RCP FeLV. Finally, only cats vaccinated with Leucofeligen™ FeLV/RCP had a significantly lower cumulative score, reflecting the intensity and duration of calicivirosis clinical signs, than the control cats (77% lower vs. 62% lower for cats vaccinated with Purevax™ RCP FeLV). Both vaccines, Leucofeligen™ FeLV/RCP and Purevax™ RCP FeLV, were found to be efficacious in reducing clinical signs induced by FCV-FR4_01, a FCV strain representative of the circulating ones. However, cats vaccinated with Leucofeligen™ FeLV/RCP were able to control the infection more efficiently than those vaccinated with Purevax™ RCP FeLV, as evidenced by the shorter duration of clinical signs and lower viral titre in excretions.", "journal": "BMC veterinary research", "doi": "10.1186/s12917-017-1217-y", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28957693", "author": "Li SF", "n_authors": 6, "title": "Interferon-omega: Current status in clinical applications.", "abstract": "Since 1985, interferon (IFN)-ω, a type I IFN, has been identified in many animals, but not canines and mice. It has been demonstrated to have antiviral, anti-proliferation, and antitumor activities that are similar to those of IFN-α. To date, IFN-ω has been explored as a treatment option for some diseases or viral infections in humans and other animals. Studies have revealed that human IFN-ω displays antitumor activities in some models of human cancer cells and that it can be used to diagnose some diseases. While recombinant feline IFN-ω has been licensed in several countries for treating canine parvovirus, feline leukemia virus, and feline immunodeficiency virus infections, it also exhibits a certain efficacy when used to treat other viral infections or diseases. This review examines the known biological activity of IFN-ω and its clinical applications. We expect that the information provided in this review will stimulate further studies of IFN-ω as a therapeutic agent.", "journal": "International immunopharmacology", "doi": "10.1016/j.intimp.2017.08.028", "deposited_data": "Sim", "nuccore_ids": "1934804069, 1934804069", "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28955476", "author": "Bree L", "n_authors": 5, "title": "Periaortic lymphoma in a cat.", "abstract": "A 14-year-old neutered male Siamese cat was presented with a 3 month history of lethargy, inappetence, dehydration, hindlimb ataxia and intermittent proprioceptive deficits in the hindlimbs. Physical examination revealed low body condition score (1.75/5), pallor and bilateral basilar grade II/VI systolic heart murmur. Neurological examination revealed hindlimb ataxia, severe atrophy of the hindlimb musculature, intermittent hindlimb proprioceptive deficits and normoreflexia. Clinicopathological investigations revealed non-regenerative anaemia (haematocrit 0.17 l/l; reference interval [RI] 0.24-0.45 l/l) and increased feline pancreatic lipase concentration (Spec fPL test [IDEXX] 8.3 μg/l; RI 0.1-3.5 μg/l). Feline leukaemia virus antigen and feline immunodeficiency virus antibody tests were negative. Thoracic and abdominal imaging revealed a soft tissue structure in the area of the thoracoabdominal aorta. CT confirmed a periaortic contrast-enhancing mass extending from the level of T9-L2, with associated intervertebral infiltration at the level of T11-T12. Post-mortem examination confirmed the presence of a solid, white, multinodular, well-demarcated mass encircling the aorta extending from T9-L2. Based on histopathology and immunohistochemistry, a diagnosis of B-cell lymphoma was made. Lymphoma was also identified histopathologically within the kidneys and spleen. Evidence of mild Wallerian degeneration was present within the spinal cord, indicating compression at the level of the periaortic mass. To our knowledge, this is the first report of periaortic lymphoma in the cat. Although periaortic tumours are exceptionally rare in veterinary medicine, lymphoma should be considered as a differential in cats.", "journal": "JFMS open reports", "doi": "10.1177/2055116917729627", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28932815", "author": "Khan AS", "n_authors": 8, "title": "A Multicenter Study To Evaluate the Performance of High-Throughput Sequencing for Virus Detection.", "abstract": "The capability of high-throughput sequencing (HTS) for detection of known and unknown viruses makes it a powerful tool for broad microbial investigations, such as evaluation of novel cell substrates that may be used for the development of new biological products. However, like any new assay, regulatory applications of HTS need method standardization. Therefore, our three laboratories initiated a study to evaluate performance of HTS for potential detection of viral adventitious agents by spiking model viruses in different cellular matrices to mimic putative materials for manufacturing of biologics. Four model viruses were selected based upon different physical and biochemical properties and commercial availability: human respiratory syncytial virus (RSV), Epstein-Barr virus (EBV), feline leukemia virus (FeLV), and human reovirus (REO). Additionally, porcine circovirus (PCV) was tested by one laboratory. Independent samples were prepared for HTS by spiking intact viruses or extracted viral nucleic acids, singly or mixed, into different HeLa cell matrices (resuspended whole cells, cell lysate, or total cellular RNA). Data were obtained using different sequencing platforms (Roche 454, Illumina HiSeq1500 or HiSeq2500). Bioinformatic analyses were performed independently by each laboratory using available tools, pipelines, and databases. The results showed that comparable virus detection was obtained in the three laboratories regardless of sample processing, library preparation, sequencing platform, and bioinformatic analysis: between 0.1 and 3 viral genome copies per cell were detected for all of the model viruses used. This study highlights the potential for using HTS for sensitive detection of adventitious viruses in complex biological samples containing cellular background. ", "journal": "mSphere", "doi": "10.1128/mSphere.00307-17", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28918382", "author": "Stavisky J", "n_authors": 3, "title": "Prevalence of and risk factors for FIV and FeLV infection in two shelters in the United Kingdom (2011-2012).", "abstract": "The aims of this study were to determine the prevalence of feline leukaemia virus (FeLV) and feline immunodeficiency virus (FIV) infections in cats presented to two RSPCA (Royal Society for the Prevention of Cruelty to Animals) animal rehoming centres and to identify risk factors for infection. All cats presented at each centre between August 2011 and August 2012 were subjected to a patient-side test for FeLV/FIV on entry. Kittens under three months and cats euthanased within a short time of presentation were excluded from the study. Univariable and multivariable logistic regression were used to separately determine risk factors for FeLV and FIV infections. At shelter A, the prevalence of FIV infection was 11.4 per cent (54/474) and FeLV infection was 3 per cent (14/473), with two FIV/FeLV coinfections identified. At shelter B, the prevalence of FIV infection was 3 per cent (4/135) and FeLV infection was 0 per cent (0/135). Cats at shelter A were significantly more likely than those at shelter B to test positive for FIV (p=0.0024) and FeLV (p=0.048). Male cats were more likely to be infected with FIV (odds ratio 27.1, p=0.001), and thin body condition and musculoskeletal disease were associated with risk of FeLV. Overall, FIV-positive and FeLV-positive cats were significantly older (median ages 5.1 and 4.75 years, respectively) than the uninfected populations (median ages 3.4 and 3.5 years, respectively). This study shows that the prevalence of these diseases varies between shelter populations. Local knowledge combined with the risk factors identified may be useful in focusing resources for population testing strategies.", "journal": "The Veterinary record", "doi": "10.1136/vr.103857", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28915995", "author": "Ghazisaeedi F", "n_authors": 7, "title": "Detection and molecular characterization of feline hemoplasmas in wild felid species in Iran in the Middle East.", "abstract": "Three feline hemoplasma species exist in felids: Mycoplasma haemofelis, 'Candidatus Mycoplasma haemominutum', and 'Candidatus Mycoplasma turicensis'. The aims of the study were to determine the presence of, and molecularly characterize, any hemoplasmas in wild felids, including the endangered Persian leopard in Iran, the Middle East. Blood samples were collected from 19 wild felids, including three Persian leopards. Using species-specific hemoplasma PCRs and ELISA serological testing for feline leukaemia virus and feline immunodeficiency virus (FIV), two Persian leopards were found to be infected with 'Ca. M. haemominutum' and were seropositive for FIV. Partial 16S rRNA gene sequences were generated for these 'Ca. M. haemominutum' species and subsequent phylogenetic analysis revealed 97.70% to 99.45% sequence identity with those found in domestic cats from Iran and other countries. This study confirms the presence of 'Ca. M. haemominutum' and concurrent FIV antibody in wild felids in Iran. This represents the first report of hemoplasma in wild felids in the Middle East as well as the first report of infection in Persian leopards.", "journal": "Comparative immunology, microbiology and infectious diseases", "doi": "10.1016/j.cimid.2017.07.004", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28902958", "author": "Keresztes MA", "n_authors": 8, "title": "Nonregenerative immune-mediated anemia associated with a diffuse large B-cell lymphoma in a captive jaguar (Panthera onca).", "abstract": "An 18-year-old male castrated jaguar (Panthera onca) was presented with anorexia and continuous bleeding from the oral cavity after a history of fighting with the partner animal. Clinical evaluation revealed ulcerating lesions on the gingiva and hard palate and a hematoma on the tongue. Computed tomography of the head and endoscopic examination of the esophagus and stomach were unremarkable. Hematology and clinical chemistry revealed severe nonregenerative anemia, mild thrombocytopenia, and moderate azotemia. Several PCRs for feline hemotropic mycoplasmas (Mycoplasma haemofelis, M heamominutium, M turicensis), Babesia felis, and Bartonella spp., as well as an FeLV antigen test were negative. The cytologic examination of a bone marrow aspirate was consistent with ineffective erythropoiesis, most likely due to immune-mediated destruction of the erythroid precursor cells. Prednisolone therapy was initiated (1.25 mg/kg/day), and the CBC returned to normal 16 days after the initiation of the therapy. Anemia relapsed after 4 months and severe splenomegaly was noted. A repeat bone marrow aspirate revealed active erythropoiesis in the presence of erythroid precursor phagocytosis suggesting an immune-mediated process. Splenic fine-needle aspiration and tissue biopsies were taken, and all findings including histology and immunohistochemistry were consistent with a diffuse large B-cell lymphoma (DLBCL). Five days later, the clinical condition deteriorated and the jaguar died. Histopathology following necropsy showed infiltration with neoplastic lymphoblasts in the spleen, liver, and abdominal lymph nodes. This case report describes a nonregenerative immune-mediated anemia associated with a DLBCL in a jaguar.", "journal": "Veterinary clinical pathology", "doi": "10.1111/vcp.12542", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28895871", "author": "Klotz D", "n_authors": 3, "title": "Type I interferons in the pathogenesis and treatment of canine diseases.", "abstract": "Type I interferons (IFNs) such as IFN-α, IFN-β, IFN-ε, IFN-κ, and IFN-ω represent cytokines, which are deeply involved in the regulation and activation of innate and adaptive immune responses. They possess strong antiviral, antiproliferative, and immunomodulatory activities allowing their use in the therapy of different viral diseases, neoplasms, and immune-mediated disorders, respectively. Initially, treatment strategies were based on nonspecific inducers of type I IFNs, which were soon replaced by different recombinant proteins. Drugs with type I IFNs as active agents are currently used in the treatment of hepatitis B and C virus infection, lymphoma, myeloid leukemia, renal carcinoma, malignant melanoma, and multiple sclerosis in humans. In addition, recombinant feline IFN-ω has been approved for the treatment of canine parvovirus, feline leukemia virus, and feline immunodeficiency virus infections. However, the role of type I IFNs in the pathogenesis of canine diseases remains largely undetermined so far, even though some share pathogenic mechanisms and clinical features with their human counterparts. This review summarizes the present knowledge of type I IFNs and down-stream targets such as Mx and 2',5'-oligoadenylate synthetase proteins in the pathogenesis of infectious and immune-mediated canine diseases. Moreover, studies investigating the potential use of type I IFNs in the treatment of canine lymphomas, melanomas, sarcomas, and carcinomas, canine distemper virus, parvovirus, and papillomavirus infections as well as immune-mediated keratoconjunctivitis sicca and atopic dermatitis are presented. A separate chapter is dedicated to the therapeutic potential of IFN-λ, a type III IFN, in canine diseases. However, further future studies are still needed to unravel the exact functions of the different subtypes of type I IFNs and their target genes in healthy and diseased dogs and the full potential action of type I IFNs as treatment strategy.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2017.08.006", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28782421", "author": "Makundi I", "n_authors": 14, "title": "Epidemiologic survey of feline leukemia virus in domestic cats on Tsushima Island, Japan: management strategy for Tsushima leopard cats.", "abstract": "The Tsushima leopard cat (TLC) Prionailurus bengalensis euptilurus, a subspecies of P. bengalensis, is designated a National Natural Monument of Japan, and lives only on Tsushima Island, Nagasaki Prefecture, Japan. TLCs are threatened by various infectious diseases. Feline leukemia virus (FeLV) causes a serious infectious disease with a poor prognosis in cats. Therefore, the transmission of FeLV from Tsushima domestic cats (TDCs) to TLCs may threaten the TLC population. We investigated the FeLV infection status of both TDCs and TLCs on Tsushima Island by screening blood samples for FeLV p27 antigen and using PCR to amplify the full-length FeLV env gene. The prevalence of FeLV was 6.4% in TDCs and 0% in TLCs. We also demonstrated that the virus can replicate in the cells of TLCs, suggesting its potential cross-species transmission. The viruses in TDCs were classified as genotype I/clade 3, which is prevalent on a nearby island, based on previous studies of FeLV genotypes and FeLV epidemiology. The FeLV viruses identified on Tsushima Island can be further divided into 2 lineages within genotype I/clade 3, which are geographically separated in Kamijima and Shimojima, indicating that FeLV may have been transmitted to Tsushima Island at least twice. Monitoring FeLV infection in the TDC and TLC populations is highly recommended as part of the TLC surveillance and management strategy.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/1040638717725551", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28780918", "author": "Sato S", "n_authors": 7, "title": "Molecular survey of Bartonella henselae and Bartonella clarridgeiae in pet cats across Japan by species-specific nested-PCR.", "abstract": "Cats are known to be the main reservoir for Bartonella henselae and Bartonella clarridgeiae, which are the agents of 'cat-scratch disease' in humans. In the present study, we investigated the prevalence of the two Bartonella species on 1754 cat bloods collected from all prefectures in Japan during 2007-2008 by a nested-polymerase chain reaction (PCR) targeting the 16S-23S rRNA internal transcribed spacer region. Overall, Bartonella DNA was detected in 4·6% (80/1754) of the cats examined. The nested-PCR showed that 48·8% (39/80) of the positive cats were infected with B. henselae mono-infection, 33·8% (27/80) with B. clarridgeiae mono-infection and 17·5% (14/80) were infected with both species. The prevalence (5·9%; 65/1103) of Bartonella infection in the western part of Japan was significantly higher than that (2·3%; 15/651) of eastern Japan (P < 0·001). Statistical analysis of the cats examined suggested a significant association between Bartonella infection and FeLV infection (OR = 1·9; 95% CI = 1·1-3·4), but not with FIV infection (OR = 1·6; 95% CI = 1·0-2·6).", "journal": "Epidemiology and infection", "doi": "10.1017/S0950268817001601", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28768854", "author": "Kawasaki J", "n_authors": 5, "title": "Presence of a Shared 5'-Leader Sequence in Ancestral Human and Mammalian Retroviruses and Its Transduction into Feline Leukemia Virus.", "abstract": "Recombination events induce significant genetic changes, and this process can result in virus genetic diversity or in the generation of novel pathogenicity. We discovered a new recombinant feline leukemia virus (FeLV) ", "journal": "Journal of virology", "doi": "10.1128/JVI.00829-17", "deposited_data": "Sim", "nuccore_ids": "1227954422, 1227954421, 1227954420, 1227954419, 1227954418, 1227954417, 1227954416, 1227954415, 1227954414, 1227954413, 1227954412, 1227954411, 1227954338, 1227954337, 1227954336, 1227954335, 1227954334, 1227954333, 1227954332, 1227954331, 1227954330, 1227954329, 1227954328, 1227954327, 1227954326, 1227954325, 1227954324, 1227954323, 1227954322, 1227954321, 1227954320, 1227954319, 1227954318, 1227954317, 1227954316, 1227954315, 1227954314, 2130996210, 2130949117", "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28746448", "author": "Pena HFJ", "n_authors": 13, "title": "Fatal toxoplasmosis in an immunosuppressed domestic cat from Brazil caused by Toxoplasma gondii clonal type I.", "abstract": "The objective of the study was to report on a fatal case of feline toxoplasmosis with coinfection with the feline leukemia virus (FeLV). A domestic cat (Felis silvestris catus) presented intense dyspnea and died three days later. In the necropsy, the lungs were firm, without collapse and with many white areas; moderate lymphadenomegaly and splenomegaly were also observed. The histopathological examination showed severe necrotic interstitial bronchopneumonia and mild necrotic hepatitis, associated with intralesional cysts and tachyzoites of Toxoplasma gondii that were positive by anti-T. gondii immunohistochemical (IHC) evaluation. The bone marrow showed chronic myeloid leukemia and the neoplastic cells were positive by anti-FeLV IHC evaluation. DNA extracted from lungs was positive for T. gondii by PCR targeting REP-529. T. gondii was characterized by PCR-RFLP and by the microsatellites technique. ToxoDB-PCR-RFLP #10, i.e. the archetypal type I, was identified. Microsatellite analysis showed that the strain was a variant of type I with two atypical alleles. This was the first time that a T. gondii clonal type I genotype was correlated with a case of acute toxoplasmosis in a host in Brazil.", "journal": "Revista brasileira de parasitologia veterinaria = Brazilian journal of veterinary parasitology : Orgao Oficial do Colegio Brasileiro de Parasitologia Veterinaria", "doi": "10.1590/S1984-29612017025", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28734742", "author": "Grosenbaugh DA", "n_authors": 6, "title": "Efficacy of a nonadjuvanted recombinant FeLV vaccine and two inactivated FeLV vaccines when subject to consistent virulent FeLV challenge conditions.", "abstract": "The purpose of this study was to compare the efficacy of three FeLV vaccines, under identical conditions in a laboratory challenge model that closely mimics natural infection. Four groups of cats (n = 20 per group) were administered two doses of vaccine, 21 days apart, starting at 9-10 weeks of age (Purevax", "journal": "Biologicals : journal of the International Association of Biological Standardization", "doi": "10.1016/j.biologicals.2016.10.004", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28677421", "author": "Furtado MM", "n_authors": 13, "title": "Molecular detection of viral agents in free-ranging and captive neotropical felids in Brazil.", "abstract": "We describe molecular testing for felid alphaherpesvirus 1 (FHV-1), carnivore protoparvovirus 1 (CPPV-1), feline calicivirus (FCV), alphacoronavirus 1 (feline coronavirus [FCoV]), feline leukemia virus (FeLV), feline immunodeficiency virus (FIV), and canine distemper virus (CDV) in whole blood samples of 109 free-ranging and 68 captive neotropical felids from Brazil. Samples from 2 jaguars ( Panthera onca) and 1 oncilla ( Leopardus tigrinus) were positive for FHV-1; 2 jaguars, 1 puma ( Puma concolor), and 1 jaguarundi ( Herpairulus yagouaroundi) tested positive for CPPV-1; and 1 puma was positive for FIV. Based on comparison of 103 nucleotides of the UL24-UL25 gene, the FHV-1 sequences were 99-100% similar to the FHV-1 strain of domestic cats. Nucleotide sequences of CPPV-1 were closely related to sequences detected in other wild carnivores, comparing 294 nucleotides of the VP1 gene. The FIV nucleotide sequence detected in the free-ranging puma, based on comparison of 444 nucleotides of the pol gene, grouped with other lentiviruses described in pumas, and had 82.4% identity with a free-ranging puma from Yellowstone Park and 79.5% with a captive puma from Brazil. Our data document the circulation of FHV-1, CPPV-1, and FIV in neotropical felids in Brazil.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/1040638717720245", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28671491", "author": "Burling AN", "n_authors": 7, "title": "Seroprevalences of feline leukemia virus and feline immunodeficiency virus infection in cats in the United States and Canada and risk factors for seropositivity.", "abstract": "OBJECTIVE To estimate seroprevalences for FeLV antigen and anti-FIV antibody and risk factors for seropositivity among cats in the United States and Canada. DESIGN Cross-sectional study. ANIMALS 62,301 cats tested at 1,396 veterinary clinics (n = 45,406) and 127 animal shelters (16,895). PROCEDURES Blood samples were tested with a point-of-care ELISA for FeLV antigen and anti-FIV antibody. Seroprevalence was estimated, and risk factors for seropositivity were evaluated with bivariate and multivariable mixed-model logistic regression analyses adjusted for within-clinic or within-shelter dependencies. RESULTS Overall, seroprevalence was 3.1% for FeLV antigen and 3.6% for anti-FIV antibody. Adult age, outdoor access, clinical disease, and being a sexually intact male were risk factors for seropositivity for each virus. Odds of seropositivity for each virus were greater for cats tested in clinics than for those tested in shelters. Of 1,611 cats with oral disease, 76 (4.7%) and 157 (9.7%) were seropositive for FeLV and FIV, respectively. Of 4,835 cats with respiratory disease, 385 (8.0%) were seropositive for FeLV and 308 (6.4%) were seropositive for FIV. Of 1,983 cats with abscesses or bite wounds, 110 (5.5%) and 247 (12.5%) were seropositive for FeLV and FIV, respectively. Overall, 2,368 of 17,041 (13.9%) unhealthy cats were seropositive for either or both viruses, compared with 1,621 of 45,260 (3.6%) healthy cats. CONCLUSIONS AND CLINICAL RELEVANCE Seroprevalences for FeLV antigen and anti-FIV antibody were similar to those reported in previous studies over the past decade. Taken together, these results indicated a need to improve compliance with existing guidelines for management of feline retroviruses.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.251.2.187", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28659065", "author": "Gates MC", "n_authors": 3, "title": "Prevalence and risk factors for cats testing positive for feline immunodeficiency virus and feline leukaemia virus infection in cats entering an animal shelter in New Zealand.", "abstract": "AIMS To estimate the prevalence of cats testing positive for antibodies to feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV) antigens in domestic cats entering a New Zealand animal shelter, based on a commercial point-of-care ELISA, to identify risk factors associated with cats testing positive, and to compare the results obtained from the ELISA with those obtained using PCR-based testing. METHOD A cross-sectional study was performed on 388 cats entering the Royal New Zealand Society for the Prevention of Cruelty to Animals animal shelter in Auckland, New Zealand between 7 February 2014 and 30 May 2014. Whole blood samples were collected from each cat and tested for FIV antibody and FeLV antigen using a commercial point-of-care ELISA. Information on the signalment and health status of the cat at the time of entry was also recorded. Blood and saliva samples from a subset of cats were tested for FIV and FeLV proviral DNA using a real-time PCR assay. RESULTS Of the 388 cats in the study sample, 146 (37.6%) had been relinquished by owners, 237 (62.4%) were strays, and 5 (1.3%) were of unknown origin. Overall, 53/388 (13.7%) cats tested positive for FIV antibodies and 4/388 (1.0%) were positive for FeLV antigen. Stray cats had a higher FIV seroprevalence than relinquished cats (42/237 (17.8%) vs. 11/146 (7.5%); p=0.008). Of 53 cats that were FIV-seropositive, 51 (96%) tested positive for FIV proviral DNA using PCR testing of blood. Of these 51 cats, 28 (55%) were positive by PCR testing of saliva. Of the four cats that were FeLV antigen-positive by ELISA, two (50%) were positive for FeLV proviral DNA by PCR testing of blood. The odds of a cat being seropositive for FIV were greater for intact compared to desexed cats (OR=3.3; 95% CI=1.6-7.4) and for male compared to female cats (OR=6.5; 95% CI=3.2-14.0). CONCLUSIONS AND CLINICAL RELEVANCE The seroprevalence for FIV was 14% among cats entering an animal shelter in Auckland, whereas the prevalence of FeLV antigen-positive cats was only 1%. These findings suggest differences in the transmission dynamics of each virus in free-roaming cat populations in New Zealand. Our study also highlights the potential role of desexing cats in reducing transmission of FIV. However, further data from first-opinion veterinary practices are required to confirm that these findings may be generalised to the wider domestic cat population in New Zealand.", "journal": "New Zealand veterinary journal", "doi": "10.1080/00480169.2017.1348266", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28548572", "author": "Buch JS", "n_authors": 9, "title": "Analytical validation of a reference laboratory ELISA for the detection of feline leukemia virus p27 antigen.", "abstract": "Feline leukemia virus (FeLV) is an oncogenic retrovirus of cats. Immunoassays for the p27 core protein of FeLV aid in the detection of FeLV infections. Commercial microtiter-plate ELISAs have rapid protocols and visual result interpretation, limiting their usefulness in high-throughput situations. The purpose of our study was to validate the PetChek FeLV 15 ELISA, which is designed for the reference laboratory, and incorporates sequential, orthogonal screening and confirmatory protocols. A cutoff for the screening assay was established with 100% accuracy using 309 feline samples (244 negative, 65 positive) defined by the combined results of FeLV PCR and an independent reference p27 antigen ELISA. Precision of the screening assay was measured using a panel of 3 samples (negative, low-positive, and high-positive). The intra-assay coefficient of variation (CV) was 3.9-7.9%; the inter-assay CV was 6.0-8.6%. For the confirmatory assay, the intra-assay CV was 3.0-4.7%, and the inter-assay CV was 7.4-9.7%. The analytical sensitivity for p27 antigen was 3.7 ng/mL for inactivated whole FeLV and 1.2 ng/mL for purified recombinant FeLV p27. Analytical specificity was demonstrated based on the absence of cross-reactivity to related retroviruses. No interference was observed for samples containing added bilirubin, hemoglobin, or lipids. Based on these results, the new high-throughput design of the PetChek FeLV 15 ELISA makes it suitable for use in reference laboratory settings and maintains overall analytical performance.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/1040638717710451", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28510253", "author": "Lacerda LC", "n_authors": 6, "title": "Feline immunodeficiency virus and feline leukemia virus: frequency and associated factors in cats in northeastern Brazil.", "abstract": "Our aims were to determine the frequencies of feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) in owned and stray cats in the northeastern region of Brazil, ascertain the status of FeLV infection, and investigate potential associated factors among the owned cats. Blood samples from 200 asymptomatic owned cats and 30 stray cats were processed using nested PCR and commercial immunochromatographic tests to diagnose infections. To evaluate the factors associated with FIV and/or FeLV in owned cats, a semi-structured interview was conducted with each owner about the animal's environment, and these data were subjected to unconditional logistic regression. The frequencies for owned cats were 6% (12/200) and 3% (6/200) for FIV and FeLV, respectively. No owned cat was positive for both viruses. Stray cats showed frequencies of 6.66% (2/30) and 0% (0/30) for FIV and FeLV, respectively. Contact with other cats and living in peri-urban areas were considered to be risk factors (P < 0.05) for FIV. We did not identify any factors associated with infections with FeLV. Our results confirm the presence of these two retroviruses in the region under study. Our use of different diagnostic techniques allowed us to determine the frequency of retroviruses in the feline population more accurately, particularly with regard to infections by FeLV, which have complex pathogenesis.", "journal": "Genetics and molecular research : GMR", "doi": "10.4238/gmr16029633", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "31014634", "author": "Munhoz AD", "n_authors": 7, "title": "Toxoplasmosis in cats in northeastern Brazil: Frequency, associated factors and coinfection with Neospora caninum, feline immunodeficiency virus and feline leukemia virus.", "abstract": "The aim of this study was to determine the frequency and the factors associated with infection by Toxoplasma gondii and demonstrate occurrences of coinfection with Neospora caninum, the feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) in cats in the state of Bahia, Brazil. A total of 231 blood samples were collected from 201 owned cats and 30 stray cats. Serological investigations on T. gondii and N. caninum were performed using the indirect fluorescent antibody test with cutoff points of 1:64 and 1:50, respectively. To diagnose FIV and FeLV, a commercial immunochromatographic kit and a nested polymerase chain reaction (PCR) was used. Unconditional logistic regression was performed to assess the factors associated with infection by T. gondii among owned cats. The seropositivity for T. gondii among the owned cats and stray cats was 44.3% (89/201) and 53.3% (16/30), respectively. For N. caninum, the seropositivity among owned cats was 21.4% (43/201) and among stray cats, 23.3% (7/30). The copositivity between the two coccidia were 23.6% (21/201) and 37.5% (6/30), among owned and stray cats respectively. The periurban environment was a risk factor for infection by T. gondii, while infection by FIV was associated with infection by T. gondii (p<0.05) among owned cats. No association was found between T. gondii and FeLV, or between N. caninum and the retroviruses. Based on these results, it can be concluded that the cats of the present study were exposed to the agents T. gondii and N. caninum, which suggests that significant infection of intermediate hosts and or environmental contamination with oocysts was present, and that the cats coinfected with T. gondii and the retroviruses did not present any serological signs of reactivation of infection.", "journal": "Veterinary parasitology, regional studies and reports", "doi": "10.1016/j.vprsr.2017.01.007", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28399176", "author": "Lempp C", "n_authors": 12, "title": "Pathological findings in the red fox (Vulpes vulpes), stone marten (Martes foina) and raccoon dog (Nyctereutes procyonoides), with special emphasis on infectious and zoonotic agents in Northern Germany.", "abstract": "Anthropogenic landscape changes contributed to the reduction of availability of habitats to wild animals. Hence, the presence of wild terrestrial carnivores in urban and peri-urban sites has increased considerably over the years implying an increased risk of interspecies spillover of infectious diseases and the transmission of zoonoses. The present study provides a detailed characterisation of the health status of the red fox (Vulpes vulpes), stone marten (Martes foina) and raccoon dog (Nyctereutes procyonoides) in their natural rural and peri-urban habitats in Schleswig-Holstein, Germany between November 2013 and January 2016 with focus on zoonoses and infectious diseases that are potentially threatening to other wildlife or domestic animal species. 79 red foxes, 17 stone martens and 10 raccoon dogs were collected from traps or hunts. In order to detect morphological changes and potential infectious diseases, necropsy and pathohistological work-up was performed. Additionally, in selected animals immunohistochemistry (influenza A virus, parvovirus, feline leukemia virus, Borna disease virus, tick-borne encephalitis, canine adenovirus, Neospora caninum, Toxoplasma gondii and Listeria monocytogenes), next-generation sequencing, polymerase chain reaction (fox circovirus) and serum-neutralisation analysis (canine distemper virus) were performed. Furthermore, all animals were screened for fox rabies virus (immunofluorescence), canine distemper virus (immunohistochemistry) and Aujeszky's disease (virus cultivation). The most important findings included encephalitis (n = 16) and pneumonia (n = 20). None of the investigations revealed a specific cause for the observed morphological alterations except for one animal with an elevated serum titer of 1:160 for canine distemper. Animals displayed macroscopically and/or histopathologically detectable infections with parasites, including Taenia sp., Toxocara sp. and Alaria alata. In summary, wildlife predators carry zoonotic parasitic disease and suffer from inflammatory diseases of yet unknown etiology, possibly bearing infectious potential for other animal species and humans. This study highlights the value of monitoring terrestrial wildlife following the \"One Health\" notion, to estimate the incidence and the possible spread of zoonotic pathogens and to avoid animal to animal spillover as well as transmission to humans.", "journal": "PloS one", "doi": "10.1371/journal.pone.0175469", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28382853", "author": "Yoshino Y", "n_authors": 9, "title": "Primary cerebellar lymphoma with Hodgkin lymphoma-like morphology in a cat.", "abstract": "A 4-y-old cat exhibited neurologic signs such as wobbling, right head tilt, and intention tremor, and MRI revealed a mass in the cerebellum. The cat died 5 mo after initial presentation, and no neoplastic lesions, other than the cerebellar mass, were observed at autopsy. Histologically, large atypical cells resembling Hodgkin cells, with single large inclusion-like nucleoli, and those resembling Reed-Sternberg cells, with symmetrically arranged nuclei, had infiltrated the left side of the cerebellum and were admixed with small lymphocytes. These atypical cells were positive for feline leukemia virus (FeLV), CD20, BLA36, vimentin, p16, p53, and Pax5, and negative for CD3, CD79a, and Iba1 by immunohistochemistry. Multiplex PCR for immunoglobulin heavy-chain gene rearrangement revealed monoclonal proliferation of B-lymphocytes. We describe this feline primary cerebellar B-cell lymphoma that displayed Hodgkin lymphoma-like tumor cells with FeLV protein expression.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/1040638717704239", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28358636", "author": "Levy JK", "n_authors": 6, "title": "Seroprevalence of heartworm infection, risk factors for seropositivity, and frequency of prescribing heartworm preventives for cats in the United States and Canada.", "abstract": "OBJECTIVE To determine the seroprevalence of heartworm infection, risk factors for seropositivity, and frequency of prescribing heartworm preventives for cats. DESIGN Prospective cross-sectional study. ANIMALS 34,975 cats from 1,353 veterinary clinics (n = 26,707) and 125 animal shelters (8,268) in the United States and Canada. PROCEDURES Blood samples were collected from all cats and tested with a point-of-care ELISA for Dirofilaria immitis antigen, FeLV antigen, and FIV antibody. Results were compared among geographic regions and various cat groupings. RESULTS Seropositivity for heartworm antigen in cats was identified in 35 states but not in Canada; overall seroprevalence in the United States was 0.4%. Seroprevalence of heartworm infection was highest in the southern United States. A 3-fold increase in the proportion of seropositive cats was identified for those with (vs without) outdoor access, and a 2.5-fold increase was identified for cats that were unhealthy (vs healthy) when tested. Seroprevalence was 0.3% in healthy cats, 0.7% in cats with oral disease, 0.9% in cats with abscesses or bite wounds, and 1.0% in cats with respiratory disease. Coinfection with a retrovirus increased the risk of heartworm infection. Heartworm preventives were prescribed for only 12.6% of cats at testing, and prescribing was more common in regions with a higher seroprevalence. CONCLUSIONS AND CLINICAL RELEVANCE At an estimated prevalence of 0.4%, hundreds of thousands of cats in the United States are likely infected with heartworms. Given the difficulty in diagnosing infection at all clinically relevant parasite stages and lack of curative treatment options, efforts should be increased to ensure all cats receive heartworm preventives.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.250.8.873", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28356105", "author": "Legroux JP", "n_authors": 8, "title": "First clinical case report of Cytauxzoon sp. infection in a domestic cat in France.", "abstract": "Feline cytauxzoonosis is an emerging infection caused by tick-transmitted apicomplexan parasites of the genus Cytauxzoon. The association of clinical disease with Cytauxzoon infection appears to be limited to C. felis infections in the Americas. Sporadic infections of wild and domestic felids with Cytauxzoon sp. were recently described in European countries but clinical reports of the infection are rare and incomplete. This case report brings new interesting information on cytauxzoonosis expression in Europe. A 9-years-old castrated European shorthair cat living in rural area of north-eastern France (Saint Sauveur, Bourgogne-Franche-Comté region), without any travel history was presented for consultation due to hyperthermia, anorexia, depression and prolonged fever that didn't respond to antibiotic therapy. The cat had outdoor access with a history of vagrancy and was adequately vaccinated (core vaccines and FeLV vaccine). During biological investigations, intraerythrocytic inclusions were observed on blood smear and were further investigated by PCR analysis and sequencing. Molecular analyses confirmed Cytauxzoon sp. infection. The cat was treated with a subcutaneous injection of imidocarb dipropionate (3.5 mg/kg). One week after treatment, the cat improved clinically, although parasitic inclusions within erythrocytes persisted, and only a mild lymphocytosis was found. Two weeks after treatment, the cat appeared in excellent health, appetite was normal and parasitemia was negative. However, one month after treatment the cat relapsed with hyperthermia, anorexia, and depression. Blood smears and PCR were once again positive. Subsequently, the cat received an additional dose of imidocarb dipropionate (3.5 mg/kg SC) and recovered rapidly without other clinical signs. Two weeks after the second imidocarb injection, the cat was hit by a car and died. This case provides the first clinical description of infection by Cytauxzoon sp. in a domestic cat in France. These findings support the fact that cytauxzoonosis should be considered in the differential diagnosis of acute febrile illness which does not respond to antibiotic in cats with outdoor access especially in areas where populations of wild felids are present.", "journal": "BMC veterinary research", "doi": "10.1186/s12917-017-1009-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28285597", "author": "Attipa C", "n_authors": 11, "title": "Prevalence study and risk factor analysis of selected bacterial, protozoal and viral, including vector-borne, pathogens in cats from Cyprus.", "abstract": "Feline infectious agent studies are lacking in Cyprus. The aims of this study were to determine the prevalence and risk factors for various feline infectious agents, including feline vector-borne pathogens (FVBP), in cats from Cyprus. A cross-sectional, descriptive, multicentre study was performed on 174 feline samples [138 owned and 36 shelter-feral, including both healthy (43) and non-healthy (131), cats] from private veterinary clinics from all six districts of Cyprus. Real-time quantitative polymerase chain reaction (qPCR) assays were used to detect Mycoplasma haemofelis (Mhf), \"Candidatus Mycoplasma haemominutum\" (CMhm) and \"Candidatus Mycoplasma turicensis\" (CMt). The population was tested for four FVBP including Bartonella henselae and Leishmania spp. using qPCR, while conventional PCR assays were used to detect Ehrlichia/Anaplasma spp. and Hepatozoon spp. Serological assays were performed to detect Leishmania infantum antibodies, feline leukaemia virus (FeLV) antigen and feline immunodeficiency virus (FIV) antibodies. Statistical analysis was performed to test associations and possible risk factors between variables and infectious agents. Ninety-six (55.2%) of the 174 cats were PCR-positive for at least one infectious agent. Forty-six cats (26.4%) were haemoplasma positive, including 13 (7.5%) for Mhf, 36 (20.7%) for CMhm and 12 (6.9%) for CMt. Sixty-six cats (37.9%) were positive for Hepatozoon spp., while 19 (10.9%) were positive for B. henselae, four (2.3%) for Leishmania spp. and one (0.6%) for Ehrlichia/Anaplasma spp. Sequencing revealed the presence of Hepatozoon felis, L. infantum and Anaplasma platys. Of the 164 cats that underwent retroviral serology, 10 (6.1%) were FeLV-positive and 31 (18.9%) were FIV-positive, while L. infantum serology was positive in 7 (4.4%) of the 160 cats tested. Multivariable logistic regression revealed significant associations for various infectious agents including L. infantum with each of Hepatozoon spp. and CMt infection. A high prevalence of infectious agents was found in cats from Cyprus with Mhf, CMhm, CMt, L. infantum, B. henselae, H. felis, A. platys, FeLV and FIV infections reported for the first time. The significant associations between different pathogens provide a better understanding of similarities in the epidemiology of these pathogens and interactions between them.", "journal": "Parasites & vectors", "doi": "10.1186/s13071-017-2063-2", "deposited_data": "Sim", "nuccore_ids": "1104531161, 1104515340, 1104515339, 1104515338, 1104515337, 1104515336, 1104515335, 1104515334, 1104515333, 1104515332, 1104515331, 1104515330, 1104515329, 1104515328, 1104515327", "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28285590", "author": "Díaz-Regañón D", "n_authors": 9, "title": "Molecular detection of Hepatozoon spp. and Cytauxzoon sp. in domestic and stray cats from Madrid, Spain.", "abstract": "Different species of apicomplexan protozoans of the genera Hepatozoon and Cytauxzoon can infect domestic cats, but their epidemiology and clinical relevance are not fully understood. The aim of this study was to assess the molecular prevalence of Hepatozoon spp. and Cytauxzoon spp. and to identify associated risk factors and clinical and laboratory abnormalities in a population of cats from Madrid, Spain. Six hundred and forty-four client-owned and stray cats from Madrid, Spain, were included in this study. DNA samples were analyzed by two polymerase chain reaction (PCR) tests to detect a partial sequence of the 18S rRNA gene of Hepatozoon spp. and Cytauxzoon spp. In order to evaluate possible associations between infection by these protozoans and epidemiological or clinical parameters, data were collected related to: the season of sample collection, age, gender, spayed/neutered status, breed, living area, lifestyle, outdoor access, contact with other animals, prey on wild animals, history of tick or flea infestation, travel history, ectoparasiticide treatment, previous blood transfusion, previous tetracycline administration in the last 60 days, Feline Leukemia virus (FeLV) and Feline Immunodeficiency virus (FIV) status, positivity to other vector-borne diseases, the presence or absence of clinical signs and hematological or biochemical alterations. DNA of Hepatozoon spp. and Cytauxzoon sp. was amplified from the blood of 10 (1.6%) and 8 (1.2%) cats, respectively. Previous treatment with tetracyclines in the last 60 days, previous administration of blood transfusion, a decrease in haematocrit and an increase in creatinine were associated with Hepatozoon spp. infection. Cytauxzoon sp. infection was more frequent in samples collected during the winter months and in cats living in rural areas. This infection was associated with a FIV-positive status. Some of the cats that were positive for Hepatozoon spp. or Cytauxzoon sp. had been exposed to other vector-borne pathogens, such as Ehrlichia canis and Bartonella henselae. Our results indicate that cats from Madrid, central Spain, are infected with Hepatozoon spp. and Cytauxzoon sp., although with a low prevalence. Further studies are needed to determine the virulence of these agents in Spanish cats.", "journal": "Parasites & vectors", "doi": "10.1186/s13071-017-2056-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28202016", "author": "Bergmann M", "n_authors": 6, "title": "Risk factors of different hemoplasma species infections in cats.", "abstract": "Hemoplasma species (spp.) commonly cause infections in cats worldwide. However, data on risk factors for infections are limited. The aim of this study was to determine the prevalence of hemoplasma spp. infections in cats in Southern Germany and to assess risk factors associated with infection. DNA was extracted from blood samples of 479 cats presented to different veterinary hospitals for various reasons. DNA of feline hemoplasmas was amplified by use of a previously reported PCR assay. Direct sequencing was used to confirm all purified amplicons and compared to hemoplasma sequences reported in GenBank. Results were evaluated in relation to the age, sex, housing conditions, feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) status of the cats. The overall hemoplasma prevalence rate was 9.4% (45/479; 95% CI: 7.08-12.36). 'Candidatus Mycoplasma (M.) haemominutum' (Mhm) DNA was amplified from 42 samples, M. haemofelis from 2, and M. haemocanis from 1 sample. There was a significantly higher risk of hemoplasma infection in cats from multi-cat households, in outdoor cats, as well as in cats with FIVinfection and in cats with abortive FeLV infection, but not in cats with progressive or regressive FeLV infection. Mhm infection is common in cats in Southern Germany. Higher prevalence in multi-cat households and associations with FeLV infection likely reflect the potential for direct transmission amongst cats. Outdoor access, male gender, and FIV infection are additional risk factors that might relate to aggressive interactions and exposure to vectors.", "journal": "BMC veterinary research", "doi": "10.1186/s12917-017-0953-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28158913", "author": "Levy JK", "n_authors": 3, "title": "Performance of 4 Point-of-Care Screening Tests for Feline Leukemia Virus and Feline Immunodeficiency Virus.", "abstract": "More than 3 million cats in the United States are infected with FeLV or FIV. The cornerstone of control is identification and segregation of infected cats. To compare test performance with well-characterized clinical samples of currently available FeLV antigen/FIV antibody combination test kits. Surplus serum and plasma from diagnostic samples submitted by animal shelters, diagnostic laboratories, veterinary clinics, and cat research colonies. None of the cats had been vaccinated against FIV. The final sample set included 146 FeLV+, 154 FeLV-, 94 FIV+, and 97 FIV- samples. Prospective, blind comparison to a gold standard: Samples were evaluated in 4 different point-of-care tests by ELISA antigen plate tests (FeLV) and virus isolation (FIV) as the reference standards. All test results were visually read by 2 blinded observers. Sensitivity and specificity, respectively, for FeLV were SNAP The SNAP", "journal": "Journal of veterinary internal medicine", "doi": "10.1111/jvim.14648", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28155290", "author": "Friedlein RB", "n_authors": 4, "title": "The diagnosis of bilateral primary renal paragangliomas in a cat.", "abstract": "A 9-year-old sterilised female domestic short-hair cat was referred with a history of vomiting and anorexia of 3 months' duration. Biochemistry, full-blood counts, thoracic radiographs, feline pancreatic-specific lipase, abdominal ultrasonography and feline immunodeficiency virus/feline leukaemia virus (FIV/FeLV) SNAP tests had been performed. Mild hypochloraemia and moderate hypokalaemia were evident on initial presentation. Abdominal ultrasonography initially revealed unilateral renal nodules on the left side. These were subjected to fine-needle aspiration and cytological evaluation. A neuroendocrine tumour was suspected, and biopsies via midline coeliotomy were taken to confirm the diagnosis. Initial histopathology diagnosed primary renal carcinomas or neuroendocrine neoplasia; however, the definitive diagnosis became renal paragangliomas after immunohistochemistry and transmission electron microscopy were performed. The cat was regularly monitored with serum biochemistry parameters, blood pressure determinations, thoracic radiographs and subsequent abdominal ultrasonography. Biochemistry, radiography and blood pressures remained normal over a 24-week follow-up period, while subsequent ultrasonography revealed tumour progression in both number and size in both kidneys. Primary neuroendocrine tumours of the kidney are frequently incorrectly diagnosed as other renal tumours such as renal cell carcinoma, mesonephric tumours or undifferentiated carcinomas. This case report highlights the importance of additional testing, including immunohistochemistry and transmission electron microscopy, to obtain a definitive diagnosis of paragangliomas.", "journal": "Journal of the South African Veterinary Association", "doi": "10.4102/jsava.v88i0.1412", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28154463", "author": "Thengchaisri N", "n_authors": 4, "title": "Association of gingivitis with dental calculus thickness or dental calculus coverage and subgingival bacteria in feline leukemia virus- and feline immunodeficiency virus-negative cats.", "abstract": "Periodontal disease is the most common oral disease in cats. The objectives of this study were to determine the relationships between gingivitis and dental calculus thickness (DCT), or dental calculus coverage (DCC); determine the association of gingivitis scores and types of oral bacteria; and to evaluate bacterial co-infection in cats with periodontal disease. Twelve cats that were not infected with feline leukemia or feline immunodeficiency viruses were enrolled in the study. Gingivitis, DCT, and DCC were scored and recorded. A Kruskal-Wallis test was used to compare scores among canine, 2nd premolar, 3rd premolar, 4th premolar, and 1st molar teeth. The relationship between gingivitis and DCT or DCC scores was determined using the Spearman rank sum test (ρ). Subgingival bacteria were cultured and the association between bacterial species and gingivitis score was evaluated using a Fisher's exact test. The average gingivitis, DCT, and DCC scores for the caudal maxillary teeth were higher for the caudal mandibular teeth and more severe for the 3rd premolar, 4th premolar, and 1st molar teeth than for the canine teeth. A strong relationship between average DCT or DCC score and average gingivitis score was found (ρ = 0.96 and 1, respectively). Aerobic and anaerobic bacterial infections were identified in a large number of cats with periodontal disease (71.1% and 28.9%, respectively). In conclusion, severe gingivitis scores were associated with anaerobic bacterial infection. The caudal teeth are affected with more severe gingivitis, DCT, and DCC than the other teeth. Antibiotic prophylaxis should be prescribed in cats with periodontal disease.", "journal": "Canadian journal of veterinary research = Revue canadienne de recherche veterinaire", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28131385", "author": "Westman ME", "n_authors": 5, "title": "Comparison of three feline leukaemia virus (FeLV) point-of-care antigen test kits using blood and saliva.", "abstract": "Feline leukaemia virus (FeLV) can be a challenging infection to diagnose due to a complex feline host-pathogen relationship and occasionally unreliable test results. This study compared the accuracy of three point-of-care (PoC) FeLV p27 antigen test kits commonly used in Australia and available commercially worldwide (SNAP FIV/FeLV Combo, Witness FeLV/FIV and Anigen Rapid FIV/FeLV), using detection of FeLV provirus by an in-house real-time polymerase chain reaction (qPCR) assay as the diagnostic gold standard. Blood (n=563) and saliva (n=419) specimens were collected from a population of cats determined to include 491 FeLV-uninfected and 72 FeLV-infected individuals (45 progressive infections [p27 and qPCR positive], 27 regressive infections [p27 negative, qPCR positive]). Sensitivity and specificity using whole blood was 63% and 94% for SNAP Combo, 57% and 98% for Witness, and 57% and 98% for Anigen Rapid, respectively. SNAP Combo had a significantly lower specificity using blood compared to the other two kits (P=0.004 compared to Witness, P=0.007 compared to Anigen Rapid). False-positive test results occurred with all three kits using blood, and although using any two kits in parallel increased specificity, no combination of kits completely eliminated the occurrence of false-positive results. We therefore recommend FeLV proviral PCR testing for any cat that tests positive with a PoC FeLV antigen kit, as well as for any cat that has been potentially exposed to FeLV but tests negative with a FeLV antigen kit, before final assignment of FeLV status can be made with confidence. For saliva testing, sensitivity and specificity was 54% and 100%, respectively, for all three test kits. The reduced sensitivity of saliva testing compared to blood testing, although not statistically significant, suggests saliva testing with the current generation of PoC FeLV antigen kits is unsuitable for screening large populations of cats, such as in shelters.", "journal": "Comparative immunology, microbiology and infectious diseases", "doi": "10.1016/j.cimid.2016.11.014", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28130406", "author": "Bergmann M", "n_authors": 6, "title": "Prevalence of Bartonella species infections in cats in Southern Germany.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.103843", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28112564", "author": "Yilmaz H", "n_authors": 13, "title": "Frequency, clinicopathological features and phylogenetic analysis of feline morbillivirus in cats in Istanbul, Turkey.", "abstract": "Objectives The aim of the study was to investigate feline morbillivirus (FmoPV) frequency, phylogeny and associated pathology in cats in Istanbul, Turkey. Methods Samples from sick (n = 96) and dead ( n = 15) cats were analysed using reverse transcription PCR. Blood and urine analyses and histopathology were also performed. Results FmoPV RNA was detected in six cats (5.4%), including three sick (in the urine) and three dead cats (tissues). A significantly greater proportion of FmoPV RNA-positive cats had street access compared with non-infected cats. Blood samples from the morbillivirus-positive cats were negative for morbillivirus RNA. Tubular parenchymal cells, lymphoid and plasma cells in kidney and hepatocytes, lymphoid and plasma cells in liver from dead cats were also positive by immunohistochemistry for the viral N protein. Two FmoPV-positive cats were also positive for feline coronavirus RNA and one cat for feline immunodeficiency virus RNA and feline leukaemia virus proviral DNA. Phylogenetic analysis of the six FmoPV-positive cats showed that the strains were grouped into cluster D and had high similarity (98.5-100%) with strains from Japan and Germany. In the three FmoPV RNA-positive sick cats, respiratory, urinary and digestive system signs were observed as well as weight loss, fever and depression in some cats. Similar clinical signs were also seen in the morbillivirus RNA-negative sick cats. FmoPV RNA-positive cats had lower median red blood cell count, haemoglobin, albumin, albumin/globulin and urobilinogen and higher alanine transaminase, alkaline phosphatase and bilirubin compared with non-infected cats. Significant histopathology of FmoPV RNA-positive dead cats included tubulointerstitial nephritis characterised by severe granular and vacuolar degeneration of the epithelial cells of the cortical and medullary tubules as well as mononuclear cell infiltrates. Widespread lymphoid cell infiltrates were detected in the renal cortex and medullary regions of the kidneys. Cellular infiltration, cholangiohepatitis and focal necrosis in the liver were also found. Although virus-infected cells were found in the kidney and liver of FmoRV RNA-positive cats, tubulointerstitial nephritis, cholangiohepatitis and focal necrosis seen in FmoRV RNA-positive cats were similar to those observed in FmoRV RNA-negative cats. Conclusions and relevance This is the first study to show the presence of FmoPV infection in cats in Turkey. Sick cats, particularly those with kidney disease, should be tested for this virus. The genotypes found in this study were similar to previously reported strains, indicating that circulating morbilliviruses in Turkey are conserved.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X16686728", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "30050850", "author": "Saba CF", "n_authors": 1, "title": "Vaccine-associated feline sarcoma: current perspectives.", "abstract": "Feline injection site sarcomas (FISS; also known as vaccine-associated sarcomas) have been recognized for >20 years. Although uncommon, these tumors are iatrogenic, and vaccination against rabies and feline leukemia virus is perhaps the most common inciting cause. The exact etiopathogenesis is unknown, but it is widely accepted that inflammation induced by vaccines or other injections likely plays a critical role in tumor development. Injection site sarcomas are extremely locally invasive. Multimodal therapy, incorporating combinations of surgery, radiation therapy, and sometimes chemotherapy or immunotherapy, is recommended. However, tumor recurrences are common even with aggressive treatment, and many cats with FISS ultimately succumb to this devastating disease. While vaccination protocols play an important role in the management and control of infectious disease, veterinarians must be diligent in following established vaccination guidelines to minimize individual patient risk of FISS development. Early tumor detection and client education are also vital in the successful treatment of FISS.", "journal": "Veterinary medicine (Auckland, N.Z.)", "doi": "10.2147/VMRR.S116556", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28062843", "author": "León CI", "n_authors": 9, "title": "Prevalence of selected pathogens in small carnivores in reintroduction areas of the Iberian lynx (Lynx pardinus).", "abstract": null, "journal": "The Veterinary record", "doi": "10.1136/vr.104038", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28031367", "author": "Terry A", "n_authors": 10, "title": "Barriers to Infection of Human Cells by Feline Leukemia Virus: Insights into Resistance to Zoonosis.", "abstract": "The human genome displays a rich fossil record of past gammaretrovirus infections, yet no current epidemic is evident, despite environmental exposure to viruses that infect human cells ", "journal": "Journal of virology", "doi": "10.1128/JVI.02119-16", "deposited_data": "Sim", "nuccore_ids": "1890529932, 1889455422, 1889451272, 1519314687, 1159731398", "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28005210", "author": "Kawamura M", "n_authors": 10, "title": "AKT capture by feline leukemia virus.", "abstract": "Oncogene-containing retroviruses are generated by recombination events between viral and cellular sequences, a phenomenon called \"oncogene capture\". The captured cellular genes, referred to as \"v-onc\" genes, then acquire new oncogenic properties. We report a novel feline leukemia virus (FeLV), designated \"FeLV-AKT\", that has captured feline c-AKT1 in feline lymphoma. FeLV-AKT contains a gag-AKT fusion gene that encodes the myristoylated Gag matrix protein and the kinase domain of feline c-AKT1, but not its pleckstrin homology domain. Therefore, it differs structurally from the v-Akt gene of murine retrovirus AKT8. AKT may be involved in the mechanisms underlying malignant diseases in cats.", "journal": "Archives of virology", "doi": "10.1007/s00705-016-3192-1", "deposited_data": "Sim", "nuccore_ids": "1247173509, 1247173507, 1247173505, 1016841021, 803376001, 803375601, 2131058517, 2131058516, 2131058514, 2131058512, 2131058510, 2131058508, 2131058506, 2131058504, 2131058502, 2131058500, 2131058498, 2131058496, 1016841021", "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "27770018", "author": "Westman ME", "n_authors": 6, "title": "Duration of antibody response following vaccination against feline immunodeficiency virus.", "abstract": "Objectives Recently, two point-of-care (PoC) feline immunodeficiency virus (FIV) antibody test kits (Witness and Anigen Rapid) were reported as being able to differentiate FIV-vaccinated from FIV-infected cats at a single time point, irrespective of the gap between testing and last vaccination (0-7 years). The aim of the current study was to investigate systematically anti-FIV antibody production over time in response to the recommended primary FIV vaccination series. Methods First, residual plasma from the original study was tested using a laboratory-based ELISA to determine whether negative results with PoC testing were due to reduced as opposed to absent antibodies to gp40. Second, a prospective study was performed using immunologically naive client-owned kittens and cats given a primary FIV vaccination series using a commercially available inactivated whole cell/inactivated whole virus vaccine (Fel-O-Vax FIV, three subcutaneous injections at 4 week intervals) and tested systematically (up to 11 times) over 6 months, using four commercially available PoC FIV antibody kits (SNAP FIV/FeLV Combo [detects antibodies to p15/p24], Witness FeLV/FIV [gp40], Anigen Rapid FIV/FeLV [p24/gp40] and VetScan FeLV/FIV Rapid [p24]). Results The laboratory-based ELISA showed cats from the original study vaccinated within the previous 0-15 months had detectable levels of antibodies to gp40, despite testing negative with two kits that use gp40 as a capture antigen (Witness and Anigen Rapid kits). The prospective study showed that antibody testing with SNAP Combo and VetScan Rapid was positive in all cats 2 weeks after the second primary FIV vaccination, and remained positive for the duration of the study (12/12 and 10/12 cats positive, respectively). Antibody testing with Witness and Anigen Rapid was also positive in a high proportion of cats 2 weeks after the second primary FIV vaccination (8/12 and 7/12, respectively), but antibody levels declined below the level of detection in most cats (10/12) by 1 month after the third (final) primary FIV vaccination. All cats tested negative using Witness and Anigen Rapid 6 months after the third primary FIV vaccination. Conclusions and relevance This study has shown that a primary course of FIV vaccination does not interfere with FIV antibody testing in cats using Witness and Anigen Rapid, provided primary vaccination has not occurred within the previous 6 months. Consequently, Witness and Anigen Rapid antibody test kits can be used reliably to determine FIV infection status at the time of annual booster FIV vaccination to help detect 'vaccine breakthroughs' and in cats that have not received a primary course of FIV vaccination within the preceding 6 months. The duration of antibody response following annual booster FIV vaccination and the resulting effect on antibody testing using PoC kits needs to be determined by further research. The mechanism(s) for the variation in FIV antibody test kit performance remains unclear.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X16673292", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "26858258", "author": "Rolim VM", "n_authors": 9, "title": "Clinical, pathological, immunohistochemical and molecular characterization of feline chronic gingivostomatitis.", "abstract": "Objectives This study presents the clinical, pathological, immunohistochemical and molecular characterization of 26 cats with feline chronic gingivostomatitis (FCG). Methods Oral mucosal biopsies, blood and swabs were collected from cats presenting with oral lesions. The tissue sections were submitted for histopathology and immunohistochemical analysis for feline calicivirus (FCV), feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV). The swabs were subjected to PCR analysis for FCV, and blood for FeLV and FIV. Results The main clinical findings were dysphagia (88.2%), halitosis (76.5%), sialorrhea (47.1%), weight loss (41.2%), intense oral discomfort (35.3%), oral hemorrhage (17.6%), and lackluster and fragile coat (11.8%). Gross inspection revealed bilateral lesions across the palatoglossal fold to the lateral tongue base. The lesions were diffuse, proliferative, intensely red and friable, and bled easily upon examination in 80.8% of cases. In 23.1% of cases, the lesions were multifocal to coalescent, at times forming multiple vesicles on a reddened, edematous palatoglossal fold. Microscopic examination showed that 15.4% of lesions had moderate (grade 2) and 84.6% had severe (grade 3) inflammation. Immunohistochemistry revealed the presence of FeLV antigens in the epithelium and the inflammatory infiltrate of 30.8% of the cats with FCG. FCV antigens were not detected in the FCG lesions. Conclusions and relevance The FCG cases analyzed could not be correlated with FCV. It is possible that FeLV plays a role as a causal agent of lesions in cases where the presence of the virus has been confirmed by immunohistochemistry in epithelial samples.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X16628578", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "30544924", "author": "Cavalcante LTF", "n_authors": 10, "title": "Clinical and Molecular Features of Feline Foamy Virus and Feline Leukemia Virus Co-Infection in Naturally-Infected Cats.", "abstract": "Feline foamy virus (FFV) and feline leukemia virus (FeLV) belong to the ", "journal": "Viruses", "doi": "10.3390/v10120702", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "30502798", "author": "Leite-Filho RV", "n_authors": 4, "title": "Pathological Characterization of Lymphoma with Pulmonary Involvement in Cats.", "abstract": "Studies evaluating histological patterns of lung infiltration by lymphoma in cats are lacking. We evaluated retrospectively the histological patterns of 125 necropsy cases of feline lymphoma collected over a 12-year period. Of the 125 cases, 16 showed lung infiltration (12.8%). Nine cats were female, seven cats were male and all were of mixed breed. Gross lesions observed in the lungs consisted of masses (25%) and nodules (18.7%); however, the majority of cases (56.2%) did not show any gross abnormality. Peribronchial-vascular infiltration (93.7%) was the most frequent pattern, followed by pleural (56.2%), interstitial (50%), nodular (37.5%) and alveolar (12.5%) patterns, but 75% of the cases had more than one pulmonary infiltration pattern. There were 14 (87.5%) B-cell and two (12.5%) T-cell lymphomas. Six cats (37.5%) were positive for feline leukaemia virus and three cats (18.7%) were positive for feline immunodeficiency virus. Diffuse large B-cell lymphoma was the most frequent type, accounting for 56% of all cases.", "journal": "Journal of comparative pathology", "doi": "10.1016/j.jcpa.2018.09.007", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "30500849", "author": "de Miranda LHM", "n_authors": 10, "title": "Co-infection with feline retrovirus is related to changes in immunological parameters of cats with sporotrichosis.", "abstract": "Feline sporotrichosis due to Sporothrix brasiliensis is frequently severe and often correlated to zoonotic transmission. Feline Immunodeficiency Virus (FIV) and Feline Leukemia Virus (FeLV) cause immunodeficiency in cats; no association has been identified with critical cases of sporotrichosis. Moreover, the cytokine profile in Sporothrix-infected cats and a potential impact of retrovirus co-infections on their immunity is unknown. This study assessed immunological parameters in cats with sporotrichosis with and without FIV or FeLV co-infection. FeLV infection was detected by antigen ELISA and by provirus PCR. FIV infection was investigated through ELISA and Western blot. Cytokine transcription (IFN-γ, IL-4, IL-5, IL-6, IL-10, IL-12, TNF-α) was quantified using RT-qPCR and lymphocyte subpopulations (CD4, CD8, CD5 and CD21) were assessed by flow cytometry. Thirty cats with sporotrichosis were recruited to the study, including three FIV-positive and five FeLV-positive (progressive infection) cats. One cat with regressive FeLV infection was excluded from statistics. In comparison to retrovirus-negative cats, FIV-positive cats and FeLV-positive cats had higher IL-10 levels, FeLV-positive cats had lower IL-4 levels and FIV-positive cats had lower IL-12 levels and a lower CD4+/CD8+ ratio. Remarkably, all cats with poor general condition were FeLV (progressive infection) or FIV-positive, but the retrovirus status was not associated with the sporotrichosis treatment length or outcome. The immunological changes and the more severe clinical presentation observed in cats with retrovirus co-infections encourage future prospective studies that address the impact of these changes on prognostic determinants of feline sporotrichosis and the development of new therapy strategies that control disease spread.", "journal": "PloS one", "doi": "10.1371/journal.pone.0207644", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "30462823", "author": "Munhoz AD", "n_authors": 8, "title": "Hemotropic mycoplasmas in naturally infected cats in Northeastern Brazil.", "abstract": "This study aimed to determine the prevalence, factors associated, laboratory findings (with and without coinfection by retroviruses) among naturally infected cats by hemoplasmas in northeastern Brazil. For convenience, 200 domesticated and healthy cats were selected. Blood samples were taken to perform complete blood counts, serum biochemical, immunochromatography tests and nPCR for FIV and FeLV, and PCR for hemoplasma recognition. An interview was conducted to determine the factors associated with hemoplasmas. A total of 71/200 (35.5%) cats were positive for at least one hemoplasma species. Isolated infections were observed in 12,5% for 'Candidatus Mycoplasma haemominutum', 12% for Mycoplasma haemofelis and 3% for 'Candidatus Mycoplasma turicensis'. Regarding copositivity, 2% of the animals were positive for M. haemofelis and 'Candidatus Mycoplasma haemominutum', 1.5% for M. haemofelis and 'Candidatus Mycoplasma turicensis', and 4.5% for ' Candidatus Mycoplasma haemominutum' and 'Candidatus Mycoplasma turicensis'. No clinical and laboratory changes were observed in the animals that were concomitantly positive for retroviruses and hemoplasmas. Periurban region cats were more likely to be infected by M. haemofelis, while contact with other cats and infection by ' Candidatus Mycoplasma turicensis' were associated with 'Candidatus Mycoplasma haemominutum'. This study indicates that infection by hemoplasmas is a common find in cats from northeastern Brazil.", "journal": "Revista brasileira de parasitologia veterinaria = Brazilian journal of veterinary parasitology : Orgao Oficial do Colegio Brasileiro de Parasitologia Veterinaria", "doi": "10.1590/S1984-296120180074", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "30444160", "author": "Lee J", "n_authors": 9, "title": "Clinical and imaging characteristics of posterior column ataxia with retinitis pigmentosa with a specific FLVCR1 mutation.", "abstract": "Posterior column ataxia retinitis pigmentosa (PCARP) with feline leukemia virus subgroup C cellular receptor 1 (FLVCR1) gene mutation is a rare disorder with significant ophthalmic features. We conducted a retrospective case series study of patients diagnosed with PCARP and genetic testing positive for FLVCR1 mutation between 1 January 2015 and 1 October 2017 at the Children's Hospital of Pittsburgh. Clinical charts, visual fields, fundus autofluorescence, and spectral-domain optical coherence tomography (SD-OCT) were reviewed. Seven patients from three families were identified to have PCARP and FLVCR1 mutation. The median age at presentation was 13 years (range, 7-28 years). Common clinical exam findings were astigmatism, cataracts, and vitreous syneresis. Funduscopy on all patients revealed bull's eye maculopathy, retinal vessels attenuation, and bone spicule changes in the peripheral retina. Fundus autofluorescence showed bilateral hyperautofluorescent rings. SD-OCT demonstrated morphological changes, which differed based on age. The youngest sibling family exhibited peripheral loss, but subfoveal preservation of the outer retinal layers. These layers were lost in the oldest sibling family. Visual fields loss paralleled SD-OCT findings. There is limited published ophthalmic data on FLVCR1-related PCARP. We describe clinical and retinal imaging features in the one of the largest cohorts of affected patients in the literature. Given the availability of genetic testing for this phenotype, testing for FLVCR1 mutations should be considered in pediatric and adult patients with sensory ataxia and retinitis pigmentosa.", "journal": "Ophthalmic genetics", "doi": "10.1080/13816810.2018.1547913", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "30213367", "author": "Graf R", "n_authors": 5, "title": "Feline Injection Site Sarcomas: Data from Switzerland 2009-2014.", "abstract": "Feline injection site sarcomas (FISS) were first described in the early 1990s. Despite extensive research, the pathogenesis of these tumours has not been elucidated conclusively. Their appearance and the marked increase in their incidence has been mainly connected to the injection of vaccines, and it is assumed that a chronic inflammatory reaction at the injection site triggers subsequent malignant transformation. The role of alum-based adjuvants has been discussed, but is controversial. The present study of the Swiss Feline Cancer Registry (SFCR) with data from 2009 to 2014 revealed a marked decrease of the incidence of fibrosarcomas compared with the previous observation period. Notably, this drop occurred after a non-adjuvanted feline leukaemia virus vaccine was introduced in Switzerland in 2007. This observation, together with the previous findings of the SFCR, further supports the notion that alum-adjuvanted vaccines are involved in the genesis of FISS and that non-adjuvanted vaccines might be safer for cats.", "journal": "Journal of comparative pathology", "doi": "10.1016/j.jcpa.2018.06.008", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "30149410", "author": "Krug S", "n_authors": 5, "title": "[Feline leprosy in a 5-month-old male cat in Germany].", "abstract": "A 5-month-old, male, 4 kg European shorthair cat presented with ulcera ted cutaneous nodules in many areas over its entire body. The serological results for feline immunodeficiency virus and the feline leukaemia virus were negative. Following detection of acid-proof bacilli in histological examination of three skin biopsies, the diagnosis of mycobacteriosis of the skin was made. Polymerase chain reaction revealed the presence of ", "journal": "Tierarztliche Praxis. Ausgabe K, Kleintiere/Heimtiere", "doi": "10.15654/TPK-170642", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "30104776", "author": "Zandonà L", "n_authors": 6, "title": "Cerebral toxoplasmosis in a cat with feline leukemia and feline infectious peritonitis viral infections.", "abstract": "A diarrheic young cat died after neurological involvement. Biochemistry pointed to feline infectious peritonitis (FIP). The final diagnosis was severe multifocal meningoencephalitis due to ", "journal": "The Canadian veterinary journal = La revue veterinaire canadienne", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "30062638", "author": "Heddergott M", "n_authors": 9, "title": "Serological survey of feline viral pathogens in free-living European wildcats (Felis s. silvestris) from Luxembourg.", "abstract": "European populations of free-living wildcats have been shown to be exposed to cat viruses. Luxembourg has a high degree of habitat fragmentation, and hybridisation rates between domestic cats and wildcats are high. We therefore assessed the seroprevalence of six viruses in 34 serum samples collected between 2001 and 2016 from wildcats in Luxembourg. The values for feline leukemia virus (FeLV; 52.9%) and feline coronavirus (FCoV; 47.1%) were amongst the highest reported for wildcats. We found evidence for the cumulative likelihood of exposure to FCoV affecting its seroprevalence. Routine monitoring of viral agents in this strictly protected species should be considered.", "journal": "Archives of virology", "doi": "10.1007/s00705-018-3972-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "30029545", "author": "Makundi I", "n_authors": 4, "title": "Identification of Felis catus Gammaherpesvirus 1 in Tsushima Leopard Cats (Prionailurus bengalensis euptilurus) on Tsushima Island, Japan.", "abstract": null, "journal": "Viruses", "doi": "10.3390/v10070378", "deposited_data": "Sim", "nuccore_ids": "1393169295, 1393169293, 1393169291, 1393169289, 1393169287, 1393169285, 1393169283, 1393169281, 1393169279, 1393169277, 1393169275, 1393169273, 1393169271, 1393169269, 1393169267, 1393169265, 1393169263, 1273480102, 1273480100, 1273480098, 1273480096, 1273480094, 1273480092, 1273480090, 1273480088, 1273480086, 1273480084, 1273480082, 1273480080, 1273480078, 1273480076, 1273480074, 1273480072, 1273480070, 1273480068, 1273480066, 1273480064, 1273480062, 1273480060, 1273480058, 1273480056, 1273480054, 1273480052, 1273480050, 1273480048, 1273480046, 1273480044, 1273480042", "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29976676", "author": "Powers JA", "n_authors": 9, "title": "Feline Leukemia Virus (FeLV) Disease Outcomes in a Domestic Cat Breeding Colony: Relationship to Endogenous FeLV and Other Chronic Viral Infections.", "abstract": "Exogenous feline leukemia virus (FeLV) is a feline gammaretrovirus that results in a variety of disease outcomes. Endogenous FeLV (enFeLV) is a replication-defective provirus found in species belonging to the ", "journal": "Journal of virology", "doi": "10.1128/JVI.00649-18", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29967720", "author": "Hwang J", "n_authors": 6, "title": "Disentangling the link between supplemental feeding, population density, and the prevalence of pathogens in urban stray cats.", "abstract": "Supplemental feeding of free-roaming animals, including wildlife and feral or stray animals, is well known to have a substantial impact on various aspects of animal ecology including habitat use, activity patterns, and host-pathogen interactions. Among them, an increased population density (PD) of animals receiving supplemental food raises concerns regarding the transmission of pathogens in these host populations. The primary aim of this study was to investigate how supplemental feeding is associated with host PD and prevalence of pathogens with different transmission modes in urban stray cats. We hypothesized that supplemental feeding would be positively associated with host PD and the prevalence of pathogens with density-dependent transmission modes compared with pathogens with transmission modes that are considered relatively density-independent. This study was conducted in six districts in Seoul, Republic of Korea which were selected based on different degrees of supplemental feeding and cat caretaker activity (CCA). The PD of stray cats was estimated by mark-recapture surveys. Stray cat blood samples ( In contrast to initial predictions, the cat PD was generally higher in low CCA districts. The prevalence of (FeLV), which is transmitted through direct contact, was significantly higher in areas with a high CCA, conforming to our hypothesis. On the other hand, the prevalence of feline parvovirus, which can be spread by environmental transmission, was higher in low CCA districts. The remaining six pathogens did not show any association with the CCA; however, they had a unique association with the PD or the sex of the stray cats. Our findings suggest that in addition to influencing the PD, supplemental feeding may affect the prevalence of pathogens in urban animals by mechanisms such as increased aggregation and/or altered foraging strategies, with different consequences depending on the transmission mode of each pathogen.", "journal": "PeerJ", "doi": "10.7717/peerj.4988", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "32734056", "author": "Oliveira IVPM", "n_authors": 9, "title": "Research on viral agents associated with feline reproductive problems reveals a high association with feline panleukopenia virus.", "abstract": "Although reproductive failures (RF) such as abortion, stillbirth and neonatal mortality in cats are still under researched, it is known that many RF are caused by viral agents. This research surveyed the viral agent prevalence in queens with RF. Queens were excluded from the study if their RF was caused by issues other than infection, such as genetic, traumatic, hormonal or nutritional problems, or if they had a history of RF. Blood samples from 26 pregnant females with RF were collected for complete blood counts (BCC), renal/hepatic biochemistry and glycaemic analysis. Ultrasonography was performed to evaluate gestational age and foetal viability. When possible, placentas, humours and foetal tissues were collected. Blood samples were tested by PCR and qPCR for feline leukaemia virus (FeLV), feline immunodeficiency virus (FIV), ", "journal": "Veterinary and animal science", "doi": "10.1016/j.vas.2018.06.004", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29899416", "author": "de Souza EW", "n_authors": 11, "title": "Clinical features, fungal load, coinfections, histological skin changes, and itraconazole treatment response of cats with sporotrichosis caused by Sporothrix brasiliensis.", "abstract": "Zoonotic sporotrichosis caused by the fungus Sporothrix brasiliensis is usually severe in cats. This study investigated the associations between clinical features, fungal load, coinfections, histological skin changes, and response to itraconazole in cats with sporotrichosis caused by S. brasiliensis. Fifty-two cats with skin lesions and a definitive diagnosis of sporotrichosis were treated with itraconazole for a maximum period of 36 weeks. The animals were submitted to clinical examination and two subsequent collections of samples from the same skin lesion for fungal diagnosis and histopathology, as well as serology for feline immunodeficiency (FIV) and leukaemia (FeLV) viruses. Thirty-seven (71%) cats were clinically cured. Nasal mucosa lesions and respiratory signs were associated with treatment failure. Cats coinfected with FIV/FeLV (n = 12) had a lower neutrophil count in the lesion. A high fungal load in skin lesions was linked to young age and treatment failure, as well as to a longer time of wound healing, poorly formed granulomas and fewer neutrophils, macrophages and lymphocytes in these lesions. These results indicate that itraconazole is effective, but nasal mucosal involvement, respiratory signs and high fungal loads in skin lesions are predictors of treatment failure that will assist in the development of better treatment protocols for cats.", "journal": "Scientific reports", "doi": "10.1038/s41598-018-27447-5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29872537", "author": "Bastos BF", "n_authors": 5, "title": "Pentatrichomonas hominis infection in two domestic cats with chronic diarrhea.", "abstract": "Chronic diarrhea is a common and recurring problem in feline medicine. Intestinal trichomonads have been reported as causative agents of diarrhea in cats. While  This case report describes ", "journal": "JFMS open reports", "doi": "10.1177/2055116918774959", "deposited_data": "Sim", "nuccore_ids": "1399043929", "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29854412", "author": "Sarvani E", "n_authors": 11, "title": "Prevalence and risk factor analysis for feline haemoplasmas in cats from Northern Serbia, with molecular subtyping of feline immunodeficiency virus.", "abstract": "The objectives of this study were to estimate the prevalence of feline haemoplasma infections in Northern Serbia, identify potential risk factors and perform molecular subtyping of feline immunodeficiency virus (FIV). PCR analysis for feline haemoplasmas was performed on surplus EDTA blood samples from 373 cats from the Belgrade region, Serbia. An ELISA was used to determine the prevalence of feline leukaemia virus (FeLV) and FIV; PCR was performed on a subpopulation of these cats. FIV subtyping was performed using PCR. Within this population, 64/373 cats (17.2%) were infected with one or more haemoplasma species.  All three known species of feline haemoplasma were detected, confirming their presence in Serbia; '", "journal": "JFMS open reports", "doi": "10.1177/2055116918770037", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29851314", "author": "Hutchinson KM", "n_authors": 4, "title": "Pneumatosis of the intestines, colon and liver in a young cat.", "abstract": "To describe a case of naturally occurring pneumatosis intestinalis, pneumatosis coli and emphysematous hepatitis in a cat. A 9-month-old, indoors-only, female spayed, domestic medium hair cat presented for vomiting, open-mouth breathing and acute collapse. The initial physical examination identified moderate to severe hypothermia [35°C (95°F)], obtunded mentation, weak femoral pulses, tachycardia (heart rate 240 beats per min), pale pink mucous membranes and significant splenomegaly on abdominal palpation. Immediate diagnostics performed [packed cell volume and total solids (PCV, TS), venous blood gas and electrolytes] revealed severe anaemia (PCV 12%), hypoproteinaemia (TS = 2.2 g/dl), and severe metabolic acidosis (pH 6.956). Additional diagnostics performed included Feline Leukaemia Virus and Feline Immunodeficiency Virus testing (FeLV/FIV), complete blood count (CBC) with pathology review, serum biochemistry profile, prothrombin time (PT) and partial thromboplastin time (PTT), urinalysis, and abdominal radiographs. Abdominal radiographs were consistent with gas within hepatic and splenic veins and parenchyma, small intestinal walls and colonic wall. Due to the guarded prognosis, euthanasia was elected. Necropsy was performed and the most significant gross and histopathological findings included intra-luminal and intra-mural intestinal haemorrhage and vascular congestion with mild neutrophilic hepatitis, and marked hepatic periportal emphysema. Clostridium perfrigens and Escherichia coli were cultured from the bowel wall; no bacterial growth from the liver or spleen was identified. This case report describes idiopathic emphysematous hepatitis, with concurrent emphysema of the spleen and intestinal wall and intestinal haemorrhage. To the authors' knowledge, this type of pathology in a feline patient has not been previously described.", "journal": "Veterinary medicine and science", "doi": "10.1002/vms3.96", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29642384", "author": "Kawasaki J", "n_authors": 2, "title": "Tracking the Continuous Evolutionary Processes of an Endogenous Retrovirus of the Domestic Cat: ERV-DC.", "abstract": "An endogenous retrovirus (ERV) is a remnant of an ancient retroviral infection in the host genome. Although most ERVs have lost their viral productivity, a few ERVs retain their replication capacity. In addition, partially inactivated ERVs can present a potential risk to the host via their encoded virulence factors or the generation of novel viruses by viral recombination. ERVs can also eventually acquire a biological function, and this ability has been a driving force of host evolution. Therefore, the presence of an ERV can be harmful or beneficial to the host. Various reports about paleovirology have revealed each event in ERV evolution, but the continuous processes of ERV evolution over millions of years are mainly unknown. A unique ERV family, ERV-DC, is present in the domestic cat (", "journal": "Viruses", "doi": "10.3390/v10040179", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29568541", "author": "Sivagurunathan A", "n_authors": 3, "title": "Prevalence of feline immunodeficiency virus and feline leukaemia virus infection in Malaysia: a retrospective study.", "abstract": "Feline ownership is popular and represents the largest segment of the pet population in Malaysia. Most feline owners own, on average, 2-3 cats, with some having >10 cats per household. Feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV) are two clinically important viral infections in cats. Documenting the prevalence of these diseases in the feline population is important for both veterinarians and the public. This was a retrospective study, using data collected from the domestic cat population seen at a 24 h private veterinary hospital in Malaysia, to determine the prevalence of FIV and FeLV in an urban area and risk factors associated with these infections. Between 2010 and 2016, 2230 blood samples were collected and tested for FIV antibodies and FeLV antigen using commercially available ELISA test kits. In total, 10.0% (n = 224; 95% confidence interval [CI] 8.80-11.26) were seropositive for FIV; 12.0% (n = 267; 95% CI 10.62-13.32) were seropositive for FeLV; and 2.6% (n = 58; 95% CI 2.01-3.17) were seropositive for both. The prevalence of FIV is lower and FeLV higher than previously documented for this region. Because of the immunosuppressive potential of both viruses, client education and use of appropriate control strategies such as routine screening, vaccination and eradication should be considered.", "journal": "JFMS open reports", "doi": "10.1177/2055116917752587", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29554981", "author": "Díaz-Regañón D", "n_authors": 7, "title": "Epidemiological study of hemotropic mycoplasmas (hemoplasmas) in cats from central Spain.", "abstract": "Hemotropic mycoplasmas (hemoplasmas) have been found infecting cats worldwide. However, studies about feline hemoplasma infections in Spain are scarce. Therefore, the purpose of the research was to evaluate the prevalence of feline hemotropic mycoplasmas and to characterize risk factors and clinical findings associated with these infections in a cat population from the Madrid area, Spain. Polymerase chain reaction (PCR) was employed to detect Mycoplasma haemofelis (Mhf), \"Candidatus Mycoplasma haemominutum\" (CMhm) and \"Candidatus Mycoplasma turicensis\" (CMt) in blood samples from 456 client-owned and 138 stray cats from Madrid. In order to assess associations between these hemoplasma infections and epidemiological parameters, data regarding signalment, environment, prophylaxis measures, retrovirus status, clinical signs and laboratory findings were compiled, whenever possible. DNA of feline hemoplasmas was detected from the blood of 63 out of 594 cats (10.6%), with a prevalence of 3.7% (22/594) for Mhf, 8.1% (48/594) for CMhm and 0.5% (3/594) for CMt. Stray cats had statistically higher prevalences of feline hemoplasmas (15.9%) and, specifically, of Mhf (8.7%) than client-owned cats (9 and 2.2%, respectively). A total of seven cats (1.17%) were co-infected with \"Candidatus M. haemominutum\" and M. haemofelis, two (0.33%) with \"Candidatus M. haemominutum\" and \"Candidatus M. turicensis\" and another one (0.17%) with M. haemofelis and Candidatus \"M. turicensis\". Male gender, collection of blood during warm months and FeLV/FIV positivity status were associated with hemotropic mycoplasma infection in cats from Madrid. Additionally, within the group of client-owned cats, hemoplasma infection was associated with adult age, outdoor access, and the existence of low haematocrit, erythrocyte count and haemoglobin concentration values. To our knowledge, this is the first epidemiological survey of feline hemoplasmas performed in central Spain (Madrid). Our study confirms that \"Ca. Mycoplasma haemominutum\", Mycoplasma haemofelis and \"Ca. Mycoplasma turicensis\" are infecting client-owned and stray cats in this region of Spain, \"Ca. Mycoplasma haemominutum\" being the most prevalent species. More studies are necessary to help understand the role of the natural infection by these species of hemoplasma in cats.", "journal": "Parasites & vectors", "doi": "10.1186/s13071-018-2740-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29554969", "author": "Marcondes M", "n_authors": 7, "title": "Infection by Mycoplasma spp., feline immunodeficiency virus and feline leukemia virus in cats from an area endemic for visceral leishmaniasis.", "abstract": "Visceral leishmaniasis (VL) has been increasingly recognized in cats living in areas endemic for the disease. Co-infection with Leishmania infantum and other infectious agents is well established in dogs. However, for cats, data on co-infections with L. infantum and other infectious agents are still sparse. The aim of this study was to identify the prevalence of vector-borne pathogens, Mycoplasma spp., feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV) in cats from an area endemic for VL in southeastern Brazil. Of the 90 cats, eight (8.9%) were infected with Mycoplasma spp., five (5.5%) were FIV- positive and one (1.1%) was FeLV-positive. Co-infection with L. infantum and at least one other infectious agent was found in 9/50 (18.0%; CI: 8.6-31.4%) cats. In Group 1 (cats infected naturally by L. infantum), 4/50 (8.0%) cats were positive for FIV, 4/50 (8%) for Mycoplasma spp. and 1/50 (2.0%) was co-infected with FeLV and Mycoplasma spp. In Group 2 (cats non-infected with L. infantum), 2/40 (5.0%) cats were infected with Mycoplasma spp. and 1/40 (2.5%) was co-infected with FIV and Mycoplasma spp. All cats were negative for Ehrlichia spp., Babesia spp. and Anaplasma platys. A low prevalence of co-infection in Leishmania-infected and non-infected cats was found. Co-infections with Leishmania and vector-borne diseases in cats are not common in this area endemic for VL in Brazil.", "journal": "Parasites & vectors", "doi": "10.1186/s13071-018-2716-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29538321", "author": "McLuckie AJ", "n_authors": 6, "title": "Molecular Diagnosis of Felis catus Gammaherpesvirus 1 (FcaGHV1) Infection in Cats of Known Retrovirus Status with and without Lymphoma.", "abstract": "The pathogenicity of ", "journal": "Viruses", "doi": "10.3390/v10030128", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29532854", "author": "Peng C", "n_authors": 10, "title": "FLVCR1 promotes the proliferation and tumorigenicity of synovial sarcoma through inhibiting apoptosis and autophagy.", "abstract": "Feline leukemia virus subgroup C receptor 1 (FLVCR1) has been reported to have a crucial role in variety of biological processes, including cell proliferation, cell death, apoptosis, oxidative stress response, cellular differentiation and metabolism. However, little is known about its role in synovial sarcoma (SS). In the current study, FLVCR1 expression was analyzed in two SS cell lines (SW982 and HS-SY-II), and in eight SS tissues and paired adjacent non-tumor tissues using reverse transcription-quantitative polymerase chain reaction, western blot analysis and immunohistochemistry. Lentivirus-mediated short hairpin RNAs were used to knock down FLVCR1 expression in SW982 and HS-SY-II cells. The effects of FLVCR1 knockdown on the cell proliferation, clonogenicity, cell cycle and apoptosis in SS cells were evaluated by MTT, colony formation assay, flow cytometry analysis, western blotting and in vivo tumorigenesis in nude mice. In the current study, gene expression of FLVCR1 was upregulated in SS cell lines (SW982 and HS-SY-II) and SS tissues from patients. The protein levels of FLVCR1 in SS tissues were also significantly higher than in adjacent non-tumor tissues. Furthermore, suppressing the expression of FLVCR1 in SS cells using short hairpin RNA effectively attenuated cell proliferation, colony formation and impaired the cell cycle, and also significantly induced apoptosis and autophagy. In accordance with this, an in vivo tumorigenicity assay in mice demonstrated that suppression of FLVCR1 expression inhibited the growth of SS tumors implanted subcutaneously. Collectively, these results demonstrated that FLVCR1 may act as an oncoprotein, and have key roles in promoting proliferation and tumorigenicity of SS, and this may shed new light on finding novel therapeutic strategies against SS.", "journal": "International journal of oncology", "doi": "10.3892/ijo.2018.4312", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29501695", "author": "Montoya A", "n_authors": 11, "title": "Detection and molecular characterization of Acanthamoeba spp. in stray cats from Madrid, Spain.", "abstract": "Acanthamoeba spp. is a widespread protozoan that has been isolated from air, dust, soil, water and biological samples. An opportunistic pathogen of humans and animals, it may cause ocular keratitis, encephalitis, and even multisystem disease. The frequency of Acanthamoeba in animals is unknown. The aim of present study was determine the presence of Acanthamoeba spp. in immunocompromised stray cats - animals possibly more likely to harbour the infection given their immunocompromised status and frequenting of contaminated environments. Of 307 cats examined, 55 were positive for feline immunodeficiency virus and/or feline leukaemia virus and therefore included in the study. Corneal scrapings were obtained to isolate Acanthamoeba spp. by culture and molecular detection by conventional and real time PCR. None of the samples examined directly by molecular methods were positive for Acanthamoeba spp. However, two (3.6%) cases of the cultured samples provided positive results, which were confirmed by subsequent molecular analysis. Sequencing assigned one isolate to genotype T4 and the other to T2. Since Acanthamoeba spp. may also infect animals and humans, the present findings may raise some public health and veterinary concerns.", "journal": "Experimental parasitology", "doi": "10.1016/j.exppara.2018.02.011", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29487747", "author": "Kerns AT", "n_authors": 5, "title": "Extranodal non-B, non-T-cell lymphoma with bilateral tympanic bulla involvement in a cat.", "abstract": "A 9-year-old spayed female domestic shorthair cat with clinical signs suggestive of chronic recurrent otitis media and recent seizures was presented with multifocal nervous system disease, including bilateral central and/or peripheral vestibular, cerebellar and forebrain deficits. Prior to presentation, there was inadequate improvement after 6 weeks of treatment for bilateral middle ear effusion from which a highly susceptible  To our knowledge, this is the first report of lymphoma with confirmed bilateral tympanic bulla involvement in the human and veterinary literature. Neoplasia should be considered in cases of middle-ear effusion that do not improve adequately with appropriate antimicrobial therapy.", "journal": "JFMS open reports", "doi": "10.1177/2055116918756724", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29479677", "author": "Elliott J", "n_authors": 1, "title": "Temporary spontaneous regression of feline non-Hodgkin's lymphoma.", "abstract": "A 6-year-old neutered male British Shorthair cat presented with two rapidly growing subcutaneous masses, one over each thoracic wall. High-grade, non-Hodgkin's lymphoma was confirmed following histopathology, immunohistochemistry and PCR analysis for antigen receptor re-arrangements. Following biopsy there was rapid regression of the remaining neoplastic tissue with no medical treatment. The cat relapsed 3 months later, with poor response to therapy, and was euthanased. Spontaneous regression (SR) of cancer is a rare occurrence and is uncommonly reported in veterinary species. To the author's knowledge this is the first reported case of SR of non-FeLV-related feline, high-grade non-Hodgkin's lymphoma.", "journal": "Australian veterinary journal", "doi": "10.1111/avj.12672", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29456553", "author": "Walter-Nuno AB", "n_authors": 5, "title": "Silencing of Iron and Heme-Related Genes Revealed a Paramount Role of Iron in the Physiology of the Hematophagous Vector Rhodnius prolixus.", "abstract": "Iron is an essential element for most organisms However, free iron and heme, its complex with protoporphyrin IX, can be extremely cytotoxic, due to the production of reactive oxygen species, eventually leading to oxidative stress. Thus, eukaryotic cells control iron availability by regulating its transport, storage and excretion as well as the biosynthesis and degradation of heme. In the genome of ", "journal": "Frontiers in genetics", "doi": "10.3389/fgene.2018.00019", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29426469", "author": "Montoya A", "n_authors": 12, "title": "Implications of zoonotic and vector-borne parasites to free-roaming cats in central Spain.", "abstract": "Cats are definitive hosts and reservoirs for several parasites, some of which are responsible for serious zoonotic diseases. We conducted a case-control study of data from a trap-neuter-return (TNR) programme (years 2014-2017) designed to examine the prevalence of zoonotic parasites in free-roaming cats living in urban areas of central Spain. In the animal population tested (n = 263), we detected a 29.2% prevalence of endoparasites, including high rates of cestodes (12.9%) and Toxocara cati (11.7%). While faecal samples showed no Toxoplasma gondii oocysts, the seroprevalence of T. gondii infection was 24.2%. Antibodies to Leishmania infantum were detected in 4.8% of the animals, though all skin and blood samples analyzed were PCR negative for this parasite. Ectoparasites (ticks and fleas) were found in 4.6% of the cat population, and 10.6% of the cats were detected with Otodectes cynotis. Finally, 6.3% and 7.9% cats tested positive for feline leukaemia virus and feline immunodeficiency virus, respectively. Our study provides useful information for animal-welfare and public-health, as the parasites detected can affect native wild animals through predation, competition and disease transmission. Our detection of zoonotic parasites such as L. infantum, T. gondii, T. cati, Giardia duodenalis and several ectoparasites prompts an urgent need for health control measures in stray cats.", "journal": "Veterinary parasitology", "doi": "10.1016/j.vetpar.2018.01.009", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29406082", "author": "Spada E", "n_authors": 4, "title": "Survival time and effect of selected predictor variables on survival in owned pet cats seropositive for feline immunodeficiency and leukemia virus attending a referral clinic in northern Italy.", "abstract": "Feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) are among the most important feline infectious diseases worldwide. This retrospective study investigated survival times and effects of selected predictor factors on survival time in a population of owned pet cats in Northern Italy testing positive for the presence of FIV antibodies and FeLV antigen. One hundred and three retrovirus-seropositive cats, 53 FIV-seropositive cats, 40 FeLV-seropositive cats, and 10 FIV+FeLV-seropositive cats were included in the study. A population of 103 retrovirus-seronegative age and sex-matched cats was selected. Survival time was calculated and compared between retrovirus-seronegative, FIV, FeLV and FIV+FeLV-seropositive cats using Kaplan-Meier survival analysis. Cox proportional-hazards regression analysis was used to study the effect of selected predictor factors (male gender, peripheral blood cytopenia as reduced red blood cells - RBC- count, leukopenia, neutropenia and lymphopenia, hypercreatininemia and reduced albumin to globulin ratio) on survival time in retrovirus-seropositive populations. Median survival times for seronegative cats, FIV, FeLV and FIV+FeLV-seropositive cats were 3960, 2040, 714 and 77days, respectively. Compared to retrovirus-seronegative cats median survival time was significantly lower (P<0.000) in FeLV and FIV+FeLV-seropositive cats. Median survival time in FeLV and FIV+FeLV-seropositive cats was also significant lower (P<0.000) when compared to FIV-seropositive cats. Hazard ratio of death in FeLV and FIV+FeLV-seropositive cats being respectively 3.4 and 7.4 times higher, in comparison to seronegative cats and 2.3 and 4.8 times higher in FeLV and FIV+FeLV-seropositive cats as compared to FIV-seropositive cats. A Cox proportional-hazards regression analysis showed that FIV and FeLV-seropositive cats with reduced RBC counts at time of diagnosis of seropositivity had significantly shorter survival times when compared to FIV and FeLV-seropositive cats with normal RBC counts at diagnosis. In summary, FIV-seropositive status did not significantly affect longevity of cats in this study, unlike FeLV and FIV+FeLV-seropositivity. Reduced RBC counts at time of FIV and FeLV diagnosis could impact negatively on the longevity of seropositive cats and therefore blood counts should always be evaluated at diagnosis and follow-up of retrovirus-seropositive cats.", "journal": "Preventive veterinary medicine", "doi": "10.1016/j.prevetmed.2017.12.001", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29386166", "author": "Hofmann-Lehmann R", "n_authors": 10, "title": "[Feline leukemia virus infection: importance and current situation in Switzerland].", "abstract": "Feline leukemia virus (FeLV) leads to fatal disease in cats with progressive infection. The aim of this study was to determine the importance of FeLV infection in Switzerland and make a comparison with previous studies. Of 881 blood samples taken from cats living in Switzerland (minimum of 20 samples per Canton), 47 samples were provirus-positive (5.3%; 95% confidence interval (CI) 3.9-7.0%) and 18 samples were antigen-positive (2%; 95% CI 1.2-3.2%). Together with data previously collected in similar studies, these findings demonstrated a decrease in prevalence between 1997 and 2003 followed by a relative constant low prevalence thereafter. Young cats (=2 years) were more frequently infected than older cats, but FeLV-positive cats were up to 15 (antigen-positive) and 19 (provirus-positive) years old. Sexually intact cats were more frequently viremic than neutered cats; purebred cats were somewhat less frequently FeLV-positive than non-purebred cats. In a second study, in which 300 saliva samples were analyzed, samples from 5 cats were FeLV-RNA positive (1.7%; 95% CI, 0.5-3.8%), although one young feral cat had been falsely assumed to be FeLV-negative based on a point-of-care test. Of the 300 cats, only 50% were FeLV tested or vaccinated, although 90% of the cats were at risk of exposure to FeLV. Testing and vaccination of all cats with exposure risk may help further decrease the prevalence of FeLV infection. Moreover, characteristics of FeLV tests should be considered, such as the risk of false negative results in the early phase of infection when performing antigen testing.", "journal": "Schweizer Archiv fur Tierheilkunde", "doi": "10.17236/sat00146", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29355998", "author": "Ellis J", "n_authors": 4, "title": "Prevalence and disease associations in feline thrombocytopenia: a retrospective study of 194 cases.", "abstract": "To assess the prevalence of thrombocytopenia in a referral population of cats in the UK, to identify disease processes associated with thrombocytopenia and to assess the proportion of thrombocytopenic cats that tested positive for feline leukaemia virus or feline immunodeficiency virus. Retrospective analysis of medical records at a UK referral hospital. Cats were grouped by mechanism of thrombocytopenia and disease process (where known). Prevalence of thrombocytopenia was 5·9%. The most common disease processes associated with thrombocytopenia were haematological or infectious disease and neoplasia; 11% of thrombocytopenic cats tested were positive for feline leukaemia virus, which is lower than reported previously. Cats presenting with unexplained haemorrhage had significantly lower platelet counts than other thrombocytopenic cats. Primary immune-mediated thrombocytopenia was less commonly diagnosed than in dogs and associated with the most severe platelet depletion in this study. Thrombocytopenia in cats may be more prevalent than previously reported and severe thrombocytopenia may be associated with spontaneous haemorrhage. Severe thrombocytopenia in cats appears less commonly immune-mediated than in dogs. Thrombocytopenia did not appear to be associated with retroviral infections.", "journal": "The Journal of small animal practice", "doi": "10.1111/jsap.12814", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29353423", "author": "Sumi R", "n_authors": 6, "title": "Polymerase chain reaction-based detection of myc transduction in feline leukemia virus-infected cats.", "abstract": "Feline lymphomas are associated with the transduction and activation of cellular proto-oncogenes, such as c-myc, by feline leukemia virus (FeLV). We describe a polymerase chain reaction assay for detection of myc transduction usable in clinical diagnosis. The assay targets c-myc exons 2 and 3, which together result in a FeLV-specific fusion gene following c-myc transduction. When this assay was conducted on FeLV-infected feline tissues submitted for clinical diagnosis of tumors, myc transduction was detected in 14% of T-cell lymphoma/leukemias. This newly established system could become a useful diagnostic tool in veterinary medicine.", "journal": "Archives of virology", "doi": "10.1007/s00705-018-3721-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29320424", "author": "Chiu ES", "n_authors": 3, "title": "A Retrospective Examination of Feline Leukemia Subgroup Characterization: Viral Interference Assays to Deep Sequencing.", "abstract": "Feline leukemia virus (FeLV) was the first feline retrovirus discovered, and is associated with multiple fatal disease syndromes in cats, including lymphoma. The original research conducted on FeLV employed classical virological techniques. As methods have evolved to allow FeLV genetic characterization, investigators have continued to unravel the molecular pathology associated with this fascinating agent. In this review, we discuss how FeLV classification, transmission, and disease-inducing potential have been defined sequentially by viral interference assays, Sanger sequencing, PCR, and next-generation sequencing. In particular, we highlight the influences of endogenous FeLV and host genetics that represent FeLV research opportunities on the near horizon.", "journal": "Viruses", "doi": "10.3390/v10010029", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29318027", "author": "Krecic MR", "n_authors": 5, "title": "Diagnostic performances of two rapid tests for detection of feline leukemia virus antigen in sera of experimentally feline leukemia virus-infected cats.", "abstract": "The objective of this study was to compare the diagnostic sensitivities and specificities of WITNESS FeLV-FIV (Zoetis) and SNAP FIV/FeLV Combo Test (IDEXX) for the detection of FeLV p27 antigen in the sera of experimentally feline leukemia virus (FeLV)-infected cats. Diagnostic sensitivities of WITNESS and SNAP were determined through testing of 47 serum samples collected from cats day 56 post-experimental infection with a virulent FeLV Rickard strain. Successful experimental infection was confirmed based on observation of FeLV antigen and proviral DNA in anti-coagulated (EDTA) whole-blood samples by immunofluorescent antibody (IFA) test and PCR, respectively. Diagnostic specificities of both tests were determined through testing of sera of 92 laboratory-housed, non-FeLV-exposed specific pathogen-free (SPF) cats. Forty-one of 47 blood samples were IFA positive, whereas all 47 samples were PCR positive. All 92 non-FeLV-infected SPF cats were IFA and PCR negative. In comparison to IFA as the reference method, both WITNESS and SNAP tests yielded equivalent sensitivities and specificities of 100% and 97.8%, respectively. In comparison to PCR as the reference method, both WITNESS and SNAP tests likewise performed equivalently, with sensitivities and specificities of 91.5% and 100%, respectively. Sensitivity and specificity of WITNESS FeLV-FIV for identifying FeLV p27 antigen in the sera of these experimentally FeLV-infected and non-FeLV-exposed SPF cats equaled those of the SNAP FIV/FeLV Combo Test. However, all positive results, regardless of the point-of-care test used, should be confirmed before making clinical decisions such as segregation from other cats or euthanasia.", "journal": "JFMS open reports", "doi": "10.1177/2055116917748117", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29192808", "author": "Yusuf IH", "n_authors": 4, "title": "A splice-site variant in FLVCR1 produces retinitis pigmentosa without posterior column ataxia.", "abstract": "FLVCR1 (feline leukemia virus subgroup c receptor 1) is a transmembrane protein involved in the trafficking of intracellular heme. Homozygous variants in FLVCR1 have been described in association with a clinical syndrome of posterior column ataxia with retinitis pigmentosa (PCARP). Here, we describe a patient with non-syndromic retinitis pigmentosa homozygous for a splice-site variant in FLVCR1 (c.1092 + 5G>A) without evidence of posterior column ataxia or cerebellar degeneration. We suggest an association between intronic splice-site variants in FLVCR1 and the absence of posterior column degeneration and suggest a hypothesis to explain this observation. Should this association be proven, it would provide valuable prognostic information for patients. Retinal degeneration appears to be the sole clinical manifestation of this FLVCR1 variant; gene therapy approaches using an adeno-associated viral vector with sub-retinal delivery may therefore represent a therapeutic approach to halting retinal degeneration in this patient group.", "journal": "Ophthalmic genetics", "doi": "10.1080/13816810.2017.1408848", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29134339", "author": "Martins NDS", "n_authors": 9, "title": "Feline immudeficiency virus subtypes B and A in cats from São Luis, Maranhão, Brazil.", "abstract": "Feline immunodeficiency virus (FIV) is a retrovirus of the genus Lentivirus that is distributed worldwide, with prevalence rates varying between 2.5% and 44%. FIV causes immunosuppression, with depletion of TCD4", "journal": "Archives of virology", "doi": "10.1007/s00705-017-3636-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "28840782", "author": "Marenzoni ML", "n_authors": 7, "title": "Comparison of three blood transfusion guidelines applied to 31 feline donors to minimise the risk of transfusion-transmissible infections.", "abstract": "Objectives The increased demand for animal blood transfusions creates the need for an adequate number of donors. At the same time, a high level of blood safety must be guaranteed and different guidelines (GLs) deal with this topic. The aim of this study was to evaluate the appropriateness of different GLs in preventing transfusion-transmissible infections (TTI) in Italian feline blood donors. Methods Blood samples were collected from 31 cats enrolled as blood donors by the owners' voluntary choice over a period of approximately 1 year. Possible risk factors for TTI were recorded. Based on Italian, European and American GLs, specific TTI, including haemoplasmas, feline leukaemia virus (FeLV), feline immunodeficiency virus (FIV), Anaplasma phagocytophilum, Ehrlichia species, Bartonella species, Babesia species, Theileria species, Cytauxzoon species, Leishmania donovani sensu lato and feline coronavirus (FCoV), were screened. Rapid antigen and serological tests and biomolecular investigations (PCR) were used. Several PCR protocols for haemoplasma and FeLV DNA were compared. Results The presence of at least one recognised risk factor for TTI was reported in all cats. Results for FIV and FeLV infections were negative using rapid tests, whereas five (16.1%) cats were positive for FCoV antibodies. Four (12.9%) cats were PCR positive for haemoplasma DNA and one (3.2%) for FeLV provirus, the latter being positive only using the most sensitive PCR protocol applied. Other TTI were not detected using PCR. Conclusions and relevance Blood safety increases by combining the recommendations of different GLs. To reduce the risk of TTI, sensitive tests are needed and the choice of the best protocol is a critical step in improving blood safety. The cost and time of the screening procedures may be reduced if appropriate tests are selected. To this end, the GLs should include appropriate recruitment protocols and questionnaire-based risk profiles to identify suitable donors.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X17727233", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "28660738", "author": "Lieser J", "n_authors": 2, "title": "Pseudolymphoma in a cat on phenobarbital treatment.", "abstract": "A two-year-old female spayed domestic shorthair cat was presented with apathy, inappetence and generalised lymphadenomegaly. Anamnestic data included a generalised seizure disorder and phenobarbital treatment started one month before presentation. Routine blood analysis revealed only mild abnormalities and FeLV and FIV tests were negative. Both popliteal lymph nodes were aspirated and cytology was consistent with reactive lymph node hyperplasia. PCR for antigen receptor rearrangement testing diagnosed a polyclonal cell population. In the absence of another cause, lymphadenomegaly was attributed to an adverse drug reaction and phenobarbital was discontinued. The cat's condition improved and lymph node size normalised over the next 10 days. The retrospective diagnosis was phenobarbital-induced pseudolymphoma.", "journal": "The Journal of small animal practice", "doi": "10.1111/jsap.12693", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "28589743", "author": "Wilkes RP", "n_authors": 9, "title": "Rapid and sensitive insulated isothermal PCR for point-of-need feline leukaemia virus detection.", "abstract": "Objectives Feline leukaemia virus (FeLV), a gamma retrovirus, causes diseases of the feline haematopoietic system that are invariably fatal. Rapid and accurate testing at the point-of-need (PON) supports prevention of virus spread and management of clinical disease. This study evaluated the performance of an insulated isothermal PCR (iiPCR) that detects proviral DNA, and a reverse transcription (RT)-iiPCR that detects both viral RNA and proviral DNA, for FeLV detection at the PON. Methods Mycoplasma haemofelis, feline coronavirus, feline herpesvirus, feline calicivirus and feline immunodeficiency virus were used to test analytical specificity. In vitro transcribed RNA, artificial plasmid, FeLV strain American Type Culture Collection VR-719 and a clinical FeLV isolate were used in the analytical sensitivity assays. A retrospective study including 116 clinical plasma and serum samples that had been tested with virus isolation, real-time PCR and ELISA, and a prospective study including 150 clinical plasma and serum samples were implemented to evaluate the clinical performances of the iiPCR-based methods for FeLV detection. Results Ninety-five percent assay limit of detection was calculated to be 16 RNA and five DNA copies for the RT-iiPCR, and six DNA copies for the iiPCR. Both reactions had analytical sensitivity comparable to a reference real-time PCR (qPCR) and did not detect five non-target feline pathogens. The clinical performance of the RT-iiPCR and iiPCR had 98.82% agreement (kappa[κ] = 0.97) and 100% agreement (κ = 1.0), respectively, with the qPCR (n = 85). The agreement between an automatic nucleic extraction/RT-iiPCR system and virus isolation to detect FeLV in plasma or serum was 95.69% (κ = 0.95) and 98.67% (κ = 0.85) in a retrospective (n = 116) and a prospective (n = 150) study, respectively. Conclusions and relevance These results suggested that both RT-iiPCR and iiPCR assays can serve as reliable tools for PON FeLV detection.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X17712847", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "28375041", "author": "Bollez A", "n_authors": 4, "title": "Prevalence of external ear disorders in Belgian stray cats.", "abstract": "Objectives Feline otitis externa is a multifactorial dermatological disorder about which very little is known. The objective of this study was to map the prevalence of external ear canal disorders and the pathogens causing otitis externa in stray cats roaming around the region of Ghent, Belgium. Methods One hundred and thirty stray cats were randomly selected during a local trap-neuter-return programme. All cats were European Shorthairs. This study included clinical, otoscopic and cytological evaluation of both external ears of each cat. Prospective data used as parameters in this study included the sex, age and body condition score of each cat, as well as the presence of nasal and/or ocular discharge, and the results of feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV) Snap tests. Results Remarkably, very few (sub)clinical problems of the external ear canal were found in the stray cat population. Malassezia species was by far the most common organism found in the external ear canals of the 130 stray cats. A total of 96/130 (74%) cats were found to have Malassezia species organisms present in one or both ears based on the cytological examination. No correlation was found between the parameters of sex, age, body condition score, the presence of nasal and/or ocular discharge and FIV and FeLV status, and the presence of parasites, bacteria or yeasts. Conclusions and relevance This study provides more information about the normal state of the external ear canal of stray cats. The ears of most stray cats are relatively healthy. The presence of Malassezia species organisms in the external ear canal is not rare among stray cats.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X17700808", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31998618", "author": "Pardo AP", "n_authors": 3, "title": "Cerebellar cortical degeneration associated with feline leukemia virus infection and cerebellar lymphoma in a young cat.", "abstract": "Cerebellar cortical degeneration (CCD) is the premature death of cerebellar neurons of heterogeneous etiology that is uncommonly observed as a neurological complication of certain neoplasia. Here, we report an 8-month-old male domestic cat with altered consciousness, symmetric ataxia, hypermetric gait, vertical positional nystagmus, mydriasis, strabismus, intention tremor of the head, and increased patellar reflexes. Neuroanatomical diagnosis suggested a multifocal brain dysfunction (cerebellar and cerebral). The cat tested seropositive for feline leukemia virus. Cerebrospinal fluid analysis indicated mononuclear and neutrophilic pleocytosis. Contrast computed tomography imaging revealed multiple hypodense heterogeneous areas in both cerebral hemispheres, mild ventriculomegaly at the level of the caudal fossa, and a circular sharply marginated, homogeneously hyperdense mass occupying the right cerebellar hemisphere. Postmortem study indicated a 1.1 × 1.3 × 1.2 cm mass in the right cerebellar hemisphere close to the vermis. Histopathological analysis showed diffuse and severe Purkinje cell loss with a decrease in granular cell density and moderate gliosis compatible with CCD. Further, numerous neoplastic lymphoid cells were observed in the infiltrated mass, consistent with a diagnosis of central nervous system (CNS) lymphoma. Immunohistochemistry showed CD20 expression, indicative of a B-cell immunophenotype. In humans, CCD is reported as a rare paraneoplastic syndrome in patients with Hodgkin lymphoma. CNS lymphoma and/or Feline Leukemia Virus (FeLV) infection were both considered as a possible cause of CCD in this case. This is the first described case of possible paraneoplastic cerebellar cortical degeneration associated with CNS lymphoma and/or FeLV infection in a domestic cat.", "journal": "Open veterinary journal", "doi": "10.4314/ovj.v9i3.9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31884612", "author": "Dockery A", "n_authors": 7, "title": "A Novel FLVCR1 Variant Implicated in Retinitis Pigmentosa.", "abstract": "Here we describe the identification and evaluation of a rare novel autosomal recessive mutation in FLVCR1 which is implicated solely in RP, with no evidence of posterior column ataxia in a number of affected patients. The mutation was detected as part of an ongoing target capture NGS study (Target 5000), aimed at identifying candidate variants in pedigrees with inherited retinal degenerations (IRDs) in Ireland. The mutation, FLVCR1 p.Tyr341Cys, was observed homozygously in seven affected patients across four pedigrees. FLVCR1 p.Tyr341Cys is a very rare mutation, with no previous reports of pathogenicity and no homozygous cases reported in online allele frequency databases. Our sequencing study identified seven homozygotes across multiple pedigrees, all with similar clinical presentations of RP without ataxia, a scenario extremely unlikely to occur by chance for a benign allele, particularly given the low population frequency of p.Tyr341Cys.", "journal": "Advances in experimental medicine and biology", "doi": "10.1007/978-3-030-27378-1_33", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31856815", "author": "Abdollahi-Pirbazari M", "n_authors": 4, "title": "Comparative measurement of FeLV load in hemolymphatic tissues of cats with hematologic cytopenias.", "abstract": "Feline leukemia virus (FeLV) is a serious viral infection in cats. FeLV is found in some tissues, such as spleen, lymph nodes and epithelial tissues. However, there is controversy about the organ in which the virus can be reliably detected in infected cats. The purpose of this study was to determine the level of viral infection in hemolymphatic tissues, including blood, bone marrow and spleen by reverse-transcriptase quantitative polymerase chain reaction (RT-qPCR). A total of 31 cats with clinical signs of FeLV infection associated with at least a single lineage hematologic cytopenia were included in this study. Peripheral blood, bone marrow and spleen samples were obtained from each cat. Complete blood counts, biochemical tests, and a rapid test to detect FeLV p27 antigen in blood samples of cats were performed. Of 31 cats, 9 had anemia alone, 4 had thrombocytopenia alone, 2 had neutropenia alone, 9 had bicytopenia of anemia and thrombocytopenia, 3 had bicytopenia of anemia and neutropenia, and 4 had pancytopenia. FeLV RNA was then detected by RT-qPCR in the whole blood, bone marrow and spleen. Viral RNA copy numbers were detected in all cats by RT-qPCR whereas 24 out of 31 cats were positive for the serum FeLV antigen. We detected a significantly greater number of viral RNA in the spleen compared with the whole blood and bone marrow. Spleen is a site where FeLV is most frequently detected in cats with hematologic cytopenias.", "journal": "BMC veterinary research", "doi": "10.1186/s12917-019-2208-y", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31839979", "author": "Szilasi A", "n_authors": 8, "title": "Prevalence of feline immunodeficiency virus and feline leukaemia virus in domestic cats in Hungary.", "abstract": "Feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV) are retroviruses affecting cats worldwide. The objectives of the study were to estimate the prevalence of these retroviruses in domestic cats in Hungary and to characterise the phylogenetic relationships of FIV strains. A total of 335 anticoagulated whole-blood samples obtained from both a healthy and ill cat population were examined for the presence of FIV and FeLV with two methods: ELISA and PCR. Statistical analysis was carried out to analyse the data obtained. Sequencing and phylogenetic analysis of partial polymerase ( Statistical analysis showed 11.8% and 9.9% true prevalence of FeLV and FIV, respectively, with ELISA. The apparent prevalence calculated from the PCR results were 17.3% for FeLV and 13.1% for FIV. Phylogenetic analysis of partial  We report the first thorough overview of the prevalence of FeLV and FIV in Hungary, which is relatively high, and give insight into the genetic diversity of Hungarian strains of FIV.", "journal": "JFMS open reports", "doi": "10.1177/2055116919892094", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31837752", "author": "Pereira A", "n_authors": 7, "title": "An Unusual Case of Feline Leishmaniosis With Involvement of the Mammary Glands.", "abstract": "We report an unusual case of leishmaniosis with the involvement of mammary glands in an old cat with what seems to be a concurrent regressive feline leukemia virus infection. Leishmania donovani complex parasites were identified for the first time in inflammatory breast fluid during a clinical recurrence manifested about 4 years after the first diagnosis of feline leishmaniosis. Combined treatment with allopurinol and meglumine antimoniate resulted in clinical cure of mammary lesion and a concurrent uveitis.", "journal": "Topics in companion animal medicine", "doi": "10.1016/j.tcam.2019.100356", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31691733", "author": "Bezerra JAB", "n_authors": 11, "title": "Serological and molecular investigation of Leishmania spp. infection in cats from an area endemic for canine and human leishmaniasis in Northeast Brazil.", "abstract": "The aim of this study was to investigate the occurrence of Leishmania spp. antibodies, and its association with feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV), in domestic cats from an area endemic for canine and human leishmaniasis in Rio Grande do Norte State, Brazil. Ninety-one cats were subjected to a complete clinical exam, and blood samples were collected. An epidemiological questionnaire was used to investigate the risk factors. IgG anti-Leishmania spp. antibodies were detected by immunofluorescence antibody test (IFAT), with a cut-off value of 1:40. Polymerase chain reaction (PCR) was performed to detect genetic material of Leishmania spp. in the blood samples. The presence of antibodies against FIV and antigens of FeLV was evaluated using an immunochromatographic test. Seropositivity for Leishmania spp., FIV, and FeLV was observed in 14/91 (15.38%), 26/91 (28.57%), and 3/91 (3.29%) cats, respectively. All samples gave negative results on PCR analysis. Based on these data, no significant statistical association was observed between seropositivity for Leishmania spp., and sex, age, presence of clinical signs, evaluated risk factors, and positivity for retroviruses. These findings demonstrated for the first time that cats from Mossoró, Rio Grande do Norte, are being exposed to this zoonosis and might be part of the epidemiological chain of transmission of visceral leishmaniasis.", "journal": "Revista brasileira de parasitologia veterinaria = Brazilian journal of veterinary parasitology : Orgao Oficial do Colegio Brasileiro de Parasitologia Veterinaria", "doi": "10.1590/S1984-29612019082", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31671816", "author": "Studer N", "n_authors": 39, "title": "Pan-European Study on the Prevalence of the Feline Leukaemia Virus Infection - Reported by the European Advisory Board on Cat Diseases (ABCD Europe).", "abstract": "Feline leukaemia virus (FeLV) is a retrovirus associated with fatal disease in progressively infected cats. While testing/removal and vaccination led to a decreased prevalence of FeLV, recently, this decrease has reportedly stagnated in some countries. This study aimed to prospectively determine the prevalence of FeLV viraemia in cats taken to veterinary facilities in 32 European countries. FeLV viral RNA was semiquantitatively detected in saliva, using RT-qPCR as a measure of viraemia. Risk and protective factors were assessed using an online questionnaire to report geographic, demographic, husbandry, FeLV vaccination, and clinical data. The overall prevalence of FeLV viraemia in cats visiting a veterinary facility, of which 10.4% were shelter and rescue cats, was 2.3% (141/6005; 95% CI: 2.0%-2.8%) with the highest prevalences in Portugal, Hungary, and Italy/Malta (5.7%-8.8%). Using multivariate analysis, seven risk factors (Southern Europe, male intact, 1-6 years of age, indoor and outdoor or outdoor-only living, living in a group of ≥5 cats, illness), and three protective factors (Northern Europe, Western Europe, pedigree cats) were identified. Using classification and regression tree (CART) analysis, the origin of cats in Europe, pedigree, and access to outdoors were important predictors of FeLV status. FeLV-infected sick cats shed more viral RNA than FeLV-infected healthy cats, and they suffered more frequently from anaemia, anorexia, and gingivitis/stomatitis than uninfected sick cats. Most cats had never been FeLV-vaccinated; vaccination rates were indirectly associated with the gross domestic product (GDP) per capita. In conclusion, we identified countries where FeLV was undetectable, demonstrating that the infection can be eradicated and highlighting those regions where awareness and prevention should be increased.", "journal": "Viruses", "doi": "10.3390/v11110993", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31611482", "author": "Sacristán I", "n_authors": 13, "title": "Molecular and serological survey of carnivore pathogens in free-roaming domestic cats of rural communities in southern Chile.", "abstract": "Owned, free-roaming domestic cats are abundant in the Chilean countryside, having high probability of contact with wildlife and potentially participating as reservoirs of zoonotic pathogens. In the present study, 131 cats from two remote study areas (Valdivia and Chiloe Island) in southern Chile were analyzed for infection/exposure to eight pathogens. Serum samples from 112 cats were tested for antigens against feline leukemia virus (FeLV antigen-ELISA) and antibodies against feline immunodeficiency virus (FIV-ELISA) and canine distemper virus (CDV-serum neutralization), yielded occurrence of 8.9, 1.7 and 0.8% respectively. The presence of DNA of five vector-borne pathogens, piroplasmids, Ehrlichia spp., Anaplasma spp., Rickettsia spp. and Bartonella spp. was investigated in thirty cats. Overall observed occurrence was 6.6% (2/30) for both Anaplasma platys, and B. henselae, and 3.3% (1/30) for both Bartonella sp. and Theileria equi. Observed occurrence for all vector-borne pathogens in Valdivia area was significantly higher than in Chiloe Island (5/15 vs 0/15; P=0.04). Our results represent the first description of exposure to CDV and DNA detection of T. equi and A. platys in domestic cats in Chile. The results highlight the importance of performing pathogen screening in owned, free-roaming rural cats to evaluate their potential role as reservoirs of infection and vectors for disease transmission to wildlife.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.19-0208", "deposited_data": "Sim", "nuccore_ids": "1615700820, 1615700819, 1615700818, 1610102890", "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31585524", "author": "Henrich M", "n_authors": 4, "title": "Lack of Bcl-2 expression in feline follicular lymphomas.", "abstract": "Bcl-2, an anti-apoptotic protein, is commonly overexpressed in follicular lymphomas in humans. This is usually the result of a chromosomal translocation that transposes the ", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/1040638719877916", "deposited_data": "Sim", "nuccore_ids": "57163882, 2131037092, 2131037091, 57163882", "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31562905", "author": "Koç BT", "n_authors": 2, "title": "First report on the prevalence and genetic relatedness of Feline Foamy Virus (FFV) from Turkish domestic cats.", "abstract": "Feline Foamy Virus (FFV) is an important retroviral agent affecting domestic cats in Turkey that has been studied less intensively than Feline Immunodeficiency Virus (FIV) and Feline Leukemia Virus (FeLV). Accordingly, we aimed to investigate the presence and prevalence of FFV among domestic cats by molecular techniques. PCR was used to amplify the gag-pol gene overlap in order to detect the presence of FFV. The gene encoding bet, an important accessory gene, was also characterized. Molecular characteristics were analyzed and phylogenetic trees were constructed. We determined the positivity rate as 10% in all samples (20/200) based on the gag-pol test. The phylogenetic analysis indicated that the Turkish FFV sequences form a separate cluster among other isolates in the constructed maximum likelihood (ML) tree. bet-based products were obtained for two samples (1%; 2/200) that were also positive for gag-pol. These bet gene sequences confirm the presence of a separate cluster for the Turkish FFV isolates. The results suggest that FFV is prevalent and widespread in Turkish domestic cats. Additionally, these new FFV sequences represent the first FFV sequences from Turkey to be submitted to GenBank. This study paves the way for studies on the pathogenicity of FFV.", "journal": "Virus research", "doi": "10.1016/j.virusres.2019.197768", "deposited_data": "Sim", "nuccore_ids": "1689866581, 1689866578, 1569741650, 1569741649, 1569741648, 1569741647, 1569741646, 1569741645, 1569741644, 1569741643, 1569741642, 1569741641, 1569741640, 1569741639, 1569741638, 1569741637, 1569741636, 1569741635, 1569741634, 1569741633, 1569741632, 1569741631", "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31551410", "author": "Zhao P", "n_authors": 6, "title": "Cystathionine β-synthase (CBS) deficiency suppresses erythropoiesis by disrupting expression of heme biosynthetic enzymes and transporter.", "abstract": "The reduced iron usage induced by the suppression of erythropoiesis is a major cause of the systemic iron overload in CBS knockout (CBS", "journal": "Cell death & disease", "doi": "10.1038/s41419-019-1951-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31534776", "author": "Tchamo CC", "n_authors": 3, "title": "Occurrence of feline immunodeficiency virus and feline leukaemia virus in Maputo city and province, Mozambique: a pilot study.", "abstract": "Feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV) are immunosuppressive viruses in cats that increase their susceptibility to zoonotic pathogens. This study aimed to determine the occurrence of one or both viruses, the risk factors associated with infection, and to develop further recommendations. This was a cross-sectional study conducted at the Veterinary Faculty of Eduardo Mondlane University, Mozambique, between March and December 2017, in 145 cats. From each of 145 cats, we took 1.5 ml of blood by jugular puncture for detection of antibodies to FIV and FeLV antigens in whole blood using a commercial test kit, DFV Test FeLV/FIV. We found an overall prevalence of 11.0% and 14.5% for FIV antibodies and FeLV antigens, respectively, with four (2.8%) cats coinfected by both pathogens. Male cats were more likely to be infected with FIV (odds ratio [OR] 1.1, 95% confidence interval [CI] 0.3-4.0) compared with female cats. Clinically ill cats were more likely to have a positive result for FeLV antigen infection (OR 18.8, 95% CI 5.2-68.3). Moreover, cats living in suburban areas have a greater chance of a positive result for FeLV infection (OR 3.7, 95% CI 1.4-9.6) compared with cats living in urban areas. FIV and FeLV occur in cats from Maputo and possibly all over the country. Further studies should be conducted in Mozambique and other African countries to define the burden of both pathogens in cats, coinfection with other zoonotic pathogens and the possible role played by the cats on the transmission of zoonotic and opportunistic diseases to humans.", "journal": "JFMS open reports", "doi": "10.1177/2055116919870877", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31534037", "author": "Ngo MH", "n_authors": 9, "title": "Tracking the Fate of Endogenous Retrovirus Segregation in Wild and Domestic Cats.", "abstract": "Endogenous retroviruses (ERVs) of domestic cats (ERV-DCs) are one of the youngest feline ERV groups in domestic cats (", "journal": "Journal of virology", "doi": "10.1128/JVI.01324-19", "deposited_data": "Sim", "nuccore_ids": "1737725642, 1737725641, 1737725640, 1737725639, 1737725638, 1737725637, 1737725636, 1737725635, 1737725634, 1737725633, 1737725632, 1737725631", "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31527012", "author": "Beall MJ", "n_authors": 8, "title": "Evaluation of a quantitative enzyme-linked immunosorbent assay for feline leukemia virus p27 antigen and comparison to proviral DNA loads by real-time polymerase chain reaction.", "abstract": "Feline leukemia virus (FeLV) is an oncogenic retrovirus of cats. While higher viral RNA and proviral DNA loads have been correlated with progressive infections and disease, a similar correlation has been suggested for p27 antigen concentrations. This analytical study compared the results of a quantitative ELISA for p27 antigen with quantitative real-time PCR results for FeLV proviral DNA in patient samples. A significant positive correlation between copies of proviral DNA and the concentration of p27 antigen was identified (r = 0.761, P < 0.0001). Samples with high proviral DNA loads, at least 1 × 10", "journal": "Comparative immunology, microbiology and infectious diseases", "doi": "10.1016/j.cimid.2019.101348", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31514435", "author": "Gomez-Lucia E", "n_authors": 6, "title": "Follow-Up of Viral Parameters in FeLV- or FIV-Naturally Infected Cats Treated Orally with Low Doses of Human Interferon Alpha.", "abstract": "Specific treatments for the long-life infections by feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) are either toxic, expensive or not too effective. Interferon α (IFN-α) is an immunomodulatory molecule which has been shown in vitro to decrease the release of infective particles. The aim of this study was to follow the progress of the clinical score and viral parameters of FeLV- and FIV-naturally infected privately owned cats treated with recombinant human IFN-α (rHuIFN-α, Roferon-A). Twenty-seven FeLV-infected cats (FeLV+) and 31 FIV-infected cats (FIV+) were enrolled in the study. Owners were instructed to orally administer 1 mL/day of 60 IU rHuIFN-α/mL in alternating weeks for four months. Blood samples were taken at the beginning of the study (M0), mid-treatment (M2), end of treatment (M4), and 6-10 months later (M10). Clinical status at these time points improved notably with rHuIFN-α treatment, regardless of the initial severity of the disease, an effect which lasted throughout the study in most animals (15 of the 16 FeLV+ symptomatic cats; 20 of the 22 FIV+ symptomatic cats) improved markedly their clinical situation. In FeLV+ cats plasma antigenemia (p27CA), reverse transcriptase (RT) activity, and proviral load decreased at M2 and M4 but increased again at M10 (\"rebound effect\"). The level of antigenemia or RT activity was below the detection limits in FIV+ cats, and the effect on proviral load was less marked than in FeLV+ cats. Taken together, these results indicate that rHuIFN-α is a good candidate for treating FeLV+ cats, but the \"rebound effect\" seen when treatment was discontinued suggests that additional studies should be conducted to clarify its effect on progression of the infection in cats.", "journal": "Viruses", "doi": "10.3390/v11090845", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31429743", "author": "Rossi F", "n_authors": 8, "title": "Immune-complex glomerulonephritis in cats: a retrospective study based on clinico-pathological data, histopathology and ultrastructural features.", "abstract": "Chronic kidney disease (CKD) has typically a non-immune mediated origin in cats and immune-complex glomerulonephritis (ICGN) is scarcely described. Aims of this study were to characterize ICGN by light and electron microscopy and identify associations with clinico-pathological findings. In addition, comparisons between cats with ICGN and non immune-complex glomerulonephritis (non-ICGN) were performed. Renal samples examined between 2010 and 2019 were considered if both light and electron microscopy were performed. Signalment, feline immunodeficiency virus (FIV) and leukemia virus (FeLV) status, serum creatinine concentration, urine protein-to-creatinine (UPC) ratio, systolic blood pressure (SBP) and International Renal Interest Society (IRIS) stage were retrieved and used for comparisons. Sixty-eight client-owned cats were included. Thirty-seven cats (54.4%) had ICGN and 31 (45.6%) non-ICGN. Eighteen (48.6%) with ICGN had membranous glomerulonephropathy (MGN), 14 (37.8%) membranoproliferative glomerulonephritis (MPGN), and 5 (13.5%) mesangioproliferative glomerulonephritis (MeGN). Clinico-pathological data were not associated with any type of ICGN. Among cats with non-ICGN, 11 (35.5%) had end-stage CKD, 9 (29%) focal segmental glomerulosclerosis, 6 (19.4%) global and multifocal mesangiosclerosis, 2 (6.5%) glomerular atrophy, 2 (6.5%) renal dysplasia and 1 (3.1%) amyloidosis. Eight (25.8%) cats with non-ICGN had chronic interstitial nephritis (CIN) grade 1, 13 (41.9%) grade 2 and 10 (32.3%) grade 3; creatinine and UPC ratio increased with CIN grades (p = 0.001, p < 0.001). Cats with ICGN were more frequently FIV or FeLV-infected (OR:11.4; 95%CI:1.4-94.4; p = 0.024), had higher UPC ratio (OR:6.8; 95%CI:2.5-18.2; p < 0.001) and were younger (OR:0.9; 95%CI:0.7-1.0; p = 0.042) than cats with non-ICGN. MGN and MPGN were the most common morphological diagnoses of ICGN in cats. Unfortunately, none of the investigated findings differentiated ICGN morphological diagnoses. Serum creatinine concentration and UPC ratio were directly associated with grades of CIN (p = 0.001 and p < 0.001, respectively), confirming previous literature. More ICGN than non-ICGN was observed in cats with retroviral infections, younger cats and higher UPC ratio.", "journal": "BMC veterinary research", "doi": "10.1186/s12917-019-2046-y", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31408049", "author": "Bertino F", "n_authors": 13, "title": "Heme and sensory neuropathy: insights from novel mutations in the heme exporter feline leukemia virus subgroup C receptor 1.", "abstract": "Hereditary sensory and autonomic neuropathies (HSANs) are a group of clinically and genetically heterogeneous disorders of the peripheral nervous system mainly characterized by impaired nociception and autonomic dysfunction. We previously identified heme metabolism as a novel pathway contributing to sensory neurons maintenance and nociception. Indeed, we reported mutations in the feline leukemia virus subgroup C receptor 1 (FLVCR1) gene in individuals affected by HSAN. FLVCR1 gene encodes for 2 heme export proteins, FLVCR1a (plasma membrane) and FLVCR1b (mitochondria), crucially involved in the regulation of cellular heme homeostasis. Here, we report on 2 additional patients carrying novel biallelic mutations in FLVCR1 translation initiation codon (c.2T>C; p.(Met1Thr) and c.3G>T; p.(Met1Ile)). We overexpressed the c.2T>C; p.(Met1Thr) mutant in human cell lines and we describe its impact on protein structure and function in comparison with other HSAN-related mutations. We found that the mutation interferes with translation in 2 different ways: by lowering levels of translation of wild-type protein and by inducing translation initiation from a downstream in-frame ATG, leading to the production of an N-terminal truncated protein that is retained in the endoplasmic reticulum. The impact of different kinds of mutations on FLVCR1a localization and structure was also described. The identification of novel FLVCR1 mutations in HSAN reinforces the crucial role of heme in sensory neuron maintenance and pain perception. Moreover, our in vitro findings demonstrate that heme export is not completely lost in HSAN patients, thus suggesting the possibility to improve FLVCR1 expression/activity for therapeutic purposes.", "journal": "Pain", "doi": "10.1097/j.pain.0000000000001675", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31390829", "author": "Novacco M", "n_authors": 7, "title": "Prevalence, Geographic Distribution, Risk Factors and Co-Infections of Feline Gammaherpesvirus Infections in Domestic Cats in Switzerland.", "abstract": "Recently, a gammaherpesvirus was described in domestic cats (FcaGHV1). The goal of the present study was to investigate the presence of FcaGHV1 in Swiss domestic cats and analyze potential risk factors. Blood samples from 881 cats presented to veterinarians in all Swiss cantons and from 91 stray cats and neoplastic tissue samples from 17 cats with lymphoma were evaluated. FcaGHV1 was detected by real-time PCR targeting the glycoprotein B gene, followed by sequencing. Blood samples were also tested for feline hemoplasmas, feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV). The molecular prevalence of FcaGHV1 was 6.0% (95% confidence interval (CI), 4.5-7.8%) in cats presented to veterinarians and 5.5% (95% CI, 1.8-12.4%) in stray cats. FcaGHV1 PCR-positive cats originated from 19/26 Swiss cantons. Factors significantly associated with FcaGHV1 detection included male sex, age >3 years, nonpedigree status and co-infection with FIV and hemoplasmas. Moreover, FeLV viremia tended to be associated with FcaGHV1 detection. High FcaGHV1 blood loads were found more frequently in FeLV-viremic cats and less frequently in hemoplasma-infected cats than in uninfected cats. Clinical information was unavailable for most of the 881 cats, but leukemia, carcinoma and cardiomyopathy were reported in FcaGHV1-positive cats. None of the tissue samples from the 17 cats with lymphoma tested positive for FcaGHV1. Sequence analyses revealed homogeneity among the Swiss isolates and >99.7% identity to published FcaGHV1 sequences. In conclusion, FcaGHV1 is present in Switzerland with a similar prevalence in cats presented to veterinarians and in stray cats. The pathogenic potential of FcaGHV1 needs further evaluation.", "journal": "Viruses", "doi": "10.3390/v11080721", "deposited_data": "Sim", "nuccore_ids": "1752314476, 1752314474, 1752314472", "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31375152", "author": "Cristo TG", "n_authors": 10, "title": "Feline Leukaemia Virus Associated with Leukaemia in Cats in Santa Catarina, Brazil.", "abstract": "Leukaemia is a haemopoietic neoplasm originating from myeloid or lymphoid precursors in the bone marrow and may be either acute or chronic. These tumours are rare, but occur more frequently in cats because of an association with the feline leukaemia virus (FeLV) and feline immunodeficiency virus (FIV). To the best of our knowledge, no studies conducted in Brazil to date have analysed the association between leukaemia and FeLV and FIV infection in cats. The aim of this study was to perform a histopathological analysis of feline leukaemia and evaluate the association between leukaemia and FeLV and FIV infection in cats. The study evaluated 37 cats with leukaemia diagnosed between 2009 and 2017. The animals underwent necropsy examination, histopathology and immunohistochemistry with anti-FeLV gp70 and anti-FIV p24 gag antibodies. Of the evaluated animals, 54% (20/37) were males and 43.2% (16/37) were females. With respect to the life stage of the animals, 24.3% (9/37) were junior, 32.4% (12/37) were prime, 18.9% (7/37) were mature and 10.8% (4/37) were senior, and five animals were of unknown age. Myeloid leukaemia occurred in 56.8% (21/37) of the cases and lymphocytic leukaemia occurred in 43.2% (16/37) of the cases. Acute leukaemia (73%, 27/37) was more common than chronic leukaemia (27%, 10/37). The positivity for FeLV (78.4%, 29/37) and FIV (16.2%, 6/37) indicated a high association between FeLV infection and tumour development in the study region.", "journal": "Journal of comparative pathology", "doi": "10.1016/j.jcpa.2019.05.002", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31352725", "author": "Kim WJ", "n_authors": 6, "title": "Treatment of Adult Spinal Deformity with Sagittal Imbalance Using Oblique Lumbar Interbody Fusion: Can We Predict How Much Lordosis Correction Is Possible?", "abstract": "Prospective, single-center study. The current trend of operative treatment for adult spinal deformity (ASD) is combined anterior-posterior staged surgery. When anterior surgery was first performed, oblique lumbar interbody fusion (OLIF) was employed; this method became increasing popular. This study aimed to determine the lordosis correction that can be achieved using OLIF and assess whether we can preoperatively predict the lordosis correction angle achieved using OLIF. Many previous studies on OLIF have shown improved clinical and radiologic outcomes. With the increase in the popularity of OLIF, several surgeons have started using larger cages to attain greater lordosis correction. Moreover, some studies have reported complications of OLIF because of immoderate cage insertion. To our knowledge, this is the first prospective study that attempted to determine whether it is possible to predict the lordosis correction angle achieved with OLIF preoperatively, using fullextension lateral view (FELV). Forty-six patients with ASD were enrolled. All the operations were performed by a single surgeon in two stages (first, anterior and second, posterior) with a 1-week interval. Radiological evaluation was performed by comparing the Cobb's angle of the segmental and regional lordosis obtained using preoperative and postoperative simple radiography (including the FELV) and magnetic resonance imaging (MRI). Regional lordosis (L1-S1) in the whole-spine standing lateral radiograph was -3.03°; however, in the supine lateral MRI, it was 20.92°. The regional lordosis of whole-spine standing lateral and supine lateral (MRI) was significantly different. In the FELV, regional lordosis was 25.72° and that in the postoperative supine lateral (MRI) was 25.02°; these values were not significantly different. Although OLIF offers many advantages, it alone plays a limited role in ASD treatment. Lordosis correction using OLIF as well as lordosis determined in the FELV was possible. Hence, our results suggest that FELV can help predict the lordosis correction angle preoperatively and thus aid the selection of the appropriate technique in the second staged operation.", "journal": "Asian spine journal", "doi": "10.31616/asj.2018.0306", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31306417", "author": "Iatta R", "n_authors": 13, "title": "A nationwide survey of Leishmania infantum infection in cats and associated risk factors in Italy.", "abstract": "Though scantly investigated, Leishmania infantum infection and clinical cases of leishmaniasis in cats have been recently reported in several countries of the Mediterranean basin, with large variability in prevalence data. A major limitation in the comparability of the data available is attributed to the differences in diagnostic techniques employed and cat populations sampled. The aim of this study was to assess the prevalence of L. infantum infection in owned cats across Italy by serological and molecular tests and the identification of potential risk factors. Blood samples from 2,659 cats from northern (n = 1,543), central (n = 471) and southern (n = 645) Italy were tested for antibodies against L. infantum, by an immunofluorescence antibody test and for the parasites' DNA, by real-time PCR. Samples were additionally screened for feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) proviral DNAs. An overall cumulative L. infantum prevalence of 3.9% was recorded by serology (3.3%) and/or qPCR (0.8%), with a higher rate (10.5%) in southern Italy. The risk of L. infantum infection in cats was significantly associated to the geographical areas (South vs North and Centre; p<0.0001), age class (from 19 months to 6 years old vs ≤18 months old, p = 0.0003), neutering status (not neutered vs neutered, p = 0.0028) and FIV infection (p = 0.0051).Though the role of cats in the epidemiology of L. infantum is still debated, our findings indicate that cats are exposed to and/or infected by this protozoan, mainly in endemic regions of Italy. Hence, a standardization of procedures for a prompt diagnosis of L. infantum infection in cats and for screening cat population is crucial for a better understanding of the epidemiology of feline leishmaniasis, and of the potential role of cats in the transmission cycle of zoonotic visceral leishmaniasis.", "journal": "PLoS neglected tropical diseases", "doi": "10.1371/journal.pntd.0007594", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31230159", "author": "Cavalera MA", "n_authors": 9, "title": "Serological survey and risk factors of Aelurostrongylus abstrusus infection among owned cats in Italy.", "abstract": "Feline lungworms affect the respiratory tract of domestic cats causing respiratory conditions of various degrees. In this study, we investigated the exposure of cats to feline lungworm infections by detecting antibodies in a large population of animals from several regions of Italy. Sera of 1087 domestic cats living in regions of the north (n = 700), the centre (n = 227) and the south (n = 160) of Italy were examined by a newly developed indirect ELISA conceived for detection of antibodies against the most frequently occurring feline lungworm Aelurostrongylus abstrusus. Individual cat data (i.e., age, sex, neutering status and provenience) were analysed as potential risk factors for exposure to lungworm infections. Samples were additionally screened for feline leukaemia virus (FeLV) and feline immunodeficiency virus (FIV) proviral DNAs. Overall, 9% (98/1087; 95% confidence interval (CI) 7.4-10.9%) of the animals tested seropositive to lungworm antibodies. Positive cats were identified in the north (7.1%; CI 5.5-9.3%), in the centre (5.3%; CI 3.0-9.0%) and in the South (22.5%; CI 16.7-29.6%), with more seropositive animals in the latter area (p < 0.05). The risk of lungworm infection in cats was significantly associated with age less than 6 months (i.e. 24.4%, p < 0.05) and FIV infection (p < 0.05). This large-scale serological survey confirms the exposure of cats to lungworm infections in Italy and that serological tests can be used to assess the distribution of lungworm infections in large populations of animals.", "journal": "Parasitology research", "doi": "10.1007/s00436-019-06373-z", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31228586", "author": "Basso W", "n_authors": 5, "title": "First autochthonous case of clinical Hepatozoon felis infection in a domestic cat in Central Europe.", "abstract": "Three different Hepatozoon (Apicomplexa, Hepatozoidae) species have been described infecting domestic cats in Europe (i.e. H. felis, H. canis and H. silvestris), however, reports on clinical hepatozoonosis are uncommon and treatment protocols are not clearly defined. A six-year-old male European short-hair cat from Austria presented poor general condition, lethargy, anorexia, icterus, a painful abdomen, fever, ruffled hair and a tick infestation, and it had never left Austria. Laboratory tests revealed leukopenia, thrombocytopenia and increased serum levels of symmetric dimethylarginine (SDMA) and bilirubin. In May Grünwald-Giemsa-stained blood smears, structures resembling Hepatozoon gamonts were observed inside neutrophil granulocytes. A PCR targeting a fragment of the 18S rRNA gene of Hepatozoon spp. and DNA sequencing allowed the diagnosis of H. felis-DNA in blood samples. The cat was treated with imidocarb dipropionate (6 mg/kg body weight, repeated after 14 days) and doxycycline monohydrate (5 mg/kg body weight twice a day, p.o., for four weeks) and recovered completely. A broad haematological and biochemical laboratory control after six months showed all evaluated parameters under normal ranges. Coinfection with other feline pathogens (i.e. feline leukaemia virus, feline immunodeficiency virus, feline Coronavirus, Leishmania and Dirofilaria immitis) could not be detected. This study reveals the presence of H. felis in Austria and provides more evidence on the geographical distribution and pathogenicity of this parasite for domestic cats. To the authors' knowledge, this is the first autochthonous case of feline hepatozoonosis in Central Europe.", "journal": "Parasitology international", "doi": "10.1016/j.parint.2019.101945", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31176263", "author": "Ludwick K", "n_authors": 2, "title": "Comparative meta-analysis of feline leukemia virus and feline immunodeficiency virus seroprevalence correlated with GDP per capita around the globe.", "abstract": "Feline Leukemia Virus (FeLV) and Feline Immunodeficiency Virus (FIV) are two prevalent transmittable diseases for domestic cats. This paper reports the frequency of these two diseases compared globally across Gross Domestic Product (GDP) at purchasing power parity per capita (PPP). Information around FeLV and FIV rates of infection in specific locations around the world was analyzed from 47 published articles. Results show that based on the data available, the statistical model indicates that the highest percentage of FeLV or FIV infected cats live in areas of lower PPP (p ≤.001) with a decreasing rate of infection of FeLV and FIV with increasing income. Two theories for this could be that the lower PPP locations in this study were also in areas of greater feral cat and cat colony populations, as well as were areas with less emphasis on animal welfare and animal control programs. Additional research should be conducted to strengthen the study size in South America and Africa before further conclusions can be drawn.", "journal": "Research in veterinary science", "doi": "10.1016/j.rvsc.2019.05.013", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31159230", "author": "Westman M", "n_authors": 14, "title": "The Diagnosis of Feline Leukaemia Virus (FeLV) Infection in Owned and Group-Housed Rescue Cats in Australia.", "abstract": "A field study was undertaken to (i) measure the prevalence of feline leukaemia virus (FeLV) exposure and FeLV infection in a cross-section of healthy Australian pet cats; and (ii) investigate the outcomes following natural FeLV exposure in two Australian rescue facilities. Group 1 (", "journal": "Viruses", "doi": "10.3390/v11060503", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "30996094", "author": "Miyake A", "n_authors": 8, "title": "Reduced Folate Carrier: an Entry Receptor for a Novel Feline Leukemia Virus Variant.", "abstract": "Feline leukemia virus (FeLV) is horizontally transmitted among cats and causes a variety of hematopoietic disorders. Five subgroups of FeLV, A to D and T, each with distinct receptor usages, have been described. Recently, we identified a new FeLV Env (TG35-2) gene from a pseudotyped virus that does not belong to any known subgroup. FeLV-A is the primary virus from which other subgroups have emerged via mutation or recombination of the subgroup A ", "journal": "Journal of virology", "doi": "10.1128/JVI.00269-19", "deposited_data": "Sim", "nuccore_ids": "2462583176, 2462583174, 2462583172, 2462583170, 2462583168, 2462583166, 2462583164, 2462583162, 2462583160, 2462583158, 2462583156, 2462583154, 2462583152, 2462583150, 2462583148, 2462583146, 2462583144, 2462583142, 2462583140, 2462499610, 2462499608, 2462499606, 2462499604, 2462499602, 2462499600, 2462499598, 2462499596, 2462499594, 2462499592, 2462499590, 2462499588, 2462499586, 2462499584, 2462499582, 2462499580, 2462499578, 2462499576, 2462499574, 2217338142, 2217338140, 2217338138, 2217338136, 2217338135, 2217338133, 2217338131, 2217338129, 2217338128, 2217338126, 2217338125, 2217338124, 2217338122, 2217338120, 2217338118, 2217338116, 2217338115, 2217338113, 2217338112, 1890343338, 1890268074, 1676319583, 1675172771, 1675133521, 1519243035, 34823294", "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "30961813", "author": "Biezus G", "n_authors": 10, "title": "Prevalence of and factors associated with feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) in cats of the state of Santa Catarina, Brazil.", "abstract": "A cross-sectional study was conducted in 274 cats for determination of FeLV antigenemia and FIV seropositivity and factors associated with those infections in cats presented at the Veterinary Hospital of the Santa Catarina State University - UDESC (Brazil). Apparent prevalence for sick cats at the hospital population was 28.41% (95%CI 21.88-34.94%) for FeLV, 7.65% (95%CI 3.71-11.50%) for FIV and 2.18% (95%CI 0.56-5.47%) for both viruses. For healthy cats, the apparent prevalence was 9.89% (95%CI 3.75-16.02%) for FeLV, 2.20% (95%CI 0.34-7.75%) for FIV by immunoassay (ELISA). Average age for FeLV- and FIV-positive individuals was 38.32 and 64.25 months, respectively. Behavior such as aggressiveness and sex (male) were both associated with increased odds of result positivity test for FeLV and FIV; older animals were also associated with FIV test results. A very small proportion of the animals were vaccinated against FeLV and none against FIV. Most of the animals were adopted from shelters or rescued from streets, living with multiple cats that had access to outdoors. The high prevalence of FeLV suggests a need for better control strategies against this disease.", "journal": "Comparative immunology, microbiology and infectious diseases", "doi": "10.1016/j.cimid.2018.12.004", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "30941311", "author": "Destefanis F", "n_authors": 4, "title": "Investigating the Connection Between Endogenous Heme Accumulation and COX2 Activity in Cancer Cells.", "abstract": "Heme, an iron-containing porphyrin, is fundamental for a variety of functions in cell homeostasis. Nevertheless, recent data indicate that dysregulation of heme metabolism might promote tumorigenesis. The intracellular heme pool is finely regulated through the control of heme synthesis, degradation, incorporation into hemoproteins and trafficking across membranes. All these processes might be potentially targeted to alter endogenous heme content in order to counteract cancer growth. Nevertheless, these putative therapeutic interventions have to take into account the possibility of undesired side effects, such as the over-activation of heme-dependent enzymes involved in cancer. Among them, cyclooxygenase-2 is a prostaglandin-producing hemoprotein, induced during inflammation and in different types of tumor, particularly in colorectal cancer. The aim of this study was to evaluate whether modulation of endogenous heme may affect cyclooxygenase-2 expression and activity, taking advantage of two different approaches able to alter heme levels: the silencing of the heme exporter Feline Leukemia Virus subgroup C receptor 1 and the induction of heme synthesis by 5-aminolevulinic acid administration. Our data demonstrate that the down-regulation of the heme exporter in colorectal cancer cells does not affect cyclooxygenase-2 expression and activity. Conversely, 5-aminolevulinic acid administration results in decreased cyclooxygenase-2 expression. However, the overall cyclooxygenase-2 enzymatic activity is maintained. The present work sheds light on the complex modulation of cyclooxygenase-2 by endogenous heme and support the idea that targeting heme metabolism could be a valuable therapeutic option against cancer.", "journal": "Frontiers in oncology", "doi": "10.3389/fonc.2019.00162", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "30909954", "author": "Brianti E", "n_authors": 10, "title": "Treatment and long-term follow-up of a cat with leishmaniosis.", "abstract": "Leishmania infection in cats is being increasingly reported in endemic areas. Nevertheless, only a few clinical cases have been described in cats, and even fewer have provided information on the response to treatment and a proper follow-up. Here we report a case of feline leishmaniosis not associated with any other disease or co-infection and document its response to allopurinol treatment and long-term follow-up data. A 6-year-old domestic shorthair female cat was referred for nodular blepharitis, mucocutaneous ulcerative lesions of the mouth and lymph node enlargement. The cat was moderately anaemic, hyperglobulinaemic and tested negative for feline leukaemia virus and feline immunodeficiency virus. Fine needle aspirates of nodules and mucocutaneous lesions showed the presence of numerous amastigote forms of Leishmania. Leishmania infection was further confirmed by serology (IFAT test, 1:640) and real-time PCR (RT-PCR) on blood and conjunctival swabs. The cat was treated with allopurinol (20 mg/kg SID), which was clinically effective, although the cat remained Leishmania-positive in serology and RT-PCR on blood and conjunctival swabs. Allopurinol treatment was interrupted after seven months because of the healing of all lesions and lack of compliance by the owner. After two years, the cat relapsed displaying almost the same clinical signs and clinicopathological alterations. On this occasion, the parasite was isolated by culture and identified as belonging to L. infantum. Allopurinol treatment was started again but was interrupted several times because of the itching side effect observed. The cat worsened progressively and died two months after the relapse without any chance to shift the treatment to another molecule (e.g. meglumineantimoniate or miltefosine). Out of all documented cases of feline leishmanosis, the present case has the longest follow-up period and it is one of the few in which the parasite was isolated and identified. It further confirms the potential progression of Leishmania infection to disease in cats even in the absence of comorbidities. Veterinarians practicing in endemic areas should be aware of this susceptibility, properly include feline leishmaniosis in the differential diagnosis and propose preventative measures to those cats at risk.", "journal": "Parasites & vectors", "doi": "10.1186/s13071-019-3388-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "30909952", "author": "Priolo V", "n_authors": 9, "title": "Leishmania infantum-specific IFN-γ production in stimulated blood from cats living in areas where canine leishmaniosis is endemic.", "abstract": "Feline leishmaniosis caused by Leishmania infantum is considered a rare disease in endemic areas, whereas subclinical infections are common. Immune response plays a key role in driving the course of L. infantum infection in other host species; however, the feline cell-mediated immune response to L. infantum infection has not yet been investigated. The aim of this study was to determine the cell-mediated immune response specific to L. infantum by means of interferon (IFN)-γ release in whole blood assay from cats living in endemic areas (66 in Sicily and 113 in Catalonia) and to compare with antibody levels to L. infantum [enzyme-linked immunosorbent assay (ELISA) and immunofluorescence antibody test (IFAT)], blood parasite load and retroviral infections. Most cats (n = 140) were L. infantum antibody negative and only 22% (n = 39) were positive. Only 9 and 2% of tested cats had a feline immunodeficency virus (FIV) infection or a feline leukemia virus (FeLV) infection, respectively. Thirty-two cats out of 179 (18%) produced IFN-γ after stimulation with L. infantum soluble antigen (LSA) while the majority of cats (93%) produced IFN-γ after stimulation with concanavalin A (ConA). Six LSA-IFN-γ-producer cats were seropositive (three to ELISA and five to IFAT) but they were polymerase chain reaction (PCR) negative, while only one cat was antibody- and PCR-positive. Significant positive correlations were found between IFN-γ concentrations after stimulation with LSA and ConA, and between serology and PCR testing. No association was found between FIV status and LSA or ConA-IFN-γ production. Combining PCR, serology and specific IFN-γ concentration results, we found that 36% of cats studied were exposed to L. infantum. As expected, cats from endemic areas produce IFN-γ after ex vivo blood stimulation with LSA and therefore are able to activate a cell-mediated adaptive immune response against the parasite that is variably associated with antibody or blood PCR positivity. The association of this assay to serological and molecular tests provides a better estimate of cat exposure to L. infantum.", "journal": "Parasites & vectors", "doi": "10.1186/s13071-019-3386-y", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "30809813", "author": "Westman ME", "n_authors": 3, "title": "Diagnosing feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV) infection: an update for clinicians.", "abstract": "With the commercial release in Australia in 2004 of a vaccine against feline immunodeficiency virus (FIV; Fel-O-Vax FIV®), the landscape for FIV diagnostics shifted substantially. Point-of-care (PoC) antibody detection kits, which had been the mainstay for diagnosing FIV infection since the early 1990s, were no longer considered accurate to use in FIV-vaccinated cats, because of the production of vaccine-induced antibodies that were considered indistinguishable from those produced in natural FIV infections. Consequently, attention shifted to alternative diagnostic methods such as nucleic acid detection. However, over the past 5 years we have published a series of studies emphasising that FIV PoC test kits vary in their methodology, resulting in differing accuracy in FIV-vaccinated cats. Importantly, we demonstrated that two commercially available FIV antibody test kits (Witness™ and Anigen Rapid™) were able to accurately distinguish between FIV-vaccinated and FIV-infected cats, concluding that testing with either kit offers an alternative to PCR testing. This review summarises pertinent findings from our work published in a variety of peer-reviewed research journals to inform veterinarians (particularly veterinarians in Australia, New Zealand and Japan, where the FIV vaccine is currently commercially available) about how the approach to the diagnosis of FIV infection has shifted. Included in this review is our work investigating the performance of three commercially available FIV PoC test kits in FIV-vaccinated cats and our recommendations for the diagnosis of FIV infection; the effect of primary FIV vaccination (three FIV vaccines, 4 weeks apart) on PoC test kit performance; our recommendations regarding annual testing of FIV-vaccinated cats to detect 'vaccine breakthroughs'; and the potential off-label use of saliva for the diagnosis of FIV infection using some FIV PoC test kits. We also investigated the accuracy of the same three brands of test kits for feline leukaemia virus (FeLV) diagnosis, using both blood and saliva as diagnostic specimens. Based on these results, we discuss our recommendations for confirmatory testing when veterinarians are presented with a positive FeLV PoC test kit result. Finally, we conclude with our results from the largest and most recent FIV and FeLV seroprevalence study conducted in Australia to date.", "journal": "Australian veterinary journal", "doi": "10.1111/avj.12781", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "30775368", "author": "Kreisler RE", "n_authors": 3, "title": "Decrease in Population and Increase in Welfare of Community Cats in a Twenty-Three Year Trap-Neuter-Return Program in Key Largo, FL: The ORCAT Program.", "abstract": "The objective of this study was to evaluate the effect of a long-term (23-year) trap-neuter-return program on the population size of community cats in the Ocean Reef Community and to describe the demographic composition and outcome of enrolled cats. A retrospective study was performed using both cat census data collected between 1999 and 2013 as well as individual medical records for cats whose first visit occurred between 3/31/1995 and 12/31/2017. Medical record entries were reviewed to determine program inputs, cat outcomes, retroviral disease prevalence, and average age of first visit, sterilization, and death through 6/11/2018. Change over time was analyzed via linear regression. The free-roaming population decreased from 455 cats recorded in 1999 to 206 recorded in 2013 (55% decrease, P < 0.0001). There were 3,487 visits recorded for 2,529 community cats, with 869 ovariohysterectomies and 822 orchiectomies performed. At last recorded visit, there were 1,111 cats returned back to their original location, and 1,419 cats removed via adoption (510), transfer to the adoption center (201), euthanasia of unhealthy or retrovirus positive cats (441), died in care (58), or outcome of dead on arrival (209). The number of first visits per year decreased 80% from 348 in 1995 to 68 in 2017. The estimated average age of the active cat population increased by 0.003 months each year (P = 0.031) from 16.6 months in 1995 to 43.8 months in 2017. The mean age of cats at removal increased 1.9 months per year over time (P < 0.0001) from 6.4 months in 1995 to 77.3 months in 2017. The mean age of cats at return to the original location was 20.8 months, which did not change over time. The overall retrovirus prevalence over the entire duration was 6.5%, with FIV identified in 3.3% of cats and FeLV identified in 3.6%. Retrovirus prevalence decreased by 0.32% per year (P = 0.001), with FIV decreasing by 0.16% per year (P = 0.013) and FeLV decreasing 0.18% per year (P = 0.033). In conclusion, a trap-neuter-return program operating for over two decades achieved a decrease in population and an increase in population welfare as measured by increased average age of population and decreased retrovirus prevalence.", "journal": "Frontiers in veterinary science", "doi": "10.3389/fvets.2019.00007", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "30691602", "author": "Cristo TG", "n_authors": 9, "title": "Feline Lymphoma and a High Correlation with Feline Leukaemia Virus Infection in Brazil.", "abstract": "Lymphoma is the most important haemopoietic tumour in cats and has been associated with feline leukaemia virus (FeLV) infection. In Brazil, no studies have established a correlation between FeLV infection and lymphoma. The aim of this study was to characterize lymphomas arising in cats in Brazil anatomically and microscopically, and to correlate these data with FeLV infection as determined by immunohistochemistry for the FeLV gp70 antigen. Fifty-three cats with lymphoma were evaluated. The mean age of junior, prime, mature, senior and geriatric cats was 1.65 years, 4.34 years, 8 years, 12.14 years and 15.5 years, respectively. The anatomical types of lymphoma were multicentric (43.4%, 23/53), mediastinal (33.96%, 18/53), renal (11.32%, 6/53), hepatic (5.66%, 3/53), nodal (3.77%, 2/53) and alimentary (1.89 %, 1/53). The histological types were small noncleaved-cell (33.96%, 18/53), mixed diffuse (22.64%, 12/53), immunoblastic (15.11%, 8/53), lymphoblastic (11, 32%, 6/53), small lymphocytic (9.43%, 5/53), small cleaved-cell (3.77%, 2/53) and large cell lymphomas (3.77%, 2/3). Immunopositivity for FeLV was observed in 56.6% (30/53) of the samples. FeLV positivity was equally distributed between the genders, but predominated in junior and prime cats. The degree of association between lymphoma and FeLV infection in Brazil was higher than that found in other countries, demonstrating the need to prevent and control the factors associated with infection.", "journal": "Journal of comparative pathology", "doi": "10.1016/j.jcpa.2018.10.171", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "30675368", "author": "Jenkins EL", "n_authors": 4, "title": "Suspected adverse drug interaction between spinosad and milbemycin oxime in a cat.", "abstract": "A 12-year-old male neutered Tonkinese cat was presented for acute ataxia, weakness, altered mentation and generalised tremors. The cat had been administered oral spinosad (140 mg; 33.5 mg/kg) 48 h prior to the onset of clinical signs, and an oral anthelmintic containing milbemycin oxime (16 mg; 3.8 mg/kg) and praziquantel (40 mg; 9.6 mg/kg) 12 h before the onset of clinical signs. On physical examination, dull-to-obtunded mentation, tetraparesis, ataxia and mild tremors of facial, limb and trunk muscles were noted. Serum biochemical changes and urinalysis were consistent with haemoconcentration. The results of a complete blood count, urine culture and serology for feline leukaemia virus, feline immunodeficiency virus and cryptococcal antigen were negative. The patient was monitored in hospital and all clinical signs resolved within 24 h. The neurological signs in this case were consistent with macrocyclic lactone neurotoxicity, which is suspected to have occurred from an adverse drug interaction between spinosad and milbemycin oxime. This report serves to highlight the potential for this adverse drug interaction between these commonly used prophylactic drugs.", "journal": "JFMS open reports", "doi": "10.1177/2055116918820733", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "30642591", "author": "Russo V", "n_authors": 9, "title": "Expression of the feline leukemia virus subgroup C receptors in normal and neoplastic urothelium of the urinary bladder of cattle associated with bovine papillomavirus infection.", "abstract": "The feline leukemia virus subgroup C receptors (FLVCRs) were originally cloned as virus receptors, but are now believed to function also as heme transporters and are expressed in a broad range of tissues in a wide range of mammalian species. Expression of FLVCR1 and FLVCR2 was investigated in 19 bovine papillomavirus-associated urinary bladder cancers and in 15 non-neoplastic samples of bladder from cattle. E5 oncoprotein of bovine Deltapapillomaviruses (δPVs) was detected in 17 of the 19 bladder cancers. Flvcr1 and Flvcr2 were amplified and sequenced both in neoplastic and non-neoplastic samples showing a 100% identity with bovine Flvcr1 and Flvcr2 mRNA sequences present in GenBank database (accession numbers: NM_001206019.1 and NM_001192143.1, respectively). Reverse transcription (RT)-PCR showed that Flvcr1 and Flvcr2 were overexpressed in 4 and 5 out of 19 urothelial cancers, respectively, but in none of the non-neoplastic samples. In addition, western blot analysis detected higher levels of FLVCR1 and FLVCR2 in samples in which transcripts were not increased, suggesting post-translational changes to these proteins. Increased FLCVR1 and FLVCR2 was also observed immunohistochemically in the neoplastic cells. Immunolabeling for FLVCR1 was seen in the cytoplasm and plasm membrane of urothelial cancer cells, wheras immunolabeling for FLVCR2 was present within the nucleus. This is the first time that FLVCR expression has been investigated in bovine tissues and the first to suggest that expression could be increased in cancers. Additional studies are required to define the role, if any, of FLVCR in papillomavirus-associated cancer cells.", "journal": "Veterinary microbiology", "doi": "10.1016/j.vetmic.2018.12.024", "deposited_data": "Sim", "nuccore_ids": "329664791, 2868800441, 2587638813, 2587638812, 2587638811, 2587638810, 329664791", "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "32218716", "author": "Candela MG", "n_authors": 6, "title": "Canine distemper virus may affect European wild cat populations in Central Spain.", "abstract": "The main objective of this brief communication is to inform about the exposure to certain pathogens of interest for mesocarnivores in wildcats (", "journal": "Mammalian biology = Zeitschrift fur Saugetierkunde", "doi": "10.1016/j.mambio.2019.04.006", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "32214947", "author": "Nájera F", "n_authors": 10, "title": "Lynx eats cat: disease risk assessment during an Iberian lynx intraguild predation.", "abstract": "Lethal interactions between members of the carnivore guild are well represented in literature. In the Iberian lynx, interspecific killing (without prey consumption) of some mesocarnivores, such as the Egyptian mongoose, genet, and red fox, has been reported. Although vaguely documented, evidence suggests feral cats fall victim to interactions with this apex predator. Here, we describe the first documented case of interspecific killing and partial consumption of a feral cat by an adult male Iberian lynx reintroduced in Southwestern Spain. Ulterior analyses demonstrated that the victim was viremic to feline leukemia virus. To prevent the dissemination of the virus and a potential outbreak in the Iberian lynx population, control measures, including the clinical evaluation of the male Iberian lynx, and intensive monitoring were implemented in order to detect intraspecific interactions. After 3 weeks, the lynx was evaluated, presented good condition and resulted negative to both ELISA and RT-PCR. Thanks to the long-term monitoring, this case could be detected and measures to prevent an outbreak could be implemented.", "journal": "European journal of wildlife research", "doi": "10.1007/s10344-019-1275-5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "30561312", "author": "Chiu ES", "n_authors": 6, "title": "Multiple Introductions of Domestic Cat Feline Leukemia Virus in Endangered Florida Panthers.", "abstract": "The endangered Florida panther (Puma concolor coryi) had an outbreak of infection with feline leukemia virus (FeLV) in the early 2000s that resulted in the deaths of 3 animals. A vaccination campaign was instituted during 2003-2007 and no additional cases were recorded until 2010. During 2010-2016, six additional FeLV cases were documented. We characterized FeLV genomes isolated from Florida panthers from both outbreaks and compared them with full-length genomes of FeLVs isolated from contemporary Florida domestic cats. Phylogenetic analyses identified at least 2 circulating FeLV strains in panthers, which represent separate introductions from domestic cats. The original FeLV virus outbreak strain is either still circulating or another domestic cat transmission event has occurred with a closely related variant. We also report a case of a cross-species transmission event of an oncogenic FeLV recombinant (FeLV-B). Evidence of multiple FeLV strains and detection of FeLV-B indicate Florida panthers are at high risk for FeLV infection.", "journal": "Emerging infectious diseases", "doi": "10.3201/eid2501.181347", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "30554553", "author": "Bergmann M", "n_authors": 5, "title": "Antibody response to feline panleukopenia virus vaccination in cats with asymptomatic retrovirus infections: a pilot study.", "abstract": "Currently, there are only a few studies on how immunocompromised cats, such as cats infected with feline leukaemia virus (FeLV) and feline immunodeficiency virus (FIV), respond to vaccination. Therefore, this study measured feline panleukopenia virus (FPV) antibodies in retrovirus-infected cats within a period of 28 days after FPV vaccination, and compared the immune response to that of non-infected cats. Eight asymptomatic retrovirus-infected cats (four FeLV, four FIV), and non-infected age-matched control cats (n = 67) were vaccinated with a commercial FPV modified live virus (MLV). Pre- and post-vaccination antibody titres were measured by haemagglutination inhibition (HI) on days 0, 7 and 28. An HI titre ⩾1:40 was defined as protective. An adequate response to vaccination was defined as a four-fold titre increase or higher. Comparison of the immune response of retrovirus-infected and non-infected cats was performed. Pre-vaccination FPV antibody titres ⩾1:40 were present in 100% (n = 8/8; 95% confidence interval [CI] 62.8-100) of retrovirus-infected and in 77.6% (n = 52/67; 95% CI 66.2-86.0) of non-infected cats. An adequate response to vaccination (titre increase ⩾four-fold) was seen in 1/8 retrovirus-infected cats (12.5%; 95% CI 0.1-49.2) compared with 22/67 non-infected cats (32.8%; 95% CI 22.8-44.8). In cats with high pre-vaccination titres (⩾1:160), a four-fold titre increase or higher was observed in 1/8 retrovirus infected cats (12.5%; 95% CI 0.1-49.2) compared with 4/42 non-infected cats (9.5%; 95% CI 3.2-22.6). None of the eight retrovirus-infected cats developed illness or vaccination side effects after vaccination with MLV against FPV within the 28 days. There were no significant differences between groups: for pre-vaccination titres; for at least four-fold titre increases following vaccination in either all cats or the cats with high pre-vaccination titres; and concerning adverse effects. All retrovirus-infected asymptomatic cats had pre-vaccination FPV antibodies indicating protection against panleukopenia. Response of retrovirus-infected cats to vaccination was similar to the response of non-infected cats.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X18816463", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "29911463", "author": "Cline MG", "n_authors": 4, "title": "Body composition of lean outdoor intact cats vs lean indoor neutered cats using dual-energy x-ray absorptiometry.", "abstract": "The objectives for this study were to compare the body composition of adult indoor neutered domestic cats with outdoor intact cats with an ideal body condition score using dual-energy x-ray absorptiometry, and to report the body composition findings of free-roaming cats, as this has not been previously reported. Most domestic house cats differ from free-roaming cats as they are confined indoors and neutered. Indoor neutered cats have reduced activity and hormonal alterations that may result in lower muscle mass and higher body fat percentages vs outdoor intact cats, despite similar body condition scores. Twenty-one outdoor intact cats (10 male, 11 female) were selected from a trap-neuter-return program and 16 indoor neutered domestic cats (10 male, six female) were client-owned. Inclusion criteria included an estimated age between 1 and 6 years, complete blood count, biochemistry panel, urinalysis, total thyroxine, feline leukemia virus/feline immunodeficiency virus screening and a body condition score of 4-5/9. Indoor neutered cats had a higher body fat percentage (22.1% [range 17.3-28.2%]) than outdoor intact cats (17.3% [range 10.0-33.6%]; P = 0.002). Indoor neutered male cats had a higher body fat percentage ( P <0.001) than outdoor intact cats. No difference in body fat percentage was observed in female cats ( P = 0.159). Indoor neutered domestic cats had a higher bone mineral density than outdoor intact cats ( P = 0.023). The results of this study suggest indoor confinement and neutering increase body fat percentage and bone mineral density in cats with an ideal body condition score.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X18780872", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "29788832", "author": "Carneiro CS", "n_authors": 5, "title": "Feline injection site sarcoma: immunohistochemical characteristics.", "abstract": "Feline injection site sarcoma (FISS) is a rapid growing locally aggressive tumor with a low metastatic rate. Its histologic features are clearly defined, but there are few studies regarding its immunohistochemical characteristics. The present study investigated the immunohistochemical characteristics of 21 cases of FISS. FISSs from 12 male and nine female cats, 20 mixed-breed and one Siamese, were included in the study. After histopathological diagnosis, additional histologic sections were immunostained for vimentin, cytokeratin, desmin, S100 protein, viral feline leukemia virus (FeLV) particles, cyclooxygenase 2 (COX-2) and c-KIT. Positive and negative controls were adopted accordingly. Immunostainings were classified as positive or negative according to the number of positive cells from a total of 1000 cells per tumor section. Histopathologic diagnosis of the tumors revealed 18 (85.7%) fibrosarcomas and three (14.3%) other sarcomas; four fibrosarcomas (22.2%) were grade III, five (27.8%) were grade II and nine (50.0%) were grade I. Two sarcomas were grade III and one was grade II. Seventeen (81%) tumors were negative for desmin. All samples were positive for vimentin. Twenty tumors (95.2%) were positive for S-100 protein. Positivity for c-KIT was observed in four (19%) samples; COX-2 was positive in 13 (61.9%) and FeLV viral particles were positive in nine (42.9%) FISSs. Immunohistochemical findings of FISSs revealed positive immunostainings for desmin, vimentin, S-100 protein, c-KIT, COX-2 and FeLV viral particles.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X18774709", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "29595359", "author": "Amengual Batle P", "n_authors": 5, "title": "Feline hyperaesthesia syndrome with self-trauma to the tail: retrospective study of seven cases and proposal for an integrated multidisciplinary diagnostic approach.", "abstract": "This was a retrospective study on the clinical features and response to treatment in seven cats with feline hyperaesthesia syndrome (FHS) and tail mutilation. FHS is a poorly understood disorder characterised by skin rippling over the dorsal lumbar area, episodes of jumping and running, excessive vocalisation, and tail chasing and self-trauma. The majority of the cats were young, with a median age of 1 year at the onset of clinical signs, male (n = 6) and with access to the outdoors (n = 5). Multiple daily episodes of tail chasing and self-trauma were reported in five cats, with tail mutilation in four cats. Vocalisation during the episodes (n = 5) and rippling of lumbar skin (n = 5) were also reported. Haematology, serum biochemistry, Toxoplasma gondii and feline immunodeficiency virus/feline leukaemia virus serology, MRI scans of brain, spinal cord and cauda equina, cerebrospinal fluid analysis and electrodiagnostic tests did not reveal any clinically significant abnormalities. A definitive final diagnosis was not reached in any of the cats, but hypersensitivity dermatitis was suspected in two cases. A variety of medications was used alone or in combination, including gabapentin (n = 6), meloxicam (n = 4), antibiotics (n = 4), phenobarbital (n = 2), prednisolone (n = 2) and topiramate (n = 2); ciclosporin, clomipramine, fluoxetine, amitriptyline and tramadol were used in one cat each. Clinical improvement was achieved in six cases; in five cats complete remission of clinical signs was achieved with gabapentin alone (n = 2), a combination of gabapentin/ciclosporin/amitriptyline (n = 1), gabapentin/prednisolone/phenobarbital (n = 1) or gabapentin/topiramate/meloxicam (n = 1). This is the first retrospective study on a series of cats with FHS. The diagnostic work-up did not reveal any significant abnormalities of the central or peripheral nervous system; dermatological and behavioural problems could not be ruled out. We propose an integrated multidisciplinary diagnostic pathway to be used for the management of clinical cases and for future prospective studies.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X18764246", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "33488001", "author": "Sattasathuchana P", "n_authors": 3, "title": "Comparison of subclinical dermatophyte infection in short- and long-haired cats.", "abstract": "Long-haired cats may have an increased risk of dermatophytosis due to insufficient grooming and their thick hair coat trapping fungal spores. The prevalence of subclinical dermatophytosis in long-haired cats was evaluated using fungal culture and Wood's lamp test. Hematology and blood chemistry results were compared between cats negative and positive for dermatophytosis. A total of 127 cats (median age, 3 years [range, 10 months-10 years]) without feline leukemia virus or feline immunodeficiency virus infection were classified into short-haired (n=64) and long-haired (n=63) groups. Hair samples were cultured on a fungal culture medium (dermatophyte test medium, enhanced sporulation agar, and Sabouraud agar). The prevalence of dermatophytosis in short-haired and long-haired cats was 6.25% (95% confidence interval [CI], 2.15-12.28) and 34.92% (95% CI, 22.94-46.90), respectively. The odds of long-haired cats having dermatophytosis were 8.05 (95% CI, 2.44-33.97) times greater than that in short-haired cats. The number of positive dermatophytosis found in domestic short-haired cats (2/50, 4.0%) was significantly lower than that in Persian cats (17/47, 36.17%; p<0.001) and long-haired mixed breed cats (3/7, 42.86%; p=0.011). The overall sensitivity and specificity of the Wood's lamp test for diagnosing  Subclinical dermatophytosis was more common in long-haired cats; therefore, dermatophyte examinations should be performed routinely.", "journal": "Veterinary world", "doi": "10.14202/vetworld.2020.2798-2805", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "33204894", "author": "Moreira da Silva J", "n_authors": 9, "title": "Detection and modeling of anti-Leptospira IgG prevalence in cats from Lisbon area and its correlation to retroviral infections, lifestyle, clinical and hematologic changes.", "abstract": "Leptospirosis is a zoonosis of global importance caused by ", "journal": "Veterinary and animal science", "doi": "10.1016/j.vas.2020.100144", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "33092590", "author": "Imre M", "n_authors": 9, "title": "Molecular detection of hemotropic mycoplasmas (hemoplasmas) in domestic cats (Felis catus) in Romania.", "abstract": "The hemotropic mycoplasmas (hemoplasmas) of the genus Mycoplasma are recognized as important bacteria that parasitize red blood cells, causing hemolytic anemia in many mammalian species, including cats. No information is available concerning the presence of feline hemoplasma infections in cats in Romania. Thus, the objective of the present study was to provide data on the occurrence and molecular characterization of hemotropic mycoplasmas in client-owned cats in Romania. Blood samples from 51 unhealthy cats, originating from Timişoara Municipality, Romania, were screened for the presence of hemoplasmas using conventional polymerase chain reaction (PCR) targeting the 16S rRNA gene and sequencing assays. PCR-positive samples were subsequently analyzed by phylogenetic and population genetic analysis. Molecular analysis revealed 11 (21.6%) positive samples, consisting of 8 (72.7%) Candidatus Mycoplasma haemominutum and 3 (27.3%) Mycoplasma haemofelis confirmed positives. Candidatus Mycoplasma turicensis was not detected, and no co-infections were registered. No significant associations (p > 0.05) were found between the hemoplasma infection status and age, gender, breed, presence of ectoparasites, feline leukemia virus/feline immunodeficiency virus positivity of cats, or the sampling season. However, outdoor access was positively associated (p = 0.049) with infection and could be considered a risk factor (OR = 4.1) in acquiring feline hemotropic mycoplasmas. Phylogenetic analysis revealed that our sequences clustered with those selected from the GenBank database in two distinct clades. The registered population genetic indices were strongly supportive of the great variance in sequences between the recorded Mycoplasma species. The findings support the occurrence of feline hemoplasma infections in previously uninvestigated territories of Europe, providing useful information for small animal practitioners. To our knowledge, the present survey is the first reported molecular evidence of feline hemoplasma infections in Romania.", "journal": "BMC veterinary research", "doi": "10.1186/s12917-020-02626-7", "deposited_data": "Sim", "nuccore_ids": "1896706570, 1896706568, 1896706566, 1896706563, 1896706561, 1896706560, 1896706557, 1896706556, 1896706555, 1435075102, 1435075101", "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "33063876", "author": "Stavroulaki EM", "n_authors": 5, "title": "Steroid-responsive neutropenia in a cat with progressive feline leukemia virus infection.", "abstract": "An 8-month-old female domestic shorthair cat was presented to the Animal Medical Center with anorexia, lethargy, and mild gastrointestinal signs. A CBC revealed a profound neutropenia, and serologic testing with an in-house test kit (SNAP FIV/FeLV Combo, IDEXX) was positive for feline leukemia virus (FeLV) antigen. Serial hematologic examinations during hospitalization showed a persistent neutropenia with occasionally severe anemia and thrombocytopenia. Prednisolone administration afforded complete hematologic remission within 3 days. Four weeks after the premature discontinuation of prednisolone, the patient relapsed; however, complete and prolonged hematologic remission was achieved after prednisolone was re-induced. Bone marrow aspiration cytology was consistent with immune-mediated destruction of the mature myeloid cells. steroid-responsive (likely immune-mediated) cytopenias rarely occur in cats with progressive FeLV infection. Although only a few cases of FeLV-positive, severely neutropenic cats that responded to immunosuppressive therapy have been reported, this case highlights that a grave prognosis should not always be given to these FeLV-positive cats.", "journal": "Veterinary clinical pathology", "doi": "10.1111/vcp.12896", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32974584", "author": "Vale AP", "n_authors": 4, "title": "Challenges in the veterinary microbiology diagnostic laboratory: a novel Acinetobacter species as presumptive cause for feline unilateral conjunctivitis.", "abstract": "The present study highlights challenges in the veterinary microbiology diagnostic laboratory in the identification of bacteria responsible for infections in veterinary settings, particularly when evidence-based data is lacking. A 1.8-year-old neutered male domestic cat (FIV/FeLV negative) was presented to a veterinary practice in April 2016 with a history of left unilateral mild conjunctivitis that was empirically treated with fusidic acid and chloramphenicol. In January 2017, the same animal was presented with chronic left unilateral conjunctivitis and an eye swab was submitted for microbiological culture and susceptibility testing. Significant growth was not detected in two samples tested. Finally, in February 2017 another eye swab produced a slow growing pure culture identified by VITEK 2 as ", "journal": "Access microbiology", "doi": "10.1099/acmi.0.000118", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32966900", "author": "Biezus G", "n_authors": 8, "title": "Plasma Cell Pododermatitis Associated With Feline Leukemia Virus (FeLV) and Concomitant Feline Immunodeficiency Virus (FIV) Infection in a Cat.", "abstract": "This report aims to describe one case of plasma cell pododermatitis associated with feline leukemia virus (FeLV) and concomitant feline immunodeficiency virus (FIV) infection in a cat. A 2-year-old, intact male, mixed-breed cat was presented with alopecia, skin peeling, and erythematous swelling in the left metacarpal paw pad. Swelling, softening, ulceration with secondary crusts, and erythematous to violaceous discoloration were observed in multiple metacarpal, metatarsal, and digital paw pads. Complete blood count and serum biochemistry were analyzed. FeLV antigenemia and FIV seropositivity were assessed by immunoassay (enzyme-linked immunosorbent assay). Nested-PCR was used to detect FIV and FeLV proviral DNA in blood cells. Histopathological examination and anti-FeLV and anti-FIV immunohistochemical were performed on paw pad biopsies. According to clinical and histopathological findings, a diagnosis of plasma cell pododermatitis was made. The cat was FIV and FeLV seropositive. The immunohistochemical of paw pad biopsies revealed FeLV positivity and FIV negativity. This study provides reference for further investigations about feline plasma cell pododermatitis and highlights retrovirus infection as a potential factor associated with this disease.", "journal": "Topics in companion animal medicine", "doi": "10.1016/j.tcam.2020.100475", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32845225", "author": "Hofmann-Lehmann R", "n_authors": 2, "title": "Feline leukaemia virus infection: A practical approach to diagnosis.", "abstract": "Feline leukaemia virus (FeLV) is a retrovirus of domestic cats worldwide. Cats lacking strong FeLV-specific immunity and undergoing progressive infection commonly develop fatal FeLV-associated disease. Many aspects of FeLV infection pathogenesis have been elucidated, some during more recent years using molecular techniques. It is recommended that the FeLV status of every cat is known, since FeLV infection can influence the prognosis and clinical management of every sick cat. Moreover, knowledge of a cat's FeLV status is of epidemiological importance to prevent further spread of the infection. Diagnosing FeLV infection remains challenging due to different outcomes of infection, which can vary over time depending on the balance between the virus and the host's immune system. Furthermore, testing for FeLV infection has become more refined over the years and now includes diagnostic assays for different viral and immunological parameters. Knowledge of FeLV infection pathogenesis, as well as the particulars of FeLV detection methods, is an important prerequisite for correct interpretation of any test results and accurate determination of a cat's FeLV status. The current review presents recent knowledge on FeLV pathogenesis, key features to be determined in FeLV infection, and frequently used FeLV detection methods, and their characteristics and interpretation. An algorithm for the diagnosis of FeLV infection in a single cat, developed by the European Advisory Board on Cat Diseases, is included, and FeLV testing in specific situations is addressed. As well as increasing awareness of this deadly infection in domestic cats, the aim is to contribute diagnostic expertise to allow veterinarians in practice to improve their recognition, and further reduce the prevalence, of FeLV infection.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X20941785", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32825496", "author": "Gomez-Lucia E", "n_authors": 6, "title": "Clinical and Hematological Follow-Up of Long-Term Oral Therapy with Type-I Interferon in Cats Naturally Infected with Feline Leukemia Virus or Feline Immunodeficiency Virus.", "abstract": "Feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV), two of the most important pathogens of cats, produce chronic systemic diseases with progressive death of cells involved in the immune response, ultimately leading to death. Immunostimulants is one of the few alternatives to the symptomatic treatment. In this study, 27 naturally FeLV-infected (FeLV+) and 31 naturally FIV-infected (FIV+) cats were administered orally by their owners 60 IU/day of recombinant human interferon alpha (rHuIFN-α) for four months in alternate weeks. Clinical status was evaluated and blood samples collected at four different visits or months (M): pretreatment (M0), mid-treatment (M2), end of treatment (M4), and 4-8 months after end of treatment (M10). Most cats ostensibly improved their clinical status, and many became asymptomatic. rHuIFN-α treatment improved the anemic processes observed at M0 (at least in cats with mild or moderate anemia) and leukocyte counts, including a more favorable CD4+/CD8+ ratio. An increase in the serum gammaglobulin concentration was seen in 80% of the cats. Despite observing an obvious favorable progress in the clinical, biopathological, and CD4+/CD8+ values during treatment, almost invariably all the parameters analyzed worsened after treatment discontinuation (M10), which suggests that the interferon-α protocol should be either extended or include additional cycles for a long-lasting benefit in FeLV+ and FIV+ cats.", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani10091464", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32817213", "author": "Chiu ES", "n_authors": 2, "title": "Presence of Endogenous Viral Elements Negatively Correlates with Feline Leukemia Virus Susceptibility in Puma and Domestic Cat Cells.", "abstract": "While feline leukemia virus (FeLV) has been shown to infect felid species other than the endemic domestic cat host, differences in FeLV susceptibility among species has not been evaluated. Previous reports have noted a negative correlation between endogenous FeLV (enFeLV) copy number and exogenous FeLV (exFeLV) infection outcomes in domestic cats. Since felids outside the genus ", "journal": "Journal of virology", "doi": "10.1128/JVI.01274-20", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32801452", "author": "Walter J", "n_authors": 5, "title": "Prevalence of feline herpesvirus-1, feline calicivirus, Chlamydia felis, and Bordetella bronchiseptica in a population of shelter cats on Prince Edward Island.", "abstract": "The prevalence of the causative agents of feline upper respiratory tract disease (URTD) has been previously documented in many regions worldwide, but has yet to be reported in eastern Canada. The objectives of this study were to determine the prevalence of feline herpesvirus-1 (FHV-1), feline calicivirus (FCV), ", "journal": "Canadian journal of veterinary research = Revue canadienne de recherche veterinaire", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32785525", "author": "Alberigi B", "n_authors": 6, "title": "Unusual feline Dirofilaria immitis infection: a case report.", "abstract": "Cats are less susceptible to Dirofilaria immitis infection than dogs. Although rare, the feline disease can be fatal even with low parasitic loads. The infection is often asymptomatic or has non-specific symptoms that are mainly associated with the death of immature worms. Microfilaremia is rare and transient. Normally, microfilaremia, when present, lasts for not more than 33 days. This study describes a feline case presenting with non-specific clinical signs and prolonged microfilaremia. Case: a random bred cat infected by feline leukemia virus (FeLV) that was found to be microfilaremic by chance. The infection was detected by the presence of microfilariae in a blood smear and was confirmed by antigen test (SNAP Feline Triple Test, Idexx®) and echocardiogram.", "journal": "Revista brasileira de parasitologia veterinaria = Brazilian journal of veterinary parasitology : Orgao Oficial do Colegio Brasileiro de Parasitologia Veterinaria", "doi": "10.1590/s1984-29612020061", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32687655", "author": "Bandinelli MB", "n_authors": 9, "title": "Ophthalmopathologic characterization of multicentric or metastatic neoplasms with an extraocular origin in dogs and cats.", "abstract": "To characterize the frequency and distribution of secondary ocular neoplasms in dogs and cats identified during necropsy. A retrospective analysis of necropsy records of dogs and cats was conducted, and cases with metastatic/multicentric neoplasms with an extraocular origin, involving the eyes, were selected. From January 2015 to January 2019, we identified a total of 233 dogs and 100 cats with metastatic disease. Of these, 11.6% (27/233) of the dogs and 13% (13/100) of the cats had ocular metastases. Lymphoma was the most common multicentric neoplasm involving the eyes of both species. In dogs, these neoplasms occurred bilaterally, predominantly in the anterior uvea, and were diffuse large B-cell, T-lymphoblastic, peripheral T-cell not otherwise specified, and lymphocytic B-cell lymphomas. In cats, feline leukemia virus (FeLV)-associated T-cell lymphoma was the most common. Mammary carcinoma was the second most common ocular metastatic neoplasm in bitches, with a predominantly unilateral involvement of the uveal tract. In cats, following lymphoma, pulmonary and squamous cell carcinomas were the most common multicentric/metastatic neoplasms of the eyes. Individual cases of cholangiocarcinoma, hemangiosarcoma, and chemodectoma in dogs, as well as mammary gland cribriform carcinoma, salivary gland carcinoma, and histiocytic sarcoma in cats were detected. The eyes of dogs were mostly affected by lymphoma or mammary gland carcinoma, while those of cats mostly had lymphoma, pulmonary carcinoma, or squamous cell carcinoma as the main metastatic/multicentric neoplasm. To the best of our knowledge, this is the first study to identify intraocular metastatic cholangiocarcinoma and chemodectoma in dogs, aside from identifying salivary gland carcinoma in cats.", "journal": "Veterinary ophthalmology", "doi": "10.1111/vop.12803", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32680664", "author": "Hartmann K", "n_authors": 2, "title": "What's New in Feline Leukemia Virus Infection.", "abstract": "Feline leukemia virus (FeLV) is a retrovirus with global impact on the health of domestic cats that causes tumors (mainly lymphoma), bone marrow disorders, and immunosuppression. The importance of FeLV is underestimated due to complacency associated with previous decline in prevalence. However, with this comes lowered vigilance, which, along with potential for regressively infected cats to reactivate viremia and shed the virus or develop clinical signs, can pose a risk to feline health. This article summarizes knowledge on FeLV pathogenesis, courses of infection, and factors affecting prevalance, infection outcome, and development of FeLV-associated diseases, with special focus on regressive FeLV infection.", "journal": "The Veterinary clinics of North America. Small animal practice", "doi": "10.1016/j.cvsm.2020.05.006", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32626942", "author": "Gao W", "n_authors": 6, "title": "Long non‑coding RNA FLVCR1‑AS1 promotes glioma cell proliferation and invasion by negatively regulating miR‑30b‑3p.", "abstract": "Glioblastoma (GBM) is the most common and malignant primary brain tumor in adults that originates from glial cells. The prognosis of patients with high‑grade glioma is poor. It is therefore crucial to develop effective therapeutic strategies. Long non‑coding RNAs (lncRNAs) have been reported as potential inducers or suppressors of tumor progression. Previous studies have indicated that the lncRNA Feline Leukemia Virus Subgroup C Cellular Receptor 1 Antisense RNA 1 (FLVCR1‑AS1) is involved in the development and progression of gastric and lung cancer, as well as hepatocellular carcinoma and cholangiocarcinoma; however, the biological effect of FLVCR1‑AS1 in glioma is not completely understood. The aim of the present study was to investigate how FLVCR1‑AS1 modulates cell proliferation and invasion in glioma. FLVCR1‑AS1 expression was significantly upregulated in GBM tissues compared with adjacent normal brain samples, and was higher in GBM cell lines compared with normal human astrocyte cells. Furthermore, the microRNA (miR)‑30b‑3p was revealed to be a putative target of FLVCR1‑AS1, and the suppressive effects of miR‑30b‑3p on cellular proliferation and invasion were reversed following FLVCR1‑AS1‑knockdown. The results from Cell Counting Kit‑8 and Transwell assays confirmed that FLVCR1‑AS1‑knockdown inhibited GBM cell proliferation and invasion ability. In addition, FLVCR1‑AS1 was found to directly interact with miR‑30b‑3p, and a rescue experiment further established that FLVCR1‑AS1 contributed to glioma progression by inhibiting miR‑30b‑3p. The results from the present study demonstrated that FLVCR1‑AS1 may serve an oncogenic role in GBM and promote disease progression by interacting with miR‑30b‑3p. These findings suggested that FLVCR1‑AS1 may be considered as a novel therapeutic target and diagnostic biomarker for GBM.", "journal": "Molecular medicine reports", "doi": "10.3892/mmr.2020.11149", "deposited_data": "Sim", "nuccore_ids": "224591397, 224591396, 2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556, 262205236, 224591397, 224591396", "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32511839", "author": "Liu C", "n_authors": 13, "title": "Molecular and serological investigation of cat viral infectious diseases in China from 2016 to 2019.", "abstract": "In order to analyse the prevalence of cat viral diseases in China, including feline parvovirus (FPV), feline calicivirus (FCV), feline herpesvirus 1 (FHV-1), feline leukaemia virus (FeLV), feline immunodeficiency virus (FIV) and feline infectious peritonitis virus (FIPV), a total of 1,326 samples of cats from 16 cities were investigated from 2016 to 2019. Collectively, 1,060 (79.9%) cats were tested positive for at least one virus in nucleotide detection, and the positive rates of cat exposure to FeLV, FPV, FHV-1, FCV, FIV and FIPV were 59.6%, 19.2%, 16.3%, 14.2%, 1.5% and 0.5%, respectively. The prevalence of FHV-1 and FPV was dominant in winter and spring. Cats from north China showed a higher positive rate of viral infection than that of cats from south China. The virus infection is not highly correlated with age, except that FPV is prone to occur within the age of 12 months. In the serological survey, the seroprevalences of 267 vaccinated cats to FPV, FCV and FHV-1 were 83.9%, 58.3% and 44.0%, respectively. Meanwhile, the seroprevalences of 39 unvaccinated cats to FPV, FCV and FHV-1 were 76.9% (30/39), 82.4% (28/34) and 58.6% (17/29), respectively. This study demonstrated that a high prevalence of the six viral diseases in China and the insufficient serological potency of FCV and FHV-1 remind the urgency for more effective vaccines.", "journal": "Transboundary and emerging diseases", "doi": "10.1111/tbed.13667", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32450457", "author": "Duda NCB", "n_authors": 10, "title": "Laboratory and clinical findings and their association with viral and proviral loads in cats naturally infected with feline leukemia virus.", "abstract": "This study was conducted to correlate clinical, laboratory, and bone marrow (BM) changes in cats naturally infected with feline leukemia virus and their association with viral loads in blood and BM and proviral loads in BM. Cats were classified into five groups based on antigenemia, clinical and/or laboratory findings and viral/proviral loads, according to a prospective study: symptomatic progressive (GI); asymptomatic progressive (GII); regressive (GIII); unclassified (GIV); or healthy (GV). |Correlations between these five groups and viral/proviral loads were evaluated. High viral and proviral loads were detected in GI and GII and viral loads were significantly associated with laboratory signs. Proviral loads detected in BM were significantly lower in GIII and GIV. GI cats were more likely to develop hematopoietic disorders than those from the other groups. Hematological and clinical disorders and disease severity are related to higher viral blood and proviral BM loads.", "journal": "Comparative immunology, microbiology and infectious diseases", "doi": "10.1016/j.cimid.2020.101491", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32448817", "author": "Tagawa M", "n_authors": 8, "title": "Acute monoblastic leukemia in a feline leukemia virus-negative cat.", "abstract": "A 12-year-old female domestic short-haired cat was presented due to weight loss, anorexia, and tachypnea. Complete blood count revealed severe anemia, leukocytosis with massive undifferentiated blast cells, and thrombocytopenia. Bone marrow aspiration showed acute myeloid leukemia, subclassified as monoblastic leukemia (M5a) based on the outcomes of the cytochemistry examinations. The SNAP feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) test using whole blood was negative. In addition, FeLV/FIV proviral polymerase chain reaction test using bone marrow aspirate was also negative. Although the cat was treated with doxorubicin, cytosine arabinoside, and prednisolone, anemia did not improve without blood transfusion. The owner declined further treatment after 2 months, and the cat died a few days later.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.20-0157", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32448520", "author": "Akhtardanesh B", "n_authors": 7, "title": "Leishmania infection in cats positive for immunodeficiency virus and feline leukemia virus in an endemic region of Iran.", "abstract": null, "journal": "Veterinary parasitology, regional studies and reports", "doi": "10.1016/j.vprsr.2020.100387", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32409536", "author": "Chin PJ", "n_authors": 4, "title": "Complete Genome Sequence of Feline Leukemia Virus Kawakami-Theilen Strain KT-FeLV-UCD-1.", "abstract": "This full-length genome sequence of a feline leukemia virus Kawakami-Theilen strain (designated KT-FeLV-UCD-1), produced from the chronically infected FL74-UCD-1 cell line, was obtained using high-throughput sequencing. It consisted of 8,464 bp and had a genomic organization similar to that of other gammaretroviruses, containing long terminal repeats and open reading frames for Gag, Pol, and Env.", "journal": "Microbiology resource announcements", "doi": "10.1128/MRA.00233-20", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32338565", "author": "Lockhart HL", "n_authors": 5, "title": "Outcome of cats referred to a specialized adoption program for feline leukemia virus-positive cats.", "abstract": "The purpose of this retrospective study was to assess outcomes of cats referred to a specialized adoption program for feline leukemia virus (FeLV)-positive cats. Cats referred to an FeLV-specific adoption program between January 2018 and July 2019 at an animal shelter in Austin, TX, USA, were first identified based on their putative FeLV status as reported by the referring shelter, rescue group, veterinarian or individual. Each cat was re-screened for FeLV upon admission and subsequently deemed infected or uninfected. Data on cat source, admission date, outcome date, outcome type, signalment and comorbidities at the time of admission were extracted from the shelter database. Outcomes were recorded up to 15 December 2019. In total, 801 cats suspected to be infected with FeLV were referred to the FeLV adoption program. Of these, 149 (18.6%) were ultimately deemed uninfected, and infection was confirmed in 652 (81.4%) cats. Adoption was the most common outcome for FeLV-infected cats (n = 514 cats; 78.8%), followed by euthanasia or death in care (n = 109; 16.7%). Upper respiratory infection (URI) was the most common comorbidity in FeLV-infected cats (n = 106; 16.3%) at the time of admission, which was not significantly different than URI in the cats that were deemed not to be infected with FeLV (n = 29; 19.5%). This study demonstrated high national demand for a lifesaving option for cats diagnosed with FeLV. FeLV infections could not be confirmed in approximately one in five cats referred to the FeLV adoption program, a reminder of the risk behind basing the fate of a cat on a single positive test result. The majority of cats referred to the FeLV program were adopted, demonstrating that programs centered on adopter education and post-adoption support can create lifesaving outcomes for most FeLV-infected cats, despite uncertainty regarding their long-term prognosis.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X20913359", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32325926", "author": "Ortega C", "n_authors": 4, "title": "Prevalence and Genomic Diversity of Feline Leukemia Virus in Privately Owned and Shelter Cats in Aburrá Valley, Colombia.", "abstract": "The feline leukemia virus (FeLV) belongs to the family Retroviridae; it is the first feline retrovirus discovered and one of the agents that has a great impact on cats' health and the ecology of the feline population worldwide. It is associated with the occurrence of several syndromes of fatal diseases, including the development of lymphomas. Studies on FeLV have been reported in Colombia, and most of them have been approached from a clinical point of view. However, only a few studies have focused on the prevalence of the infection, while none have clarified which variant or FeLV viral subgroup is presently circulating in our country. Therefore, the present study investigated the prevalence of the infection associated with the molecular characterization of FeLV present in cats in Aburrá Valley, Colombia. The sampling of privately owned and shelter cats was performed in female (", "journal": "Viruses", "doi": "10.3390/v12040464", "deposited_data": "Sim", "nuccore_ids": "1839276573, 1839276571, 1839276569, 1839276567, 1839276565, 1839276563, 1839276561, 1839276559, 1839276557, 1839276555, 1839276553, 1839276551, 1839276549, 1839276547, 1839276545, 1839276543, 1839276541, 1839276539, 1839276537, 1839276535, 1839276533, 1839276531, 1839276529, 1839276527, 1839276525, 1839276523, 1839276521, 1839276519, 1839276517, 1839276515", "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32312323", "author": "Latrofa MS", "n_authors": 12, "title": "A molecular survey of vector-borne pathogens and haemoplasmas in owned cats across Italy.", "abstract": "Feline vector-borne pathogens (FeVBPs) have been increasingly investigated for their impact on cat health and their zoonotic potential. The aim of the present study was to assess the prevalence of FeVBPs and haemoplasmas in cats across Italy and to identify potential risk factors linked to their occurrence. Blood samples from 958 owned cats living in the North (n = 556), Centre (n = 173) and South (n = 229) of Italy were tested for Babesia spp., Hepatozoon spp., Ehrlichia spp., Anaplasma spp. and filarioids by conventional PCR (cPCR) and for haemoplasmas and Bartonella spp. by SYBR green real-time PCR. Cats included in the study represent a sub-sample from a larger number of animals enrolled in a previous study, which were selected based on the geographical origin. Data on cats' positivity for Leishmania infantum, feline leukaemia virus (FeLV) and for feline immunodeficiency virus (FIV), available from the previous study, were included and examined. Potential risk factors for pathogen infection were assessed in relationship to categorical variables including sex, geographical origin, breed, neutering status and age of cats. Out of the 958 cats, 194 (20.2%) were positive for at least one of the tested pathogens, 89 (16%) from the North, 32 (18.5%) from the Centre and 73 (31.9%) from the South of Italy. A high prevalence of FeVBPs was detected in male cats (n = 125, 27.8%), living in the southern part of the country (n = 73, 31.9%), younger than 18 months of age (n = 24, 22.4%) and not neutered (n = 39; 27.5%). In particular, 24 cats (2.5%) tested PCR-positive for Bartonella spp., of which 1.6% for B. henselae and 0.9% for B. clarridgeiae. A total of 111 cats scored PCR-positive for haemoplasmas (11.6%), specifically \"Candidatus Mycoplasma haemominutum\" (n = 95, 9.9%), M. haemofelis (n = 14, 1.5%) and \"Candidatus Mycoplasma turicensis\" (n = 2, 0.2%). Moreover, 39, 31 and 8 cats were positive for FeLV (4.1%), L. infantum (3.2%) and FIV (0.8%), respectively. Co-infections were registered for 19 (9.8%) cats. These results confirm the occurrence of haemoplasmas and FeVBPs throughout Italy. Preventive measures to protect both animal and human health should be carried out also for owned cats, even if no health status of animals has been assessed in this study.", "journal": "Parasites & vectors", "doi": "10.1186/s13071-020-3990-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32278001", "author": "Chiabrando D", "n_authors": 6, "title": "Expression and purification of the heme exporter FLVCR1a.", "abstract": "With many crucial roles in enzymatic aerobic metabolism, the concentration of the heme must be tightly regulated. The heme exporter Feline Leukemia Virus sub-group C Receptor 1a (FLVCR1a), an integral membrane protein with twelve transmembrane helices, is a key player in the maintenance of cellular heme homeostasis. It was first identified as the host receptor for the Feline Leukemia Virus sub-group C (FeLV-C), a retrovirus causing hematological abnormalities in cats and other felines. Mutations in the Flvcr1 were later identified in human patients affected by Posterior Column Ataxia and Retinitis Pigmentosa (PCARP) and Hereditary Sensory and Autonomic Neuropathies (HSANs). Despite being an essential component in heme balance, currently there is a lack in the understanding of its function at the molecular level, including the effect of disease-causing mutations on protein function and structure. Therefore, there is a need for protocols to achieve efficient recombinant production yielding milligram amounts of highly pure protein to be used for biochemical and structural studies. Here, we report the first FLVCR1a reliable protocol suitable for both antibody generation and structural characterisation.", "journal": "Protein expression and purification", "doi": "10.1016/j.pep.2020.105637", "deposited_data": "Sim", "nuccore_ids": "924181778, 924181484, 124486924", "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32274976", "author": "Szilasi A", "n_authors": 9, "title": "In situ hybridization of feline leukemia virus in a primary neural B-cell lymphoma.", "abstract": "An 8-y-old castrated male, outdoor European shorthair cat was presented with a history of hindlimb weakness and paralysis. Disease progression was continuous from the onset; deep algesia disappeared at the final stage. Radiography of the vertebral column was unremarkable; along with patient history and physical examination results, magnetic resonance imaging suggested inflammatory lesions in the spinal cord, although neoplasia could not be ruled out. Feline leukemia virus (FeLV) positivity was confirmed by a serum ELISA prior to euthanasia. Upon postmortem examination, hemorrhages were present in the spinal cord at the level of vertebrae T7-8. Histologic and immunohistochemical analysis revealed primary diffuse large B-cell lymphoma of the spinal cord with multifocal myelomalacia and hemorrhages. To determine the presence of a pathogen within the lesion, we developed a novel in situ hybridization protocol for FeLV (RNAscope). The reaction revealed large amounts of FeLV viral RNA in the tumor cells.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/1040638720915449", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32232857", "author": "White ME", "n_authors": 4, "title": "Fibrosarcoma with sarcomatosis and metastasis in a FeLV-negative cat.", "abstract": "A 6-year-old, spayed female, mixed shorthair cat presented to the emergency service at The Ohio State University Veterinary Medical Center for evaluation of hypercalcemia, a right eye mass, and multiple intrathoracic and intra-abdominal masses. Cytologic evaluation of one of the abdominal masses revealed a uniform population of large, anaplastic mesenchymal cells found individually, in loose aggregates, and occasionally associated with pink, extracellular matrix. The cytology was consistent with a malignant mesenchymal neoplasm, with primary consideration given to fibrosarcoma and hemangiosarcoma. The cat was euthanized and histopathology confirmed disseminated fibrosarcoma. Fibrosarcoma comprises 12%-41% of feline cutaneous tumors and affects cats at a mean age of 9.6 years. Three manifestations of fibrosarcoma predominate in cats: spontaneous solitary fibrosarcoma, vaccine-induced/injection site fibrosarcoma, and oncogene-induced (FSV) fibrosarcoma. The history, signalment, and results from diagnostics performed did not support solitary fibrosarcoma or injection-induced sarcoma. Although some criteria fit with virally induced fibrosarcoma, such as age and the presence of multiple fibrosarcomas, the neoplastic population was negative for FeLV IHC. The presence of fibrosarcomas throughout the pleural and peritoneal cavity was most compatible with sarcomatosis and the distant metastasis of an unidentified primary neoplasm. To the authors' knowledge, this is the first reported case of sarcomatosis in a FeLV-negative cat.", "journal": "Veterinary clinical pathology", "doi": "10.1111/vcp.12842", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32227347", "author": "Day MJ", "n_authors": 4, "title": "Recommendations on vaccination for Latin American small animal practitioners: a report of the WSAVA Vaccination Guidelines Group.", "abstract": "The World Small Animal Veterinary Association Vaccination Guidelines Group has produced global guidelines for small companion animal practitioners on best practice in canine and feline vaccination. Recognising that there are unique aspects of veterinary practice in certain geographical regions of the world, the Vaccination Guidelines Group undertook a regional project in Latin America between 2016 and 2019, culminating in the present document. The Vaccination Guidelines Group gathered scientific and demographic data during visits to Argentina, Brazil and Mexico, by discussion with national key opinion leaders, visiting veterinary practices and review of the scientific literature. A questionnaire survey was completed by 1390 veterinarians in five Latin American countries and the Vaccination Guidelines Group delivered continuing education at seven events attended by over 3500 veterinarians. The Vaccination Guidelines Group recognised numerous challenges in Latin America, for example: (1) lack of national oversight of the veterinary profession, (2) extraordinary growth in private veterinary schools of undetermined quality, (3) socioeconomic constraints on client engagement with preventive health care, (4) high regional prevalence of some key infectious diseases (e.g. feline leukaemia virus infection, canine visceral leishmaniosis), (5) almost complete lack of minimal antigen vaccine products as available in other markets, (6) relative lack of vaccine products with extended duration of immunity as available in other markets, (7) availability of vaccine products withdrawn from other markets (e.g. Giardia vaccine) or unique to Latin America (e.g. some Leishmania vaccines), (8) accessibility of vaccines directly by pet owners or breeders such that vaccination is not delivered under veterinary supervision, (9) limited availability of continuing education in veterinary vaccinology and lack of compulsion for continuing professional development and (10) limited peer-reviewed published scientific data on small companion animal infectious diseases (with the exception of leishmaniosis) and lack of support for such academic research. In this document, the Vaccination Guidelines Group summarises the findings of this project and assesses in evidence-based fashion the scientific literature pertaining to companion animal vaccine-preventable diseases in Latin America. The Vaccination Guidelines Group makes some recommendations on undergraduate and postgraduate education and academic research. Recognising that current product availability in Latin America does not permit veterinarians in these countries to vaccinate according to the global World Small Animal Veterinary Association guidelines, the Vaccination Guidelines Group makes a series of \"pragmatic\" recommendations as to what might be currently achievable, and a series of \"aspirational\" recommendations as to what might be desirable for the future. The concept of \"vaccine husbandry\" is addressed via some simple guidelines for the management of vaccine products in the practice. Finally, the Vaccination Guidelines Group emphasises the global trend towards delivery of vaccination as one part of an \"annual health check\" or \"health care plan\" that reviews holistically the preventive health care needs of the individual pet animal. Latin American practitioners should transition towards these important new practices that are now well embedded in more developed veterinary markets. The document also includes 70 frequently asked questions and their answers; these were posed to the Vaccination Guidelines Group during our continuing education events and small group discussions and should address many of the issues surrounding delivery of vaccination in the Latin American countries. Spanish and Portuguese translations of this document will be made freely available from the on-line resource pages of the Vaccination Guidelines Group.", "journal": "The Journal of small animal practice", "doi": "10.1111/jsap.13125", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32095258", "author": "Combarros D", "n_authors": 5, "title": "Clinical and histological recovery of non-thymoma-associated exfoliative dermatitis in a cat treated with ciclosporin A.", "abstract": "A 6-year-old neutered female European Shorthair cat was referred for chronic, moderately pruritic, alopecic and exfoliative dermatosis that was unresponsive to antiparasitic, antibiotic or steroidal anti-inflammatory drugs. The cat presented with truncular alopecia and numerous whitish adherent scales covering the whole body. Differential diagnoses included sebaceous adenitis, dermatophytosis, demodicosis, exfoliative dermatitis associated or not with thymoma, drug reaction, feline immunodeficiency virus- or feline leukaemia virus-associated dermatoses, epitheliotropic T-cell lymphoma, and  T-cell infiltration with signs of epidermal cytotoxicity, in the absence of infectious agents or neoplastic process, suggests an immune-mediated process, and ciclosporin A, a calcineurin inhibitor, would be the drug of choice. This is the first report showing resolution of both the clinical and histological signs of non-thymoma-associated exfoliative dermatitis.", "journal": "JFMS open reports", "doi": "10.1177/2055116920902307", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "31961273", "author": "Persky ME", "n_authors": 6, "title": "Tick paralysis in a free-ranging bobcat (Lynx rufus).", "abstract": "A free-ranging male bobcat ( Physical examination of the anesthetized animal revealed tick infestation, normal mentation, and a lack of evidence of traumatic injuries. Radiography revealed no clinically relevant abnormalities. Hematologic analysis results were generally unremarkable, and serologic tests for exposure to feline coronavirus, FeLV, FIV, and  Ticks were manually removed, and the patient received supportive care and fipronil treatment. The bobcat made a full recovery within 72 hours after treatment for ticks, and a presumptive diagnosis of tick paralysis was made. Identified tick species included  To the authors' knowledge, tick paralysis has not previously been reported in felids outside Australia. This disease should be considered a differential diagnosis in felids, including exotic cats, with signs of neuromuscular disease of unknown etiopathogenesis.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.256.3.362", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "31916872", "author": "Little S", "n_authors": 7, "title": "2020 AAFP Feline Retrovirus Testing and Management Guidelines.", "abstract": "Feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) infections are found in cats worldwide. Both infections are associated with a variety of clinical signs and can impact quality of life and longevity. This document is an update of the 2008 American Association of Feline Practitioners' feline retrovirus management guidelines and represents current knowledge on pathogenesis, diagnosis, prevention and treatment of retrovirus infections in cats. Although vaccines are available for FeLV in many countries and for FIV in some countries, identification of infected cats remains an important factor for preventing new infections. The retrovirus status of every cat at risk of infection should be known. Cats should be tested as soon as possible after they are acquired, following exposure to an infected cat or a cat of unknown infection status, prior to vaccination against FeLV or FIV, and whenever clinical illness occurs. It might not be possible to determine a cat's infection status based on testing at a single point in time; repeat testing using different methods could be required. Although FeLV and FIV infections can be associated with clinical disease, some infected cats, especially those infected with FIV, can live for many years with good quality of life. There is a paucity of data evaluating treatments for infected cats, especially antiretroviral and immunomodulatory drugs. Management of infected cats is focused on effective preventive healthcare strategies, and prompt identification and treatment of illness, as well as limiting the spread of infection.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X19895940", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "31748326", "author": "Victor RM", "n_authors": 7, "title": "Molecular Detection of Feline Leukemia Virus in Oral, Conjunctival, and Rectal Mucosae Provides Results Comparable to Detection in Blood.", "abstract": "Feline leukemia virus (FeLV) infection causes immunosuppression, degeneration of the hematopoietic system, and fatal neoplasms. FeLV transmission occurs mainly by close social contact of infected and susceptible cats. Developing procedures for the diagnosis of feline retroviruses is crucial to reduce negative impacts on cat health and increase the number of animals tested. Blood collection requires physical or chemical restraint and is usually a stressful procedure for cats. Our objective was to evaluate the use of samples obtained from oral, conjunctival, and rectal mucosae for the molecular diagnosis of FeLV. Whole blood and oral, conjunctival, and rectal swabs were collected from a total of 145 cats. All samples were subjected to the amplification of a fragment of the ", "journal": "Journal of clinical microbiology", "doi": "10.1128/JCM.01233-19", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "31683165", "author": "Chiu ES", "n_authors": 4, "title": "A novel test for determination of wild felid-domestic cat hybridization.", "abstract": "In October 2018, Colorado Parks and Wildlife seized an animal believed to be an illegally possessed bobcat. The owner claimed the animal was a bobcat/domestic cat hybrid, exempted from license requirements. Burden of proof lay with CPW to determine the lineage of the animal. Commercial microsatellite arrays and DNA barcoding have not been developed for identification of bobcat/domestic cat hybrids, and limited time and resources prevented development of such tests for this application. Instead, we targeted endogenous feline leukemia virus (enFeLV) to quickly and inexpensively demonstrate the absence of domestic cat DNA in the contested animal. Using this assay, we were able to confirm that the contested animal lacked enFeLV, and therefore was not a domestic cat hybrid.", "journal": "Forensic science international. Genetics", "doi": "10.1016/j.fsigen.2019.102160", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "31461200", "author": "Leite-Filho RV", "n_authors": 9, "title": "Epidemiological, pathological and immunohistochemical aspects of 125 cases of feline lymphoma in Southern Brazil.", "abstract": "A retrospective study compiling cases of feline lymphoma diagnosed during 12 years (2004-2016) in Southern Brazil was performed. A total of 125 cases of lymphoma diagnosed in cats were reviewed, and information including age, breed, sex and tumour topography were collected. FeLV and FIV immunohistochemical tests were performed, as well as immunophenotyping of lymphomas. The alimentary form represented the most common presentation (42/125), followed by mediastinal lymphoma (35/125). Out of 125 cases, 79 presented positive retroviral immunostaining in tumour tissue (52 FeLV alone, 14 FIV alone and 13 presented FIV and FeLV co-infections), 66/125 of the cases were of T-cell origin and 59/125 of the cases were of B-cell origin. The median age of cats with T-cell lymphoma was 120 months (10-240 months), and 60 months (6-204 months) for cats with B-cell lymphoma. The most frequent alimentary tumour presentation was the enteropathy-associated T-cell lymphoma (type 1), and the major type of mediastinal tumour observed was diffuse large B-cell lymphoma. Considering only mediastinal and alimentary lymphomas (n = 77), the prevalence of mediastinal lymphoma in FeLV-positive cats was 2.21 times higher than the prevalence of this type of tumour in FeLV-negative cats (P = .036). Mediastinal lymphoma was more frequently observed in younger cats, and the prevalence of mediastinal tumours in these animals was 3.06 times higher than the prevalence of this tumour form in old cats (P = .0125). The present study indicates that retroviral infections still play an important role in the development of feline lymphomas in southern Brazil.", "journal": "Veterinary and comparative oncology", "doi": "10.1111/vco.12535", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "30994392", "author": "MaloneyHuss MA", "n_authors": 5, "title": "Efficacy and toxicity of mustargen, vincristine, procarbazine and prednisone (MOPP) for the treatment of relapsed or resistant lymphoma in cats.", "abstract": "The aims of this study were to evaluate the safety of mustargen, vincristine, procarbazine and prednisone (MOPP) chemotherapy in the treatment of relapsed or refractory feline lymphoma, and to determine the overall response rate and median remission time with this protocol. The medical records of 38 cats with relapsed or refractory lymphoma treated with MOPP chemotherapy at three institutions (University of Pennsylvania, the Animal Medical Center, and VCA Western Veterinary Specialist and Emergency Centre) were examined. Information evaluated included patient signalment, feline immunodeficiency virus/feline leukemia virus status, anatomic location(s) of lymphoma, prior protocols (type and number), MOPP doses, MOPP response, remission duration, hematologic and biochemical parameters, and owner-reported adverse effects. Overall, 70.3% of cats responded to MOPP chemotherapy. Among the responders, the median remission duration was 166 days. The most common adverse effects were neutropenia and gastrointestinal upset, which were reported in 18.4% of cats. In 55.3% of cats, no adverse effects were reported. In total, 30.8% of responders continued to respond 6 months following the initiation of MOPP, and 15.4% maintained a response 1 year after starting MOPP. MOPP is a safe protocol for the treatment of relapsed or refractory feline lymphoma, with a promising overall response rate and median remission time.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X19841916", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "30942657", "author": "Mallol C", "n_authors": 6, "title": "CT characterisation of feline adrenal glands.", "abstract": "The objectives of this study were to describe the CT characteristics of the adrenal glands in healthy cats, to provide normal reference biometry for adrenal gland size and attenuation values, and to investigate the association with age, sex, laterality and body weight. Retrospective evaluation of 30 CT studies of healthy adult cats recruited from September 2013 to July 2015 was performed. Healthy cats >1 year of age were included based on the absence of clinical signs, unremarkable physical examination, normal results of the complete blood count, biochemical profile, feline immunodeficiency virus, feline leukaemia virus and  Twenty-seven cats were included. Bilobed, arrowhead and oval adrenal gland shape patterns were recognised, the first being most common. No statistically significant differences were observed between the biometric parameters (length, height and attenuation values) and age, sex,  Adrenal gland shape, size and attenuation CT data of healthy feline patients are provided in this study, as well as normal reference intervals for morphometric characterisation based on adrenal length and height.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X19840090", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34970620", "author": "Aeluro S", "n_authors": 4, "title": "\"State of the Mewnion\": Practices of Feral Cat Care and Advocacy Organizations in the United States.", "abstract": "Over the last several decades, feral cats have moved from the fringes to the mainstream in animal welfare and sheltering. Although many best practice guidelines have been published by national non-profits and veterinary bodies, little is known about how groups “in the trenches” actually operate. Our study sought to address that gap through an online survey of feral cat care and advocacy organizations based in the United States. Advertised as “The State of the Mewnion,” its topics included a range of issues spanning non-profit administration, public health, caretaking and trapping, adoptions of friendly kittens and cats, veterinary medical procedures and policies, data collection and program efficacy metrics, research engagement and interest, and relationships with wildlife advocates and animal control agencies. Respondents from 567 organizations participated, making this the largest and most comprehensive study on this topic to date. Respondents came primarily from grassroots organizations. A majority reported no paid employees (74.6%), served 499 or fewer feral cats per year (75.0%), engaged between 1 and 9 active volunteers (54.9%), and did not operate a brick and mortar facility (63.7%). Some of our findings demonstrate a shared community of practice, including the common use of a minimum weight of 2.0 pounds for spay/neuter eligibility, left side ear tip removals to indicate sterilization, recovery holding times after surgery commonly reported as 1 night for male cats and 1 or 2 nights for females, requiring or recommending to adopters of socialized kittens/cats that they be kept indoor-only, and less than a quarter still engaging in routine testing of cats for FIV and FeLV. Our survey also reveals areas for improvement, such as most organizations lacking a declared goal with a measurable value and a time frame, only sometimes scanning cats for microchips, and about a third not using a standardized injection site for vaccines. This study paints the clearest picture yet available of what constitutes the standard practices of organizations serving feral and community cats in the United States.", "journal": "Frontiers in veterinary science", "doi": "10.3389/fvets.2021.791134", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34944329", "author": "Denner J", "n_authors": 1, "title": "Vaccination against the Koala Retrovirus (KoRV): Problems and Strategies.", "abstract": "The koala retrovirus (KoRV) is spreading in the koala population from the north to the south of Australia and is also in the process of endogenization into the koala genome. Virus infection is associated with tumorigenesis and immunodeficiency and is contributing to the decline of the animal population. Antibody production is an excellent marker of retrovirus infection; however, animals carrying endogenous KoRV are tolerant. Therefore, the therapeutic immunization of animals carrying endogenous KoRV seems to be ineffective. Using the recombinant transmembrane (TM) envelope protein of the KoRV, we immunized goats, rats and mice, obtaining in all cases neutralizing antibodies which recognize epitopes in the fusion peptide proximal region (FPPR), and in the membrane-proximal external region (MPER). Immunizing several animal species with the corresponding TM envelope protein of the closely related porcine endogenous retrovirus (PERV), as well as the feline leukemia virus (FeLV), we also induced neutralizing antibodies with similar epitopes. Immunizing with the TM envelope protein in addition to the surface envelope proteins of all three viruses resulted in higher titers of neutralizing antibodies. Immunizing KoRV-negative koalas with our vaccine (which is composed of both envelope proteins) may protect these animals from infection, and these may be the starting points of a virus-free population.", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani11123555", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34903942", "author": "de Carvalho OV", "n_authors": 5, "title": "Retrospective surveillance of severe acute respiratory syndrome coronavirus 2 in pets from Brazil.", "abstract": "The emerging concerns regarding the new Coronavirus's ability to cause infection in pets has led to animal testing and worrisome findings reported all over the world in domesticated and wild animals. This study aimed to investigate severe acute respiratory syndrome coronavirus (SARS-CoV)-2 by quantitative reverse transcription-polymerase chain reaction in dog and cat samples with the clinical presentation for respiratory or gastrointestinal disease in Brazil. One hundred and twenty-five samples were collected from 12 states of Brazil that originated from the gastrointestinal, upper respiratory tract, and other sites, including some pools of samples from before the onset of the pandemic including blood and/or urine samples. They were tested for RT-PCR detection of respiratory or gastrointestinal pathogens through Respiratory or Diarrhea RT-PCR Panels in the TECSA (Tecnologia em Saninade Animal - Animal Health Technology) Veterinary Medicine Laboratory. This work was conducted in compliance with ethical standards. Seven different microorganisms that can cause respiratory and/or gastrointestinal clinical signs were detected in cats (Feline Coronavirus [FCoV], Feline Parvovirus, Feline Leukemia Virus, Feline Calicivirus,  Although the samples corresponded to the beginning of coronavirus disease-19 spread in Brazil and clinically correlated with the expected viral replication sites, none of the animals tested positive for SARS-CoV-2; reassuringly, four cats tested positive or FCoV none of them were positive for SARS-CoV2. The epidemiological surveillance of SARS-CoV-2 in pets is considered a one health issue, important for monitoring the disease evolution, spread and minimizing the animal-human health impacts, and directing Public Health Policies.", "journal": "Veterinary world", "doi": "10.14202/vetworld.2021.2803-2808", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34886987", "author": "Slaviero M", "n_authors": 8, "title": "Causes and Lesions of Fatal Pneumonia in Domestic Cats.", "abstract": "Pneumonia in cats may cause severe lung injury and consequent death. We describe the post-mortem findings and aetiologies of naturally fatal pneumonia in 78 domestic cats, using gross and histopathological examinations, immunohistochemistry and microbiological techniques. Morphological patterns found were bronchopneumonia (27/78), interstitial (15/78), bronchointerstitial (13/78), granulomatous (8/78), aspiration (8/78) and pyogranulomatous (5/78) pneumonia, and pleuropneumonia (2/78). Bacterial pneumonia was identified as the most common cause (32/78), followed by viral (15/28 feline calicivirus, 10/28 felid alphaherpesvirus 1 and 3/28 both viruses), aspiration (8/78), fungal (5/78) and parasitic pneumonia (5/78). Co-infection with feline immunodeficiency virus and feline leukaemia virus was found in 54 cats. Viral infections involved cats of all ages, indicating the importance of investigating viral causes in cats with respiratory diseases, including in adult and ageing cats.", "journal": "Journal of comparative pathology", "doi": "10.1016/j.jcpa.2021.09.005", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34829786", "author": "Petrillo S", "n_authors": 13, "title": "Endothelial Heme Dynamics Drive Cancer Cell Metabolism by Shaping the Tumor Microenvironment.", "abstract": "The crosstalk among cancer cells (CCs) and stromal cells within the tumor microenvironment (TME) has a prominent role in cancer progression. The significance of endothelial cells (ECs) in this scenario relies on multiple vascular functions. By forming new blood vessels, ECs support tumor growth. In addition to their angiogenic properties, tumor-associated ECs (TECs) establish a unique vascular niche that actively modulates cancer development by shuttling a selected pattern of factors and metabolites to the CC. The profile of secreted metabolites is strictly dependent on the metabolic status of the cell, which is markedly perturbed in TECs. Recent evidence highlights the involvement of heme metabolism in the regulation of energy metabolism in TECs. The present study shows that interfering with endothelial heme metabolism by targeting the cell membrane heme exporter Feline Leukemia Virus subgroup C Receptor 1a (FLVCR1a) in TECs, resulted in enhanced fatty acid oxidation (FAO). Moreover, FAO-derived acetyl-CoA was partly consumed through ketogenesis, resulting in ketone bodies (KBs) accumulation in FLVCR1a-deficient TECs. Finally, the results from this study also demonstrate that TECs-derived KBs can be secreted in the extracellular environment, inducing a metabolic rewiring in the CC. Taken together, these data may contribute to finding new metabolic vulnerabilities for cancer therapy.", "journal": "Biomedicines", "doi": "10.3390/biomedicines9111557", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34828037", "author": "Silva M", "n_authors": 4, "title": "A Case Series Analysis of Dental Extractions' Outcome in Cats with Chronic Gingivostomatitis Carrying Retroviral Disease.", "abstract": "This study aims to evaluate and compare the clinical outcome after dental extractions of cats with FCGS infected with feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV). A retrospective case series included cats with diagnosis of FCGS, availability of detailed clinical records, full-mouth dental radiographs, and retroviral disease test results. Effectiveness of surgical treatment (EOT) was registered. Three groups were defined: control, FIV and FeLV. In this study, 111 cats were included: 60 controls, 29 FIV- and 22 FeLV-positive cats. When compared with control cases, FeLV-positive cats had significantly less proliferative stomatitis lesions, and they tended to have more lingual ulcers. Concurrently, FeLV-positive cats had significantly less tooth resorptive lesions. No other significant differences in FCGS clinical signs were found between groups. FeLV-positive cats had a significantly worse outcome after dental extractions compared to the other groups. In fact, FeLV-positive cats had 7.5 times more chances of having no improvement after dental extractions. This study concludes that the response to dental extractions in FeLV-positive cats is significantly worse, when comparing to cats that do not carry retroviral disease. Therefore, it is important to acknowledge the effect of FeLV status on the prognosis of these cats.", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani11113306", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34794005", "author": "Feitosa TF", "n_authors": 8, "title": "High rate of feline immunodeficiency virus infection in cats in the Brazilian semiarid region: Occurrence, associated factors and coinfection with Toxoplasma gondii and feline leukemia virus.", "abstract": "To evaluate the occurrence of feline immunodeficiency virus (FIV) and factors associated with this and to demonstrate occurrences of coinfection with Toxoplasma gondii and feline leukemia virus (FeLV) in cats, a total of 103 blood samples were collected from owned cats, during home visits. To diagnose FIV and FeLV, immunochromatographic kit was used and serological diagnoses of T. gondii, the indirect immunofluorescence test was performed. The occurrence of FIV-seropositive cats was 23.3% (24/103) and the factor associated with infection was male sex. T. gondii seropositivity of 53.4% (55/103) was observed and 75% of FIV cases (18/24) were positive for T. gondii coinfection. Only 0.9% (1/103) was positive for FeLV. It can be concluded that the seroprevalence of FIV in cats in the Brazilian semiarid region is high and that FIV positive cats were also likely to be T. gondii seropositive, while FeLV had very low occurrence in the study region.", "journal": "Comparative immunology, microbiology and infectious diseases", "doi": "10.1016/j.cimid.2021.101718", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34764397", "author": "Lacharoje S", "n_authors": 3, "title": "Rapid characterization of feline leukemia virus infective stages by a novel nested recombinase polymerase amplification (RPA) and reverse transcriptase-RPA.", "abstract": "Feline leukemia virus (FeLV) is a major viral disease in cats, causing leukemia and lymphoma. The molecular detection of FeLV RNA and the DNA provirus are important for staging of the disease. However, the rapid immunochromatographic assay commonly used for antigen detection can only detect viremia at the progressive stage. In this study, nested recombinase polymerase amplification (nRPA) was developed for exogenous FeLV DNA provirus detection, and reverse transcriptase polymerase amplification (RT-RPA) was developed for the detection of FeLV RNA. The approaches were validated using 108 cats with clinicopathologic abnormalities due to FeLV infection, and from 14 healthy cats in a vaccination plan. The nRPA and RT-RPA assays could rapidly amplify the FeLV template, and produced high sensitivity and specificity. The FeLV detection rate in regression cats by nRPA was increased up to 45.8% compared to the rapid immunochromatographic assay. Hence, FeLV diagnosis using nRPA and RT-RPA are rapid and easily established in low resource settings, benefiting FeLV prognosis, prevention, and control of both horizontal and vertical transmission.", "journal": "Scientific reports", "doi": "10.1038/s41598-021-01585-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34686385", "author": "Galdo Novo S", "n_authors": 4, "title": "[Erratum to «Viral diagnostic criteria for Feline immunodeficiency virus and Feline leukemia virus infections in domestic cats from Buenos Aires, Argentina» [Rev Argent Microbiol. 2016;48(4):293-297]].", "abstract": null, "journal": "Revista Argentina de microbiologia", "doi": "10.1016/j.ram.2021.09.002", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34679045", "author": "Elmahallawy EK", "n_authors": 7, "title": "Feline Leishmaniosis in Northwestern Italy: Current Status and Zoonotic Implications.", "abstract": "Leishmaniasis remains one of the major neglected tropical diseases. The epidemiological profile of the disease comprises a wide range of hosts, including dogs and cats. Despite several studies about feline Leishmaniosis, the role of cats in disease epidemiology and its clinical impact is still debated. The present study raises awareness about the impact of leishmaniasis in cats from an endemic region in of Northwestern Italy (Liguria). A total number of 250 serum and 282 blood samples were collected from cats, then assessed for ", "journal": "Veterinary sciences", "doi": "10.3390/vetsci8100215", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34495702", "author": "Chiu ES", "n_authors": 3, "title": "Endogenous Feline Leukemia Virus (FeLV) siRNA Transcription May Interfere with Exogenous FeLV Infection.", "abstract": "Endogenous retroviruses (ERVs) are increasingly recognized for biological impacts on host cell function and susceptibility to infectious agents, particularly in relation to interactions with exogenous retroviral progenitors (XRVs). ERVs can simultaneously promote and restrict XRV infections using mechanisms that are virus and host specific. The majority of endogenous-exogenous retroviral interactions have been evaluated in experimental mouse or chicken systems, which are limited in their ability to extend findings to naturally infected outbred animals. Feline leukemia virus (FeLV) has a relatively well-characterized endogenous retrovirus with a coexisting virulent exogenous counterpart and is endemic worldwide in domestic cats. We have previously documented an association between endogenous FeLV (enFeLV) long terminal repeat (LTR) copy number and abrogated exogenous FeLV in naturally infected cats and experimental infections in tissue culture. Analyses described here examine limited FeLV replication in experimentally infected peripheral blood mononuclear cells, which correlates with higher enFeLV transcripts in these cells compared to fibroblasts. We further examine NCBI Sequence Read Archive RNA transcripts to evaluate enFeLV transcripts and RNA interference (RNAi) precursors. We find that lymphoid-derived tissues, which are experimentally less permissive to exogenous FeLV infection, transcribe higher levels of enFeLV under basal conditions. Transcription of enFeLV-LTR segments is significantly greater than that of other enFeLV genes. We documented transcription of a 21-nucleotide (nt) microRNA (miRNA) just 3' to the enFeLV 5'-LTR in the feline miRNAome of all data sets evaluated (", "journal": "Journal of virology", "doi": "10.1128/JVI.00070-21", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34475642", "author": "Lo CLC", "n_authors": 5, "title": "Diet, parasites, and other pathogens of Sunda leopard cats (Prionailurus javanensis Desmarest 1816) in Aborlan, Palawan Island, Philippines.", "abstract": "This study is the first investigation of parasites and other pathogens present in Sunda leopard cats (", "journal": "Journal of parasitic diseases : official organ of the Indian Society for Parasitology", "doi": "10.1007/s12639-020-01335-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34474779", "author": "Jitsamai W", "n_authors": 6, "title": "Prevalence of endoparasitic and viral infections in client-owned cats in metropolitan Bangkok, Thailand, and the risk factors associated with feline hookworm infections.", "abstract": "The prevalence of enteric parasites in cats in metropolitan Bangkok has not been updated in over 13 years. The main objectives of this study include updating the prevalence of endoparasitism in client-owned cats, status of retroviral infections and determining the association between feline hookworm infection and possible risk factors. A total of 509 fecal samples were collected from client-owned cats in 2014-2015 and examined by a wet fecal mount technique. If additional sample remained, a PBS-ethyl acetate sedimentation was done (n = 229), and ZnSO", "journal": "Veterinary parasitology, regional studies and reports", "doi": "10.1016/j.vprsr.2021.100584", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34470629", "author": "Načeradská M", "n_authors": 4, "title": "Novel approach of dermatophytosis eradication in shelters: effect of Pythium oligandrum on Microsporum canis in FIV or FeLV positive cats.", "abstract": "Shelters and similar facilities with a high concentration and fluctuation of animals often have problems with various infections, which are usually difficult to solve in such environments and are very expensive to treat. This study investigated the eradication of Microsporum canis, the widespread cause of zoonotic dermatophytosis in shelters, even in immunosuppressed feline leukaemia virus or feline immunodeficiency virus positive cats. Our study showed the increased effectiveness of an alternative topical therapy for affected animals using the mycoparasitic fungus Pythium oligandrum, which is gentler and cheaper than the standard systemic treatment with itraconazole, and which can also be easily used as a preventative treatment. A decrease in the number of M. canis colonies was observed in cats treated with a preparation containing P. oligandrum 2 weeks after the start of therapy (2 cats with P-1 score, 2 cats with P-2 score, 5 cats with P-3 score) compared with the beginning of the study (9 cats with P-3 score = massive infection). The alternative topical therapy with a preparation containing P. oligandrum was significantly more effective compared with the commonly used systemic treatment using itraconazole 5 mg/kg in a 6-week pulse. After 16 weeks of application of the alternative topical therapy, the clinical signs of dermatophytosis were eliminated throughout the whole shelter. The complete elimination of the clinical signs of dermatophytosis in all cats indicates that this therapy will be useful for the management and prevention of zoonotic dermatophytosis in animal shelters.", "journal": "BMC veterinary research", "doi": "10.1186/s12917-021-03001-w", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34465558", "author": "Zaugg I", "n_authors": 2, "title": "[Vaccinovigilance: Adverse reaction reports of animal vaccines in 2020].", "abstract": "The aim of the vigilance system in Switzerland is the evaluation and classification of reported suspected adverse reactions of immunological veterinary medicines (IVMP), including suspected lack of expected efficacy. The Institute of Virology and Immunology (IVI) is the competent authority for marketing authorizations of immunological veterinary medicinal products in Switzerland and responsible for the vaccinovigilance system. In 2020, 130 adverse reaction reports were received (5% less compared to 2019). The reports mainly concerned dogs (41%) and cats (25%) followed by cattle (18%) and horses (7%). Many of the reports in dogs involved the application of combined vaccines against canine distemper, hepatitis, parvovirosis and parainfluenza in combination with canine leptospira components, in cats against cat flu and feline panleukopenia in combination with feline leukaemia virus infection. Causality assessments were done according to the international ABON system. In 27% of the reported cases, the causality assessments between the vaccination and the reaction described were evaluated as being probable (ABON A), in 44% as possible (ABON B).", "journal": "Schweizer Archiv fur Tierheilkunde", "doi": "10.17236/sat00312", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34454490", "author": "Niae S", "n_authors": 4, "title": "Prevalence and in vitro antifungal susceptibility of commensal yeasts in the external ear canal of cats.", "abstract": "Lifestyle factors such as hair length, the frequency of ear cleaning and bathing, age, cat rearing, and sex may contribute to opportunistic yeast infections in the external ear canal of cats. This study aimed to determine the prevalence of commensal yeast organisms in cats' external ear canals, evaluate their predisposing lifestyle factors, and test the susceptibility of Malassezia pachydermatis to antifungal agents. A total of 53 cats (33 male and 20 female) seronegative for feline leukemia virus and feline immunodeficiency virus were enrolled in this study. Their mean age (± standard deviation) was 6.04 (± 3.49) years. Fungal cultures and polymerase chain reaction tests were performed to identify the yeast species derived from the external ear canal. The association between lifestyle factors and the presence of M. pachydermatis was evaluated using Fisher's exact test. The susceptibility of M. pachydermatis to antifungal agents was also analyzed. M. pachydermatis was the most frequently recovered yeast species, with a prevalence of 50.94 % (95 % confidence interval [CI]: 36.84-64.94 %). There was an association between hair length and a positive culture for M. pachydermatis (p = 0.0001). The odds of a negative culture for M. pachydermatis among short-haired cats was 11.67 (95 % CI, 3.22-42.24) times higher than that among long-haired cats (p = 0.0002). There was also an association between the frequency of ear cleaning and the presence of M. pachydermatis (p = 0.007). The odds of a negative culture for M. pachydermatis in cats that were receiving ear cleaning at intervals of ≤ 2 weeks was 5.78 (95 % CI, 1.67-19.94) times greater than that of cats receiving ear cleaning at intervals greater than 2 weeks or never (p = 0.0055). Ranges of minimum inhibitory concentrations (MICs) and minimum fungicidal concentrations for itraconazole, ketoconazole, miconazole, and terbinafine against M. pachydermatis were ≤ 0.063-4 and ≤ 0.063-≥32, ≤ 0.063-8 and 0.125-≥32, ≤ 0.063-≥32 and 0.5-≥32, and ≤ 0.016-1 and 0.125-8 µg/ml, respectively. M. pachydermatis was the most commonly identified yeast organism in the external ear canal of healthy cats. Hair length and the frequency of ear cleaning played a role in the colonization of M. pachydermatis. The M. pachydermatis isolates had various MIC levels for common fungicides.", "journal": "BMC veterinary research", "doi": "10.1186/s12917-021-02995-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34452500", "author": "Helfer-Hungerbuehler AK", "n_authors": 6, "title": "Adeno-Associated Vector-Delivered CRISPR/SaCas9 System Reduces Feline Leukemia Virus Production In Vitro.", "abstract": "Feline leukemia virus (FeLV) is a retrovirus of cats worldwide. High viral loads are associated with progressive infection and the death of the host, due to FeLV-associated disease. In contrast, low viral loads, an effective immune response, and a better clinical outcome can be observed in cats with regressive infection. We hypothesize that by lowering viral loads in progressively infected cats, using CRISPR/", "journal": "Viruses", "doi": "10.3390/v13081636", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34232703", "author": "Erbeck K", "n_authors": 6, "title": "Feline Leukemia Virus (FeLV) Endogenous and Exogenous Recombination Events Result in Multiple FeLV-B Subtypes during Natural Infection.", "abstract": "Feline leukemia virus (FeLV) is associated with a range of clinical signs in felid species. Differences in disease processes are closely related to genetic variation in the envelope (", "journal": "Journal of virology", "doi": "10.1128/JVI.00353-21", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34229197", "author": "Muz D", "n_authors": 13, "title": "The molecular and serological investigation of Feline immunodeficiency virus and Feline leukemia virus in stray cats of Western Turkey.", "abstract": "This study aimed to investigate the Feline immunodeficiency virus (FIV) / Feline leukemia virus (FeLV) infection prevalence among looking healthy stray cats in Western Turkey by serologic and molecular-based tests. A total of 1008 blood samples from the stray cats were used in this study. All samples were tested for FIV antibodies / proviral DNA and FeLV antibodies / antigens / proviral DNA. The genetic characterization and phylogenetic analysis of FeLV and FIV were carried out in this study. These cats also tested for Leishmaniasis and Toxoplasmosis previously. FIV Ab and proviral DNA detected in 25.2 % and 25.5 % of samples, respectively. FeLV Ab, Ag, proviral DNA positivity was in 45.2 %, in 3.3 %, in 69.7 %, respectively. The molecular detection and phylogenetic analysis of the current FeLV pol gene and FIV gag gene performed. The molecular characterization for the pol gene of FeLV (enFeLV and exFeLV) among Turkey's cat population was reported for the first time. The exFeLV pol sequences closer to the FeLV-A genotype, and the enFeLV pol sequences overlapped with other enFeLV. The current FIV gag sequences were clustered within the subtypes A, B, and C. The findings revealed FeLV subtype A and FIV subtype-A, subtype-B, subtype-C circulate among Turkish stray cats. Single and multiple co-infection positivity was found higher compared to previous reports.", "journal": "Comparative immunology, microbiology and infectious diseases", "doi": "10.1016/j.cimid.2021.101688", "deposited_data": "Sim", "nuccore_ids": "2069681559, 2069681557, 2069681555, 2069681553, 2069681551, 2069681549, 2067168707, 2067168705, 2067168694, 1534889306, 1534889305, 1534889304, 1534889303, 1534889302, 1534889301, 1534889300, 1534889299, 1534889298, 1534889297, 1534889296, 1534889295, 1534889294, 1534889293, 1534889292", "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34225228", "author": "Kokkinaki KG", "n_authors": 8, "title": "A prospective epidemiological, clinical, and clinicopathologic study of feline leukemia virus and feline immunodeficiency virus infection in 435 cats from Greece.", "abstract": "Feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) are retroviruses causing significant morbidity and mortality in cats. The aim of this study was to describe the epidemiological, clinical and clinicopathologic aspects of FeLV and FIV infections in different populations of cats in Greece, including client-owned cats, stray cats and cats who live in catteries. A total of 435 cats were prospectively enrolled. Serological detection of FeLV antigen and FIV antibody was performed using a commercial in-house ELISA test kit. The results showed that 17 (3.9 %) and 40 (9.2 %) of the 435 cats were positive for FeLV antigen and FIV antibody, respectively, whereas 5 (1.1 %) had concurrent infection with FeLV and FIV. Factors that were associated with FeLV antigenemia, based on multivariate analysis, included vomiting, rhinitis, infection with FIV, neutropenia, decreased blood urea nitrogen and increased serum cholesterol and triglyceride concentrations. Factors associated with FIV seropositivity included male gender, older age, outdoor access, weight loss, fever, gingivostomatitis, skin lesions and/or pruritus and hyperglobulinemia. Various clinical signs and laboratory abnormalities were found to be significantly associated with retroviral infections, suggesting that current guidelines to test all sick cats should be followed, taking into particular consideration the high-risk groups of cats found in this study.", "journal": "Comparative immunology, microbiology and infectious diseases", "doi": "10.1016/j.cimid.2021.101687", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34224399", "author": "Molossi FA", "n_authors": 8, "title": "Pathological and immunohistochemical aspects of acute megakaryoblastic leukaemia in a cat - Short communication.", "abstract": "An adult, mixed-breed, feline leukaemia virus (FeLV-) positive female cat was presented with mucosal jaundice and a history of anorexia and constipation for three days. Physical examination revealed splenomegaly, cachexia, and dehydration. Humane euthanasia was conducted, followed by postmortem examination. Grossly, the cat was icteric, and presented hepatomegaly with multifocal white spots and splenomegaly. Histologically, the bone marrow was nearly completely replaced by a proliferation of megakaryocytes and megakaryoblasts, and there was a proliferation of fibrous connective tissue. Similar neoplastic proliferation was observed infiltrating the liver, lymph nodes, spleen, kidney, skeletal muscle, and lungs. Immunohistochemistry was performed for von Willebrand Factor (VWF), CD79α, CD3, feline immunodeficiency virus, FeLV, and CD61. Marked cytoplasmic labelling was observed in the neoplastic cells for FeLV, VWF and CD61, corroborating the diagnosis of acute megakaryoblastic leukaemia.", "journal": "Acta veterinaria Hungarica", "doi": "10.1556/004.2021.00025", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34157764", "author": "Sinzinger S", "n_authors": 1, "title": "[Reversible left ventricular hypertrophy and congestive heart failure due to suspected myocarditis in a cat in the course of FLUTD].", "abstract": "A 2.5-year-old castrated male domestic shorthair cat with a past pertinent history of FLUTD treatment 8 days earlier was presented during the night due to apathy and anorexia. Radiographs, ECG, blood pressure measurement and echocardiography revealed left-sided congestive heart failure, left ventricular concentric hypertrophy, left atrial dilation, severe diastolic dysfunction, hypotension, and vagotonus-associated sinus bradycardia with a first degree AV-block as well as a right bundle brunch block. NT-ProBNP and troponin I concentrations were elevated (NT-ProBNP > 1500 pmol/l, Troponin I 32.87 ng/ml). Presumptive diagnosis was acute myocarditis. ", "journal": "Tierarztliche Praxis. Ausgabe K, Kleintiere/Heimtiere", "doi": "10.1055/a-1483-3342", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34153286", "author": "Roth M", "n_authors": 8, "title": "Distinct Antiretroviral Mechanisms Elicited by a Viral Mutagen.", "abstract": "5-aza-cytidine (5-aza-C) has been shown to be a potent human immunodeficiency virus type 1 (HIV-1) mutagen that induces G-to-C hypermutagenesis by incorporation of the reduced form (i.e., 5-aza-dC, 5-aza-dCTP). Evidence to date suggests that this lethal mutagenesis is the primary antiretroviral mechanism for 5-aza-C. To investigate the breadth of application of 5-aza-C as an antiretroviral mutagen, we have conducted a comparative, parallel analysis of the antiviral mechanism of 5-aza-C between HIV-1 and gammaretroviruses - i.e., murine leukemia virus (MuLV) and feline leukemia virus (FeLV). Intriguingly, in contrast to the hallmark G-to-C hypermutagenesis observed with HIV-1, MuLV and FeLV did not reveal the presence of a significant increase in mutational burden, particularly that of G-to-C transversion mutations. The effect of 5-aza-dCTP on DNA synthesis revealed that while HIV-1 RT was not inhibited by 5-aza-dCTP even at 100 µM, 5-aza-dCTP was incorporated and significantly inhibited MuLV RT, generating pause sites and reducing the fully extended product. 5-aza-dCTP was found to be incorporated into DNA by MuLV RT or HIV-1 RT, but only acted as a non-obligate chain terminator for MuLV RT. This biochemical data provides an independent line of experimental evidence in support of the conclusion that HIV-1 and MuLV have distinct primary mechanisms of antiretroviral action with 5-aza-C. Taken together, our data provides striking evidence that an antiretroviral mutagen can have strong potency via distinct mechanisms of action among closely related viruses, unlinking antiviral activity from antiviral mechanism of action.", "journal": "Journal of molecular biology", "doi": "10.1016/j.jmb.2021.167111", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34138750", "author": "Abayli H", "n_authors": 6, "title": "Detection and molecular characterisation of feline viruses from swab samples.", "abstract": "Feline calicivirus (FCV), feline alphaherpesvirus 1 (FHV-1) and feline panleukopenia virus (FPLV) as well as retroviral agents such as feline leukaemia virus (FeLV) and feline immunodeficiency virus (FIV) are important viral pathogens of cats. The aim of this study was to detect and characterise FHV-1, FPLV, FeLV, FIV and feline foamy virus (FFV) in oropharyngeal, nasal and conjunctival swabs from 93 cats that had been screened for FCV previously. We wanted to determine the possible risk factors for infection with these viruses. The prevalence was found to be 12.9% for FHV-1 and 9.7% for FPLV. FIV was detected only in two samples and FeLV in one sample, whereas the presence of FFV was not demonstrated in any of the clinical samples. The statistical analysis of the results showed that breed, age, health status, and lifestyle are important predisposing factors to FHV-1 (P < 0.05). For FPLV, only clinically unhealthy animals were found to be at risk (P < 0.001). Sequence analysis revealed that the two FIV-positive samples in this study contained different (A and B) subtypes of the virus. This is the first report on the occurrence of subtype A FIV in Turkey.", "journal": "Acta veterinaria Hungarica", "doi": "10.1556/004.2021.00020", "deposited_data": "Sim", "nuccore_ids": "2041185680, 2041185630, 2041185593, 2041185522, 2041185464, 2041185398, 2041185345, 2041185278, 2041185228, 2041185162, 2041185113, 2041185044, 2041184986, 2041184916, 2041184849, 2041184785, 2041184756, 2041184689, 2041184665, 2041184651, 2041184626, 2041184580, 2041184512, 2041184457", "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34133926", "author": "Fiorito V", "n_authors": 23, "title": "The heme synthesis-export system regulates the tricarboxylic acid cycle flux and oxidative phosphorylation.", "abstract": "Heme is an iron-containing porphyrin of vital importance for cell energetic metabolism. High rates of heme synthesis are commonly observed in proliferating cells. Moreover, the cell-surface heme exporter feline leukemia virus subgroup C receptor 1a (FLVCR1a) is overexpressed in several tumor types. However, the reasons why heme synthesis and export are enhanced in highly proliferating cells remain unknown. Here, we illustrate a functional axis between heme synthesis and heme export: heme efflux through the plasma membrane sustains heme synthesis, and implementation of the two processes down-modulates the tricarboxylic acid (TCA) cycle flux and oxidative phosphorylation. Conversely, inhibition of heme export reduces heme synthesis and promotes the TCA cycle fueling and flux as well as oxidative phosphorylation. These data indicate that the heme synthesis-export system modulates the TCA cycle and oxidative metabolism and provide a mechanistic basis for the observation that both processes are enhanced in cells with high-energy demand.", "journal": "Cell reports", "doi": "10.1016/j.celrep.2021.109252", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 2210364609, 2210364607, 2210364555, 2210364553, 2210364512, 2210364502, 2210364501, 2210364494, 2210364471, 2210364449, 2210364427, 2210364423, 2210364421, 2210364405, 2210364389, 1907202778, 1907128564, 1907128562, 1907128559, 1907128557, 1907128554, 1907128552, 1907128549, 1907128548, 1907128545, 1907128533, 1907128531, 1907128529, 1907128526, 1907128520, 1907128516, 1907128509, 1720392432, 1720392426, 1720392425, 1720392414, 1720392408, 1720392403, 1720392397, 1519315556, 1347826188, 1347826186, 924181778, 924181484, 820375847, 820375845, 124486924", "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34059963", "author": "Loock DJE", "n_authors": 5, "title": "Viral Prevalence in Wild Serval Population is Driven by Season and Sex.", "abstract": "One of the key factors influencing the population dynamics of threatened species such as felids is disease, but long-term studies of the factors influencing seroprevalence of wild felids are extremely rare, hindering conservation efforts. We set out to determine seroprevalence of six viral diseases (feline panleukopenia virus, feline leukemia virus, feline coronavirus, feline calicivirus, feline herpes virus, and feline immunodeficiency virus) among a population of serval (Leptailurus serval) with an extremely high density in South Africa. We captured 55 individuals over four years and screened blood samples for antibodies to each virus. We found that seroprevalence were high (ranging from 30.0% positive for a single virus to 1.8% positive for up to five viruses) and that seroprevalence was influenced by season and sex, but not body condition. We suggest further monitoring of this population and recommend that long-term studies are conducted for serval and other felids to determine whether these trends are representative on a broader scale.", "journal": "EcoHealth", "doi": "10.1007/s10393-021-01533-z", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33981439", "author": "Paulo C", "n_authors": 8, "title": "A 5-year retrospective study of canine and feline patients referred to an isolation unit for infectious diseases.", "abstract": "Referral of cases is becoming more and more frequent in companion animal practice. The Infectious Diseases Isolation Unit (IDIU) admits first opinion, second opinion and referred patients with a confirmed infectious disease (ID) or a clinically suspected ID that is awaiting laboratory diagnosis. The primary aims of this study were to describe the annual number and characteristics of patients referred to the IDIU and identify the most frequent IDs in referred dogs and cats. A secondary aim was to investigate possible differences in the length of the hospitalisation and the clinical outcome among referred cases and those admitted to the IDIU after first and second opinion appointments. A retrospective study was carried out on patients hospitalised at the unit over 5 years from 9th October 2013 to 31st December 2018. The study population consisted of 365 dogs and 515 cats to give a total of 880 patients hospitalised at the IDIU from October 2013 to December 2018. Among the 96 referred dogs, parvovirosis (37.7%) and leptospirosis (31.1%) were the most frequent IDs. Feline upper respiratory tract infection (38.2%) and feline leukaemia virus infections (36.4%) were the main causes in the 80 referred cats. Worrying noncompliance rates of dog (51.0%) and cat (52.5%) vaccination schedules were identified. The analysis of the length of hospitalisation in the three groups of patients was not statistically different. In both animal species there were statistically significant higher clinical discharge rates on the first opinion patients' group in comparison to referred patients and the second opinion group. Parvovirosis and leptospirosis in dogs and upper respiratory disease and feline leukaemia virus infection in cats were the most common diagnoses for patients admitted to the IDIU, reinforcing the need for accurate vaccination. Discharge rates results pinpoint the need for timely accurate reference.", "journal": "Veterinary record open", "doi": "10.1002/vro2.5", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33924616", "author": "Abramo F", "n_authors": 9, "title": "Skin Lesions in Feline Leishmaniosis: A Systematic Review.", "abstract": "Feline leishmaniosis (FeL) is increasingly reported throughout the world and skin lesions predominate in the clinical picture. There are, however, few evidence-based data on cutaneous feline leishmaniosis and directions are strongly needed for a better management of the disease. In this study, we systematically reviewed what is currently known about the clinical dermatological presentation of FeL through analysis of the literature and, further, by adding unpublished cases managed by Italian veterinary dermatologists. Sixty-six feline cases of cutaneous leishmaniosis published in 33 articles between 1990 and 2020 met the inclusion criteria and were analyzed. Six unpublished cases of cutaneous FeL managed by Italian dermatologists were also reviewed. The majority of cases were reported from South America, followed by Europe and North America. Nodules were the most frequently reported clinical signs and the presence of Leishmania in lesioned skin was assessed mainly by cytology. A total of six Leishmania species have been identified as being responsible for skin lesions. Coinfections by FIV or FeLV were reported in 12.1% and 9.1% of the cases, respectively. Clinical data including treatment have been analyzed and discussed to provide directives for proper management of the disease for which cats may also serve as domestic reservoirs for human infections.", "journal": "Pathogens (Basel, Switzerland)", "doi": "10.3390/pathogens10040472", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33897821", "author": "Sacristán I", "n_authors": 15, "title": "Cross-species transmission of retroviruses among domestic and wild felids in human-occupied landscapes in Chile.", "abstract": "Human transformation of natural habitats facilitates pathogen transmission between domestic and wild species. The guigna (", "journal": "Evolutionary applications", "doi": "10.1111/eva.13181", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33894589", "author": "Kharbush RJ", "n_authors": 4, "title": "B-cell lymphoma invading and compressing the heart base and pericardium in a cat.", "abstract": "A 3-year-old, 3.5-kg, neutered male, domestic shorthair cat presented with progressive lethargy, anorexia, coughing, and acute respiratory distress of two-week duration. Auscultation detected diffuse pulmonary crackles. Lung sounds were absent over the left cranial thorax. Sinus tachycardia was recorded. Thoracic radiographs revealed cardiac silhouette enlargement, dorsal displacement of the carina, and uniform, soft tissue opacity in the left cranial hemithorax. Transthoracic two-dimensional echocardiography revealed a large mass within and external to the pericardial space, effacing the pericardium, and compressing basal cardiac structures. The point-of-care feline immunodeficiency virus and feline leukemia virus test was negative. Euthanasia was elected, and permission for necropsy granted. Gross postmortem evaluation revealed a prominent mediastinal mass that effaced the left cranial lung lobe and invaded the heart base and pericardium. The mass was confirmed as B-cell lymphoma by histopathology and immunohistochemistry.", "journal": "Journal of veterinary cardiology : the official journal of the European Society of Veterinary Cardiology", "doi": "10.1016/j.jvc.2021.03.006", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33842377", "author": "Zhou S", "n_authors": 6, "title": "FLVCR1 Predicts Poor Prognosis and Promotes Malignant Phenotype in Esophageal Squamous Cell Carcinoma via Upregulating CSE1L.", "abstract": "Dysregulation of feline leukemia virus subgroup C receptor 1(FLVCR1) expression has been investigated in several tumors. However, the expression and role of FLVCR1 in esophageal squamous cell carcinoma (ESCC) remain largely unknown. FLVCR1 expression in tissues was measured by immunohistochemical staining (IHC). Celigo assay, MTT assay, colony formation, caspase 3/7 activity analysis, wound healing assay, Transwell migration, and invasion assay were applied to assess the effects of FLVCR1 on ESCC tumorigenesis. Coimmunoprecipitation (Co-IP) and liquid chromatography-mass spectrometry (LC-MS) were used to identify protein interactions with FLVCR1. An  Elevated expression of FLVCR1 was detected in ESCC tissues and predicted poor survival. Upregulated FLVCR1 was positively correlated with lymph node metastasis (N stage) and late tumor-node-metastasis (TNM) stage. FLVCR1 knockdown inhibited cell proliferation and colony formation ability, induced cell apoptosis, and repressed cell migration and invasion of ESCC  FLVCR1 plays a pivotal role in ESCC cell survival, growth, and migration. These functions may be partially dependent upon the protein interaction between FLVCR1 and CSE1L. In addition, FLVCR1 can be applied as a clinical prognostic marker for patients with ESCC.", "journal": "Frontiers in oncology", "doi": "10.3389/fonc.2021.660955", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33838591", "author": "Demkin VV", "n_authors": 2, "title": "Prevalence of hemotropic mycoplasmas and coinfection with feline leukemia virus and feline immunodeficiency virus in cats in the Moscow region, Russia.", "abstract": "Feline haemoplasma infection studies are lacking in Russia. This retrospective study was conducted to estimate the prevalence of feline haemoplasmas in domestic cats in the Moscow region, Russia. A risk of haemoplasma coinfection with feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) was also determined. qPCR analysis for feline haemoplasmas was performed on EDTA blood samples from 753 cats from the Moscow region, Russia. Subsets of these samples were tested also for FIV and FeLV by qPCR. Of the 753 blood samples, 104 (13.8 %) were positive for one of the Mycoplasma species. The prevalence of 'Candidatus Mycoplasma haemominutum' (CMhm), Mycoplasma haemofelis (Mhf), and 'Candidatus Mycoplasma turicensis' (CMt) was 7.6 %, 5.5 %, and 0.7 %, respectively. One sample (0.1 %) was simultaneously infected with two haemoplasmas, namely, Mhf and CMt. Haemoplasma positive cats were more likely to be infected with FIV than haemoplasma negative (17.6 % vs 6.7 %), but these differences were not statistically significant. The prevalence of FeLV was comparable among haemoplasma positive and negative cats (23.5 % vs 25.7 %) All three known species of feline haemoplasma were detected, confirming their presence in Russia. The overall and species-specific rates of haemoplasma infections in Russian cats are generally similar to the rates in the countries of central Europe. This report documents for the first time the prevalence of feline hemotropic mycoplasmas in domestic cats not only in Russia but also in eastern Europe.", "journal": "Preventive veterinary medicine", "doi": "10.1016/j.prevetmed.2021.105339", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "35749085", "author": "Almeida IO", "n_authors": 7, "title": "Retrospective study of retroviruses by immunoenzymatic test on cats in Grande Vitória (ES, Brazil) and associated neoplasms.", "abstract": "Retroviruses are among the leading causes of death in domestic cats. Retroviruses associate with the host cell in a persistent and permanent way, leading to diverse clinical conditions. The feline leukemia virus (FeLV) is the most pathogenic retrovirus with the potential to cause both degenerative diseases and immunosuppression, as well as proliferative diseases, as its association with the cell may lead to a direct oncogenic effect. The feline immunodeficiency virus (FIV), in turn, can lead to the classic immunodeficiency syndrome, usually has a chronic, less aggressive course and has no direct oncogenic effect. The use of vaccines and control measures has resulted in a decrease in the prevalence of FeLV in the United States of America (USA) and Europe, however, in Brazil, statistics show prevalence rates above 50%. This study aimed to assess the prevalence of feline retroviruses, by immunoenzymatic assay testing, in the region of Grande Vitória, in Espírito Santo and also point out the frequency of neoplasms in these cats. A total of 388 cats were retrospectively evaluated (2014-2016). The prevalence of FIV was 2.3% and FeLV was 33.7%. Neoplasms were identified in the three cats seropositive for FIV and FeLV and in three cats infected only with FIV. Neoplasms were also found in 26.6% of cats that were seropositive only for FeLV, especially mediastinal lymphoma. The high prevalence of FeLV demonstrated in this study highlights the need for establishing effective control measures, with emphasis on vaccination.", "journal": "Brazilian journal of veterinary medicine", "doi": "10.29374/2527-2179.bjvm114220", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33829376", "author": "Mesquita MCSR", "n_authors": 8, "title": "Sepsis in cougar (Puma concolor) associated with Chromobacterium violaceum.", "abstract": "The genus Chromobacterium is widely distributed in the environment and is composed of Gram-negative, aerobic, or facultative anaerobic bacilli that occur in violet-colored colonies. These bacteria rarely cause infections, but when it occurs, it spreads quickly and has a high mortality. Because diseases are infrequent, the diagnosis is often delayed, and it takes time for suitable treatment to be initiated, leading to increased mortality due to the rapid progression of the disease. After the death of a cougar, serologically positive for feline leukemia virus, at the Center for Medicine and Research on Wild Animals of the Federal University of Mato Grosso, an autopsy was carried out, and fragments of its organs were sent for bacterial culture. Significant lesions were found, mainly in the liver and lungs, and upon bacterial isolation, violet-colored colonies were obtained from all of the referred organs, suggestive of C. violaceum, which was later confirmed by 16S DNA sequencing. The objective of this study was to report a case of death associated primarily with disseminated infection caused by C. violaceum in a FeLV-positive wild cougar in July 2018; no other occurrence in this species has yet been described.", "journal": "Brazilian journal of microbiology : [publication of the Brazilian Society for Microbiology]", "doi": "10.1007/s42770-021-00460-z", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33822151", "author": "McCauley D", "n_authors": 7, "title": "Serologic Survey of Selected Pathogens in Free-Ranging Bengal Tigers (Panthera tigris tigris) in Nepal.", "abstract": "Serum samples of 11 Bengal tigers (Panthera tigris tigris) from Chitwan National Park in Nepal, collected between 2011-17, were evaluated for the presence of antibodies to eight diseases commonly investigated in large felids. This initial serologic survey was done to establish baseline information to understand the exposure of Nepal's free-ranging tiger population to these diseases. Tiger serum samples collected opportunistically during encounters such as translocation, human conflict, and injury were placed in cold storage for later use. Frozen serum samples were assessed for feline coronavirus (FCoV), feline immunodeficiency virus, feline leukemia virus, feline herpesvirus (FHV), canine distemper virus, canine parvovirus-2 (CPV-2), leptospirosis (LEP; seven serovars), and toxoplasmosis (TOX). Six tigers were found to be positive for LEP, eight for CPV-2, five for FHV, one for FCoV, and 10 for TOX. Tigers, like other wild felids, have been exposed to these common pathogens, but further research is needed to determine the significance of these pathogens to the Nepali population.", "journal": "Journal of wildlife diseases", "doi": "10.7589/JWD-D-20-00046", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33800090", "author": "Parr YA", "n_authors": 7, "title": "Measuring the Humoral Immune Response in Cats Exposed to Feline Leukaemia Virus.", "abstract": "Retroviruses belong to an important and diverse family of RNA viruses capable of causing neoplastic disease in their hosts. Feline leukaemia virus (FeLV) is a gammaretrovirus that infects domestic and wild cats, causing immunodeficiency, cytopenia and neoplasia in progressively infected cats. The outcome of FeLV infection is influenced by the host immune response; progressively infected cats demonstrate weaker immune responses compared to regressively infected cats. In this study, humoral immune responses were examined in 180 samples collected from 123 domestic cats that had been naturally exposed to FeLV, using a novel ELISA to measure antibodies recognizing the FeLV surface unit (SU) glycoprotein in plasma samples. A correlation was demonstrated between the strength of the humoral immune response to the SU protein and the outcome of exposure. Cats with regressive infection demonstrated higher antibody responses to the SU protein compared to cats belonging to other outcome groups, and samples from cats with regressive infection contained virus neutralising antibodies. These results demonstrate that an ELISA that assesses the humoral response to FeLV SU complements the use of viral diagnostic tests to define the outcome of exposure to FeLV. Together these tests could allow the rapid identification of regressively infected cats that are unlikely to develop FeLV-related disease.", "journal": "Viruses", "doi": "10.3390/v13030428", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33776305", "author": "Mummoorthy K", "n_authors": 8, "title": "Molecular detection of feline leukemia virus in clinically ill cats in Klang Valley, Malaysia.", "abstract": "Feline leukemia virus (FeLV) is classified as  Convenience sampling was performed in 20 cats from the Gasing Veterinary Hospital in Selangor. Plasma and saliva samples were collected from 15 clinically ill cats and 5 healthy cats subjected to one-step reverse transcription-polymerase chain reaction with primers targeting a highly conserved gene of U3-LTR-gag. Two clinically ill cats' plasma and saliva samples tested positive for FeLV RNA. Partial nucleotide sequencing and phylogenetic analysis revealed that the current isolates were 94-99% homologous to the previous Malaysian and Japanese FeLV isolates. Current FeLV isolates from this study displayed higher similarity with the previous Malaysian isolates, signifying that a similar FeLV strain circulated among the cat population in Selangor.", "journal": "Veterinary world", "doi": "10.14202/vetworld.2021.405-409", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33766113", "author": "Alcover MM", "n_authors": 11, "title": "A cross-sectional study of Leishmania infantum infection in stray cats in the city of Zaragoza (Spain) using serology and PCR.", "abstract": "Feline leishmaniosis is a vector-borne parasitic disease caused by Leishmania spp. Leishmania infection in dogs is prevalent in the Mediterranean basin, but in other animals, such as cats, it could also play a role in the epidemiology of the disease. Information on the geographical distribution and epidemiological features of L. infantum infection in cats is scarce, particularly in urban stray cats living in regions where canine leishmaniosis is endemic. As diagnosis can be challenging, combining different serological and molecular methods is a useful approach. Our aim was to investigate the prevalence of infection of L. infantum in apparently healthy stray cats in an endemic region of Spain (Zaragoza city) using serological and molecular methods, and to compare the results of the different techniques. The prevalence of Leishmania infection was studied in stray cats captured in urban and peri-urban areas of Zaragoza. Blood was collected from each animal for serology and molecular analysis. Three serological methods, namely the immunofluorescent antibody test (IFAT), enzyme-linked immunosorbent assay (ELISA) and western blot (WB), were used to detect L. infantum antibodies and a real-time PCR (qPCR) assay was used to detect L. infantum DNA. The results were analyzed by Fisher's exact test and Cohen's kappa statistic (κ)  to assess the level of agreement between the diagnostic techniques. Serological analysis of blood samples from 180 stray cats revealed 2.2% (4/179) Leishmania infection positivity by IFAT, 2.8% (5/179) by ELISA and 14.5% (26/179) by WB. Leishmania DNA was detected by qPCR in 5.6% (10/179) of the cats. Sixteen cats (8.9%) tested positive by only one serological technique and four tested positive by all three serological methods used. The overall rate of infected cats (calculated as the number of cats seropositive and/or qPCR positive) was 15.6%, and only two cats tested positive by all the diagnostic methods. A significant association was found between male cats and a positive qPCR result. Comparison of the techniques revealed a fair agreement in seropositivity between blood qPCR and IFAT (κ = 0.26), blood qPCR and ELISA (κ = 0.24), WB and ELISA (κ = 0.37) and WB and IFAT (κ = 0.40). The highest agreement between seropositive results was between IFAT and ELISA (κ = 0.89), and the lowest was between blood qPCR and WB (κ = 0.19). The prevalence of the feline leukemia virus antigen was 4.49% (8/178 cats) and that of the feline immunodeficiency virus (FIV) antibody was 6.74% (12/178), while co-infection with both retroviruses was observed in one female cat (1/178). Leishmania ELISA and IFAT seropositivity were statistically associated with FIV status by the chi-square test. The results obtained in this study, using serological tests and qPCR, indicate the existence of L. infantum asymptomatic infection in apparently healthy stray cats in the city of Zaragoza, an endemic area in Spain.", "journal": "Parasites & vectors", "doi": "10.1186/s13071-021-04682-w", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33764584", "author": "da Silva Serpa PB", "n_authors": 2, "title": "A case of acute monocytic leukemia (AMoL or AML-M5) in an adult FeLV/FIV-positive cat.", "abstract": "A 7-year-old castrated male domestic shorthair cat was presented for evaluation of decreased appetite and respiratory signs. A CBC run on presentation revealed severe nonregenerative anemia, thrombocytopenia, and leukocytosis characterized by a prominent population of blasts, having morphologic features suggestive of a monocytic lineage. The cat tested positive for FIV, FeLV, Mycoplasma haemominutum, and only mild abnormalities were identified on the chemistry panel. Bone marrow biopsies were obtained to investigate the bicytopenia and the possibility of a hematopoietic neoplasm. Although the bone marrow aspirate was nondiagnostic, the core biopsy was markedly hypercellular with a population of blasts, largely replacing the normal hematopoietic tissue. Immunohistochemical staining revealed that the blasts were CD3-negative, Pax5-negative, dimly CD18-positive, and moderately positive for Iba1. These findings, in addition to the prominent monocytic differentiation seen in peripheral blood, supported a diagnosis of acute monocytic leukemia. Palliative antiviral and antibiotic treatment and blood transfusion were performed. The patient was discharged on his fourth day of hospitalization. However, 15 days following discharge, the cat was euthanized due to the worsening of his systemic signs. This report discusses the classifications of myeloid leukemias, implications of infectious diseases in the pathogenesis of neoplasia in cats, and the use of Iba1, a \"pan-monocytic/histiocytic\" marker, in the diagnosis of acute leukemia.", "journal": "Veterinary clinical pathology", "doi": "10.1111/vcp.12964", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33757494", "author": "Makhtar ST", "n_authors": 6, "title": "Development of TaqMan-based real-time RT-PCR assay based on N gene for the quantitative detection of feline morbillivirus.", "abstract": "Morbilliviruses are categorized under the family of Paramyxoviridae and have been associated with severe diseases, such as Peste des petits ruminants, canine distemper and measles with evidence of high morbidity and/or could cause major economic loss in production of livestock animals, such as goats and sheep. Feline morbillivirus (FeMV) is one of the members of Morbilliviruses that has been speculated to cause chronic kidney disease in cats even though a definite relationship is still unclear. To date, FeMV has been detected in several continents, such as Asia (Japan, China, Thailand, Malaysia), Europe (Italy, German, Turkey), Africa (South Africa), and South and North America (Brazil, Unites States). This study aims to develop a TaqMan real-time RT-PCR (qRT-PCR) assay targeting the N gene of FeMV in clinical samples to detect early phase of FeMV infection. A specific assay was developed, since no amplification was observed in viral strains from the same family of Paramyxoviridae, such as canine distemper virus (CDV), Newcastle disease virus (NDV), and measles virus (MeV), and other feline viruses, such as feline coronavirus (FCoV) and feline leukemia virus (FeLV). The lower detection limit of the assay was 1.74 × 10 The TaqMan-based real-time RT-PCR assay targeting the N gene described in this study is more sensitive, specific, rapid, and reproducible compared to the conventional RT-PCR assay targeting the N gene, which could be used to detect early infection in cats.", "journal": "BMC veterinary research", "doi": "10.1186/s12917-021-02837-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33733387", "author": "Mendes-de-Almeida F", "n_authors": 5, "title": "Infection with Dirofilaria immitis and Other Infections in Cats and Dogs from Rio de Janeiro, Brazil: The Need for Prophylactic Enforcement.", "abstract": "Dirofilaria immitis, a mosquito-borne nematode that primarily infects dogs, can equally infect cats. Although there have been numerous studies on canine heartworm prevalence in Brazil, there have been few studies on feline infections. Feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) are both life-threatening retroviruses transmitted directly between cats. Infections with Ehrlichia spp. and Anaplasma spp. are highly prevalent among dogs in Brazil, with Rhipicephalus sanguineus being the main vector for both bacteria. This study aimed to gather information on these infections among dogs and cats in the metropolitan area of Rio de Janeiro by performing rapid point-of-care tests for prophylactic enforcement. Surplus samples of serum or plasma from private laboratories were tested by enzyme-linked immunosorbent assay (ELISA) (SNAP Feline Triple Test or SNAP 4Dx Plus Test). The prevalence of heartworm disease was 7% among dogs and 0.9% among cats, the latter being 12.9% of the former. The prevalence of FIV and FeLV was 4.3 and 11.9%, respectively. Among dogs, the seroprevalence of Ehrlichia spp. and Anaplasma spp. was 27.1 and 9.8%, respectively, and Borrelia burgdorferi was not detected. Given that such infections circulate among pets, prophylactic measures should be encouraged by small animal practitioners.", "journal": "Acta parasitologica", "doi": "10.1007/s11686-021-00345-z", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33671961", "author": "Beall MJ", "n_authors": 10, "title": "Feline Leukemia Virus p27 Antigen Concentration and Proviral DNA Load Are Associated with Survival in Naturally Infected Cats.", "abstract": "Longitudinal studies of cats naturally infected with feline leukemia virus (FeLV) are important for understanding disease outcomes. Levels of p27 antigen and copy numbers of proviral DNA have been associated with FeLV-infection courses. The purpose of this prospective study was to establish cutoff values for p27 antigen concentration and proviral DNA load that distinguished high positive from low positive groups of cats and to evaluate an association with survival. At enrollment, 254 cats were tested by point-of-care and microtiter plate enzyme-linked immunosorbent assays (ELISAs) for p27 antigen and real-time polymerase chain reaction (PCR) for proviral DNA. The 127 positive cats were retested monthly for six months and monitored for survival over the four-year study. A receiver operating characteristic-based analysis of samples with concordant or discordant qualitative results for p27 antigen and proviral DNA was used to establish cutoff values, and when applied to test results at enrollment for classifying cats as high positive or low positive, a significant difference in survival was observed. High positive cats had a median survival of 1.37 years (95% CI 0.83-2.02) from time of enrollment, while most low positive cats were still alive (93.1% survival). Quantitative results for p27 antigen concentration and proviral DNA load were highly correlated with survival times in FeLV-infected cats.", "journal": "Viruses", "doi": "10.3390/v13020302", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33669869", "author": "Nájera F", "n_authors": 11, "title": "Disease Surveillance during the Reintroduction of the Iberian Lynx (Lynx pardinus) in Southwestern Spain.", "abstract": "The restoration of Iberian lynx (", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani11020547", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33611160", "author": "Roccabianca P", "n_authors": 8, "title": "Feline lymphoplasmacytic rhinitis (FLPCR): Severity of inflammation correlates with reduced mucosal IgA expression.", "abstract": "Feline lymphoplasmacytic rhinitis (FLPCR) is a rare disease with an unclear pathogenesis characterized by lymphoplasmacytic (LPC) inflammation and progressive tissue destruction. Aims were to evaluate specific FLPCR clinical and pathological features to gain insights into disease pathogenesis. Signalment, clinical signs, serology and 47 pin. h biopsies were retrospectively collected from 33 FLPCR and 3 normal cats. Microscopical lesions and immunohistochemistry results utilizing anti-CD3, anti-CD20, anti-FOXP3, anti-feline-IgA, IgG, IgE and anti-FeLV (p27 and gp70), FIV, FCV and, FHV were scored and most were analyzed statistically. The majority of cats were domestic short haired (26/31) with median age of 11 years and a 0.35 F/M ratio. Serology evidenced 3/22 FIV and 1/22 FeLV positive cats. Immunohistochemistry evidenced 1/33 FeLV-p27 positive cats. Common clinical signs were sneezing (19/24 [79 %]), mucous discharge (13/24 [54 %]) and stertor (10/24 [42 %]). In normal tissues, IgAs were expressed in mucin, apical and lateral cell membrane of columnar cells and in periglandular plasma cells. IgGs were expressed in 20-30 % of columnar cells. Number of clinical signs was statistically significantly higher in female cats (p < 0.0001) and was significantly correlated with chronicity (p = 0.004), and IgG scores (p = 0.01). LPC severity scores correlated positively with infiltration of neutrophils (p = 0.015), gland destruction (p = 0.019) and angiogenesis (p = 0.016) and negatively with fibrosis (p < 0.0001). LPC severity scores were also significantly associated to female sex (p = 0.01) and to IgA (p = 0.03), with higher IgA scores associated to lower LPC scores. FLPCR associated to disruption of mucosal defense mechanisms generating cycles of tissue inflammation, tissue damage and repair with progressive loss of function independent from viral infections.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2021.110193", "deposited_data": "Sim", "nuccore_ids": "2130896857", "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33582484", "author": "Capozza P", "n_authors": 14, "title": "Feline leukemia virus in owned cats in Southeast Asia and Taiwan.", "abstract": "Feline leukaemia virus (FeLV) is a retrovirus associated with fatal disease in cats with infection in its progressive form. Although there are numerous reports on the occurrence of FeLV in the feline population worldwide, there is a paucity of data in Asia. In this study, we assessed the circulation of FeLV by ELISA and nested PCR in cats from different countries in Southeast Asia (i.e., Thailand, Malaysia, Singapore, Philippines, Indonesia and Vietnam) and Taiwan during 2017-2018. Forty-seven cats were positive to FeLV by antigen or provirus detection, but 32 samples were considered truly positive on the basis of positive molecular testing. Frequency of occurrence of FeLV proviral DNA ranged from 0% (0/43 positive samples) in Indonesia to 18.5% (22/119 positive samples) in Thailand. A statistically significant association (p < 0.05) was found between country of cats origin, age, lifestyle, abnormal oral mucosa, and FeLV molecular positive results. In-depth studies are needed in other countries in Southeast Asia to elucidate the mosaic of knowledge about FeLV epidemiology.", "journal": "Veterinary microbiology", "doi": "10.1016/j.vetmic.2021.109008", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33546485", "author": "Westman M", "n_authors": 10, "title": "Anti-SU Antibody Responses in Client-Owned Cats Following Vaccination against Feline Leukaemia Virus with Two Inactivated Whole-Virus Vaccines (Fel-O-Vax(®) Lv-K and Fel-O-Vax(®) 5).", "abstract": "A field study undertaken in Australia compared the antibody responses induced in client-owned cats that had been vaccinated using two inactivated whole feline leukaemia virus (FeLV) vaccines, the monovalent vaccine Fel-O-Vax", "journal": "Viruses", "doi": "10.3390/v13020240", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33494205", "author": "Chi X", "n_authors": 5, "title": "Prevalence of Feline Immunodeficiency Virus and Toxoplasma gondii in Feral Cats on St. Kitts, West Indies.", "abstract": null, "journal": "Veterinary sciences", "doi": "10.3390/vetsci8020016", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33459612", "author": "Szilasi A", "n_authors": 6, "title": "Prevalence of feline leukaemia virus and feline immunodeficiency virus in domestic cats in Ireland.", "abstract": "Feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV) are retroviruses affecting felid species worldwide. A study was performed over a period of 5 months in Ireland with the aim to get an updated and more realistic prevalence of these retroviruses. A total of 183 EDTA-anticoagulated whole-blood samples were collected from cats distributed between 10 clinics. The samples were tested using both point-of-care enzyme-linked immunosorbent assay (ELISA) and polymerase chain reaction (PCR). Basic clinical data and vaccination history were also recorded for the sampled cats. The results of ELISA tests showed a prevalence of 10.4 and 3.3% for FIV and FeLV, respectively, and an apparent prevalence of 9.3% for FIV and 11.6% for FeLV with PCR. Phylogenetic analysis of the partial polymerase (pol) gene sequences obtained from 8 FIV-positive strains showed that all but one of the Irish strains belonged to FIV subtype A, and one to subtype B. The overall mean genetic similarity between the analysed strains was 91.15%.", "journal": "Acta veterinaria Hungarica", "doi": "10.1556/004.2020.00056", "deposited_data": "Sim", "nuccore_ids": "2065947350, 2065947348, 2065947346, 2065947344, 2065947342, 2065947340, 2065947338, 2065947336", "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33421326", "author": "Carlos RSA", "n_authors": 12, "title": "First genome sequencing of SARS-CoV-2 recovered from an infected cat and its owner in Latin America.", "abstract": "An 11-year-old male mixed-breed cat, with exclusively indoor life, presented 3 cough episodes after the owners tested positive by RT-PCR for SARS-CoV-2. The house is inhabited by 5 people (3 adults and 2 children), and 2 of the adults have shown mild symptoms associated with throat discomfort. The cat was vaccinated, had no history of any previous disease, and tested negative for feline coronavirus (FCoV), feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV). Rectal sample collected from the cat was positive for SARS-CoV-2 by RT-PCR. Viral genome sequences recovered from human and cat samples showed an average 99.4% sequence identity. This is the first report of genome sequences of SARS-CoV-2 recovered from a cat and its owner in Latin America.", "journal": "Transboundary and emerging diseases", "doi": "10.1111/tbed.13984", "deposited_data": "Sim", "nuccore_ids": null, "bioproject_ids": "674624, 658053", "sra_ids": "12327660, 12327659, 12327658, 12327657, 12327656"}, {"year": 2021, "pmid": "33389172", "author": "Chen CC", "n_authors": 6, "title": "Molecular survey of selected viral pathogens in wild leopard cats (Prionailurus bengalensis) in Taiwan with an emphasis on the spatial and temporal dynamics of carnivore protoparvovirus 1.", "abstract": "The leopard cat (Prionailurus bengalensis) was listed as an endangered species under the Wildlife Conservation Act in Taiwan in 2009. However, no study has evaluated the possible direct or indirect effects of pathogens on the Taiwanese leopard cat population. Here, we targeted viral pathogens, including carnivore protoparvovirus 1 (genus Protoparvovirus), feline leukemia virus (FeLV), feline immunodeficiency virus (FIV), coronaviruses (CoVs), and canine distemper virus (CDV), through molecular screening. The spatial and temporal dynamics of the target pathogens were evaluated. Through sequencing and phylogenetic analysis, we clarified the phylogenetic relationship of viral pathogens isolated from leopard cats and domestic carnivores. Samples from 23 live-trapped leopard cats and 29 that were found dead were collected from 2015 to 2019 in Miaoli County in northwestern Taiwan. Protoparvoviruses and CoVs were detected in leopard cats, and their prevalence (95% confidence interval) was 63.5% (50.4%-76.6%) and 8.8% (0%-18.4%), respectively. Most of the protoparvovirus sequences amplified from Taiwanese leopard cats and domestic carnivores were identical. All of the CoV sequences amplified from leopard cats were identified as feline CoV. No spatial or temporal aggregation of protoparvovirus infection in leopard cats was found in the sampling area, indicating a wide distribution of protoparvoviruses in the leopard cat habitat. We consider sympatric domestic carnivores to be the probable primary reservoir for the identified pathogens. We strongly recommend management of protoparvoviruses and feline CoV in the leopard cat habitat, particularly vaccination programs and population control measures for free-roaming dogs and cats.", "journal": "Archives of virology", "doi": "10.1007/s00705-020-04904-z", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33313944", "author": "Han Y", "n_authors": 5, "title": "lncRNA FLVCR1‑AS1 drives colorectal cancer progression via modulation of the miR‑381/RAP2A axis.", "abstract": "Colorectal cancer (CRC) is one of the most prevalent types of cancer globally. Long non‑coding RNAs (lncRNAs) have been suggested to serve as vital regulators in CRC. lncRNA feline leukemia virus subgroup C receptor 1 antisense RNA 1 (FLVCR1‑AS1) is closely associated with the tumorigenesis of various types of cancer. The aim of the present study was to investigate the molecular mechanisms of lncRNA FLVCR1‑AS1 in CRC progression. The expression levels of FLVCR1‑AS1, microRNA (miR)‑381 and Ras‑related protein 2a (RAP2A) were measured by reverse transcription‑quantitative polymerase chain reaction (RT‑qPCR). A Kaplan‑Meier analysis was performed to determine the overall survival rate of patients with CRC. Furthermore, cell viability, migration and invasion were assessed using Cell Counting Kit‑8 (CCK‑8) and Transwell assays. The interaction between genes was confirmed using dual‑luciferase reporter and pull‑down assays. The results demonstrated that FLVCR1‑AS1 was upregulated in CRC tissues and cells, and increased FLVCR1‑AS1 expression levels in patients with CRC were associated with poor prognosis. FLVCR1‑AS1 knockdown significantly attenuated the viability, migration and invasion ability of CRC cells. In addition, the results confirmed that FLVCR1‑AS1 directly binds with miR‑381‑3p, and that RAP2A is a direct target of miR‑381‑3p. The overexpression of FLVCR1‑AS1 increased RAP2A expression levels. Functional assays revealed that miR‑381 inhibitor or RAP2A overexpression attenuated the suppressive effects of FLVCR1‑AS1 silencing on CRC cell viability, migration and invasion. Overall, the findings of the current study suggest that FLVCR1‑AS1 promotes CRC progression via the miR‑381/RAP2A pathway. These findings may provide a novel approach for CRC treatment.", "journal": "Molecular medicine reports", "doi": "10.3892/mmr.2020.11778", "deposited_data": "Sim", "nuccore_ids": "224591397, 224591396, 2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556, 1519246294, 262206258, 224591397, 224591396", "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33305378", "author": "Mesa-Sanchez I", "n_authors": 8, "title": "Transfusion transmissible pathogens are prevalent in healthy cats eligible to become blood donors.", "abstract": "This study aims to determine the prevalence of subclinical infectious agents considered core pathogens for worldwide screening in healthy, client-owned, indoor cats eligible to become blood donors in Spain and Portugal. Blood samples of healthy, indoor, domestic cats selected to be potential blood donors were tested for feline leukaemia virus antigens, feline immunodeficiency virus antibodies and polymerase chain reactions for Mycoplasma haemofelis, Candidatus Mycoplasma haemominutum, Candidatus Mycoplasma turicensis, feline leukaemia virus provirus, Leishmania spp. and Bartonella spp. Not all donors were tested for all agents. Overall, 5105 healthy indoor cats were tested and 8.1% (414/5105) had at least one subclinical infectious agent that is transmissible through blood product transfusion. 1.5% (77/5105) were positive for feline leukaemia virus antigens and 2.9% (148/5105) were positive for feline immunodeficiency virus antibodies, therefore they were excluded as donors. The overall prevalence of haemoplasmas in feline leukaemia virus and feline immunodeficiency virus SNAP-negative feline blood donors was 3.7% (181/4880) [1.3% (63/4880) were positive for Mycoplasma haemofelis; 2.3% (112/4880) to Candidatus Mycoplasma haemominutum and 0.12% (6/4880) to Candidatus Mycoplasma turicensis]. The prevalence of feline leukaemia provirus was 5.2% (9/173) and of Bartonella spp. was 0.2% (2/1122). None of the 173 cats were positive for Leishmania spp. The prevalence of many transfusion transmissible pathogens was relatively high in this healthy, client-owned, indoor cats eligible to become blood donors. Performing an extended screening panel that includes at least polymerase chain reactions for Mycoplasma haemofelis, Candidatus Mycoplasma haemominutum, Candidatus Mycoplasma turicensis, feline leukaemia virus provirus, and Bartonella spp., in addition to feline leukaemia virus antigens and feline immunodeficiency virus antibodies, is recommended in pet blood banks from analogous regions.", "journal": "The Journal of small animal practice", "doi": "10.1111/jsap.13257", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33290087", "author": "Chiu ES", "n_authors": 2, "title": "Endogenous Retroviruses Drive Resistance and Promotion of Exogenous Retroviral Homologs.", "abstract": "Endogenous retroviruses (ERVs) serve as markers of ancient viral infections and provide invaluable insight into host and viral evolution. ERVs have been exapted to assist in performing basic biological functions, including placentation, immune modulation, and oncogenesis. A subset of ERVs share high nucleotide similarity to circulating horizontally transmitted exogenous retrovirus (XRV) progenitors. In these cases, ERV-XRV interactions have been documented and include (", "journal": "Annual review of animal biosciences", "doi": "10.1146/annurev-animal-050620-101416", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33225861", "author": "Suzuki S", "n_authors": 5, "title": "Anti-CD71 antibody immunohistochemistry in the diagnosis of acute myeloid leukemia, subtype acute erythroid leukemia with erythroid dominance (AML M6-Er), in a retrovirus-negative cat.", "abstract": "CD71 is an immunohistochemical marker used in diagnosing acute myeloid leukemia (AML) M6-Er in humans; however, to our knowledge, it has not been reportedly used for immunohistochemistry in veterinary medicine. We evaluated the pathologic features of AML M6-Er in a retrovirus-negative cat and used CD71 to support the diagnosis. A 4-y-old spayed female Scottish Fold cat was presented with lethargy, anorexia, and fever. Whole-blood PCR assay results for pro feline leukemia virus/pro feline immunodeficiency virus and feline vector-borne diseases were negative. Early erythroid precursors were observed in the peripheral blood smear. Fine-needle aspiration of the enlarged spleen and splenic lymph node showed many early erythroid precursors. Bone marrow aspirate smears revealed erythroid hyperplasia with 68.4% erythroid lineage and 3.6% rubriblasts. Dysplastic cells infiltrated other organs. The patient was diagnosed with myelodysplastic syndrome, progressing to the early phase of AML M6-Er. The patient died on day 121 despite multidrug treatments. Postmortem examination revealed neoplastic erythroblasts infiltrating the bone marrow and other organs. Neoplastic cells were immunopositive for CD71 but immunonegative for CD3, CD20, granzyme B, von Willebrand factor, CD61, myeloperoxidase, and Iba-1. Although further studies are necessary for the application of CD71, our results supported the morphologic diagnosis of AML M6-Er.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/1040638720973403", "deposited_data": "Sim", "nuccore_ids": "2462592181, 2462592179, 2462592178, 2462592177, 2462592176, 2462592175, 2462592174, 2462592173, 2462592171, 2462592169, 2462592167, 2462592166, 2217345685, 1676362562, 1676317495, 1675178475, 1519315083", "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "32880509", "author": null, "n_authors": 0, "title": "LOPH: a novel chemotherapeutic protocol for feline high-grade multicentric or mediastinal lymphoma, developed in an area endemic for feline leukemia virus.", "abstract": null, "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X20957530", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "32684120", "author": "Horta RS", "n_authors": 7, "title": "LOPH: a novel chemotherapeutic protocol for feline high-grade multicentric or mediastinal lymphoma, developed in an area endemic for feline leukemia virus.", "abstract": "The aim of this study was to establish the safety and efficacy of a novel multidrug lomustine-based chemotherapeutic protocol for cats with high-grade multicentric or mediastinal lymphoma, in an area endemic for feline leukemia virus (FeLV). This prospective study included owned cats, diagnosed (cytologically) with multicentric or mediastinal lymphoma and treated with the LOPH (lomustine, vincristine [Oncovin; Antibióticos do Brasil], prednisolone and hydroxydaunorubicin [doxorubicin]) protocol. A complete blood count was performed before every chemotherapy session and any significant abnormalities recorded as possible related toxicities. Median survival time (MST) and disease-free interval were estimated by Kaplan-Meier curves. Twenty-one cats were included in this study. Nineteen (90.5%) tested positive for FeLV and were therefore considered to have persistent viremia. Complete response was reported in 81% (n = 17/21), while three had partial remission and one had no response. Seven cats finished the induction protocol within 20-31 weeks (23.1 ± 4.5; median 20) and all seven received a maintenance protocol. The MST (lymphoma-related survival) for the 21 cats was 214 days. The MST was 214 days for cats with mediastinal lymphoma (n = 13), but it was not reached for multicentric lymphoma (n = 8;  The LOPH protocol was well tolerated by cats with lymphoma and persistent FeLV viremia, and resulted in a better MST than similar studies with other protocols. Novel studies and controlled trials are necessary in order to evaluate the efficacy of different protocols according to the lymphoma subtype, anatomic form and FeLV status.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X20926893", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "36669015", "author": "Xiao X", "n_authors": 5, "title": "Two Multiplex PCR Methods for Detecting Several Pathogens Associated with Feline Respiratory and Intestinal Tracts.", "abstract": "Respiratory tract and intestinal diseases are common threats to feline health. Coinfection with multiple pathogens is not rare among clinical infectious cases. Rapid diagnosis of these coinfections is of great significance for timely and effective clinical treatment. In this study, two novel multiplex polymerase chain reactions (mPCRs) were established for simultaneous detection of four pathogens associated with the feline intestinal tract (feline coronavirus (FCoV), feline astrovirus (FeAstV), feline panleukopenia virus (FPV) and feline kobuvirus (FeKoV)) and five pathogens associated with the respiratory tract (feline calicivirus (FCV), feline herpesvirus 1 (FHV-1), feline leukemia virus (FeLV), ", "journal": "Veterinary sciences", "doi": "10.3390/vetsci10010014", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "36580443", "author": "Kent MS", "n_authors": 8, "title": "Longevity and mortality in cats: A single institution necropsy study of 3108 cases (1989-2019).", "abstract": "Client-owned cats who underwent a post-mortem examination (n = 3,108) at a veterinary medical teaching hospital between 1989 and 2019 were studied to determine longevity and factors affecting mortality. Demographic factors, environmental factors, age, and causes of death were assessed. Sexes included 5.66% intact females, 39.86% spayed females, 6.95% intact males and 47.49% neutered males. 84.2% were mixed breed cats. Age at death was known for 2,974 cases with a median of 9.07 years. Cancer was the most common pathophysiologic cause of death (35.81%) and was identified in 41.3% of cats. When categorized by organ system, mortality was most attributed to multiorgan/systemic (21.72%). Renal histologic abnormalities were noted in 62.84% of cats but was considered the primary cause of death in only 13.06% of cats. Intact female and male cats had significantly shorter lifespans than their spayed or neutered counterparts. FeLV positive status was associated with decreased longevity (P<0.0001) while FIV status was not. This study reports on risk factors associated with mortality and highlights areas of research that may contribute to improved lifespan in cats.", "journal": "PloS one", "doi": "10.1371/journal.pone.0278199", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "36560695", "author": "Spada E", "n_authors": 10, "title": "Do Blood Phenotypes of Feline AB Blood Group System Affect the SARS-CoV-2 Antibody Serostatus in Cats?", "abstract": "Cats are susceptible to coronavirus infections, including infection by human severe acute respiratory syndrome coronavirus (SARS-CoV). In human ABO system blood groups, alloantibodies can play a direct role in resistance to infectious diseases. Individuals with the AB blood type were over-represented in the SARS-CoV-2 infection group. Blood type AB individuals lack both anti-A and anti-B antibodies, and therefore lack the protective effect against SARS-CoV-2 infection given by these antibodies. Starting from this knowledge, this pilot preliminary study evaluated a possible association between feline blood phenotypes A, B, and AB and serostatus for SARS-CoV-2 antibodies in cats. We also investigated selected risk or protective factors associated with seropositivity for this coronavirus. A feline population of 215 cats was analysed for AB group system blood phenotypes and antibodies against the nucleocapsid (N-protein) SARS-CoV-2 antigen using a double antigen ELISA. SARS-CoV-2 seropositive samples were confirmed using a surrogate virus neutralization test (sVNT). Origin (stray colony/shelter/owned cat), breed (DSH/non DSH), gender (male/female), reproductive status (neutered/intact), age class (kitten/young adult/mature adult/senior), retroviruses status (seropositive/seronegative), and blood phenotype (A, B, and AB) were evaluated as protective or risk factors for SARS-CoV-2 seropositivity. Seropositivity for antibodies against the SARS-CoV-2 N-protein was recorded in eight cats, but only four of these tested positive with sVNT. Of these four SARS-CoV-2 seropositive cats, three were blood phenotype A and one was phenotype AB. Young adult age (1-6 years), FeLV seropositivity and blood type AB were significantly associated with SARS-CoV-2 seropositivity according to a univariate analysis, but only blood type AB (", "journal": "Viruses", "doi": "10.3390/v14122691", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "36552398", "author": "Edinboro CH", "n_authors": 1, "title": "Feral Cat Populations and Feline Retrovirus Prevalence in San Mateo County, California in Three Time Periods between 2001 and 2016.", "abstract": "This study was initiated in 2004 because the prevalence of feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) infections in feral cats in San Mateo County (SMC) was not known. The cities attributed to the feral cat population presented to the Peninsula Humane Society & SPCA’s Spay/Neuter Clinic and to the Shelter itself were analyzed to examine potential geographic concentrations of feral cats with positive retroviral status. Trends in FIV and FeLV status were examined in three 3-year periods (2001−2003, 2005−2007, and 2014−2016). Population trends over the 15 years of this study for feral cats admitted to the Shelter were also examined. In each study period, more female feral cats were presented to the S/N Clinic (54.06%, 57.37%, 54.89%). FIV prevalence increased from 5.52% to 6.41% (p = 0.29) from the first to third period; FeLV prevalence decreased significantly from 1.73% to 0.29% (p = 0.01). Significantly more FIV-positive males than females were identified each year and for each period (p < 0.01). The four largest SMC cities were the major source of feral cats to the Shelter, S/N Clinic, and of FIV- and FeLV-positive cats in the first two periods; in the third period, 50% of feral cats to the Shelter and of FeLV-positive cats were from these cities. Despite a 61.63% reduction in feral cat admissions to the S/N Clinic, the FIV prevalence for males remained similar and increased for females. The retrovirus prevalence suggests the need for continued testing and surveillance of FIV among SMC free-living cats.", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani12243477", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "36534205", "author": "Acevedo-Jiménez GE", "n_authors": 5, "title": "Detection and genetic characterization of feline retroviruses in domestic cats with different clinical signs and hematological alterations.", "abstract": "Feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) are globally distributed retroviruses that infect domestic cats and cause various syndromes that can lead to death. The aim of this study was to detect and genotype feline retroviruses in Mexican domestic cats. We used PCR assays to identify proviral DNA and viral RNA in 50 domestic cats with different clinical signs and hematological alterations. Endogenous FeLV (enFeLV) was identified in the genomic DNA of all cats in the study, and we detected transcripts of the LTR region of enFeLV in 48 individuals. Exogenous FeLV (exFeLV) was found in 13 cats. Furthermore, we detected FIV proviral DNA in 10 cats. The enFeLV sequences were shown to be the most variable, while the exFeLV sequences were highly conserved and related to previously reported subgroup A sequences. Sequencing of the FIV gag gene revealed the presence of subtype B in the infected cats.", "journal": "Archives of virology", "doi": "10.1007/s00705-022-05627-z", "deposited_data": "Sim", "nuccore_ids": "2281570017, 2281570015, 2281570013, 2281570011, 2281570009, 2281570007, 2281570005, 2281570003, 2281570001, 2281569999, 2281569998, 2281569997, 2281569996, 2281569995, 2281569994, 2281569993, 2281569992, 2281569991, 2281569990, 2281569989, 2281569988, 2281569987, 2281569986, 2281569985, 2281569984, 2281569983, 2281569982, 2281569981, 2281569980, 2281569979, 2281569978, 2281569977, 2281569976, 2281569975, 2281569974, 2281569973, 2281569972, 2281569971", "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "36467865", "author": "Gilbertson MLJ", "n_authors": 5, "title": "Paradoxes and synergies: optimizing management of a deadly virus in an endangered carnivore.", "abstract": "Pathogen management strategies in wildlife are typically accompanied by an array of uncertainties such as the efficacy of vaccines or potential unintended consequences of interventions. In the context of such uncertainties, models of disease transmission can provide critical insight for optimizing pathogen management, especially for species of conservation concern. The endangered Florida panther experienced an outbreak of feline leukemia virus (FeLV) in 2002-04, and continues to be affected by this deadly virus. Ongoing management efforts aim to mitigate the effects of FeLV on panthers, but with limited information about which strategies may be most effective and efficient.We used a simulation-based approach to determine optimal FeLV management strategies in panthers. We simulated use of proactive FeLV management strategies (i.e., proactive vaccination) and several reactive strategies, including reactive vaccination and test-and-removal. Vaccination strategies accounted for imperfect vaccine-induced immunity, specifically partial immunity in which all vaccinates achieve partial pathogen protection. We compared the effectiveness of these different strategies in mitigating the number of FeLV mortalities and the duration of outbreaks.Results showed that inadequate proactive vaccination can paradoxically increase the number of disease-induced mortalities in FeLV outbreaks. These effects were most likely due to imperfect vaccine immunity causing vaccinates to serve as a semi-susceptible population, thereby allowing outbreaks to persist in circumstances otherwise conducive to fadeout. Combinations of proactive vaccination with reactive test-and-removal or vaccination, however, had a synergistic effect in reducing impacts of FeLV outbreaks, highlighting the importance of using mixed strategies in pathogen management.", "journal": "The Journal of applied ecology", "doi": "10.1111/1365-2664.14165", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "36425135", "author": "Boonaramrueng K", "n_authors": 4, "title": "Risk factors of Bartonella spp. infection and the association between Bartonella spp. and T-lymphocyte subset alteration in asymptomatic retrovirus-infected cats in Bangkok Metropolitan, Thailand.", "abstract": "Cats are a reservoir for  We collected blood samples from 161 client-owned cats at veterinary clinics and hospitals throughout the Bangkok Metropolitan area from 2017 to 2020. The samples underwent hematological biochemical tests, feline retroviral status evaluation,  The prevalence of  In endemic countries or areas, cat owners must be made aware of the risk of exposure to ", "journal": "Veterinary world", "doi": "10.14202/vetworld.2022.2399-2406", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "36423192", "author": "Amoroso MG", "n_authors": 12, "title": "A Retrospective Study of Viral Molecular Prevalences in Cats in Southern Italy (Campania Region).", "abstract": "From 2019 to 2021, a retrospective molecular study was conducted in the Campania region (southern Italy) to determine the prevalence of viral diseases in domestic cats. A total of 328 dead animals were analyzed by Real-Time PCR for the presence of feline panleukopenia virus (FPV), feline leukemia virus (FeLV), feline enteric coronavirus (FCoV), rotavirus (RVA), feline herpesvirus type 1 (FHV-1), and feline calicivirus (FCV). The possible presence of SARS-CoV-2 was also investigated by Real-Time PCR. The cats included in this study were specifically sourced and referred by local veterinarians and local authorities to the Zooprofilactic Experimental Institute of Southern Italy (IZSM) for pathological evaluation. The samples consisted of owners, catteries, and stray cats. Results revealed: 73.5% positive cats for FPV (189/257), 23.6% for FeLV (21/89), 21.5% for FCoV (56/266), 11.4% for RVA (16/140), 9.05% for FeHV-1 (21/232), and 7.04 for FCV (15/213). In contrast, SARS-CoV-2 was never detected. FPV was more prevalent in winter (", "journal": "Viruses", "doi": "10.3390/v14112583", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "36419134", "author": "Simonato G", "n_authors": 10, "title": "First autochthonous clinical case of Hepatozoon silvestris in a domestic cat in Italy with unusual presentation.", "abstract": "Hepatozoon spp. is the causative agent of a vector-borne parasitic disease in many animal species. In felids, Hepatozoon felis, Hepatozoon canis and Hepatozoon silvestris have been molecularly isolated. Hepatozoonosis usually causes asymptomatic infections in domestic cats, but clinical cases have recently been reported in Europe. We describe the first Italian case of hepatozoonosis in a cat with an unusual presentation. An 11-year-old neutered European shorthair cat was urgently hospitalized for intestinal intussusception. Hematology, biochemistry, FIV-FeLV tests, blood smears and molecular investigation targeting the 18S rRNA gene of Hepatozoon spp. were performed on blood samples; in addition, histological and molecular investigations were performed to analyze surgical samples to identify Hepatozoon infection. Hepatozoon gamonts were detected in granulocytes in the blood smear, and Hepatozoon spp. DNA was confirmed by PCR on blood. The intussusception was caused by a sessile endoluminal nodule that was surgically removed. Histologically, many elements referring to parasitic tissue forms were identified in the intestinal cells, and then the specimens were molecularly confirmed to harbor H. silvestris. This is the first description of symptomatic hepatozoonosis in a domestic cat in Italy. Hepatozoon silvestris has been described in wild felids, which are usually resilient to the infection, whereas the domestic cat seems to be more susceptible. Indeed, H. silvestris in cats usually presents tropism for skeletal muscle and myocardium with subsequent clinical manifestations. This is the first description of a domestic cat with H. silvestris localized in the intestinal epithelium and associated with intussusception.", "journal": "Parasites & vectors", "doi": "10.1186/s13071-022-05534-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "36411402", "author": "Yang J", "n_authors": 9, "title": "Identification of crucial genes and metabolites regulating the eggshell brownness in chicken.", "abstract": "Protoporphyrin IX (Pp IX) is the primary pigment for brown eggshells. However, the regulatory mechanisms directing Pp IX synthesis, transport, and genetic regulation during eggshell calcification in chickens remain obscure. In this study, we investigated the mechanism of brown eggshell formation at different times following oviposition, using White Leghorn hens (WS group), Rhode Island Red light brown eggshell line hens (LBS group) and Rhode Island Red dark brown eggshell line hens (DBS group). At 4, 16 and 22 h following oviposition, Pp IX concentrations in LBS and DBS groups were significantly higher in shell glands than in liver (P < 0.05). Pp IX concentrations in shell glands of LBS and DBS groups at 16 and 22 h following oviposition were significantly higher than WS group (P < 0.05). In comparative transcriptome analysis, δ-aminolevulinate synthase 1 (ALAS1), solute carrier family 25 member 38 (SLC25A38), ATP binding cassette subfamily G member 2 (ABCG2) and feline leukemia virus subgroup C cellular receptor 1 (FLVCR1), which were associated with Pp IX synthesis, were identified as differentially expressed genes (DEGs). RT-qPCR results showed that the expression level of ALAS1 in shell glands was significantly higher in DBS group than in WS group at 16 and 22 h following oviposition (P < 0.05). In addition, four single nucleotide polymorphisms (SNPs) in ALAS1 gene that were significantly associated with eggshell brownness were identified. By identifying the differential metabolites in LBS and DBS groups, we found 11-hydroxy-E4-neuroprostane in shell glands and 15-dehydro-prostaglandin E1(1-) and prostaglandin G2 2-glyceryl ester in uterine fluid were related to eggshell pigment secretion. In this study, the regulatory mechanisms of eggshell brownness were studied comprehensively by different eggshell color and time following oviposition. Results show that Pp IX is synthesized de novo and stored in shell gland, and ALAS1 is a key gene regulating Pp IX synthesis in the shell gland. We found three transporters in Pp IX pathway and three metabolites in shell glands and uterine fluid that may influence eggshell browning.", "journal": "BMC genomics", "doi": "10.1186/s12864-022-08987-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "36374109", "author": "Petch RJ", "n_authors": 13, "title": "Feline Leukemia Virus Frequently Spills Over from Domestic Cats to North American Pumas.", "abstract": "Feline leukemia virus (FeLV) is a gammaretrovirus with horizontally transmitted and endogenous forms. Domestic cats are the primary reservoir species, but FeLV outbreaks in endangered Florida panthers and Iberian lynxes have resulted in mortalities. To assess prevalence and interspecific/intraspecific transmission, we conducted an extensive survey and phylogenetic analysis of FeLV infection in free-ranging pumas (", "journal": "Journal of virology", "doi": "10.1128/jvi.01201-22", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "36337180", "author": "Lorenzo V", "n_authors": 9, "title": "Clinical and magnetic resonance imaging features, and pathological findings of spinal lymphoma in 27 cats.", "abstract": "This multicentric retrospective study describes the clinical and MRI features and pathological studies of spinal lymphoma in 27 cats. MRI characteristics and their possible correlations with histopathological findings were studied. The most frequent neurological signs were rapidly progressive paraparesis (62.9%) or paraplegia (22.2%). Bimodal age distribution was found with 40.7% of cats aged ≤2.5 years (63.6% of them FeLV positive), and 44.4% of cats aged ≥8 years (16.7% of them FeLV positive). Spinal lymphoma was generally presented on MRI as an ill-defined epidural focal lesion with moderate to severe spinal cord compression, expanding more than one vertebral body. MRI lesions were typically localized in the lumbar vertebral segment (", "journal": "Frontiers in veterinary science", "doi": "10.3389/fvets.2022.980414", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "36324639", "author": "Santos CRGR", "n_authors": 6, "title": "Undetectable proviral DNA and viral RNA levels after raltegravir administration in two cats with natural feline leukemia virus infection.", "abstract": "Feline leukemia virus (FeLV) infection was discovered over 50 years ago; however, the serious clinical changes associated with FeLV infection still have great importance in the diagnosis, prevention, and clinical management of symptomatic patients. Progressive infection with FeLV leads to a reduction in the patient's life expectancy and quality of life. This report describes the use of an antiretroviral integrase inhibitor, raltegravir, in two cats with natural FeLV infection. Raltegravir was administered orally at a dose of 40 mg/cat every 12 h in both cases. In case one, 13 weeks after starting raltegravir, RNA loads were undetectable, while proviral DNA loads were still detectable. In case two, proviral DNA loads were undetectable after 32 weeks of medication, while RNA loads were undetectable throughout the treatment. No adverse effects or laboratory test abnormalities were detected with the use of raltegravir in either patient. The patients are currently clinically healthy, still receiving the drug, and are under close observation. To our knowledge, this is the first report describing the use of raltegravir in naturally infected FeLV-positive cats and its effects on circulating viral load. Moreover, the patients described here were followed-up for a longer period than those in previously reported cases.", "journal": "Brazilian journal of veterinary medicine", "doi": "10.29374/2527-2179.bjvm003522", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "36313565", "author": "Su X", "n_authors": 10, "title": "The prognostic marker FLVCR2 associated with tumor progression and immune infiltration for acute myeloid leukemia.", "abstract": "Acute myeloid leukemia (AML) is one of the most common hematopoietic malignancies in adults. The tumor microenvironment (TME) has a critical effect on AML occurrence, recurrence, and progression. The gene feline leukemia virus subgroup C cellular receptor family member 2 (FLVCR2) belongs to the major facilitator superfamily of transporter protein members, which is primarily involved in transporting small molecules. The potential role of FLVCR2 in the TME in AML has not been investigated. To clarify the expression and role of FLVCR2 in AML, we analyzed the Gene Expression Omnibus and The Cancer Genome Atlas databases and found that FLVCR2 mRNA expression significantly increased among patients with AML. Furthermore, based on an analysis of the Gene Expression Profiling Interactive Analysis database, FLVCR2 upregulation predicted dismal overall survival of patients with AML. Our validation analysis revealed the significant upregulation of FLVCR2 within the bone marrow of AML relative to healthy controls by western blotting and qPCR assays. Gene set enrichment analysis was conducted to explore FLVCR2's related mechanism in AML. We found that high FLVCR2 expression was related to infiltration degrees of immune cells and immune scores among AML cases, indicating that FLVCR2 possibly had a crucial effect on AML progression through the immune response. Specifically, FLVCR2 upregulation was negatively related to the immune infiltration degrees of activated natural killer cells, activated memory CD4", "journal": "Frontiers in cell and developmental biology", "doi": "10.3389/fcell.2022.978786", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "36185533", "author": "Rungsuriyawiboon O", "n_authors": 6, "title": "Risk factors and clinical and laboratory findings associated with feline immunodeficiency virus and feline leukemia virus infections in Bangkok, Thailand.", "abstract": "Feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) are retroviruses associated with chronic and neoplastic diseases in domestic and non-domestic cats. There has been increasing interest in the clinical importance of feline retroviruses in Thailand and the identification of associated risk factors in domestic cats. To prevent the spread of retroviral diseases and improve the management of retrovirus-infected cats, risk factors and associated clinical laboratory data must be clearly understood. This study aimed to identify the influence of household, lifestyle, health status, sterilization, clinical presentations, and laboratory findings on FIV- and FeLV-infected cats in Bangkok, Thailand. A total of 480 cats were evaluated for FeLV p27 antigen and FIV antibodies using Witness FeLV-FIV Rapid Test and SNAP FIV/FeLV Combo Test at a veterinary hospital service. Of the 480 cats tested, 113 were positive for virus infection, including 60 for FeLV (12.5%), 40 for FIV (8.3%), and 13 for both FeLV and FIV (2.7%). The findings revealed that the risk factors for cats infected with FeLV, FIV, or both FeLV and FIV were significantly different compared with those for non-infected cats (p < 0.05). Multivariate analysis showed that multi-cat ownership is a risk factor for the high prevalence of feline retrovirus infection, as multi-cat households exhibited a higher prevalence of infection than single-cat households. Anemic and sick cats were also at a greater risk of testing positive for specific retrovirus infections. FeLV-infected cats had a higher risk of anemia and low erythrocyte and thrombocyte counts (p ≤ 0.0001), whereas FIV-infected cats were more likely to have anemia and leukocytopenia than controls. Knowledge of the risk factors for retroviral diseases and associated clinical and laboratory findings can be used to develop strategies to reduce FIV and FeLV infections in cats.", "journal": "Veterinary world", "doi": "10.14202/vetworld.2022.1601-1609", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "36157183", "author": "Gilbertson MLJ", "n_authors": 17, "title": "Apathogenic proxies for transmission dynamics of a fatal virus.", "abstract": "Identifying drivers of transmission-especially of emerging pathogens-is a formidable challenge for proactive disease management efforts. While close social interactions can be associated with microbial sharing between individuals, and thereby imply dynamics important for transmission, such associations can be obscured by the influences of factors such as shared diets or environments. Directly-transmitted viral agents, specifically those that are rapidly evolving such as many RNA viruses, can allow for high-resolution inference of transmission, and therefore hold promise for elucidating not only which individuals transmit to each other, but also drivers of those transmission events. Here, we tested a novel approach in the Florida panther, which is affected by several directly-transmitted feline retroviruses. We first inferred the transmission network for an apathogenic, directly-transmitted retrovirus, feline immunodeficiency virus (FIV), and then used exponential random graph models to determine drivers structuring this network. We then evaluated the utility of these drivers in predicting transmission of the analogously transmitted, pathogenic agent, feline leukemia virus (FeLV), and compared FIV-based predictions of outbreak dynamics against empirical FeLV outbreak data. FIV transmission was primarily driven by panther age class and distances between panther home range centroids. FIV-based modeling predicted FeLV dynamics similarly to common modeling approaches, but with evidence that FIV-based predictions captured the spatial structuring of the observed FeLV outbreak. While FIV-based predictions of FeLV transmission performed only marginally better than standard approaches, our results highlight the value of proactively identifying drivers of transmission-even based on analogously-transmitted, apathogenic agents-in order to predict transmission of emerging infectious agents. The identification of underlying drivers of transmission, such as through our workflow here, therefore holds promise for improving predictions of pathogen transmission in novel host populations, and could provide new strategies for proactive pathogen management in human and animal systems.", "journal": "Frontiers in veterinary science", "doi": "10.3389/fvets.2022.940007", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "36136683", "author": "Rolph KE", "n_authors": 2, "title": "Infectious Causes of Neoplasia in the Domestic Cat.", "abstract": "In recent years, growing attention has been paid to the influence/role of infectious diseases in tumour development and progression. Investigations have demonstrated that some infectious organisms can have a direct role in the development of neoplasia, whereas others can predispose to neoplasia by alterations in the immune response, or by creating a pro-inflammatory environment. Feline leukaemia virus was one of the first infectious agents recognised as an oncogenic organism, and along with feline immunodeficiency virus has received the most attention. Since the discovery of this retrovirus, several other organisms have been associated with neoplastic processes in cats, these include gammaherpes virus, mouse mammary tumour virus, papillomaviruses, hepadnavirus, ", "journal": "Veterinary sciences", "doi": "10.3390/vetsci9090467", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35854050", "author": "Slaviero M", "n_authors": 8, "title": "Generalized and fatal felid alphaherpesvirus-1 natural infection with liver involvement in a feline leukaemia virus-positive adult cat: a case report.", "abstract": "Generalized and fatal felid alphaherpesvirus-1 (FeHV-1) natural infection with liver involvement is rarely reported in cats, and the occurrence of herpesvirus viraemia with internal organ histologic lesions in adult cats is unknown. A 1.5-year-old cat, female, mixed breed, positive for feline leukaemia virus (FeLV) presented in a veterinary teaching hospital with sneezing, nasal discharge, anorexia, and diarrhoea after two weeks, evolving to inspiratory dyspnoea. Complete blood count and serum biochemistry analysis showed marked leukopenia and thrombocytopenia. After clinical worsening and lack of treatment response, the cat was euthanized. Pathological findings included hepatic necrosis, fibrinonecrotic tracheitis, and bronchointerstitial pneumonia. Marked amounts of coccobacillary bacteria were observed covering the necrotic tracheal and bronchial mucosa, at the cytoplasm of alveolar macrophages, and free in alveoli lumen, mimicking a primary bacterial tracheitis and pneumonia. Both lung and tracheal bacteria exhibited marked immunolabeling in anti-Escherichia coli immunohistochemistry. In addition, rare epithelial cells of bronchi contained round, eosinophilic, intranuclear viral inclusion bodies (4-7 µm) that marginate the chromatin, characteristic of FeHV-1 infection. Strong multifocal anti-FeHV-1 immunolabeling was observed in necrotic epithelial cells of the liver, trachea, and lungs. Generalized herpesvirus infection with the occurrence of acute hepatic necrosis and severe respiratory illness is a potential differential diagnosis in FeLV-positive cats with respiratory signs. The immunodepression in these cats probably favours a FeHV-1 viraemia in addition to the development of opportunistic bacterial infections, such as Escherichia coli, and it is associated with a poor outcome.", "journal": "Veterinary research communications", "doi": "10.1007/s11259-022-09977-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35815910", "author": "Steenkamp G", "n_authors": 6, "title": "Sublingual papillomas of cheetahs in southern Africa.", "abstract": "Nine distinct papillomaviruses (Lambdapapillomavirus) have been described in domestic and nondomestic cats, but not in cheetahs. These viruses have been associated with cutaneous papillomas or plaques, bowenoid ", "journal": "Veterinary pathology", "doi": "10.1177/03009858221109610", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35814669", "author": "Shofa M", "n_authors": 5, "title": "Global Prevalence of Domestic Cat Hepadnavirus: An Emerging Threat to Cats' Health?", "abstract": "Hepatitis B is an infectious hepatocellular disease of global concern caused by hepatitis B virus (HBV), which belongs to ", "journal": "Frontiers in microbiology", "doi": "10.3389/fmicb.2022.938154", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35792756", "author": "Silva ARD", "n_authors": 10, "title": "The outcomes of polyparasitism in stray cats from Brazilian Midwest assessed by epidemiological, hematological and pathological data.", "abstract": "We evaluated the epidemiological, hematological, and pathological data of Leishmania spp., Toxoplasma gondii, Platynosomum illiciens, feline immunodeficiency virus (FIV), and feline leukemia virus (FeLV) infections and the coinfections in stray cats of an endemic area for leishmaniasis. The diagnosis was performed by serological tests and necropsy. We described gross lesions and histopathological findings. We used immunohistochemistry and chromogenic in situ hybridization for L. infantum detection. We found infection in 27 out of 50 sampled cats, among them, 14 presented coinfections. A strong correlation between splenomegaly and lymphadenomegaly with FeLV, and an association between hepatic lesions and cachexia with parasitism due to P. illiciens were observed. Moreover, we found a significant increase in the monocyte count in the FeLV-infected and a decrease in the red blood cell count in the FIV-infected animals. Amastigote forms of Leishmania spp. and tissue changes were detected in lymphoid organs of an animal coinfected with P. illiciens, T. gondii, and FIV. Polyparasitism recorded in stray cats of the Brazilian Midwest should be considered in effective control strategies for public health diseases. Moreover, stray cats of Campo Grande may be a source of infection of FIV, FeLV and P. illiciens for populations of domiciled cats.", "journal": "Revista brasileira de parasitologia veterinaria = Brazilian journal of veterinary parasitology : Orgao Oficial do Colegio Brasileiro de Parasitologia Veterinaria", "doi": "10.1590/S1984-29612022033", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35790167", "author": "Giselbrecht J", "n_authors": 4, "title": "[Feline leukemia virus infection - a guide to diagnosis].", "abstract": "Feline leukemia virus (FeLV) infection affects cats worldwide. The course of FeLV infection can change and vary over time. The complex pathogenesis, the availability of many different testing methods, and the interpretation of test results are often challenging for veterinarians. Cats with progressive infection (persistently p27 antigen-positive) shed FeLV mainly through saliva and are therefore considered a source of infection for uninfected cats. Diagnosing regressive infection is often challenging, since it usually cannot be detected by commonly used point of care-tests (p27 antigen test) and thus, it often remains undetected. Nevertheless, cats with regressive infection are FeLV carriers (provirus-positive) and when the immune system is suppressed, reactivation of the infection and FeLV-associated clinical signs can occur. Abortively infected cats are never viraemic, do not shed virus, and do not develop clinical signs. Abortive infection can solely be diagnosed via antibodies detection in blood. A new point-of-care test for the identification of antibodies against FeLV p15E antigen has recently been introduced on the European market and is currently being evaluated.", "journal": "Tierarztliche Praxis. Ausgabe K, Kleintiere/Heimtiere", "doi": "10.1055/a-1845-0750", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35763618", "author": "Villalba-Briones R", "n_authors": 5, "title": "Prevalence of Infection of Canine Distemper Virus, Feline Immunodeficiency Virus, and Feline Leukemia Virus in Wild Ecuadorian Ocelots; Efficacy of Their Diagnosis, and Recovery from Infection.", "abstract": "This retrospective study provides an analysis of the prevalence and detectability of canine distemper virus (CDV), feline leukemia virus (FeLV), and feline immunodeficiency virus (FIV) in ocelots (Leopardus pardalis) sheltered in a wild animal recovery center in Guayaquil, Ecuador. Blood samples of 19 rescued ocelots from 2019-20 were analyzed using FeLV p27 antigen enzyme-linked immunosorbent assays (ELISA) and commercial insulated isothermal reverse transcriptase PCR (iiRT-PCR) kits. Using this PCR we detected positive results for CDV (4/ 17; 23.5%) and FeLV (14/16; 87.5%), but not for FIV (0/8). Three previously positive cases of CDV and two of FeLV showed negative results on retesting 6 mo later. Moreover, a third analysis was conducted and was negative for CDV. Our results suggest that ocelots can recover from the local CDV and FeLV strains. An ELISA for the FeLV p27 antigen showed no capability to detect FeLV in ocelots that were confirmed positive by iiRT-PCR. Regional lineages, viral virulence, and host immune response capabilities should be addressed in further research to inform management and decision making for wildlife conservation.", "journal": "Journal of wildlife diseases", "doi": "10.7589/JWD-D-21-00123", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35749360", "author": "Miyake A", "n_authors": 7, "title": "Convergent evolution of antiviral machinery derived from endogenous retrovirus truncated envelope genes in multiple species.", "abstract": "Host genetic resistance to viral infection controls the pathogenicity and epidemic dynamics of infectious diseases. Refrex-1 is a restriction factor against feline leukemia virus subgroup D (FeLV-D) and an endogenous retrovirus (ERV) in domestic cats (ERV-DC). Refrex-1 is encoded by a subset of ERV-DC loci with truncated envelope genes and secreted from cells as a soluble protein. Here, we identified the copper transporter CTR1 as the entry receptor for FeLV-D and genotype I ERV-DCs. We also identified CTR1 as a receptor for primate ERVs from crab-eating macaques and rhesus macaques, which were found in a search of intact envelope genes capable of forming infectious viruses. Refrex-1 counteracted infection by FeLV-D and ERV-DCs via competition for the entry receptor CTR1; the antiviral effects extended to primate ERVs with CTR1-dependent entry. Furthermore, truncated ERV envelope genes found in chimpanzee, bonobo, gorilla, crab-eating macaque, and rhesus macaque genomes could also block infection by feline and primate retroviruses. Genetic analyses showed that these ERV envelope genes were acquired in a species- or genus-specific manner during host evolution. These results indicated that soluble envelope proteins could suppress retroviral infection across species boundaries, suggesting that they function to control retroviral spread. Our findings revealed that several mammalian species acquired antiviral machinery from various ancient retroviruses, leading to convergent evolution for host defense.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.2114441119", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35739908", "author": "Meepoo W", "n_authors": 4, "title": "Investigation of Bacterial Isolations and Antimicrobial Susceptibility of Chronic Rhinitis in Cats.", "abstract": "Chronic rhinitis is a quite common upper respiratory tract (URT) disease in cats. As a result of unclear etiology, frequently, multidrug-resistant bacteria are identified. This study investigated bacterial isolations and an antimicrobial susceptibility test (AST) in chronic rhinitis in cats. The medical records of 395 cats with chronic URT signs were reviewed at the Kasetsart University Veterinary Teaching Hospital (KUVTH) between 2016 and 2021 to survey the underlying causes of URT. Then, apart from rhinitis, other causes were excluded to identify the bacterial species and antimicrobial susceptibility. The results indicated that the most frequent finding was neoplasia, followed by rhinitis and anatomical defects. Furthermore, the only significant association was between the age range and disease group, with gender, FIV, or FeLV infection not being significant. Rhinitis was 4.7 times more likely to occur than neoplasia in younger and young adult cats in the age range < 1−3 years compared to the group > 10 years. The main bacterial species was the Pseudomonas species. Antimicrobials with a susceptibility rate of more than 90% were amikacin, gentamicin, ciprofloxacin, norfloxacin, marbofloxacin, imipenem, and meropenem. In conclusion, rhinitis was the second most common chronic URT disease in cats and was more common in younger and young adult cats. The predominant bacteria with AST in this study reflect the antimicrobial resistance situation. Thus, antimicrobial usage should follow antimicrobial use guidelines first.", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani12121572", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35720839", "author": "Györke A", "n_authors": 5, "title": "Case Report: Notoedric Mange and Aelurostrongylidosis in Two Domestic Cats From Rural Environment in Romania.", "abstract": "This article describes two cases of notoedric mange concurrent with aelurostrongylidosis in two domestic-owned cats from a rural environment in Romania. Two European shorthair cats originating from the same litter were referred to our clinic, at 2 months apart, with a history of skin lesions, pruritus, weight loss, and respiratory signs. Cats lived mainly outdoor together with the queen and a third littermate. The latter two expressed the same clinical signs and had died before the presentation of the first cat. None of the four cats was vaccinated, dewormed, or treated for external parasites. Coat brushing, skin scrapings, skin cytology, earwax direct microscopic examination, and coproparasitological techniques (flotation and Baermann methods) were used as laboratory procedures. A blood sample was also collected for hematology, blood biochemistry, and feline immunodeficiency virus/feline leukemia virus (FIV/FeLV) test. ", "journal": "Frontiers in veterinary science", "doi": "10.3389/fvets.2022.849525", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35719100", "author": "Fujii Y", "n_authors": 9, "title": "A frameshift variant in the EXT1 gene in a feline leukemia virus-negative cat with osteochondromatosis.", "abstract": "Osteochondromatosis is a benign proliferative disorder characterized by cartilage-capped bony protuberances. In humans and most mammals, variants in the EXT1 or EXT2 gene are strongly correlated with the etiology of osteochondromatosis. However, in cats, osteochondromatosis has only been associated with feline leukemia virus infection. In this study, to explore other factors involved in the etiology of feline osteochondromatosis, we examined the EXT1 and EXT2 genes in a feline leukemia virus-negative cat with osteochondromatosis. Genetic analysis revealed a heterozygous single base pair duplication in exon 6 of the EXT1 gene (XM_023248762.2:c.1468dupC), leading to a premature stop codon in the EXT1 protein. Notably, this frameshift variant is recognized as one of the most common pathogenic variants in human osteochondromatosis. Our data suggest for the first time that genetic variants can have etiologic roles in osteochondromatosis in cats, as in humans and other animals.", "journal": "Animal genetics", "doi": "10.1111/age.13232", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35679968", "author": "Alves ML", "n_authors": 11, "title": "Use of the intradermal leishmanin test (Montenegro skin test) for feline visceral leishmaniosis: Detection of cellular immunity.", "abstract": "This study evaluated the humoral and cellular response in 100 cats living in an endemic area of visceral leishmaniosis (VL) using the Montenegro Skin Test (MST) and serological diagnosis and compared the MST with other diagnostic techniques. Sixty 60%, (60/100) cats were positive for MST and the diameter of positive skin reactions ranged from 5 to 9 mm. By serological methods, 74% (74/100) and 34% (34/100) had antibodies against Leishmania spp. by Immunofluorescence Antibody Test (IFAT) and Indirect Enzyme-Linked Immunosorbent Assay (ELISA), respectively. Comparing tests, the observed profiles were (1) IFAT (+)/MST (-) = 27 cats, (2) IFAT(-)/MST(+) = 13 cats, (3) IFAT(+)/MST(+) = 47 cats, (4) ELISA(+)/MST(-) = 12 cats, (5) ELISA(-)/MST(+) = 38 cats and (6) ELISA(+)/MST(+) = 22 cats. Through the combination of serological diagnosis and MST, a positivity frequency of 87% (87/100) by IFAT + MST and 72% (72/100) by ELISA + MST was identified in this cat population. Five cats (5%) were positive for Leishmania donovani complex DNA by molecular analysis, and two cats (2%) had Leishmania spp. amastigotes in lymph node smears. Therefore, the agreement between tests was classified as poor for all tests by Kappa index. The IFAT (+)/MST (+) response was the most frequent considering all cats (47%; 47/100); nonetheless, the most frequent immune expression in Polymerase Chain Reaction (PCR)-positive cats was the IFAT (+)/MST (-) profile (80%; 4/5). Five sick and PCR-positive cats, negative for Feline Immunodeficiency Virus (FIV) and Feline Leukemia Virus (FeLV), that PCR sequencing matched 100% with L. donovani complex, all but one were MST negative. These results suggest that cats develop a significant cellular response against infection by parasites of the L. donovani complex, and most PCR and parasitological positive cats may be unable to develop a significant cellular response.", "journal": "Experimental parasitology", "doi": "10.1016/j.exppara.2022.108294", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35652657", "author": "Tury S", "n_authors": 6, "title": "Identification of Copper Transporter 1 as a Receptor for Feline Endogenous Retrovirus ERV-DC14.", "abstract": "Vertebrates harbor hundreds of endogenous retroviral (ERV) sequences in their genomes, which are considered signs of past infections that occurred during evolution. On rare occasions, ERV genes like ", "journal": "Journal of virology", "doi": "10.1128/jvi.00229-22", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35635064", "author": "Spada E", "n_authors": 11, "title": "Lack of association between feline AB blood groups and retroviral status: a multicenter, multicountry study.", "abstract": "The relationship between blood group antigens and disease has been studied in humans. Blood types have been associated with both decreased and increased rates of various infections. In addition, blood group expression has been shown to vary with some cancers and gastrointestinal diseases. The objective of this study was to explore whether there is a relationship between blood type and retroviral infections in cats. Case records from a veterinary research laboratory, veterinary teaching hospitals and veterinary blood banks were retrospectively searched for cats where both blood type and retroviral status (feline leukemia [FeLV], feline immunodeficiency virus [FIV] or both) were listed (part 1). In addition, a sample of 33 cats with confirmed FIV infection was genotyped to determine blood groups (part 2). In part 1, 709 cats were identified, 119 of which were positive for retroviral infection. Among all cases, 621 were type A (87.6%), 68 were type B (9.6%) and 20 were type AB (2.8%). There was no relationship between overall retroviral status (positive/negative) and blood type ( No relationship was identified between feline retroviral status and blood type in this study. The relationship between blood type and other disease states requires further study in veterinary patients.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X221100082", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35632665", "author": "Hartmann K", "n_authors": 16, "title": "Vaccination of Immunocompromised Cats.", "abstract": "Immunocompromise is a common condition in cats, especially due to widespread infections with immunosuppressive viruses, such as feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV), but also due to chronic non-infectious diseases, such as tumours, diabetes mellitus, and chronic kidney disease, as well as treatment with immunosuppressive drugs, such as glucocorticoids, cyclosporins, or tumour chemotherapy. In this review, the European Advisory Board on Cat Diseases (ABCD), a scientifically independent board of experts in feline medicine from eleven European countries, discusses the current knowledge and rationale for vaccination of immunocompromised cats. So far, there are few data available on vaccination of immunocompromised cats, and sometimes studies produce controversial results. Thus, this guideline summarizes the available scientific studies and fills in the gaps with expert opinion, where scientific studies are missing. Ultimately, this review aims to help veterinarians with their decision-making in how best to vaccinate immunocompromised cats.", "journal": "Viruses", "doi": "10.3390/v14050923", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35619142", "author": "Carneiro RL", "n_authors": 13, "title": "First description of a multisystemic and lethal SARS-CoV-2 variant of concern P.1 (Gamma) infection in a FeLV-positive cat.", "abstract": "Phylogenetic studies indicate bats as original hosts of SARS-CoV-2. However, it remains unclear whether other animals, including pets, are crucial in the spread and maintenance of COVID-19 worldwide. In this study, we analyzed the first fatal case of a SARS-CoV-2 and FeLV co-infection in an eight-year-old male cat. We carried out a clinical evaluation and several laboratory analyses. As main results, we observed an animal presenting severe acute respiratory syndrome and lesions in several organs, which led to the animal's death. RT-qPCR analysis showed a SARS-CoV-2 as the causative agent. The virus was detected in several organs, indicating a multisystemic infection. The virus was found in a high load in the trachea, suggesting that the animal may have contribute to the transmission of the virus. The whole-genome sequencing revealed an infection by SARS-CoV-2 Gamma VOC (P.1), and any mutations indicating host adaptation were observed. Our data show that FeLV-positive cats are susceptible to SARS-CoV-2 infection and raise questions about the potential of immunocompromised FeLV-positive cats to act as a reservoir for SARS-CoV-2 new variants.", "journal": "Virology journal", "doi": "10.1186/s12985-022-01816-z", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35565499", "author": "Kusuda S", "n_authors": 7, "title": "Fecal Glucocorticoid Metabolites as a Noninvasive Indicator of Stress in the Tsushima Leopard Cats (Prionailurus bengalensis euptilurus): Application to Health Care.", "abstract": "This study investigates whether the measurement of glucocorticoid metabolites (GCMs) in feces is a useful method for the noninvasive evaluation of stress in the endangered Tsushima leopard cats (", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani12091072", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35405890", "author": "Sunpongsri S", "n_authors": 6, "title": "Effectiveness and Adverse Events of Cyclophosphamide, Vincristine, and Prednisolone Chemotherapy in Feline Mediastinal Lymphoma Naturally Infected with Feline Leukemia Virus.", "abstract": "Feline leukemia virus (FeLV) infection is considered a poor prognostic factor for feline lymphoma. This study investigated the prevalence of cats suffering from feline lymphoma with natural infection of the feline leukemia virus, as well as clinical signs, adverse events, and survival time after cyclophosphamide, vincristine and prednisolone (COP) chemotherapy. This retrospective study involved 92 cats diagnosed with mediastinal or mediastinal plus other anatomical sites of lymphoma and treated with COP chemotherapy. FeLV-antigen-positive was observed in all cats. Clinical signs and adverse events were observed after the 1st, 2nd, and 3rd inductions. Clinical signs improved after the 3rd induction of COP chemotherapy. The response rate was 96.74% (81.52% complete response, 15.22% partial response, and 3.26% no response). The overall median survival time was 338 days (range 62−1057 days). The overall response rate and median survival time of cats with feline lymphoma that were FeLV-antigen-positive and treated with COP chemotherapy were higher than from other studies. This study found that cats aged <4 years survived longer than those aged at least 4 years. Anemia (before COP), azotemia (after 2nd induction), and elevated alanine aminotransferase (after 1st induction) were associated with an increased chance of mortality.", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani12070900", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35390075", "author": "Pare A", "n_authors": 3, "title": "Clinicopathological findings of FeLV- positive cats at a secondary referral center in Florida, USA (2008-2019).", "abstract": "The aim of this study was to describe the seroprevalence, presenting complaint, clinicopathological changes, co-morbidities and outcomes of feline leukemia virus positive cats presented to a specialty referral center in Florida, USA. In this retrospective study, medical records of 8050 cats presented to a private referral center from August 2008 to September 2019 were reviewed. Inclusion criteria required was a positive result for feline leukemia virus by point-of-care antigen testing or immunofluorescence assay. Forty-one cases met the inclusion criteria. Of 2002 cats that were tested, 41 cats (2%) met the inclusion criteria. One cat had a negative point of care antigen test result and positive bone marrow IFA result. The mean age at diagnosis was 9 years. The main reasons for presentation were abnormal complete blood cell count results (35%), followed by pleural effusion (18%), and anorexia (15%). The most common laboratory abnormalities included anaemia (71%), of which 74% had a nonregenerative anemia, thrombocytopenia (52%), elevated aspartate aminotransferase (50%), hyperbilirubinemia (35%), and hypokalemia (35%). Seven percent of cats (3/41) were also positive for feline immunodeficiency virus. The most common diagnoses were neoplasia (76%) and bone marrow disorders (12%). Cats with neoplasia were significantly younger. Survival to discharge was 88%. Results of this study show that feline leukemia virus is uncommon in secondary referral center, even if this represents a population of unhealthy cats. The most common associated diagnosis was neoplasia, which was more likely to be seen in younger cats (< 4 years of age). The mean age of cats positive for feline leukemia virus was also older than previously published data. These findings support the current guidelines which indicate that cats presented with clinical illness should be tested for FeLV at the time of presentation.", "journal": "PloS one", "doi": "10.1371/journal.pone.0266621", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35385154", "author": "Nivy R", "n_authors": 7, "title": "Treatment of a cat with presumed Bartonella henselae-associated immune-mediated hemolytic anemia, fever, and lymphadenitis.", "abstract": "A 2.5-year-old castrated male cat presented with fever and marked generalized lymphadenopathy of 4-months duration, despite treatment with amoxicillin-clavulanate/marbofloxacin. Abnormalities were not detected on complete blood count, serum chemistry, and FIV/FeLV test apart from a borderline, non-regenerative anemia. Peripheral lymph node fine needle aspirations revealed a marked increase in the percentage of intermediate- and lymphoblastic-lymphocytes in addition to reactive macrophages. Three weeks after presentation, the cat developed a severe, regenerative, immune-mediated hemolytic anemia (IMHA) which responded to immunosuppressive therapy. Fever and lymphadenopathy persisted. Peripheral lymph nodes tested positive for Bartonella henselae DNA in real-time PCR assay and sequencing. Treatment with pradofloxacin and doxycycline resulted in resolution of clinical signs, and negative PCR tests. Despite its reported low pathogenicity, B. henselae infection should also be considered in cats with protracted unexplained fever, lymphadenitis, and IMHA. Furthermore, a combination of pradofloxacin and doxycycline might be considered in cats with bartonellosis given its apparent clinical efficacy.", "journal": "Journal of veterinary internal medicine", "doi": "10.1111/jvim.16415", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35324834", "author": "Deschamps JY", "n_authors": 3, "title": "Xenotransfusion of Blood from Dog to Cat: Should Canine Blood Be Our First Choice for Feline Transfusion in Emergency Situations?", "abstract": "Despite the ability to determine feline blood types, the transfusion of canine blood to cats is still practiced in some countries. Xenotransfusion is effective-even if its effects only last for a few days-and is not associated with serious adverse effects. It avoids the need for blood typing, and most importantly, it avoids the transmission of intraspecific infectious agents, notably the feline leukemia virus (FeLV). Transfusion with canine blood is easier, quicker and less costly than transfusion with feline blood; it is less disagreeable for the donor. In the light of these arguments, when feline blood collected according to current guidelines is not available, in particular when the donor is not confirmed to be negative for the FeLV provirus, the authors consider it to be judicious to use canine blood for feline transfusion in emergency situations; this practice is preferable to inaction and to the inoculation of an infectious agent. Allotransfusion remains preferable in non-emergency situations as a treatment of chronic compensated anaemiae or if an appropriate donor (negative for FeLV provirus) is available. However, 2-4 days after a xenotransfusion, if a clinical alteration and a significant decrease in haematocrit are observed, a transfusion with cat's blood confirmed to be negative for FeLV provirus should be performed. Xenotransfusion should never be used twice.", "journal": "Veterinary sciences", "doi": "10.3390/vetsci9030106", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35319227", "author": "Hötzel I", "n_authors": 1, "title": "Deep-Time Structural Evolution of Retroviral and Filoviral Surface Envelope Proteins.", "abstract": "The retroviral surface envelope protein subunit (SU) mediates receptor binding and triggers membrane fusion by the transmembrane (TM) subunit. SU evolves rapidly under strong selective conditions, resulting in seemingly unrelated SU structures in highly divergent retroviruses. Structural modeling of the SUs of several retroviruses and related endogenous retroviral elements with AlphaFold 2 identifies a TM-proximal SU β-sandwich structure that has been conserved in the orthoretroviruses for at least 110 million years. The SU of orthoretroviruses diversified by the differential expansion of the β-sandwich core to form domains involved in virus-host interactions. The β-sandwich domain is also conserved in the SU equivalent GP", "journal": "Journal of virology", "doi": "10.1128/jvi.00063-22", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35268230", "author": "Thuesen IS", "n_authors": 5, "title": "How Serious Are Health-Related Welfare Problems in Unowned Unsocialised Domestic Cats? A Study from Denmark Based on 598 Necropsies.", "abstract": "Free ranging unsocialised domestic cats are widely believed to suffer from a high load of welfare problems. We assessed the validity of this belief by performing necropsies on the corpses of 598 unsocialised cats, originating from all parts of Denmark, that had been euthanised by two Danish cat welfare organisations. We selected a number of variables for health-related cat welfare that could be assessed through necropsy (e.g., gross lesions, ectoparasites and body condition) or by laboratory analysis (e.g., infection with feline immunodeficiency virus (FIV), and by feline leukaemia virus (FeLV)). Each finding was classified as having either a major or minor welfare impact on the cat. More than 83% of the cats had no major finding, and 54% had no finding indicating a welfare issue at all. More than 83% of the cats had a body condition within normal range. Only 0.3% were emaciated. The most common finding was infestation with ectoparasites, with 15.9% infected with lice, 12.3% with fleas, 4.7% with ticks, and 6.7% with ear mites. FIV and FeLV were detected in 9.2% and 1.2% of the cases, respectively. The most common lesion related to the cats' teeth. Overall, unsocialised cats in Denmark have a moderate level of health-related welfare problems.", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani12050662", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35224084", "author": "Alberigi B", "n_authors": 12, "title": "Feline Heartworm in Clinical Settings in a High Canine Prevalence Area.", "abstract": "Heartworm (HTW) infection in cats is associated with persistent pulmonary pathology, even when clinical signs are absent. Treatment options for cats are limited once infected, making prevention an important topic for discussion with cat owners. In Brazil, tests to detect feline HTW infections are unavailable, likely leading to an underestimation of its impact on the wellbeing of cats. The present study investigated the seroprevalence of HTW antigen in cats living in an area with high canine HTW prevalence and investigated risk factors and clinical signs associated with HTW disease in cats from Rio de Janeiro, Brazil. Clinical examinations were conducted, and serological evaluations performed with a point-of-care test (SNAP", "journal": "Frontiers in veterinary science", "doi": "10.3389/fvets.2022.819082", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35215842", "author": "Cano-Ortiz L", "n_authors": 5, "title": "Could Phylogenetic Analysis Be Used for Feline Leukemia Virus (FeLV) Classification?", "abstract": "The surface envelope (SU) protein determines the cell tropism and consequently the pathogenesis of the feline leukemia virus (FeLV) in felids. Recombination of exogenous FeLV (exFeLV) with endogenous retroviruses (enFeLV) allows the emergence of more pathogenic variants. Currently, phenotypic testing through interference assays is the only method to distinguish among subgroups-namely, FeLV-A, -B, -C, -E, and -T. This study proposes a new method for FeLV classification based on molecular analysis of the ", "journal": "Viruses", "doi": "10.3390/v14020249", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35211532", "author": "Sprißler F", "n_authors": 7, "title": "Prevalence and Risk Factors of Feline Immunodeficiency Virus and Feline Leukemia Virus Infection in Healthy Cats in Thailand.", "abstract": "Infections with feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) occur worldwide and are among the most important infectious diseases in cats. The aim of the present study was to determine the prevalence of FIV and FeLV infection in healthy outdoor cats in North, Northeast and Central Thailand. So far, a study on retrovirus prevalence of healthy cats in Thailand in a larger geographic area has not been published yet. In addition, risk factors for FIV and FeLV infections were evaluated. Two hundred sixty healthy cats were prospectively recruited. They originated from 13 locations in North, Northeast, and Central Thailand and were presented for either preventive health care and/or neutering. In each cat, a physical examination was performed to confirm health status. FIV and FeLV status was determined using a commercial rapid enzyme-linked immunosorbent assay (ELISA) (SNAP Combo Plus FeLV/FIV, IDEXX). Risk factors were analyzed by binary logistic regression analysis. Samples of 15/260 (5.8%) cats were positive for FIV antibodies, and 11/260 (4.2%) samples were positive for FeLV antigen. One of the 260 (0.4%) cats was positive for both, FIV and FeLV infection. In binary logistic regression analysis, no parameter was associated with a higher risk for FeLV infection. However, cats had a significantly (", "journal": "Frontiers in veterinary science", "doi": "10.3389/fvets.2021.764217", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35202311", "author": "Szilasi A", "n_authors": 5, "title": "In Situ Hybridization of Feline Leukemia Virus in a Case of Osteochondromatosis.", "abstract": "Osteochondromatosis, also known as multiple cartilaginous exostosis, polyostotic osteochondroma, and multiple osteochondromas, comprises one-fifth of all primary bone tumors in cats, with no breed or sex predisposition or hereditary pattern. Unlike in dogs, horses, and humans, it is predominantly seen in young cats (2-4 years old), after the maturation of the skeleton. Although the pathogenesis of osteochondromatosis is not fully understood, it is considered to be related to infection by feline leukemia virus (FeLV) or other retroviruses, such as the feline sarcoma virus. However, the presence of viral particles within tumor lesions has only been demonstrated by electron microscopy. The malignant transformation of osteochondromas, most typically to osteosarcoma or chondrosarcoma, has also been attributed to the viral infection. Here we report the case of osteochondromatosis in a 3.5-year-old male domestic European shorthair cat with concurrent FeLV infection confirmed by polymerase chain reaction. Viral RNA was visualized in representative tissues (spleen, mesenteric lymph node, liver, kidney, lung, brain) and in the osteochondromas with RNAscope in situ hybridization, which supports that FeLV infection may be involved in the pathogenesis of osteochondromatosis.", "journal": "Veterinary sciences", "doi": "10.3390/vetsci9020059", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35202303", "author": "Antognoni MT", "n_authors": 7, "title": "Cytauxzoon sp. Infection and Coinfections in Three Domestic Cats in Central Italy.", "abstract": "Cytauxzoonosis is an emerging disease caused by a tick-transmitted haemoprotozoan affecting domestic and wild felids. The clinical and biomolecular findings of the infection due to ", "journal": "Veterinary sciences", "doi": "10.3390/vetsci9020050", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35173973", "author": "Ishikawa K", "n_authors": 9, "title": "Primary pulmonary diffuse large B-cell lymphoma associated with feline leukaemia virus infection in a young cat.", "abstract": "A 4-year-old castrated male domestic shorthair cat with a continuous cough was brought to a private veterinary clinic for detailed examination. Radiography of the thoracic cavity revealed a severe radiopaque region in the caudal lobe of the right lung. At 108 days after the initial visit, CT showed a mass of 27 × 23 × 18 mm in the caudal lobe of the right lung. At that time, no abnormalities in other organs except for the lung were detected on CT and peripheral blood and blood biochemistry tests. The mass in the caudal lobe of the right lung was resected by lobectomy; it had a white surface and was firm. Histopathologically, the mass was non-encapsulated, showing an unclear boundary with surrounding tissues. The mass comprised large, round or polygonal neoplastic cells arranged in a diffuse pattern. Immunohistochemically, neoplastic cells were diffusely positive for CD20, feline leukaemia virus (FeLV) p27 and FeLV glycoprotein 70 but negative for CD3, CD204 and E-cadherin. Based on these findings, diffuse large B-cell lymphoma associated with FeLV infection was diagnosed. Although the cat showed no clinical signs of gastrointestinal or respiratory injury, a routine ultrasonography revealed thickening in the jejunum wall 196 days after lobectomy, and subsequent fine-needle aspiration examination confirmed high-grade lymphoma. This is the first report of primary pulmonary diffuse large B-cell lymphoma associated with FeLV infection in a young cat.", "journal": "JFMS open reports", "doi": "10.1177/20551169221074240", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35158547", "author": "Jaroensong T", "n_authors": 3, "title": "Effects of Chemotherapy on Hematological Parameters and CD4(+)/CD8(+) Ratio in Cats with Mediastinal Lymphoma and Seropositive to Feline Leukemia Virus.", "abstract": "The objective of this study was to evaluate the effect of the COP chemotherapeutic protocol on hematological parameters, CD4", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani12030223", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35152562", "author": "Huang S", "n_authors": 15, "title": "Prevalence of four viruses in captive Siberian tigers from Northeastern China.", "abstract": "Our study investigated the prevalence of feline herpesvirus-1 (FHV-1), feline calicivirus (FCV), feline immunodeficiency virus (FIV), and feline leukemia virus (FeLV) in captive Siberian tigers in Northeastern China. A total of 324 blood samples and 33 nasopharyngeal swab samples of Siberian tigers collected from 2019 to 2021 in three cities were investigated by nested PCR. The results showed that 28.1% (91/324) tigers were infected with at least one virus; the positive rates of FHV-1, FCV, and FIV were 17.3%, 13.6%, and 0.9%, respectively; and the coinfection prevalence was 13.2%. No FeLV-positive sample was detected. And we found that the blood is the best for FCV, FIV, and FeLV detection, but nasopharyngeal swabs for FHV-1. By comparing the gD genes, TK gene, and gI gene of FHV-1, the homology of the three FHV-1 positive strains in this study was found to be 91.5%-99.9% shared with tigers and domestic cats. Based on a comparison of the nucleic acid sequences of 13 FCV strains, we found that the homology of strain HB-1926 with the other strains in this study was only about 77.7%, but shared 99.3% and 98.6% homology with Urnaba strain in American cat and TG1 strain in Chinese tiger, respectively. However, the other 12 FCV strains shared 87.1%-87.5% homology compared with the Chinese domestic cats. Phylogenetic tree analysis showed that the HB-1926 strain was not in the same clade as other strains. The fragments gag-p26, pol-RT, and pol-RNAse of Siberian tiger FIV shared more than 99% homology than domestic cats FIV subtype A. This study demonstrated that captive Siberian tigers in Northeastern China were exposed to FHV-1, FCV, and FIV, and it is necessary to develop more effective vaccines and improve daily management measures.", "journal": "Transboundary and emerging diseases", "doi": "10.1111/tbed.14475", "deposited_data": "Sim", "nuccore_ids": "2199429182, 2199429180, 2199429178, 2199429176, 2199429174, 2199429172, 2199429170, 2199429168, 2199429166, 2199429164, 2199429162, 2199429160, 2199429158", "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35034833", "author": "Malter KB", "n_authors": 7, "title": "Variability in non-core vaccination rates of dogs and cats in veterinary clinics across the United States.", "abstract": "Vaccination guidelines for dogs and cats indicate that core vaccines (for dogs, rabies, distemper, adenovirus, parvovirus; for cats, feline parvovirus, herpes virus-1, calicivirus) are essential to maintain health, and that non-core vaccines be administered according to a clinician's assessment of a pet's risk of exposure and susceptibility to infection. A reliance on individual risk assessment introduces the potential for between-practice inconsistencies in non-core vaccine recommendations. A study was initiated to determine non-core vaccination rates of dogs (Leptospira, Borrelia burgdorferi, Bordetella bronchiseptica, canine influenza virus) and cats (feline leukemia virus) in patients current for core vaccines in veterinary practices across the United States. Transactional data for 5,531,866 dogs (1,670 practices) and 1,914,373 cats (1,661 practices) were retrieved from practice management systems for the period November 1, 2016 through January 1, 2020, deidentified and normalized. Non-core vaccination status was evaluated in 2,798,875 dogs and 788,772 cats that were core-vaccine current. Nationally, median clinic vaccination rates for dogs were highest for leptospirosis (70.5%) and B. bronchiseptica (68.7%), and much lower for canine influenza (4.8%). In Lyme-endemic states, the median clinic borreliosis vaccination rate was 51.8%. Feline leukemia median clinic vaccination rates were low for adult cats (34.6%) and for kittens and 1-year old cats (36.8%). Individual clinic vaccination rates ranged from 0 to 100% for leptospirosis, B. bronchiseptica and feline leukemia, 0-96% for canine influenza, and 0-94% for borreliosis. Wide variation in non-core vaccination rates between clinics in similar geographies indicates that factors other than disease risk are driving the use of non-core vaccines in pet dogs and cats, highlighting a need for veterinary practices to address gaps in patient protection. Failure to implement effective non-core vaccination strategies leaves susceptible dogs and cats unprotected against vaccine-preventable diseases.", "journal": "Vaccine", "doi": "10.1016/j.vaccine.2022.01.003", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "34954236", "author": "Cano-Ortiz L", "n_authors": 12, "title": "Feline Leukemia Virus-B Envelope Together With its GlycoGag and Human Immunodeficiency Virus-1 Nef Mediate Resistance to Feline SERINC5.", "abstract": "Human SERINC5 (SER5) protein is a recently described restriction factor against human immunodeficiency virus-1 (HIV-1), which is antagonized by HIV-1 Nef protein. Other retroviral accessory proteins such as the glycosylated Gag (glycoGag) from the murine leukemia virus (MLV) can also antagonize SER5. In addition, some viruses escape SER5 restriction by expressing a SER5-insensitive envelope (Env) glycoprotein. Here, we studied the activity of human and feline SER5 on HIV-1 and on the two pathogenic retroviruses in cats, feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV). HIV-1 in absence of Nef is restricted by SER5 from domestic cats and protected by its Nef protein. The sensitivity of feline retroviruses FIV and FeLV to human and feline SER5 is considerably different: FIV is sensitive to feline and human SER5 and lacks an obvious mechanism to counteract SER5 activity, while FeLV is relatively resistant to SER5 inhibition. We speculated that similar to MLV, FeLV-A or FeLV-B express glycoGag proteins and investigated their function against human and feline SER5 in wild type and envelope deficient virus variants. We found that the endogenous FeLV recombinant virus, FeLV-B but not wild type exogenous FeLV-A envelope mediates a strong resistance against human and feline SER5. GlycoGag has an additional but moderate role to enhance viral infectivity in the presence of SER5 that seems to be dependent on the FeLV envelope. These findings may explain, why in vivo FeLV-B has a selective advantage and causes higher FeLV levels in infected cats compared to infections of FeLV-A only.", "journal": "Journal of molecular biology", "doi": "10.1016/j.jmb.2021.167421", "deposited_data": "Sim", "nuccore_ids": "2462601969, 2462601967, 2462601965, 2217355471, 2217355469, 2217355468, 1701216772, 1700660365, 1675150712, 1675115504, 1519241846", "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "34931442", "author": "Vaughan DP", "n_authors": 2, "title": "Extending the phenotype of posterior column ataxia with retinitis pigmentosa caused by variants in FLVCR1.", "abstract": "Posterior column ataxia with retinitis pigmentosa (PCARP) is a rare autosomal recessive condition due to variants in the Feline Leukemia Virus Subgroup C Cellular Receptor 1 (FLVCR1) gene which was first described in 1997. In this article, we describe a young female patient with a childhood diagnosis of retinitis pigmentosa and learning disability, presenting with progressive ataxia from her late teens. Examination revealed spastic lower limbs with absent reflexes, and reduced vibration and joint position sensation. Magnetic resonance imaging showed normal cerebellar volume and linear signal abnormality within the posterior columns of her spinal cord. Trio exome analysis confirmed two variants in FLVCR1. Our case extends the phenotype of PCARP to include learning disability and developmental delay, and highlights the importance of considering this rare condition in young adults or children with visual impairment and ataxia.", "journal": "American journal of medical genetics. Part A", "doi": "10.1002/ajmg.a.62612", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "34911870", "author": "Shimoda T", "n_authors": 13, "title": "Monoblastic leukemia (M5a) with chronic basophilic leukemia in a cat.", "abstract": "A cat was presented with depression and anorexia. The complete blood cell count (CBC) revealed non-regenerative anemia (PCV, 8.5%), marked thrombocytopenia (2,400/µl), and leukocytosis (32,090/µl). In the peripheral blood, proliferation of blast cells (85%; 27,276/µl) and basophils (7.7%; 2,460/µl) was observed. Bone marrow aspirate showed hyperplasia with 8.8% blasts and 90.2% basophils of all nucleated cells. The blast cells were negative for myeloperoxidase staining and positive for alpha-naphthol butyrate esterase staining, indicating the agranular blasts are monoblasts. Thus, acute monoblastic leukemia (M5a) with chronic basophilic leukemia was diagnosed. Basophils accounted for more than 40% of the bone marrow, and we diagnosed secondary basophilic leukemia. Secondary basophilic leukemia should be included in the differential list when abnormal basophil increases are observed in feline bone marrow.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.21-0383", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "34739587", "author": "Lin L", "n_authors": 6, "title": "Molecular epidemiology of type I and II feline coronavirus from cats with suspected feline infectious peritonitis in China between 2019 and 2021.", "abstract": "Feline infectious peritonitis (FIP) is one of the deadliest diseases of cats in China. In this study, 120 ascitic fluid samples from FIP-suspected cats were collected from veterinary hospitals in 21 provinces in China between 2019 and 2021. One hundred nine samples were positive for feline coronavirus (FCoV), with no feline immunodeficiency virus infections and one feline leukemia virus infection (1/109, 0.92%). The prevalence of FCoV was significantly associated with age (p < 0.01) and was not highly associated with gender, breed, geographical location, or viral coinfection (p > 0.01). One unique strain, SD/202012/003, contained a six-nucleotide deletion in the spike gene. Sequence analysis showed that 94.68% (89/94) of the isolates had a mutation of methionine to leucine at position 1058 in the spike protein. The epidemiological data obtained of FCoV in this study may be beneficial for clinical monitoring of FCoV in China.", "journal": "Archives of virology", "doi": "10.1007/s00705-021-05291-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "34599794", "author": "Park DS", "n_authors": 4, "title": "Treatment of acute erythroleukaemia with high-dose cytarabine in a cat with feline leukaemia virus infection.", "abstract": "Erythroleukaemia is a malignant neoplasm of the erythroid lineage that rarely occurs in cats. It is associated with the feline leukaemia virus (FeLV), and owing to the poor prognosis, treatment is rarely reported. A 4-year-old female Korean domestic shorthair cat was presented with hyporexia, fever, lethargy, severe anaemia and rubricytosis. An FeLV antigen test was positive, but a subsequent polymerase chain reaction test was negative. Serum biochemistry analysis results were normal, except for slightly elevated alanine aminotransferase. The patient was tentatively diagnosed with acute erythroleukaemia, and single high-dose (600 mg/m", "journal": "Veterinary medicine and science", "doi": "10.1002/vms3.646", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "34284671", "author": "Siewert J", "n_authors": 6, "title": "Feline cutaneous lymphoma: an evaluation of disease presentation and factors affecting response to treatment.", "abstract": "The primary goal of this study was to characterize the clinical presentation of feline cutaneous lymphoma. The secondary aims included determining if treatment or initial response to treatment affected the overall survival of patients, and understanding if disease characteristics such as immunophenotype, cell size or the presence of epitheliotropism influenced response to treatment. Veterinary medical oncologists at four academic veterinary teaching hospitals submitted cases of feline patients with cutaneous lymphoma diagnosed by histopathology or cytology. Signalment, feline leukemia virus (FeLV)/feline immunodeficiency virus (FIV) status, physical examination findings, clinical signs, diagnostic tests, therapy, response and outcome, and necropsy findings, when available, were recorded. Forty-one patients were identified and described. The majority of patients were domestic shorthair cats (n = 29). The median age at diagnosis was 12.3 years. Males were over-represented in the population (n = 30). In the majority of patients (n = 33), the FIV/FeLV status was unknown. Twenty patients were fully staged. Thirty-four patients were treated with a variety of modalities, including surgery, radiation, single-agent or combination chemotherapy, or prednisolone only. In multiple patients, surgery or radiation was combined with a systemic therapy. Of 34 patients treated with some form of therapy, 20 responded (achieving either a partial response or complete remission). Clinical signs and physical examination findings varied among patients. Response to therapy appeared to be associated with survival (P = 0.0025); however, this population was highly censored. Immunophenotype, cell size and the presence of epitheliotropism did not influence treatment response. Results were limited by small numbers of patients, heterogeneous disease manifestations and treatment protocols. Further studies are necessary to evaluate the effect of specific treatment modalities and disease subtype on prognosis.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X211028837", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "34254846", "author": "Loft KE", "n_authors": 4, "title": "Feline cystadenomatosis affecting the ears and skin of 57 cats (2011-2019).", "abstract": "This study aimed to understand epidemiological factors associated with feline cystadenomatosis, including signalment and papillomavirus PCR status. Cystadenomatosis is an uncommon condition primarily involving the ceruminous and apocrine skin and ear glands. This was a retrospective case series. Clinical records from 2011 to 2019 from a tertiary referral hospital in Boston, MA, USA were screened for cases, and case data were re-evaluated and analyzed. The total patient pool contained 65,385 individual cats, of which 797 were referred to the dermatology service. Medical records and biopsy specimens were reviewed; the information collected included signalment, clinical signs, physical examination and diagnostic tests, comorbidities and histopathologic findings. PCR was performed on biopsy specimens to test for papillomavirus DNA. The cystadenomatosis population consisted of 57 cases (7.1% of total cases referred to the dermatology service) with 105 affected ears. Twenty-seven cases (48 ears) were confirmed via histopathology; four cats (7%) exhibited clinically cystic lesions on the periocular, periorbital and perianal regions; only one cat did not have pinnal lesions. Domestic shorthair cats were most often affected. Relative risk for cystadenomatosis was 2.24 times higher in male cats. In 48 cats (84.2%), ears were bilaterally affected. Seven cats (12.3%) had malignant neoplasia, which included: inflamed adenocarcinoma (n = 5); mast cell tumor (n = 1); or squamous cell carcinoma (n = 1). PCR testing on biopsy specimens from 24 cats revealed feline papillomavirus type 2 DNA in only four cats. Cystadenomatosis was more prevalent in senior non-purebred cats, over-represented in male cats and did not appear to be associated with papillomavirus, feline infectious peritonitis, feline immunodeficiency virus/feline leukemia virus status or other identifiable illnesses. Further studies are needed to investigate the causes of cystadenomatosis.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X211024498", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "33686768", "author": "Villanueva-Saz S", "n_authors": 19, "title": "Serological evidence of SARS-CoV-2 and co-infections in stray cats in Spain.", "abstract": "A new coronavirus known as SARS-CoV-2 emerged in Wuhan in 2019 and spread rapidly to the rest of the world causing the pandemic disease named coronavirus disease of 2019 (COVID-19). Little information is known about the impact this virus can cause upon domestic and stray animals. The potential impact of SARS-CoV-2 has become of great interest in cats due to transmission among domestic cats and the severe phenotypes described recently in a domestic cat. In this context, there is a public health warning that needs to be investigated in relation with the epidemiological role of this virus in stray cats. Consequently, in order to know the impact of the possible transmission chain, blood samples were obtained from 114 stray cats in the city of Zaragoza (Spain) and tested for SARS-CoV-2 and other selected pathogens susceptible to immunosuppression including Toxoplasma gondii, Leishmania infantum, feline leukaemia virus (FeLV) and feline immunodeficiency virus (FIV) from January to October 2020. Four cats (3.51%), based on enzyme-linked immunosorbent assay (ELISA) using the receptor binding domain (RBD) of Spike antigen, were seroreactive to SARS-CoV-2. T. gondii, L. infantum, FeLV and FIV seroprevalence was 12.28%, 16.67%, 4.39% and 19.30%, respectively. Among seropositive cats to SARS-CoV-2, three cats were also seropositive to other pathogens including antibodies detected against T. gondii and FIV (n = 1); T. gondii (n = 1); and FIV and L. infantum (n = 1). The subjects giving positive for SARS-CoV-2 were captured in urban areas of the city in different months: January 2020 (2/4), February 2020 (1/4) and July 2020 (1/4). This study revealed, for the first time, the exposure of stray cats to SARS-CoV-2 in Spain and the existence of concomitant infections with other pathogens including T. gondii, L. infantum and FIV, suggesting that immunosuppressed animals might be especially susceptible to SARS-CoV-2 infection.", "journal": "Transboundary and emerging diseases", "doi": "10.1111/tbed.14062", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "38257898", "author": "Bezerra JAB", "n_authors": 11, "title": "Coinfection with Leishmania infantum and Toxoplasma gondii in Domestic Cats from a Region with a High Prevalence of Feline Immunodeficiency Virus.", "abstract": "The aim of this study was to investigate the coinfection of feline retroviruses (feline immunodeficiency virus-FIV, and the feline leukemia virus-FeLV) with ", "journal": "Microorganisms", "doi": "10.3390/microorganisms12010071", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "38257747", "author": "Choi YR", "n_authors": 7, "title": "Domestic Cat Hepadnavirus and Pathogenic Retroviruses; A Sero-Molecular Survey of Cats in Santiago, Chile.", "abstract": "Cat ownership is common in Chile, but data on the regional prevalence of infectious agents are limited. A sero-molecular survey of 120 client- or shelter-owned domestic cats in greater Santiago was performed. Whole blood DNA was tested for the novel hepatitis-B-like virus, domestic cat hepadnavirus (DCH) by conventional PCR (cPCR) and quantitative PCR (qPCR), and for feline leukaemia virus (FeLV) by qPCR. Point-of-care serology for FeLV p27 antigen and antibodies recognising feline immunodeficiency virus (FIV) p15 and p24 was performed. DCH DNA was detected in the serum of 2/120 cats (1.67%). Sequencing and phylogenetic analysis showed that the DCH detected in Chile occupies a position outside the main clustering of DCH in the near-complete genome tree. Progressive (antigen-positive, provirus-positive) and regressive (antigen-negative, provirus-positive) FeLV infections were identified in 6/120 (5%) and 9/120 (7.5%) of cats. A total of 2/120 (1.7%) cats had dual FeLV/FIV infection, and another 2 cats had FIV infection alone. This study shows that the global footprint of DCH includes South America with a low molecular frequency in Chile, similar to that reported in the USA. Progressive FeLV infection is relatively common in urban Chile, and male cats are at greater risk than females. Testing and control measures for pathogenic retroviruses are indicated. The potential impact of FeLV, FIV and DCH on Chile's wildcat species is worthy of further investigation.", "journal": "Viruses", "doi": "10.3390/v16010046", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "38144711", "author": "Silva S", "n_authors": 5, "title": "Clinical features, MRI findings and outcome of a primary extranodal B-cell lymphoma affecting the tympanic bulla treated with chemotherapy alone.", "abstract": "A 2-year-old neutered female feline leukaemia virus (FeLV)-negative domestic shorthair cat was referred with an acute onset of vestibular signs. A clinical examination identified evidence of otitis externa of the right ear and enlargement of the right mandibular lymph node. MRI revealed predominantly T2 and FLAIR hyperintense and contrast-enhancing lesions affecting the right external ear canal, tympanic bulla and nasopharyngeal regions with intracranial extension. Cytology and culture and sensitivity samples collected from the middle ear via myringotomy revealed a population of intermediate to large lymphocytes consistent with lymphoma and mixed  This is the first report of a primary extranodal B-cell lymphoma affecting the tympanic bulla with suspected involvement of the nasopharynx and cranial vault treated with chemotherapy alone in the veterinary literature. Although very rare, B-cell lymphoma should be included in the differentials for diseases affecting the inner and/or middle ear and extending intracranially in cats. Chemotherapy represents a non-invasive treatment modality with a survival of up to 22 months appearing possible.", "journal": "JFMS open reports", "doi": "10.1177/20551169231214441", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "38137850", "author": "Dall'Ara P", "n_authors": 12, "title": "Prevalence of Serum Antibody Titers against Core Vaccine Antigens in Italian Cats.", "abstract": "Feline core vaccines strongly recommended for all cats are against Feline panleukopenia virus (FPV), Felid herpesvirus type 1 (FeHV-1), and Feline calicivirus (FCV), but cats can be classified as low- and high-risk based on their lifestyle. The aim of this study was to determine the actual seroprotection against FPV, FeHV-1, and FCV in a large cohort of Italian cats by using the VacciCheck test. A total of 740 cats (567 owned and 173 stray cats; 435 vaccinated and 305 unvaccinated) were analyzed for Protective Antibody Titers (PATs). Differences related to origin, sex, age, breed, FIV/FeLV status, health status, and time elapsed since last vaccination were evaluated. Less than half of the entire cohort (36.4%) had PATs for all three diseases simultaneously, increasing to 48.6% if weak positive values were also considered and 50.3% when considering only the 435 vaccinated cats. Particularly, antibodies were detected against FCV, FPV, and FeHV-1 at protective titers (PATs) in 78.6%, 68.1, and 49.1% of the cats, respectively. In general, owned, neutered, and adult FIV- and/or FeLV-negative cats were the most protected categories, even if not always for the three viruses. Most cats maintained high PATs for 3 years or longer after vaccination against FPV and FCV but not FeHV-1. Long-lasting protective immunity persisted for many years after the last vaccination (more than 18 years in the oldest cats). Nevertheless, since not all cats were protected after so many years and for all pathogens, checking protection via antibody titration could be the best choice to prevent immunity breakdowns. The discussion also focuses on the reliability of antibody titration for the two URTD (upper respiratory tract disease) viruses which, unlike for FPV, is not widely accepted as a valid index of protection.", "journal": "Life (Basel, Switzerland)", "doi": "10.3390/life13122249", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "38026675", "author": "Fusco G", "n_authors": 8, "title": "Prevalence of feline leukemia virus and feline immunodeficiency virus in cats from southern Italy: a 10-year cross-sectional study.", "abstract": "Feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) are well-known retroviruses causing important infections in domestic cats worldwide. The goal of this study was to determine the prevalence of FeLV and FIV infections in cat living indoor and outdoor in southern Italy. The survey was conducted on 1322 stray and owned cats from the regions of Campania, Basilicata, and Calabria. It was carried out over a 10-year period to obtain a more realistic picture of the prevalence of these retroviral diseases in the country. FIV and FeLV status was determined by enzyme-linked immunosorbent assay (ELISA) using a commercial kit (SNAP Combo Plus FeLV/FIV, IDEXX). Risk factors were analysed by logistic regression. The results showed that 101/1322 (7.64%) cats were positive for FeLV antigen and 110/1322 (8.32%) cats were positive for FIV antibody. Twenty-six of the 1322 cats (1.97%) were positive for both FIV and FeLV infection. Our results are similar to those published in recent studies in Europe. A statistically significant association (", "journal": "Frontiers in veterinary science", "doi": "10.3389/fvets.2023.1260081", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "38022580", "author": "Ciulean IS", "n_authors": 10, "title": "CD44v6 specific CAR-NK cells for targeted immunotherapy of head and neck squamous cell carcinoma.", "abstract": "Head and neck squamous cell carcinoma (HNSCC) is a major challenge for current therapies. CAR-T cells have shown promising results in blood cancers, however, their effectiveness against solid tumors remains a hurdle. Recently, CD44v6-directed CAR-T cells demonstrated efficacy in controlling tumor growth in multiple myeloma and solid tumors such as HNSCC, lung and ovarian adenocarcinomas. Apart from CAR-T cells, CAR-NK cells offer a safe and allogenic alternative to autologous CAR-T cell therapy. In this paper, we investigated the capacity of CAR-NK cells redirected against CD44v6 to execute cytotoxicity against HNSCC. Anti-CD44v6 CAR-NK cells were generated from healthy donor peripheral blood-derived NK cells using gamma retroviral vectors (gRVs). The NK cell transduction was optimized by exploring virus envelope proteins derived from the baboon endogenous virus envelope (BaEV), feline leukemia virus (FeLV, termed RD114-TR) and gibbon ape leukemia virus (GaLV), respectively. BaEV pseudotyped gRVs induced the highest transduction rate compared to RD114-TR and GaLV envelopes as measured by EGFP and surface CAR expression of transduced NK cells. CAR-NK cells showed a two- to threefold increase in killing efficacy against various HNSCC cell lines compared to unmodified, cytokine-expanded primary NK cells. Anti-CD44v6 CAR-NK cells were effective in eliminating tumor cell lines with high and low CD44v6 expression levels. Overall, the improved cytotoxicity of CAR-NK cells holds promise for a therapeutic option for the treatment of HNSCC. However, further preclinical trials are necessary to test ", "journal": "Frontiers in immunology", "doi": "10.3389/fimmu.2023.1290488", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37986028", "author": "Villanueva-Saz S", "n_authors": 16, "title": "Molecular survey on vector-borne pathogens in clinically healthy stray cats in Zaragoza (Spain).", "abstract": "In Europe, feline vector-borne infections are gaining importance because of the changing climate, expanding habitats of potential vectors and expanding pathogen reservoirs. The main objective of this study was to assess the prevalence of vector-borne pathogens (VBPs) in stray cats in Zaragoza, Spain, and to investigate potential risk factors for infection, including feline leukaemia virus (FeLV) and feline immunodeficiency virus (FIV). Blood samples from stray cats presented to the veterinary faculty in Zaragoza between February 2020 and 2022 were tested by polymerase chain reaction (PCR) for the presence of Anaplasma phagocytophilum, Anaplasma platys, Bartonella henselae, Ehrlichia canis, Rickettsia spp., haemotropic Mycoplasma spp., Hepatozoon spp., Leishmania infantum, piroplasms and microfilariae at the LABOKLIN laboratory. The cats were also tested for FeLV and FIV by PCR. Nearly half of the cats (158/332, 47.6%) were positive for at least one VBP. Hepatozoon spp. were detected in 25.6%, haemotropic Mycoplasma spp. in 22.9%, B. henselae in 9.3% and L. infantum in 2.1% of the cats. Male sex had a statistically significant association with test results for haemotropic Mycoplasma spp. (odds ratio 1.38 [1.21;1.57]); regionality with Hepatozoon spp., B. henseale and FIV; and seasonality with Hepatozoon spp., haemotropic Mycoplasma spp., L. infantum and FeLV (P ≤ 0.05 each). A strong positive correlation was reported for the amount of rainfall and the number of cats that tested positive for Hepatozoon spp. (ρ = 753, P = 0.05). None of the cats tested positive for A. phagocytophilum, A. platys, E. canis, Rickettsia spp., piroplasms, or microfilariae. Co-infections with multiple VBPs were detected in 56 out of 332 cats (16.9%). Thirty-one of the 332 cats included in the study (9.3%) tested positive for FeLV (6.9%) and for FIV (3.6%). In 20/31 cats (64.5%) that tested positive for FeLV/FIV, coinfections with VBP were detected (P = 0.048, OR 2.15 [0.99; 4.64]). VBPs were frequently detected in stray cats in Zaragoza. In particular, regionality and seasonality had a statistically significant association with PCR results for most VBPs included in the study.", "journal": "Parasites & vectors", "doi": "10.1186/s13071-023-06046-y", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37896905", "author": "Silva BBI", "n_authors": 12, "title": "Genetic Diversity of Domestic Cat Hepadnavirus in Southern Taiwan.", "abstract": "Domestic cat hepadnavirus (DCH) is an infectious disease associated with chronic hepatitis in cats, which suggests a similarity with hepatitis B virus infections in humans. Since its first identification in Australia in 2018, DCH has been reported in several countries with varying prevalence rates, but its presence in Taiwan has yet to be investigated. In this study, we aimed to identify the presence and genetic diversity of DCH infections in Taiwan. Among the 71 samples tested, eight (11.27%) were positive for DCH. Of these positive cases, three cats had elevated levels of alanine transaminase (ALT) and aspartate transaminase (AST), suggesting an association between DCH infection and chronic hepatitis. Four DCH-positive samples were also tested for feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) coinfection. One sample (25%) was positive for FIV, whereas there was no positive sample for FeLV (0%). In addition, we performed whole genome sequencing on six samples to determine the viral genome sequences. Phylogenetic analyses identified a distinct lineage compared with previously reported sequences. This study highlights the importance of continuous surveillance of DCH and further research to elucidate the pathophysiology and transmission route of DCH.", "journal": "Viruses", "doi": "10.3390/v15102128", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37896893", "author": "Singh S", "n_authors": 7, "title": "Diagnostic Accuracy of a Point-of-Care Immunoassay for Feline Immunodeficiency Virus Antibodies, Feline Leukemia Virus Antigen, and Dirofilaria immitis Antigen.", "abstract": "Feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) are retroviral infections of cats worldwide whose clinical manifestations range from mild to severe disease. In both cases, infected cats can live a long life with proper care and should be managed to prevent infection of other cats. ", "journal": "Viruses", "doi": "10.3390/v15102117", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37861160", "author": "Hargreaves R", "n_authors": 1, "title": "Vaccinating cats for feline leukaemia virus.", "abstract": null, "journal": "The Veterinary record", "doi": "10.1002/vetr.3588", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37851857", "author": "Phongroop K", "n_authors": 6, "title": "High-resolution melting analysis for simultaneous detection and discrimination between wild-type and vaccine strains of feline calicivirus.", "abstract": "High-resolution melting (HRM) analysis, a post-polymerase chain reaction (PCR) application in a single closed tube, is the straightforward method for simultaneous detection, genotyping, and mutation scanning, enabling more significant dynamic detection and sequencing-free turnaround time. This study aimed to establish a combined reverse-transcription quantitative PCR and HRM (RT-qPCR-HRM) assay for diagnosing and genotyping feline calicivirus (FCV). This developed method was validated with constructed FCV plasmids, clinical swab samples from living cats, fresh-frozen lung tissues from necropsied cats, and four available FCV vaccines. We performed RT-qPCR to amplify a 99-base pair sequence, targeting a segment between open reading frame (ORF) 1 and ORF2. Subsequently, the HRM assay was promptly applied using Rotor-Gene Q® Software. The results significantly revealed simultaneous detection and genetic discrimination between commercially available FCV vaccine strains, wild-type Thai FCV strains, and VS-FCV strains within a single PCR reaction. There was no cross-reactivity with other feline common viruses, including feline herpesvirus-1, feline coronavirus, feline leukemia virus, feline immunodeficiency virus, and feline morbillivirus. The detection limit of the assay was 6.18 × 10", "journal": "The veterinary quarterly", "doi": "10.1080/01652176.2023.2272188", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37817623", "author": "Franco PN", "n_authors": 10, "title": "SEROLOGICAL SURVEY FOR SELECTED PATHOGENS IN FREE-RANGING COUGARS (PUMA CONCOLOR) IN SÃO PAULO, BRAZIL.", "abstract": "This study performed a serological assay to assess the exposure of free-ranging cougars (", "journal": "Journal of zoo and wildlife medicine : official publication of the American Association of Zoo Veterinarians", "doi": "10.1638/2022-0152", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "40303808", "author": "Alves BSG", "n_authors": 7, "title": "Epidemiology of a Hybrid Swarm: Evidence of 11 Feline Infectious Agents Circulating in a Population of Sympatric European Wildcat Hybrids and Free-Living Domestic Cats, in Scotland.", "abstract": "Hybridisation between wild and domestic species poses a serious challenge to conservation management and can, potentially, lead to extinction. Alongside it, disease transmission will inevitably occur. However, the link between these two phenomena has historically been neglected. In Scotland, the European wildcat is particularly threatened by hybridisation with the domestic cat, a process promoted by long-term habitat loss, human encroachment, and persecution. Between 2015 and 2019, free-living cats (", "journal": "Transboundary and emerging diseases", "doi": "10.1155/2023/6692514", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37768269", "author": "Piewbang C", "n_authors": 6, "title": "Domestic cat hepadnavirus detection in blood and tissue samples of cats with lymphoma.", "abstract": "Domestic cat hepadnavirus (DCH), a relative hepatitis B virus (HBV) in human, has been recently identified in cats; however, association of DCH infection with lymphoma in cats is not investigated. To determine the association between DCH infection and feline lymphoma, seven hundred and seventeen cats included 131 cats with lymphoma (68 blood and 63 tumor samples) and 586 (526 blood and 60 lymph node samples) cats without lymphoma. DCH DNA was investigated in blood and formalin-fixed paraffin-embedded (FFPE) tissues by quantitative polymerase chain reaction (qPCR). The FFPE lymphoma tissues were immunohistochemically subtyped, and the localization of DCH in lymphoma sections was investigated using ", "journal": "The veterinary quarterly", "doi": "10.1080/01652176.2023.2265172", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37766260", "author": "Moll GM", "n_authors": 3, "title": "BET Inhibitor JQ1 Attenuates Feline Leukemia Virus DNA, Provirus, and Antigen Production in Domestic Cat Cell Lines.", "abstract": "Feline leukemia virus (FeLV) is a cosmopolitan gammaretrovirus that causes lifelong infections and fatal diseases, including leukemias, lymphomas, immunodeficiencies, and anemias, in domestic and wild felids. There is currently no definitive treatment for FeLV, and while existing vaccines reduce the prevalence of progressive infections, they neither provide sterilizing immunity nor prevent regressive infections that result in viral reservoirs with the potential for reactivation, transmission, and the development of associated clinical diseases. Previous studies of murine leukemia virus (MuLV) established that host cell epigenetic reader bromodomain and extra-terminal domain (BET) proteins facilitate MuLV replication by promoting proviral integration. Here, we provide evidence that this facilitatory effect of BET proteins extends to FeLV. Treatment with the archetypal BET protein bromodomain inhibitor (+)-JQ1 and FeLV challenge of two phenotypically disparate feline cell lines, 81C fibroblasts and 3201 lymphoma cells, significantly reduced FeLV proviral load, total FeLV DNA load, and p27 capsid protein expression at nonlethal concentrations. Moreover, significant decreases in FeLV proviral integration were documented in 81C and 3201 cells. These findings elucidate the importance of BET proteins for efficient FeLV replication, including proviral integration, and provide a potential target for treating FeLV infections.", "journal": "Viruses", "doi": "10.3390/v15091853", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37668713", "author": "Hartmann G", "n_authors": 9, "title": "Anti-Leishmania spp. antibody detection in domestic cats from a visceral leishmaniasis transmission area.", "abstract": "Feline leishmanial infection is reported worldwide, but the epidemiological role of domestic cats in the leishmaniasis cycle remains unclear, and cats might act as cryptic reservoir hosts in endemic areas with no feline leishmaniosis cases. Considering that, a serological screening for anti-Leishmania spp. antibodies was performed by indirect immunofluorescence antibody test (IFAT) in 389 necropsied cats' serum samples from a new visceral leishmaniasis transmission area with no feline leishmanial infection reported to unveil if the cats are being exposed to the parasite. The overall seroprevalence for Leishmania spp. was 11.05% (43/389). No association was found between sex, neutering status, age group, breed, coat length, feline immunodeficiency virus (FIV) infection, and Leishmania spp. antibody detection. A positive association was found with coat color (cats within the orange spectrum with white [particolor]) (OR = 2.47, CI 95% 1 - 6.13, P = 0.044) and a negative association (OR = 0.38, CI 95% 0.18 - 0.79, P = 0.01) between feline leukemia virus (FeLV) infection and IFAT positivity for Leishmania spp. Therefore, it is concluded that the seroprevalence found was greater than 10%, indicating contact of the protozoan with cats in the region served.", "journal": "Parasitology research", "doi": "10.1007/s00436-023-07961-w", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37649553", "author": "de Cristo TG", "n_authors": 8, "title": "Overview of Bone Marrow Aspiration from 120 Cats in Different Hematological Conditions.", "abstract": "Bone marrow (BM) evaluation is highly important for the diagnosis of numerous hematological alterations in animals, especially cats, given their greater propensity for hematopoietic changes associated with retrovirus infections. This study aims to describe the main aspects of the BM of cats with different hematological conditions, comparing with reference intervals established from animals without hematological alterations and also with a previously established reference interval. To do so, we evaluated full blood and BM samples from 120 cats with no abnormalities on physical examination, negative for FeLV and FIV. Hemograms were performed from automated total cell and platelet and leukocyte differential counts in blood smears. BM samples were placed in Petri dishes; medullary spicules were selected to make up to eight cytological slides stained by the May-Grunwald-Giemsa technique, which were subjected to quantitative and cellular morphology evaluations. The cats were predominantly young, 64.2% female and 35.8% male. The average number of medullary spicules in samples was 13.7%, and density was 44%. In the BM quantitative analysis, prorubricytes and rubriblasts had higher quantities than the recommended one for all cats with or without hematological alterations. In all groups, lymphocytes were decreased, and cats with lymphocytosis were closest to the reference range, showing flame cells and Mott cells. The reference interval for the bone marrow cell count obtained from the samples in this work differs from previously established data, leading to different interpretations of the patient's BM condition, according to the cell population observed and the reference interval used. This divergence strongly emphasizes the need to correlate clinical, epidemiological, hematological, and bone marrow data of each patient for a better understanding of the patient's condition. The popularization of BM assessment is essential so that more reliable reference intervals can be established according to the population served by each pathologist and clinical laboratory.", "journal": "Veterinary medicine international", "doi": "10.1155/2023/2493618", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37632060", "author": "Giselbrecht J", "n_authors": 14, "title": "Prevalence of Different Courses of Feline Leukaemia Virus Infection in Four European Countries.", "abstract": "Prevalence of progressive feline leukaemia virus (FeLV) infection is known to still be high in cats in Europe, especially in Southern Europe, but the prevalence of other outcomes of FeLV infection has not been determined in most countries. The present study aimed to investigate the prevalence of progressive, regressive, abortive, and focal infection in four European countries, two with a high (Italy, Portugal) and two with a low expected prevalence (Germany, France). Blood samples of 934 cats (Italy: 269; Portugal: 240; France: 107; Germany: 318) were evaluated for the p27 antigen, as well as anti-whole virus, anti-SU, and anti-p15E antibodies by enzyme-linked immunosorbent assay (ELISA) in serum and for proviral DNA by quantitative polymerase chain reaction (qPCR) in whole blood. Positive p27 antigen ELISA results were confirmed by reverse transcriptase-qPCR (RT-qPCR) detecting viral RNA in saliva swabs and/or blood. The outcome of FeLV infection was categorised as progressive (antigen-positive, provirus-positive), regressive (antigen-negative, provirus-positive), abortive (antigen- and provirus-negative, antibody-positive), and focal (antigen-positive, provirus-negative) infection. Overall FeLV prevalence was 21.2% in Italy, 20.4% in Portugal, 9.5% in Germany, and 9.3% in France. Prevalence of progressive, regressive, abortive, and focal infection in Italy was 7.8%, 4.5%, 6.3%, and 2.6%; in Portugal 3.8%, 8.3%, 6.7%, and 1.7%; in Germany 1.9%, 1.3%, 3.5%, and 2.8%; in France 1.9%, 3.7%, 2.8%, and 0.9%, respectively. In conclusion, overall FeLV prevalence is still very high, especially in Southern European countries. Therefore, testing, separation of infected cats, and vaccination are still important measures to reduce the risk of FeLV infection.", "journal": "Viruses", "doi": "10.3390/v15081718", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37627457", "author": "Versteegh H", "n_authors": 5, "title": "Feline Lymphoma: Patient Characteristics and Response Outcome of the COP-Protocol in Cats with Malignant Lymphoma in The Netherlands.", "abstract": "Feline lymphoma is currently less commonly associated with retrovirus infections as the feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV). This is thought to have caused a shift in the distribution of anatomical subtypes and eventually have led to poorer treatment outcomes. The aim of this study was to evaluate whether this change was also notable in the Netherlands, a country historically known for its low prevalence of FeLV and FIV, and to determine its consequences on treatment response. A 10-year cohort of 174 cats with large cell lymphoma (110 treated) were included and compared to historical data from previously published reports in the Netherlands. Of the 90 cats screened, only one tested positive for FeLV and three for FIV. The most current cohort had an increased age (median 8.7 years) and fever Siamese cats (6.3%) compared to previous reports, with alimentary (24.5%) and nasopharyngeal lymphoma (22.7%) being the most common subtypes. Sixty-six of the one hundred and ten cats (60%) went into complete remission, (CR) resulting in a median disease-free period (DFP) of 763 days, with nasopharyngeal and mediastinal having the longest DFP. The median overall survival time was 274 days with an estimated 1-year survival of 41.3% and a 2-year survival of 34.6%, respectively. Patient characteristics of cats with malignant lymphoma in the Netherlands have changed over the years, but this cannot be explained by differences in FeLV/FIV prevalence. Although the overall response rate to therapy did not change over time, for some lymphoma subtypes, longer DFPs were observed compared to 30 years ago.", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani13162667", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37627365", "author": "Schäfer I", "n_authors": 4, "title": "Vector-Borne Pathogens in Stray Cats in Eastern Germany (Thuringia).", "abstract": "Bacterial, protozoal, and viral vector-borne pathogens (VBPs) can cause infections in cats. There is little information on feline VBP prevalence in Germany. Stray cats are frequently exposed to vectors but receive no veterinary care. The aim of this study was to determine the prevalence of selected VBPs in stray cats. EDTA blood and serum samples were taken from apparently healthy stray cats during a spay/neuter campaign in the federal state of Thuringia. Overall, 11/50 (22%) and 32/50 (64%) cats tested positive for at least one VBP by direct and indirect detection methods, respectively. PCR testing of EDTA blood detected hemotropic ", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani13162574", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37597496", "author": "Gómez Á", "n_authors": 9, "title": "Feline osteochondromatosis in a 12-year-old feline leukaemia virus-negative cat.", "abstract": "Feline osteochondromatosis is a spontaneous osteocartilaginous exostosis associated with feline leukaemia virus (FeLV) infection or due to a frameshift variant in the exostosin glycosyltransferase 1 (EXT1) gene. Osteochondromatosis was diagnosed in an indoor-only, 12-year-old, neutered female, Russian Blue cat. Radiographs revealed bilateral calcified proliferations in the elbow, costochondral and sternochondral joints, which distorted the normal skeletal structure. Grossly, the proliferated joints presented with consistent, rounded masses, causing complete ankylosis. The main histopathological finding was an osteocartilaginous proliferation composed of multiple irregular islands of well-differentiated hyaline cartilage surrounded and delimited by osteoid tissue. Immunohistochemistry of the osteochondromas, bone marrow and mediastinal lymph nodes, using a primary anti-FeLV gp70 antibody, and FeLV proviral DNA real-time polymerase chain reaction on bone marrow were negative. Sequencing of exon 6 of the EXT1 gene was performed and nucleotide BLAST analysis demonstrated the absence of a frameshift variant. This study reports the only case of spontaneous feline osteochondromatosis in an animal more than 10 years old.", "journal": "Journal of comparative pathology", "doi": "10.1016/j.jcpa.2023.07.003", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37565270", "author": "Rogato F", "n_authors": 6, "title": "Clinical characterisation and long-term survival of paediatric and juvenile lymphoma in cats: 33 cases (2008-2022).", "abstract": "The aims of this study were to describe the clinical presentation, tumour characteristics, responses to chemotherapy protocols and toxicity in a cohort of cats with lymphoma up to 18 months of age. In addition, the probability of long-term (>2 years) survival was explored. The medical records of client-owned cats aged up to 18 months diagnosed with lymphoma between 2008 and 2022 at five UK-based veterinary referral hospitals were reviewed. Thirty-three cats were included. The most common anatomical forms were mediastinal (42%), disseminated disease (30%) and renal (15%), with all cats having intermediate to large cell lymphoma. Three out of 29 cats tested were positive for FeLV but none for FIV. Twenty-six cats were treated with multi-agent chemotherapy protocols with complete and partial responses seen in 46% and 50% of cats, respectively. For this group, median progression-free survival was 133 days (95% confidence interval [Cl] 67 to 199) and median survival time was 268 days (95% Cl 106 to 430). Complete response to chemotherapy was associated with a longer progression-free survival. Seven cats were considered long-term survivors (>2 years). Chemotherapy was generally well tolerated with none of the long-term survivors suffering from chronic sequelae from cytotoxic treatment. Paediatric and juvenile cats with lymphoma showed a high response rate to multi-agent chemotherapy protocols with rare significant toxicities. The presence of long-term survivors may suggest a more favourable outcome in a subset of patients.", "journal": "The Journal of small animal practice", "doi": "10.1111/jsap.13667", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37546656", "author": "Rasri N", "n_authors": 7, "title": "Generation of a Single-Chain Variable Fragment Antibody against Feline Immunoglobulin G for Biosensor Applications.", "abstract": "For many decades, feline infectious disease has been among the most common health problems and a leading cause of death in cats. These diseases include toxoplasmosis, feline leukemia virus (FeLV), and particularly feline immunodeficiency virus (FIV) disease. Early diagnosis is essential to increase the chance of successful treatment. Generally, measurement of the IgG level is considered to be indicative of an individual's immune status for a particular pathogen. The antibodies specific to feline IgG are crucial components for the development of a detection kit. In this study, feline IgG-bound scFv was selected using phage display technology. Three rounds of biopanning were conducted against purified feline IgG. Through an indirect enzyme-linked immunosorbent assay (ELISA), two scFv clones demonstrating the best binding ability to feline IgG were chosen for biochemical characterization. In addition, the selected scFv (N14) was expressed and purified in a bacterial system. Sodium dodecyl sulfate-polyacrylamide gel electrophoresis revealed that the size of the purified N14 was 29 kDa. A sandwich ELISA was used to evaluate the binding capacity of the purified scFv to feline IgG. As expected, the purified N14 had the capacity to bind feline IgG. Furthermore, N14 was modified to create a scFv-alkaline phosphatase (scFv-AP) fusion platform. The surface plasmon resonance (SPR) results revealed that N14-AP bound to feline IgG with an affinity binding value of 0.3 ± 0.496 μM. Additionally, the direct ELISA demonstrated the binding capacity of N14-AP to feline IgG in both cell lysate and purified protein. Moreover, N14-AP could be applied to detect feline IgG based on electrosensing with a detection limit of 10.42 nM. Overall, this study successfully selected a feline IgG-bound scFv and developed a scFv-AP platform that could be further engineered and applied in a feline infectious disease detection kit.", "journal": "ACS omega", "doi": "10.1021/acsomega.3c03581", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37521360", "author": "de Almeida JCN", "n_authors": 6, "title": "Use of selected samples to diagnose a tricky feline viral disease in a cat with uveitis and neurological signs.", "abstract": "This case involved a 2-year-old neutered male domestic mixed-breed cat that was rescued from the street eight months earlier. The animal presented with weakness, hyporexia, progressive weight loss, fatigue, uveitis, pale mucous membranes, dehydration (7%), and pelvic limb paresis. Aqueous humor was collected for molecular analysis for the differential diagnosis of potential etiological agents [Feline coronavirus (FCoV), Feline leukemia virus (FeLV), Feline immunodeficiency virus (FIV), ", "journal": "Brazilian journal of veterinary medicine", "doi": "10.29374/2527-2179.bjvm001223", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37515217", "author": "Duijvestijn MBHM", "n_authors": 10, "title": "Serological Survey of Retrovirus and Coronavirus Infections, including SARS-CoV-2, in Rural Stray Cats in The Netherlands, 2020-2022.", "abstract": "Stray cats can host (zoonotic) viral pathogens and act as a source of infection for domestic cats or humans. In this cross-sectional (sero)prevalence study, sera from 580 stray cats living in 56 different cat groups in rural areas in The Netherlands were collected from October 2020 to July 2022. These were used to investigate the prevalence of the cat-specific feline leukemia virus (FeLV, n = 580), the seroprevalence of the cat-specific feline viruses feline immunodeficiency virus (FIV, n = 580) and feline coronavirus (FCoV, n = 407), and the zoonotic virus severe acute respiratory coronavirus-2 (SARS-CoV-2, n = 407) using enzyme-linked immunosorbent assays (ELISAs). ELISA-positive results were confirmed using Western blot (FIV) or pseudovirus neutralization test (SARS-CoV-2). The FIV seroprevalence was 5.0% (95% CI (Confidence Interval) 3.4-7.1) and ranged from 0-19.0% among groups. FIV-specific antibodies were more often detected in male cats, cats ≥ 3 years and cats with reported health problems. No FeLV-positive cats were found (95% CI 0.0-0.6). The FCoV seroprevalence was 33.7% (95% CI 29.1-38.5) and ranged from 4.7-85.7% among groups. FCoV-specific antibodies were more often detected in cats ≥ 3 years, cats with reported health problems and cats living in industrial areas or countryside residences compared to cats living at holiday parks or campsites. SARS-CoV-2 antibodies against the subunit 1 (S1) and receptor binding domain (RBD) protein were detected in 2.7% (95% CI 1.4-4.8) of stray cats, but sera were negative in the pseudovirus neutralization test and therefore were considered SARS-CoV-2 suspected. Our findings suggest that rural stray cats in The Netherlands can be a source of FIV and FCoV, indicating a potential risk for transmission to other cats, while the risk for FeLV is low. However, suspected SARS-CoV-2 infections in these cats were uncommon. We found no evidence of SARS-CoV-2 cat-to-cat spread in the studied stray cat groups and consider the likelihood of spillover to humans as low.", "journal": "Viruses", "doi": "10.3390/v15071531", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37471581", "author": "Adıgüzel E", "n_authors": 5, "title": "The detection and full genomic characterization of domestic cat Orthohepadnaviruses from Türkiye.", "abstract": "Domestic cat hepadnaviruses (DCHs) have been described as a novel virus that can infect cats. The aim of our study is the first identification and molecular characterizations of DCH infection in Turkish domestic cats. The blood, organ and ascites fluid samples from 550 cats were randomly sampled. The presence of DCH nucleic acid was investigated by using both in the literature and newly designed primers. It was found that the hepadnavirus positivity rate is 4% (22/550) in Türkiye. The full genomic characterization was performed on 13 of 22 samples, and others were characterized as nearly full genome. In this study, we highlight that whole blood samples should be also screened for DCH, not only serum samples as has frequently been done in other studies. DCH-infected cats were also found positive (54.54%, 12/22) for Feline leukaemia virus infection. BLAST results revealed that Turkish DCHs have 86.32%-99.08% homology with strains in the GenBank database, enabling us to construct phylogenetic trees. According to this study's results, it is suggested that this infection should be added to veterinary diagnostic panels worldwide. Additionally, we suggest that our new synthesized primers for the amplification of X gene can also be used for diagnosis.", "journal": "Veterinary medicine and science", "doi": "10.1002/vms3.1217", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37439634", "author": "Kornya M", "n_authors": 3, "title": "Discordant FeLV p27 immunoassay and PCR test results in 21 cats with hematologic disorders.", "abstract": "A total of 1692 medical records from a primary care feline practice and a veterinary referral hospital were evaluated retrospectively to assess discordant feline leukemia virus (FeLV) test results. In total, 73 cats were positive for FeLV using serum in a lateral flow immunoassay (LFI) or laboratory-based ELISA. Of these cats, 21 subsequently tested negative for FeLV proviral DNA by non-quantitative PCR on EDTA whole blood (16/21, 76.2%), bone marrow (4/21, 19%) or both (1/21, 4.7%). The proportional morbidity (an estimate of prevalence in a sample of the total population) for FeLV by LFI/ELISA and PCR assays was 3.1%, consistent with that reported in previous studies for cats in North America. Cats with discordant LFI/ELISA and PCR results had either primary bone marrow disease (18 autoimmune, one neoplastic), a bone marrow insult (hemotrophic mycoplasmosis) or systemic inflammation (pyothorax with a marked neutrophilic leukocytosis). The percentage of cats with a positive LFA/ELISA result and negative PCR assay surviving to discharge was 85.7% (18/21). Of these, 88.9% (16/18) survived 4 months to 6 years. Seven cats (33.3%) were re-tested with LFI or ELISA once primary disease was controlled, and all tested negative. These findings indicate that in cats with bone marrow disease that shares features of progressive FeLV infection, positive LFI and ELISA FeLV test results should be followed up with FeLV proviral DNA PCR testing, particularly in populations where disease prevalence is low.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X231183297", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37436206", "author": "Batista JF", "n_authors": 8, "title": "Clinical, hematological, biochemical, and histopathological evaluations in domestic cats (Felis catus) infected by Leishmania infantum.", "abstract": "A high frequency of feline leishmaniasis has been reported in several countries. However, much information about disease progression in cats still needs to be clarified. This study aimed to verify the occurrence of clinicopathological changes in cats infected with Leishmania infantum. A total of 60 cats were divided into three groups of 20 animals each: control, suspects, and infected. All 60 cats underwent blood count and biochemical analyses. Serum samples from 20 animals with leishmaniasis were also used to diagnose feline immunodeficiency virus and feline leukemia virus. A total of five of the infected animals underwent necropsy for a histopathological study. The main clinical findings in cats with leishmaniasis were lymphadenomegaly (65%), alopecia (55%), ulcerative skin lesions and weight loss (40%), skin nodules (25%), a significant reduction in red blood cells (p=0.0005) and hematocrit (p=0.0007), hyperplasia in spleen 4/5(80%), presence of Leishmania in the spleen 2/5(40%), hepatitis 3/5(60%), liver degeneration 4/5(80%) and inflammatory nephropathy 3/5(60%). It was concluded that cats with leishmaniasis presented significant clinical, hematological, and histopathological alterations compatible with L. infantum infection. The observation of lymphadenomegaly, weight loss, skin lesions and low concentration of red blood cells, contributes significantly to the diagnosis and analysis of progression of feline leishmaniasis.", "journal": "Revista brasileira de parasitologia veterinaria = Brazilian journal of veterinary parasitology : Orgao Oficial do Colegio Brasileiro de Parasitologia Veterinaria", "doi": "10.1590/S1984-29612023037", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37386451", "author": "Parisi F", "n_authors": 6, "title": "Exploring the link between viruses and cancer in companion animals: a comprehensive and comparative analysis.", "abstract": "Currently, it is estimated that 15% of human neoplasms globally are caused by infectious agents, with new evidence emerging continuously. Multiple agents have been implicated in various forms of neoplasia, with viruses as the most frequent. In recent years, investigation on viral mechanisms underlying tumoral transformation in cancer development and progression are in the spotlight, both in human and veterinary oncology. Oncogenic viruses in veterinary medicine are of primary importance not only as original pathogens of pets, but also in the view of pets as models of human malignancies. Hence, this work will provide an overview of the main oncogenic viruses of companion animals, with brief notes of comparative medicine.", "journal": "Infectious agents and cancer", "doi": "10.1186/s13027-023-00518-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37377321", "author": "Silva DTD", "n_authors": 10, "title": "Feline leishmaniosis: hematological and biochemical analysis.", "abstract": "One hundred and sixty-six cats from two animal shelters were subjected to enzyme-linked immunosorbent assay (ELISA), indirect immunofluorescence antibody test (IFAT), conventional polymerase chain reaction (cPCR), quantitative PCR (qPCR) and parasitological tests (PA) for the diagnosis of Leishmania spp. Among them, 15% (25/166), 53.6% (89/166), 3.6% (06/166) and 1.8% (03/166) were positive by ELISA, IFAT, both PCRs and PA, respectively. The sequencing of ITS-1 PCR amplicons revealed a 100% match with Leishmania infantum. After the Leishmania spp. survey, 12 cats were selected and divided into two groups for clinical, hematological, and biochemical analysis: six L. infantum positive cats (G1) and six Leishmania spp. negative cats (G2). All the cats were negative for feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV). A statistical analysis indicated significantly low platelet counts and significant hyperproteinemia associated with hypoalbuminemia in positive cats (p<0.05). Our results suggest that in endemic areas, cats with clinical signs of feline leishmaniosis (such as skin lesions, weight loss and/or enlarged lymph nodes) and that exhibit hematological and biochemical changes, such as low platelet counts and hyperproteinemia with hypoalbuminemia, should be tested for Leishmania spp. infection.", "journal": "Revista brasileira de parasitologia veterinaria = Brazilian journal of veterinary parasitology : Orgao Oficial do Colegio Brasileiro de Parasitologia Veterinaria", "doi": "10.1590/S1984-29612023035", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37355451", "author": "Haist V", "n_authors": 11, "title": "Comparison of the local safety of two multi-component feline vaccines, adjuvanted (1 mL) versus non-adjuvanted at reduced volume (0.5 mL), using computed tomography imaging.", "abstract": "In 2020, a new 0.5 mL presentation of PUREVAX® RCP FeLV was registered and introduced in Europe. The objectives of this study were to investigate the local safety of this non-adjuvanted vaccine at reduced volume by classical methods (clinical examination, histopathology) and to evaluate the suitability of an alternative non-invasive methodology, the computed tomography (CT). For this purpose, the course of local reactions was assessed for 3 months after subcutaneous injection of PUREVAX® RCP FeLV 0.5 mL and compared to an adjuvanted vaccine, LEUCOFELIGEN® FeLV/RCP 1.0 mL. Injection site reactions consisted mainly of swelling reactions, which were more frequent, more pronounced and long-lasting in the adjuvanted vaccine group. Microscopically, in this group, moderate to severe inflammatory reactions were observed on day 7 (D7) and D21 post-injection and still present on D84, while mild inflammatory lesions were observed in the non-adjuvanted vaccine group only on D7 and D21. With the adjuvanted vaccine, inflamed areas were measurable by CT scan in all cats on D7 and D21, whereas they were detected only on D7 and only in 20 % of cats from the non-adjuvanted vaccine group. Besides the higher frequency, the mean inflamed volume was nearly 300 times larger in adjuvanted vaccine group on D7. Using different methodologies, the favorable safety profile of PUREVAX® RCP FeLV 0.5 mL was confirmed. Furthermore, the vaccine is aligned with current vaccination guidelines by inducing less inflammatory reactions, being adjuvant-free and injectable under a reduced volume, thus improving the convenience of administration in recommended sites (eg, legs). CT scan proved to be a suitable non-invasive method for the experimental follow-up of injection site reactions, yielding results consistent with clinical assessment and histopathology on D7 and D21. CT scan substantiated large differences between the investigated vaccines with a more prominent inflammatory reaction after injection of an adjuvanted vaccine.", "journal": "Vaccine", "doi": "10.1016/j.vaccine.2023.06.045", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37321792", "author": "Pargass I", "n_authors": 5, "title": "First reported case of leishmaniasis in a cat in Trinidad and Tobago.", "abstract": "A 3-year-old, female, domestic shorthair cat, was presented to the Veterinary Teaching Hospital at the School of Veterinary Medicine (SVM), Trinidad and Tobago for a swollen nose, and multiple, variably sized small masses on both ears. The initial diagnostic tests included a CBC, serum biochemistry profile, cytological evaluation of masses on the ear and nose, and FeLV/FIV testing. The CBC and biochemistry results were unremarkable except for a hyperproteinaemia and hyperglobulinemia. Cytology of the nose and ear lesions revealed mixed inflammation and high numbers of intracellular and extracellular organisms consistent with Leishmania amastigotes. The cat was FeLV/FIV negative. Histopathology and Leishmania IFA and PCR analysis were subsequently performed, confirming the Leishmania diagnosis. The PCR, DNA sequencing and phylogenetic tree analyses identified L. amazonensis. This is the first reported case of L. amazonensis infection in a domestic animal in Trinidad with molecular characterization indicating it exists in the region and is likely being transmitted by sandflies.", "journal": "Veterinary parasitology, regional studies and reports", "doi": "10.1016/j.vprsr.2023.100896", "deposited_data": "Sim", "nuccore_ids": "2523364374", "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37257827", "author": "Robert LI", "n_authors": 7, "title": "A retrospective review of cats with suspected false positive results in point-of-care feline leukemia virus tests and concurrent immune-mediated anemia.", "abstract": "To describe clinical findings, diagnosis, treatment, and survival in 18 cats with anemia of suspected immune-mediated origin (ASIMO) and conflicting results using FeLV diagnosis tests, and to suggest an accurate way to assess their FeLV diagnosis. 18 cats. Medical records from 5 veterinary institutions were retrospectively reviewed to identify cats with ASIMO, positive results on p27 SNAP ELISA, and negative results on pro-virus PCR testing in peripheral blood, in the absence of other identified triggers. Follow-up was recorded from diagnosis to the time of writing, and survival analysis was performed to assess similarities with previous published data. 18 cats were enrolled from referral centers in Spain, Italy, and the United Kingdom. Both peripheral immune-mediated hemolytic anemia (IMHA; 12/18) and precursor targeted immune-mediated anemia (PIMA; 6/18) were described. When the SNAP ELISA test was rechecked in patients with disease control, SNAP ELISA positive results had become negative. Two cats had a relapse of the ASIMO, and the FeLV SNAP ELISA tested positive again. Other signs of FeLV disease did not appear in any of these patients despite immunosuppression. 14 cats (14/18 [78%]) were alive at the time of writing, and the mean estimated survival time was 769 days. This study describes incongruent FeLV results in cats with ASIMO. It supports the necessity to confirm FeLV SNAP ELISA positive results using additional tools, such as pro-virus PCR testing, as different p27 point-of-care and external serological tests may be inconsistent.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.23.02.0059", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37240371", "author": "Ortiz R", "n_authors": 15, "title": "Exploring FeLV-Gag-Based VLPs as a New Vaccine Platform-Analysis of Production and Immunogenicity.", "abstract": "Feline leukemia virus (FeLV) is one of the most prevalent infectious diseases in domestic cats. Although different commercial vaccines are available, none of them provides full protection. Thus, efforts to design a more efficient vaccine are needed. Our group has successfully engineered HIV-1 Gag-based VLPs that induce a potent and functional immune response against the HIV-1 transmembrane protein gp41. Here, we propose to use this concept to generate FeLV-Gag-based VLPs as a novel vaccine strategy against this retrovirus. By analogy to our HIV-1 platform, a fragment of the FeLV transmembrane p15E protein was exposed on FeLV-Gag-based VLPs. After optimization of Gag sequences, the immunogenicity of the selected candidates was evaluated in C57BL/6 and BALB/c mice, showing strong cellular and humoral responses to Gag but failing to generate anti-p15E antibodies. Altogether, this study not only tests the versatility of the enveloped VLP-based vaccine platform but also sheds light on FeLV vaccine research.", "journal": "International journal of molecular sciences", "doi": "10.3390/ijms24109025", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37235153", "author": "Moyadee W", "n_authors": 10, "title": "The first study on clinicopathological changes in cats with feline infectious peritonitis with and without retrovirus coinfection.", "abstract": "Feline infectious peritonitis (FIP) is an infectious, immune-mediated, and fatal disease in cats caused by a mutant feline coronavirus (FCoV) infection. Feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) are two common retroviruses that play a role in reducing feline immune function with opportunistic retrovirus infection being a predisposing factor for the development of FIP. This study aimed to evaluate the clinicopathological parameters of FIP in cats with and without retrovirus coinfection. In total, 62 cats presenting with pleural and/or peritoneal effusion at the Kasetsart University Veterinary Teaching Hospital, Bangkok, Thailand, were selected for the study. Effusion samples were collected and a reverse transcriptase-polymerase chain reaction (RT-PCR) assay was performed on all samples using the 3' untranslated region primer. All FCoV-positive cats were tested for retrovirus infection using a commercial kit (Witness FeLV-FIV [Zoetis]; United States). Clinical signs, hematological, and biochemical parameters of these cats were investigated and grouped. Of the 62 cats with pleural and/or peritoneal effusion, FCoV was detected in 32, of which 21 were highly suspicious for FIP. The cats suspected of FIP were divided into three subgroups following viral detection. A total of 14 had only FCoV infection (Group A), four had FCoV and FeLV infection (Group B), and three had FCoV, FeLV, and FIV infection (Group C). Of the rest, 11 had definitive diagnoses, which included three being FCoV and FeLV-positive (Group D), and eight were retrovirus-negative (Group E). Mild anemia and lymphopenia were found in cats infected with these three viruses. An albumin-to-globulin ratio lower than 0.5 was found in FIP cats with only FCoV infection. Typically, cats with clinical effusion and FIP, with and without retrovirus coinfection, had similar hematological findings. Clinical signs, blood parameters, fluid analysis with cytological assessment, and RT-PCR assays could identify better criteria to diagnose FIP with and without retrovirus coinfection.", "journal": "Veterinary world", "doi": "10.14202/vetworld.2023.820-827", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37223406", "author": "Yamakawa AC", "n_authors": 11, "title": "Molecular detection of feline hemoplasmas and retroviruses in free-roaming and shelter cats within a university campus.", "abstract": "The aim of the present study was to assess the frequency of hemoplasma, feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) infections in cats living in an on-campus shelter and free-roaming cats within a university campus in Brazil. Blood samples were tested using quantitative PCR for hemoplasma, FIV and FeLV. Positive hemoplasma samples were sequenced. Associations between hemoplasma detection and living situation, sex, flea and/or tick parasitism, and coinfection with FIV and FeLV, were assessed using Fisher's exact test and the respective odds ratios were calculated. Overall, 6/45 (13.3%) cats tested positive: four (8.9%) were infected with ' These results show that even if the free-roaming cat population is clinically healthy and has adequate access to food, it may present flea infestation and hemoplasma infection with lower packed cell volume values.", "journal": "JFMS open reports", "doi": "10.1177/20551169221148672", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37209619", "author": "Biezus G", "n_authors": 9, "title": "Progressive and regressive infection with feline leukemia virus (FeLV) in cats in southern Brazil: Prevalence, risk factors associated, clinical and hematologic alterations.", "abstract": "Enzyme-linked immunosorbent assay (ELISA) for viral antigen is commonly used for the diagnosis of progressive feline leukemia virus (FeLV) infection but is not able to determine the true prevalence of infection when used as the sole test. Additional testing to detect proviral DNA will identify regressive (antigen negative) FeLV infections as well as progressive infections. Therefore, this study aimed to determine the prevalence of progressive and regressive FeLV infection, outcome-associated factors, and hematologic changes. A cross-sectional study was performed on 384 cats selected from routine hospital care. Blood samples were subjected to complete blood count, ELISA for FeLV antigen and FIV antibody, and nested PCR amplifying the U3- LTR region and gag gene, which are conserved in most exogenous FeLV. The prevalence of FeLV infection was 45.6% (CI", "journal": "Preventive veterinary medicine", "doi": "10.1016/j.prevetmed.2023.105945", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37195404", "author": "Martins NDS", "n_authors": 14, "title": "Molecular characterization of Brazilian FeLV strains in São Luis, Maranhão Brazil.", "abstract": "The feline leukemia virus (FeLV) belongs to the Retroviridae family and Gammaretrovirus genus, and causes a variety of neoplastic and non-neoplastic diseases in domestic cats (Felis catus), such as thymic and multicentric lymphomas, myelodysplastic syndromes, acute myeloid leukemia, aplastic anemia, and immunodeficiency. The aim of the present study was to carry out the molecular characterization of FeLV-positive samples and determine the circulating viral subtype in the city of São Luís, Maranhão, Brazil, as well as identify its phylogenetic relationship and genetic diversity. The FIV Ac/FeLV Ag Test Kit (Alere™) and the commercial immunoenzymatic assay kit (Alere™) were used to detect the positive samples, which were subsequently confirmed by ELISA (ELISA - SNAP® Combo FeLV/FIV). To confirm the presence of proviral DNA, a polymerase chain reaction (PCR) was performed to amplify the target fragments of 450, 235, and 166 bp of the FeLV gag gene. For the detection of FeLV subtypes, nested PCR was performed for FeLV-A, B, and C, with amplification of 2350-, 1072-, 866-, and 1755-bp fragments for the FeLV env gene. The results obtained by nested PCR showed that the four positive samples amplified the A and B subtypes. The C subtype was not amplified. There was an AB combination but no ABC combination. Phylogenetic analysis revealed similarities (78% bootstrap) between the subtype circulating in Brazil and FeLV-AB and with the subtypes of Eastern Asia (Japan) and Southeast Asia (Malaysia), demonstrating that this subtype possesses high genetic variability and a differentiated genotype.", "journal": "Virus genes", "doi": "10.1007/s11262-023-01997-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37173777", "author": "Schäfer I", "n_authors": 9, "title": "Feline leishmaniosis with focus on ocular manifestation: a case report.", "abstract": "In Europe, feline leishmaniosis is commonly caused by Leishmania infantum. There is little knowledge regarding pathogenesis, ocular manifestations and long-term follow-ups in cats with leishmaniosis. A 6-year-old female, spayed European Shorthair cat was imported from Spain to Germany 2 years prior to its first clinical presentation. The cat showed lethargy, weight loss, ulcerative lesions on the front limbs and high-grade chronic uveitis. The diagnosis of L. infantum infection was based on the cytological finding of amastigotes in skin lesions, positive qPCR of EDTA-blood and positive PCR of a cyto-brush sample from the conjunctiva. Supportive findings included positive serology by IFAT, serum protein capillary electrophoresis with peaks in alpha2- and gamma-globulin sections and marked elevation of SAA. Enucleation had to be performed on day 288 on both eyes because of blindness, glaucoma and high-grade uveitis. Histologically, high numbers of Leishmania spp. amastigotes were found in histiocytes. IFAT and PCR were positive in the aqueous humor in both eyes, respectively. Feline leukemia virus antigen and feline immunodeficiency virus antibody testings were positive. Hematological and biochemical results revealed mild leukocytosis with lymphocytosis, monocytosis and eosinopenia as well as marked elevation of SAA and hyperglobulinemia. The cat was treated with allopurinol, responded well and was still alive at follow-up on day 288 after first presentation. However, enucleation was necessary because of refractory glaucoma and uveitis.  CONCLUSION: For the first time, ocular evidence of Leishmania IgG antibodies was demonstrated in the aqueous humor of both eyes in cats. There is limited knowledge about the pathogenesis, treatment options and outcomes in cats infected with L. infantum. This case report supports the hypothesis that immunosuppression increases the risk of clinical signs of leishmaniasis in cats. Alpha2- and gamma-globulin peaks in serum protein capillary electrophoresis are supportive criteria for the diagnosis of L. infantum infection. SAA is valuable for monitoring. Regarding ophthalmology, uveitis and glaucoma may have a poor prognosis.", "journal": "Parasites & vectors", "doi": "10.1186/s13071-023-05741-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37112816", "author": "AbuEed L", "n_authors": 7, "title": "Feline Foamy Virus Transmission in Tsushima Leopard Cats (Prionailurus bengalensis euptilurus) on Tsushima Island, Japan.", "abstract": "Tsushima leopard cats (TLC; ", "journal": "Viruses", "doi": "10.3390/v15040835", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37100056", "author": "Kenny TC", "n_authors": 12, "title": "Integrative genetic analysis identifies FLVCR1 as a plasma-membrane choline transporter in mammals.", "abstract": "Genome-wide association studies (GWASs) of serum metabolites have the potential to uncover genes that influence human metabolism. Here, we combined an integrative genetic analysis that associates serum metabolites to membrane transporters with a coessentiality map of metabolic genes. This analysis revealed a connection between feline leukemia virus subgroup C cellular receptor 1 (FLVCR1) and phosphocholine, a downstream metabolite of choline metabolism. Loss of FLVCR1 in human cells strongly impairs choline metabolism due to the inhibition of choline import. Consistently, CRISPR-based genetic screens identified phospholipid synthesis and salvage machinery as synthetic lethal with FLVCR1 loss. Cells and mice lacking FLVCR1 exhibit structural defects in mitochondria and upregulate integrated stress response (ISR) through heme-regulated inhibitor (HRI) kinase. Finally, Flvcr1 knockout mice are embryonic lethal, which is partially rescued by choline supplementation. Altogether, our findings propose FLVCR1 as a major choline transporter in mammals and provide a platform to discover substrates for unknown metabolite transporters.", "journal": "Cell metabolism", "doi": "10.1016/j.cmet.2023.04.003", "deposited_data": "Sim", "nuccore_ids": "2293176160, 2293176159, 2293176158, 2293176156, 2293176150, 2293176103, 2293176055, 2293176015, 229892321, 229892319, 229892317, 229892315, 2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2293176160, 2293176159, 2293176158, 2293176156, 2293176150, 2293176103, 2293176055, 2293176015, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 2213208191, 2213207086, 2213206999, 2213206978, 2213206969, 2213206931, 2213206870, 1907119948, 1907068588, 1907068586, 1907068585, 1907068583, 1907068581, 1907068579, 1720387888, 1720355056, 1519315556, 924181778, 924181484, 651165916, 649572214, 563317862, 563317861, 229892321, 229892319, 229892317, 229892315, 124486924", "bioproject_ids": "948356", "sra_ids": "27101935, 27101934, 27101933, 27101932, 27101931, 27101930, 27101929, 27101928, 27101927, 27101926, 27101925, 27101924"}, {"year": 2023, "pmid": "37068860", "author": "Melo TB", "n_authors": 12, "title": "Molecular detection of vector-borne pathogens in cats tested for FIV and FeLV.", "abstract": "The aim of this study was to detect molecularly vector borne pathogens (VBPs) in domiciled cats tested for Feline immunodeficiency virus (FIV) and Feline leukemia virus (FeLV). Blood samples (n = 119) were analyzed microscopically and molecularly through PCR and sequenced for the detection of the following pathogens: piroplasmids., Bartonella henselae, Cytauxzoon felis, Ehrlichia canis, Leishmania spp., hemotropic Mycoplasma spp., Trypanosoma spp., and Ricketssia spp. Animals were also serological assessed for detection of antibodies against FIV and FeLV. Out of all animals, 20.16% (24/119) tested positive for at least one VBPs at molecular examination. Conversely, no animal resulted positive at microscopic analysis. The most prevalent pathogen was hemotropic Mycoplasma haemofelis (8.40%; 10/119), followed by Candidatus Mycoplasma haemominutum (5.88%; 7/119), E. canis (5.04%; 6/119), C. felis (0.84%; 1/119) and B. henselae (0.84%; 1/119). One animal (0.84%; 1/119) was co-infected with. E. canis and B. henselae. A total of 5.88% (7/119) and 1.68% (2/119) tested positive for FIV and FeLV, respectively. Data of this study demonstrate that owned cats can be at risk of hemotropic Mycoplasma spp., E. canis, C. felis and B. henselae. Therefore, preventive measures against vectors of these pathogens should be implemented in order to reduce the risk of exposition and consequently infection. Additionally, aggressive behaviors among cats should be avoided, especially because hemotropic Mycoplasma spp. may be transmitted through the bite of animals.", "journal": "Veterinary parasitology, regional studies and reports", "doi": "10.1016/j.vprsr.2023.100857", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36985312", "author": "Aslam MW", "n_authors": 6, "title": "Clinicopathological and Radiological Features of Cats Presented with Infectious Respiratory Disease Signs: A Focus on Rhodococcus equi and Klebsiella pneumoniae.", "abstract": "The objective of this study was to evaluate the prevalence of involvement of common viral organisms ", "journal": "Microorganisms", "doi": "10.3390/microorganisms11030737", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36947073", "author": "Gozashti L", "n_authors": 3, "title": "Transposable Element Interactions Shape the Ecology of the Deer Mouse Genome.", "abstract": "The genomic landscape of transposable elements (TEs) varies dramatically across species, with some TEs demonstrating greater success in colonizing particular lineages than others. In mammals, long interspersed nuclear element (LINE) retrotransposons are typically more common than any other TE. Here, we report an unusual genomic landscape of TEs in the deer mouse, Peromyscus maniculatus. In contrast to other previously examined mammals, long terminal repeat elements occupy more of the deer mouse genome than LINEs (11% and 10%, respectively). This pattern reflects a combination of relatively low LINE activity and a massive invasion of lineage-specific endogenous retroviruses (ERVs). Deer mouse ERVs exhibit diverse origins spanning the retroviral phylogeny suggesting they have been host to a wide range of exogenous retroviruses. Notably, we trace the origin of one ERV lineage, which arose ∼5-18 million years ago, to a close relative of feline leukemia virus, revealing inter-ordinal horizontal transmission. Several lineage-specific ERV subfamilies have very high copy numbers, with the top five most abundant accounting for ∼2% of the genome. We also observe a massive amplification of Kruppel-associated box domain-containing zinc finger genes, which likely control ERV activity and whose expansion may have been facilitated by ectopic recombination between ERVs. Finally, we find evidence that ERVs directly impacted the evolutionary trajectory of LINEs by outcompeting them for genomic sites and frequently disrupting autonomous LINE copies. Together, our results illuminate the genomic ecology that shaped the unique deer mouse TE landscape, shedding light on the evolutionary processes that give rise to variation in mammalian genome structure.", "journal": "Molecular biology and evolution", "doi": "10.1093/molbev/msad069", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36924831", "author": "Biezus G", "n_authors": 8, "title": "Phylogenetic identification of feline leukemia virus A and B in cats with progressive infection developing into lymphoma and leukemia.", "abstract": "To date, only a few studies have examined the impacts of feline leukemia virus (FeLV) subgroups on disease development in spontaneously infected cats. The present study identified FeLV-A and FeLV-B subgroups in cats with lymphoma and leukemia and explored the phylogenetic relationships of env sequences. Twenty-six cats with lymphoma (n=16) or leukemia (n=10) were selected. FeLV p27 antigen positivity was determined using ELISA, and proviral DNA in blood samples was detected using nested PCR. Positive animals in both tests were classified as cases of FeLV progressive infection and subjected to a second nested PCR for env amplification and subgroup determination. Six samples of FeLV-A and five samples of FeLV-B were sequenced using the Sanger method, and the results were used to build a phylogenetic tree and estimate evolutionary divergence. Among cats with lymphoma, 68.8% carried FeLV-AB and 31.2% FeLV-A. Among cats with leukemia, 70% carried FeLV-AB and 30% FeLV-A. Regarding cat characteristics, 50% were young, 30.8% young adults, and 19.2% adults; 88.5% were mixed-breed and 11.5% pure breed; and 42.3% were males and 57.7% were females. Among lymphomas, 62.5% were mediastinal, 31.3% multicentric, and 6.3% extranodal. Regarding histological classification, lymphoblastic and small non-cleaved-cell lymphomas were the most frequently detected. Among leukemia cases, 30% were acute lymphoid, 30% chronic myeloid, and 40% acute myeloid. Phylogenetic analysis showed that FeLV-A SC sequences were closely related to the Arena, Glasgow-1, and FeLV-FAIDS variants. Meanwhile, FeLV-B SC sequences were divergent from one another but similar to the endogenous FELV env gene (enFeLV). In conclusion, FeLV-AB is prevalent in cats with lymphoma and leukemia, highlighting the genetic diversity involved in the pathogenesis of these neoplasms in Brazil.", "journal": "Virus research", "doi": "10.1016/j.virusres.2023.199093", "deposited_data": "Sim", "nuccore_ids": "2462483771, 2462483770, 2462483768, 2462483766, 2462483764, 2462483762, 2462483760, 2462483758, 2462483756, 2459163109", "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36871053", "author": "Morishita M", "n_authors": 10, "title": "Wavy changes in the whiskers of domestic cats are correlated with feline leukemia virus infection.", "abstract": "Feline leukemia virus (FeLV) is a retrovirus with global impact on the health of domestic cats and is usually examined by serology. In our daily clinical practice, we noticed that cats infected with FeLV often possess wavy whiskers (sinus hairs on the face). To investigate the relationship between wavy whiskers (WW) and FeLV infection, the association between the presence or absence of wavy changes in whiskers and serological FeLV infection was examined in a total of 358 cats including 56 cats possessing WW, using the chi-square test. The results of blood tests from 223 cases were subjected to multivariate analysis (logistic analysis). Isolated whiskers were observed under light microscopy, and upper lip tissues (proboscis) were subjected to histopathological and immunohistochemical analyses. The prevalence of WW was significantly correlated with FeLV antigen positivity in the blood. Of 56 cases with WW, 50 (89.3%) were serologically positive for FeLV. The significant association between WW and serological FeLV positivity was also confirmed by multivariate analysis. In WW, narrowing, degeneration, and tearing of the hair medulla were observed. Mild infiltration of mononuclear cells in the tissues, but no degeneration or necrosis, was found. By immunohistochemistry, FeLV antigens (p27, gp70 and p15E) were observed in various epithelial cells including the sinus hair follicular epithelium of the whisker. The data suggest that the wavy changes in whiskers, a unique and distinctive external sign on a cat's face, were associated with FeLV infection.", "journal": "BMC veterinary research", "doi": "10.1186/s12917-023-03610-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36869834", "author": "Wronski JG", "n_authors": 9, "title": "Ophthalmic and immunopathological characterization of systemic infectious diseases in cats.", "abstract": "Ocular involvement in systemic diseases is frequent in cats; however, without concurrent clinical and ophthalmic examinations with gross and/or histologic analysis of the eye, these findings can be underdiagnosed. This article aims to provide gross, histologic, and immunohistochemical characteristics of ocular lesions from cats submitted to necropsy, focusing on those caused by systemic infectious agents. Cats that died due to a systemic infectious disease were selected based on necropsy diagnosis and presence of ocular lesions. Gross, histologic, and immunohistochemical findings were recorded. From April 2018 to September 2019, 849 eyes of 428 cats were evaluated. Histologic abnormalities were seen in 29% of cases, which were classified as inflammatory (41%), neoplastic (32%), degenerative (19%), and metabolic/vascular (8%). Macroscopic changes were present in one-third of eyes with histologic lesions. Of these, 40% were attributed to inflammatory or neoplastic diseases associated with infectious agents. The most important infectious agents causing ocular disease in this study were feline leukemia virus, feline infectious peritonitis virus, and ", "journal": "Veterinary pathology", "doi": "10.1177/03009858231158075", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36858000", "author": "de Mello LS", "n_authors": 7, "title": "Diseases associated with feline leukemia virus and feline immunodeficiency virus infection: A retrospective study of 1470 necropsied cats (2010-2020).", "abstract": "Feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) are retroviruses affecting cats worldwide, and the prevalence of infection varies considerably according to the geographic area. We retrospectively described FIV- and FeLV-associated diseases in a population of 1470 necropsied cats, of which 396 (26.9%) were infected with FeLV, 199 (13.5%) with FIV, and 134 (9.1%) with FeLV and FIV concomitantly. Cats infected with FeLV (OR 3.4) and co-infected with FeLV and FIV (OR 1.9) were more likely to have neoplasms. The diagnosis of lymphoma and leukemia was higher in cats infected with FeLV (OR 3.9 and 19.4, respectively) and coinfected with FeLV and FIV (OR 1.9 and 19.3, respectively). The odds of diagnosing bacterial diseases were higher in cats coinfected with FeLV and FIV (OR: 2.8), whereas the odds of viral diseases were higher in those infected with FeLV (OR: 2.8), with 2.2 times more diagnoses of feline infectious peritonitis. Neoplastic and infectious diseases in FIV-infected cats did not differ significantly from those in uninfected cats. According to our results, a high prevalence of retroviral infections was observed in southern Brazil, mainly in relation to FeLV. Infected cats were significantly younger than uninfected cats. The main causes of death associated with FeLV infection and FeLV and FIV coinfection were neoplastic and infectious diseases. In contrast, FIV infection was not associated with any specific condition.", "journal": "Comparative immunology, microbiology and infectious diseases", "doi": "10.1016/j.cimid.2023.101963", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36851705", "author": "Westman ME", "n_authors": 11, "title": "Field Performance of a Rapid Test to Detect Progressive, Regressive, and Abortive Feline Leukemia Virus Infections in Domestic Cats in Australia and Germany.", "abstract": "Different feline leukemia virus (FeLV) infection outcomes are possible in cats following natural exposure, such as progressive infections (persistent viremia), regressive infections (transient or no viremia followed by proviral persistence) and abortive infections (presence of only antibodies). Laboratory-based testing is currently required for categorization of infection outcomes in cats. The aim of this study was to evaluate the field performance of a novel, rapid, combination point-of-care (PoC) test kit commercially available in Europe (v-RetroFel", "journal": "Viruses", "doi": "10.3390/v15020491", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36777664", "author": "Miguel-Pastor L", "n_authors": 9, "title": "Evaluation of Platelet-Rich Plasma by means of PRGF(®)-Endoret(®) protocol in leukemia cats: PDGF-BB and TGF-ß1 valuation.", "abstract": "Feline leukemia virus (FeLV) is a chronic disease that leads to the weakening of a cat's immune system. Platelet-rich plasma (PRP) offers therapeutic effects for multiple diseases, the use of PRP and growth factors (GFs) determination could be an alternative treatment to improve the quality of life in these patients. The objectives of this study were to determine and compare the concentration of platelets (PLTs), red blood cells (RBCs) and white blood cells (WBCs) between samples of whole blood (WB), PRP and platelet-poor plasma (PPP) fractions, and to evaluate the concentration of platelet-derived growth factor BB (PDGF-BB) and transforming growth factor β1 (TGF-β1) in both fractions in FeLV cats using a PRGF WB was collected from 11 asymptomatic FeLV-positive cats. PRP and PPP was obtained following PRGF PLT in the PRP fraction was statistically higher than WB and PPP fraction, with no statistical differences between WB and PPP. PLT concentration increased 1.4 times in PRP fraction compared to WB. Mean platelet volume (MPV) did not differ significantly between the WB, PRP, and PPP fractions. Compared to WB, the absolute numbers of RBCs and WBCs were decreased by 99% and more than 95% in the PRP and PPP fractions, respectively. TGF-ß1 concentrations increased in PRP vs. PPP, with no changes in PDGF-BB. Based on the degree of PLT enrichment and the absence of RBCs and WBCs, this blood product could be classified as a Pure Platelet-Rich Plasma (P-PRP). The presence of GFs in PRP and PPP samples suggests that the PRGF", "journal": "Frontiers in veterinary science", "doi": "10.3389/fvets.2023.1110055", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36744227", "author": "Dezubiria P", "n_authors": 5, "title": "Animal shelter management of feline leukemia virus and feline immunodeficiency virus infections in cats.", "abstract": "Approximately 5% of cats in animal shelters in the United States test positive for either feline leukemia virus (FeLV) or feline immunodeficiency virus (FIV), which translates to more than 100,000 positive cats managed by shelters each year. Little is known about the current status of retroviral management in animal shelters, particularly in regions burdened by chronic pet overpopulation and high shelter admissions, such as the southern United States. The purpose of this study was to describe feline retroviral management in Florida shelters. Shelters were surveyed on practices including selection of cats for testing, diagnostic techniques, and outcome options for cats with positive test results. Responses were received from 139 of 153 animal shelters known to admit cats, including 55 municipal shelters (40%), 70 private shelters (50%), and 14 private shelters with municipal contracts (10%). A total of 115 shelters (83%) performed at least some testing, most using combination point-of-care devices for simultaneous FeLV antigen and FIV antibody screening. Of shelters that performed any testing, 56 (49%) tested all cats for FeLV and 52 (45%) tested all cats for both FeLV and FIV. The most common reason for testing was screening adoptable cats (108 shelters; 94%) and cats available for transfer to other organizations (78; 68%). Testing cats in trap-neuter-return/return-to-field programs was least common (21; 18%). Most common outcome options for positive cats included adoption (74; 64%), transfer (62; 54%), and euthanasia (49; 43%). Euthanasia following a positive test result was more common for cats with FeLV (49; 43%) than for cats with FIV (29; 25%) and was more common in municipal shelters, rural shelters, shelters taking in <500 cats a year, and shelters with overall live outcome rates for cats <70%. Although Florida shelter compliance with national guidelines for identification and management of FeLV and FIV positive cats was variable, most had live outcome options for at least some of their cats with positive test results. Increased access to training and practical programmatic tools may help more shelters implement cost-effective testing protocols, reduce risk for transmission to other cats, and support the best outcomes for this vulnerable population of cats.", "journal": "Frontiers in veterinary science", "doi": "10.3389/fvets.2022.1003388", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36691036", "author": "Nielsen SS", "n_authors": 8, "title": "Assessing welfare risks in unowned unsocialised domestic cats in Denmark based on associations with low body condition score.", "abstract": "Populations of unowned unsocialised cats are present worldwide. Generally, there is concern about their welfare. Low body condition score (BCS) is a potentially relevant indicator that is relatively easy to assess: emaciated cats are likely to have welfare problems while thin cats may be at risk of becoming emaciated. The objective of this study was to assess the association of low BSC with a selection of factors relating to the host, disease, and infection in unowned unsocialised domestic cats. We necropsied 598 euthanised unowned unsocialised cats from Denmark. We recorded each cat's age-group, sex, and neuter status, together with its pregnancy status, the season and location of trapping, as well as gross lesions at necropsy. We also tested for feline immunodeficiency virus and feline leukaemia virus, recorded presence of ectoparasites, and a subsample of the cats were also tested for endoparasites. Cats with no or sparse adipose deposits were categorised as having low BCS, and logistic regression was used to determine the factors associated with low BCS. Of the cats, 11.4% had low BCS. Season, age-group and sex were associated with low BCS and confounded potential associations with other variables. Intact adult males and females in spring and early summer were at highest risk of low BCS. When these factors were taken into account, cats with biting lice had 2.8 (95% confidence interval (CI) 1.4-5.4) times higher odds of low BCS, and cats with gastro-intestinal findings (i.e., enlarged mesenteric lymph nodes, abdominal hernia, diarrhoea, obstructive foreign bodies, or diaphragmatic hernia) had 50 (95% CI 10-417) times higher odds of low BCS, than cats with no such findings. Cats with low BCS were primarily adult intact cats with tooth lesions and skin lesions, ear mite infection, and positive test result for feline immunodeficiency virus. The results highlight associations that can be used to define a risk profile: low BCS, notably in summer-autumn, in an unowned unsocialised cat was associated with underlying, less visible problems. Thus, low BCS can be more than a step towards being emaciated; it can also be an indicator of other underlying welfare problems.", "journal": "Acta veterinaria Scandinavica", "doi": "10.1186/s13028-023-00665-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36685018", "author": "Matralis D", "n_authors": 6, "title": "A Case of Feline Leishmaniosis with Panniculitis.", "abstract": "Leishmaniases are a group of diseases caused by protozoa of the genus ", "journal": "Case reports in veterinary medicine", "doi": "10.1155/2023/8864790", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36668961", "author": "Mazzotta E", "n_authors": 10, "title": "Feline Susceptibility to Leptospirosis and Presence of Immunosuppressive Co-Morbidities: First European Report of L. interrogans Serogroup Australis Sequence Type 24 in a Cat and Survey of Leptospira Exposure in Outdoor Cats.", "abstract": "Leptospirosis is one of the most widespread zoonotic diseases and can infect both humans and animals worldwide. The role of the cat as a susceptible host and potential environmental reservoir of ", "journal": "Tropical medicine and infectious disease", "doi": "10.3390/tropicalmed8010054", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36656269", "author": "Roug A", "n_authors": 4, "title": "Disease Surveillance of Cougars (Puma concolor) in Utah, USA.", "abstract": "Adult, free-ranging cougars (Puma concolor) were sampled in three regions of Utah, US, from 2018 to 2021. A total of 68% (23/34) of the sampled cougars had antibodies to feline parvovirus, 15% (5/33) to canine distemper virus, 18% (6/34) to calicivirus, and 22% (8/37) to Yersinia pestis. Forty-one percent (13/32) had IgG antibodies to Toxoplasma gondii and 6% (2/33) to feline immunodeficiency virus, and 3% (1/32) were positive for Dirofilaria immitis (heartworm) antigen. All were seronegative for Toxoplasma gondii IgM, feline enteric coronavirus, SARS-CoV-2, feline leukemia virus, feline herpesvirus, and Francisella tularensis. Tapeworms and Toxascaris leonina eggs were detected in the feces. The disease exposures detected were similar to what has been reported from cougar populations in other western US states, and the current level of exposures is unlikely to have a negative impact on the state's population.", "journal": "Journal of wildlife diseases", "doi": "10.7589/JWD-D-22-00080", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36653146", "author": "Shoji H", "n_authors": 4, "title": "Characterization of ferret Pit1 as a receptor of feline leukemia virus subgroup B.", "abstract": "Feline leukemia virus (FeLV) is a retrovirus that causes immune suppression and immunodeficiency, leading to opportunistic infections and leukemia/lymphoma in cats. Today, a variety of domestic mammals are kept in houses, and it is important to evaluate the possibility of interspecies transmission of FeLV. In this study, we assessed the infectivity of FeLV-B in ferrets that belong to Mustelidae. By pseudotype virus infection assay, we revealed that a ferret cell line, Mpf cells, is resistant to FeLV-B infection. The mRNA expression level of the FeLV-B receptor, Pit-1, was approximately half that of cat FEA cells in ferret Mpf cells. There was no significant difference in receptor usage between ferret's and cat's Pit1. These data may indicate the presence of the post-transcriptional modification and/or the restriction factor(s) against the FeLV-B infection in ferrets.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.22-0526", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36631598", "author": "Petrillo S", "n_authors": 22, "title": "Endothelial cells require functional FLVCR1a during developmental and adult angiogenesis.", "abstract": "The Feline Leukemia Virus Subgroup C Receptor 1a (FLVCR1a) is a transmembrane heme exporter essential for embryonic vascular development. However, the exact role of FLVCR1a during blood vessel development remains largely undefined. Here, we show that FLVCR1a is highly expressed in angiogenic endothelial cells (ECs) compared to quiescent ECs. Consistently, ECs lacking FLVCR1a give rise to structurally and functionally abnormal vascular networks in multiple models of developmental and pathologic angiogenesis. Firstly, zebrafish embryos without FLVCR1a displayed defective intersegmental vessels formation. Furthermore, endothelial-specific Flvcr1a targeting in mice led to a reduced radial expansion of the retinal vasculature associated to decreased EC proliferation. Moreover, Flvcr1a null retinas showed defective vascular organization and loose attachment of pericytes. Finally, adult neo-angiogenesis is severely affected in murine models of tumor angiogenesis. Tumor blood vessels lacking Flvcr1a were disorganized and dysfunctional. Collectively, our results demonstrate the critical role of FLVCR1a as a regulator of developmental and pathological angiogenesis identifying FLVCR1a as a potential therapeutic target in human diseases characterized by aberrant neovascularization.", "journal": "Angiogenesis", "doi": "10.1007/s10456-023-09865-w", "deposited_data": "Sim", "nuccore_ids": "2992366784, 3377526273, 3377526270, 2992366784, 2973648576, 2973648575, 2972057995, 2972057928, 2972057901, 2972057847, 924181778, 924181484, 124486924", "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36630814", "author": "da Rosa Maciel A", "n_authors": 8, "title": "Mycoplasma haemofelis infection and its correlation with feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) in cats in Southern Brazil.", "abstract": "A cross-sectional study was conducted on 274 cats in Southern Brazil to estimate the prevalence of Mycoplasma haemofelis PCR, associated factors, and its correlation with ELISA for FeLV and FIV. The apparent prevalence of M. haemofelis was 6.6% (18/274) (95% CI: 3.6-9.5%), of which 33.3% (6/18) had co-infection with FeLV, 5.6% (1/18) with FIV, and 5.6% (1/18) with both. Male cats were more likely to be positive for M. haemofelis [OR: 7.07 (1.97-25.34)]. Only three M. haemofelis-positive cats showed related clinical changes, such as mucosal pallor. A statistically significant difference was observed between M. haemofelis-positive cats and the negative control group for age, hemoglobin concentration, packed cell volume, and rod neutrophil counts. Mycoplasma haemofelis is prevalent in southern Brazil, with a higher risk in male cats. Most cats could be classified as asymptomatic carriers since they were healthy.", "journal": "Comparative immunology, microbiology and infectious diseases", "doi": "10.1016/j.cimid.2022.101941", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36619784", "author": "Intrieri JM", "n_authors": 9, "title": "Pyothorax caused by Nocardia sp. in a cat - Case report.", "abstract": "Nocardiosis is an infection caused by ubiquitous opportunistic bacteria and is rare in felines. In retrospective studies of the infection in the species, pyothorax was found in only about 5% of the cases described, with the most frequent forms being cutaneous and subcutaneous. This report describes ", "journal": "Brazilian journal of veterinary medicine", "doi": "10.29374/2527-2179.bjvm005522", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36565524", "author": "Khalife S", "n_authors": 2, "title": "Occurrence and risk factors of feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV) in cats of Lebanon.", "abstract": "A cross-sectional study was carried out between April 2020 and August 2021. Blood samples were collected from 260 household cats recruited in different clinics in North and Mount Lebanon, with the aim of determining the seroprevalence of feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV). The seroprevalence reported reached 18.84% (95% CI 0.14-0.24) and 13.84% (95% CI 0.09-0.18) for FIV and FeLV, respectively. FIV seropositivity was associated with a younger age, health and neuter status, lymphoma, lethargy, and vomiting. Furthermore, male sex, neuter status, lymphoma, anaemia, lethargy, and vomiting were significantly associated with FeLV seropositivity. This first data from Lebanon emphasizes the need for implementing preventive programmes to cope with FIV- and FeLV-associated morbidity and mortality among cats.", "journal": "Comparative immunology, microbiology and infectious diseases", "doi": "10.1016/j.cimid.2022.101931", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36307958", "author": "Esty K", "n_authors": 7, "title": "Evaluation of barcoded magnetic bead-based immunoassays for the simultaneous detection of feline leukemia virus antigen and antibody against feline immunodeficiency virus.", "abstract": "Testing platforms that leverage automation, require minimal sample volume, and enable various tests to be performed simultaneously on a single sample have the potential to improve workflow and efficiency in veterinary diagnostic laboratories. We evaluated a barcoded magnetic bead (BMB) technology using established immunoassays for detection of feline leukemia virus (FeLV) p27 antigen and antibody against feline immunodeficiency virus (FIV). Analytical sensitivity, limit of blank, and limit of detection were used to establish a functional sensitivity of 1.00 ng/mL of inactivated FeLV antigen and 35.7 ng/mL of anti-FIV monoclonal antibody. Common interferents, such as hemoglobin, lipid, and bilirubin, were not found to interfere with the performance of the assay. Intra- and inter-assay CVs were <13% for both assays using manufactured samples. Using a set of 116 feline samples, the diagnostic accuracy of our multiplex assay was 100% compared to reference assays. Performance in a convenience set of 1,000 feline samples submitted to a commercial diagnostic laboratory revealed a proportion of positive results of 1.3% for FeLV and 3.7% for FIV. BMB technology should enable rapid screening of samples for various markers in a single immunoassay well.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/10406387221129259", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36229725", "author": "Villanueva-Saz S", "n_authors": 19, "title": "A cross-sectional serosurvey of SARS-CoV-2 and co-infections in stray cats from the second wave to the sixth wave of COVID-19 outbreaks in Spain.", "abstract": "Severe Acute Respiratory Syndrome Coronavirus 2 is the causative agent of Coronavirus Disease 2019 in humans. Among domestic animals, cats are more susceptible to SARS-CoV-2 than dogs. The detection of anti-SARS-CoV-2 antibodies in seemingly healthy cats and/or infected cats which are in close contact with infected humans has been described. The presence of animals that tested positive by serology or molecular techniques could represent a potential transmission pathway of SARS-CoV-2 that can spill over into urban wildlife. This study analyses the seroprevalence variation of SARS-CoV-2 in stray cats from different waves of outbreaks in a geographical area where previous seroepidemiological information of SARS-CoV-2 was available and investigate if SARS-CoV-2-seropositive cats were exposed to other co-infections causing an immunosuppressive status and/or a chronic disease that could lead to a SARS-CoV-2 susceptibility. For this purpose, a total of 254 stray cats from Zaragoza (Spain) were included. This analysis was carried out by the enzyme-linked immunosorbent assay using the receptor binding domain of Spike antigen and confirmed by serum virus neutralization assay. The presence of co-infections including Toxoplasma gondii, Leishmania infantum, Dirofilaria immitis, feline calicivirus, feline herpesvirus type 1, feline leukemia virus and feline immunodeficiency virus, was evaluated using different serological methods. A seropositivity of 1.57% was observed for SARS-CoV-2 including the presence of neutralizing antibodies in three cats. None of the seropositive to SARS-CoV-2 cats were positive to feline coronavirus, however, four SARS-CoV-2-seropositive cats were also seropositive to other pathogens such as L. infantum, D. immitis and FIV (n = 1), L. infantum and D. immitis (n = 1) and L. infantum alone (n = 1).Considering other pathogens, a seroprevalence of 16.54% was detected for L. infantum, 30.31% for D. immitis, 13.78%, for T. gondii, 83.86% for feline calicivirus, 42.52% for feline herpesvirus type 1, 3.15% for FeLV and 7.87% for FIV.Our findings suggest that the epidemiological role of stray cats in SARS-CoV-2 transmission is scarce, and there is no increase in seropositivity during the different waves of COVID-19 outbreaks in this group of animals. Further epidemiological surveillances are necessary to determine the risk that other animals might possess even though stray cats do not seem to play a role in transmission.", "journal": "Veterinary research communications", "doi": "10.1007/s11259-022-10016-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36178295", "author": "Canto-Valdés MC", "n_authors": 4, "title": "What role do endogenous retroviruses play in domestic cats infected with feline leukaemia virus?", "abstract": "Feline leukaemia virus (FeLV) is a retrovirus that infects domestic and wild cats around the world. FeLV infection is associated with the development of neoplasms, bone marrow disorders and immunosuppression. Viral subgroups arise from mutations in the FeLV genome or from recombination of FeLV with ancestral endogenous retroviruses in the cat genome. The retroviral endogenisation process has allowed generation of a diversity of endogenous viruses, both functional and defective. These elements may be part of the normal functioning of the feline genome and may also interact with FeLV to form recombinant FeLV subgroups, enhance pathogenicity of viral subgroups, or inhibit and/or regulate other retroviral infections. Recombination of the env gene occurs most frequently and appears to be the most significant in terms of both the quantity and diversification of pathogenic effects in the viral population, as well as affecting cell tropism and types of disease that occur in infected cats. This review focuses on available information regarding genetic diversity, pathogenesis and diagnosis of FeLV as a result of the interaction between endogenous and exogenous viruses.", "journal": "New Zealand veterinary journal", "doi": "10.1080/00480169.2022.2131648", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "39765664", "author": "Gregor KM", "n_authors": 11, "title": "Fatal Feline Leukemia Virus-Associated Enteritis in a Wild Eurasian Lynx (Lynx lynx) in Germany.", "abstract": "The Eurasian lynx (", "journal": "Biology", "doi": "10.3390/biology13120997", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "39597560", "author": "Carvalho SF", "n_authors": 15, "title": "Feline Vector-Borne Diseases and Their Possible Association with Hematological Abnormalities in Cats from Midwestern Brazil.", "abstract": "Among the parasitic and infectious diseases affecting cats, those caused by vector-borne pathogens deserve attention due to their ability to cause nonspecific clinical signs and clinicopathological abnormalities. We studied the presence of ", "journal": "Microorganisms", "doi": "10.3390/microorganisms12112171", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "39591320", "author": "Yahiaoui F", "n_authors": 3, "title": "First Seroprevalence Study of Feline Leukemia and Feline Immunodeficiency Infections Among Cats in Algiers (Algeria) and Associated Risk Factors.", "abstract": "Feline leukemia and feline immunodeficiency virus infections are two widespread diseases that affect the health of domestic cats all over the world. In Algeria, despite the existence of a large population of cats, there are no published data regarding the epidemiological status of feline retroviruses. Therefore, the objective of the present study was to estimate the seroprevalence of FIV and FeLV infections in cats in Algiers and to assess the main factors associated with the infection. A cross-sectional study was conducted in which 71 cats were sampled from several private veterinary clinics, and their obtained sera were tested using an immunochromatography analysis (SNAP Duo FIV/FeLV Test; Virbac Laboratories, France). The seroprevalence was about 32.39% and 22.53% for FIV and FeLV, respectively. Overall, 11.26% were positive for both infections. The present study showed that FIV seropositivity was associated with a younger age and health status (", "journal": "Veterinary sciences", "doi": "10.3390/vetsci11110546", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "39540666", "author": "Schäfer I", "n_authors": 5, "title": "Serological and molecular detection of Toxoplasma gondii in cats in Europe with evaluation of associated risk factors for pathogen contact/infection.", "abstract": " A laboratory database was screened for  A total of 45,523 cats were included: 14,500 (31.9%) tested positive by direct and/or indirect detection methods for  Breed, age, sex, neuter status, seasonality and regionality significantly impacted serological results. Neuter status, seasonality and regionality significantly impacted the PCR results. Immunosuppression (FeLV/FIV) had a significant impact on serological results. PCR-positive cats shed oocysts and spread infection to other susceptible hosts, including humans. Surveillance is therefore recommended, taking into consideration the associated risk factors.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X241281223", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "39532595", "author": "Antonelo FA", "n_authors": 5, "title": "Cutaneous infection in an immunocompromised domestic cat caused by Setosphaeria turcica (Luttr.) Leonard & Suggs.", "abstract": "This is the first report of a cutaneous infection in an immunocompromised domestic cat caused by Setosphaeria turcica. The investigation encompasses an assessment of its virulence factors and susceptibility to antifungal drugs. The isolated strain originated from a domestic cat displaying cutaneous lesions that tested positive for feline leukemia virus (FeLV) infection. Identification procedures employed both microscopic and molecular techniques, with molecular identification relying on ITS DNA sequencing. Enzymatic assays targeting lipase, phospholipase, protease, and keratinase yielded negative results, suggesting the prevalence of alternative virulence mechanisms. Successful treatment of the infection was achieved with itraconazole, and susceptibility testing confirmed its sensitivity to azoles and polyene antifungal drugs.", "journal": "Revista Argentina de microbiologia", "doi": "10.1016/j.ram.2024.08.003", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "39474776", "author": "Erhan S", "n_authors": 9, "title": "Evaluation of the Diversities in the Inflammatory Responses in Cats With Bacterial and Viral Infections.", "abstract": "Understanding the nature of inflammatory responses in cats with bacterial and viral infections is essential for accurately managing the infection. This study aimed to investigate the diversities of inflammatory responses between bacterial and viral infections in cats to figure out their role in the pathophysiology of these infections. Seventy-five owned cats were included in the study. The evaluations were performed based on three groups: healthy control, bacterial infection group (those with bronchopneumonia and gastrointestinal tract and urinary tract infections) and viral infection group (21 with feline coronavirus [FCoV], 3 with feline leukaemia virus [FeLV] and 1 with feline calicivirus), each containing 25 individuals. Total and differential leukocyte counts, C-reactive protein (CRP), transforming growth factor beta (TGF-β), interleukin-6 (IL-6), tumour necrosis factor-alpha (TNF-α), interleukin-1 beta (IL-1β) and interleukin-10 (IL-10) concentrations were assessed in the blood samples collected from sick and healthy animals. No statistically significant difference was noted in serum TNF-α, IL-1β and IL-10 concentrations of the infected cats (p = 0.996, p = 0.160 and p = 0.930, respectively). Serum TGF-β concentration in the viral infection group was reduced compared to the healthy control (p = 0.001). In contrast, WBC count and IL-6 and CRP concentrations were increased in the cats with bronchopneumonia, gastrointestinal tract infections and urinary tract infections compared to the healthy control and viral infection groups (p = 0.001, p = 0.001 and p = 0.001, respectively). This study revealed significant differences between bacterial and viral infections regarding the fashion of inflammatory responses in cats, and the relevant data will undoubtedly contribute to the management and control of feline infectious diseases, rendering the development of novel therapeutic strategies.", "journal": "Veterinary medicine and science", "doi": "10.1002/vms3.70098", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "39459853", "author": "Miklík D", "n_authors": 6, "title": "Long Terminal Repeats of Gammaretroviruses Retain Stable Expression after Integration Retargeting.", "abstract": "Retroviruses integrate into the genomes of infected host cells to form proviruses, a genetic platform for stable viral gene expression. Epigenetic silencing can, however, hamper proviral transcriptional activity. As gammaretroviruses (γRVs) preferentially integrate into active promoter and enhancer sites, the high transcriptional activity of γRVs can be attributed to this integration preference. In addition, long terminal repeats (LTRs) of some γRVs were shown to act as potent promoters by themselves. Here, we investigate the capacity of different γRV LTRs to drive stable expression within a non-preferred epigenomic environment in the context of diverse retroviral vectors. We demonstrate that different γRV LTRs are either rapidly silenced or remain active for long periods of time with a predominantly active proviral population under normal and retargeted integration. As an alternative to the established γRV systems, the feline leukemia virus and koala retrovirus LTRs are able to drive stable, albeit intensity-diverse, transgene expression. Overall, we show that despite the occurrence of rapid silencing events, most γRV LTRs can drive stable expression outside of their preferred chromatin landscape after retrovirus integrations.", "journal": "Viruses", "doi": "10.3390/v16101518", "deposited_data": "Sim", "nuccore_ids": null, "bioproject_ids": "1119963", "sra_ids": "33118196"}, {"year": 2024, "pmid": "39332239", "author": "Arcidiaco S", "n_authors": 6, "title": "Vaccines efficacy against infection with circulating feline calicivirus after one single injection: Comparison of Leucofeligen™ FeLV/RCP and Purevax™ RCPFeLV vaccines.", "abstract": "Feline calicivirus (FCV) is a worldwide pathogen that affects the general health status of cats. The aim of this study was to assess the efficacy of the FCV component of two multivalent commercial vaccines after one injection. The cats assigned to the vaccinated groups received one subcutaneous injection of either the Leucofeligen™ FeLV/RCP (Virbac, France) vaccine or the Purevax™ RCPFeLV (Boehringer Ingelheim, Germany) vaccine. In the control group, the cats did not receive any vaccine. Three weeks after the vaccine injection, all the cats were inoculated with a heterologous calicivirus strain, isolated in the field. The clinical signs of calicivirosis and the viral shedding were assessed. The results demonstrated that Leucofeligen™ FeLV/RCP could protect kittens against FCV infection by reducing clinical signs and viral excretion from 3 weeks after the first injection of primary vaccination, whereas Purevax™ RCPFeLV couldn't offer the same level of protection in similar experimental conditions.", "journal": "Vaccine", "doi": "10.1016/j.vaccine.2024.126393", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "39318663", "author": "Vojtek B", "n_authors": 9, "title": "Incidence of Chlamydia spp., FIV, FeLV in Free-Roaming Cats in Slovakia.", "abstract": "Free-roaming cats represent a potential reservoir of infectious diseases. The most common co-infections of free-roaming cats include mixed viral, bacterial, fungal, yeast and parasitic infections. This study focuses on the occurrence of  The study involved 168 (113♀ and 55♂) free-roaming adult cats during the years 2021-2022. All cats belonged to Slovak citizens with permanent residence in the Slovak Republic. Blood samples and swabs (Invasive EUROTUBO The overall prevalence of  The observed prevalence of ", "journal": "Veterinary medicine (Auckland, N.Z.)", "doi": "10.2147/VMRR.S465088", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "39293106", "author": "Castillo-Aliaga C", "n_authors": 4, "title": "High prevalence and risk factors of feline leukemia virus infection in Chilean urban cats (Felis catus).", "abstract": "Feline Leukemia Virus is a retrovirus causing fatal disease in domestic cats. While FeLV has been controlled in many countries, it remains a major concern in Latin American countries. This study conducted an epidemiological survey of FeLV in 182 Chilean domestic cats using PCR to detect provirus infection. The results were analysed using Multivariate Logistic Regression to examine risk factors associated with FeLV detection. The FeLV prevalence was 54.95 %, and statistically significant associations (p < 0.05) were found for two protective factors and one risk factor. Cats from Concepcion city (95 %CI 0.08-0.56 %) and cats sampled in 2022 (95 %CI 0.1-0.06 %) had lower odds ratios for provirus positivity, whereas non-vaccinated cats (95 %CI 2.3-15.8 %) had an increased odds ratio. No other factors were statistically significant. The high FeLV prevalence is similar to other Latin American countries and the geographical differences highlighted in this study likely correspond to the socioeconomic status of the owners. This study highlights the need for improved FeLV control measures such as promoting FeLV vaccination, implementing health screening prior to adoption of new cats, and educating owners about FeLV to control its circulation.", "journal": "Research in veterinary science", "doi": "10.1016/j.rvsc.2024.105403", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "39267365", "author": "Fruchter B", "n_authors": 5, "title": "Clinicopathological findings in cats with haws syndrome.", "abstract": "Haws syndrome is a relatively common yet poorly understood disorder in cats. Ten cats with acute haws syndrome underwent ophthalmic and physical examinations, bloodwork, faecal analysis and pharmacological testing with 1% phenylephrine. The cats were discharged with broad-spectrum deworming (with or without metronidazole) as well as topical tetrahydrozoline. Cats were 17.6 ± 9.1 (2‒36) months old. All eyes had bilateral third eyelid protrusion and ptosis but no miosis or other ocular abnormalities. Diarrhoea was noted in four of 10 cats; otherwise, the cats were systemically healthy. A newly adopted kitten with haws syndrome and diarrhoea caused the condition to develop in the other three cats (from the same multicat household) within 4‒11 days. All cats tested negative for feline immunodeficiency virus and feline leukaemia virus. Serum amyloid A levels were elevated in two of eight tested cats. Tests for the presence of Giardia were positive in four of nine tested cats. Clinical signs transiently resolved within 20 minutes of the application of topical phenylephrine or tetrahydrozoline. Haws syndrome resolved in nine of the 10 cats within 37.7 ± 23 (12‒95) days but recurred in three of the nine cats 156‒182 days later. The small sample size limits the conclusions that can be drawn. Haws syndrome occurs in generally healthy cats, with or without diarrhoea, and is characterised by a sympathetic neuropathy causing bilateral third eyelid protrusion and ptosis. Clinical signs are possibly triggered by contagious gastrointestinal pathogen(s) that presumably affect(s) the gut microbiota and influence(s) the gut‒brain axis.", "journal": "The Veterinary record", "doi": "10.1002/vetr.4646", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "39191090", "author": "de Cristo TG", "n_authors": 8, "title": "Immunocytochemistry of bone marrow aspirates: a tool in the diagnosis of feline leukemia virus infection in cats.", "abstract": "Feline leukemia virus (FeLV) is a highly debilitating cat pathogen due to its ability to cause many pathological changes. Therefore, identifying the virus directly in bone marrow can be a highly relevant diagnostic tool even in the absence of viraemia. The aim of this study was to compare the diagnostic efficiency of immunocytochemistry (ICC) of bone marrow aspirates with enzyme-linked immunosorbent assay (ELISA) and polymerase chain reaction (PCR). Blood samples were collected from 188 cats and separated into aliquots of whole blood for nested PCR using the U3 LTR region and the gag gene of FeLV-A as reference and serum for detection of the p27 antigen by ELISA. Bone marrow samples from these cats were placed on silanized slides for anti-FeLV ICC using gp70 as primary antibody. A total of 28.2% of the cats tested for FeLV were positive in at least one of the tests, with 26.6% positive by PCR, 18.1% by ICC and 11.2% by ELISA. Cohen's kappa agreement test revealed moderate agreement between ELISA and PCR results and substantial agreement between ICC and ELISA and between ICC and PCR. The results indicated that ICC of bone marrow is an efficient novel diagnostic test for FeLV infection.", "journal": "Journal of comparative pathology", "doi": "10.1016/j.jcpa.2024.07.007", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "39160611", "author": "Carbonara M", "n_authors": 14, "title": "Feline leishmaniosis in the Mediterranean Basin: a multicenter study.", "abstract": "Cats are now recognized as competent hosts for Leishmania infantum and a blood source for sand fly vectors. Although canine leishmaniosis (CanL) is endemic in Mediterranean Basin countries, large-scale epidemiological studies are lacking for feline leishmaniosis (FeL). This study aimed to assess the prevalence of L. infantum infections, associated risk factors, clinical signs, and clinicopathological abnormalities in domestic cat populations from six Mediterranean Basin countries. From 2019 to 2022, blood and serum samples of cats (n = 2067) living in Italy (n = 300), Greece (n = 297), Portugal (n = 295), France (n = 231), Israel (n = 313), and Spain (n = 631) were collected along with animal data (i.e., age, sex, breed, housing conditions, and geographical origin), clinical signs, and laboratory blood test parameters. Cats were grouped according to their age as kittens (up to 1 year), young (older than 1 and younger than 7 years), mature (between 7 and 10 years), and senior (older than 10 years). Serum samples were tested for L. infantum by immunofluorescence antibody test (IFAT) and enzyme-linked immunosorbent assay (ELISA), and blood samples of seropositive cats were tested for L. infantum kinetoplast deoxyribonucleic acid (kDNA). Viral infection by feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) was molecularly addressed in all cats enrolled. Statistical analysis was performed to evaluate the association between the risk of L. infantum infection and independent variables, and among co-infection of L. infantum with FIV and/or FeLV, clinical signs, and clinicopathological abnormalities. Overall, 17.3% (358/2067) of cats scored positive for L. infantum by serological tests. Specifically, 24.7% were from Portugal, 23.2% from Greece, 16.6% from Israel, 15% from Spain, 13.3% from France, and 12.6% from Italy. Leishmania infantum DNA was detected in 15 seropositive animals. Housing condition and FIV infection proved to be risk factors for FeL. Leishmania seropositivity was significantly associated with weight loss, lymphadenomegaly, gingivostomatitis, and oral ulcers, as well as with reduced albumin and albumin/globulin ratio, increased total globulins and total proteins, leukocytosis, and thrombocytosis. This study provides, for the first time, a large-scale epidemiological survey on FeL and its clinical presentation, revealing that L. infantum circulates among domestic cats, especially shelter/free-roaming and FIV-infected animals, living in CanL endemic countries of the Mediterranean Basin.", "journal": "Parasites & vectors", "doi": "10.1186/s13071-024-06419-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "39153451", "author": "Pramono D", "n_authors": 10, "title": "Endogenous retrovirus ERV-DC8 highly integrated in domestic cat populations is a replication-competent provirus.", "abstract": "Endogenous retroviruses (ERVs) are remnants of ancient retroviral infections in vertebrate genomes and are inherited by offspring. ERVs can produce pathogenic viruses through gene mutations or recombination. ERVs in domestic cats (ERV-DCs) generate feline leukemia virus subgroup D (FeLV-D) through viral recombination. Herein, we characterized the locus ERV-DC8, on chromosome B1, as an infectious replication-competent provirus. ERV-DC8 infected several cell lines, including human cells. Transmission electron microscopy of ERV-DC8 identified the viral release as a Gammaretrovirus. ERV-DC8 was identified as the FeLV-D viral interference group, with feline copper transporter 1 as its viral receptor. Insertional polymorphism analysis showed high ERV-DC8 integration in domestic cats. This study highlights the role, pathogenicity, and evolutionary relationships between ERVs and their hosts.", "journal": "Biochemical and biophysical research communications", "doi": "10.1016/j.bbrc.2024.150521", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "39151280", "author": "Pandolfo GW", "n_authors": 9, "title": "Neoplastic and non-neoplastic diseases associated with feline leukaemia virus (FeLV) in cats in southern Brazil.", "abstract": "The objective of this study was to categorise diseases associated with FeLV infection in cats. A total of 154 cats were submitted to necropsy, histopathology exam and anti-FeLV immunohistochemistry (IHC), and 83 (50.9 %) were IHC FeLV-positive. The cats age means of 4.1 years, including 3.6 % kittens, 34.9 % junior, 37.4 % prime, 18.1 % mature, 2.4 % senior, 3.6 % unknown age. Neoplastic diseases were most prevalent with leukaemia and lymphoma being most predominant, followed by viral diseases, bacterial, trauma, degenerative, intoxications, parasitic, malformation and others. FeLV+ cats were 5.73 times more likely to be diagnosed with neoplasms than other diseases. The odds ratio (OR) of FeLV+ cats developing leukaemia (OR = 7.75) and lymphoma (OR = 6.75) was higher than other neoplasms. FeLV infection was more prevalent in the mixed breed, junior to prime, male, with neoplastic diseases, including leukaemia and lymphoma. Therefore, understanding the diseases associated with FeLV is of paramount importance in Brazil due to its high prevalence, and it may encourage the implementation of prophylactic measures to reduce its dissemination.", "journal": "Comparative immunology, microbiology and infectious diseases", "doi": "10.1016/j.cimid.2024.102228", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "39073984", "author": "Ferrer-Jorda E", "n_authors": 2, "title": "Description of outcome and adverse events in 21 cats with locally advanced nasal planum squamous cell carcinoma treated with electrochemotherapy.", "abstract": "Squamous cell carcinoma (SCC) is the most common tumour in the nasal planum of cats. Surgery has traditionally been the treatment of choice but might not be feasible in locally advanced scenarios. Electrochemotherapy (ECT) has shown good control in superficial tumours, but there is a lack of robust information about efficacy in locally advanced cases. The aim of this study was to assess the safety and efficacy of ECT in the treatment of locally advanced stage nasal planum SCC in cats. The clinical database of a veterinary referral hospital was searched retrospectively for cats diagnosed with a locally advanced nasal planum SCC (T In total, 21 cats were enrolled over a 4-year period. Nineteen cats achieved a complete response (CR) and two cats a partial response (PR) for an overall response rate of 100%. Cats achieving a CR had a median disease-free interval of 182 days (range 128-327) and those with a PR had a median progression-free survival of 156.5 days (range 122-191). The median time to progression was not reached. The overall survival was 453 days for a median follow-up of 341 days (range 191-989). Of the cats, 62% had grade 3 or 4 toxicities, but no deaths due to the treatment were documented. Only voltage was correlated with longer survival ( ECT appears to be an effective treatment for feline nasal planum SCC and could be considered a first-line therapy for locally advanced cases. Toxicities reported can be severe in the short term and these could be secondary to more invasive lesions and equipment used.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X241248043", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "39042044", "author": "Westman ME", "n_authors": 6, "title": "Antiviral therapy in cats progressively infected with feline leukaemia virus: lessons from a series of 18 consecutive cases from Australia.", "abstract": "It is doubtful that any of the treatments proposed for feline leukaemia virus (FeLV) infection are effective, despite the entity being described 60 years ago. Eighteen pet cats with progressive FeLV infections were recruited in Australia. One or more antiviral drugs were trialled in 16 cats, while two FeLV-infected cats were not handleable and served as untreated controls. Six cats were administered RetroMAD1™ only (0.5 mg/kg orally twice daily), a commercially available recombinant chimeric protein with proposed antiretroviral activity. Three cats were administered the integrase inhibitor raltegravir only (10-15 mg/kg orally twice daily), a drug used as a component of highly effective antiretroviral therapy for human immunodeficiency virus (HIV-1) infection. Three cats were administered RetroMAD1™ and raltegravir concurrently, and four cats were administered raltegravir and the reverse transcriptase inhibitor zidovudine (AZT, 5 mg/kg orally twice daily) concurrently. FeLV RNA and p27 antigen loads were measured at two timepoints (T1-2 months and T3-5 months) during therapy and compared to baseline (pretreatment) levels, to assess the response to therapy using linear modelling. The median survival time (MST) of the cats from commencement of FeLV treatment to death was also determined and compared between treatments. The MST for the 16 FeLV-positive cats which received antiviral therapy was 634 days, while the MST from FeLV diagnosis to death for the two untreated control cats was 780 days. In cats treated with RetroMAD1™, FeLV viral load decreased from T0 to T1-2 months (median viral load reduced from 1339 × 10 Results from this small case series do not provide convincing support for the use of RetroMAD1™, raltegravir or AZT, alone or in combination, for the treatment of cats progressively infected with FeLV. The changes observed were biologically insignificant. Age and FeLV viral load at diagnosis are useful prognostic markers, and p27 antigen concentration can be used to predict viral load. Larger field trials should be performed examining antiretroviral therapy in FeLV-positive cats with progressive infections, preferably using three or more drugs from at least two classes, as is standard with human antiretroviral therapy. Future studies would be easier in countries with a higher prevalence of FeLV infections than Australia.", "journal": "Australian veterinary journal", "doi": "10.1111/avj.13363", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "39019006", "author": "Bertino F", "n_authors": 39, "title": "Dysregulation of FLVCR1a-dependent mitochondrial calcium handling in neural progenitors causes congenital hydrocephalus.", "abstract": "Congenital hydrocephalus (CH), occurring in approximately 1/1,000 live births, represents an important clinical challenge due to the limited knowledge of underlying molecular mechanisms. The discovery of novel CH genes is thus essential to shed light on the intricate processes responsible for ventricular dilatation in CH. Here, we identify FLVCR1 (feline leukemia virus subgroup C receptor 1) as a gene responsible for a severe form of CH in humans and mice. Mechanistically, our data reveal that the full-length isoform encoded by the FLVCR1 gene, FLVCR1a, interacts with the IP3R3-VDAC complex located on mitochondria-associated membranes (MAMs) that controls mitochondrial calcium handling. Loss of Flvcr1a in mouse neural progenitor cells (NPCs) affects mitochondrial calcium levels and energy metabolism, leading to defective cortical neurogenesis and brain ventricle enlargement. These data point to defective NPCs calcium handling and metabolic activity as one of the pathogenetic mechanisms driving CH.", "journal": "Cell reports. Medicine", "doi": "10.1016/j.xcrm.2024.101647", "deposited_data": "Sim", "nuccore_ids": "924181778, 924181484, 124486924, 2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2461689713, 2461689617, 2461689596, 2288627507, 2288627503, 2288627369, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1907137381, 1907088640, 1907088637, 1907088636, 1907088633, 1907088629, 1907088626, 1907088624, 1907088621, 1907088619, 1907088616, 1907088612, 1907088609, 1720372664, 1720372661, 1720372660, 1519315556, 1399236859, 924181778, 924181484, 860610461, 860610408, 860610326, 860610190, 860610145, 860610141, 860610051, 860610049, 556503408, 124486924, 120587006, 120586998", "bioproject_ids": "913440", "sra_ids": "25840713, 25840712, 25840711, 25840710, 25840709, 25840708"}, {"year": 2024, "pmid": "38985775", "author": "Soltero-Rivera M", "n_authors": 5, "title": "Antimicrobial use practices in canine and feline patients with co-morbidities undergoing dental procedures in primary care practices in the US.", "abstract": "This study aimed to investigate how the presence of co-morbid conditions influenced antimicrobial usage as presumptive prophylaxis for suspected bacteremia in dogs and cats undergoing dental treatments at primary care veterinary clinics in the United States. In 2020, data was collected from 1076 veterinary clinics across 44 US states. A total of 681,541 general anesthesia dental procedures were conducted on 592,472 dogs and 89,069 cats. This revealed that systemic antimicrobials were administered in 8.8% of dog procedures and 7.8% of cat procedures in the absence of concurrent periodontal disease or extractions. Cefpodoxime, clindamycin, and amoxicillin-clavulanate were the most frequently used antimicrobials in dogs, while cefovecin, amoxicillin-clavulanate, and clindamycin topped the list for cats. Dogs with cardiovascular, hepato-renal, and endocrine co-morbidities, as well as those undergoing concurrent removal of cutaneous or subcutaneous neoplasia, displayed higher antimicrobial use. Similarly, cats with endocrine or hepato-renal disease, retroviral infection (i.e., feline leukemia virus (FeLV), feline immunodeficiency virus (FIV)), and concurrent removal of cutaneous or subcutaneous neoplasia exhibited increased antimicrobial use. Dogs with hepato-renal abnormalities had longer treatment durations compared to those without (10.1 vs. 9.6 days). Conversely, cats with concurrent removal of cutaneous or subcutaneous neoplasia had shorter durations of treatment as compared to those that did not have this procedure performed (8.4 vs 9.2 days). The findings of this study underscore the necessity for further research and collaboration within the veterinary community to develop evidence-based guidelines, promoting responsible antimicrobial use, and advancing the field of veterinary dentistry for enhanced patient outcomes.", "journal": "PloS one", "doi": "10.1371/journal.pone.0305533", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38958295", "author": "Barbosa WZ", "n_authors": 5, "title": "Feline immunodeficiency virus, feline leukemia virus and Leishmania spp. prevalence in cats from shelters in Mato Grosso do Sul, Brazil.", "abstract": "Diseases such as those caused by feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) represent health problems for cats. Feline leishmaniasis (FL) has been reported in several cities across the country. The objective was to carry out a clinical-epidemiological and laboratory study of FIV, FeLV and FL in cats from shelters in Dourados, Mato Grosso do Sul, Brazil. Blood samples and swabs from the conjunctival and nasal mucosa were obtained from 75 cats, from four animal shelters. Serology for FIV and FeLV was performed. For Leishmania, polymerase chain reaction (PCR) was performed on blood, conjunctiva and nasal mucosa. In the immunochromatographic serological test, seven cats tested positive for FIV and none for FeLV. No samples was positive in PCR for Leishmania. The study showed that despite the presence of human and canine leishmaniasis in the studied region, Leishmania spp. were absent in the cats studied. To avoid an increase in contagion in shelters, it is essential isolate cats with FIV.", "journal": "Revista brasileira de parasitologia veterinaria = Brazilian journal of veterinary parasitology : Orgao Oficial do Colegio Brasileiro de Parasitologia Veterinaria", "doi": "10.1590/S1984-29612024035", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38932278", "author": "Ortiz R", "n_authors": 16, "title": "Production and Immunogenicity of FeLV Gag-Based VLPs Exposing a Stabilized FeLV Envelope Glycoprotein.", "abstract": "The envelope glycoprotein (Env) of retroviruses, such as the Feline leukemia virus (FeLV), is the main target of neutralizing humoral response, and therefore, a promising vaccine candidate, despite its reported poor immunogenicity. The incorporation of mutations that stabilize analogous proteins from other viruses in their prefusion conformation (e.g., HIV Env, SARS-CoV-2 S, or RSV F glycoproteins) has improved their capability to induce neutralizing protective immune responses. Therefore, we have stabilized the FeLV Env protein following a strategy based on the incorporation of a disulfide bond and an Ile/Pro mutation (SOSIP) previously used to generate soluble HIV Env trimers. We have characterized this SOSIP-FeLV Env in its soluble form and as a transmembrane protein present at high density on the surface of FeLV Gag-based VLPs. Furthermore, we have tested its immunogenicity in DNA-immunization assays in C57BL/6 mice. Low anti-FeLV Env responses were detected in SOSIP-FeLV soluble protein-immunized animals; however, unexpectedly no responses were detected in the animals immunized with SOSIP-FeLV Gag-based VLPs. In contrast, high humoral response against FeLV Gag was observed in the animals immunized with control Gag VLPs lacking SOSIP-FeLV Env, while this response was significantly impaired when the VLPs incorporated SOSIP-FeLV Env. Our data suggest that FeLV Env can be stabilized as a soluble protein and can be expressed in high-density VLPs. However, when formulated as a DNA vaccine, SOSIP-FeLV Env remains poorly immunogenic, a limitation that must be overcome to develop an effective FeLV vaccine.", "journal": "Viruses", "doi": "10.3390/v16060987", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38911097", "author": "He M", "n_authors": 7, "title": "One-step triplex TaqMan quantitative reverse transcription polymerase chain reaction for the detection of feline coronavirus, feline panleukopenia virus, and feline leukemia virus.", "abstract": "Feline coronavirus (FCoV), feline panleukopenia virus (FPV), and feline leukemia virus (FeLV) are prevalent throughout China and significantly threaten cat health. These viruses cause similar manifestations and pathological damage. Rapid and accurate diagnosis depends on detection in the laboratory. This study aimed to establish a reliable and rapid method for accurate detection of FCoV, FPV, and FeLV so that a definite diagnosis can be made and effective measures can be taken to prevent and control viral infection. We designed three pairs of specific primers and probes for the detection of FCoV 5' untranslated region, FPV viral protein 2, and FeLV pol genes. Recombinant plasmid constructs were generated for use as standard plasmid constructs. Optimal reaction conditions, including primer and probe concentrations, reaction cycles, and annealing temperatures, were obtained on the basis of optimization tests. One-step triplex real-time reverse transcription-quantitative polymerase chain reaction (RT-qPCR) was successfully established to simultaneously detect FCoV, FPV, and FeLV. The specificity, sensitivity, and repeatability of the assay were analyzed, and its applicability was validated by testing 1175 clinical samples. One-step triplex RT-qPCR had a high degree of specificity only for the detection of FCoV, FPV, and FeLV; it had high sensitivity with limits of detection of 139.904, 143.099, and 152.079 copies/reaction for p-FCoV, p-FPV, and p-FeLV standard plasmid constructs, respectively, and it had reliable repeatability with 0.06%-0.87% intra-assay coefficients of variations. A total of 1175 clinical samples were examined for FCoV, FPV, and FeLV using triplex RT-qPCR, and the FCoV, FPV, and FeLV positivity rates were 18.47%, 19.91%, and 47.57%, respectively. The clinical sensitivity and specificity of one-step triplex RT-qPCR were 93.07% and 97.99%, respectively. We developed a rapid and reliable one-step triplex RT-qPCR method for the detection of FCoV, FPV, and FeLV, which could be used as a diagnostic tool for clinical monitoring and diagnosis.", "journal": "Veterinary world", "doi": "10.14202/vetworld.2024.946-955", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38891700", "author": "Almendros A", "n_authors": 6, "title": "Description and Characterization of Different Types of Lymphoma in Cats in Hong Kong.", "abstract": "This study aimed to characterize and describe the different lymphoma types and anatomical forms in cats in Hong Kong. The clinical and histopathological data of cats diagnosed with lymphoma by cytology and/or histopathology were collected from a large diagnostic laboratory in Hong Kong. In total, 444 cats were diagnosed with lymphoma over four years (2019-2022). Like other countries where there is a low prevalence of FeLV infection, the predominant form of lymphoma was gastrointestinal (abdominal). Nasopharyngeal and peripheral nodal lymphoma were the second and third most common forms of lymphoma. The large cell/high-grade lymphoma type was much more common than the low-grade/small cell lymphoma in the study population. Domestic short hair was the most commonly affected breed in our study (", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani14111654", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38803041", "author": "Roels E", "n_authors": 5, "title": "Prevalence of Hemoplasma spp. positivity in potential feline blood donors and study of the association with selected clinical variables.", "abstract": "Hemotropic mycoplasmas, hemoplasmas, are epi-erythrocytic parasitic bacteria that can be transmitted through blood transfusion. To study the prevalence of hemoplasma infection of potential feline blood donors and investigate the association between Hemoplasma spp. quantitative polymerase chain reaction (qPCR) positivity in blood units and selected variables. Seven thousand five hundred seventy-three blood units from 4121 privately-owned potential donor cats. Retrospective observational cross-sectional study. The Banco Sangue Animal (BSA)-Animal Blood Bank medical database was reviewed for all feline donations performed in 2022 in Portugal, Spain, and Belgium. Baseline characteristics and results of blood-borne pathogens screening tests were extracted from the medical records. Two hundred twelve of 4034 Portuguese donor cats and 2 of 70 Spanish donor cats tested positive for Hemoplasma spp. qPCR in 2022 leading to an overall estimated prevalence of 5.2% (95% CI: 4.5%-5.9%) in potential blood donors. Using multivariable generalized estimation equation models, Hemoplasma spp. qPCR was more often positive among blood units issued from male cats (OR = 1.9, 95% CI: 1.4-2.6, P < .0001), units positive for FeLV (OR = 2.8, 95% CI: 1.4-5.6, P = .0023), and units collected in winter months (OR = 2.5, 95% CI: 1.7-3.6, P < .0001). This study underscores the importance of Hemoplasma spp. and other relevant blood-borne pathogens screening at every donation. Implementing stringent screening protocols is crucial to mitigate the risk of hemoplasma transmission via blood transfusions, thereby safeguarding the health and welfare of cats receiving transfusions.", "journal": "Journal of veterinary internal medicine", "doi": "10.1111/jvim.17119", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38780525", "author": "Walter-Nuno AB", "n_authors": 6, "title": "Export of heme by the feline leukemia virus C receptor regulates mitochondrial biogenesis and redox balance in the hematophagous insect Rhodnius prolixus.", "abstract": "Heme is a prosthetic group of proteins involved in vital physiological processes. It participates, for example, in redox reactions crucial for cell metabolism due to the variable oxidation state of its central iron atom. However, excessive heme can be cytotoxic due to its prooxidant properties. Therefore, the control of intracellular heme levels ensures the survival of organisms, especially those that deal with high concentrations of heme during their lives, such as hematophagous insects. The export of heme initially attributed to the feline leukemia virus C receptor (FLVCR) has recently been called into question, following the discovery of choline uptake by the same receptor in mammals. Here, we found that RpFLVCR is a heme exporter in the midgut of the hematophagous insect Rhodnius prolixus, a vector for Chagas disease. Silencing RpFLVCR decreased hemolymphatic heme levels and increased the levels of intracellular dicysteinyl-biliverdin, indicating heme retention inside midgut cells. FLVCR silencing led to increased expression of heme oxygenase (HO), ferritin, and mitoferrin mRNAs while downregulating the iron importers Malvolio 1 and 2. In contrast, HO gene silencing increased FLVCR and Malvolio expression and downregulated ferritin, revealing crosstalk between heme degradation/export and iron transport/storage pathways. Furthermore, RpFLVCR silencing strongly increased oxidant production and lipid peroxidation, reduced cytochrome c oxidase activity, and activated mitochondrial biogenesis, effects not observed in RpHO-silenced insects. These data support FLVCR function as a heme exporter, playing a pivotal role in heme/iron metabolism and maintenance of redox balance, especially in an organism adapted to face extremely high concentrations of heme.", "journal": "FASEB journal : official publication of the Federation of American Societies for Experimental Biology", "doi": "10.1096/fj.202301671RR", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38778100", "author": "Ri K", "n_authors": 17, "title": "Molecular mechanism of choline and ethanolamine transport in humans.", "abstract": "Human feline leukaemia virus subgroup C receptor-related proteins 1 and 2 (FLVCR1 and FLVCR2) are members of the major facilitator superfamily", "journal": "Nature", "doi": "10.1038/s41586-024-07444-7", "deposited_data": "Sim", "nuccore_ids": "1675021395, 1519316194, 2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1675021395, 1519316194, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38754624", "author": "Rossi A", "n_authors": 5, "title": "Evaluation of leukocyte ratios as survival prognostic markers in feline retrovirus infections.", "abstract": "The utility of neutrophil-lymphocyte ratio (NLR), monocyte-lymphocyte ratio (MLR), and platelet-lymphocyte ratio (PLR) as prognostic markers in Feline Leukemia Virus (FeLV) and Feline Immunodeficiency Virus (FIV) infections has not yet been investigated. The aim of this study was to investigate these leukocyte ratios in retrovirus-positive cats and to evaluate their prognostic value for survival. This retrospective case-control study included 142 cats, 75 FIV-Antibodies (Ab)-positive, 52 FeLV-Antigen (Ag)-positive, and 15 FIV-Ab+FeLV-Ag-positive, and a control population of 142 retrovirus-negative age-, sex-, and lifestyle-matched cats. Signalment, complete blood count at the time of serological testing, and outcome were recorded. Leukocyte ratios were compared within the same case-control population, among the three retrovirus-seropositive populations, and were related to survival time. No significant difference was found in NLR, MLR, or PLR between FIV-Ab-positive and FIV-Ab+FeLV-Ag-positive cats and their cross-matched controls. In the FeLV-Ag-positive population, MLR was significantly lower than in the control population (0.05 and 0.14, respectively, P=0.0008). No ratio discriminated among the three infectious states. No ratio was significantly different between survivors and non-survivors in the population of FIV-Ab-positive cats. MLR at diagnosis was significantly higher in FeLV-Ag-positive cats that died 1-3 years after diagnosis than in FeLV-Ag-positive cats still alive at 3 years (P=0.0284). None of the three ratios could predict retroviruses-positive cats that would survive to the end of the study. Overall the results indicate that NLR, MLR, and PLR are not significantly different among retrovirus statuses evaluated and had a very limited prognostic value for the survival time in retrovirus-positive cats.", "journal": "Veterinary journal (London, England : 1997)", "doi": "10.1016/j.tvjl.2024.106128", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38694738", "author": "Kimura S", "n_authors": 4, "title": "Recognizing uterine torsion as a differential diagnosis in pregnant cats with severe anemia to provide appropriate and timely care in the absence of a definitive presurgical diagnosis.", "abstract": "A pregnant female domestic longhair cat ~8 mo of age was referred to the Western College of Veterinary Medicine (Saskatoon, Saskatchewan) for a diagnostic evaluation of severe anemia (PCV: 10.8%) after a 2-day period of lethargy. A CBC, serum biochemistry profile, FeLV/FIV testing, and abdominal radiographs were completed and did not determine a cause for the anemia. Abdominal ultrasonography identified 1 viable and 6 nonviable and fetuses, anechoic fluid in the uterus, and a mild volume of peritoneal effusion. A whole-blood transfusion and C-section with ovariohysterectomy were performed even though a definitive presurgical diagnosis for the anemia had not yet been established. Exploratory surgery revealed a left uterine horn torsion with a necrotic base, severe congestion, and 7 nonviable fetuses. Following surgery, the queen made a full clinical recovery. Key clinical message: Uterine torsion can be easily overlooked as a cause of severe anemia due to the relative infrequency of this condition in cats and the low sensitivity of ultrasonography to provide a definitive presurgical diagnosis. Client communication must emphasize the need for a prompt surgical intervention to establish the diagnosis and to save the cat, despite poor rates of neonatal survival. Once the animal is stabilized after surgery, further diagnostic tests and procedures are indicated if the cause of anemia has not yet been identified.", "journal": "The Canadian veterinary journal = La revue veterinaire canadienne", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38675954", "author": "Giselbrecht J", "n_authors": 12, "title": "Evaluation of a Revised Point-of-Care Test for the Detection of Feline Leukaemia p27 Antigen and Anti-p15E Antibodies in Cats.", "abstract": "The first point-of-care (PoC) test (v-RetroFel", "journal": "Viruses", "doi": "10.3390/v16040614", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38647460", "author": "Brown T", "n_authors": 5, "title": "Determination of the reference interval for urine kidney injury molecule-1 in 50 healthy cats.", "abstract": "The aim of the present study was to establish a reference interval (RI) for urine kidney injury molecule-1 (KIM-1) in healthy cats. History, physical examination, blood pressure, and feline immunodeficiency virus and feline leukemia virus serology status were determined. A complete blood cell count, serum biochemical profile, urinalysis and kidney ultrasound were performed, and N-terminal pro-brain natriuretic peptide, total thyroxine (TT4) and urine KIM-1 were measured. An RI was calculated and the effect of age, sex, body condition score (BCS), blood pressure, symmetric dimethylarginine (SDMA), serum creatinine concentration (SCr), phosphorus, TT4, urine specific gravity (USG) and mid-sagittal kidney length on urine KIM-1 was evaluated using a general linear model. Of 69 recruited cats, 50 met the inclusion criteria. There were 35 male cats and 15 female cats, with a median age of 4.3 years (range 1.0-12.3), median weight of 5.11 kg (range 2.52-8.45) and median BCS of 6/9 (range 3-8). The median serum concentrations were SDMA 11.0 µg/dl (range 2-14), SCr 88.5 µmol/l (range 47-136), phosphorus 1.41 mmol/l (range 0.8-2.2) and TT4 32.0 nmol/l (range 17-51). Median USG was 1.057 (range 1.035-1.076), mid-sagittal left kidney length was 3.50 cm (range 2.94-4.45) and mid-sagittal right kidney length was 3.70 cm (range 3.06-4.55). The derived RI for urine KIM-1 was 0.02-0.68. USG was a significant ( Urine concentration was significantly correlated with urine KIM-1, which will be an important consideration when interpreting findings in cats with potential kidney injury.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X241238923", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38644457", "author": "Gallina L", "n_authors": 11, "title": "Molecular investigation and genetic characterization of feline leukemia virus (FeLV) in cats referred to a veterinary teaching hospital in Northern Italy.", "abstract": "Feline leukemia virus (FeLV) is responsible for feline leukemia syndrome in domestic cats. The prevention and control of disease caused by FeLV are primarily based on vaccination and identification and isolation of infected subjects. Antigen diagnostic methods, which are the most widely used in clinical practices, can be associated to molecular tests to characterize the FeLV detected. In this study, a quantitative SYBR Green Real-Time PCR (qPCR) assay was used to detect FeLV proviral DNA in blood samples from antigen positive cats referred to a veterinary teaching hospital in Northern Italy in 2018-2021. To genetically characterize the identified viruses, a portion of the viral envelope (env) gene was amplified using six different end-point PCRs and sequenced. Twenty-two of 26 (84.6%) cats included in the study tested positive by qPCR assay. This suggests a high performance of the qPCR adopted but further studies are required to investigate the cause of discordant results between the antigen test and qPCR in four cats. From env gene analysis, 15/22 qPCR-positive cats were infected by FeLV subtype A and 5/15 shown coinfection with subtype B.", "journal": "Veterinary research communications", "doi": "10.1007/s11259-024-10380-6", "deposited_data": "Sim", "nuccore_ids": "2756348275, 2756348273, 2756348271, 2756348269, 2756348267, 2756348265, 2756348263, 2756348261, 2756348259, 2756348257, 2756348255, 2756348253, 2756348251, 2756348249, 2756348247, 2756348245, 2756348243, 2756348241, 2756348239, 2756348237, 2756348235, 2756348233, 2756348231, 2756348229, 2756348227, 2756348225, 2756348223, 2756348221, 2756348219, 2756348217", "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38613921", "author": "Nascimento LFJ", "n_authors": 14, "title": "Feline leishmaniasis in an animal shelter in northeastern Brazil: Clinical aspects, coinfections, molecular detection, and serological study of a new recombinant protein.", "abstract": "Infection and clinical cases of leishmaniasis caused by Leishmania infantum in cats have been increasingly reported in several countries, including Brazil. In this study, we used an enzyme-linked immunosorbent assay (ELISA) and an immunochromatographic test (ICT) based on a recombinant antigen (rKDDR-plus) to detect anti-Leishmania antibodies in cats from an animal shelter in northeastern Brazil. We compared the results with an ELISA using L. infantum crude antigen (ELISA-CA). We also investigated the presence of Leishmania DNA in blood or ocular conjunctival samples as well as the association between Leishmania PCR positivity and serological positivity to feline immunodeficiency virus (FIV), feline leukemia virus (FeLV) and Toxoplasma gondii. Concerning serological assays, a higher positivity was detected using the ICT-rKDDR-plus (7.5%; 7/93) as compared to ELISA-rKDDR-plus (5.4%; 5/93) and ELISA-CA (4.3%; 4/93). Upon PCR testing, 52.7% (49/93) of the ocular conjunctival swabs and 48.3% (44/91) of the blood samples were positive. Together, PCR and serological testing revealed overall positivities of 73.1% (68/93) and 12.9% (12/93), respectively. Among PCR-positive samples, 45.5% (31/68) showed co-infection with FIV, 17.6% (12/68) with FeLV, and 82.3% (56/68) with T. gondii. More than half of the PCR-positive cats showed at least one clinical sign suggestive of leishmaniasis (58.8%; 40/68) and dermatological signs were the most frequent ones (45.5%; 31/68). Both tests employing the recombinant antigen rKDDR-plus (i.e., ICT-rKDDR-plus and ELISA-rKDDR-plus) detected more positive cats than the ELISA-CA but presented low overall accuracy. PCR testing using either blood or ocular conjunctival samples detected much more positive cats than serological tests.", "journal": "Research in veterinary science", "doi": "10.1016/j.rvsc.2024.105256", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38612290", "author": "Diesel LP", "n_authors": 10, "title": "Epidemiological Insights into Feline Leukemia Virus Infections in an Urban Cat (Felis catus) Population from Brazil.", "abstract": "Feline leukemia virus (FeLV) is a retrovirus distributed worldwide in domestic cats and with different outcomes (progressive, regressive, abortive, focal). The present study reports an epidemiological survey of FeLV frequency and the evaluation of some risk factors and the two main disease outcomes (progressive and regressive) in an urban cat population from Brazil. A total of 366 cats with sociodemographic information and p27 FeLV antigen test performed were included in the study. FeLV DNA (provirus) in the blood samples of all cats was detected via real-time polymerase chain reaction (qPCR). Plasma samples from 109 FeLV-positive and FeLV-negative cats were also submitted to reverse transcription (RT-qPCR) to determine the FeLV viral load. The results demonstrated that 112 (30.6%) cats were positive through the p27 antigen and/or qPCR. A risk factor analysis demonstrated that cats without vaccination against FeLV (OR 9.9, ", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani14071051", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38581583", "author": "Fiorito V", "n_authors": 2, "title": "Unearthing FLVCR1a: tracing the path to a vital cellular transporter.", "abstract": "The Feline Leukemia Virus Subgroup C Receptor 1a (FLVCR1a) is a member of the SLC49 Major Facilitator Superfamily of transporters. Initially recognized as the receptor for the retrovirus responsible of pure red cell aplasia in cats, nearly two decades since its discovery, FLVCR1a remains a puzzling transporter, with ongoing discussions regarding what it transports and how its expression is regulated. Nonetheless, despite this, the substantial body of evidence accumulated over the years has provided insights into several critical processes in which this transporter plays a complex role, and the health implications stemming from its malfunction. The present review intends to offer a comprehensive overview and a critical analysis of the existing literature on FLVCR1a, with the goal of emphasising the vital importance of this transporter for the organism and elucidating the interconnections among the various functions attributed to this transporter.", "journal": "Cellular and molecular life sciences : CMLS", "doi": "10.1007/s00018-024-05205-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38543760", "author": "Meli ML", "n_authors": 4, "title": "Prospective Investigation of Feline Leukemia Virus Infection in Stray Cats Subjected to a Trap-Neuter-Return Program in Switzerland.", "abstract": "Feline leukemia virus (FeLV) remains a serious concern in some countries despite advances in diagnostics and vaccines. FeLV-infected cats often have reduced lifespans due to FeLV-associated diseases. The infection is transmitted through social interactions. While Northern European countries have reported a decrease in FeLV among pet cats, Switzerland's rates remain stagnant at 2.7% (2016/17: 95% CI 1.4-5.2%). Research on FeLV in Swiss stray cats has been lacking, even though these animals could serve as a virus reservoir. Sampling stray cats that do not receive regular veterinary care can be challenging. Collaboration with the Swiss Network for Animal Protection (NetAP) allowed for the prospective collection of saliva samples from 1711 stray cats during a trap-neuter-return program from 2019 to 2023. These samples were tested for FeLV RNA using RT-qPCR as a measure for antigenemia. Viral RNA was detected in 4.0% (95% CI 3.1-5.0%) of the samples, with 7.7% (95% CI 4.9-11.3%) in sick cats and 3.3% (95% CI 2.4-4.4%) in healthy ones. We identified three geographically independent hotspots with alarmingly high FeLV infection rates in stray cats (up to 70%). Overall, including the previous data of privately owned cats, FeLV-positive cats were scattered throughout Switzerland in 24/26 cantons. Our findings underscore welfare concerns for FeLV infections among stray cats lacking veterinary attention, highlighting the potential risk of infection to other free-roaming cats, including those privately owned. This emphasizes the critical significance of vaccinating all cats with outdoor access against FeLV and developing programs to protect cats from FeLV infections.", "journal": "Viruses", "doi": "10.3390/v16030394", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38533976", "author": "Zhou Q", "n_authors": 2, "title": "Shared Genetic Features of Psoriasis and Myocardial Infarction: Insights From a Weighted Gene Coexpression Network Analysis.", "abstract": "Increasing evidence suggests a higher propensity for acute myocardial infarction (MI) in patients with psoriasis. However, the shared mechanisms underlying this comorbidity in these patients remain unclear. This study aimed to explore the shared genetic features of psoriasis and MI and to identify potential biomarkers indicating their coexistence. Data sets obtained from the gene expression omnibus were examined using a weighted gene coexpression network analysis approach. Hub genes were identified using coexpression modules and validated in other data sets and through in vitro cellular experiments. Bioinformatics tools, including the Human microRNA Disease Database, StarBase, and miRNet databases, were used to construct a ceRNA network and predict potential regulatory mechanisms. By applying weighted gene coexpression network analysis, we identified 2 distinct modules that were significant for both MI and psoriasis. Inflammatory and immune pathways were highlighted by gene ontology enrichment analysis of the overlapping genes. Three pivotal genes-Src homology and collagen 1, disruptor of telomeric silencing 1-like, and feline leukemia virus subgroup C cellular receptor family member 2-were identified as potential biomarkers. We constructed a ceRNA network that suggested the upstream regulatory roles of these genes in the coexistence of psoriasis and MI. As potential therapeutic targets, Src homology and collagen 1, feline leukemia virus subgroup C cellular receptor family member 2, and disruptor of telomeric silencing 1-like provide novel insights into the shared genetic features between psoriasis and MI. This study paves the way for future studies focusing on the prevention of MI in patients with psoriasis.", "journal": "Journal of the American Heart Association", "doi": "10.1161/JAHA.123.033893", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38479335", "author": "Slaviero M", "n_authors": 9, "title": "Pathological findings and patterns of feline infectious peritonitis in the respiratory tract of cats.", "abstract": "Feline infectious peritonitis (FIP) is an important cause of death in cats. Thoracic manifestations are less common than abdominal manifestations, and FIP-associated respiratory disease is poorly documented. This study aimed to investigate pathological findings in the respiratory tract of cats with FIP and the occurrence and distribution of feline coronavirus antigen in the respiratory tract using immunohistochemistry. A retrospective study was carried out on 112 cats with FIP, of which 66 had inflammatory histological lesions in the respiratory tract (58.9%) and were included in this study. Three major gross patterns were defined: marked fibrin deposition in the thoracic cavity with lung atelectasis; marked fibrin deposition in the thoracic cavity with lung pyogranulomas; and lung pyogranulomas without thoracic effusion. Histological analysis revealed primary lesions in the visceral pleura and lung parenchyma at a similar frequency, with multifocal to diffuse presentations. Marked lesions were commonly observed. Five major histological patterns were defined: pleuritis; pleuritis and vasculitis/perivascular injury in the lung parenchyma; pleuritis and pneumonia; perivascular injury in the parenchyma without pleuritis; and pneumonia without pleuritis. In the pleura and pulmonary parenchyma, FIP virus antigen was detected in perivascular and peribronchial macrophages and in macrophages within bronchial-associated lymphoid tissue and foci of necrosis and inflammation in the pleura and lung parenchyma. Co-infections with retroviruses were detected in 47 cats (71.2%), mainly with feline leukemia virus (62.2%). Although FIP is a systemic disease, some cats developed significant lesions in the thoracic cavity, including involvement of the upper respiratory tract and presenting respiratory signs, without other classic signs of FIP. This work advances our knowledge of FIP in the respiratory system, helping veterinarians to recognize the various presentations of this disease.", "journal": "Journal of comparative pathology", "doi": "10.1016/j.jcpa.2024.02.001", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38461703", "author": "Bezerra JAB", "n_authors": 9, "title": "Epidemiological and clinicopathological findings of feline immunodeficiency virus and feline leukemia virus infections in domestic cats from the Brazilian semiarid region.", "abstract": "Feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) are retroviruses of great importance for domestic cats with a worldwide distribution. A retrospective study was conducted to determine the epidemiological and clinicopathological aspects of the infection by FIV and FeLV in cats from the Brazilian semiarid region. Cats treated between 2011 and 2021 at the teaching veterinary hospital of the Federal Rural University of the Semi-Arid Region that were submitted to a point-of-care (POC) test to detect anti-FIV IgG antibodies and FeLV antigen were enrolled in the study. Overall, 454 cats were selected, of which 30.2% [95% CI = 26.0% - 34.3%] were FIV-positive, 1.1% [95% CI = 0.9% - 1.2%] were FeLV-positive, and 0.7% [95% CI = 0.1% - 1.3%] were coinfected by both retroviruses. No statistical association was found between the studied retroviruses (P = 0.144). Multivariable analysis detected significant associations between FIV infection and male sex [OR = 5.7, 95% CI = 3.0-10.7, P < 0.0001), age between 19 and 78 months [OR = 5.2, 95% CI = 2.2-12.1, P < 0.0001], age greater than 78 months [OR = 12.8, 95% CI = 5.1-31.9, P < 0.0001], crossbreed [OR = 4.1, 95% CI = 1.2-13.4, P = 0.021], the presence of oral disease [OR = 2.1, 95% CI = 1.3-3.4, P = 0.004], reduced red blood cell (RBC) count [OR = 3.7, 95% CI = 1.9-7.2, P < 0.0001], and an albumin:globulin (A:G) ratio lower than 0.6 [OR = 3.4, 95% CI = 1.6-7.1, P = 0.001]. No statistical analyses were performed for FeLV infection due to the low number of positive animals. In the quantitative analyses of hematological parameters, FIV-positive cats presented lower values for RBC, hemoglobin, hematocrit, lymphocytes, and platelets compared to the negative animals. In the biochemical profile, cats infected with FIV showed higher creatinine, urea, total protein, and globulin values, while lower values for albumin and A:G ratio were observed (P < 0.05). The findings of this study characterized the prevalence, clinicopathological findings, and risk factors associated with FIV and FeLV in cats from the Brazilian semiarid region. They may help support veterinary practitioners in diagnosing feline retroviruses. The FIV prevalence observed is among the highest reported in Brazil, demonstrating the need for prevention and control strategies for this retrovirus.", "journal": "Preventive veterinary medicine", "doi": "10.1016/j.prevetmed.2024.106167", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38443503", "author": "Nájera F", "n_authors": 18, "title": "Long-term surveillance of the feline leukemia virus in the endangered Iberian lynx (Lynx pardinus) in Andalusia, Spain (2008-2021).", "abstract": "Feline leukemia virus (FeLV) infection is considered one of the most serious disease threats for the endangered Iberian lynx (Lynx pardinus) Over 14 years (2008-2021), we investigated FeLV infection using point-of-care antigen test and quantitative real-time TaqMan qPCR for provirus detection in blood and tissues in lynxes from Andalusia (Southern Spain). A total of 776 samples from 586 individuals were included in this study. The overall prevalence for FeLV antigen in blood/serum samples was 1.4% (5/360) (95% CI: 0.2-2.6), FeLV proviral DNA prevalence in blood samples was 6.2% (31/503) (95% CI: 4.1-8.6), and FeLV proviral DNA in tissues samples was 10.2% (34/333) (95% CI: 7-13.5). From a subset of 129 longitudinally sampled individuals, 9.3% (12/129) PCR-converted during the study period. Our results suggest that FeLV infection in the Andalusian population is enzootic, with circulation of the virus at low levels in almost all the sampling years. Moreover, since only one viremic individual succumbed to the infection, this study suggests that lynxes may therefore control the infection decreasing the possibility of developing a more aggressive outcome. Although our results indicate that the FeLV infection in the Iberian lynx from Andalusia tends to stay within the regressive stage, continuous FeLV surveillance is paramount to predict potential outbreaks and ensure the survival of this population.", "journal": "Scientific reports", "doi": "10.1038/s41598-024-55847-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38440982", "author": "Pramono D", "n_authors": 9, "title": "FeLIX is a restriction factor for mammalian retrovirus infection.", "abstract": "Endogenous retroviruses (ERVs) are remnants of ancestral viral infections. Feline leukemia virus (FeLV) is an exogenous and endogenous retrovirus in domestic cats. It is classified into several subgroups (A, B, C, D, E, and T) based on viral receptor interference properties or receptor usage. ERV-derived molecules benefit animals, conferring resistance to infectious diseases. However, the soluble protein encoded by the defective envelope (", "journal": "Journal of virology", "doi": "10.1128/jvi.01771-23", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38412099", "author": "Mistretta M", "n_authors": 20, "title": "Flvcr1a deficiency promotes heme-based energy metabolism dysfunction in skeletal muscle.", "abstract": "The definition of cell metabolic profile is essential to ensure skeletal muscle fiber heterogeneity and to achieve a proper equilibrium between the self-renewal and commitment of satellite stem cells. Heme sustains several biological functions, including processes profoundly implicated with cell metabolism. The skeletal muscle is a significant heme-producing body compartment, but the consequences of impaired heme homeostasis on this tissue have been poorly investigated. Here, we generate a skeletal-muscle-specific feline leukemia virus subgroup C receptor 1a (FLVCR1a) knockout mouse model and show that, by sustaining heme synthesis, FLVCR1a contributes to determine the energy phenotype in skeletal muscle cells and to modulate satellite cell differentiation and muscle regeneration.", "journal": "Cell reports", "doi": "10.1016/j.celrep.2024.113854", "deposited_data": "Sim", "nuccore_ids": "924181778, 924181484, 124486924, 924181778, 924181484, 170172578, 124486924", "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38405817", "author": "Calame DG", "n_authors": 63, "title": "Biallelic variation in the choline and ethanolamine transporter FLVCR1 underlies a pleiotropic disease spectrum from adult neurodegeneration to severe developmental disorders.", "abstract": null, "journal": "medRxiv : the preprint server for health sciences", "doi": "10.1101/2024.02.09.24302464", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38399943", "author": "Beatty JA", "n_authors": 7, "title": "Epidemiology of Pathogenic Retroviruses and Domestic Cat Hepadnavirus in Community and Client-Owned Cats in Hong Kong.", "abstract": "Understanding the local epidemiology of feline leukaemia virus (FeLV) and feline immunodeficiency virus (FIV) in Hong Kong will inform retrovirus prevention strategies. Domestic cat hepadnavirus (DCH), a novel hepatitis-B-like virus, is commonly detected among client-owned cats in Hong Kong, but community cats have not been studied. The aims of this study were to investigate the frequency and potential risk factors for (i) FeLV and FIV among community and client-owned cats and (ii) perform molecular detection of DCH among community cats in Hong Kong. Blood samples from 713 cats were obtained from client-owned (n = 415, residual diagnostic) and community cats (n = 298, at trap-neuter-return). Point-of-care (POC) testing for FeLV antigen and feline immunodeficiency virus (FIV) anti-p15 and p24 antibodies was performed. FeLV-positive samples were progressed to p27 sandwich enzyme-linked immunosorbent assay. Whole blood DNA was tested with qPCRs for FeLV U3 and gag, and nested PCRs where additional information was required. DCH qPCR was performed on a subset of community cats (n = 193). A single, regressive, FeLV infection was detected in a client-owned cat (1/415 FeLV U3 qPCR positive, 0.2%, 95% CI 0.0-1.3%). Five/415 client-owned cats tested presumably false FeLV-antigen positive (qPCR negative). No markers of FeLV infection were detected in community cats (0/298; 0%). FIV seroprevalence was much higher in community cats (46/298, 15.4%) than in client-owned cats (13/415, 3.1%) (", "journal": "Viruses", "doi": "10.3390/v16020167", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38397386", "author": "Manco M", "n_authors": 10, "title": "FLVCR1a Controls Cellular Cholesterol Levels through the Regulation of Heme Biosynthesis and Tricarboxylic Acid Cycle Flux in Endothelial Cells.", "abstract": "Feline leukemia virus C receptor 1a (FLVCR1a), initially identified as a retroviral receptor and localized on the plasma membrane, has emerged as a crucial regulator of heme homeostasis. Functioning as a positive regulator of δ-aminolevulinic acid synthase 1 (ALAS1), the rate-limiting enzyme in the heme biosynthetic pathway, FLVCR1a influences TCA cycle cataplerosis, thus impacting TCA flux and interconnected metabolic pathways. This study reveals an unexplored link between FLVCR1a, heme synthesis, and cholesterol production in endothelial cells. Using cellular models with manipulated FLVCR1a expression and inducible endothelial-specific ", "journal": "Biomolecules", "doi": "10.3390/biom14020149", "deposited_data": "Sim", "nuccore_ids": "924181778, 924181484, 124486924, 924181778, 924181484, 124486924", "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38358295", "author": "Weidinger AK", "n_authors": 5, "title": "Anti-rabies humoral immune response in cats after concurrent vs separate vaccination against rabies and feline leukaemia virus using canarypox-vectored vaccines.", "abstract": "Some expert groups recommend that cats should be vaccinated with non-adjuvanted feline leukaemia virus (FeLV) and rabies vector vaccines, which, in the European Union, are currently not licensed for concurrent use and have to be administered at least 14 days apart (different from the USA) and thus at separate visits, which is associated with more stress for cats and owners. The aim of this study was to assess the anti-rabies antibody response in cats after vaccination against rabies and FeLV at concurrent vs separate (4 weeks apart) visits using two canarypox-vectored vaccines (Purevax Rabies and Purevax FeLV; Boehringer Ingelheim) and to evaluate the occurrence of vaccine-associated adverse events (VAAEs). Healthy FeLV antigen-negative client-owned kittens (n = 106) were prospectively included in this randomised study. All kittens received primary vaccinations against rabies (week 0) and FeLV (weeks 4 and 8). After 1 year, the study group (n = 52) received booster vaccinations against rabies and FeLV concurrently at the same visit (weeks 50-52). The control group (n = 54) received booster vaccinations against rabies (weeks 50-52) and FeLV (weeks 54-56) separately. Anti-rabies virus antibodies (anti-RAV Ab) were determined by fluorescent antibody virus neutralisation assay at weeks 4, 50-52 and 54-56, and compared between both groups using a Mann-Whitney U-test. Four weeks after the first rabies vaccination, 87/106 (82.1%) kittens had a titre ⩾0.5 IU/ml and 19/106 (17.9%) had a titre <0.5 IU/ml. Four weeks after the 1-year rabies booster, all cats had adequate anti-RAV Ab according to the World Organisation for Animal Health (⩾0.5 IU/ml), and the titres of the study group (median = 14.30 IU/ml) and the control group (median = 21.39 IU/ml) did not differ significantly ( Concurrent administration of Purevax FeLV and Purevax Rabies vector vaccines at the 1-year booster does not interfere with the development of anti-RAV Ab or cause more adverse effects and thus represents a better option than separate vaccination visits for cats and owners.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X231218643", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38347535", "author": "Chiu ES", "n_authors": 6, "title": "Endogenous feline leukemia virus long terminal repeat integration site diversity is highly variable in related and unrelated domestic cats.", "abstract": "Endogenous retroviruses (ERV) are indicators of vertebrate evolutionary history and play important roles as homeostatic regulators. ERV long terminal repeat (LTR) elements may act as cis-activating promoters or trans-activating enhancer elements modifying gene transcription distant from LTR insertion sites. We previously documented that endogenous feline leukemia virus (FeLV)-LTR copy number variation in individual cats tracks inversely with susceptibility to virulent FeLV disease. To evaluate FeLV-LTR insertion characteristics, we assessed enFeLV-LTR integration site diversity in 20 cats from three genetically distinct populations using a baited linker-mediated PCR approach. We documented 765 individual integration sites unequally represented among individuals. Only three LTR integration sites were shared among all individuals, while 412 sites were unique to a single individual. When primary fibroblast cultures were challenged with exogenous FeLV, we found significantly increased expression of both exogenous and endogenous FeLV orthologs, supporting previous findings of potential exFeLV-enFeLV interactions; however, viral challenge did not elicit transcriptional changes in genes associated with the vast majority of integration sites. This study assesses FeLV-LTR integration sites in individual animals, providing unique transposome genotypes. Further, we document substantial individual variation in LTR integration site locations, even in a highly inbred population, and provide a framework for understanding potential endogenous retroviral element position influence on host gene transcription.", "journal": "Retrovirology", "doi": "10.1186/s12977-024-00635-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38338028", "author": "Korkulu E", "n_authors": 7, "title": "Status Quo of Feline Leukaemia Virus Infection in Turkish Cats and Their Antigenic Prevalence.", "abstract": "Feline leukaemia virus (FeLV) is a member of the Gammaretrovirus genus, which has two genotypes in cats: endogenous (replication-defective provirus) and exogenous (replication-competent). In this study, 550 cats were examined, and 112 of them (20.36%) were found to have the endogenous FeLV (enFeLV) genotype. EnFeLV-positive animals were also tested for additional viral infections, and 48 cats (42.85%) were discovered to be co-infected with other viruses. According to co-infection data, these cats were infected with feline coronavirus (FCoV) (27/112, 24.1%), feline panleukopenia virus (FPV) (14/112, 12.5%), feline immunodeficiency virus (FIV) (0/112, 0%), and domestic cat hepadnavirus (DCH) (13/112, 11.6%). Their age, sex, breed, clinical state, lifestyle (in/outdoor), and immunization data against FeLV were also evaluated. In line with our results, the prevalence of enFeLV and co-infection with other pathogens in cats admitted to the clinic for various reasons were discussed. The majority of positive animals in terms of FeLV (94/112, 83.93%) had clinical findings. We emphasized that the FeLV-positive situation of cats should be taken into consideration by veterinarians when planning treatment and vaccination programs. Additionally, in this study, we questioned the group in which our enFeLVs were phylogenetically located. Therefore, we performed a phylogenetic analysis based on a comparison with global FeLV sequences obtained from the GenBank database. The sequenced positive samples were in the AGTT subgroup within Group-II.", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani14030385", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "40303121", "author": "Martins NB", "n_authors": 9, "title": "Occurrence of Typical Domestic Animal Viruses in Wild Carnivorans: An Emerging Threat to the Conservation of Endangered Species.", "abstract": "Wild species are susceptible to several typical domestic animal pathogens, and the increasingly close contact between these groups is a predictive factor for disease exposure. Some viruses are important and old-known, and others are emerging or reemerging for domestic carnivorans and have been identified as threats to the conservation of wild mammals. The purpose of the study was to investigate the occurrence of bocaparvoviruses (BoVs, ", "journal": "Transboundary and emerging diseases", "doi": "10.1155/2024/3931047", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38304754", "author": "Wilson R", "n_authors": 2, "title": "Salmonella enterica subspecies enterica serotype Typhimurium induced pyelonephritis and suspected multifocal myositis in a cat.", "abstract": "A 2-year-old male neutered domestic shorthair cat presented with an acute onset of muscular pain, ataxia and fever. Serological tests for  Infection with ", "journal": "JFMS open reports", "doi": "10.1177/20551169231221951", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38296890", "author": "Safwat S", "n_authors": 6, "title": "Genetic blueprint of congenital muscular dystrophies with brain malformations in Egypt: A report of 11 families.", "abstract": "Congenital muscular dystrophies (CMDs) are a group of rare muscle disorders characterized by early onset hypotonia and motor developmental delay associated with brain malformations with or without eye anomalies in the most severe cases. In this study, we aimed to uncover the genetic basis of severe CMD in Egypt and to determine the efficacy of whole exome sequencing (WES)-based genetic diagnosis in this population. We recruited twelve individuals from eleven families with a clinical diagnosis of CMD with brain malformations that fell into two groups: seven patients with suspected dystroglycanopathy and five patients with suspected merosin-deficient CMD. WES was analyzed by variant filtering using multiple approaches including splicing and copy number variant (CNV) analysis. We identified likely pathogenic variants in FKRP in two cases and variants in POMT1, POMK, and B3GALNT2 in three individuals. All individuals with merosin-deficient CMD had truncating variants in LAMA2. Further analysis in one of the two unsolved cases showed a homozygous protein-truncating variant in Feline Leukemia Virus subgroup C Receptor 1 (FLVCR1). FLVCR1 loss of function has never been previously reported. Yet, loss of function of its paralog, FLVCR2, causes lethal hydranencephaly-hydrocephaly syndrome (Fowler Syndrome) which should be considered in the differential diagnosis for dystroglycanopathy. Overall, we reached a diagnostic rate of 86% (6/7) for dystroglycanopathies and 100% (5/5) for merosinopathy. In conclusion, our results provide further evidence that WES is an important diagnostic method in CMD in developing countries to improve the diagnostic rate, management plan, and genetic counseling for these disorders.", "journal": "Neurogenetics", "doi": "10.1007/s10048-024-00745-z", "deposited_data": "Sim", "nuccore_ids": "2462567684, 2462567682, 2462567680, 2462567678, 2462567676, 2462567674, 2462567672, 2462567670, 2462567668, 2462567666, 2462567664, 2462567662, 2462567660, 2462567658, 2462567656, 2217323089, 2217323088, 2217323087, 2217323086, 2217323084, 2217323082, 2217323080, 2217323078, 2217323076, 2217323074, 2217323073, 2217323072, 2217323071, 2217323069, 2217323067, 2217323066, 1675172863, 1653961479", "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38240589", "author": "Ngo MH", "n_authors": 17, "title": "Multiple recombination events between endogenous retroviral elements and feline leukemia virus.", "abstract": "Feline leukemia virus (FeLV) is an exogenous retrovirus that causes malignant hematopoietic disorders in domestic cats, and its virulence may be closely associated with viral sequences. FeLV is classified into several subgroups, including A, B, C, D, E, and T, based on viral receptor interference properties or receptor usage. However, the transmission manner and disease specificity of the recombinant viruses FeLV-D and FeLV-B remain unclear. The aim of this study was to understand recombination events between exogenous and endogenous retroviruses within a host and elucidate the emergence and transmission of recombinant viruses. We observed multiple recombination events involving endogenous retroviruses (ERVs) in FeLV from a family of domestic cats kept in one house; two of these cats (ON-T and ON-C) presented with lymphoma and leukemia, respectively. Clonal integration of FeLV-D was observed in the ON-T case, suggesting an association with FeLV-D pathogenesis. Notably, the receptor usage of FeLV-B observed in ON-T was mediated by feline Pit1 and feline Pit2, whereas only feline Pit1 was used in ON-C. Furthermore, XR-FeLV, a recombinant FeLV containing an unrelated sequence referred to the X-region, which is homologous to a portion of the 5'-leader sequence of ", "journal": "Journal of virology", "doi": "10.1128/jvi.01400-23", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38199688", "author": "Osorio-Peralta DC", "n_authors": 3, "title": "Leishmania spp. diagnosis and therapeutic management in a cat from urban area in Ibagué (Colombia).", "abstract": "Leishmania spp., a protozoan transmitted by sandflies, widely affects humans and dogs in Colombia, nevertheless feline leishmaniasis (FeL) remains understudied. This study reports a case of feline leishmaniasis in Colombia and its therapeutic management. Complete blood count, renal and hepatic serum biochemistry, nodular lesion cytology, FeLV/FIV snap test, abdominal ultrasound, and molecular diagnosis of Leishmania spp. 16 s rRNA gene amplification by real-time-PCR (qPCR), ITS-1 and hsp70 gene by endpoint-PCR and Sanger sequencing were performed. The patient was negative for FIV/FeLV and showed leukocytosis, lymphocytosis, thrombocytopenia, neutrophilia, monocytosis, hypergammaglobulinemia, increased gamma-glutamyl-transferase, cortical nephrocalcinosis, diffuse heterogeneous splenic parenchyma, and cholangitis. Nodular lesion cytology, qPCR and Sanger sequencing confirmed the diagnosis of Leishmania spp. The patient was treated with allopurinol and miltefosine. After treatment, clinical signs disappeared. Clinical examination, cytology, and molecular tests allowed a rapid and sensitive FeL diagnosis. Allopurinol and miltefosine improved the clinical condition of the cat.", "journal": "Veterinary parasitology, regional studies and reports", "doi": "10.1016/j.vprsr.2023.100980", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38171093", "author": "Losada-Medina D", "n_authors": 4, "title": "Acute myeloid leukemia with neutrophilic differentiation in a 12-year-old African lion (Panthera leo).", "abstract": "To describe the clinical presentation, progression, and diagnosis of acute myeloid leukemia (AML) with neutrophilic differentiation in an African lion (Panthera leo). A 12-year-old male African lion kept at a zoological institution in Colombia. The lion presented for anorexia, pale mucous membranes, and a hind limb lameness of acute onset. Feline leukemia virus testing was negative, and repeated blood samples revealed severe anemia, intermittent thrombocytopenia, lymphopenia, and neutrophilia. Coinfection with Anaplasma and Mycoplasma spp and chronic kidney disease were diagnosed based on clinicopathological findings. The lion received symptomatic treatment, doxycycline, and methylprednisolone or prednisolone. Euthanasia was elected due to clinical deterioration and unresponsive anemia, despite the resolution of Anaplasma and Mycoplasma spp infections. AML with neutrophilic differentiation was diagnosed based on bone marrow cytology, histopathology, and immunohistochemistry. AML is a rare, aggressive hematopoietic disorder in domestic cats, although it has not yet been reported in nondomestic cats. This is the first description of the clinicopathological, histological, and immunohistochemical features of AML with neutrophilic differentiation in an FeLV-negative African lion that lacked circulating blasts.", "journal": "Journal of the American Veterinary Medical Association", "doi": "10.2460/javma.23.09.0530", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38157678", "author": "Valiant WG", "n_authors": 4, "title": "Efficient extraction of adventitious virus nucleic acid using commercially available methods.", "abstract": "An essential step in pharmaceutical product development is screening for contamination with adventitious agents, and there is desire to develop highly sensitive assays to detect adventitious viral nucleic acid. This study sought to examine the nucleic acid extraction efficiency of three viral candidates in relevant background matrices using four different extraction methods. Three model adventitious viruses, Minute virus of Mice, Porcine Circovirus, and Feline Leukemia Virus, were diluted within a variety of background matrices relevant to pharmaceutical production methods. Upon extraction, the nucleic acid was quantified using droplet digital PCR methods. Four nucleic acid extraction methods were assessed, including commercially available kits and manual extraction methods. Each method recovered nucleic acid post-extraction for each of the model viruses within the tested background matrices. The silica-column based method recovered a greater amount of viral nucleic acid, compared to the other methods tested. Similar trends were observed when model virus was diluted in bioreactor supernatant, which replicates industry testing conditions and provides details on which extraction methods might be used in Next Generation Sequencing and PCR methods for detecting contamination within pharmaceutical products.", "journal": "Biologicals : journal of the International Association of Biological Standardization", "doi": "10.1016/j.biologicals.2023.101741", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "37921544", "author": "Ginoudis A", "n_authors": 9, "title": "Discordance between ABC blood phenotype and genotype in a domestic short-haired cat.", "abstract": "An adult domestic short-haired feline leukemia virus-infected cat was referred for kidney failure and worsening anemia requiring transfusions. ABC blood typing was performed with an immunochromatographic strip assay at different occasions. Gel column systems were used for the major and minor crossmatching tests, and anti-A and anti-B titers were determined. No discrete A or B bands appeared on the immunochromatographic strips at any time point for the recipient cat. The recipient's plasma agglutinated RBCs from tested type A and B cats. The recipient's RBCs appeared compatible with plasma from 1 type A and 2 B donors, and incompatible with plasma from another type A cat. Genotyping of recipient blood revealed a single homozygous c.179G>T CMAH variant predicting a blood type B. These studies suggest an unusual weak type B or missing all ABC antigens. The latter resembles the exceedingly rare Bombay phenotype in the human ABO blood group system.", "journal": "Journal of veterinary internal medicine", "doi": "10.1111/jvim.16927", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "37913970", "author": "Castillo AP", "n_authors": 17, "title": "Evidence of SARS-CoV-2 infection and co-infections in stray cats in Brazil.", "abstract": "The zoonotic virus SARS-CoV-2, which causes severe acute respiratory syndrome in humans (COVID-19), has been identified in cats. Notably, most positive cases were in cats that had close contact with infected humans, suggesting a role for humans in animal transmission routes. Previous studies have suggested that animals with immune depletion are more susceptible to SARS-CoV-2 infection. To date, there is limited evidence of SARS-CoV-2 infections in stray and free-range cats affected by other pathogens. In this study, we investigated infections caused by SARS-CoV-2, Leishmania spp., Toxoplasma gondii, Mycoplasma spp., Bartonella spp., Feline leukemia virus (FeLV), and Feline immunodeficiency virus (FIV) in stray cats from an urban park in Brazil during the COVID-19 pandemic. From February to September 2021, 78 mixed-breed cats were tested for SARS-CoV-2 and hemopathogens using molecular analysis at Américo Renné Giannetti Municipal Park, Belo Horizonte, Minas Gerais, Brazil. An enzyme-linked immunosorbent assay (ELISA) was used to detect IgG in T. gondii. None of the animals in this study showed any clinical signs of infections. The SARS-CoV-2 virus RNA was detected in 7.7 % of cats, and a whole virus genome sequence analysis revealed the SARS-CoV-2 Delta lineage (B.1.617.2). Phylogenetic analysis showed that SARS-CoV-2 isolated from cats was grouped into the sublineage AY.99.2, which matches the epidemiological scenario of COVID-19 in the urban area of our study. Leishmania infantum was detected and sequenced in 9 % of cats. The seroprevalence of T. gondii was 23.1 %. Hemotropic Mycoplasma spp. was detected in 7.7 % of the cats, with Mycoplasma haemofelis and Candidatus Mycoplasma haemominutum being the most common. Bartonella henselae and Bartonella clarridgeiae were detected in 38.5 % of the cats, FeLV was detected in 17,9 %, and none of the cats studied tested positive for FIV. This study reports, for the first time, the SARS-CoV-2 infection with whole-genome sequencing in stray cats in southeastern Brazil and co-infection with other pathogens, including Bartonella spp. and Feline leukemia virus. Our study observed no correlation between SARS-CoV-2 and the other detected pathogens. Our results emphasize the importance of monitoring SARS-CoV-2 in stray cats to characterize their epidemiological role in SARS-CoV-2 infection and reinforce the importance of zoonotic disease surveillance.", "journal": "Acta tropica", "doi": "10.1016/j.actatropica.2023.107056", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "37469134", "author": "Li Z", "n_authors": 13, "title": "Novel mutations in FLVCR1 cause tremors, sensory neuropathy with retinitis pigmentosa.", "abstract": "The mutations of the feline leukemia virus subgroup C receptor-related protein 1 (FLVCR1) cause ataxia with retinitis pigmentosa. Recent studies indicated a large variation in the phenotype of FLVCR1-associated diseases. In this report, we describe an adult male who manifested first with tremors in his third decade, followed by retinitis pigmentosa, sensory ataxia, and sensory neuropathy in his fourth decade. While retinitis pigmentosa and sensory ataxia are well-recognized features of FLVCR1-associated disease, tremor is rarely described. Whole-exome sequencing revealed novel compound heterozygous pathogenic FLVCR1 variants: c.498 G > A; p.(Trp166*) and c.369 T > G; p.(Phe123Leu). In addition, we have highlighted the ultrastructural abnormalities of the sural biopsy in this patient.", "journal": "Neuropathology : official journal of the Japanese Society of Neuropathology", "doi": "10.1111/neup.12936", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41835954", "author": "Pimentel PAB", "n_authors": 8, "title": "Corrigendum to Feline lymphoma associated with feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) infections in Brazil- Systematic review [Veterinary and Animal Science volume 30 (December 2025) 100514].", "abstract": "[This corrects the article DOI: 10.1016/j.vas.2025.100514.].", "journal": "Veterinary and animal science", "doi": "10.1016/j.vas.2025.100547", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41497461", "author": "Jania B", "n_authors": 4, "title": "The use of selected electrophoretic techniques to assess the health of domestic cats (Felis catus).", "abstract": "Electrophoretic analytical techniques provide extremely important information about an animal's clinical condition. They are recommended in every case, including in screening tests of animals showing no concerning clinical symptoms. Such tests can detect subclinical conditions, such as inflammation, antigen stimulation or certain forms of cancer. The aim of the study was to determine the suitability of native serum protein electrophoresis and the comet assay for assessing the health status of cats. Electrophoresis was performed on serum samples from 125 cats. On sera with abnormalities in electropherograms (25 individuals), the following additional analyses were performed: haematological analysis, microscopic examination of a blood smear, plate tests detecting antibodies against feline infectious peritonitis (FIP) and feline immunodeficiency virus (FIV), a plate test detecting feline leukaemia virus (FeLV) surface antigen and a comet assay in peripheral blood lymphocytes. Native protein electrophoresis enabled the identification of latent disease conditions in individuals assessed as good for overall condition on the basis of clinical examination. Some cats thus assessed had an abnormal electropherogram and were carriers of FIV, FeLV or FIP. In addition, the comet assay identified increased instability in the genetic material of cats with electropherogram abnormalities. Electrophoretic techniques can be successfully used as a tools for identifying latent conditions and evaluating the overall health status of cats.", "journal": "Journal of veterinary research", "doi": "10.2478/jvetres-2025-0062", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41497367", "author": "Aftab G", "n_authors": 3, "title": "A Comparative Study on the Impact of FIV and FeLV Infection on the Ocular Microbiota in Persian Cats: Insights From Co-Infection and Single Infections.", "abstract": "The ocular microbiome of cats infected with feline immunodeficiency virus (FIV) or feline leukemia virus (FeLV) might differ from that of healthy cats. This study aimed to examine and compare the conjunctival bacterial and fungal flora in these groups. Bacterial and fungal cultures were conducted from the conjunctiva of 80 Persian cats, categorized into four groups: normal, FIV-infected, FeLV-infected, and co-infected with both FIV and FeLV. PCR assays confirmed the presence of FIV, FeLV,  The conjunctival bacterial flora of normal cats was predominantly Gram-positive, with  The co-infection of FIV and FeLV significantly alters the conjunctival microbiome, promoting the colonization of specific opportunistic pathogens. These findings may influence the clinical management of cats with these viral infections, especially in combination, and may create a more favorable environment for the growth of certain bacteria and fungi in the conjunctiva.", "journal": "Veterinary medicine international", "doi": "10.1155/vmi/8146795", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41465225", "author": "Rapichai W", "n_authors": 15, "title": "Innovative Colorimetric Neutral Red-Based Loop-Mediated Isothermal Amplification (NR-LAMP) Assay: Transforming Rapid and Affordable Feline Leukemia Virus Detection.", "abstract": "Feline leukemia virus (FeLV) is a retrovirus that globally affects both domestic and wild cats, leading to the development of leukemia, lymphoma, and immunosuppression. However, it is important to note that the daily antigen test may yield false negative results. In this study, we successfully developed the first colorimetric loop-mediated isothermal amplification (LAMP) associated with neutral red (NR-LAMP) for the detection of FeLV. The NR-LAMP assay exhibited high sensitivity and efficiency compared to the routine polymerase chain reaction (PCR) reference method. To ensure specificity, a novel LAMP primer set was custom-designed based on the ", "journal": "International journal of molecular sciences", "doi": "10.3390/ijms262411793", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41405820", "author": "de Oliveira Santana W", "n_authors": 8, "title": "Epidemiology and co-infection of URTD pathogens in domestic cats during COVID-19.", "abstract": "This study investigated the prevalence of upper respiratory tract disease (URTD) pathogens in domestic cats during the SARS-CoV-2 pandemic in southern Brazil, focusing on the detection of feline herpesvirus-1 (FHV-1), feline calicivirus (FCV), Mycoplasma felis, Chlamydia felis, and SARS-CoV-2. A total of 120 cats presenting URTD symptoms and with recent contact (within 15 days) with SARS-CoV-2-positive tutors were analyzed. The detection rates were 38.3% for FHV-1, 34.1% for FCV, 43.3% for M. felis, 19.16% for C. felis, and 1.2% for SARS-CoV-2. Co-infections were common, affecting 64.45% of cases, with M. felis as the most frequent mono-infection and FHV-1 and M. felis as the predominant co-infection. Significant associations were observed between specific host factors and pathogen presence; non-neutered cats and those with outdoor access had higher odds of infection. Retroviral infections (FIV and FeLV) were found to increase susceptibility to URTD agents, particularly C. felis and FCV. Clinically, sneezing and nasal discharge were prevalent in over 90% of cases, and conjunctivitis was strongly linked to C. felis and FHV-1. Despite concerns surrounding the zoonotic potential of SARS-CoV-2 during the COVID-19 pandemic, the virus played a limited role, as only one cat tested positive for SARS-CoV-2 RNA. These findings emphasize the importance of focusing on established URTD pathogens for feline health management, even amid global health events.", "journal": "Brazilian journal of microbiology : [publication of the Brazilian Society for Microbiology]", "doi": "10.1007/s42770-025-01844-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41392067", "author": "Stone NV", "n_authors": 10, "title": "Intra-host diversity of proviral FeLV and clinical outcomes.", "abstract": "Feline leukemia virus (FeLV) is a retrovirus associated with a variety of clinical conditions, including either regenerative or non-regenerative anemia. The high mutation rate of retroviruses promotes the formation of quasispecies — populations composed of multiple genetically related haplotypes — which drives the evolution of the viral population within a host and can impact on disease development. This study investigated the intra-host diversity of proviral FeLV and evaluated their impact on the hematological parameters in naturally infected cats. Twenty-seven blood samples from FeLV-positive cats were analyzed. Total DNA was extracted, and the complete env gene was amplified by PCR, followed by next-generation sequencing (NGS). Raw sequence data were quality-checked, trimmed, and aligned to the FeLV SU reference sequence. Quasispecies with frequencies above 5% were inferred using CliqueSNV v2.0.3, phylogenetic reconstruction was performed with IQ-TREE v1.6.12 and recombinant sequences were identified using SimPlot v3.5.1. A remarkable variability in quasispecies composition was observed among infected cats. While 13 animals (48.1%) harbored infections driven by a single haplotype, others (n = 14) exhibited a much more complex viral landscape, with five or more distinct haplotypes detected. In samples with greater viral diversity, quasispecies frequencies were more evenly distributed. In the phylogenetic reconstruction, most quasispecies sequences isolated from the same host clustered together in well-supported clades within the FeLV-A lineage. Notably, one exception was identified as a FeLV-A/enFeLV recombinant. Additionally, five other recombinant quasispecies were detected. Analysis of hematological parameters showed no significant correlations between the number of haplotypes and the presence of anemia (regenerative or non-regenerative). However, classifying animals by their lymphocyte values’ adherence to normal reference ranges revealed a statistically significant difference in the number of viral haplotypes detected between groups (p = 0.04). Additionally, a negative binomial regression indicated that life stage had a positive trend in its relationship with the number of proviral quasispecies (p = 0.0593), indirectly suggesting that a higher number of quasispecies tends to be observed in more advanced disease stages. Although not statistically significant, the result suggests a potential relationship that warrants further investigation. This study, therefore, indicates that the number of intra-host quasispecies can be influenced by both the duration of infection and alterations in the immune response in naturally FeLV-infected cats.", "journal": "Brazilian journal of microbiology : [publication of the Brazilian Society for Microbiology]", "doi": "10.1007/s42770-025-01815-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41346446", "author": "van Duijl J", "n_authors": 4, "title": "Recurrent pyothorax in a cat caused by Candida albicans.", "abstract": "A 7-month-old Siberian cat was presented for persistent fever and recurrent tachypnoea and dyspnoea. The cat was treated 2 weeks prior by the referring veterinarian for pyothorax. Repeated thoracic radiographs and CT showed severe pleuropneumonia. Although serology was positive for feline coronavirus antibodies, an RT-PCR for feline infectious peritonitis of the thoracic fluid was negative. The feline immunodeficiency virus/feline leukaemia virus SNAP test was negative. Repeated aerobic and anaerobic culture and sensitivity results were unable to detect bacterial growth but did detect  Pyothorax by ", "journal": "JFMS open reports", "doi": "10.1177/20551169251383150", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41305526", "author": "Wenk J", "n_authors": 14, "title": "Viral Coinfections Potentially Associated with Feline Chronic Gingivostomatitis in Cats with Feline Infectious Peritonitis.", "abstract": "Feline infectious peritonitis (FIP) is a fatal but now treatable disease in cats caused by feline coronavirus (FCoV). This study prospectively investigated viral coinfections in 100 cats diagnosed with FIP and subsequently treated with oral GS-441524 (Bova UK) and their influence on outcome, focusing on viruses potentially associated with feline chronic gingivostomatitis (FCGS). Cats were tested for feline leukemia virus (FeLV), feline immunodeficiency virus (FIV), feline calicivirus (FCV), feline herpesvirus (FHV), feline foamy virus (FFV), and feline gammaherpesvirus (FcaGHV1). Coinfections were identified at the following frequencies: FCV (27), FFV (22), FHV (6), FIV (4), FcaGHV1 (2), and FeLV (2, both progressive infections). FFV infection was significantly associated with FIV (p", "journal": "Viruses", "doi": "10.3390/v17111505", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41275274", "author": "Pawelczak P", "n_authors": 5, "title": "A novel and superior diagnostic test for feline leukemia virus: enhanced precision in rapid detecting viral antigen in blood, plasma and serum.", "abstract": "Feline leukemia virus (FeLV) significantly impacts feline health worldwide. Although several FeLV antigen rapid tests are available, selecting an accurate diagnostic tool remains a clinical challenge. In this paper, we present a novel and robust point-of-care assay that enables the precise diagnosis of FeLV antigen in blood, plasma, and serum and directly compared it with five other commercially available rapid FeLV antigen tests. Among the evaluated assays, Vet Expert and SNAP demonstrated 100% sensitivity, specificity, and accuracy, equaling gold-standard performance. Results demonstrate Vet Expert's superior diagnostic accuracy and practical applicability in both veterinary practice and disease control strategies.", "journal": "Virology journal", "doi": "10.1186/s12985-025-03015-y", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41247555", "author": "Bezerra JC", "n_authors": 16, "title": "Possible role of domestic cats in the epidemiology of leishmaniasis: evidence of genital lesions and vertical transmission.", "abstract": "Feline leishmaniasis has been increasingly reported in countries endemic for zoonotic leishmaniasis, including Brazil, Spain, Italy, Portugal, and Israel, raising questions about the role of cats in disease transmission. Although dogs are the primary reservoirs, cats may contribute to the maintenance and spread of Leishmania spp. This study investigated genital lesions associated with feline leishmaniasis and explored the potential for vertical transmission. ELISA results showed seropositivity in 33.7% of females and 43.8% of males, while PCR on genital secretions was positive in 31.5% and 18.8%, respectively. Concordance between ELISA and PCR occurred in 33.3% of females and 7.1% of males. The most frequent genital lesions were endometritis in females and epididymitis or testicular degeneration in males. Epididymitis was significantly more frequent (p < 0.01) and more severe (p < 0.01) in seropositive males, while other lesions showed no significant association with infection. Among the four pregnant cats analyzed, one was seropositive and two were PCR-positive. Importantly, all carried at least one PCR-positive fetus (8/13; 61.5%), supporting the occurrence of vertical transmission. In conclusion, feline leishmaniasis is associated with genital lesions, particularly epididymitis in males, and may involve transplacental transmission. These findings strengthen the evidence that cats could play an epidemiological role in leishmaniasis and highlight the need for further investigation.", "journal": "Veterinary research communications", "doi": "10.1007/s11259-025-10975-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41245806", "author": "Madani K", "n_authors": 5, "title": "Therapeutic applications of IgY in common canine and feline viral diseases.", "abstract": "Immunoglobulin yolk (IgY) is the major antibody in birds whose immunotherapeutic potential has been investigated in canine and feline viral diseases. Management currently focuses on supportive care (often insufficient) or prevention using vaccines (slow to develop). IgY is developed against a wide range of antigens, and commercial formulations also exist. Several therapeutic trials and case reports examine IgY as main or adjunctive treatment in feline and canine viral diseases. To map and summarize the available evidence on IgY-based immunotherapy for viral infections of dogs and cats and assess its reported benefits and shortcomings in a scoping review following the PRISMA-ScR guidelines. Original English-language studies, focusing on the application of IgY in treating canine and feline viral diseases. Six databases (Web of Science, Scopus, ScienceDirect, Google Scholar, PubMed, ResearchGate) were searched in October 2024 using combinations of keywords related to IgY, small animals and therapy. Data on study design, treatment protocol/dosage/outcome and OCEBM level of evidence score were extracted. In total, 14 studies met inclusion criteria, including 7 clinical trials, 3 case series and 4 case reports; ten investigated CPV-2, while four examined feline viruses (FIV/FeLV/FIP). Most were small non-randomized clinical trials. IgY was administered orally, intravenously, and intranasally. Higher doses generally produced stronger effects. Feline studies used non-specific IgY with limited therapeutical benefit. IgY-based immunotherapy appeared safe, accelerated recovery and reduced mortality in most studies, but current evidence in feline viral infections is limited and non-specific. Further pathogen-specific trials are required.", "journal": "Veterinary and animal science", "doi": "10.1016/j.vas.2025.100534", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41240245", "author": "Didkowska A", "n_authors": 10, "title": "The prevalence of highly-pathogenic viruses in European wildcat and Eurasian Lynx in Poland.", "abstract": "Many diseases commonly found in domestic cats may represent potential threats to wild cats. This study investigates the prevalence of selected viral pathogens in the Eurasian lynx (Lynx lynx) and European wildcat (Felis silvestris) in Poland, both being strictly-protected species vulnerable to environmental pressures. A total of 20 Eurasian lynx and five wildcats were subjected to serological and molecular analyses (ELISA and real-time PCR) aimed at confirming the presence of antibodies and genetic material for feline leukemia virus (FeLV), feline immunodeficiency virus (FIV), feline coronavirus (FCoV), feline calicivirus (FCV), feline herpesvirus (FHV), and feline panleukopenia virus (FPV). Antibodies were most frequently detected against FCV (32%), and FHV (32%), FCoV (23.1%), and FeLV (16%). No FIV and FPV antibodies were detected. Viral genetic material was confirmed in four animals, with FCV being most prevalent (9.1%), followed by FeLV and FHV (each 4.5%). Statistically significant associations were observed between the presence of FCV and FHV. These results suggest that viral infections may play a role in limiting wild felid populations in Central Europe. Continued surveillance is crucial to inform conservation efforts and assess long-term health risks.", "journal": "Veterinary research communications", "doi": "10.1007/s11259-025-10971-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41233817", "author": "Ibrahim AH", "n_authors": 3, "title": "Virological perspectives of the current situation of oncogenic viruses in Egypt: a review.", "abstract": "Oncogenic viruses play a pernicious role in the development of cancer, causing various tumors in humans and animals. These viruses are of public health importance in developing nations. Worldwide, about 15–20% of cancer cases are related to viral infections. About 12% of all cancers in humans are attributed to oncoviruses. However, the accurate rate of cancers attributed to oncoviruses across all animal cancers remains uncertain. In some species, such as chickens and cats, oncoviruses are responsible for approximately 80–100% of specific cancer cases. The first oncovirus reported in humans was the Epstein-Barr virus, in the case of Burkitt’s lymphoma. The Jaagsiekte sheep retrovirus was the first oncovirus to be reported in livestock. The main reported tumor viruses of veterinary importance are bovine leukemia virus, jaagsiekte sheep retrovirus, feline leukemia virus, bovine papillomavirus, equine papillomavirus, Marek’s disease virus, avian leukosis virus, and reticuloendotheliosis virus. The control of oncoviruses mainly relies on early molecular methods, such as PCR, with remaining difficulties concerning virus isolation. Moreover, the potential for viral oncogenes to integrate into host genomes underscores the challenges in diagnosis, control, and eradication. These viruses have a significant impact on veterinary health in Egypt, affecting various animal species and posing substantial economic challenges. Therefore, exploring the up-to-date situation of oncogenic viruses recorded in Egypt is essential. This review aims to elucidate the general mechanisms of viral oncogenesis, shedding light on the situation of oncoviruses of veterinary importance that circulate in Egypt, as well as their diagnosis and control.", "journal": "Infectious agents and cancer", "doi": "10.1186/s13027-025-00706-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41218517", "author": "Zhu S", "n_authors": 14, "title": "Identification of two novel linear B-cell epitopes in p27 of feline leukemia virus using monoclonal antibodies.", "abstract": "Feline leukemia virus (FeLV) is a gammaretrovirus that is prevalent among a wide range of felids worldwide and causes various hematopoietic disorders in domestic cats. The core protein p27 is the group-specific antigen of FeLV. It is soluble and abundantly produced, making it an ideal target for detection by immunoassays. In this study, the FeLV p27 gene, with a size of 744 bp, was expressed through prokaryotic expression systems, and the purified products were injected into BALB/c mice. Two new hybridoma cells (named mAb 1A6 and 3A7) were screened by Enzyme-Linked Immunosorbent Assay (ELISA), western blot analysis (WB), and indirect immunofluorescence assay (IFA). The antigenic epitope of these monoclonal antibodies was examined by WB or ELISA using a series of truncated GST-fused or artificially synthesized peptides. Further identification of monoclonal antibody target sequences revealed ", "journal": "International journal of biological macromolecules", "doi": "10.1016/j.ijbiomac.2025.148439", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41215536", "author": "Beall MJ", "n_authors": 4, "title": "Feline leukemia virus lifetime study: whole blood samples increase detection of low positive cats with extended long-term survival.", "abstract": "ObjectivesThousands of cats in the USA are newly diagnosed with feline leukemia virus (FeLV) each year, and known FeLV-infected cats are increasingly adopted from shelters. This study investigated optimal sample types to identify FeLV-infected cats and predictors of long-term survival in a cohort of FeLV-positive cats followed for up to 8 years after diagnosis.MethodsPreviously, 127 FeLV p27 antigen-positive cats were enrolled in a prospective study. Whole blood, plasma and serum were collected at enrollment and monthly for 6 months. All sample types were tested on SNAP FIV/FeLV Combo Test (SNAP) monthly, and results from microtiter plate ELISA (PetChek) for p27 antigen and a quantitative RT-PCR (qPCR) for proviral DNA were used for confirmation and classification of infection status (high positive, low positive or cryptic/negative). After the 6-month testing phase, cats entered a lifetime survival monitoring phase. Owner-reported status in the current study extended previous survival results by 4 years.ResultsTesting anticoagulated whole blood on SNAP at enrollment identified five and nine more FeLV-infected low positive cats (n = 29) than plasma or serum, respectively. Although some low positive (n = 11) cats demonstrated variable test results on SNAP with plasma and serum, others (n = 17) were SNAP positive with all three sample types and classified as low positive based on PetChek and qPCR results. After an additional 4 years of monitoring, low positive cats had not reached a median survival, with 19/29 (66%) cats still alive compared with 2/90 (2.2%) high positive cats.Conclusions and relevanceAnticoagulated whole blood on SNAP was a sensitive indicator of FeLV infection relative to plasma and serum and therefore should be the preferred diagnostic sample for FeLV antigen testing. Combining the results of whole blood antigen testing, PetChek and qPCR identified cats as high positive, low positive or cryptic/negative, with high positive cats having higher risk for early mortality. Use of these diagnostic tools facilitates the management of FeLV as a chronic condition.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X251379219", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41195078", "author": "Silva JC", "n_authors": 3, "title": "Bilateral conjunctival sporotrichosis in a domestic cat: case report.", "abstract": "Feline sporotrichosis is a subcutaneous mycosis caused by the dimorphic fungi of the genus ", "journal": "Frontiers in veterinary science", "doi": "10.3389/fvets.2025.1661507", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41150128", "author": "Eraghi V", "n_authors": 13, "title": "Feline Lymphoma in Focus: Examining the Patterns and Types in Croatia's Pathological Records.", "abstract": "Feline lymphoma, a common neoplasm in cats, presents across diverse anatomical sites and is influenced by genetic, immune, environmental, and viral factors. This 15-year retrospective study analyzed feline lymphoma cases from the University of Zagreb's Department of Veterinary Pathology, focusing on epidemiology, anatomical distribution, and immunophenotype. A bimodal age distribution was observed, with peaks at 2-3 and 10-12 years, and breed predispositions were noted in British and European Shorthairs after adjusting for referral frequency. Multicentric lymphoma was the most frequent type observed, followed by alimentary and mediastinal forms. Mediastinal lymphoma predominated in younger cats, whereas alimentary lymphoma was more common in older individuals. Male cats were overrepresented among renal lymphoma cases. Feline leukemia virus/feline immunodeficiency virus (FeLV/FIV) infection showed a strong correlation with mediastinal lymphoma. Overall, B-cell lymphomas were predominant; however, T-cell types were more frequently observed in European Shorthairs. In our study, mediastinal forms were uniformly T-cell, while alimentary and multicentric lymphomas were predominantly B-cell. Temporal trends showed surges in 2016-2017 and 2022-2023, and a decline during the COVID-19 pandemic. These findings highlight the complexity of feline lymphoma and underscore the need for tailored diagnostic and therapeutic strategies.", "journal": "Veterinary sciences", "doi": "10.3390/vetsci12100986", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41143441", "author": "Dertsiz Kozan B", "n_authors": 3, "title": "New Phenotype in Two Siblings with Familial FLVCR1 Mutation: Neurotrophic Keratopathy.", "abstract": "The feline leukemia virus subgroup C receptor (", "journal": "Turkish journal of ophthalmology", "doi": "10.4274/tjo.galenos.2025.05043", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41111634", "author": "Pimentel PAB", "n_authors": 8, "title": "Feline lymphoma associated with feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) infections in Brazil- Systematic review.", "abstract": "Lymphoma is the most common neoplasia in cats and is frequently linked with concurrent retroviral infections. Despite preventive strategies, feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) remain endemic in many parts of the world, with FeLV significantly shortening the lifespan of infected cats. In Brazil and other low-income countries, the incidence of FeLV and FIV remains high. However, the distribution of these retroviruses across South America is still unclear, and their correlation with the anatomical and clinical features of feline lymphoma remains poorly understood. Gaining a deeper understanding of these associations could lead to more effective disease control strategies and better-defined chemotherapy protocols. In this study, we examined the geographical distribution and clinical presentations of feline lymphoma in retrovirus-positive cats in Brazil. A modified bias risk analysis assessed the quality of published studies, and a map was created to highlight areas in need of further research. Initial screening of 703 studies identified 29 relevant ones, encompassing 607 cats with feline lymphoma. After bias analysis, 273 cases were included in this review: 190 were FeLV-positive and FIV-negative, 98 were FeLV-negative and FIV-negative, and 15 were FeLV-negative and FIV-positive. Cases were reported from six Brazilian states and the Federal District of Brazil (2000-2023). The anatomical location of lymphoma varied depending on the cats' viral status, with notable differences in intestinal and mediastinal manifestations. FeLV-negative cats showed an 11.1-fold increased risk (95 % CI=6.0-20.0) for intestinal lymphoma, while FeLV-positive cases had a 7.5-fold increased risk (95 % CI=3.7-15.6) for mediastinal lymphoma. Due to the scarcity of FIV-related cases, analyzing associations was not feasible. Given the apparent association between FeLV-positive status and lymphoma location, further research into this neoplasm is strongly encouraged. We also recommend widespread retrovirus testing and expanded FeLV vaccination efforts in Brazil.", "journal": "Veterinary and animal science", "doi": "10.1016/j.vas.2025.100514", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41108469", "author": "Fonseca J", "n_authors": 8, "title": "Identification of a mouse-virulent recombinant type I/III Toxoplasma gondii strain in liver cytology of an immunosuppressed cat infected with FeLV-C subgroup.", "abstract": "Toxoplasma gondii infection is common in cats, though clinical disease is uncommon and typically occurs in immunocompromised individuals. Till now, there is no specific genotype that can be associated with a certain clinical outcome. A 5-year-old Siamese cat, diagnosed as Feline Leukemia Virus (FeLV)-positive and classified within the FeLV-C subgroup, presented with a two-month history of progressive lethargy, hyporexia, weight loss, and non-regenerative anemia. The cat, a rescued stray with ongoing outdoor access, had previously responded to doxycycline and prednisolone for presumed Mycoplasma spp. infection, but relapsed and began showing signs of discomfort in head and neck regions, consistent with peripheral neuropathy/ encephalitis. Despite treatment with raltegravir, prednisolone, darbopoetin alfa, cyclosporine and clindamycin (although unknown effectiveness of oral administration), clinical deterioration occurred. The cat developed fever, severe anemia, neutropenia, hyperbilirubinemia, hypoglycaemia and elevated ALT activity. Imaging revealed diffuse hepatic changes and a pulmonary interstitial pattern. Liver FNA identified T. gondii organisms, confirmed by qPCR. Despite the initiation of intravenous clindamycin and trimethoprim-sulfamethoxazole, the cat developed seizures, acute respiratory distress, and septic shock, leading to euthanasia. Genotyping of the hepatic T. gondii isolate via targeted NGS at 13 loci revealed a strain with a recombinant type I/III profile. This mosaicism was previously associated with high virulence in mice and also detected in human patients from the same geographical region. This case highlights the variable presentation of toxoplasmosis in cats and contributes to the scarce knowledge of circulating strains in animals. Characterizing the genetic background of strains could identify sources during zoonotic outbreaks and identify genotypes associated with specific clinical manifestations.", "journal": "Veterinary research communications", "doi": "10.1007/s11259-025-10942-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41105726", "author": "Swapna GVT", "n_authors": 4, "title": "Memorization bias impacts modeling of alternative conformational states of solute carrier membrane proteins with methods from deep learning.", "abstract": "The Solute Carrier (SLC) superfamily of integral membrane proteins transport a wide array of small molecules across plasma and organelle membranes, and function as important drug transporters and as viral receptors. They populate different conformational states during the solute transport process, including outward-open, intermediate (occluded), and inward-open conformational states. For some SLC proteins this structural \"flipping\" corresponds to swapping between conformations of their N-terminal and C-terminal symmetry-related sub-structures. Conventional AlphaFold2, AlphaFold3, or Evolutionary Scale Modeling methods typically generate models for only one of these multiple conformational states of SLC proteins. While several AI-based protocols for modeling multiple conformational states of proteins have been described recently, these methods are often impacted by \"memorization\" of one of the alternative conformational states, and do not always provide both the inward- and outward-open conformations of SLC proteins. Here we assess the impact of memorization in modeling SLC proteins with AlphaFold2/3, and describe a combined ESM - template-based-modeling process, based on a previously described template-based modeling method that relies on the internal pseudo-symmetry of many SLC proteins, to consistently model the alternate conformational states of SLC proteins. We also demonstrate how the resulting multi-state models can be validated by comparison with sequence-based evolutionary co-variance data (ECs) that encode information about contacts present in the various conformational states adopted by the protein. This simple, rapid, and robust approach for modeling conformational landscapes of pseudo-symmetric SLC proteins is demonstrated for several integral membrane protein transporters, including SLC35F2 the receptor of a feline leukemia virus envelope protein required for viral entry into eukaryotic cells.", "journal": "PLoS computational biology", "doi": "10.1371/journal.pcbi.1013590", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41090071", "author": "LaVigne EK", "n_authors": 8, "title": "Spectrum of care approach to animal shelter management of feline infectious peritonitis complicated by feline leukemia virus.", "abstract": "Feline infectious peritonitis (FIP) occurs most commonly in multi-cat environments such as animal shelters. FIP is often suspected based on compatible history, signalment, physical examination, and hematological and biochemical findings. Increased diagnostic certainty requires additional diagnostic imaging and laboratory testing that may be out of reach for resource-poor caregivers and organizations. The objective of this retrospective study was to evaluate response to GS-441524 (GS) therapy of cats diagnosed with FIP using a spectrum of care approach relying on physical examination, hematology, biochemistry, and Feline Leukemia Virus (FeLV) antigen at a shelter specializing in the adoption of cats with FeLV. The FIP treatment protocol included treatment with GS for 84 days, followed by observation for 84 days. Starting dosage, dose adjustment, route of administration, and treatment extensions were based on initial condition and response to therapy. Hematology and biochemistry panels were performed at baseline, treatment, and post-treatment observation periods. Response to treatment and survival times were compared between FeLV-positive and FeLV-negative cats. A total of 170 cats diagnosed with FIP (104 FeLV-positive; 66 FeLV-negative) were included in the study. Hematology and serum chemistry abnormalities and their resolution during treatment were not significantly different between the groups, nor were there significant differences in survival through the treatment period (79% vs. 76%) or observation period (74% vs. 74%) between FeLV-positive and FeLV-negative cats respectively. Most mortality (55%) occurred in the first 7 days; cats surviving >7 days had an 86% survival rate. Despite equivalent responses to GS treatment, the FeLV-positive group experienced progressive mortality following the observation period. Survival of FeLV-positive cats (median 524 days, range 1-1585 days) was significantly shorter than for FeLV-negative cats (median not reached, range 0-1424 days) ( The spectrum of care diagnostic approach appeared to be sufficient and preserved resources for the successful treatment of shelter cats. FeLV-positive cats achieved equivalent FIP remission rates to FeLV-negative cats but were still at risk for shortened lifespan associated with FeLV infection.", "journal": "Frontiers in veterinary science", "doi": "10.3389/fvets.2025.1570267", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41085900", "author": "Dos Santos TA", "n_authors": 8, "title": "Metabolic and cardiovascular effects of obesity in domestic cats.", "abstract": "Obesity in cats has become increasingly prevalent in clinical practice and is associated with several comorbidities and reduced longevity. However, data on metabolic alterations in overweight or obese cats remain limited. This study aimed to evaluate hematological, lipid profile, oxidative metabolism, and cardiovascular parameters in overweight and obese cats. A total of 42 neutered mixed-breed cats were included and divided into three groups (n = 14): control group, overweight group, and obese group. Animals were selected based on medical history, physical examination, complete blood count, FIV/FeLV serology, and biochemical profile; individuals with comorbidities were excluded. Evaluations included complete blood count, lipid profile, malondialdehyde (MDA), reduced glutathione (GSH), erythrocyte osmotic fragility, electrocardiogram, and systemic blood pressure. Overweight cats showed significantly elevated cholesterol levels (179.93 ± 37.41 mg/dL; p = 0.003). Obese cats showed lymphopenia (1175 cells/µL; 871-2662), increased cholesterol (181.92 ± 27.78 mg/dL; p = 0.003), triglycerides (117 mg/dL; 80-211; p = 0.002), very low-density lipoprotein (VLDL) (30.7 ± 20 mg/dL; p = 0.001), and systolic blood pressure (160.3 ± 20.56 mmHg; p < 0.001) compared to the control group. In conclusion, feline obesity induces significant alterations in hematological, lipid, and cardiovascular parameters, indicating a relevant systemic impact.", "journal": "Veterinary research communications", "doi": "10.1007/s11259-025-10929-z", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41036018", "author": "Kulnides N", "n_authors": 8, "title": "Sporotrichosis incidence and risk factors in cats in Thonburi District, Bangkok, Thailand: A retrospective study.", "abstract": "Sporotrichosis is a zoonotic fungal infection caused by  To investigate the incidence and potential risk factors of feline sporotrichosis in Thonburi District, Bangkok, Thailand, from 2018 to 2024. A retrospective review of clinical records was conducted at a veterinary clinic in Thonburi. Among the 1,030 cats examined, 22 cases of sporotrichosis were confirmed through cytological examination. Data collected included sex, neuter status, age, husbandry system, feline leukemia virus (FeLV)/feline immunodeficiency virus (FIV) infection status, and blood parasite infections. Statistical analysis using the chi-square test was performed to identify significant associations between infections and risk factors. The incidence of sporotrichosis was 2.14%. Infected cats were evenly distributed between sexes, with 68.18% being unneutered. All infected cats were domestic shorthairs raised in open systems. Clinical signs included ulcerative skin lesions, sneezing, nasal swelling, anorexia, and dehydration. Co-infection with FeLV, FIV, and  Feline sporotrichosis in Thonburi is significantly associated with open husbandry systems and immunosuppressive viral infections. Effective treatment is possible but requires long-term owner compliance. Public education on closed-system cat care and early diagnosis should be included in preventive strategies. These findings support the relevance of the One Health approach in managing zoonotic fungal diseases in urban settings.", "journal": "Open veterinary journal", "doi": "10.5455/OVJ.2025.v15.i8.31", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41015115", "author": "Slaviero M", "n_authors": 7, "title": "Feline herpesvirus and calicivirus: Occurrence and pathology in cats with respiratory disease.", "abstract": "Feline herpesvirus (FHV) and feline calicivirus (FCV) are the primary causative agents of respiratory disease in cats. Although fatal respiratory disease is frequently observed in routine pathological diagnostics, the role of viral involvement is rarely investigated. This study aimed to assess the involvement of FHV and FCV in necropsied cats with fatal respiratory disease using immunohistochemistry, and to characterize the affected tissues, along pathological and epidemiological findings of the positive cats. Sixty cats were assessed. Immunolabeling for FHV was observed in 12 cats, for FCV in seven cats, and for both viruses in three cats. These FHV and FCV-positive cats (n = 22) were included in the study. Co-infection with feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV) was observed in 14 cats (six FeLV-positive, four FIV-positive, and four FeLV and FIV-positive). Gross lesions were mainly restricted to the respiratory and upper digestive tracts. Histological analysis revealed that the affected tissues included the nasal and oral cavities, esophagus, larynx, trachea, and lungs. All FCV-positive cats and most FHV-positive cats presented erosive, ulcerative, and fibrinonecrotic lesions in the upper respiratory/digestive tracts, concomitant with pneumonia (18/22). The remaining 4/22 cats, all infected with FHV, had lesions restricted to the upper respiratory tract. FHV-positive cats showed a bronchointerstitial pneumonia, whereas FCV-positive cats exhibited a fibrinosuppurative pneumonia. This study highlights pneumonia as an important cause of death in cats with FCV and FHV infection, particularly in those co-infected with retroviruses. It also emphasizes the importance of collecting samples from the respiratory and upper digestive tracts during necropsy and using immunohistochemistry to confirm the involvement of viral infectious agents-even in adult and aging cats. The findings of this study may contribute to further investigations into feline respiratory diseases.", "journal": "Topics in companion animal medicine", "doi": "10.1016/j.tcam.2025.101023", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41012827", "author": "Maximino MM", "n_authors": 7, "title": "Statistical Triage Model for Feline Infectious Diseases in a Veterinary Isolation Unit: The Case of Feline Immunodeficiency and Leukemia Viruses.", "abstract": "Isolation units in veterinary hospitals are essential for managing infectious diseases, but limited resources in staff, equipment and budget make timely triage difficult. In this scenario, data-driven models, if trained with high-quality data and presenting good accuracy, might be a rapid and low-cost first step before more costly diagnostics are deployed to unclear cases. In this study, we aimed at constructing simple triage models for two common feline infections using routine-collected data from 1211 cats admitted to a Biological Isolation and Containment Unit (BICU) in Portugal, of which 640 were eligible for analysis. Our study focused on infections caused by Feline Immunodeficiency and Leukemia viruses (FIV and FeLV) due to their potential to induce immunosuppression and increased susceptibility to secondary diseases. Our model training was based on data from 134 FIV-seropositive cats, 126 FeLV-seropositive, and 504 confirmed non-cases (i.e., controls) of these infections diagnosed by rapid immunomigration assays and ELISA. Significant triage factors of FIV infections included older age, outdoor access, and concomitant disorders whereas, for FeLV, infections, they were mixed-breed status, concomitant conditions, and low hematocrit. The models showed areas under the receiver operating characteristic curve of 0.70 and 0.69 for FIV and FeLV infections, respectively, with sensitivities and specificities estimated above ≥65%. This performance, being far from sensitivities and specificities above 90%, motivates further research to find additional triage factors to improve model utility.", "journal": "Veterinary sciences", "doi": "10.3390/vetsci12090902", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40993081", "author": "Yutsudo A", "n_authors": 7, "title": "High prevalence of renal amyloidosis in cats in an overcrowded colony.", "abstract": "Multiple cats in an overcrowded colony died of acute kidney injury with renal amyloidosis. To investigate the etiology of these deaths, we performed histological analysis of the kidneys of 27 colony cats and 29 noncolony cats (8 with acute kidney injury, 9 with chronic kidney disease, and 12 nonazotemic). Congo red-positive amyloid deposition was observed prominently in the glomeruli and cortical and medullary interstitium and was identified as AA amyloid using permanence. The prevalence and severity of renal amyloidosis were significantly higher in colony cats than in noncolony cats. Feline immunodeficiency virus showed no association with feline leukemia virus infection. Based on our results, adverse environmental conditions may accelerate the incidence of feline renal amyloidosis.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.25-0044", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40986110", "author": "Abdillah DA", "n_authors": 11, "title": "Feline leukaemia virus subgrouping using a viral interference assay.", "abstract": "Feline leukaemia virus subgroup A (FeLV-A) is transmitted among cats, and FeLV subgroups are frequently generated de novo. We investigated the frequency of detection of subgroups using interference assays in 50 cases. FeLV-A infection alone was detected in 38% of the cases, whereas coinfection with both FeLV-A and FeLV-B was observed in 62% of the cases. No cases of FeLV-B infection alone were observed. Cases of coinfection with FeLV-A and FeLV-B showed a higher prevalence than cases of FeLV-A infection alone. The FeLV containing an X region was discovered in two new cases. This study may help to elucidate the mechanism underlying FeLV-B-associated diseases.", "journal": "Archives of virology", "doi": "10.1007/s00705-025-06407-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40951560", "author": "Shekarabi D", "n_authors": 3, "title": "Evaluation of Apoptosis and Caspase-3 Activity in EL4 Cell Line Lymphoma Using Moringa Oleifera Plant Extract.", "abstract": "Lymphoproliferative disorders are a group of hematological malignancies involving the proliferation of lymphocytes. These neoplasms are generally classified into three distinct groups: lymphoma, leukemia, and plasma cell tumors. Among these, lymphomas are among the most prevalent types of malignant tumors in veterinary medicine. These neoplasms exhibit a high prevalence rate in dogs and cats afflicted with diseases such as FeLV. In light of the deleterious side effects associated with chemotherapy drugs, there has been a surge of interest in exploring the use of medicinal plants. M. oleifera, also known as the miracle tree, is a plant that contains anti-cancer compounds in all its parts, including the leaves, roots, and stems. It has been identified as having high antioxidant potential, making it a valuable plant for promoting health and preventing diseases. Moringa oleifera, a well-known member of the Moringaceae family, has been extensively studied due to its high antioxidant capacity. Recent research has highlighted its significant anti-inflammatory and anti-cancer properties. The present study sought to investigate the toxicity effect of moringa extract on the EL4 lymphoma cell line. In this study, EL4 cells were exposed to varying concentrations of M. oleifera extract for 24, 48, and 72 hours. The survival rates of the different groups were initially evaluated using trypan blue and MTT assay methods, and subsequently, real-time PCR was employed for a more precise analysis. The resulting data were then subjected to thorough analysis using SPSS software and the one-way ANOVA test. The treatment of the cell line with M. oleifera powder extract at all concentrations resulted in the inhibition of cancer cell growth. The most significant outcomes were observed at a concentration of 10 µg/ml after 48 hours, and the IC50 value was found to be greater than 50%. The study concluded that M. oleifera extract inhibits the growth of EL4 cells.", "journal": "Archives of Razi Institute", "doi": "10.32592/ARI.2025.80.1.37", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40944939", "author": "Oikonomidis IL", "n_authors": 7, "title": "Serum Amyloid A and Haptoglobin as Markers in Cats with Gingivitis-Preliminary Study.", "abstract": "Chronic gingivostomatitis has been associated with increases in α1-acid glycoprotein and serum haptoglobin (Hp) in cats. However, serum amyloid A (SAA) and Hp have not been previously evaluated in cats with uncomplicated gingivitis. To compare SAA and Hp between cats with gingivitis and healthy cats, and to investigate the correlation between these two proteins and the severity of gingivitis. This was a prospective cross-sectional study. Adult, FIV- and FeLV-seronegative cats were included. The cats were allocated into two age- and sex-matched groups. The case group included cats with gingivitis, and the control group included clinically and clinicopathologically healthy cats. The severity of gingivitis was assessed by the Total Mouth Periodontal Score (TMPS)-G index. Serum samples were used to measure SAA and Hp using a previously validated turbidimetric immunoassay and haemoglobin-binding method, respectively. The R statistical language was used for the statistical analysis. A total of 22 cats were included, 11 in each study group. The median (range) age of cats was 5.0 (3.0-11.0) years. The median Hp concentration was significantly higher (p = 0.001) in the case group (2.40 [0.72-4.44] g/L) compared with the control group (1.06 [0.50-1.42] g/L). A significant correlation was found between Hp and TMPS-G (rho = 0.636, p = 0.040). The SAA was below the detection limit (0.4 mg/L) in all samples of the control group and in 10/11 samples of the case group. Feline gingivitis is associated with increased Hp, suggesting the presence of an acute-phase reaction. Haptoglobin appears to be correlated with the severity of the disease.", "journal": "Veterinary medicine and science", "doi": "10.1002/vms3.70606", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40944569", "author": "Wardhani SW", "n_authors": 5, "title": "Longitudinal observation of chronic domestic cat hepadnavirus infection in cats with evidence of extrahepatic involvement.", "abstract": "ObjectivesDomestic cat hepadnavirus (DCHBV), belonging to the ", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X251359148", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40905267", "author": "Westman ME", "n_authors": 17, "title": "Antibody responses to feline leukaemia vaccination: exploring the effect of sex, boosting schedule, site of administration and vaccine type.", "abstract": "ObjectivesHistorically, vaccines have been administered in the dorsal interscapular region of cats (the 'scruff' of the neck) owing to easy access to the subcutaneous space. In response to concerns about sarcomas developing at injection sites (feline injection site sarcomas [FISSs]), and a possible association between feline leukaemia virus (FeLV) vaccination and the development of FISS, alternative FeLV vaccination sites such as the distal left hindlimb and tail have been proposed by influential vaccination bodies and various key opinion leaders. There is a dearth of evidence, however, to demonstrate the development of a comparable immune response after FeLV vaccination in these sites.MethodsThis field study was undertaken to investigate the FeLV anti-surface unit (SU) antibody response in FeLV-uninfected cats inoculated with one of three different FeLV vaccines (Fel-O-Vax 5, Fel-O-Vax Lv-K or Leucogen FeLV), administered in one of three different anatomical locations ('scruff', left distal hindlimb or tail). Kittens were sampled at three different time points, 1 month apart (T0, T1, T2) and again 12 months later (T12). Testing with a published anti-SU ELISA to detect FeLV-A and FeLV-B antibody responses to vaccination was performed. Antigen p27 testing, PCR testing to detect FeLV proviral DNA and neutralising antibody (NAb) testing to identify any FeLV-infected or FeLV-exposed animals were also performed.ResultsA total of 125 kittens were recruited and allocated into one of nine vaccine groups, with 105 kittens completing the initial course of vaccinations and blood draws, and 83 cats returning for T12 sampling. No progressive or regressive FeLV infections were detected in the entire kitten or adult cohorts. A total of 14 (11%) kittens and two (2%) adults tested FeLV NAb-positive. Females had higher (approximately 1.6-fold) post-vaccinal FeLV-A and FeLV-B antibody concentrations compared with males (", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X251353080", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40859264", "author": "Mendoza-Roldan JA", "n_authors": 11, "title": "Leishmania (Leishmania) infantum and Leishmania (Sauroleishmania) tarentolae in outdoor cats and report of infection in feline-derived peripheral blood mononuclear cells.", "abstract": "Feline leishmaniosis (FeL) is mainly caused by Leishmania infantum in the Mediterranean Basin. In Italy, in the same epidemiological context where canine leishmaniosis (CanL) is hyperendemic, a nonpathogenic species, Leishmania tarentolae, may also occur in sympatry, infecting reptiles, dogs, and humans. Thus, this study aimed to assess L. tarentolae infection in outdoor cats along with its co-occurrence with L. infantum and to evaluate risk factors. In addition, the persistence of L. tarentolae in feline-derived peripheral blood mononuclear cells (PBMCs) was herein evaluated in vitro. Outdoor colony or stray cats were screened for Leishmania spp. by immunofluorescence antibody test (IFAT) using promastigotes of both L. infantum and L. tarentolae. Whole blood and buffy coat were tested by a real-time polymerase chain reaction (qPCR) and duplex real-time PCR (dqPCR), and positive samples sequenced following an ITS1 conventional PCR (cPCR). Feline-derived PMBCs were subsequently infected with promastigotes of L. tarentolae to assess the persistence of amastigotes. Viral infections caused by feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) were molecularly addressed in all enrolled cats. Statistical analysis was performed to evaluate the possible association between Leishmania spp. infection and FIV/FeLV infection by using a multivariate logistic regression model following an initial LASSO-penalized logistic regression. Overall, 42 out of 194 cats (21.6%) were serologically or molecularly positive for Leishmania spp. In particular, 26 (13.4%) cats were seropositive for L. infantum and/or L. tarentolae by IFAT, with 16 (8.2%) animals positive for both species. Molecularly, 14 out of 194 cats (7.2%) were positive for L. infantum by qPCR, whereas five (2.6%) were positive for L. tarentolae by dqPCR. Cat PBMCs were successfully infected with L. tarentolae, and the infection persisted for at least 72 h. Overall, 38 out of the 194 screened cats (19.6%) were infected by FIV and/or FeLV, of which 12 were serologically or molecularly positive for Leishmania spp., with one cat positive for L. tarentolae DNA, and five for L. infantum DNA. Multivariate screening identified municipality (OR 2.206; P = 0.031; 95% CI 1.077-4.516) as a risk factor for Leishmania spp. infection, while the association between Leishmania spp. and FIV infection was not significant (OR 2.359; P = 0.08, 95% CI 0.901-6.179). Colony or stray cats were herein found for the first time infected by L. tarentolae, in areas where L. infantum is endemic. Cross-reactivity using IFAT test may pose a diagnostic hindrance also in FeL. The infection with this saurian-associated Leishmania in cats was further confirmed through the persistence of this Leishmania in cat PBMCs. Further studies are needed to fully unravel the complex interactions between both species of Leishmania and the implication of the sympatric occurrence of both species in the diagnosis and control of leishmaniosis.", "journal": "Parasites & vectors", "doi": "10.1186/s13071-025-06983-w", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40819490", "author": "Grandinetti JAB", "n_authors": 5, "title": "Subcutaneous hyalohyphomycosis in a domestic cat caused by Flavodon flavus, an under-recognized fungal pathogen.", "abstract": "This report describes the first documented case of subcutaneous hyalohyphomycosis caused by Flavodon flavus in a domestic cat. A 3-year-old spayed indoor cat presented with progressive cutaneous nodules on all four limbs. Histopathology revealed a pyogranulomatous inflammatory response with fungal elements, and fungal culture followed by molecular identification confirmed F. flavus as the etiologic agent. The cat tested negative for FIV and FeLV. Initial treatment with oral itraconazole (5 mg/kg/day) resulted in partial improvement. Due to stagnation in clinical response by day 90, oral potassium iodide (5 mg/kg/day) was added. Combined therapy led to complete resolution of lesions by day 135, and treatment was extended for an additional 60 days. No recurrence has been observed to date. This case highlights the emerging role of F. flavus-an environmental basidiomycete previously unrecognized as a feline pathogen-as a potential cause of subcutaneous mycoses in cats. Long-term antifungal treatment and close monitoring are recommended due to the risk of relapse.", "journal": "Research in veterinary science", "doi": "10.1016/j.rvsc.2025.105859", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40786738", "author": "Urkiola A", "n_authors": 5, "title": "Long-term oclacitinib administration for the control of feline allergic pruritus: A retrospective study of 14 client-owned cats.", "abstract": "Our objective was to provide preliminary clinical and laboratory data and the minimum effective dose for long-term (≥ 7 mo) treatment of feline allergic pruritus with oclacitinib. We studied 14 privately owned cats with pruritic allergic dermatitis controlled with oclacitinib treatment. Clinical data and results of blood testing (at the onset and at least once thereafter) during treatment were retrospectively evaluated. The median initial dosage of oclacitinib was 1.1 mg/kg q12h. In 7 animals, the maintenance dose could be reduced by ≥ 50%, usually after 15 d of treatment. The median duration of treatment was 15.5 mo. An FeLV-FIV test was conducted in 10 cats and all were negative. During treatment, 4 cats had non-dermatologic disorders that resolved without changing the oclacitinib dosing schedule. Alterations in blood tests during treatment were mild and frequently transient and included hypercholesterolemia, increased alanine aminotransferase and/or creatinine, and hyperglycemia. Limited and transitory disruptions in platelets and white cell lineage numbers were identified in some cats but none required specific treatment or discontinuation of oclacitinib. Alterations observed in the 14 cats treated with oclacitinib for a median of 15.5 mo were few and mild. No direct relationships were apparent between laboratory abnormalities or clinical signs and the dosing schedule of oclacitinib. A reduction of the daily dose to control allergic pruritus was feasible in 7/14 cats. Key clinical message: Based on the 14 cases included, long-term treatment with oclacitinib appeared to be well-tolerated and effective for managing feline allergic pruritus. However, close monitoring is recommended, and prospective studies with larger samples are needed to confirm these results.", "journal": "The Canadian veterinary journal = La revue veterinaire canadienne", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40782285", "author": "Braga ÍA", "n_authors": 18, "title": "Feline botulism: two decades and two reports.", "abstract": "This study describes an outbreak of type C botulism in domestic cats in central region of Brazil, two decades after the only previously reported natural case in the specie. Between August and October 2024, 21 cats presented with flaccid tetraparesis and were clinically evaluated. The course of the clinical signs varied from acute to subacute, with signs including hypotonia of all limbs, bladder and intestines, hypophonia, and flaccid paralysis of masticatory muscles. Eight cats died due to cardiorespiratory arrest. Necropsy and histopathological analyses revealed no significant macroscopic or microscopic lesions. Botulinum toxin type C was detected in five cats through standard mouse bioassay: in feces (n = 3), liver (n = 1), and intestinal contents (n = 1). Although the toxin was not found in the remaining animals, botulism was not excluded based on clinical and epidemiological findings, absence of spinal or other neurological lesions, and the exclusion of other infectious agents. All cats tested negative for FeLV, Coronavirus, Toxoplasma gondii, and Neospora caninum, and were also screened for intestinal parasites. Despite the strong epidemiological evidence, including common exposure to commercial diets, hunting behavior, and outdoor access, the source of intoxication was not identified. This study highlights a rare and severe outbreak of feline botulism and reinforces the importance of considering this diagnosis in similar clinical scenarios.", "journal": "Veterinary research communications", "doi": "10.1007/s11259-025-10848-z", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40771398", "author": "Douralidou D", "n_authors": 4, "title": "Multifocal discospondylitis and osteomyelitis due to Salmonella species in a cat.", "abstract": "A 1-year-old male castrated Savannah cat presented with chronic recurrent lethargy, stiffness, right pelvic limb lameness and spinal hyperaesthesia. Eight months before referral, the cat was treated with prednisolone, remdesivir and a 1-week course of amoxicillin/clavulanic acid and marbofloxacin for suspected feline infectious peritonitis. Multiple recurrences were reported after initial presentation, and were treated with 1-week courses of amoxicillin/clavulanic acid. Neurological examination did not reveal further findings. Haematology showed neutrophilia/monocytosis. Spinal, limb and thoracic radiographs revealed irregular endplates and narrowing of T12-T13 and L7-S1 intervertebral disc spaces, metaphyseal lesions of multiple long bones with heterogeneous medullary bone and reduced corticomedullary distinction, and two areas of increased opacity in the left lung lobes. Feline leukaemia virus, feline immunodeficiency virus, toxoplasma serology and urine culture were negative. Blood culture was positive for  To our knowledge, this is the first reported case of feline discospondylitis and osteomyelitis caused by ", "journal": "JFMS open reports", "doi": "10.1177/20551169251349741", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40733674", "author": "Carritt K", "n_authors": 9, "title": "A Novel, Safe, Non-Adjuvanted Alphavirus Replicon-Based Vaccine Expressing the Feline Leukemia Virus Envelope Protein Protects Against Virulent FeLV Challenge.", "abstract": null, "journal": "Vaccines", "doi": "10.3390/vaccines13070697", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40723527", "author": "So-In C", "n_authors": 5, "title": "Molecular Detection of Vector-Borne Pathogens and Their Association with Feline Immunodeficiency Virus and Feline Leukemia Virus in Cats from Northeastern Thailand.", "abstract": "In Thailand, domestic cats are frequently exposed to vectors that transmit a variety of pathogens. In this study, the prevalence of vector-borne pathogens (VBPs) and their association with feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) were investigated in 187 domestic cats from animal hospitals across five northeastern provinces. Twelve pathogens, including viruses, bacteria, and protozoa, were screened using PCR assays. FIV was identified in 2.67% of the cats, while FeLV exhibited a notably higher prevalence of 29.95%. Among the bacterial pathogens, ", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani15142065", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40716042", "author": "Westman ME", "n_authors": 7, "title": "Feline leukaemia virus (FeLV) infection in domestic pet cats in Australia and New Zealand: Guidelines for diagnosis, prevention and management.", "abstract": "Progressive feline leukaemia virus (FeLV) infection dramatically shortens the lives of infected cats, causing acquired immunodeficiency, aplastic anaemia, lymphoma, leukaemia and other myeloproliferative diseases. The potential impact of regressive FeLV infection on the development of disease remains largely unknown, although there is evidence it contributes to lymphoma development. Despite a perception that there has been a general decline in the incidence of progressive FeLV infection in Australia and New Zealand, it remains an important health threat and the risk of infection should not be ignored. Clinicians should therefore have a thorough understanding of the complexities surrounding the diagnosis, management and prevention of this disease. Point-of-care (PoC) antigen testing using whole blood is the first step to detect progressive FeLV infection. Clinicians should remember the increased rate of false-positive results using such kits when the disease being detected is at a low prevalence. We therefore advise that confirmatory FeLV polymerase chain reaction (PCR) testing to detect proviral DNA is essential before a PoC-positive cat can be confirmed as being FeLV-infected. Critically, progressively infected cats should not be euthanased because of a positive FeLV diagnosis, as some cats will remain healthy for many years. Regressively infected cats should not be used as blood donors, so blood donor programmes should include FeLV antigen and provirus PCR testing in their standard screening protocols. No cure currently exists for progressive or regressive FeLV infection; therefore, veterinarians should advocate to minimise the exposure of cats to FeLV as a first-line preventative strategy. The most reliable way to achieve this is for cats to be kept indoors, or with secured outdoor access (e.g., cat enclosures and secure gardens). Cats kept in this manner do not require FeLV vaccination. All animal holding facilities should aim to individually house untested adult cats to limit the spread of FeLV infection. For at-risk cats that cannot be kept indoors/enclosed, or for cats that live together with known FeLV-infected cats, vaccination should be undertaken. Two pentavalent vaccines containing inactivated whole-FeLV are currently available in Australia, whereas no FeLV vaccine is currently available in New Zealand. Given the unavailability of monovalent FeLV vaccines, we endorse the use of a pentavalent vaccine in Australia only in FeLV-endemic catteries or in situations where there is a demonstrable and substantial risk of FeLV exposure. Manufacturers are encouraged to reintroduce efficacious monovalent FeLV vaccines in Australia and New Zealand. Further research into potential antiretroviral therapy to treat FeLV infections in cats is needed.", "journal": "Australian veterinary journal", "doi": "10.1111/avj.13470", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40645469", "author": "de Villiers L", "n_authors": 13, "title": "A multi-modal investigation into the prevalence and diagnostic evaluation of vector-borne pathogens and retroviruses in domestic cats throughout Namibia.", "abstract": "Neglected, but economically significant, tropical diseases may be prevalent in domestic cats of Namibia. A multi-centre prevalence field study was conducted across Namibia to assess the distribution of vector-borne pathogens and retroviruses from domestic cats. Samples of blood and serum from 280 cats in 15 towns across eight regions (22-51 cats per region) were analysed. Screening for Ehrlichia, Anaplasma, Babesia, and Hepatozoon species, as well as feline leukaemia virus (FeLV) and feline immunodeficiency virus (FIV), was conducted using light microscopy, point-of-care serology, and quantitative real-time polymerase chain reaction (qPCR) assays. Haematology and serum biochemistry analyses were also performed. Several pathogens were identified in Namibian cats using these diagnostic tools. Comparatively, pathogen detection rates varied by modality, namely light microscopy (5 %), serology (42 %), and qPCR (27 %). More specifically, microscopy revealed an overall prevalence (3 %) for inclusions resembling large Babesia parasites, serology indicated a seroprevalence for FIV antibodies (4 %) and FeLV antigen (40 %), and an overall prevalence determined by qPCR for E. canis (2 %) and H. canis (26 %). The investigation also demonstrated the associations between tick presence, pathogen infection, and disease manifestations in Namibian cats. A particular significant positive association was found between H. canis infection and FeLV antigen seroprevalence (P = 0.005). Overall, the study highlighted the difference of various diagnostic tools for detecting pathogen prevalence in cats. Appropriate diagnostic testing - informed by known associations with disease manifestation - should be key in guiding responsible treatment strategies and evaluating potential zoonotic risks linked to domestic cats of Namibia.", "journal": "Acta tropica", "doi": "10.1016/j.actatropica.2025.107738", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40591622", "author": "Biezus G", "n_authors": 7, "title": "Survival analysis and clinical abnormalities in cats with progressive or regressive feline leukemia virus (FeLV) infection in Brazil.", "abstract": "This study aimed to characterize the clinical presentations and effects of progressive and regressive outcomes of feline leukemia virus (FeLV) infection on the life expectancy of cats. In total, 176 cats were selected: 116 with progressive infection (FeLV+P), 30 with regressive infection (FeLV+ R), and 30 FeLV-negative cats (Control). The cats underwent testing using ELISA to detect the FeLV p27 antigen and nested polymerase chain reaction to identify U3-LTR region and gag proviral DNA. The cats were clinically monitored until their death or for a period ranging 12-54 months. Survival analysis was performed using Kaplan-Meier analysis and Cox regression. The median survival time following FeLV diagnosis was 30 days for the FeLV+P group. The median survival time was not reached for the other groups. The cats' health status (sick) at the time of inclusion in the study and the progression status of the FeLV infection led to a 4-5-fold increase in the Hazard Ratio (HR) for death in the general population. The primary causes of death among cats in the FeLV+P group were lymphoma, leukemia, anemia, and other diseases. In the FeLV+R group, the causes of death included leukemia, anemia, and other diseases. Progressive FeLV infection reduced life expectancy, whereas regressive FeLV infection had no direct impact on the survival curve.", "journal": "PloS one", "doi": "10.1371/journal.pone.0322691", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40567544", "author": "Alves TGL", "n_authors": 10, "title": "Oncolytic potential of Newcastle Disease Virus in feline lymphoma cells: an in vitro evaluation.", "abstract": "Lymphoma is one of the most prevalent types of feline cancer. It is characterized as a group of diseases that can affect various organs, such as the gastrointestinal tract, kidneys, thymus, and skin. In feline medicine, the search for alternative treatments is of utmost importance, given the significant number of animals that relapse or are unresponsive to conventional chemotherapy treatment. As an alternative to existing modalities of treatment for a variety of cancers, oncolytic viruses have been studied in the last few years. Those viruses possess a unique ability to target and eliminate cancer cells while simultaneously stimulating an immune response against malignant cells, acting as an immunotherapy. Newcastle Disease Virus (NDV) is an avian paramyxovirus that affects both domestic and wild birds, causing symptoms that range from severe to asymptomatic, depending on the viral strain. Less virulent strains are considered safe for use as a vaccine against Newcastle Disease. In the Oncology field, those strains are also being studied to be used as oncolytic virotherapy for mammals, and several results demonstrate their efficacy ", "journal": "Frontiers in veterinary science", "doi": "10.3389/fvets.2025.1484947", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40564351", "author": "Cortese L", "n_authors": 9, "title": "Feline Leishmaniosis: A Retrospective Study of Seroprevalence in Cats in the Campania Region, Southern Italy.", "abstract": "Feline leishmaniasis (FeL), caused by ", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani15121801", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40549335", "author": "Dallmann PRJ", "n_authors": 12, "title": "Mycoplasma haemofelis and 'Candidatus Mycoplasma haemominutum' in domestic cats from Pelotas, RS: molecular detection and risk factors.", "abstract": "Hemotropic mycoplasmas are small, pleomorphic, gram-negative, epierithrocytic bacteria that infect a wide variety of animals, including domestic cats. These microorganisms cause the disease known as feline hemotropic mycoplasmosis (MHF), also called feline infectious anemia. The objective of the study was to use PCR assays based on amplification of 16S rDNA to detect the species Mycoplasma haemofelis (Mhf) and 'Candidatus Mycoplasma haemominutum' (CMhm) in felines treated at a clinic specialized exclusively in cats in the city of Pelotas, Rio Grande do Sul. Furthermore, the research aimed to identify potential risk factors associated with the infection. A total of 253 blood samples from domestic felines were analyzed, of which 76 samples (30%) were positive for at least one species. The most detected hemoplasma was CMhm, with 51/253 (20.1%), followed by Mhf, with 23/253 (9.1%). Mhf and CMhm co-infection was detected in 2/253 (0.8%) samples. Felines with access to the street, presence of ectoparasites, co-infection with FeLV, FIV and other diseases (unhealthy animals) were more likely to be infected by hemoplasmas.", "journal": "Brazilian journal of microbiology : [publication of the Brazilian Society for Microbiology]", "doi": "10.1007/s42770-025-01712-y", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40545979", "author": "Úsuga-Monroy C", "n_authors": 7, "title": "Prevalence, Recombination Events, and Risk Factors of FeLV Infection in Domestic Cats from Colombia.", "abstract": "Feline leukemia virus (FeLV) is one of the primary pathogens in domestic felines, causing significant immunosuppression, lymphomas, and even death. Various subtypes of this virus have been described, with FeLV-A being the least pathogenic and the most widely distributed subtype. Conversely, the recombination of FeLV-A with endogenous retroviral sequences has resulted in variant B, which is associated with the development of leukemias and lymphomas. FeLV transmission occurs primarily through grooming between individuals, facilitating its distribution and circulation. The aim of this study was to characterize subtype B and analyze risk factors associated with viral infection in a sample of felines from Colombia. To achieve this, blood samples were taken from the cephalic or jugular veins of 151 felines in four municipalities of Antioquia, and data on age, sex, and area of origin were collected. PCR was performed on a region of the pol gene (306 bp), and only FeLV-positive feline samples underwent a second PCR for the env gene (1400 bp). Only env-positive PCR products were sequenced, and phylogenetic and recombination analyses were performed. Logistic regression was used to calculate the odds ratios (OR) for each variable (age, sex, and area of origin). The overall FeLV positivity rate was 33.77%, with an association found between male sex and FeLV infection (OR = 2.23, p = 0.038), as well as between the area of origin and FeLV infection (OR = 0.22, p = 0.035). Of the total samples, only 11 (7.3%) amplified for FeLV-B, with seven samples from Buriticá and four from Medellín. The recombination analyses confirmed that all sequences belonged to the FeLV-B subtype and were unique recombinants. The molecular presence of the virus in the study area demonstrates that the circulation of this retrovirus remains active. Additionally, the area of origin and male sex are risk factors for FeLV infection. Finally, an increase in FeLV positivity was observed, and while the B variants are generated de novo in each feline, it is crucial to continue health monitoring, especially in regions distant from major urban centers.", "journal": "Veterinaria italiana", "doi": "10.12834/VetIt.3641.31503.1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40534782", "author": "Decrop F", "n_authors": 7, "title": "Case Report: Mycobacterial epidural pyogranulomatous steatitis in a cat.", "abstract": "A 2-year-old neutered male domestic short-haired cat was presented with chronic spinal hyperesthesia and a 24-h acute progression to non-ambulatory, non-painful tetraparesis, consistent with a C1-T2 myelopathy. Physical examination, serum biochemistry, hematology, thoracic and abdominal imaging were unremarkable. Magnetic resonance imaging revealed a well-defined, crescent-shaped, extra-dural, compressive, T2w/T1w/STIR hyperintense contrast-enhancing mass lesion within the dorsal and right lateral vertebral canal, from C2 to cranial C4. Mild mononuclear pleocytosis and increased protein concentration were detected on CSF analysis. Serology for Feline Corona Virus (FeCoV), ", "journal": "Frontiers in veterinary science", "doi": "10.3389/fvets.2025.1610313", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40446426", "author": "Caballero-Gómez J", "n_authors": 13, "title": "Endemic and widespread exposure to Sarcoptes scabiei in the threatened Iberian lynx (Lynx pardinus).", "abstract": "The Iberian lynx (Lynx pardinus) is one of the most endangered feline species in the world, and different infectious diseases, such as feline leukaemia virus, Aujeszky's disease or sarcoptic mange, have long posed a significant threat to its survival. Severe clinical disease caused by Sarcoptes scabiei have been reported in the Iberian lynx, however, the extent of S. scabiei infestations/infections in this species is unknown. In this context, we aimed (1) to assess S. scabiei exposure in Iberian lynx populations, and (2) to identify potential risk factors associated with parasite exposure. Between 2010 and 2023, 615 Iberian lynxes from captive (n = 270) and free-ranging (n = 345) populations were sampled across the Iberian Peninsula. Antibodies against S. scabiei were found in 15.4 % (95/615; 95 %CI: 12.8-18.5) of the Iberian lynxes using an in-house indirect enzyme-linked immunosorbent assay (ELISA) based on the immunodominant recombinant antigen Ssλ20ΔB3. Seropositive individuals were found in the three major free-range areas under study, such as the Central, Southern and Southwestern Iberian Peninsula. A significantly higher seroprevalence was detected in free-ranging (18.0 %) than in captive (12.2 %) lynxes. Logistic regression analysis identified \"age\" and \"free-range sampling area\" as potential risk factors for parasite exposure. Anti-S. scabiei antibodies were detected in lynxes sampled in each year of the study period, except for 2023, including five free-ranging yearlings sampled in 2012, 2019, 2020 and 2022. Our results confirm that both free-ranging and captive populations are naturally exposed to the parasite. The detected seroprevalence indicates moderate S. scabiei exposure of the Iberian lynx and provides evidence of endemic, widespread, and heterogeneous circulation of the parasite in lynx populations over the last two decades, which could be of animal health and even conservation concern. Additional studies are needed to assess the impact of S. scabiei in this vulnerable felid species.", "journal": "Preventive veterinary medicine", "doi": "10.1016/j.prevetmed.2025.106585", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40427361", "author": "Suwannachote T", "n_authors": 4, "title": "A Comparison of Diagnostic Methods for Feline Leukemia Virus and Feline Immunodeficiency Virus: Immunochromatographic Assay and RNases Hybridization-Assisted Amplification Test Kit Compared to Reverse Transcription Quantitative Polymerase Chain Reaction.", "abstract": "Feline leukemia virus (FeLV) and Feline immunodeficiency virus (FIV) are globally prevalent retroviral pathogens that pose significant health risks to domestic cats. This study aimed to compare the diagnostic performance of two point-of-care-the immunochromatographic assay (ICA) and the RNase hybridization-assisted amplification (RHAM) test kit-against reverse transcription quantitative polymerase chain reaction (RT-qPCR), the current gold standard for FeLV and FIV detection. For FeLV detection, ICA demonstrated a sensitivity of 86.89%, specificity of 96.55%, accuracy of 90.00%, and precision of 98.15%, while for FIV detection, the assay showed a sensitivity of 75.86%, specificity of 88.52%, accuracy of 84.44%, and precision of 75.86%. In contrast, the RHAM test exhibited superior performance, with FeLV detection sensitivity of 93.44%, specificity of 98.28%, accuracy of 94.44%, and precision of 98.28%. For FIV detection, RHAM demonstrated a sensitivity of 75.86%, specificity of 100%, accuracy of 92.22%, and precision of 100%. Additionally, the RHAM assay significantly reduced detection time compared to RT-qPCR, enabling expedited clinical decision-making, alleviating laboratory workload, and lowering diagnostic costs. These benefits are particularly relevant in veterinary settings with limited access to PCR-based diagnostics, where the RHAM assay represents a rapid, reliable, and resource-efficient alternative for FeLV and FIV detection.", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani15101484", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40427346", "author": "Puga-Torres B", "n_authors": 3, "title": "Retrospective Analysis of Feline Leukemia Virus (FeLV) Frequency in Domestic Cats in Quito, Ecuador (2021-2024).", "abstract": "Feline leukemia (FeLV) is a viral disease that primarily affects domestic cats (Felis catus), with high mortality rates because it mainly targets the immune system and is also associated with lymphomas. The objective of this study is to retrospectively analyze the prevalence of FeLV in cats treated at veterinary centers in the city of Quito, between September 2021 and December 2024. Data were obtained from diagnostic test results conducted at the Laboratory of Biology and Molecular Genetics (LABIGEN) using RT-qPCR. A total of 850 samples met the inclusion criteria. FeLV was detected in 28.59% (243/850) of samples, with a slightly higher prevalence in males (53.50%) than females (46.50%). Regarding age, 54.32% (132/243) were between 1 and 5 years, 22.22% (54/243) were between 1 and 11 months, 18.52% (45/243) were between 5 and 10 years, and 4.94% (12/243) were between 10 and 19 years. In conclusion, the prevalence of FeLV in Quito, Ecuador, is high, requiring greater efforts to prevent and control this disease, in pursuit of animal health and well-being.", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani15101469", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40422255", "author": "Lee I", "n_authors": 6, "title": "Utilization of Flow Cytometry, Metabolomic Analyses and a Feline Infectious Peritonitis Case Study to Evaluate the Physiological Impact of Polyprenyl Immunostimulant.", "abstract": "Measles, hepatitis C, and COVID-19 are significant human diseases caused by RNA viruses. While vaccines exist to prevent infections, there are a small number of currently available therapeutic agents that can effectively treat these diseases after infection occurs. This study explores a new therapeutic strategy using a small molecule designated polyprenyl immunostimulant (PI) to increase innate immune responses and combat viral infections. Using a multi-disciplinary approach, this study quantifies the effects of PI in mice and THP-1 cells using flow cytometry to identify immune phenotypic markers and mass spectroscopy to monitor the metabolomic profiles of immune cells perturbed by PI treatment. The metabolomic studies identified that sphinganine and ceramide, which are precursors of sphingosine-1-phosphate (S1P), were the common metabolites upregulated in THP-1 and mice blood. Sphingosine-1-phosphate can mediate the trafficking of T cells, whereas ceramide can signal the activation and proliferation of T cells, thereby modulating the mammalian host's immunity. To demonstrate proof-of-principle, a case study was conducted to examine the benefit of administering PI to improve the outcomes of a feline co-infected with two distinct RNA viruses-feline leukemia virus and feline infectious peritonitis virus. Both viruses produce deadly symptoms that closely resemble RNA viruses that infect humans. The results identify quantifiable cellular and metabolic markers arising from PI treatment that can be used to establish a platform measuring the efficacy of PI in modulating the innate immune system.", "journal": "Cells", "doi": "10.3390/cells14100752", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40420390", "author": "Stubbe SP", "n_authors": 5, "title": "High Prevalence of Antigens of and Specific Antibodies Against Various Viral Pathogens in European Wildcats (Felis silvestris) from Southwest Germany, 2020-22.", "abstract": "The recent expansion of the European wildcat (Felis silvestris silvestris) and increasing numbers of domestic cats in Germany are leading to more interactions between domestic cats and wildcats. Not only hybridization, but also the reciprocal transmission of pathogens may occur. This could threaten wildcat populations, or they may act as a reservoir for their domestic relatives. In this study, 102 effusion fluid samples collected from wildcats found dead between 2020 and 2022 in the German federal state of Rhineland-Palatinate were serologically tested for antigens of and specific antibodies against viral pathogens typically found in domestic cats (feline herpesvirus [FHV], feline calicivirus [FCV], feline parvovirus [FPV], feline immunodeficiency virus [FIV], feline coronavirus [FCoV], and feline leukemia virus [FeLV]). Antigens of and/or specific antibodies against at least one virus were detected in 59% of the wildcats. Detected prevalences of specific antibodies against FHV (22.5%), FCV (20.6%), FPV (13.7%), FIV (0%), and FCoV (17.6%) were each 0-22.5%. The prevalence of antigens of FeLV was 28.4%. The high prevalence detected for FeLV antigens possibly shows that wildcats form a reservoir for this virus, as the prevalence in domestic cat populations is significantly lower.", "journal": "Journal of wildlife diseases", "doi": "10.7589/JWD-D-24-00191", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40405898", "author": "Ferrero I", "n_authors": 5, "title": "Feline Leukemia Virus in Cats: A Novel Rapid ELISA Assay for p27 Antigen Detection.", "abstract": "Feline leukemia virus (FeLV) is an oncogenic immunosuppressive virus belonging to the ", "journal": "Veterinary medicine international", "doi": "10.1155/vmi/9914340", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40395123", "author": "Reck J", "n_authors": 8, "title": "Feline Leukemia Virus in Free-ranging Neotropical Wild Felids and in Domestic Cats Found Inside Protected Areas within Rio Grande do Sul, Brazil.", "abstract": "Feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) are retroviruses that cause severe diseases in domestic cats. Recently, they have emerged as a concern for wild felids. The aim of this study was to evaluate the exposure to feline retroviruses in free-ranging Neotropical wild felids from southern Brazil. A total of 48 road-killed wild felids belonging to three species were sampled: Geoffroy's cat (Leopardus geoffroyi), margay (Leopardus wiedii), and Southern tiger cat (Leopardus guttulus). In addition, 28 domestic cats found inside protected areas were investigated. Both the wild and domestic felids were tested for the presence of FeLV and FIV with lateral flow immunoassay (LFA) and molecular methods. Three wild felids (two Geoffroy's cats and one margay) were positive to FeLV by LFA (antigen), PCR (proviral DNA), and quantitative reverse-transcription PCR (viral RNA). From the 28 free-roaming domestic cats sampled inside protected areas, 10 (35%) were positive for FeLV. None of the domestic or wild felids were positive for FIV. In addition to the occurrence of FeLV in two species of free-ranging Neotropical felids, FeLV-positive domestic cats appear to be relatively common in protected areas from southern Brazil, posing an important risk of FeLV transmission to threatened wild felids inside those areas.", "journal": "Journal of wildlife diseases", "doi": "10.7589/JWD-D-24-00136", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40341138", "author": "Ölmedal G", "n_authors": 6, "title": "Prevalence of selected infectious agents in Swedish cats with fever and/or anemia compared to cats without fever and/or anemia and to stable/stray cats.", "abstract": "There are multiple infectious agents of cats around the world; those transmitted by direct contact among cats, hunting, or exposure to fleas or ticks are frequently the most common. Some infectious disease agents have been reported in cats in Sweden; for example, Anaplasma phagocytophilum infection was first reported in a cat in this country. However, there has not been a study in Sweden that reported test results for agents with different transmission cycles in cats with and without signs of clinical disease. Thus, the aims of this study were to (i) investigate prevalence of exposure to Anaplasma species, Bartonella species, Ehrlichia species, haemotropic Mycoplasma species, feline foamy virus (FFV), Felis catus gammaherpesvirus (FcaGHV1), feline immunodeficiency virus (FIV), feline leukemia virus (FeLV) and Toxoplasma gondii in cats residing in the Southern part of Sweden (ii) compare prevalence in samples between 3 groups of cats (cats with fever and/or anemia, cats without any signs of infectious disease, and cats that were either stray cats or stable cats). Overall, antibodies were detected against FcaGHV1 (67%, CI 57-76%), FFV (45%, CI 35-55%), Bartonella species (43%, CI 34-54%), T. gondii (37%. CI 28-47%), and FIV (3.3%, CI 1.1-9.2%). FeLV antigen was detected in one cat (1.1%, CI 0.19-5.9%). Haemotropic Mycoplasma DNA was amplified in seven cats (7.6%, CI 3.7-15%). All five samples with successful sequencing were 'Candidatus M. haemominutum'. The one cat (1.1%, CI 0.19-5.9%) that was positive for B. henselae DNA also had a Bartonella spp. titer of 1:1024. Anaplasma and Ehrlichia spp. DNA were not amplified from any cat. The antibody test results suggest that many of these cats were exposed to other cats (FFV, FcaGHV1, FIV, FeLV), had inadequate flea control (Bartonella spp.), and were fed undercooked meat or allowed to hunt (T. gondii). While infection was common, the only haemotropic Mycoplasma amplified from these cats was the relatively non-pathogenic 'Candidatus M. haemominutum'. As previously documented for each of these agents, the presence of a positive test result or infection by one or more organisms is not always associated with illness.", "journal": "Acta veterinaria Scandinavica", "doi": "10.1186/s13028-025-00807-8", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40320184", "author": "Yasujima T", "n_authors": 12, "title": "The role of FLVCR1 and FLVCR2 in choline transport in the Caco-2 intestinal epithelial cell model and rat small intestine.", "abstract": "Choline is a vital cationic nutrient for maintaining organismal homeostasis, partially synthesized in the liver but primarily obtained from dietary sources. While previous studies have explored mechanisms of choline absorption in intestinal cells, the precise roles of specific transporters remain to be fully elucidated. This study aimed to investigate the roles of the choline transporters feline leukemia virus subgroup C receptor 1 (FLVCR1) and FLVCR2. Using MDCKII cells expressing human FLVCR1 or FLVCR2, the study revealed that FLVCR1 facilitates choline efflux from the basolateral membrane, while FLVCR2 enables choline uptake through the apical membrane. Functional analyses of FLVCR1 and FLVCR2 variants identified mutations that significantly reduce choline uptake activity. Knockdown experiments in Caco-2 cells resulted in significantly reduced cellular uptake of choline. Functional analysis of choline transport in the everted tissue sacs of the rat small intestine suggested that Flvcr2 aids intestinal choline uptake. Conclusively, the findings of this study indicate that FLVCR1 and FLVCR2 work cumulatively to regulate intestinal choline absorption. These findings provide novel insights into the roles of FLVCR1 and FLVCR2 and offer bases for further research into choline transport mechanisms in the small intestine.", "journal": "Biochimica et biophysica acta. Molecular basis of disease", "doi": "10.1016/j.bbadis.2025.167883", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40293160", "author": "Vásquez-Domínguez E", "n_authors": 5, "title": "IFPTML Multi-Output Model for Anti-Retroviral Compounds Including the Drug Structure and Target Protein Sequence Information.", "abstract": "Retroviruses such as HIV cause significant diseases in humans and other organisms, making the discovery of antiretroviral (ARV) drugs a critical priority. While databases like ChEMBL contain valuable information, their complexity poses challenges. The data set includes approximately >140,000 assays across eight viruses, encompassing >350 biological activity parameters, >50 target proteins, >80 cell lines, >60 assay organisms, and >770 viral strains. Artificial Intelligence/Machine Learning (AI/ML) models offer a promising approach to accelerate ARV discovery. Recently, we developed AI/ML models for ChEMBL ARV data using the Information Fusion Perturbation Theory and Machine Learning (IFPTML) strategy. However, neither existing AI/ML models nor our prior IFPTML implementation simultaneously incorporates viral protein sequences, strains, cell lines, assay organisms, or virus/human mutations. This limitation renders them ineffective for predicting activity against amino acid sequence variations (e.g., mutations, variants, or emerging strains)─a critical shortcoming given the well-documented prevalence of drug-resistance mutations in marketed ARVs. In this work, we present an enhanced IFPTML model integrating protein sequence descriptors. We computed and incorporated sequence descriptors for all drug target proteins in ChEMBL, derived from proteomes of retroviruses (HIV, FeLV, MMV, SIV, etc.). The model demonstrated robust performance, with sensitivity (Sn), specificity (Sp), and accuracy (Ac) values ranging between 72.0 and 88.0% in both training and validation phases. We analyze its predictions for protein mutations documented in ChEMBL and other literature sources. To our knowledge, this represents the first unified multicondition, multioutput model for ARV discovery that systematically accounts for protein sequence information.", "journal": "Journal of chemical information and modeling", "doi": "10.1021/acs.jcim.5c00242", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40255021", "author": "Aung HPP", "n_authors": 7, "title": "PCR testing of conjunctival swabs to detect feline leukaemia virus in domestic cats in Thailand.", "abstract": "This study aimed to classify the Feline leukaemia virus (FeLV) infection outcomes in domestic cats in Thailand and determine the accuracy of conjunctival swabs for FeLV proviral DNA detection by comparing results to PCR testing of blood samples. Whole blood and conjunctival swabs were collected from 126 cats with and without clinical signs. Blood specimens were evaluated for p27 FeLV antigen using the SNAP Feline Immunodeficiency Virus (FIV)/FeLV Combo Test, IDEXX Laboratories. The 3'-LTR region of the proviral FeLV was amplified from both blood and conjunctival samples. The prevalence rates of progressive and regressive FeLV infections in this study were 14.3% (95% CI: 8.69-21.63) and 36.5% (95% CI: 28.12-45.55), respectively. Cats older than 12 months of age had a higher probability of being regressively infected than cats younger than 1 year (", "journal": "The veterinary quarterly", "doi": "10.1080/01652176.2025.2488025", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40231602", "author": "Sánchez-Vallejo M", "n_authors": 3, "title": "Feline chronic gingivostomatitis: a thorough systematic review of associated factors.", "abstract": "ObjectivesThe aim of the present study was to systematically compile and analyze the available evidence from studies that have explored factors associated with feline chronic gingivostomatitis (FCGS).MethodsAn electronic search was conducted using four databases (OVID/MEDLINE, PubMed, SciELO, Redalyc), as well as proceedings from the European Veterinary Dentistry Forum and the Veterinary Dental Forum, when available. The inclusion and exclusion criteria were predetermined and maintained throughout the systematic process, focusing exclusively on articles published in peer-reviewed journals.ResultsA total of 17 articles met the definitive inclusion criteria. All were published in English, in 11 journals, and between 1984 and 2023. The relevant articles reported a global frequency of FCGS of 10.9% (747/6881 cats). Six studies reported the exploration of factors inherent to the cat (eg, age, sex, reproductive status), two reported the exploration of factors related to the cats' environment, feeding and management (eg, type of confinement, number of cats in the household, vaccination status) and 15 reported the exploration of factors related to infectious agents (eg, feline calicivirus [FCV], feline leukemia virus [FeLV], feline herpesvirus type 1 [FHV-1], ", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X241310590", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40155393", "author": "Chin PJ", "n_authors": 15, "title": "Virus detection by short read high throughput sequencing in a high virus low cellular background.", "abstract": "The safety of all biological products includes demonstrating the absence of adventitious viruses by testing various types of samples at different stages of the manufacturing process. Seven laboratories evaluated short-read high-throughput sequencing (HTS) for sensitivity and breadth of adventitious virus detection using viruses with distinct physicochemical and genome properties. These five viruses are currently designated as CBER NGS Virus Reagents and include: Epstein-Barr virus (EBV; or human herpes virus 4), feline leukemia virus (FeLV), respiratory syncytial virus (RSV), mammalian orthoreovirus type 1 (Reo1), and porcine circovirus type 1 (PCV1). To evaluate adventitious virus detection in a biological material with a high production virus titer and low cellular background, the 5 viruses were mixed and different copies of the viral genomes spiked into 1 - 5 × 10", "journal": "NPJ vaccines", "doi": "10.1038/s41541-025-01104-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40147381", "author": "Chen MC", "n_authors": 11, "title": "Domestic cat hepadnavirus is detected infrequently in feline blood and liver samples submitted for diagnostic testing in Texas, USA.", "abstract": "Domestic cat hepadnavirus (DCH), a novel hepatitis B-like virus, has been detected in cats in several regions but data are fragmented. Investigation of DCH is driven by the societal role of cats as human companions, disease risk to sympatric endangered felids, as well as HBV medicine. This study investigated the molecular epidemiology and sequence diversity of DCH in diagnostic blood or non-paired liver samples submitted in Texas. Patient age, sex, breed, neuter status, and retrovirus serology results were recorded for risk factor analyses. Using qPCR, DCH DNA was amplified from 3/400 blood samples (0.8 % (95 % CI: 0.3-2.2 %) with virus loads of 4.06 × 10", "journal": "Virology", "doi": "10.1016/j.virol.2025.110506", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40133929", "author": "de Almeida PM", "n_authors": 5, "title": "Prevalence and genetic characterization of feline leukemia virus in portuguese stray cats.", "abstract": "With its large stray population, Portugal had the highest prevalence of the Feline Leukemia Virus (FeLV) infection in Europe. Progressive infection is still high, especially in southern Europe. In addition to the viral load, the subgroup is a determining factor in the development of the various syndromes associated with this disease, which can be fatal, justifying the morbidity and mortality of this retrovirus. The aim of the study was to determine the prevalence of FeLV, the viral load and to identify the subgroup of circulating virus in stray cats in the Lisbon metropolitan area. This prospective study was conducted at the Veterinary Teaching Hospital of the FMV-ULusófona, from November 2022 to January 2023. Blood samples from 129 stray cats from the Lisbon metropolitan area were included. All samples were tested for p27 antigen detection and proviral DNA by qPCR. For the detection of FeLV subgroups (A, B and C) nested PCR was performed. The results showed that at the time of enrollment, 8.5% (n = 11/129) of the cats tested positive for FeLV using p27 antigen and qPCR for proviral DNA. Considering the proviral DNA load, 90.9% (n = 10/11) of the FeLV infections were classified as \"likely progressive infection\" (> 4.0 × 10 To the best of our knowledge, this is the first study to research FeLV subgroups in Portugal. The prevalence of FeLV in this group was consistent with our expectations. However, the molecular characterization differed significantly from that observed in other countries. These results suggest that stray cats may not be the main epidemiological concern.", "journal": "BMC veterinary research", "doi": "10.1186/s12917-025-04691-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40005849", "author": "Ferrero I", "n_authors": 5, "title": "A New Rapid Indirect ELISA Test for Serological Diagnosis of Feline Immunodeficiency.", "abstract": "The Feline Immunodeficiency Virus (FIV) is a lentivirus belonging to Retroviridae family that affects feline immune cells, causing a progressive immunosuppression by depleting CD4+ T-lymphocytes, similarly to the acquired immune deficiency syndrome (AIDS) in humans caused by human immunodeficiency virus (HIV). Diagnosis is usually performed by clinicians using rapid Enzyme-Linked Immunosorbent Assay (ELISA) or lateral flow tests that detect FIV antibodies. The aim of this work was the development of FIVCHECK Ab ELISA, a new rapid indirect assay for the detection of FIV antibodies in feline serum/plasma samples; FIVCHECK Ab ELISA was developed after a meticulous set-up and cut-off analysis through several methods, including the Youden's index and ROC curve, to achieve the best test performance. The new kit was validated by testing 115 feline sera (38 positives and 77 negatives for FIV antibodies) against the ELISA rapid test SNAP FIV/FeLV Combo (IDEXX). Moreover, 103 sera (28 positives and 75 negatives) were also analyzed with two other rapid indirect ELISAss, INgezim FIV (Gold Standard Diagnostics) and VetLine FIV (NovaTec); FIVCHECK Ab ELISA agreed at 100% with SNAP (100% sensitivity, 95% confidence interval (CI): 88.5-100%; 100% specificity, 95% CI: 94.0-100%), 100% with INgezim FIV and 92.2% with VetLine FIV. Intra- and inter-assay accuracy and precision gave coefficients of variation lower than 10%. The new ELISA is a simple and quick test that provides reliable results for veterinary clinics and practices.", "journal": "Veterinary sciences", "doi": "10.3390/vetsci12020089", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "39988085", "author": "Dos Santos JR", "n_authors": 9, "title": "Characterization of Rhodococcus equi isolated from pyogranulomatous lesions in cats from Brazil.", "abstract": "This study aimed to describe and provide a laboratory characterization of three cases of Rhodococcus equi isolates from pyogranulomatous lesions in domestic cats in Brazil, collected between 2015 and 2021. Swabs and aspirates from nodular skin lesions located in the abdominal region (Case 1) and thoracic limbs (Cases 1-3) were subjected to microbiological culture, biochemical and molecular analyses, evaluation of biofilm formation capacity, and antimicrobial sensitivity testing. Cats 1 and 2 were positive for FeLV p27 antigen on SNAP testing. Cat 1 died at home from complications of Rhodococcus infection, and Cat 2 was euthanized following failure of medical and surgical treatment of infection. The cat in Case 3, which was FeLV-negative, received treatment with oral erythromycin and topical rifampicin for 30 days. However, due to failure of antimicrobial therapy to resolve the lesions, the cat underwent amputation of the affected right hindlimb. R. equi, positive for the plasmid-encoded virulence-associated protein A, was identified on the microbiological cultures and PCR from all cases. Biofilm formation analysis categorized all three isolates as weak biofilm formers. Additionally, antimicrobial susceptibility testing revealed that all isolates were sensitive to azithromycin, clarithromycin, erythromycin, imipenem, and rifampicin in vitro. These findings underscore the clinical, epidemiological, and laboratory characteristics of R. equi infection in Brazilian cats, indicating that these microorganisms are phenotypically and molecularly similar to those isolated from horses.", "journal": "Topics in companion animal medicine", "doi": "10.1016/j.tcam.2025.100962", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "39965620", "author": "Arbeitskreis kleine Haustiere der Ständigen Impfkommission Veterinärmedizin (StIKo Vet)", "n_authors": 1, "title": "[Guidelines for the vaccination of small animals - 6th edition].", "abstract": "Vaccination is one of the most important measures for preventing infectious diseases. The basic immunization of puppies is particularly important, because the development of robust, active immunity in the young has a positive effect on the health and constitution of the entire later life. Maternal antibodies can seriously interfere with the success of the vaccination by neutralizing the administered vaccine antigen - especially with live vaccines. The higher the levels of these antibodies, the longer they may prevent successful induction of active immunity. The level of these antibodies is usually unknown. Therefore, repeated vaccinations during the first months of life keep the time window, in which maternal antibodies have declined and no active immunity has been developed, as short as possible.In dogs, vaccinations against distemper, parvovirosis and leptospirosis are considered core vaccinations. The use of tetravalent leptospirosis vaccines is highly recommended. The attenuated live components against distemper and parvovirus should be administered to puppies in week 8, 12 and 16. Since the leptospirosis component is inactivated and is as much affected by maternal antibodies, it is sufficient to administer the leptospirosis vaccination in week 8 and 12. A vaccination against distemper, parvovirus and leptospirosis at the age of 15 months completes the basic immunization. In addition to the core components mentioned, vaccines against pathogens of the Canine Infectious Respiratory Disease Complex (CIRDC) (formerly: kennel cough complex), against canine herpes viruses, dermatophytoses, Lyme borreliosis and Leishmaniasis are approved for dogs. The use of these vaccines can be highly advisable depending on the individual risk of infection. For cats, vaccinations against panleukopenia and against feline herpes- and caliciviruses are considered core vaccinations. Kittens should be vaccinated against all three components in week 8, 12 and 16. A vaccination against all three components at 15 months of age completes the basic immunization. For cats, vaccinations against bordetella and chlamydia infections, against dermatophytoses and against infections with the feline leukemia virus are considered non-core. Immunization against feline infectious peritonitis is not recommended. Ferrets should be vaccinated against distemper. Rabies has been eradicated in Germany. The vaccination is therefore no longer considered a core vaccination. However, susceptible pets, i.e. dogs, cats and ferrets, that are moved within the EU or taken across the border to or from third countries must be vaccinated against rabies. Rabbits should be vaccinated against myxomatosis and rabbit hemorrhagic disease.", "journal": "Tierarztliche Praxis. Ausgabe K, Kleintiere/Heimtiere", "doi": "10.1055/a-2501-5778", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "39957497", "author": "Abdullah S", "n_authors": 7, "title": "An exceptional case of peritoneal cystic echinococcosis in a domestic cat in Australia.", "abstract": "A case of peritoneal cystic echinococcosis (CE) in a domestic cat was reported from Queensland, Australia. Physical examination of the cat indicated a large, distended abdomen, which when palpated appeared to be fluid-filled. Ultrasonography showed numerous cysts with hyperechoic walls and anechoic contents within the cat's abdominal cavity. Whole mount microscopy and histology, together with molecular identification of the contents based on mitochondrial DNA gene sequencing indicated that the causative agent was Echinococcus granulosus (sensu stricto) (genotype G1). Moreover, the cat was also found infected with Feline Leukemia Virus (FeLV). It is surmised that FeLV-induced immunosuppression could have led to the development of CE in this cat. This is the first report of CE in a FeLV infected cat in Australia.", "journal": "Australian veterinary journal", "doi": "10.1111/avj.13427", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "39909190", "author": "Carbonara M", "n_authors": 17, "title": "Dirofilaria spp. infection in cats from the Mediterranean basin: diagnosis and epidemiology.", "abstract": "Dirofilaria immitis and Dirofilaria repens, causing heartworm disease and subcutaneous dirofilariosis, respectively, are zoonotic mosquito-borne filarioids infecting a plethora of hosts including cats. Only fragmented data are available on the diagnosis and epidemiology of feline dirofilariosis. We assessed the occurrence of both nematode infections, their risk factors and clinicopathological abnormalities in cats, from six countries of the Mediterranean Basin. In addition, Wolbachia spp. endosymbionts were assessed in Dirofilaria spp.-positive animals. Blood and sera samples were obtained from cats with outdoor access from Spain (n = 354), Portugal (n = 287), Italy (n = 125), Greece (n = 116), Israel (n = 101) and France (n = 100). Cat sera were tested by both direct antigenic (SNAP test, commercial ELISA kit) and indirect antibodies (in-house ELISA) serological tools, and blood samples by real time and conventional PCR targeting Dirofilaria spp. DNA, followed by sequencing. A statistical analysis was run to assess the link between Dirofilaria spp. infection and independent variables, as well as among feline immunodeficiency virus (FIV) and/or feline leukaemia virus (FeLV) co-infections, and clinicopathological abnormalities. Overall, 3.8% (i.e., 41/1,083) cats scored positive for Dirofilaria spp. infection with prevalences ranging from 2% in Israel to 7.8% in Greece. Of the 41 positive cats, 16 were infected by D. immitis (by SNAP test and/or PCR) and two by D. repens (by PCR); the remaining animals were antibody-positive for Dirofilaria spp. using the in-house ELISA. Wolbachia DNA was detected in one D. immitis-infected cat. Nematode positivity was significantly associated with age, breed, hyporexia, dandruff, and dyspnoea. This study provides data on the prevalence of Dirofilaria spp. infection in cats from the Mediterranean Basin, as well as new insights on its diagnosis, revealing the importance of performing strategic chemoprophylactic treatments for cats living in areas where the infection is endemic in dogs.", "journal": "International journal for parasitology", "doi": "10.1016/j.ijpara.2025.01.011", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "39820985", "author": "Garcia TS", "n_authors": 11, "title": "First report of a cat (Felis catus) infected by Leishmania (Viannia) guyanensis from Southeastern Brazil.", "abstract": "Feline leishmaniasis is increasingly recognized as a disease affecting cats worldwide, with notable prevalence in regions surrounding the Mediterranean Basin and in Brazil. An approximately one-year-old domestic shorthair cat was presented with small papules and nodules (2 mm) on the nasal planum. Physical examination and routine blood analyses were normal. The cat tested negative for FIV and FeLV. Skin biopsies of the lesions were conducted, removing the nodules entirely due to their small size. The samples were submitted for histopathological and molecular analysis. Histopathology confirmed the presence of Leishmania amastigotes, while PCR-RFLP and Sanger sequencing of the hsp70 gene identified the infecting species as Leishmania guyanensis. The patient has since been under continuous clinical monitoring every six months, with no recurrence observed to date. This is the first documented case of L. guyanensis infection in a domestic cat, underscoring the need for improved diagnostic accuracy and a broader understanding of feline leishmaniasis.", "journal": "Veterinary research communications", "doi": "10.1007/s11259-025-10647-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "39817776", "author": "Petch RJ", "n_authors": 13, "title": "Erratum for Petch et al., \"Feline Leukemia Virus Frequently Spills Over from Domestic Cats to North American Pumas\".", "abstract": null, "journal": "Journal of virology", "doi": "10.1128/jvi.02169-24", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "39647437", "author": "de Mello LS", "n_authors": 10, "title": "Feline immunodeficiency virus (FIV): Prevalence, risk factors, and clinical findings in domestic cats (Felis catus) from southern Brazil.", "abstract": "Feline immunodeficiency virus (FIV) is a retrovirus affecting domestic cats worldwide and causing immunosuppression and reduced quality of life. The prevalence of FIV infection varies according to geographic regions / countries and it is associated with domestic cat health managements (vaccination, neutering, basic health care, etc.). This study aimed to evaluate prevalence, risk factors and some clinical information of FIV infection in a domestic cat population in southern Brazil. A total of 366 cats from ten different veterinary facilities and 43 neighborhoods located in the city of Caxias do Sul were sampled for this study. Each animal was examined by a clinical veterinarian and blood was collected for laboratory analysis. Blood samples were tested with a point-of-care (POC) assay to detect FIV antibodies and a real-time polymerase chain reaction (qPCR) to detect and quantify FIV proviral DNA. The results demonstrated an overall prevalence of 7.1 % (n = 26; 95 % CI = 4.9 % - 10.2 %) of FIV infection. FIV-positive cats demonstrated undetectable (n = 6; 23.1 %) and detectable (n = 20; 76.9 %) proviral DNA, with loads varying from less than 10 (10", "journal": "Comparative immunology, microbiology and infectious diseases", "doi": "10.1016/j.cimid.2024.102285", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "39566539", "author": "Walton D", "n_authors": 6, "title": "Monitoring Seroprevalence of Infectious Diseases in the Florida Panther (Puma concolor coryi).", "abstract": "Infectious diseases can have detrimental effects on wildlife populations, particularly those that persist at small sizes, have low genetic diversity, and are affected by fragmented habitat. One such example is the endangered Florida panther (Puma concolor coryi), which has been intensively managed since the early 1980s, with the current population ranging between 120 and 230 individuals. For more than three decades, panthers have been captured, demographics recorded, and blood samples collected to monitor for multiple infectious diseases; however, an updated comprehensive study of many of these pathogens has not occurred since 1991. Our goal was to identify temporal patterns and spatial clustering in seroprevalence; determine if the pathogens of interest tend to co-occur; and describe relationships between an individual's genetic assignment (admixed or canonical) and seropositivity. We analyzed serology data for eight pathogens representing different modes of transmission (direct, indirect, vector borne) and infection duration (acute, chronic) from 232 panthers collected between 1992 and 2017. Panthers held consistently high seropositivity for feline calicivirus (62.3%) and panleukopenia virus (79.7%) throughout the study, whereas feline herpesvirus and feline leukemia virus were at lower prevalence (3.1% and 2.4%, respectively), although neither had been noted prior to 1992. Panthers were frequently seropositive for canine distemper virus and feline immunodeficiency virus, and seroprevalence fluctuated through time. West Nile virus seropositivity increased over the study period following its introduction in North America in 1999. Panthers were consistently negative for feline coronavirus, which causes feline infectious peritonitis. Genetics and demographics (sex and age) had little influence on serostatus, and coexposure among pathogens did not tend to occur. Both feline immunodeficiency virus and feline leukemia virus appeared to have spatial clusters of seropositive individuals. Our findings enhance the understanding of pathogen exposure in panthers, informing and supporting ongoing surveillance efforts for timely detection and management of potential disease threats in vulnerable populations.", "journal": "Journal of wildlife diseases", "doi": "10.7589/JWD-D-24-00057", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "39397195", "author": "Tessmann A", "n_authors": 13, "title": "Domestic cat hepadnavirus genotype B is present in Southern Brazil.", "abstract": "Domestic cat hepadnavirus (DCH) (Orthohepadnavirus felisdomestici) is an emerging virus related to the hepatitis B virus (HBV) already reported in many countries. The molecular prevalence of DCH varies widely in the regions investigated so far. In the present work, we reported the presence of DCH in Brazil. Sixty cat serum samples tested by DCH presence using PCR and 1.67% (1/60) were positive, similar to the low positive molecular rates reported in United States and Japan. The DCH full-length genome was classified in genotype B, which is uncommon since this genotype was only reported once in Japan. The DCH-positive sample was obtained in a stray cat female apparently healthy, presenting ALT, AST, and ALKP normal values, and negative for FIV and FeLV. Due the low positivity rate detected, some factors as alteration in hepatic enzymes and FIV/FeLV infection could not be evaluated. Other works are necessary to statistically validate these observations in Brazil.", "journal": "Virus genes", "doi": "10.1007/s11262-024-02115-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "39071413", "author": "Swapna GVT", "n_authors": 4, "title": "Memorization Bias Impacts Modeling of Alternative Conformational States of Symmetric Solute Carrier Membrane Proteins with Methods from Deep Learning.", "abstract": "Conformational memorization impacts the performance of AlphaFold in modeling the dynamic structures of proteins. The Solute Carrier (SLC) superfamily of integral membrane proteins transport a wide array of small molecules across plasma and organelle membranes, and function as important drug transporters and as viral receptors. They populate different conformational states during the solute transport process, including outward-open, intermediate (occluded), and inward-open conformational states. For some SLC proteins this structural \"flipping\" corresponds to swapping between conformations of their N-terminal and C-terminal symmetry-related sub-structures. Conventional AlphaFold2, AlphaFold3, or Evolutionary Scale Modeling methods typically generate models for only one of these multiple conformational states of SLC proteins. While several AI-based protocols for modeling multiple conformational states of proteins have been described recently, these methods are often impacted by \"memorization\" of one of the alternative conformational states, and do not always provide both the inward- and outward-open conformations of SLC proteins. Here we assess the impact of memorization in modeling SLC proteins with AlphaFold, and describe a combined ESM - template-based-modeling process, based on a previously described template-based modeling method that relies on the internal pseudo-symmetry of many SLC proteins, to consistently model the alternate conformational states of SLC proteins. We also demonstrate how the resulting multi-state models can be validated experimentally by comparison with sequence-based evolutionary co-variance data (ECs) that encode information about contacts present in the various conformational states adopted by the protein. This simple, rapid, and robust approach for modeling conformational landscapes of pseudo-symmetric SLC proteins is demonstrated for several integral membrane protein transporters, including SLC35F2 the receptor of a feline leukemia virus envelope protein required for viral entry into eukaryotic cells.", "journal": "bioRxiv : the preprint server for biology", "doi": "10.1101/2024.07.15.603529", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "38800883", "author": "Reis Ribeiro P", "n_authors": 9, "title": "Diffuse large B-cell lymphoma affecting the third eyelid of two young adult FeLV-infected cats.", "abstract": "Lymphoma is one of the most frequently diagnosed tumors in FeLV-infected cats. Extranodal lymphomas include lymphomas in ocular and periocular tissues, such as the third eyelid (TEL), which is an uncommonly diagnosed type of lymphoma in cats. This study aimed to describe the clinicopathological features of lymphoma in the TEL of two FeLV-infected cats. A retrospective study in two anatomic pathology laboratories was performed, and two cases met the inclusion criteria. A 4-year-old, female cat (case 1), positive for FIV gp40 antigen and FeLV gp70 antigen by immunohistochemistry (IHC), and a male cat of 22 months old (case 2), positive both serologically for FeLV p27 antigen and for FeLV gp70 antigen by IHC, were referred to veterinary clinics with unilateral swelling and mass in the TEL, which had rapid growth in case 2. Histological and immunohistochemical analysis established the final diagnosis of diffuse large B-cell lymphoma in both cases. The cat in case 2 died 4 months after the diagnosis, with clinical worsening prior to death. Necropsy was not performed in either case, which precluded the definition of a primary or secondary involvement. However, the ocular lesions were the reason for consultation in both cases and it may have been an initial manifestation of a multicentric disease. Thus, FeLV-infected cats with clinical finding of eyelid swelling or mass formation should have lymphoma as a differential diagnosis, and a complete physical examination should be performed to detect extraocular involvement.", "journal": "Veterinary ophthalmology", "doi": "10.1111/vop.13241", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42750065", "author": "Safwat MS", "n_authors": 16, "title": "Clinical insights into Candidatus Mycoplasma haemominutum-associated anaemia in naturally infected cats: flea-associated risk and paradoxical clinicopathological findings.", "abstract": "The specific pathophysiological drivers and host-pathogen-environment factors that dictate the pathogenicity of Candidatus Mycoplasma haemominutum (CMhm) remain poorly defined, hindering accurate clinical interpretation and effective disease control. This study provides detailed mechanistic insights into CMhm-associated anaemia in naturally infected cats by integrating analyses of concurrent diseases and comprehensive clinicopathological panels, alongside molecular characterisation in an under-represented region. Two groups of CMhm-infected cats (anaemic, n = 13; non-anaemic, n = 25) were systematically screened for 14 concurrent infectious, metabolic, or endocrine conditions, alongside extensive haematological, biochemical, and iron profile assessments. Multivariable logistic regression identified independent risk factors, while CMhm molecular diversity was assessed using 16S rRNA gene sequencing. Multivariable analysis identified flea infestation as the sole significant driver of anaemia (OR 7.77; P = 0.04), underscoring a key vector-trigger role and contributing evidence to the ongoing debate on CMhm's flea-borne transmission. Although specific conditions such as feline immunodeficiency virus, feline leukaemia virus, Mycoplasma haemofelis, Candidatus Mycoplasma turicensis, and hyperglycaemia were not statistically significant, they may still be biologically relevant. Notably, most cats in the non-anaemic group also had comorbidities, suggesting that disease stage or severity may be more critical than mere presence. Supporting this, the anaemic group showed significantly lower lymphocyte counts and a downward trend in other leucocytes. Anaemia appeared deceptively normocytic-normochromic and non-regenerative despite ongoing CMhm-induced haemolysis, indicating additional counteracting mechanisms. Detailed clinicopathological and concurrent disease investigations pointed to true iron deficiency (flea-related) and functional iron deficiency (inflammatory comorbidities) as contributors. The coexistence of these three opposing pathophysiological processes shaped the paradoxical haematological and iron profile. Molecular analysis identified three CMhm nucleotide sequence types (nSTs) new to the region. The results of this study suggest that CMhm-associated anaemia is likely a secondary condition, in which environmental triggers and host immune status shape disease manifestation. This study elucidates the complex pathophysiological mechanisms underlying anaemia, providing insights to enhance clinical diagnosis and inform control strategies.", "journal": "Irish veterinary journal", "doi": "10.1186/s13620-026-00359-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42712251", "author": "Jobbins SE", "n_authors": 6, "title": "Performance of point-of-care tests for diagnosing feline immunodeficiency virus infection in captive African lions (Panthera leo).", "abstract": "Point-of-care (PoC) antibody (Ab) testing forms an integral component of feline immunodeficiency virus (FIV) diagnosis in both domestic and non-domestic felids, with test kits designed for use in domestic cats frequently extrapolated for use in their wild counterparts. The SNAP® FIV/FeLV Combo lateral flow ELISA is commonly used to assign FIV infection status in wild and captive African lions (Panthera leo). The aim of this study was to investigate the performance of four other commercially available PoC FIV antibody test kits in African lions held in Australian zoos, when compared to SNAP® as a quasi-reference test. To first validate the use of SNAP®, a subset of samples from SNAP® FIV-positive (n = 3) and SNAP® FIV-negative (n = 23) lions were evaluated with Western blotting, with perfect agreement demonstrated (Cohen's kappa coefficient = 1). Forty-eight serum samples from SNAP® FIV-positive (n = 16) and SNAP® FIV-negative (n = 32) lions were then assessed with Anigen Rapid®, Witness®, VetScan® Rapid and SensPERT® FIV Ab tests. No seropositivity was observed in FIV-infected lion sera using Anigen Rapid® or Witness® (Se 0%, Sp 100%), which utilise domestic cat FIV (FIV-Fca) transmembrane glycoprotein gp40 as their capture antigen. In contrast, VetScan® Rapid, which employs FIV-Fca capsid protein p24 as its capture antigen, demonstrated excellent performance (Se 100%, Sp 96.9%). The presence of p24 as a capture antigen did not guarantee the performance of an assay, as SensPERT®, which also features p24 as its capture antigen, was significantly less sensitive than VetScan® Rapid (Se 25%, Sp 100%; p < 0.001). Our findings have important implications for captive threatened felids, where timely, accurate diagnosis and careful management are critical for minimising retroviral transmission. We recommend using SNAP® or VetScan® Rapid FIV Ab tests for accurate diagnosis of FIV infection in African lions; however, the original VetScan® Rapid FIV test has been unavailable in Australia since 2019.", "journal": "Australian veterinary journal", "doi": "10.1111/avj.70137", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42641070", "author": "Ploypetch S", "n_authors": 8, "title": "Serum peptidomic profiling identifies systemic JAK-STAT and PI3K-Akt pathway dysregulation in cats with chronic gingivostomatitis.", "abstract": "Chronic gingivostomatitis in cats is a debilitating inflammatory disease marked by severe oral pain and systemic immune dysregulation. Although localized oral pathology is well-documented, the systemic peptidomic profile remains largely unclear. Characterize the serum peptidomic profiles of cats with feline chronic gingivostomatitis (FCGS) and identify systemic biomarkers and signaling hubs that drive disease pathogenesis and therapeutic interactions. Client-owned cats with clinically and histopathologically confirmed FCGS (n = 34) and healthy controls (n = 18). A case-control, cross-sectional study was conducted. All cats were screened for feline leukemia virus, feline immunodeficiency virus, and feline heartworm infections. Serum samples were analyzed using matrix-assisted laser desorption/ionization-time-of-flight mass spectrometry (MALDI-TOF MS) to produce peptide mass fingerprints. Detailed peptide identification was conducted using nanoscale liquid chromatography-tandem mass spectrometry (nano LC-MS/MS). Functional enrichment and protein-protein/chemical interaction networks were developed using ShinyGO and the Kyoto Encyclopedia of Genes and Genomes database. Both MALDI-TOF MS and nano LC-MS/MS identified distinct systemic protein signatures that distinguished FCGS from controls. Fifteen proteins showed significant changes, with 13 increased (including inflammatory markers such as interleukin (IL)-6 and interferon-γ) and 2 decreased (gastrin, IL-18). Network analysis identified 8 key proteins (eg, p21(CDKN1A), CASP1, IL-6) that interact with FCGS drug treatments. These systemic changes focus on the Janus kinase-signal transducers and activators of transcription (JAK-STAT) and phosphatidylinositol 3-kinase (PI3K)/protein kinase B (AKT; PI3K-Akt) pathways, which are important therapeutic targets. Our study provides a molecular framework for FCGS. Whereas MALDI-TOF MS enables rapid systemic profiling, nano LC-MS/MS identifies key dysregulated pathways, specifically IL-6/JAK-STAT and PI3K-Akt. These findings offer potential therapeutic targets and a basis for monitoring molecular pathology in affected cats.", "journal": "Journal of veterinary internal medicine", "doi": "10.1093/jvimsj/aalag169", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42634285", "author": "Sato M", "n_authors": 5, "title": "Acute Myeloid Leukemia With Suspected Basophilic Differentiation in a Cat Negative for Feline Leukemia Virus.", "abstract": "An 8-year-old spayed female domestic shorthair cat presented with anorexia and weight loss. A complete blood count revealed mild nonregenerative anemia, circulating blasts, dysplastic granulocytes, and basophilia. Both feline leukemia virus (FeLV) and feline immunodeficiency virus tested negative upon SNAP testing using peripheral blood and PCR using bone marrow. Bone marrow aspiration revealed an increased number of blast cells and basophils, and some blast cells were positive for MPO staining. Based on the basophilic lineages observed in the peripheral blood and bone marrow, acute myeloid leukemia with maturation (AML-M2) with basophilic differentiation was the most likely diagnosis in this case. This study reports the unique morphologic features of a rare case of AML-M2 with suspected basophilic differentiation in an FeLV-negative cat.", "journal": "Veterinary clinical pathology", "doi": "10.1111/vcp.70148", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42572183", "author": "Kelly N", "n_authors": 5, "title": "Laboratory Changes Supporting a Diagnosis of Immune-Mediated Anemia in Cats With Initial Suspicion of Progressive Feline Leukemia Virus.", "abstract": "Progressive feline leukemia virus (FeLV) infection and anemia of suspected immune-mediated origin (ASIMO) are associated with similar hematologic abnormalities, including anemia, neutropenia, and lymphocytosis. Cats with ASIMO may test positive for FeLV using point-of-care (POC) ELISA tests. To describe laboratory changes that may result in the misclassification of cats with ASIMO as having progressive FeLV. Cats with ASIMO and laboratory results mimicking FeLV infection were retrospectively identified via searches of laboratory and clinical records. Inclusion criteria were: 1) a positive POC FeLV result with negative confirmatory testing, 2) hematocrit < 20%, with or without macrocytosis, neutropenia, lymphocytosis, or suspicion of circulating atypical cells, and 3) a clinical diagnosis of ASIMO. Clinical and laboratory data, treatment, and outcome were recorded. Nine cats met the inclusion criteria. All were vaccinated against FeLV. Seven (78%) had outdoor access and two (22%) were indoor only. Hematocrit at presentation ranged from 7-16%, and macrocytosis was recorded in seven cases (78%), of which six were normochromic by analyzer data. Seven cats (78%) had one or more laboratory indicators of hemolysis, including an abnormal RBC histogram in all five cases in which this was available for review. Other hematologic abnormalities included neutropenia (n = 6, 67%), lymphocytosis (n = 1, 11%), and circulating atypical cells (n = 1, 11%). Cats with ASIMO may present with macrocytic, normochromic anemia and other laboratory features mimicking progressive FeLV. Evaluation of RBC histograms alongside detailed blood film evaluation is helpful in identifying immune-mediated anemia as a likely diagnosis.", "journal": "Veterinary clinical pathology", "doi": "10.1111/vcp.70137", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42554915", "author": "de Villiers L", "n_authors": 10, "title": "Tracing feline herpesvirus-1 exposure in domestic cats from Namibia: associations with neutralising antibodies, vaccination, clinical signs, and retroviral status.", "abstract": "Feline herpesvirus type 1 (FHV-1) is a major cause of upper respiratory and ocular disease in domestic cats and remains widely distributed worldwide. However, information on FHV-1 exposure and neutralising antibody responses in cats from Namibia is limited. This study assessed FHV-1 neutralising antibody prevalence in a convenience sample of 236 domestic cats sampled across 15 towns in eight regions of Namibia. Neutralising antibodies were detected in 18/236 (8%) cats (95% CI: 4.88-11.73%). Seropositive animals were identified only in Erongo, Khomas, and Hardap regions, with the highest regional seroprevalence observed in Erongo. Seropositivity was uncommon in both vaccinated and unvaccinated cats and was not significantly associated with vaccination status, feline immunodeficiency virus antibody status, or feline leukaemia virus antigen status. A significant association was identified between seropositivity and oculonasal discharge (p < 0.001). Overall, the findings indicate low FHV-1 neutralising antibody prevalence within the sampled population rather than the wider domestic cat population of Namibia, and suggest that detectable neutralising antibodies were observed predominantly in unvaccinated cats, although interpretation is limited by the small number of vaccinated animals and the absence of detailed vaccination histories.", "journal": "Veterinary research communications", "doi": "10.1007/s11259-026-11446-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42548827", "author": "Chin JH", "n_authors": 3, "title": "Rare occurrence of an intumescent cataract in a diabetic domestic longhair cat.", "abstract": "A domestic longhair cat in Australia was referred to an ophthalmology service with the complaint of lens opacity. An incipient cataract was diagnosed in the right eye and an intumescent cataract with an equatorial lens capsule rupture in the left eye. The patient was being treated for diabetes mellitus, and previous concerns for the eyes had included conjunctivitis and left-sided periocular swelling and epiphora. Systemic work-up performed over the 7 months before ophthalmic referral included complete blood counts, biochemistry, serology (feline immunodeficiency virus, feline leukaemia virus, toxoplasmosis, cryptococcosis), thoracic radiographs, and ocular ultrasound and electroretinography performed before phacoemulsification. The patient did not have evidence of active uveitis at the initial ophthalmological examination, and historical serology excluded some common infectious causes of uveitis. The cataracts were treated successfully by phacoemulsification in both eyes, restoring vision. However, an intraocular lens was implanted only in the right eye, as the pre-existing lens capsule tear in the left eye precluded intraocular lens placement. Based on the medical history and clinical presentation, diabetes mellitus was suspected to be the cause of the cataracts. Intumescent cataracts are reported in humans and dogs but have rarely been reported in domestic cats. Nonetheless, the intumescent cataract in this patient had similar characteristics to those in diabetic canine cataracts.", "journal": "JFMS open reports", "doi": "10.1177/20551169261466438", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42528363", "author": "Campos-Camacho J", "n_authors": 10, "title": "Diagnosis of feline platynosomosis: case series and literature review.", "abstract": "Platynosomosis is a parasitic disease of cats and other animal species, caused by trematodes of the genus ", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/10406387261467915", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42515592", "author": "Denner J", "n_authors": 1, "title": "Retrovirus-Induced Immunosuppression: Role of the Transmembrane Envelope Protein.", "abstract": "Retroviruses induce immunosuppression in their infected hosts. This phenomenon is well described for the immunodeficiency viruses, with human immunodeficiency virus type 1 (HIV-1) representing the best-studied example, but it also occurs in other retroviral infections. Immunosuppressive properties were first characterized in murine leukemia viruses (MuLV). Additional well-studied examples include feline leukemia virus (FeLV) and koala retrovirus (KoRV). Investigations into the mechanisms underlying retrovirus-induced immunosuppression revealed that not only inactivated viral particles but also their purified transmembrane (TM) envelope proteins exhibit immunosuppressive activity. However, in certain retroviral infections, additional viral proteins contribute to the immunosuppression in vivo. Within the TM envelope proteins, a highly conserved region-designated the immunosuppressive (isu) domain-was identified. Synthetic peptides corresponding to this domain suppress a wide range of in vitro immune responses, possibly by regulating Ras-Raf-MEK-MAPK and PI3K-AKT-mTOR pathways. They modulate cytokine release and alter gene expression in immune cells, mirroring the activity of the corresponding TM envelope protein. Mutations in the sequence abrogate the effect. Numerous TM envelope proteins have demonstrated immunosuppressive activity in vivo in a tumor rejection model, and mutations within the isu domain also abrogate this function. These studies have important implications for reproduction, particularly through the immunosuppressive syncytins in the placenta, for tumor development, where similar mechanisms may protect cancer cells from the host immune system, and for vaccine development and xenotransplantation. Notably, immunization with TM envelope proteins carrying mutations in the isu domain elicits stronger immune responses compared with the wild-type proteins. Finally, the potential of retroviral TM envelope proteins to protect xenotransplants from immune rejection will be discussed.", "journal": "Viruses", "doi": "10.3390/v18070740", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42506662", "author": "Huisman W", "n_authors": 9, "title": "Development of a New Feline Combination Vaccine Including a Novel RNA Particle Vaccine Against Feline Leukemia Virus.", "abstract": "We describe the rationale, design and evaluation of a novel feline combination vaccine (Nobivac Nobivac NXT HCPChFeLV is a 0.5 mL, non-adjuvanted, lyophilized vaccine containing live attenuated FHV, FCV, FPL, and  Vaccination significantly reduced clinical disease following FHV, FCV and  Nobivac NXT HCPChFeLV provides robust, long-lasting protection against multiple feline pathogens, reduced pathogen shedding and demonstrated a favorable safety profile, supporting its use in feline preventive healthcare.", "journal": "Vaccines", "doi": "10.3390/vaccines14070625", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42504294", "author": "Mastrangelo C", "n_authors": 4, "title": "Suspected chronic eosinophilic leukemia in a cat treated with toceranib.", "abstract": "A 16-year-old, spayed female domestic shorthair cat was referred to the Schwarzman Animal Medical Center for evaluation of chronic, progressive eosinophilia accompanied by vomiting and weight loss despite normal appetite. Blood smear evaluation revealed immature eosinophils with dysplastic features and occasional giant forms. Abdominal ultrasound identified small-intestinal thickening, a hepatopathy and splenomegaly. Screening for feline leukemia virus, feline immunodeficiency virus and heartworm infection were negative. Chronic eosinophilic leukemia was suspected, although hypereosinophilic syndrome could not be ruled out. At the time of referral, the cat was receiving prednisolone and chlorambucil for suspected small cell gastrointestinal lymphoma, but showed persistent clinical signs and progressive eosinophilia. Chlorambucil was discontinued and toceranib was initiated alongside prednisolone. No adverse effects attributable to toceranib were observed. A partial response, defined as resolution of clinical signs and a 30% reduction in circulating eosinophils, was observed on day 39. A subsequent progression-free survival interval of 4 weeks was achieved. Progressive disease developed on day 75, and given declining quality of life, euthanasia was thereby elected on day 89. This case report is the first to describe the use of toceranib to treat suspected chronic eosinophilic leukemia, a rare and poorly documented disease process in cats. This novel therapeutic approach is the first publication of a partial response and stable disease in the treatment of suspected chronic eosinophilic leukemia in a cat.", "journal": "JFMS open reports", "doi": "10.1177/20551169261460751", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42462912", "author": "Gu J", "n_authors": 16, "title": "Heme-mediated liver-heart axis promotes myocardial pyroptosis in db/db mice.", "abstract": "Diabetes, a systemic metabolic disorder, often involves multi-organ interactions in its complications. Although the pathogenesis of diabetic cardiomyopathy (DCM) is complex, the role of the liver in this process remains unclear. Using the db/db mouse model, this study demonstrated that metabolic dysfunction associated steatotic liver disease (MASLD) reduced hepatic synthesis of hemopexin (HPX) and impaired Kupffer cell function, leading to systemic heme accumulation. This circulating heme was taken up by cardiomyocytes via the membrane protein feline leukemia virus subgroup C receptor 2 (FLVCR2), which induced cardiomyocyte pyroptosis and aggravated myocardial injury. Intervention experiments indicated that targeted supplementation of hepatic HPX effectively restored heme homeostasis, reduced exogenous heme influx into cardiomyocytes, and improved cardiac function. These findings reveal a liver-heart axis mechanism in which hepatic heme mediates cardiomyocyte pyroptosis through FLVCR2, offering novel perspectives for the prevention and treatment of DCM.", "journal": "Free radical biology & medicine", "doi": "10.1016/j.freeradbiomed.2026.07.028", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42462498", "author": "Mon Hla H", "n_authors": 8, "title": "Thymidine kinase 1 and lactate dehydrogenase activities in plasma and pleural effusion as biomarkers of feline mediastinal lymphoma: Clinical, viral and molecular correlates.", "abstract": "Feline mediastinal lymphoma is an aggressive cancer needing non-invasive methods for monitoring. This study aims to examine the correlation of thymidine kinase (TK1) and lactate dehydrogenase (LDH) levels in plasma and pleural effusion in cats diagnosed with mediastinal lymphoma and to explore how these markers relate to clinical, pathological, and genetic factors. We analyzed plasma and effusion samples from 30 cats with confirmed mediastinal lymphoma. TK1 was measured using an ELISA assay, and LDH activity and albumin levels were measured using an automatic chemical analyzer. We assessed FeLV infection, cytological grade, immunophenotype, and specific single nucleotide variants (SNVs) in KIT, BCL2, and ZEB1. Lymphoma cats had significantly higher TK1 levels than non-neoplastic controls. A positive correlation was observed between plasma and effusion TK1 levels. No correlation with LDH activity was observed. FeLV-positive cats showed higher plasma TK1 levels and a greater likelihood of elevated effusion. However, fluid TK1 levels were also higher in cats with T-cell lymphomas and those with the ZEB1 c. T > C variant; these differences were not statistically significant. No notable differences were found for LDH or the LDH-to-albumin ratio. The strong correlation and moderate agreement between plasma and pleural effusion TK1 levels potentially indicate that either sample type can be used to assess tumour activity. In contrast, the LDH values differed between the two compartments. Biological factors, including FeLV infection, T-cell phenotype, and ZEB1 variants, may impact tumour activity. This study highlights plasma TK1 as a valuable, non-invasive biomarker for monitoring feline mediastinal lymphoma. However, validation in larger cohorts is needed before clinical application.", "journal": "Research in veterinary science", "doi": "10.1016/j.rvsc.2026.106325", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42437610", "author": "Tondo LA", "n_authors": 7, "title": "Vestibular syndrome associated with subcutaneous hemangiosarcoma in a cat.", "abstract": "Hemangiosarcomas (HSAs) are rare neoplasms in cats, with cutaneous and subcutaneous forms occurring more frequently than visceral HSAs and often associated with chronic ultraviolet radiation exposure. Herein, we report a case of vestibular syndrome secondary to subcutaneous hemangiosarcoma in a 2-year-old cat. The patient was presented with ataxia, proprioceptive deficits, cranial nerve palsy, mild nystagmus, and head tilt. The cat tested positive for feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV), while complete blood count, serum biochemical profile, and albumin-to-globulin ratio were within normal limits. Based on the neurological findings and the absence of systemic abnormalities, central vestibulopathy was suspected. Corticosteroid therapy resulted in transient clinical improvement within 36 hours; however, 48 hours later, the cat developed vocalization and reduced consciousness. Due to the poor prognosis, euthanasia was elected. Necropsy revealed two dark-red subcutaneous nodules (∼1 cm) in the right thoracic region, multifocal omental nodules, and a red mass (3.2 × 2.7 × 1.3 cm) compressing and replacing part of the cerebellar parenchyma. Histopathologically, all nodules consisted of proliferating neoplastic endothelial cells forming irregular vascular channels filled with erythrocytes, consistent with hemangiosarcoma. Cerebellar metastasis accounted for the clinical signs of central vestibulopathy. Although meningoencephalitis is the most common cause of central vestibular disease in cats, neoplasms involving the cerebellum or brainstem should also be considered as differential diagnoses.", "journal": "Topics in companion animal medicine", "doi": "10.1016/j.tcam.2026.101088", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42429482", "author": "Goncalves A", "n_authors": 8, "title": "FLVCR2 Regulation of Intracellular Heme Modulates Vascular Tip/Stalk Specification During Retinal Angiogenesis.", "abstract": "Fowler syndrome is an embryonic lethal disease with proliferative vasculopathy and hydranencephaly-hydrocephaly of the central nervous system caused by mutations in feline leukemia virus subgroup C receptor-related protein 2 (FLVCR2) characterized by large regions of hypovascularization along with glomeruloid formation of poorly organized vascular endothelial cell masses. The purpose of the current study is to elucidate the mechanisms by which FLVCR2 regulates retinal angiogenesis. Recent animal models have characterized reduced brain vascularization in gene deletion models of Flvcr2. Here, we use conditional knockout of Flvcr2 in mice and knockdown in primary bovine retinal endothelial cell culture to explore retinal development and associated mechanisms of angiogenic regulation by FLVCR2. Endothelial cell-specific deletion of Flvcr2 or chemical inhibition of heme synthesis during post-natal retinal vascularization led to reduced vascular expansion in both primary (superficial) and secondary (deep) vascular plexuses, and a more severe but partially penetrant phenotype with attenuation of retinal vascular development and formation of abnormal vascular glomeruloids. Mechanistically, Flvcr2 knockdown in retinal endothelial cells led to reduced heme content and promoted NOTCH signaling and hyperproliferation that could be reversed with addition of a heme precursor. Similar effects were observed in cells treated with inhibitors of heme synthesis and reversed with addition of cell-permeable hemin. Furthermore, we found that FLVCR2/heme signaling attenuates NOTCH1 activation and affects downstream tip/stalk cell specification, while also preventing VEGF-induced proliferation. Collectively, these data indicate a newly identified role for FLVCR2 and heme in the regulation of tip/stalk specification in angiogenesis.", "journal": "Investigative ophthalmology & visual science", "doi": "10.1167/iovs.67.8.32", "deposited_data": "Sim", "nuccore_ids": "2260855274, 2260855270, 2260855261, 2260855247, 459683844, 118130135, 2260855274, 2260855270, 2260855261, 2260855247, 1907086933, 459683844, 118130135", "bioproject_ids": "1192242", "sra_ids": null}, {"year": 2026, "pmid": "42422439", "author": "Nogueira MM", "n_authors": 5, "title": "Feline paraneoplastic hypereosinophilic syndrome associated with lymphocytic intestinal lymphoma.", "abstract": "Alimentary lymphocytic lymphoma (AL) is the most prevalent neoplastic subtype in cats. T-cell neoplasms have been associated with eosinophil chemotaxis and, consequently, paraneoplastic hypereosinophilic syndrome. This report describes a case of marked hypereosinophilia in a cat with AL, consistent with a paraneoplastic hypereosinophilic syndrome, based on clinical findings. A 13-year-old neutered male Persian cat, negative for feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV), with a history of frequent vomiting, presented with a mild increase in abdominal volume on palpation, suggestive of mesenteric lymph node enlargement. Blood profile revealed marked leukocytosis (81,500 leukocytes/µL) due to severe eosinophilia (69,000/µL), consisting exclusively of segmented eosinophils. Abdominal ultrasonography showed lymphadenomegaly and increased echogenicity of the meso-omentum, suggestive of an infiltrative neoplastic process. Following suspicion of lymphoma, intestinal biopsy and bone marrow (BM) sampling were performed. BM evaluation was consistent with a myeloproliferative process, with eosinophilic lineage involvement. Histopathological examination of the duodenum, jejunum, and mesenteric lymph node confirmed the diagnosis of AL. Treatment with prednisolone, chlorambucil, and cobalamin was instituted. One month after treatment, the cat was clinically stable, with a total eosinophil count of 22,000/µL. After six months, eosinophil counts decreased to 9,030/µL, and abdominal ultrasonography showed no abnormalities. This report highlights the importance of investigating AL in cats presenting with marked hypereosinophilia.", "journal": "Brazilian journal of veterinary medicine", "doi": "10.29374/2527-2179.bjvm000926", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42419139", "author": "Keil E", "n_authors": 8, "title": "Primary pancreatic histiocytic sarcoma with peritoneal sarcomatosis in a cat.", "abstract": "A 12-year-old neutered male Domestic Shorthair Cat, negative for feline immunodeficiency virus and feline leukaemia virus, was presented to the veterinary hospital with a 3-week history of anorexia, lethargy, abdominal pain and intermittent vomiting. Abdominal ultrasonography revealed a heterogeneous, poorly demarcated mass in the right mesogastric region, involving the pancreas and adjacent organs. Cytological evaluation of the abdominal fluid revealed a neoplastic effusion consistent with carcinomatosis. Given the poor prognosis, the cat was euthanized and submitted for necropsy, which revealed a large volume of free transudate within the abdominal cavity. In the pancreas, there was a 6.0 × 3.0 × 7.5 cm, irregular, soft, white-to-yellow mass and multiple small, firm, white nodules, ranging from 0.1 cm to 1 cm in diameter, were adhered to the omentum, mesentery, diaphragm and abdominal wall and to the serosal surfaces of the urinary bladder, intestines, spleen, stomach, liver and lungs. Microscopically, the pancreas contained a neoplastic proliferation composed predominantly of round cells arranged in loosely cohesive groups. Similar neoplastic proliferations were observed in the peritoneum, diaphragm, omentum and mesentery, the serosal surfaces of the urinary bladder, intestines, spleen, stomach, liver, left adrenal gland and lungs, and in the mediastinal lymph nodes. Based on these findings, the histopathological diagnosis was metastatic undifferentiated pancreatic neoplasia. Immunohistochemical evaluation revealed strong, diffuse cytoplasmic immunolabelling for vimentin and ionized calcium-binding adaptor molecule 1 in the neoplastic cells, with no labelling for pancytokeratin (AE1/AE3), E-cadherin, CD3 and CD20. The gross, histological and immunohistochemical findings were consistent with a histiocytic sarcoma of probable pancreatic origin, with metastatic dissemination throughout the peritoneum resembling that observed in primary pancreatic carcinomatosis. Histiocytic proliferative disorders are rare in cats, and the unusual presentation of this case provides an important contribution to the recognition of the possible manifestations of histiocytic sarcomas in this species.", "journal": "Journal of comparative pathology", "doi": "10.1016/j.jcpa.2026.06.009", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42415333", "author": "Baltz A", "n_authors": 1, "title": "EXPRESS: Feline stress through owners' eyes: Comparing perceptions in veterinary clinics with and without designated feline-only areas or hours.", "abstract": "This study compared veterinary clinics with and without designated feline-only areas or hours across four domains: feline stress during visits, handling and restraint techniques, owner education on preventive care and common diseases, and overall client satisfaction. A cross-sectional questionnaire study was conducted across eight clinics in Greater Lisbon, Portugal (November 2015-January 2016). In total, 204 cat owners completed a 37-question survey evaluating clinic experience, feline stress, owner education, and service quality. Respondents were divided based on whether their clinic offered feline-segregated areas or hours (n = 96) or not (n = 108). Data were analysed using Chi-square and Mann-Whitney U tests (p < 0.05), with effect sizes calculated via Cramér's V and rank-biserial correlation. Owners at non-segregated clinics reported greater difficulty removing cats from carriers (p = 0.034) and administering home medication (p = 0.040). Their cats were more frequently scruffed (18.4% vs 7.4%) or sedated (10.3% vs 2.5%; p = 0.046; Cramér's V = 0.24), with the presence of other species increasing perceived stress (p = 0.004; r = 0.21). Non-segregated clinic owners also received significantly less information regarding FeLV (42.6% vs 17.7% uninformed; p < 0.001), FIV (40.7% vs 15.6%; p < 0.001), flea prevention (27.8% vs 7.3%; p < 0.001), and deworming (21.3% vs 5.2%; p = 0.001). Satisfaction with staff and veterinarians was higher in the segregated group (p = 0.001 for both). Clinics utilizing designated feline-only spaces or hours demonstrated superior outcomes across all evaluated domains. These findings provide quantitative support for feline-friendly principles, suggesting that investing in species segregation, staff training, and client education yields tangible improvements in animal welfare, client relationships, and veterinary practice quality.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X261468776", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42371188", "author": "Jiang H", "n_authors": 13, "title": "Molecular epidemiological investigation of viruses in Amur tigers in Northeast China.", "abstract": "A systematic molecular epidemiology survey was conducted on ten viruses in 226 captive and two wild Amur tigers from Northeast China. The target viruses were: feline panleukopenia virus (FPV), feline herpesvirus-1 (FHV-1), feline immunodeficiency virus (FIV), feline leukemia virus (FeLV), canine distemper virus (CDV), feline coronavirus (FCoV), feline calicivirus (FCV), influenza A virus (IAV), hepatitis E virus (HEV), and rotavirus A (RVA). The overall infection prevalence in captive tigers was 45.6% (103/226), with FPV (25.2%) and FHV-1 (20.4%) identified as the dominant pathogens. Other viruses detected at lower frequencies were FIV (3.1%), CDV (1.8%), FCoV (0.9%), and FeLV (0.4%); FCV, IAV, HEV, and RVA were not detected. This study reports the first detection of FeLV in this subspecies. Infection prevalence exhibited marked age and regional dependence, being highest in juveniles (56.5%) and in the facilities of Shenyang (55.8%) and Harbin (52.6%). Phylogenetic analysis of partial VP2 sequences indicated that FPV strains from captive tigers formed a distinct, well-supported monophyletic clade (bootstrap = 99). In contrast, the VP2 sequence from the wild tiger (YINGCHUN) did not group within the captive tiger clade; instead, it occupied a separate position within the broader FPV cluster. FIV strains from tigers were phylogenetically interspersed with strains from domestic cats in China. Despite existing vaccination protocols, the persistent high prevalence of FPV and FHV-1 indicates suboptimal immunoprotection. These findings clarify the current viral pathogen profile in captive Amur tigers and underscore the necessity for optimizing disease management strategies, including age-stratified immunization, enhanced biosecurity, and the establishment of transboundary surveillance.", "journal": "Archives of virology", "doi": "10.1007/s00705-026-06644-y", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42357636", "author": "Heddergott M", "n_authors": 10, "title": "Exposure to Feline Viruses in European Wildcats (Felis s. silvestris) in Germany: Spatial Patterns and Environmental Risk Factors.", "abstract": "While viral diseases of domestic cats (", "journal": "Viruses", "doi": "10.3390/v18060627", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42329486", "author": "Putri MND", "n_authors": 8, "title": "A newly developed multiplex RT-PCR enables detection of blood-associated viral nucleic acids in cats.", "abstract": "Feline immunodeficiency virus (FIV), feline leukemia virus (FeLV), domestic cat hepadnavirus (DCHBV), felis catus gammaherpesvirus 1 (FcaGHV1), and severe fever with thrombocytopenia syndrome virus (SFTSV) are significant blood-associated pathogens impacting feline health. Because these viruses often co-circulate, rapid and simultaneous detection is essential for effective diagnosis and surveillance. A multiplex reverse transcription polymerase chain reaction (RT-PCR) assay was developed for simultaneous detection of viral and proviral nucleic acids associated with feline blood-borne viruses. Initial analytical evaluation using spike and non-spike controls established limits of detection ranging from 1.6 copies/µl (FeLV) to 900 copies/µl (FcaGHV1 and SFTSV). No cross-reactivity with other common feline viruses was observed during analytical specificity testing. When evaluated relative to corresponding singleplex RT-PCR assays (n = 126), the assay demonstrated 100% negative percent agreement and 91.9% positive percent agreement relative to corresponding singleplex RT-PCR assays, with diagnostic agreement (κ = 0.878). Following validation, the multiplex assay was applied to 442 clinical samples (401 blood and 41 spleen samples), identifying single detections in 17.2%, and codetections in 4.3% of cases. FeLV and FIV were most prevalent, while no SFTSV was detected; furthermore, FcaGHV1-positive samples underwent additional genetic characterization. Retroviral presence significantly correlated with clinically ill, male cats older than three years. Overall, the assay demonstrated reliable multiplex detection and may serve as a useful screening tool for feline viral surveillance and clinical evaluation, although negative results should be interpreted cautiously for low-copy targets.", "journal": "Veterinary research communications", "doi": "10.1007/s11259-026-11359-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42312125", "author": "Sánchez-Bermúdez JF", "n_authors": 7, "title": "First molecular detection of Leishmania infantum in a domestic cat from Costa Rica.", "abstract": " A 4-year-old, neutered male domestic cat was presented with an indolent, non-ulcerated and painless subcutaneous nodule on the left hindlimb. Abdominal ultrasonography revealed generalized lymphadenomegaly and splenomegaly with a honeycomb pattern. The cat tested negative for feline leukemia virus and feline immunodeficiency virus. Fine-needle aspiration of the lesion showed mixed inflammatory cells, including eosinophils and macrophages containing small intracytoplasmic basophilic inclusions considered suspicious for  This report describes the first molecular detection of ", "journal": "JFMS open reports", "doi": "10.1177/20551169261445126", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42310831", "author": "Hartmann G", "n_authors": 8, "title": "Disseminated histiocytic sarcoma in 2 FeLV-positive cats in Brazil.", "abstract": "Histiocytic sarcomas (HSs) are uncommon malignant neoplasms in cats, typically affecting older animals and not previously associated with feline leukemia virus (FeLV). Here, we describe 2 cases of disseminated HS in young FeLV-positive domestic shorthair cats that clinically and grossly mimicked lymphoma. Case 1, a 1-y-old female cat, was presented with hemiplegia and dysuria and was euthanized because of the clinical suspicion of spinal lymphoma. Case 2, a 4-y-old male cat, had hyporexia, ocular abnormalities, and bilateral renal enlargement and was euthanized because of the clinical suspicion of renal and ocular lymphoma. Both cases tested positive for feline leukemia virus (FeLV) infection with a SNAP test. At autopsy, case 1 had a white, irregular, intradural spinal cord mass at the C6-C7 segment, and case 2 had coalescing, unencapsulated, white nodules that effaced both renal cortices, along with uveal thickening in the left eye with hyphema. Both cases had highly pleomorphic neoplastic round-cell proliferation in neoplastic masses, with strong cytoplasmic labeling for vimentin and IBA1 on immunohistochemistry and no CD20 or CD3 labeling, confirming disseminated HS. The neoplastic cells also had strong cytoplasmic immunolabeling for FeLV, suggesting a possible oncogenic role of FeLV in feline HSs.", "journal": "Journal of veterinary diagnostic investigation : official publication of the American Association of Veterinary Laboratory Diagnosticians, Inc", "doi": "10.1177/10406387261452652", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42288833", "author": "Castillo-Aliaga C", "n_authors": 6, "title": "Cross-species transmission of host adaptation of feline leukemia virus between domestic cats and the wild felid Leopardus guigna.", "abstract": "Feline leukemia virus (FeLV) is widespread in domestic cats and frequently spills over into wild felid populations, causing severe outbreaks in nondomestic felid populations. Domestic cats carry both endogenous FeLV (enFeLV) and exogenous variants of FeLV (exFeLV), which can recombine to generate novel variants with alternate receptor usage. In contrast, most nondomestic felids, including the guigna, do not harbor enFeLV. This study applied amplification of the FeLV envelope gene combined with Illumina sequencing to characterize FeLV envelope gene diversity and transmission dynamics in guignas (Leopardus guigna), a small wild felid native to Chile and Argentina. Seven polymerase chain reaction (PCR )amplicons from five free-ranging guignas were sequenced. Illumina sequencing was successfully conducted, and subsequent phylogenetic analysis indicated that the detected infections were most closely related to strains circulating in Chilean domestic cats. However, a distinct guigna-specific cluster with unique sequence variations was identified, suggesting that FeLV transmission also occurs among guignas independent of domestic cats. Phylogenetic analysis showed that all guigna sequences formed a Chile-specific FeLV clade, closely related to domestic cat viruses but clearly separated from international FeLV-A strains.", "journal": "Veterinary research", "doi": "10.1186/s13567-026-01770-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42216781", "author": "Castillo-Aliaga C", "n_authors": 4, "title": "Twenty-year lifetime histories of FIV- and FeLV-infected cats in a sanctuary in the UK indicate an effect of retroviral infection on longevity.", "abstract": "Feline immunodeficiency virus (FIV) and feline leukaemia virus (FeLV) are retroviruses that affect cat longevity and health. This study aimed to assess the impact of retroviral status on life expectancy in a feline sanctuary population, which includes cats with behavioural issues and retroviral infections. A retrospective cohort analysis was conducted on 132 cats, including 22 uninfected, 82 FIV The median life expectancies were 160.3 months for uninfected cats, 149.1 months for FIV The study is limited by the low number of animals, particularly in the FeLV/FIV FeLV infection markedly shortens lifespan and increases the risk of lymphoma, whereas FIV-infected cats are less likely to live to extremely old age.", "journal": "The Veterinary record", "doi": "10.1002/vetr.70806", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42183043", "author": "Zanin Venturini DI", "n_authors": 2, "title": "FLVCR1-related diseases: from clinical heterogeneity to mechanistic insights.", "abstract": "Feline Leukemia Virus subgroup-C Receptor 1 (FLVCR1) is an ubiquitously expressed choline and ethanolamine importer that is involved in the control of multiple aspects of cell biology including the regulation of phospholipids metabolism, heme homeostasis, mitochondria-ER contact sites and cellular bioenergetics. Mutations in the ", "journal": "Brain communications", "doi": "10.1093/braincomms/fcag165", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42139320", "author": "Černá P", "n_authors": 7, "title": "Descriptive assessment of cardiac changes in cats with feline infectious peritonitis.", "abstract": "Myocarditis and myocardial injury associated with feline infectious peritonitis (FIP) recently are being recognized. Prospectively document the frequency of cardiac changes in cats with FIP using echocardiography and cardiac troponin I (cTnI) concentrations. Twenty cats with naturally occurring FIP without previous history of heart disease. Cats diagnosed with FIP were tested for common concurrent infections associated with myocarditis by testing serum for feline immunodeficiency virus (FIV) antibodies, feline leukemia virus antigen (FeLV), Dirofilaria immitis antigen, Bartonella spp. immunoglobulin G (IgG), and Toxoplasma gondii IgG and immunoglobulin M (IgM) as well as by testing blood for nucleic acids of Bartonella spp. and coronavirus (SARS-COV-2). Each cat also was tested for serum cTn1 concentration and underwent an echocardiographic examination. After 12 weeks of treatment with antiviral drugs, serum cTnI concentrations were reassessed. All echocardiographic measurements were normalized to patient body weight. The left ventricular posterior wall from right parasternal long axis and short axis was thickened in 55% (11/20) and 25% (5/20) of cats, respectively. Pleural effusion was present in 40% (8/20) of cats and pericardial effusion in 25% (5/20) of cats, but a cardiac cause was not identified for these effusions. Median cTnI at initial evaluation was 0.37 ng/ml (interquartile range [IQR], 0.20-0.83; upper reference interval, 0.20 ng/ml). Repeat cTnI was performed after 12 weeks of antiviral treatment in 6 cats that initially had increased cTnI (median initial cTnI, 0.75 ng/mL) and, in all 6 cats, cTnI normalized to < 0.20 ng/mL. Cats with FIP can present with increases in cTnI and ventricular wall thickening, findings suggestive of myocarditis or myocardial injury.", "journal": "Journal of veterinary internal medicine", "doi": "10.1093/jvimsj/aalag083", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42134627", "author": "Silva WI", "n_authors": 3, "title": "Epidemiology of hemoplasma infections in domestic cats (Felis catus): A global systematic review with meta-analysis.", "abstract": "Hemoplasmas of the genus Mycoplasma are hemotropic bacteria that parasitize red blood cells and can cause hemolytic anemia in several mammalian species, including domestic cats (Felis catus). Given their importance, the aim of this study was to globally characterize hemoplasma infections in domestic cats (Felis catus) through a systematic review with meta-analysis. Five databases were used to obtain observational studies (ScienceDirect, PubMed, Web of Science, Scopus, and SciELO) published worldwide up to December 2025. The global prevalence was estimated through a meta-analysis using a random-effects model in the R software with the meta package. A total of 128 articles were included in the systematic review and meta-analysis. The results demonstrated a global prevalence of hemoplasmas of 19.8% (95% CI: 17.1-22.6), with high heterogeneity among studies. Among the identified species, 'Candidatus Mycoplasma haemominutum' (CMhm) was the most prevalent, followed by Mycoplasma haemofelis (Mhf) and 'Candidatus Mycoplasma turicensis' (CMt). Coinfections between species were frequently reported. Among the risk factors most commonly associated with infection were male sex, adulthood, FIV infection, outdoor access, and FeLV. hemoplasma infections show a wide global distribution in domestic cats, with CMhm as the predominant species. These findings reinforce the importance of epidemiological surveillance and the use of molecular methods for the diagnosis of feline hemoplasmosis.", "journal": "Microbial pathogenesis", "doi": "10.1016/j.micpath.2026.108556", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42129643", "author": "Morais de Almeida P", "n_authors": 7, "title": "Clinical and virological effects of the integrase inhibitor raltegravir in cats with naturally progressive feline leukaemia virus infection.", "abstract": "ObjectivesFeline leukaemia virus (FeLV) infection - particularly the progressive course - continues to cause substantial morbidity and reduced survival in cats. Therapeutic options with proven antiviral effectiveness remain limited. This study aimed to evaluate the clinical and virological effects of the integrase inhibitor raltegravir in naturally infected, FeLV-progressive cats with FeLV-related conditions, clinical outcome, viraemia, proviral burden and survival.MethodsIn total, 14 client-owned cats with confirmed progressive FeLV infection and at least one FeLV-related condition were enrolled. Raltegravir was administered for 90 days, followed by a 90-day treatment-free observation period. Clinical evaluation and quantification of viral RNA and proviral DNA loads were performed at treatment initiation, day 45, day 90 and day 180. Cats continued to receive standard of care as clinically indicated. Survival data were recorded until study closure.ResultsAfter 45 days of treatment, plasma viral RNA load showed a non-significant mean reduction of 1.34 log", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X261452556", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42114998", "author": "Nel L", "n_authors": 5, "title": "Structural and biochemical comparison of the FLVCR and CTL membrane protein families in eukaryotes.", "abstract": "The organic cation choline is essential for eukaryotic metabolism. Recently, the feline leukemia virus subgroup C receptor-related (FLVCR, SLC49) family was demonstrated as central for basal choline transport, questioning the role of the choline transporter-like (CTL, SLC44) family in this capacity. Here, we use ", "journal": "Life science alliance", "doi": "10.26508/lsa.202503583", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42108251", "author": "Yin M", "n_authors": 14, "title": "Diversity of fecal viromes and zoonotic risk assessment in captive wild felids using viral metagenomics.", "abstract": "Emerging viral diseases-particularly zoonotic pathogens-affect the health and conservation of endangered felids, including Panthera tigris altaica (Amur tiger) and Panthera pardus (leopard). To address this challenge, we employed a viromics approach to investigate the diversity of the fecal virome in wild felids and assess its zoonotic potential. Using in-depth metagenomic sequencing and analysis of fecal samples from captive wild felids housed in a wildlife institution, this study characterized the enteric virome and evaluated associated risks. A total of 18 viral families and 48 viral genera were identified. The DNA virus community exhibited stability in abundance and composition, dominated by the phyla Heunggongvirae and Bamfordvirae. Within Heunggongvirae, the class Caudoviricetes was the core component, with its abundance aligning with the intestinal bacterial community, suggesting a potential role of these bacteriophages in regulating microbial ecology. Additionally, sequences of the family Poxviridae, homologous to Variola virus (VARV), were detected. In contrast, the RNA virus community displayed higher diversity and variability, with the order Ortervirales as the predominant group. Sequences highly homologous to feline leukemia virus (FeLV) were repeatedly identified, suggesting potential latent infections. The detection of sequences related to rare environmental viruses, such as Casadabanvirus, highlights the potential risk of cross-species virus transmission under captive conditions. Stability analysis revealed that dominant DNA virus groups exhibited low abundance variability across samples. In contrast, unclassified RNA viral taxa showed higher abundance variability. KEGG functional annotation mapped DNA viral contigs primarily to microbial metabolic modules. Conversely, RNA assemblies extensively mapped to eukaryotic pathways (e.g., arachidonic acid and energy metabolism); due to the total nucleic acid extraction methodology, these mappings primarily reflect co-extracted host transcriptomic background rather than viral-encoded functions, providing an indirect snapshot of the concurrent enteric microenvironment. These baseline data delineate the virome structure in captive environments and provide practical targets for zoological biosecurity and proactive veterinary surveillance.", "journal": "Scientific reports", "doi": "10.1038/s41598-026-52077-7", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42083096", "author": "Westman ME", "n_authors": 17, "title": "Antibody responses to inactivated (adjuvanted) and attenuated (non-adjuvanted) feline panleukopaenia virus vaccination, including in different injection sites.", "abstract": "ObjectivesVaccines have traditionally been administered to cats into the interscapular subcutaneous region ('scruff') for ease of restraining the cat while the vaccine is injected. Concern about feline injection-site sarcomas (FISSs) has prompted recommendations to use distal sites such as the hindlimb or tail, but evidence of adequate immune response at these sites is limited. This field study evaluated the antibody response to feline panleukopaenia virus (FPV) in kittens vaccinated with one of two commercial vaccines, injected at different sites.MethodsAn inactivated (killed), adjuvanted pentavalent vaccine (Fel-O-Vax 5; Boehringer Ingelheim Animal Health Australia) was injected subcutaneously into the scruff, left distal hindlimb or proximal tail. A modified-live virus (attenuated [MLV]), non-adjuvanted trivalent vaccine (Feligen RCP; Virbac Animal Health Australia) was given into the scruff only. For the latter, an inactivated, adjuvanted monovalent feline leukaemia virus vaccine was administered concurrently into the contralateral scruff, left distal hindlimb or proximal tail. Only one FPV-containing vaccine was administered to each cat/kitten: either the inactivated vaccine given in one of the three different anatomical regions or the MLV vaccine given into the scruff only. Cats were re-vaccinated in the same site and using the same vaccine type. Kittens were randomly allocated into study groups according to order of recruitment. Kittens were sampled at four time points over 12 months (T0, T1, T2 and T12). Protective FPV antibody titres were determined by haemagglutination inhibition (HI; negative <1:32, positive ⩾1:32).ResultsSamples from 100 kittens (T0, T1, T2) and 77 returning adult cats (T12) were available for FPV antibody testing (median age of kittens at T0 was 13 weeks, range 7-16). Eight kittens (8%) were found to be HI-positive at T0. Protective titres did not differ significantly among the three injection sites for the inactivated vaccine. Linear modelling demonstrated that antibody titres were higher in kittens given the MLV vaccine compared with kittens given the inactivated vaccine at T1 (", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X261450889", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42068381", "author": "Šolaja S", "n_authors": 7, "title": "Molecular insights into domestic cat hepatitis B virus linking genome to function.", "abstract": "Domestic cat hepatitis B virus (DCHBV) is a member of the Hepadnaviridae family and has been associated with hepatocellular carcinoma (HCC) in cats. This study aimed to determine the prevalence of DCHBV and associations with feline immunodeficiency virus (FIV), feline leukaemia virus (FeLV) and feline coronavirus (FCoV) infections in cats in Serbia, and to characterise the detected DCHBV genomes. Whole blood, serum and liver samples from 308 animals were screened by real-time (RT-)PCR for DCHBV, FIV, FeLV, and FCoV. The prevalence of DCHBV was 2.60%, with no significant associations observed between DCHBV infection and age, sex, or coinfection status. Three whole genome sequences were obtained, and phylogenetic analysis demonstrated that the Serbian strains belong to genotype A. Molecular analysis revealed three unique nonsynonymous substitutions in the S ORF. Within the C ORF, a 28-amino acid N-terminal precore region with conserved cysteine residues critical for protein maturation was identified, along with the C-terminal arginine-rich domain. A putative core promoter region was detected, containing two motifs analogous to the pgRNA and pcRNA initiator elements described in hepatitis B virus (HBV). DCHBV sequences contained two 11-bp direct repeats with DR2 located in X ORF and DR1 positioned in the C ORF. This study represents the first report of DCHBV in Serbia, providing new insights into its epidemiology and genomic features. The findings expand current knowledge of its molecular diversity and underscore the importance of genomic characterisation for understanding its role in liver disease development.", "journal": "Veterinary research communications", "doi": "10.1007/s11259-026-11236-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42050592", "author": "Lacerda WK", "n_authors": 6, "title": "Multiple congenital malformations in a litter of feline fetuses associated with gestational exposure to a synthetic estrus-suppressing progestin.", "abstract": "BACKGROUND: Congenital malformations in domestic cats are traditionally considered uncommon; however, recent evidence suggests they may represent an underrecognized cause of neonatal mortality. Most reported anomalies occur as isolated defects in individual animals, while the occurrence of multiple severe malformations within the same fetus or affecting an entire litter appears to be rare. Exposure to exogenous substances during critical windows of embryonic development has been proposed as a potential contributing factor. Reports describing congenital abnormalities in feline fetuses following gestational exposure to synthetic progestins remain scarce. CASE PRESENTATION: A three-year-old intact domestic shorthair cat was presented for veterinary evaluation due to dystocia approximately 65 days after repeated escape episodes from the household. In an attempt to suppress estrus and prevent mating, the owner administered two subcutaneous injections of a commercially available estrus-suppressing agent containing medroxyprogesterone acetate, before pregnancy was clinically recognized. Cesarean section revealed three dead fetuses, all presenting multiple congenital malformations. Cleft palate and arthrogryposis were observed in all fetuses, with arthrogryposis limited to the thoracic limbs in two and generalized in the third. Two female fetuses exhibited clitoromegaly consistent with virilization of the external genitalia. Additional findings included markedly reduced lung size suggestive of pulmonary hypoplasia in one fetus, cranium bifidum associated with meningocele in another, and severe axial and ventral body wall defects compatible with schistosomus retroflexus in the third. Rapid tests for feline immunodeficiency virus, feline leukemia virus, and feline panleukopenia virus in the queen were negative. Histopathological examination revealed diffuse vascular congestion and moderate autolysis, consistent with intrauterine fetal death, without evidence of inflammatory or infectious disease. CONCLUSIONS: Although a direct causal relationship cannot be established, the temporal sequence of events and the spectrum of malformations observed are suggestive of disruption of early embryonic development. This case highlights the potential risks associated with the use of synthetic estrus-suppressing progestins in intact queens when pregnancy status is unknown. Increased awareness, cautious use of hormonal contraceptives, and further well-documented reports are warranted to better elucidate their potential impact on fetal development in cats.", "journal": "BMC veterinary research", "doi": "10.1186/s12917-026-05506-8", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42013235", "author": "Mouta R", "n_authors": 7, "title": "Evolutionary Dynamics of Endogenous Feline Leukemia Virus in the Felis Genus Through the Lens of Genomics.", "abstract": "Feline leukemia virus (Gammaretrovirus felleu) causes variable pathologies, partially modulated by its endogenous form (enFeLV). Although enFeLV is found in genomes of all species of the Felis genus, the limitations of transposable element sequencing have hindered a comprehensive characterization. In this study, we examined 17 felid genomes for enFeLV copies, confirming that enFeLV is restricted to the Felis genus. From the long-read genomes of Felis catus, Felis nigripes, and Felis chaus, we identified 73 solo LTRs, 64 copies with genic segments, and 4 atypical copies. These were annotated and characterized using recombination assessment, phylogenetic analysis, insertion dating, and Fisher's exact tests. All enFeLV copies shared a single origin, with insertions occurring within the last 3.5 million years, except for predicted recombinants. Copy distribution, dating, and the phylogenetic position of F. chaus copies reinforce the hypothesis of a recent introgression of enFeLV into this species. Furthermore, 41 copies exhibit identical LTR pairs and 14 retain intact open reading frames spanning the viral genome. Uneven evolutionary pressures across the enFeLV genome were evidenced by discrepancies between tree topologies of individual genes and the preferential loss of pol. We conclude that enFeLV has undergone a complex post-endogenization evolutionary history and urge additional studies of other endogenous retroviruses.", "journal": "Annals of the New York Academy of Sciences", "doi": "10.1111/nyas.70278", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "41946374", "author": "Tetlow ER", "n_authors": 11, "title": "Serum protein alterations characterize feline chronic gingivostomatitis: a case-control study of electrophoresis, immunoglobulin, and cytokine profiles.", "abstract": "To characterize systemic immune alterations in feline chronic gingivostomatitis (FCGS) through serum protein electrophoresis (SPE), immunoglobulin (Ig), and cytokine profiling. We hypothesized that FCGS cases would exhibit polyclonal hyperglobulinemia, elevated Igs, and proinflammatory cytokine elevations compared to controls. Cats with FCGS and controls were prospectively enrolled in an observational case-control study at 2 veterinary dental practices. Exclusion criteria included FIV/FeLV infection, recent vaccination, corticosteroid administration, and systemic disease. A single preanesthetic serum sample was analyzed for 31 biomarkers, including SPE fractions, Ig concentrations, and cytokine levels. 13 FCGS cats and 14 controls were enrolled. Six biomarkers differed significantly after false discovery rate (FDR) correction, with very large effect sizes (Hedges g = 1.43 to 2.27): globulin, IgG, γ globulin, total protein, albumin, and albumin-to-globulin ratio. Polyclonal gammopathy was present in 76.9% of FCGS cases. Seven cytokines showed medium to large effect sizes (Hedges g = 0.57 to 0.88) without surviving FDR correction. Hierarchical clustering separated 85% of cases from 79% of controls based on coordinated cytokine profiles despite modest individual elevations. This study confirms FCGS as a disease with a quantifiable, systemic inflammatory response characterized by polyclonal hypergammaglobulinemia and mixed T helper 1/2 cytokine activation. FCGS extends beyond localized oral inflammation to involve measurable systemic immune dysregulation. Hyperglobulinemia, combined with oromucosal inflammation, should prompt diagnostic consideration of FCGS in cats. The coordinated activation of IL-8, IL-4, IFN-γ, and IL-6 identifies potential therapeutic targets for immunomodulatory intervention in refractory cases.", "journal": "American journal of veterinary research", "doi": "10.2460/ajvr.26.02.0052", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "41929732", "author": "Brodkin J", "n_authors": 3, "title": "Feline leukemia virus-negative acute lymphoid B-cell aleukemic leukemia in a cat with prolonged survival.", "abstract": "A 13-year-old feline leukemia virus-negative cat was diagnosed with acute lymphoid B-cell aleukemic leukemia. The diagnosis was based on the combination of pancytopenia, large and atypical round cells present on liver and splenic cytology, bone marrow cytology and histopathology showing a majority nucleated population of atypical blast cells, immunohistochemistry, and a lack of malignant lymphoblasts observed in the peripheral blood. The cat was initially treated with L-asparaginase, vincristine, doxorubicin, cyclophosphamide, and prednisolone, which led to a resolution of the cytopenias. After relapse on Day 242, lomustine was first administered, followed by a modified protocol of vincristine, mitoxantrone, cyclophosphamide, and prednisolone, due to progressive disease. A survival time exceeding 1 y following diagnosis was obtained. This case highlights both a rare, aleukemic form of acute lymphoid leukemia in a feline leukemia virus-negative cat and an atypically prolonged survival time. Key clinical message: Prolonged survival of cats with acute lymphoid aleukemic leukemia is possible with chemotherapy treatment.", "journal": "The Canadian veterinary journal = La revue veterinaire canadienne", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "41901790", "author": "Van der Walt M", "n_authors": 8, "title": "Clinical Features and Outcomes of Treatment for Effusive Feline Infectious Peritonitis with GS-441524 in Seventeen Retrovirus-Positive Cats.", "abstract": "There is limited information about treatment success and outcomes in retrovirus-positive cats diagnosed with feline infectious peritonitis (FIP). A survey was distributed to caretakers of cats with feline leukemia virus (FeLV) and/or feline immunodeficiency virus (FIV) that were treated with GS-441524 for presumptive effusive FIP based on survey responses. Cats with FIV developed FIP at an older age and longer after retrovirus infection than cats with FeLV. The average starting dosage (7 mg/kg/d) was increased in 65% of cats, and treatment was extended in 35%. Three cats relapsed (18%). There was a 94% (16/17) twelve-week survival rate and 82% (14/17) one-year survival rate. Seven cats were alive at follow-up, a median of 1306 days (range 983-2069) after FIP diagnosis, but many cats succumbed to neoplasia. Treatment success for retrovirus-positive cats with presumptive FIP was similar to previously reported outcomes for FIP alone. This could support current evidence of successful antiviral therapy for similar populations, if noncurrent, unstandardized protocols and unlicensed product use are considered. Additional studies are needed to determine ideal protocols for rapid resolution of FIP, good long-term survival, and limited relapse in retrovirus-positive cats, and the impact of the FeLV proviral load.", "journal": "Pathogens (Basel, Switzerland)", "doi": "10.3390/pathogens15030337", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "41897966", "author": "Kim HJ", "n_authors": 3, "title": "A Retrospective Investigation of 28 Cats with Intermediate- to Large-Cell Lymphoma Treated with Lomustine and Prednisolone as a First-Line Chemotherapy.", "abstract": "Lymphoma is the most common neoplastic disease in cats; however, lomustine has been insufficiently evaluated as a first-line chemotherapeutic agent. This study assessed treatment response, survival, and progression-free interval (PFI) in cats with intermediate-to-large cell lymphoma treated with lomustine and prednisolone as first-line therapy. Twenty-eight cats with cytologically or histopathologically confirmed lymphoma received lomustine (10 mg/cat every 3 weeks) and prednisolone until disease progression or unacceptable toxicity. All cats were feline leukemia virus- and feline immunodeficiency virus-negative, with a mean age of 9.93 years; alimentary lymphoma was most common (75%). Treatment responses included complete response (CR, 5/28), partial response (5/28), stable disease (11/28), and progressive disease (7/28). The median PFI for all cats was 51 days, and the median survival time was not reached during the study period. No significant associations were identified between PFI or survival and age, sex, packed cell volume, drug dosage, tumor size, or tumor location. Cats achieving CR showed significantly prolonged PFI compared with cats with other responses (median, 561 vs. 42 days; ", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani16060989", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "41868399", "author": "Urig HE", "n_authors": 4, "title": "Feline leukemia virus point-of-care lateral flow tests have low positive predictive value in apparently healthy shelter cats.", "abstract": "This study aimed to determine the true prevalence of feline leukemia virus (FeLV) infections in apparently healthy and sick shelter cats in Mississippi and estimate the predictive value of a lateral flow test results at the estimated true prevalences to guide testing recommendations. Blood samples (", "journal": "Frontiers in veterinary science", "doi": "10.3389/fvets.2026.1752228", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "41808988", "author": "Malekos E", "n_authors": 3, "title": "Integrative multiomics analysis and CRISPR screening identify functional noncanonical translation loci in the mouse immune system.", "abstract": "Ribosome profiling has revealed thousands of noncanonical translation events across mammalian genomes, yet functional characterization has overwhelmingly focused on proliferative fitness in cancer cell lines. Here, we present a comprehensive survey of noncanonical translation in the mouse immune system and its functional consequences in macrophages. By performing a unified Ribo-seq meta-analysis across 20 public mouse leukocyte datasets - spanning macrophages, dendritic cells, neutrophils, B cells, and T cells - we define a compendium of 22,276 noncanonical coding sequences (CDSs), including upstream ORFs (uORFs), downstream ORFs, and ORFs on noncoding RNAs and pseudogenes (ncORFs). Proteogenomic integration with reanalyzed mass spectrometry data prioritizes a high-confidence subset with detectable protein products, including pseudogene-encoded and lncRNA-encoded zinc finger proteins. To move beyond cataloging, we carried out two orthogonal CRISPR screens in immortalized bone marrow-derived macrophages: a fitness screen identifying noncanonical CDSs required for macrophage viability, and a TLR1/TLR2-NFκB reporter screen uncovering CDSs that modulate innate immune signaling. These screens nominate uORFs, several conserved between mouse and human, that exert phenotypic effects on par with their cognate coding sequences. We unexpectedly discovered a family of endogenous retroviral envelope-derived proteins translated in adult myeloid cells. Among these, SYNIR is a full-length syncytin-like membrane glycoprotein that positively regulates NFκB-responsive transcription, while SEMR is a secreted protein with structural homology to the feline leukemia virus accessory protein FeLIX that drives broad transcriptional remodeling of macrophage gene programs upon knockout. Updated single-cell RNA-seq annotations and an interactive UCSC Genome Browser session integrating Ribo-seq, proteomics, and CRISPR screen data are provided as community resources. Together, these findings expand the functional landscape of noncanonical translation in immunity and establish endogenous retroviral proteins as previously unrecognized regulators of macrophage biology.", "journal": "bioRxiv : the preprint server for biology", "doi": "10.64898/2026.02.23.707583", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "41807351", "author": "Buchta K", "n_authors": 19, "title": "Large-cell lymphoma in four cats after successful treatment of feline infectious peritonitis with oral GS-441524: a novel clinical observation.", "abstract": "Case series summaryFatal feline infectious peritonitis (FIP), caused by feline coronavirus (FCoV), can now be cured with GS-441524. Only a few unexpected clinical and laboratory observations have been reported with treatment, including lymphocytosis, eosinophilia and long-term persistence of abdominal lymphadenomegaly. Yet immune overstimulation associated with FIP might have negative long-term consequences. This report describes four cases of large-cell lymphoma (LCL) arising within 2 years of FIP diagnosis and successful treatment with legally sourced oral GS-441524 (15 mg/kg q24h), representing an incidence of 2.0% (n = 4/202) in a large treatment cohort. At LCL diagnosis, two cats were aged under 2 years, one was aged 8 years and one was aged 13 years. All cats showed weight loss, three had hyporexia and two had chronic vomiting; all tested negative for feline leukaemia virus and feline immunodeficiency virus. LCL was diagnosed by histology (n = 3) or cytology (n = 1) at 81, 365 (n = 2) and 595 days after FIP diagnosis/treatment start. The cats died a median of 15.5 days after LCL diagnosis. Neither a high FCoV viral load nor FCoV antigen, as determined by semi-quantitative RT-PCR and immunohistochemistry, respectively, was detected in any of the available samples. PCR for antigen receptor rearrangements revealed a monoclonal B-cell population in two cats, supporting a diagnosis of large B-cell lymphoma.Relevance and novel informationThe incidence of LCL reported here among cats in remission from FIP after legally sourced oral GS-441524 treatment is remarkably high compared with the general feline population. LCL should be considered a potential 'long-FIP syndrome' and/or a long-term complication after GS-441524 treatment. The pathogenesis of LCL in this context requires further clarification.", "journal": "Journal of feline medicine and surgery", "doi": "10.1177/1098612X261434629", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "41768374", "author": "José MOP", "n_authors": 5, "title": "Chronic Atypical Myelomonocytic Leukemia of Eosinophilic Lineage in a Cat With Feline Leukemia Virus: A First Case Report.", "abstract": "Feline hematopoietic neoplasms associated with retroviruses pose a diagnostic and therapeutic challenge, especially when they present with atypical morphological features that do not fit conventional classifications. This work describes the first reported case worldwide of atypical chronic myelomonocytic leukemia of eosinophilic lineage in a cat positive for feline leukemia virus, diagnosed through detailed cytomorphological analysis and the use of enzymatic cytochemical stains. The rarity of this case underscores the importance of documenting and studying uncommon presentations, with the goal of expanding clinical knowledge and strengthening diagnostic tools in feline veterinary medicine.", "journal": "Case reports in veterinary medicine", "doi": "10.1155/crve/6729159", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "41691085", "author": "Bertino F", "n_authors": 34, "title": "Mitochondrial energetic failure underlies FLVCR1-related sensory neuropathy.", "abstract": "Genetic pain loss disorders represent a heterogeneous group of rare diseases mainly characterized by defective nociception. Understanding the underlying molecular mechanism is fundamental to improve the treatment of patients affected by these rare disorders. Feline Leukemia Virus Subgroup C Receptor 1 (FLVCR1) is one of the genes previously associated with sensory neuropathy that requires further investigation. Here, we report on two additional patients with novel disease-causing variants in FLVCR1 and introduce a zebrafish model of the disease. The analyses of patient-derived fibroblasts show that distinct FLVCR1 variants compromised all the known functions associated with FLVCR1, thus affecting choline levels, heme biosynthesis and mitochondrial Ca", "journal": "Communications biology", "doi": "10.1038/s42003-026-09691-y", "deposited_data": "Sim", "nuccore_ids": "2992366784, 3377526273, 3377526270, 2992366784, 2973648576, 2973648575", "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "41689919", "author": "Maruri A", "n_authors": 5, "title": "Allogeneic mesenchymal stromal cell therapy for nonregenerative anemia in a FeLV-infected cat: a case report.", "abstract": "Feline Leukemia Virus (FeLV) induces hematologic abnormalities, including anemia, neutropenia, and thrombocytopenia, primarily through disruption of hematopoiesis. Current treatments for FeLV-induced nonregenerative anemia are limited, and the therapeutic potential of mesenchymal stromal cells (MSCs) in this context remains unexplored. This case report describes a 4-year-old FeLV-infected cat with severe refractory anemia and bone marrow erythroid hypoplasia treated with allogeneic adipose tissue-derived MSCs (AMSCs) via combined intraosseous and intravenous delivery (10 million cells per route, 20 million total). The AMSCs were isolated from a healthy donor, expanded, and characterized prior to administration. One month post-treatment, hematocrit and hemoglobin levels significantly improved, enabling corticosteroid discontinuation within 60 days. The cat remained clinically stable without further therapy for 32 months. This case highlights the potential of MSC therapy as a novel approach for FeLV-associated anemia, demonstrating promising long-term outcomes and warranting further investigation.", "journal": "Cytotherapy", "doi": "10.1016/j.jcyt.2025.10.002", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "41672241", "author": "Huang L", "n_authors": 7, "title": "FLVCR2: structure, substrate transport, and emerging roles in human disease.", "abstract": "The feline leukemia virus subgroup C receptor 2 (FLVCR2), a key member of the solute carrier (SLC) major facilitator superfamily (MFS), is a highly conserved transmembrane protein with diverse and critical functions in mammalian biology. Although once proposed as an extracellular heme importer, recent functional and structural studies strongly support FLVCR2 as a primary choline transporter, notably at the blood-brain barrier (BBB). Cryo-electron microscopy (cryo-EM) has resolved the outward-facing (OFS) and inward-facing (IFS) conformations, providing a molecular understanding of its classic MFS fold and the proposed proton-dependent rocker-switch mechanism for choline transport. This structural clarity definitively resolves the primary substrate debate. Mutations in FLVCR2 are the cause of Fowler syndrome (PVHH), resulting from severely impaired central nervous system (CNS) vascular development. Beyond this, FLVCR2 maintains systemic heme homeostasis, with its deficiency linked to exacerbation of hemolytic-induced lung injury via ferroptosis. Finally, its role in choline transport makes its upregulation in malignancies, such as acute myeloid leukemia (AML), significant, positioning FLVCR2 as a potential prognostic tumor biomarker and therapeutic target. Further research is necessary to fully exploit its clinical potential.", "journal": "Life sciences", "doi": "10.1016/j.lfs.2026.124269", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "41505408", "author": "de Almeida PM", "n_authors": 6, "title": "Prevalence of feline leukemia virus infection and associated diseases in a Portuguese domestic cat population: A 4.5-year cross-sectional study.", "abstract": "In a 2019 Pan-European Study, Portugal exhibited the highest prevalence of Feline Leukemia Virus (FeLV) infection (8.8%). Following the coronavirus disease 2019 (COVID-19) pandemic, it is crucial to evaluate how the prevalence of FeLV has evolved. FeLV infection is associated with the highest morbidity rates, primarily due to the increased incidence of diseases that compromise the health of cat populations, which varies according to the lifestyle and background of the cats studied. This study aimed (1) to estimate the prevalence and temporal trends of FeLV and FIV infections among cats presented to a university veterinary hospital in the Lisbon metropolitan area, and (2) to evaluate the clinical associations between FeLV infection, health status, and FeLV-related conditions in cats. Conducted over 4.5 years, from January 2019 to July 2023, this cross-sectional study took place at a teaching hospital and involved 1,124 cats that were tested serologically and/or by qPCR and RT-qPCR for FeLV. Information was gathered on the intrinsic and extrinsic characteristics of the cats, their health status, and any related diseases. The overall prevalence of FeLV was found to be 11.3% (95% CI: 9.5%-13.3%), with 1.8% (95% CI: 1.1%-2.7%) of cats co-infected with FIV, and it peaked in 2020 at 14.1% (95% CI: 7.5%-23.4%), with 2.4% (95% CI: 0.03%-8.2%) co-infected with FIV. Over the 4.5-year period, an increasing number of cats were tested, and more quantification of proviral and viral loads was performed. This indicated a more progressive course in 47.0% (31/66), of sick FeLV-infected cats, who exhibited a higher incidence of FeLV-related diseases. Although there was no significant difference in the average age between positive and negative cats, FeLV-positive cats demonstrated a higher rate of sickness (74.8%, n = 95). To the best of the authors' knowledge, this study represents the largest cross-sectional investigation of FeLV infection prevalence and its health implications conducted in Portugal. Overall, the available data suggest a possible increase in FeLV prevalence in Portugal, concurrent with a declining vaccination rate from 14.2% to 5.0%. The results also highlight notable differences in clinical status between progressive and regressive disease courses, reinforcing the necessity of staging the course of infection at diagnosis to ensure an informed medical approach and realistic prognosis. Efforts should focus on improving vaccination and screening activities, promoting neutering of indoor and outdoor cats, and isolating infected cats.", "journal": "PloS one", "doi": "10.1371/journal.pone.0339172", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "41454673", "author": "Ribeiro PR", "n_authors": 10, "title": "Pathological characterization of lymphomas with involvement of the alimentary tract in feline leukemia virus-infected cats.", "abstract": "Lymphoma is a common neoplasm in cats, in which alimentary lymphoma is a common subtype, and it is usually diagnosed in elderly, feline leukemia virus (FeLV)-negative cats. This study aimed to describe the pathological features of lymphoma with involvement of the alimentary tract in FeLV-antigen-positive cats. In a 12-year retrospective study, 32 necropsied and FeLV-infected cats with lymphoma affecting the alimentary tract were identified. Twenty-one cases were multicentric lymphomas with secondary involvement of the alimentary tract, and the remaining 11 cats were considered to have primary alimentary lymphoma. The small intestine was the most common anatomic location (23/32; 72%), followed by the large intestine (19/32; 59%) and stomach (18/32; 56%). In 22/32 cases (69%), multiple organs within the alimentary tract were concomitantly affected. Thickening of the intestinal and gastric walls was the most common gross lesion (23/32; 72%), while mural nodules were observed in 16/32 cats (50%). The mesenteric lymph nodes were frequently affected (22/32; 69%). Most lymphomas were composed of large (17/32; 53%) and intermediate cells (14/32; 44%). B-cell lymphomas were more frequent (24/32; 75%), and diffuse large B-cell lymphoma was the most common diagnosis (15/32; 47%). In 31/32 (97%) cases, FeLV gp70 antigen was detected in neoplastic lymphocytes by immunohistochemistry. Lymphomas affecting the alimentary tract may be observed in FeLV-infected, young adult cats, in which large to intermediate cell and B-cell lymphomas are more frequently observed, and small cell T-cell intestinal lymphoma is unlikely to be diagnosed.", "journal": "Veterinary pathology", "doi": "10.1177/03009858251400689", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "41391187", "author": "Zhan S", "n_authors": 4, "title": "Intranasal immunization of recombinant vaccinia virus bearing FeLV SU elicits systemic and mucosal immunity.", "abstract": "Feline leukemia virus (FeLV) is a major cause of mortality in domestic and wild felids, primarily spread through mucosal routes. Current FeLV vaccines offer moderate systemic protection but limited mucosal immunity. Previously, we showed that intranasal vaccination with a recombinant vaccinia virus (VV) can induce strong mucosal immune responses against multiple pathogens. Here, we constructed a recombinant VV expressing the surface unit (SU) of the FeLV envelope (VV", "journal": "Veterinary microbiology", "doi": "10.1016/j.vetmic.2025.110841", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "41384308", "author": "Han Y", "n_authors": 5, "title": "[Expression of Concern] lncRNA FLVCR1‑AS1 drives colorectal cancer progression via modulation of the miR‑381/RAP2A axis.", "abstract": "Following the publication of this paper, it was drawn to the Editor's attention by a concerned reader that, regarding the TUNEL assay experiments shown in Fig. 2E on p. 5, the Merge panels for the shFLVCR1‑AS1 experiments shown for the Caco‑2 and SW480 cell lines appeared to have been inserted into this figure the wrong way around. The authors were contacted by the Editorial Office to offer an explanation for this apparent anomaly in the presentation of the data in this paper; however, up to this time, no response from them has been forthcoming. Owing to the fact that the Editorial Office has been made aware of potential issues surrounding the scientific integrity of this paper, we are issuing an Expression of Concern to notify readers of this potential problem while the Editorial Office continues to investigate this matter further. [Molecular Medicine Reports 23: 139, 2021; DOI: 10.3892/mmr.2020.11778].", "journal": "Molecular medicine reports", "doi": "10.3892/mmr.2025.13774", "deposited_data": "Sim", "nuccore_ids": "2462508280, 2462508279, 2462508277, 2462508275, 2462508273, 2462508272, 2462508270, 2462508269, 2217266775, 2217266774, 2217266773, 2217266772, 2217266771, 2217266770, 2217266769, 1519315556", "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "41265810", "author": "Duncan H", "n_authors": 6, "title": "Affinity-based selection of anti-Feline Leukaemia Virus p27 monoclonal antibodies for efficient lateral flow assay development.", "abstract": "Traditional diagnostic methods like RT-PCR and proviral DNA PCR have limitations, underscoring the need for swift, sensitive alternatives such as lateral flow immunoassays (LFIA). Yet, efficiently identifying monoclonal antibody (mAb) pairs for robust ternary antigen-antibody interactions remains a universal bottleneck, as conventional ELISA screening is costly and may not accurately reflect native binding. Here, we combined ELISA with Spectral Shift Technology (SST) to minimise reagent use and comprehensively profile anti-FeLV p27 mAbs. This orthogonal approach enabled rapid selection of two low nanomolar mAbs with different epitope targets that form a ternary complex, which translates into a sensitive detection of the FeLV p27 in a LFIA prototype. Our screening methodology supports resource-efficient LFIA development for FeLV and extends to other significant animal and human pathogens like Monkeypox or Helicobacter pylori, improving diagnostics and quality control.", "journal": "Analytical biochemistry", "doi": "10.1016/j.ab.2025.116013", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "41259928", "author": "Hartmann G", "n_authors": 7, "title": "Retroperitoneal T-cell lymphoma with cystitis and megacolon in a young feline leukaemia virus-positive cat.", "abstract": "Retroperitoneal neoplasms are rare in both human and veterinary medicine, particularly in cats, where they account for less than 0.1 % of all neoplasms. This report describes a rare case of retroperitoneal T-cell lymphoma in a 7-month-old, feline leukaemia virus (FeLV)-positive Domestic Shorthair cat, leading to urethral and intestinal obstruction and subsequently cystitis and megacolon, respectively. The cat presented with clinical signs of weight loss, vomiting, tenesmus and urinary retention, and was diagnosed with a retroperitoneal mass compressing the colon and the urinary bladder. Due to the poor prognosis, the cat was euthanized during an exploratory laparoscopy and submitted for post-mortem examination. At necropsy, there was a large retroperitoneal, white, soft-to-firm, irregular mass that encompassed and compressed the rectum, colon, urethra and urinary bladder neck, along with megacolon and haemorrhagic cystitis. Histologically, the mass consisted of sheets of medium-sized neoplastic lymphocytes with mild anisocytosis and anisokaryosis. In the urinary bladder, a necrohaemorrhagic cystitis was observed. The cytoplasm of the neoplastic lymphocytes was positive by immunolabelling for CD3; therefore, the neoplasm was classified as a lymphoblastic T-cell lymphoma. Additionally, multifocal cytoplasmic FeLV immunolabelling was observed within the neoplastic cells, suggesting a possible viral involvement in the case's oncogenesis. This is the first reported case of a possibly FeLV-related retroperitoneal lymphoma in a cat. It had both intestinal and urinary tract obstructions as clinical outcomes. Our findings highlight retroperitoneal lymphoma as a new differential diagnosis for cats with lower urinary tract and gastrointestinal tract obstructions.", "journal": "Journal of comparative pathology", "doi": "10.1016/j.jcpa.2025.11.002", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "41125404", "author": "Wang Y", "n_authors": 8, "title": "FLVCR1 Deficiency Impairs Mitochondrial Homeostasis in Retinal Degeneration: Choline as a Potential Therapy.", "abstract": "The Feline Leukaemia Virus Subgroup C Receptor 1 (FLVCR1) has been recognized as a heme exporter essential for erythropoiesis, and emerging research identifies its novel function as a choline transporter. Mutations in FLVCR1 have been associated with the pathogenesis of retinitis pigmentosa (RP); however, the roles of FLVCR1 in retina remain unexplored. This study aims to elucidate the connection between FLVCR1 and RP and investigate potential therapeutic interventions. Utilizing CRISPR/Cas9 technology, we established retina-specific Flvcr1 knockout (SKO) and rod-specific Flvcr1 knockout (RKO) mouse models to investigate the in vivo functions of FLVCR1 in the retina. We performed optical coherence tomography (OCT) to assess the retinal thickness, electroretinography (ERG) to test the retinal function and histopathological sections and staining to analyse the pathological changes. Additionally, we administered choline supplementation treatment (CST) to evaluate its potential efficacy in alleviating symptoms of retinal degeneration. Genotyping and immunoblotting analyses confirmed the successful establishment of the SKO and RKO mouse models. Retinal degeneration in SKO mice manifested at postnatal day 14, while its onset in RKO mice occurred at P25, including diminished scotopic electroretinogram (ERG) responses, progressive degeneration of photoreceptor cells, infiltration of microglia into the outer nuclear layer (ONL) and disruption of mitochondrial homeostasis. Notably, we found that choline supplementation in RKO mice alleviated the associated phenotypes. We developed two innovative mouse models and revealed that FLVCR1 is critical for maintaining mitochondrial homeostasis and supporting photoreceptor survival. Choline supplementation serves as a therapeutic intervention for RP caused by FLVCR1 mutations.", "journal": "Clinical & experimental ophthalmology", "doi": "10.1111/ceo.70014", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "40914880", "author": "Roccabianca P", "n_authors": 7, "title": "Clonality assessment and feline leukemia virus protein expression in injection-site sarcoma-associated lymphocytic infiltrates.", "abstract": "Injections have been linked to feline sarcomas (feline injection-site sarcoma; FISS) and cutaneous lymphomas (cutaneous lymphoma at injection site; CLIS). Both tumors often exhibit lymphoplasmacytic inflammation ascribed to injected immunogenic material. CLIS is hypothesized to emerge from transformation and clonal expansion of lymphoid cells following persistent immune stimulation with feline leukemia virus (FeLV) reactivation and transformation. To further study whether the lymphocytic infiltrates associated with FISS can represent a suitable niche for the development of CLIS, 34 cases of FISS were examined. Lymphoid cell phenotypes were assessed using CD3 and CD79 immunohistochemistry. For cases with prominent inflammation, FeLV p27 and gp70 immunohistochemistry and PCR for antigen receptor rearrangements were performed. Male domestic shorthair cats predominated. The mean age was 12.2 years (range: 5-17 years). FISS developed in thoracic (8/34, 24%), flank (7/34, 21%), and interscapular (5/34, 15%) regions. Similar proportions of B and T lymphocytes were found in 11/34 (32%) cases; T-cells predominated in 12/34 (35%) cases, and B-cells predominated in 11/34 (32%). At least one FeLV antigen was expressed in lymphoid infiltrates in 10/18 cases (55%), and in neoplastic fibroblasts in 8/18 cases (44%), while both FeLV proteins were expressed in neoplastic cells in 3/18 cases (17%). One cat had clonal T-cell receptor-gamma and was diagnosed with concurrent FISS and CLIS. This case lacked FeLV expression. FeLV amplification from formalin-fixed paraffin-embedded material was unsuccessful. The expression of FeLV p27 and/or gp70 in neoplastic spindle cells and lymphoid infiltrates raises the possibility of FeLV involvement in the tumorigenesis of FISS and CLISs.", "journal": "Veterinary pathology", "doi": "10.1177/03009858251367396", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}]};
